INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(1, 1, 'بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ', 'রহমানের রাহীম আল্লাহ তায়ালার নামে-', 'Bismi Allahi alrrahmani alrraheemi', 1, NOW(), NOW()),
(1, 2, 'ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', 'সমস্ত প্রশংসা আল্লাহ তায়ালার জন্যে- তিনি সৃষ্টিকুলের রব,', 'Alhamdu lillahi rabbi alAAalameena', 1, NOW(), NOW()),
(1, 3, 'ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ', 'তিনি পরম দয়ালু, অতি মেহেরবান,', 'Alrrahmani alrraheemi', 1, NOW(), NOW()),
(1, 4, 'مَٰلِكِ يَوۡمِ ٱلدِّينِ', 'তিনি বিচার দিনের মালিক।', 'Maliki yawmi alddeeni', 1, NOW(), NOW()),
(1, 5, 'إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ', '(হে প্রভু,) আমরা তোমারই বন্দেগী করি এবং তোমার কাছেই আমরা সাহায্য চাই।', 'Iyyaka naAAbudu waiyyaka nastaAAeenu', 1, NOW(), NOW()),
(1, 6, 'ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ', 'তুমি আমাদের (সরল ও) অবিচল পথটি দেখিয়ে দাও-', 'Ihdina alssirata almustaqeema', 1, NOW(), NOW()),
(1, 7, 'صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ', 'তাদের পথ- যাদের ওপর তুমি অনুগ্রহ করেছো, তাদের (পথ) নয়- যাদের ওপর অভিশাপ দেয়া হয়েছে এবং (তাদের পথও নয়) যারা পথভ্রষ্ট হয়ে গেছে।', 'Sirata allatheena anAAamta AAalayhim ghayri almaghdoobi AAalayhim wala alddalleena', 1, NOW(), NOW()),
(2, 1, 'الٓمٓ', 'আলিফ লা-ম মী-ম।', 'Aliflammeem', 1, NOW(), NOW()),
(2, 2, 'ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ', '(এই) সেই (মহা) গ্রন্থ (আল কোরআন), তাতে (কোন) সন্দেহ নেই, যারা তাকওয়া অবলম্বন করে (এই কিতাব কেবল) তাদের জন্যেই পথপ্রদর্শক,', 'Thalika alkitabu la rayba feehi hudan lilmuttaqeena', 1, NOW(), NOW()),
(2, 3, 'ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ', 'যারা গায়বের ওপর ঈমান আনে, যারা নামায প্রতিষ্ঠা করে, তাদের আমি যা কিছু দান করেছি তারা তা থেকে (আমার নির্দেশিত পথে) ব্যয় করে,', 'Allatheena yuminoona bialghaybi wayuqeemoona alssalata wamimma razaqnahum yunfiqoona', 1, NOW(), NOW()),
(2, 4, 'وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ', 'যারা তোমার ওপর যা কিছু নাযিল করা হয়েছে তার ওপর ঈমান আনে- (ঈমান আনে) তোমার আগে (অন্য নবীদের ওপর) যা কিছু নাযিল করা হয়েছে তার ওপরও, (সর্বোপরি) তারা পরকালের ওপর দৃঢ় বিশ্বাস রাখে।', 'Waallatheena yuminoona bima onzila ilayka wama onzila min qablika wabialakhirati hum yooqinoona', 1, NOW(), NOW()),
(2, 5, 'أُوْلَـٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', '(সত্যিকার অর্থে) এ লোকগুলোই তাদের রবের কাছ থেকে (পাওয়া) হেদায়েতের ওপর রয়েছে এবং এরাই হচ্ছে প্রকৃত সফলকাম,', 'Olaika AAala hudan min rabbihim waolaika humu almuflihoona', 1, NOW(), NOW()),
(2, 6, 'إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ', 'যারা (এ বিষয়গুলোকে) নিশ্চিত অস্বীকার করে, তাদের তুমি (পরকালের কথা বলে) সাবধান করো আর না করো, (কার্যত) উভয়টাই তাদের জন্যে সমান (কথা), এরা (কখনো) ঈমান আনবে না।', 'Inna allatheena kafaroo sawaon AAalayhim aanthartahum am lam tunthirhum la yuminoona', 1, NOW(), NOW()),
(2, 7, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ', '(ক্রমাগত কুফুরী করার কারণে) আল্লাহ তায়ালা তাদের মন ও শোনার ওপর মোহর মেরে দিয়েছেন, এদের দেখার ওপরও আবরণ পড়ে আছে এবং তাদের জন্যে (পরকালের) কষ্টদায়ক শাস্তি রয়েছে।', 'Khatama Allahu AAala quloobihim waAAala samAAihim waAAala absarihim ghishawatun walahum AAathabun AAatheemun', 1, NOW(), NOW()),
(2, 8, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ', 'মানুষদের মাঝে কিছু (লোক এমনও) আছে যারা (মুখে) বলে, আমরা আল্লাহ তায়ালা ও পরকালের ওপর ঈমান এনেছি, (অথচ) এরা (কিন্তু মোটেই) ঈমানদার নয়।', 'Wamina alnnasi man yaqoolu amanna biAllahi wabialyawmi alakhiri wama hum bimumineena', 1, NOW(), NOW()),
(2, 9, 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', '(ঈমানের কথা বলে) এরা আল্লাহ তায়ালা ও তাঁর নেক বান্দাদের সাথে প্রতারণা করছে, (মূলত এ কাজের মাধ্যমে) তারা অন্য কাউকে নয়, নিজেদেরই ধোকা দিয়ে যাচ্ছে, (যদিও এ ব্যাপারে) তাদের কোনো চৈতন্য নেই।', 'YukhadiAAoona Allaha waallatheena amanoo wama yakhdaAAoona illa anfusahum wama yashAAuroona', 1, NOW(), NOW()),
(2, 10, 'فِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ', 'এদের মনের ভিতর রয়েছে (এক ধরণের মারাত্মক) ব্যাধি, (প্রতারণার কারণে) অতঃপর আল্লাহ তায়ালা (এদের সে) ব্যাধি বাড়িয়ে দিয়েছেন, তাদের জন্যে রয়েছে পীড়াদায়ক আযাব, কেননা তারা মিথ্যে বলছিলো।', 'Fee quloobihim maradun fazadahumu Allahu maradan walahum AAathabun aleemun bima kanoo yakthiboona', 1, NOW(), NOW()),
(2, 11, 'وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ', 'তাদের যখন বলা হয়, তোমরা (এই শান্তিপূর্ণ) যমীনে অশান্তি (ও বিপর্যয়) সৃষ্টি করো না, তখন তারা বলে, না, আমরাই তো হচ্ছি বরং সংশোধনকারী।', 'Waitha qeela lahum la tufsidoo fee alardi qaloo innama nahnu muslihoona', 1, NOW(), NOW()),
(2, 12, 'أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَٰكِن لَّا يَشۡعُرُونَ', 'জেনে রেখো এরাই হচ্ছে আসল বিপর্যয় সৃষ্টিকারী, কিন্তু তারা (বিষয়টা) বোঝে না।', 'Ala innahum humu almufsidoona walakin la yashAAuroona', 1, NOW(), NOW()),
(2, 13, 'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ', 'তাদের যখন বলা হয়, অন্য লোকেরা যেমন ঈমান এনেছে তোমরাও তেমনিভাবে ঈমান আনো, (তখন) তারা বলে (হে নবী, তুমি কি চাও), আমরাও নির্বোধ লোকদের মতো ঈমান আনি? জেনে রেখো, (আসল) নির্বোধ তো হচ্ছে এরা নিজেরাই, যদিও তারা (এ কথাটা) জানে না!', 'Waitha qeela lahum aminoo kama amana alnnasu qaloo anuminu kama amana alssufahao ala innahum humu alssufahao walakin la yaAAlamoona', 1, NOW(), NOW()),
(2, 14, 'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ', '(মোনাফেকদের অবস্থা হচ্ছে,) তারা যখন ঈমানদারদের সাথে মিলিত হয় তখন বলে, আমরা ঈমান এনেছি, (আবার) যখন একাকী তাদের শয়তানদের সাথে মিলিত হয় তখন বলে, আমরা অবশ্যই তোমাদের সাথে আছি, (ঈমানের কথা বলে ওদের সাথে) আমরা ঠাট্টা করছিলাম মাত্র!', 'Waitha laqoo allatheena amanoo qaloo amanna waitha khalaw ila shayateenihim qaloo inna maAAakum innama nahnu mustahzioona', 1, NOW(), NOW()),
(2, 15, 'ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', '(মূলত) আল্লাহ তায়ালাই তাদের সাথে ঠাট্টা করে যাচ্ছেন, আল্লাহ তায়ালা অবকাশ দিয়ে রেখেছেন, তারা তাদের বিদ্রোহে উদ্ভ্রান্তের ন্যায়ই ঘুরে বেড়াচ্ছে।', 'Allahu yastahzio bihim wayamudduhum fee tughyanihim yaAAmahoona', 1, NOW(), NOW()),
(2, 16, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ', 'এরা (জেনে বুঝে) হেদায়েতের বিনিময়ে গোমরাহী কিনে নিয়েছে, তাদের এ ব্যবসাটা (কিন্তু) মোটেই লাভজনক হয়নি এবং এরা সঠিক পথের অনুসারীও নয়।', 'Olaika allatheena ishtarawoo alddalalata bialhuda fama rabihat tijaratuhum wama kanoo muhtadeena', 1, NOW(), NOW()),
(2, 17, 'مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ', 'এদের উদাহরণ হচ্ছে সে (হতভাগ্য) ব্যক্তির মতো, যে (অন্ধকারে) আগুন জ্বালাতে চাইলো, যখন তা তার গোটা পরিবেশকে আলোকোজ্জ্বল করে দিলো, তখন (হঠাৎ করে) আল্লাহ তায়ালা তাদের (কাছ থেকে) আলোটুকু ছিনিয়ে নিলেন এবং তাদের তিনি (এমন) অন্ধকারে ফেলে রাখলেন যে, তারা কিছুই দেখতে পাচ্ছে না।', 'Mathaluhum kamathali allathee istawqada naran falamma adaat ma hawlahu thahaba Allahu binoorihim watarakahum fee thulumatin la yubsiroona', 1, NOW(), NOW()),
(2, 18, 'صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ', '(এদের অবস্থা হচ্ছে) এরা (কানেও) শোনে না, (চোখেও) দেখে না, (মুখ দিয়ে) কথাও বলতে পারে না, এরা (সঠিক পথের দিকেও) ফিরে আসবে না।', 'Summun bukmun AAumyun fahum la yarjiAAoona', 1, NOW(), NOW()),
(2, 19, 'أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ', 'অথবা (এদের উদাহরণ হচ্ছে), আসমান থেকে নেমে আসা বৃষ্টির মতো, এর মাঝে রয়েছে অন্ধকার, মেঘের গর্জন ও বিদ্যুতের চমক। বিদ্যুতের গর্জন ও মৃত্যুর ভয়ে এরা নিজেদের কানে আংগুল ঢুকিয়ে রাখে, আল্লাহ তায়ালা (কিন্তু) কাফেরদের (সকল দিক থেকেই) ঘিরে রেখেছেন।', 'Aw kasayyibin mina alssamai feehi thulumatun waraAAdun wabarqun yajAAaloona asabiAAahum fee athanihim mina alssawaAAiqi hathara almawti waAllahu muheetun bialkafireena', 1, NOW(), NOW()),
(2, 20, 'يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'মনে হয় এখনই বিদ্যুৎ এদের চোখকে নিষ্প্রভ করে দেবে; (এ অবস্থায়) আল্লাহ তায়ালা যখন এদের জন্যে একটু আলো জ্বালিয়ে দেন তখন এরা তার মধ্যে চলতে থাকে, আবার যখন তিনি তাদের ওপর অন্ধকার চাপিয়ে দেন তখন এরা (একটু থমকে) দাঁড়ায়; অথচ আল্লাহ তায়ালা চাইলে তাদের শোনার ও দেখার (ক্ষমতা) ছিনিয়ে নিতে পারতেন; নিশ্চই আল্লাহ তায়ালা সবকিছুর ওপর ক্ষমতাবান।', 'Yakadu albarqu yakhtafu absarahum kullama adaa lahum mashaw feehi waitha athlama AAalayhim qamoo walaw shaa Allahu lathahaba bisamAAihim waabsarihim inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 21, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ', 'হে মানুষ, তোমরা তোমাদের রবের ইবাদত কর, যিনি তোমাদের এবং তোমাদের আগে যারা ছিলো তাদের (সবাইকে) পয়দা করেছেন, আশা করা যায় তোমরা তাকওয়া অর্জন করতে পারবে।', 'Ya ayyuha alnnasu oAAbudoo rabbakumu allathee khalaqakum waallatheena min qablikum laAAallakum tattaqoona', 1, NOW(), NOW()),
(2, 22, 'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ', '(তিনিই সেই মহান রব), যিনি যমিনকে তোমাদের জন্যে শয্যা বানালেন, আসমানকে বানালেন ছাদ এবং আসমান থেকে পানি পাঠালেন, তা দিয়ে তিনি নানা প্রকারের ফলমূল উৎপাদন করে তোমাদের জীবিকার ব্যবস্থা করলেন, অতঃপর তোমরা জেনে বুঝে (এ সব কাজে কাউকে) আল্লাহ তায়ালার সমকক্ষ বানিয়ো না।', 'Allathee jaAAala lakumu alarda firashan waalssamaa binaan waanzala mina alssamai maan faakhraja bihi mina alththamarati rizqan lakum fala tajAAaloo lillahi andadan waantum taAAlamoona', 1, NOW(), NOW()),
(2, 23, 'وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ', 'আমি আমার বান্দার ওপর যে কিতাব নাযিল করেছি, তার (সত্যতার) ব্যাপারে যদি তোমরা কোনো সন্দেহে থাকো তাহলে যাও- তার মতো (করে) একটি সূরা তোমার (রচনা করে) নিয়ে এসো, আল্লাহ তায়ালা ছাড়া তোমাদের আর যেসব বন্ধুবান্ধব রয়েছে (প্রয়োজনে) তাদেরও ডাকো, যদি তোমরা সত্যবাদী হও!', 'Wain kuntum fee raybin mimma nazzalna AAala AAabdina fatoo bisooratin min mithlihi waodAAoo shuhadaakum min dooni Allahi in kuntum sadiqeena', 1, NOW(), NOW()),
(2, 24, 'فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ', 'আর তোমরা যদি তা না করতে পারো এবং (এটা জানা কথাই যে) তোমরা তা কখনোই করতে পারবে না, তাহলে তোমরা (জাহান্নামের) সেই কঠিন আগুনকে ভয় করো, যার ইন্ধন হবে মানুষ ও পাথর, এটা প্রস্তুত করে রাখা হয়েছে তাদের জন্যে যারা আল্লাহ তায়ালাকে অস্বীকার করে।', 'Fain lam tafAAaloo walan tafAAaloo faittaqoo alnnara allatee waqooduha alnnasu waalhijaratu oAAiddat lilkafireena', 1, NOW(), NOW()),
(2, 25, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ رِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ وَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ', 'যারা (এ কিতাবের ওপর) ঈমান এনেছে এবং নেক আমল করেছে, (হে নবী) তাদের তুমি সুসংবাদ দাও, তাদের জন্যে রয়েছে এমন এক জান্নাত যার নীচ দিয়ে ঝর্ণা প্রবাহিত হতে থাকবে; যখনি তাদের (জান্নাতের) কোনো একটি ফল দেয়া হবে তখনি তারা বলবে, এ ধরণের (ফল) তো ইতিপূর্বেও আমাদের দেয়া হয়েছিল, তাদের (মূলত) এ ধরণের জিনিসই সেখানে দেয়া হবে; তাদের জন্যে (আরো) সেখানে থাকবে পবিত্র সহধর্মী ও সহধর্মিনী এবং তারা সেখানে অনন্তকাল ধরে অবস্থান করবে।', 'Wabashshiri allatheena amanoo waAAamiloo alssalihati anna lahum jannatin tajree min tahtiha alanharu kullama ruziqoo minha min thamaratin rizqan qaloo hatha allathee ruziqna min qablu waotoo bihi mutashabihan walahum feeha azwajun mutahharatun wahum feeha khalidoona', 1, NOW(), NOW()),
(2, 26, '۞إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ', 'নিঃসন্দেহে আল্লাহ তায়ালা মশা কিংবা তার চাইতে ওপরে যা কিছু আছে তার উদাহারন দিতেও লজ্জা বোধ করেন না; যারা (আল্লাহার কথায়) বিশ্বাস স্থাপন করে তারা জানে, এ সত্য তাদের মালিকের পক্ষ থেকেই এসেছে, আর যারা (আগেই) সত্য অস্বীকার করেছে তারা (একে না মানার অজুহাত দিতে গিয়ে) বলে, আল্লাহ্‌ তায়ালা এ উদাহারন দ্বারা কি বুঝাতে চান? (আসলে) একই (জিনিস) দিয়ে অনেক লোককে তিনি গোমরাহ করলেও বহু লোককে তিনি (আবার) এ দিয়ে হেদায়াতের পথও দেখান, আর কতিপয় পাপাচারী ব্যক্তি ছাড়া তা দিয়ে অন্য কাউকে তিনি পথভ্রষ্ট করেন না।', 'Inna Allaha la yastahyee an yadriba mathalan ma baAAoodatan fama fawqaha faamma allatheena amanoo fayaAAlamoona annahu alhaqqu min rabbihim waamma allatheena kafaroo fayaqooloona matha arada Allahu bihatha mathalan yudillu bihi katheeran wayahdee bihi katheeran wama yudillu bihi illa alfasiqeena', 1, NOW(), NOW()),
(2, 27, 'ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', '(অপরদিকে) যারা আল্লাহর ফরমান মেনে চলার প্রতিশ্রুতি দেয়ার পর তা ভংগ করে, (ব্যক্তি ও সমাজে) আল্লাহ্‌ তায়ালা যেসব সম্পর্ককে মজবুত করতে বলেছেন তা তারা ছিন্ন করে, (সর্বোপরি) যমীনে অহেতুক বিপর্যয় সৃষ্টি করে; এরাই হচ্ছে (আসল) ক্ষতিগ্রস্ত।', 'Allatheena yanqudoona AAahda Allahi min baAAdi meethaqihi wayaqtaAAoona ma amara Allahu bihi an yoosala wayufsidoona fee alardi olaika humu alkhasiroona', 1, NOW(), NOW()),
(2, 28, 'كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ', 'তোমরা আল্লাহকে কিভাবে অস্বীকার করবে? অথচ তোমরা ছিলে মৃত, তিনই তোমাদের জীবন দিয়েছেন, পুনরায় তিনি তোমাদের মৃত্যু দেবেন, অতপর তিনিই আবার তোমাদের জীবন দান করবেন এবং তোমাদের (একদিন) তাঁর কাছেই ফিরিয়ে নেয়া হবে।', 'Kayfa takfuroona biAllahi wakuntum amwatan faahyakum thumma yumeetukum thumma yuhyeekum thumma ilayhi turjaAAoona', 1, NOW(), NOW()),
(2, 29, 'هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'তিনিই সেই মহান সত্তা, যিনি এ পৃথিবীর সব কিছু তোমাদের জন্য তৈরি করেছেন, অতপর তিনি আসমানের দিকে মননিবেশ করলেন এবং সেগুলকে সাত আসমানে বিনস্ত্য করলেন, তিনি সবকিছুর সম্পর্কে সম্যক অবগত রয়েছেন।', 'Huwa allathee khalaqa lakum ma fee alardi jameeAAan thumma istawa ila alssamai fasawwahunna sabAAa samawatin wahuwa bikulli shayin AAaleemun', 1, NOW(), NOW()),
(2, 30, 'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ', '|-| (হে নবী, স্মরণ করো,) যখন তোমরা রব ফেরেশতাদের বললেন, আমি পৃথিবীতে (আমার) খলীফা বানাতে চাই; তারা বললো, তুমি কি সেখানে এমন কাউকে (খলীফা) বানাতে চাও যে সেখানে বিপর্যয় সৃষ্টি করবে এবং (স্বার্থের জন্যে) এরা রক্তপাত করবে, আমরাই তো তোমার প্রশংসা সহকারে তোমার তাসবীহ পড়ছি এবং (প্রতিনিয়ত) তোমার পবিত্রতা বর্ণনা করছি; তিনি বললেন, আমি যা জানি তোমরা তা জানো না।', 'Waith qala rabbuka lilmalaikati innee jaAAilun fee alardi khaleefatan qaloo atajAAalu feeha man yufsidu feeha wayasfiku alddimaa wanahnu nusabbihu bihamdika wanuqaddisu laka qala innee aAAlamu ma la taAAlamoona', 1, NOW(), NOW()),
(2, 31, 'وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَـٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَـٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ', 'আল্লাহ তায়ালা (অতঃপর) আদমকে (প্রয়োজনীয়) সব জিনিসের নাম শিখিয়ে দিলেন, পরে তিনি সেগুলো ফেরেশতাদের কাছে পেশ করে বললেন, তোমরা যদি (তোমাদের আশংকার ব্যাপারে) সত্যবাদী হও (তাহলে) তোমরা আমাকে এ নামগুলো বলো তো?', 'WaAAallama adama alasmaa kullaha thumma AAaradahum AAala almalaikati faqala anbioonee biasmai haolai in kuntum sadiqeena', 1, NOW(), NOW()),
(2, 32, 'قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', 'ফেরেশতারা বললো (হে আল্লাহ), তুমি পবিত্র, আমাদের তো (এর বাইরে আর ) কিছুই জানা নেই- যা তুমি আমাদের শিক্ষা দিয়েছ; তুমিই একমাত্র জ্ঞানী, একমাত্র কুশলী।', 'Qaloo subhanaka la AAilma lana illa ma AAallamtana innaka anta alAAaleemu alhakeemu', 1, NOW(), NOW()),
(2, 33, 'قَالَ يَـٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ', 'আল্লাহ তায়ালা (এবার) আদমকে বললেন, তুমি তাদের কাছে তাদের নামগুলো বলে দাও, অতঃপর আদম তাদের (সামনে) তাদের নামগুলো বলে দিলো, তখন আল্লাহ তায়ালা বললেন, আমি কি তোমাদের বলিনি, আমি আসমানসমূহ ও যমীনের যাবতীয় ‘গায়ব’ (সম্পর্কে) জানি এবং তোমরা যা কিছু প্রকাশ করো আর যা কিছু গোপন করো আমি তাও জানি।', 'Qala ya adamu anbihum biasmaihim falamma anbaahum biasmaihim qala alam aqul lakum innee aAAlamu ghayba alssamawati waalardi waaAAlamu ma tubdoona wama kuntum taktumoona', 1, NOW(), NOW()),
(2, 34, 'وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ', 'আমি যখন ফেরেশতাদের বললাম, তোমরা আদমকে সাজদা করো, অতঃপর তারা (আল্লাহর আদেশে) সাজদা করলো- শুধু ইবলীস ছাড়া; সে সাজদা করতে অস্বীকার করলো, সে অহংকার করলো এবং না-ফরমানদের দলে শামিল হয়ে গেলো।', 'Waith qulna lilmalaikati osjudoo liadama fasajadoo illa ibleesa aba waistakbara wakana mina alkafireena', 1, NOW(), NOW()),
(2, 35, 'وَقُلۡنَا يَـٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ', 'আমি বললাম, হে আদম, তুমি এবং তোমার স্ত্রী (পরম সুখে) এই বেহেশতে বসবাস করতে থাকো এবং এখান থেকে যা তোমাদের মন চায় তাই তোমরা স্বাচ্ছন্দ্যের সাথে আহার করো, তোমরা এ গাছটির কাছেও যেও না, গেলে তোমরা (দু’জনই) সীমা লংঘনকারীদের মধ্যে শামিল হয়ে যাবে।', 'Waqulna ya adamu oskun anta wazawjuka aljannata wakula minha raghadan haythu shituma wala taqraba hathihi alshshajarata fatakoona mina alththalimeena', 1, NOW(), NOW()),
(2, 36, 'فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ', 'অতঃপর শয়তান সেখান থেকে তাদের উভয়েরই পদস্খলন ঘটালো, তারা উভয়ে (বেহেশতের) যেখানে ছিলো সেখান থেকে সে তাদের বের করেই ছাড়লো, আমি তাদের বললাম, তোমরা একজন আরেকজনের দুশমন হিসেবে এখান থেকে নেমে পড়ো, তোমাদের (পরবর্তী) বাসস্থান (হচ্ছে) পৃথিবী, সেখানে একটি নির্দিষ্ট সময় পর্যন্ত তোমাদের জন্য জীবনের (যাবতীয়) উপকরণ থাকবে।', 'Faazallahuma alshshaytanu AAanha faakhrajahuma mimma kana feehi waqulna ihbitoo baAAdukum libaAAdin AAaduwwun walakum fee alardi mustaqarrun wamataAAun ila heenin', 1, NOW(), NOW()),
(2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'অতঃপর আদম তার মালিকের কাছ থেকে (হেদায়েত সম্বলিত) কিছু বাণী পেলো, আল্লাহ তায়ালা তার ওপর ক্ষমাপরবশ হলেন, অবশ্যই তিনি বড়ো মেহেরবান ও ক্ষমাশীল।', 'Fatalaqqa adamu min rabbihi kalimatin fataba AAalayhi innahu huwa alttawwabu alrraheemu', 1, NOW(), NOW()),
(2, 38, 'قُلۡنَا ٱهۡبِطُواْ مِنۡهَا جَمِيعٗاۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَن تَبِعَ هُدَايَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'আমি (তাদের) বললাম, তোমরা সবাই (এবার) এখান থেকে নেমে যাও, তবে (যেখানে যাবে, সেখানে) আমার পক্ষ থেকে তোমাদের কাছে অবশ্যই হেদায়েত আসবে, অতপর যে আমার হেদায়েত মেনে চলবে তাদের কোনো ভয় নেই, তাদের কোনো প্রকার উৎকন্ঠিতও হতে হবে না।', 'Qulna ihbitoo minha jameeAAan faimma yatiyannakum minnee hudan faman tabiAAa hudaya fala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 39, 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'আর যারা (সে হেদায়েত) অস্বীকার করবে এবং আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করবে, তারা হবে জাহান্নামের বাসিন্দা, তারা সেখানে চিরকাল থাকবে।', 'Waallatheena kafaroo wakaththaboo biayatina olaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(2, 40, 'يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُواْ بِعَهۡدِيٓ أُوفِ بِعَهۡدِكُمۡ وَإِيَّـٰيَ فَٱرۡهَبُونِ', 'হে বনী ইসরাঈল (জাতি), তোমাদের ওপর আমি যেসব নেয়ামত দিয়েছি তোমরা সেগুলো স্মরণ করো, আমার (আনুগত্যের) প্রতুশ্রুতি তোমরা পূর্ণ করো, আমিও (এর বিনিময়ে) তোমাদের (দুনিয়ার শান্তি ও আখেরাতের পুরস্কারের) প্রতিশ্রুতি পূর্ণ করবো এবং তোমরা একমাত্র আমাকেই ভয় করো।', 'Ya banee israeela othkuroo niAAmatiya allatee anAAamtu AAalaykum waawfoo biAAahdee oofi biAAahdikum waiyyaya fairhabooni', 1, NOW(), NOW()),
(2, 41, 'وَءَامِنُواْ بِمَآ أَنزَلۡتُ مُصَدِّقٗا لِّمَا مَعَكُمۡ وَلَا تَكُونُوٓاْ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗا وَإِيَّـٰيَ فَٱتَّقُونِ', 'আমি (মোহাম্মদের কাছে) যা নাযিল করেছি, তোমরা এর ওপর ঈমান আনো, তোমাদের কাছে যা কিছু আছে তা তার সত্যায়নকারী, তোমরা কিছুতেই এর প্রথম অস্বীকারকারী হয়ো না এবং সামান্য মূল্যে আমার আয়াতসমূহকে বিক্রি করো না, তোমরা শুধু আমাদেই ভয় কর।', 'Waaminoo bima anzaltu musaddiqan lima maAAakum wala takoonoo awwala kafirin bihi wala tashtaroo biayatee thamanan qaleelan waiyyaya faittaqooni', 1, NOW(), NOW()),
(2, 42, 'وَلَا تَلۡبِسُواْ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُواْ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ', 'তোমরা মিত্যা দিয়ে সত্যের (গায়ে) পোশাক পরিয়ে দিও না এবং জেনে বুঝে সত্য লুকিয়েও রেখো না।', 'Wala talbisoo alhaqqa bialbatili wataktumoo alhaqqa waantum taAAlamoona', 1, NOW(), NOW()),
(2, 43, 'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱرۡكَعُواْ مَعَ ٱلرَّـٰكِعِينَ', 'তোমরা নামায প্রতিষ্ঠা করো, যাকাত আদায় করো, যারা (আমার সামনে অবনত হয়ে) রুকু করে তোমরাও তাদের সাথে রুকু করো।', 'Waaqeemoo alssalata waatoo alzzakata wairkaAAoo maAAa alrrakiAAeena', 1, NOW(), NOW()),
(2, 44, '۞أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَٰبَۚ أَفَلَا تَعۡقِلُونَ', 'তোমরা কি মানুষদের ভালো কাজের আদেশ করো এবং (বাস্তবায়নের সময়) নিজেদের (কথা) ভুলে যাও, অথচ তোমরা সবাই কিতাব পড়ো; কিন্তু (কিতাবের এ কথাটি) তোমরা কি বুঝো না?', 'Atamuroona alnnasa bialbirri watansawna anfusakum waantum tatloona alkitaba afala taAAqiloona', 1, NOW(), NOW()),
(2, 45, 'وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ', '(হে ঈমানদার ব্যক্তিরা,) তোমরা সবর ও নামাযের মাধ্যমে (আল্লাহর ) কাছে সাহায্য চাও; (নিষ্ঠার সাথে ) নামায প্রতিষ্ঠা করা (অবশ্যই ) কঠিন কাজ, কিন্তু যারা (আল্লাহকে) ভয় করে তাদের কথা আলাদা,', 'WaistaAAeenoo bialssabri waalssalati wainnaha lakabeeratun illa AAala alkhashiAAeena', 1, NOW(), NOW()),
(2, 46, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ', '(তাদের কথাও আলাদা) যারা জানে একদিন তাদের সবাইকে মালিকের সামনাসামনি হতে হবে এবং তাদের (সবাইকে) তাঁর কাছেই ফিরে যেতে হবে।', 'Allatheena yathunnoona annahum mulaqoo rabbihim waannahum ilayhi rajiAAoona', 1, NOW(), NOW()),
(2, 47, 'يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ', 'হে বনী ইসরাঈল (জাতি), তোমরা আমার সেই নেয়ামতের কথা স্মরণ করো যা আমি তোমাদের দান করেছি, (নেয়ামত হিসেবে) আমি অবশ্যই তোমাদের সৃষ্টিকুলের ওপর প্রাধান্য দিয়েছি।', 'Ya banee israeela othkuroo niAAmatiya allatee anAAamtu AAalaykum waannee faddaltukum AAala alAAalameena', 1, NOW(), NOW()),
(2, 48, 'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ وَلَا هُمۡ يُنصَرُونَ', '(হে ঈমানদার ব্যক্তিরা,) তোমরা সে দিনটিকে ভয় করো যেদিন একজন আরেকজনের কোনোই কাজে আসবে না, একজনের কাছ থেকে আরেকজনের (পক্ষে) কোনো সুপারিশও গ্রহন করা হবে না, (মুক্তির জন্য) কারো কাছ থেকে কোনো মুক্তিপণ নেয়া হবে না- না তাদের (সেদিন কোনো) সাহায্য করা হবে!', 'Waittaqoo yawman la tajzee nafsun AAan nafsin shayan wala yuqbalu minha shafaAAatun wala yukhathu minha AAadlun wala hum yunsaroona', 1, NOW(), NOW()),
(2, 49, 'وَإِذۡ نَجَّيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ', '(স্মরণ করো,) যখন আমি তোমাদের ফেরাউনের লোকেদের (গোলামী) থেকে মুক্তি দিয়েছিলাম, তারা নিকৃষ্ট ধরণের শাস্তি দ্বারা তোমাদের যন্ত্রণা দিতো, তারা তোমাদের পুত্র সন্তানদের হত্যা করতো এবং তোমাদের মেয়েদের (তারা ) জীবিত রেখে দিতো; তোমাদের মালিকের পক্ষ থেকে এতে তোমাদের জন্য বড় একটা পরীক্ষা (নিহিত) ছিলো।', 'Waith najjaynakum min ali firAAawna yasoomoonakum sooa alAAathabi yuthabbihoona abnaakum wayastahyoona nisaakum wafee thalikum balaon min rabbikum AAatheemun', 1, NOW(), NOW()),
(2, 50, 'وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَيۡنَٰكُمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ', '(স্মরণ করো,) যখন আমি তোমাদের জন্য সমুদ্রকে বিভক্ত করে দিয়েছিলাম, অতঃপর আমি তোমাদের (সমূহ মৃত্যুর হাত থেকে ) বাঁচিয়ে দিয়েছিলাম এবং আমি ফেরাউন ও তার দলবলকে (সমুদ্রে ) ডুবিয়ে দিয়েছিলাম, আর (তা তো) তোমরা (নিজেরাই) প্রত্যক্ষ করেছিলে!', 'Waith faraqna bikumu albahra faanjaynakum waaghraqna ala firAAawna waantum tanthuroona', 1, NOW(), NOW()),
(2, 51, 'وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةٗ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ', '(স্মরণ করো,) যখন মূসাকে আমি (বিশেষ কাজের জন্য) চল্লিশ রাত সময় নির্ধারণ করে দিলাম, তারপর তোমরা একটি বাছুরকে (মাবুদরূপে ) গ্রহণ করে নিলে, (আসলে) তোমরা (ছিলে বড়োই) যালেম!', 'Waith waAAadna moosa arbaAAeena laylatan thumma ittakhathtumu alAAijla min baAAdihi waantum thalimoona', 1, NOW(), NOW()),
(2, 52, 'ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ', 'এরপর আমি তোমাদের ক্ষমা করে দিয়েছি, আশা করা গিয়েছিলো, তোমরা কৃতজ্ঞতা আদায় করবে।', 'Thumma AAafawna AAankum min baAAdi thalika laAAallakum tashkuroona', 1, NOW(), NOW()),
(2, 53, 'وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ', '(স্মরণ করো,) যখন আমি মূসাকে কিতাব ও (ন্যায়-অন্যায়ের) পরখকারী- (মানদণ্ড) দান করেছি, আশা করা গিয়েছিলো, তোমরা হেদায়েতের পথে চলতে পারো।', 'Waith atayna moosa alkitaba waalfurqana laAAallakum tahtadoona', 1, NOW(), NOW()),
(2, 54, 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '(আরও স্মরণ করো,) মূসা যখন তার নিজ লোকদের বললো, হে আমার জাতি, তোমরা (আমার অবর্তমানে) বাছুরকে মাবুদ হিসেবে গ্রহণ করে অবশ্যই নিজেদের ওপর (বড় রকমের) যুলুম করেছো, এ জন্য অবিলম্বে তোমরা তোমাদের সৃষ্টিকর্তার দরবারে তাওবা করো এবং তোমাদের নিজেদের (শিরক-এ অভিশপ্ত) নফসসমূওহকে হত্যা করো, এর মাঝেই সৃষ্টিকর্তার কাছে তোমাদের জন্য কল্যাণ রয়েছে; অতঃপর আল্লাহ তায়ালা তোমাদের ওপর ক্ষমাপরবশ হলেন, অবশ্যই তিনি ক্ষমাশীল ও অনুগ্রহকারী।', 'Waith qala moosa liqawmihi ya qawmi innakum thalamtum anfusakum biittikhathikumu alAAijla fatooboo ila bariikum faoqtuloo anfusakum thalikum khayrun lakum AAinda bariikum fataba AAalaykum innahu huwa alttawwabu alrraheemu', 1, NOW(), NOW()),
(2, 55, 'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ', 'তোমরা যখন বলেছিলে, হে মূসা, আমরা আল্লাহকে প্রত্যক্ষভাবে না দেখলে কখনও তার ওপর ঈমান আনবো না, তখন (এ ধৃষ্টতার শাস্তি হিসেবে) মুহূর্তের মধ্যেই বজ্র (-সম এক গযব) তোমাদের উপর নিপাতিত হলো, আর তোমরা তার দিকেই চেয়েই থাকলে!', 'Waith qultum ya moosa lan numina laka hatta nara Allaha jahratan faakhathatkumu alssaAAiqatu waantum tanthuroona', 1, NOW(), NOW()),
(2, 56, 'ثُمَّ بَعَثۡنَٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', 'অতঃপর তোমাদের (এই) মৃত্যুর পর আমি তোমাদের পুনরায় জীবন দান করলাম, আশা করা গিয়েছিলো, তোমরা (আমার) কৃতজ্ঞতা আদায় করবে।', 'Thumma baAAathnakum min baAAdi mawtikum laAAallakum tashkuroona', 1, NOW(), NOW()),
(2, 57, 'وَظَلَّلۡنَا عَلَيۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', 'আমি তোমাদের উপর মেঘের ছায়া দান করেছিলাম, ‘মান’ এবং ‘সালওয়া’ (নামক খাবারও) আমি তোমাদের জন্য পাঠিয়েছিলাম; (আমি বলেছিলাম,) সেসব পবিত্র খাবার তোমরা খাও, যা আমি তোমাদের দিয়েছি, (নেয়ামত অবজ্ঞা করে) তারা আমার উপর কোনো যুলুম করেনি, (বরং এর দ্বারা) তারা নিজেরাই নিজেদের উপর যুলুম করেছে।', 'Wathallalna AAalaykumu alghamama waanzalna AAalaykumu almanna waalssalwa kuloo min tayyibati ma razaqnakum wama thalamoona walakin kanoo anfusahum yathlimoona', 1, NOW(), NOW()),
(2, 58, 'وَإِذۡ قُلۡنَا ٱدۡخُلُواْ هَٰذِهِ ٱلۡقَرۡيَةَ فَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَدٗا وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُولُواْ حِطَّةٞ نَّغۡفِرۡ لَكُمۡ خَطَٰيَٰكُمۡۚ وَسَنَزِيدُ ٱلۡمُحۡسِنِينَ', '(স্মরণ করো,) আমি যখন তোমাদের বলেছিলাম, তোমরা এই জনপদে ঢুকে পড়ো এবং তোমরা তার যেখান থেকে ইচ্ছা স্বাচ্ছন্দ্যে আহার করো, (দম্ভ সহকারে প্রবেশ না করে) মাথানত করে ঢোকো, তোমরা ক্ষমার কথা বলবে, আমিও তোমাদের ভুল ত্রুটিসমূহ ক্ষমা করে দিবো। যারা ভালো কাজ করে আমি তাদের (পাওনার অংক) বাড়িয়ে দিই।', 'Waith qulna odkhuloo hathihi alqaryata fakuloo minha haythu shitum raghadan waodkhuloo albaba sujjadan waqooloo hittatun naghfir lakum khatayakum wasanazeedu almuhsineena', 1, NOW(), NOW()),
(2, 59, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِينَ ظَلَمُواْ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ', '(সুস্পষ্ট হেদায়েত সত্ত্বেও) অতঃপর যালেমরা এমন কিছু ব্যাপার রদবদল করে ফেললো, যা না করার জন্যই তাদের বলা হয়েছিলো, যারা যুলুম করলো তাদের উপর আমি আসমান থেকে গযব নাযিল করলাম, (মূলত) এটা ছিলো তাদের গুনাহের ফল।', 'Fabaddala allatheena thalamoo qawlan ghayra allathee qeela lahum faanzalna AAala allatheena thalamoo rijzan mina alssamai bima kanoo yafsuqoona', 1, NOW(), NOW()),
(2, 60, '۞وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', '(স্মরণ করো,) যখন মূসা (আমার কাছে ) তার জাতির লোকদের জন্য পানি চাইলো, আমি (তাকে ) বললাম, তোমার লাঠি দিয়ে তুমি (এই) পাথরে আঘাত করো, (আঘাত করা মাত্রই) তা থেকে বারোটি (পানির) নহর উৎপন্ন হয়ে গেল; প্রত্যেক গোত্রই নিজেদের (পানি পানের) ঘাট চিনে নিলো; (আমি বললাম,) আল্লাহর দেওয়া রিযিক থেকে তোমরা পানাহার করো, তবে যমীনে বিপর্যয় সৃষ্টি করো না।', 'Waithi istasqa moosa liqawmihi faqulna idrib biAAasaka alhajara fainfajarat minhu ithnata AAashrata AAaynan qad AAalima kullu onasin mashrabahum kuloo waishraboo min rizqi Allahi wala taAAthaw fee alardi mufsideena', 1, NOW(), NOW()),
(2, 61, 'وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', '(স্মরণ করো,) তোমরা যখন বলেছিলে, হে মূসা, (প্রতিদিন ) একই ধরণের খাবারের ওপর আমরা কিছুতেই (আর) ধৈর্য ধরতে পারছি না, তুমি তোমার মালিকের কাছে বলো তিনি যেম আমাদের জন্য কিছ ভূমিজাত দ্রব্য-তরিতরকারি, পেয়াজ, রসুন, ভুট্টা, ডালের ব্যবস্থা করেন যা ভূমি উৎপাদন করে, সে বললো, তোমরা কি (আল্লাহর পাঠানো) এ উৎকৃষ্ট জিনিসের সাথে একটি তুচ্ছ জিনিসকে বদলে নিতে চাও? (যদি তাই হয়) তাহলে তোমরা অন্য কোনো শহরে সরে পড়ো, যেখানে তোমাদের এসব জিনিস যা তোমরা চাইবে, তা অবশ্যই পাওয়া যাবে, (আল্লাহ তায়ালার আদেশ অমান্য করার ফলে ) অপমান ও দারিদ্রতা তাদের উপর ছেয়ে গেলো; তারা আল্লাহর গযবের যোগ্য হয়ে গেল, এটা এ কারণে (যে), তারা (ক্রমাগত) আল্লাহর আয়াত অস্বীকার করতে থাকলো এবং আল্লাহর নবীদের অন্যায়ভাবে হত্যা করতে থাকলো, আর এসব কিছু এ জন্যই ছিলো, এরা না-ফরমানী ও সীমা লংঘন করেছিলো!', 'Waith qultum ya moosa lan nasbira AAala taAAamin wahidin faodAAu lana rabbaka yukhrij lana mimma tunbitu alardu min baqliha waqiththaiha wafoomiha waAAadasiha wabasaliha qala atastabdiloona allathee huwa adna biallathee huwa khayrun ihbitoo misran fainna lakum ma saaltum waduribat AAalayhimu alththillatu waalmaskanatu wabaoo bighadabin mina Allahi thalika biannahum kanoo yakfuroona biayati Allahi wayaqtuloona alnnabiyyeena bighayri alhaqqi thalika bima AAasaw wakanoo yaAAtadoona', 1, NOW(), NOW()),
(2, 62, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّـٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'নিঃসন্দেহে যারা ঈমান এনেছে, যারা ছিলো ইহুদী-খৃষ্টান এবং ‘সাবী’- এদের (সবার মাঝে) যে কেউই আল্লাহর প্রতি ঈমান আনবে, ঈমান আনবে পরকালের প্রতি এবং ভালো কাজ করবে, তাদের জন্য তাদের মালিকের কাছে পুরষ্কার থাকবে এবং এসব লোকের কোনো ভয় নেই, তারা চিন্তিতও হবে না।', 'Inna allatheena amanoo waallatheena hadoo waalnnasara waalssabieena man amana biAllahi waalyawmi alakhiri waAAamila salihan falahum ajruhum AAinda rabbihim wala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 63, 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ', '(স্মরণ করো,) যখন আমি তোমাদের (কাছ থেকে) প্রতিশ্রুতি নিয়েছিলাম এবং তূর পাহাড়কে আমি তোমাদের ওপর তুলে ধরে (বলে)-ছিলাম; যে কিতাব আমি তোমাদের দান করেছি তা শক্তভাবে আঁকড়ে ধরো এবং তাতে যা কিছু আছে তা স্মরণ রেখো, আশা করা যায় তোমরা (শয়তান থেকে ) বাঁচতে পারবে।', 'Waith akhathna meethaqakum warafaAAna fawqakumu alttoora khuthoo ma ataynakum biquwwatin waothkuroo ma feehi laAAallakum tattaqoona', 1, NOW(), NOW()),
(2, 64, 'ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ', 'অতঃপর তোমরা এ ঘটনার পর (ওয়াদা) থেকে ফিরে গেলে, (আসলে) আল্লাহর অনুদান ও রহমত যদি তোমাদের উপর না থাকতো তাহলে তোমরা অবশ্যই ধ্বংস হয়ে যেতে!', 'Thumma tawallaytum min baAAdi thalika falawla fadlu Allahi AAalaykum warahmatuhu lakuntum mina alkhasireena', 1, NOW(), NOW()),
(2, 65, 'وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ', 'তোমরা তো ভালো করেই তাদের জানো, যারা তোমাদের মধ্যে শনিবারে (আল্লাহর আদেশের) সীমা লংঘন করেছে, অতঃপর আমি তাদের (শুধু এটুকুই) বলেছি, যাও- (এবার) তোমরা সবাই অপমানিত বানর-(এ পরিণত) হয়ে যাও।', 'Walaqad AAalimtumu allatheena iAAtadaw minkum fee alssabti faqulna lahum koonoo qiradatan khasieena', 1, NOW(), NOW()),
(2, 66, 'فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ', 'একে আমি সেসব মানুষদের- যারা তখন সেখানে (উপস্থিত) ছিলো- আরও যারা পরে আসবে, তাদের (সবার) জন্যই আমি দৃষ্টান্তমূলক (ঘটনা) বানিয়ে দিয়েছি, যারা তাকওয়া অবলম্বন করে তাদের জন্যও এটি (ছিলো ) একটি উপদেশ।', 'FajaAAalnaha nakalan lima bayna yadayha wama khalfaha wamawAAithatan lilmuttaqeena', 1, NOW(), NOW()),
(2, 67, 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ', '(স্মরণ করো,) যখন মূসা তার জাতিকে বললো, অবশ্যই আল্লাহ তায়ালা তোমাদের (তাঁর নামে) একটি গাভী যবাই করার আদেশ দিচ্ছেন; তারা বললো (হে মূসা, একথা বলে), তুমি কি আমাদের সাথে তামাশা করছো? সে বললো, আমি (তামাশা করে) জাহেলদের দলে অন্তর্ভুক্ত হওয়া থেকে আল্লাহ তায়ালার কাছে পানাহ চাই!', 'Waith qala moosa liqawmihi inna Allaha yamurukum an tathbahoo baqaratan qaloo atattakhithuna huzuwan qala aAAoothu biAllahi an akoona mina aljahileena', 1, NOW(), NOW()),
(2, 68, 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ', 'তারা বললো, তুমি তোমার রবকে বলো আমাদের তিনি যেন সুস্পষ্টভাবে বলে দেন- সে (জন্তু)টি কেমন (হবে)? সে বললো, অবশ্যই তা হবে এমন- যা বৃদ্ধ হবে না, (আবার ) একেবারে বাচ্চাও হবে না; (বরং তা হবে) এর মাঝামাঝি বয়সের, (যাও, এখন) যা কিছু তোমাদের নির্দেশ দেওয়া হচ্ছে তা-ই করো।', 'Qaloo odAAu lana rabbaka yubayyin lana ma hiya qala innahu yaqoolu innaha baqaratun la faridun wala bikrun AAawanun bayna thalika faifAAaloo ma tumaroona', 1, NOW(), NOW()),
(2, 69, 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّـٰظِرِينَ', 'তারা (মূসাকে) বললো, তুমি তোমার রবকে জিজ্ঞাসা করে নাও, তিনি আমাদের যেন বলে দেন তার রংটা কেমন হবে? সে বললো, তা হবে হলুদ রঙের, তার রঙ এতো আকর্ষণীয় হবে যে, যারা তার দিকে তাকাবে তা তাদেরই পরিতৃপ্ত করবে।', 'Qaloo odAAu lana rabbaka yubayyin lana ma lawnuha qala innahu yaqoolu innaha baqaratun safrao faqiAAun lawnuha tasurru alnnathireena', 1, NOW(), NOW()),
(2, 70, 'قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ', 'তারা বললো (হে মূসা), তুমি তোমার মালিককে (আবার) জিজ্ঞাসা করে নাও, (আসলে) তা কী ধরণের (গাভী) হবে, আমাদের কাছে (তো সব) গাভী দেখতে একই ধরণের মনে হয়; আল্লাহ তায়ালা চাইলে (এবার ) অবশ্যই আমরা সঠিক পথে চলতে পারবো।', 'Qaloo odAAu lana rabbaka yubayyin lana ma hiya inna albaqara tashabaha AAalayna wainna in shaa Allahu lamuhtadoona', 1, NOW(), NOW()),
(2, 71, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ', 'সে বললো, (আল্লাহ তায়ালার ঈস্পিত ) সে (গাভী) হবে এমন যে সেটি কোনো চাষাবাদের কাজ করে না, যমীনে পানি সেচের কাজও করে না, সম্পূর্ণ নিখুঁত ও ত্রুটি মুক্ত, (একথা শুনে) তারা বললো, এতক্ষণে তুমি (আমাদের সামনে) সত্য কথাটা নিয়ে এসেছো! অতঃপর তারা তা-ই যবাই করলো, যদিও (ইতিপূর্বে) মনে হয়নি, তারা এ কাজটি আদৌ করতে চায়।', 'Qala innahu yaqoolu innaha baqaratun la thaloolun tutheeru alarda wala tasqee alhartha musallamatun la shiyata feeha qaloo alana jita bialhaqqi fathabahooha wama kadoo yafAAaloona', 1, NOW(), NOW()),
(2, 72, 'وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّـٰرَ ٰٔتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ', '(স্মরণ করো,) যখন তোমরা একজন লোককে হত্যা করেছিলে, অতঃপর সে ব্যাপারে তোমরা একে অপরের উপর (হত্যার) অভিযোগ আরোপ করতে শুরু করলে, (অথচ) আল্লাহ তায়ালা সে বিষয়টিই (মানুষের সামনে ) বের করে আনতে চাইলেন, যা তোমরা লুকোনোর চেষ্টা করছিলে।', 'Waith qataltum nafsan faiddaratum feeha waAllahu mukhrijun ma kuntum taktumoona', 1, NOW(), NOW()),
(2, 73, 'فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', '(হত্যাকারীকে খোঁজার জন্য) আমি তোমাদের বললাম, (যবাই করা) সেই (গাভীর শরীরের) একাংশ দিয়ে তোমরা একে (মৃদু) আঘাত করো, এভাবেই আল্লাহ তায়ালা মৃত ব্যক্তিকে জীবন দান করবেন এবং (এ ঘটনা দ্বারা) তিনি তোমাদের কাছে তাঁর নিদর্শনসমূহ তুলে ধরেন, আশা করা গিয়েছিলো তোমরা (সত্য) অনুধাবন করবে।', 'Faqulna idriboohu bibaAAdiha kathalika yuhyee Allahu almawta wayureekum ayatihi laAAallakum taAAqiloona', 1, NOW(), NOW()),
(2, 74, 'ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'অতঃপর তোমাদের মন কঠিন হয়ে গেল, (এমন কঠিন) যেন তা (শক্ত) পাথর, (বরং মাঝে মাঝে মনে হয়) পাথরের চেয়েও বেশি কঠিন; (কেননা ) কিছু পাথর এমন আছে যা থেকে ঝর্ণাধারা নির্গত হয়, আবার কোনও কোনো সময় তা বিদীর্ণ হয়ে ফেটেও যায় এবং তা থেকে পানিও বেরিয়ে আসে, (অবশ্য) এর মধ্য থেকে (এমন কিছু পাথর আছে) যা আল্লাহর ভয়ে ধ্বসে পড়ে; আল্লাহ তায়ালা (কিন্তু) তোমাদের কার্যকপাল সম্পর্কে মোটেই গাফেল নন।', 'Thumma qasat quloobukum min baAAdi thalika fahiya kaalhijarati aw ashaddu qaswatan wainna mina alhijarati lama yatafajjaru minhu alanharu wainna minha lama yashshaqqaqu fayakhruju minhu almao wainna minha lama yahbitu min khashyati Allahi wama Allahu bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(2, 75, '۞أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ', 'তোমরা কি এরপরও এই আশা পোষণ করো যে, এরা তোমাদের জন্য ঈমান আনবে? এদের একাংশ তো (যুগ যুগ ধরে) আল্লাহর কিতাব শুনে আসছে, অতঃপর তারা তাকে বিকৃত করেছে, তাও করেছে তাকে ভালো করে বুঝার পর, অথচ তারা ভালো করেই জানে (যে, তারা কি করছে)।', 'AfatatmaAAoona an yuminoo lakum waqad kana fareequn minhum yasmaAAoona kalama Allahi thumma yuharrifoonahu min baAAdi ma AAaqaloohu wahum yaAAlamoona', 1, NOW(), NOW()),
(2, 76, 'وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ', 'এরা যখন ঈমানদারদের সাথে সাক্ষাত করে তখন বলে, আমরা ঈমান এনেছি, কিন্তু এরা যখন গোপনে একে অপরের সাথে মিলিত হয় তখন বলে, তোমরা কি মুসলমানদের কাছে সেসব কথা প্রকাশ করে দাও যা আল্লাহ তায়ালা (মোহাম্মদের নবুওত সম্পর্কে আগেই তাওরাতে) তোমাদের ওপর ব্যক্ত করে দিয়েছেন; (খবরদার, তোমরা এমনটি কখনও করো না), তাহলে তারা (একদিন) তোমাদের প্রভুর সামনে এটি দিয়ে তোমাদের বিরুদ্ধে যুক্তি দিবে, তোমরা কি বুঝতে পাচ্ছো না?', 'Waitha laqoo allatheena amanoo qaloo amanna waitha khala baAAduhum ila baAAdin qaloo atuhaddithoonahum bima fataha Allahu AAalaykum liyuhajjookum bihi AAinda rabbikum afala taAAqiloona', 1, NOW(), NOW()),
(2, 77, 'أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ', '(কিন্তু ) এরা কি জানে না যে, (আল্লাহর কিতাবের) যা কিছু এরা গোপন করে (আবার নিজেদের স্বার্থে তারা ) যা প্রকাশ করে, আল্লাহ তায়ালা তা সবই জানেন।', 'Awala yaAAlamoona anna Allaha yaAAlamu ma yusirroona wama yuAAlinoona', 1, NOW(), NOW()),
(2, 78, 'وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ', 'এদের মধ্যে কিছু আছে নিরক্ষর, যারা (আল্লাহর) কিতাব সম্পর্কে কিছুই জানে না, (আল্লাহর কিতাব এদের কাছে ) নিছক মিথ্যা আকাঙ্খা (সর্বস্ব পুস্তক ) মাত্র, এরা শুধু অমূলক ধারণাই করে থাকে।', 'Waminhum ommiyyoona la yaAAlamoona alkitaba illa amaniyya wain hum illa yathunnoona', 1, NOW(), NOW()),
(2, 79, 'فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَوَيۡلٞ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلٞ لَّهُم مِّمَّا يَكۡسِبُونَ', 'সে সব লোকেদের জন্য ধ্বংস (অনিবার্য), যারা নিজেদের হাত দিয়ে কিতাব লিখে, তারপর বলে, এগুলো হচ্ছে আল্লাহ তায়ার পক্ষ থেকে (আসা শরীয়তের বিধান, উদ্দেশ্য হচ্ছে,) তারা যেন তা দিয়ে সামান্য কিছু (স্বার্থ) কিনে নিতে পারে; তাদের হাত যা কিছু রচণা করেছে তার জন্য তাদের ধ্বংস ও দুর্ভোগ, যা কিছু তারা উপার্জন করেছে তার জন্যও আদের দুর্ভোগ।', 'Fawaylun lillatheena yaktuboona alkitaba biaydeehim thumma yaqooloona hatha min AAindi Allahi liyashtaroo bihi thamanan qaleelan fawaylun lahum mimma katabat aydeehim wawaylun lahum mimma yaksiboona', 1, NOW(), NOW()),
(2, 80, 'وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'এরা বলে, জাহান্নামের আগুন কখনও আমাদের স্পর্শ করবে না, (করলেও-) তা হবে নির্দিষ্ট কয়েকটা দিনের (জন্যে) মাত্র, (হে নবী,) তুমি বলো, তোমরা কি আল্লাহর কাছ থেকে (এমন ) কোনও প্রতিশ্রুতি আদায় করে নিয়েছো? আল্লাহ তায়ালা তো খখনও তাঁর প্রতিশ্রুতি ভঙ্গ করেন না, না তোমরা জেনে বুঝেই আল্লাহ তায়ালা সম্পর্কে এমন কথা বলে বেড়াচ্ছো যা তোমরা নিজেরাই জানো না।', 'Waqaloo lan tamassana alnnaru illa ayyaman maAAdoodatan qul attakhathtum AAinda Allahi AAahdan falan yukhlifa Allahu AAahdahu am taqooloona AAala Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(2, 81, 'بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'হ্যাঁ, যে ব্যক্তি পাপ কামিয়েছে এবং যাকে তার পাপ ঘিরে রেখেছে, এমন লোকেরাই হবে জাহান্নামের অধিবাসী, সেখানে তারা চিরদীন অবস্থান করবে।', 'Bala man kasaba sayyiatan waahatat bihi khateeatuhu faolaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(2, 82, 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ', '(আবার) যারা (আল্লাহ তায়ালার ওপর) ঈমান আনবে এবং ভালো কাজ করবে, তারা বেহেশতবাসী হবে, তারা সেখানে চিরদীন থাকবে।', 'Waallatheena amanoo waAAamiloo alssalihati olaika ashabu aljannati hum feeha khalidoona', 1, NOW(), NOW()),
(2, 83, 'وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ', '(স্মরণ করো,) যখন আমি বনী ইসরাঈলের কাছ থেকে (এ মর্মে) প্রতিশ্রুতি নিয়েছিলাম যে, তোমরা আল্লাহ তায়ালা ছাড়া অন্য কারও ইবাদত করবে না এবং মাতা পিতার সাথে সদ্ব্যবহার করবে, আত্মীয়-স্বজন, ইয়াতীম-মিসকীনদের সাথে ভালো ব্যবহার করবে, মানুষের সাথে সুন্দর কথা বলবে, নামাজ প্রতিষ্ঠা করবে, যাকাত প্রদান করবে; অতঃপর তোমাদের মধ্যে সামান্য কিছু সংখ্যক লোক ছাড়া অধিকাংশই (এই প্রতিশ্রুতি থেকে) ফিরে গেছো, (এভাবেই) তোমরা মুখ ফিরিয়ে নিয়েছিলে।', 'Waith akhathna meethaqa banee israeela la taAAbudoona illa Allaha wabialwalidayni ihsanan wathee alqurba waalyatama waalmasakeeni waqooloo lilnnasi husnan waaqeemoo alssalata waatoo alzzakata thumma tawallaytum illa qaleelan minkum waantum muAAridoona', 1, NOW(), NOW()),
(2, 84, 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ', 'তোমাদের (কাছ থেকে) আমি এ প্রতিশ্রুতিও নিয়েছিলাম যে, তোমরা তোমাদের কারও রক্তপাত করবে না এবং নিজেদের লোকদের তাদের ঘরবাড়ি থেকে উচ্ছেদ করবে না, অতঃপর তোমরা তা স্বীকারও করে নিয়েছিলে, তোমরা তো নিজেরাই (এ) সাক্ষ্য দিচ্ছো!', 'Waith akhathna meethaqakum la tasfikoona dimaakum wala tukhrijoona anfusakum min diyarikum thumma aqrartum waantum tashhadoona', 1, NOW(), NOW()),
(2, 85, 'ثُمَّ أَنتُمۡ هَـٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'তারপর এই হচ্ছো তোমরা! তোমরা নিজেদের হত্যা করতে লাগলে, তোমাদের এক দলকে তাদের ভিটেমাটি থেকে বিতাড়িত করে দিতে লাগলে, অন্যায় এবং যুলুম দ্বারা তোমরা তাদের (কাজের) ওপর তাদের পৃষ্ঠপোষকতা করতে থাকলে, (শুধু তাই নয়), কোনও লোক (যুদ্ধ) বন্দী হয়ে তোমাদের কাছে এলে তোমরা তাদের জন্য মুক্তিপণ দাবী করো, (অথচ) তাদের ঘরবাড়ি থেকে উচ্ছেদ করাটাই ছিলো তোমাদের ওপর অবৈধ কাজ (এবং আল্লাহ তায়ালাকে দেয়া প্রতিশ্রুতির সুস্পষ্ট লংঘন); তোমরা কি আল্লাহর কিতাবের একাংশ বিশ্বাস করো এবং আরেক অংশ অবিশ্বাস করো? (সাবধান!) কখনও যদি কোনও (জাতি কিংবা) ব্যক্তি (দ্বীনের অংশবিশেষের উপর ঈমান আনয়নের ) এ আচরণ করে, তাদের শাস্তি এ ছাড়া আর কী হবে যে, পার্থিব জীবনে তাদের লাঞ্ছনা ভোগ করতে হবে, পরকালেও তাদের কঠিনতম আযাবের দিকে নিক্ষেপ করা হবে; তোমরা যা করছো, আল্লাহ তায়ালা সেসব কিছু থেকে মোটেও উদাসীন নন।', 'Thumma antum haolai taqtuloona anfusakum watukhrijoona fareeqan minkum min diyarihim tathaharoona AAalayhim bialithmi waalAAudwani wain yatookum osara tufadoohum wahuwa muharramun AAalaykum ikhrajuhum afatuminoona bibaAAdi alkitabi watakfuroona bibaAAdin fama jazao man yafAAalu thalika minkum illa khizyun fee alhayati alddunya wayawma alqiyamati yuraddoona ila ashaddi alAAathabi wama Allahu bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(2, 86, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ', '(বস্তুত) এ লোকেরা আখেরাতের (স্থায়ী জীবনের ) বিনিময়ে দুনিয়ার (অস্থায়ী) জীবন খরিদ করে নিয়েছে (কেয়ামতের দিন ) তাদের উপর থেকে (তাদের) আযাব কিঞ্চিৎ পরিমাণও হালকা করা হবে না, না তাদের সেদিন (কোনও রকম) সাহায্য করা হবে!', 'Olaika allatheena ishtarawoo alhayata alddunya bialakhirati fala yukhaffafu AAanhumu alAAathabu wala hum yunsaroona', 1, NOW(), NOW()),
(2, 87, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَقَفَّيۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَآءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِيقٗا كَذَّبۡتُمۡ وَفَرِيقٗا تَقۡتُلُونَ', 'আমি মূসাকে কিতাব দিয়েছি, তারপর একে একে আমি অনেক নবীই পাঠিয়েছি এবং (বাবা ছাড়া সন্তান সৃষ্টি করার মতো) সুস্পষ্ট নিদর্শন দিয়ে আমি মারইয়াম পুত্র ঈসাকে পাঠিয়েছি এবং (আমার বাণী ও) পবিত্র আত্মার মাধ্যমে তাকে আমি সাহায্য করেছি; (অথচ) যখনই তোমাদের কাছে আল্লাহর কোনও নবী আসত, তোমাদের মনপূত না হলে তোমরা অহংকারের বশবর্তী হয়ে তাদের অস্বীকার করেছো, অতঃপর তাদের কাউকে তোমরা মিথ্যাবাদী বলেছো, (আবার) তাদের কোনও কোনও দলকে তোমরা হত্যাও করেছো।', 'Walaqad atayna moosa alkitaba waqaffayna min baAAdihi bialrrusuli waatayna AAeesa ibna maryama albayyinati waayyadnahu biroohi alqudusi afakullama jaakum rasoolun bima la tahwa anfusukumu istakbartum fafareeqan kaththabtum wafareeqan taqtuloona', 1, NOW(), NOW()),
(2, 88, 'وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ', 'তারা বলে, (হেদায়েতের জন্য) আমাদের মন (ও তার দরজা ) বন্ধ হয়ে আছে, তাদের কুফরী করার কারণে আল্লাহ তায়ালাও তাদের উপর অভিসম্পাত করেছেন, অতঃপর তাদের সামান্য পরিমাণ লোকই ঈমান এনেছে।', 'Waqaloo quloobuna ghulfun bal laAAanahumu Allahu bikufrihim faqaleelan ma yuminoona', 1, NOW(), NOW()),
(2, 89, 'وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ وَكَانُواْ مِن قَبۡلُ يَسۡتَفۡتِحُونَ عَلَى ٱلَّذِينَ كَفَرُواْ فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَٰفِرِينَ', 'যখনই তাদের কাছে আল্লাহ তায়ালার পক্ষ থেকে কোনও কিতাব নাযিল হলো- যা তাদের কাছে থাকা কিতাবের সত্যতা স্বীকার করে, (অথচ) এর আগে তারা নিজেরাই অন্যান্য কাফেরদের ওপর বিজয়ী হওয়ার জন্য (এ কিতাব ও তার বাহকের আগমন) কামনা করেছিলো, (কিন্তু আজ ) যখন তা তাদের কাছে এলো এবং যাকে তারা যথাযথ চিনতেও পারলো- তারা অস্বীকার করলো, যারা (আল্লাহর কিতাব) অস্বীকার করে তাদের উপর আল্লাহর অভিসম্পাত।', 'Walamma jaahum kitabun min AAindi Allahi musaddiqun lima maAAahum wakanoo min qablu yastaftihoona AAala allatheena kafaroo falamma jaahum ma AAarafoo kafaroo bihi falaAAnatu Allahi AAala alkafireena', 1, NOW(), NOW()),
(2, 90, 'بِئۡسَمَا ٱشۡتَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡ أَن يَكۡفُرُواْ بِمَآ أَنزَلَ ٱللَّهُ بَغۡيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٖۚ وَلِلۡكَٰفِرِينَ عَذَابٞ مُّهِينٞ', 'কতো নিকৃষ্ট (বস্তু) সেটি, যার বিনিময়ে তারা তাদের নিজেদের বিক্রয় করে দিয়েছে, শুধু গোঁড়ামির বশবর্তী হয়েই তারা আল্লাহর নাযিল করা বিধান অস্বীকার করেছে- (তাও শুধু এ কারণে), আল্লাহ তায়ালা তাঁর বান্দাদের মধ্য থেকে যাকে চান তাকে নবুওত দিয়ে অনুগ্রহ করেন, (এ কুফরীর ফলে) তারা ক্রোধের উপর ক্রোধে আক্রান্ত হলো; আর কাফেরদের জন্য রয়েছে অপমানজনক শাস্তি।', 'Bisama ishtaraw bihi anfusahum an yakfuroo bima anzala Allahu baghyan an yunazzila Allahu min fadlihi AAala man yashao min AAibadihi fabaoo bighadabin AAala ghadabin walilkafireena AAathabun muheenun', 1, NOW(), NOW()),
(2, 91, 'وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ بِمَآ أَنزَلَ ٱللَّهُ قَالُواْ نُؤۡمِنُ بِمَآ أُنزِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقٗا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِينَ', 'যখন তাদের বলা হয়, আল্লাহ তায়ালা যা কিছু নাযিল করেছেন তার ওপর ঈমান আনো, তখন তারা বলে, আমরা তো শুধু সেসব কিছুর ওপর ঈমান আনি যা আমাদের (বনী ইসরাঈল জাতির) ওপর নাযিল করা হয়েছে। এর বাইরে যা- তা তারা অস্বীকার করে, (অথচ) তা একান্ত সত্য, তা তাদের কাছে নাযিল করা আল্লাহর কথাগুলোকেও সত্য বলে স্বীকার করে; (হে নবী,) তুমি বলো, তোমরা যদি ঈমানদার হও তাহলে এর আগে আল্লাহর নবীদের হত্যা করেছিলে কেন?', 'Waitha qeela lahum aminoo bima anzala Allahu qaloo numinu bima onzila AAalayna wayakfuroona bima waraahu wahuwa alhaqqu musaddiqan lima maAAahum qul falima taqtuloona anbiyaa Allahi min qablu in kuntum mumineena', 1, NOW(), NOW()),
(2, 92, '۞وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ', 'তোমাদের কাছে তো সুস্পষ্ট নিদর্শন সহকারে মূসাও (নবী হয়ে) এসেছিলো, অতঃপর তার (সামান্য অনুপস্থিতির ) অরই তোমরা একটি বাছুরকে (মাবুদ বলে) গ্রহণ করে নিলে! তোমরা (আসলেই) যালিম!', 'Walaqad jaakum moosa bialbayyinati thumma ittakhathtumu alAAijla min baAAdihi waantum thalimoona', 1, NOW(), NOW()),
(2, 93, 'وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', '(স্মরণ করো,) যখন আমি তোমাদের কাছ থেকে একটি প্রতিশ্রুতি আদায় করেছিলাম, তোমাদের (মাথার) উপর তূর পাহাড় তুলে ধরে (আমি বলেছিলাম), যা কিছু বিধান আমি তোমাদের দিয়েছি তা শক্ত করে আঁকড়ে ধরো এবং (আমার কথাগুলো) ফহুনো, ( এর জবাবে) তারা (মুখে তো) বললো হ্যা, আমরা (তোমার কথা) শুনেছি, কিন্তু (বাস্তবে তা অস্বীকার করে তারা বললো,) আমরা তা অমান্য করলাম, (আসলে আল্লাহ তায়ালাকে) তাদের অস্বীকার করার কারণে সেই বাছুরকে মাবুদ বানানো (-এর নেশা দ্বারা তখনও) তাদের মনকে আকৃষ্ট করে রাখা হয়েছিল, তুমি বলো, যদি তোমরা সত্যিই মুমিন হও তাহলে বলতে পারো, এটা কত খারাপ ঈমান- যা তোমাদের এ ধরণের কাজের আদেশ দেয়?', 'Waith akhathna meethaqakum warafaAAna fawqakumu alttoora khuthoo ma ataynakum biquwwatin waismaAAoo qaloo samiAAna waAAasayna waoshriboo fee quloobihimu alAAijla bikufrihim qul bisama yamurukum bihi eemanukum in kuntum mumineena', 1, NOW(), NOW()),
(2, 94, 'قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ', '(হে নবী,) তুমি বলো, যদি (তোমরা মনে করো,) অন্যদের বদলে পরকালের নিবাস আল্লাহর কাছে শুধু তোমাদের জন্যই নির্দিষ্ট- তাহলে (তা পাওয়ার জন্য) তোমরা মৃত্যু কামনা করো না কেন? যদি তোমরা সত্যবাদি হও!', 'Qul in kanat lakumu alddaru alakhiratu AAinda Allahi khalisatan min dooni alnnasi fatamannawoo almawta in kuntum sadiqeena', 1, NOW(), NOW()),
(2, 95, 'وَلَن يَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ', '(হে নবী, জেনে রাখো,) তারা নিজেদের হাত দিয়ে যা অর্জন করেছে (তার পরিণাম) জানার পর এরা কখনও তা কামনা করবে না, আল্লাহ তায়ালা যালিমদের ভালো করেই জানেন।', 'Walan yatamannawhu abadan bima qaddamat aydeehim waAllahu AAaleemun bialththalimeena', 1, NOW(), NOW()),
(2, 96, 'وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٖ وَمِنَ ٱلَّذِينَ أَشۡرَكُواْۚ يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَمَّرُ أَلۡفَ سَنَةٖ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن يُعَمَّرَۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', 'তুমি অবশ্যই তাদেরকে দেখতে পাবে বেঁচে থাকার ওপর তারা বেশি লোভী, যারা শিরক করে (তারাও এদেরই মতো), এদের প্রত্যেক ব্যক্তিই হাজার বছর জীবিত থাকতে চায়, কিন্তু যত দীর্ঘ জীবনই এদের দেওয়া হোক না কেন, তা কখনও (আল্লাহর) আযাব থেকে (এদের) বাঁচাতে পারবে না; আল্লাহ তায়ালা এদের (যাবতীয় ) কাজকর্ম পর্যবেক্ষণ করেন।', 'Walatajidannahum ahrasa alnnasi AAala hayatin wamina allatheena ashrakoo yawaddu ahaduhum law yuAAammaru alfa sanatin wama huwa bimuzahzihihi mina alAAathabi an yuAAammara waAllahu baseerun bima yaAAmaloona', 1, NOW(), NOW()),
(2, 97, 'قُلۡ مَن كَانَ عَدُوّٗا لِّـجِبۡرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَهُدٗى وَبُشۡرَىٰ لِلۡمُؤۡمِنِينَ', '(হে নবী,) তুমি বলো, কে সে ব্যক্তি যে জিবরাঈলের শত্রু হতে পারে? (অথচ) সে তো আল্লাহর আদেশে (আল্লাহর) এমন সব বাণী তোমার অন্তকরণে নাযিল করে, যা তাদের কাছে বিদ্যমান বিষয়সমূহের সত্যতা স্বীকার করে, (আসলে) এ (গ্রন্থ) হচ্ছে মুমিনদের জন্য হিদায়েত ও সুসংবাদ।', 'Qul man kana AAaduwwan lijibreela fainnahu nazzalahu AAala qalbika biithni Allahi musaddiqan lima bayna yadayhi wahudan wabushra lilmumineena', 1, NOW(), NOW()),
(2, 98, 'مَن كَانَ عَدُوّٗا لِّلَّهِ وَمَلَـٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوّٞ لِّلۡكَٰفِرِينَ', 'যারা আল্লাহর শত্রু, শত্রু তাঁর (বাণীবাহক ) ফেরেশতার ও নবী রাসূলদের-(শত্রু) জিবরাঈলের ও মীকাঈলের, (তাদের জানা উচিৎ) স্বয়ং আল্লাহ তায়ালাই হচ্ছেন কাফেরদের (বড়ো) শত্রু।', 'Man kana AAaduwwan lillahi wamalaikatihi warusulihi wajibreela wameekala fainna Allaha AAaduwwun lilkafireena', 1, NOW(), NOW()),
(2, 99, 'وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكَ ءَايَٰتِۭ بَيِّنَٰتٖۖ وَمَا يَكۡفُرُ بِهَآ إِلَّا ٱلۡفَٰسِقُونَ', 'অবশ্যই আমি তোমাদের কাছে সুস্পষ্ট নিদর্শনসমূহ পাঠিয়েছি; পাপী ব্যক্তিরা ছাড়া তাকে কেউই অস্বীকার করতে পারে না।', 'Walaqad anzalna ilayka ayatin bayyinatin wama yakfuru biha illa alfasiqoona', 1, NOW(), NOW()),
(2, 100, 'أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ', '(এমনকি হয়নি যে,) যখনই তারা কোনো ওয়াদা করেছে (তখনই ) তাদের এক দল তা ভংগ করেছে; (মূলত) তাদের অধিকাংশ লোকই ঈমান আনে না।', 'Awakullama AAahadoo AAahdan nabathahu fareequn minhum bal aktharuhum la yuminoona', 1, NOW(), NOW()),
(2, 101, 'وَلَمَّا جَآءَهُمۡ رَسُولٞ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقٞ لِّمَا مَعَهُمۡ نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ', 'যখনই তাদের কাছে আল্লাহর পক্ষ থেকে কোনো নবী আসে এবং যে তাদের কাছে (আগের কিতাবে) যেসব কথা মজুদ রয়েছে তার সত্যতা স্বীকার করে, তখনি সেই আগের কিতাব– যাদের দেয়া হয়েছে তাদের একটি দল আল্লাহর (পূর্ববর্তী) কিতাবের কথাগুলোকে এমনভাবে তাদের পেছনের দিকে ফেলে দেয়, যেন তারা এ ব্যাপারে কিছুই জানে না।', 'Walamma jaahum rasoolun min AAindi Allahi musaddiqun lima maAAahum nabatha fareequn mina allatheena ootoo alkitaba kitaba Allahi waraa thuhoorihim kaannahum la yaAAlamoona', 1, NOW(), NOW()),
(2, 102, 'وَٱتَّبَعُواْ مَا تَتۡلُواْ ٱلشَّيَٰطِينُ عَلَىٰ مُلۡكِ سُلَيۡمَٰنَۖ وَمَا كَفَرَ سُلَيۡمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُواْ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَآ أُنزِلَ عَلَى ٱلۡمَلَكَيۡنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ وَلَبِئۡسَ مَا شَرَوۡاْ بِهِۦٓ أَنفُسَهُمۡۚ لَوۡ كَانُواْ يَعۡلَمُونَ', '(এর সাথে যাদুমন্ত্রের) এমন কিছু জিনিসও এরা অনুসরণ করতে শুরু করলো, (যা) শয়তানরা সোলায়মান (নবী)-এর রাজত্বের সময় পড়তো, (সত্যি কথা হচ্ছে) সোলায়মান কখনো (যাদু ব্যবহার করে আল্লাহকে) অস্বীকার করেনি, বরং (তাকে) অস্বীকার তো করেছে সেসব অভিশপ্ত শয়তান, যারা মানুষকে যাদুমন্ত্র শিক্ষা দিয়েছে; ব্যাবিলনে হারুত মারুত দু’জন ফেরেশতার কাছে যা কিছু পাঠানো হয়েছিলো, (তা ছিলো যাদুপাগল মানুষদের পরীক্ষার জন্যে, আল্লাহর) সেই দু’জন ফেরেশতা (কাউকে) ততক্ষণ পর্যন্ত এ বিষয়ের শিক্ষা দিতো না, যতক্ষণ পর্যন্ত তারা (এ কথাটা) তাদের বলে না দিতো যে, আমরা হচ্ছি (আল্লাহর) পরীক্ষা মাত্র, অতএব (কোনো অবস্থায়ই) তুমি (এ বিদ্যা দিয়ে আল্লাহ তায়ালাকে) অস্বীকার করো না, (এ সত্ত্বেও) তারা তাদের কাছ থেকে এমন কিছু বিদ্যা শিখে নিয়েছিলো, যা দিয়ে এরা স্বামী স্ত্রীর মাঝে বিচ্ছেদের সৃষ্টি করতো, (যদিও) আল্লাহর ইচ্ছা ছাড়া কেউ কারো সামান্যতম ক্ষতিও সাধন করতে পারে না; তারা (মূলত) এমন কিছু শিখে যা তাদের কোনো উপকার যেমন করতে পারে না, তেমনি তা তাদের কোনো ক্ষতিও করতে পারে না; তারা ভালো করেই এটা জেনে নিলো যে, (শ্রম ও অর্থ দিয়ে) যা তারা কিনে নিয়েছে পরকালে তার কোনো মূল্য নেই; তারা নিজেদের জীবনের পরিবর্তে যা ক্রয় করে নিয়েছে তা সত্যিই নিকৃষ্ট, (কতো ভালো হতো) যদি তারা (কথাটা) জানতো!', 'WaittabaAAoo ma tatloo alshshayateenu AAala mulki sulaymana wama kafara sulaymanu walakinna alshshayateena kafaroo yuAAallimoona alnnasa alssihra wama onzila AAala almalakayni bibabila haroota wamaroota wama yuAAallimani min ahadin hatta yaqoola innama nahnu fitnatun fala takfur fayataAAallamoona minhuma ma yufarriqoona bihi bayna almari wazawjihi wama hum bidarreena bihi min ahadin illa biithni Allahi wayataAAallamoona ma yadurruhum wala yanfaAAuhum walaqad AAalimoo lamani ishtarahu ma lahu fee alakhirati min khalaqin walabisa ma sharaw bihi anfusahum law kanoo yaAAlamoona', 1, NOW(), NOW()),
(2, 103, 'وَلَوۡ أَنَّهُمۡ ءَامَنُواْ وَٱتَّقَوۡاْ لَمَثُوبَةٞ مِّنۡ عِندِ ٱللَّهِ خَيۡرٞۚ لَّوۡ كَانُواْ يَعۡلَمُونَ', 'তারা যদি (আল্লাহর ওপর) ঈমান আনতো এবং তাকওয়া অবলম্বন করতো, তাহলে আল্লাহর পক্ষ থেকে তারা উৎকৃষ্টতম পুরস্কার পেতো; (কতো ভালো হতো) যদি তারা (এটা) অনুধাবন করতো!', 'Walaw annahum amanoo waittaqaw lamathoobatun min AAindi Allahi khayrun law kanoo yaAAlamoona', 1, NOW(), NOW()),
(2, 104, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا وَٱسۡمَعُواْۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٞ', 'হে ঈমানদার ব্যক্তিরা, (ধৃষ্টতার সাথে কখনো) বলো না (হে নবী), ‘তুমি আমাদের কথা শোনো‘, বরং (তাঁর দৃষ্টি আকর্ষণ করতে হলে) বলো, (হে নবী) ‘আমাদের প্রতি লক্ষ্য করো‘, তোমরা (সর্বদা তাঁর কথা) শুনবে, (মনে রাখবে), যারা (তাঁর কথা) অস্বীকার করে তাদের জন্যে অত্যন্ত বেদনাদায়ক শাস্তি রয়েছে।', 'Ya ayyuha allatheena amanoo la taqooloo raAAina waqooloo onthurna waismaAAoo walilkafireena AAathabun aleemun', 1, NOW(), NOW()),
(2, 105, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ', '(আসলে এই) আহলে কিতাব এবং যারা শেরেক করে তারা কেউই এটা পছন্দ করে না যে, তোমার কাছে তোমার মালিকের পক্ষ থেকে ভালো কিছু নাযিল হোক, কিন্তু আল্লাহ তায়ালা যাকে চান তাঁকেই তাঁর অনুগ্রহে (নবুওতের জন্যে) বেছে নেন; আল্লাহ তায়ালা অত্যন্ত অনুগ্রহশীল ।', 'Ma yawaddu allatheena kafaroo min ahli alkitabi wala almushrikeena an yunazzala AAalaykum min khayrin min rabbikum waAllahu yakhtassu birahmatihi man yashao waAllahu thoo alfadli alAAatheemi', 1, NOW(), NOW()),
(2, 106, '۞مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'আমি (যখন) কোনো আয়াত বাতিল করে দেই কিংবা (বিশেষ কারণে মানুষদের) তা ভুলিয়ে দিতে চাই, তখন তার জায়গায় তার চেয়ে উৎকৃষ্ট কিংবা তারই মতো কোনো আয়াত এনে হাযির করি, তুমি কি জানো না, আল্লাহ তায়ালা সব কিছুর উপর ক্ষমতাবান।', 'Ma nansakh min ayatin aw nunsiha nati bikhayrin minha aw mithliha alam taAAlam anna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 107, 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ', 'তুমি কি জানো না, আসমানসমূহ ও যমীনের সার্বভৌমত্ব একমাত্র আল্লাহ তায়ালার জন্যেই নির্দিষ্ট; আল্লাহ তায়ালা ছাড়া তোমাদের কোনো বন্ধু নেই, নেই কোনো সাহায্যকারীও।', 'Alam taAAlam anna Allaha lahu mulku alssamawati waalardi wama lakum min dooni Allahi min waliyyin wala naseerin', 1, NOW(), NOW()),
(2, 108, 'أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'তোমরা কি তোমাদের নবীর কাছে সে ধরনের (উদ্ভট) প্রশ্ন করতে চাও— যেমনি তোমাদের আগে মূসাকে প্রশ্ন করা হয়েছিলো; কেউ যদি ঈমানকে কুফরীর সাথে বদল করে নেয়, তাহলে সে ব্যক্তি সোজা পথ থেকে গোমরাহ হয়ে যাবে।', 'Am tureedoona an tasaloo rasoolakum kama suila moosa min qablu waman yatabaddali alkufra bialeemani faqad dalla sawaa alssabeeli', 1, NOW(), NOW()),
(2, 109, 'وَدَّ كَثِيرٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدٗا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'আহলে কিতাবদের অনেকেই বিদ্বেষের কারণে ঈমানের বদলে তোমাদের আবার সেই কুফরীতে ফিরিয়ে নিতে চাইবে, (এমনকি) সত্য তাদের কাছে স্পষ্ট হয়ে যাওয়ার পরও (তারা এপথ থেকে বিরত হবে না), অতএব তাদের ব্যাপারে আল্লাহর সিদ্ধান্ত আসা পর্যন্ত তোমরা ক্ষমার নীতি অবলম্বন করো এবং তাদের সাথে ভালো ব্যবহার করো; অবশ্যই আল্লাহ তায়ালা সব কিছুর উপর ক্ষমতাবান।', 'Wadda katheerun min ahli alkitabi law yaruddoonakum min baAAdi eemanikum kuffaran hasadan min AAindi anfusihim min baAAdi ma tabayyana lahumu alhaqqu faoAAfoo waisfahoo hatta yatiya Allahu biamrihi inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 110, 'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ', 'তোমরা নামায প্রতিষ্ঠা করো এবং যাকাত আদায় করো; (এর মাধ্যমে) যেসব নেকী তোমরা আল্লাহর কাছে (অগ্রিম) পাঠাবে তাঁর কাছে (গিয়ে এর সবই) তোমরা (মজুদ) পাবে; তোমরা যা কিছুই করো আল্লাহ তায়ালা অবশ্যই (এর) সব কিছু দেখতে পান।', 'Waaqeemoo alssalata waatoo alzzakata wama tuqaddimoo lianfusikum min khayrin tajidoohu AAinda Allahi inna Allaha bima taAAmaloona baseerun', 1, NOW(), NOW()),
(2, 111, 'وَقَالُواْ لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ تِلۡكَ أَمَانِيُّهُمۡۗ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ', 'তারা বলে, ইহুদী কিংবা খৃস্টান ছাড়া আর কেউই বেহেশতে প্রবেশ করবে না, (আসলে) এগুলো তাদের একটা মিথ্যা কল্পনা; (হে নবী,) তুমি বলো, যদি তোমরা সত্যবাদী হও (তাহলে) তোমাদের দলিল প্রমাণ নিয়ে এসো!', 'Waqaloo lan yadkhula aljannata illa man kana hoodan aw nasara tilka amaniyyuhum qul hatoo burhanakum in kuntum sadiqeena', 1, NOW(), NOW()),
(2, 112, 'بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ فَلَهُۥٓ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'হ্যাঁ, যে ব্যক্তি সৎকর্মশীল হয়ে আল্লাহর সামনে নিজের সত্তাকে সমর্পণ করে দেবে, তার জন্যে তার মালিকের কাছে (এর) বিনিময় থাকবে, তাদের কোনো ভয় ভীতি নেই, আর না তারা (সেদিন) দুশ্চিন্তাগ্রস্থ হবে!', 'Bala man aslama wajhahu lillahi wahuwa muhsinun falahu ajruhu AAinda rabbihi wala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 113, 'وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيۡسَتِ ٱلۡيَهُودُ عَلَىٰ شَيۡءٖ وَهُمۡ يَتۡلُونَ ٱلۡكِتَٰبَۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ', 'ইহুদীরা বলে, খৃস্টানরা কোনো কিছুর ওপরই প্রতিষ্ঠিত নয়, খৃস্টানরা বলে ইহুদীরাও কোনো কিছুর ওপর প্রতিষ্ঠিত নয়, অথচ এরা (উভয়েই) কিতাব পাঠ করে, এভাবেই যারা আদৌ কিতাবের কোনো কিছুই জানে না, এমন লোকেরা (আবার এদের উভয়ের সম্পর্কে) তাদের কথার মতো (এই) একই ধরনের কথা বলে । তারা যে বিষয়ে মতবিরোধ করছে আল্লাহ তায়ালা শেষ বিচারের দিনে সে বিষয়ে তাদের মাঝে মীমাংসা করে দেবেন।', 'Waqalati alyahoodu laysati alnnasara AAala shayin waqalati alnnasara laysati alyahoodu AAala shayin wahum yatloona alkitaba kathalika qala allatheena la yaAAlamoona mithla qawlihim faAllahu yahkumu baynahum yawma alqiyamati feema kanoo feehi yakhtalifoona', 1, NOW(), NOW()),
(2, 114, 'وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذۡكَرَ فِيهَا ٱسۡمُهُۥ وَسَعَىٰ فِي خَرَابِهَآۚ أُوْلَـٰٓئِكَ مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ', 'তার চেয়ে বড়ো যালেম আর কে আছে, যে ব্যক্তি আল্লাহর (ঘর) মাসজিদে তাঁর নাম স্মরণ করতে বাধা দেয় এবং তার ধ্বংস সাধনে সচেষ্ট হয়, এ ধরনের লোকদের (তো) তাতে ঢোকা শোভনীয়ই নয়, তবে একান্ত ভীত সন্ত্রস্তভাবে (ঢুকলে তা ভিন্ন কথা), তাদের জন্যে পৃথিবীতে যেমন অপমান লাঞ্ছনা রয়েছে, তেমনি রয়েছে পরকালে কঠিনতম শাস্তি।', 'Waman athlamu mimman manaAAa masajida Allahi an yuthkara feeha ismuhu wasaAAa fee kharabiha olaika ma kana lahum an yadkhulooha illa khaifeena lahum fee alddunya khizyun walahum fee alakhirati AAathabun AAatheemun', 1, NOW(), NOW()),
(2, 115, 'وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ', 'পূর্ব পশ্চিম সবই আল্লাহ তায়ালার, তোমরা যে দিকেই মুখ ফেরাবে সেদিকেই তো আল্লাহ তায়ালা রয়েছেন; অবশ্যই আল্লাহ তায়ালা সর্বব্যাপী এবং জ্ঞানী।', 'Walillahi almashriqu waalmaghribu faaynama tuwalloo fathamma wajhu Allahi inna Allaha wasiAAun AAaleemun', 1, NOW(), NOW()),
(2, 116, 'وَقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ بَل لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ كُلّٞ لَّهُۥ قَٰنِتُونَ', '(খৃস্টান) লোকেরা বলে, আল্লাহ তায়ালা (অমুককে) নিজের সন্তান (-রূপে) গ্রহণ করেছেন, (অথচ) সব পবিত্রতা একান্তভাবে তাঁর, (তিনি এসব কিছুর অনেক ঊর্ধ্বে); আসমানসমূহ ও যমীনের সব কিছুই তাঁর জন্যে, এর সকল বস্তুই তাঁর অনুগত।', 'Waqaloo itakhatha Allahu waladan subhanahu bal lahu ma fee alssamawati waalardi kullun lahu qanitoona', 1, NOW(), NOW()),
(2, 117, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'আসমানসমূহ ও যমীনের তিনিই হচ্ছেন উদ্ভাবক, যখন তিনি কোনো একটি বিষয়ের সিদ্ধান্ত করেন, সে ব্যাপারে শুধু (এটুকুই) বলেন ‘হও’, আর সাথে সাথেই তা হয়ে যায়।', 'BadeeAAu alssamawati waalardi waitha qada amran fainnama yaqoolu lahu kun fayakoonu', 1, NOW(), NOW()),
(2, 118, 'وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ', 'যারা (সঠিক কথা) জানে না তারা বলে, আল্লাহ তায়ালা নিজে আমাদের সাথে কথা বলেন না কেন, অথবা এমন কোনো নিদর্শন আমাদের কাছে কেন আসে না (যার মাধ্যমে আমরা তাঁকে চিনতে পারবো); এদের আগের লোকেরাও এদের মতো করেই কথা বলতো; এদের সবার মন (আসলে) একই ধরনের; (আল্লাহকে) যারা (দৃঢ়ভাবে) বিশ্বাস করে আমি তাদের জন্যে আমার নিদর্শনসমূহ সুস্পষ্ট করে পেশ করে দিয়েছি।', 'Waqala allatheena la yaAAlamoona lawla yukallimuna Allahu aw tateena ayatun kathalika qala allatheena min qablihim mithla qawlihim tashabahat quloobuhum qad bayyanna alayati liqawmin yooqinoona', 1, NOW(), NOW()),
(2, 119, 'إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ', 'অবশ্যই আমি তোমাকে সত্য (দ্বীন)-সহ পাঠিয়েছি, (পাঠিয়েছি) আযাবের ভীতি প্রদর্শনকারী ও (জান্নাতের) সুসংবাদবাহী হিসেবে । (জেনে রেখো), তোমাকে জাহান্নামের অধিবাসীদের ব্যাপারে কোনোরকম প্রশ্ন করা হবে না।', 'Inna arsalnaka bialhaqqi basheeran wanatheeran wala tusalu Aaan ashabi aljaheemi', 1, NOW(), NOW()),
(2, 120, 'وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ', 'ইহুদী ও খৃস্টানরা কখনো তোমার ওপর খুশী হবে না, যতোক্ষণ না তুমি তাদের দলের অনুসরণ করতে শুরু করবে, তুমি তাদের বলো, আল্লাহ তায়ালার হেদায়াতই হচ্ছে একমাত্র হেদায়াত; তোমার কাছে সঠিক জ্ঞান আসার পরও যদি তুমি তাদের ইচ্ছানুসারে চলতে থাকো, তাহলে আল্লাহ তায়ালা ছাড়া তোমার কোনো বন্ধু ও সাহায্যকারী থাকবে না।', 'Walan tarda AAanka alyahoodu wala alnnasara hatta tattabiAAa millatahum qul inna huda Allahi huwa alhuda walaini ittabaAAta ahwaahum baAAda allathee jaaka mina alAAilmi ma laka mina Allahi min waliyyin wala naseerin', 1, NOW(), NOW()),
(2, 121, 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَـٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', 'যাদের আমি কিতাব দিয়েছি তাদের মাঝে এমন কিছু লোকও আছে যারা এ (কোরআন)-কে তেলাওয়াতের হক আদায় করে পড়ে; তারা তার ওপর ঈমানও আনে; যারা (একে) অস্বীকার করে তারাই হচ্ছে আসল ক্ষতিগ্রস্ত লোক।', 'Allatheena ataynahumu alkitaba yatloonahu haqqa tilawatihi olaika yuminoona bihi waman yakfur bihi faolaika humu alkhasiroona', 1, NOW(), NOW()),
(2, 122, 'يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ', 'হে বনী ইসরাঈল (জাতি), তোমরা আমার সে নেয়ামত স্মরণ করো যা আমি তোমাদের ওপর দান করেছি, (সে নেয়ামতের অংশ হিসেবে) আমি (এক সময়) তোমাদের সৃষ্টিকুলের ওপর শ্রেষ্ঠত্ব দান করেছিলাম।', 'Ya banee israeela othkuroo niAAmatiya allatee anAAamtu AAalaykum waannee faddaltukum AAala alAAalameena', 1, NOW(), NOW()),
(2, 123, 'وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمۡ يُنصَرُونَ', 'তোমরা সে দিনটিকে ভয় করো, যেদিন একজন মানুষ আরেকজনের কোনোই কাজে আসবে না, না (সেদিন) তার কাছ থেকে কোনোরকম বিনিময় নেয়া হবে, (একের পক্ষে অন্যের) সুপারিশও সেদিন কোনো উপকারে আসবে না, (সেদিন) এসব লোকদের কোনোরকম সাহায্যও করা হবে না।', 'Waittaqoo yawman la tajzee nafsun AAan nafsin shayan wala yuqbalu minha AAadlun wala tanfaAAuha shafaAAatun wala hum yunsaroona', 1, NOW(), NOW()),
(2, 124, '۞وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّـٰلِمِينَ', '(স্মরণ করো,) যখন ইবরাহীমকে তার ‘রব’ কতিপয় বিষয়ে (তাঁর আনুগত্যের) পরীক্ষা নিলেন, অতপর সে তা পুরোপুরি পূরণ করলো, আল্লাহ তায়ালা বললেন, আমি তোমাকে মানব জাতির জন্যে নেতা বানাতে চাই; সে বললো, আমার ভবিষ্যত বংশধররাও (কি নেতা হিসেবে বিবেচিত হবে)? আল্লাহ তায়ালা বললেন, আমার এ প্রতিশ্রুতি যালেমদের কাছে পৌঁছবে না।', 'Waithi ibtala ibraheema rabbuhu bikalimatin faatammahunna qala innee jaAAiluka lilnnasi imaman qala wamin thurriyyatee qala la yanalu AAahdee alththalimeena', 1, NOW(), NOW()),
(2, 125, 'وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', '(স্মরণ করো,) আমি যখন মানুষদের মিলনস্থল ও নিরাপত্তার কেন্দ্র হিসেবে (কাবা) ঘর নির্মাণ করেছিলাম; (আমি তখন তাদের আদেশ দিয়েছিলাম, তোমরা ইবরাহীমের দাঁড়ানোর স্থানটিকে নামাযের স্থান হিসেবে গ্রহণ করো; আমি ইবরাহীম ও ইসমাঈলকে আদেশ দিয়েছিলাম যেন তারা আমার ঘর (কাবা)-কে (হজ্জ ও ওমরার) তাওয়াফকারীদের জন্যে, আল্লাহর এবাদাতে আত্মনিয়োগকারীদের জন্যে, (সর্বোপরি তাঁর নামে) রুকু-সাজদাকারীদের জন্যে পবিত্র করে রাখে।', 'Waith jaAAalna albayta mathabatan lilnnasi waamnan waittakhithoo min maqami ibraheema musallan waAAahidna ila ibraheema waismaAAeela an tahhira baytiya lilttaifeena waalAAakifeena waalrrukkaAAi alssujoodi', 1, NOW(), NOW()),
(2, 126, 'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'ইবরাহীম যখন বলেছিলো, হে রব, এ শহরকে তুমি (শান্তি ও) নিরাপত্তার শহর বানিয়ে দাও এবং এখানকার অধিবাসীদের মাঝে যে (কিংবা যারা) আল্লাহ তায়ালা এবং পরকাল দিবসকে বিশ্বাস করে, তুমি তাদের ফলমূল দিয়ে রেযেক দাও; আল্লাহ তায়ালা বললেন (হ্যাঁ), যে ব্যক্তি (আমাকে) অস্বীকার করবে তাকেও আমি অল্প কয়েকদিন জীবনের উপকরণ উপভোগ করাতে থাকবো, অতপর আমি ধীরে ধীরে তাদের আগুনের আযাবের জন্যে বাধ্য করবো, যা সত্যিই বড়ো নিকৃষ্টতম স্থান।', 'Waith qala ibraheemu rabbi ijAAal hatha baladan aminan waorzuq ahlahu mina alththamarati man amana minhum biAllahi waalyawmi alakhiri qala waman kafara faomattiAAuhu qaleelan thumma adtarruhu ila AAathabi alnnari wabisa almaseeru', 1, NOW(), NOW()),
(2, 127, 'وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'ইবরাহীম ও ইসমাঈল যখন এই ঘরের ভিত্তি উঠাচ্ছিলো (তখন তারা আল্লাহর কাছে দোয়া করলো), হে আমাদের রব, (আমরা যে উদ্দেশ্যে এ ঘর নির্মাণ করেছি, তা) তুমি আমাদের কাছ থেকে কবুল করো, অবশ্যই তুমি সব কিছু জানো এবং সব কিছু শোনো।', 'Waith yarfaAAu ibraheemu alqawaAAida mina albayti waismaAAeelu rabbana taqabbal minna innaka anta alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(2, 128, 'رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '(তারা আরো বললো,) হে আমাদের রব, আমাদের উভয়কে তুমি তোমার (অনুগত) মুসলিম বান্দা বানাও এবং আমাদের (পরবর্তী) বংশধরদের মাঝ থেকেও তুমি তোমার একদল অনুগত (বান্দা) বানিয়ে দাও, (হে মালিক,) তুমি (এবাদাতের) আনুষ্ঠানিক নিয়মনীতিসমূহ আমাদের দেখিয়ে দাও এবং তুমি আমাদের ওপর দয়াপরবশ হও, অবশ্যই তুমি তাওবা কবুলকারী ও পরম দয়ালু।', 'Rabbana waijAAalna muslimayni laka wamin thurriyyatina ommatan muslimatan laka waarina manasikana watub AAalayna innaka anta alttawwabu alrraheemu', 1, NOW(), NOW()),
(2, 129, 'رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'হে আমাদের রব, তাদের (বংশের) মধ্যে তাদের নিজেদের মাঝ থেকে তুমি (এমন) একজন রসূল পাঠাও, যে তাদের কাছে তোমার আয়াতসমূহ তেলাওয়াত করবে, তাদের তোমার কিতাবের জ্ঞান ও প্রজ্ঞা শিক্ষা দেবে, উপরন্তু (তা দিয়ে) সে তাদের পবিত্র করে দেবে (হে আল্লাহ, তুমি আমাদের দোয়া কবুল করো); অবশ্যই তুমি মহাপরাক্রমশালী, পরম কুশলী।', 'Rabbana waibAAath feehim rasoolan minhum yatloo AAalayhim ayatika wayuAAallimuhumu alkitaba waalhikmata wayuzakkeehim innaka anta alAAazeezu alhakeemu', 1, NOW(), NOW()),
(2, 130, 'وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ', '(জেনে বুঝে) যে নিজেকে মূর্খ বানিয়ে রেখেছে সে ব্যক্তি ছাড়া আর কে এমন হবে, যে ইবরাহীমের বিধান থেকে মুখ ফিরিয়ে নেবে? (অথচ) তাকে আমি (নবুওতের জন্যে) বাছাই করে নিয়েছি, শেষ বিচারের দিনে সে অবশ্যই নেক লোকদের মধ্যে শামিল হবে।', 'Waman yarghabu AAan millati ibraheema illa man safiha nafsahu walaqadi istafaynahu fee alddunya wainnahu fee alakhirati lamina alssaliheena', 1, NOW(), NOW()),
(2, 131, 'إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ', 'যখন আমি তাকে বললাম, তুমি (আমার অনুগত) মুসলিম হয়ে যাও, সে বললো, আমি সৃষ্টিকুলের মালিক (আল্লাহ তায়ালা)-এর পূর্ণ আনুগত্য স্বীকার করে নিলাম।', 'Ith qala lahu rabbuhu aslim qala aslamtu lirabbi alAAalameena', 1, NOW(), NOW()),
(2, 132, 'وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ', '(যে পথ ইবরাহীম নিজের জন্যে বেছে নিলো,) সে (পথে চলার) জন্যে সে তার সন্তান সন্ততিকেও ওসিয়ত করে গেলো, ইয়াকুবও (তার সন্তানদের ওসিয়ত করে বললো); হে আমার সন্তানরা, নিশ্চয়ই আল্লাহ তায়ালা তোমাদের জন্যে (এই) দ্বীনকে পছন্দ করে দিয়েছেন, অতএৰ কোনো অবস্থায়ই (এ বিধানের) আনুগত্য স্বীকার করা ব্যতিরেকে তোমরা মৃত্যুবরণ করো না।', 'Wawassa biha ibraheemu baneehi wayaAAqoobu ya baniyya inna Allaha istafa lakumu alddeena fala tamootunna illa waantum muslimoona', 1, NOW(), NOW()),
(2, 133, 'أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', '(হে ইহুদী জাতি,) তোমরা কি তখন সেখানে উপস্থিত ছিলে যখন ইয়াকুবের সামনে (তাঁর) মৃত্যু এসে হাযির হলো এবং সে যখন তাঁর ছেলেমেয়েদের বললো, আমার মৃত্যুর পর তোমরা কার এবাদাত করবে? তারা বললো, আমরা (অবশ্যই) তোমার মাবুদ– (তোমার পূর্বপুরুষ) ইবরাহীম, ইসমাঈল ও ইসহাকের মাবুদের এবাদাত করবো, (এ) মাবুদ হচ্ছেন একক, আমরা তো তাঁরই (সামনে) আত্মসমর্পণকারী।', 'Am kuntum shuhadaa ith hadara yaAAqooba almawtu ith qala libaneehi ma taAAbudoona min baAAdee qaloo naAAbudu ilahaka wailaha abaika ibraheema waismaAAeela waishaqa ilahan wahidan wanahnu lahu muslimoona', 1, NOW(), NOW()),
(2, 134, 'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ', 'এরা ছিলো এক (ধরনের) জাতি, যারা গত হয়ে গেছে, তারা যা করে গেছে তা তাদের নিজেদের জন্যে, (আবার) তোমরা যা করবে তা হবে তোমাদের নিজেদের জন্যে, তারা যা কিছু করছিলো সে ব্যাপারে তোমাদের (কিছুই) জিজ্ঞেস করা হবে না।', 'Tilka ommatun qad khalat laha ma kasabat walakum ma kasabtum wala tusaloona AAamma kano yaAAmaloona', 1, NOW(), NOW()),
(2, 135, 'وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', 'এরা বলে, তোমরা ইহুদী কিংবা খৃস্টান হয়ে যাও, তাহলে তোমরা সঠিক পথ পাবে; (হে নবী,) তুমি বলো, (আমাদের কাছে তো) বরং ইবরাহীমের একনিষ্ঠ মতাদর্শই রয়েছে; আর সে মোশরেকদের অন্তর্ভুক্ত ছিলো না।', 'Waqaloo koonoo hoodan aw nasara tahtadoo qul bal millata ibraheema haneefan wama kana mina almushrikeena', 1, NOW(), NOW()),
(2, 136, 'قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', 'তোমরা বলো, আমরা আল্লাহ্র ওপর ঈমান এনেছি এবং ঈমান এনেছি আল্লাহ তায়ালা আমাদের কাছে যা কিছু নাযিল করেছেন তার ওপর, (আমাদের আগে) ইবরাহীম, ইসমাঈল, ইসহাক, ইয়াকুব ও তাদের (পরবর্তী) সন্তানদের ওপর যা কিছু নাযিল করা হয়েছে তাও (আমরা মানি, তাছাড়া), মূসা, ঈসাসহ সব নবীকে তাদের রবের পক্ষ থেকে যা কিছু দেয়া হয়েছে তার ওপরও আমরা ঈমান এনেছি, আমরা এদের কারো মধ্যেই কোনো তারতম্য করি না, আমরা হচ্ছি আল্লাহরই অনুগত (বান্দা)।', 'Qooloo amanna biAllahi wama onzila ilayna wama onzila ila ibraheema waismaAAeela waishaqa wayaAAqooba waalasbati wama ootiya moosa waAAeesa wama ootiya alnnabiyyoona min rabbihim la nufarriqu bayna ahadin minhum wanahnu lahu muslimoona', 1, NOW(), NOW()),
(2, 137, 'فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'এরা যদি তোমাদের মতোই আল্লাহর ওপর ঈমান আনতো তাহলে তারা অবশ্যই সঠিক পথ পেতো, তারা যদি (সে পথ থেকে) ফিরে আসে তাহলে তারা অবশ্যই (উপদলীয়) অনৈক্যের মাঝে পড়ে যাবে, তাদের ব্যাপারে আল্লাহ তায়ালাই তোমার জন্যে যথেষ্ট (প্রমাণিত) হবেন, তিনিই শোনেন, তিনিই জানেন।', 'Fain amanoo bimithli ma amantum bihi faqadi ihtadaw wain tawallaw fainnama hum fee shiqaqin fasayakfeekahumu Allahu wahuwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(2, 138, 'صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ', 'আসল রং হচ্ছে আল্লাহ তায়ালার, এমন কে আছে যার রং আল্লাহ তায়ালার রঙের চেয়ে উৎকৃষ্ট হতে পারে? আমরা তো তাঁরই ইবাদাত করি।', 'Sibghata Allahi waman ahsanu mina Allahi sibghatan wanahnu lahu AAabidoona', 1, NOW(), NOW()),
(2, 139, 'قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ', '(হে নবী,) তুমি বলো, তোমরা কি স্বয়ং আল্লাহ তায়ালার ব্যাপারেই আমাদের সাথে বিতর্কে লিপ্ত হতে চাও? অথচ তিনি (যেমন) আমাদের রব, (তেমনি) তিনি তোমাদেরও রব, আমাদের কাজ আমাদের জন্যে, আর তোমাদের কাজ তোমাদের জন্যে, আমরা সবাই তাঁর (আনুগত্যের) ব্যাপারে নিষ্ঠাবান।', 'Qul atuhajjoonana fee Allahi wahuwa rabbuna warabbukum walana aAAmaluna walakum aAAmalukum wanahnu lahu mukhlisoona', 1, NOW(), NOW()),
(2, 140, 'أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'অথবা তোমরা কি একথা বলতে চাও যে, ইবরাহীম, ইসমাঈল, ইসহাক, ইয়াকুব ও তাদের বংশধররা সবাই ছিলো ইহুদী কিংবা খৃস্টান? (হে নবী,) তুমি বলে দাও, এ ব্যাপারে তোমরা বেশী জানো– না আল্লাহ তায়ালা বেশী জানেন? যদি কোনো ব্যক্তি তার কাছে মজুদ আল্লাহর কাছ থেকে (আগত) সাক্ষ্য প্রমাণ গোপন করে, তাহলে তার চেয়ে বড়ো যালিম আর কে হতে পারে? আল্লাহ তায়ালা (কিন্তু) তোমাদের কাজকর্মের ব্যাপারে মোটেই গাফেল নন।', 'Am taqooloona inna ibraheema waismaAAeela waishaqa wayaAAqooba waalasbata kanoo hoodan aw nasara qul aantum aAAlamu ami Allahu waman athlamu mimman katama shahadatan AAindahu mina Allahi wama Allahu bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(2, 141, 'تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ', 'এরা ছিলো এক (ধরনের) সম্প্রদায়, যারা গত হয়ে গেছে, তারা যা করে গেছে তা তাদের জন্যে, আর তোমাদের কর্মফল হবে তোমাদের জন্যে, তারা যা কিছু করছিলো সে ব্যাপারে তোমাদের কিছু জিজ্ঞেস করা হবে না।', 'Tilka ommatun qad khalat laha ma kasabat walakum ma kasabtum wala tusaloona AAamma kanoo yaAAmaloona', 1, NOW(), NOW()),
(2, 142, '۞سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', '(কেবলা বদলের পর) মানুষদের ভেতর থেকে কিছু মূর্খ লোক অচিরেই বলতে শুরু করবে (এ কি হলো এদের!) এতোদিন তারা তাদের যে কেবলার ওপর প্রতিষ্ঠিত ছিলো, (আজ হঠাৎ করে) কিসে তাদের সে দিক থেকে ফিরিয়ে দিলো? (হে নবী,) তুমি বলো, পূর্ব পশ্চিম (সবই) আল্লাহ তায়ালার জন্যে; তিনি যাকে ইচ্ছা তাকে সঠিক পথে পরিচালিত করেন।', 'Sayaqoolu alssufahao mina alnnasi ma wallahum AAan qiblatihimu allatee kanoo AAalayha qul lillahi almashriqu waalmaghribu yahdee man yashao ila siratin mustaqeemin', 1, NOW(), NOW()),
(2, 143, 'وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ', '(যেভাবে আমি তোমাকে হেদায়াত দিয়েছি) সেভাবেই আমি তোমাদের এক মধ্যপন্থী উম্মতে পরিণত করেছি, যেন তোমরা দুনিয়ার অন্যান্য মানুষদের ওপর (হেদায়াতের) সাক্ষী হয়ে থাকতে পারো এবং রসূলও তোমাদের ওপর সাক্ষী হয়ে থাকতে পারে । যে কেবলার ওপর তোমরা (এতোদিন) প্রতিষ্ঠিত ছিলে আমি তা এ উদ্দেশেই নির্ধারণ করেছিলাম, যাতে করে আমি এ কথাটা জেনে নিতে পারি, তোমাদের মধ্যে কে রসূলের অনুসরণ করে, আর কে তাঁর (অনুসরণ থেকে) ঘাড় ফিরিয়ে নেয়, তাদের ওপর এটা ছিলো কঠিন (পরীক্ষা), অবশ্য আল্লাহ তায়ালা যাদের হেদায়াত দান করেছেন তাদের কথা আলাদা; আল্লাহ তায়ালা এমন নন যে, তিনি তোমাদের ঈমান বিনষ্ট করবেন; অবশ্যই আল্লাহ তায়ালা মানুষদের সাথে বড়ো দয়ালু ও একান্ত মেহেরবান।', 'Wakathalika jaAAalnakum ommatan wasatan litakoonoo shuhadaa AAala alnnasi wayakoona alrrasoolu AAalaykum shaheedan wama jaAAalna alqiblata allatee kunta AAalayha illa linaAAlama man yattabiAAu alrrasoola mimman yanqalibu AAala AAaqibayhi wain kanat lakabeeratan illa AAala allatheena hada Allahu wama kana Allahu liyudeeAAa eemanakum inna Allaha bialnnasi laraoofun raheemun', 1, NOW(), NOW()),
(2, 144, 'قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ', '(কেবলা পরিবর্তনের জন্যে বারবার) আকাশের দিকে তোমার মুখ উঠানো আমি দেখতে পেয়েছি, অতপর আমি তোমাকে অবশ্যই এমন এক কেবলার দিকে ফিরিয়ে দিচ্ছি যেটাকে তুমি পছন্দ করো। (এখন থেকে) তুমি এই মর্যাদাসম্পন্ন মাসজিদের দিকে তোমার মুখ ফিরিয়ে (নামায আদায় করতে) থাকবে; তোমরা যেখানেই থাকো না কেন তোমাদের মুখমন্ডলগুলোকে সে দিকেই ফিরিয়ে দেবে; এসব লোক– যাদের আগেই কিতাব দেয়া হয়েছিলো, তারা ভালো করেই জানে; এ ব্যাপারটা তোমার মালিকের পক্ষ থেকে আসা সম্পূর্ণ একটি সত্য (ঘটনা, এ সত্ত্বেও) তারা (এর সাথে) যে আচরণ করে যাচ্ছে আল্লাহ তায়ালা তা থেকে মোটেই অনবহিত নন।', 'Qad nara taqalluba wajhika fee alssamai falanuwalliyannaka qiblatan tardaha fawalli wajhaka shatra almasjidi alharami wahaythu ma kuntum fawalloo wujoohakum shatrahu wainna allatheena ootoo alkitaba layaAAlamoona annahu alhaqqu min rabbihim wama Allahu bighafilin AAamma yaAAmaloona', 1, NOW(), NOW()),
(2, 145, 'وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ', 'ইতিপূর্বে যাদের কিতাব দেয়া হয়েছে তাদের সামনে যদি তুমি (দুনিয়ার) সব কয়টি প্রমাণও এনে হাযির করো, (তারপরও) এরা তোমার কেবলার অনুসরণ করবে না, আর (এর পর) তুমিও তাদের কেবলার অনুসরণকারী হতে পারো না, (তাছাড়া) এদের এক দলও তো আরেক দলের কেবলার অনুসরণ করে না; (আমার পক্ষ থেকে) এ জ্ঞান তোমাদের কাছে পৌঁছার পর তুমি যদি তাদের ইচ্ছা আকাঙ্ক্ষা অনুসরণ করো, তাহলে অবশ্যই তুমি যালিমদের দলে শামিল হয়ে যাবে।', 'Walain atayta allatheena ootoo alkitaba bikulli ayatin ma tabiAAoo qiblataka wama anta bitabiAAin qiblatahum wama baAAduhum bitabiAAin qiblata baAAdin walaini ittabaAAta ahwaahum min baAAdi ma jaaka mina alAAilmi innaka ithan lamina alththalimeena', 1, NOW(), NOW()),
(2, 146, 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ', 'যাদের আমি কিতাব দান করেছি এরা তাঁকে (ভালো করে) চেনে, যেমনি এরা চেনে আপন ছেলেদের; অবশ্যই এদের একদল লোক (সব সময়ই) জেনে বুঝে সত্য গোপন করার চেষ্টা করে।', 'Allatheena ataynahumu alkitaba yaAArifoonahu kama yaAArifoona abnaahum wainna fareeqan minhum layaktumoona alhaqqa wahum yaAAlamoona', 1, NOW(), NOW()),
(2, 147, 'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ', '(হে নবী, এ হচ্ছে) তোমার মালিকের পক্ষ থেকে (আগত একমাত্র) সত্য, অতপর কোনো অবস্থায়ই তুমি সন্দেহ পোষণকারীদের দলে শামিল হয়ো না।', 'Alhaqqu min rabbika fala takoonanna mina almumtareena', 1, NOW(), NOW()),
(2, 148, 'وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'প্রত্যেক (জাতির) জন্যেই (ইবাদাতের) একটা দিক (নির্দিষ্ট করা) থাকে, যে দিকে সে মুখ করে (দাঁড়ায়), তোমরা কল্যাণের কাজে একে অপরের সাথে প্রতিযোগিতা করো; তোমরা যেখানেই থাকো না কেন (কেয়ামতের দিন) আল্লাহ তায়ালা তোমাদের সবাইকে (একই স্থানে) এনে উপস্থিত করবেন; অবশ্যই আল্লাহ তায়ালা সবকিছুর ওপর ক্ষমতাবান।', 'Walikullin wijhatun huwa muwalleeha faistabiqoo alkhayrati ayna ma takoonoo yati bikumu Allahu jameeAAan inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 149, 'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'তুমি যে কোনো স্থান থেকেই বেরিয়ে আসো না কেন, (নামাযের জন্যে) মাসজিদে হারামের দিকে মুখ ফেরাও, কেননা এটাই হচ্ছে তোমার প্রভুর কাছ থেকে (কেবলা সংক্রান্ত) সঠিক (সিদ্ধান্ত); আর আল্লাহ তায়ালা তোমাদের কার্যাবলী সম্পর্কে মোটেই উদাসীন নন।', 'Wamin haythu kharajta fawalli wajhaka shatra almasjidi alharami wainnahu lalhaqqu min rabbika wama Allahu bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(2, 150, 'وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ', '(হে নবী,) যে দিক থেকেই তুমি বেরিয়ে আসবে, (নামাযের জন্যে সেখান থেকেই) মাসজিদে হারামের দিকে মুখ ফিরিয়ে (দাঁড়িয়ে) যেও; (এ সময়) তুমি যেখানেই থাকো না কেন সেদিকে মুখ ফিরিয়ে নেবে, তাহলে (প্রতিপক্ষের) লোকদের কাছে তোমাদের বিরুদ্ধে দাঁড় করানোর মতো কোনো যুক্তি অবশিষ্ট থাকবে না, তাদের মধ্য থেকে যারা বাড়াবাড়ি করে তাদের কথা আলাদা। তোমরা এদের ভয় করো না, ভয় করো আমাকে. যাতে করে আমি তোমাদের উপর আমার নেয়ামত পূর্ণ করে দিতে পারি, আশা করা যায় তোমরা সঠিক পথের সন্ধান পেয়ে যাবে,', 'Wamin haythu kharajta fawalli wajhaka shatra almasjidi alharami wahaythu ma kuntum fawalloo wujoohakum shatrahu lialla yakoona lilnnasi AAalaykum hujjatun illa allatheena thalamoo minhum fala takhshawhum waikhshawnee waliotimma niAAmatee AAalaykum walaAAallakum tahtadoona', 1, NOW(), NOW()),
(2, 151, 'كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ', '(সঠিক পথের সন্ধান দেয়ার জন্যে) আমি এভাবে তোমাদের কাছে তোমাদের মাঝ থেকেই একজনকে রসূল করে পাঠিয়েছি, যে ব্যক্তি (প্রথমত) তোমাদের কাছে 9 আমার আয়াতসমূহ তেলাওয়াত করবে, (দ্বিতীয়ত) সে তোমাদের (জীবন) পরিশুদ্ধ করে দেবে, (তৃতীয়ত) সে তোমাদের আমার কিতাব ও (তার অন্তর্নিহিত) জ্ঞান শিক্ষা দেবে, (এর সাথে) সে তোমাদের এমন বিষয়সমূহের জ্ঞানও শেখাবে, যা তোমরা কখনো জানতে না।', 'Kama arsalna feekum rasoolan minkum yatloo AAalaykum ayatina wayuzakkeekum wayuAAallimukumu alkitaba waalhikmata wayuAAallimukum ma lam takoonoo taAAlamoona', 1, NOW(), NOW()),
(2, 152, 'فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ', 'অতএব (এসব অনুগ্রহের জন্যে) তোমরা আমাকে স্মরণ করো, আমিও (পুরস্কার দিয়ে) তোমাদের স্মরণ করবো, তোমরা আমার কৃতজ্ঞতা আদায় করো এবং কখনো আমার অকৃতজ্ঞ হয়ো না।', 'Faothkuroonee athkurkum waoshkuroo lee wala takfurooni', 1, NOW(), NOW()),
(2, 153, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ', 'হে (মানুষ,) তোমরা যারা ঈমান এনেছো, ধৈর্য ও নামাযের মাধ্যমে তোমরা (আমার) সাহায্য প্রার্থনা করো; অবশ্যই আল্লাহ তায়ালা ধৈর্যশীল মানুষদের সাথে আছেন।', 'Ya ayyuha allatheena amanoo istaAAeenoo bialssabri waalssalati inna Allaha maAAa alssabireena', 1, NOW(), NOW()),
(2, 154, 'وَلَا تَقُولُواْ لِمَن يُقۡتَلُ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتُۢۚ بَلۡ أَحۡيَآءٞ وَلَٰكِن لَّا تَشۡعُرُونَ', 'যারা আল্লাহ তায়ালার পথে নিহত হয়েছে তাদের তোমরা মৃত বলো না; বরং তারাই হচ্ছে (আসল) জীবিত, কিন্তু (এ ব্যাপারে) তোমরা কোনো চৈতন্যই রাখো না।', 'Wala taqooloo liman yuqtalu fee sabeeli Allahi amwatun bal ahyaon walakin la tashAAuroona', 1, NOW(), NOW()),
(2, 155, 'وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ', 'আমি অবশ্যই তোমাদের পরীক্ষা করবো, (কখনো) ভয়-ভীতি, (কখনো) ক্ষুধা-অনাহার, (কখনো বা) জান মাল ও ফসলাদির ক্ষতি সাধন করে (তোমাদের পরীক্ষা করা হবে, যারা ধৈর্যের সাথে এর মোকাবেলা করে); তুমি (সে) ধৈর্যশীলদের (জান্নাতের) সুসংবাদ দান করো,', 'Walanabluwannakum bishayin mina alkhawfi waaljooAAi wanaqsin mina alamwali waalanfusi waalththamarati wabashshiri alssabireena', 1, NOW(), NOW()),
(2, 156, 'ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ', 'যখন তাদের ওপর (কোনো) বিপদ আপদ আসে তখন যারা বলে, নিসন্দেহে আমরা আল্লাহ তায়ালার জন্যে, অবশ্যই আমরা (একদিন) তাঁর কাছে ফিরে যাবো।', 'Allatheena itha asabathum museebatun qaloo inna lillahi wainna ilayhi rajiAAoona', 1, NOW(), NOW()),
(2, 157, 'أُوْلَـٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ', '(বস্তুত) এরা হচ্ছে সে সব ব্যক্তি, যাদের ওপর রয়েছে তাদের মালিকের পক্ষ থেকে (পাওয়া) অবারিত রহমত ও অপার করুণা; আর এরাই হচ্ছে সঠিক পথপ্রাপ্ত।', 'Olaika AAalayhim salawatun min rabbihim warahmatun waolaika humu almuhtadoona', 1, NOW(), NOW()),
(2, 158, '۞إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'অবশ্যই ‘সাফা’ এবং ‘মারওয়া’ (পাহাড় দুটো) আল্লাহ তায়ালার নিদর্শনসমূহের অন্যতম, অতএব যদি তোমাদের বে মধ্যে কেউ (আল্লাহর) ঘরের হজ্জ কিংবা ওমরা আদায় (করার এরাদা) করে, তার জন্যে এই উভয় (পাহাড়ের) মাঝে তাওয়াফ করাতে দোষের কিছু নেই; যদি কোনো ব্যক্তি নিষ্ঠার সাথে কোনো ভালো কাজ করে তাহলে (তারা যেন জেনে রাখে), নিসন্দেহে আল্লাহ তায়ালা কৃতজ্ঞতাপরায়ণ ও প্রভূত জ্ঞানের অধিকারী।', 'Inna alssafa waalmarwata min shaAAairi Allahi faman hajja albayta awi iAAtamara fala junaha AAalayhi an yattawwafa bihima waman tatawwaAAa khayran fainna Allaha shakirun AAaleemun', 1, NOW(), NOW()),
(2, 159, 'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلۡنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَيَّنَّـٰهُ لِلنَّاسِ فِي ٱلۡكِتَٰبِ أُوْلَـٰٓئِكَ يَلۡعَنُهُمُ ٱللَّهُ وَيَلۡعَنُهُمُ ٱللَّـٰعِنُونَ', 'মানুষের জন্যে যেসব (বিধান) আমি (আমার) কিতাবে বর্ণনা করে দিয়েছি, তারপর যারা আমার নাযিল করা সুস্পষ্ট নিদর্শনসমূহ ও পরিষ্কার পথনির্দেশ গোপন করে, (জেনে রেখো) এরাই হচ্ছে সেসব লোক যাদের ওপর আল্লাহ তায়ালা অভিসম্পাত করেন, অভিশাপ করে অন্যান্য অভিশাপকারীরাও,', 'Inna allatheena yaktumoona ma anzalna mina albayyinati waalhuda min baAAdi ma bayyannahu lilnnasi fee alkitabi olaika yalAAanuhumu Allahu wayalAAanuhumu allaAAinoona', 1, NOW(), NOW()),
(2, 160, 'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَـٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', 'তবে যারা (এ কাজ থেকে) তাওবা করবে এবং নিজে দের সংশোধন করে নেবে, যারা (সেসব সত্য) কথা প্রকাশ করবে (যা আহলে কিতাবরা গোপন করে আসছিলো) এদের ওপর আমি দয়াপরবশ হবো, আমি পরম ক্ষমাশীল, দয়ালু।', 'Illa allatheena taboo waaslahoo wabayyanoo faolaika atoobu AAalayhim waana alttawwabu alrraheemu', 1, NOW(), NOW()),
(2, 161, 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٌ أُوْلَـٰٓئِكَ عَلَيۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ', 'অবশ্যই যারা কুফরী করেছে এবং এই কাফের অবস্থায়ই মৃত্যু বরণ করেছে, তাদের ওপর আল্লাহর অভিশাপ রয়েছে, (অভিশাপ) ফেরেশতাদের, (সর্বোপরি অভিশাপ) সমগ্র মানবকুলের,', 'Inna allatheena kafaroo wamatoo wahum kuffarun olaika AAalayhim laAAnatu Allahi waalmalaikati waalnnasi ajmaAAeena', 1, NOW(), NOW()),
(2, 162, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ', '(অভিশপ্ত হয়েই) এরা সেখানে চিরদিন থাকবে, আযাব এদের ওপর থেকে (মোটেই) কম করা হবে না, তাদের কোনো রকম অবকাশও দেয়া হবে না।', 'Khalideena feeha la yukhaffafu AAanhumu alAAathabu wala hum yuntharoona', 1, NOW(), NOW()),
(2, 163, 'وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ', 'তোমাদের মাবুদ– একক মাবুদ, তিনি ছাড়া দ্বিতীয় কোনো মাবুদ নেই, তিনি দয়ালু, তিনি মেহেরবান।', 'Wailahukum ilahun wahidun la ilaha illa huwa alrrahmanu alrraheemu', 1, NOW(), NOW()),
(2, 164, 'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِي تَجۡرِي فِي ٱلۡبَحۡرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٖ وَتَصۡرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَيۡنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ', 'নিসন্দেহে আসমানসমূহ ও যমীনের সৃষ্টির মাঝে, রাত দিনের এই আবর্তনের মাঝে, সাগরে ভাসমান জাহাজ সমূহে— যা মানুষের জন্যে কল্যাণকর দ্রব্যসামগ্রী নিয়ে ঘুরে বেড়ায়– (এর সব কয়টিতেই আল্লাহ তায়ালার) নিদর্শন মজুদ রয়েছে, (আরো রয়েছে) আল্লাহ তায়ালা আকাশ থেকে (বৃষ্টি আকারে) যা কিছু নাযিল করেন (সেই বৃষ্টির) পানির মাঝে, ভূমির নির্জীব হওয়ার পর তিনিই পানি দ্বারা তাতে নতুন জীবন দান করেন, অতপর এখানে তিনি সব ধরনের প্রাণীর আবির্ভাব ঘটান, অবশ্যই বাতাসের প্রবাহ সৃষ্টি করার মাঝে এবং সেই মেঘমালা– যাকে আসমান যমীনের মাঝে বশীভূত করে রাখা হয়েছে— তাতে সুস্থ বিবেকবান সম্প্রদায়ের জন্যে নিদর্শন রয়েছে।', 'Inna fee khalqi alssamawati waalardi waikhtilafi allayli waalnnahari waalfulki allatee tajree fee albahri bima yanfaAAu alnnasa wama anzala Allahu mina alssamai min main faahya bihi alarda baAAda mawtiha wabaththa feeha min kulli dabbatin watasreefi alrriyahi waalssahabi almusakhkhari bayna alssamai waalardi laayatin liqawmin yaAAqiloona', 1, NOW(), NOW()),
(2, 165, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادٗا يُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِينَ ءَامَنُوٓاْ أَشَدُّ حُبّٗا لِّلَّهِۗ وَلَوۡ يَرَى ٱلَّذِينَ ظَلَمُوٓاْ إِذۡ يَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِيعٗا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلۡعَذَابِ', 'মানুষদের মাঝে কিছু এমনও রয়েছে, যে আল্লাহর বদলে অন্য কিছুকে তাঁর সমকক্ষ মনে করে, তারা তাদের তেমনি ভালোবাসে যেমনটি শুধু আল্লাহ তায়ালাকেই ভালোবাসা উচিত; আর যারা (আল্লাহ তায়ালার ওপর) ঈমান আনে, (তাদের) সর্বাধিক পরিমাণে ভালোবাসা থাকবে আল্লাহ তায়ালার জন্যে; অপরদিকে যারা যুলুম করেছে তারা যদি আযাব স্বচক্ষে দেখতে পেতো (তাহলে বুঝতে পারতো), আসমান যমীনের সমুদয় শক্তি একমাত্র আল্লাহর জন্যেই, অবশ্যই আল্লাহ তায়ালা শাস্তি দেয়ার ব্যাপারে অত্যন্ত কঠোর।', 'Wamina alnnasi man yattakhithu min dooni Allahi andadan yuhibboonahum kahubbi Allahi waallatheena amanoo ashaddu hubban lillahi walaw yara allatheena thalamoo ith yarawna alAAathaba anna alquwwata lillahi jameeAAan waanna Allaha shadeedu alAAathabi', 1, NOW(), NOW()),
(2, 166, 'إِذۡ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُواْ مِنَ ٱلَّذِينَ ٱتَّبَعُواْ وَرَأَوُاْ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ', '(সেদিনের) ভয়াবহ শাস্তি দেখে (হতভাগ্য) লোকেরা— (দুনিয়ায়) যাদের তারা মেনে চলতো, তাদের অনুসারীদের সাথে সম্পর্কচ্ছেদের কথা বলবে, এদের সাথে তাদের সব সম্পর্ক (সেদিন) ছিন্ন বিচ্ছিন্ন হয়ে যাবে।', 'Ith tabarraa allatheena ittubiAAoo mina allatheena ittabaAAoo waraawoo alAAathaba wataqattaAAat bihimu alasbabu', 1, NOW(), NOW()),
(2, 167, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُواْ لَوۡ أَنَّ لَنَا كَرَّةٗ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُواْ مِنَّاۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعۡمَٰلَهُمۡ حَسَرَٰتٍ عَلَيۡهِمۡۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', 'যারা (তাদের) অনুসরণ করেছে তারা (সেদিন) বলবে, আবার যদি একবার আমাদের জন্যে (পৃথিবীতে) ফিরে যাবার (সুযোগ) থাকতো, তাহলে আজ যেমনি করে (তারা) আমাদের সাথে সম্পর্কচ্ছেদ করেছে, আমরা (সেখানে গিয়ে) তাদের সাথেও সম্পর্কচ্ছেদ করে আসতাম, এভাবেই আল্লাহ তায়ালা তাদের কর্মকান্ডগুলো তাদের ওপর একরাশ (লজ্জা ও) আক্ষেপ হিসেবে দেখাবেন; এরা (কখনো) জাহান্নাম থেকে বেরিয়ে আসতে পারবে না।', 'Waqala allatheena ittabaAAoo law anna lana karratan fanatabarraa minhum kama tabarraoo minna kathalika yureehimu Allahu aAAmalahum hasaratin AAalayhim wama hum bikharijeena mina alnnari', 1, NOW(), NOW()),
(2, 168, 'يَـٰٓأَيُّهَا ٱلنَّاسُ كُلُواْ مِمَّا فِي ٱلۡأَرۡضِ حَلَٰلٗا طَيِّبٗا وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٌ', 'হে মানুষ, তোমরা (আল্লাহর) যমীনে যা কিছু হালাল ও পবিত্র জিনিস আছে তা খাও এবং (কোনো অবস্থায়ই হালাল হারামের ব্যাপারে) শয়তানের পদাংক অনুসরণ করো না; অবশ্যই সে তোমাদের প্রকাশ্য দুশমন।', 'Ya ayyuha alnnasu kuloo mimma fee alardi halalan tayyiban wala tattabiAAoo khutuwati alshshaytani innahu lakum AAaduwwun mubeenun', 1, NOW(), NOW()),
(2, 169, 'إِنَّمَا يَأۡمُرُكُم بِٱلسُّوٓءِ وَٱلۡفَحۡشَآءِ وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', '(শয়তানের কাজ হচ্ছে,) সে তোমাদের (সব সময়) পাপ ও অশ্লীল কাজের আদেশ দেবে এবং (সে চাইবে) যেন আল্লাহ তায়ালার নামে তোমরা এমন সব কথা বলতে শুরু করো যে সম্পর্কে তোমরা কিছুই জানো না।', 'Innama yamurukum bialssooi waalfahshai waan taqooloo AAala Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(2, 170, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ', 'তাদের যখন বলা হয়, আল্লাহ তায়ালা যা কিছু নাযিল করেছেন তোমরা তা মেনে চলো, তারা বলে, আমরা তো শুধু সে পথেরই অনুসরণ করবো যার ওপর আমরা আমাদের বাপ দাদাদের পেয়েছি; তাদের বাপ-দাদারা যদি (এ ব্যাপারে) কোনো জ্ঞান বুদ্ধির পরিচয় নাও দিয়ে থাকে, এবং তারা যদি হেদায়াত নাও পেয়ে থাকে (তবুও কি তারা তাদের অনুসরণ করবে)?', 'Waitha qeela lahumu ittabiAAoo ma anzala Allahu qaloo bal nattabiAAu ma alfayna AAalayhi abaana awalaw kana abaohum la yaAAqiloona shayan wala yahtadoona', 1, NOW(), NOW()),
(2, 171, 'وَمَثَلُ ٱلَّذِينَ كَفَرُواْ كَمَثَلِ ٱلَّذِي يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُعَآءٗ وَنِدَآءٗۚ صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَعۡقِلُونَ', 'যারা (হেদায়াত) অস্বীকার করে, তাদের উদাহরণ হচ্ছে এমন (জন্তুর মতো), যে (তার পালের আরেকটি জন্তুকে) যখন ডাক দেয়, তখন (পেছনের সেই জন্তুটি তার) চীৎকার ও কান্নার আওয়ায ছাড়া আর কিছুই শুনতে পায় না; (মূলত) এরা (কানেও) শোনে না, (মুখেও কিছু) বলতে পারে না, (চোখেও দেখে না, (হেদায়াতের কথাও) এরা বুঝে না।', 'Wamathalu allatheena kafaroo kamathali allathee yanAAiqu bima la yasmaAAu illa duAAaan wanidaan summun bukmun AAumyun fahum la yaAAqiloona', 1, NOW(), NOW()),
(2, 172, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَٱشۡكُرُواْ لِلَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, তোমরা যদি একান্তভাবে আল্লাহ তায়ালারই দাসত্ব করো তাহলে আমি যেসব পাক পবিত্র জিনিস তোমাদের দান করেছি, (নিসংকোচে) তা তোমরা খাও এবং (এ নেয়ামতের জন্যে) তোমরা আল্লাহ তায়ালার শোকর আদায় করো।', 'Ya ayyuha allatheena amanoo kuloo min tayyibati ma razaqnakum waoshkuroo lillahi in kuntum iyyahu taAAbudoona', 1, NOW(), NOW()),
(2, 173, 'إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', 'অবশ্যই তিনি তোমাদের ওপর মৃত (জন্তুর গোশত), সব ধরনের রক্ত ও শূকরের গোশত হারাম করেছেন এবং (এমন সব জন্তুও হারাম করছেন) যা আল্লাহ তায়ালা ছাড়া অন্য কারো ওপর (যবাই কিংবা উৎসর্গ করে) ডাকা হয়েছে, তবে (সে ব্যক্তির কথা আলাদা) যে (ক্ষুধার) কণ্ঠে অতিষ্ট, সে (আল্লাহর আইনের) সীমালংঘনকারী নয়, অথবা (যেটুকু হলে জীবনটা বাঁচে তার চাইতে বেশী) বাড়াবাড়িও না করে, তাহলে (এই অপারগতার সময়ে হারাম খেলে) তার ওপর কোনো গুনাহ নেই; অবশ্যই আল্লাহ তায়ালা ক্ষমাশীল, অনেক মেহেরবান।', 'Innama harrama AAalaykumu almaytata waalddama walahma alkhinzeeri wama ohilla bihi lighayri Allahi famani idturra ghayra baghin wala AAadin fala ithma AAalayhi inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(2, 174, 'إِنَّ ٱلَّذِينَ يَكۡتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَٰبِ وَيَشۡتَرُونَ بِهِۦ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ مَا يَأۡكُلُونَ فِي بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ', 'নিসন্দেহে যারা আল্লাহর নাযিল করা কিতাবের অংশবিশেষ গোপন করে রাখে এবং সামান্য (বৈষয়িক) মূল্যে তা বিক্রি করে দেয়, তারাই হচ্ছে সেসব লোক যারা আগুন দিয়ে নিজেদের পেট ভর্তি করে, কেয়ামতের দিন আল্লাহ তায়ালা তাদের সাথে কথা বলবেন না, তিনি তাদের পবিত্রও করবেন না, এদের জন্যেই রয়েছে ভয়াবহ আযাব।', 'Inna allatheena yaktumoona ma anzala Allahu mina alkitabi wayashtaroona bihi thamanan qaleelan olaika ma yakuloona fee butoonihim illa alnnara wala yukallimuhumu Allahu yawma alqiyamati wala yuzakkeehim walahum AAathabun aleemun', 1, NOW(), NOW()),
(2, 175, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ', 'এরাই হচ্ছে সেসব লোক যারা হেদায়াতের বদলে গোমরাহীর পথ কিনে নিয়েছে, ক্ষমার বদলে তারা আযাব (বেছে) নিয়েছে, (মনে হচ্ছে) জাহান্নামের আগুনের ওপর এতো ধৈর্যধারণকারী এরা!', 'Olaika allatheena ishtarawoo alddalalata bialhuda waalAAathaba bialmaghfirati fama asbarahum AAala alnnari', 1, NOW(), NOW()),
(2, 176, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِي ٱلۡكِتَٰبِ لَفِي شِقَاقِۭ بَعِيدٖ', 'এটা এই জন্যে যে, আল্লাহ তায়ালা সত্য (দ্বীন) সহকারে কিতাব নাযিল করেছেন; অবশ্যই যারা এই কিতাবে মতবিরোধ করেছে, তারা সত্য ও ন্যায়ের পথ থেকে অনেক দূরে নিক্ষিপ্ত হয়ে গেছে।', 'Thalika bianna Allaha nazzala alkitaba bialhaqqi wainna allatheena ikhtalafoo fee alkitabi lafee shiqaqin baAAeedin', 1, NOW(), NOW()),
(2, 177, '۞لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّـٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ', 'তোমরা তোমাদের মুখমন্ডলসমূহকে পূর্ব দিকে ফেরাও বা পশ্চিম দিকে ফেরাও, এতেই কিন্তু সব নেকী নিহিত নেই, তবে আসল নেকী হচ্ছে এই যে, একজন মানুষ ঈমান আনবে আল্লাহর ওপর, পরকালের ওপর, ফেরেশতাদের ওপর, (আল্লাহর) কিতাবের ওপর, (কিতাবের বাহক) নবী রসূলদের ওপর এবং মাল সম্পদের ওপর তার নিজের ভালোবাসা থাকা সত্ত্বেও সে তা (তার) আত্মীয় স্বজন, এতীম মেসকীন ও পথিক মোসাফেরের জন্যে ব্যয় করবে, সাহায্যপ্রার্থী (দুস্থ মানুষ, সর্বোপরি) মানুষদের (দাসত্বের) বন্দিদশা থেকে মুক্ত করার কাজে ব্যয় করবে এবং নামায প্রতিষ্ঠা করবে, (দারিদ্র বিমোচনের জন্যে) যাকাত আদায় করবে– (তাছাড়াও রয়েছে সেসব পুণ্যবান মানুষ); যারা প্রতিশ্রুতি দিলে তা পালন করে, ক্ষুধা দারিদ্রের সময় ও (হক বাতিলের) যুদ্ধের সময় এরা ধৈর্য ধারণ করে, (মূলত) এরাই হচ্ছে সত্যবাদী এবং এরাই হচ্ছে প্রকৃত তাকওয়া অবলম্বনকারী মানুষ।', 'Laysa albirra an tuwalloo wujoohakum qibala almashriqi waalmaghribi walakinna albirra man amana biAllahi waalyawmi alakhiri waalmalaikati waalkitabi waalnnabiyyeena waata almala AAala hubbihi thawee alqurba waalyatama waalmasakeena waibna alssabeeli waalssaileena wafee alrriqabi waaqama alssalata waata alzzakata waalmoofoona biAAahdihim itha AAahadoo waalssabireena fee albasai waalddarrai waheena albasi olaika allatheena sadaqoo waolaika humu almuttaqoona', 1, NOW(), NOW()),
(2, 178, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءٞ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنٖۗ ذَٰلِكَ تَخۡفِيفٞ مِّن رَّبِّكُمۡ وَرَحۡمَةٞۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, তোমাদের জন্যে নরহত্যার (ন্যায় বিচার নিশ্চিত করার লক্ষ্যে ‘কেসাস’ (প্রয়োগকে) ফরয করে দেয়া হয়েছে (এবং তা হচ্ছে) স্বাধীন ব্যক্তির বদলে স্বাধীন ব্যক্তি (দন্ডাজ্ঞা পাবে), দাসের বদলে (পাবে) দাস, নারীর বদলে নারীর ওপর (দন্ড প্রযোজ্য হবে), অবশ্য যে হত্যাকারীকে (−যাকে হত্যা করা হয়েছে তার পরিবারের লোকেরা কিংবা) তার ভাইর পক্ষ থেকে ক্ষমা করে দেয়া হয় তার ক্ষেত্রে কোনো ন্যায়ানুগ পন্থা অনুসরণ (করে তা নিস্পত্তি) করতে হবে, এটা তোমাদের মালিকের পক্ষ থেকে দন্ড হ্রাস (করার একটা উপায়) ও তাঁর একটি অনুগ্রহ মাত্র; এরপর যদি কেউ বাড়াবাড়ি করে, তাহলে তার জন্যে কঠোর শাস্তি রয়েছে।', 'Ya ayyuha allatheena amanoo kutiba AAalaykumu alqisasu fee alqatla alhurru bialhurri waalAAabdu bialAAabdi waalontha bialontha faman AAufiya lahu min akheehi shayon faittibaAAun bialmaAAroofi waadaon ilayhi biihsanin thalika takhfeefun min rabbikum warahmatun famani iAAtada baAAda thalika falahu AAathabun aleemun', 1, NOW(), NOW()),
(2, 179, 'وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ', 'হে বিবেকবান লোকেরা, (আল্লাহ নির্ধারিত এ) কেসাস’-এর (বিধান প্রতিষ্ঠার) মাঝেই তোমাদের (সত্যিকারের) ‘জীবন‘ (নিহিত) রয়েছে, আশা করা যায় (এর ফলে) তোমরা (নর হত্যার অপরাধ থেকে) বেঁচে থাকবে।', 'Walakum fee alqisasi hayatun ya olee alalbabi laAAallakum tattaqoona', 1, NOW(), NOW()),
(2, 180, 'كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَيۡرًا ٱلۡوَصِيَّةُ لِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ', '(হে ঈমানদার লোকেরা,) তোমাদের জন্যে এটাও ফরয করা হয়েছে যে, যদি তোমাদের কোনো লোকের মৃত্যু এসে হাযির হয় এবং সে যদি কিছু সম্পদ রেখে যায়, (তাহলে) ন্যায়ানুগ পন্থায় (তা বন্টনের কাজে) তার পিতামাতা ও আত্মীয় স্বজনের জন্যে ওসিয়তের ব্যবস্থা থাকবে, এটা তাকওয়া অবলম্বনকারীদের ওপর (একান্ত) করণীয়।', 'Kutiba AAalaykum itha hadara ahadakumu almawtu in taraka khayran alwasiyyatu lilwalidayni waalaqrabeena bialmaAAroofi haqqan AAala almuttaqeena', 1, NOW(), NOW()),
(2, 181, 'فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثۡمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', 'যারা এটা শুনে নেয়ার পর (নিজেদের স্বার্থে) তা পাল্টে নিলো (তাদের জানা উচিত); এটা বদলানোর অপরাধের দায়িত্ব তাদের ওপরই বর্তাবে, যারা একে বদলে দিয়েছে, অবশ্যই আল্লাহ তায়ালা সব কিছু শোনেন এবং সব কিছুই তাঁর জানা।', 'Faman baddalahu baAAdama samiAAahu fainnama ithmuhu AAala allatheena yubaddiloonahu inna Allaha sameeAAun AAaleemun', 1, NOW(), NOW()),
(2, 182, 'فَمَنۡ خَافَ مِن مُّوصٖ جَنَفًا أَوۡ إِثۡمٗا فَأَصۡلَحَ بَيۡنَهُمۡ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', '(অবশ্য) কারো যদি ওসিয়তকারীর কাছ থেকে কোনো পক্ষপাতিত্ত্ব কিংবা (অবিচার জনিত) অন্যায়ের আশংকা থাকে, তাহলে (যদি সদিচ্ছা নিয়ে) সে মূল বিষয়টির সংশোধন করে দেয়, এতে তার কোনো দোষ হবে না; অবশ্যই আল্লাহ তায়ালা ক্ষমাশীল, মেহেরবান।', 'Faman khafa min moosin janafan aw ithman faaslaha baynahum fala ithma AAalayhi inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(2, 183, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, তোমাদের ওপর রোযা ফরয করে দেয়া হয়েছে, যেমনি করে ফরয করা হয়েছিলো তোমাদের পূর্ববর্তী লোকদের ওপর, আশা করা যায় তোমরা (এর মাধ্যমে) তাকওয়া অর্জন করতে পারবে;', 'Ya ayyuha allatheena amanoo kutiba AAalaykumu alssiyamu kama kutiba AAala allatheena min qablikum laAAallakum tattaqoona', 1, NOW(), NOW()),
(2, 184, 'أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', '(রোযা ফরয করা হয়েছে) নির্দিষ্ট কয়েকটি দিনের জন্যে; (তারপরও) কেউ যদি সে (দিনগুলোতে) অসুস্থ হয়ে যায় কিংবা কেউ যদি (তখন) সফরে থাকে, তাহলে সে ব্যক্তি সমপরিমাণ দিনের রোযা (সুস্থ হয়ে অথবা সফর থেকে ফিরে এসে) আদায় করে নেবে; যারা রোযা রাখার শক্তি রাখে (কিন্তু রোযা রাখে না), তাদের জন্যে এর বিনিময়ে ফেদিয়া থাকবে (এবং তা) হচ্ছে গরীব ব্যক্তির (তৃপ্তিভরে) খাবার দেয়া; অবশ্য যদি কোনো ব্যক্তি (এর চাইতে বেশী দিয়ে) ভালো কাজ করতে চায়, তাহলে এ (অতিরিক্ত) কাজ তার জন্যে হবে একান্ত কল্যাণকর; (অবশ্য) তোমরা যদি রোযা রাখতে পারো (তাহলে) সেটা তোমাদের জন্যে ভালো; যদি তোমরা (রোযার উপকারিতা) সম্পর্কে জানতে!', 'Ayyaman maAAdoodatin faman kana minkum mareedan aw AAala safarin faAAiddatun min ayyamin okhara waAAala allatheena yuteeqoonahu fidyatun taAAamu miskeenin faman tatawwaAAa khayran fahuwa khayrun lahu waan tasoomoo khayrun lakum in kuntum taAAlamoona', 1, NOW(), NOW()),
(2, 185, 'شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ', 'রোযার মাস (এমন একটি মাস)- যাতে কোরআন নাযিল করা হয়েছে, আর এ (কোরআন হচ্ছে) মানব জাতির জন্যে পথের দিশা, সৎপথের সুস্পষ্ট নিদর্শন ও (হক বাতিলের) পার্থক্যকারী, অতএব তোমাদের মধ্যে যে ব্যক্তি (এ) মাসটি পাবে, সে এতে রোযা রাখবে; (তবে) যদি সে অসুস্থ হয়ে পড়ে কিংবা সফরে থাকে, সে পরবর্তী (কোনো সময়ে) গুনে গুনে সেই পরিমাণ দিন পূরণ করে নেবে; (এ সুযোগ দিয়ে) আল্লাহ তায়ালা তোমাদের (কাজকর্মকে) আসান করে দিতে চান, আল্লাহ তায়ালা কখনোই তোমাদের (জীবনকে) কঠোর করে দিতে চান না। (আল্লাহর উদ্দেশ্য হচ্ছে,) তোমরা যেন গুনে গুনে (রোযার) সংখ্যাগুলো পূরণ করো, আল্লাহ তায়ালা তোমাদের (কোরআনের মাধ্যমে) যে পথ দেখিয়েছেন তার জন্যে তোমরা তাঁর মাহাত্ম্য বর্ণনা করো এবং তাঁর কৃতজ্ঞতা আদায় করো।', 'Shahru ramadana allathee onzila feehi alquranu hudan lilnnasi wabayyinatin mina alhuda waalfurqani faman shahida minkumu alshshahra falyasumhu waman kana mareedan aw AAala safarin faAAiddatun min ayyamin okhara yureedu Allahu bikumu alyusra wala yureedu bikumu alAAusra walitukmiloo alAAiddata walitukabbiroo Allaha AAala ma hadakum walaAAallakum tashkuroona', 1, NOW(), NOW()),
(2, 186, 'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ', '(হে নবী,) আমার কোনো বান্দা যখন তোমাকে আমার ব্যাপারে জিজ্ঞেস করে (তুমি তাকে বলে দিয়ো), আমি (তার একান্ত) কাছেই আছি; আমি আহ্বানকারীর ডাকে সাড়া দেই যখন সে আমাকে ডাকে, তাই তাদেরও উচিত আমার আহ্বানে সাড়া দেয়া এবং (সম্পূর্ণভাবে) আমার ওপরই ঈমান আনা, আশা করা যায় তারা সঠিক পথের সন্ধান পাবে।', 'Waitha saalaka AAibadee AAannee fainnee qareebun ojeebu daAAwata alddaAAi itha daAAani falyastajeeboo lee walyuminoo bee laAAallahum yarshudoona', 1, NOW(), NOW()),
(2, 187, 'أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ', 'রোযার (মাসের) রাতের বেলায় তোমাদের স্ত্রীদের কাছে যৌন মিলনের জন্যে যাওয়া তোমাদের জন্য হালাল করে দেয়া হয়েছে; (আসলে তোমাদের) নারীরা (যেমনি) তোমাদের জন্যে পোশাক (স্বরূপ, ঠিক) তোমরাও তাদের জন্যে পোশাক (স্বরূপ); আল্লাহ তায়ালা এটা জেনেছেন যে, (রোযার মাসে রাতের বেলায় স্ত্রী সহবাসের ব্যাপারে) তোমরা নিজেদের সাথে খেয়ানত করছিলে, অতপর তিনি (কড়াকড়ি শিথিল করে) তোমাদের ওপর দয়াপরবশ হলেন এবং তোমাদের মাফ করে দিলেন, এখন (তোমরা চাইলে) তাদের সাথে সহবাস করতে পারো এবং (এ ব্যাপারে) আল্লাহ তায়ালা তোমাদের জন্যে যা লিখে রেখেছেন তা তাদের সাথে সহবাস করতে পারো এবং (এ ব্যাপারে) আল্লাহ তায়ালা তোমাদের জন্যে যা লিখে রেখেছেন তা সন্ধান করো । (রোযায়), তোমরা পানাহার অব্যাহত রাখতে পারো যতোক্ষণ পর্যন্ত রাতের অন্ধকার রেখার ভেতর থেকে ভোরের শুভ্র আলোক রেখা তোমাদের জন্যে পরিষ্কার প্রতিভাত না হয়, অতপর তোমরা রাতের আগমন পর্যন্ত রোযা পূর্ণ করে নাও, মাসজিদে যখন তোমরা এতেকাফ অবস্থায় থাকবে তখন নারী সম্ভোগ থেকে বিরত থেকো; (রোযার ব্যাপারে) এগুলোই হচ্ছে আল্লাহ তায়ালার নির্ধারিত সীমারেখা, অতপর তোমরা এ (সীমা রেখা)-র কাছেও যেয়ো না; এভাবেই আল্লাহ তায়ালা তাঁর আয়াতসমূহ মানুষদের জন্যে বর্ণনা করেন, আশা করা যায় তারা তাকওয়া অর্জন করতে পারবে।', 'Ohilla lakum laylata alssiyami alrrafathu ila nisaikum hunna libasun lakum waantum libasun lahunna AAalima Allahu annakum kuntum takhtanoona anfusakum fataba AAalaykum waAAafa AAankum faalana bashiroohunna waibtaghoo ma kataba Allahu lakum wakuloo waishraboo hatta yatabayyana lakumu alkhaytu alabyadu mina alkhayti alaswadi mina alfajri thumma atimmoo alssiyama ila allayli wala tubashiroohunna waantum AAakifoona fee almasajidi tilka hudoodu Allahi fala taqrabooha kathalika yubayyinu Allahu ayatihi lilnnasi laAAallahum yattaqoona', 1, NOW(), NOW()),
(2, 188, 'وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ وَتُدۡلُواْ بِهَآ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُواْ فَرِيقٗا مِّنۡ أَمۡوَٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ', 'তোমরা একে অন্যের অর্থ সম্পদ অবৈধভাবে আত্মসাত করো না, (আবার) জেনে বুঝে অন্যায়ভাবে অন্য (মানুষ)-দের সম্পদের কোনো অংশ ভোগ করার জন্যে (তাকে) বিচারকদের সামনে ঘুষ (কিংবা উপঢৌকন) হিসেবেও পেশ করো না।', 'Wala takuloo amwalakum baynakum bialbatili watudloo biha ila alhukkami litakuloo fareeqan min amwali alnnasi bialithmi waantum taAAlamoona', 1, NOW(), NOW()),
(2, 189, '۞يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', '(হে নবী,) তারা তোমাকে নতুন চাঁদগুলো (ও তাদের বাড়া কমা) সম্পর্কে জিজ্ঞেস করবে, তুমি তাদের বলে দাও, (মূলত) এগুলো হচ্ছে মানব জাতির জন্যে (একটি স্থায়ী) সময় নির্ঘন্ট (-যার মাধ্যমে মানুষরা দিন তারিখ জানতে পারে) এবং (জেনে নিতে পারে) হজ্জের সময়সূচীও। (এহরাম বাঁধার পর) পেছন দরজা দিয়ে (ঘরে) প্রবেশ করার মাঝে কোনো সওয়াব নেই,আসল সওয়াব হচ্ছে– কে আল্লাহ তায়ালাকে ভয় করলো (সেটা দেখা, এখন থেকে) ঘরে ঢোকার সময় (সামনের) দুয়ার দিয়েই তোমরা এসো, তোমরা একমাত্র আল্লাহ তায়ালাকে ভয় করবে, আশা করা যায় তোমরা সফল হতে পারবে।', 'Yasaloonaka AAani alahillati qul hiya mawaqeetu lilnnasi waalhajji walaysa albirru bian tatoo albuyoota min thuhooriha walakinna albirra mani ittaqa watoo albuyoota min abwabiha waittaqoo Allaha laAAallakum tuflihoona', 1, NOW(), NOW()),
(2, 190, 'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ', 'তোমরা আল্লাহ তায়ালার পথে সেসব লোকের সাথে লড়াই করো যারা তোমাদের সাথে লড়াই করে, তোমরা (কোনো অবস্থায়ই) সীমালংঘন করো না; নিসন্দেহে আল্লাহ তায়ালা সীমালংঘনকারীদের পছন্দ করেন না।', 'Waqatiloo fee sabeeli Allahi allatheena yuqatiloonakum wala taAAtadoo inna Allaha la yuhibbu almuAAtadeena', 1, NOW(), NOW()),
(2, 191, 'وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ', '(যুদ্ধের ময়দানে) যেখানেই তোমরা তাদের পাও সেখানেই তোমরা তাদের হত্যা করো, যে সব স্থান থেকে তারা তোমাদের বের করে দিয়েছে তোমরাও তাদের সেসব স্থান থেকে বের করে দাও (জেনে রেখো), ফেতনা ফাসাদ নরহত্যার চাইতেও বড়ো অপরাধ, তোমরা কাবা ঘরের পাশে কখনো তাদের সাথে যুদ্ধে লিপ্ত হয়ো না– যতোক্ষণ পর্যন্ত তারা সেখানে তোমাদের সাথে যুদ্ধ না করে, তারা যদি তোমাদের সাথে যুদ্ধ করে তাহলে তোমরাও তাদের সাথে যুদ্ধ করো; (মূলত) এভাবেই কাফেরদের শাস্তি (নির্ধারণ করা হয়েছে)।', 'Waoqtuloohum haythu thaqiftumoohum waakhrijoohum min haythu akhrajookum waalfitnatu ashaddu mina alqatli wala tuqatiloohum AAinda almasjidi alharami hatta yuqatilookum feehi fain qatalookum faoqtuloohum kathalika jazao alkafireena', 1, NOW(), NOW()),
(2, 192, 'فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'অতপর তারা যদি (যুদ্ধ থেকে) ফিরে আসে তাহলে (মনে রেখো), আল্লাহ তায়ালা বড়োই ক্ষমাশীল ও দয়ার আধার।', 'Faini intahaw fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(2, 193, 'وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِينَ', 'তোমরা তাদের সাথে লড়াই করতে থাকো, যতোক্ষণ না (যমীনে শেরেকের) ফেতনা অবশিষ্ট থাকে এবং (আল্লাহর যমীনে আল্লাহর দেয়া) জীবন বিধান (পুরোপুরি) আল্লাহর জন্যে নির্দিষ্ট হয়ে যায়; যদি তারা (যুদ্ধ থেকে) ফিরে আসে তবে তাদের সাথে আর কোনো বাড়াবাড়ি নয়, (অবশ্য) যারা যালেম তাদের কথা আলাদা।', 'Waqatiloohum hatta la takoona fitnatun wayakoona alddeenu lillahi faini intahaw fala AAudwana illa AAala alththalimeena', 1, NOW(), NOW()),
(2, 194, 'ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ', 'একটি সম্মানিত মাসের বদলেই একটি সম্মানিত মাস (আশা করা যায়, কিন্তু) এ সম্মানিত মাসসমূহেও প্রতিশোধ (বৈধ) হবে; (এ সময়) যদি কেউ তোমাদের ওপর বাড়াবাড়ি করে তাহলে তোমরাও তার ওপর তেমনি হস্ত প্রসারিত করো, যেমনি করে তারা তোমাদের ওপর বাড়াবাড়ি করেছে, তবে (সর্বদাই) তাকওয়া অবলম্বন করতে থাকো, জেনে রেখো, যারা (সীমালংঘন থেকে) বেঁচে থাকে আল্লাহ তায়ালা তাদের সাথেই রয়েছেন।', 'Alshshahru alharamu bialshshahri alharami waalhurumatu qisasun famani iAAtada AAalaykum faiAAtadoo AAalayhi bimithli ma iAAtada AAalaykum waittaqoo Allaha waiAAlamoo anna Allaha maAAa almuttaqeena', 1, NOW(), NOW()),
(2, 195, 'وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ', 'তোমরা আল্লাহর পথে অর্থ (সম্পদ) ব্যয় করো, (সম্পদ আঁকড়ে ধরে) নিজেদের হাতেই নিজেদের ধ্বংসের (অতলে) নিক্ষেপ করো না এবং তোমরা (মানুষদের সাথে) অনুগ্রহ করো, অবশ্যই আল্লাহ তায়ালা অনুগ্রহকারী ব্যক্তিদের ভালোবাসেন।', 'Waanfiqoo fee sabeeli Allahi wala tulqoo biaydeekum ila alttahlukati waahsinoo inna Allaha yuhibbu almuhsineena', 1, NOW(), NOW()),
(2, 196, 'وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'তোমরা আল্লাহ তায়ালার (সন্তুষ্টির) জন্যে হজ্জ ও ওমরা পালন করো; (পথে) যদি তোমাদের কোথাও আটকে দেয়া হয় তাহলে সে স্থানে কোরবানীর জন্যে যা কিছু সহজভাবে (হাতের কাছে) পাওয়া যায় তা দিয়েই কোরবানী আদায় করে নাও, (তবে) কোরবানীর পশু তার নির্দিষ্ট গন্তব্যস্থলে পৌঁছার আগ পর্যন্ত তোমরা তোমাদের মাথা মুন্ডন করো না; যদি তোমাদের মধ্যে কোনো ব্যক্তি অসুস্থ হয়ে পড়ে, অথবা যদি তার মাথায় কোনো রোগ থাকে (যে কারণে আগেই তার মাথা মুন্ডন করা প্রয়োজন হয়), তাহলে সে যেন এর বিনিময় (ফিদিয়া আদায় করে এবং তা) হচ্ছে কিছু রোযা (রাখা) অথবা অর্থ দান করা, কিংবা কোরবানী আদায় করা, অতপর তোমরা যখন নিরাপদ হয়ে যাবে কিছু রোযা (রাখা) অথবা অর্থ দান করা, কিংবা কোরবানী আদায় করা, অতপর তোমরা যখন নিরাপদ হয়ে যাবে তখন তোমাদের কেউ যদি এক সাথে হজ্জ ও ওমরা আদায় করতে চায়, তার উচিত (তার জন্যে) যা সহজলভ্য তা দিয়ে কোরবানী আদায় করা, যদি কোরবানী করার মতো কোনো পশু সে না পায় (তাহলে) সে যেন হজ্জের সময়কালে তিনটি এবং তোমরা যখন বাড়ি ফিরে আসবে তখন সাতটি– (সর্বমোট) পূর্ণ দশটি রোযা রাখে, এই (সুবিধা)-টুকু শুধু তার জন্যে, যার পরিবার পরিজন আল্লাহর ঘরের আশেপাশে বর্তমান নেই; তোমরা আল্লাহকেই ভয় করো, জেনে রাখো, আল্লাহ তায়ালা কঠোর আযাব প্রদানকারী বটে!', 'Waatimmoo alhajja waalAAumrata lillahi fain ohsirtum fama istaysara mina alhadyi wala tahliqoo ruoosakum hatta yablugha alhadyu mahillahu faman kana minkum mareedan aw bihi athan min rasihi fafidyatun min siyamin aw sadaqatin aw nusukin faitha amintum faman tamattaAAa bialAAumrati ila alhajji fama istaysara mina alhadyi faman lam yajid fasiyamu thalathati ayyamin fee alhajji wasabAAatin itha rajaAAtum tilka AAasharatun kamilatun thalika liman lam yakun ahluhu hadiree almasjidi alharami waittaqoo Allaha waiAAlamoo anna Allaha shadeedu alAAiqabi', 1, NOW(), NOW()),
(2, 197, 'ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ', 'হজ্জের মাসসমূহ (সুপরিচিত ও) সুনির্দিষ্ট, অতপর সে সময়গুলোর মধ্যে যে ব্যক্তি হজ্জ (আদায়) করার মনস্থ করবে (সে যেন জেনে রাখে), হজ্জের ভেতর (কোনো ) যৌনসম্ভোগ নেই, নেই কোনো মন্দকাজ ও ঝগড়াঝাটি। তোমরা যা ভালো কাজ করো আল্লাহ তায়ালা তা জানেন; (হজ্জের নিয়ত করলে) এর জন্যে তোমরা পাথেয় যোগাড় করে নেবে, নিসন্দেহে তাকওয়া হচ্ছে (মানুষের) সর্বোৎকৃষ্ট পাথেয়, অতএব হে বুদ্ধিমান মানুষরা, তোমরা আমাকেই ভয় করো।', 'Alhajju ashhurun maAAloomatun faman farada feehinna alhajja fala rafatha wala fusooqa wala jidala fee alhajji wama tafAAaloo min khayrin yaAAlamhu Allahu watazawwadoo fainna khayra alzzadi alttaqwa waittaqooni ya olee alalbabi', 1, NOW(), NOW()),
(2, 198, 'لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ', '(হজ্জের এ সময়গুলোতে) যদি তোমরা তোমাদের মালিকের অনুগ্রহ তালাশ করতে (গিয়ে কোনো ব্যবসা বাণিজ্য করতে চাও তাতে তোমাদের ওপর কোনোই দোষ নেই, অতপর তোমরা যখন আরাফাতের ময়দান থেকে ফিরে আসবে, তখন (মোযদালাফায়) ‘মাশয়ারে হারাম‘-এর কাছে এসে আল্লাহকে স্মরণ করো, (ঠিক) যেমনি করে আল্লাহ তায়ালা তোমাদের (তাঁকে ডাকার) পথ বলে দিয়েছেন, যদিও ইতিপূর্বে তোমরা পথভ্রষ্টদের দলে শামিল ছিলে!', 'Laysa AAalaykum junahun an tabtaghoo fadlan min rabbikum faitha afadtum min AAarafatin faothkuroo Allaha AAinda almashAAari alharami waothkuroohu kama hadakum wain kuntum min qablihi lamina alddalleena', 1, NOW(), NOW()),
(2, 199, 'ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'তারপর তোমরা সে স্থান থেকে ফিরে এসো, যেখান থেকে অন্য (হজ্জ পালনকারী) ব্যক্তিরা ফিরে আসে, (নিজে দের ভুল ভ্রান্তির জন্যে) আল্লাহ তায়ালার কাছে ক্ষমা প্রার্থনা করো, নিসন্দেহে আল্লাহ তায়ালা (গুনাহ খাতা) মাফ করে দেন, তিনি বড়োই দয়ালু!', 'Thumma afeedoo min haythu afada alnnasu waistaghfiroo Allaha inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(2, 200, 'فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ', 'যখন তোমরা তোমাদের (হজ্জের) যাবতীয় আনুষ্ঠানিকতা শেষ করে নেবে, তখন (এখানে বসে আগের দিনে) যেভাবে তোমরা তোমাদের পূর্বপুরুষদের (গৌরবের কথা) স্মরণ করতে, তেমনি– বরং তার চাইতে বেশী পরিমাণে আল্লাহকে স্মরণ করো। মানুষদের ভেতর এমন আছে যারা বলে, হে আমাদের রব, (সব) ভালো জিনিস তুমি আমাদের দুনিয়াতেই দিয়ে দাও, হাঁ, (যারা এ ধরনের কথা বলে) তাদের জন্যে পরকালে আর কোনো পাওনাই (বাকী) থাকে না।', 'Faitha qadaytum manasikakum faothkuroo Allaha kathikrikum abaakum aw ashadda thikran famina alnnasi man yaqoolu rabbana atina fee alddunya wama lahu fee alakhirati min khalaqin', 1, NOW(), NOW()),
(2, 201, 'وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ', '(আবার) তাদের মধ্যে এমনও আছে যারা বলে, হে আমাদের রব, তুমি এ দুনিয়ায় আমাদের কল্যাণ দাও, (কল্যাণ দাও) পরকালেও; (সেদিনের বড়ো কল্যাণ হিসেবে) তুমি আমাদের আগুনের আযাব থেকে বাঁচাও।', 'Waminhum man yaqoolu rabbana atina fee alddunya hasanatan wafee alakhirati hasanatan waqina AAathaba alnnari', 1, NOW(), NOW()),
(2, 202, 'أُوْلَـٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ', 'এ ধরনের লোকদের জন্যে তাদের নিজ নিজ অর্জন মোতাবেক তাদের যথার্থ হিস্যা (নির্ধারিত) রয়েছে, আল্লাহ তায়ালা হচ্ছেন দ্রুত হিসাব গ্রহণকারী।', 'Olaika lahum naseebun mimma kasaboo waAllahu sareeAAu alhisabi', 1, NOW(), NOW()),
(2, 203, '۞وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ', 'হাতেগনা (হজ্জের) এ কয়টি দিনে তোমরা আল্লাহকে স্মরণ করো; (হজ্জের পর) যদি কেউ তাড়াহুড়ো করে দু’দিনের মধ্যে (মিনা থেকে) ফিরে আসে তাতে (যেমন) তার কোনো দোষ নেই, (তেমনি) কেউ যদি সেখানে আরো বেশী অপেক্ষা করতে চায় তাতেও তার কোনো দোষ নেই, (এ নিয়ম হচ্ছে) তার জন্যে, যে আল্লাহকে ভয় করেছে, তোমরা শুধু আল্লাহ তায়ালাকেই ভয় করো এবং জেনে রাখো, একদিন তোমাদের অবশ্যই তাঁর কাছে জড়ো করা হবে।', 'Waothkuroo Allaha fee ayyamin maAAdoodatin faman taAAajjala fee yawmayni fala ithma AAalayhi waman taakhkhara fala ithma AAalayhi limani ittaqa waittaqoo Allaha waiAAlamoo annakum ilayhi tuhsharoona', 1, NOW(), NOW()),
(2, 204, 'وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ', 'মানুষদের মাঝে এমন লোকও আছে, যার কথাবার্তা তোমাকে পার্থিব জীবনে খুবই উৎফুল্ল করবে, তার মনে যা কিছু আছে সে তার ওপর আল্লাহ তায়ালাকে সাক্ষী বানায়, কিন্তু সে হচ্ছে ভীষণ ঝগড়াটে ব্যক্তি।', 'Wamina alnnasi man yuAAjibuka qawluhu fee alhayati alddunya wayushhidu Allaha AAala ma fee qalbihi wahuwa aladdu alkhisami', 1, NOW(), NOW()),
(2, 205, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ', 'যখন সে (যমীনের কোথাও) ক্ষমতা লাভ করে (তখন) সে চেষ্টা করে– সেখানে যেন সে (নানা) অশান্তি সৃষ্টি করতে পারে, (যমীনের) শস্য ক্ষেত্র (বিনাশ করে দিতে পারে জীব জন্তু) ও (মানুষের) বংশ নির্মূল করে দিতে পারে; (মূলত) আল্লাহ তায়ালা কখনো বিপর্যয় (সৃষ্টিকারীদের) পছন্দ করেন না।', 'Waitha tawalla saAAa fee alardi liyufsida feeha wayuhlika alhartha waalnnasla waAllahu la yuhibbu alfasada', 1, NOW(), NOW()),
(2, 206, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ', 'যখন তাকে বলা হয় (ফেতনা ফাসাদ না করে) তুমি আল্লাহ তায়ালাকে ভয় করো, তখন (মিথ্যা) অহংকার তাকে গুনাহর প্রতি (আরো বেশী) উৎসাহিত করে, (মূলত) এ (চরিত্রের) লোকের জন্যে জাহান্নামই যথেষ্ট; অবশ্যই (জাহান্নাম) হচ্ছে নিকৃষ্টতম ঠিকানা!', 'Waitha qeela lahu ittaqi Allaha akhathathu alAAizzatu bialithmi fahasbuhu jahannamu walabisa almihadu', 1, NOW(), NOW()),
(2, 207, 'وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ', 'মানুষদের ভেতর (আবার) এমন কিছু লোকও রয়েছে, যারা আল্লাহ তায়ালার সন্তুষ্টিলাভের জন্যে নিজের জীবন (পর্যন্ত) বিক্রি করে দেয়, (এ ধরনের) বান্দাদের প্রতি আল্লাহ তায়ালা বড়োই অনুগ্রহশীল!', 'Wamina alnnasi man yashree nafsahu ibtighaa mardati Allahi waAllahu raoofun bialAAibadi', 1, NOW(), NOW()),
(2, 208, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ', 'হে ঈমানদার লোকেরা, তোমরা পুরোপুরিই ইসলামে দাখিল হয়ে যাও এবং কোনো অবস্থায়ই শয়তানের পদাঙ্ক অনুসরণ করো না; অবশ্যই সে তোমাদের প্রকাশ্য দুশমন!', 'Ya ayyuha allatheena amanoo odkhuloo fee alssilmi kaffatan wala tattabiAAoo khutuwati alshshaytani innahu lakum AAaduwwun mubeenun', 1, NOW(), NOW()),
(2, 209, 'فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'তোমাদের কাছে (আল্লাহ তায়ালার) এসব সুস্পষ্ট নিদর্শন এসে যাওয়ার পরও যদি তোমরা পদস্খলন ঘটাও, তাহলে নিশ্চিত জেনে রাখো, আল্লাহ তায়ালা মহা বিজ্ঞ ও পরাক্রমশালী।', 'Fain zalaltum min baAAdi ma jaatkumu albayyinatu faiAAlamoo anna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(2, 210, 'هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَـٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', '(তবে) তারা কি (সেদিনের) অপেক্ষা করছে, যখন আল্লাহ তায়ালা স্বয়ং (তাঁর) ফেরেশতাসহ মেঘের ছায়া দিয়ে তাদের কাছে আসবেন এবং (তখন তাদের ভাগ্যের চূড়ান্ত) ফয়সালা হয়েই যাবে; সব কিছু তো (সর্বশেষে) আল্লাহর কাছেই উপনীত হবে।', 'Hal yanthuroona illa an yatiyahumu Allahu fee thulalin mina alghamami waalmalaikatu waqudiya alamru waila Allahi turjaAAu alomooru', 1, NOW(), NOW()),
(2, 211, 'سَلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'তুমি বনী ইসরাঈলদের জিজ্ঞেস করো, কি পরিমাণ সুস্পষ্ট নিদর্শন আমি তাদের দান করেছি; (আমি তাদের বলেছি,) যার কাছে আল্লাহর নেয়ামত আসার পর সে তা বদলে ফেলে, অবশ্যই আল্লাহ তায়ালা কঠোর শাস্তিদানকারী।', 'Sal banee israeela kam ataynahum min ayatin bayyinatin waman yubaddil niAAmata Allahi min baAAdi ma jaathu fainna Allaha shadeedu alAAiqabi', 1, NOW(), NOW()),
(2, 212, 'زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ', 'যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে, তাদের জন্যে তাদের এ পার্থিব জীবনটা খুব শোভনীয় করে (সাজিয়ে) রাখা হয়েছে, এরা ঈমানদার ব্যক্তিদের বিদ্রূপ করে, (অথচ) এ ঈমানদার ব্যক্তি- যারা আল্লাহ তায়ালাকে ভয় করেছে, শেষ বিচারের দিন তাদের মর্যাদা হবে (এদের তুলনায়) অনেক বেশী; আল্লাহ তায়ালা যাকে চান তাকে অপরিমিত রিজিক দান করেন।', 'Zuyyina lillatheena kafaroo alhayatu alddunya wayaskharoona mina allatheena amanoo waallatheena ittaqaw fawqahum yawma alqiyamati waAllahu yarzuqu man yashao bighayri hisabin', 1, NOW(), NOW()),
(2, 213, 'كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ', '(এক সময়) সব মানুষ একই উম্মতের অন্তর্ভুক্ত ছিলো, (পরে এরা নানা দলে বিভক্ত হয়ে তাদের স্রষ্টাকেই ভুলে গেলো)। অতপর আল্লাহ তায়ালা (সঠিক পথের অনুসারীদের) সুসংবাদবাহী আর (গুনাহগারদের জন্যে) আযাবের সতর্ককারী হিসেবে নবীদের পাঠালেন, তিনি তাদের সাথে সত্য (দ্বীন)-সহ গ্রন্থও নাযিল করলেন, যেন তা মানুষদের এমন পারস্পরিক বিরোধসমূহের চূড়ান্ত ফয়সালা করতে পারে, যে ব্যাপারে তারা মতবিরোধ করে; তাদের কাছে সুস্পষ্ট হেদায়াত পাঠানো সত্ত্বেও তারা পারস্পরিক (বিদ্রোহ ও) বিদ্বেষ সৃষ্টির জন্যে মতবিরোধ করেছে, অতপর আল্লাহ তায়ালা ঈমানদারদের স্বীয় ইচ্ছায় সেই সঠিক পথ দেখালেন, যার ব্যাপারে ইতিপূর্বে তারা মতবিরোধ করেছিলো; আল্লাহ তায়ালা যাকে চান তাকে সঠিক পথ দেখান।', 'Kana alnnasu ommatan wahidatan fabaAAatha Allahu alnnabiyyeena mubashshireena wamunthireena waanzala maAAahumu alkitaba bialhaqqi liyahkuma bayna alnnasi feema ikhtalafoo feehi wama ikhtalafa feehi illa allatheena ootoohu min baAAdi ma jaathumu albayyinatu baghyan baynahum fahada Allahu allatheena amanoo lima ikhtalafoo feehi mina alhaqqi biithnihi waAllahu yahdee man yashao ila siratin mustaqeemin', 1, NOW(), NOW()),
(2, 214, 'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ', 'তোমরা কি মনে করে নিয়েছো যে, তোমরা (এমনি এমনিই) জান্নাতে প্রবেশ করবে! (অথচ) তোমাদের পূর্ববর্তী লোকদের (বিপদের) মতো কিছুই তোমাদের কাছে এখনো আসেনি, তাদের ওপর (নানা) অভাব অভিযোগ ও রোগব্যাধি এসেছে, (কঠিন নিপীড়নে) তাদের প্রকম্পিত করে দেয়া হয়েছে, এমন কি স্বয়ং (আল্লাহর) নবী ও তার সংগী সাথীরা (এক পর্যায়ে) এই বলে (আর্তনাদ করে) উঠেছে, আল্লাহ তায়ালার সাহায্য কবে (আসবে, আল্লাহ তায়ালা সান্ত্বনা দিয়ে বললেন), হাঁ, অবশ্যই আল্লাহ তায়ালার সাহায্য (অতি) নিকটে।', 'Am hasibtum an tadkhuloo aljannata walamma yatikum mathalu allatheena khalaw min qablikum massathumu albasao waalddarrao wazulziloo hatta yaqoola alrrasoolu waallatheena amanoo maAAahu mata nasru Allahi ala inna nasra Allahi qareebun', 1, NOW(), NOW()),
(2, 215, 'يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ', 'তারা তোমার কাছে জানতে চাইবে তারা কি (কি খাতে) খরচ করবে, তুমি (তাদের) বলে দাও, যা কিছুই তোমরা তোমাদের পিতামাতা, আত্মীয় স্বজন, এতীম অসহায় মেসকীন এবং মোসাফেরের জন্যে খরচ করবে (তাই আল্লাহ তায়ালা গ্রহণ করবেন); যা ভালো তোমরা করবে আল্লাহ তায়ালা তা অবশ্যই জানতে পারবেন।', 'Yasaloonaka matha yunfiqoona qul ma anfaqtum min khayrin falilwalidayni waalaqrabeena waalyatama waalmasakeeni waibni alssabeeli wama tafAAaloo min khayrin fainna Allaha bihi AAaleemun', 1, NOW(), NOW()),
(2, 216, 'كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', '(ন্যায় প্রতিষ্ঠা ও অন্যায় নির্মূল করার জন্যে) যুদ্ধ তোমাদের ওপর ফরয করে দেয়া হয়েছে, আর সেটাই তোমাদের কাছে অপছন্দনীয়, (কিন্তু) এমনও তো হতে পারে যে বিষয়টি তোমাদের ভালো লাগে না, তাই তোমাদের জন্যে কল্যাণকর, আবার (একইভাবে) এমন কোনো জিনিস, যা তোমরা পছন্দ করবে, কিন্তু তা হবে তোমাদের জন্যে ক্ষতিকর; আল্লাহ তায়ালাই সবচাইতে ভালো জানেন, তোমরা কিছুই জানো না।', 'Kutiba AAalaykumu alqitalu wahuwa kurhun lakum waAAasa an takrahoo shayan wahuwa khayrun lakum waAAasa an tuhibboo shayan wahuwa sharrun lakum waAllahu yaAAlamu waantum la taAAlamoona', 1, NOW(), NOW()),
(2, 217, 'يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'সম্মানিত মাস ও তাতে যুদ্ধ করা সম্পর্কে তারা তোমাকে জিজ্ঞেস করবে, তুমি তাদের বলে দাও, এই মাসে যুদ্ধবিগ্রহ করা অনেক বড়ো (গুনাহ), (কিন্তু আল্লাহর কাছে এর চাইতেও বড়ো গুনাহ হচ্ছে), আল্লাহর পথ থেকে মানুষদের ফিরিয়ে রাখা, আল্লাহকে অস্বীকার করা, খানায়ে কাবার দিকে যাওয়ার পথ রোধ করা ও সেখানকার অধিবাসীদের সেখান থেকে বের করে দেয়া, আর (আল্লাহদ্রোহিতার) ফেতনা ফাসাদ হত্যাকান্ডের চাইতেও অনেক বড়ো (অন্যায়, তুমি ভেবো না যে,) এরা তোমাদের সাথে (এ মাসসমূহে) লড়াই বন্ধ করে দেবে, তারা তো পারলে (বরং) তোমাদের সবাইকে তোমাদের (ইসলামী) জীবন বিধান থেকেও ফিরিয়ে নিতে চাইবে; যদি তোমাদের কোনো ব্যক্তি তাঁর দ্বীন থেকে ফিরে যায়, অতপর সে মৃত্যুমুখে পতিত হয়– এমন অবস্থায় যে, সে (সুস্পষ্ট) কাফের ছিলো, তাহলে তারাই হবে সেসব লোক যাদের যাবতীয় কর্মকান্ড দুনিয়া আখেরাতে বিফলে যাবে, আর এরাই হবে জাহান্নামের অধিবাসী, সেখানে তারা চিরদিন থাকবে।', 'Yasaloonaka AAani alshshahri alharami qitalin feehi qul qitalun feehi kabeerun wasaddun AAan sabeeli Allahi wakufrun bihi waalmasjidi alharami waikhraju ahlihi minhu akbaru AAinda Allahi waalfitnatu akbaru mina alqatli wala yazaloona yuqatiloonakum hatta yaruddookum AAan deenikum ini istataAAoo waman yartadid minkum AAan deenihi fayamut wahuwa kafirun faolaika habitat aAAmaluhum fee alddunya waalakhirati waolaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(2, 218, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَـٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'নিসন্দেহে যারা ঈমান এনেছে, যারা হিজরত করেছে এবং আল্লাহর পথে জেহাদ করেছে, তারাই হচ্ছে এমন লোক যাদের ব্যাপারে আল্লাহ তায়ালার অনুগ্রহের আশা করা যায়; আল্লাহ তায়ালা ক্ষমাশীল, অত্যন্ত দয়ালু!', 'Inna allatheena amanoo waallatheena hajaroo wajahadoo fee sabeeli Allahi olaika yarjoona rahmata Allahi waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(2, 219, '۞يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ', '(হে নবী,) এরা তোমাকে মদ ও জুয়া সম্পর্কে জিজ্ঞেস করবে; তুমি বলো, এ দুটো জিনিসের মধ্যে অনেক বড়ো ধরনের পাপ রয়েছে, (যদিও) মানুষের জন্যে (এতে) কিছু (ব্যবসায়িক) মুনাফাও রয়েছে; কিন্তু এ উভয়ের গুনাহ এদের (ব্যবসায়িক) মুনাফার চাইতে অনেক বেশী; তারা তোমাকে (এ-ও) জিজ্ঞেস করে যে, তারা (নেক কাজে) কী কী খরচ করবে; তুমি তাদের বলো, (দৈনন্দিন প্রয়োজন পূরণের পর) যা অতিরিক্ত (তা খরচ করো); আল্লাহ তায়ালা এভাবে তোমাদের জন্যে (তাঁর) আয়াতসমূহ খুলে খুলে বলে দেন, আশা করা যায় তোমরা চিন্তা ভাবনা করবে,', 'Yasaloonaka AAani alkhamri waalmaysiri qul feehima ithmun kabeerun wamanafiAAu lilnnasi waithmuhuma akbaru min nafAAihima wayasaloonaka matha yunfiqoona quli alAAafwa kathalika yubayyinu Allahu lakumu alayati laAAallakum tatafakkaroona', 1, NOW(), NOW()),
(2, 220, 'فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', 'ইহকাল পরকাল উভয় সময় (নিয়েই চিন্তা ভাবনা করবে); তোমাকে তারা এতীমদের ব্যাপারে জিজ্ঞেস করবে; তুমি বলো, সংশোধনের (সব) পন্থাই তাদের জন্যে উত্তম; যদি তোমরা (তোমাদের ধন সম্পদ) তাদের সাথে মিশিয়ে ফেলো (তাতে কোনো দোষ নেই, কারণ), তারা তো তোমাদেরই ভাই; আর আল্লাহ তায়ালা (এটা) ভালো করেই জানেন, (কে) ন্যায়ানুগ (পন্থায় আছে, আর কে ফাসাদী (স্বভাবের) লোক, আল্লাহ্ তায়ালা চাইলে (এ ব্যাপারে) তোমাদের আরো অধিক কষ্ট দিতে পারতেন; নিসন্দেহে আল্লাহ তায়ালা মহা ক্ষমতাবান, কুশলী।', 'Fee alddunya waalakhirati wayasaloonaka AAani alyatama qul islahun lahum khayrun wain tukhalitoohum faikhwanukum waAllahu yaAAlamu almufsida mina almuslihi walaw shaa Allahu laaAAnatakum inna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(2, 221, 'وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةٞ مُّؤۡمِنَةٌ خَيۡرٞ مِّن مُّشۡرِكَةٖ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدٞ مُّؤۡمِنٌ خَيۡرٞ مِّن مُّشۡرِكٖ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَـٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ', 'তোমরা (কখনো) কোনো মুশরীক নারীকে বিয়ে করো না, যতোক্ষণ না তারা ঈমান আনে, (মনে রেখো,) একজন মুসলমান দাসীও একজন (ঐতিহ্যবাহী) মুশরীক নারীর চাইতে উত্তম, যদিও এ (মুশরীক) নারীটি তোমাদের বেশী ভালো লাগে, আর তোমরা কোনো মুশরীক ব্যক্তির কাছে (মুসলিম মহিলাদের) বিয়ে দেবে না, যতোক্ষণ না তারা আল্লাহর ওপর ঈমান আনে; (কেননা) একজন ঈমানদার দাসও (একজন উঁচু খান্দানের) মুশরীক ব্যক্তির চাইতে ভালো, যদিও এ মুশরীক ব্যক্তিটি তোমাদের ভালো লাগে; (কেননা) এরা তোমাদের জাহান্নামের (আগুনের দিকেই ডাকে, আর আল্লাহ তায়ালা হামেশাই তাঁর মুমীন বান্দাদের তাঁর আদেশবলে জান্নাত ও ক্ষমার দিকেই আহবান জানান এবং (এ জন্যে) তিনি তাঁর আয়াতসমূহ মানুষদের কাছে স্পষ্ট করে বর্ণনা করেন, আশা করা যায় তারা উপদেশ গ্রহণ করবে।', 'Wala tankihoo almushrikati hatta yuminna walaamatun muminatun khayrun min mushrikatin walaw aAAjabatkum wala tunkihoo almushrikeena hatta yuminoo walaAAabdun muminun khayrun min mushrikin walaw aAAjabakum olaika yadAAoona ila alnnari waAllahu yadAAoo ila aljannati waalmaghfirati biithnihi wayubayyinu ayatihi lilnnasi laAAallahum yatathakkaroona', 1, NOW(), NOW()),
(2, 222, 'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِيضِۖ قُلۡ هُوَ أَذٗى فَٱعۡتَزِلُواْ ٱلنِّسَآءَ فِي ٱلۡمَحِيضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ يَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَيۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّـٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ', '(হে নবী,) তারা তোমার কাছ থেকে (মহিলাদের মাসিক) ঋতুকাল (ও এ সময় তাদের সাথে দৈহিক মিলন) সম্পর্কে জানতে চাইবে; তুমি বলো, (আসলে মহিলাদের) এ (সময়টা) হচ্ছে একটা কষ্টকর (অবস্থা), (কাজেই) ঋতুকালে তাদের সঙ্গ বর্জন করবে এবং (এ সময় দৈহিক মিলনের জন্যে) তোমরা তাদের কাছে যেও না, যতোক্ষণ না তারা (পুনরায়) পবিত্র হয়, অতপর তারা যখন পুরো পাক সাফ হয়ে যায় তখন তোমরা তাদের কাছে যাও— (দৈহিক মিলনের) যে পদ্ধতি আল্লাহ তায়ালা শিখিয়ে দিয়েছেন সেভাবে; আল্লাহ তায়ালা অবশ্যই সেসব লোকদের ভালোবাসেন যারা তাওবা করে এবং তিনি তাদেরও ভালোবাসেন যারা পাক পবিত্রতা অবলম্বন করে।', 'Wayasaloonaka AAani almaheedi qul huwa athan faiAAtaziloo alnnisaa fee almaheedi wala taqraboohunna hatta yathurna faitha tatahharna fatoohunna min haythu amarakumu Allahu inna Allaha yuhibbu alttawwabeena wayuhibbu almutatahhireena', 1, NOW(), NOW()),
(2, 223, 'نِسَآؤُكُمۡ حَرۡثٞ لَّكُمۡ فَأۡتُواْ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُواْ لِأَنفُسِكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُم مُّلَٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ', 'তোমাদের স্ত্রীরা হচ্ছে তোমাদের জন্যে (সন্তান উৎপাদনের) ফসল ক্ষেত্র, তোমরা তোমাদের এই ফসল ক্ষেত্রে যেভাবে ইচ্ছা সেভাবেই গমন করো, তোমরা নিজেদের (ভবিষ্যতের) জন্যে কিছু (অগ্রিম নেক আমল) পাঠিয়ে দাও; তোমরা আল্লাহকে ভয় করো, জেনে রেখো, একদিন অবশ্যই তোমাদের সবাইকে তাঁর সামনাসামনি হতে হবে। মুমীনদের তুমি (পুরস্কারের) সুসংবাদ দাও।', 'Nisaokum harthun lakum fatoo harthakum anna shitum waqaddimoo lianfusikum waittaqoo Allaha waiAAlamoo annakum mulaqoohu wabashshiri almumineena', 1, NOW(), NOW()),
(2, 224, 'وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةٗ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمٞ', 'তোমরা তোমাদের (এমন) শপথের জন্যে আল্লাহকে কখনো ঢাল হিসেবে ব্যবহার করবে না, (যার মাধ্যমে) ভালো কাজ করা, (আল্লাহ তায়ালাকে) ভয় করা এবং মানুষদের মাঝে শান্তি শৃংখলা প্রতিষ্ঠা করার কাজ থেকে তোমরা দূরে থাকবে, আল্লাহ তায়ালা তোমাদের সব কিছুই শোনেন এবং সব কথাই তিনি জানেন।', 'Wala tajAAaloo Allaha AAurdatan liaymanikum an tabarroo watattaqoo watuslihoo bayna alnnasi waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(2, 225, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ', 'আল্লাহ তায়ালা তোমাদের নিরর্থক শপথের জন্যে কখনো পাকড়াও করবেন না, তবে তিনি অবশ্যই সে সব শপথের ব্যাপারে তোমাদের জিজ্ঞাসাবাদ করবেন, যা তোমরা মনের সংকল্পের সাথে সম্পন্ন করো; (বস্তুত) আল্লাহ তায়ালা ক্ষমাশীল ধৈর্যশীল।', 'La yuakhithukumu Allahu biallaghwi fee aymanikum walakin yuakhithukum bima kasabat quloobukum waAllahu ghafoorun haleemun', 1, NOW(), NOW()),
(2, 226, 'لِّلَّذِينَ يُؤۡلُونَ مِن نِّسَآئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرٖۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'যেসব লোক নিজ স্ত্রীদের কাছে যাবে না বলে কসম করেছে (তাদের মনস্থির করার) জন্যে তাদের চার মাসের অবকাশ রয়েছে, (এ সময়ের ভেতর) যদি তারা (তাদের কসম থেকে) ফিরে আসে (তাহলে জেনে রেখো) আল্লাহ তায়ালা ক্ষমাশীল ও দয়াবান!', 'Lillatheena yuloona min nisaihim tarabbusu arbaAAati ashhurin fain faoo fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(2, 227, 'وَإِنۡ عَزَمُواْ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', 'তারা যদি (স্ত্রীদের) তালাক দেয়ার সিদ্ধান্ত করে, তাহলে (তারা যেন জেনে রাখে) আল্লাহ তায়ালা সব শোনেন জানেন।', 'Wain AAazamoo alttalaqa fainna Allaha sameeAAun AAaleemun', 1, NOW(), NOW()),
(2, 228, 'وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٖۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحٗاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةٞۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'তালাকপ্রাপ্তা মহিলারা যেন তিনটি মাসিক ঋতু (অথবা ঋতু থেকে পবিত্র থাকার তিনটি মুদ্দত) পর্যন্ত নিজেদের (পুনরায় বিয়ে) থেকে দূরে রাখে; তাদের গর্ভাশয়ে আল্লাহ তায়ালা যা কিছু সৃষ্টি করেছেন তা গোপন করা তাদের পক্ষে ন্যায়সংগত হবে না– যদি তারা আল্লাহ তায়ালা এবং পরকালের ওপর ঈমান আনে; এ সময়ের ভেতর তাদের ফিরিয়ে নেয়ার ব্যাপারে তাদের স্বামীদের অধিকার অবশ্য একটু বেশী, যদি তারা উভয়ে পরস্পর মিলে মিশে চলতে চায়; পুরুষদের ওপর নারীদের যেমন ন্যায়ানুগ অধিকার রয়েছে, তেমনি রয়েছে নারীদের ওপর পুরুষের অধিকার, (অর্থনৈতিক দায়িত্বের কারণে) তাদের ওপর পুরুষের মর্যাদা এক মাত্রা বেশী, আল্লাহ তায়ালা বিপুল ক্ষমতার মালিক, (তিনি পরম) কুশলী।', 'Waalmutallaqatu yatarabbasna bianfusihinna thalathata qurooin wala yahillu lahunna an yaktumna ma khalaqa Allahu fee arhamihinna in kunna yuminna biAllahi waalyawmi alakhiri wabuAAoolatuhunna ahaqqu biraddihinna fee thalika in aradoo islahan walahunna mithlu allathee AAalayhinna bialmaAAroofi walilrrijali AAalayhinna darajatun waAllahu AAazeezun hakeemun', 1, NOW(), NOW()),
(2, 229, 'ٱلطَّلَٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ وَلَا يَحِلُّ لَكُمۡ أَن تَأۡخُذُواْ مِمَّآ ءَاتَيۡتُمُوهُنَّ شَيۡـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', '(যে তালাক থেকে ফিরে আসা যায়, সে) তালাক দু’বার– অতপর (বিধান হচ্ছে) মর্যাদার সাথে (তাকে বিয়ের বন্ধনে) রেখে দেয়া, অথবা সহৃদয়তার সাথে তাকে চলে যেতে দেবে; তোমাদের জন্যে এটা কোনো অবস্থায়ই ন্যায়সংগত নয় যে, (বিয়ের আগে) যা কিছু তোমরা তাদের দিয়েছো তা তাদের থেকে ফিরিয়ে নেবে, তবে আল্লাহর নির্দিষ্ট সীমারেখার ভেতরে থেকে স্বামী স্ত্রী একত্রে জীবন কাটাতে পারবে না– এমন আশংকা যদি দেখা দেয় (তখন আলাদা হয়ে যাওয়াটাই উত্তম, এমন অবস্থায়) যদি তোমাদের ভয় হয় যে, এরা আল্লাহর বিধানের গন্ডির ভেতর থাকতে পারবে না; তাহলে স্ত্রী যদি স্বামীকে কিছু বিনিময় দেয় (এবং তা দিয়ে বিচ্ছেদ ঘটিয়ে নেয়), তাহলে তাদের উভয়ের ওপর এটা কোন দূষণীয় (বিষয়) হবে না, (জেনে রাখো) এটা হচ্ছে আল্লাহর নির্ধারিত সীমারেখা, তা কখনো অতিক্রম করো না, আর যারা আল্লাহর দেয়া সীমারেখা লংঘন করে তারাই হচ্ছে যালিম।', 'Alttalaqu marratani faimsakun bimaAAroofin aw tasreehun biihsanin wala yahillu lakum an takhuthoo mimma ataytumoohunna shayan illa an yakhafa alla yuqeema hudooda Allahi fain khiftum alla yuqeema hudooda Allahi fala junaha AAalayhima feema iftadat bihi tilka hudoodu Allahi fala taAAtadooha waman yataAAadda hudooda Allahi faolaika humu alththalimoona', 1, NOW(), NOW()),
(2, 230, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَيۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوۡمٖ يَعۡلَمُونَ', '(তৃতীয়বার) যদি সে তাকে তালাক দিয়ে দেয়, (তাহলে) (এ) স্ত্রী তার জন্যে তারপর (আর) বৈধ থাকবে না, (হ্যাঁ) যদি তাকে অপর কোনো স্বামী বিয়ে করে এবং (নিয়মমাফিক তাকে) তালাক দেয় এবং (পরে) তারা যদি মনে করে, তারা (এখন স্বামী স্ত্রীর অধিকার সম্পর্কে) আল্লাহর সীমারেখা মেনে চলতে পারবে, তাহলে পুনরায় (বিয়ে বন্ধনে) ফিরে আসাতে তাদের ওপর কোনো দোষ নেই; এটা হচ্ছে আল্লাহর (বেঁধে দেয়া) সীমারেখা, যারা (এ সম্পর্কে) জানে আল্লাহ তায়ালা তাদের জন্যে এ নির্দেশ সুস্পষ্ট করে পেশ করেন।', 'Fain tallaqaha fala tahillu lahu min baAAdu hatta tankiha zawjan ghayrahu fain tallaqaha fala junaha AAalayhima an yatarajaAAa in thanna an yuqeema hudooda Allahi watilka hudoodu Allahi yubayyinuha liqawmin yaAAlamoona', 1, NOW(), NOW()),
(2, 231, 'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفٖۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوٓاْ ءَايَٰتِ ٱللَّهِ هُزُوٗاۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ وَمَآ أَنزَلَ عَلَيۡكُم مِّنَ ٱلۡكِتَٰبِ وَٱلۡحِكۡمَةِ يَعِظُكُم بِهِۦۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'যখন তোমরা স্ত্রীদের তালাক দাও এবং তারা যখন তাদের (ইদ্দতের) অপেক্ষার সময় পূর্ণ করে নেয়, তখন (হয়) মর্যাদার সাথে তাদের ফিরিয়ে আনো, নতুবা ভালোভাবে তাদের বিদায় করে দাও, শুধু কষ্ট দেয়া এবং (তাদের ওপর) বাড়াবাড়ি করার উদ্দেশ্যে তাদের আটকে রেখো না, আর যে ব্যক্তি এমন কাজ করে সে (প্রকারান্তরে) নিজের ওপরই যুলুম করে; (সাবধান) আল্লাহর আয়াতসমূহকে কখনো হাসি তামাশার বস্তু মনে করো না। স্মরণ করো (তোমরা ছিলে অজ্ঞ), আল্লাহ তায়ালা তোমাদের ওপর (হেদায়াত পাঠিয়ে নেয়ামত দান করেছেন, (শুধু তাই নয়) তিনি তোমাদের জন্যে জ্ঞান ও যুক্তিপূর্ণ কিতাব নাযিল করেছেন, যা দিয়ে তিনি তোমাদের (সব ধরনের) নিয়ম (কানুন) বাতলে দেন; (অতএব) তোমরা আল্লাহকে ভয় করো এবং জেনে রাখো, আল্লাহ তোমাদের যাবতীয় কাজকর্ম সম্পর্কে সম্পূর্ণভাবে জ্ঞাত আছেন।', 'Waitha tallaqtumu alnnisaa fabalaghna ajalahunna faamsikoohunna bimaAAroofin aw sarrihoohunna bimaAAroofin wala tumsikoohunna diraran litaAAtadoo waman yafAAal thalika faqad thalama nafsahu wala tattakhithoo ayati Allahi huzuwan waothkuroo niAAmata Allahi AAalaykum wama anzala AAalaykum mina alkitabi waalhikmati yaAAithukum bihi waittaqoo Allaha waiAAlamoo anna Allaha bikulli shayin AAaleemun', 1, NOW(), NOW()),
(2, 232, 'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن يَنكِحۡنَ أَزۡوَٰجَهُنَّ إِذَا تَرَٰضَوۡاْ بَيۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۗ ذَٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', 'যখন তোমরা (তোমাদের) স্ত্রীদের তালাক দিয়ে দাও, অতপর (তালাকপ্রাপ্ত) স্ত্রীরাও তাদের অপেক্ষার সময়টুকু শেষ করে নেয়, তখন তোমরা তাদের (আগের) স্বামীদের সাথে বিয়ের ব্যাপারে বাধা দিয়ো না, (বিশেষ করে) যখন তারা (বিয়ের জন্যে) সম্মানজনকভাবে কোনো ঐকমত্যে পৌছে যায়; তোমাদের ভেতর যারা আল্লাহ তায়ালা ও পরকালের ওপর বিশ্বাস স্থাপন করে তাদের এর মাধ্যমে আদেশ দেয়া যাচ্ছে; (মূলত) এটা তোমাদের জন্যে অধিক সম্মানের এবং অনেক পবিত্র (কর্মধারা, কারণ); আল্লাহ তায়ালা জানেন, তোমরা কিছুই জানো না।', 'Waitha tallaqtumu alnnisaa fabalaghna ajalahunna fala taAAduloohunna an yankihna azwajahunna itha taradaw baynahum bialmaAAroofi thalika yooAAathu bihi man kana minkum yuminu biAllahi waalyawmi alakhiri thalikum azka lakum waatharu waAllahu yaAAlamu waantum la taAAlamoona', 1, NOW(), NOW()),
(2, 233, '۞وَٱلۡوَٰلِدَٰتُ يُرۡضِعۡنَ أَوۡلَٰدَهُنَّ حَوۡلَيۡنِ كَامِلَيۡنِۖ لِمَنۡ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودٞ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضٖ مِّنۡهُمَا وَتَشَاوُرٖ فَلَا جُنَاحَ عَلَيۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوٓاْ أَوۡلَٰدَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡتُم مَّآ ءَاتَيۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٞ', 'মায়েরা পুরো দুটো বছরই তাদের (সন্তানকে) বুকের দুধ খাওয়াবে, (এ নিয়ম তার জন্যে) যে ব্যক্তি (স ন্তানের) দুধ খাওয়ানোটা পুরোপুরি আদায় করতে চায়; সন্তানের (দুধ খাওয়ানোর) জন্যে মায়েদের (সম্মানজনক) ভরণ পোষণ (সুনিশ্চিত) করতে হবে; কোনো ব্যক্তির ওপর তার সাধ্যাতীত বোঝা চাপিয়ে দেয়া যাবে না, (পিতার সংগতির কথা ভাবতে গিয়ে দেখতে হবে,) মায়েরাও যেন (আবার) নিজ সন্তান নিয়ে (বেশী) কষ্টে না পড়ে যায় এবং পিতাকেও যেন সন্তান (জন্ম দেয়ার) কারণে (অযথা) কষ্টে পড়ে যেতে না হয়, (সেটাও খেয়াল রাখতে হবে, সন্তানের পিতার অবর্তমানে তার) উত্তরাধিকারীদের ওপর (সন্তানের জন্মদাত্রী মায়ের অধিকার) এভাবেই (বহাল থাকবে, তবে কোনো পর্যায়ে) তারা উভয়ে যদি পারস্পরিক সম্মতি ও পরামর্শের ভিত্তিতে আগে ভাগেই সন্তানের দুধ ছাড়িয়ে নিতে চায় তাতেও তাদের ওপর কোনো দোষের কিছু নেই; তোমরা যদি নিজেদের বদলে অন্য কাউকে সন্তানের দুধ খাওয়ানোর জন্যে নিয়োগ করতে চাও এবং যদি দাত্রীর পাওনা যথাযথভাবে তোমরা বুঝিয়ে দাও, তাতেও কোনো গুনাহ নেই (সর্বাবস্থায়) তোমরা আল্লাহ তায়ালাকে ভয় করো এবং জেনে রেখো, তোমরা যা কিছুই করো আল্লাহ তায়ালা তার সব কিছুই দেখতে পান।', 'Waalwalidatu yurdiAAna awladahunna hawlayni kamilayni liman arada an yutimma alrradaAAata waAAala almawloodi lahu rizquhunna wakiswatuhunna bialmaAAroofi la tukallafu nafsun illa wusAAaha la tudarra walidatun biwaladiha wala mawloodun lahu biwaladihi waAAala alwarithi mithlu thalika fain arada fisalan AAan taradin minhuma watashawurin fala junaha AAalayhima wain aradtum an tastardiAAoo awladakum fala junaha AAalaykum itha sallamtum ma ataytum bialmaAAroofi waittaqoo Allaha waiAAlamoo anna Allaha bima taAAmaloona baseerun', 1, NOW(), NOW()),
(2, 234, 'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرٖ وَعَشۡرٗاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', 'তোমাদের মধ্যে যারা মৃত্যুমুখে পতিত হয় এবং তারা (যদি তাদের) স্ত্রীদের (জীবিত) রেখে যায় (সে অবস্থায় স্ত্রীরা যদি বিয়ে করতে চায়, তাহলে) তারা তাদের নিজেদের চার মাস দশ দিন পর্যন্ত সময় (বিয়ে থেকে) বিরত রাখবে, (অপেক্ষার) এ সময়টুকু যখন তারা পূরণ করে নেবে, তখন এ বিষয়টিতে তোমাদের ওপর কোনো দোষ (চাপানো ) হবে না । তখন তারা নিজেদের (বিয়ের) ব্যাপারে ন্যায়ানুগ পন্থায় যা ইচ্ছা তা করবে। (মূলত) তোমরা (যে) যাই করো না কেন, আল্লাহ তায়ালা (তার পুরোপুরি) খবর রাখেন।', 'Waallatheena yutawaffawna minkum wayatharoona azwajan yatarabbasna bianfusihinna arbaAAata ashhurin waAAashran faitha balaghna ajalahunna fala junaha AAalaykum feema faAAalna fee anfusihinna bialmaAAroofi waAllahu bima taAAmaloona khabeerun', 1, NOW(), NOW()),
(2, 235, 'وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ', '(এমন কি সে অপেক্ষার সময় শেষ হওয়ার আগেও) তোমরা কেউ যদি (তাদের) বিয়ে করার (জন্যে) পয়গাম পাঠাও, কিংবা তেমন কোনো ইচ্ছা যদি তোমরা নিজেদের মনের ভেতর লুকিয়ে রাখো, (তাতেও) তোমাদের ওপর কোনো দোষ নেই; কেননা আল্লাহ তায়ালা এটা ভালো করেই জানেন, তাদের কথা তোমরা বার বার স্মরণ করো, কিন্তু (সাবধান আড়ালে আবডালে থেকে) গোপনে তাদের বিয়ের কোনো প্রতিশ্রুতি দিয়ো না, তাদের সাথে কখনো তোমাদের কথা বলতে হলে তা বলবে সম্মানজনক পন্থায়; তার (অপেক্ষার আল্লাহর নির্ধারিত) ইদ্দত শেষ হবার আগে কখনো (তার সাথে) বিয়ের সংকল্প করো না; জেনে রেখো, তোমাদের মনের সব (ইচ্ছা অভিসন্ধির) কথা কিন্তু আল্লাহ তায়ালা ভালো করেই জানেন, অতএব তোমরা একমাত্র তাঁর থেকেই সতর্ক হও (এবং এও জেনে রেখো), আল্লাহ তায়ালা অত্যন্ত ক্ষমাশীল ধৈর্যশীল!', 'Wala junaha AAalaykum feema AAarradtum bihi min khitbati alnnisai aw aknantum fee anfusikum AAalima Allahu annakum satathkuroonahunna walakin la tuwaAAidoohunna sirran illa an taqooloo qawlan maAAroofan wala taAAzimoo AAuqdata alnnikahi hatta yablugha alkitabu ajalahu waiAAlamoo anna Allaha yaAAlamu ma fee anfusikum faihtharoohu waiAAlamoo anna Allaha ghafoorun haleemun', 1, NOW(), NOW()),
(2, 236, 'لَّا جُنَاحَ عَلَيۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَآءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُواْ لَهُنَّ فَرِيضَةٗۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِينَ', 'যে স্ত্রীদের তোমরা কখনো স্পর্শ করোনি কিংবা তাদের জন্যে মোহরের কোনো অংক নির্ধারণ করোনি (এমন অবস্থায়) যদি তোমরা তাদের তালাক দাও, তাতে তোমাদের ওপর কোনো গুনাহ নেই, (এ পরিস্থিতিতে মোহরের কোনো অংক নির্ধারিত না হলেও) তাদের ন্যায়ানুগ পন্থায় কিছু (অর্থ) আদায় করে দেবে, ধনী ব্যক্তির ওপর (এটা হবে তার) নিজ ক্ষমতা অনুযায়ী এবং গরীব ব্যক্তির ওপর (হবে) তার সংগতি অনুযায়ী, (এটা) নেককার লোকদের ওপর (স্ত্রীদের) একটি অধিকার বটে।', 'La junaha AAalaykum in tallaqtumu alnnisaa ma lam tamassoohunna aw tafridoo lahunna fareedatan wamattiAAoohunna AAala almoosiAAi qadaruhu waAAala almuqtiri qadaruhu mataAAan bialmaAAroofi haqqan AAala almuhsineena', 1, NOW(), NOW()),
(2, 237, 'وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ', 'যদি (এমন হয়,) তোমরা তাদের (শারীরিকভাবে) স্পর্শ করার আগেই তালাক দিয়েছো এবং মোহরের অংকও নির্ধারিত করে নিয়েছো, তাহলে তাদের জন্যে পরিমাণ (থাকবে) নির্ধারিত মোহরের অর্ধেক, (যা) আদায় করে দিতে হবে, (হাঁ) তালাকপ্রাপ্তা স্ত্রী নিজের থেকে যদি তোমাদের তা মাফ করে দেয় কিংবা যে (স্বামীর) হাতে বিয়ের বন্ধন রয়েছে– সে যদি (স্ত্রীকে নির্দিষ্ট পরিমাণের বেশী দিয়ে) অনুগ্রহ দেখাতে চায় (সেটা ভিন্ন কথা), তোমরা যদি অনুগ্রহ করো (তাহলে) তা হবে তাকওয়ার একান্ত কাছাকাছি; কখনো একে অপরের প্রতি দয়া ও সহৃদয়তা দেখাতে ভুলো না; কারণ তোমরা (কে) কি করো, তার সব কিছুই আল্লাহ তায়ালা দেখেন।', 'Wain tallaqtumoohunna min qabli an tamassoohunna waqad faradtum lahunna fareedatan fanisfu ma faradtum illa an yaAAfoona aw yaAAfuwa allathee biyadihi AAuqdatu alnnikahi waan taAAfoo aqrabu lilttaqwa wala tansawoo alfadla baynakum inna Allaha bima taAAmaloona baseerun', 1, NOW(), NOW()),
(2, 238, 'حَٰفِظُواْ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُواْ لِلَّهِ قَٰنِتِينَ', 'তোমরা নামাযসমূহের ওপর (একান্ত) যত্নবান হও, (বিশেষ করে) মধ্যবর্তী নামাযের ব্যাপারে– এবং তোমরা আল্লাহর জন্যে বিনীতভাবে দাঁড়িয়ে যেও।', 'Hafithoo AAala alssalawati waalssalati alwusta waqoomoo lillahi qaniteena', 1, NOW(), NOW()),
(2, 239, 'فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانٗاۖ فَإِذَآ أَمِنتُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ', 'অতপর যদি তোমরা ভীতিপ্রদ কোনো অবস্থার সম্মুখীন হও (তখন প্রয়োজনে) তোমরা নামায পড়বে)- পায়ের ওপর দাঁড়িয়ে কিংবা সওয়ারীর ওপর থাকা অবস্থায়, তারপর তোমরা যখন নিরাপদ হয়ে যাবে, তখন আল্লাহ তায়ালাকে স্মরণ করো, যেভাবে তিনি তোমাদের তাঁকে স্মরণ করার (নিয়ম) শিখিয়েছেন, যার কিছুই তোমরা (ইতিপূর্বে) জানতে না।', 'Fain khiftum farijalan aw rukbanan faitha amintum faothkuroo Allaha kama AAallamakum ma lam takoonoo taAAlamoona', 1, NOW(), NOW()),
(2, 240, 'وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجٗا وَصِيَّةٗ لِّأَزۡوَٰجِهِم مَّتَٰعًا إِلَى ٱلۡحَوۡلِ غَيۡرَ إِخۡرَاجٖۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِي مَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ مِن مَّعۡرُوفٖۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ', 'তোমাদের মধ্য থেকে যদি কেউ মৃত্যুমুখে পতিত হয় এবং সে (পেছনে নিজ) স্ত্রীদের রেখে যায়, (তার উত্তরসুরিদের জন্যে তার) ওসিয়ত থাকবে যেন তারা এক বছর পর্যন্ত তারা তাদের (স্ত্রীদের) ব্যয়ভার বহন করে, (কোনো অবস্থায় ভিটেমাটি থেকে তাদের যেন) বের করে না দেয়, (হাঁ) যদি তারা নিজেরাই বের হয়ে যায় এবং তারা নিজেদের ব্যাপারে কোনো ভিন্ন সিদ্ধান্ত করে কোনো সম্মানজনক ব্যবস্থা করে নেয়; তাহলে এ জন্যে তোমাদের ওপর কোনো দোষ পড়বে না; আল্লাহ তায়ালা পরাক্রমশালী, তিনি বিজ্ঞ কুশলীও!', 'Waallatheena yutawaffawna minkum wayatharoona azwajan wasiyyatan liazwajihim mataAAan ila alhawli ghayra ikhrajin fain kharajna fala junaha AAalaykum fee ma faAAalna fee anfusihinna min maAAroofin waAllahu AAazeezun hakeemun', 1, NOW(), NOW()),
(2, 241, 'وَلِلۡمُطَلَّقَٰتِ مَتَٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِينَ', 'তালাকপ্রাপ্তা মহিলাদের জন্যে ন্যায়সংগত ভরণ পোষণ পাবার অধিকার থাকবে; যারা তাকওয়া অবলম্বন করে এটা তাদের ওপর (স্ত্রীদের) অধিকার।', 'Walilmutallaqati mataAAun bialmaAAroofi haqqan AAala almuttaqeena', 1, NOW(), NOW()),
(2, 242, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', 'এভাবেই আল্লাহ তায়ালা তাঁর আয়াতগুলো তোমাদের জন্যে সুস্পষ্ট করে বলে দিচ্ছেন, আশা করা যায় তোমরা অনুধাবন করবে।', 'Kathalika yubayyinu Allahu lakum ayatihi laAAallakum taAAqiloona', 1, NOW(), NOW()),
(2, 243, '۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُواْ ثُمَّ أَحۡيَٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ', 'তুমি কি (তাদের পরিণতি) দেখোনি যারা মৃত্যুর ভয়ে নিজেদের ভিটেমাটি ছেড়ে বেরিয়ে এসেছিলো, অথচ তারা (সংখ্যায়) ছিলো হাজার হাজার, (এ কাপুরুষোচিত আচরণের জন্যে) আল্লাহ তায়ালা তাদের বললেন, তোমরা নিপাত হয়ে যাও। এরপর তিনি তাদের পুনরায় জীবন দান করলেন; আল্লাহ তায়ালা মানুষদের ওপর (সর্বদাই) অনুগ্রহশীল; কিন্তু মানুষদের অধিকাংশই (এ জন্যে আল্লাহর) কৃতজ্ঞতা আদায় করে না।', 'Alam tara ila allatheena kharajoo min diyarihim wahum oloofun hathara almawti faqala lahumu Allahu mootoo thumma ahyahum inna Allaha lathoo fadlin AAala alnnasi walakinna akthara alnnasi la yashkuroona', 1, NOW(), NOW()),
(2, 244, 'وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', 'তোমরা আল্লাহর পথে লড়াই করো এবং ভালো করে জেনে রাখো, আল্লাহ তায়ালা অবশ্যই (সবকিছু) শোনেন, তিনি (সব কিছু) জানেন।', 'Waqatiloo fee sabeeli Allahi waiAAlamoo anna Allaha sameeAAun AAaleemun', 1, NOW(), NOW()),
(2, 245, 'مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ', 'কে (এমন) আছে যে আল্লাহকে উত্তম ঋণ দেবে, (যে কেউই আল্লাহকে ঋণ দেবে সে যেন জেনে রাখে), আল্লাহ তায়ালা (ঋণের) সে (অংক)টি তার জন্যে বহুগুণ বাড়িয়ে দেবেন; আল্লাহ তায়ালা (কাউকে) ধনী (আবার কাউকে) গরীব করেন, (আর) তোমাদের (ধনী গরীব) সবাইকে তো একদিন তাঁর কাছেই ফিরিয়ে নেয়া হবে।', 'Man tha allathee yuqridu Allaha qardan hasanan fayudaAAifahu lahu adAAafan katheeratan waAllahu yaqbidu wayabsutu wailayhi turjaAAoona', 1, NOW(), NOW()),
(2, 246, 'أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ', 'তুমি কি মূসার পর বনী ইসরাঈল দলের কাছে (পাঠানো তাদের) কতিপয় নেতাকে দেখোনি? যখন তারা তাদের নবীর কাছে বলেছিলো, আমাদের জন্যে একজন বাদশাহ ঠিক করে দাও, যেন (তার সাথে মিলে) আমরা আল্লাহর পথে লড়াই করতে পারি; (আল্লাহর) সে (নবী তাদের) বললো, তোমাদের অবস্থা আগের লোকদের মতো এমন হবে না তো যে– আল্লাহ তায়ালা তোমাদের লড়াইর আদেশ দেবেন এবং তোমরা লড়াই করবে না, তারা বললো, আমরা কেন আল্লাহর পথে লড়বো না, (বিশেষ করে যখন) আমাদেরকে আমাদের বাড়ি ঘর থেকে বের করে দেয়া হয়েছে, আমাদের ছেলে মেয়েদের কাছ থেকে (আমাদের বিচ্ছিন্ন করে দেয়া হয়েছে), অতপর যখন (সত্যি সত্যিই) তাদের যুদ্ধের আদেশ দেয়া হলো, তখন তাদের মধ্য থেকে কতিপয় (সাহসী) বান্দা ছাড়া অধিকাংশই (সেদিন) ময়দান ছেড়ে পালিয়ে গেলো; আল্লাহ তায়ালা যালেমদের ভালো করেই জানেন।', 'Alam tara ila almalai min banee israeela min baAAdi moosa ith qaloo linabiyyin lahumu ibAAath lana malikan nuqatil fee sabeeli Allahi qala hal AAasaytum in kutiba AAalaykumu alqitalu alla tuqatiloo qaloo wama lana alla nuqatila fee sabeeli Allahi waqad okhrijna min diyarina waabnaina falamma kutiba AAalayhimu alqitalu tawallaw illa qaleelan minhum waAllahu AAaleemun bialththalimeena', 1, NOW(), NOW()),
(2, 247, 'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', 'তাদের নবী তাদের বললো, নিসন্দেহে আল্লাহ তায়ালা তালুতকে তোমাদের ওপর বাদশাহ (নিযুক্ত) করে পাঠিয়েছেন; (এ কথা শুনে) তারা বললো, তার কি অধিকার আছে আমাদের ওপর রাজত্ব করার? বাদশাহীর অধিকার (বরং) তার চাইতে আমাদেরই বেশী, (তাছাড়া) অর্থ প্রাচুর্যও তাকে কখনো বেশী দেয়া হয়নি; (আল্লাহর) নবী বললো, তোমাদের ওপর (বাদশাহ হিসেবে) আল্লাহ তায়ালা তাকে বাছাই করেছেন এবং (এ জন্যে) তার শারীরিক যোগ্যতা ও জ্ঞান (প্রতিভা) বাড়িয়ে দিয়েছেন; আল্লাহ তায়ালা যাকে চান তাকেই তাঁর রাজক্ষমতা দান করেন; আল্লাহ তায়ালা প্রাচুর্যময় ও মহাবিজ্ঞ।', 'Waqala lahum nabiyyuhum inna Allaha qad baAAatha lakum taloota malikan qaloo anna yakoonu lahu almulku AAalayna wanahnu ahaqqu bialmulki minhu walam yuta saAAatan mina almali qala inna Allaha istafahu AAalaykum wazadahu bastatan fee alAAilmi waaljismi waAllahu yutee mulkahu man yashao waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(2, 248, 'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ءَايَةَ مُلۡكِهِۦٓ أَن يَأۡتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٞ مِّن رَّبِّكُمۡ وَبَقِيَّةٞ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحۡمِلُهُ ٱلۡمَلَـٰٓئِكَةُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', 'তাদের নবী তাদের বললো, অবশ্যই তার বাদশাহীর কিছু চিহ্ন (থাকবে এবং তা) হচ্ছে, সে তোমাদের সামনে (বনী ইসরাঈলীদের হারানো) সিন্দুকটি এনে হাযির করবে, এতে তোমাদের জন্যে তোমাদের মালিক আল্লাহর পক্ষ থেকে প্রশান্তির বিষয় মজুদ থাকবে, (তাছাড়া) এ সিন্দুকে মূসা ও হারূনের পরিবার পরিজনের কিছু রেখে যাওয়া (জিনিসপত্রও) থাকবে, (আল্লাহ তায়ালার নির্দেশে তাঁর) ফেরেশতারা এ সিন্দুক তোমাদের জন্যে বহন করে আনবে, যদি তোমরা ঈমান আনো তাহলে (তোমরা দেখবে), এতে তোমাদের জন্যে (অনেক) নিদর্শন রয়েছে।', 'Waqala lahum nabiyyuhum inna ayata mulkihi an yatiyakumu alttabootu feehi sakeenatun min rabbikum wabaqiyyatun mimma taraka alu moosa waalu haroona tahmiluhu almalaikatu inna fee thalika laayatan lakum in kuntum mumineena', 1, NOW(), NOW()),
(2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِيكُم بِنَهَرٖ فَمَن شَرِبَ مِنۡهُ فَلَيۡسَ مِنِّي وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِيَدِهِۦۚ فَشَرِبُواْ مِنۡهُ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ قَالُواْ لَا طَاقَةَ لَنَا ٱلۡيَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ ٱللَّهِ كَم مِّن فِئَةٖ قَلِيلَةٍ غَلَبَتۡ فِئَةٗ كَثِيرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ', '(রাজত্ব পেয়ে) তালুত যখন নিজ বাহিনী নিয়ে এগিয়ে গেলো, তখন সে (তার লোকদের) বললো, আল্লাহ তায়ালা ঝর্ণা (-র পানি) দিয়ে তোমাদের পরীক্ষা করবেন, যদি তোমাদের মধ্যে কেউ এ থেকে কোনো পানি পান করে তাহলে সে আর আমার দলভুক্ত থাকবে না, আর যে ব্যক্তি তা খাবে না সে অবশ্যই আমার দলভুক্ত থাকবে, তবে কেউ যদি তার হাত দিয়ে সামান্য এক আঁজলা (পানি পান করে) নেয় তা ভিন্ন কথা, অতপর (সেখানে গিয়ে) হাতেগোনা কয়জন লোক ছাড়া আর সবাই তৃপ্তিভরে পানি পান করে নিলো; এ কয়জন লোক– যারা তার কথায় তার সাথে ঈমান এনেছিলো, তারা এবং তালুত যখন নদী পার হয়ে এগিয়ে গেলো, তখন তারা (নিজেদের দীনতা দেখে) বলে উঠলো, হে আল্লাহ, আজ জালুত এবং তার বিশাল বাহিনীর মোকাবেলা করার শক্তি আমাদের নেই; (তাদেরই সাথী বন্ধু) যারা জানতো তাদের আল্লাহর সামনে হাযির হতে হবে, তারা বললো, (ইতিহাসে এমন) অনেকবারই দেখা গেছে, আল্লাহর সাহায্য নিয়ে একটি ক্ষুদ্র দলও বিশাল বাহিনীর ওপর জয়ী হয়েছে; (কেননা) আল্লাহ তায়ালা ধৈর্যশীলদের সাথেই থাকেন।', 'Falamma fasala talootu bialjunoodi qala inna Allaha mubtaleekum binaharin faman shariba minhu falaysa minnee waman lam yatAAamhu fainnahu minnee illa mani ightarafa ghurfatan biyadihi fashariboo minhu illa qaleelan minhum falamma jawazahu huwa waallatheena amanoo maAAahu qaloo la taqata lana alyawma bijaloota wajunoodihi qala allatheena yathunnoona annahum mulaqoo Allahi kam min fiatin qaleelatin ghalabat fiatan katheeratan biithni Allahi waAllahu maAAa alssabireena', 1, NOW(), NOW()),
(2, 250, 'وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', 'তারপর (যখন) সে তার সৈন্য নিয়ে জালুতের (মোকাবেলা করার) জন্যে দাঁড়ালো, তখন তারা (আল্লাহর কাছে সাহায্য চেয়ে) বললো, হে আমাদের রব, তুমি আমাদের সবরের তাওফীক দান করো, দুশমনের মোকাবেলায় আমাদের কদমগুলোকে দৃঢ় রাখো এবং অবিশ্বাসী কাফেরদের মোকাবেলায় তুমি আমাদের সাহায্য করো;', 'Walamma barazoo lijaloota wajunoodihi qaloo rabbana afrigh AAalayna sabran wathabbit aqdamana waonsurna AAala alqawmi alkafireena', 1, NOW(), NOW()),
(2, 251, 'فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَٰلَمِينَ', 'অতপর তারা আল্লাহর ইচ্ছায় তাদের পর্যুদস্ত করে দিলো এবং দাউদ জালুতকে হত্যা করলো, আল্লাহ তায়ালা তাকে দুনিয়ার রাজত্ব দান করলেন এবং তাকে (রাজত্বের) কৌশল শিক্ষা দিলেন এবং তিনি তাকে নিজ ইচ্ছামতো আরো (বহু) বিষয়ের জ্ঞান দান করেন; (আসলে) আল্লাহ তায়ালা যদি (যুগে যুগে) একদল লোককে দিয়ে আরেকদল লোককে শায়েস্তা না করতেন, তাহলে এই ভূখন্ড ফেতনা ফাসাদে ভরে যেতো, কিন্তু আল্লাহ তায়ালা সৃষ্টিকুলের ওপর বড়োই অনুগ্রহশীল!', 'Fahazamoohum biithni Allahi waqatala dawoodu jaloota waatahu Allahu almulka waalhikmata waAAallamahu mimma yashao walawla dafAAu Allahi alnnasa baAAdahum bibaAAdin lafasadati alardu walakinna Allaha thoo fadlin AAala alAAalameena', 1, NOW(), NOW()),
(2, 252, 'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ', 'এসব ঘটনা আল্লাহর এক একটা নিদর্শন, যা যথাযথভাবে আমিই তোমাকে শুনিয়েছি; তুমি অবশ্যই আমার পাঠানো রসূলদের একজন!', 'Tilka ayatu Allahi natlooha AAalayka bialhaqqi wainnaka lamina almursaleena', 1, NOW(), NOW()),
(2, 253, '۞تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ', 'এই নবী রসূলদের কাউকে আমি কারো ওপর বেশী মর্যাদা দান করেছি। এদের মধ্যে (কেউ) এমনও ছিলো যার সাথে আল্লাহ তায়ালা কথা বলেছেন তাদের কারো মর্যাদা তিনি (অন্যভাবে) বাড়িয়ে দিয়েছেন; আমি মারইয়ামের ছেলে ঈসাকে (কতিপয়) উজ্জ্বল নিদর্শন দিয়েছিলাম, অতপর পবিত্র রূহের মাধ্যমে আমি তাকে সাহায্য করেছি; আল্লাহ তায়ালা চাইলে তাদের (আগমনের) পর যাদের কাছে এসব উজ্জ্বল নিদর্শন এসেছে, তারা কখনো মারামারিতে লিপ্ত হতো না, কিন্তু (রসূলদের পর) তারা (দলে, উপদলে) বিভক্ত হয়ে গেলো, অতপর তাদের মধ্যে কিছু লোক ঈমান আনলো আবার তাদের কিছু লোক কুফরী করলো, (অথচ) আল্লাহ তায়ালা চাইলে এরা কেউই যুদ্ধ বিগ্রহে লিপ্ত হতো না, কিন্তু আল্লাহ তায়ালা তাই করেন যা তিনি ইচ্ছা করেন।', 'Tilka alrrusulu faddalna baAAdahum AAala baAAdin minhum man kallama Allahu warafaAAa baAAdahum darajatin waatayna AAeesa ibna maryama albayyinati waayyadnahu biroohi alqudusi walaw shaa Allahu ma iqtatala allatheena min baAAdihim min baAAdi ma jaathumu albayyinatu walakini ikhtalafoo faminhum man amana waminhum man kafara walaw shaa Allahu ma iqtataloo walakinna Allaha yafAAalu ma yureedu', 1, NOW(), NOW()),
(2, 254, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ', 'হে ঈমানদাররা, তোমরা আমার দেয়া ধন সম্পদ থেকে (আমার পথে) ব্যয় করো– সে দিনটি আসার আগে, যেদিন কোনো রকম বেচাকেনা, বন্ধুত্ব ভালোবাসা থাকবে না– থাকবে না কোনো রকমের সুপারিশ; (মূলত) ) অস্বীকারকারীরাই হচ্ছে যালিম।', 'Ya ayyuha allatheena amanoo anfiqoo mimma razaqnakum min qabli an yatiya yawmun la bayAAun feehi wala khullatun wala shafaAAatun waalkafiroona humu alththalimoona', 1, NOW(), NOW()),
(2, 255, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ', 'মহান আল্লাহ তায়ালা, তিনি ছাড়া দ্বিতীয় কোনো ইলাহ নেই, তিনি চিরঞ্জীব, তিনি অনাদি, ঘুম (তো দূরের কথা, সামান্য) তন্দ্রা (-ও) তাঁকে আচ্ছন্ন করে না; আসমানসমূহ ও যমীনে যা কিছু আছে তার সব কিছুরই একচ্ছত্র মালিকানা তাঁর; কে এমন আছে যে তাঁর দরবারে বিনা অনুমতিতে সুপারিশ পেশ করবে? তাদের বর্তমান ভবিষ্যতের সব কিছুই তিনি জানেন, তাঁর জানা বিষয়সমূহের কোনো কিছুই (তাঁর সৃষ্টির) কারো জ্ঞানের সীমা-পরিসীমার আয়ত্তাধীন হতে পারে না, তবে তিনি যদি ভিন্ন কিছু চান (সেটা আলাদা), তাঁর বিশাল সাম্রাজ্য আসমান যমীনের সব কিছুই পরিবেষ্টন করে আছে, এ উভয়টির হেফাযত করার কাজটি কখনো তাঁকে পরিশ্রান্ত করে না, তিনি পরাক্রমশালী ও অসীম মর্যাদাবান।', 'Allahu la ilaha illa huwa alhayyu alqayyoomu la takhuthuhu sinatun wala nawmun lahu ma fee alssamawati wama fee alardi man tha allathee yashfaAAu AAindahu illa biithnihi yaAAlamu ma bayna aydeehim wama khalfahum wala yuheetoona bishayin min AAilmihi illa bima shaa wasiAAa kursiyyuhu alssamawati waalarda wala yaooduhu hifthuhuma wahuwa alAAaliyyu alAAatheemu', 1, NOW(), NOW()),
(2, 256, 'لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّـٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '(আল্লাহর) দ্বীনের ব্যাপারে কোনো জোর জবরদস্তি নেই, (কেননা) সত্য (এখানে) মিথ্যা থেকে পরিষ্কার হয়ে গেছে, অতপর কোনো ব্যক্তি যদি বাতিল (মতাদর্শ)-কে অস্বীকার করে এবং আল্লাহর (দেয়া জীবনাদর্শের) ওপর ঈমান আনে, সে যেন এর মাধ্যমে এমন এক শক্তিশালী রশি ধরলো, যা কোনোদিনই ছিঁড়ে যাবার নয়; আল্লাহ তায়ালা (সব) শোনেন (এবং সব) জানেন।', 'La ikraha fee alddeeni qad tabayyana alrrushdu mina alghayyi faman yakfur bialttaghooti wayumin biAllahi faqadi istamsaka bialAAurwati alwuthqa la infisama laha waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(2, 257, 'ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّـٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'যারা (আল্লাহর ওপর) ঈমান আনে, আল্লাহ তায়ালাই হচ্ছেন তাদের সাহায্যকারী (বন্ধু), তিনি তাদের (জাহেলিয়াতের) অন্ধকারসমূহ থেকে (ঈমানের) আলোতে বের করে আনেন, (অপরদিকে) যারা (আল্লাহকে) অস্বীকার করে, বাতিল (শক্তিসমূহ)-ই হয় তাদের সাহায্যকারী, তারা তাদের (দ্বীনের) আলো থেকে (কুফরীর) অন্ধকারের দিকে নিয়ে যায়; এরাই হচ্ছে জাহান্নামের অধিবাসী, সেখানে তারা চিরদিন থাকবে।', 'Allahu waliyyu allatheena amanoo yukhrijuhum mina alththulumati ila alnnoori waallatheena kafaroo awliyaohumu alttaghootu yukhrijoonahum mina alnnoori ila alththulumati olaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(2, 258, 'أَلَمۡ تَرَ إِلَى ٱلَّذِي حَآجَّ إِبۡرَٰهِـۧمَ فِي رَبِّهِۦٓ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّيَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحۡيِۦ وَأُمِيتُۖ قَالَ إِبۡرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأۡتِي بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِي كَفَرَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'তুমি কি সে ব্যক্তির অবস্থা দেখোনি যে ব্যক্তিকে আল্লাহ তায়ালা (দুনিয়ায়) রাষ্ট্র ক্ষমতা দেয়ার পর সে ইবরাহীমের সাথে স্বয়ং মালিকের ব্যাপারেই বিতর্কে লিপ্ত হলো, (বিতর্কের এক পর্যায়ে) ইবরাহীম বললো, আমার রব, যিনি (সৃষ্টিকুলকে) জীবন দান করেন, মৃত্যু দান করেন, সে (দাম্ভিক শাসক) বললো, জীবন মৃত্যু তো আমিও দেই, ইবরাহীম বললো, অবশ্যই আল্লাহ তায়ালা পূর্ব দিক থেকে (প্রতিদিন) সূর্যের উদয়ন ঘটান, (একবার) তুমি তা পশ্চিম দিক থেকে বের করে দেখাও তো! (এতে সত্য) অস্বীকারকারী ব্যক্তিটি হতভম্ব হয়ে গেলো, (আসলে) আল্লাহ তায়ালা যালেম জাতিকে কখনো পথের দিশা দেন না।', 'Alam tara ila allathee hajja ibraheema fee rabbihi an atahu Allahu almulka ith qala ibraheemu rabbiya allathee yuhyee wayumeetu qala ana ohyee waomeetu qala ibraheemu fainna Allaha yatee bialshshamsi mina almashriqi fati biha mina almaghribi fabuhita allathee kafara waAllahu la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(2, 259, 'أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'অথবা (ঘটনাটি) কি সে ব্যক্তির মতো– যে একটি বস্তির পাশ দিয়ে গেলো, (সে দেখলো) তা আপন অস্তিত্বের ওপর (বিধ্বস্ত হয়ে) মুখ থুবড়ে পড়ে আছে, (তখন) সে ব্যক্তি বললো, এ (মৃত জনপদ)-কে কিভাবে আল্লাহ তায়ালা আবার পুনর্জীবন দান করবেন, অতপর আল্লাহ তায়ালা (সত্যি সত্যিই) তাকে মৃত্যু দান করলেন এবং (এভাবেই তাকে) একশ বছর মৃত (ফেলে) রাখলেন, এরপর তাকে পুনরায় জীবিত করলেন; এবার জিজ্ঞেস করলেন, (বলতে পারো) তুমি কতোকাল (মৃত অবস্থায়) কাটিয়েছো? সে বললো, একদিন কিংবা একদিনের কিছু অংশ আমি (মৃত অবস্থায়) কাটিয়েছি, আল্লাহ তায়ালা বললেন; বরং এমনি অবস্থায় তুমি একশ বছর কাটিয়ে দিয়েছো, তাকিয়ে দেখো তোমার নিজস্ব খাবার ও পানীয়ের দিকে, (দেখবে) তা বিন্দুমাত্রও পচেনি, তোমার গাধাটির দিকেও দেখো, (তাও একই অবস্থায় আছে, আমি এসব এ জন্যেই দেখালাম), যেন আমি তোমাকে মানুষদের জন্যে (পরকালীন জীবনের) একটি (জীবন্ত) প্রমাণ হিসেবে উপস্থাপন করতে পারি, এ (মৃত জীবের) হাড় পাঁজরগুলোর দিকে তাকিয়ে দেখো, আমি কিভাবে তা একটার সাথে আরেকটার জোড়া লাগিয়ে (নতুন জীবন) দিয়েছি, অতপর কিভাবে তাকে আমি গোশতের পোশাক পরিয়ে দিয়েছি, এ বিষয়টি যখন তার কাছে পরিষ্কার হয়ে গেলো তখন সে বলে উঠলো, আমি জানি, অবশ্যই আল্লাহ তায়ালা সব কিছুর ওপর ক্ষমতাবান।', 'Aw kaallathee marra AAala qaryatin wahiya khawiyatun AAala AAurooshiha qala anna yuhyee hathihi Allahu baAAda mawtiha faamatahu Allahu miata AAamin thumma baAAathahu qala kam labithta qala labithtu yawman aw baAAda yawmin qala bal labithta miata AAamin faonthur ila taAAamika washarabika lam yatasannah waonthur ila himarika walinajAAalaka ayatan lilnnasi waonthur ila alAAithami kayfa nunshizuha thumma naksooha lahman falamma tabayyana lahu qala aAAlamu anna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 260, 'وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ أَرِنِي كَيۡفَ تُحۡيِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطۡمَئِنَّ قَلۡبِيۖ قَالَ فَخُذۡ أَرۡبَعَةٗ مِّنَ ٱلطَّيۡرِ فَصُرۡهُنَّ إِلَيۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلٖ مِّنۡهُنَّ جُزۡءٗا ثُمَّ ٱدۡعُهُنَّ يَأۡتِينَكَ سَعۡيٗاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', '(স্মরণ করো,) যখন ইবরাহীম বললো, হে রব, মৃতকে তুমি কিভাবে (পুনরায়) জীবন দাও তা আমাকে একটু দেখিয়ে দাও; আল্লাহ তায়ালা বললেন, কেন– তুমি কি (না দেখে) বিশ্বাস করো না? ইবরাহীম বললো, হাঁ (প্রভু, আমি বিশ্বাস করি), কিন্তু (এর দ্বারা) আমার মন একটু সান্ত্বনা পাবে (এই যা)। আল্লাহ তায়ালা বললেন তুমি (বরং) চারটি পাখী ধরে আনো, অতপর (আস্তে আস্তে) এ পাখীগুলোকে তোমার কাছে পোষ মানিয়ে নাও (যাতে ওরা তোমার কাছে পরিচিত হয়ে যায়), তারপর (তাদের কয়েক টুকরায় ভাগ করে,) তাদের (কাটা) এক একটি টুকরো এক একটি পাহাড়ের ওপর রেখে এসো, অতপর তুমি ওদের (সবার নাম ধরে) ডাকো, (দেখবে জীবন্ত পাখীতে পরিণত হয়ে) ওরা তোমার কাছে দৌড়ে আসবে; তুমি জেনে রাখো, আল্লাহ তায়ালা মহাশক্তিশালী, বিজ্ঞ কুশলী।', 'Waith qala ibraheemu rabbi arinee kayfa tuhyee almawta qala awalam tumin qala bala walakin liyatmainna qalbee qala fakhuth arbaAAatan mina alttayri fasurhunna ilayka thumma ijAAal AAala kulli jabalin minhunna juzan thumma odAAuhunna yateenaka saAAyan waiAAlam anna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(2, 261, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'যারা নিজেদের ধন সম্পদ আল্লাহ তায়ালার পথে খরচ করে, তাদের উদাহরণ হচ্ছে একটি বীজের মতো, যে বীজটি বপন করার পর তা থেকে সাতটি শীষ বেরুলো, এর প্রতিটি শীষে রয়েছে একশ করে শস্য দানা; আল্লাহ তায়ালা যাকে চান তার জন্যে (এটাকে) বহুগুণ বৃদ্ধি করে দেন; আল্লাহ তায়ালা অনেক প্রশস্ত, অনেক বিজ্ঞ।', 'Mathalu allatheena yunfiqoona amwalahum fee sabeeli Allahi kamathali habbatin anbatat sabAAa sanabila fee kulli sunbulatin miatu habbatin waAllahu yudaAAifu liman yashao waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(2, 262, 'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'যারা আল্লাহ তায়ালার পথে নিজেদের ধন সম্পদ ব্যয় করে এবং যা কিছু ব্যয় করে তা প্রচার করে বেড়ায় না, প্রতিদান চেয়ে (কাউকে) কষ্ট দেয় না, তাদের মালিকের কাছে তাদের জন্যে পুরস্কার (সংরক্ষিত) রয়েছে, (শেষ বিচারের দিন) এদের কোনো ভয় নেই, তারা (সেদিন) দুশ্চিন্তাগ্রস্তও হবে না।', 'Allatheena yunfiqoona amwalahum fee sabeeli Allahi thumma la yutbiAAoona ma anfaqoo mannan wala athan lahum ajruhum AAinda rabbihim wala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 263, '۞قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ', 'সুন্দর কথা বলা এবং ক্ষমা করে দেয়া সেই দানের চাইতে অনেক ভালো, যে দানের পরিণামে কষ্টই আসে; আল্লাহ তায়ালা কারোই মুখাপেক্ষী নন, তিনি পরম ধৈর্যশীল।', 'Qawlun maAAroofun wamaghfiratun khayrun min sadaqatin yatbaAAuha athan waAllahu ghaniyyun haleemun', 1, NOW(), NOW()),
(2, 264, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', 'হে ঈমানদাররা, তোমরা খোঁটা দিয়ে এবং (অনুগৃহীত ব্যক্তিকে) কষ্ট দিয়ে তোমাদের দান সদকা বরবাদ করে দিয়ো না– ঠিক সেই (হতভাগ্য) ব্যক্তির মতো, যে শুধু লোক দেখানোর উদ্দেশেই দান করে, সে আল্লাহ তায়ালা ও পরকালে (কিছু পাওয়ার ওপর) বিশ্বাস করে না; তার (দানের) উদাহরণ হচ্ছে, যেন একটি মসৃণ শিলাখণ্ডের ওপর কিছু মাটি, সেখানে মুষলধারে বৃষ্টিপাত হলো, অতপর পাথর শক্ত হয়েই পড়ে থাকলো; (দান খয়রাত করে) তারা যা কিছু অর্জন করলো তার থেকে তারা কিছুই (সংগ্রহ) করতে পারলো না, আর যারা (আল্লাহকে) বিশ্বাস করে না, আল্লাহ তায়ালা তাদের কখনো সঠিক পথ দেখান না।', 'Ya ayyuha allatheena amanoo la tubtiloo sadaqatikum bialmanni waalatha kaallathee yunfiqu malahu riaa alnnasi wala yuminu biAllahi waalyawmi alakhiri famathaluhu kamathali safwanin AAalayhi turabun faasabahu wabilun fatarakahu saldan la yaqdiroona AAala shayin mimma kasaboo waAllahu la yahdee alqawma alkafireena', 1, NOW(), NOW()),
(2, 265, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ', '(অপরদিকে) যারা আল্লাহ তায়ালার সন্তুষ্টি এবং নিজে দের মানসিক অবস্থাকে (আল্লাহর পথে) সুদৃঢ় রাখার জন্যে নিজেদের ধন সম্পদ ব্যয় করে, তাদের উদাহরণ হচ্ছে, যেন তা কোনো উঁচু পাহাড়ের উপত্যকায় একটি (সজ্জিত) ফসলের বাগান, যদি সেখানে প্রবল বৃষ্টিপাত হয় তাহলে ফসলের পরিমাণ দ্বিগুণ বৃদ্ধি পায়, আর তা না হলেও শিশির বিন্দুগুলোই (ফসলের জন্য) যথেষ্ট হয়, আল্লাহ তায়ালা ভালো করেই পর্যবেক্ষণ করেন তোমরা কে কী কাজ করো।', 'Wamathalu allatheena yunfiqoona amwalahumu ibtighaa mardati Allahi watathbeetan min anfusihim kamathali jannatin birabwatin asabaha wabilun faatat okulaha diAAfayni fain lam yusibha wabilun fatallun waAllahu bima taAAmaloona baseerun', 1, NOW(), NOW()),
(2, 266, 'أَيَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةٞ مِّن نَّخِيلٖ وَأَعۡنَابٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّيَّةٞ ضُعَفَآءُ فَأَصَابَهَآ إِعۡصَارٞ فِيهِ نَارٞ فَٱحۡتَرَقَتۡۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ', 'তোমাদের কেউ কি চাইবে যে, তার কাছে (সুন্দর) একটি বাগান থাকুক, যাতে খেজুর ও আংগুর থাকবে, তার তলদেশ দিয়ে আবার প্রবাহমান থাকবে কতিপয় ঝর্ণাধারা, সেখানে আরো থাকবে সব ধরনের ফলমূল, আর (এগুলো ভোগ করার আগেই) বাগানের মালিক বয়সের ভারে নুয়ে পড়বে এবং তার কিছু দুর্বল সন্তান থাকবে, (এ অবস্থায় হঠাৎ করে) আগুনের এক ঘূর্ণিবায়ু এসে তার সব (স্বপ্ন) জ্বালিয়ে দিয়ে যাবে; এভাবেই আল্লাহ তায়ালা তাঁর নিদর্শনগুলো তোমাদের জন্যে সুস্পষ্টভাবে বর্ণনা করেন, যাতে তোমরা (এসব বিষয় নিয়ে) চিন্তা গবেষণা করতে পারো।', 'Ayawaddu ahadukum an takoona lahu jannatun min nakheelin waaAAnabin tajree min tahtiha alanharu lahu feeha min kulli alththamarati waasabahu alkibaru walahu thurriyyatun duAAafao faasabaha iAAsarun feehi narun faihtaraqat kathalika yubayyinu Allahu lakumu alayati laAAallakum tatafakkaroona', 1, NOW(), NOW()),
(2, 267, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ', 'হে ঈমানদার লোকেরা, তোমরা নিজেরা যা অর্জন করেছো, সে পবিত্র (সম্পদ) এবং যা আমি যমীনের ভেতর থেকে তোমাদের জন্যে বের করে এনেছি, তা (আল্লাহর পথে) ব্যয় করো, (আল্লাহর জন্যে এমন) খারাপ জিনিসগুলো বেছে তার থেকে ব্যয় করো না, যা অন্যরা তোমাদের দিলে তোমরা তা গ্রহণ করবে না, অবশ্য যা কিছু তোমরা অনিচ্ছাকৃতভাবে গ্রহণ করো তা আলাদা, জেনে রেখো, আল্লাহ তায়ালা (কোনো কিছুরই) মুখাপেক্ষী নন, সব প্রশংসার মালিক তো তিনিই!', 'Ya ayyuha allatheena amanoo anfiqoo min tayyibati ma kasabtum wamimma akhrajna lakum mina alardi wala tayammamoo alkhabeetha minhu tunfiqoona walastum biakhitheehi illa an tughmidoo feehi waiAAlamoo anna Allaha ghaniyyun hameedun', 1, NOW(), NOW()),
(2, 268, 'ٱلشَّيۡطَٰنُ يَعِدُكُمُ ٱلۡفَقۡرَ وَيَأۡمُرُكُم بِٱلۡفَحۡشَآءِۖ وَٱللَّهُ يَعِدُكُم مَّغۡفِرَةٗ مِّنۡهُ وَفَضۡلٗاۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', '(আল্লাহর পথে দান করার সময়) শয়তান তোমাদের অভাব অনটনের ভয় দেখাবে এবং (নানাবিধ) অশ্লীল কর্মকান্ডের আদেশ দেবে, আর আল্লাহ তায়ালা তোমাদের তাঁর কাছ থেকে অসীম বরকত ও ক্ষমার প্রতিশ্রুতি দিচ্ছেন, আল্লাহ তায়ালা প্রাচুর্যময় ও সম্যক অবগত।', 'Alshshaytanu yaAAidukumu alfaqra wayamurukum bialfahshai waAllahu yaAAidukum maghfiratan minhu wafadlan waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(2, 269, 'يُؤۡتِي ٱلۡحِكۡمَةَ مَن يَشَآءُۚ وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ', 'আল্লাহ তায়ালা যাকে চান তাকে জ্ঞান কৌশল দান করেন, আর যে ব্যক্তিকে (আল্লাহ তায়ালার) জ্ঞান কৌশল দেয়া হয়েছে (সে যেন মনে করে), তাকে (সত্যিকার অর্থেই) প্রচুর কল্যাণ দান করা হয়েছে, আর প্রজ্ঞাসম্পন্ন ব্যক্তি ছাড়া (এ থেকে) অন্য কেউই শিক্ষা গ্রহণ করে না।', 'Yutee alhikmata man yashao waman yuta alhikmata faqad ootiya khayran katheeran wama yaththakkaru illa oloo alalbabi', 1, NOW(), NOW()),
(2, 270, 'وَمَآ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرٖ فَإِنَّ ٱللَّهَ يَعۡلَمُهُۥۗ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٍ', 'তোমরা যা কিছু খরচ করো, আর যা কিছু (খরচ করার) মানত করো, আল্লাহ তায়ালা অবশ্যই তা জানেন; যালেমদের কোনোই সাহায্যকারী নেই।', 'Wama anfaqtum min nafaqatin aw nathartum min nathrin fainna Allaha yaAAlamuhu wama lilththalimeena min ansarin', 1, NOW(), NOW()),
(2, 271, 'إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', 'তোমরা যদি (তোমাদের) দানকে প্রকাশ করো– ভালো কথা (তাতে কোনো দোষ নেই), তবে যদি তোমরা তা গোপন রাখো এবং (চুপে চুপেই) তা অসহায়দের দিয়ে দাও, তা হবে তোমাদের জন্যে বেশী উত্তম; (এ দানের কারণে) আল্লাহ তায়ালা তোমাদের বহুবিধ গুনাহ খাতা মুছে দেবেন, আর তোমরা যাই করো না কেন, আল্লাহ তায়ালা সে সম্পর্কে অবগত রয়েছেন।', 'In tubdoo alssadaqati faniAAimma hiya wain tukhfooha watutooha alfuqaraa fahuwa khayrun lakum wayukaffiru AAankum min sayyiatikum waAllahu bima taAAmaloona khabeerun', 1, NOW(), NOW()),
(2, 272, '۞لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَآءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ', '(যারা তোমার কথা শোনে না,) তাদের হেদায়াতের দায়িত্ব তোমার ওপর নয়, তবে আল্লাহ তায়ালা যাকে চান তাকে অবশ্যই সঠিক পথ দেখান, তোমরা যা দান সদকা করো (তা) তোমাদের জন্যেই (কল্যাণকর, কারণ) তোমরা তো আল্লাহর সন্তুষ্টি অর্জনের জন্যেই খরচ করো; (তোমরা আজ) যা কিছু দান করবে (আগামীকাল) তার পুরোপুরি বিনিময় তোমাদের আদায় করে দেয়া হবে, (সেদিন) তোমাদের ওপর কোনো রকম যুলুম করা হবে না।', 'Laysa AAalayka hudahum walakinna Allaha yahdee man yashao wama tunfiqoo min khayrin falianfusikum wama tunfiqoona illa ibtighaa wajhi Allahi wama tunfiqoo min khayrin yuwaffa ilaykum waantum la tuthlamoona', 1, NOW(), NOW()),
(2, 273, 'لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '(দান সদকা তো এমন) কিছু গরীবদের জন্যে, যাদের আল্লাহর পথে এমনভাবে ব্যাপৃত করে রাখা হয়েছে যে, তারা (নিজেদের রিজিকের জন্যে) যমীনের বুকে চেষ্টা সাধনা করতে পারে না, আত্মসম্মানবোধের কারণে এরা কিছু চায় না বলে অজ্ঞ (মূর্খ) লোক এদের মনে করে এরা (বুঝি আসলেই) সচ্ছল, কিন্তু এদের (বাহ্যিক) চেহারা দেখেই তুমি এদের (সঠিক অবস্থা) বুঝে নিতে পারো, এরা মানুষদের কাছ থেকে কাকুতি মিনতি করে ভিক্ষা করতে পারে না; তোমরা যা কিছুই খরচ করবে আল্লাহ তায়ালা তার (যথার্থ) বিনিময় দেবেন, অবশ্যই তিনি সব কিছু জানেন।', 'Lilfuqarai allatheena ohsiroo fee sabeeli Allahi la yastateeAAoona darban fee alardi yahsabuhumu aljahilu aghniyaa mina alttaAAaffufi taAArifuhum biseemahum la yasaloona alnnasa ilhafan wama tunfiqoo min khayrin fainna Allaha bihi AAaleemun', 1, NOW(), NOW()),
(2, 274, 'ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'যারা দিন রাত গোপনে প্রকাশ্যে নিজেদের মাল সম্পদ ব্যয় করে, তাদের মালিকের দরবারে তাদের এ দানের প্রতিফল (সুরক্ষিত) রয়েছে, তাদের ওপর কোনো রকম ভয় ভীতি থাকবে না, তারা (সেদিন) চিন্তিতও হবে না।', 'Allatheena yunfiqoona amwalahum biallayli waalnnahari sirran waAAalaniyatan falahum ajruhum AAinda rabbihim wala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 275, 'ٱلَّذِينَ يَأۡكُلُونَ ٱلرِّبَوٰاْ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِي يَتَخَبَّطُهُ ٱلشَّيۡطَٰنُ مِنَ ٱلۡمَسِّۚ ذَٰلِكَ بِأَنَّهُمۡ قَالُوٓاْ إِنَّمَا ٱلۡبَيۡعُ مِثۡلُ ٱلرِّبَوٰاْۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَيۡعَ وَحَرَّمَ ٱلرِّبَوٰاْۚ فَمَن جَآءَهُۥ مَوۡعِظَةٞ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥٓ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'যারা সুদ খায় তারা (মাথা উঁচু করে) দাঁড়াতে পারবে না, (দাঁড়ালেও) তার দাঁড়ানো হবে সে ব্যক্তির মতো, যাকে শয়তান নিজস্ব পরশ দিয়ে (দুনিয়ার লোভ লালসায়) মোহাচ্ছন্ন করে রেখেছে; এটা এ জন্যে যে, এরা বলে, ব্যবসা বাণিজ্য তো সুদের মতোই (একটা কারবারের নাম, অথচ) আল্লাহ তায়ালা ব্যবসা হালাল করেছেন এবং সুদকে হারাম করেছেন, তাই তোমাদের যার (যার) কাছে তার মালিকের পক্ষ থেকে (সুদ সংক্রান্ত) এ উপদেশ পৌঁছেছে, সে সুদের কারবার থেকে বিরত থাকবে, আগে (এ আদেশ আসা পর্যন্ত) যা হয়েছে তা তো তার জন্যে (অতিবাহিত হয়েই গেছে), সে বিষয়টি আল্লাহ তায়ালার সিদ্ধান্তের ওপর; কিন্তু যে ব্যক্তি (এই আদেশের পরও আবার সূদী কারবারে) ফিরে আসবে, তারা অবশ্যই জাহান্নামের অধিবাসী হবে, সেখানে তারা চিরদিন থাকবে।', 'Allatheena yakuloona alrriba la yaqoomoona illa kama yaqoomu allathee yatakhabbatuhu alshshaytanu mina almassi thalika biannahum qaloo innama albayAAu mithlu alrriba waahalla Allahu albayAAa waharrama alrriba faman jaahu mawAAithatun min rabbihi faintaha falahu ma salafa waamruhu ila Allahi waman AAada faolaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(2, 276, 'يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', 'আল্লাহ তায়ালা সুদ নিশ্চিহ্ন করেন, আর দান সদকাকে তিনি (উত্তরোত্তর) বৃদ্ধি করেন; আল্লাহ তায়ালা (তাঁর নেয়ামতের) অকৃতজ্ঞ পাপিষ্ঠ ব্যক্তিদের কখনো পছন্দ করেন না।', 'Yamhaqu Allahu alrriba wayurbee alssadaqati waAllahu la yuhibbu kulla kaffarin atheemin', 1, NOW(), NOW()),
(2, 277, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'অবশ্যই যারা (আল্লাহ তায়ালার ওপর) ঈমান এনেছে এবং নেক কাজ করেছে, নামায প্রতিষ্ঠা করেছে, যাকাত আদায় করেছে, তাদের জন্যে তাদের মালিকের কাছে যথার্থ প্রতিদান রয়েছে, তাদের ওপর কোনো ভয় থাকবে না, তারা (সেদিন) চিন্তিতও হবে না।', 'Inna allatheena amanoo waAAamiloo alssalihati waaqamoo alssalata waatawoo alzzakata lahum ajruhum AAinda rabbihim wala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(2, 278, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَذَرُواْ مَا بَقِيَ مِنَ ٱلرِّبَوٰٓاْ إِن كُنتُم مُّؤۡمِنِينَ', 'হে ঈমানদার লোকেরা, তোমরা (সুদের ব্যাপারে) আল্লাহকে ভয় করো, (তোমাদের কাছে) আগের সুদী (কারবারের) যে সব বকেয়া আছে তোমরা তা ছেড়ে দাও, যদি সত্যিই তোমরা ঈমানদার হও।', 'Ya ayyuha allatheena amanoo ittaqoo Allaha watharoo ma baqiya mina alrriba in kuntum mumineena', 1, NOW(), NOW()),
(2, 279, 'فَإِن لَّمۡ تَفۡعَلُواْ فَأۡذَنُواْ بِحَرۡبٖ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ', 'আর যদি তোমরা এমনটি না করো, তাহলে আল্লাহ তায়ালা ও তাঁর রসূলের পক্ষ থেকে (তোমাদের বিরুদ্ধে) যুদ্ধের (ঘোষণা থাকবে), যদি তোমরা (আল্লাহর দিকে) ফিরে আসো তাহলে তোমরা তোমাদের মূলধন ফিরে পাবার অধিকারী হবে, তোমরা অন্যের ওপর যুলুম করো না, তোমাদের ওপরও অতপর কোনো যুলুম করা হবে না।', 'Fain lam tafAAaloo fathanoo biharbin mina Allahi warasoolihi wain tubtum falakum ruoosu amwalikum la tathlimoona wala tuthlamoona', 1, NOW(), NOW()),
(2, 280, 'وَإِن كَانَ ذُو عُسۡرَةٖ فَنَظِرَةٌ إِلَىٰ مَيۡسَرَةٖۚ وَأَن تَصَدَّقُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', 'সে (ঋণগ্রহীতা) ব্যক্তিটি কখনো যদি অভাবগ্রস্ত হয়ে পড়ে তাহলে (তার ওপর চাপ দিয়ো না, বরং) তার সচ্ছলতা ফিরে আসা পর্যন্ত তাকে অবকাশ দাও; আর যদি তা মাফ করে দাও, তাহলে তা হবে তোমাদের জন্যে উত্তম কাজ— যদি তোমরা জানো!', 'Wain kana thoo AAusratin fanathiratun ila maysaratin waan tasaddaqoo khayrun lakum in kuntum taAAlamoona', 1, NOW(), NOW()),
(2, 281, 'وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', 'সে দিনটিকে ভয় করো, যেদিন তোমাদের সবাইকে আল্লাহর দিকে ফিরিয়ে নেয়া হবে, অতপর সেদিন প্রত্যেকটি মানুষকে (তার) কর্মের ফলাফল দিয়ে দেওয়া হবে, তাদের ওপর কোনো ধরনের যুলুম করা হবে না।', 'Waittaqoo yawman turjaAAoona feehi ila Allahi thumma tuwaffa kullu nafsin ma kasabat wahum la yuthlamoona', 1, NOW(), NOW()),
(2, 282, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'হে ঈমানদার লোকেরা, তোমরা যখন পরস্পরের সাথে নির্দিষ্ট সময়ের জন্যে ঋণের চুক্তি করো, তখন তা লিখে রাখো; তোমাদের মধ্যকার যে কোনো একজন লেখক সুবিচারের ভিত্তিতে (এ চুক্তিনামা) লিখে দেবে, যাকে আল্লাহ তায়ালা লেখা শিখিয়েছেন সে যেন কখনো লিখতে অস্বীকৃতি না জানায়, সুতরাং সে যেন লেখে, (লেখার সময়) ঋণগ্রহীতা (লেখককে) বলে দেবে কি (কি শর্ত সেখানে) লিখতে হবে, তাকে অবশ্যই তার রবকে ভয় করা উচিত, (চুক্তিনামা লেখার সময় লক্ষ্য রাখতে হবে) তার কিছুই যেন বাদ না পড়ে; যদি সে ঋণ গ্রহীতা অজ্ঞ মূর্খ এবং (সামাজিক দিক থেকে) দুর্বল হয়, অথবা (চুক্তিনামার শর্ত বলে দেয়ার) ক্ষমতাই তার না থাকে, তাহলে তার পক্ষ থেকে তার কোনো অভিভাবক ন্যায়ানুগ পন্থায় বলে দেবে– কি কি কথা (চুক্তিতে) লিখতে হবে; (তদুপরি) তোমাদের মধ্য থেকে দুই জন পুরুষকে (এ চুক্তিপত্রে) সাক্ষী বানিয়ে নিয়ো, যদি দুই জন পুরুষ (একত্রে) না থাকে তাহলে একজন পুরুষ এবং দুজন মহিলা (সাক্ষী হবে), যাতে করে তাদের একজন ভুলে গেলে দ্বিতীয় জন তাকে স্মরণ করিয়ে দিতে পারে; এমন সব লোকদের মধ্য থেকে সাক্ষী নিতে হবে যাদের উভয় পক্ষই পছন্দ করবে, (সাক্ষীদের) যখন (সাক্ষ্য প্রদানের জন্যে) ডাকা হবে তখন তারা তা অস্বীকার করবে না; (লেনদেনের) পরিমাণ ছোট হোক কিংবা বড়ো হোক, তার দিনক্ষণসহ (লিখে রাখতে) অবহেলা করো না; এটা আল্লাহর কাছে ন্যায্যতর ও সাক্ষ্যদানের ক্ষেত্রে অধিক মযবুত (ভিত্তির ওপর প্রতিষ্ঠিত) এবং (পরবর্তীকালে) যাতে তোমরা সন্দিগ্ধ না হও তার সমাধানের জন্যেও এটা নিকটতর (পন্থা), তবে যা কিছু তোমরা নগদ আদান প্রদান করো তা না লেখলেও তোমাদের কোনো ক্ষতি নেই, ব্যবসায়িক লেনদেনের সময় অবশ্যই সাক্ষী রাখবে, (দলিলের) লেখক ও (তার) সাক্ষীদের কখনো (তাদের মত বদলানোর জন্যে) কষ্ট দেয়া যাবে না; তোমরা যদি তা করো তাহলে (জেনে রেখো), তা হবে একটি মারাত্মক গুনাহ, তোমরা তাকওয়া অবলম্বন করো, আল্লাহ তায়ালা তো তোমাদের (সবকিছুই) শিখিয়ে দিচ্ছেন, আল্লাহ তায়ালা (সকল বিষয়) জানেন।', 'Ya ayyuha allatheena amanoo itha tadayantum bidaynin ila ajalin musamman faoktuboohu walyaktub baynakum katibun bialAAadli wala yaba katibun an yaktuba kama AAallamahu Allahu falyaktub walyumlili allathee AAalayhi alhaqqu walyattaqi Allaha rabbahu wala yabkhas minhu shayan fain kana allathee AAalayhi alhaqqu safeehan aw daAAeefan aw la yastateeAAu an yumilla huwa falyumlil waliyyuhu bialAAadli waistashhidoo shaheedayni min rijalikum fain lam yakoona rajulayni farajulun waimraatani mimman tardawna mina alshshuhadai an tadilla ihdahuma fatuthakkira ihdahuma alokhra wala yaba alshshuhadao itha ma duAAoo wala tasamoo an taktuboohu sagheeran aw kabeeran ila ajalihi thalikum aqsatu AAinda Allahi waaqwamu lilshshahadati waadna alla tartaboo illa an takoona tijaratan hadiratan tudeeroonaha baynakum falaysa AAalaykum junahun alla taktubooha waashhidoo itha tabayaAAtum wala yudarra katibun wala shaheedun wain tafAAaloo fainnahu fusooqun bikum waittaqoo Allaha wayuAAallimukumu Allahu waAllahu bikulli shayin AAaleemun', 1, NOW(), NOW()),
(2, 283, '۞وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ', 'যদি তোমরা কখনো সফরে থাকো এবং (চুক্তিনামা লেখার মতো) কোনো লেখক না পাও, তাহলে কোনো জিনিস বন্ধক রেখে তা (ঋণদাতার দখলে দিয়ে) দাও, যখন তোমাদের কোনো ব্যক্তি অপর ব্যক্তিকে কোনো বন্ধকী জিনিসের ব্যাপারে বিশ্বাস করে, এমতাবস্থায় যে ব্যক্তিকে বিশ্বাস করা হয়েছে তার উচিত সেই আমানত যথাযথ ফেরত দেয়া এবং (আমানতের ব্যাপারে) আল্লাহ তায়ালাকে ভয় করা, যিনি তার মালিক। তোমরা কখনো সাক্ষ্য গোপন করো না, যে ব্যক্তি তা গোপন করে সে অবশ্যই অন্তরের দিক থেকে পাপিষ্ঠ; বস্তুত আল্লাহ তায়ালা তোমাদের যাবতীয় কাজকর্মের ব্যাপারেই সম্যক অবগত রয়েছেন।', 'Wain kuntum AAala safarin walam tajidoo katiban farihanun maqboodatun fain amina baAAdukum baAAdan falyuaddi allathee itumina amanatahu walyattaqi Allaha rabbahu wala taktumoo alshshahadata waman yaktumha fainnahu athimun qalbuhu waAllahu bima taAAmaloona AAaleemun', 1, NOW(), NOW()),
(2, 284, 'لِّلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَإِن تُبۡدُواْ مَا فِيٓ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'আসমান যমীনে যতো কিছু আছে তা সবই আল্লাহ তায়ালার জন্যে, তোমরা তোমাদের মনের ভেতর যা কিছু আছে তা যদি প্রকাশ করো কিংবা তা গোপন করো, আল্লাহ তায়ালা (একদিন) তোমাদের কাছ থেকে এর (পুরোপুরি) হিসাব গ্রহণ করবেন; (এরপর) তিনি যাকে ইচ্ছা তাকে মাফ করে দেবেন, (আবার) যাকে ইচ্ছা তাকে তিনি শাস্তি দেবেন; আল্লাহ তায়ালা সবকিছুর ওপর একক ক্ষমতাবান।', 'Lillahi ma fee alssamawati wama fee alardi wain tubdoo ma fee anfusikum aw tukhfoohu yuhasibkum bihi Allahu fayaghfiru liman yashao wayuAAaththibu man yashao waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(2, 285, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ', '(আল্লাহর) রসূল সে বিষয়ের ওপর ঈমান এনেছে যা তাঁর ওপর তাঁর মালিকের পক্ষ থেকে নাযিল করা হয়েছে, (তাঁর সাথী) মুমীনরাও ঈমান এনেছে, এরা সবাই ঈমান এনেছে আল্লাহর ওপর, তাঁর ফেরেশতাদের ওপর, তাঁর কিতাবসমূহের ওপর, তাঁর রসূলদের ওপর। (তারা বলে,) আমরা তাঁর নবী রসূলদের কারো মাঝে কোনো রকম পার্থক্য করি না; তারা বলে, আমরা (আল্লাহর নির্দেশ) শুনেছি এবং (তা) মেনে নিয়েছি, হে আমাদের রব, (আমরা) তোমার ক্ষমা চাই এবং তোমার কাছেই হচ্ছে সবার ফিরে যাওয়ার জায়গা।', 'Amana alrrasoolu bima onzila ilayhi min rabbihi waalmuminoona kullun amana biAllahi wamalaikatihi wakutubihi warusulihi la nufarriqu bayna ahadin min rusulihi waqaloo samiAAna waataAAna ghufranaka rabbana wailayka almaseeru', 1, NOW(), NOW()),
(2, 286, 'لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', 'আল্লাহ তায়ালা কাউকেই তার শক্তি সামর্থের বাইরে কোনো কাজের দায়িত্ব চাপিয়ে দেন না; সে ব্যক্তির জন্যে ততোটুকুই বিনিময় রয়েছে যতোটুকু সে (এ দুনিয়ায়) অর্জন করবে, আবার সে যতোটুকু (মন্দ দুনিয়ায়) অর্জন করেছে তার ওপর তার (ততোটুকু শাস্তিই) পতিত হবে; (অতএব, হে মোমেন ব্যক্তিরা, তোমরা এই বলে দোয়া করো,) হে আমাদের রব, আমরা যদি কিছু ভুলে যাই, (কোথাও) যদি আমরা কোনো গুনাহ করে ফেলি, তার জন্যে তুমি আমাদের পাকড়াও করো না, হে আমাদের রব, আমাদের পূর্ববর্তী (জাতিদের) ওপর যে ধরনের বোঝা তুমি চাপিয়েছিলে তা আমাদের ওপর চাপিয়ো না, হে আমাদের রব, যে বোঝা বইবার সামর্থ আমাদের নেই তা তুমি আমাদের ওপর চাপিয়ে দিয়ো না, তুমি আমাদের ওপর মেহেরবানী করো। তুমি আমাদের মাফ করে দাও। আমাদের ওপর তুমি দয়া করো। তুমিই আমাদের (একমাত্র আশ্রয়দাতা) বন্ধু, অতপর কাফেরদের মোকাবেলায় তুমি আমাদের সাহায্য করো।', 'La yukallifu Allahu nafsan illa wusAAaha laha ma kasabat waAAalayha ma iktasabat rabbana la tuakhithna in naseena aw akhtana rabbana wala tahmil AAalayna isran kama hamaltahu AAala allatheena min qablina rabbana wala tuhammilna ma la taqata lana bihi waoAAfu AAanna waighfir lana wairhamna anta mawlana faonsurna AAala alqawmi alkafireena', 1, NOW(), NOW()),
(3, 1, 'الٓمٓ', 'আলিফ-লাম-মীম।', 'Aliflammeem', 1, NOW(), NOW()),
(3, 2, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ', 'মহান আল্লাহ তায়ালা, তিনি ছাড়া কোনো মা’বুদ নেই, (তিনি) চিরঞ্জীব, (তিনি) চিরস্থায়ী।লের রব,', 'Allahu la ilaha illa huwa alhayyu alqayyoomu', 1, NOW(), NOW()),
(3, 3, 'نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ', 'তিনি সত্য (দ্বীন) সহকারে তোমার ওপর কিতাব নাযিল করেছেন, যা তোমার আগে নাযিল করা অন্যান্য কিতাবের সত্যতা স্বীকার করে। তিনি তাওরাত ও ইনজীল নাযিল করেছেন;', 'Nazzala AAalayka alkitaba bialhaqqi musaddiqan lima bayna yadayhi waanzala alttawrata waalinjeela', 1, NOW(), NOW()),
(3, 4, 'مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ', 'মানব জাতিকে (সঠিক) পথ প্রদর্শনের জন্যে ইতিপূর্বে (আল্লাহ তায়ালা আরো কিতাব নাযিল করেছেন), তিনি (হক ও বাতিলের মধ্যে) ফয়সালা করার মানদন্ড হিসেবে কোরআন) অবতীর্ণ করেছেন; অবশ্যই যারা আল্লাহ তায়ালার নিদর্শনসমূহকে অস্বীকার করবে, তাদের জন্যে কঠোর শাস্তি রয়েছে; আল্লাহ তায়ালা অসীম ক্ষমতার মালিক, তিনি চরম প্রতিশোধ গ্রহণকারীও বটে!', 'Min qablu hudan lilnnasi waanzala alfurqana inna allatheena kafaroo biayati Allahi lahum AAathabun shadeedun waAllahu AAazeezun thoo intiqamin', 1, NOW(), NOW()),
(3, 5, 'إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ', 'অবশ্যই আল্লাহ তায়ালা (মহান) তাঁর কাছে আসমান ও ভূখন্ডের কোনো তথ্যই গোপন নেই।', 'Inna Allaha la yakhfa AAalayhi shayon fee alardi wala fee alssamai', 1, NOW(), NOW()),
(3, 6, 'هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'তিনি সেই মহান সত্তা যিনি (মায়ের পেটে কিংবা) শুক্রকীটে (থাকতেই) তাঁর ইচ্ছামতো তোমাদের আকৃতি গঠন করেছেন; তিনি ছাড়া দ্বিতীয় কোনো মা’বুদ নেই, তিনি প্রচন্ড ক্ষমতাশালী এবং প্রবল প্রজ্ঞাময়।', 'Huwa allathee yusawwirukum fee alarhami kayfa yashao la ilaha illa huwa alAAazeezu alhakeemu', 1, NOW(), NOW()),
(3, 7, 'هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ', 'তিনিই সেই মহান সত্তা, যিনি তোমার ওপর কিতাব নাযিল করেছেন। (এই কিতাবে দু’ধরনের আয়াত রয়েছে), এর কিছু হচ্ছে (সুস্পষ্ট) দ্ব্যর্থহীন আয়াত, সেগুলোই হচ্ছে কিতাবের মৌলিক অংশ, (এ ছাড়া) বাকী আয়াতগুলো হচ্ছে রূপক (বর্ণনায় বর্ণিত, মানুষের মাঝে) যাদের অন্তরে বক্রতা রয়েছে, তারা (এগুলোকে কেন্দ্র করেই নানা ধরনের) ফেতনা ফাসাদ (সৃষ্টি করে) এবং (আল্লাহর কিতাবের অপ−) ব্যাখ্যা করার উদ্দেশে এসব (রূপক) আয়াত থেকে কিছু অংশের তারা অনুসরণ করে, (মূলত) এসব (রূপক) বিষয়ের ব্যাখ্যা আল্লাহ তায়ালা ছাড়া আর কেউই জানে না। (এ কারণেই) যাদের মধ্যে জ্ঞানের গভীরতা আছে তারা (এসব আয়াত সম্পর্কে) বলে, আমরা এর ওপর ঈমান এনেছি, এগুলো সবই তো আমাদের মালিকের পক্ষ থেকে (এসেছে, সত্য কথা হচ্ছে, আল্লাহর হেদায়াতে) প্রজ্ঞাসম্পন্ন লোকেরাই কেবল শিক্ষা গ্রহণ করে থাকে।', 'Huwa allathee anzala AAalayka alkitaba minhu ayatun muhkamatun hunna ommu alkitabi waokharu mutashabihatun faamma allatheena fee quloobihim zayghun fayattabiAAoona ma tashabaha minhu ibtighaa alfitnati waibtighaa taweelihi wama yaAAlamu taweelahu illa Allahu waalrrasikhoona fee alAAilmi yaqooloona amanna bihi kullun min AAindi rabbina wama yaththakkaru illa oloo alalbabi', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(3, 8, 'رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ', '(তারা আরো বলে,) হে আমাদের রব, (একবার যখন) তুমি আমাদের (সঠিক) পথের দিশা দিয়েছো, (তখন তুমি আর) আমাদের মনকে বাঁকা করে দিয়ো না, একান্ত তোমার কাছ থেকে তুমি আমাদের প্রতি দয়া করো, কেননা যাবতীয় দয়ার মালিক তো তুমিই।', 'Rabbana la tuzigh quloobana baAAda ith hadaytana wahab lana min ladunka rahmatan innaka anta alwahhabu', 1, NOW(), NOW()),
(3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ', 'হে আমাদের রব, তুমি অবশ্যই সমগ্র মানব জাতিকে একদিন (তোমার কাছে) একত্রিত করবে, এতে কোনো রকম সন্দেহ নেই: নিসন্দেহে আল্লাহ তায়ালা ওয়াদা ভংগ করেন না।', 'Rabbana innaka jamiAAu alnnasi liyawmin la rayba feehi inna Allaha la yukhlifu almeeAAada', 1, NOW(), NOW()),
(3, 10, 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ', 'যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে তাদের ধন-সম্পদ ও সন্তান সন্ততি আল্লাহর (আযাব) থেকে (তাদের বাঁচানোর ব্যাপারে) কখনোই কোনো উপকার করবে না, তারাই হবে জাহান্নামের ইন্ধন।', 'Inna allatheena kafaroo lan tughniya AAanhum amwaluhum wala awladuhum mina Allahi shayan waolaika hum waqoodu alnnari', 1, NOW(), NOW()),
(3, 11, 'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ', '(তাদের পরিণতি হবে) ফেরাউন ও তাদের পূর্ববর্তী (না-ফরমান) জাতিসমূহের মতো; তারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করেছিলো, অতপর তাদের অপরাধের কারণে আল্লাহ তায়ালা তাদের (শক্ত করে) পাকড়াও করলেন; (বস্তুত) শাস্তি প্রয়োগে আল্লাহ তায়ালা অত্যন্ত কঠোর।', 'Kadabi ali firAAawna waallatheena min qablihim kaththaboo biayatina faakhathahumu Allahu bithunoobihim waAllahu shadeedu alAAiqabi', 1, NOW(), NOW()),
(3, 12, 'قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ', '(হে নবী,) কাফেরদের তুমি বলে দাও, অচিরেই তোমরা (এ দুনিয়ায় লাঞ্ছিত) পরাজিত হবে এবং (পরকালে) তোমাদের জাহান্নামের কাছে জড়ো করা হবে; (আর জাহান্নাম!) কতো নিকৃষ্ট অবস্থান!', 'Qul lillatheena kafaroo satughlaboona watuhsharoona ila jahannama wabisa almihadu', 1, NOW(), NOW()),
(3, 13, 'قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ', '(হে নবী,) কাফেরদের তুমি বলে দাও, অচিরেই তোমরা (এ দুনিয়ায় লাঞ্ছিত) পরাজিত হবে এবং (পরকালে) তোমাদের জাহান্নামের কাছে জড়ো করা হবে; (আর জাহান্নাম!) কতো নিকৃষ্ট অবস্থান!', 'Qad kana lakum ayatun fee fiatayni iltaqata fiatun tuqatilu fee sabeeli Allahi waokhra kafiratun yarawnahum mithlayhim raya alAAayni waAllahu yuayyidu binasrihi man yashao inna fee thalika laAAibratan liolee alabsari', 1, NOW(), NOW()),
(3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ', 'নারী জাতির প্রতি ভালোবাসা, সন্তান সন্ততি, কাঁড়ি কাঁড়ি সোনা রূপা, পছন্দসই ঘোড়া, গৃহপালিত জন্তু ও যমীনের ফসলকে (সব সময়ই) মানব সন্তানের জন্যে লোভনীয় করে রাখা হয়েছে; (আসলে) এ সব হচ্ছে পার্থিব জীবনের কিছু ভোগের সামগ্রী (মাত্র! স্থায়ী জীবনের) উৎকৃষ্ট আশ্রয় তো একমাত্র আল্লাহ তায়ালার কাছেই রয়েছে।', 'Zuyyina lilnnasi hubbu alshshahawati mina alnnisai waalbaneena waalqanateeri almuqantarati mina alththahabi waalfiddati waalkhayli almusawwamati waalanAAami waalharthi thalika mataAAu alhayati alddunya waAllahu AAindahu husnu almaabi', 1, NOW(), NOW()),
(3, 15, '۞قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ', '(হে নবী,) তুমি বলো, আমি কি তোমাদের এগুলোর চাইতে উৎকৃষ্ট কোনো বস্তুর কথা বলবো? (হ্যাঁ, সে উৎকৃষ্ট বস্তু হচ্ছে) তাদের জন্যে, যারা আল্লাহকে ভয় করে তাদের মালিকের কাছে তাদের জন্যে রয়েছে (মনোরম) জান্নাত, যার পাদদেশ দিয়ে প্রবাহমান থাকবে (অগণিত) ঝর্ণাধারা এবং তারা সেখানে অনাদিকাল থাকবে, আরো থাকবে (তাদের) পূত পবিত্র সংগী ও সংগিনীরা- থাকবে আল্লাহ তায়ালার (অনাবিল) সন্তুষ্টি; আল্লাহ তায়ালা নিজ বান্দাদের (কার্যকলাপের) ওপর সতর্ক দৃষ্টি রাখেন।', 'Qul aonabbiokum bikhayrin min thalikum lillatheena ittaqaw AAinda rabbihim jannatun tajree min tahtiha alanharu khalideena feeha waazwajun mutahharatun waridwanun mina Allahi waAllahu baseerun bialAAibadi', 1, NOW(), NOW()),
(3, 16, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', 'যারা বলে, হে আমাদের রব, আমরা অবশ্যই তোমার ওপর ঈমান এনেছি, অতপর তুমি আমাদের গুনাহখাতা মাফ করে দাও এবং (শেষ বিচারের দিন) তুমি আমাদের জাহান্নামের আগুন থেকে বাঁচিয়ে দিয়ো।', 'Allatheena yaqooloona rabbana innana amanna faighfir lana thunoobana waqina AAathaba alnnari', 1, NOW(), NOW()),
(3, 17, 'ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ', 'এরা হচ্ছে ধৈর্যশীল, সত্যাশ্রয়ী, অনুগত এবং দানশীল, (সর্বোপরি) এরা হচ্ছে শেষরাতে কিংবা ঊষালগ্নের পূর্বে আল্লাহর কাছে ক্ষমা প্রার্থনাকারী।', 'Alssabireena waalssadiqeena waalqaniteena waalmunfiqeena waalmustaghfireena bialashari', 1, NOW(), NOW()),
(3, 18, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَـٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'আল্লাহ তায়ালা (স্বয়ং) সাক্ষ্য দিচ্ছেন, তিনি ছাড়া অন্য কোনো মা’বুদ নেই, (সাক্ষ্য দিচ্ছে) ফেরেশতারা এবং জ্ঞানবান মানুষরাও, আল্লাহ তায়ালাই একমাত্র ন্যায় ও ইনসাফ কার্যকর করেন, তিনি ছাড়া দ্বিতীয় কোনো মা’বুদ নেই, তিনি পরাক্রমশালী, তিনি প্রজ্ঞাময়।', 'Shahida Allahu annahu la ilaha illa huwa waalmalaikatu waoloo alAAilmi qaiman bialqisti la ilaha illa huwa alAAazeezu alhakeemu', 1, NOW(), NOW()),
(3, 19, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', 'নিসন্দেহে (মানুষের) জীবন বিধান হিসেবে আল্লাহ তায়ালার কাছে ইসলামই একমাত্র (গ্রহণযোগ্য) ব্যবস্থা। যাদের আল্লাহর পক্ষ থেকে কিতাব দেয়া হয়েছিলো, তারা (এ জীবন বিধান থেকে বিচ্যুত হবার পর) নিজেরা একে অপরের প্রতি বিদ্বেষ ও হিংসার বশবর্তী হয়ে মতানৈক্যে লিপ্ত হয়ে পড়েছিলো, (তাও আবার) তাদের কাছে (আল্লাহর পক্ষ থেকে) সঠিক জ্ঞান আসার পর। যে ব্যক্তি আল্লাহর বিধান অস্বীকার করবে (তার জানা উচিত), অবশ্যই আল্লাহ তায়ালা দ্রুত হিসাব গ্রহণকারী।', 'Inna alddeena AAinda Allahi alislamu wama ikhtalafa allatheena ootoo alkitaba illa min baAAdi ma jaahumu alAAilmu baghyan baynahum waman yakfur biayati Allahi fainna Allaha sareeAAu alhisabi', 1, NOW(), NOW()),
(3, 20, 'فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ', 'যদি এরা তোমার সাথে (এ ব্যাপারে কোনোরূপ) বিতর্কে লিপ্ত হয়, তাহলে তুমি বলো, আমি এবং আমাকে যারা অনুসরণ করেছে তারা- (সবাই) আল্লাহর কাছে আত্মসমর্পণ করে নিয়েছি; অতপর যাদের (আল্লাহর পক্ষ থেকে) কিতাব দেয়া হয়েছে এবং যারা (কোনো কিতাব না পেয়ে) মূর্খ (থেকে গেছে), তাদের জিজ্ঞেস করো, তোমরা কি সবাই আল্লাহর কাছে আত্মসমর্পণ করেছো? (হ্যাঁ,) তারা যদি আল্লাহর আনুগত্য মেনে নেয় তাহলে তারা তো সঠিক পথ পেয়েই গেলো, কিন্তু তারা যদি (ঈমান থেকে) মুখ ফিরিয়ে নেয় (তাহলে মনে রেখো), তোমার ওপর দায়িত্ব হচ্ছে কেবল (আমার কথা) পৌঁছে দেয়া; আল্লাহ তায়ালা বান্দাদের (কর্মকা ন্ড নিজেই) পর্যবেক্ষণ করছেন।', 'Fain hajjooka faqul aslamtu wajhiya lillahi wamani ittabaAAani waqul lillatheena ootoo alkitaba waalommiyyeena aaslamtum fain aslamoo faqadi ihtadaw wain tawallaw fainnama AAalayka albalaghu waAllahu baseerun bialAAibadi', 1, NOW(), NOW()),
(3, 21, 'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ', 'নিসন্দেহে যারা আল্লাহর নিদর্শনসমূহ অস্বীকার করে, যারা অন্যায়ভাবে নবীদের হত্যা করে- হত্যা করে মানব জাতির যারা ন্যায় ও ইনসাফ মেনে চলার আদেশ দেয়- তাদেরও, এদের তুমি এক কঠোর শাস্তির সুসংবাদ দাও।', 'Inna allatheena yakfuroona biayati Allahi wayaqtuloona alnnabiyyeena bighayri haqqin wayaqtuloona allatheena yamuroona bialqisti mina alnnasi fabashshirhum biAAathabin aleemin', 1, NOW(), NOW()),
(3, 22, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ', 'এরাই হচ্ছে সেসব লোক যাদের দুনিয়া আখেরাত উভয় স্থানেই তাদের কর্ম ব্যর্থ (ও নিষ্ফল) হয়ে গেছে, এদের কোনো সাহায্যকারীও নেই।', 'Olaika allatheena habitat aAAmaluhum fee alddunya waalakhirati wama lahum min nasireena', 1, NOW(), NOW()),
(3, 23, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ', '(হে নবী,) তুমি তাদের সম্পর্কে চিন্তা করে দেখেছো কি, যাদের আমার কিতাবের কিছু অংশ দেয়া হয়েছিলো, অতপর তাদের যখন আল্লাহর কিতাবের দিকে ডাকা হয়, যা তাদের মধ্যকার অমীমাংসিত বিষয়সমূহের মীমাংসা করে দেবে, তখন তাদের একদল লোক (এ থেকে) মুখ ফিরিয়ে নেয়, (মূলত) এরাই হচ্ছে সেসব লোক যারা (আল্লাহর ফয়সালা থেকে) মুখ ফিরিয়ে রাখে।', 'Alam tara ila allatheena ootoo naseeban mina alkitabi yudAAawna ila kitabi Allahi liyahkuma baynahum thumma yatawalla fareequn minhum wahum muAAridoona', 1, NOW(), NOW()),
(3, 24, 'ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ', 'এটা এ কারণে যে, এ লোকেরা বলে, (দোযখের) আগুন আমাদের কখনো স্পর্শ করবে না, (আর করলেও তা হবে) হাতেগনা কয়েকটি দিনের ব্যাপার মাত্র, (মূলত) তাদের নিজেদের ধর্ম বিশ্বাসের মাঝে নিজেদের মনগড়া ধারণাই তাদের প্রতারিত করে রেখেছে।', 'Thalika biannahum qaloo lan tamassana alnnaru illa ayyaman maAAdoodatin wagharrahum fee deenihim ma kanoo yaftaroona', 1, NOW(), NOW()),
(3, 25, 'فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', 'অতপর (সেদিন তাদের) কী অবস্থা হবে, যেদিন আমি সমগ্র মানব সন্তানকে একত্রিত করবো, যেদিন সম্পর্কে কোনো দ্বিধা সন্দেহের অবকাশ নেই- সেদিন প্রত্যেক মানুষকেই তার অর্জনের বিনিময় পুরোপুরি দিয়ে দেয়া হবে এবং তাদের ওপর বিন্দুমাত্রও যুলুম করা হবে না।', 'Fakayfa itha jamaAAnahum liyawmin la rayba feehi wawuffiyat kullu nafsin ma kasabat wahum la yuthlamoona', 1, NOW(), NOW()),
(3, 26, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', '(হে নবী), তুমি বলো, হে রাজাধিরাজ (মহান আল্লাহ), তুমি যাকে ইচ্ছা তাকে সাম্রাজ্য দান করো, আবার যার কাছ থেকে চাও তা কেড়েও নাও, যাকে ইচ্ছা তুমি সম্মানিত করো, যাকে ইচ্ছা তুমি অপমানিত করো; সব রকমের কল্যাণ তো তোমার হাতেই নিবদ্ধ; নিশ্চয়ই তুমি সবকিছুর ওপর একক ক্ষমতাবান।', 'Quli allahumma malika almulki tutee almulka man tashao watanziAAu almulka mimman tashao watuAAizzu man tashao watuthillu man tashao biyadika alkhayru innaka AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(3, 27, 'تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ', 'তুমিই রাতকে দিনের মাঝে শামিল করো, আবার দিনকে রাতের ভেতর শামিল করো; প্রাণহীন (বস্তু) থেকে তুমি (যেমন) প্রাণের আবির্ভাব ঘটাও, (আবার) প্রাণহীন (অসাড় ) বস্তু বের করে আনো প্রাণসর্বস্ব (জীব) থেকে এবং যাকে ইচ্ছা তুমি বিনা হিসাবে রেযেক দান করো।', 'Tooliju allayla fee alnnahari watooliju alnnahara fee allayli watukhriju alhayya mina almayyiti watukhriju almayyita mina alhayyi watarzuqu man tashao bighayri hisabin', 1, NOW(), NOW()),
(3, 28, 'لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ', 'ঈমানদার ব্যক্তিরা কখনো ঈমানদারদের বদলে কাফেরদের নিজেদের বন্ধু বানাবে না, যদি তোমাদের কেউ তা করে তবে আল্লাহর সাথে তার কোনো সম্পর্কই থাকবে না, হাঁ তাদের কাছ থেকে কোনো আশংকা (থাকলে) নিজেদের বাঁচানোর প্রয়োজন হলে তা ভিন্ন কথা; আল্লাহ তায়ালা তো বরং তাঁর নিজের ব্যাপারেই তোমাদের ভয় দেখাচ্ছেন (বেশী), কারণ তোমাদের ফিরে যাবার জায়গা তো আল্লাহর কাছেই।', 'La yattakhithi almuminoona alkafireena awliyaa min dooni almumineena waman yafAAal thalika falaysa mina Allahi fee shayin illa an tattaqoo minhum tuqatan wayuhaththirukumu Allahu nafsahu waila Allahi almaseeru', 1, NOW(), NOW()),
(3, 29, 'قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', '(হে নবী,) তুমি বলো, তোমরা তোমাদের মনের ভেতর কিছু গোপন করে রাখো, কিংবা তা যদি প্রকাশ করে দাও, তা আল্লাহ তায়ালা (ভালোভাবে) অবগত হন; আসমান যমীন ও এর (আভ্যন্তরীণ) সবকিছুও তিনি জানেন, সর্বোপরি আল্লাহ তায়ালা সব কিছুর ওপর ক্ষমতাবান।', 'Qul in tukhfoo ma fee sudoorikum aw tubdoohu yaAAlamhu Allahu wayaAAlamu ma fee alssamawati wama fee alardi waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(3, 30, 'يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ', 'যেদিন প্রত্যেকেই তার ভালো কাজ সামনে হাযির দেখতে পাবে যা সে (দুনিয়ায়) অর্জন করেছে, যে ব্যক্তি কোনো খারাপ কিছু অর্জন করবে সে সেদিন কামনা করতে থাকবে, তার এবং তার (কাজের) মাঝে যদি দুস্তর একটা তফাৎ থাকতো! আল্লাহ তায়ালা তোমাদের তাঁর (শাস্তির) ভয় দেখাচ্ছেন, আল্লাহ তায়ালা তাঁর বান্দাদের সাথে অত্যন্ত অনুগ্রহশীল।', 'Yawma tajidu kullu nafsin ma AAamilat min khayrin muhdaran wama AAamilat min sooin tawaddu law anna baynaha wabaynahu amadan baAAeedan wayuhaththirukumu Allahu nafsahu waAllahu raoofun bialAAibadi', 1, NOW(), NOW()),
(3, 31, 'قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', '(হে নবী,) তুমি বলো, তোমরা যদি আল্লাহ তায়ালাকে ভালোবাসো, তাহলে আমার কথা মেনে চলো, আল্লাহ তায়ালাও তোমাদের ভালোবাসবেন এবং তিনি তোমাদের গুনাহখাতা মাফ করে দেবেন; আল্লাহ তায়ালা অত্যন্ত ক্ষমাশীল ও দয়াবান।', 'Qul in kuntum tuhibboona Allaha faittabiAAoonee yuhbibkumu Allahu wayaghfir lakum thunoobakum waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(3, 32, 'قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ', 'তুমি বলো, তোমরা আল্লাহ তায়ালা ও (তাঁর) রসূলের কথা মেনে চলো, তারা যদি (এ থেকে) মুখ ফিরিয়ে নেয় (তাহলে জেনে রেখো), আল্লাহ তায়ালা (তাঁর রসূলের আনুগত্য) অস্বীকারকারীদের পছন্দ করেন না।', 'Qul ateeAAoo Allaha waalrrasoola fain tawallaw fainna Allaha la yuhibbu alkafireena', 1, NOW(), NOW()),
(3, 33, '۞إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ', 'অবশ্যই আল্লাহ তায়ালা আদম, নূহ এবং ইবরাহীমের বংশধর ও ইমরানের বংশধরদের সৃষ্টিকুলের ওপর (নেতৃত্বের জন্যে) বাছাই করে নিয়েছেন;', 'Inna Allaha istafa adama wanoohan waala ibraheema waala AAimrana AAala alAAalameena', 1, NOW(), NOW()),
(3, 34, 'ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'এদের সন্তানরা বংশানুক্রমে পরস্পর পরস্পরের বংশধর; আল্লাহ তায়ালা (সবার কথাবার্তা) শুনতে পান এবং (সব কথা তিনি) জানেন।', 'Thurriyyatan baAAduha min baAAdin waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(3, 35, 'إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', '(স্মরণ করো,) যখন ইমরানের স্ত্রী বললো, হে আমার রব, আমার গর্ভে যা আছে তাকে আমি স্বাধীনভাবে তোমার (দ্বীনের কাজ করার) জন্যে উৎসর্গ করলাম, অতপর তুমি আমার পক্ষ থেকে এ সন্তানটিকে কবুল করে নাও, অবশ্যই তুমি (সব কথা) শোনো এবং (সব বিষয়) জানো।', 'Ith qalati imraatu AAimrana rabbi innee nathartu laka ma fee batnee muharraran fataqabbal minnee innaka anta alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(3, 36, 'فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ', 'অতপর সে (ইমরানের স্ত্রী) যখন তাকে জন্ম দিলো, (তখন) সে বললো, হে আমার রব, আমি তো একটি মেয়ে সন্তান জন্ম দিয়েছি (একটা মেয়েকে স্বাধীনভাবে কি করে আমি তোমার পথে উৎসর্গ করবো); আল্লাহ তায়ালা তো ভালোভাবেই জানতেন, ইমরানের স্ত্রী কি সন্তান জন্ম দিয়েছে, (আসলে কিছু কিছু কাজ আছে যেখানে) ছেলে কখনো মেয়ের মতো হয় না। (ইমরানের স্ত্রী বললো) আমি এ তার নাম রাখলাম মারইয়াম এবং আমি এ শিশু ও তার (অনাগত) সন্তানকে অভিশপ্ত শয়তানের (অনিষ্ট) থেকে রক্ষার জন্যে তোমার কাছে আশ্রয় চাই।', 'Falamma wadaAAatha qalat rabbi innee wadaAAtuha ontha waAllahu aAAlamu bima wadaAAat walaysa alththakaru kaalontha wainnee sammaytuha maryama wainnee oAAeethuha bika wathurriyyataha mina alshshaytani alrrajeemi', 1, NOW(), NOW()),
(3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ', 'অতপর তাঁর রব তাঁর দোয়া কবুল করলেন, তাকে অত্যন্ত সুন্দরভাবেই গ্রহণ করে নিলেন এবং তাকে তিনি ভালোভাবেই গড়ে তুললেন, (আর সে জন্যেই) তিনি তাঁকে যাকারিয়ার তত্ত্বাবধানে রাখলেন, (বড়ো হবার পর) যখনি যাকারিয়া তার কাছে (তার নিজস্ব) এবাদাতের কক্ষে যেতো, (তখনি সে দেখতে) পেতো সেখানে কিছু খাবার (মজুদ) রয়েছে, (তা দেখে) যাকারিয়া জিজ্ঞেস করতো, হে মারইয়াম, এসব (খাবার) তোমার কাছে কোত্থেকে আসে? মারইয়াম জবাব দিতো, এ সব (আসে আমার মালিক) আল্লাহর কাছ থেকে; (আর) অবশ্যই আল্লাহ তায়ালা যাকে চান তাকে বিনা হিসাবে রেযেক দান করেন।', 'Fataqabbalaha rabbuha biqaboolin hasanin waanbataha nabatan hasanan wakaffalaha zakariyya kullama dakhala AAalayha zakariyya almihraba wajada AAindaha rizqan qala ya maryamu anna laki hatha qalat huwa min AAindi Allahi inna Allaha yarzuqu man yashao bighayri hisabin', 1, NOW(), NOW()),
(3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'সেখানে (দাঁড়িয়েই) যাকারিয়া তার মালিকের কাছে দোয়া করলো, হে আমার রব, তুমি তোমার কাছ থেকে আমাকে একটি নেক সন্তান দান করো, নিশ্চয়ই তুমি (মানুষের) ডাক শোনো।', 'Hunalika daAAa zakariyya rabbahu qala rabbi hab lee min ladunka thurriyyatan tayyibatan innaka sameeAAu aldduAAai', 1, NOW(), NOW()),
(3, 39, 'فَنَادَتۡهُ ٱلۡمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّـٰلِحِينَ', 'অতপর ফেরেশতারা তাঁকে ডাক দিলো (এমন এক সময়ে) যখন সে এবাদাতের কক্ষে নামায আদায় করছিলো (ফেরেশতারা বললো, হে যাকারিয়া,) অবশ্যই আল্লাহ তায়ালা তোমাকে ইয়াহইয়ার (জন্ম সম্পর্কে) সুসংবাদ দিচ্ছেন, আল্লাহর পক্ষ থেকে সে তাঁর বাণীর সত্যায়ন করবে, সে হবে (সমাজের) নেতা, সচ্চরিত্রবান, নবী, (সর্বোপরি সে হবে) সৎকর্মশীল ব্যক্তিদের একজন।', 'Fanadathu almalaikatu wahuwa qaimun yusallee fee almihrabi anna Allaha yubashshiruka biyahya musaddiqan bikalimatin mina Allahi wasayyidan wahasooran wanabiyyan mina alssaliheena', 1, NOW(), NOW()),
(3, 40, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ', '(এ কথা শুনে) যাকারিয়া বললো, হে আমার রব, আমার (ঘরে) ছেলে হবে কিভাবে, বার্ধক্য তো আমাকে পেয়ে বসেছে (তদুপরি) আমার স্ত্রীও বন্ধ্যা (সন্তান ধারণে সে সম্পূর্ণ অক্ষম); আল্লাহ তায়ালা বললেন, হাঁ এভাবেই আল্লাহ তায়ালা যা চান তা তিনি করেন।', 'Qala rabbi anna yakoonu lee ghulamun waqad balaghaniya alkibaru waimraatee AAaqirun qala kathalika Allahu yafAAalu ma yashao', 1, NOW(), NOW()),
(3, 41, 'قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ', 'সে (যাকারিয়া) নিবেদন করলো, হে রব, তুমি আমার জন্যে (এর) কিছু (পূর্ব) লক্ষণ ঠিক করে দাও; তিনি বললেন (হাঁ), তোমার (সে) লক্ষণ হবে, তুমি তিন দিন (তিন রাত) পর্যন্ত মানুষের সাথে ইশারা ইংগিত ছাড়া কথাবার্তা বলবে না; (এ অবস্থায়) তুমি তোমার মালিককে বেশী বেশী স্মরণ করবে এবং সকাল সন্ধ্যায় (তাঁর) তাসবীহ পাঠ করতে থাকবে।', 'Qala rabbi ijAAal lee ayatan qala ayatuka alla tukallima alnnasa thalathata ayyamin illa ramzan waothkur rabbaka katheeran wasabbih bialAAashiyyi waalibkari', 1, NOW(), NOW()),
(3, 42, 'وَإِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ', '(অতপর মারইয়াম বয়োপ্রাপ্ত হলে) আল্লাহর ফেরেশতারা যখন তাকে বললো, হে মারইয়াম, আল্লাহ তায়ালা নিসন্দেহে তোমাকে (বিশেষ কাজের জন্যে) বাছাই করেছেন এবং (সে জন্যে) তোমাকে তিনি পবিত্র করেছেন এবং বিশ্বের নারীকুলের ওপর তিনি তোমাকে বাছাই করেছেন।', 'Waith qalati almalaikatu ya maryamu inna Allaha istafaki watahharaki waistafaki AAala nisai alAAalameena', 1, NOW(), NOW()),
(3, 43, 'يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّـٰكِعِينَ', 'হে মারইয়াম, (এর জন্যে) তুমি সর্বদা তোমার মালিকের অনুগত হও, (তাঁর জন্যে) সাজদা করো এবং যারা (তাঁর জন্যে) রুকু করে তুমিও তাদের সাথে রুকু করো।', 'Ya maryamu oqnutee lirabbiki waosjudee wairkaAAee maAAa alrrakiAAeena', 1, NOW(), NOW()),
(3, 44, 'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ', '(হে নবী,) এ সবই হচ্ছে গায়বের সংবাদ, আমিই এগুলো তোমাকে ওহীর মাধ্যমে জানিয়েছি; (নতুবা তুমি তো সেখানে তাদের পাশে হাযির ছিলে না- (বিশেষ করে) যখন (এবাদাতখানার পুরোহিতরা) মারইয়ামের পৃষ্ঠপোষক কে হবে এটা নির্বাচনের জন্যে তাদের (লটারির) ‘কলম’ নিক্ষেপ করছিলো, আর তুমি তাদের ওখানেও উপস্থিত ছিলে না যখন তারা (এ নিয়ে) বিতর্ক করছিলো!', 'Thalika min anbai alghaybi nooheehi ilayka wama kunta ladayhim ith yulqoona aqlamahum ayyuhum yakfulu maryama wama kunta ladayhim ith yakhtasimoona', 1, NOW(), NOW()),
(3, 45, 'إِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ', 'অতপর ফেরেশতারা বললো, হে মারইয়াম, অবশ্যই আল্লাহ তায়ালা তোমাকে (পুত্র সন্তানের জন্ম সংক্রান্ত) নিজস্ব বাণী দ্বারা সুসংবাদ দিচ্ছেন, তার নাম মাসীহ- মারইয়ামের পুত্র ঈসা, দুনিয়া আখেরাতের উভয় স্থানেই সে সম্মানিত হবে, সে হবে (আল্লাহর) সান্নিধ্যপ্রাপ্ত ব্যক্তিদের অন্যতম।', 'Ith qalati almalaikatu ya maryamu inna Allaha yubashshiruki bikalimatin minhu ismuhu almaseehu AAeesa ibnu maryama wajeehan fee alddunya waalakhirati wamina almuqarrabeena', 1, NOW(), NOW()),
(3, 46, 'وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّـٰلِحِينَ', 'সে দোলনায় থাকা অবস্থায় (যেমন) মানুষের সাথে কথা বলবে, পরিণত বয়সেও (তেমনিভাবে) কথা বলবে এবং সে হবে নেককার মানুষদের একজন।', 'Wayukallimu alnnasa fee almahdi wakahlan wamina alssaliheena', 1, NOW(), NOW()),
(3, 47, 'قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'মারইয়াম বললো, হে আমার মালিক, আমার সন্তান হবে কিভাবে? আমাকে তো কখনো কোনো মানব সন্তান স্পর্শ পর্যন্ত করেনি; আল্লাহ বললেন, এভাবেই- আল্লাহ তায়ালা যাকে চান (চিরাচরিত নিয়ম ছাড়াই) তাকে পয়দা করেন; তিনি যখন কোনো কাজ করার সিদ্ধান্ত নেন তখন শুধু তাকে বলেন, ‘হও’, অতপর (সাথে সাথে) তা হয়ে যায়।', 'Qalat rabbi anna yakoonu lee waladun walam yamsasnee basharun qala kathaliki Allahu yakhluqu ma yashao itha qada amran fainnama yaqoolu lahu kun fayakoonu', 1, NOW(), NOW()),
(3, 48, 'وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ', '(ফেরেশতারা বললো,) তোমার সন্তানকে আল্লাহ তায়ালা তাঁর কিতাব ও প্রজ্ঞার বিষয়গুলো শেখাবেন, (তিনি তাকে) তাওরাত এবং ইনজীলও শিক্ষা দেবেন।', 'WayuAAallimuhu alkitaba waalhikmata waalttawrata waalinjeela', 1, NOW(), NOW()),
(3, 49, 'وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', '(আল্লাহ তায়ালা তাকে) বনী ইসরাঈলদের কাছে রসূল করে পাঠালেন (অতপর সে তাদের বললো), আমি নিসন্দেহে তোমাদের মালিকের কাছ থেকে (নবুওতের কিছু) নিদর্শন নিয়ে এসেছি (সে নিদর্শনগুলো হচ্ছে), আমি তোমাদের জন্যে মাটি দ্বারা পাখীর মতো করে একটি আকৃতি বানাবো এবং পরে আমি তাতে ফুঁ দেবো, অতপর আকৃতিটি আল্লাহর ইচ্ছায় (জীবন্ত) পাখী হয়ে যাবে, আর আমি জন্মান্ধ এবং কুষ্ঠ রোগীকেও সুস্থ করে দেবো, আল্লাহর ইচ্ছায় (এভাবে) আমি মৃতকেও জীবিত করে দেবো, আমি তোমাদের আরো বলে দেবো, তোমরা কি কি জিনিস খাও, আবার কি জিনিস (না খেয়ে) তোমাদের ঘরে জমা করে রাখো; (মূলত) তোমরা যদি (আল্লাহর ওপর) ঈমান আনো তাহলে অবশ্যই এতে তোমাদের জন্যে নিদর্শন রয়েছে।', 'Warasoolan ila banee israeela annee qad jitukum biayatin min rabbikum annee akhluqu lakum mina altteeni kahayati alttayri faanfukhu feehi fayakoonu tayran biithni Allahi waobrio alakmaha waalabrasa waohyee almawta biithni Allahi waonabbiokum bima takuloona wama taddakhiroona fee buyootikum inna fee thalika laayatan lakum in kuntum mumineena', 1, NOW(), NOW()),
(3, 50, 'وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', '(ঈসা আরও বললো,) তাওরাতের যে বাণী আমার কাছে রয়েছে আমি তার সত্যায়নকারী, (তা ছাড়া) তোমাদের ওপর হারাম করে রাখা হয়েছে এমন কতিপয় জিনিসও আমি তোমাদের জন্যে হালাল করে দেবো এবং আমি তোমাদের মালিকের পক্ষ থেকে (এ) নিদর্শন নিয়েই এসেছি, অতএব তোমরা আল্লাহকেই ভয় করো এবং আমার আনুগত্য করো।', 'Wamusaddiqan lima bayna yadayya mina alttawrati waliohilla lakum baAAda allathee hurrima AAalaykum wajitukum biayatin min rabbikum faittaqoo Allaha waateeAAooni', 1, NOW(), NOW()),
(3, 51, 'إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ', 'অবশ্যই আল্লাহ তায়ালা আমার রব, তোমাদেরও রব, অতএব তোমরা তাঁরই এবাদাত করো; (আর) এটাই হচ্ছে একমাত্র সঠিক ও সোজা পথ।', 'Inna Allaha rabbee warabbukum faoAAbudoohu hatha siratun mustaqeemun', 1, NOW(), NOW()),
(3, 52, '۞فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ', 'অতপর ঈসা যখন তাদের থেকে কুফরী আঁচ করতে পারলো, তখন সে (সাথীদের ডেকে) বললো, কে আছো তোমরা) আল্লাহ তায়ালার পথে আমার সাহায্যকারী হবে! হাওয়ারীরা বললো, (হ্যাঁ) আমরাই আল্লাহর সাহায্যকারী; আমরা আল্লাহর ওপর ঈমান এনেছি, তুমি সাক্ষী থাকো, আমরা সবাই তাঁর (এক একজন) অনুগত বান্দা।', 'Falamma ahassa AAeesa minhumu alkufra qala man ansaree ila Allahi qala alhawariyyoona nahnu ansaru Allahi amanna biAllahi waishhad bianna muslimoona', 1, NOW(), NOW()),
(3, 53, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ', '(হাওয়ারীরা বললো,) হে আমাদের রব, তুমি যা কিছু নাযিল করেছো আমরা তার ওপর ঈমান এনেছি এবং আমরা রসূলের কথাও মেনে নিয়েছি, সুতরাং তুমি (সত্যের) সাক্ষ্যদাতাদের সাথে আমাদের (নাম) লিখে দাও।', 'Rabbana amanna bima anzalta waittabaAAna alrrasoola faoktubna maAAa alshshahideena', 1, NOW(), NOW()),
(3, 54, 'وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ', '(বনী ইসরাঈলের) লোকেরা (নবীর) বিরুদ্ধে শঠতা করলো, তাই আল্লাহও কৌশলের পন্থা গ্রহণ করলেন; (বস্তুত) আল্লাহ তায়ালাই হচ্ছেন সর্বোত্তম কৌশলী!', 'Wamakaroo wamakara Allahu waAllahu khayru almakireena', 1, NOW(), NOW()),
(3, 55, 'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', 'যখন আল্লাহ তায়ালা বললেন, হে ঈসা, আমি তোমার এ দুনিয়ার (জীবন কাটানোর) কাল শেষ করতে যাচ্ছি এবং (অচিরেই) আমি তোমাকে আমার কাছে তুলে আনবো, যারা অস্বীকার করেছে তাদের (যাবতীয় পাপ) থেকেও আমি তোমাকে পবিত্র করে নেবো, আর যারা তোমাকে অনুসরণ করছে তাদের আমি কেয়ামত পর্যন্ত এ অস্বীকারকারীদের ওপর (বিজয়ী করে) রাখবো, অতপর তোমাদের ফিরে যাবার জায়গা তো আমার কাছেই, সেদিন (ঈসা সম্পর্কিত) যেসব বিষয় নিয়ে তোমরা মতবিরোধে লিপ্ত ছিলে তার সব কয়টি বিষয়ই আমি তোমাদের মাঝে মীমাংসা করে দেবো।', 'Ith qala Allahu ya AAeesa innee mutawaffeeka warafiAAuka ilayya wamutahhiruka mina allatheena kafaroo wajaAAilu allatheena ittabaAAooka fawqa allatheena kafaroo ila yawmi alqiyamati thumma ilayya marjiAAukum faahkumu baynakum feema kuntum feehi takhtalifoona', 1, NOW(), NOW()),
(3, 56, 'فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ', 'যারা (আমার বিধান) অস্বীকার করেছে আমি তাদের এ দুনিয়ায় (অপমান) ও আখেরাতে (আগুনে দগ্ধ হওয়ার) কঠোরতর শাস্তি দেবো, (এ থেকে বাঁচানোর মতো সেদিন) তাদের কোনো সাহায্যকারী থাকবে না।', 'Faamma allatheena kafaroo faoAAaththibuhum AAathaban shadeedan fee alddunya waalakhirati wama lahum min nasireena', 1, NOW(), NOW()),
(3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ', 'অপরদিকে যারা (আল্লাহর ওপর) ঈমান এনেছে এবং ভালো কাজ করেছে, অতপর আল্লাহ তাদের (সবাই)-কে তাদের পাওনাসমূহ পুরোপুরিই আদায় করে দেবেন; আল্লাহ তায়ালা যালেমদের (কখনো) ভালোবাসেন না।', 'Waamma allatheena amanoo waAAamiloo alssalihati fayuwaffeehim ojoorahum waAllahu la yuhibbu alththalimeena', 1, NOW(), NOW()),
(3, 58, 'ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ', 'এই কিতাব যা আমি তোমাকে পড়ে শোনাচ্ছি, তা হচ্ছে (আল্লাহর) নিদর্শন ও জ্ঞানপূর্ণ উপদেশ বিশেষ।', 'Thalika natloohu AAalayka mina alayati waalththikri alhakeemi', 1, NOW(), NOW()),
(3, 59, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', 'আল্লাহ তয়ালার কাছে ঈসার উদাহরণ হচ্ছে (প্রথম মানুষ) আদমের মতো; তাকে তিনি (মাতা-পিতা ছাড়া) মাটি থেকে পয়দা করেছেন, তারপর তাকে বললেন, হয়ে যাও, সাথে সাথে তা (মানুষে পরিণত) হয়ে গেলো।', 'Inna mathala AAeesa AAinda Allahi kamathali adama khalaqahu min turabin thumma qala lahu kun fayakoonu', 1, NOW(), NOW()),
(3, 60, 'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ', '(এ হচ্ছে) তোমার মালিকের পক্ষ থেকে (আসা) সত্য (প্রতিবেদন), অতপর তোমরা কখনো তাদের দলে শামিল হয়ো না যারা সন্দেহ পোষণ করে।', 'Alhaqqu min rabbika fala takun mina almumtareena', 1, NOW(), NOW()),
(3, 61, 'فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ', 'সে বিষয়ে (আল্লাহর কাছ থেকে সঠিক) জ্ঞান আসার পরও যদি কেউ তোমার সাথে (খামাখা) ঝগড়া-বিবাদ ও তর্ক করতে চায়, তাহলে তুমি তাদের বলে দাও, এসো আমরা আমাদের ছেলেদের ডাকবো এবং তোমাদের ছেলেদের ডাকবো, (আমরা ডাকবো) আমাদের নারীদের এবং তোমাদের নারীদেরও, (সাথে) আমরা আমাদের নিজে দের এবং তোমাদেরও (এক সাথে জড়ো হওয়ার জন্যে) ডাক দেবো, অতপর আমরা বিনীতভাবে দোয়া করবো, (আমাদের মধ্যে) যে মিথ্যাবাদী তার ওপর যেন আল্লাহর অভিশাপ বর্ষিত হয়।', 'Faman hajjaka feehi min baAAdi ma jaaka mina alAAilmi faqul taAAalaw nadAAu abnaana waabnaakum wanisaana wanisaakum waanfusana waanfusakum thumma nabtahil fanajAAal laAAnata Allahi AAala alkathibeena', 1, NOW(), NOW()),
(3, 62, 'إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'এ হচ্ছে সঠিক (ও নির্ভুল) ঘটনা, আল্লাহ তায়ালা ছাড়া দ্বিতীয় কোনো মা’বুদ নেই; নিসন্দেহে আল্লাহ তায়ালা পরম শক্তিশালী ও প্রজ্ঞাময়।', 'Inna hatha lahuwa alqasasu alhaqqu wama min ilahin illa Allahu wainna Allaha lahuwa alAAazeezu alhakeemu', 1, NOW(), NOW()),
(3, 63, 'فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ', 'অতপর তারা যদি মুখ ফিরিয়ে নেয়, তাহলে (জেনে রাখো) আল্লাহ তায়ালা কলহ সৃষ্টিকারীদের (ভালো করেই) জানেন।', 'Fain tawallaw fainna Allaha AAaleemun bialmufsideena', 1, NOW(), NOW()),
(3, 64, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ', '(হে নবী,) তুমি বলো, হে কিতাবধারীরা, এসো আমরা এমন এক কথায় (একমত হই) যা আমাদের কাছে এক (অভিন্ন), আমরা উভয়েই আল্লাহ তায়ালা ছাড়া অন্য কারো এবাদাত করবো না এবং তাঁর সাথে অন্য কিছুকে অংশীদার বানাবো না, (সর্বোপরি) আল্লাহ তায়ালা ছাড়া আমরা আমাদের মাঝেও একে অপরকে প্রভু বলে মেনে নেবো না; অতপর তারা যদি (এ থেকে) মুখ ফিরিয়ে নেয় তাহলে তাদের তুমি বলে দাও, তোমরা সাক্ষী থেকো, আমরা (আল্লাহর সামনে) আনুগত্যের মাথা নত করে দিয়েছি।', 'Qul ya ahla alkitabi taAAalaw ila kalimatin sawain baynana wabaynakum alla naAAbuda illa Allaha wala nushrika bihi shayan wala yattakhitha baAAduna baAAdan arbaban min dooni Allahi fain tawallaw faqooloo ishhadoo bianna muslimoona', 1, NOW(), NOW()),
(3, 65, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ', '(তুমি বলো,) হে কিতাবধারীরা, তোমরা ইবরাহীম সম্পর্কে (অযথা) কেন (এই) তর্ক করো (যে, সে ইহুদী কিংবা খৃস্টান ছিলো), তাওরাত ও ইনজীল যে তার পরে নাযিল করা হয়েছে (সে ব্যাপারেই বা কেন তর্ক করো); তোমরা কি বুঝতে পারছো না?', 'Ya ahla alkitabi lima tuhajjoona fee ibraheema wama onzilati alttawratu waalinjeelu illa min baAAdihi afala taAAqiloona', 1, NOW(), NOW()),
(3, 66, 'هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', 'হ্যাঁ, এর কয়েকটি বিষয়ে তোমাদের (হয় তো) কিছু কিছু জানাশোনা ছিলো এবং সে বিষয়ে তোমরা অনেক তর্ক বিতর্কও করলে, কিন্তু যেসব বিষয়ে তোমাদের কোনো জ্ঞানই নেই; সেসব বিষয়ে তোমরা বিতর্কে লিপ্ত হচ্ছো কেন? আল্লাহ তায়ালাই (সব কিছু) জানেন, তোমরা কিছুই জানো না,', 'Haantum haolai hajajtum feema lakum bihi AAilmun falima tuhajjoona feema laysa lakum bihi AAilmun waAllahu yaAAlamu waantum la taAAlamoona', 1, NOW(), NOW()),
(3, 67, 'مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', '(সঠিক ঘটনা হচ্ছে,) ইবরাহীম ইহুদীও ছিলো না- খৃস্টানও ছিলো না; বরং সে ছিলো একজন একনিষ্ঠ মুসলিম; সে কখনো মোশরেকদের দলভুক্ত ছিলো না।', 'Ma kana ibraheemu yahoodiyyan wala nasraniyyan walakin kana haneefan musliman wama kana mina almushrikeena', 1, NOW(), NOW()),
(3, 68, 'إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ', 'মানুষদের মাঝে ইবরাহীমের সাথে (ঘনিষ্ঠতম) সম্পর্কের বেশী অধিকার তো আছে সেসব লোকের, যারা তার অনুসরণ করেছে, (আসলে) এ নবী ও (তার ওপর) ঈমান আনয়নকারীরাই (হচ্ছে) ইবরাহীমের ঘনিষ্ঠতম ব্যক্তি; আল্লাহ তায়ালাই হচ্ছেন ঈমানদারদের একমাত্র সাহায্যকারী।', 'Inna awla alnnasi biibraheema lallatheena ittabaAAoohu wahatha alnnabiyyu waallatheena amanoo waAllahu waliyyu almumineena', 1, NOW(), NOW()),
(3, 69, 'وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', 'এ কিতাবধারীদের একটি দল তোমাদের কোনো না কোনোভাবে পথভ্রষ্ট করে দিতে চায়; তাদের এ বোধটুকু নেই যে, (তাদের এসব কর্মপন্থা) তাদের নিজেদের ছাড়া অন্য কোনো ব্যক্তিকেই পথভ্রষ্ট করতে পারবে না।', 'Waddat taifatun min ahli alkitabi law yudilloonakum wama yudilloona illa anfusahum wama yashAAuroona', 1, NOW(), NOW()),
(3, 70, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ', 'হে কিতাবধারীরা, তোমরা কেন আল্লাহর আয়াতসমূহকে অস্বীকার করছো, অথচ তোমরা নিজেরাই (এর সত্যতার) সাক্ষ্য দিচ্ছো।', 'Ya ahla alkitabi lima takfuroona biayati Allahi waantum tashhadoona', 1, NOW(), NOW()),
(3, 71, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ', 'হে কিতাবধারীরা, তোমরা কেন ‘হক’-কে বাতিলের সাথে মিশিয়ে দিচ্ছো, (এতে করে) তোমরা তো সত্যই গোপন করছো, অথচ (এটা যে সত্যের পরিপন্থী) তা তোমরা জানো।', 'Ya ahla alkitabi lima talbisoona alhaqqa bialbatili wataktumoona alhaqqa waantum taAAlamoona', 1, NOW(), NOW()),
(3, 72, 'وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ', 'আহলে কিতাবদের (মধ্য থেকে) একদল লোক (তাদের নিজেদের লোকদের) বলে, মুসলমানদের ওপর যা কিছু অবতীর্ণ হয়েছে তোমরা সকাল বেলায় তার ওপর ঈমান আনো এবং বিকেল বেলায় তা অস্বীকার করো, সম্ভবত তারা (এর ফলে ঈমান থেকে) ফিরে আসবে।', 'Waqalat taifatun min ahli alkitabi aminoo biallathee onzila AAala allatheena amanoo wajha alnnahari waokfuroo akhirahu laAAallahum yarjiAAoona', 1, NOW(), NOW()),
(3, 73, 'وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', 'যারা তোমাদের জীবনবিধানের অনুসরণ করে, এমন সব লোকজন ছাড়া অন্য কারো কথাই তোমরা মেনে নিয়ো না; (হে নবী,) তুমি বলে দাও, একমাত্র হেদায়াত হচ্ছে আল্লাহর হেদায়াত, (তোমরা একথা মনে করো না), তোমাদের যে ধরনের (ব্যবস্থা) দেয়া হয়েছে তেমন ধরনের কিছু অন্য কাউকেও দেয়া হবে অথবা (সে সূত্র ধরে) অন্য লোকেরা তোমাদের মালিকের দরবারে তোমাদের বিরুদ্ধে কোনো রকম যুক্তিতর্ক খাড়া করবে (হে নবী), তুমি তাদের বলে দাও, (হেদায়াতের এ) অনুগ্রহ অবশ্যই আল্লাহর হাতে, তিনি যাকে ইচ্ছা তাকেই তা দান করেন; আল্লাহ তায়ালা বিশাল, প্রজ্ঞাসম্পন্ন।', 'Wala tuminoo illa liman tabiAAa deenakum qul inna alhuda huda Allahi an yuta ahadun mithla ma ooteetum aw yuhajjookum AAinda rabbikum qul inna alfadla biyadi Allahi yuteehi man yashao waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(3, 74, 'يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ', 'নিজের দয়া দিয়ে তিনি যাকে ইচ্ছা তাকেই (হেদায়াতের জন্যে) নিদৃষ্ট করে নেন; আল্লাহ তায়ালা হচ্ছেন অসীম দয়া ও অনুগ্রহের মালিক।', 'Yakhtassu birahmatihi man yashao waAllahu thoo alfadli alAAatheemi', 1, NOW(), NOW()),
(3, 75, '۞وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ', 'আহলে কেতাবদের মধ্যে এমন লোকও আছে, তুমি যদি তার কাছে ধন সম্পদের এক স্তূপও আমানত রাখো, সে (চাওয়া মাত্রই) তা তোমাকে ফেরত দেবে, আবার এদের মধ্যে এমন কিছু (লোকও) আছে যার কাছে যদি একটি দীনারও তুমি রাখো, সে তা তোমাকে ফিরিয়ে দেবে না, হ্যাঁ, যদি (এ জন্যে) তুমি তার ওপর চেপে বসতে পারো (তাহলে সেটা ভিন্ন), এটা এই কারণে যে, এরা বলে, এই (অ-ইহুদী) অশিক্ষিত লোকদের ব্যাপারে আমাদের ওপর কোনো বাধ্যবাধকতা নেই, এরা (আসলে) বুঝে শুনে আল্লাহর ওপর মিথ্যা কথা বলে।', 'Wamin ahli alkitabi man in tamanhu biqintarin yuaddihi ilayka waminhum man in tamanhu bideenarin la yuaddihi ilayka illa ma dumta AAalayhi qaiman thalika biannahum qaloo laysa AAalayna fee alommiyyeena sabeelun wayaqooloona AAala Allahi alkathiba wahum yaAAlamoona', 1, NOW(), NOW()),
(3, 76, 'بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ', 'অবশ্য যে ব্যক্তি আল্লাহর (সাথে সম্পাদিত) প্রতিশ্রুতি রক্ষা করে এবং (সে ব্যাপারে) সাবধানতা অবলম্বন করে, (তাদের জন্যে সুখবর হচ্ছে) আল্লাহ তায়ালা তাকওয়া অবলম্বনকারীদের ভালোবাসেন।', 'Bala man awfa biAAahdihi waittaqa fainna Allaha yuhibbu almuttaqeena', 1, NOW(), NOW()),
(3, 77, 'إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'অবশ্যই যারা আল্লাহর (সাথে সম্পাদিত) প্রতিশ্রুতি ও শপথসমূহ সামান্য (বৈষয়িক) মূল্যে বিক্রি করে দেয়, পরকালে (আল্লাহর পুরস্কারের) কোনো অংশই তাদের জন্যে থাকবে না, এদের সাথে আল্লাহ তায়ালা কোনো কথাবার্তা বলবেন না, তিনি তাদের দিকে তাকিয়ে দেখবেন না এবং তিনি তাদের পাক পবিত্রও করবেন না, এদের জন্যে রয়েছে কঠোর পীড়াদায়ক আযাব।', 'Inna allatheena yashtaroona biAAahdi Allahi waaymanihim thamanan qaleelan olaika la khalaqa lahum fee alakhirati wala yukallimuhumu Allahu wala yanthuru ilayhim yawma alqiyamati wala yuzakkeehim walahum AAathabun aleemun', 1, NOW(), NOW()),
(3, 78, 'وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ', 'এদের মধ্যে এমন কিছু লোকও আছে, যারা কিতাবের কোনো অংশ যখন পড়ে তখন নিজেদের জিহ্বা এমনভাবে এদিক-সেদিক করে নেয়, যাতে তোমরা মনে করো, সত্যি বুঝি তা কিতাবের কোনো অংশ, কিন্তু (আসলে) তা কিতাবের কোনো অংশই নয়, তারা আরো বলে, এটা আল্লাহর কাছ থেকেই এসেছে, কিন্তু তা আল্লাহর কাছ থেকে আসা কিছু নয়, এরা জেনে শুনে আল্লাহর ওপর মিথ্যা কথা বলে চলেছে।', 'Wainna minhum lafareeqan yalwoona alsinatahum bialkitabi litahsaboohu mina alkitabi wama huwa mina alkitabi wayaqooloona huwa min AAindi Allahi wama huwa min AAindi Allahi wayaqooloona AAala Allahi alkathiba wahum yaAAlamoona', 1, NOW(), NOW()),
(3, 79, 'مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ', 'কোনো মানব সন্তানের পক্ষেই এটা (সম্ভব) নয়, আল্লাহ তায়ালা তাকে তাঁর কিতাব, প্রজ্ঞা ও নবুওত দান করবেন, অতপর সে লোকদের বলবে, তোমরা আল্লাহকে ছেড়ে সবাই আমার বান্দা হয়ে যাও, বরং সে (তো এ কথাই) বলবে, তোমরা সবাই তোমাদের মালিকের বান্দা হয়ে যাও, কেননা তোমরাই মানুষদের (এই) কিতাব শেখাচ্ছিলে এবং তোমরা নিজেরাও (তা) অধ্যয়ন করছিলে।', 'Ma kana libasharin an yutiyahu Allahu alkitaba waalhukma waalnnubuwwata thumma yaqoola lilnnasi koonoo AAibadan lee min dooni Allahi walakin koonoo rabbaniyyeena bima kuntum tuAAallimoona alkitaba wabima kuntum tadrusoona', 1, NOW(), NOW()),
(3, 80, 'وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ', 'আল্লাহর ফেরেশতা ও তাঁর নবীদের রব হিসেবে স্বীকার করে নিতে এ ব্যক্তি তোমাদের কখনো আদেশ দেবে না; একবার আল্লাহর অনুগত মুসলমান হবার পর সে কিভাবে তোমাদের পুনরায় কুফরীর আদেশ দিতে পারে?', 'Wala yamurakum an tattakhithoo almalaikata waalnnabiyyeena arbaban ayamurukum bialkufri baAAda ith antum muslimoona', 1, NOW(), NOW()),
(3, 81, 'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ', 'আল্লাহ তায়ালা যখন তাঁর নবীদের কাছ থেকে প্রতিশ্রুতি নিয়েছিলেন (তখন তিনি বলেছিলেন, এ হচ্ছে) কিতাব ও (তার ব্যবহারিক) জ্ঞান কৌশল, যা আমি তোমাদের দান করলাম, অতপর তোমাদের কাছে যখন (আমার কোনো) রসূল আসবে, যে তোমাদের কাছে রক্ষিত (আগের) কিতাবের সত্যায়ন করবে, তখন তোমরা অবশ্যই তার (আনীত বিধানের) ওপর ঈমান আনবে এবং তাকে সাহায্য করবে; তিনি জিজ্ঞেস করলেন, তোমরা কি অংগীকার গ্রহণ করছো এবং আমার এ প্রতিশ্রুতির দায়িত্ব পালন করছো? তারা বললো, হ্যাঁ আমরা অংগীকার করছি; তিনি বললেন, তাহলে তোমরা সাক্ষী থেকো এবং আমিও তোমাদের সাথে (এ অংগীকারে) সাক্ষী হয়ে রইলাম।', 'Waith akhatha Allahu meethaqa alnnabiyyeena lama ataytukum min kitabin wahikmatin thumma jaakum rasoolun musaddiqun lima maAAakum latuminunna bihi walatansurunnahu qala aaqrartum waakhathtum AAala thalikum isree qaloo aqrarna qala faishhadoo waana maAAakum mina alshshahideena', 1, NOW(), NOW()),
(3, 82, 'فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', 'এরপর যারা (এ থেকে) মুখ ফিরিয়ে নেবে, তারা অবশ্যই বিদ্রোহী (বলে বিবেচিত হবে)।', 'Faman tawalla baAAda thalika faolaika humu alfasiqoona', 1, NOW(), NOW()),
(3, 83, 'أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ', 'তারা কি আল্লাহর (দেয়া জীবন) ব্যবস্থার বদলে অন্য কোনো বিধানের সন্ধান করছে? অথচ আসমানসমূহ ও যমীনে যা কিছু আছে তা ইচ্ছায় হোক কিংবা অনিচ্ছায় হোক, আল্লাহ তায়ালার সামনে আত্মসমর্পণ করে আছে এবং প্রত্যেককে তো (একদিন) তাঁর কাছেই ফিরিয়ে নেয়া হবে।', 'Afaghayra deeni Allahi yabghoona walahu aslama man fee alssamawati waalardi tawAAan wakarhan wailayhi yurjaAAoona', 1, NOW(), NOW()),
(3, 84, 'قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ', '(হে নবী,) তুমি বলো, আমরা আল্লাহর ওপর ঈমান এনেছি, ঈমান এনেছি আমাদের ওপর যা নাযিল করা হয়েছে তার ওপর- ইবরাহীম, ইসমাঈল, ইসহাক, ইয়াকুব ও তাদের অন্যান্য বংশধরদের প্রতি যা কিছু নাযিল করা হয়েছে তার ওপরও, আমরা ঈমান এনেছি, মূসা, ঈসা এবং অন্য নবীদের কাছে তাঁদের মালিকের পক্ষ থেকে যা কিছু দেয়া হয়েছে তার ওপরও, নবীদের কারো মাঝেই আমরা কোনো ধরনের তারতম্য করি না, (মূলত) আমরা সবাই হচ্ছি (তাঁর) কাছে আত্মসমর্পণকারী।', 'Qul amanna biAllahi wama onzila AAalayna wama onzila AAala ibraheema waismaAAeela waishaqa wayaAAqooba waalasbati wama ootiya moosa waAAeesa waalnnabiyyoona min rabbihim la nufarriqu bayna ahadin minhum wanahnu lahu muslimoona', 1, NOW(), NOW()),
(3, 85, 'وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ', 'যদি কেউ ইসলাম ছাড়া অন্য কোনো জীবন বিধান অনুসন্ধান করে তবে তার কাছ থেকে সে (উদ্ভাবিত) ব্যবস্থা কখনো গ্রহণ করা হবে না, পরকালে সে চরম ব্যর্থ হবে।', 'Waman yabtaghi ghayra alislami deenan falan yuqbala minhu wahuwa fee alakhirati mina alkhasireena', 1, NOW(), NOW()),
(3, 86, 'كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'যারা ঈমানের (আলো পাওয়ার) পর কুফরী করেছে, আল্লাহ তায়ালা তাদের কিভাবে (আবার আলোর) পথ প্রদর্শন করবেন, অথচ (এর আগে) এরাই সাক্ষ্য দিয়েছিলো যে, আল্লাহর রসূল সত্য এবং (রসূলের মাধ্যমে) এদের কাছে উজ্জ্বল নিদর্শনসমূহ এসেছিলো; (আসলে) আল্লাহ তায়ালা কখনো যালিমদের সঠিক পথ দেখান না।', 'Kayfa yahdee Allahu qawman kafaroo baAAda eemanihim washahidoo anna alrrasoola haqqun wajaahumu albayyinatu waAllahu la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(3, 87, 'أُوْلَـٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ', 'এরাই হচ্ছে সেসব লোক যাদের কার্যকলাপের একমাত্র প্রতিদান হচ্ছে, তাদের ওপর আল্লাহ তায়ালা, তাঁর ফেরেশতা ও অন্য সব মানুষের অভিশাপ (বর্ষিত হবে)।', 'Olaika jazaohum anna AAalayhim laAAnata Allahi waalmalaikati waalnnasi ajmaAAeena', 1, NOW(), NOW()),
(3, 88, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ', '(আর সে অভিশপ্ত স্থান হচ্ছে জাহান্নাম,) সেখানে তারা অনাদিকাল ধরে পড়ে থাকবে, তাদের (ওপর) থেকে শাস্তির মাত্রা কমানো হবে না, না আযাব থেকে তাদের (কোনো রকম) বিরাম দেয়া হবে!', 'Khalideena feeha la yukhaffafu AAanhumu alAAathabu wala hum yuntharoona', 1, NOW(), NOW()),
(3, 89, 'إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', 'আর তাদের কথা আলাদা, যারা (এসব কিছুর পর) তাওবা করেছে এবং (তারপর) নিজেদের সংশোধন করে নিয়েছে, আল্লাহ তায়ালা অবশ্যই ক্ষমাশীল ও পরম দয়ালু।', 'Illa allatheena taboo min baAAdi thalika waaslahoo fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(3, 90, 'إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ', 'অবশ্যই যারা একবার ঈমান আনার পর কুফরীর (পথ) অবলম্বন করেছে, অতপর তারা এই বেঈমানী (কার্যকলাপ) দিন দিন বাড়াতেই থেকেছে, (আল্লাহর দরবারে) তাদের তাওবা কখনো কবুল হবে না, কারণ এ ধরনের লোকেরাই হচ্ছে পথভ্রষ্ট।', 'Inna allatheena kafaroo baAAda eemanihim thumma izdadoo kufran lan tuqbala tawbatuhum waolaika humu alddalloona', 1, NOW(), NOW()),
(3, 91, 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّـٰصِرِينَ', 'অবশ্যই যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে এবং কুফরী অবস্থায়ই তাদের মৃত্যু হয়েছে, তারা যদি নিজে দের (আল্লাহর আযাব থেকে) বাঁচানোর জন্যে এক পৃথিবী পূর্ণ স্বর্ণও মুক্তিপণ হিসেবে খরচ করে, তবু তাদের কারো কাছ থেকে তা গ্রহণ করা হবে না; বস্তুত এরাই হচ্ছে সে সব (হতভাগ্য) ব্যক্তি, যাদের জন্যে মর্মন্তুদ আযাব রয়েছে, আর সেদিন তাদের কোনো সাহায্যকারীও থাকবে না।', 'Inna allatheena kafaroo wamatoo wahum kuffarun falan yuqbala min ahadihim milo alardi thahaban walawi iftada bihi olaika lahum AAathabun aleemun wama lahum min nasireena', 1, NOW(), NOW()),
(3, 92, 'لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ', 'তোমরা কখনো (যথার্থ) নেকী অর্জন করতে পারবে না, যতোক্ষণ না তোমরা এমন কিছু থেকে (আল্লাহর পথে) ব্যয় করবে যা তোমরা ভালোবাসো; (মূলত) তোমরা যা কিছুই ব্যয় করো, আল্লাহ তায়ালা অবশ্যই তা জানেন।', 'Lan tanaloo albirra hatta tunfiqoo mimma tuhibboona wama tunfiqoo min shayin fainna Allaha bihi AAaleemun', 1, NOW(), NOW()),
(3, 93, '۞كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَـٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَـٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ', '(আসলে) সব খাবারই বনী ইসরাঈলদের জন্যে হালাল ছিলো, (অবশ্য) এমন (দু’একটা) জিনিস বাদে, যা তাওরাত নাযিল হওয়ার আগেই ইসরাঈল তার নিজের ওপর হারাম করে রেখেছিলো; তুমি বলো, (যাও) তোমরা তাওরাত নিয়ে এসো এবং তা পড়ো, যদি (তোমরা) সত্যবাদী হও!', 'Kullu alttaAAami kana hillan libanee israeela illa ma harrama israeelu AAala nafsihi min qabli an tunazzala alttawratu qul fatoo bialttawrati faotlooha in kuntum sadiqeena', 1, NOW(), NOW()),
(3, 94, 'فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'এরপরও যারা এ বিষয় নিয়ে আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করে, তারাই হচ্ছে যালেম।', 'Famani iftara AAala Allahi alkathiba min baAAdi thalika faolaika humu althalimoona', 1, NOW(), NOW()),
(3, 95, 'قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', 'তুমি বলো, আল্লাহ তায়ালা সত্য কথা বলেছেন, অতএব তোমরা সবাই নিষ্ঠার সাথে ইবরাহীমের মতাদর্শ অনুসরণ করো, আর ইবরাহীম কখনো মোশরেকদের (দলে) শামিল ছিলো না।', 'Qul sadaqa Allahu faittabiAAoo millata ibraheema haneefan wama kana mina almushrikeena', 1, NOW(), NOW()),
(3, 96, 'إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ', 'নিশ্চয়ই গোটা মানব জাতির জন্যে সর্বপ্রথম যে ঘরটি (বানিয়ে) রাখা হয়েছিলো তা ছিলো বাক্কায় (মক্কা নগরীতে), এ ঘর হচ্ছে মানবকূলের জন্যে কল্যাণ ও হেদায়াত।', 'Inna awwala baytin wudiAAa lilnnasi lallathee bibakkata mubarakan wahudan lilAAalameena', 1, NOW(), NOW()),
(3, 97, 'فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ', 'এখানে রয়েছে (আল্লাহ তায়ালার) সুস্পষ্ট নিদর্শনসমূহ, রয়েছে ইবরাহীমের দাঁড়ানোর স্থান, (এই ঘরের বিশেষ মর্যাদা হচ্ছে), যে এখানে প্রবেশ করবে সে নিরাপদ (হয়ে যাবে, দ্বিতীয় মর্যাদা হচ্ছে); মানব জাতির ওপর আল্লাহর হুকুম পালনের জন্যে (তাদের) এই দায়িত্ব দেয়া হয়েছে, যে ব্যক্তিরই এ ঘর পর্যন্ত পৌঁছার সামর্থ থাকবে, সে যেন এই ঘরের হজ্জ আদায় করে, আর যদি কেউ (এ বিধান) অস্বীকার করে (তার জেনে রাখা উচিত), আল্লাহ তায়ালা সৃষ্টিকুলের মুখাপেক্ষী নন।', 'Feehi ayatun bayyinatun maqamu ibraheema waman dakhalahu kana aminan walillahi AAala alnnasi hijju albayti mani istataAAa ilayhi sabeelan waman kafara fainna Allaha ghaniyyun AAani alAAalameena', 1, NOW(), NOW()),
(3, 98, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ', '(হে নবী!) তুমি বলো, হে আহলে কিতাবরা, তোমরা কেন (জেনে বুঝে) আল্লাহর আয়াতসমূহকে অস্বীকার করো, তোমরা যা কিছু করো আল্লাহ তায়ালাই তার ওপর সাক্ষী।', 'Qul ya ahla alkitabi lima takfuroona biayati Allahi waAllahu shaheedun AAala ma taAAmaloona', 1, NOW(), NOW()),
(3, 99, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجٗا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'তুমি (আরো) বলো, হে আহলে কিতাবরা, তোমরা কেন তাদের আল্লাহর পথ থেকে ফেরাতে চেষ্টা করছো যারা ঈমান এনেছে, (কেনই বা) তোমরা তাকে বাঁকা পথে ধাবিত করতে চাও, অথচ (এই লোকদের সত্যপন্থী হবার ওপর) তোমরাই সাক্ষী; আল্লাহ তায়ালা তোমাদের (বিদ্রোহমূলক) আচরণ সম্পর্কে মোটেই উদাসীন নন।', 'Qul ya ahla alkitabi lima tasuddoona AAan sabeeli Allahi man amana tabghoonaha AAiwajan waantum shuhadao wama Allahu bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(3, 100, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ', 'হে মানুষ- তোমরা যারা ঈমান এনেছো (আগে) যাদের কিতাব দেয়া হয়েছে তোমরা যদি তাদের কোনো একটি দলের কথা মেনে চলো, তাহলে এরা ঈমান আনার পরও তোমাদের কুফরীর দিকে ফিরিয়ে দেবে।', 'Ya ayyuha allatheena amanoo in tuteeAAoo fareeqan mina allatheena ootoo alkitaba yaruddookum baAAda eemanikum kafireena', 1, NOW(), NOW()),
(3, 101, 'وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আর তোমরা কিভাবে কুফরী করবে, অথচ তোমাদের সামনে (বার বার) আল্লাহর আয়াতসমূহ তেলাওয়াত করা হচ্ছে, তাছাড়া (আয়াতের বাহক স্বয়ং) তাঁর রসূল যখন তোমাদের মাঝেই মজুদ রয়েছে, যে ব্যক্তিই আল্লাহ (ও তাঁর বিধান)-কে শক্ত করে আঁকড়ে ধরবে, অবশ্যই তাকে সোজা পথে পরিচালিত করা হবে।', 'Wakayfa takfuroona waantum tutla AAalaykum ayatu Allahi wafeekum rasooluhu waman yaAAtasim biAllahi faqad hudiya ila siratin mustaqeemin', 1, NOW(), NOW()),
(3, 102, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, আল্লাহকে ভয় করো, ঠিক যতোটুকু ভয় তাঁকে করা উচিত, (তাঁর কাছে সম্পূর্ণ) আত্মসমর্পণকারী না হয়ে তোমরা কখনো মৃত্যু বরণ করো না।', 'Ya ayyuha allatheena amanoo ittaqoo Allaha haqqa tuqatihi wala tamootunna illa waantum muslimoona', 1, NOW(), NOW()),
(3, 103, 'وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ', 'তোমরা সবাই মিলে আল্লাহর রশি (কোরআন)-কে শক্ত করে আঁকড়ে ধরো এবং কখনো পরস্পর বিচ্ছিন্ন হয়ো না, তোমরা তোমাদের ওপর আল্লাহর (সেই) নেয়ামতের কথা -রণ করো, যখন তোমরা একে অপরের দুশমন ছিলে, অতপর তিনি (দ্বীনের বন্ধন দিয়ে) তোমাদের উভয়ের মনের মাঝে ভালোবাসার সঞ্চার করে দিলেন, অতপর (শত্রুতা ভুলে) তোমরা তাঁর অনুগ্রহে একে অপরের ‘ভাই’ হয়ে গেলে, অথচ তোমরা ছিলে (হানাহানির) অগ্নিকুন্ডের প্রান্তসীমায়, অতপর সেখান থেকে তিনি তোমাদের উদ্ধার করলেন; আল্লাহ তায়ালা এভাবেই তাঁর আয়াতসমূহ তোমাদের কাছে স্পষ্ট করে বর্ণনা করেন, আশা করা যায়, তোমরা সঠিক পথ পেয়ে যাবে।', 'WaiAAtasimoo bihabli Allahi jameeAAan wala tafarraqoo waothkuroo niAAmata Allahi AAalaykum ith kuntum aAAdaan faallafa bayna quloobikum faasbahtum biniAAmatihi ikhwanan wakuntum AAala shafa hufratin mina alnnari faanqathakum minha kathalika yubayyinu Allahu lakum ayatihi laAAallakum tahtadoona', 1, NOW(), NOW()),
(3, 104, 'وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'তোমাদের মধ্য থেকে এমন একটি দল থাকা উচিত, যারা (মানুষদের) কল্যাণের দিকে ডাকবে, (সত্য ও) ন্যায়ের আদেশ দেবে, আর (অসত্য ও অন্যায় কাজ থেকে (তাদের) বিরত রাখবে; এরাই হচ্ছে (সত্যিকারের) সফল।', 'Waltakun minkum ommatun yadAAoona ila alkhayri wayamuroona bialmaAAroofi wayanhawna AAani almunkari waolaika humu almuflihoona', 1, NOW(), NOW()),
(3, 105, 'وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ', 'তোমরা (কখনো) তাদের মতো হয়ো না, যাদের কাছে (আল্লাহর) সুস্পষ্ট নিদর্শন আসার পরও তারা বিভিন্ন দলে উপদলে বিভক্ত হয়ে পড়েছে এবং (নিজেদের মধ্যে) নানা মতানৈক্য সৃষ্টি করেছে; এরাই হচ্ছে সে সব মানুষ যাদের জন্যে কঠোর শাস্তি রয়েছে।', 'Wala takoonoo kaallatheena tafarraqoo waikhtalafoo min baAAdi ma jaahumu albayyinatu waolaika lahum AAathabun AAatheemun', 1, NOW(), NOW()),
(3, 106, 'يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ', '(কেয়ামতের) সে দিন (নিজেদের নেক আমল দেখে) কিছু সংখ্যক চেহারা শুভ্র সমুজ্জ্বল হয়ে যাবে, (আবার) কিছু সংখ্যক মানুষের চেহারা (ব্যর্থতার নথিপত্র দেখার পর) কালো (বিশ্রী) হয়ে পড়বে, যাদের মুখ কালো হয়ে যাবে (জাহান্নামের প্রহরীরা তাদের জিজ্ঞেস করবে), ঈমানের (নেয়ামত পাওয়ার) পরও কি তোমরা কুফরীর পথ অবলম্বন করেছিলে? অতপর তোমরা নিজেদের কুফরীর প্রতিফল (হিসেবে এ) আযাব উপভোগ করতে থাকো!', 'Yawma tabyaddu wujoohun wataswaddu wujoohun faamma allatheena iswaddat wujoohuhum akafartum baAAda eemanikum fathooqoo alAAathaba bima kuntum takfuroona', 1, NOW(), NOW()),
(3, 107, 'وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'আর যাদের চেহারা আলোকোজ্জ্বল হবে, তারা (সেদিন) আল্লাহ তায়ালার (অফুরন্ত) দয়ার আশ্রয়ে থাকবে, তারা সেখানে থাকবে চিরদিন।', 'Waamma allatheena ibyaddat wujoohuhum fafee rahmati Allahi hum feeha khalidoona', 1, NOW(), NOW()),
(3, 108, 'تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ', 'এগুলো হচ্ছে আল্লাহ তায়ালার আয়াত, আমি সেগুলো যথাযথভাবে তোমাকে পড়ে শোনাচ্ছি; আল্লাহ তায়ালা (তাঁর আয়াতসমূহ গোপন রেখে তার জন্যে শাস্তি দিয়ে) সৃষ্টিকুলের ওপর কোনো যুলুম করতে চান না।', 'Tilka ayatu Allahi natlooha AAalayka bialhaqqi wama Allahu yureedu thulman lilAAalameena', 1, NOW(), NOW()),
(3, 109, 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', 'আসমানসমূহ ও যমীনে যা কিছু আছে সবই আল্লাহর জন্যে; সব কিছুকে একদিন আল্লাহর দিকেই ফিরিয়ে দেয়া হবে।', 'Walillahi ma fee alssamawati wama fee alardi waila Allahi turjaAAu alomooru', 1, NOW(), NOW()),
(3, 110, 'كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ', 'তোমরা (হচ্ছো) সর্বোত্তম জাতি, সমগ্র মানব জাতির (কল্যাণের) জন্যেই তোমাদের বের করে আনা হয়েছে, (তোমাদের দায়িত্ব হচ্ছে) তোমরা দুনিয়ার মানুষদের সৎ কাজের আদেশ দেবে এবং অসৎ কাজ থেকে বিরত রাখবে, আর তোমরা নিজেরাও আল্লাহর ওপর ঈমান আনবে, আহলে কিতাবরা যদি ঈমান আনতো তাহলে এটা তাদের জন্যে ভালোই হতো; তাদের মধ্যে কিছু ঈমানদার ব্যক্তিও রয়েছে, (তবে) তাদের অধিকাংশই হচ্ছে অপরাধী।', 'Kuntum khayra ommatin okhrijat lilnnasi tamuroona bialmaAAroofi watanhawna AAani almunkari watuminoona biAllahi walaw amana ahlu alkitabi lakana khayran lahum minhumu almuminoona waaktharuhumu alfasiqoona', 1, NOW(), NOW()),
(3, 111, 'لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ', 'সামান্য কিছু দুঃখ কষ্ট দেয়া ছাড়া তারা তোমাদের কখনো কোনো ক্ষতি করতে পারবে না, তারা যদি কোনো সময় তোমাদের সাথে সম্মুখসমরে লিপ্ত হয়, তাহলে তারা পৃষ্ঠ প্রদর্শন করবে, অতপর তাদের আর সাহায্য করা হবে না।', 'Lan yadurrookum illa athan wain yuqatilookum yuwallookumu aladbara thumma la yunsaroona', 1, NOW(), NOW()),
(3, 112, 'ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', 'যেখানেই এদের পাওয়া যাবে সেখানেই এদের অপমানিত ও লাঞ্ছিত করে রাখা হবে, তবে আল্লাহ তায়ালার নিজের প্রতিশ্রুতি ও মানুষের প্রতিশ্রুতি (-র মাধ্যমে পাওয়া নিরাপত্তা) ভিন্ন কথা, এরা (আল্লাহর ক্রোধ ও) গযবের পাত্র হয়েছে, এদের ওপর দারিদ্র (ও লাঞ্ছনা) চাপিয়ে দেয়া হয়েছে; কেননা, এরা আল্লাহ তায়ালার আয়াতসমূহকে অস্বীকার করছিলো, এরা অন্যায়ভাবে (আল্লাহর) নবীদের হত্যা করছিলো; এর (আরো) কারণ হচ্ছে, এরা বিদ্রোহ করেছে এবং এরা সীমালংঘন করে চলতো।', 'Duribat AAalayhimu alththillatu ayna ma thuqifoo illa bihablin mina Allahi wahablin mina alnnasi wabaoo bighadabin mina Allahi waduribat AAalayhimu almaskanatu thalika biannahum kanoo yakfuroona biayati Allahi wayaqtuloona alanbiyaa bighayri haqqin thalika bima AAasaw wakanoo yaAAtadoona', 1, NOW(), NOW()),
(3, 113, '۞لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ', 'তারা (আবার) সবাই এক রকম নয়, আহলে কিতাবদের মধ্যে এমন কিছু লোকও আছে; যারা (ন্যায়ের ওপর) দাঁড়িয়ে আছে, যারা রাতভর আল্লাহর আয়াতসমূহ তেলাওয়াত করে এবং তারা (তাঁর জন্যে) সাজদা করে।', 'Laysoo sawaan min ahli alkitabi ommatun qaimatun yatloona ayati Allahi anaa allayli wahum yasjudoona', 1, NOW(), NOW()),
(3, 114, 'يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَـٰٓئِكَ مِنَ ٱلصَّـٰلِحِينَ', 'তারা আল্লাহ তায়ালা ও শেষ বিচার দিনের ওপর ঈমান রাখে এবং তারা (মানুষদের) ন্যায় কাজের আদেশ দেয় ও অন্যায় কাজ থেকে বিরত রাখে, সৎকাজে এরা প্রতিযোগিতা করে, আর এ (ধরনের) মানুষরাই সত্যিকার অর্থে নেক লোকদের অন্তর্ভুক্ত।', 'Yuminoona biAllahi waalyawmi alakhiri wayamuroona bialmaAAroofi wayanhawna AAani almunkari wayusariAAoona fee alkhayrati waolaika mina alssaliheena', 1, NOW(), NOW()),
(3, 115, 'وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ', 'তারা যা কিছু ভালো কাজ করবে তাকে কখনো অস্বীকার করা হবে না; (কারণ) আল্লাহ তায়ালা পরহেযগার লোকদের ভালো করেই জানেন।', 'Wama yafAAaloo min khayrin falan yukfaroohu waAllahu AAaleemun bialmuttaqeena', 1, NOW(), NOW()),
(3, 116, 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'নিসন্দেহে যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে, তাদের ধন সম্পদ, সন্তান সন্ততি আল্লাহ তায়ালার মোকাবেলায় তাদের কোনোই উপকারে আসবে না; (বরং) তারাই হবে জাহান্নামের অধিবাসী, সেখানে অনন্তকাল তারা পড়ে থাকবে।', 'Inna allatheena kafaroo lan tughniya AAanhum amwaluhum wala awladuhum mina Allahi shayan waolaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(3, 117, 'مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ', 'তারা এ দুনিয়ার জীবনে যা খরচ করে, তার উদাহরণ হচ্ছে (এমন লোকদের মতো), যারা নিজেদের ওপর অবিচার করেছে- (এটা হচ্ছে) সেই দলের শস্যক্ষেত্রের ওপর দিয়ে প্রবাহমান হীমশীতল (তীব্র) বাতাসের মতো, যা (তাদের শস্যক্ষেত) বরবাদ করে দিয়ে গেলো; (মূলত) আল্লাহ তায়ালা তাদের ওপর কোনোই অবিচার করেননি; বরং (কুফরী অবলম্বন করে) এরা নিজেরাই নিজেদের ওপর যুলুম করেছে।', 'Mathalu ma yunfiqoona fee hathihi alhayati alddunya kamathali reehin feeha sirrun asabat hartha qawmin thalamoo anfusahum faahlakathu wama thalamahumu Allahu walakin anfusahum yathlimoona', 1, NOW(), NOW()),
(3, 118, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ', 'হে ঈমানদার ব্যক্তিরা, তোমরা নিজেদের লোক ছাড়া অন্য কাউকে নিজেদের বন্ধু হিসেবে গ্রহণ করো না, (কেননা) এরা তোমাদের অনিষ্ট সাধনের কোনো পথই অনুসরণ করতে দ্বিধা করবে না, তারা তো তোমাদের ক্ষতিই কামনা করে, তাদের প্রতিহিংসা (বিদ্বেষ এখন) তাদের মুখ থেকেও প্রকাশ পেতে শুরু করেছে, অবশ্য তাদের অন্তর যা লুকায় তা বাইরের অবস্থার চাইতেও মারাত্মক, আমি আমার আয়াতসমূহ তোমাদের সামনে খোলাখুলি বলে দিচ্ছি, তোমাদের যদি জ্ঞানবুদ্ধি থাকে (তাহলে তোমরা সতর্ক হতে পারবে)।', 'Ya ayyuha allatheena amanoo la tattakhithoo bitanatan min doonikum la yaloonakum khabalan waddoo ma AAanittum qad badati albaghdao min afwahihim wama tukhfee sudooruhum akbaru qad bayyanna lakumu alayati in kuntum taAAqiloona', 1, NOW(), NOW()),
(3, 119, 'هَـٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'সাবধান, যাদের তোমরা ভালোবাসো; তারা (কিন্তু) তোমাদের (মোটেই) ভালোবাসে না, তোমরা তো (আমার) সব কয়টি কিতাবের ওপরও ঈমান আনো, (আর তারা তোমাদের কিতাবকে বিশ্বাসই করে না), এরা যখন তোমাদের সাথে সাক্ষাত করে তখন বলে, হ্যাঁ, আমরা (তোমাদের কিতাব) মানি, আবার যখন এরা একান্তে চলে যায়, তখন নিজেদের ক্রোধের বশবর্তী হয়ে এরা তোমাদের (সাফল্যের) ওপর (নিজেদের) আংগুল কামড়াতে শুরু করে; তুমি (তাদের) বলো, যাও, নিজেদের ক্রোধের (আগুনে) নিজেরাই তোমরা (পুড়ে) মরো, অবশ্যই আল্লাহ তায়ালা মনের ভেতর লুকিয়ে থাকা যাবতীয় বিষয় সম্পর্কে সম্যক অবগত আছেন।', 'Haantum olai tuhibboonahum wala yuhibboonakum watuminoona bialkitabi kullihi waitha laqookum qaloo amanna waitha khalaw AAaddoo AAalaykumu alanamila mina alghaythi qul mootoo bighaythikum inna Allaha AAaleemun bithati alssudoori', 1, NOW(), NOW()),
(3, 120, 'إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ', 'কোনো কল্যাণ তোমাদের (স্পর্শ করলে) তাদের খারাপ লাগে, আবার তোমাদের কোনো অকল্যাণ স্পর্শ করলে তারা আনন্দে ফেটে পড়ে; (এ অবস্থায়) তোমরা যদি ধৈর্য ধারণ করতে পারো এবং সাবধান হতে পারো, তাহলে তাদের চক্রান্ত তোমাদের কোনো ক্ষতিই করতে পারবে না; অবশ্যই আল্লাহ তায়ালা তাদের যাবতীয় কর্মকান্ডকে পরিবেষ্টন করে আছেন।', 'In tamsaskum hasanatun tasuhum wain tusibkum sayyiatun yafrahoo biha wain tasbiroo watattaqoo la yadurrukum kayduhum shayan inna Allaha bima yaAAmaloona muheetun', 1, NOW(), NOW()),
(3, 121, 'وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '(হে নবী, স্মরণ করো,) যখন তুমি ভোরবেলায় তোমার আপনজনের কাছ থেকে বিদায় নিয়ে মোমেনদের যুদ্ধের ঘাটিসমূহে মোতায়েন করছিলে (তখন তুমি নিশ্চিত জানতে যে,) আল্লাহ তায়ালা সব কিছু শোনেন এবং তিনি (বান্দাদের) ভালো করেই জানেন।', 'Waith ghadawta min ahlika tubawwio almumineena maqaAAida lilqitali waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(3, 122, 'إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', 'যখন তোমাদের দু’টো দল মনোবল হারিয়ে ফেলার উপক্রম করে ফেলেছিলো, (তখন সেখানে) আল্লাহ তায়ালাই তাদের উভয় দলের অভিভাবক হিসেবে মজুদ ছিলেন, আর আল্লাহর ওপর যারা ঈমান আনে তাদের তো (সর্বাবস্থায়) তাঁর ওপরই ভরসা করা উচিত।', 'Ith hammat taifatani minkum an tafshala waAllahu waliyyuhuma waAAala Allahi falyatawakkali almuminoona', 1, NOW(), NOW()),
(3, 123, 'وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ', '(এই ভরসা করার কারণেই) বদরে (যুদ্ধে) আল্লাহ তায়ালা তোমাকে বিজয় ও সাহায্য দান করেছিলেন, অথচ তোমরা কতো দুর্বল ছিলে; তোমরা আল্লাহকে ভয় করো, আশা করা যায় তোমরা (এ বিজয়ের জন্যে তাঁর) কৃতজ্ঞতা আদায় করবে।', 'Walaqad nasarakumu Allahu bibadrin waantum athillatun faittaqoo Allaha laAAallakum tashkuroona', 1, NOW(), NOW()),
(3, 124, 'إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُنزَلِينَ', '(স্মরণ করো,) যখন তুমি মোমেনদের বলছিলে, তোমাদের রব যদি আসমান থেকে তিন হাজার ফেরেশতা পাঠিয়ে তোমাদের সাহায্য করেন, তাহলে তোমাদের (বিজয়ের জন্যে তা কি) যথেষ্ট হবে না?', 'Ith taqoolu lilmumineena alan yakfiyakum an yumiddakum rabbukum bithalathati alafin mina almalaikati munzaleena', 1, NOW(), NOW()),
(3, 125, 'بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُسَوِّمِينَ', '(হ্যাঁ) অবশ্যই, তোমরা যদি ধৈর্য ধারণ করো এবং (শয়তানের চক্রান্ত থেকে) বেঁচে থাকতে পারো, এ অবস্থায় তারা যদি তোমাদের ওপর দ্রুত আক্রমণ করে বসে তাহলে তোমাদের রব (প্রয়োজনে) পাঁচ হাজার চিহ্নিত ফেরেশতা দিয়েও তোমাদের সাহায্য করবেন।', 'Bala in tasbiroo watattaqoo wayatookum min fawrihim hatha yumdidkum rabbukum bikhamsati alafin mina almalaikati musawwimeena', 1, NOW(), NOW()),
(3, 126, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ', '(আসলে) এ (সংখ্যাটা)কে আল্লাহ তায়ালা তোমাদের জন্যে একটি সুসংবাদ বানিয়ে দিয়েছেন, এর ফলে তোমাদের মন যেন (কিছুটা) প্রশান্ত (ও আশ্বস্ত) হতে পারে, আর সাহায্য ও বিজয়! তা তো পরাক্রান্ত প্রজ্ঞাময় আল্লাহ তায়ালার পক্ষ থেকেই আসে, তিনিই সর্বজ্ঞ।', 'Wama jaAAalahu Allahu illa bushra lakum walitatmainna quloobukum bihi wama alnnasru illa min AAindi Allahi alAAazeezi alhakeemi', 1, NOW(), NOW()),
(3, 127, 'لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ', 'আল্লাহ তায়ালা এই (যুদ্ধের) দ্বারা কাফেরদের এক দলকে নিশ্চিহ্ন করে দিতে চান, অথবা তাদের একাংশকে তিনি এর মাধ্যমে লাঞ্ছিত করে দিতে চান, অতপর যেন তারা ব্যর্থ হয়ে ফিরে যায়।', 'LiyaqtaAAa tarafan mina allatheena kafaroo aw yakbitahum fayanqaliboo khaibeena', 1, NOW(), NOW()),
(3, 128, 'لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ', '(হে নবী), এ ব্যাপারে তোমার কিছুই করার নেই, আল্লাহ তায়ালা চাইলে তাদের ওপর দয়াপরবশ হবেন কিংবা তিনি চাইলে তাদের কঠোর শাস্তি দেবেন, নিসন্দেহে এরা হচ্ছে যালিম।', 'Laysa laka mina alamri shayon aw yatooba AAalayhim aw yuAAaththibahum fainnahum thalimoona', 1, NOW(), NOW()),
(3, 129, 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'আসমানসমূহ ও যমীনে যা কিছু আছে তার সব কিছুই আল্লাহ তায়ালার জন্যে, তিনি যাকে ইচ্ছা- ক্ষমা করে দেবেন, যাকে ইচ্ছা- শাস্তি দেবেন; আল্লাহ তায়ালা অত্যন্ত ক্ষমাশীল ও পরম দয়ালু।', 'Walillahi ma fee alssamawati wama fee alardi yaghfiru liman yashao wayuAAaththibu man yashao waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(3, 130, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, চক্রবৃদ্ধি হারে সুদ খেয়ো না এবং তোমরা আল্লাহ তায়ালাকে ভয় করো, আশা করা যায় তোমরা সফল হতে পারবে।', 'Ya ayyuha allatheena amanoo la takuloo alrriba adAAafan mudaAAafatan waittaqoo Allaha laAAallakum tuflihoona', 1, NOW(), NOW()),
(3, 131, 'وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ', '(জাহান্নামের) আগুনকে তোমরা ভয় করো, কাফেরদের জন্যেই এটাকে তৈরী করে রাখা হয়েছে।', 'Waittaqoo alnnara allatee oAAiddat lilkafireena', 1, NOW(), NOW()),
(3, 132, 'وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ', 'তোমরা আল্লাহ তায়ালা ও (তাঁর) রসূলের কথা মেনে চলো, আশা করা যায় তোমাদের ওপর দয়া করা হবে।', 'WaateeAAoo Allaha waalrrasoola laAAallakum turhamoona', 1, NOW(), NOW()),
(3, 133, '۞وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ', 'তোমরা তোমাদের মালিকের ক্ষমা পাওয়ার কাজে (একে অপরের সাথে) প্রতিযোগিতা করো, আর সেই জান্নাতের জন্যেও (প্রতিযোগিতা করো), যার প্রশস্ততা আকাশসমূহ ও পৃথিবী সমান, এটি মোত্তাকীদের জন্যেই প্রস্তুত করে রাখা হয়েছে,', 'WasariAAoo ila maghfiratin min rabbikum wajannatin AAarduha alssamawatu waalardu oAAiddat lilmuttaqeena', 1, NOW(), NOW()),
(3, 134, 'ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', '(আল্লাহভীরু হচ্ছে তারা) যারা সচ্ছল হোক কিংবা অসচ্ছল- সর্বাবস্থায় (আল্লাহর পথে) নিজেদের ধন-সম্পদ ব্যয় করে, যারা নিজেদের ক্রোধ সংবরণ করে এবং যারা মানুষের ক্ষমা করে দেয়; আল্লাহ তায়ালা উত্তম মানুষদের ভালোবাসেন।', 'Allatheena yunfiqoona fee alssarrai waalddarrai waalkathimeena alghaytha waalAAafeena AAani alnnasi waAllahu yuhibbu almuhsineena', 1, NOW(), NOW()),
(3, 135, 'وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ', 'তারা- যখন কোনো অশ্লীল কাজ করে বসে কিংবা (এর দ্বারা) নিজেদের ওপর নিজেরা যুলুম করে ফেলে (সাথে সাথেই) তারা আল্লাহকে স্মরণ করে এবং নিজেদের গুনাহের জন্যে (আল্লাহর) ক্ষমা প্রার্থনা করে। (আসলে) আল্লাহ তায়ালা ছাড়া আর কে আছে যে (তাদের) গুনাহ মাফ করে দিতে পারে? এরা জেনে বুঝে কখনো নিজেদের গুনাহের ওপর অটল হয়ে বসে থাকে না।', 'Waallatheena itha faAAaloo fahishatan aw thalamoo anfusahum thakaroo Allaha faistaghfaroo lithunoobihim waman yaghfiru alththunooba illa Allahu walam yusirroo AAala ma faAAaloo wahum yaAAlamoona', 1, NOW(), NOW()),
(3, 136, 'أُوْلَـٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ', 'এই (হচ্ছে সে বৈশিষ্ট্যমন্ডিত) মানুষগুলো! তাদের মালিকের পক্ষ থেকে তাদের প্রতিদান হবে ক্ষমা, আর এমন এক জান্নাত যার তলদেশ দিয়ে ঝর্ণাধারা বইতে থাকবে, সেখানে (নেককার) লোকেরা অনন্তকাল ধরে অবস্থান করবে। (এটা) সৎ কর্মশীল ব্যক্তিদের জন্যে (আল্লাহর পক্ষ থেকে) কতো সুন্দর প্রতিদান!', 'Olaika jazaohum maghfiratun min rabbihim wajannatun tajree min tahtiha alanharu khalideena feeha waniAAma ajru alAAamileena', 1, NOW(), NOW()),
(3, 137, 'قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ', 'তোমাদের আগেও বহু যুগ অতিবাহিত হয়ে গেছে, সুতরাং তোমরা পৃথিবীতে ঘুরে বেড়াও এবং দেখো, (আল্লাহ তায়ালাকে) মিথ্যা প্রতিপন্নকারীদের কি পরিণতি হয়েছিলো!', 'Qad khalat min qablikum sunanun faseeroo fee alardi faonthuroo kayfa kana AAaqibatu almukaththibeena', 1, NOW(), NOW()),
(3, 138, 'هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ', 'এটি হচ্ছে মানব জাতির জন্যে (আল্লাহর বিধানের বিশেষ) বর্ণনা এবং আল্লাহভীরুদের জন্যে সুস্পষ্ট পথনির্দেশ ও সদুপদেশ।', 'Hatha bayanun lilnnasi wahudan wamawAAithatun lilmuttaqeena', 1, NOW(), NOW()),
(3, 139, 'وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ', 'তোমরা হতোদ্যম হইয়ো না, চিন্তিত হয়ো না, তোমরা যদি (সত্যিকার অর্থে) ঈমানদার হও তাহলে তোমরাই বিজয়ী হবে।', 'Wala tahinoo wala tahzanoo waantumu alaAAlawna in kuntum mumineena', 1, NOW(), NOW()),
(3, 140, 'إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ', 'তোমাদের যদি (কোনো সাময়িক) বিপর্যয় স্পর্শ করে (এতে মনোক্ষুণ্ন হয়ো না), এ ধরনের আঘাত তো (সে) দলের ওপরও এসেছে, আর (এভাবেই) আমি মানুষের মাঝে (উত্থান পতনের) দিনগুলোকে পালাক্রমে অদল- বদল করাতে থাকি, যাতে করে (এর মাধ্যমে) আল্লাহ তায়ালা জেনে নিতে পারেন, কে (সত্যিকার অর্থে) আল্লাহর ওপর ঈমান রাখে এবং (এর মাধ্যমে) তোমাদের মাঝখান থেকে কিছু ‘শহীদ’ও আল্লাহ তায়ালা গ্রহণ করেন, আল্লাহ তায়ালা কখনো যালেমদের পছন্দ করেন না।', 'In yamsaskum qarhun faqad massa alqawma qarhun mithluhu watilka alayyamu nudawiluha bayna alnnasi waliyaAAlama Allahu allatheena amanoo wayattakhitha minkum shuhadaa waAllahu la yuhibbu alththalimeena', 1, NOW(), NOW()),
(3, 141, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ', 'আল্লাহ তায়ালা (এর মাধ্যমে) ঈমানদার বান্দাদের পরিশুদ্ধ করে কাফেরদের নাস্তানাবুদ করে দিতে চান।', 'Waliyumahhisa Allahu allatheena amanoo wayamhaqa alkafireena', 1, NOW(), NOW()),
(3, 142, 'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّـٰبِرِينَ', 'তোমরা কি মনে করো তোমরা (এমনি এমনি) বেহেশতে প্রবেশ করবে, অথচ আল্লাহ তায়ালা (পরীক্ষার মাধ্যমে) এ কথা জেনে নেবেন না যে, কে (তাঁর পথে) জেহাদ করেছে এবং তোমাদের মধ্যে কে (বিপদে) কঠোর ধৈর্য ধারণ করতে পেরেছে!', 'Am hasibtum an tadkhuloo aljannata walamma yaAAlami Allahu allatheena jahadoo minkum wayaAAlama alssabireena', 1, NOW(), NOW()),
(3, 143, 'وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ', 'তোমরা তার মুখোমুখি হওয়ার আগেই (সত্যের পথে) মৃতু কামনা করছিলে, আর (এখন) তা (তো) তোমাদের সামনেই চলে এসেছে এবং (নিজের চোখেই) তোমরা তা দেখতে পাচ্ছো।', 'Walaqad kuntum tamannawna almawta min qabli an talqawhu faqad raaytumoohu waantum tanthuroona', 1, NOW(), NOW()),
(3, 144, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّـٰكِرِينَ', 'মোহাম্মদ একজন রসূল ছাড়া কিছুই নয়, তার আগেও বহু রসূল গত হয়ে গেছে (এবং তারা সবাই মৃত্যুমুখে পতিত হয়েছে); তাই সে যদি (আজ) মরে যায় অথবা তাকে যদি কেউ মেরে ফেলে, তাহলে তোমরা কি (হেদায়াত থেকে) মুখ ফিরিয়ে নেবে? আর যে ব্যক্তি মুখ ফিরিয়ে নেয়, সে কখনোই আল্লাহর (দ্বীনের) ক্ষতি সাধন করতে পারবে না, আল্লাহ তায়ালা অচিরেই কৃতজ্ঞ বান্দাদের প্রতিফল দান করবেন।', 'Wama muhammadun illa rasoolun qad khalat min qablihi alrrusulu afain mata aw qutila inqalabtum AAala aAAqabikum waman yanqalib AAala AAaqibayhi falan yadurra Allaha shayan wasayajzee Allahu alshshakireena', 1, NOW(), NOW()),
(3, 145, 'وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّـٰكِرِينَ', 'কোনো প্রাণীই আল্লাহর অনুমতি ছাড়া মরবে না, (আল্লাহ তায়ালার কাছে সবার) দিনক্ষণ সুনির্দিষ্ট, যে ব্যক্তি পার্থিব পুরস্কারের প্রত্যাশা করে আমি তাকে (এ দুনিয়াতেই) তার কিছু অংশ দান করি, আর যে ব্যক্তি আখেরাতের পুরস্কারের ইচ্ছা পোষণ করবে, আমি তাকে সে (পাওনা) থেকেই এর প্রতিফল দান করবো এবং অচিরেই আমি কৃতজ্ঞদের প্রতিফল দান করবো।', 'Wama kana linafsin an tamoota illa biithni Allahi kitaban muajjalan waman yurid thawaba alddunya nutihi minha waman yurid thawaba alakhirati nutihi minha wasanajzee alshshakireena', 1, NOW(), NOW()),
(3, 146, 'وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّـٰبِرِينَ', 'অনেক নবীই (এখানে এমন) ছিলো, নবী (আল্লাহর পথে) যুদ্ধ করেছে, তার সাথে (আরো যুদ্ধ করেছে) অনেক সাধক ব্যক্তি, আল্লাহর পথে তাদের ওপর যতো বিপদ-মসিবতই এসেছে তাতে (কোনোদিনই) তারা হতাশ হয়ে পড়েনি, তারা দুর্বলও হয়নি, (বাতিলের সামনে তারা) মাথাও নত করেনি, আল্লাহ তায়ালা ধৈর্যশীলদের ভালোবাসেন।', 'Wakaayyin min nabiyyin qatala maAAahu ribbiyyoona katheerun fama wahanoo lima asabahum fee sabeeli Allahi wama daAAufoo wama istakanoo waAllahu yuhibbu alssabireena', 1, NOW(), NOW()),
(3, 147, 'وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', 'তাদের (মুখে তখন) এছাড়া অন্য কথা ছিলো না যে, তারা বলছিলো, হে আমাদের রব, তুমি আমাদের যাবতীয় গুনাহখাতা মাফ করে দাও, আমাদের কাজকর্মের সব বাড়াবাড়ি (তুমি ক্ষমা করে দাও) তুমি আমাদের কদমগুলো মযবুত রাখো এবং কাফেরদের ওপর তুমি আমাদের বিজয় দান করো।', 'Wama kana qawlahum illa an qaloo rabbana ighfir lana thunoobana waisrafana fee amrina wathabbit aqdamana waonsurna AAala alqawmi alkafireena', 1, NOW(), NOW()),
(3, 148, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', 'অতপর আল্লাহ তায়ালা তাদের দুনিয়ার জীবনেও (ভালো) প্রতিফল দিয়েছেন এবং পরকালীন জীবনেও তিনি তাদের উত্তম পুরস্কার দিয়েছেন; আল্লাহ তায়ালা নেক বান্দাদের ভালোবাসেন।', 'Faatahumu Allahu thawaba alddunya wahusna thawabi alakhirati waAllahu yuhibbu almuhsineena', 1, NOW(), NOW()),
(3, 149, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ', 'হে মানুষ, তোমরা যারা (আল্লাহর ওপর) ঈমান এনেছো, তোমরা যদি (কথায় কথায়) এ কাফেরদের অনুসরণ করতে শুরু করো, তাহলে এরা তোমাদের (ঈমান) পূর্ববর্তী অবস্থায় ফিরিয়ে নিয়ে যাবে, ফলে তোমরা ক্ষতিগ্রস্ত হয়ে পড়বে।', 'Ya ayyuha allatheena amanoo in tuteeAAoo allatheena kafaroo yaruddookum AAala aAAqabikum fatanqaliboo khasireena', 1, NOW(), NOW()),
(3, 150, 'بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّـٰصِرِينَ', 'আল্লাহ তায়ালাই হচ্ছেন তোমাদের অভিভাবক এবং তিনিই তোমাদের উত্তম সাহায্যকারী।', 'Bali Allahu mawlakum wahuwa khayru alnnasireena', 1, NOW(), NOW()),
(3, 151, 'سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّـٰلِمِينَ', 'অচিরেই আমি এ কাফেরদের অন্তরে ভীতি সঞ্চার করে দেবো, কারণ তারা আল্লাহর সাথে অন্যদের শরীক করেছে, অথচ তাদের এ কাজের সপক্ষে আল্লাহ তায়ালা কখনো কোনো দলীল-প্রমাণ পাঠাননি, এদের শেষ গন্তব্যস্থল হচ্ছে (জাহান্নামের) আগুন; যালেমদের বাসস্থান (হিসেবে) জাহান্নাম কতো নিকৃষ্ট!', 'Sanulqee fee quloobi allatheena kafaroo alrruAAba bima ashrakoo biAllahi ma lam yunazzil bihi sultanan wamawahumu alnnaru wabisa mathwa alththalimeena', 1, NOW(), NOW()),
(3, 152, 'وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ', '(উহুদের ময়দানে) আল্লাহ তায়ালা তোমাদের যে (সাহায্যের) প্রতিশ্রুতি দিয়েছিলেন তা তিনি পালন করেছেন, (প্রথম দিকে) যখন তোমরা আল্লাহর অনুমতি (ও সাহায্য) নিয়ে তাদের নির্মূল করে যাচ্ছিলে! এমনকি তোমরা যখন সাহস হারিয়ে ফেললে এবং (আল্লাহর রসূলের বিশেষ একটি) আদেশ পালনের ব্যাপারে মতপার্থক্য শুরু করে দিলে, আল্লাহর রসূল যখন তোমাদের ভালোবাসার সেই জিনিস (ও আসন্ন বিজয়) দেখিয়ে দিলেন, তারপরও তোমরা তার কথা অমান্য করে (তার বলে দেয়া স্থান ছেড়ে) চলে গেলে, তোমাদের কিছু লোক (তখন) বৈষয়িক ফায়দা হাসিল করতে চাইলো, (অপরদিকে) তোমাদের কিছু লোক (তখনও) পরকালের কল্যাণই চাইতে থাকলো, অতপর আল্লাহ তায়ালা (তোমাদের) পরীক্ষা নিতে চাইলেন এবং তা থেকে তিনি তোমাদের অন্য দিকে ফিরিয়ে দিলেন, তারপর আল্লাহ তায়ালা তোমাদের মাফ করে দিলেন, আল্লাহ তায়ালা (সবসময়ই) ঈমানদারদের ওপর দয়াবান।', 'Walaqad sadaqakumu Allahu waAAdahu ith tahussoonahum biithnihi hatta itha fashiltum watanazaAAtum fee alamri waAAasaytum min baAAdi ma arakum ma tuhibboona minkum man yureedu alddunya waminkum man yureedu alakhirata thumma sarafakum AAanhum liyabtaliyakum walaqad AAafa AAankum waAllahu thoo fadlin AAala almumineena', 1, NOW(), NOW()),
(3, 153, '۞إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ', '(উহুদের বিপর্যয়ের সময়) তোমরা যখন (ময়দান ছেড়ে পাহাড়ের) ওপরের দিকে ওঠে যাচ্ছিলে এবং তোমরা তোমাদের কোনো লোকের প্রতি লক্ষ্যই করছিলে না, অথচ আল্লাহর রসূল তোমাদের (তখনও) পেছন থেকে ডাকছিলো, তাই আল্লাহ তায়ালা তোমাদের দুঃখের পর দুঃখ দিলেন, যেন তোমাদের কাছ থেকে যা হারিয়ে গেছে এবং যা কিছু বিপদ তোমাদের ওপর পতিত হয়েছে, এর ব্যাপারে তোমরা উদ্বিগ্ন না হও, আল্লাহ তায়ালা তোমাদের সব ধরনের কর্মকান্ড সম্পর্কেই ওয়াকেফহাল রয়েছেন।', 'Ith tusAAidoona wala talwoona AAala ahadin waalrrasoolu yadAAookum fee okhrakum faathabakum ghamman bighammin likayla tahzanoo AAala ma fatakum wala ma asabakum waAllahu khabeerun bima taAAmaloona', 1, NOW(), NOW()),
(3, 154, 'ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'বিপর্যয়ের পর আল্লাহ তায়ালা পরবর্তী পর্যায়ে তোমাদের ওপর এমন প্রশান্তি নাযিল করে দিলেন, যা তোমাদের একদল লোককে তন্দ্রাচ্ছন্ন করে দেয়, আর আরেক দল, যারা নিজেরাই নিজেদের উদ্বিগ্ন করে রেখেছিলো, তারা তাদের জাহেলী ধারণা অনুযায়ী আল্লাহ তায়ালা সম্পর্কে অন্যায় ধারণা করতে থাকে, তারা বলে, (যুদ্ধ পরিচালনার) এ কাজে কি আমাদের কোনো ভূমিকা আছে? (হে নবী,) তুমি বলো ক্ষমতা (ও) কর্তৃত্বের সবটুকুই আল্লাহর হাতে, এরা তাদের মনের ভেতর যেসব কথাবার্তা গোপন করে রেখেছে তা তোমার সামনে (খোলাখুলি) প্রকশ করে না; তারা বলে, এ (যুদ্ধ পরিচালনার) কাজে যদি আমাদের কোনো ভূমিকা থাকতো, তাহলে আমরা এখানে নিহত হতাম না; তুমি তাদের বলো, যদি (আজ) তোমরা তোমাদের ঘরের ভেতরেও থাকতে, তবুও নিহত হওয়া যাদের অবধারিত ছিলো তারা (এই মরণের) বিছানার দিকেই বের হয়ে পড়তো, আর এভাবেই তোমাদের মনের ভেতর যা আছে সে ব্যাপারে আল্লাহ তায়ালা তোমাদের পরীক্ষা করেন এবং এ (ঘটনা) দিয়ে তিনি তোমাদের অন্তরে যা কিছু আছে তাও পরিশুদ্ধ করে দেন, তোমাদের মনের কথা সম্পর্কে আল্লাহ তায়ালা সম্যক ওয়াকেফহাল রয়েছেন।', 'Thumma anzala AAalaykum min baAAdi alghammi amanatan nuAAasan yaghsha taifatan minkum wataifatun qad ahammathum anfusuhum yathunnoona biAllahi ghayra alhaqqi thanna aljahiliyyati yaqooloona hal lana mina alamri min shayin qul inna alamra kullahu lillahi yukhfoona fee anfusihim ma la yubdoona laka yaqooloona law kana lana mina alamri shayon ma qutilna hahuna qul law kuntum fee buyootikum labaraza allatheena kutiba AAalayhimu alqatlu ila madajiAAihim waliyabtaliya Allahu ma fee sudoorikum waliyumahhisa ma fee quloobikum waAllahu AAaleemun bithati alssudoori', 1, NOW(), NOW()),
(3, 155, 'إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ', 'দু’টি বাহিনী যেদিন একে অপরের মুখোমুখি হয়েছিলো, নিসন্দেহে সেদিন যারা (ময়দান থেকে) পালিয়ে গিয়েছিলো তাদের একাংশের অর্জিত কাজের জন্যে শয়তানই তাদের পদস্খলন ঘটিয়ে দিয়েছিলো, অতপর (তারা অনুতপ্ত হলে) আল্লাহ তায়ালা তাদের ক্ষমা করে দিলেন; অবশ্যই আল্লাহ তায়ালা একান্ত ক্ষমাশীল ও পরম ধৈর্যশীল।', 'Inna allatheena tawallaw minkum yawma iltaqa aljamAAani innama istazallahumu alshshaytanu bibaAAdi ma kasaboo walaqad AAafa Allahu AAanhum inna Allaha ghafoorun haleemun', 1, NOW(), NOW()),
(3, 156, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ', 'হে ঈমানদার ব্যক্তিরা, তোমরা কাফেরদের মতো হয়ো না, কাফেরদের কোনো ভাই (বন্ধু) যখন বিদেশ (বিভূঁইয়ে) মারা যেতো, কিংবা কোনো যুদ্ধে লিপ্ত হতো, তখন এরা তাদের ভাইদের বলতো, এরা যদি আমাদের কাছে থাকতো, তাহলে এরা (এভাবে) মরতো না এবং এরা নিহতও হতো না, এটা (এ জন্যে) যেন আল্লাহ তায়ালা একে তাদের মনের আক্ষেপে পরিণত করে দেন, (আসলে) আল্লাহই মানুষের জীবন দেন, তিনি মানুষের মৃত্যু ঘটান এবং তোমরা (এই দুনিয়ায়) যা করে যাচ্ছো আল্লাহ তায়ালা তার সব কিছুই দেখেন।', 'Ya ayyuha allatheena amanoo la takoonoo kaallatheena kafaroo waqaloo liikhwanihim itha daraboo fee alardi aw kanoo ghuzzan law kanoo AAindana ma matoo wama qutiloo liyajAAala Allahu thalika hasratan fee quloobihim waAllahu yuhyee wayumeetu waAllahu bima taAAmaloona baseerun', 1, NOW(), NOW()),
(3, 157, 'وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ', 'তোমরা যদি আল্লাহর পথে নিহত হও অথবা (সে পথে) তোমরা মৃত্যুবরণ করো, তাহলে আল্লাহর পক্ষ থেকে (যে) রহমত ও ক্ষমা (লাভ করবে), এটা তার চাইতে অনেক বেশী উত্তম (কাফেররা) যা সঞ্চয় করে!', 'Walain qutiltum fee sabeeli Allahi aw muttum lamaghfiratun mina Allahi warahmatun khayrun mimma yajmaAAoona', 1, NOW(), NOW()),
(3, 158, 'وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ', 'তোমরা যদি (আল্লাহর পথে) মৃতুবরণ করো, অথবা (তাঁর পথে) তোমরা যদি নিহত হও, (উভয় অবস্থায়ই) তোমাদের একদিন আল্লাহ তায়ালার সমীপেই জড়ো করা হবে।', 'Walain muttum aw qutiltum laila Allahi tuhsharoona', 1, NOW(), NOW()),
(3, 159, 'فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ', 'এটা আল্লাহর দয়া যে, তুমি এদের জন্যে ছিলে কোমল প্রকৃতির (মানুষ,) যদি তুমি নিষ্ঠুর ও পাষাণ হৃদয়ের হতে, তাহলে এসব লোক তোমার আশপাশ থেকে সরে যেতো, তুমি এদের (অপরাধসমূহ) মাফ করে দাও, এদের জন্যে (আল্লাহর কাছে) ক্ষমা প্রার্থনা করো এবং কাজকর্মের ব্যাপারে এদের সাথে পরামর্শ করো, যখন তুমি (কোনো কাজের) সংকল্প করবে, তখন (তার সফলতার জন্যে ) আল্লাহর ওপর ভরসা করো; অবশ্যই আল্লাহ তায়ালা (তাঁর ওপর) নির্ভরশীল মানুষদের ভালোবাসেন।', 'Fabima rahmatin mina Allahi linta lahum walaw kunta faththan ghaleetha alqalbi lainfaddoo min hawlika faoAAfu AAanhum waistaghfir lahum washawirhum fee alamri faitha AAazamta fatawakkal AAala Allahi inna Allaha yuhibbu almutawakkileena', 1, NOW(), NOW()),
(3, 160, 'إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', 'যদি আল্লাহ তায়ালা তোমাদের সাহায্য করেন তাহলে কেউই তোমাদের পরাজিত করতে পারবে না, আর তিনিই যদি তোমাদের পরিত্যাগ করেন তাহলে এমন কোন শক্তি আছে যে অতপর তোমাদের সাহায্য করতে পারে; কাজেই (আল্লাহর ওপর) যারা ঈমান আনে তাদের আল্লাহর ওপরই ভরসা করা উচিত।', 'In yansurkumu Allahu fala ghaliba lakum wain yakhthulkum faman tha allathee yansurukum min baAAdihi waAAala Allahi falyatawakkali almuminoona', 1, NOW(), NOW()),
(3, 161, 'وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ', '(কোনো) নবীর পক্ষেই খেয়ানত করা সম্ভব নয়; (হ্যাঁ মানুষের মধ্যে) কেউ যদি খেয়ানত করে তাহলে কেয়ামতের দিন সে ব্যক্তি তার (খেয়ানতের) সে বস্তুসহ হাযির হবে, অতপর প্রত্যেককেই তার অর্জিত (ভালো মন্দের) পাওনা সঠিকভাবে আদায় করে দেয়া হবে, (সেদিন) তাদের কারো ওপরই অবিচার করা হবে না।', 'Wama kana linabiyyin an yaghulla waman yaghlul yati bima ghalla yawma alqiyamati thumma tuwaffa kullu nafsin ma kasabat wahum la yuthlamoona', 1, NOW(), NOW()),
(3, 162, 'أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'যে ব্যক্তি আল্লাহর সন্তুষ্টির পথ অনুসরণ করে, তার সাথে কিভাবে সে ব্যক্তির তুলনা করা যায়, যে আল্লাহর বিরোধী পথে চলে শুধু তাঁর ক্রোধই অর্জন করেছে, তার জন্যে জাহান্নামের আগুন হবে একমাত্র বাসস্থান; আর তা (হচ্ছে) নিকৃষ্ট আশ্রয়স্থল!', 'Afamani ittabaAAa ridwana Allahi kaman baa bisakhatin mina Allahi wamawahu jahannamu wabisa almaseeru', 1, NOW(), NOW()),
(3, 163, 'هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', 'এরা (নিজ নিজ আমল অনুযায়ী) আল্লাহর কাছে বিভিন্ন স্তরে (বিভক্ত) হবে, এরা যা কিছু করে আল্লাহ তায়ালা তা জানেন।', 'Hum darajatun AAinda Allahi waAllahu baseerun bima yaAAmaloona', 1, NOW(), NOW()),
(3, 164, 'لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ', 'আল্লাহ তায়ালা অবশ্যই মোমেনদের ওপর অনুগ্রহ করেছেন, যখন তিনি তাদের মাঝ থেকে একজন ব্যক্তিকে রসূল করে পাঠিয়েছেন, যে তাদের কাছে আল্লাহর কিতাবের আয়াতসমূহ পড়ে শোনায় এবং (সে অনুযায়ী) সে তাদের জীবনকে পরিশুদ্ধ করে, (সর্বোপরি) সে তাদের আল্লাহর কিতাব ও (তাঁর গ্রন্থলব্ধ) জ্ঞান-বিজ্ঞান শিক্ষা দেয়, যদিও এরা সবাই ইতিপূর্বে স্পষ্ট গোমরাহীতে নিমজ্জিত ছিলো।', 'Laqad manna Allahu AAala almumineena ith baAAatha feehim rasoolan min anfusihim yatloo AAalayhim ayatihi wayuzakkeehim wayuAAallimuhumu alkitaba waalhikmata wain kanoo min qablu lafee dalalin mubeenin', 1, NOW(), NOW()),
(3, 165, 'أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'যখনি তোমাদের ওপর (ওহুদ যুদ্ধের) বিপদ নেমে এলো, (তখনি তোমরা বলতে শুরু করলে, পরাজয়ের) এ বিপদ আমাদের ওপর কিভাবে এলো- অথচ (বদরের যুদ্ধে) এর চাইতে দ্বিগুণ (পরাজয়ের) বিপদ তো তোমরাই তাদের ঘটিয়েছিলে; (হে নবী,) তুমি বলো, এটা এসেছে তোমাদের নিজেদের কারণেই; আল্লাহ তায়ালা অবশ্যই সর্ববিষয়ের ওপর ক্ষমতাবান।', 'Awalamma asabatkum museebatun qad asabtum mithlayha qultum anna hatha qul huwa min AAindi anfusikum inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(3, 166, 'وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ', '(উহুদের ময়দানে) দু’দলের সম্মুখ লড়াইয়ের দিনে যে (সাময়িক) বিপর্যয় তোমাদের ওপর এসেছিলো, তা (এসেছে) আল্লাহর ইচ্ছায়, (এর দ্বারা) তিনি জেনে নিতে চান, কারা সত্যিকার মুমীন,', 'Wama asabakum yawma iltaqa aljamAAani fabiithni Allahi waliyaAAlama almumineena', 1, NOW(), NOW()),
(3, 167, 'وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ', 'আর তাদের (পরিচয়ও) তিনি জেনে নেবেন, যারা (মোনাফেকী) করেছে, এদের যখন বলা হয়েছিলো, আল্লাহর পথে লড়াই করো, অথবা (কমপক্ষে নিজেদের শহরের) প্রতিরক্ষাটুকু তোমরা করো, তখন তারা বললো, যদি আমরা জানতাম (আজ) যুদ্ধ হবে, তাহলে অবশ্যই আমরা তোমাদের অনুসরণ করতাম, (এ সময়) তারা ঈমানের চাইতে কুফরীরই বেশী কাছাকাছি অবস্থান করছিলো, এরা মুখে এমন সব কথা বলে যা তাদের অন্তরে নেই; আর আল্লাহ তায়ালা ভালো করেই জানেন যা কিছু এরা গোপন করে।', 'WaliyaAAlama allatheena nafaqoo waqeela lahum taAAalaw qatiloo fee sabeeli Allahi awi idfaAAoo qaloo law naAAlamu qitalan laittabaAAnakum hum lilkufri yawmaithin aqrabu minhum lileemani yaqooloona biafwahihim ma laysa fee quloobihim waAllahu aAAlamu bima yaktumoona', 1, NOW(), NOW()),
(3, 168, 'ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ', 'যারা (যুদ্ধে শরীক না হয়ে ঘরে) বসে থাকলো (তারা তাদের) ভাইদের সম্পর্কে বললো, তারা যদি ঘরে বসে থাকতো এবং) তাদের কথা শুনতো, তাহলে তারা (আজ এভাবে) মারা পড়তো না; (হে নবী,) তুমি বলো, যদি তোমরা (এ দাবীতে) সত্যবাদী হও তাহলে তোমাদের কাছ থেকে (তোমাদের) মৃত্যুটাকে সরিয়ে দাও।', 'Allatheena qaloo liikhwanihim waqaAAadoo law ataAAoona ma qutiloo qul faidraoo AAan anfusikumu almawta in kuntum sadiqeena', 1, NOW(), NOW()),
(3, 169, 'وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ', 'যারা আল্লাহর পথে নিহত হয়েছে তাদের তোমরা কোনো অবস্থাতেই ‘মৃত’ মনে করো না, তারা তো জীবিত, তাদের মালিকের কাছে তাদের (রীতিমতো) রিজিক দেয়া হচ্ছে।', 'Wala tahsabanna allatheena qutiloo fee sabeeli Allahi amwatan bal ahyaon AAinda rabbihim yurzaqoona', 1, NOW(), NOW()),
(3, 170, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'আল্লাহ তায়ালা নিজ অনুগ্রহ দিয়ে তাদের যা কিছু দান করেছেন তাতে তারা পরিতৃপ্ত এবং যারা এখনো তাদের পেছনে রয়ে গেছে, যারা এখনো তাদের সাথে মিলিত হতে পারেনি, তাদের ব্যাপারেও এরা (এই মর্মে) সুসংবাদ দিচ্ছে যে, এমন ধরনের লোকদের জন্যে কোনো ভয় নেই এবং তারা (সে দিন কোনোরকম) চিন্তাও করবে না।', 'Fariheena bima atahumu Allahu min fadlihi wayastabshiroona biallatheena lam yalhaqoo bihim min khalfihim alla khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(3, 171, '۞يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ', 'এরা আল্লাহর পক্ষ থেকে অফুরন্ত নেয়ামত ও অনুগ্রহের সুসংবাদ লাভ করে, আল্লাহ তায়ালা কখনোই ঈমানদারদের পাওনা বিনষ্ট করেন না।', 'Yastabshiroona biniAAmatin mina Allahi wafadlin waanna Allaha la yudeeAAu ajra almumineena', 1, NOW(), NOW()),
(3, 172, 'ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ', 'তাদের ওপর (বড়ো) আঘাত আসার পরও যারা (আবার) আল্লাহ তায়ালা ও তাঁর রসূলের ডাকে সাড়া দিয়েছে এবং তাদের মধ্যে আরো যারা নেক কাজ করেছে, (সর্বোপরি) সর্বদা যারা আল্লাহকে ভয় করে চলেছে, এদের জন্যে রয়েছে মহাপুরস্কার।', 'Allatheena istajaboo lillahi waalrrasooli min baAAdi ma asabahumu alqarhu lillatheena ahsanoo minhum waittaqaw ajrun AAatheemun', 1, NOW(), NOW()),
(3, 173, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ', 'মানুষরা যখন তাদের বললো, তোমাদের বিরুদ্ধে (কাফেরদের) এক বিশাল বাহিনী জমায়েত হয়েছে, অতএব তোমরা তাদের ভয় করো, (এ বিষয়টা) তাদের ঈমানকে আরো বাড়িয়ে দিলো, তারা বললো, আল্লাহ তায়ালাই আমাদের জন্যে যথেষ্ট এবং তিনিই (আমাদের) উত্তম কর্মবিধায়ক।', 'Allatheena qala lahumu alnnasu inna alnnasa qad jamaAAoo lakum faikhshawhum fazadahum eemanan waqaloo hasbuna Allahu waniAAma alwakeelu', 1, NOW(), NOW()),
(3, 174, 'فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ', 'অতপর আল্লাহর নেয়ামত ও অনুগ্রহ নিয়ে এরা (এমনভাবে) ফিরে এলো যে, কোনো প্রকার অনিষ্টই তাদের স্পর্শ করতে পারলো না, এরা আল্লাহর সন্তুষ্টির পথই অনুসরণ করলো; (বস্তুত) আল্লাহ তায়ালা মহা অনুগ্রহশীল।', 'Fainqalaboo biniAAmatin mina Allahi wafadlin lam yamsashum sooon waittabaAAoo ridwana Allahi waAllahu thoo fadlin AAatheemin', 1, NOW(), NOW()),
(3, 175, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ', 'এই হচ্ছে তোমাদের (প্ররোচনাদানকারী) শয়তান, তারা (শত্রুপক্ষের অতিরঞ্জিত শক্তির কথা বলে) তাদের বন্ধু বান্ধবদের ভয় দেখায়, তোমরা তাদের ভয় করো না, (বরং) আমাকেই ভয় করো, যদি তোমরা ঈমানদার হও!', 'Innama thalikumu alshshaytanu yukhawwifu awliyaahu fala takhafoohum wakhafooni in kuntum mumineena', 1, NOW(), NOW()),
(3, 176, 'وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ', '(হে নবী,) যারা দ্রুতগতিতে কুফরীর পথে এগিয়ে যাচ্ছে, তাদের কর্মকান্ড যেন তোমাকে চিন্তান্বিত না করে, তারা কখনো আল্লাহর কোনো ক্ষতি সাধন করতে পারবে না; (মূলত) আল্লাহ তায়ালা এদের জন্যে পরকালে (পুরস্কারের) কোনো অংশই রাখতে চান না, তাদের জন্যে অবশ্যই কঠিন আযাব রয়েছে।', 'Wala yahzunka allatheena yusariAAoona fee alkufri innahum lan yadurroo Allaha shayan yureedu Allahu alla yajAAala lahum haththan fee alakhirati walahum AAathabun AAatheemun', 1, NOW(), NOW()),
(3, 177, 'إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'যারা ঈমানের বদলে কুফরী ক্রয় করে নিয়েছে, তারা কখনোই আল্লাহ তায়ালার ক্ষতি করতে পারবে না, এদের জন্যে মর্মান্তিক শাস্তি রয়েছে।', 'Inna allatheena ishtarawoo alkufra bialeemani lan yadurroo Allaha shayan walahum AAathabun aleemun', 1, NOW(), NOW()),
(3, 178, 'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ', 'কাফেররা যেন এটা কখনো মনে না করে, আমি যে তাদের ঢিল দিয়ে রেখেছি এটা তাদের জন্যে কল্যাণকর হবে, (আসলে) আমি তো তাদের অবকাশ দিচ্ছি যেন তারা তাদের গুনাহ (-এর বোঝা) আরো বাড়িয়ে নিতে পারে, তাদের জন্যেই রয়েছে লাঞ্ছনাদায়ক আযাব।', 'Wala yahsabanna allatheena kafaroo annama numlee lahum khayrun lianfusihim innama numlee lahum liyazdadoo ithman walahum AAathabun muheenun', 1, NOW(), NOW()),
(3, 179, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ', 'আল্লাহ তায়ালা কখনো মুমীনদের- তোমরা বর্তমানে যে (ভালো মন্দে মিশানো) অবস্থার ওপর আছো এর ওপর ছেড়ে দিতে চান না, যতোক্ষণ না তিনি পাকপবিত্র (মানুষ)দের অপবিত্র (লোক)দের থেকে আলাদা করে দেবেন; (একইভাবে) এটাও আল্লাহ তায়ালার কাজ নয় যে, তিনি তোমাদের গায়বের কিছু অবহিত করবেন, তবে আল্লাহ তায়ালা তাঁর রসূলদের মাঝ থেকে যাকে চান তাকে (বিশেষ কাজের জন্যে) বাছাই করে নেন, অতপর তোমরা আল্লাহ তায়ালা ও তাঁর রসূলদের ওপর বিশ্বাস স্থাপন করো, তোমরা যদি (আল্লাহর ওপর) ঈমান আনো এবং তাকওয়া অবলম্বন করো, তাহলে তোমাদের জন্যে মহাপুরস্কার থাকবে।', 'Ma kana Allahu liyathara almumineena AAala ma antum AAalayhi hatta yameeza alkhabeetha mina alttayyibi wama kana Allahu liyutliAAakum AAala alghaybi walakinna Allaha yajtabee min rusulihi man yashao faaminoo biAllahi warusulihi wain tuminoo watattaqoo falakum ajrun AAatheemun', 1, NOW(), NOW()),
(3, 180, 'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ', 'আল্লাহ তায়ালা নিজের অনুগ্রহ দিয়ে তাদের যে প্রাচুর্য দিয়েছেন যারা তা আল্লাহর পথে ব্যয় করতে কার্পণ্য করে- তারা যেন কখনো এটা মনে না করে, এটা তাদের জন্যে কোনো কল্যাণকর কিছু হবে; না, এ (কৃপণতা আসলে) তাদের জন্যে খুবই অকল্যাণকর; কার্পণ্য করে তারা যা জমা করেছে, কেয়ামতের দিন অচিরেই তা দিয়ে তাদের গলায় বেড়ি পরিয়ে দেয়া হবে, আসমানসমূহ ও যমীনের উত্তরাধিকার আল্লাহ তায়ালার জন্যেই, আর তোমরা যা করো আল্লাহ তায়ালা তা সম্পর্কে সম্যক অবগত আছেন।', 'Wala yahsabanna allatheena yabkhaloona bima atahummu Allahu min fadlihi huwa khayran lahum bal huwa sharrun lahum sayutawwaqoona ma bakhiloo bihi yawma alqiyamati walillahi meerathu alssamawati waalardi waAllahu bima taAAmaloona khabeerun', 1, NOW(), NOW()),
(3, 181, 'لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ', 'আল্লাহ তায়ালা সেই (ইহুদী) লোকদের কথা (ভালো করেই) শুনেছেন, তারা (বিদ্রূপ করে) বলেছিলো, অবশ্যই আল্লাহ গরীব, আর আমরা হচ্ছি ধনী। তারা যা কিছু বলে তা আমি (তাদের হিসাবের খাতায় লিখে রাখবো, (আমি আরো লিখে রাখবো) অন্যায়ভাবে তাদের নবীদের হত্যা করার বিষয়টিও, (সেদিন) আমি তাদের বলবো, এবার তোমরা জাহান্নামের স্বাদ উপভোগ করো।', 'Laqad samiAAa Allahu qawla allatheena qaloo inna Allaha faqeerun wanahnu aghniyaon sanaktubu ma qaloo waqatlahumu alanbiyaa bighayri haqqin wanaqoolu thooqoo AAathaba alhareeqi', 1, NOW(), NOW()),
(3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ', 'এ (আযাব) হচ্ছে তোমাদের নিজেদেরই পাঠানো আমল, আল্লাহ তায়ালা কখনো (তাঁর) বান্দাদের প্রতি অবিচারক নন।', 'Thalika bima qaddamat aydeekum waanna Allaha laysa bithallamin lilAAabeedi', 1, NOW(), NOW()),
(3, 183, 'ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ', 'যারা বলে, (স্বয়ং) আল্লাহ তায়ালাই তো আমাদের প্রতিশ্রুতি দিয়েছেন যেন আমরা কোনো রসূলের ওপর ঈমান না আনি, যতোক্ষণ না সে আমাদের কাছে এমন একটা কোরবানী এনে হাযির করবে, যাকে (গায়ব থেকে এক) আগুন এসে খেয়ে ফেলবে; (হে মোহাম্মদ,) তুমি (তাদের) বলো, হ্যাঁ আমার আগে অনেক উজ্জ্বল নিদর্শন নিয়ে তোমাদের কাছে বহু নবী রসূল এসেছে, তোমরা যে কথা বলছো তা সবই (তারা নিয়ে এসেছিলো,) যদি তোমরা (তোমাদের দাবীতে) সত্যবাদী হও তাহলে কেন তাদের হত্যা করলে?', 'Allatheena qaloo inna Allaha AAahida ilayna alla numina lirasoolin hatta yatiyana biqurbanin takuluhu alnnaru qul qad jaakum rusulun min qablee bialbayyinati wabiallathee qultum falima qataltumoohum in kutum sadiqeena', 1, NOW(), NOW()),
(3, 184, 'فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ', '(হে মোহাম্মদ,) এরা যদি তোমাকে অস্বীকার করে (তাহলে তুমি ভেবো না, কারণ), তোমার আগেও এমন বহু নবী রসূল (নবুওতের) সুস্পষ্ট দলীল প্রমাণ ও (হেদায়াতের) দীপ্তিমান গ্রন্থমালা নিয়ে এসেছিলো, তাদেরও (এমনিভাবে) অস্বীকার করা হয়েছিলো।', 'Fain kaththabooka faqad kuththiba rusulun min qablika jaoo bialbayyinati waalzzuburi waalkitabi almuneeri', 1, NOW(), NOW()),
(3, 185, 'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ', 'প্রত্যেক প্রাণীই মরণের স্বাদ আস্বাদন করবে; (অতপর) তোমাদের (কর্মকান্ডের) পাওনা কেয়ামতের দিন পুরোপুরি আদায় করে দেয়া হবে, যাকে (জাহান্নামের) আগুন থেকে বাঁচিয়ে দেয়া হবে এবং জান্নাতে প্রবেশ করানো হবে; সে-ই সফলতা পাবে। (মনে রেখো,) এই পার্থিব জীবন (কিছু বাহ্যিক) ছলনার মাল সামানা ছাড়া আর কিছুই নয়।', 'Kullu nafsin thaiqatu almawti wainnama tuwaffawna ojoorakum yawma alqiyamati faman zuhziha AAani alnnari waodkhila aljannata faqad faza wama alhayatu alddunya illa mataAAu alghuroori', 1, NOW(), NOW()),
(3, 186, '۞لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ', '(হে ঈমানদার ব্যক্তিরা,) নিশ্চয়ই জান মালের (ক্ষতি সাধনের) মাধ্যমে তোমাদের পরীক্ষা নেয়া হবে। (এ পরীক্ষা দিতে গিয়ে) তোমরা অবশ্যই তোমাদের পূর্ববর্তী সম্প্রদায়- যাদের (আল্লাহর) কিতাব দেয়া হয়েছিলো এবং যারা (আল্লাহর সাথে অন্যদের) শরীক করেছে, তাদের (উভয়ের) কাছ থেকে অনেক কষ্টদায়ক কথাবার্তা শুনবে; এ অবস্থায় তোমরা যদি ধৈর্য ধারণ করো এবং আল্লাহকে ভয় করে চলো, তাহলে অবশ্যই তা হবে বড়ো ধরনের এক সাহসিকতার ব্যাপার।', 'Latublawunna fee amwalikum waanfusikum walatasmaAAunna mina allatheena ootoo alkitaba min qablikum wamina allatheena ashrakoo athan katheeran wain tasbiroo watattaqoo fainna thalika min AAazmi alomoori', 1, NOW(), NOW()),
(3, 187, 'وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ', '(স্মরণ করো,) যখন আল্লাহ তায়ালা তাদের কিতাবধারী ব্যক্তিদের কাছ থেকে এই মর্মে প্রতিশ্রুতি গ্রহণ করেছিলেন যে, তোমরা অবশ্যই একে মানুষদের কাছে বর্ণনা করবে এবং একে তোমরা গোপন করবে না, কিন্তু তারা এ প্রতিশ্রুতি নিজেদের পেছনে ফেলে রাখলো এবং অত্যন্ত অল্প মূল্যে তা বিক্রি করে দিলো; বড়োই নিকৃষ্ট ছিলো যা তারা বিক্রী করছে!', 'Waith akhatha Allahu meethaqa allatheena ootoo alkitaba latubayyinunnahu lilnnasi wala taktumoonahu fanabathoohu waraa thuhoorihim waishtaraw bihi thamanan qaleelan fabisa ma yashtaroona', 1, NOW(), NOW()),
(3, 188, 'لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'এমন সব লোকদের ব্যাপারে তুমি কখনো ভেবো না যারা নিজেরা যা করে তাতে আনন্দ প্রকাশ করে, আবার নিজেরা যা কখনো করেনি তার জন্যেও প্রশংসিত হতে ভালোবাসে, তুমি কখনো ভেবো না, এরা (বুঝি আল্লাহর) আযাব থেকে অব্যাহতি পেয়ে গেছে, (মূলত) এদের জন্যেই রয়েছে যন্ত্রণাদায়ক শাস্তি।', 'La tahsabanna allatheena yafrahoona bima ataw wayuhibboona an yuhmadoo bima lam yafAAaloo fala tahsabannahum bimafazatin mina alAAathabi walahum AAathabun aleemun', 1, NOW(), NOW()),
(3, 189, 'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'আসমানসমূহ ও যমীনের সার্বভৌমত্ব এককভাবে আল্লাহর জন্যে;আল্লাহ তায়ালা সবকিছুর ওপর একক ক্ষমতাবান।', 'Walillahi mulku alssamawati waalardi waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(3, 190, 'إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ', 'নিসন্দেহে আসমানসমূহ ও যমীনের (নিখুঁত) সৃষ্টি এবং দিবা রাত্রির আবর্তনের মাঝে জ্ঞানবান লোকদের জন্যে অনেক নিদর্শন রয়েছে।', 'Inna fee khalqi alssamawati waalardi waikhtilafi allayli waalnnahari laayatin liolee alalbabi', 1, NOW(), NOW()),
(3, 191, 'ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'যারা দাঁড়িয়ে, বসে এবং শুয়ে সর্বাবস্থায় আল্লাহ তায়ালাকে স্মরণ করে এবং আসমানসমূহ ও যমীনের এই সৃষ্টি (নৈপুণ্য) সম্পর্কে চিন্তা গবেষণা করে (এবং এসব দেখে তারা বলে), হে আমাদের রব, (সৃষ্টি জগত)-এর কোনো কিছুই তুমি অযথা পয়দা করোনি, তুমি অনেক পবিত্র, অতপর তুমি আমাদের জাহান্নামের কঠিন আযাব থেকে নিষ্কৃতি দাও।', 'Allatheena yathkuroona Allaha qiyaman waquAAoodan waAAala junoobihim wayatafakkaroona fee khalqi alssamawati waalardi rabbana ma khalaqta hatha batilan subhanaka faqina AAathaba alnnari', 1, NOW(), NOW()),
(3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ', 'হে আমাদের রব, যাকেই তুমি জাহান্নামের আগুনে প্রবেশ করাবে, অবশ্যই তাকে তুমি অপমানিত করবে। (সেদিন) যালেমদের কোনো সাহায্যকারীই থাকবে না।', 'Rabbana innaka man tudkhili alnnara faqad akhzaytahu wama lilththalimeena min ansarin', 1, NOW(), NOW()),
(3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ', 'হে আমাদের রব, আমরা শুনতে পেয়েছি একজন আহ্বানকারী (নবী- মানুষদের) ঈমানের দিকে ডাকছে (সে বলছিলো, হে মানুষরা), তোমরা তোমাদের মালিকের ওপর ঈমান আনো, (হে রব, সেই আহ্বানকারীর কথায়) আমরা ঈমান এনেছি, হে আমাদের রব, তুমি আমাদের অপরাধসমূহ ক্ষমা করে দাও, (আমাদের আমলনামা থেকে) আমাদের গুনাহসমূহ তুমি মুছে দাও, (তোমার) নেক লোকদের সাথে তুমি আমাদের মৃত্যু দান করো।', 'Rabbana innana samiAAna munadiyan yunadee lileemani an aminoo birabbikum faamanna rabbana faighfir lana thunoobana wakaffir AAanna sayyiatina watawaffana maAAa alabrari', 1, NOW(), NOW()),
(3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ', 'হে আমাদের রব, তুমি তোমার নবী রসূলদের মাধ্যমে যেসব (পুরস্কারের) প্রতিশ্রুতি আমাদের দিয়েছো তা তুমি আমাদের দান করো এবং কেয়ামতের দিন তুমি আমাদের অপমানিত করো না; নিশ্চয়ই তুমি ওয়াদার বরখেলাপ করো না।', 'Rabbana waatina ma waAAadtana AAala rusulika wala tukhzina yawma alqiyamati innaka la tukhlifu almeeAAada', 1, NOW(), NOW()),
(3, 195, 'فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ', 'অতপর তাদের রব (এই বলে) তাদের ডাকে সাড়া দিলেন যে, নর-নারী নির্বিশেষে তোমাদের যে যেই কাজ করে, আমি তাদের কোনো কাজ কখনো বিনষ্ট করবো না এবং তোমরা তো একে অপরের মতো, অতপর যারা (নিজেদের ভিটেমাটি ছেড়ে) হিজরত করেছে এবং যাদের নিজেদের জন্মভূমি থেকে বের করে দেয়া হয়েছে, আমারই পথে যারা নির্যাতিত হয়েছে, (সর্বোপরি) যারা (আমার জন্যে) লড়াই করেছে এবং (আমারই জন্যে) জীবন দিয়েছে, অবশ্যই আমি তাদের গুনাহসমূহ মাফ করে দেবো, অবশ্যই আমি তাদের (এমন) জান্নাতে প্রবেশ করাবো, যার তলদেশ দিয়ে ঝর্ণাধারা বইতে থাকবে, এ হচ্ছে আল্লাহ তায়ালার পক্ষ থেকে পুরস্কার, আর (যাবতীয়) উত্তম পুরস্কার তো আল্লাহ তায়ালার কাছেই রয়েছে!', 'Faistajaba lahum rabbuhum annee la odeeAAu AAamala AAamilin minkum min thakarin aw ontha baAAdukum min baAAdin faallatheena hajaroo waokhrijoo min diyarihim waoothoo fee sabeelee waqataloo waqutiloo laokaffiranna AAanhum sayyiatihim walaodkhilannahum jannatin tajree min tahtiha alanharu thawaban min AAindi Allahi waAllahu AAindahu husnu alththawabi', 1, NOW(), NOW()),
(3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ', '(হে মোহাম্মদ,) জনপদসমূহে যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে, তাদের (দাম্ভিক) পদচারণা যেন কোনোভাবেই তোমাকে প্রতারিত না করে।', 'La yaghurrannaka taqallubu allatheena kafaroo fee albiladi', 1, NOW(), NOW()),
(3, 197, 'مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ', '(কেননা তাদের এ পদচারনা) সামান্য (কয়দিনের) সামগ্রী মাত্র, অতপর তাদের নিবাস (হবে) জাহান্নাম; আর জাহান্নাম হচ্ছে নিকৃষ্টতম আবাসস্থল!', 'MataAAun qaleelun thumma mawahum jahannamu wabisa almihadu', 1, NOW(), NOW()),
(3, 198, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ', 'তবে যারা নিজেদের মালিককে ভয় করেছে, তাদের জন্যে রয়েছে (সুরমা) উদ্যানমালা, যার নীচ দিয়ে প্রবাহিত হবে ঝর্ণাধারা, সেখানে তারা অনাদিকাল থাকবে, এ হবে আল্লাহ তায়ালার পক্ষ থেকে (তাদের) আতিথেয়তা, আর আল্লাহ তায়ালার কাছে যা আছে, তা অবশ্যই নেককার লোকদের জন্যে অতি উত্তম জিনিস!', 'Lakini allatheena ittaqaw rabbahum lahum jannatun tajree min tahtiha alanharu khalideena feeha nuzulan min AAindi Allahi wama AAinda Allahi khayrun lilabrari', 1, NOW(), NOW()),
(3, 199, 'وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَـٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', '(ইতিপূর্বে) আমি যাদের কাছে কিতাব পাঠিয়েছি, সেসব কিতাবধারী লোকদের মাঝে এমন লোক অবশ্যই আছে, যারা আল্লাহকে বিশ্বাস করে, তোমাদের এ কিতাবের ওপর তারা (যেমনি) বিশ্বাস করে, (তেমনি) তারা বিশ্বাস করে তাদের ওপর পাঠানো কিতাবের ওপরও, এরা হচ্ছে আল্লাহর ভীত সন্ত্রস্ত ও বিনয়ী বান্দা, এরা আল্লাহর আয়াতসমূহকে (স্বার্থের বিনিময়ে) সামান্য মূল্যে বিক্রি করে না, এরাই হচ্ছে সেসব ব্যক্তি, যাদের জন্যে তাদের মালিকের কাছে পাওনা (সংরক্ষিত) রয়েছে, নিসন্দেহে আল্লাহ তায়ালা হচ্ছেন দ্রুত হিসাব সম্পন্নকারী।', 'Wainna min ahli alkitabi laman yuminu biAllahi wama onzila ilaykum wama onzila ilayhim khashiAAeena lillahi la yashtaroona biayati Allahi thamanan qaleelan olaika lahum ajruhum AAinda rabbihim inna Allaha sareeAAu alhisabi', 1, NOW(), NOW()),
(3, 200, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ', 'হে মানুষ, যারা ঈমান এনেছো, তোমরা ধৈর্য ধারণ করো, (এ কাজে) সুদৃঢ় থেকো, (শত্রুর মোকাবেলায়) তৎপর থেকো, একমাত্র আল্লাহকেই ভয় করো, আশা করা যায় তোমরা সফলকাম হতে পারবে!', 'Ya ayyuha allatheena amanoo isbiroo wasabiroo warabitoo waittaqoo Allaha laAAallakum tuflihoona', 1, NOW(), NOW()),
(4, 1, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا', 'হে মানুষ, তোমরা তোমাদের মালিককে ভয় করো, যিনি তোমাদের একটি (মাত্র) ব্যক্তিসত্তা থেকে সৃষ্টি করেছেন, অতঃপর তিনি তা থেকে (তার) জুড়ি সৃষ্টি করেছেন, তাদের (এই আদি জুড়ি) থেকে তিনি বহু সংখ্যক নর-নারী (দুনিয়ায়) ছড়িয়ে দিয়েছেন (হে মানুষ), তোমরা ভয় করো আল্লাহ তায়ালাকে, যাঁর (পবিত্র) নামে তোমরা একে অপরের কাছে অধিকার দাবী করো এবং (সম্মান করো) গর্ভ (ধারিণী মা)-কে, অবশ্যই আল্লাহ তায়ালা তোমাদের ওপর তীক্ষ্ণ দৃষ্টি রাখেন।', 'Ya ayyuha alnnasu ittaqoo rabbakumu allathee khalaqakum min nafsin wahidatin wakhalaqa minha zawjaha wabaththa minhuma rijalan katheeran wanisaan waittaqoo Allaha allathee tasaaloona bihi waalarhama inna Allaha kana AAalaykum raqeeban', 1, NOW(), NOW()),
(4, 2, 'وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا', 'ইয়াতীমদের ধন-সম্পদ তাদের কাছে দিয়ে দাও, (তাদের) ভালো জিনিসের সাথে (নিজেদের) খারাপ জিনিসের বদল করো না, তাদের সম্পদসমূহ কখনো নিজেদের মালের সাথে মিলিয়ে হযম করে নিয়ো না, অবশ্যই তা জঘন্য পাপ।', 'Waatoo alyatama amwalahum wala tatabaddaloo alkhabeetha bialttayyibi wala takuloo amwalahum ila amwalikum innahu kana hooban kabeeran', 1, NOW(), NOW()),
(4, 3, 'وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ', 'আর যদি তোমরা এ আশংকা করো যে, তোমরা ইয়াতীম (মেয়ে)-দের মাঝে ন্যায়বিচার করতে পারবে না, তাহলে (তাদের বদলে সাধারণ) নারীদের মাঝে থেকে তোমাদের যাদের ভালো লাগে তাদের দুই জন, তিন জন কিংবা চার জনকে বিয়ে করে নাও, যদি তোমরা ভয় করো যে, তোমরা (একের অধিক হলে তাদের মাঝে) ইনসাফ করতে পারবে না, তাহলে (তোমাদের জন্যে) একজনই (যথেষ্ট), কিংবা যে তোমাদের অধিকারভুক্ত; (তাদেরই যথেষ্ট মনে করে নাও। ) সীমালংঘন থেকে বেঁচে থাকার জন্যে এটাই (উত্তম ও) সহজতর (পন্থা)।', 'Wain khiftum alla tuqsitoo fee alyatama fainkihoo ma taba lakum mina alnnisai mathna wathulatha warubaAAa fain khiftum alla taAAdiloo fawahidatan aw ma malakat aymanukum thalika adna alla taAAooloo', 1, NOW(), NOW()),
(4, 4, 'وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا', 'নারীদের তাদের মোহরানার অংক খুশী মনে তাদের (মালিকানায়) দিয়ে দাও; অতঃপর তারা যদি খুশী হয়ে এর কিছু অংশ তোমাদের (ছেড়ে) দেয়, তাহলে তোমরা তাও খুশী মনে ভোগ করো।', 'Waatoo alnnisaa saduqatihinna nihlatan fain tibna lakum AAan shayin minhu nafsan fakuloohu haneean mareean', 1, NOW(), NOW()),
(4, 5, 'وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا', 'আল্লাহ তায়ালা তোমাদের যে সম্পদ (দুনিয়ায়) তোমাদের প্রতিষ্ঠা লাভের উপকরণ বানিয়ে দিয়েছেন, তা নির্বোধ লোকদের হাতে ছেড়ে দিয়ো না, (অবশ্যই এ থেকে) তাদের খাওয়ার ব্যবস্থা করবে, তাদের পোশাক সরবরাহ করবে, (সর্বোপরি) তাদের সাথে ভালো কথা বলবে।', 'Wala tutoo alssufahaa amwalakumu allatee jaAAala Allahu lakum qiyaman waorzuqoohum feeha waoksoohum waqooloo lahum qawlan maAAroofan', 1, NOW(), NOW()),
(4, 6, 'وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا', 'ইয়াতীমদের প্রতি লক্ষ্য রাখতে হবে যতোক্ষণ না তারা বিয়ের বয়স পর্যন্ত পৌঁছে, অতঃপর যদি তোমরা তাদের মধ্যে (সম্পদ পরিচালনার) যোগ্যতা অনুভব করতে পারো, তাহলে তাদের ধন-সম্পদ তাদের হাতেই তুলে দেবে এবং তাদের বড়ো হবার আগেই (তাড়াহুড়ো করে) তা হযম করে ফেলো না, (ইয়াতীমদের পৃষ্ঠপোষক) যদি সম্পদশালী হয় তাহলে সে যেন (এই বাড়াবাড়ি থেকে) বেঁচে থাকে (তবে হ্যাঁ), যদি সে (পৃষ্ঠপোষক) গরীব হয় তাহলে (সমাজের) প্রচলিত নিয়ম অনুযায়ী সে যেন তা থেকে (নিজের পারিশ্রমিক) গ্রহণ করে, যখন তোমরা তাদের ধন-সম্পদ তাদের ফিরিয়ে দেবে, তখন তাদের ওপর সাক্ষী রেখো, (যদিও) হিসাব গ্রহণের জন্যে আল্লাহ তায়ালাই যথেষ্ট!', 'Waibtaloo alyatama hatta itha balaghoo alnnikaha fain anastum minhum rushdan faidfaAAoo ilayhim amwalahum wala takulooha israfan wabidaran an yakbaroo waman kana ghaniyyan falyastaAAfif waman kana faqeeran falyakul bialmaAAroofi faitha dafaAAtum ilayhim amwalahum faashhidoo AAalayhim wakafa biAllahi haseeban', 1, NOW(), NOW()),
(4, 7, 'لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا', '(তাদের) পিতামাতা ও আত্মীয়-স্বজনদের রেখে যাওয়া ধন-সম্পদে পুরুষদের (যেমন) অংশ রয়েছে, (একইভাবে ) নারীদের জন্যেও (সে সম্পদে) অংশ রয়েছে, যা (তাদের) পিতা-মাতা ও আত্মীয় স্বজনরা রেখে গেছে, (পরিমাণ) অল্প হোক কিংবা বেশী; (উভয়ের জন্যেই এর) অংশ নির্দিষ্ট করে দেয়া হয়েছে।', 'Lilrrijali naseebun mimma taraka alwalidani waalaqraboona walilnnisai naseebun mimma taraka alwalidani waalaqraboona mimma qalla minhu aw kathura naseeban mafroodan', 1, NOW(), NOW()),
(4, 8, 'وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا', '(মৃত ব্যক্তির সম্পদ) বন্টনের সময় যখন (তার) আপনজন, ইয়াতীম ও মিসকীনরা (সেখানে) এসে হাযির হয়, তখন তা থেকে তাদেরও কিছু দেবে এবং তাদের সাথে সুন্দরভাবে কথা বলবে।', 'Waitha hadara alqismata oloo alqurba waalyatama waalmasakeenu faorzuqoohum minhu waqooloo lahum qawlan maAAroofan', 1, NOW(), NOW()),
(4, 9, 'وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا', 'মানুষের (এটুকু) ভয় করা উচিত, যদি তারা (মৃত্যুর সময় এমনি কিছু) দুর্বল সন্তানদের পেছনে রেখে চলে আসতো, তাহলে (তাদের ব্যাপারে) তারা (এভাবেই) ভীত শংকিত থাকতো, অতএব তারা যেন আল্লাহকে ভয় করে এবং এদের সাথে ন্যায়-ইনসাফের কথাবার্তা বলে।', 'Walyakhsha allatheena law tarakoo min khalfihim thurriyyatan diAAafan khafoo AAalayhim falyattaqoo Allaha walyaqooloo qawlan sadeedan', 1, NOW(), NOW()),
(4, 10, 'إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا', 'যারা অন্যায়ভাবে ইয়াতীমদের মাল-সম্পদ ভক্ষণ করে, তারা যেন আগুন দিয়েই নিজেদের পেট ভর্তি করে, অচিরেই এ লোকগুলো জাহান্নামের আগুনে জ্বলতে থাকবে।', 'Inna allatheena yakuloona amwala alyatama thulman innama yakuloona fee butoonihim naran wasayaslawna saAAeeran', 1, NOW(), NOW()),
(4, 11, 'يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا', 'আল্লাহ তায়ালা (তোমাদের রেখে যাওয়া সম্পদে) তোমাদের সন্তানদের সম্পর্কে (এ মর্মে) তোমাদের জন্যে বিধান জারি করছেন যে, এক ছেলের অংশ হবে দুই কন্যা সন্তানের মতো, হ্যাঁ (উত্তরাধিকারী) কন্যারা যদি দু’য়ের বেশী হয় তাহলে তাদের জন্যে (থাকবে) রেখে যাওয়া সম্পত্তির দুই তৃতীয়াংশ, আর (সে) কন্যা সন্তান যদি একজন হয়, তাহলে তার (অংশ) হবে (রেখে যাওয়া সম্পত্তির) অর্ধেক; মৃত ব্যক্তির সন্তান থাকলে তার পিতামাতার প্রত্যেকের জন্যে থাকবে (সে সম্পদের) ছয় ভাগের এক ভাগ, (অপর দিকে) মৃত ব্যক্তির যদি কোনো সন্তান না থাকে এবং পিতামাতাই যদি হয় (তার একমাত্র) উত্তরাধিকারী, তাহলে তার মায়ের (অংশ) হবে তিন ভাগের এক ভাগ, যদি মৃত ব্যক্তির কোনো ভাই বোন (বেঁচে) থাকে তাহলে তার মায়ের (অংশ) হবে ছয় ভাগের এক ভাগ, (মৃত্যুর) আগে সে যে ওসিয়ত করে গেছে এবং তার (রেখে যাওয়া) ঋণ আদায় করে দেয়ার পরই (কিন্তু ভাগ-বাটোয়ারা করতে হবে); তোমরা জানো না তোমাদের পিতামাতা ও তোমাদের সন্তান-সন্ততির মধ্যে কে তোমাদের জন্যে উপকারের দিক থেকে বেশী নিকটবর্তী। (এ হচ্ছে) আল্লাহর বিধান, অবশ্যই আল্লাহ তায়ালা হচ্ছেন বিজ্ঞ, পরম কুশলী।', 'Yooseekumu Allahu fee awladikum lilththakari mithlu haththi alonthayayni fain kunna nisaan fawqa ithnatayni falahunna thulutha ma taraka wain kanat wahidatan falaha alnnisfu waliabawayhi likulli wahidin minhuma alssudusu mimma taraka in kana lahu waladun fain lam yakun lahu waladun wawarithahu abawahu faliommihi alththuluthu fain kana lahu ikhwatun faliommihi alssudusu min baAAdi wasiyyatin yoosee biha aw daynin abaokum waabnaokum la tadroona ayyuhum aqrabu lakum nafAAan fareedatan mina Allahi inna Allaha kana AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 12, '۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ', 'তোমাদের স্ত্রীদের রেখে যাওয়া সম্পত্তিতে তোমাদের অংশ হচ্ছে অর্ধেক- যদি তাদের কোনো সন্তানাদি না থাকে, আর যদি তাদের সন্তান থাকে তাহলে (সে সম্পত্তিতে) তোমাদের অংশ হবে চার ভাগের এক ভাগ, তারা যে ওসিয়ত করে গেছে কিংবা (তাদের) ঋণ পরিশোধ করার পরই (কিন্তু তোমরা এই অংশ পাবে); তোমাদের স্ত্রীদের জন্যে (থাকবে) তোমাদের রেখে যাওয়া সম্পত্তির এক চতুর্থাংশ- যদি তোমাদের কোনো সন্তান না থাকে, যদি তোমাদের সন্তান থাকে, তাহলে তারা পাবে রেখে যাওয়া সম্পদের আট ভাগের এক ভাগ, (মৃত্যুর আগে) তোমরা যা ওসিয়ত করে যাবে কিংবা যে ঋণ (তোমরা রেখে যাবে) তা পরিশোধ করে। দেয়ার পরই (এই অংশ তারা পাবে); যদি কোনো পুরুষ কিংবা নারী এমন হয় যে, তার কোনো সন্তানও নেই, পিতা মাতাও নেই, (শুধু) আছে তার এক ভাই ও এক বোন, তাহলে তাদের সবার জন্যে থাকবে ছয় ভাগের এক ভাগ, (ভাই বোন মিলে) তারা যদি এর চাইতে বেশী হয় তবে (রেখে যাওয়া সম্পদের) এক-তৃতীয়াংশে তারা সবাই (সমান) অংশীদার হবে, অবশ্য (এ সম্পত্তির ওপর) মৃত ব্যক্তির যা ওসিয়ত করা আছে কিংবা কোনো ঋণ (পরিশোধ)-এর পরই (এ ভাগাভাগি সম্পন্ন হবে), তবে (খেয়াল রাখতে হবে, কখনো উত্তরাধিকারীদের অধিকার পাওয়ার পথে) তা যেন ক্ষতিকর না হয়, (কেননা) এ নির্দেশ হচ্ছে আল্লাহর পক্ষ থেকে; আর আল্লাহ তায়ালা সর্বজ্ঞানী ও পরম ধৈর্যশীল।', 'Walakum nisfu ma taraka azwajukum in lam yakun lahunna waladun fain kana lahunna waladun falakumu alrrubuAAu mimma tarakna min baAAdi wasiyyatin yooseena biha aw daynin walahunna alrrubuAAu mimma taraktum in lam yakun lakum waladun fain kana lakum waladun falahunna alththumunu mimma taraktum min baAAdi wasiyyatin toosoona biha aw daynin wain kana rajulun yoorathu kalalatan awi imraatun walahu akhun aw okhtun falikulli wahidin minhuma alssudusu fain kanoo akthara min thalika fahum shurakao fee alththuluthi min baAAdi wasiyyatin yoosa biha aw daynin ghayra mudarrin wasiyyatan mina Allahi waAllahu AAaleemun haleemun', 1, NOW(), NOW()),
(4, 13, 'تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'এগুলো হচ্ছে আল্লাহ তায়ালার সীমারেখা; যে ব্যক্তি (এর ভেতরে থেকে) আল্লাহ ও তাঁর রাসূলের আনুগত্য করবে, (আল্লাহ তায়ালা) তাকে এমন এক জান্নাতে প্রবেশ করাবেন যার তলদেশ দিয়ে ঝর্ণাধারা প্রবাহিত হবে, সেখানে তারা অনন্তকাল ধরে অবস্থান করবে; (মূলত) এ হচ্ছে এক মহাসাফল্য।', 'Tilka hudoodu Allahi waman yutiAAi Allaha warasoolahu yudkhilhu jannatin tajree min tahtiha alanharu khalideena feeha wathalika alfawzu alAAatheemu', 1, NOW(), NOW()),
(4, 14, 'وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ', '(অপরদিকে) যে ব্যক্তি আল্লাহ তায়ালা ও তাঁর রাসূলের না-ফরমানী করবে এবং আল্লাহ তায়ালার (নির্ধারিত) সীমারেখা লংঘন করবে, তিনি তাকে (জ্বলন্ত) আগুনে প্রবেশ করাবেন, সেখানে সে অনন্তকাল থাকবে, তার জন্যে (রয়েছে) অপমানকর শাস্তি।', 'Waman yaAAsi Allaha warasoolahu wayataAAadda hudoodahu yudkhilhu naran khalidan feeha walahu AAathabun muheenun', 1, NOW(), NOW()),
(4, 15, 'وَٱلَّـٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا', 'তোমাদের নারীদের মধ্যে যারা (ব্যভিচারের) দুষ্কর্মে অভিযুক্ত হয়ে আসবে তাদের (বিচারের) ওপর তোমরা নিজেদের মধ্যে থেকে চার জন সাক্ষী যোগাড় করবে, অতঃপর সে চার জন লোক যদি (ইতিবাচক) সাক্ষ্য প্রদান করে তাহলে সে নারীদের তোমরা ঘরের ভেতর অবরুদ্ধ করে রাখবে, যতোদিন না মৃত্যু এসে তাদের (জীবনের) সমাপ্তি ঘটিয়ে দেয়, অথবা আল্লাহ তায়ালা তাদের জন্যে অন্য কোনো ব্যবস্থা করেন।', 'Waallatee yateena alfahishata min nisaikum faistashhidoo AAalayhinna arbaAAatan minkum fain shahidoo faamsikoohunna fee albuyooti hatta yatawaffahunna almawtu aw yajAAala Allahu lahunna sabeelan', 1, NOW(), NOW()),
(4, 16, 'وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا', 'আর তোমাদের মধ্যে যে দুজন (নর-নারী) এ (ব্যভিচারের) কাজ করবে, তাদের দুজনকেই তোমরা শাস্তি দেবে, (হ্যাঁ) তারা যদি তাওবা করে এবং নিজেদের সংশোধন করে নেয়, তাহলে তাদের (শাস্তি দেয়া) থেকে তোমরা সরে দাঁড়াও, অবশ্যই আল্লাহ তায়ালা তাওবা কবুলকারী এবং পরম দয়ালু।', 'Waallathani yatiyaniha minkum faathoohuma fain taba waaslaha faaAAridoo AAanhuma inna Allaha kana tawwaban raheeman', 1, NOW(), NOW()),
(4, 17, 'إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', 'আল্লাহ তায়ালার ওপর শুধু তাদের তাওবাই (কবুলযোগ্য) হবে, যারা অজ্ঞতার সাথে গুনাহের কাজ করে, অতঃপর (জানা মাত্রই) তারা দ্রুত (তা থেকে) ফিরে আসে, (মূলত) এরাই হচ্ছে সেসব লোক, যাদের ওপর আল্লাহ তায়ালা দয়াপরবশ হন; আর আল্লাহ তায়ালাই হচ্ছেন সর্ববিষয়ে জ্ঞানী, কুশলী।', 'Innama alttawbatu AAala Allahi lillatheena yaAAmaloona alssooa bijahalatin thumma yatooboona min qareebin faolaika yatoobu Allahu AAalayhim wakana Allahu AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 18, 'وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَـٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا', 'আর তাদের জন্যে কোনো তাওবা নেই, যারা (আজীবন) শুধু গুনাহের কাজই করে, এভাবেই একদিন তাদের কারো (দুয়ারে) যখন মৃত্যু এসে হাযির হয়, তখন সে বলে (হে আল্লাহ), আমি এখন তাওবা করলাম, তাদের জন্যেও (কোনো তাওবা) নয় যারা কাফের অবস্থায় ইহলীলা সাঙ্গ করলো; এরাই হচ্ছে সেসব লোক, যাদের জন্যে আমি কঠিন যন্ত্রণাদায়ক আযাবের ব্যবস্থা করে রেখেছি।', 'Walaysati alttawbatu lillatheena yaAAmaloona alssayyiati hatta itha hadara ahadahumu almawtu qala innee tubtu alana wala allatheena yamootoona wahum kuffarun olaika aAAtadna lahum AAathaban aleeman', 1, NOW(), NOW()),
(4, 19, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, তোমাদের জন্যে কখনো জোর করে বিধবা নারীদের উত্তরাধিকারের পণ্য বানানো বৈধ নয়, (বিয়ের সময় মোহর হিসেবে) যা তোমরা তাদের দিয়েছো তার কোনো অংশ তাদের কাছ থেকে নিয়ে নেয়ার জন্যে তোমরা তাদের আটক করে রেখো না, যতোক্ষণ পর্যন্ত তারা প্রকাশ্য কোনো ব্যভিচারের (অভিযুক্ত) না হয়ে আসে, তাদের সাথে সদ্ভাবে জীবন যাপন করো, তোমরা যদি তাদের পছন্দ নাও করো, মনে রেখো এমনও তো হতে পারে, যা কিছু তোমরা পছন্দ করো না তার মধ্যেই আল্লাহ তায়ালা (তোমাদের জন্যে) অফুরন্ত কল্যাণ নিহিত রেখেছেন।', 'Ya ayyuha allatheena amanoo la yahillu lakum an tarithoo alnnisaa karhan wala taAAduloohunna litathhaboo bibaAAdi ma ataytumoohunna illa an yateena bifahishatin mubayyinatin waAAashiroohunna bialmaAAroofi fain karihtumoohunna faAAasa an takrahoo shayan wayajAAala Allahu feehi khayran katheeran', 1, NOW(), NOW()),
(4, 20, 'وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا', 'আর যদি তোমরা এক স্ত্রীর জায়গায় আরেক স্ত্রী গ্রহণ করার সংকল্প করেই নাও, তাহলে (মোহর হিসেবে) যে বিপুল পরিমাণ সোনাদানা তোমরা দিয়েছো তার কোনো অংশ তোমরা তার কাছ থেকে ফেরত নিয়ো না; তোমরা কি (মিথ্যা) অপবাদ দিয়ে ও সুস্পষ্ট পাপাচার করে তা ফেরত নিতে চাচ্ছো?', 'Wain aradtumu istibdala zawjin makana zawjin waataytum ihdahunna qintaran fala takhuthoo minhu shayan atakhuthoonahu buhtanan waithman mubeenan', 1, NOW(), NOW()),
(4, 21, 'وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا', 'তোমরা (মোহরানার) সে অংশটুকু ফেরত নেবেই বা কী করে? অথচ (বিভিন্নভাবে) তোমরা তো একে অপরের স্বাদ গ্রহণ করেছো, (তাছাড়া) তারা তোমাদের কাছ থেকে (বিয়ে বন্ধনের) পাকাপাকি একটা প্রতিশ্রুতিও আদায় করে নিয়েছিলো।', 'Wakayfa takhuthoonahu waqad afda baAAdukum ila baAAdin waakhathna minkum meethaqan ghaleethan', 1, NOW(), NOW()),
(4, 22, 'وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا', 'নারীদের মধ্য থেকে তোমাদের পিতা (পিতামহ)-রা যাদের বিয়ে করেছে তাদের তোমরা কখনো বিয়ে করো না, (হ্যাঁ, এ নির্দেশ আসার) আগে যা হয়ে গেছে তা তো হয়েই গেছে, এটি (আসলেই) ছিলো অশ্লীল (নির্লজ্জ) কাজ এবং খুবই ঘৃণ্য ও নিকৃষ্ট আচরণ।', 'Wala tankihoo ma nakaha abaokum mina alnnisai illa ma qad salafa innahu kana fahishatan wamaqtan wasaa sabeelan', 1, NOW(), NOW()),
(4, 23, 'حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّـٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّـٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَـٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', '(বিয়ের জন্যে) তোমাদের ওপর হারাম করে দেয়া হয়েছে– তোমাদের মা, তোমাদের মেয়ে, তোমাদের বোন, তোমাদের ফুফু, তোমাদের খালা, ভাইদের মেয়ে, বোনদের মেয়ে, (আরো হারাম করা হয়েছে) সেসব মা– যারা তোমাদের বুকের দুধ খাইয়েছে, তোমাদের দুধ বোন, তোমাদের স্ত্রীদের মা, তোমাদের স্ত্রীদের মাঝে যাদের সাথে তোমরা সহবাস করেছো তাদের আগের স্বামীর ঔরসজাত মেয়েরা– যারা তোমাদের অভিভাবকত্বে রয়েছে, যদি তাদের সাথে তোমাদের শুধু বিয়ে হয়ে থাকে, (কিন্তু) কখনো তোমরা তাদের সাথে সহবাস করোনি, তাহলে (তাদের আগের স্বামীর মেয়েদের বিয়ে করায়) তোমাদের জন্যে কোনো দোষ নেই, (তোমাদের জন্যে) তোমাদের নিজেদের ঔরসজাত ছেলেদের স্ত্রীদের হারাম করা হয়েছে; (উপরন্তু বিয়ের বন্ধনে) তোমাদের ওপর দুই বোনকে একত্র করাও (হারাম করা হয়েছে), তবে যা কিছু (এর) আগে সংঘটিত হয়ে গেছে (তা তো হয়েই গেছে, সে ব্যাপারে) অবশ্যই আল্লাহ তায়ালা বড়োই ক্ষমাশীল ও একান্ত দয়াবান।', 'Hurrimat AAalaykum ommahatukum wabanatukum waakhawatukum waAAammatukum wakhalatukum wabanatu alakhi wabanatu alokhti waommahatukumu allatee ardaAAnakum waakhawatukum mina alrradaAAati waommahatu nisaikum warabaibukumu allatee fee hujoorikum min nisaikumu allatee dakhaltum bihinna fain lam takoonoo dakhaltum bihinna fala junaha AAalaykum wahalailu abnaikumu allatheena min aslabikum waan tajmaAAoo bayna alokhtayni illa ma qad salafa inna Allaha kana ghafooran raheeman', 1, NOW(), NOW()),
(4, 24, '۞وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا', 'নারীদের মাঝে (বিয়ের) দুর্গে অবস্থানকারীদেরও (তোমাদের জন্যে হারাম করা হয়েছে), তবে যেসব নারী (যুদ্ধবন্দী হয়ে) তোমাদের অধিকারে এসে পড়েছে তারা ব্যতীত, (এ হচ্ছে বিয়ের ব্যাপারে) তোমাদের ওপর আল্লাহ তায়ালার বিধান, এর বাইরে যে সব (নারী) রয়েছে, তাদের তোমাদের জন্যে (এ শর্তে) হালাল করা হয়েছে যে, তোমরা (বিয়ের জন্যে মোহরের) কিছু সম্পদ দ্বারা তাদের পেতে চাইবে এবং তোমরা (বিয়ের) সংরক্ষিত দুর্গে অবস্থান করবে, তোমরা অবাধ যৌনস্পৃহা পূরণে নিয়োজিত হবে না; অতঃপর তাদের মধ্যে যাদের তোমরা (বিয়ের) মাধ্যমে উপভোগ করবে, তাদের বিনিময় (মোহর) ফরয হিসেবে আদায় করে দাও, (অবশ্য) মোহর নির্ধারিত হয়ে যাওয়ার পর যে (পরিমাণের) ওপর তোমরা উভয়ে একমত হও, তাতে কোনো দোষের কিছু নেই, নিশ্চয়ই আল্লাহ তায়ালা সর্বজ্ঞ, কুশলী,', 'Waalmuhsanatu mina alnnisai illa ma malakat aymanukum kitaba Allahi AAalaykum waohilla lakum ma waraa thalikum an tabtaghoo biamwalikum muhsineena ghayra musafiheena fama istamtaAAtum bihi minhunna faatoohunna ojoorahunna fareedatan wala junaha AAalaykum feema taradaytum bihi min baAAdi alfareedati inna Allaha kana AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 25, 'وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'আর তোমাদের মধ্যে যে ব্যক্তির স্বাধীন ও সম্ভ্রান্ত কোনো ঈমানদার নারীকে বিয়ে করার (আর্থিক) সামর্থ থাকবে না, সে যেন তোমাদের অধিকারভুক্ত কোনো ঈমানদার নারীকে বিয়ে করে নেয়; তোমাদের ঈমান সম্পর্কে আল্লাহ তায়ালা সম্যক অবগত আছেন; (ঈমানের মাপকাঠিতে) তোমরা তো একই রকম, অতঃপর (যারা তোমাদের অধিকারভুক্ত) তোমরা তাদের অভিভাবকদের অনুমতি নিয়ে বিয়ে করো এবং তাদের ন্যায়-ইনসাফভিত্তিক যথার্থ মোহরানা দিয়ে দাও (এর উদ্দেশ্য হচ্ছে), তারা (যেন) বিয়ের দুর্গে সুরক্ষিত হয়ে যায়-(স্বেচ্ছাচারিণী হয়ে) পরপুরুষকে আনন্দদানের কাজে নিয়োজিত না থাকে, অতঃপর যখন তাদের বিয়ের দুর্গে অবস্থান করে দেয়া হলো, তখন যদি তারা ব্যভিচারে লিপ্ত হয়, (তখন) তাদের ওপর আরোপিত শাস্তির পরিমাণ কিন্তু (বিয়ের) দুর্গে অবস্থানকারিণী স্বাধীন (সম্ভ্রান্ত) নারীদের ওপর (আরোপিত শাস্তির) অর্ধেক; তোমাদের মধ্যে যাদের ব্যভিচারে লিপ্ত হবার আশংকা থাকবে, (শুধু) তাদের জন্যেই এ (রেয়াত)- টুকু (দেয়া হয়েছে, কিন্তু) তোমরা যদি ধৈর্য ধারণ করতে পারো, তা তোমাদের জন্যে কল্যাণকর এবং আল্লাহ তায়ালা একান্ত ক্ষমাপরায়ণ, পরম দয়ালু।', 'Waman lam yastatiAA minkum tawlan an yankiha almuhsanati almuminati famin ma malakat aymanukum min fatayatikumu almuminati waAllahu aAAlamu bieemanikum baAAdukum min baAAdin fainkihoohunna biithni ahlihinna waatoohunna ojoorahunna bialmaAAroofi muhsanatin ghayra masafihatin wala muttakhithati akhdanin faitha ohsinna fain atayna bifahishatin faAAalayhinna nisfu ma AAala almuhsanati mina alAAathabi thalika liman khashiya alAAanata minkum waan tasbiroo khayrun lakum waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(4, 26, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'আল্লাহ তায়ালা (তাঁর বাণীসমূহ) তোমাদের কাছে স্পষ্ট করে বলে দিতে চান এবং তিনি তোমাদেরকে তোমাদের পূর্ববর্তী (পুণ্যবান) মানুষদের পথে পরিচালিত করতে চান, আর (এর মাধ্যমে ) তিনি তোমাদের ওপর দয়াপরবশ হতে চান, আল্লাহ তায়ালা সর্বজ্ঞ, কুশলী।', 'Yureedu Allahu liyubayyina lakum wayahdiyakum sunana allatheena min qablikum wayatooba AAalaykum waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(4, 27, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا', 'আল্লাহ তায়ালা তোমাদের ওপর ক্ষমাপরবশ হতে চান, (অপরদিকে) যারা নিজেদের (পাশবিক) লালসার অনুসরণ করে তারা চায়, তোমরা সে (ক্ষমার পথ থেকে) বহুদূরে (নিক্ষিপ্ত হয়ে গোমরাহ) থেকে যাও।', 'WaAllahu yureedu an yatooba AAalaykum wayureedu allatheena yattabiAAoona alshshahawati an tameeloo maylan AAatheeman', 1, NOW(), NOW()),
(4, 28, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا', 'আল্লাহ তায়ালা তোমাদের ওপর থেকে (নানা ধরনের বোঝা) লঘু করে (তোমাদের জীবনকে সহজ করে) দিতে চান, (কেননা) মানুষকে (আসলেই) দুর্বল করে পয়দা করা হয়েছে।', 'Yureedu Allahu an yukhaffifa AAankum wakhuliqa alinsanu daAAeefan', 1, NOW(), NOW()),
(4, 29, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, তোমরা একে অপরের ধন-সম্পত্তি অন্যায়ভাবে গ্রাস করো না, (হ্যাঁ,) ব্যবসা-বাণিজ্য যা করবে তা তোমাদের পারস্পরিক সম্মতির ভিত্তিতেই করবে এবং কখনো (স্বার্থের কারণে) নিজেদের হত্যা করো না, অবশ্যই আল্লাহ তায়ালা তোমাদের প্রতি মেহেরবান।', 'Ya ayyuha allatheena amanoo la takuloo amwalakum baynakum bialbatili illa an takoona tijaratan AAan taradin minkum wala taqtuloo anfusakum inna Allaha kana bikum raheeman', 1, NOW(), NOW()),
(4, 30, 'وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'যে কেউই বাড়াবাড়ি ও যুলুম করতে গিয়ে এই (নর হত্যার) কাজটি করবে, অচিরেই আমি তাকে আগুনে পুড়িয়ে দিবো, (আর) আল্লাহর পক্ষে এটা একেবারেই সহজ।', 'Waman yafAAal thalika AAudwanan wathulman fasawfa nusleehi naran wakana thalika AAala Allahi yaseeran', 1, NOW(), NOW()),
(4, 31, 'إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا', 'যদি তোমরা সে সমস্ত বড়ো বড়ো গুনাহ থেকে বেঁচে থাকো, যা থেকে তোমাদের নিষেধ করা হয়েছে, তাহলে তোমাদের (ছোটোখাটো) গুনাহ আমি (এমনিই) তোমাদের (হিসাব) থেকে মুছে দিবো এবং আমি অত্যন্ত সম্মানজনক স্থানে তোমাদের প্রবেশ করাবো।', 'In tajtaniboo kabaira ma tunhawna AAanhu nukaffir AAankum sayyiatikum wanudkhilkum mudkhalan kareeman', 1, NOW(), NOW()),
(4, 32, 'وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا', 'আল্লাহ তায়ালা তোমাদের একজনের ওপর আরেকজনকে যা (কিছু বেশী) দান করেছেন, তোমরা (তার) লোভ করো না, যা কিছু পুরুষরা উপার্জন করলো তা তাদেরই অংশ; আবার নারীরা যা কিছু অর্জন করলো তাও তাদেরই অংশ; তোমরা আল্লাহ তায়ালার কাছ থেকে তাঁর অনুগ্রহ প্রার্থনা করো; অবশ্যই আল্লাহ তায়ালা প্রতিটি বিষয় সম্পর্কে সম্যক ওয়াকেফহাল রয়েছেন।', 'Wala tatamannaw ma faddala Allahu bihi baAAdakum AAala baAAdin lilrrijali naseebun mimma iktasaboo walilnnisai naseebun mimma iktasabna waisaloo Allaha min fadlihi inna Allaha kana bikulli shayin AAaleeman', 1, NOW(), NOW()),
(4, 33, 'وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا', 'পিতামাতা ও আত্মীয়-স্বজনের রেখে যাওয়া সম্পত্তিতে আমি সবার জন্যেই অভিভাবক বানিয়ে রেখেছি; যাদের সাথে তোমাদের কোনো চুক্তি কিংবা অংগীকার রয়েছে তাদের অংশ আদায় করে দেবে, আল্লাহ তায়ালা অবশ্যই প্রতিটি বিষয়ের ওপর সাক্ষী।', 'Walikullin jaAAalna mawaliya mimma taraka alwalidani waalaqraboona waallatheena AAaqadat aymanukum faatoohum naseebahum inna Allaha kana AAala kulli shayin shaheedan', 1, NOW(), NOW()),
(4, 34, 'ٱلرِّجَالُ قَوَّـٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّـٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا', 'পুরুষরা হচ্ছে নারীদের (কাজকর্মের) ওপর প্রহরী, যেহেতু আল্লাহ তায়ালা এদের একজনকে আরেকজনের ওপর (কিছু বিশেষ) মর্যাদা প্রদান করেছেন, কেননা (প্রধানত) তারাই (দাম্পত্য জীবনের জন্যে) নিজেদের অর্থ সম্পদ ব্যয় করে; অতএব সতী-সাধ্বী নারীরা হবে (একান্ত) অনুগত, (পুরুষদের) অনুপস্থিতিতে তারা (স্বয়ং) আল্লাহর তত্ত্বাবধানে (থেকে) নিজেদের (ইযযত-আবরু ও অদেখা অন্য সব কিছুর) রক্ষণাবেক্ষণ করবে; আর যখন তোমরা কোনো নারীর অবাধ্যতার আশংকা করো, তখন তোমরা তাদের (ভালো কথার) উপদেশ দাও, (তা কার্যকর না হলে) তাদের সাথে একই বিছানায় থাকা ছেড়ে দাও, (তাতেও সংশোধন না হলে চূড়ান্ত ব্যবস্থা হিসেবে) তাদের (মৃদু) প্রহার করো, যদি তারা অনুগত হয়ে যায়, তাহলে তাদের (খামাখা কষ্ট দেয়ার) ওপর অজুহাত খুঁজে বেড়িয়ো না; অবশ্যই আল্লাহ তায়ালা সর্বশ্রেষ্ঠ, সবার চাইতে মহান!', 'Alrrijalu qawwamoona AAala alnnisai bima faddala Allahu baAAdahum AAala baAAdin wabima anfaqoo min amwalihim faalssalihatu qanitatun hafithatun lilghaybi bima hafitha Allahu waallatee takhafoona nushoozahunna faAAithoohunna waohjuroohunna fee almadajiAAi waidriboohunna fain ataAAnakum fala tabghoo AAalayhinna sabeelan inna Allaha kana AAaliyyan kabeeran', 1, NOW(), NOW()),
(4, 35, 'وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا', 'আর যদি তাদের (স্বামী-স্ত্রী এ) দুজনের মাঝে বিচ্ছেদের আশংকা দেখা দেয়, তাহলে তার পরিবারের পক্ষ থেকে একজন এবং তার (স্ত্রীর) পরিবারের পক্ষ থেকে একজন সালিস নিযুক্ত করো, এরা উভয়ে যদি নিষ্পত্তি চায়, তাহলে আল্লাহ তায়ালা তাদের (মীমাংসায় পৌঁছার) তাওফীক দেবেন, নিশ্চয়ই আল্লাহ তায়ালা সম্যক জ্ঞানী, সর্ববিষয়ে ওয়াকেফহাল।', 'Wain khiftum shiqaqa baynihima faibAAathoo hakaman min ahlihi wahakaman min ahliha in yureeda islahan yuwaffiqi Allahu baynahuma inna Allaha kana AAaleeman khabeeran', 1, NOW(), NOW()),
(4, 36, '۞وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا', 'তোমরা এক আল্লাহ তায়ালার এবাদাত করো, কোনো কিছুকেই তাঁর সাথে অংশীদার বানিয়ো না এবং পিতামাতার সাথে ভালো ব্যবহার করো, যারা (তোমাদের) ঘনিষ্ঠ আত্মীয়, এতীম, মেসকীন, আত্মীয় প্রতিবেশী, কাছের প্রতিবেশী, পাশের লোক, পথচারী ও তোমার অধিকারভুক্ত (দাস দাসী, তাদের সাথেও ভালো ব্যবহার করো), অবশ্যই আল্লাহ তায়ালা এমন মানুষকে কখনো পছন্দ করেন না, যে অহংকারী ও দাম্ভিক,', 'WaoAAbudoo Allaha wala tushrikoo bihi shayan wabialwalidayni ihsanan wabithee alqurba waalyatama waalmasakeeni waaljari thee alqurba waaljari aljunubi waalssahibi bialjanbi waibni alssabeeli wama malakat aymanukum inna Allaha la yuhibbu man kana mukhtalan fakhooran', 1, NOW(), NOW()),
(4, 37, 'ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', '(আল্লাহ তায়ালা তাদেরও ভালোবাসেন না) যারা নিজেরা (যেমন) কার্পণ্য করে, (তেমনি) অন্যদেরও কার্পণ্য করার আদেশ করে, (তাছাড়া) আল্লাহ তায়ালা তাদের যা কিছু (ধন-সম্পদের) অনুগ্রহ দান করেছেন তারা তা লুকিয়ে রাখে; আমি কাফেরদের জন্যে এক লাঞ্ছনাদায়ক শাস্তির ব্যবস্থা করে রেখেছি।', 'Allatheena yabkhaloona wayamuroona alnnasa bialbukhli wayaktumoona ma atahumu Allahu min fadlihi waaAAtadna lilkafireena AAathaban muheenan', 1, NOW(), NOW()),
(4, 38, 'وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا', '(আল্লাহ তায়ালা তাদেরও পছন্দ করেন না) যারা লোক দেখানোর উদ্দেশে নিজেদের ধন-সম্পদ ব্যয় করে, তারা আল্লাহ তায়ালা এবং শেষ বিচারের দিনকেও বিশ্বাস করে না; (আর) শয়তান যদি কোনো ব্যক্তির সাথী হয় তাহলে (বুঝতে হবে) সে বড়োই খারাপ সাথী (পেলো)!', 'Waallatheena yunfiqoona amwalahum riaa alnnasi wala yuminoona biAllahi wala bialyawmi alakhiri waman yakuni alshshaytanu lahu qareenan fasaa qareenan', 1, NOW(), NOW()),
(4, 39, 'وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا', 'কি (দুর্যোগ) তাদের ওপর দিয়ে বয়ে যেতো যদি তারা (শয়তানকে সাথী বানানোর বদলে) আল্লাহ তায়ালা ও পরকাল দিবসের ওপর ঈমান আনতো, আল্লাহ তায়ালা তাদের যা কিছু দান করেছেন তা থেকে তারা খরচ করতো; আল্লাহ তায়ালা অবশ্যই তাদের সম্পর্কে জানেন।', 'Wamatha AAalayhim law amanoo biAllahi waalyawmi alakhiri waanfaqoo mimma razaqahumu Allahu wakana Allahu bihim AAaleeman', 1, NOW(), NOW()),
(4, 40, 'إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا', 'আল্লাহ তায়ালা কারো ওপর এক বিন্দু পরিমাণও যুলুম করেন না, (বরং তিনি এতো দয়ালু যে,) নেকীর কাজ যদি একটি হয় তবে তিনি তার পরিমাণ দ্বিগুণ করে দেন এবং (এর সাথে) তিনি নিজ থেকেও বড়ো পুরস্কার দান করেন।', 'Inna Allaha la yathlimu mithqala tharratin wain taku hasanatan yudaAAifha wayuti min ladunhu ajran AAatheeman', 1, NOW(), NOW()),
(4, 41, 'فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدٗا', 'সেদিন (তার অবস্থাটা) কেমন হবে যখন আমি প্রত্যেক উম্মতের (কাজের) সাক্ষী (হিসেবে তাদের নবীকে) এনে হাযির করবো, (হে মোহাম্মদ,) এদের সবার কাছে সাক্ষী হিসেবে আমি (সেদিন) তোমাকে নিয়ে আসবো।', 'Fakayfa itha jina min kulli ommatin bishaheedin wajina bika AAala haolai shaheedan', 1, NOW(), NOW()),
(4, 42, 'يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا', 'যারা কুফরী করেছে এবং রাসূলের বিরুদ্ধাচরণ করেছে, তারা সেদিন কামনা করবে, ভূমি (যদি ধ্বসে যেতো এবং) মাটি যদি তাদের ওপর এসে সব সমান হয়ে যেতো! (সেদিন) মানুষ কোনো কথাই আল্লাহ তায়ালার কাছ থেকে গোপন করতে পারবে না।', 'Yawmaithin yawaddu allatheena kafaroo waAAasawoo alrrasoola law tusawwa bihimu alardu wala yaktumoona Allaha hadeethan', 1, NOW(), NOW()),
(4, 43, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', 'হে ঈমানদাররা, তোমরা কখনো নেশাগ্রস্ত অবস্থায় নামাযের কাছে যেও না, যতোক্ষণ পর্যন্ত (তোমরা নিশ্চিত না হবে যে,) তোমরা যা কিছু বলছো তা তোমরা (ঠিক ঠিক) জানতে (ও বুঝতে পারছো, অপবিত্র অবস্থায়ও (নামাযের কাছে যেও) না, যতোক্ষণ না তোমরা গোসল সেরে নেবে, তবে সফরে থাকলে তা ভিন্ন কথা, যদি তোমরা অসুস্থ হয়ে পড়ো অথবা প্রবাসে থাকো, কিংবা তোমাদের কেউ যদি পায়খানা থেকে (বেরিয়ে আসো অথবা তোমরা যদি (দৈহিক মিলনের সাথে) নারী স্পর্শ করো (তাহলে পানি দিয়ে নিজেদের পরিষ্কার করে নেবে), তবে যদি পানি না পাও, তাহলে পবিত্র মাটি দিয়ে তায়াম্মুম করে নেবে, (তার পদ্ধতি হচ্ছে, তা দিয়ে) তোমাদের মুখমন্ডল ও তোমাদের হাত মাসেহ করে নেবে, অবশ্যই আল্লাহ তায়ালা গুনাহ মার্জনাকারী, পরম ক্ষমাশীল।', 'Ya ayyuha allatheena amanoo la taqraboo alssalata waantum sukara hatta taAAlamoo ma taqooloona wala junuban illa AAabiree sabeelin hatta taghtasiloo wain kuntum marda aw AAala safarin aw jaa ahadun minkum mina alghaiti aw lamastumu alnnisaa falam tajidoo maan fatayammamoo saAAeedan tayyiban faimsahoo biwujoohikum waaydeekum inna Allaha kana AAafuwwan ghafooran', 1, NOW(), NOW()),
(4, 44, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ', '(হে নবী,) তুমি কি তাদের (অবস্থা) দেখোনি, যাদের (আসমানী) গ্রন্থের (সামান্য) একটা অংশই দেয়া হয়েছিলো, (কিন্তু) তারা গোমরাহীর পথই কিনে নিচ্ছে, তারা চায় তোমরা যেন পথভ্রষ্ট হয়ে যাও।', 'Alam tara ila allatheena ootoo naseeban mina alkitabi yashtaroona alddalalata wayureedoona an tadilloo alssabeela', 1, NOW(), NOW()),
(4, 45, 'وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا', 'তোমাদের দুশমনদের আল্লাহ তায়ালা ভালো করেই জানেন; অভিভাবক হিসেবে আল্লাহ তায়ালা যথেষ্ট, সাহায্যকারী হিসেবেও আল্লাহ তায়ালাই যথেষ্ট।', 'WaAllahu aAAlamu biaAAdaikum wakafa biAllahi waliyyan wakafa biAllahi naseeran', 1, NOW(), NOW()),
(4, 46, 'مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا', 'ইহুদী জাতির মধ্যে কিছু লোক এমন আছে যারা (রাসূলের) কথাগুলোকে মূল জায়গা থেকে সরিয়ে (বিকৃত করে) দেয়। তারা বলে, আমরা শুনলাম এবং (সাথে সাথে) অমান্যও করলাম, (আবার বলে) আমাদের কথা শুনুন, (আসলে) দ্বীনের মাঝে অপবাদ দানের উদ্দেশ্যে নিজেদের জিহ্বাকে কুঞ্চিত করে এরা বলে (হে নবী), আপনি শুনুন, (সাথে সাথেই বলে), আপনার শ্রবণশক্তি রহিত হয়ে যাক । তারা যদি বলতো (হে নবী), আমরা শুনলাম এবং মেনে নিলাম । আপনি আমাদের কথা শুনুন, আমাদের প্রতি লক্ষ্য করুন, তাহলে এ বিষয়টা তাদের জন্যে খুবই ভালো হতো, তাই হতো (বরং) তাদের জন্যে সংগত, কিন্তু সত্য অস্বীকার করার কারণে তাদের ওপর আল্লাহ তায়ালা অভিশাপ দিয়েছেন, অতঃপর (তাদের) সামান্য কিছু লোকই মাত্র ঈমান এনে থাকে।', 'Mina allatheena hadoo yuharrifoona alkalima AAan mawadiAAihi wayaqooloona samiAAna waAAasayna waismaAA ghayra musmaAAin waraAAina layyan bialsinatihim wataAAnan fee alddeeni walaw annahum qaloo samiAAna waataAAna waismaAA waonthurna lakana khayran lahum waaqwama walakin laAAanahumu Allahu bikufrihim fala yuminoona illa qaleelan', 1, NOW(), NOW()),
(4, 47, 'يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا', 'হে মানুষেরা, যাদের কিতাব দেয়া হয়েছে, তোমরা সেই গ্রন্থের ওপর ঈমান আনো, যা আমি (মোহাম্মদের ওপর) নাযিল করেছি, (এ কিতাব) তোমাদের কাছে মজুদ (পূর্ববর্তী) কিতাবের সত্যতা স্বীকার করে, (ঈমান আনো) সে সময় আসার আগে, যখন আমি (পাপিষ্ঠদের) চেহারাসমূহ বিকৃত করে তা উল্টো দিকে ঘুরিয়ে দিবো, অথবা (ইহুদীদের পবিত্র দিন) শনিবারের অবমাননাকারীদের প্রতি আমি যেভাবে অভিশাপ নাযিল করেছি (তেমনি কোনো বিপর্যয় আসার আগেই তোমরা ঈমান আনো), আর আল্লাহ তায়ালার হুকুম, সে তো অবধারিত!', 'Ya ayyuha allatheena ootoo alkitaba aminoo bima nazzalna musaddiqan lima maAAakum min qabli an natmisa wujoohan fanaruddaha AAala adbariha aw nalAAanahum kama laAAanna ashaba alssabti wakana amru Allahi mafAAoolan', 1, NOW(), NOW()),
(4, 48, 'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا', 'নিসন্দেহে আল্লাহ তায়ালা কখনো (সে গুনাহ মাফ করবেন না (যেখানে) তাঁর সাথে কাউকে শরীক করা হয়, এ ছাড়া অন্য সব গুনাহ তিনি যাকে ইচ্ছা ক্ষমা করে দেন, যে ব্যক্তি আল্লাহর সাথে শেরেক করলো সে সত্যিই (আল্লাহর ওপর) মিথ্যা আরোপ করলো যা বড়ো ধরনের একটি গুনাহ।', 'Inna Allaha la yaghfiru an yushraka bihi wayaghfiru ma doona thalika liman yashao waman yushrik biAllahi faqadi iftara ithman AAatheeman', 1, NOW(), NOW()),
(4, 49, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا', '(হে নবী,) তুমি কি তাদের অবস্থা দেখোনি যারা নিজেদের খুব পবিত্র মনে করে, অথচ একমাত্র আল্লাহ তায়ালাই যাকে ইচ্ছা তাকে পবিত্র করেন। (যারা অহংকারী) তাদের ওপর বিন্দু পরিমাণও যুলুম করা হবে না।', 'Alam tara ila allatheena yuzakkoona anfusahum bali Allahu yuzakkee man yashao wala yuthlamoona fateelan', 1, NOW(), NOW()),
(4, 50, 'ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا', 'তাকিয়ে দেখো (এদের দিকে), কিভাবে এরা আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করছে, প্রকাশ্য গুনাহ হিসেবে এটাই তো তার জন্যে যথেষ্ট!', 'Onthur kayfa yaftaroona AAala Allahi alkathiba wakafa bihi ithman mubeenan', 1, NOW(), NOW()),
(4, 51, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَـٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا', 'তুমি কি তাদের (অবস্থা) দেখোনি, যাদের (আল্লাহ তায়ালার) কিতাবের কিছু অংশ দান করা হয়েছিলো, (তারা আস্তে আস্তে) নানা ধরনের ভিত্তিহীন অমূলক যাদুমন্ত্ৰ জাতীয় জিনিস ও (বহুতরো) মিথ্যা মাবুদের ওপর ঈমান আনতে শুরু করলো এবং এ কাফেরদের সম্পর্কে তারা বলতে লাগলো, ঈমানদারদের তুলনায় এরাই তো বেশী সঠিক পথের ওপর রয়েছে!', 'Alam tara ila allatheena ootoo naseeban mina alkitabi yuminoona bialjibti waalttaghooti wayaqooloona lillatheena kafaroo haolai ahda mina allatheena amanoo sabeelan', 1, NOW(), NOW()),
(4, 52, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', 'এরাই হচ্ছে সেই (হতভাগ্য) মানুষগুলো, যাদের ওপর আল্লাহ তায়ালা অভিসম্পাত করেছেন, আর আল্লাহ তায়ালা যার ওপর অভিশাপ পাঠান তার জন্যে তুমি কখনো কোনো সাহায্যকারী পাবে না।', 'Olaika allatheena laAAanahumu Allahu waman yalAAani Allahu falan tajida lahu naseeran', 1, NOW(), NOW()),
(4, 53, 'أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا', 'অথবা (এরা কি মনে করে), তাদের ভাগে রাজত্ব (বরাদ্দ করা) আছে? তেমন কিছু হলে এরা খেজুর পাতার একটি ঝিল্লিও কাউকে দিতো না।', 'Am lahum naseebun mina almulki faithan la yutoona alnnasa naqeeran', 1, NOW(), NOW()),
(4, 54, 'أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا', 'অথবা এরা কি অন্যান্য মানুষদের তার ওপর হিংসা করে, যাদের আল্লাহ তায়ালা নিজস্ব ভান্ডার থেকে (নানা কিছু) দান করেছেন, আমি তো (ইতিপূর্বে) ইবরাহীমের বংশধরদেরও (আমার) গ্রন্থ (ও সেই গ্রন্থলব্ধ) জ্ঞান-বিজ্ঞান দান করেছিলাম, আমি তাদের বিশাল রাজত্বও দান করেছিলাম।', 'Am yahsudoona alnnasa AAala ma atahumu Allahu min fadlihi faqad atayna ala ibraheema alkitaba waalhikmata waataynahum mulkan AAatheeman', 1, NOW(), NOW()),
(4, 55, 'فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', 'অতঃপর তাদের মধ্যে কিছু লোক ছিলো যারা তার ওপর ঈমান এনেছে, আবার কেউ ছিলো যারা তার থেকে মুখ ফিরিয়ে নিয়েছে; এদের জন্যে জাহান্নামের জলন্ত আগুনই যথেষ্ট!', 'Faminhum man amana bihi waminhum man sadda AAanhu wakafa bijahannama saAAeeran', 1, NOW(), NOW()),
(4, 56, 'إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا', 'যারা আমার আয়াতসমূহ অস্বীকার করেছে আমি অচিরেই তাদের জাহান্নামের আগুনে পুড়িয়ে দিবো, অতঃপর যখনি তাদের দেহের চামড়া গলে যাবে তখনি আমি তাদের নতুন চামড়া বদলে দিবো, যাতে করে তারা আযাব ভোগ করতে পারে, অবশ্যই আল্লাহ তায়ালা মহাপরাক্রমশালী, বিজ্ঞ কুশলী।', 'Inna allatheena kafaroo biayatina sawfa nusleehim naran kullama nadijat julooduhum baddalnahum juloodan ghayraha liyathooqoo alAAathaba inna Allaha kana AAazeezan hakeeman', 1, NOW(), NOW()),
(4, 57, 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا', 'অপরদিকে যারা ঈমান এনেছে এবং ভালো কাজ করেছে, তাদের অচিরেই আমি এমন এক জান্নাতে প্রবেশ করাবো, যার তলদেশ দিয়ে ঝর্ণাধারা প্রবাহিত হবে, সেখানে তারা থাকবে চিরকাল, তাদের জন্যে থাকবে পূতপবিত্র (সংগী ও) সংগিনীরা, (সর্বোপরি) আমি তাদের এক চির স্নিগ্ধ ছায়ায় প্রবেশ করিয়ে দিবো।', 'Waallatheena amanoo waAAamiloo alssalihati sanudkhiluhum jannatin tajree min tahtiha alanharu khalideena feeha abadan lahum feeha azwajun mutahharatun wanudkhiluhum thillan thaleelan', 1, NOW(), NOW()),
(4, 58, '۞إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا', 'অবশ্যই আল্লাহ তায়ালা তোমাদের নির্দেশ দিচ্ছেন, তোমরা আমানতসমূহ তাদের (যথার্থ) মালিকের কাছে সোপর্দ করে দেবে, আর যখন মানুষের মাঝে (কোনো কিছুর) ব্যাপারে তোমরা বিচার ফয়সালা করো তখন তা ন্যায় ও ইনসাফের ভিত্তিতে করবে; আল্লাহ তায়ালা তার মাধ্যমে তোমাদের যা কিছু উপদেশ দেন তা সত্যিই সুন্দর! অবশ্যই আল্লাহ তায়ালা সবকিছু দেখেন এবং শোনেন।', 'Inna Allaha yamurukum an tuaddoo alamanati ila ahliha waitha hakamtum bayna alnnasi an tahkumoo bialAAadli inna Allaha niAAimma yaAAithukum bihi inna Allaha kana sameeAAan baseeran', 1, NOW(), NOW()),
(4, 59, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا', 'হে ঈমানদার মানুষেরা, তোমরা আল্লাহর আনুগত্য করো, আনুগত্য করো (তাঁর) রাসূলের এবং সেসব লোকদের, যারা তোমাদের মাঝে দায়িত্বপ্রাপ্ত, অতঃপর কোনো ব্যাপারে তোমরা যদি একে অপরের সাথে মতবিরোধ করো, তাহলে সে বিষয়টি (ফয়সালার জন্যে) আল্লাহ তায়ালা ও তাঁর রাসূলের দিকে ফিরিয়ে নিয়ে যাও, যদি তোমরা আল্লাহর ওপর এবং শেষ বিচার দিনের ওপর ঈমান এনে থাকো! (তাহলে) এ (পদ্ধতিই) হচ্ছে (বিরোধ মীমাংসার) সর্বোৎকৃষ্ট উপায় এবং পরিণামের দিক থেকেও (এটি) হচ্ছে উত্তম পন্থা।', 'Ya ayyuha allatheena amanoo ateeAAoo Allaha waateeAAoo alrrasoola waolee alamri minkum fain tanazaAAtum fee shayin faruddoohu ila Allahi waalrrasooli in kuntum tuminoona biAllahi waalyawmi alakhiri thalika khayrun waahsanu taweelan', 1, NOW(), NOW()),
(4, 60, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا', '(হে নবী,) তুমি কি তাদের (অবস্থা) দেখোনি যারা মনে করে, তারা সে বিষয়ের ওপর ঈমান এনেছে যা তোমার কাছে পাঠানো হয়েছে এবং তার ওপরও ঈমান এনেছে, যা তোমার আগে নাযিল করা হয়েছে, (কিন্তু বিচার ফয়সালার সময় আমার কিতাবের বদলে) এরা মিথ্যা মাবুদদের কাছ থেকেই ফয়সালা পেতে চায়, অথচ এদের নির্দেশ দেয়া হয়েছিলো তারা যেন এ (মিথ্যা মাবুদ)- দের অস্বীকার করে; (আসলেই) শয়তান এদের সত্য থেকে অনেক দূরে সরিয়ে নিতে চায়।', 'Alam tara ila allatheena yazAAumoona annahum amanoo bima onzila ilayka wama onzila min qablika yureedoona an yatahakamoo ila alttaghooti waqad omiroo an yakfuroo bihi wayureedu alshshaytanu an yudillahum dalalan baAAeedan', 1, NOW(), NOW()),
(4, 61, 'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا', 'এদের যখন বলা হয়, আল্লাহ তায়ালা তাঁর রাসূলের ওপর যা কিছু নাযিল করেছেন তোমরা তার দিকে (ফিরে) এসো, তখন তুমি মোনাফেকদের দেখবে, এরা তোমার কাছ থেকে মুখ ফিরিয়ে দূরে সরে যাচ্ছে।', 'Waitha qeela lahum taAAalaw ila ma anzala Allahu waila alrrasooli raayta almunafiqeena yasuddoona AAanka sudoodan', 1, NOW(), NOW()),
(4, 62, 'فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا', 'অতঃপর তাদের কৃতকর্মের কারণে যখন তাদের ওপর কোনো বিপদ-মসিবত এসে পড়ে, (তখন এদের অবস্থাটা) কি হয়? তারা তখন সবাই তোমার কাছে (ছুটে আসে এবং আল্লাহর নামের কসম করে আমরা তো কল্যাণ ও সম্প্রীতি ছাড়া আর কিছুই চাইনি।', 'Fakayfa itha asabathum museebatun bima qaddamat aydeehim thumma jaooka yahlifoona biAllahi in aradna illa ihsanan watawfeeqan', 1, NOW(), NOW()),
(4, 63, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا', 'এরা হচ্ছে সেসব লোক যাদের মনের ভেতরে কি (অভিসন্ধি) আছে তা আল্লাহ তায়ালা জানেন, তাই তুমি এদের এড়িয়ে চলো, তুমি এদের ভালো উপদেশ দাও এবং তাদের এমন সব কথা বলো, যা তাদের অন্তরে পৌঁছে যায়।', 'Olaika allatheena yaAAlamu Allahu ma fee quloobihim faaAArid AAanhum waAAithhum waqul lahum fee anfusihim qawlan baleeghan', 1, NOW(), NOW()),
(4, 64, 'وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا', 'আমি যখনই (জনপদে) কোনো রাসূল পাঠিয়েছি, তাকে এ জন্যেই পাঠিয়েছি যে, আল্লাহর নির্দেশ অনুযায়ী তাঁর আনুগত্য করা হবে; ভালো হতো এরা যখনি নিজে দের ওপর কোনো যুলুম করবে, তখনি তারা তোমার কাছে (ছুটে) আসবে এবং নিজেদের কৃতকর্মের জন্যে আল্লাহ তায়ালার কাছে ক্ষমা প্রার্থনা করবে এবং রাসূলও (তাদের জন্যে) ক্ষমা চাইবে, তাহলে তারা অবশ্যই আল্লাহকে পরম ক্ষমাশীল ও অতীব দয়ালু হিসেবে (দেখতে) পেতো!', 'Wama arsalna min rasoolin illa liyutaAAa biithni Allahi walaw annahum ith thalamoo anfusahum jaooka faistaghfaroo Allaha waistaghfara lahumu alrrasoolu lawajadoo Allaha tawwaban raheeman', 1, NOW(), NOW()),
(4, 65, 'فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا', '(হে নবী,) তোমার মালিকের শপথ, এরা কিছুতেই ঈমানদার হতে পারবে না, যতোক্ষণ না তারা তাদের যাবতীয় মতবিরোধের ফয়সালায় তোমাকে (শর্তহীন) বিচারক মেনে নেবে, অতঃপর তুমি যা ফয়সালা করবে সে ব্যাপারে তাদের মনে কোনো দ্বিধাদ্বন্দ্ব থাকবে না এবং তোমার সিদ্ধান্ত তারা সর্বান্তকরণে মেনে নেবে।', 'Fala warabbika la yuminoona hatta yuhakkimooka feema shajara baynahum thumma la yajidoo fee anfusihim harajan mimma qadayta wayusallimoo tasleeman', 1, NOW(), NOW()),
(4, 66, 'وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا', 'আমি যদি তাদের ওপর এ আদেশ জারি করতাম যে, তোমরা নিজেদের জীবন বিসর্জন দাও অথবা তোমরা নিজে দের ভিটেমাটি ছেড়ে বের হয়ে যাও, (তাহলে) তাদের মধ্যে সামান্য সংখ্যক মানুষই তা করতো, যেসব উপদেশ তাদের দেয়া হয়েছে তা যদি তারা মেনে চলতো, তবে তা তাদের জন্যে অবশ্যই কল্যাণকর হতো এবং (তাদের) মানসিক স্থিরতাও (এতে করে) মযবুত হতো!', 'Walaw anna katabna AAalayhim ani oqtuloo anfusakum awi okhrujoo min diyarikum ma faAAaloohu illa qaleelun minhum walaw annahum faAAaloo ma yooAAathoona bihi lakana khayran lahum waashadda tathbeetan', 1, NOW(), NOW()),
(4, 67, 'وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا', 'এমতাবস্থায় আমিও আমার পক্ষ থেকে তাদের বড়ো ধরনের পুরস্কার দিতাম,', 'Waithan laataynahum min ladunna ajran AAatheeman', 1, NOW(), NOW()),
(4, 68, 'وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا', '(উপরন্তু) আমি তাদের সরল পথও দেখিয়ে দিতাম!', 'Walahadaynahum siratan mustaqeeman', 1, NOW(), NOW()),
(4, 69, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَۚ وَحَسُنَ أُوْلَـٰٓئِكَ رَفِيقٗا', 'যারা আল্লাহ তায়ালা ও (তাঁর) রাসূলের আনুগত্য করে, তারা (শেষ বিচারের দিন সেসব) পুণ্যবান মানুষদের সাথে থাকবে, যাদের ওপর আল্লাহ তায়ালা নেয়ামত বর্ষণ করেছেন, এরা (হচ্ছে) সকল নবী, (আরো) যারা (নবুয়তের) সত্যতা স্বীকার করেছে, (আল্লাহর পথে জীবন উৎসর্গকারী) শহীদ ও অন্যান্য নেককার মানুষ, সাথী হিসেবে এরা সত্যিই উত্তম!', 'Waman yutiAAi Allaha waalrrasoola faolaika maAAa allatheena anAAama Allahu AAalayhim mina alnnabiyyeena waalssiddeeqeena waalshshuhadai waalssaliheena wahasuna olaika rafeeqan', 1, NOW(), NOW()),
(4, 70, 'ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا', 'এটা (মানুষদের প্রতি) আল্লাহ তায়ালার (বিরাট) অনুগ্রহ, (কোনো কিছু) জানার জন্যে আল্লাহ তায়ালাই যথেষ্ট!', 'Thalika alfadlu mina Allahi wakafa biAllahi AAaleeman', 1, NOW(), NOW()),
(4, 71, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا', 'হে ঈমানদাররা, (শত্রুর মোকাবেলায়) তোমরা তোমাদের প্রতিরক্ষা (ও প্রস্তুতি) অব্যাহত রাখো। দলে দলে বিভক্ত হয়ে, কিংবা সবাই একসংগে (শত্রুর মোকাবেলা) করো।', 'Ya ayyuha allatheena amanoo khuthoo hithrakum fainfiroo thubatin awi infiroo jameeAAan', 1, NOW(), NOW()),
(4, 72, 'وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا', 'অবশ্যই তোমাদের মধ্যে এমন (মোনাফেক) লোক থাকবে, যে (যুদ্ধের ব্যাপারে) গড়িমসি করবে, তোমাদের ওপর কোনো বিপদ-মসিবত এলে সে বলবে, আল্লাহ তায়ালা আমার ওপর বড়ো অনুগ্রহ করেছেন, (কেননা) আমি সে সময় তাদের সাথে ছিলাম না।', 'Wainna minkum laman layubattianna fain asabatkum museebatun qala qad anAAama Allahu AAalayya ith lam akun maAAahum shaheedan', 1, NOW(), NOW()),
(4, 73, 'وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا', 'আর যদি তোমাদের ওপর আল্লাহ তায়ালার পক্ষ থেকে (বিজয়ের) অনুগ্রহ আসে, তখন সে (এমন সম্পর্কবিহীনভাবে কথা) বলে, যেন তার সাথে তোমাদের কোনো রকম বন্ধুত্বই ছিলো না, সে (তখন) বলে, কতোই না ভালো হতো যদি আমি তাদের সাথে থাকতাম, তাহলে (আজ) আমিও অনেক বড়ো সফলতা অর্জন করতে পারতাম!', 'Walain asabakum fadlun mina Allahi layaqoolanna kaan lam takun baynakum wabaynahu mawaddatun ya laytanee kuntu maAAahum faafooza fawzan AAatheeman', 1, NOW(), NOW()),
(4, 74, '۞فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا', 'যেসব মানুষ পরকালের বিনিময়ে এ পার্থিব জীবনকে বিক্রি করে দিয়েছে, মানুষের উচিত আল্লাহ তায়ালার পথে (তাদের বিরুদ্ধে) লড়াই করা, যে আল্লাহর পথে লড়াই করবে সে (এ পথে) নিহত হবে কিংবা সে বিজয় লাভ করবে, (উভয় অবস্থায়ই) আমি তাকে বিরাট পুরস্কার দিবো৷', 'Falyuqatil fee sabeeli Allahi allatheena yashroona alhayata alddunya bialakhirati waman yuqatil fee sabeeli Allahi fayuqtal aw yaghlib fasawfa nuteehi ajran AAatheeman', 1, NOW(), NOW()),
(4, 75, 'وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', 'তোমাদের এ কি হয়েছে, তোমরা আল্লাহর পথে সেসব অসহায় নর-নারী ও (দুস্থ) শিশু সন্তানদের (বাঁচাবার) জন্যে লড়াই করো না, যারা (এই বলে) ফরিয়াদ করছে, হে আমাদের রব, যালিমদের এই জনপদ থেকে তুমি আমাদের বের করে নাও, অতঃপর তুমি আমাদের জন্যে তোমার কাছ থেকে একজন অভিভাবক বানিয়ে দাও, তোমার কাছ থেকে আমাদের জন্যে একজন সাহায্যকারী বানিয়ে দাও!', 'Wama lakum la tuqatiloona fee sabeeli Allahi waalmustadAAafeena mina alrrijali waalnnisai waalwildani allatheena yaqooloona rabbana akhrijna min hathihi alqaryati alththalimi ahluha waijAAal lana min ladunka waliyyan waijAAal lana min ladunka naseeran', 1, NOW(), NOW()),
(4, 76, 'ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّـٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا', 'যারা ঈমান এনেছে, তারা (সর্বদা) আল্লাহর পথে যুদ্ধ করে, আর যারা (আল্লাহ তায়ালাকে) অস্বীকার করেছে তারা লড়াই করে মিথ্যা মাবুদদের পথে, অতএব তোমরা যুদ্ধ করো শয়তান ও তার চেলা-চামুন্ডাদের বিরুদ্ধে, অবশ্যই শয়তানের ষড়যন্ত্র একান্ত দুর্বল।', 'Allatheena amanoo yuqatiloona fee sabeeli Allahi waallatheena kafaroo yuqatiloona fee sabeeli alttaghooti faqatiloo awliyaa alshshaytani inna kayda alshshaytani kana daAAeefan', 1, NOW(), NOW()),
(4, 77, 'أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا', '(হে নবী,) তুমি কি তাদের দিকে তাকিয়ে দেখোনি, যাদের (প্রথম দিকে) যখন বলা হয়েছিলো, তোমরা (আপাতত লড়াই থেকে) নিজেদের হাত গুটিয়ে রাখো, (এখন শুধু) নামায প্রতিষ্ঠা করো এবং যাকাত প্রদান করো (তখন তারা লড়াই করার জন্যে অস্থির হয়ে পড়েছিলো, অথচ) যখন (সত্যি সত্যিই) তাদের ওপর লড়াইর হুকুম নাযিল করা হলো (তখন) এদের একদল লোক তো (প্রতিপক্ষের) মানুষদের এমনভাবে ভয় করতে শুরু করলো, যেমনি ভয় শুধু আল্লাহ তায়ালাকেই করা উচিত; কিংবা তার চাইতেও বেশী ভয়। তারা বললো, হে আমাদের রব, তুমি আমাদের ওপর যুদ্ধের হুকুম (এতো তাড়াতাড়ি) জারি করতে গেলে কেন? কতো ভালো হতো যদি তুমি আমাদের আরো কিছুটা অবকাশ দিতে? (হে নবী,) তুমি বলো, দুনিয়ার এ ভোগ সামগ্রী অত্যন্ত সামান্য; যে ব্যক্তি (আল্লাহ তায়ালাকে ভয় করে, তার জন্যে পরকাল অনেক উত্তম, আর (সেই পরকালে) তোমাদের ওপর কণামাত্রও যুলুম করা হবে না।', 'Alam tara ila allatheena qeela lahum kuffoo aydiyakum waaqeemoo alssalata waatoo alzzakata falamma kutiba AAalayhimu alqitalu itha fareequn minhum yakhshawna alnnasa kakhashyati Allahi aw ashadda khashyatan waqaloo rabbana lima katabta AAalayna alqitala lawla akhkhartana ila ajalin qareebin qul mataAAu alddunya qaleelun waalakhiratu khayrun limani ittaqa wala tuthlamoona fateelan', 1, NOW(), NOW()),
(4, 78, 'أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا', 'তোমরা যেখানেই থাকো– মৃত্যু তোমাদের নাগাল পাবেই, তোমরা যদি (কোনো) মযবুত দুর্গেও থাকো (সেখানেও মৃত্যু এসে হাযির হবে। এদের অবস্থা হচ্ছে), যখন কোনো কল্যাণ তাদের স্পর্শ করে তখন তারা বলে, (হ্যাঁ) এ তো আল্লাহর পক্ষ থেকেই এসেছে, অপরদিকে যখন কোনো ক্ষতি (ও অকল্যাণ) তাদের স্পর্শ করে তখন তারা বলে, এ (সব) তোমার কাছ থেকেই এসেছে, তুমি (তাদের) বলে দাও, (কল্যাণ-অকল্যাণ) সব কিছুই আল্লাহর পক্ষ থেকে আসে; এ জাতির হয়েছে কি, এরা মনে হয় কথাটি বুঝতেই চায় না।', 'Aynama takoonoo yudrikkumu almawtu walaw kuntum fee buroojin mushayyadatin wain tusibhum hasanatun yaqooloo hathihi min AAindi Allahi wain tusibhum sayyiatun yaqooloo hathihi min AAindika qul kullun min AAindi Allahi famali haolai alqawmi la yakadoona yafqahoona hadeethan', 1, NOW(), NOW()),
(4, 79, 'مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا', 'যে কল্যাণই তুমি লাভ করো (না কেন, মনে রেখো), তা আল্লাহর পক্ষ থেকেই আসে, আর যেটুকু অকল্যাণ তোমার ওপর আসে তা আসে তোমার নিজের কাছ থেকে; আমি তোমাকে মানুষদের জন্যে রাসূল বানিয়ে পাঠিয়েছি; আর সাক্ষী হিসেবে তো আল্লাহ তায়ালাই যথেষ্ট।', 'Ma asabaka min hasanatin famina Allahi wama asabaka min sayyiatin famin nafsika waarsalnaka lilnnasi rasoolan wakafa biAllahi shaheedan', 1, NOW(), NOW()),
(4, 80, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا', 'যে ব্যক্তি রাসূলের আনুগত্য করে সে (যেন) আল্লাহরই আনুগত্য করে, আর যে ব্যক্তি (এ আনুগত্য থেকে) মুখ ফিরিয়ে নেয়, (মনে রেখো) তাদের ওপর আমি তোমাকে প্রহরী বানিয়ে পাঠাইনি।', 'Man yutiAAi alrrasoola faqad ataAAa Allaha waman tawalla fama arsalnaka AAalayhim hafeethan', 1, NOW(), NOW()),
(4, 81, 'وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'তারা বলে, (আমরা তোমার) আনুগত্য (স্বীকার করি), কিন্তু তারা যখন তোমার কাছ থেকে দূরে সরে যায়, তখন তাদের একদল লোক রাতের বেলায় একত্রিত হয়ে ঠিক তুমি যা বলো তার বিরুদ্ধেই শলা পরামর্শ করে; তারা রাতের বেলায় যা শলা পরামর্শ করে আল্লাহ তায়ালা সেসব কর্মকান্ডগুলো লিখে রাখছেন, অতএব তুমি এদের এড়িয়ে চলো এবং শুধু আল্লাহ তায়ালার ওপরই ভরসা রাখো, অভিভাবক হিসেবে তো আল্লাহ তায়ালাই যথেষ্ট!', 'Wayaqooloona taAAatun faitha barazoo min AAindika bayyata taifatun minhum ghayra allathee taqoolu waAllahu yaktubu ma yubayyitoona faaAArid AAanhum watawakkal AAala Allahi wakafa biAllahi wakeelan', 1, NOW(), NOW()),
(4, 82, 'أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا', 'এরা কি কোরআন নিয়ে চিন্তা গবেষণা করে না? এ (গ্রন্থ)-টা যদি আল্লাহ তায়ালা ছাড়া অন্য কারো কাছ থেকে আসতো তাহলে তাতে অবশ্যই তারা অনেক গরমিল (দেখতে) পেতো।', 'Afala yatadabbaroona alqurana walaw kana min AAindi ghayri Allahi lawajadoo feehi ikhtilafan katheeran', 1, NOW(), NOW()),
(4, 83, 'وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا', 'এদের কাছে যখন নিরাপত্তা কিংবা ভয়জনিত কোনো খবর আসে, তখন (সত্য-মিথ্যা যাচাই না করেই) এরা তা প্রচার করে বেড়ায়; তারা যদি এ বিষয়টা (আল্লাহর) রাসূল এবং তাদের দায়িত্বপ্রাপ্ত ব্যক্তিকে জানিয়ে দিতো, তাহলে এমন সব লোকেরা তা জানতে পারতো, যারা তাদের মধ্যে থেকে সেই খবরের যথার্থতা যাচাই করতে পারতো; যদি তোমাদের ওপর আল্লাহর অনুগ্রহ না থাকতো, তাহলে (এ প্রচারণার ফলে) হাতেগোনা কিছু লোক ছাড়া তোমরা অধিকাংশই শয়তানের অনুগত্য করতে!', 'Waitha jaahum amrun mina alamni awi alkhawfi athaAAoo bihi walaw raddoohu ila alrrasooli waila olee alamri minhum laAAalimahu allatheena yastanbitoonahu minhum walawla fadlu Allahi AAalaykum warahmatuhu laittabaAAtumu alshshaytana illa qaleelan', 1, NOW(), NOW()),
(4, 84, 'فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا', 'অতঃপর (হে নবী), তুমি আল্লাহর পথে লড়াই করো, তোমাকে শুধু তোমার কাজকর্মের জন্যেই দায়ী করা হবে, তুমি মুমীনদের (আল্লাহ তায়ালার পথে লড়াই করতে) উদ্বুদ্ধ করতে থাকো, সম্ভবত আল্লাহ তায়ালা অচিরেই কাফেরদের শক্তি চূর্ণ-বিচূর্ণ করে দেবেন; আল্লাহ তায়ালা শক্তিতে প্রবল, শাস্তিদানে তিনি কঠোরতর।', 'Faqatil fee sabeeli Allahi la tukallafu illa nafsaka waharridi almumineena AAasa Allahu an yakuffa basa allatheena kafaroo waAllahu ashaddu basan waashaddu tankeelan', 1, NOW(), NOW()),
(4, 85, 'مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا', 'যদি কোনো ব্যক্তি কোনো ভালো কাজের সুপারিশ করে, তাহলে তাতে অবশ্যই তার অংশ থাকবে, আবার যে ব্যক্তি কোনো অন্যায় কাজের ব্যাপারে সুপারিশ করবে, (তার সৃষ্ট অকল্যাণেও) তার অংশ থাকবে, আল্লাহ তায়ালাই হচ্ছেন সকল কাজের একক নিয়ন্ত্রণকারী।', 'Man yashfaAA shafaAAatan hasanatan yakun lahu naseebun minha waman yashfaAA shafaAAatan sayyiatan yakun lahu kiflun minha wakana Allahu AAala kulli shayin muqeetan', 1, NOW(), NOW()),
(4, 86, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا', 'যখন তোমাদের (সালাম বা অন্য কিছু) দ্বারা অভিবাদন জানানো হয়, তখন তোমরা তার চাইতেও উত্তম পন্থায় তার জবাব দাও, কিংবা ততোটুকু ফেরত দাও, অবশ্যই আল্লাহ তায়ালা সব কিছুর হিসাব রাখেন।', 'Waitha huyyeetum bitahiyyatin fahayyoo biahsana minha aw ruddooha inna Allaha kana AAala kulli shayin haseeban', 1, NOW(), NOW()),
(4, 87, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا', 'আল্লাহ তায়ালা (মহান সত্তা)- তিনি ছাড়া (দ্বিতীয়) কোনো মাবুদ নেই; অবশ্যই তিনি কেয়ামতের দিন তোমাদের এক জায়গায় জড়ো করবেন, তাতে কোনো রকম সন্দেহ নেই; আর এমন কে আছে যে আল্লাহ তায়ালার চাইতে বেশী সত্য কথা বলতে পারে?', 'Allahu la ilaha illa huwa layajmaAAannakum ila yawmi alqiyamati la rayba feehi waman asdaqu mina Allahi hadeethan', 1, NOW(), NOW()),
(4, 88, '۞فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا', 'এ কি হলো তোমাদের! তোমরা মোনাফেকদের ব্যাপারে দু’দল হয়ে গেলে? (বিশেষ করে) যখন আল্লাহ তায়ালা তাদের কৃতকর্মের জন্যে তাদের ওপর অভিশাপ নাযিল করলেন; আল্লাহ তায়ালা যাদের পথভ্রষ্ট করে দিয়েছেন তোমরা কি তাদের সঠিক পথে আনতে চাও? (বস্তুত) আল্লাহ তায়ালা যাকে পথভ্রষ্ট করেন তুমি তার জন্যে কোনো পথই (খুঁজে) পাবে না।', 'Fama lakum fee almunafiqeena fiatayni waAllahu arkasahum bima kasaboo atureedoona an tahdoo man adalla Allahu waman yudlili Allahu falan tajida lahu sabeelan', 1, NOW(), NOW()),
(4, 89, 'وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا', 'তারা তো এটাই কামনা করে যে, তারা যেভাবে কুফরী করেছে তোমরাও তেমনি কুফরী করো, অতঃপর তোমরা উভয়ে একই রকম হয়ে যাবে, কাজেই তুমি তাদের মধ্য থেকে কাউকে নিজের বন্ধুরূপে গ্রহণ করো না, যতোক্ষণ না তারা আল্লাহ তায়ালার পথে নিজেদের ভিটেমাটি ত্যাগ না করবে, আর যদি তারা এ কাজ থেকে মুখ ফিরিয়ে নেয়, তাহলে তোমরা তাদের যেখানেই পাবে গ্রেফতার করবে এবং (শত্রুদের সহযোগিতা করার জন্যে) তাদের হত্যা করবে, তাদের মধ্য থেকে কাউকেই তোমরা বন্ধু ও সাহায্যকারী হিসেবে গ্রহণ করো না।', 'Waddoo law takfuroona kama kafaroo fatakoonoona sawaan fala tattakhithoo minhum awliyaa hatta yuhajiroo fee sabeeli Allahi fain tawallaw fakhuthoohum waoqtuloohum haythu wajadtumoohum wala tattakhithoo minhum waliyyan wala naseeran', 1, NOW(), NOW()),
(4, 90, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا', 'অবশ্য তাদের কথা আলাদা যারা তোমাদের সাথে চুক্তিবদ্ধ কোনো একটি সম্প্রদায়ের সাথে এসে মিলিত হবে, আবার (তাদের ব্যাপারও নয়-) যারা তোমাদের সামনে (দ্বিধাগ্রস্থ অন্তর নিয়ে) আসে, তাদের অন্তর তোমাদের সাথে (যেমনি) লড়াই করতে বাধা দেয়, (তেমনি) নিজেদের জাতির বিরুদ্ধেও তাদের লড়াই করতে বাধা দেয়; আল্লাহ তায়ালা যদি চাইতেন তিনি তোমাদের ওপর এদের ক্ষমতাবান করে দিতে পারতেন, তেমন অবস্থায় তারা অবশ্যই তোমাদের সাথে লড়াই করতো, অতএব এরা যদি তোমাদের কাছ থেকে আলাদা হয়ে যায়, লড়াই থেকে বিরত থাকে এবং তোমাদের কাছে (শান্তি ও) সন্ধির প্রস্তাব পাঠায়, তাহলে তাদের বিরুদ্ধে অভিযানের কোনো পন্থাই আল্লাহ তায়ালা তোমাদের জন্যে (উন্মুক্ত) রাখবেন না।', 'Illa allatheena yasiloona ila qawmin baynakum wabaynahum meethaqun aw jaookum hasirat sudooruhum an yuqatilookum aw yuqatiloo qawmahum walaw shaa Allahu lasallatahum AAalaykum falaqatalookum faini iAAtazalookum falam yuqatilookum waalqaw ilaykumu alssalama fama jaAAala Allahu lakum AAalayhim sabeelan', 1, NOW(), NOW()),
(4, 91, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَـٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا', 'অচিরেই তোমরা আরেকটি দল পাবে, যারা তোমাদের দিক থেকে (যেমন) শান্তি ও নিরাপত্তা পেতে চায়; (তেমনি) তারা তাদের নিজেদের জাতির কাছ থেকেও নিরাপত্তা পেতে চায়, কিন্তু এদের যখনি কোনো বিপর্যয়ের দিকে ডাক দেয়া হবে, তখন সাথে সাথেই তারা তার মধ্যে গিয়ে নিক্ষিপ্ত হবে, এরা যদি তোমাদের (সাথে যুদ্ধ করা) থেকে সরে না দাঁড়ায়, কোনো শান্তি ও সন্ধি প্রস্তাব তোমাদের কাছে পেশ না করে এবং নিজেদের অস্ত্র সংবরণ না করে, তাহলে তাদের তোমরা যেখানেই পাবে গ্রেফতার করবে এবং (বিদ্রোহের জন্যে) তাদের তোমরা হত্যা করবে; (মূলত) এরাই হচ্ছে সেসব লোক, যাদের ওপর আমি তোমাদের সুস্পষ্ট ক্ষমতা দান করেছি।', 'Satajidoona akhareena yureedoona an yamanookum wayamanoo qawmahum kulla ma ruddoo ila alfitnati orkisoo feeha fain lam yaAAtazilookum wayulqoo ilaykumu alssalama wayakuffoo aydiyahum fakhuthoohum waoqtuloohum haythu thaqiftumoohum waolaikum jaAAalna lakum AAalayhim sultanan mubeenan', 1, NOW(), NOW()),
(4, 92, 'وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', 'এটা কোনো ঈমানদার ব্যক্তির কাজ নয় যে, সে কোনো ঈমানদার ব্যক্তিকে হত্যা করবে, অবশ্য ভুলবশত করে ফেললে তা ভিন্ন কথা, যদি কোনো (ঈমানদার) ব্যক্তি আরেকজন ঈমানদার ব্যক্তিকে ভুল করে হত্যা করে, তাহলে (বিনিময় হিসেবে) সে একজন দাস মুক্ত করে দেবে এবং নিহত ব্যক্তির পরিবার-পরিজনকে (তার) রক্তের মূল্য পরিশোধ করে দেবে, তবে (নিহত ব্যক্তির) লোকেরা যদি (রক্তমূল্য) মাফ করে দেয় তবে তা আলাদা; এ (নিহত) ঈমানদার ব্যক্তি যদি এমন কোনো জাতির (বা গোত্রের) লোক হয় যারা তোমাদের শত্রু এবং সে (নিহত ব্যক্তি) মুমীন হয় তাহলে (তার বিনিময় হবে) একজন মুমীন দাসের মুক্তি; অপরদিকে সে (নিহত) ব্যক্তি যদি এমন এক সম্প্রদায়ের কেউ হয়ে থাকে, যাদের সাথে তোমাদের কোনো সন্ধি চুক্তি বলবত আছে, তবে তার রক্তের মূল্য আদায় করার (সাথে) একজন ঈমানদার দাসের মুক্তিও (অপরিহার্য), যে ব্যক্তি (মুক্ত করার জন্যে কোনো দাস) পাবে না, (তার বিধান হচ্ছে) ক্রমাগত দুই মাসের রোযা রাখা, (এটা হচ্ছে) আল্লাহ তায়ালার পক্ষ থেকে (এই গুনাহর) তাওবা, আল্লাহ তায়ালা সর্বজ্ঞ, কুশলী।', 'Wama kana limuminin an yaqtula muminan illa khataan waman qatala muminan khataan fatahreeru raqabatin muminatin wadiyatun musallamatun ila ahlihi illa an yassaddaqoo fain kana min qawmin AAaduwwin lakum wahuwa muminun fatahreeru raqabatin muminatin wain kana min qawmin baynakum wabaynahum meethaqun fadiyatun musallamatun ila ahlihi watahreeru raqabatin muminatin faman lam yajid fasiyamu shahrayni mutatabiAAayni tawbatan mina Allahi wakana Allahu AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 93, 'وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا', 'যে ব্যক্তি ইচ্ছাকৃতভাবে কোনো ঈমানদার ব্যক্তিকে হত্যা করবে, তার শাস্তি হচ্ছে জাহান্নাম, সেখানে সে অনন্তকাল থাকবে, আল্লাহ তায়ালা তার ওপর ভীষণ রুষ্ট হন, তাকে তিনি লানত দেন, তিনি তার জন্যে যন্ত্রণাদায়ক আযাব প্রস্তুত করে রেখেছেন।', 'Waman yaqtul muminan mutaAAammidan fajazaohu jahannamu khalidan feeha waghadiba Allahu AAalayhi walaAAanahu waaAAadda lahu AAathaban AAatheeman', 1, NOW(), NOW()),
(4, 94, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', 'হে ঈমানদার ব্যক্তিরা, তোমরা যখন আল্লাহ তায়ালার পথে (জেহাদের) রাস্তায় বের হবে, তখন (সবকিছু) যাচাই বাছাই করবে, কোনো ব্যক্তি যখন তোমাদের সামনে (শান্তি ও) সন্ধির প্রস্তাব পেশ করে, তখন তোমরা বলো না যে, তুমি ঈমানদার নও, তোমরা তো বৈষয়িক জীবনের (স্বার্থ) সন্ধান করো, আল্লাহ তায়ালার কাছে অনায়াসলভ্য সম্পদ প্রচুর রয়েছে । তোমরাও আগে এমনই ছিলে, অতঃপর আল্লাহ তায়ালা তোমাদের ওপর অনুগ্রহ করেছেন, কাজেই তোমরা (বিষয়টি) যাছাই বাছাই করে নিয়ো; তোমরা যা কিছুই করো আল্লাহ তায়ালা অবশ্যই সে ব্যাপারে সম্যক অবগত আছেন।', 'Ya ayyuha allatheena amanoo itha darabtum fee sabeeli Allahi fatabayyanoo wala taqooloo liman alqa ilaykumu alssalama lasta muminan tabtaghoona AAarada alhayati alddunya faAAinda Allahi maghanimu katheeratun kathalika kuntum min qablu famanna Allahu AAalaykum fatabayyanoo inna Allaha kana bima taAAmaloona khabeeran', 1, NOW(), NOW()),
(4, 95, 'لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا', 'মুমীনদের মাঝে যারা কোনো রকম (শারীরিক) অক্ষমতা না থাকা সত্ত্বেও (ঘরে) বসে থেকেছে, আর যারা নিজেদের জান ও মাল দিয়ে আল্লাহ তায়ালার পথে জেহাদে অবতীর্ণ হয়েছে– এরা উভয়ে কখনো সমান নয়; (ঘরে) বসে থাকা লোকদের তুলনায় (ময়দানের) মোজোহেদদের– যারা নিজেদের জান মাল দিয়ে (আল্লাহ তায়ালার পথে) জেহাদ করেছে– আল্লাহ তায়ালা তাদের উঁচু মর্যাদা দান করেছেন, (ময়দানের জেহাদ তখনো ফরয ঘোষিত না হওয়ায়) এদের সবার জন্যেই আল্লাহ তায়ালা উত্তম পুরস্কারের ওয়াদা করেছেন; (তবে) আল্লাহ তায়ালা (ঘরে) বসে থাকা লোকদের ওপর (সংগ্রামরত ময়দানের) মুজাহিদদের উৎকৃষ্ট বিনিময় দান করেছেন।', 'La yastawee alqaAAidoona mina almumineena ghayru olee alddarari waalmujahidoona fee sabeeli Allahi biamwalihim waanfusihim faddala Allahu almujahideena biamwalihim waanfusihim AAala alqaAAideena darajatan wakullan waAAada Allahu alhusna wafaddala Allahu almujahideena AAala alqaAAideena ajran AAatheeman', 1, NOW(), NOW()),
(4, 96, 'دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا', '(এই) মর্যাদাসমূহ স্বয়ং আল্লাহ তায়ালার পক্ষ থেকেই, এর সাথে রয়েছে তাঁর ক্ষমা ও দয়া, আল্লাহ তায়ালা বড়ো ক্ষমাশীল ও অতীব দয়ালু।', 'Darajatin minhu wamaghfiratan warahmatan wakana Allahu ghafooran raheeman', 1, NOW(), NOW()),
(4, 97, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا', 'যারা নিজেদের ওপর যুলুম করেছে ফেরেশতারা তাদের মওতের সময় যখন তাদের জিজ্ঞেস করবে, (বলো তো!) সেখানে তোমরা কিভাবে ছিলে? তারা বলবে, আমরা দুনিয়ায় দুর্বল (অক্ষম) ছিলাম; ফেরেশতারা বলবে, কেন, (তোমাদের জন্যে) আল্লাহর এ যমীন কি প্রশস্ত ছিলো না? তোমরা ইচ্ছা করলে হিজরত করে যেখানে চলে যেতে পারতে, (আসলে) এরা হচ্ছে সেসব লোক যাদের আবাসস্থল জাহান্নাম; আর তা খুবই নিকৃষ্ট আবাস!', 'Inna allatheena tawaffahumu almalaikatu thalimee anfusihim qaloo feema kuntum qaloo kunna mustadAAafeena fee alardi qaloo alam takun ardu Allahi wasiAAatan fatuhajiroo feeha faolaika mawahum jahannamu wasaat maseeran', 1, NOW(), NOW()),
(4, 98, 'إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا', 'তবে সেসব পুরুষ, নারী ও শিশু সন্তান, যাদের (হিজরত করার) শক্তি ছিলো না, কোথাও যাওয়ার কোনো উপকরণ ছিলো না– তাদের কথা আলাদা।', 'Illa almustadAAafeena mina alrrijali waalnnisai waalwildani la yastateeAAoona heelatan wala yahtadoona sabeelan', 1, NOW(), NOW()),
(4, 99, 'فَأُوْلَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا', 'এরা হচ্ছে সেসব লোক– আল্লাহ তায়ালা সম্ভবত যাদের (গোনাহসমূহ মাফ করে দেবেন, অবশ্যই আল্লাহ তায়ালা গুনাহ মোচনকারী ও পরম ক্ষমাশীল।', 'Faolaika AAasa Allahu an yaAAfuwa AAanhum wakana Allahu AAafuwwan ghafooran', 1, NOW(), NOW()),
(4, 100, '۞وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', 'আর যে কেউই আল্লাহ তায়ালার পথে হিজরত করবে সে আল্লাহ তায়ালার যমীনে প্রশস্ততা ও অগণিত ধন-সম্পদ পেয়ে যাবে; যখন কোনো ব্যক্তি আল্লাহ তায়ালা ও তাঁর রাসূলের উদ্দেশে হিজরত করার জন্যে নিজ বাড়ী থেকে বের হয় অতঃপর এমতাবস্থায় মৃত্যু এসে তাকে গ্রাস করে নেয়, তাহলে তার (অপূর্ণ হিজরতের) পুরস্কার দেয়ার দায়িত্ব আল্লাহ তায়ালার ওপর; আল্লাহ তায়ালা বড়ো ক্ষমাশীল ও পরম দয়ালু।', 'Waman yuhajir fee sabeeli Allahi yajid fee alardi muraghaman katheeran wasaAAatan waman yakhruj min baytihi muhajiran ila Allahi warasoolihi thumma yudrikhu almawtu faqad waqaAAa ajruhu AAala Allahi wakana Allahu ghafooran raheeman', 1, NOW(), NOW()),
(4, 101, 'وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا', 'তোমরা যখন সফরে বের হবে, তখন তোমরা যদি তোমাদের নামায কছর করে নাও তাতে তোমাদের ওপর কোনোই দোষ নেই; তোমাদের যদি এ আশংকা থাকে যে, কাফেররা (নামাযের সময় আক্রমণ করে) তোমাদের বিপদগ্রস্ত করে ফেলবে, তাহলে (তোমরা সতর্ক থেকো), নিসন্দেহে কাফেররা হচ্ছে তোমাদের প্রকাশ্যতম দুশমন।', 'Waitha darabtum fee alardi falaysa AAalaykum junahun an taqsuroo mina alssalati in khiftum an yaftinakumu allatheena kafaroo inna alkafireena kanoo lakum AAaduwwan mubeenan', 1, NOW(), NOW()),
(4, 102, 'وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', '(হে নবী,) তুমি যখন মুসলমানদের মাঝে অবস্থান করবে এবং (যুদ্ধাবস্থায়) যখন তুমি তাদের (ইমামতির) জন্যে (নামাযে) দাঁড়াবে, তখন যেন তাদের একদল লোক তোমার সাথে (নামাযে) দাঁড়ায় এবং তারা যেন তাদের অস্ত্র সাথে (নিয়ে সতর্ক) রাখে; অতঃপর তারা যখন (নামাযের) সাজদা সম্পন্ন করে নেবে তখন তারা তোমাদের পেছনে থাকবে, দ্বিতীয় দল– যারা (তখনো) নামায পড়েনি তারা তোমার সাথে এসে নামায আদায় করবে, (কিন্তু সর্বাবস্থায়ই) তারা যেন সতর্কতা অবলম্বন করে এবং সশস্ত্র (অবস্থায়) থাকে, (কারণ,) কাফেররা তো এ (সুযোগটুকুই) চায়, যদি তোমরা তোমাদের মালসামানা ও অস্ত্রশস্ত্র সম্পর্কে একটু অসাবধান হয়ে যাও, যাতে করে তারা তোমাদের ওপর (আকস্মিকভাবে) ঝাঁপিয়ে পড়তে পারে; অবশ্য (অতিরিক্ত) বৃষ্টি বাদলের জন্যে যদি তোমাদের কষ্ট হয় কিংবা শারীরিকভাবে তোমরা যদি অসুস্থ হও, তাহলে (কিছুক্ষণের জন্যে) তোমরা অস্ত্র রেখে দিতে পারো; (অস্ত্র রেখে দিলেও) তোমরা কিন্তু নিজেদের সাবধানতা বজায় রাখবে; অবশ্যই আল্লাহ তায়ালা কাফেরদের জন্যে এক অপমানকর আযাব নির্দিষ্ট করে রেখেছেন।', 'Waitha kunta feehim faaqamta lahumu alssalata faltaqum taifatun minhum maAAaka walyakhuthoo aslihatahum faitha sajadoo falyakoonoo min waraikum waltati taifatun okhra lam yusalloo falyusalloo maAAaka walyakhuthoo hithrahum waaslihatahum wadda allatheena kafaroo law taghfuloona AAan aslihatikum waamtiAAatikum fayameeloona AAalaykum maylatan wahidatan wala junaha AAalaykum in kana bikum athan min matarin aw kuntum marda an tadaAAoo aslihatakum wakhuthoo hithrakum inna Allaha aAAadda lilkafireena AAathaban muheenan', 1, NOW(), NOW()),
(4, 103, 'فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا', 'অতঃপর তোমরা যখন নামায শেষ করে নেবে, তখন দাঁড়িয়ে, বসে এবং তোমাদের শোয়া অবস্থায় আল্লাহ তায়ালাকে স্মরণ করতে থাকবে, এরপর যখন তোমরা পুরোপুরি স্বস্তি বোধ করবে তখন (যথারীতি) নামায আদায় করবে, অবশ্যই নামায ঈমানদরাদের ওপর সুনির্দিষ্ট সময়ের সাথেই ফরয করা হয়েছে।', 'Faitha qadaytumu alssalata faothkuroo Allaha qiyaman waquAAoodan waAAala junoobikum faitha itmanantum faaqeemoo alssalata inna alssalata kanat AAala almumineena kitaban mawqootan', 1, NOW(), NOW()),
(4, 104, 'وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'কোনো (শত্রু) দলের পেছনে ধাওয়া করার সময় তোমরা বিন্দুমাত্রও মনোবল হারিয়ো না; তোমরা যদি কষ্ট পেয়ে থাকো (তাহলে জেনে রেখো), তারাও তো তোমাদের মতো কষ্ট পাচ্ছে, ঠিক যেমনিভাবে তোমরা কষ্ট পাচ্ছো। (কিন্তু) তোমরা আল্লাহ তায়ালার কাছ থেকে যে (জান্নাত) আশা করো, তারা তো সেটা করে না; আল্লাহ তায়ালা সর্বজ্ঞ, কুশলী।', 'Wala tahinoo fee ibtighai alqawmi in takoonoo talamoona fainnahum yalamoona kama talamoona watarjoona mina Allahi ma la yarjoona wakana Allahu AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 105, 'إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا', 'অবশ্যই আমি সত্য (দ্বীনের) সাথে তোমার ওপর এ গ্রন্থ নাযিল করেছি, যাতে করে আল্লাহ তায়ালা তোমাকে (ওহী দ্বারা) যা দেখিয়েছেন তার আলোকে তুমি মানুষদের বিচার মীমাংসা করতে পারো; (মীমাংসার সময়) তুমি কখনো বিশ্বাসঘাতকদের পক্ষে তর্ক করো না।', 'Inna anzalna ilayka alkitaba bialhaqqi litahkuma bayna alnnasi bima araka Allahu wala takun lilkhaineena khaseeman', 1, NOW(), NOW()),
(4, 106, 'وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', 'তুমি আল্লাহ তায়ালার কাছে ক্ষমা প্রার্থনা করো; অবশ্যই আল্লাহ তায়ালা বড়ো ক্ষমাশীল ও পরম দয়ালু।', 'Waistaghfiri Allaha inna Allaha kana ghafooran raheeman', 1, NOW(), NOW()),
(4, 107, 'وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا', 'যারা নিজেদের সাথে বিশ্বাসঘাতকতা করে, তুমি কখনো এমন সব লোকের পক্ষ নিয়ে কোনো বিতর্ক করো না, অবশ্যই আল্লাহ তায়ালা তাকে কখনো পছন্দ করেন না যে পাপিষ্ঠ বিশ্বাসঘাতক।', 'Wala tujadil AAani allatheena yakhtanoona anfusahum inna Allaha la yuhibbu man kana khawwanan atheeman', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(4, 108, 'يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا', 'এরা মানুষদের কাছ থেকে নিজেদের (কর্ম) লুকিয়ে রাখতে চায়, যদিও আল্লাহ তায়ালার কাছ থেকে তারা কিছুই লুকাতে পারবে না; তারা যখন রাতের অন্ধকারে এমন সব বিষয়ে শলা পরামর্শ করে যেসব কথা (ও কাজ) আল্লাহ তায়ালা পছন্দ করেন না, তখনও তিনি তাদের সাথেই থাকেন; এরা যা কিছু করে তা আল্লাহ তায়ালা (পুরোপুরিই) পরিবেষ্টন করে আছেন।', 'Yastakhfoona mina alnnasi wala yastakhfoona mina Allahi wahuwa maAAahum ith yubayyitoona ma la yarda mina alqawli wakana Allahu bima yaAAmaloona muheetan', 1, NOW(), NOW()),
(4, 109, 'هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا', 'হ্যাঁ, এরাই হচ্ছে সেসব লোক, দুনিয়ার জীবনে (সঠিক জ্ঞানের অভাবে) তোমরা যাদের পক্ষে কথা বলেছো, কিন্তু কেয়ামতের দিনে আল্লাহ তায়ালার সামনে কে তাদের পক্ষে কথা বলবে, কিংবা কে তাদের ওপর (সেদিন) অভিভাবক হবে?', 'Haantum haolai jadaltum AAanhum fee alhayati alddunya faman yujadilu Allaha AAanhum yawma alqiyamati am man yakoonu AAalayhim wakeelan', 1, NOW(), NOW()),
(4, 110, 'وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا', 'যে ব্যক্তি গুনাহের কাজ করে অথবা (গুনাহ করে) নিজের ওপর যুলুম করে, সে আল্লাহ তায়ালার কাছে ক্ষমা প্রার্থনা করে, (তখন) সে আল্লাহ তায়ালাকে পরম ক্ষমাশীল ও অতীব দয়ালু হিসেবে পাবে।', 'Waman yaAAmal sooan aw yathlim nafsahu thumma yastaghfiri Allaha yajidi Allaha ghafooran raheeman', 1, NOW(), NOW()),
(4, 111, 'وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', 'যে ব্যক্তি কোনো গুনাহের কাজ করে, সে এর দ্বারা নিজেই নিজের ক্ষতি সাধন করে, আল্লাহ তায়ালা সবকিছুই জানেন, তিনি কুশলী।', 'Waman yaksib ithman fainnama yaksibuhu AAala nafsihi wakana Allahu AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 112, 'وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا', 'যে ব্যক্তি একটি অন্যায় কিংবা পাপ কাজ করে; কিন্তু সে দোষ চাপিয়ে দিলো একজন নির্দোষ ব্যক্তির ওপর, (এ কাজের ফলে) সে (প্রকারান্তরে) সাংঘাতিক একটি অপবাদ ও জঘন্য গুনাহের বোঝা নিজের ঘাড়ে উঠিয়ে নিলো।', 'Waman yaksib khateeatan aw ithman thumma yarmi bihi bareean faqadi ihtamala buhtanan waithman mubeenan', 1, NOW(), NOW()),
(4, 113, 'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا', 'যদি তোমার ওপর আল্লাহ তায়ালার অনুগ্রহ ও দয়া না থাকতো, তাহলে এদের একদল লোক তো তোমাকে (প্রায়) ভুল পথে পরিচালিত করেই ফেলেছিলো! যদিও তারা এই আচরণ দিয়ে তাদের নিজেদের ছাড়া অন্য কাউকেই পথভ্রষ্ট করতে পারছিলো না, (অবশ্য) তাদের এ (প্রতারণামূলক) কাজ দ্বারা তারা তোমার কোনোই ক্ষতি সাধন করতে সক্ষম হতো না! (কারণ) আল্লাহ তায়ালা তাঁর গ্রন্থ ও (সে গ্রন্থলব্ধ) কলা-কৌশল তোমার ওপর নাযিল করেছেন এবং তিনি তোমাকে এমন সব কিছুর জ্ঞান শিক্ষা দিয়েছেন, যা কখনো তোমার জানা ছিলো না; (আসলেই) তোমার ওপর আল্লাহ তায়ালার অনুগ্রহ ছিলো অনেক বড়ো!', 'Walawla fadlu Allahi AAalayka warahmatuhu lahammat taifatun minhum an yudillooka wama yudilloona illa anfusahum wama yadurroonaka min shayin waanzala Allahu AAalayka alkitaba waalhikmata waAAallamaka ma lam takun taAAlamu wakana fadlu Allahi AAalayka AAatheeman', 1, NOW(), NOW()),
(4, 114, '۞لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا', 'এদের অধিকাংশ গোপন শলা পরামর্শের ভেতরেই কোনো কল্যাণ নিহিত নেই, তবে যদি কেউ (এর দ্বারা) কাউকে কোনো দান-খয়রাত, সৎকাজ ও অন্য মানুষের মাঝে সংশোধন (কর্মসূচী)-এর আদেশ দেয়– তা ভিন্ন কথা; আর আল্লাহ তায়ালার সন্তুষ্টি অর্জনের লক্ষ্যে যদি কেউ এসব কাজ করে তাহলে অতি শীঘ্রই আমি তাকে মহাপুরস্কার দিবো।', 'La khayra fee katheerin min najwahum illa man amara bisadaqatin aw maAAroofin aw islahin bayna alnnasi waman yafAAal thalika ibtighaa mardati Allahi fasawfa nuteehi ajran AAatheeman', 1, NOW(), NOW()),
(4, 115, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا', '(আবার) যে ব্যক্তি তার কাছে প্রকৃত হেদায়াত স্পষ্ট হয়ে যাওয়ার পর রাসূলের বিরুদ্ধাচরণ করবে এবং ঈমানদারদের পথ ছেড়ে (বেঈমান লোকদের) অন্য ধরনের নিয়ম-নীতির অনুসরণ করবে, তাকে আমি সেদিকেই ধাবিত করবো– যেদিকে সে ধাবিত হয়েছে, (এর শাস্তি হিসেবে) তাকে আমি জাহান্নামের আগুনে পুড়িয়ে দিবো, (আর) তা কতো নিকৃষ্ট আবাসস্থল!', 'Waman yushaqiqi alrrasoola min baAAdi ma tabayyana lahu alhuda wayattabiAA ghayra sabeeli almumineena nuwallihi ma tawalla wanuslihi jahannama wasaat maseeran', 1, NOW(), NOW()),
(4, 116, 'إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا', 'আল্লাহ তায়ালা (এ বিষয়টি) কখনো ক্ষমা করবেন না যে, তাঁর সাথে (কোনো কিছুকে) শরীক করা হবে, এ ছাড়া অন্য সকল গুনাহ তিনি যাকে ইচ্ছা করেন তাকে ক্ষমা করে দেবেন; যে ব্যক্তি আল্লাহ তায়ালার সাথে (কাউকে) শরীক করলো, সে চরমভাবে গোমরাহ হয়ে গেলো।', 'Inna Allaha la yaghfiru an yushraka bihi wayaghfiru ma doona thalika liman yashao waman yushrik biAllahi faqad dalla dalalan baAAeedan', 1, NOW(), NOW()),
(4, 117, 'إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا', 'আল্লাহকে ছাড়া এরা (যদি কাউকে ডাকে)- ডাকবে কোনো (নিকৃষ্ট) দেবীকে কিংবা কোনো বিদ্রোহী শয়তানকে!', 'In yadAAoona min doonihi illa inathan wain yadAAoona illa shaytanan mareedan', 1, NOW(), NOW()),
(4, 118, 'لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا', '(যে এভাবে ডাকে) তাকে আল্লাহ তায়ালা অভিশাপ দিয়েছেন। (কারণ) সে (আল্লাহকে প্রতিদ্বন্দ্বিতায় আহবান দিয়ে) বলেছিলো, আমি তোমার বান্দাদের এক অংশকে নিজের (দলে শামিল) করেই ছাড়বো।', 'LaAAanahu Allahu waqala laattakhithanna min AAibadika naseeban mafroodan', 1, NOW(), NOW()),
(4, 119, 'وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا', '(শয়তান আরো বলেছিলো,) আমি অবশ্যই তাদের গোমরাহ করে দিবো, আমি অবশ্যই তাদের হৃদয়ে নানা প্রকারের মিথ্যা কামনা (বাসনা) জাগিয়ে তুলবো এবং আমি তাদের নির্দেশ দিবো যেন তারা (কুসংস্কারে লিপ্ত হয়ে) জন্তু-জানোয়ারের কান ছিদ্র করে, আমি তাদের আরো নির্দেশ দিবো তারা যেন আল্লাহ তায়ালার সৃষ্টিকে বিকৃত করে দেয়; (মূলত) যে ব্যক্তি (এ কাজ করে) আল্লাহ তায়ালার বদলে শয়তানকে নিজের পৃষ্ঠপোষক বানিয়ে নেবে, সে এক সুস্পষ্ট ক্ষতি ও লোকসানের সম্মুখীন হবে।', 'Walaodillannahum walaomanniyannahum walaamurannahum falayubattikunna athana alanAAami walaamurannahum falayughayyirunna khalqa Allahi waman yattakhithi alshshaytana waliyyan min dooni Allahi faqad khasira khusranan mubeenan', 1, NOW(), NOW()),
(4, 120, 'يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا', 'শয়তান তাদের (নানা) প্রতিশ্রুতি দেয়, তাদের (সামনে) মিথ্যা বাসনার (মায়াজাল) সৃষ্টি করে, আর শয়তান যা প্রতিশ্রুতি দেয় তা তো প্রতারণা ছাড়া আর কিছুই নয়।', 'YaAAiduhum wayumanneehim wama yaAAiduhumu alshshaytanu illa ghurooran', 1, NOW(), NOW()),
(4, 121, 'أُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا', 'এরাই হচ্ছে সেসব (হতভাগ্য) ব্যক্তি, যাদের আবাসস্থল হচ্ছে জাহান্নাম, যার (আযাব) থেকে মুক্তির কোনো পন্থাই (সেদিন) তারা (খুঁজে) পাবে না।', 'Olaika mawahum jahannamu wala yajidoona AAanha maheesan', 1, NOW(), NOW()),
(4, 122, 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا', 'অপরদিকে যারা (শয়তানের প্রতিশ্রুতি উপেক্ষা করে আল্লাহ তায়ালার ওপর) ঈমান আনবে এবং ভালো কাজ করবে, তাদের আমি অচিরেই এমন এক জান্নাতে প্রবেশ করাবো, যার তলদেশ দিয়ে ঝর্ণাধারা বইতে থাকবে, তারা সেখানে অনন্তকাল অবস্থান করবে; আল্লাহর ওয়াদা সত্য; আর আল্লাহর চাইতে বেশী সত্য কথা কে বলতে পারে?', 'Waallatheena amanoo waAAamiloo alssalihati sanudkhiluhum jannatin tajree min tahtiha alanharu khalideena feeha abadan waAAda Allahi haqqan waman asdaqu mina Allahi qeelan', 1, NOW(), NOW()),
(4, 123, 'لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا', '(কারো ভালোমন্দ যেমন) তোমাদের খেয়াল খুশীর সাথে (জড়িত) নয়, (তেমনি তা) আহলে কিতাবদের খেয়ালখুশীর সাথেও (সম্পৃক্ত) নয়, (আসল কথা হচ্ছে), যে ব্যক্তি কোনো গুনাহের কাজ করবে, তাকে তার প্রতিফল দেয়া হবে, আর সে ব্যক্তি (সেদিন) আল্লাহ তায়ালা ছাড়া অন্য কাউকেই তার পৃষ্ঠপোষক ও সাহায্যকারী হিসেবে পাবে না।', 'Laysa biamaniyyikum wala amaniyyi ahli alkitabi man yaAAmal sooan yujza bihi wala yajid lahu min dooni Allahi waliyyan wala naseeran', 1, NOW(), NOW()),
(4, 124, 'وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا', '(পক্ষান্তরে) যে ব্যক্তি কোনো ভালো কাজ করবে- নর কিংবা নারী, সে যদি ঈমানদার অবস্থায়ই তা (সম্পাদন) করে, তাহলে (সে এবং তার মতো অন্য) সব লোক জান্নাতে প্রবেশ করবে, (সেদিন) তাদের ওপর বিন্দুমাত্রও অবিচার করা হবে না।', 'Waman yaAAmal mina alssalihati min thakarin aw ontha wahuwa muminun faolaika yadkhuloona aljannata wala yuthlamoona naqeeran', 1, NOW(), NOW()),
(4, 125, 'وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا', 'তার চাইতে উত্তম জীবন বিধান আর কার হতে পারে, যে আল্লাহ তায়ালার সামনে মাথানত করে, (মূলত) সে-ই হচ্ছে নিষ্ঠাবান ব্যক্তি, (তদুপরি) সে ইবরাহীমের আদর্শেরও অনুসরণ করে; আর আল্লাহ তায়ালা ইবরাহীমকে স্বীয় বন্ধুরূপে গ্রহণ করেছেন।', 'Waman ahsanu deenan mimman aslama wajhahu lillahi wahuwa muhsinun waittabaAAa millata ibraheema haneefan waittakhatha Allahu ibraheema khaleelan', 1, NOW(), NOW()),
(4, 126, 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا', 'আসমান ও যমীনে যা কিছু আছে তার সব কিছু‍ই আল্লাহ তায়ালার জন্যে, আর আল্লাহ তায়ালা (তাঁর ক্ষমতা দিয়ে) সব কিছুই পরিবেষ্টন করে আছেন।', 'Walillahi ma fee alssamawati wama fee alardi wakana Allahu bikulli shayin muheetan', 1, NOW(), NOW()),
(4, 127, 'وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّـٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا', '(হে নবী,) তারা তোমার কাছে নারীদের ব্যাপারে সিদ্ধান্ত জানতে চায়, তুমি বলো, আল্লাহ তায়ালা তাদের ব্যাপারে তোমাদের জানিয়ে দিচ্ছেন, আর এ কিতাব থেকে যা কিছু তোমাদের ওপর পঠিত হচ্ছে, সেই এতীম নারীদের সম্পর্কিত (বিষয়), তিনি তাদের যেসব অধিকার দান করেছেন যা তোমরা আদায় করতে চাও না, অথচ তোমরা তাদের বিয়ে (ঠিকই) করতে চাও, অসহায় শিশুদের ব্যাপারে (তোমাদের বলা হচ্ছে,) তোমরা যেন এতীমদের ব্যাপারে সুবিচার কায়েম করো; তোমরা যেটুকু ভালো কাজই করো, আল্লাহ তায়ালা সে সম্পর্কে সম্যকভাবে অবহিত রয়েছেন।', 'Wayastaftoonaka fee alnnisai quli Allahu yufteekum feehinna wama yutla AAalaykum fee alkitabi fee yatama alnnisai allatee la tutoonahunna ma kutiba lahunna watarghaboona an tankihoohunna waalmustadAAafeena mina alwildani waan taqoomoo lilyatama bialqisti wama tafAAaloo min khayrin fainna Allaha kana bihi AAaleeman', 1, NOW(), NOW()),
(4, 128, 'وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', 'যদি কোনো স্ত্রীলোক তার স্বামীর কাছ থেকে দুর্ব্যবহার কিংবা অবজ্ঞার আশংকা করে, তাহলে (পারস্পরিক ভালোর জন্যে) তাদের উভয়ের মধ্যে আপস- নিষ্পত্তি করে নিলে তাদের ওপর এতে কোনো দোষ নেই; কারণ আপসই হচ্ছে উত্তম, (আসলে) মানুষ লালসার দিকেই বেশী পরিমাণে ধাবিত হয়ে পড়ে; (কিন্তু) তোমরা যদি সততা ও তাকওয়া অবলম্বন করো, তাহলে (তাই তোমাদের জন্যে ভালো) আল্লাহ তায়ালা তোমাদের সব কর্মকান্ডই অবলোকন করছেন।', 'Waini imraatun khafat min baAAliha nushoozan aw iAAradan fala junaha AAalayhima an yusliha baynahuma sulhan waalssulhu khayrun waohdirati alanfusu alshshuhha wain tuhsinoo watattaqoo fainna Allaha kana bima taAAmaloona khabeeran', 1, NOW(), NOW()),
(4, 129, 'وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا', 'তোমরা কখনো (একাধিক) স্ত্রীদের মাঝে ইনসাফ করতে পারবে না, যদিও (মনে প্রাণে) তোমরা তা চাইবে, তাই তাদের একজনের দিকে তুমি এমনভাবে ঝুঁকে পড়ো না, (মনে হবে) আরেকজনকে তুমি ঝুলন্ত অবস্থায় (রেখে দিয়েছো); তোমরা যদি সংশোধন এবং তাকওয়া অবলম্বন করো, তাহলে (তুমি দেখবে,) আল্লাহ তায়ালা অতি ক্ষমাশীল ও পরম দয়ালু।', 'Walan tastateeAAoo an taAAdiloo bayna alnnisai walaw harastum fala tameeloo kulla almayli fatatharooha kaalmuAAallaqati wain tuslihoo watattaqoo fainna Allaha kana ghafooran raheeman', 1, NOW(), NOW()),
(4, 130, 'وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا', '(অতঃপর) যদি তারা একে অপরের কাছ থেকে বিচ্ছিন্ন হয়ে যায়, তাহলে আল্লাহ তায়ালা তার ভান্ডার থেকে দান করে তাদের সবাইকে পারস্পরিক মুখাপেক্ষিতা থেকে রেহাই দেবেন, আল্লাহ তায়ালা প্রাচুর্যময় ও প্রশংসাভাজন।', 'Wain yatafarraqa yughni Allahu kullan min saAAatihi wakana Allahu wasiAAan hakeeman', 1, NOW(), NOW()),
(4, 131, 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا', 'আসমান যমীনে যা কিছু আছে সবই আল্লাহ তায়ালার জন্যে, তোমাদের আগেও যাদের কিতাব দেয়া হয়েছিলো, তাদের ও তোমাদের আমি এ নির্দেশ দিয়েছিলাম যেন তারা ও তোমরা আল্লাহ তায়ালাকে ভয় করো । যদি তোমরা (আল্লাহকে) অস্বীকার করো (তাহলে জেনে রেখো), আসমান যমীনে যা কিছু আছে সব কিছুই আল্লাহ তায়ালার জন্যে; আল্লাহ তায়ালা কারোই মুখাপেক্ষী নন, সব প্রশংসা তাঁর।', 'Walillahi ma fee alssamawati wama fee alardi walaqad wassayna allatheena ootoo alkitaba min qablikum waiyyakum ani ittaqoo Allaha wain takfuroo fainna lillahi ma fee alssamawati wama fee alardi wakana Allahu ghaniyyan hameedan', 1, NOW(), NOW()),
(4, 132, 'وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'অবশ্যই আসমান-যমীনের সব কয়টি জিনিসের মালিকানা আল্লাহর, অভিভাবক হিসেবে আল্লাহ তায়ালাই যথেষ্ট!', 'Walillahi ma fee alssamawati wama fee alardi wakafa biAllahi wakeelan', 1, NOW(), NOW()),
(4, 133, 'إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا', 'হে মানুষ, তিনি চাইলে যে কোনো সময় (যমীনের কর্তৃত্ব থেকে) তোমাদের অপসারণ করে অন্য কোনো সম্প্রদায়কে এনে বসিয়ে দিতে পারেন, এ কাজের ওপর আল্লাহ তায়ালা অবশ্যই ক্ষমতাবান।', 'In yasha yuthhibkum ayyuha alnnasu wayati biakhareena wakana Allahu AAala thalika qadeeran', 1, NOW(), NOW()),
(4, 134, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا', 'যে ব্যক্তি এ দুনিয়ার পুরস্কারটুকুই পেতে চায় (তার জেনে রাখা উচিত), আল্লাহ তায়ালার কাছে তো ইহকাল পরকাল (এ উভয়কালের) পুরস্কারই রয়েছে, আল্লাহ তায়ালা সব কিছু শোনেন এবং সব কিছুই দেখেন।', 'Man kana yureedu thawaba alddunya faAAinda Allahi thawabu alddunya waalakhirati wakana Allahu sameeAAan baseeran', 1, NOW(), NOW()),
(4, 135, '۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا', 'হে ঈমানদাররা, তোমরা ইনসাফের ওপর (দৃঢ়ভাবে ) কায়েম থেকো এবং আল্লাহ তায়ালার জন্যে সত্যের সাক্ষী হয়ে যাও, যদি এ (কাজ)-টি তোমার নিজের, নিজের পিতামাতার কিংবা নিজের আত্মীয় স্বজনের বিপক্ষেও আসে (তবুও তোমরা তা পালন করবে), সে ব্যক্তি ধনী হোক কিংবা গরীব হোক! (মনে রাখবে) তাদের উভয়ের চাইতে আল্লাহ তায়ালার অধিকার অনেক বেশী, অতএব তুমি কখনো ন্যায়বিচার করতে গিয়ে নিজের খেয়ালখুশীর অনুসরণ করো না, যদি তোমরা পেঁচানো কথা বলো কিংবা (ইনসাফ থেকে) বিরত থাকো, তাহলে (জেনে রেখো,) তোমরা যা কিছুই করো না কেন, আল্লাহ তায়ালা তার খবর রাখেন।', 'Ya ayyuha allatheena amanoo koonoo qawwameena bialqisti shuhadaa lillahi walaw AAala anfusikum awi alwalidayni waalaqrabeena in yakun ghaniyyan aw faqeeran faAllahu awla bihima fala tattabiAAoo alhawa an taAAdiloo wain talwoo aw tuAAridoo fainna Allaha kana bima taAAmaloona khabeeran', 1, NOW(), NOW()),
(4, 136, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا', 'হে ঈমানদার ব্যক্তিরা, তোমরা ঈমান আনো আল্লাহর ওপর, তাঁর রাসূলের ওপর, সে কিতাবের ওপর যা তিনি তিনি তাঁর রাসূলের ওপর নাযিল করেছেন এবং সেসব কিতাবের ওপর যা (তিনি তারও আগে) নাযিল করেছেন, যে ব্যক্তি আল্লাহ তায়ালা, তাঁর ফেরেশতা তাঁর কিতাবসমূহ, তাঁর নবী রাসূল ও পরকাল দিবসকে অস্বীকার করবে, সে অবশ্যই মারাত্মকভাবে পথভ্রষ্ট হয়ে যাবে!', 'Ya ayyuha allatheena amanoo aminoo biAllahi warasoolihi waalkitabi allathee nazzala AAala rasoolihi waalkitabi allathee anzala min qablu waman yakfur biAllahi wamalaikatihi wakutubihi warusulihi waalyawmi alakhiri faqad dalla dalalan baAAeedan', 1, NOW(), NOW()),
(4, 137, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا', 'নিসন্দেহে যারা ঈমান আনলো আবার কুফরী করলো, (কিছু দিন পর) আবার ঈমান আনলো, এরপর (সুযোগ বুঝে) আবার কাফের হয়ে গেলো, এরপর কুফরীর পরিমাণ তারা (দিনে দিনে) বাড়িয়ে দিলো, আল্লাহ তায়ালা এমন লোকদের কখনো ক্ষমা করবেন না, না কখনো তিনি এসব ব্যক্তিদের সঠিক পথ দেখাবেন!', 'Inna allatheena amanoo thumma kafaroo thumma amanoo thumma kafaroo thumma izdadoo kufran lam yakuni Allahu liyaghfira lahum wala liyahdiyahum sabeelan', 1, NOW(), NOW()),
(4, 138, 'بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا', '(হে নবী,) মোনাফেকদের তুমি সুসংবাদ দাও যে, তাদের জন্যে ভয়াবহ আযাব রয়েছে,', 'Bashshiri almunafiqeena bianna lahum AAathaban aleeman', 1, NOW(), NOW()),
(4, 139, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا', 'যারা (বৈষয়িক স্বার্থে) ঈমানদারদের বদলে কাফেরদের বন্ধু হিসেবে গ্রহণ করেছে, তারা (কি এর দ্বারা) এদের কাছ থেকে কোনো রকম মান-সম্মানের প্রত্যাশা করে? অবশ্যই (সবটুকু) মান-সম্মান তো আল্লাহ তায়ালার জন্যেই (নির্দিষ্ট)।', 'Allatheena yattakhithoona alkafireena awliyaa min dooni almumineena ayabtaghoona AAindahumu alAAizzata fainna alAAizzata lillahi jameeAAan', 1, NOW(), NOW()),
(4, 140, 'وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا', 'তিনি ইতিপূর্বেও এ কিতাবের মাধ্যমে তোমাদের ওপর আদেশ নাযিল করেছিলেন যে, তোমরা যখন শুনবে (কাফেরদের কোনো বৈঠকে) আল্লাহ তায়ালার নাযিল করা কোনো আয়াত অস্বীকার করা হচ্ছে এবং তা নিয়ে ঠাট্টা-বিদ্রূপ করা হচ্ছে, তখন তোমরা তাদের সাথে (সে মজলিসে) বসো না, যতোক্ষণ না তারা অন্য কোনো আলোচনায় লিপ্ত হয়, (এমনটি করলে) তোমরা তো ঠিক তাদের মতোই হয়ে গেলে, (জেনে রেখো) আল্লাহ তায়ালা অবশ্যই সব কাফের ও মোনাফেকদের জাহান্নামে একত্রিত করে ছাড়বেন।', 'Waqad nazzala AAalaykum fee alkitabi an itha samiAAtum ayati Allahi yukfaru biha wayustahzao biha fala taqAAudoo maAAahum hatta yakhoodoo fee hadeethin ghayrihi innakum ithan mithluhum inna Allaha jamiAAu almunafiqeena waalkafireena fee jahannama jameeAAan', 1, NOW(), NOW()),
(4, 141, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا', 'যারা সব সময়ই তোমাদের (শুভ দিনের) প্রতীক্ষায় থাকে, যদি আল্লাহ তায়ালার কাছ থেকে তোমাদের বিজয় আসে তখন এরা বলবে, কেন, আমরা কি (যুদ্ধে) তোমাদের সাথে ছিলাম না? (আবার) যদি কখনো কাফেরদের (ভাগে বিজয়ের) অংশ (লেখা) হয়, তাহলে এরা বলবে, আমরা কি তোমাদের ঘিরে রাখিনি? এবং তোমাদেরকে মুসলমানদের কাছ থেকে রক্ষা করিনি? (আসলে) শেষ বিচারের দিনে আল্লাহ তায়ালাই তোমাদের উভয়ের মাঝে ফয়সালা শুনিয়ে দেবেন এবং আল্লাহ তায়ালা (সেদিন) মুমীনদের বিরুদ্ধে কাফেরদের কোনো (অজুহাত পেশ করার) পথ অবশিষ্ট রাখবেন না।', 'Allatheena yatarabbasoona bikum fain kana lakum fathun mina Allahi qaloo alam nakun maAAakum wain kana lilkafireena naseebun qaloo alam nastahwith AAalaykum wanamnaAAkum mina almumineena faAllahu yahkumu baynakum yawma alqiyamati walan yajAAala Allahu lilkafireena AAala almumineena sabeelan', 1, NOW(), NOW()),
(4, 142, 'إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا', 'অবশ্যই মোনাফেকরা আল্লাহ তায়ালাকে ধোকা দেয়, (মূলত এর মাধ্যমে) আল্লাহ তায়ালাই তাদের প্রতারণায় ফেলে দিচ্ছেন, এরা যখন নামাযে দাঁড়ায় তখন একান্ত আলস্যভরেই দাঁড়ায়, তারা কেবল লোকদের দেখায়, এরা আল্লাহ তায়ালাকে (আসলে) কমই স্মরণ করে।', 'Inna almunafiqeena yukhadiAAoona Allaha wahuwa khadiAAuhum waitha qamoo ila alssalati qamoo kusala yuraoona alnnasa wala yathkuroona Allaha illa qaleelan', 1, NOW(), NOW()),
(4, 143, 'مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا', 'এরা (কুফরী ও ঈমানের) দোটানায় দোদুল্যমান, (এরা) না এদিকে না ওদিকে; যাকে আল্লাহ তায়ালাই গোমরাহ করে দেন তুমি সে ব্যক্তিকে কখনো (সঠিক) পথ দেখাতে পারবে না।', 'Muthabthabeena bayna thalika la ila haolai wala ila haolai waman yudlili Allahu falan tajida lahu sabeelan', 1, NOW(), NOW()),
(4, 144, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا', 'হে মানুষ তোমরা যারা ঈমান এনেছো, তোমরা ঈমানদারদের বাদ দিয়ে কাফেরদের নিজেদের বন্ধুরূপে গ্রহণ করো না; (তেমন কিছু করে) তোমরা কি আল্লাহ তায়ালার কাছে তোমাদের বিরুদ্ধে (কোনো) সুস্পষ্ট প্রমাণ তুলে দিতে চাও?', 'Ya ayyuha allatheena amanoo la tattakhithoo alkafireena awliyaa min dooni almumineena atureedoona an tajAAaloo lillahi AAalaykum sultanan mubeenan', 1, NOW(), NOW()),
(4, 145, 'إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا', 'অবশ্যই মোনাফেকরা জাহান্নামের সর্বনিম্নস্তরে অবস্থান করবে, তুমি সেদিন তাদের জন্যে কোনো সাহায্যকারী (খুঁজে) পাবে না।', 'Inna almunafiqeena fee alddarki alasfali mina alnnari walan tajida lahum naseeran', 1, NOW(), NOW()),
(4, 146, 'إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا', 'তবে তাদের কথা আলাদা, যারা তাওবা করে এবং (সে আলোকে নিজেদের) সংশোধন করে নেয়, আল্লাহ তায়ালার রশি শক্ত করে ধরে রাখে এবং একমাত্র আল্লাহ তায়ালার উদ্দেশেই তারা তাদের জীবন বিধানকে নিবেদন করে নেয়, এসব লোকেরা অবশ্যই (সেদিন) ঈমানদারদের সাথে থাকবে; আর অচিরেই আল্লাহ তায়ালা তাঁর ঈমানদার বান্দাদের বড়ো ধরনের পুরস্কার দেবেন।', 'Illa allatheena taboo waaslahoo waiAAtasamoo biAllahi waakhlasoo deenahum lillahi faolaika maAAa almumineena wasawfa yuti Allahu almumineena ajran AAatheeman', 1, NOW(), NOW()),
(4, 147, 'مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا', 'তোমাদের শাস্তি দিয়ে আল্লাহ তায়ালা কি করবেন– যদি তোমরা (তাঁর) কৃতজ্ঞতা আদায় করো এবং তাঁর ওপর ঈমান আনো; (বস্তুত) আল্লাহ তায়ালাই হচ্ছেন (সর্বোচ্চ) পুরস্কারদাতা, সম্যক ওয়াকেফহাল।', 'Ma yafAAalu Allahu biAAathabikum in shakartum waamantum wakana Allahu shakiran AAaleeman', 1, NOW(), NOW()),
(4, 148, '۞لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', 'আল্লাহ তায়ালা প্রকাশ্যভাবে মন্দ বলা পছন্দ করেন না, তবে যে ব্যক্তির ওপর অবিচার করা হয়েছে তার কথা আলাদা; আল্লাহ তায়ালা সবকিছুই শোনেন এবং জানেন।', 'La yuhibbu Allahu aljahra bialssooi mina alqawli illa man thulima wakana Allahu sameeAAan AAaleeman', 1, NOW(), NOW()),
(4, 149, 'إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا', 'ভালো কাজ তোমরা প্রকাশ করো কিংবা তা গোপন করো, অথবা কোনো মন্দ কাজের জন্যে যদি তোমরা (কাউকে) ক্ষমা করে দাও, তাহলে (তোমরা দেখতে পাবে,) নিসন্দেহে আল্লাহ তায়ালা অতি ক্ষমাশীল ও প্রবল শক্তিমান।', 'In tubdoo khayran aw tukhfoohu aw taAAfoo AAan sooin fainna Allaha kana AAafuwwan qadeeran', 1, NOW(), NOW()),
(4, 150, 'إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا', 'নিশ্চয়ই যারা আল্লাহ তায়ালা ও তাঁর রাসূলদের অস্বীকার করে এবং আল্লাহ তায়ালা ও রাসূলদের মাঝে যারা পার্থক্য করতে চায় তারা বলে, আমরা (রাসূলদের) কয়েকজনকে স্বীকার করি আবার কয়েকজনকে স্বীকার করি না, এর দ্বারা (আসলে) এরা (নিজেদের জন্যে) একটা মাঝামাঝি রাস্তা বের করে নিতে চায়।', 'Inna allatheena yakfuroona biAllahi warusulihi wayureedoona an yufarriqoo bayna Allahi warusulihi wayaqooloona numinu bibaAAdin wanakfuru bibaAAdin wayureedoona an yattakhithoo bayna thalika sabeelan', 1, NOW(), NOW()),
(4, 151, 'أُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا', 'এরা হচ্ছে সত্যিকারের কাফের, আর আমি কাফেরদের জন্যে এক চরম লাঞ্ছনাদায়ক শাস্তি নির্দিষ্ট করে রেখেছি।', 'Olaika humu alkafiroona haqqan waaAAtadna lilkafireena AAathaban muheenan', 1, NOW(), NOW()),
(4, 152, 'وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَـٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', '(অপরদিকে) যারা আল্লাহ তায়ালা ও তাঁর রাসূলদের ওপর ঈমান এনেছে এবং তাঁদের একজনের সাথে আরেকজ নের কখনো কোনো রকম পার্থক্য করেনি, এরা হচ্ছে সেসব লোক যাদের তিনি অচিরেই অনেক পুরস্কার দান করবেন, আল্লাহ তায়ালা অত্যন্ত ক্ষমাশীল, মহাদয়ালু।', 'Waallatheena amanoo biAllahi warusulihi walam yufarriqoo bayna ahadin minhum olaika sawfa yuteehim ojoorahum wakana Allahu ghafooran raheeman', 1, NOW(), NOW()),
(4, 153, 'يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا', 'আহলে কিতাবের লোকেরা তোমার কাছে চায়– তুমি যেন আসমান থেকে তাদের জন্যে কোনো কিতাব নাযিল (করার ব্যবস্থা) করো! এরা (কিন্তু) মূসার কাছে এর চাইতেও বড়ো রকমের দাবী পেশ করেছিলো, তারা বলেছিলো (হে মূসা), তুমি স্বয়ং আল্লাহ তায়ালাকেই আমাদের প্রকাশ্যভাবে দেখিয়ে দাও, অতঃপর তাদের এই সীমালংঘনের জন্যে তাদের ওপর প্রচন্ড বজ্রপাত নিপতিত হয়েছে এবং (নবুওতের) সুস্পষ্ট প্রমাণসমূহ তাদের কাছে আসার পরও তারা গো-বাছুরকে উপাস্য হিসেবে গ্রহণ করেছে, তারপরও আমি তাদের এ (অপরাধ)-টা ক্ষমা করে দিলাম এবং আমি মূসাকে স্পষ্ট প্রমাণ (-সহ কিতাব) দান করলাম।', 'Yasaluka ahlu alkitabi an tunazzila AAalayhim kitaban mina alssamai faqad saaloo moosa akbara min thalika faqaloo arina Allaha jahratan faakhathathumu alssaAAiqatu bithulmihim thumma ittakhathoo alAAijla min baAAdi ma jaathumu albayyinatu faAAafawna AAan thalika waatayna moosa sultanan mubeenan', 1, NOW(), NOW()),
(4, 154, 'وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا', 'এদের কাছ থেকে (আনুগত্যের) প্রতিশ্রুতি আদায় করার জন্যে আমি তূর পাহাড়কে এদের উপর উঁচু করে ধরেছিলাম, আমি তাদের বলেছিলাম, নগরের দরজা দিয়ে প্রবেশ করার সময় তোমরা একান্ত অনুগত হয়ে ঢুকবে, আমি তাদের বলেছিলাম, তোমরা শনিবারে (মাছ ধরে আমার বিধানের) সীমালংঘন করো না, (এ ব্যাপারে) আমি তাদের কাছ থেকে শক্ত প্রতিশ্রুতিও আদায় করে নিয়েছিলাম।', 'WarafaAAna fawqahumu alttoora bimeethaqihim waqulna lahumu odkhuloo albaba sujjadan waqulna lahum la taAAdoo fee alssabti waakhathna minhum meethaqan ghaleethan', 1, NOW(), NOW()),
(4, 155, 'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا', 'অতঃপর তাদের (এই) প্রতিশ্রুতি ভঙ্গ করা, আল্লাহর আয়াতসমূহকে তাদের অস্বীকার করা এবং অন্যায়ভাবে নবীদের তাদের হত্যা করা, (তদুপরি) তাদের (একথা) বলা যে, আমাদের অন্তরসমূহ (বাতিল চিন্তাধারায়) আচ্ছাদিত (হয়ে আছে), প্রকৃতপক্ষে তাদের কুফুরীর কারণে আল্লাহ তায়ালা স্বয়ং তাদের দিলের ওপর মোহর মেরে দিয়েছেন, অতঃপর এদের কমসংখ্যক লোকই ঈমান আনে।', 'Fabima naqdihim meethaqahum wakufrihim biayati Allahi waqatlihimu alanbiyaa bighayri haqqin waqawlihim quloobuna ghulfun bal tabaAAa Allahu AAalayha bikufrihim fala yuminoona illa qaleelan', 1, NOW(), NOW()),
(4, 156, 'وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا', 'যেহেতু এরা (আল্লাহকে) অস্বীকার করতেই থাকলো এবং এরা (পুণ্যবতী) মারইয়ামের ওপরও জঘন্য অপবাদ আনলো,', 'Wabikufrihim waqawlihim AAala maryama buhtanan AAatheeman', 1, NOW(), NOW()),
(4, 157, 'وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا', 'উপরন্তু তাদের উক্তি যে, আমরাই আল্লাহর রাসূল মারইয়ামের পুত্র ঈসাকে হত্যা করেছি, (আসলে) তারা কখনোই তাকে হত্যা করেনি, তারা তাকে শূলবিদ্ধও করেনি, (শুধু ধাঁধার কারণে) তাদের কাছে এমনি একটা কিছু মনে হয়েছিলো; (সঠিক ঘটনা না জানার কারণে) | যারা তার ব্যাপারে মতবিরোধ করেছিলো, তারাও (এতে করে) সন্দেহে পড়ে গেলো, আর এ ব্যাপারে তাদের অনুমানের অনুসরণ করা ছাড়া সঠিক কোনো জ্ঞানই ছিলো না, (তবে) এটুকু নিশ্চিত, তারা তাকে হত্যা করেনি।', 'Waqawlihim inna qatalna almaseeha AAeesa ibna maryama rasoola Allahi wama qataloohu wama salaboohu walakin shubbiha lahum wainna allatheena ikhtalafoo feehi lafee shakkin minhu ma lahum bihi min AAilmin illa ittibaAAa alththanni wama qataloohu yaqeenan', 1, NOW(), NOW()),
(4, 158, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا', 'বরং আল্লাহ তায়ালাই তাকে তাঁর নিজের কাছে তুলে নিয়েছেন; আল্লাহ তায়ালা মহাপরাক্রমশালী ও মহাপ্রজ্ঞাময়।', 'Bal rafaAAahu Allahu ilayhi wakana Allahu AAazeezan hakeeman', 1, NOW(), NOW()),
(4, 159, 'وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا', 'আহলে কিতাবদের মাঝে এমন একজনও থাকবে না, যে ব্যক্তি তার মৃত্যুর আগে তাঁর (তিরোধান সম্পর্কে আল্লাহ তায়ালার এই কথার) ওপর ঈমান আনবে না, কেয়ামতের দিন সে তো নিজেই এদের ওপর সাক্ষী হবে।', 'Wain min ahli alkitabi illa layuminanna bihi qabla mawtihi wayawma alqiyamati yakoonu AAalayhim shaheedan', 1, NOW(), NOW()),
(4, 160, 'فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا', 'ইহুদীদের বাড়াবাড়ি ও সীমালংঘনমূলক আচরণের জন্যে (এমন) অনেক পবিত্র জিনিসও আমি তাদের জন্যে হারাম করে দিয়েছিলাম যেটা তাদের জন্যে (আগে) হালাল ছিলো, এটা এই কারণে যে, এরা বহু মানুষকে আল্লাহ তায়ালার পথ থেকে বিরত রেখেছে।', 'Fabithulmin mina allatheena hadoo harramna AAalayhim tayyibatin ohillat lahum wabisaddihim AAan sabeeli Allahi katheeran', 1, NOW(), NOW()),
(4, 161, 'وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا', '(লেনদেনে) এদের সূদ গ্রহণ করা, এবং এদের অন্যের মাল-সম্পদ ধোকা প্রতারণার মাধ্যমে গ্রাস করা; অথচ এদের তা থেকে (সুস্পষ্টভাবে) নিষেধ করা হয়েছিলো, তাদের মধ্যে (এ সব অপরাধে লিপ্ত) কাফেরদের জন্যে আমি কঠিন আযাব নির্দিষ্ট করে রেখেছি।', 'Waakhthihimu alrriba waqad nuhoo AAanhu waaklihim amwala alnnasi bialbatili waaAAtadna lilkafireena minhum AAathaban aleeman', 1, NOW(), NOW()),
(4, 162, 'لَّـٰكِنِ ٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَـٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا', 'কিন্তু তাদের মধ্যে যাদের জ্ঞানের গভীরতা রয়েছে তারা এবং এমন সব ঈমানদার যারা তোমার ওপর যা কিছু নাযিল হয়েছে তার ওপর বিশ্বাস করে, (সাথে সাথে) তোমার পূর্ববর্তী নবী ও রাসূলদের ওপর যা নাযিল হয়েছে তার ওপরও বিশ্বাস করে, নামায প্রতিষ্ঠা করে, যাকাত আদায় করে, (সর্বোপরি) আল্লাহ তায়ালা ও শেষ দিনের ওপর ঈমান আনে; (মূলত) এরাই হচ্ছে সেসব (সৌভাগ্যবান) মানুষ, যাদের অচিরেই আমি বড়ো পুরস্কার দিবো।', 'Lakini alrrasikhoona fee alAAilmi minhum waalmuminoona yuminoona bima onzila ilayka wama onzila min qablika waalmuqeemeena alssalata waalmutoona alzzakata waalmuminoona biAllahi waalyawmi alakhiri olaika sanuteehim ajran AAatheeman', 1, NOW(), NOW()),
(4, 163, '۞إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا', '(হে নবী,) আমি তোমার কাছে আমার ওহী পাঠিয়েছি, যেমনি করে আমি ওহী পাঠিয়েছিলাম নূহ ও তার পরবর্তী নবীদের কাছে, আমি (আরো) ওহী পাঠিয়েছি ইবরাহীম, ইসমাঈল, ইসহাক, ইয়াকুব ও তার বংশধরদের কাছে, (ওহী পাঠিয়েছি) ঈসা, আইয়ুব, ইউনুস, হারূন ও সুলাইমানের কাছেও এবং আমি দাউদের ওপর যাবুর (গ্রন্থ) অবতীর্ণ করেছি।', 'Inna awhayna ilayka kama awhayna ila noohin waalnnabiyyeena min baAAdihi waawhayna ila ibraheema waismaAAeela waishaqa wayaAAqooba waalasbati waAAeesa waayyooba wayoonusa waharoona wasulaymana waatayna dawooda zabooran', 1, NOW(), NOW()),
(4, 164, 'وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا', 'রাসূলদের মাঝে এমন অনেক আছে, যাদের কথা ইতিপূর্বে আমি তোমার কাছে বলেছি, কিন্তু এদের মাঝে এমনও বহু রাসূল আছে যাদের (কথা) কখনো আমি তোমাকে বলিনি; মূসার সাথে তো আল্লাহ তায়ালা কথাও বলেছেন।', 'Warusulan qad qasasnahum AAalayka min qablu warusulan lam naqsushum AAalayka wakallama Allahu moosa takleeman', 1, NOW(), NOW()),
(4, 165, 'رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا', 'রাসূলরা (হচ্ছে জান্নাতের) সুসংবাদবাহী ও (জাহান্নামের) ভয় প্রদর্শনকারী, (তাদের এ জন্যেই পাঠানো হয়েছিলো) যাতে করে রাসূলদের আগমনের পর আল্লাহ তায়ালার ওপর মানব জাতির কোনো অজুহাত খাড়া করার সুযোগ না থাকে; (সত্যিই) আল্লাহ তায়ালা মহাপরাক্রমশালী, প্রজ্ঞাময়।', 'Rusulan mubashshireena wamunthireena lialla yakoona lilnnasi AAala Allahi hujjatun baAAda alrrusuli wakana Allahu AAazeezan hakeeman', 1, NOW(), NOW()),
(4, 166, 'لَّـٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 'কিন্তু আল্লাহ তায়ালা তোমার ওপর যা কিছু নাযিল | করেছেন তা তার (প্রত্যক্ষ) জ্ঞানের মাধ্যমেই করেছেন, ফেরেশতারাও তো (এর) সাক্ষ্য দেবে; যদিও সাক্ষ্য প্রদানের জন্যে আল্লাহ তায়ালাই যথেষ্ট।', 'Lakini Allahu yashhadu bima anzala ilayka anzalahu biAAilmihi waalmalaikatu yashhadoona wakafa biAllahi shaheedan', 1, NOW(), NOW()),
(4, 167, 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا', 'নিশ্চয়ই যারা (আল্লাহ তায়ালাকে) অস্বীকার করে এবং (অন্য মানুষদেরও) আল্লাহ তায়ালার এ পথ থেকে সরিয়ে রাখে, তারা গোমরাহী ও পথভ্রষ্টতায় অনেক দূর এগিয়ে গেছে।', 'Inna allatheena kafaroo wasaddoo AAan sabeeli Allahi qad dalloo dalalan baAAeedan', 1, NOW(), NOW()),
(4, 168, 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا', 'নিশ্চয়ই যারা কুফরী করলো এবং সীমালংঘন করলো, (তাদের ব্যাপারে) এটা কখনো হবে না যে, আল্লাহ তায়ালা তাদের ক্ষমা করে দেবেন, আর না তিনি তাদের সঠিক রাস্তা দেখাবেন!', 'Inna allatheena kafaroo wathalamoo lam yakuni Allahu liyaghfira lahum wala liyahdiyahum tareeqan', 1, NOW(), NOW()),
(4, 169, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا', 'কিন্তু (তাদের জন্যে উন্মুক্ত থাকবে) শুধু জাহান্নামের রাস্তা, যেখানে তারা অনন্তকাল পড়ে থাকবে; ( শাস্তি প্রদানের) এ কাজ আল্লাহর জন্যে খুবই সহজ।', 'Illa tareeqa jahannama khalideena feeha abadan wakana thalika AAala Allahi yaseeran', 1, NOW(), NOW()),
(4, 170, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا', 'হে মানুষরা, তোমাদের মালিকের কাছ থেকে তোমাদের জন্যে সঠিক (বিধান) নিয়ে রাসূল এসেছে, (এ বিধানের ওপর) তোমরা ঈমান আনো, (এতেই) তোমাদের জন্যে কল্যাণ (রয়েছে), আর তোমরা যদি তা মেনে নিতে ন-যমীনে যা অস্বীকার করো তাহলে (জেনে রেখো,) আসমান– কিছু আছে তার সব কিছুই আল্লাহ তায়ালার জন্যে এবং আল্লাহ তায়ালা সর্বজ্ঞ, কুশলী।', 'Ya ayyuha alnnasu qad jaakumu alrrasoolu bialhaqqi min rabbikum faaminoo khayran lakum wain takfuroo fainna lillahi ma fee alssamawati waalardi wakana Allahu AAaleeman hakeeman', 1, NOW(), NOW()),
(4, 171, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا', 'হে কিতাবধারীরা, নিজেদের দ্বীনের মাঝে তোমরা বাড়াবাড়ি করো না এবং (ঈসার ঘটনা নিয়ে) আল্লাহ তায়ালার ওপর সত্য ছাড়া কোনো মিথ্যা চাপিয়ো না; (সে সত্য কথা হচ্ছে,) মারইয়ামের পুত্র মাসীহ ছিলো অল্লাহর রাসূল ও তাঁর (এমন এক) বাণী, যা তিনি মারইয়ামের ওপর প্রেরণ করেছেন এবং সে ছিলো আল্লাহ তায়ালার কাছ থেকে পাঠানো এক ‘রূহ’, অতএব (হে আহলে কিতাবরা), তোমরা আল্লাহ তায়ালা ও তাঁর রাসূলদের ওপর ঈমান আনো, আর (কখনো) এটা বলো না যে, (মাবুদের সংখ্যা) তিন; এ (জঘন্য মিথ্যা) থেকে তোমরা বেঁচে থেকো, (এটাই) তোমাদের জন্যে উত্তম; নিসন্দেহে আল্লাহ তায়ালা একক মাবুদ; তিনি এ থেকে অনেক পবিত্র যে, তাঁর কোনো সন্তান থাকবে; এ আকাশ ও ভূমন্ডলের সব কিছুর মালিকানাই তাঁর, আর অভিভাবক হিসেবে আল্লাহ তায়ালাই যথেষ্ট।', 'Ya ahla alkitabi la taghloo fee deenikum wala taqooloo AAala Allahi illa alhaqqa innama almaseehu AAeesa ibnu maryama rasoolu Allahi wakalimatuhu alqaha ila maryama waroohun minhu faaminoo biAllahi warusulihi wala taqooloo thalathatun intahoo khayran lakum innama Allahu ilahun wahidun subhanahu an yakoona lahu waladun lahu ma fee alssamawati wama fee alardi wakafa biAllahi wakeelan', 1, NOW(), NOW()),
(4, 172, 'لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَـٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا', '(ঈসা) মাসীহ কখনো (এতে) নিজেকে হেয় মনে করেনি যে, সে হবে আল্লাহ তায়ালার বান্দা, ঘনিষ্ঠ ফেরেশতারাও (একে লজ্জাকর মনে করেনি); কোনো ব্যক্তি যদি (আল্লাহ তায়ালার) বন্দেগী করাকে লজ্জাকর বিষয় মনে করে (এবং এটা ভেবে) সে অহংকার করে (তার জানা উচিত), তিনি অচিরেই এদের সকলকে তাঁর সামনে একত্রিত (করে দন্ডাজ্ঞা দান) করবেন।', 'Lan yastankifa almaseehu an yakoona AAabdan lillahi wala almalaikatu almuqarraboona waman yastankif AAan AAibadatihi wayastakbir fasayahshuruhum ilayhi jameeAAan', 1, NOW(), NOW()),
(4, 173, 'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا', 'যেসব মানুষ (আল্লাহ তায়ালার ওপর) ঈমান এনেছে এবং ভালো কাজ করেছে, (সেদিন) তিনি তাদের এর জন্যে পুরোপুরি পুরস্কার দেবেন, (আল্লাহ তায়ালা) তাঁর একান্ত অনুগ্রহ থেকে তাদের (পাওনা) আরো বাড়িয়ে দেবেন, অপরদিকে যারা তাঁর বিধান মেনে নেয়াকে লজ্জাকর মনে করলো এবং অহংকার করলো, তাদের তিনি কঠোর শাস্তি দেবেন, তারা (সেদিন) আল্লাহ ছাড়া দ্বিতীয় কোনো অভিভাবক ও সাহায্যকারী পাবে না।', 'Faamma allatheena amanoo waAAamiloo alssalihati fayuwaffeehim ojoorahum wayazeeduhum min fadlihi waamma allatheena istankafoo waistakbaroo fayuAAaththibuhum AAathaban aleeman wala yajidoona lahum min dooni Allahi waliyyan wala naseeran', 1, NOW(), NOW()),
(4, 174, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا', 'হে মানুষ, তোমাদের মালিকের কাছ থেকে তোমাদের কাছে একটি উজ্জ্বল প্রমাণ এসেছে এবং আমি তোমাদের কাছে একটি উজ্জ্বল জ্যোতি নাযিল করেছি।', 'Ya ayyuha alnnasu qad jaakum burhanun min rabbikum waanzalna ilaykum nooran mubeenan', 1, NOW(), NOW()),
(4, 175, 'فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا', 'অতঃপর যারা (সে জ্যোতি দিয়ে) আল্লাহর ওপর ঈমান আনলো এবং তা শক্ত করে আঁকড়ে থাকলো, তিনি তাদের অচিরেই তাঁর অফুরন্ত দয়া ও অনুগ্রহে (জান্নাতে) প্রবেশ করাবেন এবং তিনি তাদের তার দিকে সঠিক পথে পরিচালিত করবেন।', 'Faamma allatheena amanoo biAllahi waiAAtasamoo bihi fasayudkhiluhum fee rahmatin minhu wafadlin wayahdeehim ilayhi siratan mustaqeeman', 1, NOW(), NOW()),
(4, 176, 'يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ', '(হে নবী,) তারা তোমার কাছে জানতে চায়; তুমি বলো, আল্লাহ তায়ালা সে ব্যক্তির (উত্তরাধিকার বিষয়ে) তোমাদের তাঁর সিদ্ধান্ত জানাচ্ছেন; যার মাতা পিতা কেউই নেই, আবার তার নিজেরও কোনো সন্তান নেই, (এ ধরনের) কোনো ব্যক্তি যদি মারা যায় এবং সে ব্যক্তি যদি সন্তানহীন হয় এবং তার একটি বোন থাকে, তাহলে সে বোনটির জন্যে (মৃত) ব্যক্তির পরিত্যক্ত সম্পত্তির অর্ধাংশ থাকবে, অপরদিকে সে যদি নিসন্তান হয়,তাহলে সে তার বোনের (সম্পত্তির) উত্তরাধিকারী হবে; (আবার) যদি তারা দুজন হয়, তাহলে তাদের দু বোনের জন্যে সেই পরিত্যক্ত সম্পত্তির তিন ভাগের দুই ভাগ পরিমাণ অংশ থাকবে; যদি সে ভাইবোন ও মহিলারা কয়েকজন হয়, তাহলে মেয়েদের অংশ এক ভাগ ও পুরুষদের অংশ দুই ভাগ হবে; আল্লাহ তায়ালা (উত্তরাধিকারের এ আইন) সুস্পষ্টভাবে তোমাদের জন্যে বলে দিয়েছেন, যাতে করে (মানুষের উদ্ভাবিত বন্টন পদ্ধতিতে) তোমরা বিভ্রান্ত হয়ে না পড়ো; আল্লাহ তায়ালা সব কিছুর ব্যাপারেই সম্যক ওয়াকেফহাল।', 'Yastaftoonaka quli Allahu yufteekum fee alkalalati ini imruon halaka laysa lahu waladun walahu okhtun falaha nisfu ma taraka wahuwa yarithuha in lam yakun laha waladun fain kanata ithnatayni falahuma alththuluthani mimma taraka wain kanoo ikhwatan rijalan wanisaan falilththakari mithlu haththi alonthayayni yubayyinu Allahu lakum an tadilloo waAllahu bikulli shayin AAaleemun', 1, NOW(), NOW()),
(5, 1, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَوۡفُواْ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِيمَةُ ٱلۡأَنۡعَٰمِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّي ٱلصَّيۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ يَحۡكُمُ مَا يُرِيدُ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো তোমরা ওয়াদাসমূহ পূরণ করো (মনে রেখো); তোমাদের জন্যে চার পা’বিশিষ্ট পোষা জন্তু হালাল করা হয়েছে, সেসব (জন্তু) ছাড়া, যা (বিবরণসহ) তোমাদের পড়ে শোনানো হচ্ছে, তবে এহরাম (বাঁধা অবস্থায় এসব জন্তু) শিকার করাও বৈধ নয়; অবশ্যই আল্লাহ তায়ালা যা চান সে আদেশই তিনি জারি করেন।', 'Ya ayyuha allatheena amanoo awfoo bialAAuqoodi ohillat lakum baheematu alanAAami illa ma yutla AAalaykum ghayra muhillee alssaydi waantum hurumun inna Allaha yahkumu ma yureedu', 1, NOW(), NOW()),
(5, 2, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'হে ঈমানদার বান্দারা, তোমরা আল্লাহ তায়ালার নিদর্শনসমূহের অসম্মান করো না, সম্মানিত মাসগুলোকে (যুদ্ধ-বিগ্রহের জন্যে) কখনো হালাল বানিয়ে নিয়ো না, (আল্লাহর নামে) উৎসর্গীকৃত জন্তুসমূহ ও যেসব জন্তুর গলায় (উৎসর্গের চিহ্ন হিসাবে) পট্টি বেঁধে দেয়া হয়েছে, যারা (আল্লাহর) অনুগ্রহ ও সন্তুষ্টি অর্জনের লক্ষ্যে (আল্লাহর) পবিত্র ঘর কাবার দিকে রওনা দিয়েছে (তাদেরও তোমরা অসম্মান করো না), তোমরা যখন এহরামমুক্ত হবে তখন তোমরা শিকার করতে পারো। (বিশেষ) কোনো সম্প্রদায়ের বিদ্বেষ- (এমন বিদ্বেষ যার কারণে) তারা তোমাদের (আল্লাহ তায়ালার) পবিত্র মাসজিদে আসার পথ বন্ধ করে দিয়েছিলো, যেন তোমাদের (কোনো রকম) সীমালংঘন করতে প্ররোচিত না করে, তোমরা নেক কাজ ও তাকওয়ার ব্যাপারে একে অপরের সহযোগিতা করো, পাপ ও বাড়াবাড়ির কাজে (কখনো) একে অপরের সহযোগিতা করো না, সর্বাবস্থায়ই আল্লাহ তায়ালাকে ভয় করো, কেননা আল্লাহ তায়ালা দন্ডদানের ব্যাপারে অত্যন্ত কঠোর!', 'Ya ayyuha allatheena amanoo la tuhilloo shaAAaira Allahi wala alshshahra alharama wala alhadya wala alqalaida wala ammeena albayta alharama yabtaghoona fadlan min rabbihim waridwanan waitha halaltum faistadoo wala yajrimannakum shanaanu qawmin an saddookum AAani almasjidi alharami an taAAtadoo wataAAawanoo AAala albirri waalttaqwa wala taAAawanoo AAala alithmi waalAAudwani waittaqoo Allaha inna Allaha shadeedu alAAiqabi', 1, NOW(), NOW()),
(5, 3, 'حُرِّمَتۡ عَلَيۡكُمُ ٱلۡمَيۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُواْ بِٱلۡأَزۡلَٰمِۚ ذَٰلِكُمۡ فِسۡقٌۗ ٱلۡيَوۡمَ يَئِسَ ٱلَّذِينَ كَفَرُواْ مِن دِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينٗاۚ فَمَنِ ٱضۡطُرَّ فِي مَخۡمَصَةٍ غَيۡرَ مُتَجَانِفٖ لِّإِثۡمٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'মৃত জন্তু, রক্ত, শুয়োরের গোশ্ত ও যে জন্তু আল্লাহ তায়ালা ছাড়া অন্য কারো নামে যবাই (কিংবা উৎসর্গ) করা হয়েছে, (তা) তোমাদের ওপর হারাম করা হয়েছে । শ্বাসরুদ্ধ হয়ে মরা, আঘাত খেয়ে মরা, ওপর থেকে পড়ে মরা, শিংয়ের আঘাতে মরা, হিংস্র জন্তুর খাওয়া জন্তুও (তোমাদের জন্যে হারাম), তবে তোমরা তা যদি (জীবিত অবস্থায় পেয়ে) যবাই করে থাকো (তাহলে তা হারাম নয়)। পূজার বেদীতে বলি দেয়া জন্তুও হারাম, (লটারি কিংবা) জুয়ার তীর নিক্ষেপ করে ভাগ্য নির্ণয় করা (হারাম), এর সব কয়টাই হচ্ছে বড়ো (বড়ো) গুনাহের কাজ, আজ কাফেররা তোমাদের দ্বীন (নির্মূল করা) সম্পর্কে হতাশ হয়ে পড়েছে, সুতরাং তোমরা তাদের ভয় করো না, বরং আমাকেই ভয় করো; আজ আমি তোমাদের জন্যে তোমাদের দ্বীন পরিপূর্ণ করে দিলাম, আর তোমাদের ওপর আমার (প্রতিশ্রুত) নেয়ামতও আমি পুরো করে দিলাম, তোমাদের জন্যে জীবন বিধান হিসাবে আমি ইসলামকেই পছন্দ করলাম । যদি কোনো ব্যক্তিকে ক্ষুধার তাড়নায় (হারাম খেতে) বাধ্য করা হয়, কিন্তু (ইচ্ছা করে) সে কোনো পাপের দিকে ঝুঁকে পড়তে না চায় (তার ব্যাপারে) অবশ্যই আল্লাহ তায়ালা ক্ষমাশীল পরম দয়ালু।', 'Hurrimat AAalaykumu almaytatu waalddamu walahmu alkhinzeeri wama ohilla lighayri Allahi bihi waalmunkhaniqatu waalmawqoothatu waalmutaraddiyatu waalnnateehatu wama akala alssabuAAu illa ma thakkaytum wama thubiha AAala alnnusubi waan tastaqsimoo bialazlami thalikum fisqun alyawma yaisa allatheena kafaroo min deenikum fala takhshawhum waikhshawni alyawma akmaltu lakum deenakum waatmamtu AAalaykum niAAmatee waradeetu lakumu alislama deenan famani idturra fee makhmasatin ghayra mutajanifin liithmin fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(5, 4, 'يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', 'তারা তোমার কাছ থেকে জানতে চায় কোন্ কোন্ জিনিস তাদের জন্যে হালাল করা হয়েছে? তুমি বলো, সব ধরনের পাক-সাফ বস্তুই (তোমাদের জন্যে) হালাল করা হয়েছে এবং সেসব শিকারী (জন্তু ও পাখীর) ধরে আনা (শিকার) তোমরা খাও, যাদের তোমরা (শিকার করার নিয়ম) শিক্ষা দিয়েছো, যেভাবে আল্লাহ তায়ালা তোমাদের শিক্ষা দিয়েছিলেন, (তবে) এর ওপর অবশ্যই আল্লাহ তায়ালার নাম নেবে, তোমরা আল্লাহ তায়ালাকেই ভয় করো; অবশ্যই আল্লাহ তায়ালা দ্রুত হিসাব গ্রহণকারী।', 'Yasaloonaka matha ohilla lahum qul ohilla lakumu alttayyibatu wama AAallamtum mina aljawarihi mukallibeena tuAAallimoonahunna mimma AAallamakumu Allahu fakuloo mimma amsakna AAalaykum waothkuroo isma Allahi AAalayhi waittaqoo Allaha inna Allaha sareeAAu alhisabi', 1, NOW(), NOW()),
(5, 5, 'ٱلۡيَوۡمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُۖ وَطَعَامُ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حِلّٞ لَّكُمۡ وَطَعَامُكُمۡ حِلّٞ لَّهُمۡۖ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلۡمُؤۡمِنَٰتِ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِيٓ أَخۡدَانٖۗ وَمَن يَكۡفُرۡ بِٱلۡإِيمَٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ', 'আজ তোমাদের জন্যে যাবতীয় পাক জিনিস হালাল করা হলো; যাদের ওপর (আল্লাহর) কিতাব নাযিল করা হয়েছে তাদের খাবারও তোমাদের জন্যে হালাল, আবার তোমাদের খাদ্যদ্রব্যও তাদের জন্যে হালাল। (বিয়ের) দুর্গে অবস্থানকারী মুমীন নারী ও তোমাদের আগে যাদের কিতাব দেয়া হয়েছিলো- যখন তোমরা (তাদের) মোহরানা আদায় করে দিবে, সেসব (আহলে কিতাব) সতী সাধ্বী নারীরাও (তখন তোমাদের জন্যে হালাল হয়ে যাবে), তোমরা (থাকবে চরিত্রের) রক্ষক হয়ে, কামনা চরিতার্থকারী কিংবা গোপন অভিসারী হয়ে নয়; যে কেউই ঈমান অস্বীকার করবে, তার (জীবনের সব) কর্মই নিষ্ফল হয়ে যাবে এবং শেষ বিচারের দিনে সে হবে (চরমভাবে) ক্ষতিগ্রস্তদের একজন।', 'Alyawma ohilla lakumu alttayyibatu wataAAamu allatheena ootoo alkitaba hillun lakum wataAAamukum hillun lahum waalmuhsanatu mina almuminati waalmuhsanatu mina allatheena ootoo alkitaba min qablikum itha ataytumoohunna ojoorahunna muhsineena ghayra musafiheena wala muttakhithee akhdanin waman yakfur bialeemani faqad habita AAamaluhu wahuwa fee alakhirati mina alkhasireena', 1, NOW(), NOW()),
(5, 6, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُواْ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَيۡنِۚ وَإِن كُنتُمۡ جُنُبٗا فَٱطَّهَّرُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُم مِّنۡهُۚ مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', 'হে ঈমানদার ব্যক্তিরা, তোমরা যখন নামাযের জন্যে দাঁড়াবে- তখন (ওযু করবে, আর ওযুর নিয়ম হচ্ছে) তোমরা তোমাদের মুখমন্ডল ও কনুই পর্যন্ত তোমাদের হাত দুটো ধুয়ে নেবে, অতঃপর তোমাদের মাথা মাসেহ করবে এবং পা দুটো গোড়ালি পর্যন্ত (ধুয়ে নেবে,) কখনো যদি (এমন বেশী) নাপাক হয়ে যাও, তাহলে (গোসল করে) পবিত্র হয়ে নেবে, যদি তোমরা অসুস্থ হয়ে পড়ো কিংবা তোমরা যদি সফরে থাকো, অথবা তোমাদের কেউ যদি মলমূত্র ত্যাগ করে আসে অথবা যদি নারী সম্ভোগ করে থাকো (তাহলে পানি দিয়ে পবিত্রতা অর্জন করো), আর যদি পানি না পাও তাহলে পবিত্র মাটি দিয়ে তায়াম্মুম করে নাও, (আর তায়াম্মুমের নিয়ম হচ্ছে, পবিত্র) মাটি দিয়ে তোমরা তোমাদের মুখমন্ডল ও হাত মাসেহ করে নেবে; (মূলত) আল্লাহ তায়ালা এটা চান না যে, তোমাদের ওপর তিনি কোনো কষ্ট পৌঁছাবেন; বরং তিনি চান তোমাদের পাক-সাফ করে দিতে এবং (এভাবেই) তিনি তোমাদের ওপর তাঁর নেয়ামতসমূহ পূর্ণ করে দিতে চান, আশা করা যায় তোমরা তাঁর কৃতজ্ঞতা আদায় করবে।', 'Ya ayyuha allatheena amanoo itha qumtum ila alssalati faighsiloo wujoohakum waaydiyakum ila almarafiqi waimsahoo biruoosikum waarjulakum ila alkaAAbayni wain kuntum junuban faittahharoo wain kuntum marda aw AAala safarin aw jaa ahadun minkum mina alghaiti aw lamastumu alnnisaa falam tajidoo maan fatayammamoo saAAeedan tayyiban faimsahoo biwujoohikum waaydeekum minhu ma yureedu Allahu liyajAAala AAalaykum min harajin walakin yureedu liyutahhirakum waliyutimma niAAmatahu AAalaykum laAAallakum tashkuroona', 1, NOW(), NOW()),
(5, 7, 'وَٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ وَمِيثَٰقَهُ ٱلَّذِي وَاثَقَكُم بِهِۦٓ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'তোমরা তোমাদের ওপর আল্লাহ তায়ালার নেয়ামতসমূহ স্মরণ করো এবং তোমাদের কাছ থেকে যে পাকা প্রতিশ্রুতি তিনি গ্রহণ করেছিলেন (সে কথাও স্মরণ করো), যখন তোমরা বলেছিলে (হে আমাদের রব), আমরা (তোমার কথা) শুনলাম এবং (তা) মেনে নিলাম, তোমরা আল্লাহ তায়ালাকে ভয় করো, অবশ্যই আল্লাহ তায়ালা তোমাদের অন্তরে যা কিছু আছে সে সম্পর্কে সম্যক অবগত আছেন।', 'Waothkuroo niAAmata Allahi AAalaykum wameethaqahu allathee wathaqakum bihi ith qultum samiAAna waataAAna waittaqoo Allaha inna Allaha AAaleemun bithati alssudoori', 1, NOW(), NOW()),
(5, 8, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ', 'হে ঈমানদার লোকেরা, তোমরা আল্লাহর জন্যে (সত্য ও) ন্যায়ের ওপর সাক্ষী হয়ে অবিচলভাবে দাঁড়িয়ে থাকো, (বিশেষ) কোনো সম্প্রদায়ের দুশমনী যেন তোমাদের এমনভাবে প্ররোচিত না করে যে, (এর ফলে) তোমরা (আর তাদের সাথে) ন্যায় ও ইনসাফ করবে না, তোমরা ইনসাফ করো । কারণ এ (কাজ)-টি (আল্লাহ তায়ালাকে) ভয় করে চলার অধিক নিকটতর; তোমরা আল্লাহ তায়ালাকে ভয় করো; অবশ্যই আল্লাহ তায়ালা তোমাদের কর্মকান্ড সম্পর্কে পূর্ণাংগ ওয়াকেফহাল।', 'Ya ayyuha allatheena amanoo koonoo qawwameena lillahi shuhadaa bialqisti wala yajrimannakum shanaanu qawmin AAala alla taAAdiloo iAAdiloo huwa aqrabu lilttaqwa waittaqoo Allaha inna Allaha khabeerun bima taAAmaloona', 1, NOW(), NOW()),
(5, 9, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ', 'যারা ঈমান আনে এবং নেক কাজ করে, আল্লাহ তায়ালা তাদের সবাইকে প্রতিশ্রুতি দিয়েছেন, তাদের জন্যে (তাঁর কাছে বিশেষ) ক্ষমা ও বড়ো পুরস্কার রয়েছে।', 'WaAAada Allahu allatheena amanoo waAAamiloo alssalihati lahum maghfiratun waajrun AAatheemun', 1, NOW(), NOW()),
(5, 10, 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', '(অপরদিকে) যারা কুফরী করেছে এবং আমার আয়াতসমূহকে অস্বীকার করেছে, তারাই হচ্ছে এমন- যারা জাহান্নামের অধিবাসী।', 'Waallatheena kafaroo wakaththaboo biayatina olaika ashabu aljaheemi', 1, NOW(), NOW()),
(5, 11, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', 'হে ঈমানদার ব্যক্তিরা, তোমাদের ওপর আল্লাহর নেয়ামত স্মরণ করো, যখন একটি জনগোষ্ঠী তোমাদের বিরুদ্ধে হাত ওঠাতে উদ্যত হয়েছিলো, তখন আল্লাহ তায়ালা তাদের সে হাতগুলোকে তোমাদের ওপর (আক্রমণ করা) থেকে বিরত রাখলেন, তোমরা আল্লাহ তায়ালাকে ভয় করো, মুমীনদের তো আল্লাহ তায়ালার ওপরই ভরসা করা উচিত।', 'Ya ayyuha allatheena amanoo othkuroo niAAmata Allahi AAalaykum ith hamma qawmun an yabsutoo ilaykum aydiyahum fakaffa aydiyahum AAankum waittaqoo Allaha waAAala Allahi falyatawakkali almuminoona', 1, NOW(), NOW()),
(5, 12, '۞وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'আল্লাহ তায়ালা বনী ইসরাঈলদের (আনুগত্যের) অঙ্গীকার গ্রহণ করলেন, অতঃপর আমি (এ জন্যে) তাদের মধ্য থেকে বারো জন সর্দার পাঠালাম; আল্লাহ তায়ালা তাদের বললেন, অবশ্যই আমি তোমাদের সাথে আছি, তোমরা যদি নামায প্রতিষ্ঠা করো, যাকাত আদায় করো, ঈমান আনো আমার রাসূলদের ওপর এবং (যদি) তোমরা তাদের সাহায্য সহযোগিতা করো, (সর্বোপরি) আল্লাহ তায়ালাকে তোমরা যদি উত্তম ঋণ প্রদান করো, তাহলে অবশ্যই আমি তোমাদের (হিসাব) থেকে (তোমাদের) গুনাহসমূহ মোচন করে দিবো এবং অবশ্যই আমি তোমাদের এমন এক জান্নাতে প্রবেশ করাবো যার তলদেশ দিয়ে ঝর্ণাধারা প্রবাহিত, এরপর যদি তোমাদের কোনো ব্যক্তি কুফুরী করে, তাহলে সে সরল পথ থেকে অনেক বিচ্যুত হয়ে পড়বে।', 'Walaqad akhatha Allahu meethaqa banee israeela wabaAAathna minhumu ithnay AAashara naqeeban waqala Allahu innee maAAakum lain aqamtumu alssalata waataytumu alzzakata waamantum birusulee waAAazzartumoohum waaqradtumu Allaha qardan hasanan laokaffiranna AAankum sayyiatikum walaodkhilannakum jannatin tajree min tahtiha alanharu faman kafara baAAda thalika minkum faqad dalla sawaa alssabeeli', 1, NOW(), NOW()),
(5, 13, 'فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ', '(অতঃপর) তাদের সেই অঙ্গীকার ভংগ করার কারণে আমি তাদের ওপর অভিশাপ নাযিল করেছি এবং তাদের হৃদয়কে কঠিন বানিয়ে দিয়েছি (তাদের চরিত্র ছিলো), তারা (আল্লাহর) কথাগুলোকে তার নির্দিষ্ট অর্থ থেকে সরিয়ে নিয়ে বিকৃত করে দিতো, (হেদায়াতের) যা কিছু তাদের শিক্ষা দেয়া হয়েছিলো তার অধিকাংশ কথাই তারা ভুলে গেলো; তুমি তাদের দেখতে পাবে, তাদের সামান্য একটি অংশ ছাড়া অধিকাংশ মানুষই (আল্লাহর সাথে) বিশ্বাসঘাতকতা করে চলেছে, তুমি তাদের ক্ষমা করে দাও, (যথাসম্ভব) তুমি তাদের (কার্যকলাপ) মার্জনা করো; অবশ্যই আল্লাহ তায়ালা কল্যাণকামী মানুষদের ভালোবাসেন।', 'Fabima naqdihim meethaqahum laAAannahum wajaAAalna quloobahum qasiyatan yuharrifoona alkalima AAan mawadiAAihi wanasoo haththan mimma thukkiroo bihi wala tazalu tattaliAAu AAala khainatin minhum illa qaleelan minhum faoAAfu AAanhum waisfah inna Allaha yuhibbu almuhsineena', 1, NOW(), NOW()),
(5, 14, 'وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ', 'আমি তো তাদের (কাছ থেকেও আনুগত্যের) অঙ্গীকার গ্রহণ করেছিলাম, যারা বলে আমরা হচ্ছি খৃস্টান, অতঃপর এরাও (অঙ্গীকারের) অধিকাংশ কথা ভুলে গেলো, যা তাদের স্মরণ করানো হয়েছিলো, অতঃপর আমি তাদের মধ্যে কেয়ামত পর্যন্ত (স্থায়ী) শত্রুতা ও বিদ্বেষের বীজ বপন করে দিলাম; (দুনিয়ার জীবনে) তারা যা কিছু উদ্ভাবন করতো অচিরেই আল্লাহ তায়ালা তাদের তা বলে দিবেন।', 'Wamina allatheena qaloo inna nasara akhathna meethaqahum fanasoo haththan mimma thukkiroo bihi faaghrayna baynahumu alAAadawata waalbaghdaa ila yawmi alqiyamati wasawfa yunabbiohumu Allahu bima kanoo yasnaAAoona', 1, NOW(), NOW()),
(5, 15, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ', 'হে আহলে কিতাবরা, তোমাদের কাছে আমার ( পক্ষ থেকে) রাসূল এসেছে, (আগের) কিতাবের যা কিছু তোমরা এতোদিন গোপন করে রেখেছিলে তার বহু কিছুই সে তোমাদের স্পষ্ট করে বলে দিচ্ছে, আবার অনেক কিছু সে এড়িয়েও যাচ্ছে; তোমাদের কাছে (এখন) তো আল্লাহর পক্ষ থেকে আলোকবর্তিকা এবং সুস্পষ্ট কিতাবও এসে গেছে।', 'Ya ahla alkitabi qad jaakum rasooluna yubayyinu lakum katheeran mimma kuntum tukhfoona mina alkitabi wayaAAfoo AAan katheerin qad jaakum mina Allahi noorun wakitabun mubeenun', 1, NOW(), NOW()),
(5, 16, 'يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'এর দ্বারা আল্লাহ তায়ালা তাকে শান্তি ও নিরাপত্তার পথ বাতলে দেন, যে ব্যক্তি আনুগত্য করে তাঁর সন্তুষ্টি লাভ করতে চায়, অতঃপর তিনি তাঁর অনুমতিক্রমে তাদের (জাহেলিয়াতের) অন্ধকার থেকে (ঈমানের) আলোতে বের করে আনেন, আর (এভাবেই) তাদের তিনি সঠিক পথে পরিচালিত করেন।', 'Yahdee bihi Allahu mani ittabaAAa ridwanahu subula alssalami wayukhrijuhum mina alththulumati ila alnnoori biithnihi wayahdeehim ila siratin mustaqeemin', 1, NOW(), NOW()),
(5, 17, 'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'নিশ্চয়ই তারা কুফরী করেছে, যারা বলেছে, অবশ্যই মারইয়ামের পুত্র মাসীহই আল্লাহ; (হে মুহাম্মদ, তুমি তাদের বলো, আল্লাহ তায়ালা যদি মারইয়াম পুত্র মাসীহ, তার মা ও গোটা বিশ্ব-চরাচরে যা কিছু আছে- সব কিছুও ধ্বংস করে দিতে চান, এমন কে আছে যে আল্লাহ তায়ালার কাছ থেকে এদের রক্ষা করতে পারে? এই আকাশমালা, ভূমন্ডল ও এর মধ্যবর্তী স্থানে যা কিছু আছে, তার সার্বভৌমত্ব আল্লাহ তায়ালার জন্যেই (নির্দিষ্ট); তিনি যা ইচ্ছা তাই সৃষ্টি করেন; আল্লাহ তায়ালা সকল বিষয়ের ওপর একক ক্ষমতাবান।', 'Laqad kafara allatheena qaloo inna Allaha huwa almaseehu ibnu maryama qul faman yamliku mina Allahi shayan in arada an yuhlika almaseeha ibna maryama waommahu waman fee alardi jameeAAan walillahi mulku alssamawati waalardi wama baynahuma yakhluqu ma yashao waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(5, 18, 'وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَـٰٓؤُاْ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ', 'ইহুদী ও খৃস্টানরা বলে, আমরা আল্লাহর সন্তান এবং তাঁর প্রিয়পাত্র; তুমি (তাদের) বলো, তাহলে তিনি তোমাদের গুনাহের জন্যে তোমাদের দন্ড প্রদান করবেন কেন; (মূলত) তোমরা (সবাই তাদেরই অন্তর্ভুক্ত কতিপয় ) মানুষ, যাদের আল্লাহ তায়ালা সৃষ্টি করেছেন, তিনি তাঁর বান্দাদের যাকে ইচ্ছা ক্ষমা করে দেন, আবার যাকে ইচ্ছা তিনি শাস্তি প্রদান করেন; আসমানসমূহ ও যমীনের মধ্যবর্তী সব কিছুর একক মালিকানা আল্লাহ তায়ালার জন্যেই (নির্দিষ্ট), তাঁর কাছেই হচ্ছে সবার ফিরে যাওয়ার জায়গা।', 'Waqalati alyahoodu waalnnasara nahnu abnao Allahi waahibbaohu qul falima yuAAaththibukum bithunoobikum bal antum basharun mimman khalaqa yaghfiru liman yashao wayuAAaththibu man yashao walillahi mulku alssamawati waalardi wama baynahuma wailayhi almaseeru', 1, NOW(), NOW()),
(5, 19, 'يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'হে আহলে কিতাবরা, রাসূলদের (আগমন ধারার দীর্ঘ বিরতির পর আমার (পক্ষ থেকে) তোমাদের কাছে একজন রাসূল এসেছে, সে তোমাদের জন্যে (আমার কথাগুলোকে) সুস্পষ্টভাবে বর্ণনা করছে, যাতে করে তোমরা (শেষ বিচারের দিন) একথা বলতে না পারো যে, আমাদের কাছে (জান্নাতের) সুসংবাদ বহনকারী ও (জাহান্নামের) সতর্ককারী (হিসেবে) কেউই তো আগমন করেনি, হ্যাঁ, আজ তো সত্যি সত্যিই) তোমাদের কাছে সুসংবাদবাহী ও সতর্ককারী (একজন রাসূল) এসে গেছে, বস্তুত আল্লাহ তায়ালা সর্ববিষয়ে শক্তিমান।', 'Ya ahla alkitabi qad jaakum rasooluna yubayyinu lakum AAala fatratin mina alrrusuli an taqooloo ma jaana min basheerin wala natheerin faqad jaakum basheerun wanatheerun waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(5, 20, 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ', 'যখন মূসা তার জাতিকে বলেছিলো, হে আমার সম্প্রদায়ের লোকেরা, আল্লাহ তায়ালা তোমাদের ওপর যে নেয়ামত নাযিল করেছেন তা তোমরা স্মরণ করো, (সে নেয়ামতের কথাও স্মরণ করো) যখন তিনি তোমাদের মাঝে বহু নবী পয়দা করেছেন, তিনি তোমাদের (এ যমীনের) শাসনকর্তা বানিয়েছেন, এছাড়াও তিনি তোমাদের এমন সব নেয়ামত দান করেছেন যা তিনি সৃষ্টিকুলের আর কাউকে দান করেননি।', 'Waith qala moosa liqawmihi ya qawmi othkuroo niAAmata Allahi AAalaykum ith jaAAala feekum anbiyaa wajaAAalakum mulookan waatakum ma lam yuti ahadan mina alAAalameena', 1, NOW(), NOW()),
(5, 21, 'يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ', 'হে আমার জাতি, আল্লাহ তায়ালা তোমাদের জন্যে যে পবিত্র ভূখন্ড লিখে রেখেছেন তোমরা তাতে প্রবেশ করো এবং (এ অভিযানে) কখনো পশ্চাদপসরণ করো না; তারপরও তোমরা যদি ফিরে আসো তাহলে ভীষণ ক্ষতিগ্রস্ত হবে।', 'Ya qawmi odkhuloo alarda almuqaddasata allatee kataba Allahu lakum wala tartaddoo AAala adbarikum fatanqaliboo khasireena', 1, NOW(), NOW()),
(5, 22, 'قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ', 'তারা বললো, হে মূসা, সেখানে (তো) এক দোর্দন্ড প্রতাপশালী সম্প্রদায় রয়েছে, তারা সেখান থেকে বেরিয়ে না আসা পর্যন্ত আমরা কিছুতেই সেখানে প্রবেশ করবো না, (হ্যাঁ) তারা সেখান থেকে বেরিয়ে এলে আমরা অবশ্যই (সেখানে) প্রবেশ করবো।', 'Qaloo ya moosa inna feeha qawman jabbareena wainna lan nadkhulaha hatta yakhrujoo minha fain yakhrujoo minha fainna dakhiloona', 1, NOW(), NOW()),
(5, 23, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ', 'তাদের দুজন লোক, যারা (আল্লাহ তায়ালাকে ভয় করছিলো, যাদের ওপর আল্লাহ তায়ালা অনুগ্রহ করেছিলেন- তারা (এগিয়ে এসে) বললো, তোমরা (সদর) দরজা দিয়েই সেখানে প্রবেশ করো, আর (একবার) সেখানে প্রবেশ করলেই তোমরা বিজয়ী হবে, তোমরা যদি (সত্যিকার অর্থে) মুমীন হও তাহলে আল্লাহর ওপরই ভরসা করো।', 'Qala rajulani mina allatheena yakhafoona anAAama Allahu AAalayhima odkhuloo AAalayhimu albaba faitha dakhaltumoohu fainnakum ghaliboona waAAala Allahi fatawakkaloo in kuntum mumineena', 1, NOW(), NOW()),
(5, 24, 'قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', 'তারা বললো, হে মূসা, সেই (শক্তিশালী) লোকেরা যতোক্ষণ সেখানে থাকবে, ততোক্ষণ আমরা কখনো সেখানে প্রবেশ করবো না, তুমিই (বরং) যাও, তুমি ও তোমার রব- উভয়ে মিলে যুদ্ধ করো, আমরা এখানেই বসে রইলাম।', 'Qaloo ya moosa inna lan nadkhulaha abadan ma damoo feeha faithhab anta warabbuka faqatila inna hahuna qaAAidoona', 1, NOW(), NOW()),
(5, 25, 'قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ', 'মূসা বললো, হে আমার রব, (তুমি জানো) আমার নিজের এবং আমার ভাই ছাড়া আর কারো ওপর আমার আধিপত্য নেই, অতএব আমাদের ও এই নাফরমান লোকদের মাঝে তুমি একটা মীমাংসা করে দাও।', 'Qala rabbi innee la amliku illa nafsee waakhee faofruq baynana wabayna alqawmi alfasiqeena', 1, NOW(), NOW()),
(5, 26, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ', 'আল্লাহ তায়ালা বললেন, (হ্যাঁ, আগামী) চল্লিশ বছর অবশ্যই সে (জনপদ)টি তাদের জন্যে নিষিদ্ধ করে দেয়া হলো, (এ সময়ে) তারা উদ্ভ্রান্ত হয়ে পৃথিবীতে ঘুরে বেড়াবে; সুতরাং তুমি এই না-ফরমান লোকদের ওপর কখনো দুঃখ করো না।', 'Qala fainnaha muharramatun AAalayhim arbaAAeena sanatan yateehoona fee alardi fala tasa AAala alqawmi alfasiqeena', 1, NOW(), NOW()),
(5, 27, '۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ', '(হে মুহাম্মদ,) তুমি এদের কাছে আদমের দুই পুত্রের গল্প যথাযথভাবে শুনিয়ে দাও! (গল্পটি ছিলো এই,) যখন তারা দুই জন (আল্লাহর নামে) কোরবানী পেশ করলো, তখন তাদের মধ্যে একজনের কাছ থেকে কোরবানী কবুল করা হলো, আরেকজনের কাছ থেকে কবুলই করা হলো না, (যার কোরবানী কবুল করা হয়নি) সে বললো, আমি অবশ্যই তোমাকে হত্যা করবো, (যার কোরবানী কবুল করা হলো), সে বললো, আল্লাহ তায়ালা শুধু মোত্তাকীদের কাছ থেকেই (কোরবানী) কবুল করেন,', 'Waotlu AAalayhim nabaa ibnay adama bialhaqqi ith qarraba qurbanan fatuqubbila min ahadihima walam yutaqabbal mina alakhari qala laaqtulannaka qala innama yataqabbalu Allahu mina almuttaqeena', 1, NOW(), NOW()),
(5, 28, 'لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ', '(হিংসার বশবর্তী হয়ে) তুমি যদি আজ আমাকে হত্যা করার জন্যে আমার দিকে তোমার হাত বাড়াও, তাহলে (মনে রেখো) আমি (কিন্তু) তোমাকে হত্যা করার জন্যে তোমার প্রতি আমার হাত বাড়াবো না, অবশ্যই আমি সৃষ্টিকুলের মালিক আল্লাহকে ভয় করি।', 'Lain basatta ilayya yadaka litaqtulanee ma ana bibasitin yadiya ilayka liaqtulaka innee akhafu Allaha rabba alAAalameena', 1, NOW(), NOW()),
(5, 29, 'إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ', 'আমি (বরং) চাইবো, তুমি আমার গুনাহ ও তোমার গুনাহর (বোঝা) একাই তোমার (মাথার) ওপর উঠিয়ে নাও এবং (এভাবেই) তুমি জাহান্নামের অধিবাসী হয়ে পড়ো, (মূলত) এটাই হচ্ছে যালিমদের (যথার্থ) কর্মফল।', 'Innee oreedu an tabooa biithmee waithmika fatakoona min ashabi alnnari wathalika jazao alththalimeena', 1, NOW(), NOW()),
(5, 30, 'فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ', 'অতঃপর তার কুপ্রবৃত্তি তাকে নিজ ভাইয়ের হত্যার কাজে উস্কানি দিলো, একপর্যায়ে সে তাকে খুন করে ফেললো এবং (এ কাজের ফলে) সে ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে গেলো।', 'FatawwaAAat lahu nafsuhu qatla akheehi faqatalahu faasbaha mina alkhasireena', 1, NOW(), NOW()),
(5, 31, 'فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ', 'অতঃপর আল্লাহ তায়ালা (সেখানে) একটি কাক পাঠালেন, কাকটি (হত্যাকারীর সামনে এসে) মাটি খুঁড়তে লাগলো, উদ্দেশ্য, তাকে দেখানো কিভাবে সে তার ভাইয়ের লাশ লুকিয়ে রাখবে; (এটা দেখে) সে (নিজে নিজে) বলতে লাগলো, হায়! আমি তো এই কাকটির চাইতেও অক্ষম হয়ে পড়েছি যে, আমি আমার ভাইয়ের লাশটা গোপন করবো, অতঃপর সে সত্যি সত্যিই (নিজের কৃতকর্মের জন্যে) অনুতপ্ত হলো।', 'FabaAAatha Allahu ghuraban yabhathu fee alardi liyuriyahu kayfa yuwaree sawata akheehi qala ya waylata aAAajaztu an akoona mithla hatha alghurabi faowariya sawata akhee faasbaha mina alnnadimeena', 1, NOW(), NOW()),
(5, 32, 'مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ', 'ওই (ঘটনার) কারণেই (পরবর্তীকালে) আমি বনী ইসরাঈলদের জন্যে এই বিধান জারি করলাম, কোনো মানুষকে হত্যা করা কিংবা পৃথিবীতে ধ্বংসাত্মক কাজ (করার শাস্তি প্রদান) ছাড়া (অন্য কোনো কারণে) কেউ যদি কাউকে হত্যা করে, সে যেন গোটা মানব জাতিকেই হত্যা করলো; (আবার এমনিভাবে) যদি কেউ একজনের প্রাণ রক্ষা করে তবে সে যেন গোটা মানব জাতিকেই বাঁচিয়ে দিলো; এদের কাছে আমার রাসূলরা সুস্পষ্ট নিদর্শন নিয়ে এসেছিলো, তারপরও এদের অধিকাংশ লোক এ যমীনের বুকে সীমালংঘনকারী (হিসেবেই) থেকে গেলো।', 'Min ajli thalika katabna AAala banee israeela annahu man qatala nafsan bighayri nafsin aw fasadin fee alardi fakaannama qatala alnnasa jameeAAan waman ahyaha fakaannama ahya alnnasa jameeAAan walaqad jaa thum rusuluna bialbayyinati thumma inna katheeran minhum baAAda thalika fee alardi lamusrifoona', 1, NOW(), NOW()),
(5, 33, 'إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ', 'যারা আল্লাহ তায়ালা ও তাঁর রাসূলের বিরুদ্ধে যুদ্ধ করে এবং (আল্লাহর) যমীনে বিপর্যয় সৃষ্টির অপচেষ্টা করে, তাদের শাস্তি হচ্ছে, তাদের হত্যা করা হবে কিংবা তাদের শূলবিদ্ধ করা হবে, অথবা বিপরীত দিক থেকে তাদের হাত-পা কেটে ফেলা হবে, কিংবা দেশ থেকে তাদের নির্বাসিত করা হবে; এই অপমানজনক শাস্তি হচ্ছে তাদের দুনিয়ার (জীবনের) জন্যে, পরকালে তাদের জন্যে ভয়াবহ আযাব তো রয়েছেই।', 'Innama jazao allatheena yuhariboona Allaha warasoolahu wayasAAawna fee alardi fasadan an yuqattaloo aw yusallaboo aw tuqattaAAa aydeehim waarjuluhum min khilafin aw yunfaw mina alardi thalika lahum khizyun fee alddunya walahum fee alakhirati AAathabun AAatheemun', 1, NOW(), NOW()),
(5, 34, 'إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'তবে (এটা তাদের জন্যে নয়,) যাদের ওপর তোমাদের আধিপত্য স্থাপিত হবার আগেই তারা তাওবা করেছে, তোমরা জেনে রেখো, আল্লাহ তায়ালা একান্ত ক্ষমাশীল, পরম করুণাময়।', 'Illa allatheena taboo min qabli an taqdiroo AAalayhim faiAAlamoo anna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(5, 35, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো, আল্লাহ তায়ালাকে ভয় করো এবং তাঁর দিকে (এগিয়ে যাওয়ার) উপায় খুঁজতে থাকো (তার দিকে এগুনোর বড়ো একটি উপায় হচ্ছে), তোমরা তাঁর পথে জেহাদ করো, আশা করা যায় তোমরা সফলকাম হতে পারবে।', 'Ya ayyuha allatheena amanoo ittaqoo Allaha waibtaghoo ilayhi alwaseelata wajahidoo fee sabeelihi laAAallakum tuflihoona', 1, NOW(), NOW()),
(5, 36, 'إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'অবশ্যই যারা ঈমান আনতে অস্বীকার করেছে, (কেয়ামতের দিন) পৃথিবীর সমুদয় ধন-দৌলতও যদি তাদের করায়ত্ত থাকে-(তার সাথে আরো) যদি সমপরিমাণ সম্পদ তাদের কাছে থাকে, (এ সমূদয় সম্পদকে) মুক্তিপণ হিসেবে দান করেও যদি তারা কেয়ামতের দিন জাহান্নামের আযাব থেকে মুক্তি পেতে চায় (তাও সম্ভব হবে না), তাদের কাছ থেকে (এর কিছুই সেদিন) গ্রহণ করা হবে না, তাদের জন্যে (সেদিন) কঠোর আযাব নির্ধারিত থাকবে।', 'Inna allatheena kafaroo law anna lahum ma fee alardi jameeAAan wamithlahu maAAahu liyaftadoo bihi min AAathabi yawmi alqiyamati ma tuqubbila minhum walahum AAathabun aleemun', 1, NOW(), NOW()),
(5, 37, 'يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ', 'তারা (সেদিন বারবার) দোযখের আগুন থেকে বেরিয়ে আসতে চাইবে, কিন্তু (কিছুতেই) তারা সেখান থেকে বেরিয়ে আসতে পারবে না, তাদের জন্যে স্থায়ী আযাব নির্দিষ্ট হয়ে আছে।', 'Yureedoona an yakhrujoo mina alnnari wama hum bikharijeena minha walahum AAathabun muqeemun', 1, NOW(), NOW()),
(5, 38, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ', 'পুরুষ ও নারী- এদের যে কেউই চুরি করবে, তাদের উভয়ের হাত কেটে ফেলো, এটা তাদেরই কৰ্মফল, (এটা) আল্লাহর পক্ষ থেকে (একটি শিক্ষণীয়) নির্ধারিত দন্ড; আল্লাহ তায়ালা মহাশক্তিশালী, প্রবল প্রজ্ঞাময়।', 'Waalssariqu waalssariqatu faiqtaAAoo aydiyahuma jazaan bima kasaba nakalan mina Allahi waAllahu AAazeezun hakeemun', 1, NOW(), NOW()),
(5, 39, 'فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', 'যে ব্যক্তি তার যুলুমের পর (আল্লাহ তায়ালার কাছে) তাওবা করবে এবং (নিজের) সংশোধন করে নেবে, অবশ্যই আল্লাহ তায়ালা তার প্রতি দয়াপরবশ হবেন; নিসন্দেহে আল্লাহ তায়ালা বড়ো ক্ষমাশীল, দয়াময়।', 'Faman taba min baAAdi thulmihi waaslaha fainna Allaha yatoobu AAalayhi inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(5, 40, 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'তুমি কি জানো না, এই আকাশমন্ডলী ও যমীনের একক সার্বভৌমত্ব একমাত্র আল্লাহ তায়ালার জন্যে; যাকে ইচ্ছা তাকে তিনি শাস্তি দেন, (আবার) যাকে ইচ্ছা তাকে তিনি মাফ করে দেন; আল্লাহ তায়ালা সব কিছুর ওপর একক ক্ষমতাবান।', 'Alam taAAlam anna Allaha lahu mulku alssamawati waalardi yuAAaththibu man yashao wayaghfiru liman yashao waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(5, 41, '۞يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ', 'হে রাসূল, যারা দ্রুতগতিতে কুফরীর পথে ধাবিত হচ্ছে, (তাদের) এই বিষয়টি যেন তোমাকে দুঃখ না দেয়, এরা সে দলের (লোক) যারা মুখে বলে, আমরা ঈমান এনেছি, কিন্তু (সত্যিকার অর্থে) তাদের অন্তর কখনো ঈমান আনেনি, (অপর দিকে) যারা ইহুদী- তারাও মিথ্যা কথা শোনার জন্যে (সদা) কান খাড়া করে রাখে এবং (তাদের বন্ধু সম্প্রদায়ের) যেসব লোক কখনো তোমার কাছে আসেনি, এরা সে অপর সম্প্রদায়টির জন্যেই নিজে দের কান খাড়া করে রাখে; তারা (আল্লাহর কিতাবের) কথাগুলো আপন জায়গায় (বিন্যস্ত) থাকার পরেও তাকে বিকৃত করে এবং (অন্যদের কাছে) বলে, (হ্যাঁ) যদি এ (ধরনের বিধান) তোমাদের দেয়া হয় তাহলে তোমরা তা গ্রহণ করো, আর তা দেয়া না হলে তোমরা সতর্ক থেকো; (আসলে) আল্লাহ তায়ালা যার পথচ্যুতি চান, তাকে আল্লাহর (পাকড়াও) থেকে বাঁচানোর জন্যে তুমি কিছুই করতে পারো না; এরাই হচ্ছে সেসব (হতভাগ্য) লোক, আল্লাহ তায়ালা যাদের অন্তরগুলোকে কখনো পাক-সাফ করার এরাদা পোষণ করেন না, তাদের জন্যে পৃথিবীতে রয়েছে অপমান ও লাঞ্ছনা, পরকালেও তাদের জন্যে ভয়াবহ আযাব রয়েছে।', 'Ya ayyuha alrrasoolu la yahzunka allatheena yusariAAoona fee alkufri mina allatheena qaloo amanna biafwahihim walam tumin quloobuhum wamina allatheena hadoo sammaAAoona lilkathibi sammaAAoona liqawmin akhareena lam yatooka yuharrifoona alkalima min baAAdi mawadiAAihi yaqooloona in ooteetum hatha fakhuthoohu wain lam tutawhu faihtharoo waman yuridi Allahu fitnatahu falan tamlika lahu mina Allahi shayan olaika allatheena lam yuridi Allahu an yutahhira quloobahum lahum fee alddunya khizyun walahum fee alakhirati AAathabun AAatheemun', 1, NOW(), NOW()),
(5, 42, 'سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ', '(ইহুদীদের চরিত্র হচ্ছে,) এরা (যেমন) মিথ্যা কথা শুনতে অভ্যস্ত, (তেমনি) এরা হারাম সম্পদ ভোগ করতেও পটু; এরা যদি কখনো (কোনো বিচার নিয়ে) তোমার কাছে আসে তাহলে তুমি (চাইলে) তাদের বিচার করতে পারো কিংবা তাদের উপেক্ষা করো, যদি তুমি তাদের উপেক্ষা করো তাহলে (নিশ্চিত থাকো), এরা কখনো তোমার কোনো অনিষ্ট করতে পারবে না, তবে যদি তুমি তাদের বিচার ফয়সালা করো তাহলে অবশ্যই ন্যায়বিচার করবে; নিসন্দেহে আল্লাহ তায়ালা ন্যায় বিচারকদের ভালোবাসেন।', 'SammaAAoona lilkathibi akkaloona lilssuhti fain jaooka faohkum baynahum aw aAArid AAanhum wain tuAArid AAanhum falan yadurrooka shayan wain hakamta faohkum baynahum bialqisti inna Allaha yuhibbu almuqsiteena', 1, NOW(), NOW()),
(5, 43, 'وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ', 'এসব লোক কিভাবে তোমাকে বিচারক মানবে, যখন তাদের নিজেদের কাছেই (আল্লাহর পাঠানো) তাওরাত মজুদ রয়েছে, তাতেও তো আল্লাহর বিধান আছে, (তুমি যাই করো না কেন) এরপরই তারা তোমার কাছ থেকে মুখ ফিরিয়ে নেবে, এরা কেউই (আল্লাহর কিতাবে) বিশ্বাসী নয়।', 'Wakayfa yuhakkimoonaka waAAindahumu alttawratu feeha hukmu Allahi thumma yatawallawna min baAAdi thalika wama olaika bialmumineena', 1, NOW(), NOW()),
(5, 44, 'إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ', 'অবশ্যই আমি (মূসার কাছে) তাওরাত নাযিল করেছি, তাতে (আমার) হেদায়াত ও আলোকবর্তিকা ছিলো, আমার নবীরা- যারা আমার বিধানের আনুগত্য করতো- তারা ইহুদী জাতিকে এ (হেদায়াত) মোতাবেকই বিচার ফয়সালা দিতো, (নবীদের পর তাদের) জ্ঞানসাধক এবং ধর্মীয় পন্ডিতরাও (এ অনুযায়ী বিচার-আচার করতো), কেননা, (নবীর পর) আল্লাহর কিতাব সংরক্ষণ করার দায়িত্ব এদেরই দেয়া হয়েছিলো, তারা (নিজেরাও) এর ওপর সাক্ষী ছিলো, সুতরাং তোমরা মানুষদের ভয় না করে একান্তভাবে আমাকেই ভয় করো, আর আমার আয়াতসমূহকে (তাদের মতো) সামান্য মূল্যে বিক্রি করো না; যারা আল্লাহর নাযিল করা আইন অনুযায়ী বিচার- -ফয়সালা করে না, তারাই (হচ্ছে) কাফের।', 'Inna anzalna alttawrata feeha hudan wanoorun yahkumu biha alnnabiyyoona allatheena aslamoo lillatheena hadoo waalrrabbaniyyoona waalahbaru bima istuhfithoo min kitabi Allahi wakanoo AAalayhi shuhadaa fala takhshawoo alnnasa waikhshawni wala tashtaroo biayatee thamanan qaleelan waman lam yahkum bima anzala Allahu faolaika humu alkafiroona', 1, NOW(), NOW()),
(5, 45, 'وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'সেখানে আমি তাদের জন্যে (এই ফৌজদারী) বিধান নাযিল করেছিলাম যে, প্রত্যেক জানের বদলে জান, চোখের বদলে চোখ, নাকের বদলে নাক, কানের বদলে কান, দাঁতের বদলে দাঁত, (শাস্তি প্রয়োগের সময় এই শারীরিক) যখমটাই কিন্তু আসল দন্ড (বলে বিবেচনা করবে); অবশ্য (বাদী পক্ষের) কেউ যদি এই দন্ড মাফ করে দিতে চায়, তাহলে তা তার (নিজের গুনাহ-খাতার) জন্যে কাফফারা হিসেবে পরিগণিত) হবে; আর যারা আল্লাহর নাযিল করা বিধান অনুযায়ী বিচার-ফয়সালা করে না, তারাই হচ্ছে যালিম।', 'Wakatabna AAalayhim feeha anna alnnafsa bialnnafsi waalAAayna bialAAayni waalanfa bialanfi waalothuna bialothuni waalssinna bialssinni waaljurooha qisasun faman tasaddaqa bihi fahuwa kaffaratun lahu waman lam yahkum bima anzala Allahu faolaika humu alththalimoona', 1, NOW(), NOW()),
(5, 46, 'وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ', 'এ ক্রমধারায় অতঃপর আমি মারইয়াম-পুত্র ঈসাকে পাঠিয়েছি, (সেখানে) আগে থেকে তাওরাতের যা কিছু (অবশিষ্ট) ছিলো, সে ছিলো তার সত্যায়নকারী, আর আমি তাকে ইনজীল দান করেছি, তাতে ছিলো হেদায়াত ও নূর; তখন তাওরাতের যা কিছু তার কাছে (বর্তমান) ছিলো- সে তার সত্যায়নকারী ছিলো, (তদুপরি) তাতে মোত্তাকী লোকদের জন্যে পথনির্দেশ ও উপদেশ (মজুদ) ছিলো।', 'Waqaffayna AAala atharihim biAAeesa ibni maryama musaddiqan lima bayna yadayhi mina alttawrati waataynahu alinjeela feehi hudan wanoorun wamusaddiqan lima bayna yadayhi mina alttawrati wahudan wamawAAithatan lilmuttaqeena', 1, NOW(), NOW()),
(5, 47, 'وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', 'ইনজীলের অনুসারীদের উচিত ছিলো এর ভেতর আল্লাহ তায়ালা যা কিছু নাযিল করেছেন তার ভিত্তিতে বিচার ফয়সালা করা; (কেননা) যারা আল্লাহর নাযিল করা আইনের ভিত্তিতে বিচার করে না তারাই হচ্ছে ফাসেক।', 'Walyahkum ahlu alinjeeli bima anzala Allahu feehi waman lam yahkum bima anzala Allahu faolaika humu alfasiqoona', 1, NOW(), NOW()),
(5, 48, 'وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', '(হে মুহাম্মদ,) আমি তোমার প্রতি সত্য (দ্বীন)-সহ এ কিতাব নাযিল করেছি, (আগের) কিতাবের যা কিছু তার সামনে মজুদ রয়েছে, এ কিতাব তার সত্যতা স্বীকার করে, (শুধু তাই নয়), এ কিতাব তার হেফাযতকারীও বটে! (সুতরাং) আল্লাহ তায়ালা যেসব বিধি-বিধান নাযিল করেছেন তার ভিত্তিতেই তুমি তাদের মধ্যে বিচার-ফয়সালা করো, আর (বিচারের সময়) তোমার নিজের কাছে যে সত্য (দ্বীন) এসেছে, তার থেকে সরে গিয়ে তাদের খেয়াল খুশীর অনুসরণ করো না; (কেননা) আমি তোমাদের প্রতিটি (সম্প্রদায়ের) জন্যে শরীয়ত ও কর্মপন্থা নির্ধারণ করে দিয়েছি; আল্লাহ তায়ালা চাইলে তোমাদের সবাইকে একই উম্মত বানিয়ে দিতে পারতেন; কিন্তু তিনি তোমাদের যা দিয়েছেন তা দিয়ে তোমাদের যাচাই-বাছাই করে নিতে চান, অতএব ভালো কাজে তোমরা সবাই প্রতিযোগিতা করো; (কেননা) আল্লাহ তায়ালার কাছেই তোমাদের সকলের প্রত্যাবর্তন করার স্থান, (এখানে) তোমরা যেসব বিষয় নিয়ে মতভেদ করতে, (ওখানে) তিনি তা তোমাদের বলে দিবেন।', 'Waanzalna ilayka alkitaba bialhaqqi musaddiqan lima bayna yadayhi mina alkitabi wamuhayminan AAalayhi faohkum baynahum bima anzala Allahu wala tattabiAA ahwaahum AAamma jaaka mina alhaqqi likullin jaAAalna minkum shirAAatan waminhajan walaw shaa Allahu lajaAAalakum ommatan wahidatan walakin liyabluwakum fee ma atakum faistabiqoo alkhayrati ila Allahi marjiAAukum jameeAAan fayunabbiokum bima kuntum feehi takhtalifoona', 1, NOW(), NOW()),
(5, 49, 'وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', '(অতএব, হে মুহাম্মদ,) তোমার ওপর আল্লাহ তায়ালা (আইন-কানুনের) যা কিছু নাযিল করেছেন তুমি তা দিয়ে এদের মাঝে বিচার ফয়সালা করো এবং কখনো তাদের খেয়াল-খুশীর অনুসরণ করো না, তাদের থেকে সতর্ক থেকো, যা কিছু আল্লাহ তায়ালা তোমার ওপর নাযিল করেছেন তার কোনো বিষয়ে তারা যেন কখনো তোমাকে ফেতনায় না ফেলতে পারে; অতঃপর (তোমার ফয়সালা থেকে) যদি এরা মুখ ফিরিয়ে নেয়, তাহলে জেনে রেখো, আল্লাহ তায়ালা তাদের নিজেদেরই কোনো গুনাহের জন্যে তাদের কোনো মসিবতে ফেলবেন; অবশ্যই মানুষের মাঝে অধিকাংশ হচ্ছে অবাধ্য।', 'Waani ohkum baynahum bima anzala Allahu wala tattabiAA ahwaahum waihtharhum an yaftinooka AAan baAAdi ma anzala Allahu ilayka fain tawallaw faiAAlam annama yureedu Allahu an yuseebahum bibaAAdi thunoobihim wainna katheeran mina alnnasi lafasiqoona', 1, NOW(), NOW()),
(5, 50, 'أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ', 'তবে কি তারা পুনরায় জাহেলিয়াতের বিচার ব্যবস্থা তালাশ করছে? অথচ যারা (আল্লাহতে) একনিষ্ঠভাবে বিশ্বাস করে, তাদের কাছে আল্লাহ তায়ালার চাইতে উত্তম বিচারক আর কে হতে পারে?', 'Afahukma aljahiliyyati yabghoona waman ahsanu mina Allahu hukman liqawmin yooqinoona', 1, NOW(), NOW()),
(5, 51, '۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'হে ঈমানদার লোকেরা, তোমরা (কখনো) ইহুদী- খৃস্টানদের নিজেদের বন্ধু হিসেবে গ্রহণ করো না । (কেননা) এরা নিজেরা (সব সময়ই) একে অপরের বন্ধু; তোমাদের মধ্যে কেউ যদি এদের কাউকে বন্ধু বানিয়ে নেয় তাহলে সে অবশ্যই তাদের দলভুক্ত হয়ে যাবে; আর আল্লাহ তায়ালা কখনো যালিম সম্প্রদায়কে হেদায়াত দান করেন না।', 'Ya ayyuha allatheena amanoo la tattakhithoo alyahooda waalnnasara awliyaa baAAduhum awliyao baAAdin waman yatawallahum minkum fainnahu minhum inna Allaha la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(5, 52, 'فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ', 'অতঃপর যাদের অন্তরে (মুনাফিকীর) ব্যাধি রয়েছে তাদের তুমি দেখবে, তারা (বিশেষ) তৎপরতার সাথে এই বলে তাদের সাথে মিলিত হচ্ছে, ‘আমাদের আশংকা, কোনো বিপর্যয় এসে আমাদের ওপর আপতিত হবে’। (পরে) হয়তো আল্লাহ তায়ালা (তোমাদের কাছে) বিজয় নিয়ে আসবেন; কিংবা তাঁর কাছ থেকে অন্য কিছু (অনুগ্রহ তিনি দান করবেন), তখন (এ) লোকেরা নিজেদের মনের ভেতর যে কপটতা লুকিয়ে রেখেছিলো, তার জন্যে ভীষণ অনুতপ্ত হবে।', 'Fatara allatheena fee quloobihim maradun yusariAAoona feehim yaqooloona nakhsha an tuseebana dairatun faAAasa Allahu an yatiya bialfathi aw amrin min AAindihi fayusbihoo AAala ma asarroo fee anfusihim nadimeena', 1, NOW(), NOW()),
(5, 53, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ', '(তখন) ঈমানদার লোকেরা বলবে, এরাই কি সেসব মানুষ, যারা আল্লাহ তায়ালার নামে বড়ো বড়ো শপথ করতো যে, তারা অবশ্যই তোমাদের সঙ্গে আছে; আজ (তাদের সমগ্র কার্যকলাপ) বিনষ্ট হয়ে গেলো এবং তারা ভীষণ ক্ষতিগ্রস্ত হয়ে পড়লো।', 'Wayaqoolu allatheena amanoo ahaolai allatheena aqsamoo biAllahi jahda aymanihim innahum lamaAAakum habitat aAAmaluhum faasbahoo khasireena', 1, NOW(), NOW()),
(5, 54, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'হে ঈমানদার ব্যক্তিরা, (জেনে রেখো) তোমাদের মধ্যে কোনো লোক যদি নিজের দ্বীন (ইসলাম) থেকে মোরতাদ হয়ে যায় তাহলে (তার জায়গায়) আল্লাহ তায়ালা অচিরেই (এখানে) এমন এক সম্প্রদায়কে নিয়ে আসবেন যাদের তিনি ভালোবাসবেন, তারাও তাঁকে ভালোবাসবে, (তারা হবে) মুমীনদের প্রতি কোমল ও কাফেরদের প্রতি কঠোর, তারা আল্লাহর পথে জেহাদ করবে, কোনো নিন্দুকের নিন্দাকে তারা ভয় করবে না; (মূলত) এটা হচ্ছে আল্লাহর অনুগ্রহ, যাকে চান তাকেই তিনি তা দান করেন; আল্লাহ তায়ালা প্রাচুর্যময় ও প্রজ্ঞাময়।', 'Ya ayyuha allatheena amanoo man yartadda minkum AAan deenihi fasawfa yatee Allahu biqawmin yuhibbuhum wayuhibboonahu athillatin AAala almumineena aAAizzatin AAala alkafireena yujahidoona fee sabeeli Allahi wala yakhafoona lawmata laimin thalika fadlu Allahi yuteehi man yashao waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(5, 55, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ', 'অবশ্যই তোমাদের পৃষ্ঠপোষক হচ্ছেন আল্লাহ তায়ালা, তাঁর রাসূল এবং সেসব ঈমানদার লোকেরা, যারা নামায প্রতিষ্ঠা করে, যাকাত আদায় করে, (সর্বোপরি আল্লাহ তায়ালার সামনে যারা) অবনমিত থাকে।', 'Innama waliyyukumu Allahu warasooluhu waallatheena amanoo allatheena yuqeemoona alssalata wayutoona alzzakata wahum rakiAAoona', 1, NOW(), NOW()),
(5, 56, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ', 'আর যে ব্যক্তি আল্লাহ তায়ালা, তাঁর রাসূল ও ঈমানদারদের নিজের বন্ধুরূপে গ্রহণ করবে (তারা যেন জেনে রাখে), অবশ্যই আল্লাহ তায়ালার দল বিজয়ী হবে।', 'Waman yatawalla Allaha warasoolahu waallatheena amanoo fainna hizba Allahi humu alghaliboona', 1, NOW(), NOW()),
(5, 57, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ', 'হে ঈমানদার লোকেরা, তোমাদের আগে যাদের (আল্লাহ তায়ালার) কিতাব দেয়া হয়েছিলো, তাদের মধ্যে যারা তোমাদের দ্বীনকে বিদ্রূপ ও খেল-তামাশার বস্তুতে পরিণত করে রেখেছে, তাদের এবং কাফেরদের কখনো তোমরা নিজেদের বন্ধু বানিয়ো না, যদি তোমরা সত্যিকার অর্থে মুমীন হয়ে থাকো তাহলে একমাত্র আল্লাহ তায়ালাকেই (বন্ধু বানাও এবং তাঁকেই) ভয় করো।', 'Ya ayyuha allatheena amanoo la tattakhithoo allatheena ittakhathoo deenakum huzuwan walaAAiban mina allatheena ootoo alkitaba min qablikum waalkuffara awliyaa waittaqoo Allaha in kuntum mumineena', 1, NOW(), NOW()),
(5, 58, 'وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ', 'যখন তোমরা (মানুষদের) নামাযের জন্যে ডাকো, তখন এ (ডাক)কে এরা হাসি-তামাশা ও খেলার বস্তু বানিয়ে দেয়; এটা এ জন্যে যে, এরা হচ্ছে এমন এক সম্প্রদায়, যারা (সত্য মিথ্যার) কিছুই বোঝে না।', 'Waitha nadaytum ila alssalati ittakhathooha huzuwan walaAAiban thalika biannahum qawmun la yaAAqiloona', 1, NOW(), NOW()),
(5, 59, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ', '(হে রাসূল,) তুমি বলো, হে আহলে কিতাবরা, তোমরা কি আমাদের কাছ থেকে এ কারণেই প্রতিশোধ নিচ্ছো যে, আমরা আল্লাহর ওপর ঈমান এনেছি এবং ঈমান এনেছি আমাদের ওপর আগে ও বর্তমানে যা কিছু নাযিল করা হয়েছে তার ওপরও, (আসলে) তোমাদের অধিকাংশ (মানুষই) হচ্ছো গুনাহগার।', 'Qul ya ahla alkitabi hal tanqimoona minna illa an amanna biAllahi wama onzila ilayna wama onzila min qablu waanna aktharakum fasiqoona', 1, NOW(), NOW()),
(5, 60, 'قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', '(হে রাসূল,) তুমি বলো, আমি কি তোমাদের বলে দিবো- আল্লাহর কাছে এর চাইতে নিকৃষ্ট (শাস্তি) কে পাবে? (হ্যাঁ) সে লোক (হচ্ছে,) যার ওপর আল্লাহ তায়ালা অভিশাপ দিয়েছেন, যার ওপর তাঁর ক্রোধ রয়েছে এবং যাদের কিছু লোককে তিনি বানর (কিছু লোককে) শুয়োরে পরিণত করে দিয়েছেন, যারা মিথ্যা মাবুদের আনুগত্য করেছে; এরাই হচ্ছে সেসব লোক, (পরকালে) যাদের অবস্থান হবে অত্যন্ত নিকৃষ্ট এবং (দুনিয়াতেও) এরা সরল পথ থেকে (বহুদূরে) বিচ্যুত হয়ে পড়বে।', 'Qul hal onabbiokum bisharrin min thalika mathoobatan AAinda Allahi man laAAanahu Allahu waghadiba AAalayhi wajaAAala minhumu alqiradata waalkhanazeera waAAabada alttaghooti olaika sharrun makanan waadallu AAan sawai alssabeeli', 1, NOW(), NOW()),
(5, 61, 'وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ', 'তারা যখন তোমাদের সামনে আসে তখন বলে, আমরা ঈমান এনেছি, (আসলে তোমার এ জায়গায়) তারা কুফরী নিয়েই প্রবেশ করছিলো এবং তা নিয়েই (তোমার কাছ থেকে) তারা বেরিয়ে গেছে; (তারা তাদের মনের ভেতর) যা কিছু লুকিয়ে রাখছিলো, আল্লাহ তায়ালা সে ব্যাপারে পূর্ণ ওয়াকেফহাল রয়েছেন।', 'Waitha jaookum qaloo amanna waqad dakhaloo bialkufri wahum qad kharajoo bihi waAllahu aAAlamu bima kanoo yaktumoona', 1, NOW(), NOW()),
(5, 62, 'وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ', 'তাদের অনেককেই তুমি দেখতে পাবে, গুনাহ, বিদ্রোহ ও হারাম মাল ভোগ করার কাজে একে অপরের সাথে প্রতিযোগিতা করে চলেছে; এরা যা করে (আসলেই) তা বড়ো নিকৃষ্ট কাজ!', 'Watara katheeran minhum yusariAAoona fee alithmi waalAAudwani waaklihimu alssuhta labisa ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(5, 63, 'لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ', '(কতো ভালো হতো, এদের) ধর্মীয় নেতা ও পন্ডিত ব্যক্তিরা যদি এদেরকে এসব পাপের কথা ও হারাম মাল ভোগ করা থেকে বিরত রাখতো! (কারণ) এরা যা কিছু (সংগ্রহ) করছে তা বড়োই জঘন্য!', 'Lawla yanhahumu alrrabbaniyyoona waalahbaru AAan qawlihimu alithma waaklihimu alssuhta labisa ma kanoo yasnaAAoona', 1, NOW(), NOW()),
(5, 64, 'وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ', 'ইহুদীরা বলে, আল্লাহর (দানের) হাত বাঁধা পড়ে গেছে; (আসলে আল্লাহ তায়ালার নয়-) তাদের নিজেদের হাতই বাঁধা পড়ে গেছে, আর তারা যা কিছু বলেছে সে কারণে তাদের অভিশাপ দেয়া হয়েছে । আল্লাহর তো উভয় হাতই মুক্ত, যেভাবে তিনি চান সেভাবেই তিনি দান করেন; (আসলে) তোমার মালিকের পক্ষ থেকে যা কিছু তোমার ওপর নাযিল করা হয়েছে, তা অবশ্যই তাদের অনেকেরই সীমালংঘন ও কুফরীকে বাড়িয়ে দিয়েছে; (ফলে) আমি তাদের মাঝে কেয়ামত পর্যন্ত শত্রুতা ও পরস্পর বিদ্বেষ সঞ্চার করে দিয়েছি; যখনি তারা যুদ্ধের আগুন জ্বালিয়ে দিতে চেয়েছে, আল্লাহ তায়ালা (তখনি) তা নিভিয়ে দিয়েছেন, তারা (বার বার) এ যমীনে বিপর্যয় সৃষ্টির প্রয়াস পেয়েছে; আল্লাহ তায়ালা বিপর্যয় সৃষ্টিকারীদের পছন্দ করেন না।', 'Waqalati alyahoodu yadu Allahi maghloolatun ghullat aydeehim waluAAinoo bima qaloo bal yadahu mabsootatani yunfiqu kayfa yashao walayazeedanna katheeran minhum ma onzila ilayka min rabbika tughyanan wakufran waalqayna baynahumu alAAadawata waalbaghdaa ila yawmi alqiyamati kullama awqadoo naran lilharbi atfaaha Allahu wayasAAawna fee alardi fasadan waAllahu la yuhibbu almufsideena', 1, NOW(), NOW()),
(5, 65, 'وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ', 'যদি আহলে কিতাবরা ঈমান আনতো এবং (আল্লাহকে) ভয় করতো, তাহলে অবশ্যই আমি তাদের গুনাহখাতা মুছে দিতাম, অবশ্যই আমি তাদের নেয়ামতে পরিপূর্ণ জান্নাতে প্রবেশ করাতাম।', 'Walaw anna ahla alkitabi amanoo waittaqaw lakaffarna AAanhum sayyiatihim walaadkhalnahum jannati alnnaAAeemi', 1, NOW(), NOW()),
(5, 66, 'وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ', 'যদি তারা (আল্লাহর যমীনে) তাওরাত ও ইনজীল এবং যা তাদের ওপর তাদের মালিকের কাছ থেকে নাযিল করা হয়েছে তা প্রতিষ্ঠা করতো, তাহলে তারা তাদের মাথার ওপরের (আসমান) থেকে ও তাদের পায়ের নীচের (যমীন) থেকে পাওয়া রিজিক ভোগ করতে পারতো; তাদের মধ্যে একদল (ন্যায় ও) মধ্যপন্থী লোক রয়েছে, তবে তাদের অধিকাংশই হচ্ছে এমন, যাদের কর্মকান্ড খুবই নিকৃষ্ট!', 'Walaw annahum aqamoo alttawrata waalinjeela wama onzila ilayhim min rabbihim laakaloo min fawqihim wamin tahti arjulihim minhum ommatun muqtasidatun wakatheerun minhum saa ma yaAAmaloona', 1, NOW(), NOW()),
(5, 67, '۞يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', 'হে রাসূল, তোমার মালিকের পক্ষ থেকে যা কিছু তোমার ওপর নাযিল করা হয়েছে তা তুমি (অন্যের কাছে) পৌঁছে দাও, যদি তুমি (তা) না করো তাহলে তুমি তো (মানুষদের কাছে) তাঁর বার্তা পৌঁছে দিলে না! আল্লাহ তায়ালা তোমাকে মানুষের (অনিষ্ট) থেকে বাঁচিয়ে রাখবেন; আল্লাহ তায়ালা কখনো কোনো কাফের জাতিকে পথ প্রদর্শন করেন না।', 'Ya ayyuha alrrasoolu balligh ma onzila ilayka min rabbika wain lam tafAAal fama ballaghta risalatahu waAllahu yaAAsimuka mina alnnasi inna Allaha la yahdee alqawma alkafireena', 1, NOW(), NOW()),
(5, 68, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', 'তুমি (তাদের) বলো, হে আহলে কিতাবরা, যতোক্ষণ পর্যন্ত তোমরা তাওরাত, ইনজীল ও তোমাদের প্রতি তোমাদের মালিকের পক্ষ থেকে যা নাযিল করা হয়েছে তা (এ যমীনে) প্রতিষ্ঠিত না করবে, ততোক্ষণ পর্যন্ত (মনে করতে হবে,) তোমরা কোনো কিছুর ওপরই প্রতিষ্ঠিত নেই; তোমার মালিকের কাছ থেকে যা কিছু তোমার প্রতি নাযিল করা হয়েছে (গোঁড়ামীর কারণে) তা অবশ্যই তাদের অনেকেরই সীমালংঘন ও কুফরীকে বাড়িয়ে দিবে, সুতরাং তুমি এই কাফের সম্প্রদায়ের জন্যে মোটেই আফসোস করো না।', 'Qul ya ahla alkitabi lastum AAala shayin hatta tuqeemoo alttawrata waalinjeela wama onzila ilaykum min rabbikum walayazeedanna katheeran minhum ma onzila ilayka min rabbika tughyanan wakufran fala tasa AAala alqawmi alkafireena', 1, NOW(), NOW()),
(5, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'নিশ্চয়ই যারা ঈমান এনেছে এবং যারা ছিলো ইহুদী, সাবেয়ী, খৃস্টান— (এদের) যে কেউই এক আল্লাহ তায়ালা ও শেষ বিচার দিনের ওপর ঈমান আনবে এবং (ঈমানের দাবী অনযায়ী) নেক কাজ করবে, (পরকালে) তাদের কোনো ভয় নেই, তারা কোনো দুশ্চিন্তা করবে না।', 'Inna allatheena amanoo waallatheena hadoo waalssabioona waalnnasara man amana biAllahi waalyawmi alakhiri waAAamila salihan fala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(5, 70, 'لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ', 'আমি বনী ইসরাঈলের কাছ থেকে (আনুগত্যের) অঙ্গীকার আদায় করে নিয়েছিলাম এবং আমি তাদের কাছে রাসূলদের প্রেরণ করেছিলাম; কিন্তু যখনি কোনো রাসূল তাদের কাছে এমন কিছু (বিধান) নিয়ে হাযির হয়েছে, যা তাদের মন পছন্দ করেনি, তখনি তারা (রাসূলদের) একদলকে মিথ্যাবাদী বলেছে, আরেক দলকে তারা হত্যা করেছে।', 'Laqad akhathna meethaqa banee israeela waarsalna ilayhim rusulan kullama jaahum rasoolun bima la tahwa anfusuhum fareeqan kaththaboo wafareeqan yaqtuloona', 1, NOW(), NOW()),
(5, 71, 'وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ', 'তারা ধরে নিয়েছিলো, (এতো কিছু করা সত্ত্বেও) তাদের জন্যে কোনো বিপর্যয় থাকবে না, তাই তারা (সত্য গ্রহণ করার ব্যাপারে) অন্ধ ও বধির হয়ে থাকলো, তারপরও আল্লাহ তায়ালা তাদের ওপর ক্ষমাপরবশ হলেন, অতঃপর তাদের অনেকেই আবার অন্ধ ও বধির হয়ে গেলো; তারা যা কিছু করছে আল্লাহ তায়ালা তা পর্যবেক্ষণ করছেন।', 'Wahasiboo alla takoona fitnatun faAAamoo wasammoo thumma taba Allahu AAalayhim thumma AAamoo wasammoo katheerun minhum waAllahu baseerun bima yaAAmaloona', 1, NOW(), NOW()),
(5, 72, 'لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ', 'নিশ্চয়ই তারা কাফের হয়ে গেছে যারা (একথা) বলেছে, আল্লাহই হচ্ছেন মারইয়ামের পুত্র মাসীহ; অথচ মাসীহ (নিজেই একথা) বলেছে যে, হে বনী ইসরাঈল, তোমরা এক আল্লাহর এবাদাত করো, যিনি আমারও রব, তোমাদেরও রব; অবশ্যই যে ব্যক্তি আল্লাহর সাথে শরীক করবে, আল্লাহ তায়ালা তার ওপর জান্নাত হারাম করে দিবেন, আর তার (স্থায়ী) ঠিকানা হবে জাহান্নাম; এই যালিমদের (সেদিন) কোনো সাহায্যকারীই থাকবে না।', 'Laqad kafara allatheena qaloo inna Allaha huwa almaseehu ibnu maryama waqala almaseehu ya banee israeela oAAbudoo Allaha rabbee warabbakum innahu man yushrik biAllahi faqad harrama Allahu AAalayhi aljannata wamawahu alnnaru wama lilththalimeena min ansarin', 1, NOW(), NOW()),
(5, 73, 'لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ', 'তারাও কুফরী করেছে যারা বলেছে, তিন জনের মধ্যে তৃতীয় হচ্ছেন আল্লাহ । অথচ এক ইলাহ ছাড়া আর কোনো ইলাহ নেই; তারা যেসব (অলীক) কথাবার্তা বলে তা থেকে যদি এখনো ফিরে না আসে, তবে তাদের মাঝে যারা (একথা বলে) কুফরী করেছে, তাদের অবশ্যই কঠিন যন্ত্রণাদায়ক আযাবে পেয়ে যাবে।', 'Laqad kafara allatheena qaloo inna Allaha thalithu thalathatin wama min ilahin illa ilahun wahidun wain lam yantahoo AAamma yaqooloona layamassanna allatheena kafaroo minhum AAathabun aleemun', 1, NOW(), NOW()),
(5, 74, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'তারা কি আল্লাহর কাছে তাওবা করবে না? এবং (কখনো কি) তারা তাঁর কাছে ক্ষমা প্রার্থনা করবে না? আল্লাহ তায়ালা বড়োই ক্ষমাশীল,দয়াময়।', 'Afala yatooboona ila Allahi wayastaghfiroonahu waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(5, 75, 'مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ', 'মারইয়াম পুত্র মাসীহ তো রাসূল ছাড়া কিছুই ছিলো না, তার আগেও (তার মতো) অনেক রাসূল গত হয়েছে; তার মা ছিলো এক সত্যনিষ্ঠ মহিলা; তারা (মা ও ছেলে) উভয়ই (আর দু’দশটি মানুষের মতো করেই) খাবার খেতো; তুমি লক্ষ্য করে দেখো, আমি কিভাবে তাদের জন্যে (আমার) আয়াতগুলো খুলে খুলে বর্ণনা করছি, অতঃপর তুমি দেখো, কিভাবে (আজ) তাদের দ্বারে দ্বারে ঠোকর খাওয়ানো হচ্ছে।', 'Ma almaseehu ibnu maryama illa rasoolun qad khalat min qablihi alrrusulu waommuhu siddeeqatun kana yakulani alttaAAama onthur kayfa nubayyinu lahumu alayati thumma onthur anna yufakoona', 1, NOW(), NOW()),
(5, 76, 'قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'তুমি বলো, তোমরা কি আল্লাহকে বাদ দিয়ে এমন কিছুর এবাদাত করছো- যা তোমাদের কোনো ক্ষতি কিংবা উপকার কিছুই করার ক্ষমতা রাখে না; (প্রকৃতপক্ষে ) আল্লাহ তায়ালা (সব কিছুই) শোনেন এবং জানেন।', 'Qul ataAAbudoona min dooni Allahi ma la yamliku lakum darran wala nafAAan waAllahu huwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(5, 77, 'قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ', 'তুমি বলো, হে আহলে কিতাবরা, তোমরা কখনো নিজেদের দ্বীনের ব্যাপারে অন্যায়ভাবে বাড়াবাড়ি করো না, তোমরা সেসব জাতির খেয়াল-খুশীর অনুসরণ করো না, যারা আগেই পথভ্রষ্ট হয়ে গেছে এবং তারা অনেক লোককেই গোমরাহ করে দিয়েছে, আর তারা নিজেরাও সহজ সরল পথ থেকে বিচ্যুত হয়ে গেছে।', 'Qul ya ahla alkitabi la taghloo fee deenikum ghayra alhaqqi wala tattabiAAoo ahwaa qawmin qad dalloo min qablu waadalloo katheeran wadalloo AAan sawai alssabeeli', 1, NOW(), NOW()),
(5, 78, 'لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ', 'বনী ইসরাঈলদের মাঝে আরো যারা (মাসীহের ব্যাপারে আল্লাহর এ ঘোষণা) অস্বীকার করেছে, তাদের ওপর দাউদ ও মারইয়াম পুত্র ঈসার মুখে অভিশাপ দেয়া হয়েছে; কেননা, তারা (আল্লাহর বিরুদ্ধে) বিদ্রোহ করেছে এবং সীমালংঘন করেছে।', 'LuAAina allatheena kafaroo min banee israeela AAala lisani dawooda waAAeesa ibni maryama thalika bima AAasaw wakanoo yaAAtadoona', 1, NOW(), NOW()),
(5, 79, 'كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ', 'তারা যেসব গর্হিত কাজ করতো তা থেকে তারা একে অপরকে বারণ করতো না, তারা যা করতো নিসন্দেহে তা ছিলো নিকৃষ্ট।', 'Kanoo la yatanahawna AAan munkarin faAAaloohu labisa ma kanoo yafAAaloona', 1, NOW(), NOW()),
(5, 80, 'تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ', 'তুমি তাদের মাঝে এমন বহু লোককে দেখতে পাবে, যারা (ঈমানদারদের বদলে) কাফেরদের সাথে বন্ধুত্ব করতেই বেশী আগ্রহী, তারা নিজেরা নিজেদের জন্যে যা কিছু অর্জন করে সামনে পাঠিয়েছে তাও অতি নিকৃষ্ট, এ কারণে আল্লাহ তায়ালা তাদের ওপর ক্রোধান্বিত হয়েছেন, এ লোকেরা অনন্তকাল ধরে আযাবেই নিমজ্জিত থাকবে।', 'Tara katheeran minhum yatawallawna allatheena kafaroo labisa ma qaddamat lahum anfusuhum an sakhita Allahu AAalayhim wafee alAAathabi hum khalidoona', 1, NOW(), NOW()),
(5, 81, 'وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ', 'তারা যদি আল্লাহ তায়ালা, (তাঁর) নবী ও তাঁর প্রতি যা কিছু নাযিল করা হয়েছে তার প্রতি যথাযথ ঈমান আনতো, তাহলে এরা কাফেরদের বন্ধু হিসেবে গ্রহণ করতো না, কিন্তু তাদের অধিকাংশ লোকই হচ্ছে গুনাহগার।', 'Walaw kanoo yuminoona biAllahi waalnnabiyyi wama onzila ilayhi ma ittakhathoohum awliyaa walakinna katheeran minhum fasiqoona', 1, NOW(), NOW()),
(5, 82, '۞لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةٗ لِّلَّذِينَ ءَامَنُواْ ٱلۡيَهُودَ وَٱلَّذِينَ أَشۡرَكُواْۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةٗ لِّلَّذِينَ ءَامَنُواْ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰۚ ذَٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَانٗا وَأَنَّهُمۡ لَا يَسۡتَكۡبِرُونَ', 'মানুষদের মাঝে যারা ঈমান এনেছে— তাদের সাথে শত্রুতার ব্যাপারে অবশ্যই তোমরা ইহুদী ও মোশরেকদেরই বেশী কঠোর (দেখতে পাবে, (অপরদিকে) মুমীনদের সাথে বন্ধুত্বের ব্যাপারে তোমরা সেসব লোককে (কিছুটা) নিকটতর পাবে, যারা বলেছে অবশ্যই আমরা খৃস্টান; এটা এই কারণে, (তখনো তাদের মধ্যে ধর্মীয় পন্ডিত ব্যক্তি ও সংসারবিরাগী ফকীর- দরবেশরা মজুদ ছিলো, আর এ (ধরনের) লোকেরা (বেশী) অহংকারও করে না।', 'Latajidanna ashadda alnnasi AAadawatan lillatheena amanoo alyahooda waallatheena ashrakoo walatajidanna aqrabahum mawaddatan lillatheena amanoo allatheena qaloo inna nasara thalika bianna minhum qisseeseena waruhbanan waannahum la yastakbiroona', 1, NOW(), NOW()),
(5, 83, 'وَإِذَا سَمِعُواْ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعۡيُنَهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُواْ مِنَ ٱلۡحَقِّۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ', 'রাসূলের ওপর যা কিছু নাযিল করা হয়েছে তা যখন এরা শোনে, তখন সত্যের যেটুকু এরা জেনেছে- সে কারণে তুমি এদের অনেকের চোখকেই অশ্রুসজল দেখতে পাবে, (নিবেদিত হয়ে) তারা বলে, হে আমাদের রব, আমরা ঈমান এনেছি, তুমি আমাদের (নাম) সত্যের সাক্ষ্যদাতাদের সাথে লিখে নাও।', 'Waitha samiAAoo ma onzila ila alrrasooli tara aAAyunahum tafeedu mina alddamAAi mimma AAarafoo mina alhaqqi yaqooloona rabbana amanna faoktubna maAAa alshshahideena', 1, NOW(), NOW()),
(5, 84, 'وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن يُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِينَ', 'আল্লাহ তায়ালার কাছ থেকে আমাদের কাছে যা কিছু সত্য এসেছে তার ওপর আমরা ঈমান আনবো না কেন? আমরা তো (বরং) প্রত্যাশা করবো যে, আমাদের রব আমাদের সৎকর্মশীলদের সাথে (জান্নাতে) দাখিল করবেন,', 'Wama lana la numinu biAllahi wama jaana mina alhaqqi wanatmaAAu an yudkhilana rabbuna maAAa alqawmi alssaliheena', 1, NOW(), NOW()),
(5, 85, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُواْ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ', 'অতঃপর তারা যা বললো সেজন্যে আল্লাহ তায়ালা সন্তুষ্ট হয়ে তাদের এমন এক জান্নাত দান করবেন, যার তলদেশ দিয়ে ঝর্ণাধারা প্রবাহমান থাকবে, সেখানে তারা হবে চিরস্থায়ী; আর এটা হচ্ছে নেককার লোকদের পুরস্কার।', 'Faathabahumu Allahu bima qaloo jannatin tajree min tahtiha alanharu khalideena feeha wathalika jazao almuhsineena', 1, NOW(), NOW()),
(5, 86, 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', 'অপরদিকে যারা কুফরী করেছে এবং আমার আয়াতগুলোকে যারা মিথ্যা প্রতিপন্ন করেছে, তারাই হবে জাহান্নামের অধিবাসী।', 'Waallatheena kafaroo wakaththaboo biayatina olaika ashabu aljaheemi', 1, NOW(), NOW()),
(5, 87, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحَرِّمُواْ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ', 'হে ঈমানদার ব্যক্তিরা, আল্লাহ তায়ালা তোমাদের জন্যে যে পবিত্র জিনিসগুলো হালাল করে দিয়েছেন, তোমরা সেগুলোকে (নিজেদের জন্যে) হারাম করে নিয়ো না, আর তোমরা সীমা লংঘন করো না; নিসন্দেহে আল্লাহ তায়ালা সীমালংঘনকারীদের পছন্দ করেন না।', 'Ya ayyuha allatheena amanoo la tuharrimoo tayyibati ma ahalla Allahu lakum wala taAAtadoo inna Allaha la yuhibbu almuAAtadeena', 1, NOW(), NOW()),
(5, 88, 'وَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ', 'আল্লাহ তায়ালা তোমাদের যে হালাল ও পবিত্র রিজিক দান করেছেন তোমরা তা খাও এবং সে আল্লাহ তায়ালাকে ভয় করো, যাঁর ওপর তোমরা ঈমান এনেছো।', 'Wakuloo mimma razaqakumu Allahu halalan tayyiban waittaqoo Allaha allathee antum bihi muminoona', 1, NOW(), NOW()),
(5, 89, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَيۡمَٰنَۖ فَكَفَّـٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖۚ ذَٰلِكَ كَفَّـٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ', 'আল্লাহ তায়ালা তোমাদের অর্থহীন শপথের জন্যে তোমাদের পাকড়াও করবেন না, কিন্তু যে শপথ তোমরা শক্তভাবে করো সে ব্যাপারে আল্লাহ তায়ালা অবশ্যই তোমাদের পাকড়াও করবেন, (এ ধরনের শপথ ভংগ করলে) তার কাফফারা হচ্ছে দশ জন গরীব মেসকীনকে মধ্যম মানের খাবার খাওয়ানো, যা তোমরা (সচরাচর) নিজেদের পরিবার পরিজনদের খাইয়ে থাকো, কিংবা তাদের পোশাক পরানো, অথবা একজন ক্রীতদাস মুক্ত করে দেয়া; যে ব্যক্তি (এর কোনোটাই) পাবে না, তার জন্যে (কাফফারা হচ্ছে) তিন দিন রোযা (রাখা); যখন তোমরা তোমাদের শপথ ভাংগো তখন এই হচ্ছে তোমাদের শপথের কাফফারা; (অতএব) তোমরা তোমাদের শপথসমূহ রক্ষা করো; আল্লাহ তায়ালা এভাবেই তাঁর আয়াতসমূহ তোমাদের কাছে বিশদভাবে বর্ণনা করেন- যাতে করে তোমরা কৃতজ্ঞতা জ্ঞাপন করতে পারো।', 'La yuakhithukumu Allahu biallaghwi fee aymanikum walakin yuakhithukum bima AAaqqadtumu alaymana fakaffaratuhu itAAamu AAasharati masakeena min awsati ma tutAAimoona ahleekum aw kiswatuhum aw tahreeru raqabatin faman lam yajid fasiyamu thalathati ayyamin thalika kaffaratu aymanikum itha halaftum waihfathoo aymanakum kathalika yubayyinu Allahu lakum ayatihi laAAallakum tashkuroona', 1, NOW(), NOW()),
(5, 90, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ', 'হে মানুষ, তোমরা যারা ঈমান এনেছো (তোমরা জেনে রেখো), মদ, জুয়া, পূজার বেদী ও ভাগ্য নির্ণয়কারী শর হচ্ছে ঘৃণিত শয়তানের কাজ, অতএব তোমরা তা (সম্পূর্ণরূপে) বর্জন করো, আশা করা যায় তোমরা মুক্তি পেয়ে যাবে।', 'Ya ayyuha allatheena amanoo innama alkhamru waalmaysiru waalansabu waalazlamu rijsun min AAamali alshshaytani faijtaniboohu laAAallakum tuflihoona', 1, NOW(), NOW()),
(5, 91, 'إِنَّمَا يُرِيدُ ٱلشَّيۡطَٰنُ أَن يُوقِعَ بَيۡنَكُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ فِي ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِ وَيَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ', 'শয়তান মদ ও জুয়ার মধ্যে (ফেলে) তোমাদের মাঝে শত্রুতা ও বিদ্বেষ সৃষ্টি করে দিতে চায় এবং এভাবেই সে তোমাদের আল্লাহ তায়ালার স্মরণ ও নামায থেকে দূরে সরিয়ে রাখে, (এরপরও) কি তোমরা (এ কাজ থেকে) ফিরে আসবে না?', 'Innama yureedu alshshaytanu an yooqiAAa baynakumu alAAadawata waalbaghdaa fee alkhamri waalmaysiri wayasuddakum AAan thikri Allahi waAAani alssalati fahal antum muntahoona', 1, NOW(), NOW()),
(5, 92, 'وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَٱحۡذَرُواْۚ فَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ', 'তোমরা আল্লাহর আনুগত্য করো, আনুগত্য করো (তাঁর) রাসূলের, (হারাম কাজের ধ্বংসকারিতা থেকে) সতর্ক থেকো, আর তোমরা যদি মুখ ফিরিয়ে নাও তাহলে জেনে রাখো, আমার রাসূলের দায়িত্ব হচ্ছে সুস্পষ্টভাবে (আমার কথাগুলো) পৌঁছে দেয়া।', 'WaateeAAoo Allaha waateeAAoo alrrasoola waihtharoo fain tawallaytum faiAAlamoo annama AAala rasoolina albalaghu almubeenu', 1, NOW(), NOW()),
(5, 93, 'لَيۡسَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جُنَاحٞ فِيمَا طَعِمُوٓاْ إِذَا مَا ٱتَّقَواْ وَّءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ ثُمَّ ٱتَّقَواْ وَّءَامَنُواْ ثُمَّ ٱتَّقَواْ وَّأَحۡسَنُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ', 'যারা ঈমান এনেছে এবং নেক কাজ করেছে, (এ নিষেধাজ্ঞা জারির আগে) তারা যা কিছু খেয়েছে তার জন্যে তাদের ওপর কোনোই গুনাহ নেই, (হ্যাঁ, ভবিষ্যতে) যদি তারা (হারাম থেকে) বেঁচে থাকে, (আল্লাহর ওপর) ঈমান আনে এবং নেক আমল করে, অতঃপর (আল্লাহ তায়ালার নিষেধসমূহ থেকে) তারা সতর্ক থাকে, (এভাবে যতোক্ষণ পর্যন্ত) তারা ঈমান আনবে ও নেক আমল করবে, আবারও (আল্লাহ তায়ালাকে) ভয় করবে ও সততার নীতি অবলম্বন করতে থাকবে (আল্লাহ তায়ালা অবশ্যই তাদের ক্ষমা করে দিবেন, কেননা); আল্লাহ তায়ালা সৎকর্মশীল মানুষদের ভালোবাসেন।', 'Laysa AAala allatheena amanoo waAAamiloo alssalihati junahun feema taAAimoo itha ma ittaqaw waamanoo waAAamiloo alssalihati thumma ittaqaw waamanoo thumma ittaqaw waahsanoo waAllahu yuhibbu almuhsineena', 1, NOW(), NOW()),
(5, 94, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَيَبۡلُوَنَّكُمُ ٱللَّهُ بِشَيۡءٖ مِّنَ ٱلصَّيۡدِ تَنَالُهُۥٓ أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلۡغَيۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٞ', 'হে ঈমানদার লোকেরা, (এহরাম বাঁধা অবস্থায়) আল্লাহ তায়ালা অবশ্যই এমন কিছু শিকারের বস্তু দিয়ে তোমাদের পরীক্ষা নেবেন, যেগুলো তোমরা সহজেই নিজে দের হাত ও বর্শা দ্বারা ধরতে পারো, যেন আল্লাহ তায়ালা এ কথা ভালো করে জেনে নিতে পারেন, কে তাঁকে গায়ব থেকে ভয় করে, এরপরও যদি কেউ সীমালংঘন করে, তার জন্যে যন্ত্রণাদায়ক আযাব রয়েছে।', 'Ya ayyuha allatheena amanoo layabluwannakumu Allahu bishayin mina alssaydi tanaluhu aydeekum warimahukum liyaAAlama Allahu man yakhafuhu bialghaybi famani iAAtada baAAda thalika falahu AAathabun aleemun', 1, NOW(), NOW()),
(5, 95, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡتُلُواْ ٱلصَّيۡدَ وَأَنتُمۡ حُرُمٞۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدٗا فَجَزَآءٞ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحۡكُمُ بِهِۦ ذَوَا عَدۡلٖ مِّنكُمۡ هَدۡيَۢا بَٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةٞ طَعَامُ مَسَٰكِينَ أَوۡ عَدۡلُ ذَٰلِكَ صِيَامٗا لِّيَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ', 'হে ঈমানদার ব্যক্তিরা, এহরাম (বাঁধা) অবস্থায় তোমরা কখনো শিকার হত্যা করো না, যদি তোমাদের কেউ (এ অবস্থায়) জেনে-বুঝে শিকার হত্যা করে (তার জন্যে এর বিনিময় হচ্ছে), সে যে জন্তু হত্যা করেছে তার সমান পর্যায়ের একটি গৃহপালিত জন্তু কোরবানী হিসেবে কাবায় পৌঁছে দিবে, (যার) ফয়সালা করবে তোমাদের দু’জন ন্যায়বান বিচারক ব্যক্তি, কিংবা (তার জন্যে) কাফফারা হবে (কয়েকজন) গরীব-মেসকীনকে খাওয়ানো অথবা সমপরিমাণ রোযা রাখা, যাতে করে সে আপন কৃতকর্মের স্বাদ গ্রহণ করতে সক্ষম হয়। (এ নিষেধাজ্ঞা জারির আগে) যা কিছু গত হয়ে গেছে আল্লাহ তায়ালা তা মাফ করে দিয়েছেন; কিন্তু (এর পর) যদি কেউ (এর) পুনরাবৃত্তি করে, তাহলে আল্লাহ তায়ালা (অবশ্যই) তার কাছ থেকে প্রতিশোধ নেবেন; আর আল্লাহ তায়ালা পরাক্রমশালী ও প্রতিশোধ গ্রহণে প্রবল শক্তিমান।', 'Ya ayyuha allatheena amanoo la taqtuloo alssayda waantum hurumun waman qatalahu minkum mutaAAammidan fajazaon mithlu ma qatala mina alnnaAAami yahkumu bihi thawa AAadlin minkum hadyan baligha alkaAAbati aw kaffaratun taAAamu masakeena aw AAadlu thalika siyaman liyathooqa wabala amrihi AAafa Allahu AAamma salafa waman AAada fayantaqimu Allahu minhu waAllahu AAazeezun thoo intiqamin', 1, NOW(), NOW()),
(5, 96, 'أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعٗا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمٗاۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ', 'তোমাদের জন্যে সমুদ্রের শিকার হালাল করা হয়েছে এবং তার খাবার তোমাদের জন্যে ও (সমুদ্রের) পর্যটকদের জন্যে (উৎকৃষ্ট) সম্পদ, (মনে রাখবে), যতোক্ষণ পর্যন্ত তোমরা এহরাম (বাঁধা) অবস্থায় থাকবে, ততোক্ষণ পর্যন্ত (শুধু) স্থলভাগের শিকার তোমাদের জন্যে হারাম থাকবে; তোমরা ভয় করো আল্লাহ তায়ালাকে, যাঁর সমীপে তোমাদের সবাইকে জড়ো করা হবে।', 'Ohilla lakum saydu albahri wataAAamuhu mataAAan lakum walilssayyarati wahurrima AAalaykum saydu albarri ma dumtum huruman waittaqoo Allaha allathee ilayhi tuhsharoona', 1, NOW(), NOW()),
(5, 97, '۞جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡيَ وَٱلۡقَلَـٰٓئِدَۚ ذَٰلِكَ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ', 'আল্লাহ তায়ালা কাবা ঘরকে সম্মানিত করেছেন, মানব জাতির জন্যে (তার) ভিত্তি হিসেবে (তিনি এটা প্রতিষ্ঠা করেছেন), একইভাবে তিনি সম্মানিত করেছেন (হজ্জের) পবিত্র মাসকে, কোরবানীর জন্তুকে এবং (এ উদ্দেশে) পট্টি বাঁধা জন্তুগুলোকে, এটা এ জন্যে, যাতে করে তোমরা (এ কথা) জেনে নিতে পারো যে, আকাশমালা ও পৃথিবীর যেখানে যা কিছু আছে আল্লাহ তায়ালা তা সবই জানেন, অবশ্যই আল্লাহ তায়ালা সব বিষয়ে সর্বজ্ঞ।', 'JaAAala Allahu alkaAAbata albayta alharama qiyaman lilnnasi waalshshahra alharama waalhadya waalqalaida thalika litaAAlamoo anna Allaha yaAAlamu ma fee alssamawati wama fee alardi waanna Allaha bikulli shayin AAaleemun', 1, NOW(), NOW()),
(5, 98, 'ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'তোমরা জেনে রাখো, অবশ্যই আল্লাহ তায়ালা শাস্তিদানের ব্যাপারে (খুবই) কঠোর, নিসন্দেহে (পুরস্কারের বেলায়ও) আল্লাহ তায়ালা ক্ষমাশীল, পরম দয়ালু।', 'IAAlamoo anna Allaha shadeedu alAAiqabi waanna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(5, 99, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ', 'রাসূলের দায়িত্ব (হেদায়াতের বাণী) পৌঁছে দেয়া ছাড়া আর কিছুই নয়, আল্লাহ তায়ালা জানেন তোমরা যা কিছু প্রকাশ করো এবং যা কিছু গোপন রাখো।', 'Ma AAala alrrasooli illa albalaghu waAllahu yaAAlamu ma tubdoona wama taktumoona', 1, NOW(), NOW()),
(5, 100, 'قُل لَّا يَسۡتَوِي ٱلۡخَبِيثُ وَٱلطَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِيثِۚ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ', '(হে রাসূল,) তুমি বলো, পাক এবং নাপাক জিনিস কখনো সমান হতে পারে না, নাপাক জিনিসের প্রাচুর্য | যতোই তোমাকে চমৎকৃত করুক না কেন! অতঃপর হে জ্ঞানবান মানুষরা, তোমরা আল্লাহকে ভয় করো, আশা করা যায় তোমরা সফলকাম হতে পারবে।', 'Qul la yastawee alkhabeethu waalttayyibu walaw aAAjabaka kathratu alkhabeethi faittaqoo Allaha ya olee alalbabi laAAallakum tuflihoona', 1, NOW(), NOW()),
(5, 101, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَسۡـَٔلُواْ عَنۡ أَشۡيَآءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُواْ عَنۡهَا حِينَ يُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِيمٞ', 'হে ঈমানদার লোকেরা, (আল্লাহর নবীর কাছে) এমন সব বিষয় নিয়ে প্রশ্ন করো না, যার জবাব তোমাদের কাছে প্রকাশ করা হলে তোমাদের কষ্ট হবে, (অবশ্য) কুরআন নাযিল হবার মুহূর্তে যদি তোমরা প্রশ্ন করো, তাহলে তা তোমাদের জন্যে প্রকাশ করা হবে; (এ বিধান জারির আগে যা কিছু হয়ে গেছে) তা আল্লাহ তায়ালা মাফ করে দিয়েছেন; আল্লাহ তায়ালা পরম ক্ষমাশীল, ধৈর্যশীল।', 'Ya ayyuha allatheena amanoo la tasaloo AAan ashyaa in tubda lakum tasukum wain tasaloo AAanha heena yunazzalu alquranu tubda lakum AAafa Allahu AAanha waAllahu ghafoorun haleemun', 1, NOW(), NOW()),
(5, 102, 'قَدۡ سَأَلَهَا قَوۡمٞ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُواْ بِهَا كَٰفِرِينَ', 'তোমাদের আগেও কিছু সম্প্রদায় (তাদের নবীকে এ ধরনের) প্রশ্ন করেছিলো, কিন্তু পরক্ষণেই তারা তা অমান্য করতে শুরু করলো।', 'Qad saalaha qawmun min qablikum thumma asbahoo biha kafireena', 1, NOW(), NOW()),
(5, 103, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٖ وَلَا سَآئِبَةٖ وَلَا وَصِيلَةٖ وَلَا حَامٖ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُواْ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِلُونَ', 'দেবতার উদ্দেশে প্রেরিত (কান ছেঁড়া) ‘বহীরা’, (দেবতার নামে উৎসর্গীকৃত) ‘সায়েবা’, (দেবতার উদ্দেশে ছেড়ে দেয়া নর ও মাদী বাচ্চা প্রসবকারী) ‘ওয়াসীলা’ ও (দেবতার উদ্দেশে ছেড়ে দেয়া দশ বাচ্চা প্রসবকারিণী উষ্ট্রী) ‘হাম’- এর কোনোটাই কিন্তু আল্লাহ তায়ালা বানিয়ে দেননি, বরং কাফেররাই (কুসংস্কার দিয়ে) আল্লাহর ওপর মিথ্যা আরোপ করে, আর এদের অধিকাংশই কিছু উপলব্ধি করে না।', 'Ma jaAAala Allahu min baheeratin wala saibatin wala waseelatin wala hamin walakinna allatheena kafaroo yaftaroona AAala Allahi alkathiba waaktharuhum la yaAAqiloona', 1, NOW(), NOW()),
(5, 104, 'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُواْ حَسۡبُنَا مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـٔٗا وَلَا يَهۡتَدُونَ', 'যখন এদের বলা হয়, আল্লাহ তায়ালা যা কিছু নাযিল করেছেন তোমরা সেদিকে এসো, (এসো তাঁর রাসূলের দিকে, (তখন) তারা বলে, আমরা আমাদের বাপ-দাদাদের যার ওপর পেয়েছি তা-ই আমাদের জন্যে যথেষ্ট; যদিও তাদের বাপ-দাদারা (সত্য-মিথ্যা সম্পর্কে) কিছুই জানতো না এবং তারা হেদায়াতের পথেও চলতো না।', 'Waitha qeela lahum taAAalaw ila ma anzala Allahu waila alrrasooli qaloo hasbuna ma wajadna AAalayhi abaana awalaw kana abaohum la yaAAlamoona shayan wala yahtadoona', 1, NOW(), NOW()),
(5, 105, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', 'হে ঈমানদার লোকেরা, তোমাদের নিজেদের দায়িত্ব তোমাদের নিজেদের ওপর, কোনো ব্যক্তি যদি গোমরাহ হয় তাহলে সে ব্যক্তি তোমাদের কোনো ক্ষতি সাধন করতে পারবে না, যতোক্ষণ পর্যন্ত তোমরা নিজেরা সঠিক পথের ওপর চলতে থাকবে; তোমাদের সবার ফিরে যাওয়ার জায়গা আল্লাহর কাছে, অতঃপর তোমাদের (সেদিন) তিনি তোমাদের বলে দিবেন (দুনিয়ায়) তোমরা কী করছিলে!', 'Ya ayyuha allatheena amanoo AAalaykum anfusakum la yadurrukum man dalla itha ihtadaytum ila Allahi marjiAAukum jameeAAan fayunabbiokum bima kuntum taAAmaloona', 1, NOW(), NOW()),
(5, 106, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ شَهَٰدَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِينَ ٱلۡوَصِيَّةِ ٱثۡنَانِ ذَوَا عَدۡلٖ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَأَصَٰبَتۡكُم مُّصِيبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَيُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِي بِهِۦ ثَمَنٗا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذٗا لَّمِنَ ٱلۡأٓثِمِينَ', 'হে ঈমানদার ব্যক্তিরা, তোমাদের কারো যখন মৃত্যু (সময়) এসে উপনীত হয়, ওসিয়ত করার মুহূর্তে তোমাদের মধ্য থেকে দু’জন ন্যায়পরায়ণ মানুষের সাক্ষ্য থাকা (প্রয়োজন), আর যদি তোমরা প্রবাসে থাকো এবং এ সময় যদি তোমাদের ওপর মৃত্যুর বিপদ এসে পড়ে, তখন বাইরের লোকদের মধ্য থেকে দু’জন ব্যক্তি সাক্ষী থাকবে; (পরে যদি) তোমরা কোনো সন্দেহ প্রকাশ করো, তাহলে (সাক্ষী) দু’জনকে নামাযের পর আটকে রাখবে, অতঃপর তারা আল্লাহর নামে কসম করে বলবে, আমরা কোনো স্বার্থের খাতিরে এ সাক্ষ্য বিক্রি করবো না, (এমনকি ঘনিষ্ঠ আত্মীয় হলেও (নয়), আমরা আল্লাহর সাক্ষ্য গোপন করবো না, আমরা যদি তেমন কিছু করি তাহলে আমরা গুনাহগারদের দলে শামিল হয়ে যাবো।', 'Ya ayyuha allatheena amanoo shahadatu baynikum itha hadara ahadakumu almawtu heena alwasiyyati ithnani thawa AAadlin minkum aw akharani min ghayrikum in antum darabtum fee alardi faasabatkum museebatu almawti tahbisoonahuma min baAAdi alssalati fayuqsimani biAllahi ini irtabtum la nashtaree bihi thamanan walaw kana tha qurba wala naktumu shahadata Allahi inna ithan lamina alathimeena', 1, NOW(), NOW()),
(5, 107, 'فَإِنۡ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسۡتَحَقَّآ إِثۡمٗا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسۡتَحَقَّ عَلَيۡهِمُ ٱلۡأَوۡلَيَٰنِ فَيُقۡسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعۡتَدَيۡنَآ إِنَّآ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ', 'অতঃপর যদি (এটা) প্রকাশিত হয় যে, এ (বাইরের) দু’জন সাক্ষী (সাক্ষ্য গোপন করে) অপরাধে লিপ্ত ছিলো, তাহলে আগে (যাদের) স্বার্থহানি ঘটেছিলো তাদের মধ্য থেকে দু’জন সাক্ষী তাদের স্থলাভিষিক্ত হবে, তারা (এসে) আল্লাহর নামে শপথ করে বলবে, আমাদের সাক্ষ্য অবশ্যই তাদের সাক্ষ্য অপেক্ষা বেশী সত্যভিত্তিক (হবে), আমরা (সাক্ষ্যের ব্যাপারে) সীমালংঘন করিনি (আমরা যদি তেমনটি করি), তাহলে আমরা যালিমদের দলভুক্ত হয়ে পড়বো।', 'Fain AAuthira AAala annahuma istahaqqa ithman faakharani yaqoomani maqamahuma mina allatheena istahaqqa AAalayhimu alawlayani fayuqsimani biAllahi lashahadatuna ahaqqu min shahadatihima wama iAAtadayna inna ithan lamina alththalimeena', 1, NOW(), NOW()),
(5, 108, 'ذَٰلِكَ أَدۡنَىٰٓ أَن يَأۡتُواْ بِٱلشَّهَٰدَةِ عَلَىٰ وَجۡهِهَآ أَوۡ يَخَافُوٓاْ أَن تُرَدَّ أَيۡمَٰنُۢ بَعۡدَ أَيۡمَٰنِهِمۡۗ وَٱتَّقُواْ ٱللَّهَ وَٱسۡمَعُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ', 'এ (পদ্ধতি)-তে বেশী আশা করা যায়, তারা ঠিক ঠিক সাক্ষ্য নিয়ে আসবে অথবা তারা অন্ততপক্ষে এ ভয় করবে, (তাদের) কসম আবার অন্য কারো কসম দ্বারা বাতিল করে দেয়া হবে; তোমরা আল্লাহ তায়ালাকে ভয় করো এবং (রাসূলের কথা) শোনো; আল্লাহ তায়ালা কখনো পাপী লোকদের সৎপথে পরিচালিত করেন না।', 'Thalika adna an yatoo bialshshahadati AAala wajhiha aw yakhafoo an turadda aymanun baAAda aymanihim waittaqoo Allaha waismaAAoo waAllahu la yahdee alqawma alfasiqeena', 1, NOW(), NOW()),
(5, 109, '۞يَوۡمَ يَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبۡتُمۡۖ قَالُواْ لَا عِلۡمَ لَنَآۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ', 'যেদিন আল্লাহ তায়ালা সকল রাসূলকে একত্রিত করবেন, অতঃপর তিনি বলবেন, হে রাসূলরা, তোমাদের (দাওয়াতের প্রতি মানুষদের পক্ষ থেকে) কিভাবে সাড়া দেয়া হয়েছিলো; তারা বলবে, আমরা তো (তার) কিছুই জানি না; যাবতীয় গায়বের বিষয়ে তুমিই ভালো জানো।', 'Yawma yajmaAAu Allahu alrrusula fayaqoolu matha ojibtum qaloo la AAilma lana innaka anta AAallamu alghuyoobi', 1, NOW(), NOW()),
(5, 110, 'إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَـٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ', '(স্মরণ করো,) যখন আল্লাহ তায়ালা বলবেন, হে মাইরয়াম-পুত্র ঈসা, আমার সেই নেয়ামতের কথা স্মরণ করো যা আমি তোমাকে ও তোমার মাকে দান করেছিলাম, (বিশেষ করে) যখন আমি পবিত্র আত্মা দিয়ে তোমাকে সাহায্য করেছিলাম । তুমি মনুষের সাথে (যেমনি) দোলনায় থাকতে কথা বলতে, (তেমনি বলবে) পরিণত বয়সেও, আমি যখন তোমাকে কিতাব, জ্ঞান-ি -বিজ্ঞান, তাওরাত ও ইনজীল দান করেছিলাম, যখন তুমি আমারই হুকুমে কাঁচা মাটি দিয়ে পাখি সদৃশ আকৃতি বানাতে, অতঃপর তাতে ফুঁ দিতে, আর আমার আদেশক্রমেই তা পাখী হয়ে যেতো, আমারই হুকুমে তুমি জন্মান্ধ ও কুষ্ঠ রোগীকে নিরাময় করে দিতে, আমারই আদেশে তুমি মৃতদের বের করে আনতে, আমি তোমার (কোনো অনিষ্ট সাধন) থেকে বনী ইসরাঈলদের নিবৃত্ত করে রেখেছিলাম যখন তুমি তাদের কাছে (নবুওতের) এসব নিদর্শন নিয়ে পৌঁছলে, তখন তাদের মধ্যে যারা (তোমাকে) অস্বীকার করেছিলো তারা বললো, এ নিদর্শনগুলো যাদু ছাড়া আর কিছুই নয়।', 'Ith qala Allahu ya AAeesa ibna maryama othkur niAAmatee AAalayka waAAala walidatika ith ayyadtuka biroohi alqudusi tukallimu alnnasa fee almahdi wakahlan waith AAallamtuka alkitaba waalhikmata waalttawrata waalinjeela waith takhluqu mina altteeni kahayati alttayri biithnee fatanfukhu feeha fatakoonu tayran biithnee watubrio alakmaha waalabrasa biithnee waith tukhriju almawta biithnee waith kafaftu banee israeela AAanka ith jitahum bialbayyinati faqala allatheena kafaroo minhum in hatha illa sihrun mubeenun', 1, NOW(), NOW()),
(5, 111, 'وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ', '(আরো স্মরণ করো,) যখন আমি হাওয়ারী (সাথী)- দের (অন্তরে) এ প্রেরণা দিয়েছিলাম, তোমরা আমার প্রতি ও আমার রাসূলের প্রতি ঈমান আনো, তারা বললো (হে রব,) আমরা (তোমার ওপর) ঈমান আনলাম, তুমি একথার ওপর সাক্ষী থেকো যে, আমরা তোমার অনুগত।', 'Waith awhaytu ila alhawariyyeena an aminoo bee wabirasoolee qaloo amanna waishhad biannana muslimoona', 1, NOW(), NOW()),
(5, 112, 'إِذۡ قَالَ ٱلۡحَوَارِيُّونَ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِۖ قَالَ ٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ', '(অতঃপর যখন এই হাওয়ারীরা বললো, হে মারইয়াম-পুত্র ঈসা! তোমার রব কি আসমান থেকে খাবার সজ্জিত একটি টেবিল আমাদের জন্যে পাঠাতে পারেন? ঈসা বললো, (সত্যিই) যদি তোমরা মুমীন হয়ে থাকো তাহলে (অহেতুক দাবী পেশ করার ব্যাপারে) আল্লাহ তায়ালাকে ভয় করো।', 'Ith qala alhawariyyoona ya AAeesa ibna maryama hal yastateeAAu rabbuka an yunazzila AAalayna maidatan mina alssamai qala ittaqoo Allaha in kuntum mumineena', 1, NOW(), NOW()),
(5, 113, 'قَالُواْ نُرِيدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَئِنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَيۡهَا مِنَ ٱلشَّـٰهِدِينَ', 'তারা বললো, আমরা (শুধু এটুকুই) চাই, আমরা সেই টেবিল থেকে (কিছু) খাবার খাবো, এতে আমাদের মন পরিতৃপ্ত হয়ে যাবে, (এতে করে) আমরা এও জানতে পারবো যে, তুমি আমাদের কাছে সঠিক কথা বলেছো, আমরা নিজেরাও এর ওপর সাক্ষী হবো।', 'Qaloo nureedu an nakula minha watatmainna quloobuna wanaAAlama an qad sadaqtana wanakoona AAalayha mina alshshahideena', 1, NOW(), NOW()),
(5, 114, 'قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰزِقِينَ', 'মারইয়াম-পুত্র ঈসা (আল্লাহর দরবারে) বললো, হে আল্লাহ, হে আমাদের রব, তুমি আমাদের জন্যে আসমান থেকে খাবার সজ্জিত একটি টেবিল পাঠাও, এ হবে আমাদের জন্যে, আমাদের পূর্ববর্তী ও আমাদের পরবর্তীদের জন্যে তোমার কাছ থেকে (পাঠানো) একটি আনন্দোৎসব এবং তোমার (কুদরতের একটি) নিদর্শন, তুমি আমাদের রিজিক দাও, কেননা তুমিই হচ্ছো উত্তম রিজিকদাতা।', 'Qala AAeesa ibnu maryama allahumma rabbana anzil AAalayna maidatan mina alssamai takoonu lana AAeedan liawwalina waakhirina waayatan minka waorzuqna waanta khayru alrraziqeena', 1, NOW(), NOW()),
(5, 115, 'قَالَ ٱللَّهُ إِنِّي مُنَزِّلُهَا عَلَيۡكُمۡۖ فَمَن يَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّيٓ أُعَذِّبُهُۥ عَذَابٗا لَّآ أُعَذِّبُهُۥٓ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ', 'আল্লাহ তায়ালা বললেন, (হ্যাঁ, অচিরেই) আমি তা তোমাদের ওপর পাঠাচ্ছি, এরপর যদি তোমাদের কেউ (আমার ক্ষমতা) অস্বীকার করে তাহলে তাকে আমি এমন কঠিন শাস্তি দিবো, যা আমি সৃষ্টিকুলের কাউকেই আর দিবো না।', 'Qala Allahu innee munazziluha AAalaykum faman yakfur baAAdu minkum fainnee oAAaththibuhu AAathaban la oAAaththibuhu ahadan mina alAAalameena', 1, NOW(), NOW()),
(5, 116, 'وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُيُوبِ', 'যখন আল্লাহ তায়ালা বলবেন, হে মারইয়াম পুত্র ঈসা! তুমি কি কখনো (তোমার) লোকদের (একথা) বলেছিলে, তোমরা আল্লাহকে বাদ দিয়ে আমাকে ও আমার মাকে ‘ইলাহ’ বানিয়ে নাও; (এ কথার উত্তরে) সে বলবে (হে আল্লাহ), সমগ্র পবিত্রতা তোমার জন্যে, এমন কোনো কথা আমার পক্ষে শোভা পেতো না, যে কথা বলার আমার কোনো অধিকারই ছিলো না, যদি আমি তাদের এমন কোনো কথা বলতামই, তাহলে তুমি তো অবশ্যই তা জানতে; নিশ্চয়ই তুমি জানো আমার মনে যা কিছু আছে, কিন্তু আমি জানি না তোমার মনে কি আছে; যাবতীয় গায়বের খবর অবশ্যই তুমি ভালো করে জানো।', 'Waith qala Allahu ya AAeesa ibna maryama aanta qulta lilnnasi ittakhithoonee waommiya ilahayni min dooni Allahi qala subhanaka ma yakoonu lee an aqoola ma laysa lee bihaqqin in kuntu qultuhu faqad AAalimtahu taAAlamu ma fee nafsee wala aAAlamu ma fee nafsika innaka anta AAallamu alghuyoobi', 1, NOW(), NOW()),
(5, 117, 'مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ', 'তুমি আমাকে যা কিছু বলতে হুকুম করেছো আমি তো তাদের তাছাড়া (অন্য) কিছুই বলিনি, (আর সে বিষয়টি ছিলো), তোমরা শুধু আল্লাহ তায়ালার এবাদাত করো, যিনি আমার রব, তোমাদেরও রব, আমি যতোদিন তাদের মধ্যে ছিলাম ততোদিন আমি (নিজেই তাদের কার্যকলাপের) সাক্ষী ছিলাম, কিন্তু যখন তুমি আমাকে তুলে নিলে তখন তুমিই ছিলে তাদের ওপর একক নেগাহবান, যাবতীয় ক্রিয়াকর্মের তুমিই ছিলে সাক্ষী।', 'Ma qultu lahum illa ma amartanee bihi ani oAAbudoo Allaha rabbee warabbakum wakuntu AAalayhim shaheedan ma dumtu feehim falamma tawaffaytanee kunta anta alrraqeeba AAalayhim waanta AAala kulli shayin shaheedun', 1, NOW(), NOW()),
(5, 118, 'إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'তাদের (অপরাধের জন্যে) তুমি যদি তাদের শাস্তি দাও (দিতে পারো), নিসন্দেহে তারা তোমারই বান্দা, আর তুমি যদি তাদের ক্ষমা করে দাও (তাও তোমার দয়া), অবশ্যই তুমি বিপুল ক্ষমতাশালী, প্রজ্ঞাময়।', 'In tuAAaththibhum fainnahum AAibaduka wain taghfir lahum fainnaka anta alAAazeezu alhakeemu', 1, NOW(), NOW()),
(5, 119, 'قَالَ ٱللَّهُ هَٰذَا يَوۡمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'আল্লাহ তায়ালা বলবেন (হ্যাঁ), এ হচ্ছে সেদিন, যেদিন সত্যবাদী ব্যক্তিদের তাদের সততা (প্রচুর) কল্যাণ দান করবে; (আর সে কল্যাণ হচ্ছে,) তাদের জন্যে এমন সুরম্য জান্নাত, যার তলদেশ দিয়ে অমীয় ঝর্ণাধারা প্রবাহিত থাকবে, সেখানে তারা চিরদিন থাকবে; আল্লাহ তায়ালা তাদের ওপর সন্তুষ্ট থাকবেন এবং তারাও আল্লাহর ওপর সন্তুষ্ট থাকবে; (বস্তুত) এ হচ্ছে এক মহাসাফল্য।', 'Qala Allahu hatha yawmu yanfaAAu alssadiqeena sidquhum lahum jannatun tajree min tahtiha alanharu khalideena feeha abadan radiya Allahu AAanhum waradoo AAanhu thalika alfawzu alAAatheemu', 1, NOW(), NOW()),
(5, 120, 'لِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا فِيهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرُۢ', 'আকাশমালা, যমীন এবং এর মধ্যবর্তী সমগ্র সৃষ্টিলোকের ভেতর যা কিছু আছে তার সমুদয় বাদশাহী আল্লাহর জন্যেই এবং তিনিই সব কিছুর ওপর ক্ষমতাবান।', 'Lillahi mulku alssamawati waalardi wama feehinna wahuwa AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(11, 1, 'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ', 'সমস্ত প্রশংসা আল্লাহ তায়ালার জন্যে, যিনি আকাশমালা ও ভূমন্ডল পয়দা করেছেন, তিনি অন্ধকারসমূহ ও আলো সৃষ্টি করেছেন; যারা (আল্লাহ তায়ালাকে) অস্বীকার করে, তারা (প্রকারান্তরে অন্য কিছুকেই) তাদের মালিকের সমকক্ষ হিসেবে দাঁড় করায়।', 'Alhamdu lillahi allathee khalaqa alssamawati waalarda wajaAAala alththulumati waalnnoora thumma allatheena kafaroo birabbihim yaAAdiloona', 1, NOW(), NOW()),
(11, 2, 'هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ', 'তিনি তোমাদের মাটি থেকে সৃষ্টি করেছেন, অতপর তিনি (সবার বাঁচার একটি) মেয়াদ নির্দিষ্ট করে দিয়েছেন, (তেমনি তাদের মৃত্যুরও) তাঁর কাছে একটি সুনির্দিষ্ট মেয়াদ রয়েছে, তারপরও তোমরা সন্দেহ করছো!', 'Huwa allathee khalaqakum min teenin thumma qada ajalan waajalun musamman AAindahu thumma antum tamtaroona', 1, NOW(), NOW()),
(11, 3, 'وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ', 'আসমানসমূহ ও যমীনের (সর্বত্র) তিনিই হচ্ছেন একমাত্র আল্লাহ; তিনি (যেমনি) তোমাদের গোপন ও প্রকাশ্য বিষয়সমূহ জানেন, (তেমনি) তিনি জানেন তোমরা (পাপ- পুণ্যের) কতোটুকু উপার্জন করছো- তাও।', 'Wahuwa Allahu fee alssamawati wafee alardi yaAAlamu sirrakum wajahrakum wayaAAlamu ma taksiboona', 1, NOW(), NOW()),
(11, 4, 'وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ', 'তাদের মালিকের আয়াতসমূহের মধ্যে এমন একটি আয়াতও নেই, যা তাদের কাছে আসার পর তারা তা থেকে মুখ ফিরিয়ে নেয়নি।', 'Wama tateehim min ayatin min ayati rabbihim illa kanoo AAanha muAArideena', 1, NOW(), NOW()),
(11, 5, 'فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'তাদের কাছে যতোবারই সত্য (দ্বীন) এসেছে; ততোবারই তারা তাকে মিথ্যা বলেছে; অচিরেই তাদের কাছে সে খবরগুলো এসে উপস্থিত হবে যা নিয়ে তারা বিদ্রুপ করছিলো।', 'Faqad kaththaboo bialhaqqi lamma jaahum fasawfa yateehim anbao ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(11, 6, 'أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ', 'তারা কি দেখেনি, তাদের আগে আমি এমন বহু জাতিকে বিনাশ করে দিয়েছি যাদের আমি পৃথিবীতে এমন প্রতিষ্ঠা দান করেছিলাম, যা তোমাদেরও দান করিনি। আকাশ থেকে তাদের ওপর আমি প্রচুর বৃষ্টি বর্ষণ করেছি, আবার তাদের (মাটির) নীচ থেকে আমি ঝর্ণাধারা প্রবাহিত করে দিয়েছি, অতপর তাদের পাপের কারণে আমি তাদের (চিরতরে) ধ্বংস করে দিয়েছি, আর তাদের পর আমি এক নতুন জাতির উত্থান ঘটিয়েছি।', 'Alam yaraw kam ahlakna min qablihim min qarnin makkannahum fee alardi ma lam numakkin lakum waarsalna alssamaa AAalayhim midraran wajaAAalna alanhara tajree min tahtihim faahlaknahum bithunoobihim waanshana min baAAdihim qarnan akhareena', 1, NOW(), NOW()),
(11, 7, 'وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ', '(হে নবী,) আমি যদি তোমার ওপর কাগজে লেখা কোনো কিতাব নাযিল করতাম এবং তারা যদি তাদের হাত দিয়ে তা স্পর্শও করতো, তারপরও যারা কুফরী করেছে তারা বলতো, এটা তো সুস্পষ্ট যাদু ছাড়া আর কিছুই নয়!', 'Walaw nazzalna AAalayka kitaban fee qirtasin falamasoohu biaydeehim laqala allatheena kafaroo in hatha illa sihrun mubeenun', 1, NOW(), NOW()),
(11, 8, 'وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ', 'তারা বলে, এ (নবী)-র প্রতি কোনো ফেরেশতা নাযিল করা হলো না কেন? যদি সত্যিই আমি কোনো ফেরেশতা পাঠাতাম তাহলে (আযাবের) ফয়সালা (তখনি) হয়ে যেতো, এরপর তো আর কোনো অবকাশই তাদের দেয়া হতো না।', 'Waqaloo lawla onzila AAalayhi malakun walaw anzalna malakan laqudiya alamru thumma la yuntharoona', 1, NOW(), NOW()),
(11, 9, 'وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ', '(তা ছাড়া) আমি যদি (সত্যিই) ফেরেশতা পাঠাতাম, তাকেও তো মানুষ বানিয়েই পাঠাতাম, (আজ) যেমন এরা সন্দেহ করছে তখনও আমি এমনিভাবে তাদের (মনের) ওপর সন্দেহ বসিয়ে দিতাম।', 'Walaw jaAAalnahu malakan lajaAAalnahu rajulan walalabasna AAalayhim ma yalbisoona', 1, NOW(), NOW()),
(11, 10, 'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', '(হে রাসূল,) তোমার আগেও বহু নবী– –রাসূলকে এভাবে ঠাট্টা-বিদ্রূপ করা হয়েছিলো, (অনন্তর) তাদের মধ্যে যারা নবীর সাথে যে ঠাট্টা-বিদ্রূপ করেছে তাই (তাদের আযাবের আকারে) পরিবেষ্টন করে ফেলেছে!', 'Walaqadi istuhzia birusulin min qablika fahaqa biallatheena sakhiroo minhum ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(11, 11, 'قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ', '(হে নবী,) তুমি বলো, তোমরা পৃথিবীতে ঘুরে-ফিরে দেখো, দেখো যারা (নবী-রাসূলদের) মিথ্যা প্রতিপন্ন করেছে তাদের কী (ভয়াবহ) পরিণাম হয়েছে।', 'Qul seeroo fee alardi thumma onthuroo kayfa kana AAaqibatu almukaththibeena', 1, NOW(), NOW()),
(11, 12, 'قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ', '(হে নবী!) তুমি তাদের জিজ্ঞেস করো, আসমানসমূহ ও যমীনে যা আছে তা সব কার? তুমি বলো, (এর সবকিছুই) আল্লাহ তায়ালার জন্যে; (মানুষদের ওপর) দয়া করাটা তিনি তাঁর নিজের ওপর (কর্তব্য বলে) স্থির করে নিয়েছেন; কেয়ামতের দিন তিনি তোমাদের অবশ্যই জড়ো করবেন, এতে সন্দেহ নেই; যারা নিজেরাই নিজেদের ক্ষতি সাধন করেছে, তারা (এই দিনকে) বিশ্বাস করে না।', 'Qul liman ma fee alssamawati waalardi qul lillahi kataba AAala nafsihi alrrahmata layajmaAAannakum ila yawmi alqiyamati la rayba feehi allatheena khasiroo anfusahum fahum la yuminoona', 1, NOW(), NOW()),
(11, 13, '۞وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'রাত ও দিনের মাঝে যা কিছু স্থিতি লাভ করেছে তার সব কিছুই তাঁর জন্যে; তিনি সব শোনেন এবং দেখেন।', 'Walahu ma sakana fee allayli waalnnahari wahuwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(11, 14, 'قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ', '(হে নবী,) তুমি বলো, আমি কিভাবে আসমানসমূহ ও যমীনের মালিক আল্লাহ তায়ালাকে বাদ দিয়ে অন্য কাউকে নিজের পৃষ্ঠপোষক বানিয়ে নেবো, অথচ তিনিই (সবাইকে) আহার যোগান, তাঁকে কোনো রকমের আহার যোগানো যায় না; (তুমি) বলো, আমাকে আদেশ দেয়া হয়েছে, যেন সবার আগে আমি তাঁর অনুগত হই এবং (আমাকে আরো আদেশ দেয়া হয়েছে-) তুমি কখনো মুশরিকদের দলে শামিল হয়ো না।', 'Qul aghayra Allahi attakhithu waliyyan fatiri alssamawati waalardi wahuwa yutAAimu wala yutAAamu qul innee omirtu an akoona awwala man aslama wala takoonanna mina almushrikeena', 1, NOW(), NOW()),
(11, 15, 'قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ', '(তুমি) বলো, আমি যদি আমার মালিকের অবাধ্য হই, তাহলে আমি এক মহাদিবসের আযাব (আপতিত হওয়ার) ভয় করি।', 'Qul innee akhafu in AAasaytu rabbee AAathaba yawmin AAatheemin', 1, NOW(), NOW()),
(11, 16, 'مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ', 'সে মহান দিবসে যাকে সে আযাব থেকে রেহাই দেয়া হবে, তার ওপর (নিসন্দেহে) আল্লাহ তায়ালা অনুগ্রহ করবেন, আর এটিই হচ্ছে সুস্পষ্ট সাফল্য।', 'Man yusraf AAanhu yawmaithin faqad rahimahu wathalika alfawzu almubeenu', 1, NOW(), NOW()),
(11, 17, 'وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'যদি আল্লাহ তায়ালা তোমাকে কোনো দুঃখ পৌঁছান তাহলে তিনি ছাড়া আর কেউই তা দূর করতে পারবে না; অপরদিকে তিনি যদি তোমার কোনো উপকার করেন তাহলে (কেউ তাতে বাধাও দিতে পারে না, কেননা) তিনি সব কিছুর ওপর ক্ষমতাবান!', 'Wain yamsaska Allahu bidurrin fala kashifa lahu illa huwa wain yamsaska bikhayrin fahuwa AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(11, 18, 'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ', 'তিনি তাঁর বান্দাদের ওপর একচ্ছত্র ক্ষমতার অধিকারী; তিনি মহাজ্ঞানী, তিনি সম্যক ওয়াকেফহাল।', 'Wahuwa alqahiru fawqa AAibadihi wahuwa alhakeemu alkhabeeru', 1, NOW(), NOW()),
(11, 19, 'قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ', 'তুমি বলো, সাক্ষী হিসেবে কার সাক্ষ্য সবচেয়ে বড়? তুমি বলো, (হ্যাঁ) একমাত্র আল্লাহ তায়ালার, যিনি তোমাদের এবং আমার মধ্যকার (সর্বোত্তম) সাক্ষী। এ কুরআন (তাঁর কাছ থেকেই) আমার প্রতি নাযিল করা হয়েছে, আমি যেন তা দিয়ে তোমাদের এবং (তোমাদের পর) যাদের কাছে এ গ্রন্থ পৌঁছবে (তাদের আযাবের) ভয় দেখাই; তোমরা কি একথার সাক্ষ্য দিতে পারবে, আল্লাহর সাথে আরো কোনো ইলাহ রয়েছে ? (হে নবী,) তুমি (তাদের) জানিয়ে দাও, আমি (জেনে-বুঝে) কখনো এ ধরনের (মিথ্যা) সাক্ষ্য দিতে পারবো না, তুমি বলো, তিনি একক, তোমরা (আল্লাহ তায়ালার সাথে) যে শিরক করে যাচ্ছো, তার থেকে আমি অবশ্যই মুক্ত।', 'Qul ayyu shayin akbaru shahadatan quli Allahu shaheedun baynee wabaynakum waoohiya ilayya hatha alquranu lionthirakum bihi waman balagha ainnakum latashhadoona anna maAAa Allahi alihatan okhra qul la ashhadu qul innama huwa ilahun wahidun wainnanee bareeon mimma tushrikoona', 1, NOW(), NOW()),
(11, 20, 'ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ', '(তোমার আগে) যাদের আমি কিতাব দান করেছি তারা নবীকে ঠিক সেভাবেই চেনে, যেভাবে তারা তাদের ছেলেদের চেনে, (কিন্তু অজ্ঞতার বশবর্তী হয়ে) যারা নিজেরা নিজেদের ক্ষতি সাধন করেছে তারা (কখনো) ঈমান আনবে না।', 'Allatheena ataynahumu alkitaba yaAArifoonahu kama yaAArifoona abnaahum allatheena khasiroo anfusahum fahum la yuminoona', 1, NOW(), NOW()),
(11, 21, 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ', 'তার চাইতে বড় যালেম আর কে আছে, যে স্বয়ং আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করে; কিংবা তাঁর আয়াতসমূহকে অস্বীকার করে, আসলে যালেমরা কখনো সাফল্য লাভ করে না।', 'Waman athlamu mimmani iftara AAala Allahi kathiban aw kaththaba biayatihi innahu la yuflihu alththalimoona', 1, NOW(), NOW()),
(11, 22, 'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ', 'একদিন আমি তাদের সবাইকে একত্রিত করবো, অতপর যারা শিরক করেছে– তাদের আমি বলবো, তোমাদের সেসব শরীকরা কোথায় (আজ)? কোথায় (তারা) যাদের তোমরা (আমার সাথে শরীক ) মনে করতে!', 'Wayawma nahshuruhum jameeAAan thumma naqoolu lillatheena ashrakoo ayna shurakaokumu allatheena kuntum tazAAumoona', 1, NOW(), NOW()),
(11, 23, 'ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ', 'অতপর তাদের (সেদিন) একথা (বলা) ছাড়া কোনো যুক্তিই থাকবে না যে, আল্লাহ তায়ালার কসম, যিনি আমাদের রব, আমরা কখনো মুশরিক ছিলাম না।', 'Thumma lam takun fitnatuhum illa an qaloo waAllahi rabbina ma kunna mushrikeena', 1, NOW(), NOW()),
(11, 24, 'ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', '(হে নবী,) তুমি দেখো, কিভাবে (আজ) এরা নিজে রাই নিজেদের মিথ্যা প্রতিপন্ন করছে এবং তাদের নিজেদের বানানো কথা (কিভাবে আজ) নিষ্ফল হয়ে যাচ্ছে!', 'Onthur kayfa kathaboo AAala anfusihim wadalla AAanhum ma kanoo yaftaroona', 1, NOW(), NOW()),
(11, 25, 'وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', 'তাদের মধ্যে এমন কিছু লোকও আছে যাকে (দেখলে মনে হয়) তোমার কথা সে কান দিয়ে শুনছে, কিন্তু আসলে) আমি তাদের মনের ওপর পর্দা ঢেলে দিয়েছি, যার কারণে তারা কিছুই উপলব্ধি করতে পারে না, আমি তাদের কানেও ছিপি এঁটে দিয়েছি; (মূলত) তারা যদি (আল্লাহর) সব কয়টি নিদর্শন দেখেও নেয়, তবু তারা তাতে ঈমান আনবে না; এমনকি তারা যখন তোমার সামনে আসবে তখন তোমার সাথে বিতর্কে লিপ্ত হবে, (কুরআনের আয়াত সম্পর্কে) কাফেররা বলবে, এ তো পুরনো দিনের গল্পকথা ছাড়া আর কিছুই নয়।', 'Waminhum man yastamiAAu ilayka wajaAAalna AAala quloobihim akinnatan an yafqahoohu wafee athanihim waqran wain yaraw kulla ayatin la yuminoo biha hatta itha jaooka yujadiloonaka yaqoolu allatheena kafaroo in hatha illa asateeru alawwaleena', 1, NOW(), NOW()),
(11, 26, 'وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ', 'তারা (যেমন) নিজেদের তা (শোনা) থেকে বিরত রাখে, (তেমনি) অন্যদেরও তা থেকে দূরে রাখে, (এ দিয়ে মূলত) তারা নিজেদেরই ধ্বংস সাধন করছে, অথচ তারা কোনো খবরই রাখে না।', 'Wahum yanhawna AAanhu wayanawna AAanhu wain yuhlikoona illa anfusahum wama yashAAuroona', 1, NOW(), NOW()),
(11, 27, 'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ', 'তুমি যদি (সত্যিই তাদের) দেখতে পেতে– যখন এদের আগুনের ওপর এনে দাঁড় করানো হবে, তখন তারা বলবে, হায়! যদি আমাদের আবার (দুনিয়ায়) ফেরত পাঠানো হতো, তাহলে আমরা (আর কখনো) আমাদের মালিকের আয়াতসমূহকে মিথ্যা প্রতিপন্ন করতাম না এবং আমরা (অবশ্যই) ঈমানদার লোকদের দলে শামিল হয়ে যেতাম।', 'Walaw tara ith wuqifoo AAala alnnari faqaloo ya laytana nuraddu wala nukaththiba biayati rabbina wanakoona mina almumineena', 1, NOW(), NOW()),
(11, 28, 'بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ', 'এর আগে যা কিছু তারা গোপন করে আসছিলো (আজ) তা তাদের জন্যে উন্মুক্ত হয়ে গেলো; যদি তাদের আবার দুনিয়ায় ফেরত পাঠানোও হয়, তারা তাই করে বেড়াবে যা থেকে তাদের নিষেধ করা হয়েছিলো, অবশ্যই তারা মিথ্যাবাদী।', 'Bal bada lahum ma kanoo yukhfoona min qablu walaw ruddoo laAAadoo lima nuhoo AAanhu wainnahum lakathiboona', 1, NOW(), NOW()),
(11, 29, 'وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ', 'এরা বলে, আমাদের এ পার্থিব জীবনই হচ্ছে একমাত্র জীবন, আমরা কখনোই পুনরুজ্জীবিত হবো না।', 'Waqaloo in hiya illa hayatuna alddunya wama nahnu bimabAAootheena', 1, NOW(), NOW()),
(11, 30, 'وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ', 'হায়! তুমি যদি (সে দৃশ্য) দেখতে পেতে— যখন তাদেরকে তাদের মালিকের সামনে দাঁড় করানো হবে এবং তিনি বলবেন (বলো), এ (দিন)-টি কি সত্য নয়? তারা বলবে, হ্যাঁ, আমাদের মালিকের শপথ (এটা সত্য); তিনি বলবেন, তাহলে (আজ) সে আযাব ভোগ করো, যাকে তোমরা অবিশ্বাস করতে।', 'Walaw tara ith wuqifoo AAala rabbihim qala alaysa hatha bialhaqqi qaloo bala warabbina qala fathooqoo alAAathaba bima kuntum takfuroona', 1, NOW(), NOW()),
(11, 31, 'قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ', 'অবশ্যই তারা (ভীষণভাবে) ক্ষতিগ্রস্ত হয়ে পড়েছে, যারা আল্লাহর সামনা সামনি হওয়াকে মিথ্যা বলেছে; আর একদিন যখন (সত্যি সত্যিই) কেয়ামতের ঘন্টা হঠাৎ করেই তাদের সামনে এসে উপস্থিত হবে, তখন তারা বলবে, হায় আফসোস, (দুনিয়ায়) এ (দিন)-টিতে আমরা কতো না অবহেলা করেছি, সেদিন তারা নিজেদের (পাপের) বোঝা নিজেদের পিঠেই বয়ে বেড়াবে; (দেখো,) কতো নিকৃষ্ট বোঝা সেটি– যা সেদিন তারা বইবে!', 'Qad khasira allatheena kaththaboo biliqai Allahi hatta itha jaathumu alssaAAatu baghtatan qaloo ya hasratana AAala ma farratna feeha wahum yahmiloona awzarahum AAala thuhoorihim ala saa ma yaziroona', 1, NOW(), NOW()),
(11, 32, 'وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ', 'আর (এ) বৈষয়িক জীবন তো নিছক খেল-তামাশা ছাড়া আর কিছুই নয়; (মূলত) যারা (আল্লাহ তায়ালাকে) ভয় করে পরকালের বাড়িঘরই তাদের জন্যে উৎকৃষ্ট; তোমরা কি (মোটেই) অনুধাবন করো না?', 'Wama alhayatu alddunya illa laAAibun walahwun walalddaru alakhirati khayrun lillatheena yattaqoona afala taAAqiloona', 1, NOW(), NOW()),
(11, 33, 'قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ', '(হে রাসূল,) আমি জানি, এরা যা বলে, তা তোমাকে পীড়া দেয়, (এসব বলে) এরা (শুধু) তোমাকেই মিথ্যা সাব্যস্ত করছে না; বরং এ যালেমরা (এর মাধ্যমে) আল্লাহ তায়ালার আয়াতকেই অস্বীকার করছে।', 'Qad naAAlamu innahu layahzunuka allathee yaqooloona fainnahum la yukaththiboonaka walakinna alththalimeena biayati Allahi yajhadoona', 1, NOW(), NOW()),
(11, 34, 'وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ', 'তোমার আগেও রাসূলদের মিথ্যাবাদী সাব্যস্ত করা হয়েছিলো, কিন্তু তাদের মিথ্যাবাদী সাব্যস্ত করা ও (নানাভাবে) নির্যাতিত হবার পরও তারা ধৈর্য ধারণ করেছে, শেষ পর্যন্ত তাদের কাছে আমার সাহায্য এসে উপস্থিত হয়েছে। (আসলে) আল্লাহর কথা বদল করার কেউ নেই, অবশ্য নবীদের সংবাদ তো তোমার কাছে (আগেই) এসে পৌঁছেছে।', 'Walaqad kuththibat rusulun min qablika fasabaroo AAala ma kuththiboo waoothoo hatta atahum nasruna wala mubaddila likalimati Allahi walaqad jaaka min nabai almursaleena', 1, NOW(), NOW()),
(11, 35, 'وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ', 'কষ্টকর মনে হয়, তাহলে তোমার সাধ্য থাকলে তুমি (পালানোর জন্যে) ভূগর্ভে কোনো সুড়ংগ কিংবা আসমানে কোনো সিঁড়ি তালাশ করো এবং (সেখান থেকে) তাদের জন্যে কোনো নিদর্শন নিয়ে এসো; আল্লাহ তায়ালা যদি চাইতেন, তিনি তাদের সবাইকে হেদায়াতের ওপর জড়ো করে দিতে পারতেন এবং তুমি কখনো মূর্খ লোকদের দলে শামিল হয়ো না।', 'Wain kana kabura AAalayka iAAraduhum faini istataAAta an tabtaghiya nafaqan fee alardi aw sullaman fee alssamai fatatiyahum biayatin walaw shaa Allahu lajamaAAahum AAala alhuda fala takoonanna mina aljahileena', 1, NOW(), NOW()),
(11, 36, '۞إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ', 'যারা (এ কথাগুলো) শোনে, তারা অবশ্যই (আল্লাহর) ডাকে সাড়া দেয়। যারা মরে গেছে আল্লাহ তায়ালা তাদেরকেও কবর থেকে উঠাবেন, অতপর (মহাবিচারের জন্যে) তারা সবাই তাঁর সামনে প্রত্যাবর্তিত হবে।', 'Innama yastajeebu allatheena yasmaAAoona waalmawta yabAAathuhumu Allahu thumma ilayhi yurjaAAoona', 1, NOW(), NOW()),
(11, 37, 'وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', 'এরা বলে, নবীর ওপর তাঁর মালিকের পক্ষ থেকে (আমাদের কথামতো) কোনো নিদর্শন নাযিল করা হয়নি কেন? (হে রাসূল,) তুমি বলো, অবশ্যই আল্লাহ তায়ালা (সব ধরনের) নিদর্শন পাঠানোর ক্ষমতা রাখেন, কিন্তু এদের অধিকাংশ লোকই (এ ব্যাপারে) কিছু জানে না।', 'Waqaloo lawla nuzzila AAalayhi ayatun min rabbihi qul inna Allaha qadirun AAala an yunazzila ayatan walakinna aktharahum la yaAAlamoona', 1, NOW(), NOW()),
(11, 38, 'وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَـٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ', 'যমীনের বুকে বিচরণশীল যে কোনো জন্তু কিংবা বাতাসের বুকে নিজ ডানা দুটি দিয়ে উড়ে চলা যে কোনো পাখী– যারা তোমাদের মতো সৃষ্টি নয়– আমি (এ) গ্রন্থে (তাদের) বর্ণনার কোনো কিছুও বাকী রাখিনি, অতপর এদের সবাইকে তাদের মালিকের কাছে জড়ো করা হবে।', 'Wama min dabbatin fee alardi wala tairin yateeru bijanahayhi illa omamun amthalukum ma farratna fee alkitabi min shayin thumma ila rabbihim yuhsharoona', 1, NOW(), NOW()),
(11, 39, 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'যারা আমার আয়াতসমূহকে মিথ্যা সাব্যস্ত করে, তারা (হেদায়াতের ব্যাপারে) বধির ও মূক, তারা অন্ধকারে পড়ে আছে; আল্লাহ তায়ালা যাকে চান তাকে গোমরাহ করে দেন; আবার যাকে চান তাকে তিনি সঠিক পথের ওপর এনে স্থাপন করেন।', 'Waallatheena kaththaboo biayatina summun wabukmun fee alththulumati man yashai Allahu yudlilhu waman yasha yajAAalhu AAala siratin mustaqeemin', 1, NOW(), NOW()),
(11, 40, 'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ', 'তুমি বলো, তুমি কি তোমাদের (নিজেদের অবস্থা) দেখেছো, যখন তোমাদের ওপর আল্লাহর পক্ষ থেকে কোনো আযাব আসবে, কিংবা হঠাৎ করে কেয়ামত এসে উপস্থিত হবে, তখন তোমরা কি আল্লাহ তায়ালা ছাড়া আর কাউকে ডাকবে? (বলো) যদি তোমরা সত্যবাদী হও!', 'Qul araaytakum in atakum AAathabu Allahi aw atatkumu alssaAAatu aghayra Allahi tadAAoona in kuntum sadiqeena', 1, NOW(), NOW()),
(11, 41, 'بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ', 'বরং তোমরা (তো তখন) শুধু তাঁকেই ডাকবে, তোমরা যে জন্যে তাঁকে ডাকবে তিনি চাইলে তা দূর করে দিবেন (এবং) যাদের তোমরা (আল্লাহ তায়ালার) অংশীদার বানাতে, তাদের তোমরা ভুলে যাবে।', 'Bal iyyahu tadAAoona fayakshifu ma tadAAoona ilayhi in shaa watansawna ma tushrikoona', 1, NOW(), NOW()),
(11, 42, 'وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ', 'তোমার আগের জাতিসমূহের কাছেও আমি আমার রাসূল পাঠিয়েছিলাম, তাদেরও আমি নানা দুঃখ-কষ্ট ও বিপর্যয়ে আটকে রেখেছিলাম, যাতে করে তারা বিনয়ের সাথে নতি স্বীকার করে।', 'Walaqad arsalna ila omamin min qablika faakhathnahum bialbasai waalddarrai laAAallahum yatadarraAAoona', 1, NOW(), NOW()),
(11, 43, 'فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ', 'যদি এমন হতো যে, তাদের ওপর আমার বিপর্যয় এসে আপতিত হলো, তারা বিনীত হয়ে গেলো, কিন্তু তাদের অন্তর (এতে) আরো শক্ত হয়ে গেলো এবং তারা যা করে যাচ্ছিলো, শয়তান তাদের কাছে তা শোভনীয় করে তুলে ধরছিলো।', 'Falawla ith jaahum basuna tadarraAAoo walakin qasat quloobuhum wazayyana lahumu alshshaytanu ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(11, 44, 'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ', 'অতপর তারা সে সব কিছুই ভুলে গেলো, যা তাদের (বার বার) স্মরণ করানো হয়েছিলো; তারপরও আমি তাদের ওপর (সচ্ছলতার) সব কয়টি দুয়ারই খুলে দিলাম; শেষ পর্যন্ত যখন তারা তাতেই মত্ত হয়ে গেলো যা তাদের দেয়া হয়েছিলো, তখন আমি তাদের হঠাৎ পাকড়াও করে নিলাম, তারা সাথে সাথে নিরাশ হয়ে পড়লো।', 'Falamma nasoo ma thukkiroo bihi fatahna AAalayhim abwaba kulli shayin hatta itha farihoo bima ootoo akhathnahum baghtatan faitha hum mublisoona', 1, NOW(), NOW()),
(11, 45, 'فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', 'যারা (আল্লাহ তায়ালার ব্যাপারে) যুলুম করেছে, তাদের সবার মূলোচ্ছেদ করে দেয়া হয়েছে; আর সকল প্রশংসা আল্লাহ তায়ালার জন্যেই, যিনি সৃষ্টিকুলের মালিক।', 'FaqutiAAa dabiru alqawmi allatheena thalamoo waalhamdu lillahi rabbi alAAalameena', 1, NOW(), NOW()),
(11, 46, 'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ', '(হে রাসূল) তুমি বলো, তোমরা কি একথা ভেবে দেখেছো, যদি আল্লাহ তায়ালা কখনো তোমাদের শোনার ও দেখার ক্ষমতা কেড়ে নেন এবং তোমাদের অন্তরসমূহের ওপর মোহর মেরে দেন, তবে আল্লাহ তায়ালা ছাড়া দ্বিতীয় কোনো ইলাহ আছে কি, যে তোমাদের এসব কিছু ফিরিয়ে দিতে পারবে; তাকিয়ে দেখো কিভাবে আমি আমার আয়াতসমূহ খুলে খুলে বর্ণনা করছি, এ সত্ত্বেও তারা মুখ ফিরিয়ে নিচ্ছে।', 'Qul araaytum in akhatha Allahu samAAakum waabsarakum wakhatama AAala quloobikum man ilahun ghayru Allahi yateekum bihi onthur kayfa nusarrifu alayati thumma hum yasdifoona', 1, NOW(), NOW()),
(11, 47, 'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّـٰلِمُونَ', 'তুমি বলো, তোমরা কি তাদের দেখেছো, যদি কখনো গোপনে কিংবা প্রকাশ্যভাবে তোমাদের ওপর আল্লাহর আযাব আপতিত হয়, (তাতে) কতিপয় যালেম সম্প্রদায়ের লোক ব্যতীত অন্য কাউকে ধ্বংস করা হবে কি?', 'Qul araaytakum in atakum AAathabu Allahi baghtatan aw jahratan hal yuhlaku illa alqawmu alththalimoona', 1, NOW(), NOW()),
(11, 48, 'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'আমি রাসূলদের (জান্নাতের) সুসংবাদবাহী ও (জাহান্নামের) সতর্ককারী ছাড়া অন্যভাবে পাঠাই না, অতপর যে ব্যক্তি ঈমান আনবে এবং নিজেকে সংশোধন করে নেবে, তাদের কোনো ভয় নেই এবং তারা (সেদিন) কোনোরকম চিন্তাও করবে না।', 'Wama nursilu almursaleena illa mubashshireena wamunthireena faman amana waaslaha fala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(11, 49, 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ', '(অপরদিকে) যারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করবে, কঠোর আযাব তাদের ঘিরে ধরবে, কেননা তারা (আমার সাথে) নাফরমানী করছিলো।', 'Waallatheena kaththaboo biayatina yamassuhumu alAAathabu bima kanoo yafsuqoona', 1, NOW(), NOW()),
(11, 50, 'قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ', '(হে মুহাম্মদ,) তুমি বলো, আমি তো তোমাদের (একথা) বলি না যে, আমার কাছে আল্লাহ তায়ালার বিপুল ধনভান্ডার রয়েছে, না (একথা বলি যে,) আমি গায়বের কোনো খবর রাখি! একথাও বলি না যে, আমি একজন ফেরেশতা, (আসলে) আমি তো সেই ওহীরই অনুসরণ করি যা আমার ওপর নাযিল করা হয়, তুমি বলো, অন্ধ আর চক্ষুষ্মান ব্যক্তি কি (কখনো) এক হতে পারে? তোমরা কি মোটেই চিন্তাভাবনা করো না?', 'Qul la aqoolu lakum AAindee khazainu Allahi wala aAAlamu alghayba wala aqoolu lakum innee malakun in attabiAAu illa ma yooha ilayya qul hal yastawee alaAAma waalbaseeru afala tatafakkaroona', 1, NOW(), NOW()),
(11, 51, 'وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ', '(হে মুহাম্মদ,) তুমি (আল্লাহর) কিতাবের মাধ্যমে সেসব লোকদের (আযাবের) সতর্ক করো, যারা এ ভয় করে যে, তাদেরকে তাদের মালিকের সামনে একত্র করা হবে, (সেদিন) তাদের জন্যে তিনি ছাড়া কোনো বন্ধু কিংবা কোনো সুপারিশকারী থাকবে না, আশা করা যায় তারা সাবধান হবে।', 'Waanthir bihi allatheena yakhafoona an yuhsharoo ila rabbihim laysa lahum min doonihi waliyyun wala shafeeAAun laAAallahum yattaqoona', 1, NOW(), NOW()),
(11, 52, 'وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ', 'তাদের তুমি (তোমার কাছ থেকে) সরিয়ে দিয়ো না– যারা সকাল-সন্ধ্যায় তাদের মালিককে ডাকে, তাঁরই সন্তুষ্টি কামনা করে, (কারণ) তাদের কাজকর্মের কোনো রকম দায়িত্বই তোমার ওপর নেই, তোমার কাজকর্মের হিসাব– কিতাবের কোনো রকম দায়িত্বও তাদের ওপর নেই, যদি তুমি তাদের সরিয়ে দাও, তাহলে তুমিও যালেমদের দলে শামিল হয়ে যাবে।', 'Wala tatrudi allatheena yadAAoona rabbahum bialghadati waalAAashiyyi yureedoona wajhahu ma AAalayka min hisabihim min shayin wama min hisabika AAalayhim min shayin fatatrudahum fatakoona mina alththalimeena', 1, NOW(), NOW()),
(11, 53, 'وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّـٰكِرِينَ', 'আর আমি এভাবেই তাদের একদল দ্বারা অন্য দলের পরীক্ষা নিয়েছি, যেন (অহংকারী) লোকেরা (গরীবদের একথা) বলতে পারে যে, এরাই কি হচ্ছে আমাদের মাঝে সে দলের লোক, যাদের ওপর আল্লাহ তায়ালা অনুগ্রহ করেছেন; আল্লাহ তায়ালা কি (তাঁর) কৃতজ্ঞ বান্দাদের ভালো করে জানেন না?', 'Wakathalika fatanna baAAdahum bibaAAdin liyaqooloo ahaolai manna Allahu AAalayhim min baynina alaysa Allahu biaAAlama bialshshakireena', 1, NOW(), NOW()),
(11, 54, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ', 'যারা আমার আয়াতসমূহের ওপর ঈমান এনেছে তারা যখন তোমার কাছে আসবে, তখন তুমি তাদের বলো, তোমাদের ওপর শান্তি বর্ষিত হোক— তোমাদের ওপর অনুগ্রহ করাটা তোমাদের রব নিজের কর্তব্য বলে স্থির করে নিয়েছেন, তবে তোমাদের মধ্যে যদি কেউ কখনো অজ্ঞতাবশত কোনো অন্যায় কাজ করে বসে এবং পরক্ষণেই তাওবা করে ও (নিজেকে) শুধরে নেয়, তাহলে (আল্লাহ তায়ালা তাকে ক্ষমা করে দিবেন,) তিনি একান্ত ক্ষমাশীল ও পরম দয়ালু।', 'Waitha jaaka allatheena yuminoona biayatina faqul salamun AAalaykum kataba rabbukum AAala nafsihi alrrahmata annahu man AAamila minkum sooan bijahalatin thumma taba min baAAdihi waaslaha faannahu ghafoorun raheemun', 1, NOW(), NOW()),
(11, 55, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ', 'আর এভাবেই আমি আমার আয়াতসমূহকে বিশদভাবে বর্ণনা করি, যাতে করে (অন্যদের সামনে) অপরাধীদের পথ পরিষ্কার হয়ে যায়।', 'Wakathalika nufassilu alayati walitastabeena sabeelu almujrimeena', 1, NOW(), NOW()),
(11, 56, 'قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ', '(হে মুহাম্মদ,) তুমি বলো, আল্লাহ তায়ালাকে বাদ দিয়ে তোমরা আর যাদের ডাকো, আমাকে তাদের গোলামী করতে নিষেধ করা হয়েছে; তুমি (এও) বলো, আমি কখনো তোমাদের খেয়াল-খুশীর অনুসরণ করবো না, (তেমনটি করলে) আমি গোমরাহ হয়ে যাবো এবং আমি আর সত্যের অনুসরণকারীদের অন্তর্ভুক্ত থাকবো না।', 'Qul innee nuheetu an aAAbuda allatheena tadAAoona min dooni Allahi qul la attabiAAu ahwaakum qad dalaltu ithan wama ana mina almuhtadeena', 1, NOW(), NOW()),
(11, 57, 'قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ', 'তুমি বলো, আমি অবশ্যই আমার মালিকের এক উজ্জ্বল দলীল-প্রমাণের ওপর প্রতিষ্ঠিত আছি, আর সে জিনিসটাই তোমরা অস্বীকার করছো, যা তোমরা দ্রুত (দেখতে) চাও তা (ঘটানোর ক্ষমতা) আমার নেই; (সব কিছুর) চূড়ান্ত ক্ষমতা কেবলমাত্র আল্লাহ তায়ালার হাতেই রয়েছে; (আর এ সত্যটাই) তিনি (এখানে) বর্ণনা করছেন, তিনি হচ্ছেন উত্তম ফয়সালাকারী।', 'Qul innee AAala bayyinatin min rabbee wakaththabtum bihi ma AAindee ma tastaAAjiloona bihi ini alhukmu illa lillahi yaqussu alhaqqa wahuwa khayru alfasileena', 1, NOW(), NOW()),
(11, 58, 'قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّـٰلِمِينَ', 'তুমি বলো, (আযাবের) যে বিষয়টার জন্যে তোমরা তাড়াহুড়ো করছো, তা (ঘটানো) যদি আমার ক্ষমতার মধ্যে থাকতো, তাহলে তোমাদের ও আমার মধ্যকার ফয়সালা (তো অনেক আগেই) হয়ে যেতো! আল্লাহ তায়ালা যালেমদের ভালো করেই জানেন।', 'Qul law anna AAindee ma tastaAAjiloona bihi laqudiya alamru baynee wabaynakum waAllahu aAAlamu bialththalimeena', 1, NOW(), NOW()),
(11, 59, '۞وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ', 'গায়বের চাবিগুলো সব তাঁর হাতেই নিবদ্ধ রয়েছে, সে খবর তিনি ছাড়া কারোই জানা নেই; জলে-স্থলে (যেখানে) যা কিছু আছে তা শুধু তিনিই জানেন; (গাছের) একটি পাতা (কোথাও) ঝরে না, যা তিনি জানেন না, মাটির অন্ধকারে একটি শস্যকণাও নেই– নেই কোনো তাজা সবুজ, (কিংবা ক্ষয়িষ্ণু) শুকনো (কিছু), যার বিবরণ একটি সুস্পষ্ট গ্রন্থে মজুদ নেই।', 'WaAAindahu mafatihu alghaybi la yaAAlamuha illa huwa wayaAAlamu ma fee albarri waalbahri wama tasqutu min waraqatin illa yaAAlamuha wala habbatin fee thulumati alardi wala ratbin wala yabisin illa fee kitabin mubeenin', 1, NOW(), NOW()),
(11, 60, 'وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', 'তিনিই (মহান আল্লাহ), যিনি রাতের বেলা তোমাদের ওপর মৃত্যু ছেয়ে দেন, দিনের বেলায় তোমরা যা কিছু করো তা তিনি জানেন। (রাতের পর) তিনি আবার তোমাদের উঠিয়ে দেন, যাতে করে (তোমাদের) নির্দিষ্ট সময়কাল পূর্ণতা পেতে পারে, এরপর তাঁর দিকেই হচ্ছে তোমাদের ফিরে যাবার জায়গা, অতপর তিনি তোমাদের বলে দিবেন তোমরা (দুনিয়ায়) কী কাজ করছিলে।', 'Wahuwa allathee yatawaffakum biallayli wayaAAlamu ma jarahtum bialnnahari thumma yabAAathukum feehi liyuqda ajalun musamman thumma ilayhi marjiAAukum thumma yunabbiokum bima kuntum taAAmaloona', 1, NOW(), NOW()),
(11, 61, 'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ', 'আল্লাহ তায়ালা নিজ বান্দাদের ওপর পূর্ণ মাত্রায় কর্তৃত্বশীল, তিনি তোমাদের ওপর পাহারাদার (ফেরেশতা) নিযুক্ত করেন; এভাবে তোমাদের কারো যখন মৃত্যু এসে উপস্থিত হয়, তখন প্রেরিত ফেরেশতারা তার (জীবনের) সমাপ্তি ঘটিয়ে দেয়, (দায়িত্ব পালনে) তারা কখনো কোনও ভুল করে না।', 'Wahuwa alqahiru fawqa AAibadihi wayursilu AAalaykum hafathatan hatta itha jaa ahadakumu almawtu tawaffathu rusuluna wahum la yufarritoona', 1, NOW(), NOW()),
(11, 62, 'ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ', 'অতপর তাদের সবাইকে তাদের (আসল) মালিক আল্লাহর সামনে ফিরিয়ে নেয়া হবে; সাবধান! যাবতীয় ক্ষমতা ও কর্তৃত্ব কিন্তু একা তাঁর । ত্বরিৎ হিসাব গ্রহণে তিনি অত্যন্ত তৎপর।', 'Thumma ruddoo ila Allahi mawlahumu alhaqqi ala lahu alhukmu wahuwa asraAAu alhasibeena', 1, NOW(), NOW()),
(11, 63, 'قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', 'তুমি বলো, যখন তোমরা স্থলভূমে ও সমুদ্রের অন্ধকারে (বিপদে) পড়ো, (যখন) তোমরা কাতর কণ্ঠে এবং নীরবে তাঁকেই ডাকতে থাকো, তখন কে তোমাদের (সেসব থেকে) উদ্ধার করে? (কাকে তোমরা তখন) বলো, (হে মালিক), আমাদের তুমি যদি এ থেকে বাঁচিয়ে দাও, তাহলে আমরা তোমার কৃতজ্ঞ বান্দাদের দলে শামিল হয়ে যাবো।', 'Qul man yunajjeekum min thulumati albarri waalbahri tadAAoonahu tadarruAAan wakhufyatan lain anjana min hathihi lanakoonanna mina alshshakireena', 1, NOW(), NOW()),
(11, 64, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ', 'তুমি বলো, হ্যাঁ, আল্লাহ তায়ালাই তোমাদের সে (অবস্থা) থেকে এবং অন্য সব বিপদ-আপদ থেকে বাঁচিয়ে দেন, তারপরও তোমরাই তাঁর সাথে অন্যদের শরীক করো!', 'Quli Allahu yunajjeekum minha wamin kulli karbin thumma antum tushrikoona', 1, NOW(), NOW()),
(11, 65, 'قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ', 'তুমি বলো, আল্লাহ তায়ালা তোমাদের ওপর– তোমাদের ওপর থেকে অথবা তোমাদের পায়ের নীচ থেকে আযাব পাঠাতে সক্ষম, অথবা তিনি তোমাদের দল-উপদলে বিভক্ত করে একদলকে আরেক দলের শাস্তির স্বাদ গ্রহণ করাতেও সম্পূর্ণরূপে সক্ষম; লক্ষ্য করো, কিভাবে আমি আমার আয়াতসমূহকে খুলে খুলে বর্ণনা করি, আশা করা যায়, তারা (সত্য) অনুধাবন করতে পারবে।', 'Qul huwa alqadiru AAala an yabAAatha AAalaykum AAathaban min fawqikum aw min tahti arjulikum aw yalbisakum shiyaAAan wayutheeqa baAAdakum basa baAAdin onthur kayfa nusarrifu alayati laAAallahum yafqahoona', 1, NOW(), NOW()),
(11, 66, 'وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ', 'তোমার জাতির লোকেরা এ (কুরআন)-কে অস্বীকার করেছে, অথচ তাই হচ্ছে একমাত্র সত্য; তুমি (তাদের) বলে দাও, আমি তোমাদের ওপর কর্মবিধায়ক নই।', 'Wakaththaba bihi qawmuka wahuwa alhaqqu qul lastu AAalaykum biwakeelin', 1, NOW(), NOW()),
(11, 67, 'لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ', 'প্রতিটি বার্তার জন্যে একটি সুনির্দিষ্ট দিনক্ষণ মজুদ রয়েছে এবং তোমরা অচিরেই (তা) জানতে পারবে।', 'Likulli nabain mustaqarrun wasawfa taAAlamoona', 1, NOW(), NOW()),
(11, 68, 'وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'তুমি যখন এমন সব লোককে দেখতে পাও যারা আমার আয়াতসমূহ নিয়ে হাসি-বিদ্রূপ করছে, তখন তুমি তাদের কাছ থেকে সরে এসো, যতোক্ষণ না তারা অন্য কথায় মনোনিবেশ করে; যদি কখনো শয়তান তোমাকে ভুলিয়ে (ওখানে বসিয়ে রাখে, তাহলে মনে পড়ার পর তুমি যালেম সম্প্রদায়ের সাথে আর বসে থেকো না।', 'Waitha raayta allatheena yakhoodoona fee ayatina faaAArid AAanhum hatta yakhoodoo fee hadeethin ghayrihi waimma yunsiyannaka alshshaytanu fala taqAAud baAAda alththikra maAAa alqawmi alththalimeena', 1, NOW(), NOW()),
(11, 69, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ', 'তাদের (এসব কার্যকলাপের) হিসাবের ব্যাপারে– যারা (আল্লাহ তায়ালাকে ভয় করে, তাদের ওপর কোনো দায়-দায়িত্ব নেই, তবে উপদেশ (তো দিয়েই যেতে হবে), আশা করা যায়, তারা (একদিন আল্লাহ তায়ালাকে) ভয় করবে।', 'Wama AAala allatheena yattaqoona min hisabihim min shayin walakin thikra laAAallahum yattaqoona', 1, NOW(), NOW()),
(11, 70, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ', 'সেসব লোকদের তুমি (আল্লাহর হাতে) ছেড়ে দাও, যারা তাদের দ্বীনকে নিছক খেল-তামাশায় পরিণত করে রেখেছে এবং এ পার্থিব জীবন যাদের প্রতারণার জালে আটকে রেখেছে, তুমি এ (কুরআন) দিয়ে (তাদের) স্মরণ করাতে থাকো, যাতে করে কেউ নিজের অর্জিত কর্মকান্ডের ফলে ধ্বংস হয়ে যেতে না পারে, (হাশরের দিন) তার জন্যে আল্লাহ তায়ালা ছাড়া কোনো বন্ধু এবং সুপারিশকারী থাকবে না, কোনো ব্যক্তি যদি নিজের সব কিছু দিয়েও দেয়, তবু তার কাছ থেকে (সেদিন তা) গ্রহণ করা হবে না; এরাই হচ্ছে সে মানুষ, যাদের নিজেদের (গুনাহ) অর্জনের কারণে তাদের ধ্বংস করে দেয়া হবে, (আল্লাহ তায়ালাকে) অস্বীকার করার কারণে তাদের জন্যে (থাকবে) ফুটন্ত পানি ও মারাত্মক শাস্তি।', 'Wathari allatheena ittakhathoo deenahum laAAiban walahwan wagharrathumu alhayatu alddunya wathakkir bihi an tubsala nafsun bima kasabat laysa laha min dooni Allahi waliyyun wala shafeeAAun wain taAAdil kulla AAadlin la yukhath minha olaika allatheena obsiloo bima kasaboo lahum sharabun min hameemin waAAathabun aleemun bima kanoo yakfuroona', 1, NOW(), NOW()),
(11, 71, 'قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ', 'তুমি বলো, আমরা কি আল্লাহ তায়ালাকে বাদ দিয়ে এমন কাউকে ডাকবো, যে- না আমাদের কোনো ক্ষতি করতে পারে, না আমাদের কোনো অপকার করতে পারে, আল্লাহ তায়ালা যেখানে আমাদের সঠিক পথ বাতলে দিয়েছেন, সেখানে তাঁকে বাদ দিয়ে আমরা কি আমাদের উল্টো পায়ে ফিরে যাবো- ঠিক সে ব্যক্তিটির মতো, যাকে শয়তানরা যমীনের বুকে পথভ্রষ্ট করে দ্বারে দ্বারে ঠোকর খাওয়াচ্ছে, অথচ তার সংগী-সাথীরা তাকে ডাকছে, তুমি আমাদের কাছে এসো, (এসো) সহজ সরল পথের দিকে! তুমি বলো, সত্যিকার অর্থে হেদায়াত তো হচ্ছে আল্লাহ তায়ালার (পাঠানো), সেটাই হচ্ছে আসল হেদায়াত এবং আমাদের এ আদেশ দেয়া হয়েছে যেন আমরা সৃষ্টিকুলের মালিকের সামনে আনুগত্যের মাথা নত করি,', 'Qul anadAAoo min dooni Allahi ma la yanfaAAuna wala yadurruna wanuraddu AAala aAAqabina baAAda ith hadana Allahu kaallathee istahwathu alshshayateenu fee alardi hayrana lahu ashabun yadAAoonahu ila alhuda itina qul inna huda Allahi huwa alhuda waomirna linuslima lirabbi alAAalameena', 1, NOW(), NOW()),
(11, 72, 'وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ', '(আরো আদেশ দেয়া হয়েছে) তোমরা যেন নামায প্রতিষ্ঠা করো এবং তোমরা যেন আল্লাহ তায়ালাকে ভয় করো; তিনি হচ্ছেন এমন (সত্তা), যাঁর সামনে সবাইকে সমবেত করা হবে।', 'Waan aqeemoo alssalata waittaqoohu wahuwa allathee ilayhi tuhsharoona', 1, NOW(), NOW()),
(11, 73, 'وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ', 'তিনি যথাযথভাবে আসমানসমূহ ও যমীন সৃষ্টি করেছেন; যেদিন তিনি বলবেন (সব কিছু বিলীন) হয়ে যাও, তখন (সাথে সাথেই) তা (বিলীন) হয়ে যাবে, তাঁর কথাই হচ্ছে চূড়ান্ত সত্য, যেদিন শিংগায় ফুঁ দেয়া হবে (সেদিন) যাবতীয় কর্তৃত্ব ও বাদশাহী হবে একান্তই তাঁর; তিনি দৃশ্য-অদৃশ্য সব কিছু সম্পর্কেই সম্যক অবগত রয়েছেন; তিনি প্রজ্ঞাময়, তিনি সবকিছুর খবর রাখেন।', 'Wahuwa allathee khalaqa alssamawati waalarda bialhaqqi wayawma yaqoolu kun fayakoonu qawluhu alhaqqu walahu almulku yawma yunfakhu fee alssoori AAalimu alghaybi waalshshahadati wahuwa alhakeemu alkhabeeru', 1, NOW(), NOW()),
(11, 74, '۞وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ', '(স্মরণ করো,) যখন ইবরাহীম তার পিতা আযরকে বললো, তুমি কি (সত্যি সত্যিই এই) মূর্তিগুলোকে মাবুদ হিসেবে গ্রহণ করছো? আমি তো দেখতে পাচ্ছি, তুমি ও তোমার সম্প্রদায়ের লোকেরা স্পষ্ট গোমরাহীতে নিমজ্জিত রয়েছো।', 'Waith qala ibraheemu liabeehi azara atattakhithu asnaman alihatan innee araka waqawmaka fee dalalin mubeenin', 1, NOW(), NOW()),
(11, 75, 'وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ', 'এভাবেই আমি ইবরাহীমকে আকাশসমূহ ও যমীনের পরিচালন ব্যবস্থা দেখাচ্ছিলাম, যেন সে বিশ্বাসীদের দলে শামিল হয়ে যেতে পারে।', 'Wakathalika nuree ibraheema malakoota alssamawati waalardi waliyakoona mina almooqineena', 1, NOW(), NOW()),
(11, 76, 'فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ', 'যখন তার ওপর (আঁধার ছেয়ে) রাত এলো, তখন সে একটি তারকা দেখতে পেলো, (তারকাটি দেখেই) সে বলে উঠলো, এ (বুঝি) আমার রব, অতপর যখন তারকাটি ডুবে গেলো, তখন সে বললো, যা ডুবে যায় তাকে তো আমি (আমার রব বলে) পছন্দ করতে পারি না!', 'Falamma janna AAalayhi allaylu raa kawkaban qala hatha rabbee falamma afala qala la ohibbu alafileena', 1, NOW(), NOW()),
(11, 77, 'فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ', 'অতপর যখন সে (আকাশে) একটি ঝলমলে চাঁদ দেখলো, তখন বললো (হ্যাঁ), এ-ই (মনে হয়) আমার রব, অতপর (এক পর্যায়ে) যখন তাও ডুবে গেলো তখন সে বললো, আমার ‘রব’ যদি আমাকে সঠিক পথ না দেখান, তাহলে অবশ্যই আমি গোমরাহ লোকদের দলে শামিল হয়ে যাবো।', 'Falamma raa alqamara bazighan qala hatha rabbee falamma afala qala lain lam yahdinee rabbee laakoonanna mina alqawmi alddalleena', 1, NOW(), NOW()),
(11, 78, 'فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ', '(এরপর দিনের বেলায়) সে যখন একটি আলোকোজ্জ্বল সূর্য দেখলো তখন সে বললো, (মনে হচ্ছে) এই আমার রব, (কারণ) এটা হচ্ছে সবগুলোর চাইতে বড়, (সন্ধ্যা ঘনিয়ে এলে) তাও যখন ডুবে গেলো, তখন সে (নিজের জাতিকে) বললো, হে আমার সম্প্রদায়ের লোকেরা, তোমরা যে সব কিছুকে (আল্লাহ তায়ালার সাথে) অংশীদার বানাও, আমি তা থেকে সম্পূর্ণ মুক্ত।', 'Falamma raa alshshamsa bazighatan qala hatha rabbee hatha akbaru falamma afalat qala ya qawmi innee bareeon mimma tushrikoona', 1, NOW(), NOW()),
(11, 79, 'إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ', 'আমি নিষ্ঠার সাথে সেই সার্বভৌম মালিকের দিকেই আমার মুখ ফিরিয়ে নিচ্ছি, যিনি এই আসমানসমূহ ও যমীন (-সহ চাঁদ-সুরুজ-গ্রহ-তারা সব কিছু) পয়দা করেছেন, আমি এখন আর মুশরিকদের দলভুক্ত নই।', 'Innee wajjahtu wajhiya lillathee fatara alssamawati waalarda haneefan wama ana mina almushrikeena', 1, NOW(), NOW()),
(11, 80, 'وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَـٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ', 'তার জাতির লোকেরা তার সাথে (আল্লাহ তায়ালার ব্যাপারে) বিতর্ক শুরু করলো; (জবাবে) সে বললো, তোমরা কি আমার সাথে স্বয়ং আল্লাহ তায়ালার ব্যাপারেই তর্ক করছো, অথচ তিনিই আমাকে সঠিক পথের দিশা দিয়েছেন; আমি তোমাদের (মাবুদদের) ডরাই না– যাদের তোমরা (আল্লাহ তায়ালার) অংশীদার (মনে) করো, অবশ্য আমার মালিক যদি অন্য কিছু চান (সেটা আলাদা); আমার মালিকের জ্ঞান সব কিছুর ওপর পরিব্যাপ্ত; (এরপরও) কি তোমরা সতর্ক হবে না?', 'Wahajjahu qawmuhu qala atuhajjoonnee fee Allahi waqad hadani wala akhafu ma tushrikoona bihi illa an yashaa rabbee shayan wasiAAa rabbee kulla shayin AAilman afala tatathakkaroona', 1, NOW(), NOW()),
(11, 81, 'وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ', 'তোমরা যাকে (আল্লাহ তায়ালার) অংশীদার বানাও, তাকে আমি কিভাবে ভয় করবো, অথচ তোমরা আল্লাহ তায়ালার সাথে অন্যদের শরীক করতে ভয় পাও না, যে ব্যাপারে তিনি কোনো প্রমাণপত্র তোমাদের কাছে পাঠাননি; (তোমরাই বলো,) আমাদের এ উভয় দলের মধ্যে কোন দলটি (দুনিয়া ও আখেরাতে) নিরাপত্তালাভের বেশী অধিকারী? (বলো!) যদি তোমরা জানো!', 'Wakayfa akhafu ma ashraktum wala takhafoona annakum ashraktum biAllahi ma lam yunazzil bihi AAalaykum sultanan faayyu alfareeqayni ahaqqu bialamni in kuntum taAAlamoona', 1, NOW(), NOW()),
(11, 82, 'ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَـٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ', '(হ্যাঁ) যারা ঈমান এনেছে এবং যারা তাদের ঈমানকে যুলুম (-এর কালিমা) দিয়ে কখনো কলুষিত করেনি, তারাই (হচ্ছে দুনিয়া ও আখেরাতে) নিরাপত্তালাভের বেশী অধিকারী, (এবং) তারাই হচ্ছে হেদায়াতপ্রাপ্ত।', 'Allatheena amanoo walam yalbisoo eemanahum bithulmin olaika lahumu alamnu wahum muhtadoona', 1, NOW(), NOW()),
(11, 83, 'وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ', 'এ ছিলো (শিরক সম্পর্কিত) আমার (সেই অকাট্য) যুক্তি, যা আমি ইবরাহীমকে তার জাতির ওপর দান করেছিলাম; (এভাবেই) আমি যাকে ইচ্ছা তাকে সমুন্নত করি; অবশ্যই তোমার রব প্রবল প্রজ্ঞাময়, কুশলী।', 'Watilka hujjatuna ataynaha ibraheema AAala qawmihi narfaAAu darajatin man nashao inna rabbaka hakeemun AAaleemun', 1, NOW(), NOW()),
(11, 84, 'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ', 'আমি তাকে দান করেছি (পুত্র হিসেবে) ইসহাক ও (পৌত্র হিসেবে) ইয়াকুব– এদের সবাইকেই আমি সঠিক পথের দিশা দিয়েছিলাম, (এদের) আগে আমি নূহকেও হেদায়াতের পথ দেখিয়েছি এবং তার বংশের মাঝে দাউদ, সোলায়মান, আইয়ুব, ইউসুফ, মূসা এবং হারুনকেও (আমি হেদায়াত দান করেছি); আর এভাবেই আমি সৎকর্মশীলদের পুরস্কার দিয়ে থাকি।', 'Wawahabna lahu ishaqa wayaAAqooba kullan hadayna wanoohan hadayna min qablu wamin thurriyyatihi dawooda wasulaymana waayyooba wayoosufa wamoosa waharoona wakathalika najzee almuhsineena', 1, NOW(), NOW()),
(11, 85, 'وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّـٰلِحِينَ', 'যাকারিয়া, ইয়াহইয়া, ঈসা এবং ইলিয়াসকেও (আমি সঠিক পথ দেখিয়েছিলাম); এরা সবাই ছিলো নেককারদের দলভুক্ত।', 'Wazakariyya wayahya waAAeesa wailyasa kullun mina alssaliheena', 1, NOW(), NOW()),
(11, 86, 'وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ', 'আমি ইসমাঈল, ইয়াসা, ইউনুস এবং লূতকেও (সৎপথ দেখিয়েছিলাম), এদের সবাইকেই আমি (নবুওত দিয়ে) সৃষ্টিকুলের ওপর বিশেষ মর্যাদা দান করেছিলাম।', 'WaismaAAeela wailyasaAAa wayoonusa walootan wakullan faddalna AAala alAAalameena', 1, NOW(), NOW()),
(11, 87, 'وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّـٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'এদের পূর্বপুরুষ, এদের পরবর্তী বংশধর ও এদের ভাই (বন্ধু)দেরও (আমি নানাভাবে পুরস্কৃত করেছি), আমি এদেরকে বাছাই করে নিয়েছি এবং আমি এদের সবাইকে সরল পথে পরিচালিত করেছি।', 'Wamin abaihim wathurriyyatihim waikhwanihim waijtabaynahum wahadaynahum ila siratin mustaqeemin', 1, NOW(), NOW()),
(11, 88, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ', 'এই হচ্ছে আল্লাহ তায়ালার হেদায়াত, নিজ বান্দাদের মাঝে যাকে চান আল্লাহ তায়ালা তাকে হেদায়াত দান করেন; (কিন্তু) তারা যদি (আল্লাহর সাথে) শিরক করতো, তাহলে তাদের যাবতীয় কর্ম অবশ্যই নিষ্ফল হয়ে যেতো।', 'Thalika huda Allahi yahdee bihi man yashao min AAibadihi walaw ashrakoo lahabita AAanhum ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(11, 89, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَـٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ', 'এরাই ছিলো সেসব লোক, যাদের আমি কিতাব, প্রজ্ঞা ও নবুওত দান করেছি, (এরপরও) যদি তারা তা অস্বীকার করে (তাহলে জেনে রেখো), আমি তো (অতীতেও) এমন এক সম্প্রদায়ের ওপর এ দায়িত্ব অর্পণ করেছিলাম, যারা কখনো (এগুলো) প্রত্যাখ্যান করেনি।', 'Olaika allatheena ataynahumu alkitaba waalhukma waalnnubuwwata fain yakfur biha haolai faqad wakkalna biha qawman laysoo biha bikafireena', 1, NOW(), NOW()),
(11, 90, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ', 'এরা হচ্ছে সে সব (সৌভাগ্যবান) বান্দা— আল্লাহ তায়ালা যাদের সৎপথে পরিচালিত করেছেন; অতএব তুমিও এদের হেদায়াতের পথের অনুসরণ করো (এবং) বলো, আমি এর ওপর তোমাদের কাছ থেকে কোনো পারিশ্রমিক চাই না; (আসলে) এ হচ্ছে মানুষের জন্যে একটি স্মরণিকা মাত্র।', 'Olaika allatheena hada Allahu fabihudahumu iqtadih qul la asalukum AAalayhi ajran in huwa illa thikra lilAAalameena', 1, NOW(), NOW()),
(11, 91, 'وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ', 'তারা আল্লাহ তায়ালাকে তাঁর যথাযোগ্য মূল্যায়ন করতে পারেনি, (বিশেষ করে) যখন তারা বললো, আল্লাহ তায়ালা কোনো মানুষের ওপর কোনো বস্তুই নাযিল করেননি; তুমি বলো, মূসার আনীত কিতাব– যা মানুষের জন্যে ছিলো এক আলোকবর্তিকা ও পথনির্দেশ, যা তোমরা কাগজের (পাতায় লিখে রাখতে, যা তোমরা মানুষের সামনে প্রকাশ করতে এবং (তার) অধিকাংশই গোপন করে রাখতে, (সর্বোপরি) সে কিতাব দ্বারা তোমাদের এমন সব জ্ঞান শিক্ষা দেয়া হতো, যার কিছুই তোমরা এবং তোমাদের পূর্বপুরুষরা জানতে না– তা কে নাযিল করেছেন? তুমি বলো (হ্যাঁ,) আল্লাহ তায়ালাই (তা নাযিল করেছেন), (হে নবী,) তুমি তাদের নিরর্থক আলোচনায় মত্ত থাকতে দাও।', 'Wama qadaroo Allaha haqqa qadrihi ith qaloo ma anzala Allahu AAala basharin min shayin qul man anzala alkitaba allathee jaa bihi moosa nooran wahudan lilnnasi tajAAaloonahu qarateesa tubdoonaha watukhfoona katheeran waAAullimtum ma lam taAAlamoo antum wala abaokum quli Allahu thumma tharhum fee khawdihim yalAAaboona', 1, NOW(), NOW()),
(11, 92, 'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ', 'এটি এক বরকতপূর্ণ গ্রন্থ, যা আমি (তোমার ওপর) নাযিল করেছি, এটি আগের কিতাবের সত্যায়ন করে এবং যাতে এ (কিতাব) দিয়ে তুমি মক্কা ও তার পার্শ্ববর্তী (জনপদসমূহের) মানুষকে সাবধান করবে; যারা আখেরাতের ওপর ঈমান আনে তারা এ কিতাবের ওপরও ঈমান আনে, আর তারা তাদের নামাযেরও হেফাজত করে।', 'Wahatha kitabun anzalnahu mubarakun musaddiqu allathee bayna yadayhi walitunthira omma alqura waman hawlaha waallatheena yuminoona bialakhirati yuminoona bihi wahum AAala salatihim yuhafithoona', 1, NOW(), NOW()),
(11, 93, 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَـٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ', 'সে ব্যক্তির চাইতে বড় যালেম আর কে আছে যে আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করে, অথবা বলে, আমার ওপর ওহী নাযিল হয়েছে, (যদিও) তার ওপর কিছুই নাযিল করা হয়নি, (তার চাইতেই বা বড় যালেম কে,) যে বলে, আমি অচিরেই আল্লাহর নাযিল করা গ্রন্থের মতো কিছু নাযিল করে দেখাবো! যদি (সত্যি সত্যিই) যালেমদের মৃত্যু-যন্ত্রণা (উপস্থিত) হবার সময়টা তুমি দেখতে পেতে! যখন (মৃত্যুর) ফেরেশতারা তাদের দিকে হাত বাড়িয়ে বলবে, তোমাদের প্রাণবায়ু বের করে দাও; তোমরা আল্লাহ তায়ালা সম্পর্কে যেসব অন্যায় কথা বলতে এবং তাঁর ব্যাপারে যে (ক্ষমাহীন) ঔদ্ধত্য প্রকাশ করতে, তার বিনিময়ে আজ অত্যন্ত অবমাননাকর এক আযাব তোমাদের দেয়া হবে।', 'Waman athlamu mimmani iftara AAala Allahi kathiban aw qala oohiya ilayya walam yooha ilayhi shayon waman qala saonzilu mithla ma anzala Allahu walaw tara ithi alththalimoona fee ghamarati almawti waalmalaikatu basitoo aydeehim akhrijoo anfusakumu alyawma tujzawna AAathaba alhooni bima kuntum taqooloona AAala Allahi ghayra alhaqqi wakuntum AAan ayatihi tastakbiroona', 1, NOW(), NOW()),
(11, 94, 'وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَـٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ', '(আজ) তোমরা আমার সামনে নিসঙ্গ অবস্থায় এলে, যেমনি নিসঙ্গ অবস্থায় আমি তোমাদের প্রথমবার সৃষ্টি করেছিলাম, অতপর তোমাদের আমি যা কিছু (বিষয় সম্পদ) দান করেছি, তার সবটুকুই তোমরা পেছনে ফেলে এসেছো, তোমাদের সাথে তোমাদের সুপারিশকারী ব্যক্তিদের– যাদের তোমরা মনে করতে তারা তোমাদের (কাজকর্মের) মাঝে অংশীদার– (কই) তাদের তো (আজ) তোমাদের মাঝে দেখতে পাচ্ছি না! বস্তুত তাদের এবং তোমাদের মধ্যকার সেই সম্পর্ক ছিন্ন ভিন্ন হয়ে গেছে এবং তাদের ব্যাপারে তোমরা যা ধারণা করতে তাও আজ নিষ্ফল হয়ে গেছে।', 'Walaqad jitumoona furada kama khalaqnakum awwala marratin wataraktum ma khawwalnakum waraa thuhoorikum wama nara maAAakum shufaAAaakumu allatheena zaAAamtum annahum feekum shurakao laqad taqattaAAa baynakum wadalla AAankum ma kuntum tazAAumoona', 1, NOW(), NOW()),
(11, 95, '۞إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ', 'অবশ্যই আল্লাহ তায়ালা শস্যবীজ ও আঁটিগুলো অঙ্কুরিত করেন, তিনি নির্জীব (কিছু) থেকে জীবন্ত (কিছু) বের করে আনেন, (আবার) তিনিই জীবন্ত (কিছু) থেকে নির্জীব (কিছু) নির্গত করেন; এই হচ্ছেন আল্লাহ তায়ালা, (এরপরও) তোমাদের কোথায় কোথায় ঠোকর খাওয়ানো হচ্ছে!', 'Inna Allaha faliqu alhabbi waalnnawa yukhriju alhayya mina almayyiti wamukhriju almayyiti mina alhayyi thalikumu Allahu faanna tufakoona', 1, NOW(), NOW()),
(11, 96, 'فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ', '(রাতের শেষে) তিনিই ঊষার উন্মেষ ঘটান, তিনি রাতকে তোমাদের বিশ্রামের জন্যে বানিয়েছেন এবং (দিন তারিখের) হিসাব কিতাবের জন্যে তিনি চাঁদ ও সুরুজ বানিয়েছেন, এসব কিছুই হচ্ছে পরাক্রমশালী ও মহাজ্ঞানী আল্লাহ তায়ালার নির্ধারণ করা।', 'Faliqu alisbahi wajaAAala allayla sakanan waalshshamsa waalqamara husbanan thalika taqdeeru alAAazeezi alAAaleemi', 1, NOW(), NOW()),
(11, 97, 'وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ', 'তিনি তোমাদের জন্যে অসংখ্য তারকা বানিয়ে রেখেছেন যেন তোমরা তা দিয়ে জলে-স্থলের আঁধারে পথের দিশা পেতে পারো, যে সম্প্রদায়ের লোকেরা (এসব রহস্যের কথা) জানে, তাদের জন্যে আমি আমার নিদর্শনসমূহ খুলে খুলে বর্ণনা করেছি।', 'Wahuwa allathee jaAAala lakumu alnnujooma litahtadoo biha fee thulumati albarri waalbahri qad fassalna alayati liqawmin yaAAlamoona', 1, NOW(), NOW()),
(11, 98, 'وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ', 'তিনি তোমাদের মাত্র একটি ব্যক্তিসত্তা থেকে পয়দা করেছেন, অতপর (এখানে তোমাদের) থাকার ও মালসামান রাখার জায়গা (বানানো) হলো, জ্ঞানী লোকদের জন্যে আমি আমার নিদর্শনগুলোকে (এভাবেই) বিস্তারিত বর্ণনা করেছি।', 'Wahuwa allathee anshaakum min nafsin wahidatin famustaqarrun wamustawdaAAun qad fassalna alayati liqawmin yafqahoona', 1, NOW(), NOW()),
(11, 99, 'وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّـٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ', 'তিনি আসমান থেকে পানি (-র ধারা) নাযিল করেন, অতপর সে পানি দিয়ে আমি সব রকমের উদ্ভিদ (ও গাছপালা) জন্মানোর ব্যবস্থা করি, তা থেকে সবুজ শ্যামল পাতা উদগত করি, (পরে) তা থেকে আমি পরস্পর জড়ানো ঘন শস্যদানা সৃষ্টি করি এবং (ফলের) ভারে নুয়ে পড়া খেজুরের গোছা বের করে আনি, আংগুরের উদ্যানমালা, জলপাই ও আনার পয়দা করি, এগুলো একে অন্যের সদৃশ হয়, আবার (একটার সাথে) আরেকটার গরমিলও থাকে; গাছ যখন সুশোভিত হয় তখন (এক সময়) তা ফলবান হয়, যখন ফলগুলো পাকতে শুরু করে, তখন তোমরা এই সৃষ্টি-নৈপুণ্য দেখো; অবশ্যই এতে ঈমানদার লোকদের জন্যে বহু নিদর্শন রয়েছে।', 'Wahuwa allathee anzala mina alssamai maan faakhrajna bihi nabata kulli shayin faakhrajna minhu khadiran nukhriju minhu habban mutarakiban wamina alnnakhli min talAAiha qinwanun daniyatun wajannatin min aAAnabin waalzzaytoona waalrrummana mushtabihan waghayra mutashabihin onthuroo ila thamarihi itha athmara wayanAAihi inna fee thalikum laayatin liqawmin yuminoona', 1, NOW(), NOW()),
(11, 100, 'وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', 'তারা জ্বিনকে আল্লাহর সাথে শরীক মনে করে, অথচ জ্বিনদের তিনিই পয়দা করেছেন, অজ্ঞতার বশবর্তী হয়ে তারা তাঁর ওপর পুত্র-কন্যা ধারণের অপবাদও আনয়ন করে, অথচ তিনি মহিমান্বিত, এরা যা বলে তিনি তার চাইতে অনেক মহান ও পবিত্র।', 'WajaAAaloo lillahi shurakaa aljinna wakhalaqahum wakharaqoo lahu baneena wabanatin bighayri AAilmin subhanahu wataAAala AAamma yasifoona', 1, NOW(), NOW()),
(11, 101, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'তিনি আসমানসমূহ ও যমীনের (একক) উদ্ভাবক । (তুমি বলো তাঁর সন্তান হবে কি ভাবে, তাঁর (তো) সঙ্গিনীই নেই, সব কিছু তিনিই পয়দা করেছেন এবং সব কিছু সম্পর্কে তিনি পুরোপুরিই ওয়াকেফহাল রয়েছেন।', 'BadeeAAu alssamawati waalardi anna yakoonu lahu waladun walam takun lahu sahibatun wakhalaqa kulla shayin wahuwa bikulli shayin AAaleemun', 1, NOW(), NOW()),
(11, 102, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ', 'আল্লাহ তায়ালা – তোমাদের রব, তিনি ছাড়া আর কোনো মাবুদ নেই, সব কিছুর স্রষ্টা (তিনি), সুতরাং তোমরা তাঁরই এবাদাত করো, সব কিছুর ওপর তিনিই তত্ত্বাবধায়ক।', 'Thalikumu Allahu rabbukum la ilaha illa huwa khaliqu kulli shayin faoAAbudoohu wahuwa AAala kulli shayin wakeelun', 1, NOW(), NOW()),
(11, 103, 'لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ', 'কোনো দৃষ্টিই তাঁকে দেখতে পায় না, (অথচ) তিনি সব কিছুই দেখতে পান, তিনি সূক্ষ্মদর্শী, তিনি সব কিছুর খোঁজ-খবর রাখেন।', 'La tudrikuhu alabsaru wahuwa yudriku alabsara wahuwa allateefu alkhabeeru', 1, NOW(), NOW()),
(11, 104, 'قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ', 'তোমাদের কাছে তোমাদের মালিকের পক্ষ থেকে (সূক্ষ্ম ও দৃষ্টিসম্পন্ন) নিদর্শন এসেছে, অতপর যদি কোনো ব্যক্তি (তা) দেখতে পায়, তাহলে সে দেখবে তার নিজের (কল্যাণের) জন্যেই, আবার যদি কেউ (তা না দেখে) অন্ধ হয়ে থাকে, তাহলে তার দায়িত্ব তার ওপরই (বর্তাবে। তুমি বলো); আমি তোমাদের ওপর তত্ত্বাবধায়ক নই।', 'Qad jaakum basairu min rabbikum faman absara falinafsihi waman AAamiya faAAalayha wama ana AAalaykum bihafeethin', 1, NOW(), NOW()),
(11, 105, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ', 'আমি এভাবেই আমার আয়াতগুলো বর্ণনা করি, যাতে করে তারা (একথা) বলতে পারে, তুমি (ভালো করেই এসব) পড়ে এসেছো এবং যারা জ্ঞানী তাদের জন্যেও যেন আমি তা সুস্পষ্ট করে দিতে পারি।', 'Wakathalika nusarrifu alayati waliyaqooloo darasta walinubayyinahu liqawmin yaAAlamoona', 1, NOW(), NOW()),
(11, 106, 'ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ', '(হে মুহাম্মদ,) তুমি শুধু তারই অনুসরণ করো যা তোমার মালিকের কাছ থেকে তোমার কাছে নাযিল করা হয়েছে, তিনি ছাড়া অন্য কোনো মাবুদ নেই, যারা শিরকে লিপ্ত, তাদের তুমি এড়িয়ে চলো।', 'IttabiAA ma oohiya ilayka min rabbika la ilaha illa huwa waaAArid AAani almushrikeena', 1, NOW(), NOW()),
(11, 107, 'وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ', 'আল্লাহ তায়ালা যদি চাইতেন, তাহলে এরা কেউই শিরক করতো না; আমি (কিন্তু) তোমাকে তাদের ওপর পাহারাদার নিযুক্ত করে পাঠাইনি, তুমি তো তাদের ওপর কোনো অভিভাবকও নও।', 'Walaw shaa Allahu ma ashrakoo wama jaAAalnaka AAalayhim hafeethan wama anta AAalayhim biwakeelin', 1, NOW(), NOW()),
(11, 108, 'وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ', 'তারা আল্লাহ তায়ালার বদলে যাদের ডাকে, তোমরা তাদের গালি-গালাজ করো না, নইলে তারা শত্রুতার বশবর্তী হয়ে— না জেনে আল্লাহ তায়ালাকে গালি দিবে; এভাবেই আমি প্রত্যেক জাতির কাছে তাদের নিজেদের কার্যকলাপ সুশোভন করে রেখেছি, অতপর তাদের ফিরে যাবার জায়গা হলো তাদের মালিকের কাছে, (তারপর) তিনি তাদের বলে দিবেন, তারা (দুনিয়ায়) কি করে এসেছে।', 'Wala tasubboo allatheena yadAAoona min dooni Allahi fayasubboo Allaha AAadwan bighayri AAilmin kathalika zayyanna likulli ommatin AAamalahum thumma ila rabbihim marjiAAuhum fayunabbiohum bima kanoo yaAAmaloona', 1, NOW(), NOW()),
(11, 109, 'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ', 'এরা আল্লাহর নামে কঠিন শপথ করে বলে, যদি তাদের কাছে কোনো নিদর্শন আসে, তাহলে অবশ্যই তারা তার ওপর ঈমান আনবে; তুমি বলো, নিদর্শন পাঠানো (সম্পূর্ণত) আল্লাহ তায়ালার ব্যাপার, তুমি কি জানো যে, নিদর্শন এলেও এরা কিন্তু ঈমান আনবে না।', 'Waaqsamoo biAllahi jahda aymanihim lain jaathum ayatun layuminunna biha qul innama alayatu AAinda Allahi wama yushAAirukum annaha itha jaat la yuminoona', 1, NOW(), NOW()),
(11, 110, 'وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', 'আমি তাদের অন্তকরণ ও দৃষ্টিশক্তিকে (অন্যদিকে) ফিরিয়ে দিবো, যেমন তারা প্রথম বারেই এ (কুরআনের) ওপর ঈমান আনেনি এবং আমি (এবার) তাদের অবাধ্যতার আবর্তে ঘুরপাক খাওয়ার জন্যে ছেড়ে দিবো!', 'Wanuqallibu afidatahum waabsarahum kama lam yuminoo bihi awwala marratin wanatharuhum fee tughyanihim yaAAmahoona', 1, NOW(), NOW()),
(11, 111, '۞وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ', 'আমি যদি তাদের কাছে (আমার) ফেরেশতাদেরও নাযিল করি, মৃত ব্যক্তিরাও যদি (কবর থেকে উঠে এসে) তাদের সাথে কথা বলতে শুরু করে এবং আমি যদি (দুনিয়ার) সমুদয় বস্তুও এনে তাদের ওপর জড়ো করে দেই, তবু এরা ঈমান আনবে না, অবশ্য যদি আল্লাহ তায়ালা (ভিন্ন কিছু) চান (তা আলাদা। আসলে), এদের অধিকাংশ ব্যক্তিই মূর্খতার আচরণ করে।', 'Walaw annana nazzalna ilayhimu almalaikata wakallamahumu almawta wahasharna AAalayhim kulla shayin qubulan ma kanoo liyuminoo illa an yashaa Allahu walakinna aktharahum yajhaloona', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(11, 112, 'وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ', 'আমি এভাবেই প্রত্যেক নবীর জন্যে (তাদের যুগে) মানুষ ও জ্বীনদের থেকে (কিছু কিছু) দুশমন বানিয়ে রেখেছি, যারা প্রতারণা করার উদ্দেশে একে অন্যকে চমকপ্রদ কথা বলে, তোমার রব চাইলে তারা এটা করতো না, তুমি তাদের ছেড়ে দাও, তারা যা পারে মিথ্যা রচনা করে বেড়াক!', 'Wakathalika jaAAalna likulli nabiyyin AAaduwwan shayateena alinsi waaljinni yoohee baAAduhum ila baAAdin zukhrufa alqawli ghurooran walaw shaa rabbuka ma faAAaloohu fatharhum wama yaftaroona', 1, NOW(), NOW()),
(11, 113, 'وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ', '(এটা এ জন্যে যে,) যারা শেষ বিচারের দিনের ওপর ঈমান রাখে না, তাদের মন এর ফলে শয়তানের প্রতি অনুরাগী হয়ে পড়ে, যেন তারা তার ব্যাপারে সন্তুষ্ট থাকতে পারে, (সর্বোপরি) তারা যেসব কুকর্ম চালিয়ে যাচ্ছিলো, এর ফলে নির্বিঘ্নে তারা তাও চালিয়ে যেতে পারে।', 'Walitasgha ilayhi afidatu allatheena la yuminoona bialakhirati waliyardawhu waliyaqtarifoo ma hum muqtarifoona', 1, NOW(), NOW()),
(11, 114, 'أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ', '(তুমি বলো,) আমি কি আল্লাহ তায়ালা ছাড়া অন্য কোনো ফয়সালাকারী সন্ধান করবো, (অথচ) তিনিই হচ্ছেন সেই মহান সত্তা, যিনি (এই বিচার ফয়সালার জন্যে) তোমাদের কাছে সবিস্তারে কিতাব নাযিল করেছেন; (আগে) যাদের আমি আমার কিতাব দান করেছিলাম তারা জানে, তোমার মালিকের পক্ষ থেকে সত্য বাণী নিয়েই এটা নাযিল করা হয়েছে, অতএব তুমি কখনো সন্দিহানদের অন্তর্ভুক্ত হয়ো না।', 'Afaghayra Allahi abtaghee hakaman wahuwa allathee anzala ilaykumu alkitaba mufassalan waallatheena ataynahumu alkitaba yaAAlamoona annahu munazzalun min rabbika bialhaqqi fala takoonanna mina almumtareena', 1, NOW(), NOW()),
(11, 115, 'وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'ন্যায় ও ইনসাফ (-এর আলোকে) তোমার মালিকের কথাগুলো পরিপূর্ণ হয়ে গেছে এবং তাঁর কথা পরিবর্তন করার কেউ নেই, তিনি সব শোনেন সব জানেন।', 'Watammat kalimatu rabbika sidqan waAAadlan la mubaddila likalimatihi wahuwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(11, 116, 'وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ', '(হে মুহাম্মদ,) তুমি যদি দুনিয়ার অধিকাংশ মানুষের কথা মেনে চলো, তাহলে তারা তোমাকে আল্লাহ তায়ালার পথ থেকে বিচ্যুত করে ছাড়বে; (কেননা) এরা নিছক কিছু আন্দাজ অনুমান ছাড়া আর কিছুরই অনুসরণ করে না, এবং এরা মিথ্যা ছাড়া অন্য কিছু বলেও না।', 'Wain tutiAA akthara man fee alardi yudillooka AAan sabeeli Allahi in yattabiAAoona illa alththanna wain hum illa yakhrusoona', 1, NOW(), NOW()),
(11, 117, 'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ', 'নিসন্দেহে তোমার মালিক (এ কথা) ভালো করেই জানেন– কে তাঁর পথ ছেড়ে বিপথগামী হচ্ছে, (আবার) কে সঠিক পথের অনুসারী– তাও তিনি সম্যক অবগত রয়েছেন।', 'Inna rabbaka huwa aAAlamu man yadillu AAan sabeelihi wahuwa aAAlamu bialmuhtadeena', 1, NOW(), NOW()),
(11, 118, 'فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ', 'তোমরা (শুধু) সেসব (জন্তুর গোশত) খাবে, যার ওপর (জবাইর সময়) আল্লাহ তায়ালার নাম নেয়া হয়েছে, যদি তোমরা আল্লাহ তায়ালার আয়াতে বিশ্বাসী হও!', 'Fakuloo mimma thukira ismu Allahi AAalayhi in kuntum biayatihi mumineena', 1, NOW(), NOW()),
(11, 119, 'وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ', 'তোমাদের এ কি হয়েছে! তোমরা সেসব জন্তুর গোশত) কেন খাবে না, যার ওপর (জবাই করার সময়) আল্লাহ তায়ালার নাম নেয়া হয়েছে, (বিশেষ করে যখন তিনি খুলে খুলে বর্ণনা করেছেন যে, তিনি তোমাদের ওপর কোন কোন বস্তু হারাম করেছেন– সে কথা অবশ্যই আলাদা– যখন তোমাদের তার জন্যে একান্ত বাধ্য করা হয় । অধিকাংশ মানুষ সুষ্ঠু জ্ঞান ছাড়াই নিজেদের খেয়াল– খুশীমতো (অন্যদের) বিপথে চালিত করে; নিসন্দেহে তোমার রব সীমালংঘনকারীদের ভালো করেই জানেন।', 'Wama lakum alla takuloo mimma thukira ismu Allahi AAalayhi waqad fassala lakum ma harrama AAalaykum illa ma idturirtum ilayhi wainna katheeran layudilloona biahwaihim bighayri AAilmin inna rabbaka huwa aAAlamu bialmuAAtadeena', 1, NOW(), NOW()),
(11, 120, 'وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ', 'তোমরা প্রকাশ্য গুনাহ থেকে বেঁচে থাকো, (বেঁচে থাকো) তার গোপন অংশ থেকেও; অবশ্যই যারা কোনো গুনাহ অর্জন করবে, অচিরেই তাদের কৃতকর্মের যথাযথ ফল তাদের প্রদান করা হবে।', 'Watharoo thahira alithmi wabatinahu inna allatheena yaksiboona alithma sayujzawna bima kanoo yaqtarifoona', 1, NOW(), NOW()),
(11, 121, 'وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ', '(জবাইর সময়) যার ওপর আল্লাহ তায়ালার নাম নেয়া হয়নি, সে (জন্তুর গোশত) তোমরা কখনো খাবে না, (কেননা) তা হচ্ছে জঘন্য গুনাহের কাজ; অবশ্যই শয়তানরা তাদের সংগী-সাথীদের মনে প্ররোচনা দেয়, যেন তারা তোমাদের সাথে (এ নিয়ে) তর্ক বিতর্ক করে, যদি তোমরা তাদের কথা মেনে চলো, তাহলে অবশ্যই তোমরা মুশরিক হয়ে যাবে।', 'Wala takuloo mimma lam yuthkari ismu Allahi AAalayhi wainnahu lafisqun wainna alshshayateena layoohoona ila awliyaihim liyujadilookum wain ataAAtumoohum innakum lamushrikoona', 1, NOW(), NOW()),
(11, 122, 'أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ', 'যে ব্যক্তি (এক সময়) ছিলো মৃত, অতপর আমি তাকে জীবিত করলাম, (তদুপরি) তার জন্যে এমন এক আলোকবর্তিকাও আমি বানিয়ে দিলাম, যার (আলো) দিয়ে মানুষের মাঝে সে চলতে পারছে, সে কি কখনো সে ব্যক্তির মতো হতে পারে, যে এমন অন্ধকারে (পড়ে) আছে, যেখান থেকে সে (কোনোক্রমেই) বেরিয়ে আসতে পারছে না; এভাবেই কাফেরদের জন্যে তাদের কর্মকাণ্ডকে শোভনীয় (ও সুখকর) বানিয়ে রাখা হয়েছে।', 'Awa man kana maytan faahyaynahu wajaAAalna lahu nooran yamshee bihi fee alnnasi kaman mathaluhu fee alththulumati laysa bikharijin minha kathalika zuyyina lilkafireena ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(11, 123, 'وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ', 'এভাবে আমি প্রত্যেক জনপদে তার বড় বড় কিছু অপরাধী বানিয়ে রেখেছি, যেন তারা সেখানে (অন্যদের) ধোকা দিতে পারে; (আসলে) এসব কিছুর মাধ্যমে তারা তাদের নিজেদেরই প্রতারিত করছে, অথচ তারা নিজেরা এ কথাটা মোটেই উপলব্ধি করছে না।', 'Wakathalika jaAAalna fee kulli qaryatin akabira mujrimeeha liyamkuroo feeha wama yamkuroona illa bianfusihim wama yashAAuroona', 1, NOW(), NOW()),
(11, 124, 'وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ', 'তাদের কাছে যখনি (আল্লাহর) কোনো আয়াত আসে তখন তারা বলে, আমরা এর ওপর কখনো ঈমান আনবো না, যতোক্ষণ না আমাদেরও তাই দেয়া হয় যা আল্লাহর রাসূলদের দেয়া হয়েছে। (অথচ) আল্লাহ তায়ালা ভালো করেই জানেন তাঁর রেসালাত তিনি কোথায় রাখবেন; যারা (এ) অপরাধ করেছে তারা অচিরেই আল্লাহর কাছে অপমান ও কঠিন আযাবের সম্মুখীন হবে, কেননা তারা (আল্লাহ তায়ালার সাথে) প্রতারণা করছিলো।', 'Waitha jaathum ayatun qaloo lan numina hatta nuta mithla ma ootiya rusulu Allahi Allahu aAAlamu haythu yajAAalu risalatahu sayuseebu allatheena ajramoo sagharun AAinda Allahi waAAathabun shadeedun bima kanoo yamkuroona', 1, NOW(), NOW()),
(11, 125, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ', 'আল্লাহ তায়ালা যদি কাউকে সৎপথে পরিচালিত করতে চান, তাহলে তিনি তার হৃদয় ইসলামের জন্যে খুলে দেন, (আবার) যদি চান কাউকে বিপথগামী করবেন তাহলে তার হৃদয়কে তিনি সংকীর্ণ করে দেন, (এ অবস্থায় তার পক্ষে ইসলামের অনুসরণ করা এমন কঠিন হয়) যেন কোনো একজন ব্যক্তি আকাশে চড়তে চাইছে; আর যারা (আল্লাহর ওপর) বিশ্বাস করে না, আল্লাহ তায়ালা এভাবেই তাদের ওপর (অপমান, লাঞ্ছনা ও) নাপাকী ছেয়ে দেন।', 'Faman yuridi Allahu an yahdiyahu yashrah sadrahu lilislami waman yurid an yudillahu yajAAal sadrahu dayyiqan harajan kaannama yassaAAAAadu fee alssamai kathalika yajAAalu Allahu alrrijsa AAala allatheena la yuminoona', 1, NOW(), NOW()),
(11, 126, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ', '(মূলত) এটিই হচ্ছে তোমার মালিকের (দেখানো) সহজ সরল পথ; আমি অবশ্যই আমার আয়াতসমূহকে উপদেশ গ্রহণে আগ্রহীদের জন্যে বিশদভাবে বর্ণনা করেছি।', 'Wahatha siratu rabbika mustaqeeman qad fassalna alayati liqawmin yaththakkaroona', 1, NOW(), NOW()),
(11, 127, '۞لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ', 'তাদের মালিকের কাছে রয়েছে (তাদের) জন্যে শান্তির এক সুন্দর নিবাস, আল্লাহ্ তায়ালাই তাদের অভিভাবক, (দুনিয়ায়) তারা যা করতো এটা হচ্ছে তারই বিনিময়।', 'Lahum daru alssalami AAinda rabbihim wahuwa waliyyuhum bima kanoo yaAAmaloona', 1, NOW(), NOW()),
(11, 128, 'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ', 'যেদিন তিনি তাদের সবাইকে একত্রিত করবেন, (তখন তিনি শয়তানরূপী জ্বিনদের বলবেন,) হে জ্বিন সম্প্রদায়, তোমরা তো অনেক মানুষকেই গোমরাহ করেছো, (এ সময়) মানুষের ভেতর থেকে (যারা) তাদের বন্ধু (তারা) বলবে, হে আমাদের রব, আমাদের একজন একেকজনকে (ব্যবহার করে) দুনিয়ার জীবনে প্রচুর লাভ কামিয়েছে, আর এভাবেই আমরা চূড়ান্ত সময়ে এসে উপস্থিত হয়েছি, যা তুমি আমাদের জন্যে নির্দিষ্ট করে রেখেছিলে; আল্লাহ তায়ালা বলবেন, (হ্যাঁ, সে জন্যেই আজ) তোমাদের ঠিকানা (হবে জাহান্নামের) আগুন, সেখানে তোমরা চিরকাল থাকবে, অবশ্য আল্লাহ তায়ালা যা কিছু চাইবেন (তা আলাদা); তোমার মালিক অবশ্যই প্রজ্ঞাময়, সম্যক অবহিত।', 'Wayawma yahshuruhum jameeAAan ya maAAshara aljinni qadi istakthartum mina alinsi waqala awliyaohum mina alinsi rabbana istamtaAAa baAAduna bibaAAdin wabalaghna ajalana allathee ajjalta lana qala alnnaru mathwakum khalideena feeha illa ma shaa Allahu inna rabbaka hakeemun AAaleemun', 1, NOW(), NOW()),
(11, 129, 'وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّـٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ', 'এভাবে আমি একদল যালেমকে তাদেরই (অন্যায়) কার্যকলাপের দরুন আরেক দল (যালেম)-এর ওপর ক্ষমতাবান করে দেই।', 'Wakathalika nuwallee baAAda alththalimeena baAAdan bima kanoo yaksiboona', 1, NOW(), NOW()),
(11, 130, 'يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ', '(আল্লাহ তায়ালা সেদিন আরো বলবেন,) হে জ্বিন ও মানুষ সম্প্রদায়, তোমাদের কাছে কি তোমাদেরই মধ্য থেকে আমার (এমন) সব রাসূল আসেনি, যারা আমার আয়াতগুলো তোমাদের কাছে বর্ণনা করতো, (উপরন্তু যারা তোমাদের আজকের এ দিনের ভয় দেখাতো ; (জবাবে) ওরা বলবে, হ্যাঁ (এসেছিলো, তবে আজ) আমরা আমাদের নিজেদের বিরুদ্ধেই সাক্ষ্য দিচ্ছি, (মূলত) দুনিয়ার জীবন এদের প্রতারিত করে রেখেছিলো, তারা নিজেদের বিরুদ্ধেই একথার সাক্ষ্য দিবে যে, তারা (আসলেই) কাফের ছিলো।', 'Ya maAAshara aljinni waalinsi alam yatikum rusulun minkum yaqussoona AAalaykum ayatee wayunthiroonakum liqaa yawmikum hatha qaloo shahidna AAala anfusina wagharrathumu alhayatu alddunya washahidoo AAala anfusihim annahum kanoo kafireena', 1, NOW(), NOW()),
(11, 131, 'ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ', 'এটা এ জন্যে, তোমার রব অন্যায়ভাবে এমন কোনো জনপদের মানুষকে কখনো ধ্বংস করেন না, যার অধিবাসীরা (সত্য দ্বীন সম্পর্কে) সম্পূর্ণ উদাসীন থাকে।', 'Thalika an lam yakun rabbuka muhlika alqura bithulmin waahluha ghafiloona', 1, NOW(), NOW()),
(11, 132, 'وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ', 'তাদের নিজ নিজ কর্ম অনুযায়ী প্রতিটি ব্যক্তির জন্যেই (তার) মর্যাদা রয়েছে, তোমার রব তাদের কাজকর্ম সম্পর্কে উদাসীন নন৷', 'Walikullin darajatun mimma AAamiloo wama rabbuka bighafilin AAamma yaAAmaloona', 1, NOW(), NOW()),
(11, 133, 'وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ', 'তোমার রব কারো মুখাপেক্ষী নন, দয়া অনুগ্রহের মালিক তিনি; তিনি যদি চান তাহলে তোমাদেরকে (এই জনপদ থেকে) সরিয়ে নিতে পারেন এবং তোমাদের পরে অন্য যাদের তিনি চান এখানে বসিয়েও দিতে পারেন, যেমনি করে (এক সময়) তিনি তোমাদেরও অন্য সম্প্রদায়ের বংশধর থেকে উত্থান ঘটিয়েছেন।', 'Warabbuka alghaniyyu thoo alrrahmati in yasha yuthhibkum wayastakhlif min baAAdikum ma yashao kama anshaakum min thurriyyati qawmin akhareena', 1, NOW(), NOW()),
(11, 134, 'إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ', 'তোমাদের (আজ) যে প্রতিশ্রুতি দেয়া হচ্ছে তা অবশ্যই আসবে, আর তোমরা (আল্লাহ তায়ালাকে) ব্যর্থ করে দেয়ার ক্ষমতা রাখো না।', 'Inna ma tooAAadoona laatin wama antum bimuAAjizeena', 1, NOW(), NOW()),
(11, 135, 'قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ', '( হে নবী, তুমি বলো) হে আমার জাতি, তোমরা নিজ নিজ জায়গায় (কাজ) করে যাও, আমিও (আমার করণীয়) করে যাবো, অচিরেই তোমরা জানতে পারবে, কার জন্যে পরিণামের (জান্নাতের) ঘরটি (নির্দিষ্ট) রয়েছে; নিসন্দেহে যালেমরা কখনো সাফল্য লাভ করবে না।', 'Qul ya qawmi iAAmaloo AAala makanatikum innee AAamilun fasawfa taAAlamoona man takoonu lahu AAaqibatu alddari innahu la yuflihu alththalimoona', 1, NOW(), NOW()),
(11, 136, 'وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ', 'স্বয়ং আল্লাহ তায়ালা যে শস্য উৎপাদন করেছেন ও গবাদিপশু সৃষ্টি করেছেন, এ (মূর্খ) ব্যক্তিরা তারই এক অংশ (আল্লাহর জন্যে) নির্দিষ্ট করে রাখে এবং নিজেদের খেয়ালখুশীমতো (একথা) বলে যে, এ অংশ হচ্ছে আল্লাহর জন্যে, আর এ অংশ হচ্ছে আমাদের শরীক (দেবতা)দের জন্যে, অতপর যা তাদের দেবতাদের জন্যে রাখা হয় তা আল্লাহর কাছ পর্যন্ত পৌঁছায় না, (যদিও) আল্লাহর (নামে) রাখা অংশ শেষতক তাদের দেবতাদের কাছে গিয়েই পৌঁছে; কতো নিকৃষ্ট তাদের এ বিচার!', 'WajaAAaloo lillahi mimma tharaa mina alharthi waalanAAami naseeban faqaloo hatha lillahi bizaAAmihim wahatha lishurakaina fama kana lishurakaihim fala yasilu ila Allahi wama kana lillahi fahuwa yasilu ila shurakaihim saa ma yahkumoona', 1, NOW(), NOW()),
(11, 137, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ', 'এভাবে বহু মুশরিকের ক্ষেত্রেই তাদের শরীক (দেবতা)রা তাদের আপন সন্তানদের হত্যা করার (জঘন্য) কাজটিকেও একান্ত শোভনীয় করে রেখেছে, এর দ্বারা সে (আসলে) তাদের ধ্বংসই সাধন করতে চায় এবং তাদের গোটা জীবন বিধানকেই তাদের কাছে সন্দেহের বিষয়ে পরিণত করে দিতে চায়, অবশ্য আল্লাহ তায়ালা চাইলে তারা এ কাজ করতো না, তুমি তাদের (তাদের অবস্থার ওপর) ছেড়ে দাও, মিথ্যা রচনা নিয়ে (তাদের ব্যস্ত) থাকতে দাও।', 'Wakathalika zayyana likatheerin mina almushrikeena qatla awladihim shurakaohum liyurdoohum waliyalbisoo AAalayhim deenahum walaw shaa Allahu ma faAAaloohu fatharhum wama yaftaroona', 1, NOW(), NOW()),
(11, 138, 'وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ', 'তারা বলে, এসব গবাদিপশু এবং এ খাদ্যশস্য নিষিদ্ধ (তালিকাভুক্ত), আমরা যাকে চাইবো সে ছাড়া অন্য কেউ তা খেতে পারবে না, এটা তাদের (মনগড়া একটা) ধারণা মাত্র, (তারা মনে করে) কিছু গবাদিপশু আছে যার পিঠ (আরোহণ কিংবা মাল সামান রাখার জন্যে) নিষিদ্ধ, আবার কিছু গবাদিপশু আছে যার ওপর (জবাই করার সময়) তারা আল্লাহর নাম স্মরণ করে না, আল্লাহর ওপর মিথ্যা আরোপ করার উদ্দেশেই (তাদের) এসব অপচেষ্টা; অচিরেই তিনি তাদের এ মিথ্যাচারের জন্যে তাদের (যথাযথ) প্রতিফল দান করবেন।', 'Waqaloo hathihi anAAamun waharthun hijrun la yatAAamuha illa man nashao bizaAAmihim waanAAamun hurrimat thuhooruha waanAAamun la yathkuroona isma Allahi AAalayha iftiraan AAalayhi sayajzeehim bima kanoo yaftaroona', 1, NOW(), NOW()),
(11, 139, 'وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ', 'তারা বলে, এসব গবাদিপশুর পেটে যা কিছু আছে তা শুধু আমাদের পুরুষদের জন্যেই নির্দিষ্ট এবং আমাদের (মহিলা) সাথীদের জন্যে (তা) হারাম, তবে যদি এ (পশুর পেটে) মরা কিছু থাকে তাহলে তাতে তারা (নারী-পুরুষ) উভয়েই সমান অংশীদার; আল্লাহ তায়ালা অতি শীঘ্রই তাদের এ ধরনের উদ্ভট কথা বলার প্রতিফল দান করবেন; নিসন্দেহে তিনি প্রবল প্রজ্ঞাময়, তিনি সর্বজ্ঞ।', 'Waqaloo ma fee butooni hathihi alanAAami khalisatun lithukoorina wamuharramun AAala azwajina wain yakun maytatan fahum feehi shurakao sayajzeehim wasfahum innahu hakeemun AAaleemun', 1, NOW(), NOW()),
(11, 140, 'قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ', 'যারা নির্বুদ্ধিতা ও অজ্ঞতার বশবর্তী হয়ে নিজেদের সন্তানদের হত্যা করলো এবং আল্লাহ তায়ালা তাদের যে রেযেক দান করেছেন তা নিজেদের ওপর হারাম করে নিলো এবং আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করলো– তারা দারুণভাবে ক্ষতিগ্রস্ত হয়ে গেলো, তারা পথভ্রষ্ট হয়ে গেলো, এরা কখনো সৎপথের অনুসারী ছিলো না।', 'Qad khasira allatheena qataloo awladahum safahan bighayri AAilmin waharramoo ma razaqahumu Allahu iftiraan AAala Allahi qad dalloo wama kanoo muhtadeena', 1, NOW(), NOW()),
(11, 141, '۞وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّـٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ', 'তিনি (মহান আল্লাহ তায়ালা)- যিনি নানা প্রকারের উদ্যান বানিয়েছেন, কিছু লতা-গুল্ম, যা কোনো কান্ড ছাড়াই মাচানের ওপর তুলে রাখা (হয়েছে), আবার (কিছু গাছ) যা মাচানের ওপর তুলে রাখা হয়নি (স্বীয় কান্ডের ওপর এমনিই দাঁড়িয়ে আছে । তিনি সৃষ্টি করেছেন), খেজুর গাছ এবং বিভিন্ন প্রকারের খাদ্যশস্য ও আনার (এগুলো স্বাদে গন্ধে এক রকমও হতে পারে), আবার তা ভিন্ন ধরনেরও হতে পারে, যখন তা ফলবান হয় তখন তোমরা তার ফল খাও, তোমরা ফসল তোলার দিনে (যে বঞ্চিত) তার হক আদায় করো, কখনো অপচয় করো না; নিসন্দেহে আল্লাহ তায়ালা অপচয়কারীদের পছন্দ করেন না।', 'Wahuwa allathee anshaa jannatin maAArooshatin waghayra maAArooshatin waalnnakhla waalzzarAAa mukhtalifan okuluhu waalzzaytoona waalrrummana mutashabihan waghayra mutashabihin kuloo min thamarihi itha athmara waatoo haqqahu yawma hasadihi wala tusrifoo innahu la yuhibbu almusrifeena', 1, NOW(), NOW()),
(11, 142, 'وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ', 'গবাদিপশুর মধ্যে (কিছু হচ্ছে উঁচু) ভারবাহী, আর কিছু হচ্ছে (ভার বহনের অনুপোযোগী) যমীনের সাথে লেগে থাকা (খাবার উপযোগী) জন্তু, আল্লাহ তায়ালা যা তোমাদের দান করেছেন তা তোমরা খাও এবং শয়তানের পদাঙ্ক অনুসরণ করো না; অবশ্যই সে তোমাদের প্রকাশ্য দুশমন।', 'Wamina alanAAami hamoolatan wafarshan kuloo mimma razaqakumu Allahu wala tattabiAAoo khutuwati alshshaytani innahu lakum AAaduwwun mubeenun', 1, NOW(), NOW()),
(11, 143, 'ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ', '(আল্লাহ তায়ালা তোমাদের দিয়েছেন) আট প্রকারের গৃহপালিত জন্তু, (প্রথমত) তার দুটো মেষ, (দ্বিতীয়ত) তার দুটো ছাগল, (হে মুহাম্মদ), তুমি (তাদের) জিজ্ঞেস করো, এর (নর দুটো কিংবা মাদী) দু’টো অথবা তাদের মায়েরা যা কিছু পেটে রেখেছে তার কোনোটি (কি আল্লাহ তায়ালা তোমাদের জন্যে) হারাম করেছেন? তোমরা আমাকে প্রমাণসহ বলো যদি তোমরা সত্যবাদী হও!', 'Thamaniyata azwajin mina alddani ithnayni wamina almaAAzi ithnayni qul alththakarayni harrama ami alonthayayni amma ishtamalat AAalayhi arhamu alonthayayni nabbioonee biAAilmin in kuntum sadiqeena', 1, NOW(), NOW()),
(11, 144, 'وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', '(তৃতীয়ত) দুটো উট, (চতুর্থত) দুটো গরু; এর (নর দুটো কিংবা মাদী) দুটো কি আল্লাহ তায়ালা হারাম করেছেন, অথবা এদের উভয়ের মায়েরা যা কিছু পেটে রেখেছে তা (কি তিনি তোমাদের জন্যে হারাম করেছেন)? আল্লাহ তায়ালা যখন তোমাদের এই (হারামের) আদেশ দিয়েছিলেন তখন তোমরা কি সেখানে উপস্থিত ছিলে? অতপর তার চাইতে বড় যালেম আর কে হতে পারে যে মানুষকে গোমরাহ করার জন্যে অজ্ঞতাবশত আল্লাহর নামে মিথ্যা আরোপ করে; নিশ্চয়ই আল্লাহ তায়ালা যালেম সম্প্রদায়কে সঠিক পথ দেখান না।', 'Wamina alibili ithnayni wamina albaqari ithnayni qul alththakarayni harrama ami alonthayayni amma ishtamalat AAalayhi arhamu alonthayayni am kuntum shuhadaa ith wassakumu Allahu bihatha faman athlamu mimmani iftara AAala Allahi kathiban liyudilla alnnasa bighayri AAilmin inna Allaha la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(11, 145, 'قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ', '(হে মুহাম্মদ,) তুমি বলো, আমার কাছে যে ওহী পাঠানো হয়েছে (তাতে) একজন ভোজনকারী (সাধারণত) যা খায় তার মধ্যে এমন কোনো জিনিস তো আমি পাচ্ছি না– যাকে হারাম করা হয়েছে, (হ্যাঁ, তা যদি হয়) মরা জন্তু, প্রবাহিত রক্ত এবং শুয়োরের গোশত (তাহলে তা অবশ্যই হারাম), কেননা এসব হচ্ছে নাপাক, অথবা এমন (এক) অবৈধ (জন্তু) যার ওপর (জবাই করার সময়) আল্লাহ তায়ালা ছাড়া অন্য কারো নাম নেয়া হয়েছে, তবে যে ব্যক্তি (ক্ষুধায়) অতীষ্ট (তার) কোনো নাফরমানীর ইচ্ছা না থাকে, প্রয়োজনের বাইরে সীমালংঘন না করে, তাহলে (তার ক্ষেত্রে) তোমার রব অবশ্যই ক্ষমাশীল, পরম দয়ালু।', 'Qul la ajidu fee ma oohiya ilayya muharraman AAala taAAimin yatAAamuhu illa an yakoona maytatan aw daman masfoohan aw lahma khinzeerin fainnahu rijsun aw fisqan ohilla lighayri Allahi bihi famani idturra ghayra baghin wala AAadin fainna rabbaka ghafoorun raheemun', 1, NOW(), NOW()),
(11, 146, 'وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ', 'আমি ইহুদীদের ওপর নখযুক্ত সব পশুই হারাম করে দিয়েছিলাম, গরু এবং ছাগলের চর্বিও আমি তাদের জন্যে হারাম করেছিলাম, তবে (জন্তুর চর্বির) যা কিছু তাদের উভয়ের পিঠ, আঁত কিংবা হাড়ের সাথে জড়ানো থাকে তা হারাম ছিলো না। এভাবে (এগুলোকে হারাম করে) আমি তাদের অবাধ্যতার জন্যে তাদের শাস্তি দিয়েছিলাম, নিসন্দেহে আমি সত্যবাদী।', 'WaAAala allatheena hadoo harramna kulla thee thufurin wamina albaqari waalghanami harramna AAalayhim shuhoomahuma illa ma hamalat thuhooruhuma awi alhawaya aw ma ikhtalata biAAathmin thalika jazaynahum bibaghyihim wainna lasadiqoona', 1, NOW(), NOW()),
(11, 147, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ', '(এরপরও) যদি তারা তোমাকে মিথ্যাবাদী বলে তাহলে তুমি বলো, অবশ্যই তোমাদের রব বিশাল দয়ার আধার, (তবে) অপরাধী সম্প্রদায়ের ওপর থেকে তাঁর শাস্তি (কারও পক্ষে) ফেরানো সম্ভব নয়।', 'Fain kaththabooka faqul rabbukum thoo rahmatin wasiAAatin wala yuraddu basuhu AAani alqawmi almujrimeena', 1, NOW(), NOW()),
(11, 148, 'سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ', 'অচিরেই এ মুশরিক লোকগুলো বলতে শুরু করবে, যদি আল্লাহ তায়ালা চাইতেন তাহলে আমরা ও আমাদের পূর্বপুরুষরা শিরক করতাম না, না এভাবে আমরা কোনো জিনিস নিজেরা হারাম করে নিতাম; (তুমি বলো, এর) আগেও অনেকে এভাবে (আল্লাহর আয়াত) অস্বীকার করেছে; অস্বীকার করতে করতে তারা আমার শাস্তির স্বাদও ভোগ করেছে; তুমি বলো, তোমাদের কাছে কি সত্যিই কোনো জ্ঞান (মজুদ) রয়েছে? (থাকলে) অতপর তা বের করে আমার কাছে নিয়ে এসো। তোমরা তো শুধু কল্পনার অনুসরণ করো এবং অনুসরণ করো শুধু মিথ্যার।', 'Sayaqoolu allatheena ashrakoo law shaa Allahu ma ashrakna wala abaona wala harramna min shayin kathalika kaththaba allatheena min qablihim hatta thaqoo basana qul hal AAindakum min AAilmin fatukhrijoohu lana in tattabiAAoona illa alththanna wain antum illa takhrusoona', 1, NOW(), NOW()),
(11, 149, 'قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ', 'তুমি বলো, (সব কিছুর) চূড়ান্ত প্রমাণ তো আল্লাহ তায়ালার জন্যেই, তিনি যদি চাইতেন তাহলে তিনি তোমাদের সবাইকেই সৎপথে পরিচালিত করে দিতেন।', 'Qul falillahi alhujjatu albalighatu falaw shaa lahadakum ajmaAAeena', 1, NOW(), NOW()),
(11, 150, 'قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ', 'তুমি বলো (যাও), তোমরা তোমাদের সেসব সাক্ষী নিয়ে এসো– যারা একথার সাক্ষ্য দিবে যে, আল্লাহ তায়ালাই এসব জিনিস হারাম করেছেন। তারা যদি সাক্ষ্য দেয়ও, তবু তুমি তাদের সাথে কোনো সাক্ষ্য দিয়ো না, তুমি তাদের ইচ্ছা আকাংখার অনুসরণ করো না যারা আমার আয়াতকে অস্বীকার করেছে, যারা পরকালের ওপর ঈমান আনেনি, সর্বোপরি তারা অন্য কিছুকেই তাদের মালিকের সমকক্ষ মনে করে।', 'Qul halumma shuhadaakumu allatheena yashhadoona anna Allaha harrama hatha fain shahidoo fala tashhad maAAahum wala tattabiAA ahwaa allatheena kaththaboo biayatina waallatheena la yuminoona bialakhirati wahum birabbihim yaAAdiloona', 1, NOW(), NOW()),
(11, 151, '۞قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ', '(হে মুহাম্মদ,) তুমি তাদের বলো, এসো আমিই তোমাদের বলে দেই– তোমাদের রব কোন্ কোন্ জিনিস তোমাদের জন্যে হারাম করেছেন, (হ্যাঁ, সে জিনিসগুলো হচ্ছে), তোমরা তাঁর সাথে অন্য কিছুকে শরীক করবে না, পিতা-মাতার সাথে ভালো ব্যবহার করবে, দারিদ্রের আশংকায় কখনো তোমরা তোমাদের সন্তানদের হত্যা করো না; কেননা আমি তোমাদের ও তাদের উভয়েরই আহার যোগাই, প্রকাশ্যে হোক কিংবা গোপনে হোক তোমরা অশ্লীলতার কাছে যেও না, আল্লাহ তায়ালা যে জীবনকে তোমাদের জন্যে সম্মানিত করেছেন তাকে যথার্থ কারণ ব্যতিরেকে হত্যা করো না; এ হচ্ছে তোমাদের (জন্যে আল্লাহ তায়ালার কতিপয় নির্দেশ), এর মাধ্যমে তিনি তোমাদের আদেশ দিয়েছেন, আশা করা যায় তোমরা অনুধাবন করতে পারবে।', 'Qul taAAalaw atlu ma harrama rabbukum AAalaykum alla tushrikoo bihi shayan wabialwalidayni ihsanan wala taqtuloo awladakum min imlaqin nahnu narzuqukum waiyyahum wala taqraboo alfawahisha ma thahara minha wama batana wala taqtuloo alnnafsa allatee harrama Allahu illa bialhaqqi thalikum wassakum bihi laAAallakum taAAqiloona', 1, NOW(), NOW()),
(11, 152, 'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ', 'তোমরা ইয়াতীমদের সম্পদের কাছে যেও না, তবে উদ্দেশ্য যদি ভালো হয় তাহলে একটা নির্দিষ্ট বয়সসীমায় পৌঁছা পর্যন্ত (কোনো পদক্ষেপ নিলে তা ভিন্ন কথা), পরিমাপ ও ওজন (করার সময়) ন্যায্যভাবেই তা করবে, আমি কারো ওপর তার সাধ্যসীমার বাইরে কোনো দায়িত্ব চাপাই না, যখনি তোমরা কোনো ব্যাপারে কথা বলবে, তখন ইনসাফ করবে, যদি তা (তোমাদের একান্ত) আপনজনের (বিরুদ্ধে)-ও হয়, তোমরা আল্লাহ তায়ালাকে দেয়া সব অংগীকার পূরণ করো; এ হচ্ছে তোমাদের জন্যে (তার কতিপয় বিধান); এর মাধ্যমে তিনি তোমাদের আদেশ দিয়েছেন, আশা করা যায় তোমরা উপদেশ গ্রহণ করবে।', 'Wala taqraboo mala alyateemi illa biallatee hiya ahsanu hatta yablugha ashuddahu waawfoo alkayla waalmeezana bialqisti la nukallifu nafsan illa wusAAaha waitha qultum faiAAdiloo walaw kana tha qurba wabiAAahdi Allahi awfoo thalikum wassakum bihi laAAallakum tathakkaroona', 1, NOW(), NOW()),
(11, 153, 'وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ', 'এটা হচ্ছে আমার (দেখানো) সহজ সরল পথ, অতএব তোমরা একমাত্র এরই অনুসরণ করো, কখনো ভিন্ন পথ অবলম্বন করো না, কেননা (ভিন্ন পথ অবলম্বন করলে) তা তোমাদের আল্লাহর পথ থেকে বিচ্ছিন্ন করে দিবে । এ হচ্ছে তোমাদের (জন্যে আরো কয়েকটি বিধান; এর মাধ্যমে) তিনি তোমাদের আদেশ দিচ্ছেন, আশা করা যায় তোমরা তাকওয়া অবলম্বন করবে।', 'Waanna hatha siratee mustaqeeman faittabiAAoohu wala tattabiAAoo alssubula fatafarraqa bikum AAan sabeelihi thalikum wassakum bihi laAAallakum tattaqoona', 1, NOW(), NOW()),
(11, 154, 'ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ', 'অতপর আমি মূসাকে কিতাব দান করেছিলাম, (যেন) যে ব্যক্তি উত্তম কাজ করেছে তার ওপর (আমার নেয়ামত) পূর্ণ হতে পারে এবং (এই কিতাব হচ্ছে) বিশদ হেদায়াত ও রহমত, যাতে করে (বনী ইসরাঈলের) লোকেরা তাদের মালিকের সাথে সাক্ষাতের ওপর বিশ্বাস স্থাপন করে।', 'Thumma atayna moosa alkitaba tamaman AAala allathee ahsana watafseelan likulli shayin wahudan warahmatan laAAallahum biliqai rabbihim yuminoona', 1, NOW(), NOW()),
(11, 155, 'وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ', 'এ হচ্ছে এমন একটি বরকতময় কিতাব যা আমিই নাযিল করেছি, অতএব তোমরা এর অনুসরণ করো এবং তোমরা তাকওয়া অবলম্বন করো, আশা করা যায় তোমাদের ওপর অনুগ্রহ করা হবে,', 'Wahatha kitabun anzalnahu mubarakun faittabiAAoohu waittaqoo laAAallakum turhamoona', 1, NOW(), NOW()),
(11, 156, 'أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ', 'তোমরা যেন একথা বলতে না পারো যে, (আল্লাহর) কিতাব তো আমাদের আগের (ইহুদী ও খৃস্টান এ) দুটো সম্প্রদায়কেই দেয়া হয়েছিলো, যদিও আমরা সেসব কিতাবের পাঠ সম্পর্কে বেখবর ছিলাম!', 'An taqooloo innama onzila alkitabu AAala taifatayni min qablina wain kunna AAan dirasatihim laghafileena', 1, NOW(), NOW()),
(11, 157, 'أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ', 'অথবা এ কথাও যেন বলতে না পারে যে, যদি (ইহুদী খৃস্টানদের মতো) আমাদের ওপরও কোনো কিতাব নাযিল করা হতো, তাহলে আমরা তাদের চাইতে বেশী সৎপথের অনুসারী হতাম, (আজ) তোমাদের কাছে (সত্যিই) তোমাদের মালিকের পক্ষ থেকে সুস্পষ্ট প্রমাণ, হেদায়াত ও রহমত (সর্বস্ব কিতাব) এসেছে (তোমরা এর অনুসরণ করো), তার চাইতে বড় যালেম আর কে– যে আল্লাহর আয়াতসমূহকে অস্বীকার করে এবং তা থেকে মুখ ফিরিয়ে নেয় (জেনে রেখো), যারাই আমার আয়াত থেকে মুখ ফিরিয়ে নেয়, অচিরেই আমি তাদের এ জঘন্য আচরণের জন্যে নিকৃষ্ট শাস্তি দিবো।', 'Aw taqooloo law anna onzila AAalayna alkitabu lakunna ahda minhum faqad jaakum bayyinatun min rabbikum wahudan warahmatun faman athlamu mimman kaththaba biayati Allahi wasadafa AAanha sanajzee allatheena yasdifoona AAan ayatina sooa alAAathabi bima kanoo yasdifoona', 1, NOW(), NOW()),
(11, 158, 'هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ', 'তারা কি (এ জন্যে) প্রতীক্ষা করছে যে, তাদের কাছে (আসমান থেকে) ফেরেশতা নাযিল হবে, কিংবা স্বয়ং তোমাদের রব তাদের কাছে এসে (কিতাব দিয়ে) যাবেন, অথবা মালিকের পক্ষ থেকে পাঠানো নিদর্শনের কোনও অংশ ( তাদের কাছে) আসবে, যেদিন সত্যিই তোমার মালিকের (পক্ষ থেকে এমন) কোনো নিদর্শন আসবে, সেদিন তো (হবে কেয়ামতের দিন, তখন) যে ব্যক্তি এর আগে ঈমান আনেনি কিংবা যে ব্যক্তি তার ঈমান দিয়ে ভালো কিছু অর্জন করেনি, তার জন্যে এ ঈমান কোনও উপকার দিবে না; (হে মুহাম্মদ,) তুমি বলো, তোমরাও প্রতীক্ষা করো, আমিও প্রতীক্ষা করছি।', 'Hal yanthuroona illa an tatiyahumu almalaikatu aw yatiya rabbuka aw yatiya baAAdu ayati rabbika yawma yatee baAAdu ayati rabbika la yanfaAAu nafsan eemanuha lam takun amanat min qablu aw kasabat fee eemaniha khayran quli intathiroo inna muntathiroona', 1, NOW(), NOW()),
(11, 159, 'إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ', 'যারা নিজেদের দ্বীনকে টুকরো টুকরো করে নিজে রাই নানা দল-উপদলে বিভক্ত হয়ে গেছে, তাদের কোনো দায়িত্বই তোমার ওপর নেই; অবশ্যই তাদের (ফয়সালার) ব্যাপারটা আল্লাহ তায়ালার হাতে, (যেদিন কেয়ামত সংঘটিত হবে) তখন তিনি তাদের বিস্তারিত বলবেন, তারা কি করছিলো।', 'Inna allatheena farraqoo deenahum wakanoo shiyaAAan lasta minhum fee shayin innama amruhum ila Allahi thumma yunabbiohum bima kanoo yafAAaloona', 1, NOW(), NOW()),
(11, 160, 'مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ', 'কেউ যদি একটা সৎকাজ নিয়ে (আল্লাহ তায়ালার সামনে) আসে, তাহলে তার জন্যে দশ গুণ বিনিময় থাকবে, (অপরদিকে) যদি কেউ একটা গুনাহের কাজ নিয়ে আসে, তাকে (তার) একটাই প্রতিফল দেয়া হবে, তাদের ওপর কোনোই যুলুম করা হবে না।', 'Man jaa bialhasanati falahu AAashru amthaliha waman jaa bialssayyiati fala yujza illa mithlaha wahum la yuthlamoona', 1, NOW(), NOW()),
(11, 161, 'قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', '(হে মুহাম্মদ,) তুমি বলো, অবশ্যই আমার মালিক আমাকে সঠিক পথ দেখিয়েছেন– সুপ্রতিষ্ঠিত জীবন বিধান দিয়েছেন, এটাই হচ্ছে ইবরাহীমের একনিষ্ঠ পৃথ, সে কখনো মুশরিকদের দলভুক্ত ছিলো না।', 'Qul innanee hadanee rabbee ila siratin mustaqeemin deenan qiyaman millata ibraheema haneefan wama kana mina almushrikeena', 1, NOW(), NOW()),
(11, 162, 'قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', 'তুমি বলো, অবশ্যই আমার নামায, আমার (আনুষ্ঠানিক) কাজকর্ম, আমার জীবন, আমার মৃত্যু– সব কিছুই সৃষ্টিকুলের মালিক আল্লাহ তায়ালার জন্যে।', 'Qul inna salatee wanusukee wamahyaya wamamatee lillahi rabbi alAAalameena', 1, NOW(), NOW()),
(11, 163, 'لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ', 'তাঁর কোনো শরীক কেউ নেই, আর একথা (বলার জন্যেই) আমাকে আদেশ দেয়া হয়েছে এবং আমিই হচ্ছি মুসলমানদের মধ্যে সর্বপ্রথম।', 'La shareeka lahu wabithalika omirtu waana awwalu almuslimeena', 1, NOW(), NOW()),
(11, 164, 'قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', 'তুমি বলো, (এরপরও) আমি কি আল্লাহ তায়ালা ছাড়া অন্য কোনো মালিক সন্ধান করে বেড়াবো? অথচ তিনিই সব কিছুর রব; (তাঁর বিধান হচ্ছে) প্রতিটি ব্যক্তি তার কৃতকর্মের জন্যে নিজেই দায়ী হবে এবং (কেয়ামতের দিন) কোনো বোঝা বহনকারী ব্যক্তিই অন্য কোনো লোকের (পাপের) বোঝা বহন করবে না, অতপর তোমাদের সবাইকে তোমাদের (আসল) মালিকের কাছে ফিরে যেতে হবে, (সেদিন) তিনি তোমাদের সেসব কিছুই জানিয়ে দিবেন, যা নিয়ে (দুনিয়ার জীবনে) তোমরা মতবিরোধ করতে।', 'Qul aghayra Allahi abghee rabban wahuwa rabbu kulli shayin wala taksibu kullu nafsin illa AAalayha wala taziru waziratun wizra okhra thumma ila rabbikum marjiAAukum fayunabbiokum bima kuntum feehi takhtalifoona', 1, NOW(), NOW()),
(11, 165, 'وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَـٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ', 'তিনিই সেই (মহান) সত্তা, যিনি তোমাদের এ যমীনে তাঁর খলিফা বানিয়েছেন এবং (এই কারণে তিনি) তোমাদের একজনকে অন্য জনের ওপর (কিছু বেশী) মর্যাদা দান করেছেন, যেন তিনি তোমাদের যা কিছু দিয়েছেন তা দিয়েই তিনি তোমাদের কাছ থেকে (কৃতজ্ঞতার) পরীক্ষা নিতে পারেন; (জেনে রেখো,) অবশ্যই তোমার রব শাস্তিদানের ব্যাপারে অত্যন্ত তৎপর, (আবার) তিনি বড় ক্ষমাশীল, পরম দয়াময়।', 'Wahuwa allathee jaAAalakum khalaifa alardi warafaAAa baAAdakum fawqa baAAdin darajatin liyabluwakum fee ma atakum inna rabbaka sareeAAu alAAiqabi wainnahu laghafoorun raheemun', 1, NOW(), NOW()),
(12, 1, 'الٓمٓصٓ', 'আলিফ-লাম-মীম-ছোয়াদ,', 'Aliflammeemsad', 1, NOW(), NOW()),
(12, 2, 'كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ', '(হে নবী,) এ গ্রন্থ তোমার প্রতি নাজিল করা হয়েছে- যেন তুমি এর দ্বারা (কাফেরদের) ভয় দেখাতে পারো, ঈমানদারদের জন্যে (এটি) একটি স্মরণিকা, অতপর তার ব্যাপারে তোমার মনে যেন কোনো প্রকারের সংকীর্ণতা না থাকে।', 'Kitabun onzila ilayka fala yakun fee sadrika harajun minhu litunthira bihi wathikra lilmumineena', 1, NOW(), NOW()),
(12, 3, 'ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ', '(হে মানুষ, এ কিতাবে) তোমাদের মালিকের কাছ থেকে তোমাদের কাছে যা কিছু পাঠানো হয়েছে তোমরা তার অনুসরণ করো এবং তার বদলে তোমরা অন্য কোনো, কর্তৃপক্ষের অনুসরণ করো না; (আসলে) তোমাদের কম লোকই উপদেশ মেনে চলো।', 'IttabiAAoo ma onzila ilaykum min rabbikum wala tattabiAAoo min doonihi awliyaa qaleelan ma tathakkaroona', 1, NOW(), NOW()),
(12, 4, 'وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ', 'এমন কতো জনপদকে আমি ধ্বংস করে দিয়েছি- তাদের ওপর আমার আযাব আসতো রাতের বেলায় (যখন তারা ঘুমিয়ে থাকতো) কিংবা (আসতো মধ্য দিনে) যখন তারা বিশ্রাম করতো,', 'Wakam min qaryatin ahlaknaha fajaaha basuna bayatan aw hum qailoona', 1, NOW(), NOW()),
(12, 5, 'فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ', 'আর যখন তাদের কাছে আমার আযাব আসতো, তখন তারা এছাড়া আর কিছুই বলতো না যে, “নিসন্দেহে আমরা ছিলাম যালিম ।”', 'Fama kana daAAwahum ith jaahum basuna illa an qaloo inna kunna thalimeena', 1, NOW(), NOW()),
(12, 6, 'فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ', 'যাদের কাছে নবী রাসূল পাঠানো হয়েছিলো অবশ্যই আমি তাদের জিজ্ঞেস করবো, (একইভাবে) আমি রাসূলদেরও অবশ্যই প্রশ্ন করবো।', 'Falanasalanna allatheena orsila ilayhim walanasalanna almursaleena', 1, NOW(), NOW()),
(12, 7, 'فَلَنَقُصَّنَّ عَلَيۡهِم بِعِلۡمٖۖ وَمَا كُنَّا غَآئِبِينَ', 'অতপর আমি (আমার নিজস্ব) জ্ঞান দ্বারা তাদের কাছে তাদের কার্যাবলী খুলে খুলে বর্ণনা করবো, আমি তো (সেখানে) অনুপস্থিত ছিলাম না!', 'Falanaqussanna AAalayhim biAAilmin wama kunna ghaibeena', 1, NOW(), NOW()),
(12, 8, 'وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'সেদিনের (পাপ-পুণ্যের) পরিমাপ সত্য, (সেদিন) যার (এবং যাদের) ওজনের পাল্লা ভারী হবে তারাই সফল হবে,', 'Waalwaznu yawmaithini alhaqqu faman thaqulat mawazeenuhu faolaika humu almuflihoona', 1, NOW(), NOW()),
(12, 9, 'وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظۡلِمُونَ', 'আর যার (কিংবা যাদের) পাল্লা সেদিন হালকা হবে, তারা (হচ্ছে এমন সব লোক, যারা) নিজেরাই নিজে দের ক্ষতি সাধন করেছে, কারণ এরা (দুনিয়ায়) আমার আয়াতসমূহের সাথে যুলুম করতো।', 'Waman khaffat mawazeenuhu faolaika allatheena khasiroo anfusahum bima kanoo biayatina yathlimoona', 1, NOW(), NOW()),
(12, 10, 'وَلَقَدۡ مَكَّنَّـٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلٗا مَّا تَشۡكُرُونَ', 'অবশ্যই আমি তোমাদের (এই) যমীনের ওপর প্রতিষ্ঠিত করেছি, তাতে আমি তোমাদের জন্যে জীবিকার ব্যবস্থাও করে দিয়েছি; কিন্তু তোমরা (নেয়ামতের) খুব কমই শোকর আদায় করো।', 'Walaqad makkannakum fee alardi wajaAAalna lakum feeha maAAayisha qaleelan ma tashkuroona', 1, NOW(), NOW()),
(12, 11, 'وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّـٰجِدِينَ', 'আমিই তোমাদের বানিয়েছি, তারপর আমিই তোমাদের (নানা) আকার দান করেছি, অতপর আমি ফেরেশতাদের বলেছি, (সম্মানের জন্যে তোমরা) আদমকে সাজদা করো, তখন সবাই সাজদা করলো, একমাত্র ইবলীস ছাড়া; সে কিছুতেই সাজদাকারীদের মধ্যে শামিল হলো না।', 'Walaqad khalaqnakum thumma sawwarnakum thumma qulna lilmalaikati osjudoo liadama fasajadoo illa ibleesa lam yakun mina alssajideena', 1, NOW(), NOW()),
(12, 12, 'قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ', 'আল্লাহ তায়ালা বললেন (হে ইবলীস), আমি যখন (নিজেই) তোমাকে সাজদা করার আদেশ দিলাম, তখন কোন্ জিনিস তোমাকে সাজদা করা থেকে বিরত রাখলো? ইবলীস বললো (আমি কেন তাকে সাজদা করবো), আমি তো তার চাইতে উত্তম, (কারণ) তুমি আমাকে বানিয়েছো আগুন থেকে, আর তাকে বানিয়েছো মাটি থেকে।', 'Qala ma manaAAaka alla tasjuda ith amartuka qala ana khayrun minhu khalaqtanee min narin wakhalaqtahu min teenin', 1, NOW(), NOW()),
(12, 13, 'قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ', 'আল্লাহ তায়ালা বললেন, তুমি এখান থেকে নেমে যাও! এখানে (বসে) অহংকার করবে, এটা তোমার পক্ষে সাজে না- – (তুমি এখান থেকে) বেরিয়ে যাও, তুমি অবশ্যই অপমানিতদের একজন।', 'Qala faihbit minha fama yakoonu laka an tatakabbara feeha faokhruj innaka mina alssaghireena', 1, NOW(), NOW()),
(12, 14, 'قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ', 'সে বললো (হে আল্লাহ), তুমি আমাকে সেদিন পর্যন্ত (শয়তানী করার) অবকাশ দাও, যেদিন এ (আদম সন্তান)- দের পুনরায় (কবর থেকে) উঠানো হবে।', 'Qala anthirnee ila yawmi yubAAathoona', 1, NOW(), NOW()),
(12, 15, 'قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ', 'আল্লাহ তায়ালা বললেন (হ্যাঁ, যাও), অবশ্যই তুমি অবকাশপ্রাপ্তদের মাঝে একজন।', 'Qala innaka mina almunthareena', 1, NOW(), NOW()),
(12, 16, 'قَالَ فَبِمَآ أَغۡوَيۡتَنِي لَأَقۡعُدَنَّ لَهُمۡ صِرَٰطَكَ ٱلۡمُسۡتَقِيمَ', 'সে বললো, যেহেতু তুমি এ (আদমের) জন্যেই আমাকে গোমরাহীতে নিমজ্জিত করলে, (তাই) আমি এদের (গোমরাহ করার) জন্যে অবশ্যই তোমার (প্রদর্শিত) সরল পথে (ওঁৎ পেতে) বসে থাকবো।', 'Qala fabima aghwaytanee laaqAAudanna lahum sirataka almustaqeema', 1, NOW(), NOW()),
(12, 17, 'ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ', 'অতপর (পথভ্রষ্ট করার জন্যে) আমি অবশ্যই তাদের কাছে আসবো, আসবো তাদের সামনের দিক থেকে, তাদের পেছন দিক থেকে, তাদের ডান দিক থেকে, তাদের বাঁ দিক থেকে (ফলে) তুমি এদের অধিকাংশ লোককেই (তোমার) কৃতজ্ঞতা আদায়কারী (হিসেবে দেখতে) পাবে না।', 'Thumma laatiyannahum min bayni aydeehim wamin khalfihim waAAan aymanihim waAAan shamailihim wala tajidu aktharahum shakireena', 1, NOW(), NOW()),
(12, 18, 'قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومٗا مَّدۡحُورٗاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِينَ', 'আল্লাহ তায়ালা বললেন, বের হয়ে যাও তুমি এখান থেকে- অপমানিত ও বিতাড়িত অবস্থায়; যারাই তোমার অনুসরণ করবে, নিশ্চয়ই আমি (তাদের এবং) তোমাদের সবাইকে দিয়ে জাহান্নাম পূর্ণ করে দিবো।', 'Qala okhruj minha mathooman madhooran laman tabiAAaka minhum laamlaanna jahannama minkum ajmaAAeena', 1, NOW(), NOW()),
(12, 19, 'وَيَـٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ', '(আল্লাহ তায়ালা আদমকে বললেন) তুমি এবং তোমার সাথী জান্নাতে বাস করতে থাকো এবং এর যেখান থেকে (যা) চাও— তা তোমরা খাও, কিন্তু এ গাছটির কাছেও যেয়ো না, (গেলে) তোমরা উভয়েই যালিমদের মধ্যে শামিল হয়ে যাবে।', 'Waya adamu oskun anta wazawjuka aljannata fakula min haythu shituma wala taqraba hathihi alshshajarata fatakoona mina alththalimeena', 1, NOW(), NOW()),
(12, 20, 'فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ', 'এরপর শয়তান তাদের দু’জনকেই কুমন্ত্রণা দিলো- যেন সে তাদের নিজেদের লজ্জাস্থানসমূহ, যা তাদের পরস্পরের কাছ থেকে গোপন করে রাখা হয়েছিলো- প্রকাশ করে দিতে পারে, সে (তাদের) বললো, তোমাদের রব এ গাছটির (কাছে যাওয়া) থেকে তোমাদের যে বারণ করেছেন, তার উদ্দেশ্য এ ছাড়া আর কিছুই নয় যে, (সেখানে গেলে) তোমরা উভয়েই ফেরেশতা হয়ে যাবে, অথবা তোমরা (জান্নাতে) চিরস্থায়ী হয়ে যাবে।', 'Fawaswasa lahuma alshshaytanu liyubdiya lahuma ma wooriya AAanhuma min sawatihima waqala ma nahakuma rabbukuma AAan hathihi alshshajarati illa an takoona malakayni aw takoona mina alkhalideena', 1, NOW(), NOW()),
(12, 21, 'وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ', 'সে তাদের কাছে কসম করে বললো, আমি অবশ্যই তোমাদের উভয়ের হিতাকাঙ্ক্ষীদের একজন।', 'Waqasamahuma innee lakuma lamina alnnasiheena', 1, NOW(), NOW()),
(12, 22, 'فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ', 'অতপর সে তাদের দুজনকেই প্রতারণার জালে আটকে ফেললো, (এক সময়) যখন তারা উভয়েই সে গাছ (-এর ফল) আস্বাদন করলো, তখন তাদের লজ্জাস্থানসমূহ তাদের উভয়ের সামনে খুলে গেলো, (সাথে সাথে) তারা জান্নাতের কিছু লতা পাতা নিজেদের ওপর জড়িয়ে (নিজেদের গোপন স্থানসমূহ) ঢাকতে শুরু করলো; তাদের রব (তখন) তাদের ডাক দিয়ে বললেন, আমি কি তোমাদের উভয়কে এ গাছটি (-র কাছে যাওয়া) থেকে নিষেধ করিনি এবং আমি কি তোমাদের একথা বলে দেইনি যে, শয়তান হচ্ছে তোমাদের উভয়ের প্রকাশ্য দুশমন!', 'Fadallahuma bighuroorin falamma thaqa alshshajarata badat lahuma sawatuhuma watafiqa yakhsifani AAalayhima min waraqi aljannati wanadahuma rabbuhuma alam anhakuma AAan tilkuma alshshajarati waaqul lakuma inna alshshaytana lakuma AAaduwwun mubeenun', 1, NOW(), NOW()),
(12, 23, 'قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ', 'অতপর তারা দুজনেই বলে উঠলো, হে আমাদের রব, আমরা আমাদের নিজেদের ওপর যুলুম করেছি, যদি তুমি আমাদের মাফ না করো এবং আমাদের (ওপর) দয়া না করো তাহলে আমরা অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে যাবো।', 'Qala rabbana thalamna anfusana wain lam taghfir lana watarhamna lanakoonanna mina alkhasireena', 1, NOW(), NOW()),
(12, 24, 'قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ', 'আল্লাহ তায়ালা বললেন, (এবার) তোমরা সবাই এখান থেকে নেমে যাও (মনে রেখো), তোমরা (ও শয়তান) একে অপরের দুশমন, সুনির্দিষ্ট সময় পর্যন্ত পৃথিবীতে থাকার উদ্দেশে তোমাদের জন্যে সেখানে বসবাসের জায়গা ও জীবন-সামগ্রীর ব্যবস্থা থাকবে।', 'Qala ihbitoo baAAdukum libaAAdin AAaduwwun walakum fee alardi mustaqarrun wamataAAun ila heenin', 1, NOW(), NOW()),
(12, 25, 'قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ', 'আল্লাহ তায়ালা বললেন, তোমরা সেখানেই জীবন যাপন করবে, সেখানেই তোমরা মৃত্যুবরণ করবে এবং সেখান থেকেই তোমাদের (পুনরায়) বের করে আনা হবে।', 'Qala feeha tahyawna wafeeha tamootoona waminha tukhrajoona', 1, NOW(), NOW()),
(12, 26, 'يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ', 'হে আদম সন্তানরা, আমি তোমাদের ওপর পোশাক (সংক্রান্ত বিধান) পাঠিয়েছি, যাতে করে (এর দ্বারা) তোমরা তোমাদের গোপন স্থানসমূহ ঢেকে রাখতে পারো এবং (নিজেদের) সৌন্দর্যও ফুটিয়ে তুলতে পারো, (তবে আসল) পোশাক হচ্ছে তাকওয়ার পোশাক, আর এটাই হচ্ছে উত্তম এবং এটা আল্লাহর নিদর্শনসমূহেরও একটি (অংশ), আশা করা যায় তারা শিক্ষা গ্রহণ করবে।', 'Ya banee adama qad anzalna AAalaykum libasan yuwaree sawatikum wareeshan walibasu alttaqwa thalika khayrun thalika min ayati Allahi laAAallahum yaththakkaroona', 1, NOW(), NOW()),
(12, 27, 'يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ', 'হে আদম সন্তানরা, শয়তান যেভাবে তোমাদের পিতা মাতাকে জান্নাত থেকে বের করে দিয়েছে, তেমনি করে তোমাদেরও সে যেন প্রতারিত করতে না পারে, শয়তান তাদের উভয়ের (দেহ) থেকে তাদের পোশাক খুলে ফেলেছিলো, যাতে করে তাদের উভয়ের গোপন স্থানসমূহ উভয়ের কাছে উন্মুক্ত হয়ে পড়ে; (মূলত) সে নিজে এবং তার সঙ্গী-সাথীরা তোমাদের এমন সব স্থান থেকে দেখতে পায়, যেখান থেকে তোমরা তাদের দেখতে পাও না; তাদের জন্যে শয়তানকে আমি অভিভাবক বানিয়ে দিয়েছি- যারা (আমার ওপর) ঈমান আনে না।', 'Ya banee adama la yaftinannakumu alshshaytanu kama akhraja abawaykum mina aljannati yanziAAu AAanhuma libasahuma liyuriyahuma sawatihima innahu yarakum huwa waqabeeluhu min haythu la tarawnahum inna jaAAalna alshshayateena awliyaa lillatheena la yuminoona', 1, NOW(), NOW()),
(12, 28, 'وَإِذَا فَعَلُواْ فَٰحِشَةٗ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'তারা যখন কোনো অশ্লীল কাজ করে, তখন বলে, আমরা আমাদের পূর্বপুরুষদের এর ওপর পেয়েছি এবং স্বয়ং আল্লাহ তায়ালাই আমাদের এর নির্দেশ দিয়েছেন; (হে নবী,) তুমি বলো, আল্লাহ তায়ালা কখনো অশ্লীল কিছুর হুকুম দেন না; তোমরা কি আল্লাহ তায়ালা সম্পর্কে এমন কিছু বলছো, যার ব্যাপারে তোমরা কিছুই জানো না।', 'Waitha faAAaloo fahishatan qaloo wajadna AAalayha abaana waAllahu amarana biha qul inna Allaha la yamuru bialfahshai ataqooloona AAala Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(12, 29, 'قُلۡ أَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ', 'তুমি বলো, আমার রব তো শুধু ন্যায়-ইনসাফেরই আদেশ দেন, (তাঁর আদেশ হচ্ছে), প্রতিটি নামাযেই তোমরা তোমাদের মুখমণ্ডলকে সোজা (কেবলামুখী) রাখবে; নিজে দের জীবন বিধানকে একান্তভাবে তাঁর জন্যে খালেস করে তাঁকেই তোমরা ডাকো; যেভাবে তিনি তোমাদের (সৃষ্টির) শুরু করেছেন সেভাবেই তোমরা (তাঁর কাছেই) ফিরে যাবে।', 'Qul amara rabbee bialqisti waaqeemoo wujoohakum AAinda kulli masjidin waodAAoohu mukhliseena lahu alddeena kama badaakum taAAoodoona', 1, NOW(), NOW()),
(12, 30, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ', 'একদল লোককে তিনি সঠিক পথ দেখিয়েছেন, (অপরদিকে) আরেক দলের ওপর গোমরাহী (বিদ্রোহ) ভালোভাবেই চেপে বসেছে; এরা আল্লাহ তায়ালাকে বাদ দিয়ে শয়তানদের নিজেদের অভিভাবক বানিয়ে নিয়েছে, অথচ তারা মনে করে তারাই হেদায়াতপ্রাপ্ত।', 'Fareeqan hada wafareeqan haqqa AAalayhimu alddalalatu innahumu ittakhathoo alshshayateena awliyaa min dooni Allahi wayahsaboona annahum muhtadoona', 1, NOW(), NOW()),
(12, 31, '۞يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ', 'হে আদম সন্তানরা, তোমরা প্রতিটি এবাদাতের সময়ই তোমাদের সৌন্দর্য (-মণ্ডিত পোশাক) গ্রহণ করো, তোমরা খাও এবং পান করো, তবে কোনো অবস্থাতেই অপচয় করো না, অবশ্যই আল্লাহ তায়ালা অপচয়কারীদের পছন্দ করেন না।', 'Ya banee adama khuthoo zeenatakum AAinda kulli masjidin wakuloo waishraboo wala tusrifoo innahu la yuhibbu almusrifeena', 1, NOW(), NOW()),
(12, 32, 'قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ', '(হে নবী,) তুমি বলো, আল্লাহ তায়ালার সেসব সৌন্দর্য (-মণ্ডিত পোশাক) এবং পবিত্র খাবার তোমাদের জন্যে কে হারাম করেছে? যেগুলো তিনি স্বয়ং তাঁর বান্দাদের জন্যে উদ্ভাবন করেছেন; তুমি বলো, এগুলো হচ্ছে যারা ঈমান এনেছে তাদের পার্থিব পাওনা, (অবশ্য) কেয়ামতের দিনও এগুলো ঈমানদারদের জন্যেই (নির্দিষ্ট থাকবে); এভাবেই আমি জ্ঞানী সম্প্রদায়ের জন্যে আমার আয়াতসমূহ খুলে খুলে বর্ণনা করি।', 'Qul man harrama zeenata Allahi allatee akhraja liAAibadihi waalttayyibati mina alrrizqi qul hiya lillatheena amanoo fee alhayati alddunya khalisatan yawma alqiyamati kathalika nufassilu alayati liqawmin yaAAlamoona', 1, NOW(), NOW()),
(12, 33, 'قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'তুমি বলো, হ্যাঁ, আমার রব অবশ্যই যাবতীয় প্রকাশ্য ও অপ্রকাশ্য অশ্লীল কাজ, গুনাহ ও অন্যায়ভাবে বাড়াবাড়ি করাকে হারাম করেছেন, (তিনি আরো হারাম করেছেন) তোমরা আল্লাহর সাথে (অন্য কাউকে) শরীক করবে, যার ব্যাপারে তিনি কখনো কোনো সনদ নাজিল করেননি এবং আল্লাহ তায়ালা সম্পর্কে তোমরা এমন সব কথা বলবে, যার ব্যাপারে তোমাদের কোনোই জ্ঞান নেই।', 'Qul innama harrama rabbiya alfawahisha ma thahara minha wama batana waalithma waalbaghya bighayri alhaqqi waan tushrikoo biAllahi ma lam yunazzil bihi sultanan waan taqooloo AAala Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(12, 34, 'وَلِكُلِّ أُمَّةٍ أَجَلٞۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ', 'প্রত্যেক জাতির জন্যেই (তার উত্থান-পতনের) একটি সুনির্দিষ্ট মেয়াদ রয়েছে, যখন তাদের সে মেয়াদ আসবে তখন তারা একদন্ডও বিলম্ব করবে না, তেমনি তারা এক মুহূর্ত এগুতেও পারবে না।', 'Walikulli ommatin ajalun faitha jaa ajaluhum la yastakhiroona saAAatan wala yastaqdimoona', 1, NOW(), NOW()),
(12, 35, 'يَٰبَنِيٓ ءَادَمَ إِمَّا يَأۡتِيَنَّكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'হে আদম সন্তানরা যখনি তোমাদের কাছে তোমাদের মধ্য থেকে রাসূলরা আসবে, যারা তোমাদের কাছে আমার আয়াতসমূহ পড়ে শোনাবে তখন যে (ও যারা সে অনুযায়ী) তাকওয়া অবলম্বন করবে এবং (নিজেদের) সংশোধন করে নিবে, তাদের কোনোই ভয় থাকবে না, তারা কখনো দুশ্চিন্তাও করবে না।', 'Ya banee adama imma yatiyannakum rusulun minkum yaqussoona AAalaykum ayatee famani ittaqa waaslaha fala khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(12, 36, 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'আর যারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করবে এবং এ (সত্য) নিয়ে অহংকার করবে, তারা হবে জাহান্নামের অধিবাসী, সেখানে তারা চিরদিন অবস্থান করবে।', 'Waallatheena kaththaboo biayatina waistakbaroo AAanha olaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(12, 37, 'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ أُوْلَـٰٓئِكَ يَنَالُهُمۡ نَصِيبُهُم مِّنَ ٱلۡكِتَٰبِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَالُوٓاْ أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ', 'যে ব্যক্তি আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করে কিংবা তাঁর আয়াতসমূহকে মিথ্যা সাব্যস্ত করে, তার চাইতে বড়ো যালিম আর কে? এরা হচ্ছে সেসব ব্যক্তি, যারা কিতাবে (বর্ণিত দুর্ভাগ্য) থেকে তাদের নিজেদের অংশ পেতে থাকবে; এমনিভাবে (তাদের মৃত্যুর সময়) তাদের কাছে আমার ফেরেশতারা যখন এসে হাযির হবে- যারা তাদের মৃত্যু দিবে (তখন) তারা বলবে (বলো), তারা (এখন) কোথায়-যাদের তোমরা আল্লাহ তায়ালার বদলে – ডাকতে; তারা বলবে- (আজ) সবাই (আমাদের ছেড়ে) সরে গেছে, তারা (সেদিন) সবাই নিজেদের বিরুদ্ধে সাক্ষ্য দিবে, তারা সত্যিই কাফের ছিলো।', 'Faman athlamu mimmani iftara AAala Allahi kathiban aw kaththaba biayatihi olaika yanaluhum naseebuhum mina alkitabi hatta itha jaathum rusuluna yatawaffawnahum qaloo ayna ma kuntum tadAAoona min dooni Allahi qaloo dalloo AAanna washahidoo AAala anfusihim annahum kanoo kafireena', 1, NOW(), NOW()),
(12, 38, 'قَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ', 'আল্লাহ তায়ালা বলবেন, তোমাদের আগে যেসব মানুষের দল, জ্বিনের দল গত হয়ে গেছে, তাদের সাথে তোমরাও আজ সবাই জাহান্নামের আগুনে প্রবেশ করো; এমনি করে যখন এক একটি জনগোষ্ঠী (জাহান্নামে) দাখিল হতে থাকবে, তখন তারা তাদের (সাথী ভাই) বোনদের ওপর লানত দিতে থাকবে, এভাবে (লানত দিতে দিতে) যখন সবাই সেখানে গিয়ে একত্র হবে, তখন তাদের শেষের দলটি পূর্ববর্তী দলের ব্যাপারে বলবে, হে আমাদের রব, এরাই হচ্ছে সেসব লোক যারা আমাদের গোমরাহ করেছিলো, তুমি এদের আগুনের শাস্তি দ্বিগুণ করে দাও; আল্লাহ তায়ালা বলবেন, (আজ) তোমাদের প্রত্যেকের (শাস্তিই) হবে দ্বিগুণ, কিন্তু তোমরা তো (বিষয়টি) জানোই না।', 'Qala odkhuloo fee omamin qad khalat min qablikum mina aljinni waalinsi fee alnnari kullama dakhalat ommatun laAAanat okhtaha hatta itha iddarakoo feeha jameeAAan qalat okhrahum lioolahum rabbana haolai adalloona faatihim AAathaban diAAfan mina alnnari qala likullin diAAfun walakin la taAAlamoona', 1, NOW(), NOW()),
(12, 39, 'وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلٖ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ', 'তাদের প্রথম দলটি তাদের শেষের দলটিকে বলবে, (হ্যাঁ, আমরা অপরাধী হয়ে থাকলে) তোমাদেরও আমাদের ওপর কোনো শ্রেষ্ঠত্ব ছিলো না, (এ সময় আল্লাহর ঘোষণা আসবে), তোমরা (আজ) নিজ নিজ কর্মফলের জন্যে আযাবের স্বাদ গ্রহণ করতে থাকো।', 'Waqalat oolahum liokhrahum fama kana lakum AAalayna min fadlin fathooqoo alAAathaba bima kuntum taksiboona', 1, NOW(), NOW()),
(12, 40, 'إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ', 'অবশ্যই যারা আমার আয়াতসমূহকে অস্বীকার করেছে এবং বিদ্রোহ করে তা থেকে মুখ ফিরিয়ে নিয়েছে, তাদের জন্যে কখনো (রহমত ভরা) আসমানের দুয়ার খুলে দেয়া হবে না, না এরা জান্নাতে প্রবেশ করতে পারবে- যতোক্ষণ পর্যন্ত একটি সুঁচের ছিদ্রপথ দিয়ে একটি উট প্রবেশ করতে পারবে, আমি এভাবেই অপরাধীদের প্রতিফল দিয়ে থাকি।', 'Inna allatheena kaththaboo biayatina waistakbaroo AAanha la tufattahu lahum abwabu alssamai wala yadkhuloona aljannata hatta yalija aljamalu fee sammi alkhiyati wakathalika najzee almujrimeena', 1, NOW(), NOW()),
(12, 41, 'لَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ', '(সেদিন) তাদের জন্যে বিছানা থাকবে জাহান্নামের (আগুনের, আবার এই আগুনই হবে) তাদের ওপরের আচ্ছাদন, এভাবেই আমি যালিমদের প্রতিফল দিয়ে থাকি।', 'Lahum min jahannama mihadun wamin fawqihim ghawashin wakathalika najzee alththalimeena', 1, NOW(), NOW()),
(12, 42, 'وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'যারা (আমার ওপর) ঈমান এনেছে এবং নেক আমল করেছে, আমি (তাদের) কাউকেই তাদের সাধ্যের বাইরে দায়িত্ব দেই না, এ লোকেরাই হচ্ছে জান্নাতের অধিবাসী, তারা সেখানে চিরদিন থাকবে।', 'Waallatheena amanoo waAAamiloo alssalihati la nukallifu nafsan illa wusAAaha olaika ashabu aljannati hum feeha khalidoona', 1, NOW(), NOW()),
(12, 43, 'وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ', '(দুনিয়ায়) তাদের মনের ভেতর (পরস্পরের বিরুদ্ধে ) যে ঘৃণা-বিদ্বেষ ছিলো, তা আমি (সেদিন) বের করে ফেলে দিবো, তাদের (জন্যে নির্দিষ্ট জান্নাতের) তলদেশ দিয়ে ঝর্ণাধারা প্রবাহিত হবে, (এসব দেখে) তারা বলবে, সমস্ত প্রশংসা আল্লাহ তায়ালার জন্যে, যিনি আমাদের এ (স্থান)- টির পথ দেখিয়েছেন। আল্লাহ তায়ালা আমাদের পথ না দেখালে আমরা নিজেরা কিছুতেই হেদায়াত পেতাম না, আমাদের মালিকের (পক্ষ থেকে) রাসূলরা সত্য বিধান নিয়ে এসেছিলো; (এ সময় তাদের জন্যে) ঘোষণা দেয়া হবে, এই হচ্ছে সে জান্নাত আজ তোমাদের যার উত্তরাধিকারী করে দেয়া হলো, (আর এটা হচ্ছে সেসব কাজের প্রতিফল) যা তোমরা (দুনিয়ায়) করছিলে।', 'WanazaAAna ma fee sudoorihim min ghillin tajree min tahtihimu alanharu waqaloo alhamdu lillahi allathee hadana lihatha wama kunna linahtadiya lawla an hadana Allahu laqad jaat rusulu rabbina bialhaqqi wanoodoo an tilkumu aljannatu oorithtumooha bima kuntum taAAmaloona', 1, NOW(), NOW()),
(12, 44, 'وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ', 'জান্নাতের অধিবাসীরা জাহান্নামী লোকদের ডেকে বলবে, আমাদের রব আমাদের সাথে যে ওয়াদা করেছিলেন আমরা তা সত্য পেয়েছি, তোমরা কি তোমাদের মালিকের ওয়াদাসমূহকে সঠিক পেয়েছো? তারা বলবে, হ্যাঁ- অতপর তাদের মাঝে একজন ঘোষণাকারী ঘোষণা করবে- যালিমদের ওপর আল্লাহ তায়ালার লা’নত হোক,', 'Wanada ashabu aljannati ashaba alnnari an qad wajadna ma waAAadana rabbuna haqqan fahal wajadtum ma waAAada rabbukum haqqan qaloo naAAam faaththana muaththinun baynahum an laAAnatu Allahi AAala alththalimeena', 1, NOW(), NOW()),
(12, 45, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ', '(লানত হোক তাদের ওপরও) যারা মানুষদের আল্লাহ তায়ালার পথ থেকে বিরত রাখতো এবং তাতে বক্রতা খুঁজে বেড়াতো, আর তারা শেষ বিচারের দিনকেও অস্বীকার করতো।', 'Allatheena yasuddoona AAan sabeeli Allahi wayabghoonaha AAiwajan wahum bialakhirati kafiroona', 1, NOW(), NOW()),
(12, 46, 'وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ', 'তাদের উভয়ের মাঝে একটি দেয়াল থাকবে, (এ দেয়ালের) উঁচু স্থানের ওপর থাকবে (আরেক দলের) কিছু লোক, যারা (সেখানে আনীত) প্রতিটি ব্যক্তিকে তাদের নিজ নিজ চিহ্ন অনুযায়ী চিনতে পারবে, তারা জান্নাতের অধিবাসীদের ডেকে বলবে, তোমাদের ওপর শান্তি বর্ষিত হোক। এরা (যদিও) তখন পর্যন্ত জান্নাতে প্রবেশ করেনি, কিন্তু (প্রতি মুহূর্তে) এরা সেখানে প্রবেশ করার আগ্রহ পোষণ করছে।', 'Wabaynahuma hijabun waAAala alaAArafi rijalun yaAArifoona kullan biseemahum wanadaw ashaba aljannati an salamun AAalaykum lam yadkhulooha wahum yatmaAAoona', 1, NOW(), NOW()),
(12, 47, '۞وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'অতপর যখন তাদের দৃষ্টি জাহান্নামের অধিবাসীদের (আযাবের) দিকে ফিরিয়ে দেয়া হবে, (তখন) তারা বলবে, হে আমাদের রব, আমাদের (তুমি) যালিম সম্প্রদায়ের অন্তর্ভুক্ত করো না।', 'Waitha surifat absaruhum tilqaa ashabi alnnari qaloo rabbana la tajAAalna maAAa alqawmi alththalimeena', 1, NOW(), NOW()),
(12, 48, 'وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ', 'অতপর (পার্থক্য নির্ণয়কারী সে দেয়ালের) উঁচু স্থানে অবস্থানকারী ব্যক্তিরা (জাহান্নামের) লোকদের-যাদের তারা নিজ নিজ চিহ্ন অনুযায়ী চিনতে পারবে— ডেকে বলবে, (কই) তোমাদের দলবল কোনোটাই তো (আজ) কাজে এলো না, তোমরা যে অহংকার করতে (তাও কোনো কাজে এলো না)!', 'Wanada ashabu alaAArafi rijalan yaAArifoonahum biseemahum qaloo ma aghna AAankum jamAAukum wama kuntum tastakbiroona', 1, NOW(), NOW()),
(12, 49, 'أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ', 'এরা কি সে সব লোক নয়, (দুনিয়ায়) যাদের ব্যাপারে তোমরা কসম করে বলতে, আল্লাহ তায়ালা তাঁর রহমতের কোনো অংশই এদের দান করবেন না (অথচ আজ এদেরকেই আল্লাহ তায়ালা বলছেন); তোমরা সবাই জান্নাতে প্রবেশ করো, তোমাদের ওপর কোনো ভয় নেই, না তোমরা কোনো রকম দুশ্চিন্তা করবে।', 'Ahaolai allatheena aqsamtum la yanaluhumu Allahu birahmatin odkhuloo aljannata la khawfun AAalaykum wala antum tahzanoona', 1, NOW(), NOW()),
(12, 50, 'وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ', 'জাহান্নামের অধিবাসীরা জান্নাতের লোকদের ডেকে বলবে, আমাদের ওপর সামান্য কিছু পানি (অন্তত) তোমরা ঢেলে দাও, অথবা আল্লাহ তায়ালা তোমাদের যে রেযেক দান করেছেন তার কিয়দংশ (আমাদের দাও); তারা বলবে, আল্লাহ তায়ালা (আজ) এ দুটি জিনিস কাফেরদের জন্যে হারাম করেছেন-', 'Wanada ashabu alnari ashaba aljannati an afeedoo AAalayna mina almai aw mimma razaqakumu Allahu qaloo inna Allaha harramahuma AAala alkafireena', 1, NOW(), NOW()),
(12, 51, 'ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوٗا وَلَعِبٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ', 'যারা দ্বীনকে খেল-তামাশায় পরিণত করে রেখেছিলো এবং পার্থিব জীবন তাদেরকে প্রতারণা (দিয়ে) আটকে রেখেছিলো, তাদের আজ আমি (ঠিক) সেভাবেই ভুলে যাবো যেভাবে তারা (আমার) সামনা সামনি হওয়ার এ দিনটিকে (দুনিয়ায়) ভুলে গিয়েছিলো। তারা আমার আয়াতসমূহকেও অস্বীকার করতো।', 'Allatheena ittakhathoo deenahum lahwan walaAAiban wagharrathumu alhayatu alddunya faalyawma nansahum kama nasoo liqaa yawmihim hatha wama kanoo biayatina yajhadoona', 1, NOW(), NOW()),
(12, 52, 'وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ', 'আমি তাদের কাছে এমন একটি কিতাব নিয়ে এসেছি, যাকে আমি (আমার বিশদ) জ্ঞান দ্বারা (সমৃদ্ধ করে) বর্ণনা করেছি, যে সম্প্রদায়ের লোকেরা (এর ওপর) ঈমান আনবে, এ কিতাব তাদের জন্যে (হবে) হেদায়াত ও রহমত।', 'Walaqad jinahum bikitabin fassalnahu AAala AAilmin hudan warahmatan liqawmin yuminoona', 1, NOW(), NOW()),
(12, 53, 'هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', 'এরা কি (চূড়ান্ত কোনো) পরিণামের অপেক্ষা করছে? যেদিন সে পরিণাম তাদের কাছে আসবে, সেদিন যারা ইতিপূর্বে এ (দিনটি)-কে ভুলে গিয়েছিলো- তারা বলবে, অবশ্যই আমাদের মালিকের পক্ষ থেকে রাসূলরা (এ দিন সম্পর্কিত) সত্য (প্রতিশ্রুতি) নিয়েই এসেছিলো, আমাদের জন্যে (আজ) কোনো সুপারিশকারী কি আছে, যারা আমাদের পক্ষে (আল্লাহর কাছে) কিছু সুপারিশ করবে, অথবা (এমন কি হবে,) আমাদের পুনরায় (দুনিয়ায়) ফিরিয়ে দেয়া হবে, যাতে আমরা (সেখানে গিয়ে) আগে যা করতাম তার চাইতে ভিন্ন ধরনের কিছু করে আসতে পারি, (মূলত) এরা নিজেরা নিজেদের ক্ষতি সাধন করেছে এরা (আল্লাহর ওপর) যা কিছু তারা মিথ্যা আরোপ করতো, তাও তাদের কাছ থেকে (আজ) হারিয়ে গেছে।', 'Hal yanthuroona illa taweelahu yawma yatee taweeluhu yaqoolu allatheena nasoohu min qablu qad jaat rusulu rabbina bialhaqqi fahal lana min shufaAAaa fayashfaAAoo lana aw nuraddu fanaAAmala ghayra allathee kunna naAAmalu qad khasiroo anfusahum wadalla AAanhum ma kanoo yaftaroona', 1, NOW(), NOW()),
(12, 54, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ', 'অবশ্যই তোমাদের রব আল্লাহ তায়ালা, যিনি ছয় দিনে আসমানসমূহ ও যমীন সৃষ্টি করেছেন, অতপর তিনি ‘আরশের’ ওপর অধিষ্ঠিত হন। তিনি দিনের ওপর রাতের পর্দা বিছিয়ে দেন, দ্রুতগতিতে তা একে অন্যকে অনুসরণ করে, সুরুজ, চাঁদ ও তারাসমূহকে তাঁর বিধানের অধীন করে রাখা হয়েছে; জেনে রেখো, সৃষ্টি (যেহেতু) তাঁর, (সুতরাং তার ওপর) সার্বভৌম ক্ষমতাও একমাত্র তাঁর; সৃষ্টিকুলের মালিক আল্লাহ তায়ালা অত্যন্ত বরকতময়।', 'Inna rabbakumu Allahu allathee khalaqa alssamawati waalarda fee sittati ayyamin thumma istawa AAala alAAarshi yughshee allayla alnnahara yatlubuhu hatheethan waalshshamsa waalqamara waalnnujooma musakhkharatin biamrihi ala lahu alkhalqu waalamru tabaraka Allahu rabbu alAAalameena', 1, NOW(), NOW()),
(12, 55, 'ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ', 'তোমরা বিনয়ের সাথে ও চুপিসারে তোমাদের রবকে ডাকো; অবশ্যই তিনি সীমালংঘনকারীদের পছন্দ করেন না।', 'OdAAoo rabbakum tadarruAAan wakhufyatan innahu la yuhibbu almuAAtadeena', 1, NOW(), NOW()),
(12, 56, 'وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ', '(আল্লাহর) যমীনে (একবার) তার শান্তি স্থাপনের পর তোমরা বিপর্যয় সৃষ্টি করো না, তোমরা ভয় ও আশা নিয়ে একমাত্র তাঁকেই ডাকো; অবশ্যই আল্লাহর রহমত নেক লোকদের অতি কাছে রয়েছে।', 'Wala tufsidoo fee alardi baAAda islahiha waodAAoohu khawfan watamaAAan inna rahmata Allahi qareebun mina almuhsineena', 1, NOW(), NOW()),
(12, 57, 'وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا ثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ', 'তিনিই (মহান আল্লাহ), যিনি বাতাসকে (বৃষ্টি ও) রহমতের সুসংবাদবাহী হিসেবে (জনপদে) পাঠান; শেষ পর্যন্ত যখন সে বাতাস (পানির) ভারী মেঘমালা বহন করে (চলতে থাকে), তখন আমি তাকে একটি মৃত জনপদের দিকে পাঠিয়ে দেই, অতপর (সে) মেঘ থেকে আমি পানি বর্ষণ করি এবং তা দিয়ে (যমীন থেকে) আমি সব ধরনের ফলমূল বের করে আনি; এভাবেই আমি মৃতকে (জীবন থেকে) বের করে আনবো, আশা করা যায়, তোমরা (এ থেকে) কিছু শিক্ষা গ্রহণ করবে।', 'Wahuwa allathee yursilu alrriyaha bushran bayna yaday rahmatihi hatta itha aqallat sahaban thiqalan suqnahu libaladin mayyitin faanzalna bihi almaa faakhrajna bihi min kulli alththamarati kathalika nukhriju almawta laAAallakum tathakkaroona', 1, NOW(), NOW()),
(12, 58, 'وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ', 'উৎকৃষ্ট যমীন তার মালিকের আদেশে তার (উৎকৃষ্ট) ফসলই উৎপন্ন করে, আর যে যমীন বিনষ্ট হয়ে গেছে তা কঠোর পরিশ্রম ব্যতীত কিছুই উৎপন্ন করে না; এভাবেই আমি আমার নিদর্শনসমূহ স্পষ্ট করে বর্ণনা করি- এমন এক জাতির জন্যে, যারা (এসব নেয়ামতের) কৃতজ্ঞতা জ্ঞাপন করে।', 'Waalbaladu alttayyibu yakhruju nabatuhu biithni rabbihi waallathee khabutha la yakhruju illa nakidan kathalika nusarrifu alayati liqawmin yashkuroona', 1, NOW(), NOW()),
(12, 59, 'لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ', 'আমি নূহকে তাঁর জাতির কাছে পাঠিয়েছিলাম, অতপর সে তাদের বললো, হে আমার জাতি, তোমরা আল্লাহ তায়ালার দাসত্ব (কবুল) করো, তিনি ছাড়া তোমাদের আর কোনো মাবুদ নেই; আমি আসলেই তোমাদের ওপর এক কঠিন দিনের আযাবের আশংকা করছি।', 'Laqad arsalna noohan ila qawmihi faqala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu innee akhafu AAalaykum AAathaba yawmin AAatheemin', 1, NOW(), NOW()),
(12, 60, 'قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ', 'তার জাতির নেতারা বললো (হে নূহ), আমরা নিশ্চিত দেখতে পাচ্ছি তুমি এক সুস্পষ্ট বিভ্রান্তিতে (নিমজ্জিত ) রয়েছো।', 'Qala almalao min qawmihi inna lanaraka fee dalalin mubeenin', 1, NOW(), NOW()),
(12, 61, 'قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ', 'সে বললো, হে আমার জাতি, আমার সাথে কোনোরকম বিভ্রান্তি নেই, আমি হচ্ছি সৃষ্টিকুলের মালিকের পক্ষ থেকে (পাঠানো) একজন রাসূল।', 'Qala ya qawmi laysa bee dalalatun walakinnee rasoolun min rabbi alAAalameena', 1, NOW(), NOW()),
(12, 62, 'أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ', '(আমার কাজ হচ্ছে) আমি আমার মালিকের বাণীসমূহ তোমাদের কাছে পৌঁছে দিবো এবং তোমাদের শুভ কামনা করবো, (কেননা আখেরাত সম্পর্কে) আমি আল্লাহ তায়ালার কাছ থেকে এমন কিছু কথা জানি যা তোমরা জানো না।', 'Oballighukum risalati rabbee waansahu lakum waaAAlamu mina Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(12, 63, 'أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ', 'তোমরা কি (এতে) আশ্চর্যন্বিত হচ্ছো যে, তোমাদের কাছে তোমাদেরই (মতো) একজন মানুষের ওপর তোমাদের মালিকের বাণী এসেছে, যাতে করে সে তোমাদের (আযাব সম্পর্কে) সতর্ক করে দিতে পারে এবং তোমরাও (সময় থাকতে) সাবধান হবে। আশা করা যায় তোমাদের ওপর দয়া করা হবে।', 'AwaAAajibtum an jaakum thikrun min rabbikum AAala rajulin minkum liyunthirakum walitattaqoo walaAAallakum turhamoona', 1, NOW(), NOW()),
(12, 64, 'فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ', 'অতপর তারা তাকে মিথ্যা প্রতিপন্ন করলো, আমি তাকে এবং তার সাথে যারা নৌকায় (মজুদ) ছিলো, তাদের সবাইকে (বিপর্যয় থেকে) উদ্ধার করলাম, আর যারা আমার আযাবসমূহকে মিথ্যা বলেছে তাদের আমি (পানিতে) ডুবিয়ে দিলাম; এরা ছিলো (আসলেই গোঁড়া ও) অন্ধ জাতি।', 'Fakaththaboohu faanjaynahu waallatheena maAAahu fee alfulki waaghraqna allatheena kaththaboo biayatina innahum kanoo qawman AAameena', 1, NOW(), NOW()),
(12, 65, '۞وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ', '(আমি) আ’দ জাতির কাছে (পাঠিয়েছিলাম) তাদেরই এক ভাই হৃদকে, সে (তাদের) বললো, হে আমার জাতি, তোমরা আল্লাহ তায়ালার দাসত্ব (স্বীকার) করো, তিনি ছাড়া তোমাদের আর কোনো ইলাহ নেই; তোমরা কি (তাঁকে) ভয় করো না?', 'Waila AAadin akhahum hoodan qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu afala tattaqoona', 1, NOW(), NOW()),
(12, 66, 'قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ', 'তার জাতির সরদাররা, যারা কুফরী করেছে, তারা বললো, আমরা তো নিশ্চিত দেখছি তুমি নির্বুদ্ধিতার মাঝে আছো, অবশ্যই আমরা মনে করি তুমি মিথ্যাবাদীদেরই একজন।', 'Qala almalao allatheena kafaroo min qawmihi inna lanaraka fee safahatin wainna lanathunnuka mina alkathibeena', 1, NOW(), NOW()),
(12, 67, 'قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ', 'সে বললো, হে আমার জাতি, আমার সাথে কোনোরকম নির্বুদ্ধিতা নেই, বরং আমি (হচ্ছি) সৃষ্টিকুলের মালিকের পক্ষ থেকে (পাঠানো) একজন রাসূল।', 'Qala ya qawmi laysa bee safahatun walakinnee rasoolun min rabbi alAAalameena', 1, NOW(), NOW()),
(12, 68, 'أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ', '(আমার দায়িত্ব হচ্ছে) আমি আমার মালিকের বাণীসমূহ তোমাদের কাছে পৌঁছে দিবো, আমি তোমাদের একজন বিশ্বস্ত শুভাকাংখীও বটে!', 'Oballighukum risalati rabbee waana lakum nasihun ameenun', 1, NOW(), NOW()),
(12, 69, 'أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ', 'তোমরা কি বিস্মিত হচ্ছো, তোমাদের কাছে তোমাদের মালিকের পক্ষ থেকে তোমাদেরই (মতো) একজন মানুষের ওপর তোমাদের জন্যে (সুস্পষ্ট) বাণী এসেছে; যাতে করে (এ দিয়ে) সে তোমাদের (আযাবের) ভয় দেখাতে পারে। স্মরণ করো; যখন আল্লাহ তায়ালা নূহের পর তোমাদেরকে এই যমীনে খলীফা বানিয়েছেন এবং অন্যান্য সৃষ্টির মাঝে তিনি তোমাদের বেশী ক্ষমতা দান করেছেন, অতএব (হে আমার জাতি), তোমরা আল্লাহ তায়ালার অনুগ্রহগুলো স্মরণ করো, আশা করা যায় তোমরা সাফল্য লাভ করতে পারবে।', 'AwaAAajibtum an jaakum thikrun min rabbikum AAala rajulin minkum liyunthirakum waothkuroo ith jaAAalakum khulafaa min baAAdi qawmi noohin wazadakum fee alkhalqi bastatan faothkuroo alaa Allahi laAAallakum tuflihoona', 1, NOW(), NOW()),
(12, 70, 'قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'তারা (হূদকে) বললো, তুমি কি আমাদের কাছে এ জন্যেই এসেছো যে, আমরা কেবল এক আল্লাহর এবাদাত করবো এবং আমাদের পূর্বপুরুষরা যাদের এবাদাত করেছে তাদের বাদ দিয়ে দিবো! (হ্যাঁ, এটাই যদি হয়), তাহলে নিয়ে এসো আমাদের কাছে সে (আযাবের) বিষয়টি, যার ব্যাপারে তুমি আমাদের (এতো) ভয় দেখাচ্ছো, যদি তুমি সত্যবাদী হও!', 'Qaloo ajitana linaAAbuda Allaha wahdahu wanathara ma kana yaAAbudu abaona fatina bima taAAiduna in kunta mina alssadiqeena', 1, NOW(), NOW()),
(12, 71, 'قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ', 'সে বললো, তোমাদের ওপর তোমাদের মালিকের পক্ষ থেকে আযাব ও ক্রোধ তো নির্ধারিত হয়েই আছে; তোমরা কি আমার সাথে সে (মিথ্যা মাবুদদের) নামগুলোর ব্যাপারে বিতর্কে লিপ্ত হতে চাও, যা তোমরা এবং তোমাদের বাপ-দাদারা (এমনি এমনিই) রেখে দিয়েছো, যার ব্যাপারে আল্লাহ তায়ালা কোনো রকম সনদ নাজিল করেননি; (অতএব) তোমরা (তোমাদের পরিণতির) অপেক্ষা করো, আমিও তোমাদের সাথে অপেক্ষা করতে থাকবো।', 'Qala qad waqaAAa AAalaykum min rabbikum rijsun waghadabun atujadiloonanee fee asmain sammaytumooha antum waabaokum ma nazzala Allahu biha min sultanin faintathiroo innee maAAakum mina almuntathireena', 1, NOW(), NOW()),
(12, 72, 'فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ', 'অতপর আমি তাকে এবং তার সাথে যেসব (ঈমানদার) ব্যক্তিরা ছিলো, তাদের আমার রহমত দ্বারা (আযাব থেকে) বাঁচিয়ে দিলাম, আর যারা আমার আয়াতসমূহকে অস্বীকার করেছে আমি তাদের নির্মূল করে দিলাম, (আসলে) ওরা ঈমানদারই ছিলো না।', 'Faanjaynahu waallatheena maAAahu birahmatin minna waqataAAna dabira allatheena kaththaboo biayatina wama kanoo mumineena', 1, NOW(), NOW()),
(12, 73, 'وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ', 'সামুদ জাতির কাছে (এসেছিলো) তাদেরই (এক) তিনি ছাড়া ভাই সালেহ, সে (তাদের) বললো, হে আমার জাতি, তোমরা এক আল্লাহ তায়ালার এবাদাত করো, তোমাদের আর কোনো ইলাহ নেই। তোমাদের কাছে তোমাদের মালিকের কাছ থেকে সুস্পষ্ট নিদর্শন এসেছে, এটা হচ্ছে আল্লাহর উষ্ট্রী, এটা তোমাদের জন্যে নিদর্শন, একে তোমরা ছেড়ে দাও যেন তা আল্লাহ তায়ালার যমীনে (বিচরণ করে) খেতে পারে, তোমরা তাকে কোনো খারাপ মতলবে স্পর্শ করো না, তাহলে (আল্লাহর) কঠোর আযাব এসে তোমাদের পাকড়াও করবে।', 'Waila thamooda akhahum salihan qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu qad jaatkum bayyinatun min rabbikum hathihi naqatu Allahi lakum ayatan fatharooha takul fee ardi Allahi wala tamassooha bisooin fayakhuthakum AAathabun aleemun', 1, NOW(), NOW()),
(12, 74, 'وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', 'স্মরণ করো, যখন তিনি আদ জাতির পর তোমাদের (দুনিয়ায়) খলীফা বানিয়েছিলেন এবং যমীনে তিনি তোমাদের প্রতিষ্ঠা দান করেছেন, তোমরা এর সমতল ভূমি থেকে (মাটি নিয়ে) প্রাসাদ বানাচ্ছো, আর পাহাড় কেটে কেটে নিজেদের ঘর-বাড়ি তৈরী করতে পারছো, অতএব তোমরা আল্লাহ তায়ালার (এ জ্ঞান ও প্রকৌশল সংক্রান্ত) নেয়ামতগুলোকে স্মরণ করো এবং যমীনে তোমরা বিপর্যয় ঘটিয়ো না।', 'Waothkuroo ith jaAAalakum khulafaa min baAAdi AAadin wabawwaakum fee alardi tattakhithoona min suhooliha qusooran watanhitoona aljibala buyootan faothkuroo alaa Allahi wala taAAthaw fee alardi mufsideena', 1, NOW(), NOW()),
(12, 75, 'قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ', 'তার জাতির সেসব নেতৃস্থানীয় লোক, যারা নিজে দের গৌরবের বড়াই করতো- অপেক্ষাকৃত দুর্বল শ্রেণীর লোকদের- যারা তাদের মধ্য থেকে ঈমান এনেছে- বললো, তোমরা কি সত্যিই জানো, সালেহ তার মালিকের পাঠানো একজন রাসূল; তারা বললো (হ্যাঁ), তাঁর সাথে যে বাণী পাঠানো হয়েছে আমরা তা বিশ্বাস করি।', 'Qala almalao allatheena istakbaroo min qawmihi lillatheena istudAAifoo liman amana minhum ataAAlamoona anna salihan mursalun min rabbihi qaloo inna bima orsila bihi muminoona', 1, NOW(), NOW()),
(12, 76, 'قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'অতপর (সে) অহংকারী লোকেরা বললো, তোমরা যা কিছুতে বিশ্বাস করো আমরা অবশ্যই তা অস্বীকার করি।', 'Qala allatheena istakbaroo inna biallathee amantum bihi kafiroona', 1, NOW(), NOW()),
(12, 77, 'فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ', 'অতপর, তারা উষ্ট্রীটিকে মেরে ফেললো এবং (এর দ্বারা) তারা তাদের মালিকের নির্দেশের স্পষ্ট বিরোধিতা করলো এবং তারা বললো, হে সালেহ (আমরা উষ্ট্রীটিকে মেরে ফেলেছি), যদি তুমি (সত্যিই) রাসূল হয়ে থাকো তাহলে সে (আযাবের) বিষয়টা নিয়ে এসো, যার ওয়াদা তুমি আমাদের দিচ্ছো।', 'FaAAaqaroo alnnaqata waAAataw AAan amri rabbihim waqaloo ya salihu itina bima taAAiduna in kunta mina almursaleena', 1, NOW(), NOW()),
(12, 78, 'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ', 'অতপর এক প্রলয়ংকরী ভূমিকম্প তাদের গ্রাস করে ফেললো, ফলে তারা নিজেদের ঘরেই মুখ থুবড়ে পড়ে থাকলো।', 'Faakhathathumu alrrajfatu faasbahoo fee darihim jathimeena', 1, NOW(), NOW()),
(12, 79, 'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ', 'তারপর সে (নবী) তাদের কাছ থেকে সরে গেলো এবং বললো, হে আমার জাতি, আমি তোমাদের কাছে আমার মালিকের (সতর্ক) বাণী পৌঁছে দিয়েছিলাম এবং আমি তোমাদের জন্যে কল্যাণ কামনা করেছিলাম, কিন্তু তোমরা তো কল্যাণকামীদের পছন্দ করো না।', 'Fatawalla AAanhum waqala ya qawmi laqad ablaghtukum risalata rabbee wanasahtu lakum walakin la tuhibboona alnnasiheena', 1, NOW(), NOW()),
(12, 80, 'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ', '(আমি) লূতকেও (পাঠিয়েছিলাম), যখন সে তার জাতিকে বলেছিলো, তোমরা এমন এক অশ্লীলতার কাজ নিয়ে এসেছো, যা তোমাদের আগে সৃষ্টিকুলের আর কেউ (কখনো) করেনি।', 'Walootan ith qala liqawmihi atatoona alfahishata ma sabaqakum biha min ahadin mina alAAalameena', 1, NOW(), NOW()),
(12, 81, 'إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ', 'তোমরা যৌন তৃপ্তির জন্যে নারীদের বাদ দিয়ে পুরুষদের কাছে আসো, তোমরা হচ্ছো বরং এক সীমালংঘনকারী জাতি।', 'Innakum latatoona alrrijala shahwatan min dooni alnnisai bal antum qawmun musrifoona', 1, NOW(), NOW()),
(12, 82, 'وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ', 'তার জাতির (তখন) এ কথা বলা ছাড়া আর কোনও জবাবই ছিলো না যে, তাদের তোমাদের জনপদ থেকে বের করে দাও, (কেননা) এরা হচ্ছে কিছু পাক পবিত্র মানুষ!', 'Wama kana jawaba qawmihi illa an qaloo akhrijoohum min qaryatikum innahum onasun yatatahharoona', 1, NOW(), NOW()),
(12, 83, 'فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ', 'অতপর (আযাব এসে গেলে) আমি তাকে এবং তার পরিবার-পরিজনকে উদ্ধার করলাম, তার স্ত্রীকে ছাড়া – সে (আযাবে কবলিত) পেছনের লোকদের মধ্যে শামিল থেকে গেলো।', 'Faanjaynahu waahlahu illa imraatahu kanat mina alghabireena', 1, NOW(), NOW()),
(12, 84, 'وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ', 'আমি তাদের উপর প্রচন্ড (আযাবের) বৃষ্টি বর্ষণ করলাম; অতপর তুমি (ভালো করে) দেখো, অপরাধীদের পরিণাম কী ভয়াবহ!', 'Waamtarna AAalayhim mataran faonthur kayfa kana AAaqibatu almujrimeena', 1, NOW(), NOW()),
(12, 85, 'وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ', 'আর মাদইয়ানবাসীদের কাছে (আমি পাঠিয়েছিলাম) তাদেরই ভাই শোয়াইবকেে; সে তাদের বললো, হে আমার জাতি, তোমরা এক আল্লাহ তায়ালার বন্দেগী করো, তিনি ছাড়া তোমাদের আর কোনো ইলাহ নেই; তোমাদের কাছে তোমাদের মালিকের পক্ষ থেকে সুস্পষ্ট নিদর্শন এসে গেছে, অতপর তোমরা (সে অনুযায়ী) ঠিক ঠিক মতো পরিমাপ ও ওজন করো, মানুষদের (দেয়ার সময়) কখনো (কম দিয়ে তাদের) ক্ষতিগ্রস্ত করো না, আল্লাহ তায়ালার এ যমীনে তার (শান্তি ও) সংস্কার স্থাপিত হওয়ার পর তাতে (পুনরায়) বিপর্যয় সৃষ্টি করো না; তোমরা যদি (আল্লাহ তায়ালার ওপর) ঈমান আনো তাহলে এটাই তোমাদের জন্যে ভালো।', 'Waila madyana akhahum shuAAayban qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu qad jaatkum bayyinatun min rabbikum faawfoo alkayla waalmeezana wala tabkhasoo alnnasa ashyaahum wala tufsidoo fee alardi baAAda islahiha thalikum khayrun lakum in kuntum mumineena', 1, NOW(), NOW()),
(12, 86, 'وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ', 'তোমরা প্রতিটি রাস্তায় এজন্যে বসে থেকো না যে, তোমরা লোকদের ধমক দিবে এবং যারা আল্লাহর ওপর ঈমান এনেছে তাদের তোমরা আল্লাহ তায়ালার পথ থেকে বিরত রাখবে, আর (সব সময়ই) বক্রতা (ও দোষত্রুটি) খুঁজতে থাকবে; স্মরণ করো, যখন তোমরা সংখ্যায় ছিলে নিতান্ত কম, অতপর (আল্লাহ) তোমাদের সংখ্যা বাড়িয়ে দিলেন এবং তোমরা চেয়ে দেখো, কেমন হয়েছিলো বিপর্যয় সৃষ্টিকারীদের পরিণাম!', 'Wala taqAAudoo bikulli siratin tooAAidoona watasuddoona AAan sabeeli Allahi man amana bihi watabghoonaha AAiwajan waothkuroo ith kuntum qaleelan fakaththarakum waonthuroo kayfa kana AAaqibatu almufsideena', 1, NOW(), NOW()),
(12, 87, 'وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ', 'আমাকে যে বাণী দিয়ে পাঠানো হয়েছে তার ওপর কোনো একটি জনগোষ্ঠী যদি ঈমান আনে, আর একটি দল যদি তার ওপর আদৌ ঈমান না আনে, তারপরও তোমরা ধৈর্য ধারণ করো, যতোক্ষণ না আল্লাহ তায়ালা নিজেই আমাদের মাঝে একটা ফয়সালা করে দেন, তিনিই হচ্ছেন উত্তম ফয়সালাকারী।', 'Wain kana taifatun minkum amanoo biallathee orsiltu bihi wataifatun lam yuminoo faisbiroo hatta yahkuma Allahu baynana wahuwa khayru alhakimeena', 1, NOW(), NOW()),
(12, 88, '۞قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ', 'তার সম্প্রদায়ের কিছু নেতৃস্থানীয় লোক – যারা অহংকার করছিলো- বললো, হে শোয়াইব, আমরা অবশ্যই তোমাকে এবং তোমার সাথে যারা ঈমান এনেছে তাদেরকে আমাদের জনপদ থেকে বের করে দিবো, অথবা তোমাদের অবশ্যই আমাদের জাতিতে ফিরে আসতে হবে; সে বললো, যদি আমরা (তোমাদের দ্বীনকে) পছন্দ নাও করি তাহলেও (কি তা মানতে হবে)?', 'Qala almalao allatheena istakbaroo min qawmihi lanukhrijannaka ya shuAAaybu waallatheena amanoo maAAaka min qaryatina aw lataAAoodunna fee millatina qala awalaw kunna kariheena', 1, NOW(), NOW()),
(12, 89, 'قَدِ ٱفۡتَرَيۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِي مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَيۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ', 'সেখান থেকে আল্লাহ তায়ালা আমাদের (একবার) মুক্তি দেয়ার পর যদি আমরা আবার তোমাদের জীবনাদর্শে ফিরে আসি, তাহলে আমরা (এর মাধ্যমে) আল্লাহ তায়ালার ওপর মিথ্যা আরোপ করবো; আমাদের পক্ষে এটা কখনো সম্ভব নয় যে, আমরা সেখানে ফিরে যাবো, (হ্যাঁ) আমাদের রব আল্লাহ তায়ালা যদি আমাদের ব্যাপারে অন্য কিছু চান (তাহলে সেটা ভিন্ন); অবশ্যই আমাদের মালিকের জ্ঞান সব কিছুর ওপর ব্যাপৃত; আমরা একান্তভাবে আল্লাহ তায়ালার ওপর নির্ভর করি; (এবং আমরা বলি,) হে আমাদের রব, আমাদের এবং আমাদের জাতির মাঝে তুমি সঠিক ফয়সালা করে দাও, কারণ তুমিই হচ্ছো সর্বোত্তম ফয়সালাকারী।', 'Qadi iftarayna AAala Allahi kathiban in AAudna fee millatikum baAAda ith najjana Allahu minha wama yakoonu lana an naAAooda feeha illa an yashaa Allahu rabbuna wasiAAa rabbuna kulla shayin AAilman AAala Allahi tawakkalna rabbana iftah baynana wabayna qawmina bialhaqqi waanta khayru alfatiheena', 1, NOW(), NOW()),
(12, 90, 'وَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ لَئِنِ ٱتَّبَعۡتُمۡ شُعَيۡبًا إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ', 'তার জাতির নেতৃস্থানীয় লোক— যারা কুফরী করেছে, তারা (অন্য মানুষদের) বললো, তোমরা যদি শোয়াইবের অনুসরণ করো তাহলে তোমরা অবশ্যই ক্ষতিগ্রস্ত হবে।', 'Waqala almalao allatheena kafaroo min qawmihi laini ittabaAAtum shuAAayban innakum ithan lakhasiroona', 1, NOW(), NOW()),
(12, 91, 'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ', 'অতপর একটা প্রচন্ড ভূকম্পন এসে তাদের (এমনভাবে ) আঘাত করলো, অতপর দেখতে দেখতে তারা সবাই তাদের নিজ নিজ ঘরেই মুখ থুবড়ে পড়ে থাকলো।', 'Faakhathathumu alrrajfatu faasbahoo fee darihim jathimeena', 1, NOW(), NOW()),
(12, 92, 'ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ ٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَانُواْ هُمُ ٱلۡخَٰسِرِينَ', 'যারা শোয়াইবকে অমান্য করলো, তারা যেমন (-ভাবে ধ্বংস হয়ে গেলো দেখে মনে হয়েছে) সেখানে কোনোদিন কেউ বসবাসই করেনি, (বস্তুত) যারা শোয়াইবকে অস্বীকার করেছে তারাই ক্ষতিগ্রস্ত।', 'Allatheena kaththaboo shuAAayban kaan lam yaghnaw feeha allatheena kaththaboo shuAAayban kanoo humu alkhasireena', 1, NOW(), NOW()),
(12, 93, 'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَٰلَٰتِ رَبِّي وَنَصَحۡتُ لَكُمۡۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ', 'এরপর শোয়াইব তাদের কাছ থেকে সরে গেলো, (যাবার সময়) বললো, হে আমার জাতি, আমি তোমাদের কাছে আমার মালিকের বাণীসমূহ পৌঁছে দিয়েছিলাম, আমি (আন্তরিকভাবেই) তোমাদের কল্যাণও কামনা করেছিলাম । আমি কিভাবে এমন সব মানুষের জন্যে (আজ) আফসোস করবো যারা (স্বয়ং আল্লাহকেই) অস্বীকার করে!', 'Fatawalla AAanhum waqala ya qawmi laqad ablaghtukum risalati rabbee wanasahtu lakum fakayfa asa AAala qawmin kafireena', 1, NOW(), NOW()),
(12, 94, 'وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ أَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ', 'আমি কোনো জনপদে কোনো নবী পাঠিয়েছি— অথচ সেই জনপদের মানুষদের অভাব ও কষ্ট দিয়ে পাকড়াও (করে পরীক্ষা) করিনি, এমনটি কখনো হয়নি, আশা করা গিয়েছিলো, তারা (আল্লাহ তায়ালার কাছে) বিনয়াবনত হবে।', 'Wama arsalna fee qaryatin min nabiyyin illa akhathna ahlaha bialbasai waalddarrai laAAallahum yaddarraAAoona', 1, NOW(), NOW()),
(12, 95, 'ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ', 'অতপর আমি তাদের দুঃখ-কষ্টের জায়গাকে সচ্ছল অবস্থা দ্বারা বদলে দিয়েছি, এমনকি যখন তারা (আমার নেয়ামতের) প্রাচুর্য লাভ করলো, তখন তারা (আমাকে ভুলে গেলো এবং) বললো, সচ্ছলতা ও অসচ্ছলতা তো আমাদের পূর্বপুরুষদের ওপরও এসেছে, অতপর আমি তাদের এমন আকস্মিকভাবে পাকড়াও করলাম, তারা টেরও পেলো না।', 'Thumma baddalna makana alssayyiati alhasanata hatta AAafaw waqaloo qad massa abaana alddarrao waalssarrao faakhathnahum baghtatan wahum la yashAAuroona', 1, NOW(), NOW()),
(12, 96, 'وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ', '(অথচ) যদি জনপদের মানুষগুলো (আল্লাহ তায়ালার ওপর) ঈমান আনতো এবং তাকওয়া অবলম্বন করতো, তাহলে আমি তাদের ওপর আসমান-যমীনের যাবতীয় বরকতের দুয়ার খুলে দিতাম, কিন্তু তারা (আমার নবীকে) মিথ্যা প্রতিপন্ন করলো, অতপর তাদের কর্মকান্ডের জন্যে আমি তাদের (ভীষণভাবে) পাকড়াও করলাম।', 'Walaw anna ahla alqura amanoo waittaqaw lafatahna AAalayhim barakatin mina alssamai waalardi walakin kaththaboo faakhathnahum bima kanoo yaksiboona', 1, NOW(), NOW()),
(12, 97, 'أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتٗا وَهُمۡ نَآئِمُونَ', 'লোকালয়ের মানুষগুলো কি এতোই নিৰ্ভয় হয়ে গেছে (তারা মনে করে নিয়েছে, নিঝুম) রাতে তাদের ওপর আমার আযাব আসবে না, যখন তারা (গভীর) ঘুমে (বিভোর) থাকবে!', 'Afaamina ahlu alqura an yatiyahum basuna bayatan wahum naimoona', 1, NOW(), NOW()),
(12, 98, 'أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحٗى وَهُمۡ يَلۡعَبُونَ', 'অথবা জনপদের মানুষগুলো কি নির্ভয় হয়ে গেছে যে,আমার আযাব তাদের ওপর মধ্য দিনে এসে পড়বে না- যখন তারা খেল-তামাশায় মত্ত থাকবে!', 'Awa amina ahlu alqura an yatiyahum basuna duhan wahum yalAAaboona', 1, NOW(), NOW()),
(12, 99, 'أَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ', 'কিংবা তারা কি আল্লাহ তায়ালার কৌশল থেকে নির্ভয় হয়ে গেছে, আসলে আল্লাহ তায়ালার কৌশল থেকে ক্ষতিগ্রস্ত জাতি ছাড়া অন্য কেউই নিশ্চিন্ত থাকতে পারে না।', 'Afaaminoo makra Allahi fala yamanu makra Allahi illa alqawmu alkhasiroona', 1, NOW(), NOW()),
(12, 100, 'أَوَلَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ', '(আগের) লোকদের চলে যাওয়ার পর (সেখানে) যারা পরে দুনিয়ার উত্তরাধিকারী হয়েছে, এ বিষয়টি কি তাদের কখনো হেদায়াতের পথ দেখায় না যে, আমি ইচ্ছা করলে তাদের অপরাধের জন্যে তাদের পাকড়াও করতে পারি এবং (এমনভাবে) তাদের দিলের ওপর মোহর মেরে দিতে পারি, যাতে করে তারা শুনতেই পাবে না।', 'Awalam yahdi lillatheena yarithoona alarda min baAAdi ahliha an law nashao asabnahum bithunoobihim wanatbaAAu AAala quloobihim fahum la yasmaAAoona', 1, NOW(), NOW()),
(12, 101, 'تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآئِهَاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ مِن قَبۡلُۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَٰفِرِينَ', 'এই সে জনপদসমূহ- যার কিছু কিছু কাহিনী আমি তোমাকে শোনাচ্ছি, তাদের কাছে সুস্পষ্ট প্রমাণাদি নিয়ে অবশ্যই রাসূলরা এসেছিলো, কিন্তু তারা যে বিষয়টি এর আগে অস্বীকার করেছিলো, তার ওপর (এবারও) ঈমান আনলো না; আর এভাবেই আল্লাহ তায়ালা কাফেরদের অন্তরে মোহর মেরে দেন।', 'Tilka alqura naqussu AAalayka min anbaiha walaqad jaathum rusuluhum bialbayyinati fama kanoo liyuminoo bima kaththaboo min qablu kathalika yatbaAAu Allahu AAala quloobi alkafireena', 1, NOW(), NOW()),
(12, 102, 'وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدٖۖ وَإِن وَجَدۡنَآ أَكۡثَرَهُمۡ لَفَٰسِقِينَ', 'আমি এদের বেশীসংখ্যক মানুষকেই (আমার সাথে সম্পাদিত) প্রতিশ্রুতির পালনকারী হিসেবে পাইনি, বরং এদের অধিকাংশকেই আমি অপরাধী (হিসেবে) পেয়েছি।', 'Wama wajadna liaktharihim min AAahdin wain wajadna aktharahum lafasiqeena', 1, NOW(), NOW()),
(12, 103, 'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَظَلَمُواْ بِهَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ', 'অতপর আমি মূসাকে আমার সুস্পষ্ট নিদর্শনসমূহ দিয়ে ফেরাউন ও তার পারিষদবর্গের কাছে পাঠিয়েছি, (কি ন্তু) তারা সে (নিদর্শন)গুলোর সাথে যুলুম করেছে, (আজ) তুমি দেখে নাও, (আমার যমীনে) বিপর্যয় সৃষ্টিকারীদের পরিণাম কেমন ছিলো!', 'Thumma baAAathna min baAAdihim moosa biayatina ila firAAawna wamalaihi fathalamoo biha faonuthur kayfa kana AAaqibatu almufsideena', 1, NOW(), NOW()),
(12, 104, 'وَقَالَ مُوسَىٰ يَٰفِرۡعَوۡنُ إِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ', 'মূসা বললো, হে ফেরাউন, অবশ্যই আমি সৃষ্টিকুলের মালিকের পক্ষ থেকে পাঠানো একজন রাসূল।', 'Waqala moosa ya firAAawnu innee rasoolun min rabbi alAAalameena', 1, NOW(), NOW()),
(12, 105, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَيِّنَةٖ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِيَ بَنِيٓ إِسۡرَـٰٓءِيلَ', 'সত্য কথা হচ্ছে, আমি আল্লাহ তায়ালা সম্পর্কে সত্য ছাড়া কিছুই বলবো না, হ্যাঁ, আমি তোমাদের মালিকের পক্ষ থেকে সুস্পষ্ট নিদর্শন নিয়ে এসেছি, অতএব তুমি বনী ইসরাঈলদের (মুক্তি দিয়ে) আমার সাথে যেতে দাও!', 'Haqeequn AAala an la aqoola AAala Allahi illa alhaqqa qad jitukum bibayyinatin min rabbikum faarsil maAAiya banee israeela', 1, NOW(), NOW()),
(12, 106, 'قَالَ إِن كُنتَ جِئۡتَ بِـَٔايَةٖ فَأۡتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'ফেরাউন বললো, তুমি যদি (সত্যিই তেমন) কোনো নিদর্শন নিয়ে এসে থাকো এবং তুমি যদি (তোমার দাবীতে) সত্যবাদী হও, তাহলে তা (সামনে) নিয়ে এসো!', 'Qala in kunta jita biayatin fati biha in kunta mina alssadiqeena', 1, NOW(), NOW()),
(12, 107, 'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ', 'অতপর সে তাঁর হাতের লাঠিটি মাটিতে নিক্ষেপ করলো, সাথে সাথেই তা একটি দৃশ্যমান অজগরে পরিণত হয়ে গেলো-', 'Faalqa AAasahu faitha hiya thuAAbanun mubeenun', 1, NOW(), NOW()),
(12, 108, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ', 'এবং সে (বগল থেকে) তার হাত বের করলো, সাথে সাথে তা (উৎসাহী) দর্শকদের জন্যে চমকাতে লাগলো।', 'WanazaAAa yadahu faitha hiya baydao lilnnathireena', 1, NOW(), NOW()),
(12, 109, 'قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ', '(এসব দেখে) ফেরাউনের জাতির প্রধান ব্যক্তিরা বললো, এ তো (দেখছি) একজন সুদক্ষ যাদুকর!', 'Qala almalao min qawmi firAAawna inna hatha lasahirun AAaleemun', 1, NOW(), NOW()),
(12, 110, 'يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ', '(আসলে এর মাধ্যমে) এ ব্যক্তি তোমাদেরকে তোমাদের দেশ থেকে বের করে দিতে চায়, (এ পরিস্থিতিতে) তোমরা (আমাকে) কী পরামর্শ দিবে?', 'Yureedu an yukhrijakum min ardikum famatha tamuroona', 1, NOW(), NOW()),
(12, 111, 'قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ', 'তারা ফেরাউনকে বললো, আপাতত তাকে এবং তার ভাইকে (এখানে) থাকতে দাও এবং (এ সুযোগে) তোমরা শহরে-বন্দরে (সরকারী) সংগ্রাহক পাঠিয়ে দাও,', 'Qaloo arjih waakhahu waarsil fee almadaini hashireena', 1, NOW(), NOW()),
(12, 112, 'يَأۡتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٖ', 'যেন তারা দেশের সকল দক্ষ যাদুকরদের (অবিলম্বে) তোমার কাছে নিয়ে আসে।', 'Yatooka bikulli sahirin AAaleemin', 1, NOW(), NOW()),
(12, 113, 'وَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ', 'যাদুকররা যখন ফেরাউনের কাছে এলো, তখন তারা বললো, আমরা যদি (মূসার মোকাবেলায়) বিজয়ী হই, তবে আমাদের জন্যে নিশ্চিত পুরস্কারের ব্যবস্থা থাকবে তো!', 'Wajaa alssaharatu firAAawna qaloo inna lana laajran in kunna nahnu alghalibeena', 1, NOW(), NOW()),
(12, 114, 'قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِينَ', 'সে বললো, হ্যাঁ (তা তো অবশ্যই) এবং তোমরাই হবে (দরবারের) ঘনিষ্ঠতম ব্যক্তিদের অন্যতম।', 'Qala naAAam wainnakum lamina almuqarrabeena', 1, NOW(), NOW()),
(12, 115, 'قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ', 'তারা বললো, হে মূসা, (যাদুর বাণ) তুমি আগে নিক্ষেপ করবে— না আমরা নিক্ষেপকারী হবো!', 'Qaloo ya moosa imma an tulqiya waimma an nakoona nahnu almulqeena', 1, NOW(), NOW()),
(12, 116, 'قَالَ أَلۡقُواْۖ فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ', 'সে বললো, তোমরাই (বরং) আগে নিক্ষেপ করো, অতপর তারা (তাদের বাণ) নিক্ষেপ করে মানুষদের দৃষ্টিশক্তির ওপর যাদু করে ফেললো, (নানাভাবে) তারা তাদের ভীত-আতংকিত করে তুললো, তারা (সেদিন সত্যিই) বড়ো যাদু (মন্ত্র) নিয়ে হাযির হয়েছিলো।', 'Qala alqoo falamma alqaw saharoo aAAyuna alnnasi waistarhaboohum wajaoo bisihrin AAatheemin', 1, NOW(), NOW()),
(12, 117, '۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ', 'আমি মূসার কাছে ওহী পাঠালাম, (তাকে বললাম এবার) তুমি (যমীনে) তোমার লাঠিটি নিক্ষেপ করো, (নিক্ষিপ্ত হবার সাথে সাথেই) তা তাদের অলীক বানোয়াটগুলোকে গ্রাস করে ফেললো।', 'Waawhayna ila moosa an alqi AAasaka faitha hiya talqafu ma yafikoona', 1, NOW(), NOW()),
(12, 118, 'فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُواْ يَعۡمَلُونَ', 'ফলে সত্য প্রতিষ্ঠিত হলো, আর তারা যা কিছু বানিয়ে এনেছিলো তা মিথ্যা প্রতিপন্ন হলো।', 'FawaqaAAa alhaqqu wabatala ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(12, 119, 'فَغُلِبُواْ هُنَالِكَ وَٱنقَلَبُواْ صَٰغِرِينَ', 'সেখানে তারা সবাই পরাভূত হলো এবং তারা লাঞ্ছিত হয়ে (ফিরে) গেলো।', 'Faghuliboo hunalika wainqalaboo saghireena', 1, NOW(), NOW()),
(12, 120, 'وَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'যাদুকররাও (সাথে সাথে) সাজদায় লুটিয়ে পড়লো।', 'Waolqiya alssaharatu sajideena', 1, NOW(), NOW()),
(12, 121, 'قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ', '(সমস্বরে) তারা বলে উঠলো, আমরা সৃষ্টিকুলের মালিকের ওপর ঈমান আনলাম,', 'Qaloo amanna birabbi alAAalameena', 1, NOW(), NOW()),
(12, 122, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', '(তিনি) মূসা ও হারূনের রব।', 'Rabbi moosa waharoona', 1, NOW(), NOW()),
(12, 123, 'قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ لِتُخۡرِجُواْ مِنۡهَآ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ', '(ঘটনার এই আকস্মিক মোড় পরিবর্তন দেখে) ফেরাউন বললো, (একি!) আমি তোমাদের কোনো রকম অনুমতি দেয়ার আগেই তোমরা তার ওপর ঈমান আনলে! (আসলে) এটা ছিলো তোমাদের নিশ্চিত ষড়যন্ত্র! (এ) নগরে (বসেই) তোমরা তা পাকিয়েছো, যাতে করে তার অধিবাসীদের তোমরা এখান থেকে বের করে দিতে পারো, অচিরেই তোমরা (এর পরিণাম) জানতে পারবে।', 'Qala firAAawnu amantum bihi qabla an athana lakum inna hatha lamakrun makartumoohu fee almadeenati litukhrijoo minha ahlaha fasawfa taAAlamoona', 1, NOW(), NOW()),
(12, 124, 'لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ', 'আমি অবশ্যই তোমাদের একদিকের হাতগুলো ও অন্যদিকের পাগুলো কেটে ফেলবো, এরপর আমি অবশ্যই তোমাদের সবাইকে শূলে চড়াবো।', 'LaoqatiAAanna aydiyakum waarjulakum min khilafin thumma laosallibannakum ajmaAAeena', 1, NOW(), NOW()),
(12, 125, 'قَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'তারা বললো, আমরা অবশ্যই আমাদের মালিকের কাছে ফিরে যাবো (আমরা তোমার এ শাস্তির পরোয়া করি না)।', 'Qaloo inna ila rabbina munqaliboona', 1, NOW(), NOW()),
(12, 126, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ', 'তুমি আমাদের কাছ থেকে এ কারণেই কি প্রতিশোধ নিচ্ছো যে, আমরা আমাদের মালিকের নিদর্শনসমূহ, যা তাঁর কাছ থেকে আমাদের কাছে এসে পৌঁছেছে- তার ওপর ঈমান এনেছি; (আমরা আল্লাহ তায়ালার কাছে প্রার্থনা করি,) হে আমাদের রব, তুমি আমাদের ধৈর্য ধারণ করার ক্ষমতা দাও এবং (তোমার) অনুগত বান্দা হিসেবে তুমি আমাদের মৃত্যু দিয়ো।', 'Wama tanqimu minna illa an amanna biayati rabbina lamma jaatna rabbana afrigh AAalayna sabran watawaffana muslimeena', 1, NOW(), NOW()),
(12, 127, 'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِيُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَآءَهُمۡ وَنَسۡتَحۡيِۦ نِسَآءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَٰهِرُونَ', 'ফেরাউনের জাতির সরদাররা তাকে বললো, তুমি কি মূসা ও তার দলবলকে এ যমীনে বিপর্যয় সৃষ্টি করার জন্যে এমনিই ছেড়ে দিয়ে রাখবে এবং তারা তোমাকে ও তোমার দেবতাদের (এভাবে) বর্জন করেই চলবে? সে বললো (না, তা কখনো হবে না), আমি (অচিরেই) তাদের ছেলেদের হত্যা করবো এবং তাদের মেয়েদের আমি জীবিত রাখবো, অবশ্যই আমি তাদের ওপর (বিপুল ক্ষমতায়) ক্ষমতাবান।', 'Waqala almalao min qawmi firAAawna atatharu moosa waqawmahu liyufsidoo fee alardi wayatharaka waalihataka qala sanuqattilu abnaahum wanastahyee nisaahum wainna fawqahum qahiroona', 1, NOW(), NOW()),
(12, 128, 'قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ', 'মূসা তার জাতিকে বললো, (তোমরা) আল্লাহর কাছেই সাহায্য চাও এবং ধৈর্য ধারণ করো (মনে রেখো), অবশ্যই (এ) যমীন আল্লাহ তায়ালার, তিনি নিজ বান্দাদের মাঝে যাকে চান তাকেই এ যমীনের উত্তরাধিকার বানান; চূড়ান্ত সাফল্য হচ্ছে তাকওয়া অবলম্বনকারীদের।', 'Qala moosa liqawmihi istaAAeenoo biAllahi waisbiroo inna alarda lillahi yoorithuha man yashao min AAibadihi waalAAaqibatu lilmuttaqeena', 1, NOW(), NOW()),
(12, 129, 'قَالُوٓاْ أُوذِينَا مِن قَبۡلِ أَن تَأۡتِيَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ فَيَنظُرَ كَيۡفَ تَعۡمَلُونَ', 'তারা (মূসাকে) বললো, তুমি আমাদের কাছে (নবী হয়ে) আসার আগেও আমরা নির্যাতিত হয়েছি, আর (এখন) তুমি আমাদের কাছে আসার পরও (কি আমরা নির্যাতিত হবো?) মূসা বললো (হ্যাঁ), খুব তাড়াতাড়িই সম্ভবত তোমাদের রব তোমাদের শত্রুকে ধ্বংস করে দিবেন এবং (এ) দুনিয়ায় তিনি তোমাদের (তাদের) স্থলাভিষিক্ত করবেন, অতপর তিনি দেখবেন তোমরা কিভাবে কাজকর্ম করো!', 'Qaloo ootheena min qabli an tatiyana wamin baAAdi ma jitana qala AAasa rabbukum an yuhlika AAaduwwakum wayastakhlifakum fee alardi fayanthura kayfa taAAmaloona', 1, NOW(), NOW()),
(12, 130, 'وَلَقَدۡ أَخَذۡنَآ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِينَ وَنَقۡصٖ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَذَّكَّرُونَ', 'ক্রমাগত বেশ কয়েক বছর ধরে আমি ফেরাউনের লোকজনদের (দুর্ভিক্ষ ও ফসলের) স্বল্পতা দিয়ে আক্রান্ত করে রেখেছিলাম, আশা (ছিলো) তারা (কিছুটা হলেও) সতর্ক হবে।', 'Walaqad akhathna ala firAAawna bialssineena wanaqsin mina alththamarati laAAallahum yaththakkaroona', 1, NOW(), NOW()),
(12, 131, 'فَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', 'যখন তাদের ওপর ভালো সময় আসতো তখন তারা বলতো, এ তো আমাদের নিজেদের (সৌভাগ্যের কারণেই এসেছে), আবার যখন দুঃসময় তাদের পেয়ে বসতো, তখন নিজেদের দুর্ভাগ্যের ভার তারা মূসা এবং তার সঙ্গী-সাথীদের ওপর আরোপ করতো; (আসলে) তাদের দুর্ভাগ্যের যাবতীয় বিষয় তো আল্লাহ তায়ালার হাতেই রয়েছে, কিন্তু তাদের অধিকাংশ লোকই (এ সম্পর্কে) অবহিত নয়।', 'Faitha jaathumu alhasanatu qaloo lana hathihi wain tusibhum sayyiatun yattayyaroo bimoosa waman maAAahu ala innama tairuhum AAinda Allahi walakinna aktharahum la yaAAlamoona', 1, NOW(), NOW()),
(12, 132, 'وَقَالُواْ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَايَةٖ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ', 'তারা (মূসাকে) বললো, আমাদের ওপর যাদুর প্রভাব বিস্তার করার জন্যে তুমি যতো নিদর্শনই নিয়ে আসো না কেন, আমরা (কিন্তু) কখনো তোমার ওপর ঈমান আনবো না।', 'Waqaloo mahma tatina bihi min ayatin litasharana biha fama nahnu laka bimumineena', 1, NOW(), NOW()),
(12, 133, 'فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ', 'অতপর (এ ধৃষ্টতার জন্যে) আমি তাদের ওপর ঝড়-তুফান (দিলাম), পংগপাল (পাঠালাম), উকুন (ছড়ালাম), ব্যাঙ (ছেড়ে দিলাম) ও রক্ত (-পাতজনিত বিপর্যয়) পাঠালাম, এর সবকয়টিই (এসেছিলো আমার কতিপয়) সুস্পষ্ট নিদর্শন (হিসেবে, কিন্তু এ সত্ত্বেও) তারা অহংকার বড়াই করতেই থাকলো, আসলেই তারা ছিলো। অপরাধী জাতি।', 'Faarsalna AAalayhimu alttoofana waaljarada waalqummala waalddafadiAAa waalddama ayatin mufassalatin faistakbaroo wakanoo qawman mujrimeena', 1, NOW(), NOW()),
(12, 134, 'وَلَمَّا وَقَعَ عَلَيۡهِمُ ٱلرِّجۡزُ قَالُواْ يَٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَئِن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِيٓ إِسۡرَـٰٓءِيلَ', 'তাদের ওপর যখন কোনো বিপর্যয় আসতো, তখন তারা বলতো হে মূসা! তোমার কাছে দেয়া তোমার মালিকের ওয়াদা অনুযায়ী তুমি আমাদের জন্যে তোমার মালিকের কাছে দোয়া করো, যদি (এবারের মতো) আমাদের ওপর থেকে এ বিপদ দূর করে দাও, তাহলে অবশ্যই আমরা তোমার ওপর ঈমান আনবো এবং অবশ্যই আমরা বনী ইসরাঈলদের তোমার সাথে যেতে দিবো।', 'Walamma waqaAAa AAalayhimu alrrijzu qaloo ya moosa odAAu lana rabbaka bima AAahida AAindaka lain kashafta AAanna alrrijza lanuminanna laka walanursilanna maAAaka banee israeela', 1, NOW(), NOW()),
(12, 135, 'فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمۡ يَنكُثُونَ', 'অতপর যখন তাদের ওপর থেকে একটি নির্দিষ্ট সময়ের জন্যে- যে সময়টুকু সে জন্যে নির্ধারিত ছিলো- সে বালা-মসিবত আমি অপসারণ করে নিতাম, তখন সাথে সাথেই তারা ওয়াদা ভঙ্গ করে ফেলতো।', 'Falamma kashafna AAanhumu alrrijza ila ajalin hum balighoohu itha hum yankuthoona', 1, NOW(), NOW()),
(12, 136, 'فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ', 'অতপর আমি তাদের কাছ থেকে (ওয়াদা ভঙ্গের) প্রতিশোধ নিলাম, তাদের আমি সাগরে ডুবিয়ে দিলাম, কেননা, তারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করেছিলো এবং তারা ছিলো এসব (নিদর্শন) থেকে উদাসীন।', 'Faintaqamna minhum faaghraqnahum fee alyammi biannahum kaththaboo biayatina wakanoo AAanha ghafileena', 1, NOW(), NOW()),
(12, 137, 'وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ', 'এবার আমি তাদেরকে ক্ষমতার আসনে বসিয়ে দিলাম- যাদের (এতোদিন) দুর্বল করে রাখা হয়েছিলো, (তাদের আমি) এ রাজ্যের পূর্ব-পশ্চিম (-সহ সব কয়টি) প্রান্তের অধিকারী বানিয়ে দিলাম, যাতে আমি আমার প্রভূত কল্যাণ ছড়িয়ে দিয়েছি। (এভাবেই) বনী ইসরাঈলের ওপর প্রদত্ত তোমার মালিকের (প্রতিশ্রুতির) সেই কল্যাণবাণী সত্যে পরিণত হলো, কেননা তারা ধৈর্য ধারণ করেছিলো; ফেরাউন ও তার জাতির যাবতীয় শিল্পকর্ম ও উঁচু প্রাসাদ-যা তারা নির্মাণ করেছিলো, আমি সব কিছুই ধ্বংস করে দিলাম।', 'Waawrathna alqawma allatheena kanoo yustadAAafoona mashariqa alardi wamagharibaha allatee barakna feeha watammat kalimatu rabbika alhusna AAala banee israeela bima sabaroo wadammarna ma kana yasnaAAu firAAawnu waqawmuhu wama kanoo yaAArishoona', 1, NOW(), NOW()),
(12, 138, 'وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ', '(ফেরাউনকে ডুবিয়ে মারার পর) আমি বনী ইসরাঈলদের সমুদ্র পার করিয়ে দিয়েছি, অতপর (সমুদ্রের ওপারে) তারা এমন একটি জাতির কাছে এসে পৌঁছলো, যারা (সব সময়) তাদের মূর্তিদের ওপর পূজার অর্ঘ দেয়ার জন্যে বসে থাকতো, (এদের দেখে বনী ইসরাঈলের) লোকেরা বললো, হে মূসা, তুমি আমাদের জন্যেও একটি দেবতা বানিয়ে দাও, যেমন দেবতা রয়েছে এদের; (এ কথা শুনে) সে তাদের বললো, নিসন্দেহে তোমরা হচ্ছো এক মূর্খ জাতি।', 'Wajawazna bibanee israeela albahra faataw AAala qawmin yaAAkufoona AAala asnamin lahum qaloo ya moosa ijAAal lana ilahan kama lahum alihatun qala innakum qawmun tajhaloona', 1, NOW(), NOW()),
(12, 139, 'إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٞ مَّا هُمۡ فِيهِ وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ', 'এ লোকেরা যেসব কাজে লিপ্ত রয়েছে, তা (একদিন) ধ্বংস করে দেয়া হবে এবং এরা যা করছে তাও সম্পূর্ণ বাতিল (সাব্যস্ত) হবে।', 'Inna haolai mutabbarun ma hum feehi wabatilun ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(12, 140, 'قَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ', 'সে বললো, আমি কি তোমাদের জন্যে আল্লাহ তায়ালাকে বাদ দিয়ে অন্য মাবুদ তালাশ করবো— অথচ তিনি তোমাদের সৃষ্টিকূলের ওপর শ্রেষ্ঠত্ব দান করেছেন।', 'Qala aghayra Allahi abgheekum ilahan wahuwa faddalakum AAala alAAalameena', 1, NOW(), NOW()),
(12, 141, 'وَإِذۡ أَنجَيۡنَٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ يُقَتِّلُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ', '(স্মরণ করো) যখন আমি তোমাদেরকে ফেরাউনের লোকজনদের কাছ থেকে মুক্ত করেছিলাম, তারা তোমাদের মর্মান্তিক শাস্তি দিতো, তারা তোমাদের পুত্র-সন্তানদের হত্যা করতো, আর তোমাদের মেয়েদের তারা জীবিত ছেড়ে দিতো; এতে তোমাদের জন্যে তোমাদের মালিকের পক্ষ থেকে এক মহাপরীক্ষা নিহিত ছিলো।', 'Waith anjaynakum min ali firAAawna yasoomoonakum sooa alAAathabi yuqattiloona abnaakum wayastahyoona nisaakum wafee thalikum balaon min rabbikum AAatheemun', 1, NOW(), NOW()),
(12, 142, '۞وَوَٰعَدۡنَا مُوسَىٰ ثَلَٰثِينَ لَيۡلَةٗ وَأَتۡمَمۡنَٰهَا بِعَشۡرٖ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرۡبَعِينَ لَيۡلَةٗۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ', 'আমি মূসাকে (আমার কাছে ডাকার জন্যে) তিরিশটি রাত নির্ধারণ করে দিয়েছিলাম, (পরে) আরো দশ মিলিয়ে তা পূর্ণ করেছি, এভাবেই তাঁর জন্যে তাঁর মালিকের নির্ধারিত সময় চল্লিশ রাতের মেয়াদ পূর্ণ হয়েছে, (যাত্রার প্রাক্কালে) মূসা তার ভাই হারুনকে বললো, (আমার অবর্তমানে) আমার জাতির মাঝে তুমি আমার প্রতিনিধিত্ব করবে, তাদের সংশোধন করবে, কখনো বিশৃংখলা সৃষ্টিকারীদের কথামতো চলবে না।', 'WawaAAadna moosa thalatheena laylatan waatmamnaha biAAashrin fatamma meeqatu rabbihi arbaAAeena laylatan waqala moosa liakheehi haroona okhlufnee fee qawmee waaslih wala tattabiAA sabeela almufsideena', 1, NOW(), NOW()),
(12, 143, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ', 'যখন মূসা আমার সাক্ষাতের জন্যে (নির্ধারিত স্থানে) এসে পৌঁছলো এবং তাঁর রব তাঁর সাথে কথা বললেন, তখন সে বললো, হে আমার রব, (তোমাকে) আমায় দেখিয়ে দাও, আমি (স্বচক্ষে) তোমার দিকে তাকাই; তিনি বললেন (না), তুমি কখনো আমাকে দেখতে পাবে না, তুমি বরং (অনতিদূরের) পাহাড়টির দিকে তাকিয়ে দেখো, যদি (আমার নূর দেখার পর) পাহাড়টি স্বস্থানে স্থির হয়ে দাঁড়িয়ে থাকতে পারে, তাহলে তুমি অবশ্যই (সেখানে) আমায় দেখতে পাবে, অতপর যখন তার রব পাহাড়ের ওপর (স্বীয়) জ্যোতি নিক্ষেপ করলেন, তখন তা পাহাড়কে চূর্ণ-বিচূর্ণ করে দিলো, (সাথে সাথেই) মূসা বেহুশ হয়ে গেলো, (পরে) যখন সে সংজ্ঞা ফিরে পেলো (তখন) সে বললো, মহাপবিত্রতা তোমার (হে আল্লাহ), আমি তোমার কাছে তাওবা করছি, আর তোমার ওপর ঈমান আনয়নকারীদের মধ্যে আমিই (হতে চাই) প্রথম।', 'Walamma jaa moosa limeeqatina wakallamahu rabbuhu qala rabbi arinee anthur ilayka qala lan taranee walakini onthur ila aljabali faini istaqarra makanahu fasawfa taranee falamma tajalla rabbuhu liljabali jaAAalahu dakkan wakharra moosa saAAiqan falamma afaqa qala subhanaka tubtu ilayka waana awwalu almumineena', 1, NOW(), NOW()),
(12, 144, 'قَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي فَخُذۡ مَآ ءَاتَيۡتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ', 'আল্লাহ তায়ালা বললেন, হে মূসা, আমি মানুষের মাঝ থেকে তোমাকে আমার নবুওত ও আমার সাথে বাক্যালাপের মর্যাদা দিয়ে বাছাই করে নিয়েছি, অতএব আমি তোমাকে (হেদায়াতের) যা কিছু (বাণী) দিয়েছি তা (নিষ্ঠার সাথে) গ্রহণ করো এবং (এ জন্যে তুমি আমার) কৃতজ্ঞ বান্দাহদের দলে শামিল হয়ে যাও।', 'Qala ya moosa innee istafaytuka AAala alnnasi birisalatee wabikalamee fakhuth ma ataytuka wakun mina alshshakireena', 1, NOW(), NOW()),
(12, 145, 'وَكَتَبۡنَا لَهُۥ فِي ٱلۡأَلۡوَاحِ مِن كُلِّ شَيۡءٖ مَّوۡعِظَةٗ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ فَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ', 'এই ফলকের মধ্যে আমি তাঁর জন্যে সব উপদেশমালা ও সব কিছুর বিস্তারিত বিবরণ লিখে দিলাম, অতএব এটা (শক্ত করে) আঁকড়ে ধরো এবং তোমার জাতির লোকদের বলো, তারা যেন (এই) ভালো ভালো কথাগুলো গ্রহণ করে; অচিরেই আমি তোমাদের (ধ্বংসপ্রাপ্ত) পাপীদের আস্তানা দেখাবো।', 'Wakatabna lahu fee alalwahi min kulli shayin mawAAithatan watafseelan likulli shayin fakhuthha biquwwatin wamur qawmaka yakhuthoo biahsaniha saoreekum dara alfasiqeena', 1, NOW(), NOW()),
(12, 146, 'سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ', 'অচিরেই আমি সেসব মানুষের দৃষ্টি আমার নিদর্শন থেকে (ভিন্ন দিকে) ফিরিয়ে দিবো, যারা পৃথিবীতে অন্যায়ভাবে বাহাদুরী করে বেড়ায়; (আসলে) এ লোকেরা যদি (অতীত ধ্বংসাবশেষের) সব কয়টি চিহ্নও দেখতে পায়, তবু তারা তার ওপর ঈমান আনবে না, যদি তারা সঠিক পথ দেখতেও পায়, তবু তারা (পথকে) পথ বলে গ্রহণ করবে না, যদি এর কোথাও কোনো বাঁকা পথ তারা দেখতে পায়, তাহলে তাকেই তারা (অনুসরণযোগ্য) পথ হিসেবে গ্রহণ করবে; এটা এ কারণে, তারা আমার আয়াতসমূহকে মিথ্যা সাব্যস্ত করেছে এবং তারা এ (আযাব) থেকেও উদাসীন ছিলো।', 'Saasrifu AAan ayatiya allatheena yatakabbaroona fee alardi bighayri alhaqqi wain yaraw kulla ayatin la yuminoo biha wain yaraw sabeela alrrushdi la yattakhithoohu sabeelan wain yaraw sabeela alghayyi yattakhithoohu sabeelan thalika biannahum kaththaboo biayatina wakanoo AAanha ghafileena', 1, NOW(), NOW()),
(12, 147, 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلۡأٓخِرَةِ حَبِطَتۡ أَعۡمَٰلُهُمۡۚ هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ', 'যারা আমার আয়াতসমূহ ও পরকালের সামনা সামনি হওয়ার বিষয়কে অস্বীকার করেছে, তাদের সব কার্যকলাপই বিনষ্ট হয়ে গেছে; আর তারা (এ দুনিয়ায়) যা কিছু করবে তাদের এ ছাড়া আর কি প্রতিফল দেয়া হবে?', 'Waallatheena kaththaboo biayatina waliqai alakhirati habitat aAAmaluhum hal yujzawna illa ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(12, 148, 'وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِيِّهِمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٌۚ أَلَمۡ يَرَوۡاْ أَنَّهُۥ لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ سَبِيلًاۘ ٱتَّخَذُوهُ وَكَانُواْ ظَٰلِمِينَ', 'মূসার জাতির লোকেরা তার (তূর পর্বতে গমনের) পর নিজেদের অলংকার দিয়ে একটি গো-বাছুর বানিয়ে নিলো, (তা ছিলো জীবনবিহীন) একটি দেহমাত্র- যার আওয়ায ছিলো শুধু (গরুর) হাম্বা রব; এ লোকেরা কি দেখতে পায় না, সে (দেহ)-টি তাদের সাথে কোনো কথা বলে না, না সেটি তাদের কোনো পথের দিশা দেয়, ( কিন্তু এ সত্ত্বেও) তারা সেটিকে (মাবুদ বলে) গ্রহণ করলো, তারা ছিলো (আসলেই) যালিম।', 'Waittakhatha qawmu moosa min baAAdihi min huliyyihim AAijlan jasadan lahu khuwarun alam yaraw annahu la yukallimuhum wala yahdeehim sabeelan ittakhathoohu wakanoo thalimeena', 1, NOW(), NOW()),
(12, 149, 'وَلَمَّا سُقِطَ فِيٓ أَيۡدِيهِمۡ وَرَأَوۡاْ أَنَّهُمۡ قَدۡ ضَلُّواْ قَالُواْ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ', 'অতপর যখন তারা অনুতপ্ত হলো এবং এটা দেখতে পেলো যে, তারা পথভ্রষ্ট হয়ে গেছে, তখন তারা বললো, আমাদের রব যদি আমাদের ওপর দয়া না করেন এবং (গো-বাছুরকে মাবুদ বানানোর জন্যে) যদি তিনি আমাদের ক্ষমা না করেন, তাহলে আমরা নিশ্চিত ক্ষতিগ্রস্ত লোকদের দলে শামিল হয়ে যাবে।', 'Walamma suqita fee aydeehim waraaw annahum qad dalloo qaloo lain lam yarhamna rabbuna wayaghfir lana lanakoonanna mina alkhasireena', 1, NOW(), NOW()),
(12, 150, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي فَلَا تُشۡمِتۡ بِيَ ٱلۡأَعۡدَآءَ وَلَا تَجۡعَلۡنِي مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'মূসা যখন ক্রুদ্ধ ও ক্ষুব্ধ হয়ে নিজের লোকজনের কাছে ফিরে এলো, তখন সে (এসব কথা শুনে) বললো, আমার (তূর পর্বতে যাওয়ার) পর তোমরা কি জঘন্য কাজই না করেছো! তোমরা কি তোমাদের মালিকের আদেশ আসার আগেই (সে ব্যাপারে) তাড়াহুড়া (শুরু) করলে! (রাগে ও ক্ষোভে) সে ফলকগুলো (একদিকে) রেখে দিলো এবং তার ভাইর মাথা (-র চুল) ধরে তাকে নিজের দিকে টেনে আনলো; (তার) সে (ভাই) বললো, হে আমার মায়ের ছেলে (আমার সহোদর ভাই), এ জাতির লোকগুলো আমাকে দুর্বল করে দিতে চেয়েছিলো, তারা আমাকে প্রায় মেরেই ফেলছিলো, তুমি (আজ) আমার সাথে এমন কোনো আচরণ করো না যা শত্রুদের আনন্দিত করবে, আর তুমি আমাকে কখনো যালিম সম্প্রদায়ের অন্তর্ভুক্ত করো না।', 'Walamma rajaAAa moosa ila qawmihi ghadbana asifan qala bisama khalaftumoonee min baAAdee aAAajiltum amra rabbikum waalqa alalwaha waakhatha birasi akheehi yajurruhu ilayhi qala ibna omma inna alqawma istadAAafoonee wakadoo yaqtuloonanee fala tushmit biya alaAAdaa wala tajAAalnee maAAa alqawmi alththalimeena', 1, NOW(), NOW()),
(12, 151, 'قَالَ رَبِّ ٱغۡفِرۡ لِي وَلِأَخِي وَأَدۡخِلۡنَا فِي رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ', 'মূসা বললো, হে আমার রব, আমাকে ও আমার ভাইকে তুমি মাফ করে দাও এবং তুমি আমাদের তোমার রহমতের মধ্যে দাখিল করে নাও, তুমি সবচাইতে বড়ো দয়াবান।', 'Qala rabbi ighfir lee waliakhee waadkhilna fee rahmatika waanta arhamu alrrahimeena', 1, NOW(), NOW()),
(12, 152, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ', 'অবশ্যই যেসব লোক গরুর বাছুরকে মাবুদ বানিয়েছে, অচিরেই তাদের ওপর তাদের মালিকের পক্ষ থেকে গযব আসবে, আর দুনিয়ার জীবনেও (তাদের জন্যে থাকবে) অপমান এবং লাঞ্ছনা; (আল্লাহ তায়ালার নামে) মিথ্যা রটনাকারীদের আমি এভাবেই শাস্তি দিয়ে থাকি।', 'Inna allatheena ittakhathoo alAAijla sayanaluhum ghadabun min rabbihim wathillatun fee alhayati alddunya wakathalika najzee almuftareena', 1, NOW(), NOW()),
(12, 153, 'وَٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُواْ مِنۢ بَعۡدِهَا وَءَامَنُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ', 'যেসব লোক অন্যায় কাজ করেছে, এরপর তারা তাওবা করেছে এবং (যথাযথ) ঈমান এনেছে, নিশ্চয়ই এ (যথার্থ) তাওবার পর তোমার রব (তাদের ওপর) ক্ষমাশীল ও পরম দয়ালু (হবেন)।', 'Waallatheena AAamiloo alssayyiati thumma taboo min baAAdiha waamanoo inna rabbaka min baAAdiha laghafoorun raheemun', 1, NOW(), NOW()),
(12, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ', 'পরে যখন মূসার ক্রোধ (কিছুটা) প্রশমিত হলো, তখন সে (তাওরাতের) ফলকগুলো তুলে নিলো, তার পাতায় ছিলো হেদায়াত ও রহমত (সম্বলিত কথা)- এমন সব লোকের জন্যে যারা তাদের মালিককে ভয় করে।', 'Walamma sakata AAan moosa alghadabu akhatha alalwaha wafee nuskhatiha hudan warahmatun lillatheena hum lirabbihim yarhaboona', 1, NOW(), NOW()),
(12, 155, 'وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِينَ رَجُلٗا لِّمِيقَٰتِنَاۖ فَلَمَّآ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِيَّـٰيَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآۖ إِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي مَن تَشَآءُۖ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ', 'মূসা তার সম্প্রদায়ের মধ্য থেকে সত্তর জন লোককে আমার নির্ধারিত সময়ে সমবেত হবার জন্যে বাছাই করে নিলো, যখন প্রচন্ড ভূকম্পন এসে তাদের পাকড়াও করলো (তখন) মূসা বললো, হে আমার রব, তুমি চাইলে তাদের সবাইকে ও আমাকে আগেই ধ্বংস করে দিতে পারতে; আমাদের মধ্যকার নির্বোধ মানুষরা যে আচরণ করেছে, (তার জন্যে) তুমি কি আমাদের ধ্বংস করে দিবে! অথচ সে ব্যাপারটা তোমার একটা পরীক্ষা ছাড়া আর কিছুই ছিলো না;এ (পরীক্ষা) দিয়ে যাকে চাও তাকে তুমি বিপথগামী করো, যাকে চাও তাকে সঠিক পথও দেখাও! তুমিই আমাদের অভিভাবক, তুমি আমাদের ক্ষমা করে দাও, আমাদের ওপর তুমি দয়া করো, কেননা তুমিই হচ্ছো সর্বশ্রেষ্ঠ ক্ষমার আধার।', 'Waikhtara moosa qawmahu sabAAeena rajulan limeeqatina falamma akhathathumu alrrajfatu qala rabbi law shita ahlaktahum min qablu waiyyaya atuhlikuna bima faAAala alssufahao minna in hiya illa fitnatuka tudillu biha man tashao watahdee man tashao anta waliyyuna faighfir lana wairhamna waanta khayru alghafireena', 1, NOW(), NOW()),
(12, 156, '۞وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءٖۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ', 'এই দুনিয়ায় তুমি আমাদের জন্যে কল্যাণ লিখে দাও, (কল্যাণ লিখে দাও) পরকালেও অবশ্যই আমরা তোমার দিকে প্রত্যাবর্তিত হয়েছি; আল্লাহ তায়ালা বললেন (হ্যাঁ), আমার শাস্তি আমি যাকে ইচ্ছা তাকেই দেই, আর আমার দয়া তো (সৃষ্টির) সবকয়টি জিনিসকেই পরিবেষ্টন করে রেখেছে; আমি অচিরেই এমন লোকদের জন্যে তা লিখে দিবো, যারা তাকওয়া অবলম্বন করে, যারা যাকাত আদায় করে, (সর্বোপরি) যারা আমার আয়াতসমূহের ওপর ঈমান আনে।', 'Waoktub lana fee hathihi alddunya hasanatan wafee alakhirati inna hudna ilayka qala AAathabee oseebu bihi man ashao warahmatee wasiAAat kulla shayin fasaaktubuha lillatheena yattaqoona wayutoona alzzakata waallatheena hum biayatina yuminoona', 1, NOW(), NOW()),
(12, 157, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ يَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَيَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَـٰٓئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَٰلَ ٱلَّتِي كَانَتۡ عَلَيۡهِمۡۚ فَٱلَّذِينَ ءَامَنُواْ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُواْ ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'যারা এই বার্তাবাহক নিরক্ষর রাসূলের অনুসরণ করে চলে- যা তারা তাদের (কিতাব) তাওরাত ও ইনজীলেও লিখিত দেখতে পাচ্ছে, যে (নবী) তাদের ভালো কাজের আদেশ দেয়, মন্দ কাজ থেকে বিরত রাখে, যে তাদের জন্যে যাবতীয় পাক জিনিসকে হালাল ও নাপাক জিনিসসমূহকে তাদের ওপর হারাম ঘোষণা করে, তাদের ঘাড় থেকে (মানুষের গোলামীর) যে বোঝা ছিলো তা সে নামিয়ে রাখে এবং (মানুষের চাপানো) যেসব বন্ধন তাদের (গলার) ওপর (ঝুলানো) ছিলো তা সে ফেলে দেয়; অতপর যারা তার ওপর ঈমান এনেছে, যারা তাকে সম্মান দিয়েছে, যারা তাকে সাহায্য সহযোগিতা করেছে, (সর্বোপরি) তার সাথে (কুরআনের) যে আলো নাজিল করা হয়েছে তার অনুসরণ করেছে, তারাই হচ্ছে সফলকাম।', 'Allatheena yattabiAAoona alrrasoola alnnabiyya alommiyya allathee yajidoonahu maktooban AAindahum fee alttawrati waalinjeeli yamuruhum bialmaAAroofi wayanhahum AAani almunkari wayuhillu lahumu alttayyibati wayuharrimu AAalayhimu alkhabaitha wayadaAAu AAanhum israhum waalaghlala allatee kanat AAalayhim faallatheena amanoo bihi waAAazzaroohu wanasaroohu waittabaAAoo alnnoora allathee onzila maAAahu olaika humu almuflihoona', 1, NOW(), NOW()),
(12, 158, 'قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ ٱلَّذِي يُؤۡمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ', '(হে মুহাম্মদ,) তুমি বলো, হে মানুষ, অবশ্যই আমি তোমাদের সবার কাছে আল্লাহ তায়ালার রাসূল হিসেবে এসেছি), আকাশমালা ও পৃথিবীর যাবতীয় সার্বভৌমত্বের একচ্ছত্র মালিকানা তাঁর, তিনি ছাড়া আর কোনো মাবুদ নেই, তিনিই জীবন দান করেন, তিনিই মৃত্যু ঘটান, অতপর তোমরা আল্লাহ তায়ালার ওপর ঈমান আনো, তাঁর বার্তাবাহক নিরক্ষর রাসূলের ওপর তোমরা ঈমান আনো, যে (রাসূল নিজেও) আল্লাহ তায়ালা ও তাঁর বাণীতে বিশ্বাস করে এবং তোমরা তাকে অনুসরণ করো, আশা করা যায় তোমরা সঠিক পথের সন্ধান পেয়ে যাবে।', 'Qul ya ayyuha alnnasu innee rasoolu Allahi ilaykum jameeAAan allathee lahu mulku alssamawati waalardi la ilaha illa huwa yuhyee wayumeetu faaminoo biAllahi warasoolihi alnnabiyyi alommiyyi allathee yuminu biAllahi wakalimatihi waittabiAAoohu laAAallakum tahtadoona', 1, NOW(), NOW()),
(12, 159, 'وَمِن قَوۡمِ مُوسَىٰٓ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ', 'মূসার জাতির মধ্যে এমন একটি সম্প্রদায়ও আছে, যারা (অন্যদের) সত্যের পথ দেখায় এবং তা দিয়ে ইনসাফ করে।', 'Wamin qawmi moosa ommatun yahdoona bialhaqqi wabihi yaAAdiloona', 1, NOW(), NOW()),
(12, 160, 'وَقَطَّعۡنَٰهُمُ ٱثۡنَتَيۡ عَشۡرَةَ أَسۡبَاطًا أُمَمٗاۚ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَيۡهِمُ ٱلۡغَمَٰمَ وَأَنزَلۡنَا عَلَيۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', 'আমি তাদের বারোটি গোত্রে ভাগ করে তাদের স্বতন্ত্র দলে পরিণত করে দিয়েছি, মূসার সম্প্রদায়ের লোকেরা যখন তার কাছে পানি চাইলো, তখন আমি মূসাকে ওহী পাঠিয়ে বললাম, তুমি তোমার হাতের লাঠি দ্বারা পাথরে আঘাত করো, অতপর তা থেকে বারোটি ঝর্ণাধারা বের হলো; প্রত্যেকটি মানুষ তাদের (নিজেদের) পানি পান করার স্থান চিনে নিলো; আমি তাদের ওপর মেঘের ছায়া বিস্তার করে দিলাম, তাদের কাছে ‘মান’ ও ‘সালওয়া’ (নামক উৎকৃষ্ট খাবার) পাঠালাম; (তাদের আমি বললাম,) তোমাদের আমি যেসব পবিত্র জিনিস দান করেছি তা তোমরা খাও; (আমার কৃতজ্ঞতা আদায় না করে) তারা আমার ওপর কোনো যুলুম করেনি, বরং তারা যুলুম করেছে তাদের নিজেদের ওপর।', 'WaqattaAAnahumu ithnatay AAashrata asbatan omaman waawhayna ila moosa ithi istasqahu qawmuhu ani idrib biAAasaka alhajara fainbajasat minhu ithnata AAashrata AAaynan qad AAalima kullu onasin mashrabahum wathallalna AAalayhimu alghamama waanzalna AAalayhimu almanna waalssalwa kuloo min tayyibati ma razaqnakum wama thalamoona walakin kanoo anfusahum yathlimoona', 1, NOW(), NOW()),
(12, 161, 'وَإِذۡ قِيلَ لَهُمُ ٱسۡكُنُواْ هَٰذِهِ ٱلۡقَرۡيَةَ وَكُلُواْ مِنۡهَا حَيۡثُ شِئۡتُمۡ وَقُولُواْ حِطَّةٞ وَٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا نَّغۡفِرۡ لَكُمۡ خَطِيٓـَٰٔتِكُمۡۚ سَنَزِيدُ ٱلۡمُحۡسِنِينَ', 'যখন তাদের বলা হয়েছিলো, তোমরা এই জনপদে বসবাস করো এবং সেখান থেকে যা কিছু চাও তোমরা আহার করো, তোমরা বলো (হে আল্লাহ), আমরা তোমার কাছে ক্ষমা চাই, আর (যখন সেই) জনপদের দ্বারপথ দিয়ে ভেতরে প্রবেশ করবে, (তখন) সাজদাবনত অবস্থায় প্রবেশ করবে, আমি তোমাদের গুনাহসমূহ মাফ করে দিবো; আমি অচিরেই (এসব) উত্তম লোকদের অতিরিক্ত দান করবো।', 'Waith qeela lahumu oskunoo hathihi alqaryata wakuloo minha haythu shitum waqooloo hittatun waodkhuloo albaba sujjadan naghfir lakum khateeatikum sanazeedu almuhsineena', 1, NOW(), NOW()),
(12, 162, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ قَوۡلًا غَيۡرَ ٱلَّذِي قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَظۡلِمُونَ', 'কিন্তু তাদের মধ্যে যারা যালিম ছিলো, তারা তাদের যা (করতে) বলা হয়েছিলো তা সম্পূর্ণ বদলে দিয়ে ভিন্ন কথা বললো, অতপর আমিও তাদের এ যুলুমের শাস্তি হিসেবে তাদের ওপর আসমান থেকে আযাব পাঠালাম।', 'Fabaddala allatheena thalamoo minhum qawlan ghayra allathee qeela lahum faarsalna AAalayhim rijzan mina alssamai bima kanoo yathlimoona', 1, NOW(), NOW()),
(12, 163, 'وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ يَعۡدُونَ فِي ٱلسَّبۡتِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَبۡتِهِمۡ شُرَّعٗا وَيَوۡمَ لَا يَسۡبِتُونَ لَا تَأۡتِيهِمۡۚ كَذَٰلِكَ نَبۡلُوهُم بِمَا كَانُواْ يَفۡسُقُونَ', 'তাদের কাছ থেকে সেই জনপদ সম্পর্কে জিজ্ঞেস করো, যা ছিলো সাগরের পাড়ে। যখন সেখানকার মানুষরা শনিবারে (আল্লাহ তায়ালার) সীমালংঘন করতো, যখন শনিবারে (সাগরের) মাছগুলো তাদের কাছে উঁচু হয়ে পানির উপরিভাগে (ভেসে) আসতো এবং শনিবার ছাড়া অন্য কোনোদিন আসতো না, এভাবেই আমি তাদের অবাধ্যতার কারণে তাদের পরীক্ষা নিচ্ছিলাম।', 'Waisalhum AAani alqaryati allatee kanat hadirata albahri ith yaAAdoona fee alssabti ith tateehim heetanuhum yawma sabtihim shurraAAan wayawma la yasbitoona la tateehim kathalika nabloohum bima kanoo yafsuqoona', 1, NOW(), NOW()),
(12, 164, 'وَإِذۡ قَالَتۡ أُمَّةٞ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗاۖ قَالُواْ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّقُونَ', 'যখন তাদের একদল লোক এও বলছিলো যে, তোমরা এমন একটি দলকে কেন উপদেশ দিতে যাচ্ছো, যাদের আল্লাহ তায়ালা ধ্বংস করতে চান, অথবা (গুনাহের জন্যে) যাদের তিনি কঠোর শাস্তি দিতে যাচ্ছেন, তারা বললো, এটা হচ্ছে তোমাদের মালিকের দরবারে (নিজেদের পক্ষে) একটা ওযর পেশ করা, আশা ছিলো তারা সাবধান হবে।', 'Waith qalat ommatun minhum lima taAAithoona qawman Allahu muhlikuhum aw muAAaththibuhum AAathaban shadeedan qaloo maAAthiratan ila rabbikum walaAAallahum yattaqoona', 1, NOW(), NOW()),
(12, 165, 'فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦٓ أَنجَيۡنَا ٱلَّذِينَ يَنۡهَوۡنَ عَنِ ٱلسُّوٓءِ وَأَخَذۡنَا ٱلَّذِينَ ظَلَمُواْ بِعَذَابِۭ بَـِٔيسِۭ بِمَا كَانُواْ يَفۡسُقُونَ', 'অতপর যা তাদের (বার বার) স্মরণ করানো হচ্ছিলো তা তারা ভুলে গেলো, তখন আমি (সে দল থেকে) এমন লোকদের উদ্ধার করলাম, যারা নিজেরা গুনাহ থেকে বেঁচে থাকতো, আর যারা যুলুম করেছে তাদের কঠিন শাস্তি দিয়ে আমি পাকড়াও করলাম, কেননা তারা নিজেরা গুনাহ করছিলো।', 'Falamma nasoo ma thukkiroo bihi anjayna allatheena yanhawna AAani alssooi waakhathna allatheena thalamoo biAAathabin baeesin bima kanoo yafsuqoona', 1, NOW(), NOW()),
(12, 166, 'فَلَمَّا عَتَوۡاْ عَن مَّا نُهُواْ عَنۡهُ قُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ', 'তাদেরকে যেসব (ঘৃণিত) কাজ থেকে নিষেধ করা হয়েছিলো, যখন তারা তা (ধৃষ্টতার সাথে) করে যাচ্ছিলো, তখন আমি তাদের বললাম, তোমরা সবাই লাঞ্ছিত বানর হয়ে যাও।', 'Falamma AAataw AAan ma nuhoo AAanhu qulna lahum koonoo qiradatan khasieena', 1, NOW(), NOW()),
(12, 167, 'وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَبۡعَثَنَّ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَن يَسُومُهُمۡ سُوٓءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمٞ', '(স্মরণ করো,) যখন তোমার রব (ইহুদীদের উদ্দেশে) ঘোষণা দিলেন, তিনি কেয়ামত পর্যন্ত এ জাতির ওপর এমন লোকদের (শক্তিধর করে) পাঠাতে থাকবেন, যারা তাদের নিকৃষ্ট ধরনের শাস্তি দিতে থাকবে; অবশ্যই তোমার রব (যেমনই) সত্বর শাস্তি দান করেন, (তেমনই) তিনি ক্ষমাশীল ও পরম দয়ালু।', 'Waith taaththana rabbuka layabAAathanna AAalayhim ila yawmi alqiyamati man yasoomuhum sooa alAAathabi inna rabbaka lasareeAAu alAAiqabi wainnahu laghafoorun raheemun', 1, NOW(), NOW()),
(12, 168, 'وَقَطَّعۡنَٰهُمۡ فِي ٱلۡأَرۡضِ أُمَمٗاۖ مِّنۡهُمُ ٱلصَّـٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَٰلِكَۖ وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمۡ يَرۡجِعُونَ', 'আমি তাদের দলে দলে বিভক্ত করে যমীনে ছড়িয়ে দিয়েছি, তাদের মধ্যে কিছু (ছিলো) নেককার মানুষ, আবার কিছু (ছিলো) এর চাইতে ভিন্ন (ধরনের), ভালো-মন্দ (উভয়) অবস্থার (সম্মুখীন) করে আমি তাদের পরীক্ষা নিয়েছি, আশা করা গিয়েছিলো, তারা (হেদায়াতের পথে) প্রত্যাবর্তন করবে।', 'WaqattaAAnahum fee alardi omaman minhumu alssalihoona waminhum doona thalika wabalawnahum bialhasanati waalssayyiati laAAallahum yarjiAAoona', 1, NOW(), NOW()),
(12, 169, 'فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ وَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡهِم مِّيثَٰقُ ٱلۡكِتَٰبِ أَن لَّا يَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُواْ مَا فِيهِۗ وَٱلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ', 'অতপর তাদের (অযোগ্য) উত্তরসুরিরা এ যমীনে উত্তরাধিকারী হলো, তারা (আল্লাহ তায়ালার) কিতাবেরও উত্তরাধিকারী হলো, তারা এ দুনিয়ার ধন-সম্পদ করায়ত্ত করে নিচ্ছিলো, (মূর্খের মতো) বলতে থাকলো যে, আমাদের অবশ্যই (শেষ বিচারের দিন) মাফ করে দেয়া হবে, কিন্তু (অর্জিত সম্পদের) অনুরূপ সম্পদ যদি তাদের কাছে এসে পড়ে, তারা সাথে সাথেই তা হস্তগত করে নেয়; তাদের কাছ থেকে (আল্লাহ তায়ালার) কিতাবের এ প্রতিশ্রুতি কি নেয়া হয়নি যে, তারা আল্লাহ তায়ালা সম্বন্ধে সত্য ছাড়া কিছু বলবে না! সেখানে যা আছে তা তারা অধ্যয়নও করেছে; আর পরকালীন ঘরবাড়ি! (হ্যাঁ) যারা তাকওয়া অবলম্বন করে তাদের জন্যে তাই হচ্ছে উত্তম (নিবাস), তোমরা কি অনুধাবন করো না?', 'Fakhalafa min baAAdihim khalfun warithoo alkitaba yakhuthoona AAarada hatha aladna wayaqooloona sayughfaru lana wain yatihim AAaradun mithluhu yakhuthoohu alam yukhath AAalayhim meethaqu alkitabi an la yaqooloo AAala Allahi illa alhaqqa wadarasoo ma feehi waalddaru alakhiratu khayrun lillatheena yattaqoona afala taAAqiloona', 1, NOW(), NOW()),
(12, 170, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلۡكِتَٰبِ وَأَقَامُواْ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجۡرَ ٱلۡمُصۡلِحِينَ', 'অপরদিকে যারা (আল্লাহর) কিতাবকে (শক্ত করে) আঁকড়ে ধরে এবং নামায প্রতিষ্ঠা করে (তাদের জানা উচিত), আমি কখনো সংশোধনকারীদের বিনিময় নষ্ট করি না।', 'Waallatheena yumassikoona bialkitabi waaqamoo alssalata inna la nudeeAAu ajra almusliheena', 1, NOW(), NOW()),
(12, 171, '۞وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ', 'আমি যখন তাদের (মাথার) ওপর পাহাড়কে উঁচু করে রেখেছিলাম, (মনে হচ্ছিলো) তা যেন একটি ছায়া, তারা তো ধরেই নিয়েছিলো, তা বুঝি (এখনি) তাদের ওপর পড়ে যাবে (আমি তাদের বললাম,) আমি তোমাদের যে কিতাব দিয়েছি তা শক্ত করে আঁকড়ে ধরো এবং তাতে যা কিছু আছে তা স্মরণ করো, আশা করা যায় তোমরা (আযাব থেকে) বেঁচে থাকতে পারবে।', 'Waith nataqna aljabala fawqahum kaannahu thullatun wathannoo annahu waqiAAun bihim khuthoo ma ataynakum biquwwatin waothkuroo ma feehi laAAallakum tattaqoona', 1, NOW(), NOW()),
(12, 172, 'وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ شَهِدۡنَآۚ أَن تَقُولُواْ يَوۡمَ ٱلۡقِيَٰمَةِ إِنَّا كُنَّا عَنۡ هَٰذَا غَٰفِلِينَ', '(স্মরণ করো,) যখন তোমাদের রব আদম সন্তানের পৃষ্ঠদেশ থেকে তাদের (পরবর্তী) সন্তান-সন্ততিদের বের করে এনেছেন এবং তাদের নিজেদের ওপর নিজেদের সাক্ষী বানিয়ে (এ মর্মে আনুগত্যের) স্বীকারোক্তি আদায় করেছেন যে, আমি কি তোমাদের রব নই? তারা বললো, হ্যাঁ, আমরা সাক্ষ্য দিলাম, (এর উদ্দেশ্য ছিলো) যেন কেয়ামতের দিন তোমরা একথা বলতে না পারো, আমরা এ বিষয়ে বে-খবর ছিলাম।', 'Waith akhatha rabbuka min banee adama min thuhoorihim thurriyyatahum waashhadahum AAala anfusihim alastu birabbikum qaloo bala shahidna an taqooloo yawma alqiyamati inna kunna AAan hatha ghafileena', 1, NOW(), NOW()),
(12, 173, 'أَوۡ تَقُولُوٓاْ إِنَّمَآ أَشۡرَكَ ءَابَآؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّيَّةٗ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ', 'কিংবা (একথাও যেন না) বলো যে, (আল্লাহর সাথে) শিরক তো আমাদের পূর্ব পুরুষরাই আগে করেছে- আর আমরা ছিলাম তাদের পরবর্তী বংশধর । বাতিলপন্থীরা যা করেছে সে জন্যে কি (আজ) তুমি আমাদের ধ্বংস করবে?', 'Aw taqooloo innama ashraka abaona min qablu wakunna thurriyyatan min baAAdihim afatuhlikuna bima faAAala almubtiloona', 1, NOW(), NOW()),
(12, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلَعَلَّهُمۡ يَرۡجِعُونَ', 'এভাবেই আমি (অতীতের) দৃষ্টান্তসমূহ খোলাখুলি বর্ণনা করি, আশা করা যায়, এরা (সোজা পথে) ফিরে আসবে।', 'Wakathalika nufassilu alayati walaAAallahum yarjiAAoona', 1, NOW(), NOW()),
(12, 175, 'وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ', '(হে মুহাম্মদ,) তুমি তাদের কাছে (এমন) একজন মানুষের কাহিনী (পড়ে) শোনাও, যার কাছে আমি আমার আয়াতসমূহ পাঠিয়েছিলাম, অতপর সে তা থেকে বিচ্যুত হয়ে পড়ে, শয়তানও তার পিছু নেয় এবং সে পথভ্রষ্টদের দলভুক্ত হয়ে পড়ে।', 'Waotlu AAalayhim nabaa allathee ataynahu ayatina fainsalakha minha faatbaAAahu alshshaytanu fakana mina alghaweena', 1, NOW(), NOW()),
(12, 176, 'وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّـٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّرُونَ', '(অথচ) আমি চাইলে তাকে এ (আয়াতসমূহ) দ্বারা উচ্চ মর্যাদা দান করতে পারতাম, কিন্তু সে তো (ঊর্ধ্বমুখী আসমানের বদলে) নিম্নমুখী যমীনের প্রতিই আসক্ত হয়ে পড়লো এবং তার (পার্থিব) কামনা-বাসনার অনুসরণ করলো, তার উদাহরণ হচ্ছে কুকুরের উদাহরণের মতো, যদি তুমি তাকে দৌড়াতে থাকো সে (জিহ্বা বের করে) হ্যাঁপাতে থাকে, আবার তোমরা তাকে ছেড়ে দিলেও সে (জিহ্বা ঝুলিয়ে) হ্যাঁপাতে থাকে; এ হচ্ছে তাদের দৃষ্টান্ত যারা আমার আয়াতসমূহকে অস্বীকার করেছে, এ কাহিনীগুলো (তাদের) তুমি পড়ে শোনাও, আশা করা যায় তারা চিন্তা-গবেষণা করবে।', 'Walaw shina larafaAAnahu biha walakinnahu akhlada ila alardi waittabaAAa hawahu famathaluhu kamathali alkalbi in tahmil AAalayhi yalhath aw tatrukhu yalhath thalika mathalu alqawmi allatheena kaththaboo biayatina faoqsusi alqasasa laAAallahum yatafakkaroona', 1, NOW(), NOW()),
(12, 177, 'سَآءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَأَنفُسَهُمۡ كَانُواْ يَظۡلِمُونَ', 'তাদের উদাহরণ কতো নিকৃষ্ট! যে সম্প্রদায়ের লোকেরা আমার নিদর্শনসমূহকে মিথ্যা সাব্যস্ত করেছে, তারা নিজেরাই নিজেদের ওপর যুলুম করে আসছে!', 'Saa mathalan alqawmu allatheena kaththaboo biayatina waanfusahum kanoo yathlimoona', 1, NOW(), NOW()),
(12, 178, 'مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ وَمَن يُضۡلِلۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', 'আল্লাহ তায়ালা যাকে পথ দেখান সে (সঠিক) পথ পাবে, আবার যাকে তিনি পথভ্রষ্ট করেন তারা হবে ভীষণ ক্ষতিগ্রস্ত।', 'Man yahdi Allahu fahuwa almuhtadee waman yudlil faolaika humu alkhasiroona', 1, NOW(), NOW()),
(12, 179, 'وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِيرٗا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبٞ لَّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُنٞ لَّا يُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانٞ لَّا يَسۡمَعُونَ بِهَآۚ أُوْلَـٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ', 'বহু সংখ্যক মানুষ ও জ্বিন (আছে, যাদের) আমি জাহান্নামের জন্যে পয়দা করেছি, তাদের কাছে যদিও (বুঝার মতো) দিল আছে, কিন্তু তা দিয়ে তারা চিন্তা করে না, তাদের কাছে (দেখার মতো) চোখ থাকলেও তারা তা দিয়ে (সত্য) দেখে না, আবার তাদের কাছে (শোনার মতো) কান আছে, কিন্তু তারা সে কান দিয়ে (সত্য কথা) শোনে না; (আসলে) এরা হচ্ছে জন্তু-জানোয়ারের মতো, বরং (কোনো কোনো ক্ষেত্রে) তাদের চাইতেও এরা বেশী পথভ্রষ্ট; এসব লোকেরাই হচ্ছে উদাসীন।', 'Walaqad tharana lijahannama katheeran mina aljinni waalinsi lahum quloobun la yafqahoona biha walahum aAAyunun la yubsiroona biha walahum athanun la yasmaAAoona biha olaika kaalanAAami bal hum adallu olaika humu alghafiloona', 1, NOW(), NOW()),
(12, 180, 'وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَـٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ', 'আল্লাহ তায়ালার জন্যেই সুন্দর নামসমূহ (নিবেদিত), অতএব তোমরা সে সব ভালো নামেই তাঁকে ডাকো এবং সেসব লোকের কথা ছেড়ে দাও যারা তাঁর নামসমূহে বিকৃতি ঘটায়; যা কিছু তারা (দুনিয়ার জীবনে) করে এসেছে, অচিরেই তার যথাযথ ফল তাদের দেয়া হবে।', 'Walillahi alasmao alhusna faodAAoohu biha watharoo allatheena yulhidoona fee asmaihi sayujzawna ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(12, 181, 'وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ', 'আমি যাদের সৃষ্টি করেছি তাদের মাঝে এমন একটি দল আছে, যারা (মানুষকে) সঠিক পথের দিকে ডাকে এবং (সে মতে) নিজেরা ইনসাফ প্রতিষ্ঠা করে।', 'Wamimman khalaqna ommatun yahdoona bialhaqqi wabihi yaAAdiloona', 1, NOW(), NOW()),
(12, 182, 'وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ', 'যারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করে, আমি আস্তে আস্তে তাদের এমন দিক থেকে (ধ্বংসের দিকে) নিয়ে যাবো যে,তারা কিছুই জানবে না।', 'Waallatheena kaththaboo biayatina sanastadrijuhum min haythu la yaAAlamoona', 1, NOW(), NOW()),
(12, 183, 'وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ', 'আমি তাদের (বিদ্রোহের) জন্যে অবকাশ দিয়ে রাখবো, (এ ব্যাপারে) আমার কৌশল (কিন্তু) অত্যন্ত মযবুত।', 'Waomlee lahum inna kaydee mateenun', 1, NOW(), NOW()),
(12, 184, 'أَوَلَمۡ يَتَفَكَّرُواْۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرٞ مُّبِينٌ', 'তারা কি কখনো চিন্তা করে দেখে না! তাদের সাথী (মুহাম্মদ)-এর সাথে কোনো জ্বিনের আছর নেই; সে তো হচ্ছে (আযাবের) একজন সুস্পষ্ট সতর্ককারী মাত্র।', 'Awalam yatafakkaroo ma bisahibihim min jinnatin in huwa illa natheerun mubeenun', 1, NOW(), NOW()),
(12, 185, 'أَوَلَمۡ يَنظُرُواْ فِي مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ وَأَنۡ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ', 'তারা কি আসমানসমূহ ও পৃথিবীর সার্বভৌমত্বের (বিষয়টির) দিকে কখনো তাকিয়ে দেখে না এবং তাকিয়ে দেখে না- আল্লাহ তায়ালা এখানে যা কিছু সৃষ্টি করেছেন (তার প্রতি, এটা কি দেখে না যে, এখানে) তাদের (অবস্থানের) মেয়াদ হয়তো নিকটবর্তী হয়ে এসেছে, অতপর আর কোন্ কথা আছে যার ওপর এরা ঈমান আনবে?', 'Awalam yanthuroo fee malakooti alssamawati waalardi wama khalaqa Allahu min shayin waan AAasa an yakoona qadi iqtaraba ajaluhum fabiayyi hadeethin baAAdahu yuminoona', 1, NOW(), NOW()),
(12, 186, 'مَن يُضۡلِلِ ٱللَّهُ فَلَا هَادِيَ لَهُۥۚ وَيَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', 'আল্লাহ তায়ালা যাকে পথহারা করে দেন তাকে পথে আনার আর কেউই নেই; তিনি তো তাদের (সবাইকে) তাদের অবাধ্যতায় উদ্ভ্রান্তের মতো ঘুরে বেড়ানোর জন্যে ছেড়ে দেন।', 'Man yudlili Allahu fala hadiya lahu wayatharuhum fee tughyanihim yaAAmahoona', 1, NOW(), NOW()),
(12, 187, 'يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّيۖ لَا يُجَلِّيهَا لِوَقۡتِهَآ إِلَّا هُوَۚ ثَقُلَتۡ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَةٗۗ يَسۡـَٔلُونَكَ كَأَنَّكَ حَفِيٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ', 'তারা তোমার কাছে কেয়ামত সম্পর্কে জিজ্ঞেস করে, এ দিনটি কখন সংঘটিত হবে; তুমি (তাদের) বলো, এর জ্ঞান তো (রয়েছে) আমার মালিকের কাছে, এর সময় আসার আগে তিনি তা প্রকাশ করবেন না, (তবে) আকাশমন্ডলী ও যমীনের জন্যে সেদিন তা হবে একটি ভয়াবহ ঘটনা; এটি তোমাদের কাছে আসবে একান্ত আকস্মিকভাবেই । তারা (এ প্রশ্নটি এমনভাবে) জিজ্ঞেস করে যে, মনে হয় তুমি বুঝি সে সম্পর্কে সব কিছু জানো; (তাদের) বলো, কেয়ামতের জ্ঞান তো একমাত্র আল্লাহ তায়ালার কাছেই রয়েছে, কিন্তু অধিকাংশ মানুষই (এ কথাটি) জানে না।', 'Yasaloonaka AAani alssaAAati ayyana mursaha qul innama AAilmuha AAinda rabbee la yujalleeha liwaqtiha illa huwa thaqulat fee alssamawati waalardi la tateekum illa baghtatan yasaloonaka kaannaka hafiyyun AAanha qul innama AAilmuha AAinda Allahi walakinna akthara alnnasi la yaAAlamoona', 1, NOW(), NOW()),
(12, 188, 'قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ', '(হে নবী,) তুমি বলো, আমি তো আমার নিজের ভালো-মন্দের মালিকও নই, তবে আল্লাহ তায়ালা যা চান তা আলাদা; যদি আমি অজানা বিষয় সম্পর্কে জানতাম, তাহলে আমি (তা দিয়ে) অনেক ফায়দাই তো হাসিল করে নিতে পারতাম এবং কোনো অকল্যাণই আমাকে স্পর্শ করতে পারতো না, আমি (জাহান্নামের) সতর্ককারী ও (জান্নাতের) সুসংবাদবাহী ছাড়া আর কিছুই নই- সে জাতির জন্যে যারা (আমার ওপর) ঈমান আনে।', 'Qul la amliku linafsee nafAAan wala darran illa ma shaa Allahu walaw kuntu aAAlamu alghayba laistakthartu mina alkhayri wama massaniya alssooo in ana illa natheerun wabasheerun liqawmin yuminoona', 1, NOW(), NOW()),
(12, 189, '۞هُوَ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِيفٗا فَمَرَّتۡ بِهِۦۖ فَلَمَّآ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَٰلِحٗا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', 'তিনিই আল্লাহ তায়ালা, যিনি তোমাদের একটি প্রাণ থেকে পয়দা করেছেন এবং তার থেকে তিনি তার জুড়ি বানিয়েছেন, যেন তার কাছে সে পরম শান্তি লাভ করতে পারে, অতপর যখন (পুরুষ) সাথীটি (তার) মহিলা সাথীটিকে (দৈহিক প্রয়োজন মেটাতে গিয়ে) ঢেকে দিলো, তখন মহিলা সাথীটি এক লঘু গর্ভ ধারণ করলো এবং সে এ নিয়েই চলাফেরা করলো; পরে যখন সে (গর্ভের কারণে) ভারী হয়ে এলো, তখন তারা উভয়েই তাদের মালিককে ডেকে বললো, (হে আল্লাহ) যদি তুমি আমাদের সুস্থ ও পূর্ণাঙ্গ সন্তান দান করো, তাহলে আমরা অবশ্যই তোমার কৃতজ্ঞ বান্দাদের দলে অন্তর্ভুক্ত হবো।', 'Huwa allathee khalaqakum min nafsin wahidatin wajaAAala minha zawjaha liyaskuna ilayha falamma taghashshaha hamalat hamlan khafeefan famarrat bihi falamma athqalat daAAawa Allaha rabbahuma lain ataytana salihan lanakoonanna mina alshshakireena', 1, NOW(), NOW()),
(12, 190, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحٗا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَاۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ', 'অতপর যখন তিনি তাদের উভয়কে একটি (নিখুঁত ও) ভালো সন্তান দান করলেন, তখন যা কিছু তাদের দেয়া হয়েছে তারা তাতে অন্যদের শরীক বানিয়ে নিলো, আল্লাহ তায়ালা কিন্তু তাদের এ শিরক থেকে অনেক পবিত্র।', 'Falamma atahuma salihan jaAAala lahu shurakaa feema atahuma fataAAala Allahu AAamma yushrikoona', 1, NOW(), NOW()),
(12, 191, 'أَيُشۡرِكُونَ مَا لَا يَخۡلُقُ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ', 'এরা কি (আল্লাহ তায়ালার) সাথে এমন কিছুকে শরীক করে, যারা কিছুই সৃষ্টি করতে পারে না, বরং তাদের নিজেদেরই সৃষ্টি করা হয়!', 'Ayushrikoona ma la yakhluqu shayan wahum yukhlaqoona', 1, NOW(), NOW()),
(12, 192, 'وَلَا يَسۡتَطِيعُونَ لَهُمۡ نَصۡرٗا وَلَآ أَنفُسَهُمۡ يَنصُرُونَ', 'তারা তাদের কোনোরকম সাহায্য করতে সক্ষম নয়, তারা তো (আসলে) নিজেদেরও সাহায্য করতে পারে না।', 'Wala yastateeAAoona lahum nasran wala anfusahum yansuroona', 1, NOW(), NOW()),
(12, 193, 'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَتَّبِعُوكُمۡۚ سَوَآءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَٰمِتُونَ', 'তোমরা যদি এ লোকদের হেদায়াতের পথের দিকে আহবান করো, তারা তোমাদের কথা শুনবে না, তাদের হেদায়াতের পথে ডাকো কিংবা চুপ করে থাকো- উভয়টাই তোমাদের জন্যে সমান কথা।', 'Wain tadAAoohum ila alhuda la yattabiAAookum sawaon AAalaykum adaAAawtumoohum am antum samitoona', 1, NOW(), NOW()),
(12, 194, 'إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡيَسۡتَجِيبُواْ لَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ', 'আল্লাহ তায়ালাকে বাদ দিয়ে তোমরা যাদের ডাকো, তারা তো তোমাদের মতোই কতিপয় বান্দা, তোমরা তাদের ডেকেই দেখো না, তোমরা সত্যবাদী হলে তাদের উচিত তোমাদের ডাকে সাড়া দেয়া।', 'Inna allatheena tadAAoona min dooni Allahi AAibadun amthalukum faodAAoohum falyastajeeboo lakum in kuntum sadiqeena', 1, NOW(), NOW()),
(12, 195, 'أَلَهُمۡ أَرۡجُلٞ يَمۡشُونَ بِهَآۖ أَمۡ لَهُمۡ أَيۡدٖ يَبۡطِشُونَ بِهَآۖ أَمۡ لَهُمۡ أَعۡيُنٞ يُبۡصِرُونَ بِهَآۖ أَمۡ لَهُمۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُواْ شُرَكَآءَكُمۡ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'তাদের কি কোনো পা আছে যার (ওপর ভর) দিয়ে তারা চলতে পারে, অথবা তাদের কি কোনো (ক্ষমতাধর) হাত আছে যা দিয়ে তারা সব কিছু ধরতে পারে, কিংবা আছে কি তাদের কোনো চোখ- যা দিয়ে তারা (সব কিছু) দেখতে পারে, কিংবা আছে কি- তাদের কোনো কান যা দিয়ে তারা শুনতে পারে! তুমি বলো, তোমরা ডাকো তোমাদের শরীকদের, এরপর তোমরা আমার বিরুদ্ধে ষড়যন্ত্র করো এবং আমাকে কোনো অবকাশও দিয়ো না।', 'Alahum arjulun yamshoona biha am lahum aydin yabtishoona biha am lahum aAAyunun yubsiroona biha am lahum athanun yasmaAAoona biha quli odAAoo shurakaakum thumma keedooni fala tunthirooni', 1, NOW(), NOW()),
(12, 196, 'إِنَّ وَلِـِّۧيَ ٱللَّهُ ٱلَّذِي نَزَّلَ ٱلۡكِتَٰبَۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ', '(তুমি বলো,) নিশ্চয়ই আমার অভিভাবক হচ্ছেন একমাত্র আল্লাহ তায়ালা, যিনি কিতাব নাজিল করেছেন, তিনি সবসময়ই ভালো লোকদের অভিভাবকত্ব করেন।', 'Inna waliyyiya Allahu allathee nazzala alkitaba wahuwa yatawalla alssaliheena', 1, NOW(), NOW()),
(12, 197, 'وَٱلَّذِينَ تَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَلَآ أَنفُسَهُمۡ يَنصُرُونَ', 'তাঁকে বাদ দিয়ে যাদের তোমরা ডাকো, তারা তোমাদের কোনোরকম সাহায্য করতে সক্ষম নয়, তারা তো নিজেদেরও সাহায্য করতে পারে না।', 'Waallatheena tadAAoona min doonihi la yastateeAAoona nasrakum wala anfusahum yansuroona', 1, NOW(), NOW()),
(12, 198, 'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا يَسۡمَعُواْۖ وَتَرَىٰهُمۡ يَنظُرُونَ إِلَيۡكَ وَهُمۡ لَا يُبۡصِرُونَ', 'তোমরা যদি তাদের হেদায়াতের পথে আসার আহ্বান জানাও, তবে তারা শুনতেই পাবে না; (কথা বলার সময়) তুমি দেখছো যে, তারা তোমার দিকেই চেয়ে আছে, কিন্তু এরা আসলে (সত্যকে) দেখতেই পায় না।', 'Wain tadAAoohum ila alhuda la yasmaAAoo watarahum yanthuroona ilayka wahum la yubsiroona', 1, NOW(), NOW()),
(12, 199, 'خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ', '(হে মুহাম্মদ, এদের সাথে) তুমি ক্ষমার নীতি অবলম্বন করো, নেক কাজের আদেশ দাও এবং মূর্খ লোকদের তুমি এড়িয়ে চলো।', 'Khuthi alAAafwa wamur bialAAurfi waaAArid AAani aljahileena', 1, NOW(), NOW()),
(12, 200, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', 'কখনো যদি শয়তানের কুমন্ত্রণা তোমাকে প্ররোচিত করে, (সাথে সাথেই) আল্লাহ তায়ালার কাছে আশ্রয় চাও; অবশ্যই তিনি (সব কিছু) শোনেন এবং (সব কিছু ) জানেন।', 'Waimma yanzaghannaka mina alshshaytani nazghun faistaAAith biAllahi innahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(12, 201, 'إِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَـٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ', '(আল্লাহ তায়ালাকে) যারা ভয় করে তাদের যদি কখনো শয়তানের কুমন্ত্রণা স্পর্শ করে, তবে তারা (সাথে সাথেই) আত্মসচেতন হয়, তৎক্ষণাৎ তাদের চোখও খুলে যায়।', 'Inna allatheena ittaqaw itha massahum taifun mina alshshaytani tathakkaroo faitha hum mubsiroona', 1, NOW(), NOW()),
(12, 202, 'وَإِخۡوَٰنُهُمۡ يَمُدُّونَهُمۡ فِي ٱلۡغَيِّ ثُمَّ لَا يُقۡصِرُونَ', 'তাদের (কাফের) ভাই-বন্ধুরা তাদের বিদ্রোহের পথেই টেনে নিতে চায়, অতপর তারা (এ চেষ্টায়) কোনো ত্রুটি করে না।', 'Waikhwanuhum yamuddoonahum fee alghayyi thumma la yuqsiroona', 1, NOW(), NOW()),
(12, 203, 'وَإِذَا لَمۡ تَأۡتِهِم بِـَٔايَةٖ قَالُواْ لَوۡلَا ٱجۡتَبَيۡتَهَاۚ قُلۡ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَيَّ مِن رَّبِّيۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُؤۡمِنُونَ', '(আবার) যখন তুমি তাদের কাছে কোনো আয়াত নিয়ে না আসো, তখন তারা বলে, ভালো হতো যদি তুমি নিজেই তেমন কিছু বেছে না নিতে! তুমি বলো, আমি তো তাই অনুসরণ করি যা আমার মালিকের কাছ থেকে আমার কাছে নাজিল হয়, আর এ (কুরআন) হচ্ছে তোমাদের মালিকের কাছ থেকে নাজিল করা (দূরদৃষ্টিসম্পন্ন) কতিপয় নিদর্শন ও দলিল, যারা ঈমান এনেছে (এ কিতাব) তাদের জন্যে হেদায়াত ও রহমত।', 'Waitha lam tatihim biayatin qaloo lawla ijtabaytaha qul innama attabiAAu ma yooha ilayya min rabbee hatha basairu min rabbikum wahudan warahmatun liqawmin yuminoona', 1, NOW(), NOW()),
(12, 204, 'وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُواْ لَهُۥ وَأَنصِتُواْ لَعَلَّكُمۡ تُرۡحَمُونَ', 'যখন কুরআন তেলাওয়াত করা হয় তখন (মনোযোগের সাথে) তা শোনো এবং নিশ্চুপ থাকো, আশা করা যায় তোমাদের ওপর দয়া করা হবে।', 'Waitha quria alquranu faistamiAAoo lahu waansitoo laAAallakum turhamoona', 1, NOW(), NOW()),
(12, 205, 'وَٱذۡكُر رَّبَّكَ فِي نَفۡسِكَ تَضَرُّعٗا وَخِيفَةٗ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ وَلَا تَكُن مِّنَ ٱلۡغَٰفِلِينَ', '(হে নবী,) স্মরণ করো তোমার মালিককে- মনে মনে, সকাল-সন্ধ্যায় সবিনয়ে সশংক চিত্তে ও অনুচ্চ স্বরের কথাবার্তা দিয়ে। কখনো গাফেলদের দলে শামিল হয়ো না।', 'Waothkur rabbaka fee nafsika tadarruAAan wakheefatan wadoona aljahri mina alqawli bialghuduwwi waalasali wala takun mina alghafileena', 1, NOW(), NOW()),
(12, 206, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسۡجُدُونَۤ۩', 'নিসন্দেহে যারা তোমার মালিকের একান্ত সান্নিধ্যে আছে, তারা কখনো অহংকার করে তাঁর এবাদাত থেকে বিরত থাকে না, তারা তাঁর তাসবীহ করে এবং তাঁর জন্যেই সাজদা করে।', 'Inna allatheena AAinda rabbika la yastakbiroona AAan AAibadatihi wayusabbihoonahu walahu yasjudoona', 1, NOW(), NOW()),
(13, 1, 'يَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ', 'আপনার কাছে জিজ্ঞেস করে, গনীমতের হুকুম। বলে দিন, গণীমতের মাল হল আল্লাহর এবং রসূলের। অতএব, তোমরা আল্লাহকে ভয় কর এবং নিজেদের অবস্থা সংশোধন করে নাও। আর আল্লাহ এবং তাঁর রসূলের হুকুম মান্য কর, যদি ঈমানদার হয়ে থাক।', 'Yasaloonaka AAani alanfali quli alanfalu lillahi waalrrasooli faittaqoo Allaha waaslihoo thata baynikum waateeAAoo Allaha warasoolahu in kuntum mumineena', 1, NOW(), NOW()),
(13, 2, 'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ', 'যারা ঈমানদার, তারা এমন যে, যখন আল্লাহর নাম নেয়া হয় তখন ভীত হয়ে পড়ে তাদের অন্তর। আর যখন তাদের সামনে পাঠ করা হয় কালাম, তখন তাদের ঈমান বেড়ে যায় এবং তারা স্বীয় পরওয়ার দেগারের প্রতি ভরসা পোষণ করে।', 'Innama almuminoona allatheena itha thukira Allahu wajilat quloobuhum waitha tuliyat AAalayhim ayatuhu zadathum eemanan waAAala rabbihim yatawakkaloona', 1, NOW(), NOW()),
(13, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ', 'সে সমস্ত লোক যারা নামায প্রতিষ্ঠা করে এবং আমি তাদেরকে যে রুযী দিয়েছি তা থেকে ব্যয় করে।', 'Allatheena yuqeemoona alssalata wamimma razaqnahum yunfiqoona', 1, NOW(), NOW()),
(13, 4, 'أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ', 'তারাই হল সত্যিকার ঈমানদার! তাদের জন্য রয়েছে স্বীয় পরওয়ারদেগারের নিকট মর্যাদা, ক্ষমা এবং সম্মানজনক রুযী।', 'Olaika humu almuminoona haqqan lahum darajatun AAinda rabbihim wamaghfiratun warizqun kareemun', 1, NOW(), NOW()),
(13, 5, 'كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ', 'যেমন করে তোমাকে তোমার পরওয়ারদেগার ঘর থেকে বের করেছেন ন্যায় ও সৎকাজের জন্য, অথচ ঈমানদারদের একটি দল (তাতে) সম্মত ছিল না।', 'Kama akhrajaka rabbuka min baytika bialhaqqi wainna fareeqan mina almumineena lakarihoona', 1, NOW(), NOW()),
(13, 6, 'يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ', 'তারা তোমার সাথে বিবাদ করছিল সত্য ও ন্যায় বিষয়ে, তা প্রকাশিত হবার পর; তারা যেন মৃত্যুর দিকে ধাবিত হচ্ছে দেখতে দেখতে।', 'Yujadiloonaka fee alhaqqi baAAdama tabayyana kaannama yusaqoona ila almawti wahum yanthuroona', 1, NOW(), NOW()),
(13, 7, 'وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ', 'আর যখন আল্লাহ দু’টি দলের একটির ব্যাপারে তোমাদের সাথে ওয়াদা করেছিলেন যে, সেটি তোমাদের হস্তগত হবে, আর তোমরা কামনা করছিলে যাতে কোন রকম কন্টক নেই, তাই তোমাদের ভাগে আসুক; অথচ আল্লাহ চাইতেন সত্যকে স্বীয় কালামের মাধ্যমে সত্যে পরিণত করতে এবং কাফেরদের মূল কর্তন করে দিতে', 'Waith yaAAidukumu Allahu ihda alttaifatayni annaha lakum watawaddoona anna ghayra thati alshshawkati takoonu lakum wayureedu Allahu an yuhiqqa alhaqqa bikalimatihi wayaqtaAAa dabira alkafireena', 1, NOW(), NOW()),
(13, 8, 'لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ', 'যাতে করে সত্যকে সত্য এবং মিথ্যাকে মিথ্যা প্রতিপন্ন করে দেন, যদিও পাপীরা অসন্তুষ্ট হয়।', 'Liyuhiqqa alhaqqa wayubtila albatila walaw kariha almujrimoona', 1, NOW(), NOW()),
(13, 9, 'إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَـٰٓئِكَةِ مُرۡدِفِينَ', 'তোমরা যখন ফরিয়াদ করতে আরম্ভ করেছিলে স্বীয় পরওয়ারদেগারের নিকট, তখন তিনি তোমাদের ফরিয়াদের মঞ্জুরী দান করলেন যে, আমি তোমাদিগকে সাহায্য করব ধারাবহিকভাবে আগত হাজার ফেরেশতার মাধ্যমে।', 'Ith tastagheethoona rabbakum faistajaba lakum annee mumiddukum bialfin mina almalaikati murdifeena', 1, NOW(), NOW()),
(13, 10, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'আর আল্লাহ তো শুধু সুসংবাদ দান করলেন যাতে তোমাদের মন আশ্বস্ত হতে পারে। আর সাহায্য আল্লাহর পক্ষ থেকে ছাড়া অন্য কারো পক্ষ থেকে হতে পারে না। নিঃসন্দেহে আল্লাহ মহাশক্তির অধিকারী হেকমত ওয়ালা।', 'Wama jaAAalahu Allahu illa bushra walitatmainna bihi quloobukum wama alnnasru illa min AAindi Allahi inna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(13, 11, 'إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ', 'যখন তিনি আরোপ করেন তোমাদের উপর তন্দ্রাচ্ছন্ন তা নিজের পক্ষ থেকে তোমাদের প্রশান্তির জন্য এবং তোমাদের উপর আকাশ থেকে পানি অবতরণ করেন, যাতে তোমাদিগকে পবিত্র করে দেন এবং যাতে তোমাদের থেকে অপসারিত করে দেন শয়তানের অপবিত্রতা। আর যাতে করে সুরক্ষিত করে দিতে পারেন তোমাদের অন্তরসমূহকে এবং তাতে যেন সুদৃঢ় করে দিতে পারেন তোমাদের পা গুলো।', 'Ith yughashsheekumu alnnuAAasa amanatan minhu wayunazzilu AAalaykum mina alssamai maan liyutahhirakum bihi wayuthhiba AAankum rijza alshshaytani waliyarbita AAala quloobikum wayuthabbita bihi alaqdama', 1, NOW(), NOW()),
(13, 12, 'إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَـٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ', 'যখন নির্দেশ দান করেন ফেরেশতাদিগকে তোমাদের পরওয়ারদেগার যে, আমি সাথে রয়েছি তোমাদের, সুতরাং তোমরা মুসলমানদের চিত্তসমূহকে ধীরস্থির করে রাখ। আমি কাফেরদের মনে ভীতির সঞ্চার করে দেব। কাজেই গর্দানের উপর আঘাত হান এবং তাদেরকে কাট জোড়ায় জোড়ায়।', 'Ith yoohee rabbuka ila almalaikati annee maAAakum fathabbitoo allatheena amanoo saolqee fee quloobi allatheena kafaroo alrruAAba faidriboo fawqa alaAAnaqi waidriboo minhum kulla bananin', 1, NOW(), NOW()),
(13, 13, 'ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'যেহেতু তারা অবাধ্য হয়েছে আল্লাহ এবং তাঁর রসূলের, সেজন্য এই নির্দেশ। বস্তুতঃ যে লোক আল্লাহ ও রসূলের অবাধ্য হয়, নিঃসন্দেহে আল্লাহর শাস্তি অত্যন্ত কঠোর।', 'Thalika biannahum shaqqoo Allaha warasoolahu waman yushaqiqi Allaha warasoolahu fainna Allaha shadeedu alAAiqabi', 1, NOW(), NOW()),
(13, 14, 'ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 'আপাততঃ বর্তমান এ শাস্তি তোমরা আস্বাদন করে নাও এবং জেনে রাখ যে, কাফেরদের জন্য রয়েছে দোযখের আযাব।', 'Thalikum fathooqoohu waanna lilkafireena AAathaba alnnari', 1, NOW(), NOW()),
(13, 15, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ', 'হে ঈমানদারগণ, তোমরা যখন কাফেরদের সাথে মুখোমুখী হবে, তখন পশ্চাদপসরণ করবে না।', 'Ya ayyuha allatheena amanoo itha laqeetumu allatheena kafaroo zahfan fala tuwalloohumu aladbara', 1, NOW(), NOW()),
(13, 16, 'وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'আর যে লোক সেদিন তাদের থেকে পশ্চাদপসরণ করবে, অবশ্য যে লড়াইয়ের কৌশল পরিবর্তনকল্পে কিংবা যে নিজ সৈন্যদের নিকট আশ্রয় নিতে আসে সে ব্যতীত অন্যরা আল্লাহর গযব সাথে নিয়ে প্রত্যাবর্তন করবে। আর তার ঠিকানা হল জাহান্নাম। বস্তুতঃ সেটা হল নিকৃষ্ট অবস্থান।', 'Waman yuwallihim yawmaithin duburahu illa mutaharrifan liqitalin aw mutahayyizan ila fiatin faqad baa bighadabin mina Allahi wamawahu jahannamu wabisa almaseeru', 1, NOW(), NOW()),
(13, 17, 'فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', 'সুতরাং তোমরা তাদেরকে হত্যা করনি, বরং আল্লাহই তাদেরকে হত্যা করেছেন। আর তুমি মাটির মুষ্ঠি নিক্ষেপ করনি, যখন তা নিক্ষেপ করেছিলে, বরং তা নিক্ষেপ করেছিলেন আল্লাহ স্বয়ং যেন ঈমানদারদের প্রতি এহসান করতে পারেন যথার্থভাবে। নিঃসন্দেহে আল্লাহ শ্রবণকারী; পরিজ্ঞাত।', 'Falam taqtuloohum walakinna Allaha qatalahum wama ramayta ith ramayta walakinna Allaha rama waliyubliya almumineena minhu balaan hasanan inna Allaha sameeAAun AAaleemun', 1, NOW(), NOW()),
(13, 18, 'ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ', 'এটাতো গেল, আর জেনে রেখো, আল্লাহ নস্যাৎ করে দেবেন কাফেরদের সমস্ত কলা-কৌশল।', 'Thalikum waanna Allaha moohinu kaydi alkafireena', 1, NOW(), NOW()),
(13, 19, 'إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ', 'তোমরা যদি মীমাংসা কামনা কর, তাহলে তোমাদের নিকট মীমাংসা পৌছে গেছে। আর যদি তোমরা প্রত্যাবর্তন কর, তবে তা তোমাদের জন্য উত্তম এবং তোমরা যদি তাই কর, তবে আমি ও তেমনি করব। বস্তুতঃ তোমাদের কোনই কাজে আসবে না তোমাদের দল-বল, তা যত বেশীই হোক। জেনে রেখ আল্লাহ রয়েছেন ঈমানদারদের সাথে।', 'In tastaftihoo faqad jaakumu alfathu wain tantahoo fahuwa khayrun lakum wain taAAoodoo naAAud walan tughniya AAankum fiatukum shayan walaw kathurat waanna Allaha maAAa almumineena', 1, NOW(), NOW()),
(13, 20, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ', 'হে ঈমানদারগণ, আল্লাহ ও তাঁর রসূলের নির্দেশ মান্য কর এবং শোনার পর তা থেকে বিমুখ হয়ো না।', 'Ya ayyuha allatheena amanoo ateeAAoo Allaha warasoolahu wala tawallaw AAanhu waantum tasmaAAoona', 1, NOW(), NOW()),
(13, 21, 'وَلَا تَكُونُواْ كَٱلَّذِينَ قَالُواْ سَمِعۡنَا وَهُمۡ لَا يَسۡمَعُونَ', 'আর তাদের অন্তর্ভুক্ত হয়ো না, যারা বলে যে, আমরা শুনেছি, অথচ তারা শোনেনা।', 'Wala takoonoo kaallatheena qaloo samiAAna wahum la yasmaAAoona', 1, NOW(), NOW()),
(13, 22, '۞إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ', 'নিঃসন্দেহে আল্লাহ তা’আলার নিকট সমস্ত প্রাণীর তুলনায় তারাই মূক ও বধির, যারা উপলদ্ধি করে না।', 'Inna sharra alddawabbi AAinda Allahi alssummu albukmu allatheena la yaAAqiloona', 1, NOW(), NOW()),
(13, 23, 'وَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ', 'বস্তুতঃ আল্লাহ যদি তাদের মধ্যে কিছুমাত্র শুভ চিন্তা জানতেন, তবে তাদেরকে শুনিয়ে দিতেন। আর এখনই যদি তাদের শুনিয়ে দেন, তবে তারা মুখ ঘুরিয়ে পালিয়ে যাবে।', 'Walaw AAalima Allahu feehim khayran laasmaAAahum walaw asmaAAahum latawallaw wahum muAAridoona', 1, NOW(), NOW()),
(13, 24, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥٓ إِلَيۡهِ تُحۡشَرُونَ', 'হে ঈমানদারগণ, আল্লাহ ও তাঁর রসূলের নির্দেশ মান্য কর, যখন তোমাদের সে কাজের প্রতি আহবান করা হয়, যাতে রয়েছে তোমাদের জীবন। জেনে রেখো, আল্লাহ মানুষের এবং তার অন্তরের মাঝে অন্তরায় হয়ে যান। বস্তুতঃ তোমরা সবাই তাঁরই নিকট সমবেত হবে।', 'Ya ayyuha allatheena amanoo istajeeboo lillahi walilrrasooli itha daAAakum lima yuhyeekum waiAAlamoo anna Allaha yahoolu bayna almari waqalbihi waannahu ilayhi tuhsharoona', 1, NOW(), NOW()),
(13, 25, 'وَٱتَّقُواْ فِتۡنَةٗ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُواْ مِنكُمۡ خَآصَّةٗۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ', 'আর তোমরা এমন ফাসাদ থেকে বেঁচে থাক যা বিশেষতঃ শুধু তাদের উপর পতিত হবে না যারা তোমাদের মধ্যে জালেম এবং জেনে রেখ যে, আল্লাহর আযাব অত্যন্ত কঠোর।', 'Waittaqoo fitnatan la tuseebanna allatheena thalamoo minkum khassatan waiAAlamoo anna Allaha shadeedu alAAiqabi', 1, NOW(), NOW()),
(13, 26, 'وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ مُّسۡتَضۡعَفُونَ فِي ٱلۡأَرۡضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَيَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ', 'আর স্মরণ কর, যখন তোমরা ছিলে অল্প, পরাজিত অবস্থায় পড়েছিলে দেশে; ভীত-সস্ত্রস্ত্র ছিলে যে, তোমাদের না অন্যেরা ছোঁ মেরে নিয়ে যায়। অতঃপর তিনি তোমাদিগকে আশ্রয়ের ঠিকানা দিয়েছেন, স্বীয় সাহায্যের দ্বারা তোমাদিগকে শক্তি দান করেছেন এবং পরিচ্ছন্ন জীবিকা দিয়েছেন যাতে তোমরা শুকরিয়া আদায় কর।', 'Waothkuroo ith antum qaleelun mustadAAafoona fee alardi takhafoona an yatakhattafakumu alnnasu faawakum waayyadakum binasrihi warazaqakum mina alttayyibati laAAallakum tashkuroona', 1, NOW(), NOW()),
(13, 27, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ', 'হে ঈমানদারগণ, খেয়ানত করোনা আল্লাহর সাথে ও রসূলের সাথে এবং খেয়ানত করো না নিজেদের পারস্পরিক আমানতে জেনে-শুনে।', 'Ya ayyuha allatheena amanoo la takhoonoo Allaha waalrrasoola watakhoonoo amanatikum waantum taAAlamoona', 1, NOW(), NOW()),
(13, 28, 'وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ', 'আর জেনে রাখ, তোমাদের ধন-সম্পদ ও সন্তান-সন্ততি অকল্যাণের সম্মুখীনকারী। বস্তুতঃ আল্লাহর নিকট রয়েছে মহা সওয়াব।', 'WaiAAlamoo annama amwalukum waawladukum fitnatun waanna Allaha AAindahu ajrun AAatheemun', 1, NOW(), NOW()),
(13, 29, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ', 'হে ঈমানদারগণ তোমরা যদি আল্লাহকে ভয় করতে থাক, তবে তোমাদের মধ্যে ফয়সালা করে দেবেন এবং তোমাদের থেকে তোমাদের পাপকে সরিয়ে দেবেন এবং তোমাদের ক্ষমা করবেন। বস্তুতঃ আল্লাহর অনুগ্রহ অত্যন্ত মহান।', 'Ya ayyuha allatheena amanoo in tattaqoo Allaha yajAAal lakum furqanan wayukaffir AAankum sayyiatikum wayaghfir lakum waAllahu thoo alfadli alAAatheemi', 1, NOW(), NOW()),
(13, 30, 'وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ', 'আর কাফেরেরা যখন প্রতারণা করত আপনাকে বন্দী অথবা হত্যা করার উদ্দেশ্যে কিংবা আপনাকে বের করে দেয়ার জন্য তখন তারা যেমন ছলনা করত তেমনি, আল্লাহও ছলনা করতেন। বস্তুতঃ আল্লাহর ছলনা সবচেয়ে উত্তম।', 'Waith yamkuru bika allatheena kafaroo liyuthbitooka aw yaqtulooka aw yukhrijooka wayamkuroona wayamkuru Allahu waAllahu khayru almakireena', 1, NOW(), NOW()),
(13, 31, 'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا قَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', 'আর কেউ যখন তাদের নিকট আমার আয়াতসমূহ পাঠ করে তবে বলে, আমরা শুনেছি, ইচ্ছা করলে আমরাও এমন বলতে পারি; এ তো পূর্ববর্তী ইতিকথা ছাড়া আর কিছুই নয়।', 'Waitha tutla AAalayhim ayatuna qaloo qad samiAAna law nashao laqulna mithla hatha in hatha illa asateeru alawwaleena', 1, NOW(), NOW()),
(13, 32, 'وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ', 'তাছাড়া তারা যখন বলতে আরম্ভ করে যে, ইয়া আল্লাহ, এই যদি তোমার পক্ষ থেকে (আগত) সত্য দ্বীন হয়ে থাকে, তবে আমাদের উপর আকাশ থেকে প্রস্তর বর্ষণ কর কিংবা আমাদের উপর বেদনাদায়ক আযাব নাযিল কর।', 'Waith qaloo allahumma in kana hatha huwa alhaqqa min AAindika faamtir AAalayna hijaratan mina alssamai awi itina biAAathabin aleemin', 1, NOW(), NOW()),
(13, 33, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ', 'অথচ আল্লাহ কখনই তাদের উপর আযাব নাযিল করবেন না যতক্ষণ আপনি তাদের মাঝে অবস্থান করবেন। তাছাড়া তারা যতক্ষণ ক্ষমা প্রার্থনা করতে থাকবে আল্লাহ কখনও তাদের উপর আযাব দেবেন না।', 'Wama kana Allahu liyuAAaththibahum waanta feehim wama kana Allahu muAAaththibahum wahum yastaghfiroona', 1, NOW(), NOW()),
(13, 34, 'وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', 'আর তাদের মধ্যে এমন কি বিষয় রয়েছে, যার ফলে আল্লাহ তাদের উপর আযাব দান করবেন না। অথচ তারা মসজিদে-হারামে যেতে বাধাদান করে, অথচ তাদের সে অধিকার নেই। এর অধিকার তো তাদেরই রয়েছে যারা পরহেযগার। কিন্তু তাদের অধিকাংশই সে বিষয়ে অবহিত নয়।', 'Wama lahum alla yuAAaththibahumu Allahu wahum yasuddoona AAani almasjidi alharami wama kanoo awliyaahu in awliyaohu illa almuttaqoona walakinna aktharahum la yaAAlamoona', 1, NOW(), NOW()),
(13, 35, 'وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ', 'আর কা’বার নিকট তাদের নামায বলতে শিস দেয়া আর তালি বাজানো ছাড়া অন্য কোন কিছুই ছিল না। অতএব, এবার নিজেদের কৃত কুফরীর আযাবের স্বাদ গ্রহণ কর।', 'Wama kana salatuhum AAinda albayti illa mukaan watasdiyatan fathooqoo alAAathaba bima kuntum takfuroona', 1, NOW(), NOW()),
(13, 36, 'إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ', 'নিঃসন্দেহে যেসব লোক কাফের, তারা ব্যয় করে নিজেদের ধন-সম্পদ, যাতে করে বাধাদান করতে পারে আল্লাহর পথে। বস্তুতঃ এখন তারা আরো ব্যয় করবে। তারপর তাই তাদের জন্য আক্ষেপের কারণ হয়ে এবং শেষ পর্যন্ত তারা হেরে যাবে। আর যারা কাফের তাদেরকে দোযখের দিকে তাড়িয়ে নিয়ে যাওয়া হবে।', 'Inna allatheena kafaroo yunfiqoona amwalahum liyasuddoo AAan sabeeli Allahi fasayunfiqoonaha thumma takoonu AAalayhim hasratan thumma yughlaboona waallatheena kafaroo ila jahannama yuhsharoona', 1, NOW(), NOW()),
(13, 37, 'لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجۡعَلَ ٱلۡخَبِيثَ بَعۡضَهُۥ عَلَىٰ بَعۡضٖ فَيَرۡكُمَهُۥ جَمِيعٗا فَيَجۡعَلَهُۥ فِي جَهَنَّمَۚ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', 'যাতে পৃথক করে দেন আল্লাহ অপবিত্র ও না-পাককে পবিত্র ও পাক থেকে। আর যাতে একটির পর একটিকে স্থাপন করে সমবেত স্তুপে পরিণত করেন এবং পরে দোযখে নিক্ষেপ করেন। এরাই হল ক্ষতিগ্রস্ত।', 'Liyameeza Allahu alkhabeetha mina alttayyibi wayajAAala alkhabeetha baAAdahu AAala baAAdin fayarkumahu jameeAAan fayajAAalahu fee jahannama olaika humu alkhasiroona', 1, NOW(), NOW()),
(13, 38, 'قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ', 'তুমি বলে দাও, কাফেরদেরকে যে, তারা যদি বিরত হয়ে যায়, তবে যা কিছু ঘটে গেছে ক্ষমা হবে যাবে। পক্ষান্তরে আবারও যদি তাই করে, তবে পুর্ববর্তীদের পথ নির্ধারিত হয়ে গেছে।', 'Qul lillatheena kafaroo in yantahoo yughfar lahum ma qad salafa wain yaAAoodoo faqad madat sunnatu alawwaleena', 1, NOW(), NOW()),
(13, 39, 'وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ بَصِيرٞ', 'আর তাদের সাথে যুদ্ধ করতে থাক যতক্ষণ না ভ্রান্তি শেষ হয়ে যায়; এবং আল্লাহর সমস্ত হুকুম প্রতিষ্ঠিত হয়ে যায়। তারপর যদি তারা বিরত হয়ে যায়, তবে আল্লাহ তাদের কার্যকলাপ লক্ষ্য করেন।', 'Waqatiloohum hatta la takoona fitnatun wayakoona alddeenu kulluhu lillahi faini intahaw fainna Allaha bima yaAAmaloona baseerun', 1, NOW(), NOW()),
(13, 40, 'وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ', 'আর তারা যদি না মানে, তবে জেনে রাখ, আল্লাহ তোমাদের সমর্থক; এবং কতই না চমৎকার সাহায্যকারী।', 'Wain tawallaw faiAAlamoo anna Allaha mawlakum niAAma almawla waniAAma alnnaseeru', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(13, 41, '۞وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'আর এ কথাও জেনে রাখ যে, কোন বস্তু-সামগ্রীর মধ্য থেকে যা কিছু তোমরা গনীমত হিসাবে পাবে, তার এক পঞ্চমাংশ হল আল্লাহর জন্য, রসূলের জন্য, তাঁর নিকটাত্নীয়-স্বজনের জন্য এবং এতীম-অসহায় ও মুসাফিরদের জন্য; যদি তোমাদের বিশ্বাস থাকে আল্লাহর উপর এবং সে বিষয়ের উপর যা আমি আমার বান্দার প্রতি অবতীর্ণ করেছি ফয়সালার দিনে, যেদিন সম্মুখীন হয়ে যায় উভয় সেনাদল। আর আল্লাহ সব কিছুর উপরই ক্ষমতাশীল।', 'WaiAAlamoo annama ghanimtum min shayin faanna lillahi khumusahu walilrrasooli walithee alqurba waalyatama waalmasakeeni waibni alssabeeli in kuntum amantum biAllahi wama anzalna AAala AAabdina yawma alfurqani yawma iltaqa aljamAAani waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(13, 42, 'إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'আর যখন তোমরা ছিলে সমরাঙ্গনের এ প্রান্তে আর তারা ছিল সে প্রান্তে অথচ কাফেলা তোমাদের থেকে নীচে নেমে গিয়েছিল। এমতাবস্থায় যদি তোমরা পারস্পরিক অঙ্গীকারাবদ্ধ হতে, তবে তোমরা এক সঙ্গে সে ওয়াদা পালন করতে পারতে না। কিন্তু আল্লাহ তা’আলা এমন এক কাজ করতে চেয়েছিলেন, যা নির্ধারিত হয়ে গিয়েছিল যাতে সে সব লোক নিহত হওয়ার ছিল, প্রমাণ প্রতিষ্ঠার পর এবং যাদের বাঁচার ছিল, তারা বেঁচে থাকে প্রমাণ প্রতিষ্ঠার পর। আর নিশ্চিতই আল্লাহ শ্রবণকারী, বিজ্ঞ।', 'Ith antum bialAAudwati alddunya wahum bialAAudwati alquswa waalrrakbu asfala minkum walaw tawaAAadtum laikhtalaftum fee almeeAAadi walakin liyaqdiya Allahu amran kana mafAAoolan liyahlika man halaka AAan bayyinatin wayahya man hayya AAan bayyinatin wainna Allaha lasameeAAun AAaleemun', 1, NOW(), NOW()),
(13, 43, 'إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'আল্লাহ যখন তোমাকে স্বপ্নে সেসব কাফেরের পরিমাণ অল্প করে দেখালেন; বেশী করে দেখালে তোমরা কাপুরুষতা অবলম্বন করতে এবং কাজের বেলায় বিপদ সৃষ্টি করতে। কিন্তু আল্লাহ বাঁচিয়ে দিয়েছেন। তিনি অতি উত্তমভাবেই জানেন; যা কিছু অন্তরে রয়েছে।', 'Ith yureekahumu Allahu fee manamika qaleelan walaw arakahum katheeran lafashiltum walatanazaAAtum fee alamri walakinna Allaha sallama innahu AAaleemun bithati alssudoori', 1, NOW(), NOW()),
(13, 44, 'وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ لِيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', 'আর যখন তোমাদেরকে দেখালেন সে সৈন্যদল মোকাবেলার সময় তোমাদের চোখে অল্প এবং তোমাদেরকে দেখালেন তাদের চোখে বেশী, যাতে আল্লাহ সে কাজ করে নিতে পারেন যা ছিল নির্ধারিত। আর সব কাজই আল্লাহর নিকট গিয়ে পৌছায়।', 'Waith yureekumoohum ithi iltaqaytum fee aAAyunikum qaleelan wayuqallilukum fee aAAyunihim liyaqdiya Allahu amran kana mafAAoolan waila Allahi turjaAAu alomooru', 1, NOW(), NOW()),
(13, 45, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ', 'হে ঈমানদারগণ, তোমরা যখন কোন বাহিনীর সাথে সংঘাতে লিপ্ত হও, তখন সুদৃঢ় থাক এবং আল্লাহকে অধিক পরিমাণে স্মরণ কর যাতে তোমরা উদ্দেশ্যে কৃতকার্য হতে পার।', 'Ya ayyuha allatheena amanoo itha laqeetum fiatan faothbutoo waothkuroo Allaha katheeran laAAallakum tuflihoona', 1, NOW(), NOW()),
(13, 46, 'وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ', 'আর আল্লাহ তা’আলার নির্দেশ মান্য কর এবং তাঁর রসূলের। তাছাড়া তোমরা পরস্পরে বিবাদে লিপ্ত হইও না। যদি তা কর, তবে তোমরা কাপুরুষ হয়ে পড়বে এবং তোমাদের প্রভাব চলে যাবে। আর তোমরা ধৈর্য্যধারণ কর। নিশ্চয়ই আল্লাহ তা''আলা রয়েছেন ধৈর্য্যশীলদের সাথে।', 'WaateeAAoo Allaha warasoolahu wala tanazaAAoo fatafshaloo watathhaba reehukum waisbiroo inna Allaha maAAa alssabireena', 1, NOW(), NOW()),
(13, 47, 'وَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ', 'আর তাদের মত হয়ে যেয়ো না, যারা বেরিয়েছে নিজেদের অবস্থান থেকে গর্বিতভাবে এবং লোকদেরকে দেখাবার উদ্দেশে। আর আল্লাহর পথে তারা বাধা দান করত। বস্তুতঃ আল্লাহর আয়ত্বে রয়েছে সে সমস্ত বিষয় যা তারা করে।', 'Wala takoonoo kaallatheena kharajoo min diyarihim bataran wariaa alnnasi wayasuddoona AAan sabeeli Allahi waAllahu bima yaAAmaloona muheetun', 1, NOW(), NOW()),
(13, 48, 'وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ', 'আর যখন সুদৃশ্য করে দিল শয়তান তাদের দৃষ্টিতে তাদের কার্যকলাপকে এবং বলল যে, আজকের দিনে কোন মানুষই তোমাদের উপর বিজয়ী হতে পারবে না আর আমি হলাম তোমাদের সমর্থক, অতঃপর যখন সামনাসামনী হল উভয় বাহিনী তখন সে অতি দ্রুত পায়ে পেছনে দিকে পালিয়ে গেল এবং বলল, আমি তোমাদের সাথে না-আমি দেখছি, যা তোমরা দেখছ না; আমি ভয় করি আল্লাহকে। আর আল্লাহর আযাব অত্যন্ত কঠিন।', 'Waith zayyana lahumu alshshaytanu aAAmalahum waqala la ghaliba lakumu alyawma mina alnnasi wainnee jarun lakum falamma taraati alfiatani nakasa AAala AAaqibayhi waqala innee bareeon minkum innee ara ma la tarawna innee akhafu Allaha waAllahu shadeedu alAAiqabi', 1, NOW(), NOW()),
(13, 49, 'إِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمۡۗ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', 'যখন মোনাফেকরা বলতে লাগল এবং যাদের অন্তর ব্যাধিগ্রস্ত, এরা নিজেদের ধর্মের উপর গর্বিত। বস্তুতঃ যারা ভরসা করে আল্লাহর উপর, সে নিশ্চিন্ত, কেননা আল্লাহ অতি পরাক্রমশীল, সুবিজ্ঞ।', 'Ith yaqoolu almunafiqoona waallatheena fee quloobihim maradun gharra haolai deenuhum waman yatawakkal AAala Allahi fainna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(13, 50, 'وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَـٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ', 'আর যদি তুমি দেখ, যখন ফেরেশতারা কাফেরদের জান কবজ করে; প্রহার করে, তাদের মুখে এবং তাদের পশ্চাদদেশে আর বলে, জ্বলন্ত আযাবের স্বাদ গ্রহণ কর।', 'Walaw tara ith yatawaffa allatheena kafaroo almalaikatu yadriboona wujoohahum waadbarahum wathooqoo AAathaba alhareeqi', 1, NOW(), NOW()),
(13, 51, 'ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ', 'এই হলো সে সবের বিনিময় যা তোমরা তোমাদের পূর্বে পাঠিয়েছ নিজের হাতে। বস্তুতঃ এটি এ জন্য যে, আল্লাহ বান্দার উপর যুলুম করেন না।', 'Thalika bima qaddamat aydeekum waanna Allaha laysa bithallamin lilAAabeedi', 1, NOW(), NOW()),
(13, 52, 'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ', 'যেমন, রীতি রয়েছে ফেরাউনের অনুসারীদের এবং তাদের পূর্বে যারা ছিল তাদের ব্যাপারে যে, এরা আল্লাহর নির্দেশের প্রতি অস্বীকৃতি জ্ঞাপন করেছে এবং সেজন্য আল্লাহ তা’আলা তাদের পাকড়াও করেছেন তাদেরই পাপের দরুন। নিঃসন্দেহে আল্লাহ মহাশক্তিশালী, কঠিন শাস্তিদাতা।', 'Kadabi ali firAAawna waallatheena min qablihim kafaroo biayati Allahi faakhathahumu Allahu bithunoobihim inna Allaha qawiyyun shadeedu alAAiqabi', 1, NOW(), NOW()),
(13, 53, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ', 'তার কারণ এই যে, আল্লাহ কখনও পরিবর্তন করেন না, সে সব নেয়ামত, যা তিনি কোন জাতিকে দান করেছিলেন, যতক্ষণ না সে জাতি নিজেই পরিবর্তিত করে দেয় নিজের জন্য নির্ধারিত বিষয়। বস্তুতঃ আল্লাহ শ্রবণকারী, মহাজ্ঞানী।', 'Thalika bianna Allaha lam yaku mughayyiran niAAmatan anAAamaha AAala qawmin hatta yughayyiroo ma bianfusihim waanna Allaha sameeAAun AAaleemun', 1, NOW(), NOW()),
(13, 54, 'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَۚ وَكُلّٞ كَانُواْ ظَٰلِمِينَ', 'যেমন ছিল রীতি ফেরাউনের বংশধর এবং যারা তাদের পূর্বে ছিল, তারা মিথ্যা প্রতিপন্ন করেছিল স্বীয় পালনকর্তার নিদর্শনসমূহকে। অতঃপর আমি তাদেরকে ধ্বংস করে দিয়েছি তাদের পাপের দরুন এবং ডুবিয়ে মেরেছি ফেরাউনের বংশধরদেরকে। বস্তুতঃ এরা সবাই ছিল যালেম।', 'Kadabi ali firAAawna waallatheena min qablihim kaththaboo biayati rabbihim faahlaknahum bithunoobihim waaghraqna ala firAAawna wakullun kanoo thalimeena', 1, NOW(), NOW()),
(13, 55, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ', 'সমস্ত জীবের মাঝে আল্লাহর নিকট তারাই সবচেয়ে নিকৃষ্ট, যারা অস্বীকারকারী হয়েছে অতঃপর আর ঈমান আনেনি।', 'Inna sharra alddawabbi AAinda Allahi allatheena kafaroo fahum la yuminoona', 1, NOW(), NOW()),
(13, 56, 'ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ', 'যাদের সাথে তুমি চুক্তি করেছ তাদের মধ্য থেকে অতঃপর প্রতিবার তারা নিজেদের কৃতচুক্তি লংঘন করে এবং ভয় করে না।', 'Allatheena AAahadta minhum thumma yanqudoona AAahdahum fee kulli marratin wahum la yattaqoona', 1, NOW(), NOW()),
(13, 57, 'فَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ', 'সুতরাং যদি কখনো তুমি তাদেরকে যুদ্ধে পেয়ে যাও, তবে তাদের এমন শাস্তি দাও, যেন তাদের উত্তরসূরিরা তাই দেখে পালিয়ে যায়; তাদেরও যেন শিক্ষা হয়।', 'Faimma tathqafannahum fee alharbi fasharrid bihim man khalfahum laAAallahum yaththakkaroona', 1, NOW(), NOW()),
(13, 58, 'وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ', 'তবে কোন সম্প্রদায়ের ধোঁকা দেয়ার ব্যাপারে যদি তোমাদের ভয় থাকে, তবে তাদের চুক্তি তাদের দিকেই ছুঁড়ে ফেলে দাও এমনভাবে যেন হয়ে যাও তোমরাও তারা সমান। নিশ্চয়ই আল্লাহ ধোকাবাজ, প্রতারককে পছন্দ করেন না।', 'Waimma takhafanna min qawmin khiyanatan fainbith ilayhim AAala sawain inna Allaha la yuhibbu alkhaineena', 1, NOW(), NOW()),
(13, 59, 'وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ سَبَقُوٓاْۚ إِنَّهُمۡ لَا يُعۡجِزُونَ', 'আর কাফেররা যেন একা যা মনে না করে যে, তারা বেঁচে গেছে; কখনও এরা আমাকে পরিশ্রান্ত করতে পারবে না।', 'Wala yahsabanna allatheena kafaroo sabaqoo innahum la yuAAjizoona', 1, NOW(), NOW()),
(13, 60, 'وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ', 'আর প্রস্তুত কর তাদের সাথে যুদ্ধের জন্য যাই কিছু সংগ্রহ করতে পার নিজের শক্তি সামর্থ্যের মধ্যে থেকে এবং পালিত ঘোড়া থেকে, যেন প্রভাব পড়ে আল্লাহর শুত্রুদের উপর এবং তোমাদের শত্রুদের উপর আর তাদেরকে ছাড়া অন্যান্যদের উপর ও যাদেরকে তোমরা জান না; আল্লাহ তাদেরকে চেনেন। বস্তুতঃ যা কিছু তোমরা ব্যয় করবে আল্লাহর রাহে, তা তোমরা পরিপূর্ণভাবে ফিরে পাবে এবং তোমাদের কোন হক অপূর্ণ থাকবে না।', 'WaaAAiddoo lahum ma istataAAtum min quwwatin wamin ribati alkhayli turhiboona bihi AAaduwwa Allahi waAAaduwwakum waakhareena min doonihim la taAAlamoonahumu Allahu yaAAlamuhum wama tunfiqoo min shayin fee sabeeli Allahi yuwaffa ilaykum waantum la tuthlamoona', 1, NOW(), NOW()),
(13, 61, '۞وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'আর যদি তারা সন্ধি করতে আগ্রহ প্রকাশ করে, তাহলে তুমিও সে দিকেই আগ্রহী হও এবং আল্লাহর উপর ভরসা কর। নিঃসন্দেহে তিনি শ্রবণকারী; পরিজ্ঞাত।', 'Wain janahoo lilssalmi faijnah laha watawakkal AAala Allahi innahu huwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(13, 62, 'وَإِن يُرِيدُوٓاْ أَن يَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِيٓ أَيَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِينَ', 'পক্ষান্তরে তারা যদি তোমাকে প্রতারণা করতে চায়, তবে তোমার জন্য আল্লাহই যথেষ্ট, তিনিই তোমাকে শক্তি যুগিয়েছেন স্বীয় সাহায্যে ও মুসলমানদের মাধ্যমে।', 'Wain yureedoo an yakhdaAAooka fainna hasbaka Allahu huwa allathee ayyadaka binasrihi wabialmumineena', 1, NOW(), NOW()),
(13, 63, 'وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ', 'আর প্রীতি সঞ্চার করেছেন তাদের অন্তরে। যদি তুমি সেসব কিছু ব্যয় করে ফেলতে, যা কিছু যমীনের বুকে রয়েছে, তাদের মনে প্রীতি সঞ্চার করতে পারতে না। কিন্তু আল্লাহ তাদের মনে প্রীতি সঞ্চার করেছেন। নিঃসন্দেহে তিনি পরাক্রমশালী, সুকৌশলী।', 'Waallafa bayna quloobihim law anfaqta ma fee alardi jameeAAan ma allafta bayna quloobihim walakinna Allaha allafa baynahum innahu AAazeezun hakeemun', 1, NOW(), NOW()),
(13, 64, 'يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ', 'হে নবী, আপনার জন্য এবং যেসব মুসলমান আপনার সাথে রয়েছে তাদের সবার জন্য আল্লাহ যথেষ্ট।', 'Ya ayyuha alnnabiyyu hasbuka Allahu wamani ittabaAAaka mina almumineena', 1, NOW(), NOW()),
(13, 65, 'يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ', 'হে নবী, আপনি মুসলমানগণকে উৎসাহিত করুন জেহাদের জন্য। তোমাদের মধ্যে যদি বিশ জন দৃঢ়পদ ব্যক্তি থাকে, তবে জয়ী হবে দু’শর মোকাবেলায়। আর যদি তোমাদের মধ্যে থাকে একশ লোক, তবে জয়ী হবে হাজার কাফেরের উপর থেকে তার কারণ ওরা জ্ঞানহীন।', 'Ya ayyuha alnnabiyyu harridi almumineena AAala alqitali in yakun minkum AAishroona sabiroona yaghliboo miatayni wain yakun minkum miatun yaghliboo alfan mina allatheena kafaroo biannahum qawmun la yafqahoona', 1, NOW(), NOW()),
(13, 66, 'ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ', 'এখন বোঝা হালকা করে দিয়েছেন আল্লাহ তা’আলা তোমাদের উপর এবং তিনি জেনে নিয়েছেন যে, তোমাদের মধ্য দূর্বলতা রয়েছে। কাজেই তোমাদের মধ্যে যদি দৃঢ়চিত্ত একশ লোক বিদ্যমান থাকে, তবে জয়ী হবে দু’শর উপর। আর যদি তোমরা এক হাজার হও তবে আল্লাহর হুকুম অনুযায়ী জয়ী হবে দু’হাজারের উপর আর আল্লাহ রয়েছেন দৃঢ়চিত্ত লোকদের সাথে।', 'Alana khaffafa Allahu AAankum waAAalima anna feekum daAAfan fain yakun minkum miatun sabiratun yaghliboo miatayni wain yakun minkum alfun yaghliboo alfayni biithni Allahi waAllahu maAAa alssabireena', 1, NOW(), NOW()),
(13, 67, 'مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ', 'নবীর পক্ষে উচিত নয় বন্দীদিগকে নিজের কাছে রাখা, যতক্ষণ না দেশময় প্রচুর রক্তপাত ঘটাবে। তোমরা পার্থিব সম্পদ কামনা কর, অথচ আল্লাহ চান আখেরাত। আর আল্লাহ হচ্ছেন পরাক্রমশালী হেকমতওয়ালা।', 'Ma kana linabiyyin an yakoona lahu asra hatta yuthkhina fee alardi tureedoona AAarada alddunya waAllahu yureedu alakhirata waAllahu AAazeezun hakeemun', 1, NOW(), NOW()),
(13, 68, 'لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ', 'যদি একটি বিষয় না হত যা পূর্ব থেকেই আল্লাহ লিখে রেখেছেন, তাহলে তোমরা যা গ্রহণ করছ সেজন্য বিরাট আযাব এসে পৌছাত।', 'Lawla kitabun mina Allahi sabaqa lamassakum feema akhathtum AAathabun AAatheemun', 1, NOW(), NOW()),
(13, 69, 'فَكُلُواْ مِمَّا غَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'সুতরাং তোমরা খাও গনীমত হিসাবে তোমরা যে পরিচ্ছন্ন ও হালাল বস্তু অর্জন করেছ তা থেকে। আর আল্লাহকে ভয় করতে থাক। নিশ্চয়ই আল্লাহ ক্ষমাশীল, মেহেরবান।', 'Fakuloo mimma ghanimtum halalan tayyiban waittaqoo Allaha inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(13, 70, 'يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّمَن فِيٓ أَيۡدِيكُم مِّنَ ٱلۡأَسۡرَىٰٓ إِن يَعۡلَمِ ٱللَّهُ فِي قُلُوبِكُمۡ خَيۡرٗا يُؤۡتِكُمۡ خَيۡرٗا مِّمَّآ أُخِذَ مِنكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'হে নবী, তাদেরকে বলে দাও, যারা তোমার হাতে বন্দী হয়ে আছে যে, আল্লাহ যদি তোমাদের অন্তরে কোন রকম মঙ্গলচিন্তা রয়েছে বলে জানেন, তবে তোমাদেরকে তার চেয়ে বহুগুণ বেশী দান করবেন যা তোমাদের কাছ থেকে বিনিময়ে নেয়া হয়েছে। তাছাড়া তোমাদেরকে তিনি ক্ষমা করে দিবেন। বস্তুতঃ আল্লাহ ক্ষমাশীল, করুণাময়।', 'Ya ayyuha alnnabiyyu qul liman fee aydeekum mina alasra in yaAAlami Allahu fee quloobikum khayran yutikum khayran mimma okhitha minkum wayaghfir lakum waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(13, 71, 'وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'আর যদি তারা তোমার সাথে প্রতারণা করতে চায়-বস্তুতঃ তারা আল্লাহর সাথেও ইতিপূর্বে প্রতারণা করেছে, অতঃপর তিনি তাদেরকে ধরিয়ে দিয়েছেন। আর আল্লাহ সর্ববিষয়ে পরিজ্ঞাত, সুকৌশলী।', 'Wain yureedoo khiyanataka faqad khanoo Allaha min qablu faamkana minhum waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(13, 72, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ', 'এতে কোন সন্দেহ নেই যে, যারা ঈমান এনেছে, দেশ ত্যাগ করেছে, স্বীয় জান ও মাল দ্বারা আল্লাহর রাহে জেহাদ করেছে এবং যারা তাদেরকে আশ্রয় ও সাহায্য সহায়তা দিয়েছে, তারা একে অপরের সহায়ক। আর যারা ঈমান এনেছে কিন্তু দেশ ত্যাগ করেনি তাদের বন্ধুত্বে তোমাদের প্রয়োজন নেই যতক্ষণ না তারা দেশত্যাগ করে। অবশ্য যদি তারা ধর্মীয় ব্যাপারে তোমাদের সহায়তা কামনা করে, তবে তাদের সাহায্য করা তোমাদের কর্তব্য। কিন্তু তোমাদের সাথে যাদের সহযোগী চুক্তি বিদ্যমান রয়েছে, তাদের মোকাবেলায় নয়। বস্তুতঃ তোমরা যা কিছু কর, আল্লাহ সেসবই দেখেন।', 'Inna allatheena amanoo wahajaroo wajahadoo biamwalihim waanfusihim fee sabeeli Allahi waallatheena awaw wanasaroo olaika baAAduhum awliyao baAAdin waallatheena amanoo walam yuhajiroo ma lakum min walayatihim min shayin hatta yuhajiroo waini istansarookum fee alddeeni faAAalaykumu alnnasru illa AAala qawmin baynakum wabaynahum meethaqun waAllahu bima taAAmaloona baseerun', 1, NOW(), NOW()),
(13, 73, 'وَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ', 'আর যারা কাফের তারা পারস্পরিক সহযোগী, বন্ধু। তোমরা যদি এমন ব্যবস্থা না কর, তবে দাঙ্গা-হাঙ্গামা বিস্তার লাভ করবে এবং দেশময় বড়ই অকল্যাণ হবে।', 'Waallatheena kafaroo baAAduhum awliyao baAAdin illa tafAAaloohu takun fitnatun fee alardi wafasadun kabeerun', 1, NOW(), NOW()),
(13, 74, 'وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ', 'আর যারা ঈমান এনেছে, নিজেদের ঘর-বাড়ী ছেড়েছে এবং আল্লাহর রাহে জেহাদ করেছে এবং যারা তাদেরকে আশ্রয় দিয়েছে, সাহায্য-সহায়তা করেছে, তাঁরা হলো সত্যিকার মুসলমান। তাঁদের জন্যে রয়েছে, ক্ষমা ও সম্মানজনক রুযী।', 'Waallatheena amanoo wahajaroo wajahadoo fee sabeeli Allahi waallatheena awaw wanasaroo olaika humu almuminoona haqqan lahum maghfiratun warizqun kareemun', 1, NOW(), NOW()),
(13, 75, 'وَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَـٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ', 'আর যারা ঈমান এনেছে পরবর্তী পর্যায়ে এবং ঘর-বাড়ী ছেড়েছে এবং তোমাদের সাথে সম্মিলিত হয়ে জেহাদ করেছে, তারাও তোমাদেরই অন্তর্ভুক্ত। বস্তুতঃ যারা আত্নীয়, আল্লাহর বিধান মতে তারা পরস্পর বেশী হকদার। নিশ্চয়ই আল্লাহ যাবতীয় বিষয়ে সক্ষম ও অবগত।', 'Waallatheena amanoo min baAAdu wahajaroo wajahadoo maAAakum faolaika minkum waoloo alarhami baAAduhum awla bibaAAdin fee kitabi Allahi inna Allaha bikulli shayin AAaleemun', 1, NOW(), NOW()),
(14, 1, 'بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ', 'সম্পর্কচ্ছেদ করা হল আল্লাহ ও তাঁর রসূলের পক্ষ থেকে সেই মুশরিকদের সাথে, যাদের সাথে তোমরা চুক্তিবদ্ধ হয়েছিলে।', 'Baraatun mina Allahi warasoolihi ila allatheena AAahadtum mina almushrikeena', 1, NOW(), NOW()),
(14, 2, 'فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ', 'অতঃপর তোমরা পরিভ্রমণ কর এ দেশে চার মাসকাল। আর জেনে রেখো, তোমরা আল্লাহকে পরাভূত করতে পারবে না, আর নিশ্চয়ই আল্লাহ কাফেরদিগকে লাঞ্ছিত করে থাকেন।', 'Faseehoo fee alardi arbaAAata ashhurin waiAAlamoo annakum ghayru muAAjizee Allahi waanna Allaha mukhzee alkafireena', 1, NOW(), NOW()),
(14, 3, 'وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ', 'আর মহান হজ্বের দিনে আল্লাহ ও তাঁর রসূলের পক্ষ থেকে লোকদের প্রতি ঘোষণা করে দেয়া হচ্ছে যে, আল্লাহ মুশরেকদের থেকে দায়িত্ব মুক্ত এবং তাঁর রসূলও। অবশ্য যদি তোমরা তওবা কর, তবে তা, তোমাদের জন্যেও কল্যাণকর, আর যদি মুখ ফেরাও, তবে জেনে রেখো, আল্লাহকে তোমরা পরাভূত করতে পারবে না। আর কাফেরদেরকে মর্মান্তিক শাস্তির সুসংবাদ দাও।', 'Waathanun mina Allahi warasoolihi ila alnnasi yawma alhajji alakbari anna Allaha bareeon mina almushrikeena warasooluhu fain tubtum fahuwa khayrun lakum wain tawallaytum faiAAlamoo annakum ghayru muAAjizee Allahi wabashshiri allatheena kafaroo biAAathabin aleemin', 1, NOW(), NOW()),
(14, 4, 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ شَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ', 'তবে যে মুশরিকদের সাথে তোমরা চুক্তি বদ্ধ, অতপরঃ যারা তোমাদের ব্যাপারে কোন ত্রুটি করেনি এবং তোমাদের বিরুদ্ধে কাউকে সাহায্যও করেনি, তাদের সাথে কৃত চুক্তিকে তাদের দেয়া মেয়াদ পর্যন্ত পূরণ কর। অবশ্যই আল্লাহ সাবধানীদের পছন্দ করেন।', 'Illa allatheena AAahadtum mina almushrikeena thumma lam yanqusookum shayan walam yuthahiroo AAalaykum ahadan faatimmoo ilayhim AAahdahum ila muddatihim inna Allaha yuhibbu almuttaqeena', 1, NOW(), NOW()),
(14, 5, 'فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'অতঃপর নিষিদ্ধ মাস অতিবাহিত হলে মুশরিকদের হত্যা কর যেখানে তাদের পাও, তাদের বন্দী কর এবং অবরোধ কর। আর প্রত্যেক ঘাঁটিতে তাদের সন্ধানে ওঁৎ পেতে বসে থাক। কিন্তু যদি তারা তওবা করে, নামায কায়েম করে, যাকাত আদায় করে, তবে তাদের পথ ছেড়ে দাও। নিশ্চয় আল্লাহ অতি ক্ষমাশীল, পরম দয়ালু।', 'Faitha insalakha alashhuru alhurumu faoqtuloo almushrikeena haythu wajadtumoohum wakhuthoohum waohsuroohum waoqAAudoo lahum kulla marsadin fain taboo waaqamoo alssalata waatawoo alzzakata fakhalloo sabeelahum inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(14, 6, 'وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ', 'আর মুশরিকদের কেউ যদি তোমার কাছে আশ্রয় প্রার্থনা করে, তবে তাকে আশ্রয় দেবে, যাতে সে আল্লাহর কালাম শুনতে পায়, অতঃপর তাকে তার নিরাপদ স্থানে পৌছে দেবে। এটি এজন্যে যে এরা জ্ঞান রাখে না।', 'Wain ahadun mina almushrikeena istajaraka faajirhu hatta yasmaAAa kalama Allahi thumma ablighhu mamanahu thalika biannahum qawmun la yaAAlamoona', 1, NOW(), NOW()),
(14, 7, 'كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ', 'মুশরিকদের চুক্তি আল্লাহর নিকট ও তাঁর রসূলের নিকট কিরূপে বলবৎ থাকবে। তবে যাদের সাথে তোমরা চুক্তি সম্পাদন করেছ মসজিদুল-হারামের নিকট। অতএব, যে পর্যন্ত তারা তোমাদের জন্যে সরল থাকে, তোমরাও তাদের জন্য সরল থাক। নিঃসন্দেহের আল্লাহ সাবধানীদের পছন্দ করেন।', 'Kayfa yakoonu lilmushrikeena AAahdun AAinda Allahi waAAinda rasoolihi illa allatheena AAahadtum AAinda almasjidi alharami fama istaqamoo lakum faistaqeemoo lahum inna Allaha yuhibbu almuttaqeena', 1, NOW(), NOW()),
(14, 8, 'كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا وَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَٰسِقُونَ', 'কিরূপে? তারা তোমাদের উপর জয়ী হলে তোমাদের আত্নীয়তার ও অঙ্গীকারের কোন মর্যাদা দেবে না। তারা মুখে তোমাদের সন্তুষ্ট করে, কিন্তু তাদের অন্তরসমূহ তা অস্বীকার করে, আর তাদের অধিকাংশ প্রতিশ্রুতি ভঙ্গকারী।', 'Kayfa wain yathharoo AAalaykum la yarquboo feekum illan wala thimmatan yurdoonakum biafwahihim wataba quloobuhum waaktharuhum fasiqoona', 1, NOW(), NOW()),
(14, 9, 'ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ', 'তারা আল্লাহর আয়াত সমূহ নগন্য মুল্যে বিক্রয় করে, অতঃপর লোকদের নিবৃত রাখে তাঁর পথ থেকে, তারা যা করে চলছে, তা অতি নিকৃষ্ট।', 'Ishtaraw biayati Allahi thamanan qaleelan fasaddoo AAan sabeelihi innahum saa ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(14, 10, 'لَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ', 'তারা মর্যাদা দেয় না কোন মুসলমানের ক্ষেত্রে আত্নীয়তার, আর না অঙ্গীকারের। আর তারাই সীমালংঘনকারী।', 'La yarquboona fee muminin illan wala thimmatan waolaika humu almuAAtadoona', 1, NOW(), NOW()),
(14, 11, 'فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ', 'অবশ্য তারা যদি তওবা করে, নামায কায়েম করে আর যাকাত আদায় করে, তবে তারা তোমাদের দ্বীনী ভাই। আর আমি বিধানসমূহে জ্ঞানী লোকদের জন্যে সর্বস্তরে র্বণনা করে থাকি।', 'Fain taboo waaqamoo alssalata waatawoo alzzakata faikhwanukum fee alddeeni wanufassilu alayati liqawmin yaAAlamoona', 1, NOW(), NOW()),
(14, 12, 'وَإِن نَّكَثُوٓاْ أَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ', 'আর যদি ভঙ্গ করে তারা তাদের শপথ প্রতিশ্রুতির পর এবং বিদ্রুপ করে তোমাদের দ্বীন সম্পর্কে, তবে কুফর প্রধানদের সাথে যুদ্ধ কর। কারণ, এদের কেন শপথ নেই যাতে তারা ফিরে আসে।', 'Wain nakathoo aymanahum min baAAdi AAahdihim wataAAanoo fee deenikum faqatiloo aimmata alkufri innahum la aymana lahum laAAallahum yantahoona', 1, NOW(), NOW()),
(14, 13, 'أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ', 'তোমরা কি সেই দলের সাথে যুদ্ধ করবে না; যারা ভঙ্গ করেছে নিজেদের শপথ এবং সঙ্কল্প নিয়েছে রসূলকে বহিস্কারের? আর এরাই প্রথম তোমাদের সাথে বিবাদের সূত্রপাত করেছে। তোমরা কি তাদের ভয় কর? অথচ তোমাদের ভয়ের অধিকতর যোগ্য হলেন আল্লাহ, যদি তোমরা মুমিন হও।', 'Ala tuqatiloona qawman nakathoo aymanahum wahammoo biikhraji alrrasooli wahum badaookum awwala marratin atakhshawnahum faAllahu ahaqqu an takhshawhu in kuntum mumineena', 1, NOW(), NOW()),
(14, 14, 'قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ', 'যুদ্ধ কর ওদের সাথে, আল্লাহ তোমাদের হস্তে তাদের শাস্তি দেবেন। তাদের লাঞ্ছিত করবেন, তাদের বিরুদ্ধে তোমাদের জয়ী করবেন এবং মুসলমানদের অন্তরসমূহ শান্ত করবেন।', 'Qatiloohum yuAAaththibhumu Allahu biaydeekum wayukhzihim wayansurkum AAalayhim wayashfi sudoora qawmin mumineena', 1, NOW(), NOW()),
(14, 15, 'وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'এবং তাদের মনের ক্ষোভ দূর করবেন। আর আল্লাহ যার প্রতি ইচ্ছা ক্ষমাশীল হবে, আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Wayuthhib ghaytha quloobihim wayatoobu Allahu AAala man yashao waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 16, 'أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ وَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ', 'তোমরা কি মনে কর যে, তোমাদের ছেড়ে দেয়া হবে এমনি, যতক্ষণ না আল্লাহ জেনে নেবেন তোমাদের কে যুদ্ধ করেছে এবং কে আল্লাহ, তাঁর রসূল ও মুসলমানদের ব্যতীত অন্য কাউকে অন্তরঙ্গ বন্ধুরূপে গ্রহণ করা থেকে বিরত রয়েছে। আর তোমরা যা কর সে বিষয়ে আল্লাহ সবিশেষ অবহিত।', 'Am hasibtum an tutrakoo walamma yaAAlami Allahu allatheena jahadoo minkum walam yattakhithoo min dooni Allahi wala rasoolihi wala almumineena waleejatan waAllahu khabeerun bima taAAmaloona', 1, NOW(), NOW()),
(14, 17, 'مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ', 'মুশরিকরা যোগ্যতা রাখে না আল্লাহর মসজিদ আবাদ করার, যখন তারা নিজেরাই নিজেদের কুফরীর স্বীকৃতি দিচ্ছে। এদের আমল বরবাদ হবে এবং এরা আগুনে স্থায়ীভাবে বসবাস করবে।', 'Ma kana lilmushrikeena an yaAAmuroo masajida Allahi shahideena AAala anfusihim bialkufri olaika habitat aAAmaluhum wafee alnnari hum khalidoona', 1, NOW(), NOW()),
(14, 18, 'إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَـٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ', 'নিঃসন্দেহে তারাই আল্লাহর মসজিদ আবাদ করবে যারা ঈমান এনেছে আল্লাহর প্রতি ও শেষ দিনের প্রতি এবং কায়েম করেছে নামায ও আদায় করে যাকাত; আল্লাহ ব্যতীত আর কাউকে ভয় করে না। অতএব, আশা করা যায়, তারা হেদায়েত প্রাপ্তদের অন্তর্ভূক্ত হবে।', 'Innama yaAAmuru masajida Allahi man amana biAllahi waalyawmi alakhiri waaqama alssalata waata alzzakata walam yakhsha illa Allaha faAAasa olaika an yakoonoo mina almuhtadeena', 1, NOW(), NOW()),
(14, 19, '۞أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'তোমরা কি হাজীদের পানি সরবরাহ ও মসজিদুল-হারাম আবাদকরণকে সেই লোকের সমান মনে কর, যে ঈমান রাখে আল্লাহ ও শেষ দিনের প্রতি এবং যুদ্ধ করেছে আল্লাহর রাহে, এরা আল্লাহর দৃষ্টিতে সমান নয়, আর আল্লাহ জালেম লোকদের হেদায়েত করেন না।', 'AjaAAaltum siqayata alhajji waAAimarata almasjidi alharami kaman amana biAllahi waalyawmi alakhiri wajahada fee sabeeli Allahi la yastawoona AAinda Allahi waAllahu la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(14, 20, 'ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ', 'যারা ঈমান এনেছে, দেশ ত্যাগ করেছে এবং আল্লাহর রাহে নিজেদের জান ও মাল দিয়ে জেহাদ করেছে, তাদের বড় মর্যাদা রয়েছে আল্লাহর কাছে আর তারাই সফলকাম।', 'Allatheena amanoo wahajaroo wajahadoo fee sabeeli Allahi biamwalihim waanfusihim aAAthamu darajatan AAinda Allahi waolaika humu alfaizoona', 1, NOW(), NOW()),
(14, 21, 'يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّـٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ', 'তাদের সুসংবাদ দিচ্ছেন তাদের পরওয়ারদেগার স্বীয় দয়া ও সন্তোষের এবং জান্নাতের, সেখানে আছে তাদের জন্য স্থায়ী শান্তি।', 'Yubashshiruhum rabbuhum birahmatin minhu waridwanin wajannatin lahum feeha naAAeemun muqeemun', 1, NOW(), NOW()),
(14, 22, 'خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ', 'তথায় তারা থাকবে চিরদিন। নিঃসন্দেহে আল্লাহর কাছে আছে মহাপুরস্কার।', 'Khalideena feeha abadan inna Allaha AAindahu ajrun AAatheemun', 1, NOW(), NOW()),
(14, 23, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'হে ঈমানদারগণ! তোমরা স্বীয় পিতা ও ভাইদের অভিভাবকরূপে গ্রহণ করো না, যদি তারা ঈমান অপেক্ষা কুফরকে ভালবাসে। আর তোমাদের যারা তাদের অভিভাবকরূপে গ্রহণ করে তারা সীমালংঘনকারী।', 'Ya ayyuha allatheena amanoo la tattakhithoo abaakum waikhwanakum awliyaa ini istahabboo alkufra AAala aleemani waman yatawallahum minkum faolaika humu alththalimoona', 1, NOW(), NOW()),
(14, 24, 'قُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ', 'বল, তোমাদের নিকট যদি তোমাদের পিতা তোমাদের সন্তান, তোমাদের ভাই তোমাদের পত্নী, তোমাদের গোত্র তোমাদের অর্জিত ধন-সম্পদ, তোমাদের ব্যবসা যা বন্ধ হয়ে যাওয়ার ভয় কর এবং তোমাদের বাসস্থান-যাকে তোমরা পছন্দ কর-আল্লাহ, তাঁর রসূল ও তাঁর রাহে জেহাদ করা থেকে অধিক প্রিয় হয়, তবে অপেক্ষা কর, আল্লাহর বিধান আসা পর্যন্ত, আর আল্লাহ ফাসেক সম্প্রদায়কে হেদায়েত করেন না।', 'Qul in kana abaokum waabnaokum waikhwanukum waazwajukum waAAasheeratukum waamwalun iqtaraftumooha watijaratun takhshawna kasadaha wamasakinu tardawnaha ahabba ilaykum mina Allahi warasoolihi wajihadin fee sabeelihi fatarabbasoo hatta yatiya Allahu biamrihi waAllahu la yahdee alqawma alfasiqeena', 1, NOW(), NOW()),
(14, 25, 'لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ', 'আল্লাহ তোমাদের সাহায্য করেছেন অনেক ক্ষেত্রে এবং হোনাইনের দিনে, যখন তোমাদের সংখ্যধিক্য তোমাদের প্রফুল্ল করেছিল, কিন্তু তা তোমাদের কোন কাজে আসেনি এবং পৃথিবী প্রশস্ত হওয়া সত্তেও তোমাদের জন্য সংকুচিত হয়েছিল। অতঃপর পৃষ্ঠ প্রদর্শন করে পলায়ন করেছিলে।', 'Laqad nasarakumu Allahu fee mawatina katheeratin wayawma hunaynin ith aAAjabatkum kathratukum falam tughni AAankum shayan wadaqat AAalaykumu alardu bima rahubat thumma wallaytum mudbireena', 1, NOW(), NOW()),
(14, 26, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ', 'তারপর আল্লাহ নাযিল করেন নিজের পক্ষ থেকে সান্ত্বনা, তাঁর রসূল ও মুমিনদের প্রতি এবং অবতীর্ণ করেন এমন সেনাবাহিনী যাদের তোমরা দেখতে পাওনি। আর শাস্তি প্রদান করেন কাফেরদের এবং এটি হল কাফেরদের কর্মফল।', 'Thumma anzala Allahu sakeenatahu AAala rasoolihi waAAala almumineena waanzala junoodan lam tarawha waAAaththaba allatheena kafaroo wathalika jazao alkafireena', 1, NOW(), NOW()),
(14, 27, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'এরপর আল্লাহ যাদের প্রতি ইচ্ছা তওবার তওফীক দেবেন, আর আল্লাহ অতীব ক্ষমাশীল, পরম দয়ালু।', 'Thumma yatoobu Allahu min baAAdi thalika AAala man yashao waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(14, 28, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ', 'হে ঈমানদারগণ! মুশরিকরা তো অপবিত্র। সুতরাং এ বছরের পর তারা যেন মসজিদুল-হারামের নিকট না আসে। আর যদি তোমরা দারিদ্রে?480; আশংকা কর, তবে আল্লাহ চাইলে নিজ করুনায় ভবিষ্যতে তোমাদের অভাবমুক্ত করে দেবেন। নিঃসন্দেহে আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Ya ayyuha allatheena amanoo innama almushrikoona najasun fala yaqraboo almasjida alharama baAAda AAamihim hatha wain khiftum AAaylatan fasawfa yughneekumu Allahu min fadlihi in shaa inna Allaha AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 29, 'قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ', 'তোমরা যুদ্ধ কর আহলে-কিতাবের ঐ লোকদের সাথে, যারা আল্লাহ ও রোজ হাশরে ঈমান রাখে না, আল্লাহ ও তাঁর রসূল যা হারাম করে দিয়েছেন তা হারাম করে না এবং গ্রহণ করে না সত্য ধর্ম, যতক্ষণ না করজোড়ে তারা জিযিয়া প্রদান করে।', 'Qatiloo allatheena la yuminoona biAllahi wala bialyawmi alakhiri wala yuharrimoona ma harrama Allahu warasooluhu wala yadeenoona deena alhaqqi mina allatheena ootoo alkitaba hatta yuAAtoo aljizyata AAan yadin wahum saghiroona', 1, NOW(), NOW()),
(14, 30, 'وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ', 'ইহুদীরা বলে ওযাইর আল্লাহর পুত্র এবং নাসারারা বলে ‘মসীহ আল্লাহর পুত্র’। এ হচ্ছে তাদের মুখের কথা। এরা পূর্ববর্তী কাফেরদের মত কথা বলে। আল্লাহ এদের ধ্বংস করুন, এরা কোন উল্টা পথে চলে যাচ্ছে।', 'Waqalati alyahoodu AAuzayrun ibnu Allahi waqalati alnnasara almaseehu ibnu Allahi thalika qawluhum biafwahihim yudahioona qawla allatheena kafaroo min qablu qatalahumu Allahu anna yufakoona', 1, NOW(), NOW()),
(14, 31, 'ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهٗا وَٰحِدٗاۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ', 'তারা তাদের পন্ডিত ও সংসার-বিরাগীদিগকে তাদের পালনকর্তারূপে গ্রহণ করেছে আল্লাহ ব্যতীত এবং মরিয়মের পুত্রকেও। অথচ তারা আদিষ্ট ছিল একমাত্র মাবুদের এবাদতের জন্য। তিনি ছাড়া কোন মাবুদ নেই, তারা তাঁর শরীক সাব্যস্ত করে, তার থেকে তিনি পবিত্র।', 'Ittakhathoo ahbarahum waruhbanahum arbaban min dooni Allahi waalmaseeha ibna maryama wama omiroo illa liyaAAbudoo ilahan wahidan la ilaha illa huwa subhanahu AAamma yushrikoona', 1, NOW(), NOW()),
(14, 32, 'يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ', 'তারা তাদের মুখের ফুৎকারে আল্লাহর নূরকে নির্বাপিত করতে চায়। কিন্তু আল্লাহ অবশ্যই তাঁর নূরের পূর্ণতা বিধান করবেন, যদিও কাফেররা তা অপ্রীতিকর মনে করে।', 'Yureedoona an yutfioo noora Allahi biafwahihim wayaba Allahu illa an yutimma noorahu walaw kariha alkafiroona', 1, NOW(), NOW()),
(14, 33, 'هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ', 'তিনিই প্রেরণ করেছেন আপন রসূলকে হেদায়েত ও সত্য দ্বীন সহকারে, যেন এ দ্বীনকে অপরাপর দ্বীনের উপর জয়যুক্ত করেন, যদিও মুশরিকরা তা অপ্রীতিকর মনে করে।', 'Huwa allathee arsala rasoolahu bialhuda wadeeni alhaqqi liyuthhirahu AAala alddeeni kullihi walaw kariha almushrikoona', 1, NOW(), NOW()),
(14, 34, '۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ', 'হে ঈমানদারগণ! পন্ডিত ও সংসারবিরাগীদের অনেকে লোকদের মালামাল অন্যায়ভাবে ভোগ করে চলছে এবং আল্লাহর পথ থেকে লোকদের নিবৃত রাখছে। আর যারা স্বর্ণ ও রূপা জমা করে রাখে এবং তা ব্যয় করে না আল্লাহর পথে, তাদের কঠোর আযাবের সুসংবাদ শুনিয়ে দিন।', 'Ya ayyuha allatheena amanoo inna katheeran mina alahbari waalrruhbani layakuloona amwala alnnasi bialbatili wayasuddoona AAan sabeeli Allahi waallatheena yaknizoona alththahaba waalfiddata wala yunfiqoonaha fee sabeeli Allahi fabashshirhum biAAathabin aleemin', 1, NOW(), NOW()),
(14, 35, 'يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ', 'সে দিন জাহান্নামের আগুনে তা উত্তপ্ত করা হবে এবং তার দ্বারা তাদের ললাট, পার্শ্ব ও পৃষ্ঠদেশকে দগ্ধ করা হবে (সেদিন বলা হবে), এগুলো যা তোমরা নিজেদের জন্যে জমা রেখেছিলে, সুতরাং এক্ষণে আস্বাদ গ্রহণ কর জমা করে রাখার।', 'Yawma yuhma AAalayha fee nari jahannama fatukwa biha jibahuhum wajunoobuhum wathuhooruhum hatha ma kanaztum lianfusikum fathooqoo ma kuntum taknizoona', 1, NOW(), NOW()),
(14, 36, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ', 'নিশ্চয় আল্লাহর বিধান ও গননায় মাস বারটি, আসমানসমূহ ও পৃথিবী সৃষ্টির দিন থেকে। তন্মধ্যে চারটি সম্মানিত। এটিই সুপ্রতিষ্ঠিত বিধান; সুতরাং এর মধ্যে তোমরা নিজেদের প্রতি অত্যাচার করো না। আর মুশরিকদের সাথে তোমরা যুদ্ধ কর সমবেতভাবে, যেমন তারাও তোমাদের সাথে যুদ্ধ করে যাচ্ছে সমবেতভাবে। আর মনে রেখো, আল্লাহ মুত্তাকীনদের সাথে রয়েছেন।', 'Inna AAiddata alshshuhoori AAinda Allahi ithna AAashara shahran fee kitabi Allahi yawma khalaqa alssamawati waalarda minha arbaAAatun hurumun thalika alddeenu alqayyimu fala tathlimoo feehinna anfusakum waqatiloo almushrikeena kaffatan kama yuqatiloonakum kaffatan waiAAlamoo anna Allaha maAAa almuttaqeena', 1, NOW(), NOW()),
(14, 37, 'إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', 'এই মাস পিছিয়ে দেয়ার কাজ কেবল কুফরীর মাত্রা বৃদ্ধি করে, যার ফলে কাফেরগণ গোমরাহীতে পতিত হয়। এরা হালাল করে নেয় একে এক বছর এবং হারাম করে নেয় অন্য বছর, যাতে তারা গণনা পূর্ণ করে নেয় আল্লাহর নিষিদ্ধ মাসগুলোর। অতঃপর হালাল করে নেয় আল্লাহর হারামকৃত মাসগুলোকে। তাদের মন্দকাজগুলো তাদের জন্যে শোভনীয় করে দেয়া হল। আর আল্লাহ কাফের সম্প্রদায়কে হেদায়েত করেন না।', 'Innama alnnaseeo ziyadatun fee alkufri yudallu bihi allatheena kafaroo yuhilloonahu AAaman wayuharrimoonahu AAaman liyuwatioo AAiddata ma harrama Allahu fayuhilloo ma harrama Allahu zuyyina lahum sooo aAAmalihim waAllahu la yahdee alqawma alkafireena', 1, NOW(), NOW()),
(14, 38, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ', 'হে ঈমানদারগণ, তোমাদের কি হল, যখন আল্লাহর পথে বের হবার জন্যে তোমাদের বলা হয়, তখন মাটি জড়িয়ে ধর, তোমরা কি আখেরাতের পরিবর্তে দুনিয়ার জীবনে পরিতুষ্ট হয়ে গেলে? অথচ আখেরাতের তুলনায় দুনিয়ার জীবনের উপকরণ অতি অল্প।', 'Ya ayyuha allatheena amanoo ma lakum itha qeela lakumu infiroo fee sabeeli Allahi iththaqaltum ila alardi aradeetum bialhayati alddunya mina alakhirati fama mataAAu alhayati alddunya fee alakhirati illa qaleelun', 1, NOW(), NOW()),
(14, 39, 'إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'যদি বের না হও, তবে আল্লাহ তোমাদের মর্মন্তুদ আযাব দেবেন এবং অপর জাতিকে তোমাদের স্থলাভিষিক্ত করবেন। তোমরা তাঁর কোন ক্ষতি করতে পারবে না, আর আল্লাহ সর্ববিষয়ে শক্তিমান।', 'Illa tanfiroo yuAAaththibkum AAathaban aleeman wayastabdil qawman ghayrakum wala tadurroohu shayan waAllahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(14, 40, 'إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'যদি তোমরা তাকে (রসূলকে) সাহায্য না কর, তবে মনে রেখো, আল্লাহ তার সাহায্য করেছিলেন, যখন তাকে কাফেররা বহিষ্কার করেছিল, তিনি ছিলেন দু’জনের একজন, যখন তারা গুহার মধ্যে ছিলেন। তখন তিনি আপন সঙ্গীকে বললেন বিষন্ন হয়ো না, আল্লাহ আমাদের সাথে আছেন। অতঃপর আল্লাহ তার প্রতি স্বীয় সান্তনা নাযিল করলেন এবং তাঁর সাহায্যে এমন বাহিনী পাঠালেন, যা তোমরা দেখনি। বস্তুতঃ আল্লাহ কাফেরদের মাথা নীচু করে দিলেন আর আল্লাহর কথাই সদা সমুন্নত এবং আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।', 'Illa tansuroohu faqad nasarahu Allahu ith akhrajahu allatheena kafaroo thaniya ithnayni ith huma fee alghari ith yaqoolu lisahibihi la tahzan inna Allaha maAAana faanzala Allahu sakeenatahu AAalayhi waayyadahu bijunoodin lam tarawha wajaAAala kalimata allatheena kafaroo alssufla wakalimatu Allahi hiya alAAulya waAllahu AAazeezun hakeemun', 1, NOW(), NOW()),
(14, 41, 'ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', 'তোমরা বের হয়ে পড় স্বল্প বা প্রচুর সরঞ্জামের সাথে এবং জেহাদ কর আল্লাহর পথে নিজেদের মাল ও জান দিয়ে, এটি তোমাদের জন্যে অতি উত্তম, যদি তোমরা বুঝতে পার।', 'Infiroo khifafan wathiqalan wajahidoo biamwalikum waanfusikum fee sabeeli Allahi thalikum khayrun lakum in kuntum taAAlamoona', 1, NOW(), NOW()),
(14, 42, 'لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ عَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ', 'যদি আশু লাভের সম্ভাবনা থাকতো এবং যাত্রাপথও সংক্ষিপ্ত হতো, তবে তারা অবশ্যই আপনার সহযাত্রী হতো, কিন্তু তাদের নিকট যাত্রাপথ সুদীর্ঘ মনে হল। আর তারা এমনই শপথ করে বলবে, আমাদের সাধ্য থাকলে অবশ্যই তোমাদের সাথে বের হতাম, এরা নিজেরাই নিজেদের বিনষ্ট করছে, আর আল্লাহ জানেন যে, এরা মিথ্যাবাদী।', 'Law kana AAaradan qareeban wasafaran qasidan laittabaAAooka walakin baAAudat AAalayhimu alshshuqqatu wasayahlifoona biAllahi lawi istataAAna lakharajna maAAakum yuhlikoona anfusahum waAllahu yaAAlamu innahum lakathiboona', 1, NOW(), NOW()),
(14, 43, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ', 'আল্লাহ আপনাকে ক্ষমা করুন, আপনি কেন তাদের অব্যাহতি দিলেন, যে পর্যন্ত না আপনার কাছে পরিষ্কার হয়ে যেত সত্যবাদীরা এবং জেনে নিতেন মিথ্যাবাদীদের।', 'AAafa Allahu AAanka lima athinta lahum hatta yatabayyana laka allatheena sadaqoo wataAAlama alkathibeena', 1, NOW(), NOW()),
(14, 44, 'لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ', 'আল্লাহ ও রোজ কেয়ামতের প্রতি যাদের ঈমান রয়েছে তারা মাল ও জান দ্বারা জেহাদ করা থেকে আপনার কাছে অব্যাহতি কামনা করবে না, আর আল্লাহ সাবধানীদের ভাল জানেন।', 'La yastathinuka allatheena yuminoona biAllahi waalyawmi alakhiri an yujahidoo biamwalihim waanfusihim waAllahu AAaleemun bialmuttaqeena', 1, NOW(), NOW()),
(14, 45, 'إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِي رَيۡبِهِمۡ يَتَرَدَّدُونَ', 'নিঃসন্দেহে তারাই আপনার কাছে অব্যাহতি চায়, যারা আল্লাহ ও রোজ কেয়ামতে ঈমান রাখে না এবং তাদের অন্তর সন্দেহগ্রস্ত হয়ে পড়েছে, সুতরাং সন্দেহের আবর্তে তারা ঘুরপাক খেয়ে চলেছে।', 'Innama yastathinuka allatheena la yuminoona biAllahi waalyawmi alakhiri wairtabat quloobuhum fahum fee raybihim yataraddadoona', 1, NOW(), NOW()),
(14, 46, '۞وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ', 'আর যদি তারা বের হবার সংকল্প নিত, তবে অবশ্যই কিছু সরঞ্জাম প্রস্তুত করতো। কিন্তু তাদের উত্থান আল্লাহর পছন্দ নয়, তাই তাদের নিবৃত রাখলেন এবং আদেশ হল বসা লোকদের সাথে তোমরা বসে থাক।', 'Walaw aradoo alkhurooja laaAAaddoo lahu AAuddatan walakin kariha Allahu inbiAAathahum fathabbatahum waqeela oqAAudoo maAAa alqaAAideena', 1, NOW(), NOW()),
(14, 47, 'لَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ', 'যদি তোমাদের সাথে তারা বের হত, তবে তোমাদের অনিষ্ট ছাড়া আর কিছু বৃদ্ধি করতো না, আর অশ্ব ছুটাতো তোমাদের মধ্যে বিভেদ সৃষ্টির উদ্দেশে। আর তোমাদের মাঝে রয়েছে তাদের গুপ্তচর। বস্তুতঃ আল্লাহ যালিমদের ভালভাবেই জানেন।', 'Law kharajoo feekum ma zadookum illa khabalan walaawdaAAoo khilalakum yabghoonakumu alfitnata wafeekum sammaAAoona lahum waAllahu AAaleemun bialththalimeena', 1, NOW(), NOW()),
(14, 48, 'لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ', 'তারা পূর্বে থেকেই বিভেদ সৃষ্টির সুযোগ সন্ধানে ছিল এবং আপনার কার্যসমূহ উল্টা-পাল্টা করে দিচ্ছিল। শেষ পর্যন্ত সত্য প্রতিশ্রুতি এসে গেল এবং জয়ী হল আল্লাহর হুকুম, যে অবস্থায় তারা মন্দবোধ করল।', 'Laqadi ibtaghawoo alfitnata min qablu waqallaboo laka alomoora hatta jaa alhaqqu wathahara amru Allahi wahum karihoona', 1, NOW(), NOW()),
(14, 49, 'وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ', 'আর তাদের কেউ বলে, আমাকে অব্যাহতি দিন এবং পথভ্রষ্ট করবেন না। শোনে রাখ, তারা তো পূর্ব থেকেই পথভ্রষ্ট এবং নিঃসন্দেহে জাহান্নাম এই কাফেরদের পরিবেষ্টন করে রয়েছে।', 'Waminhum man yaqoolu ithan lee wala taftinnee ala fee alfitnati saqatoo wainna jahannama lamuheetatun bialkafireena', 1, NOW(), NOW()),
(14, 50, 'إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ', 'আপনার কোন কল্যাণ হলে তারা মন্দবোধ করে এবং কোন বিপদ উপস্থিত হলে তারা বলে, আমরা পূর্ব থেকেই নিজেদের কাজ সামলে নিয়েছি এবং ফিরে যায় উল্লসিত মনে।', 'In tusibka hasanatun tasuhum wain tusibka museebatun yaqooloo qad akhathna amrana min qablu wayatawallaw wahum farihoona', 1, NOW(), NOW()),
(14, 51, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', 'আপনি বলুন, আমাদের কাছে কিছুই পৌঁছবে না, কিন্তু যা আল্লাহ আমাদের জন্য রেখেছেন; তিনি আমাদের কার্যনির্বাহক। আল্লাহর উপরই মুমিনদের ভরসা করা উচিত।', 'Qul lan yuseebana illa ma kataba Allahu lana huwa mawlana waAAala Allahi falyatawakkali almuminoona', 1, NOW(), NOW()),
(14, 52, 'قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', 'আপনি বলুন, তোমরা তো তোমাদের জন্যে দুটি কল্যাণের একটি প্রত্যাশা কর; আর আমরা প্রত্যাশায় আছি তোমাদের জন্যে যে, আল্লাহ তোমাদের আযাব দান করুন নিজের পক্ষ থেকে অথবা আমাদের হস্তে। সুতরাং তোমরা অপেক্ষা কর, আমরাও তোমাদের সাথে অপেক্ষমাণ।', 'Qul hal tarabbasoona bina illa ihda alhusnayayni wanahnu natarabbasu bikum an yuseebakumu Allahu biAAathabin min AAindihi aw biaydeena fatarabbasoo inna maAAakum mutarabbisoona', 1, NOW(), NOW()),
(14, 53, 'قُلۡ أَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمٗا فَٰسِقِينَ', 'আপনি বলুন, তোমরা ইচ্ছায় অর্থ ব্যয় কর বা অনিচ্ছায়, তোমাদের থেকে তা কখনো কবুল হবে না, তোমরা নাফরমানের দল।', 'Qul anfiqoo tawAAan aw karhan lan yutaqabbala minkum innakum kuntum qawman fasiqeena', 1, NOW(), NOW()),
(14, 54, 'وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ', 'তাদের অর্থ ব্যয় কবুল না হওয়ার এছাড়া আর কোন কারণ নেই যে, তারা আল্লাহ ও তাঁর রসূলের প্রতি অবিশ্বাসী, তারা নামাযে আসে অলসতার সাথে ব্যয় করে সঙ্কুচিত মনে।', 'Wama manaAAahum an tuqbala minhum nafaqatuhum illa annahum kafaroo biAllahi wabirasoolihi wala yatoona alssalata illa wahum kusala wala yunfiqoona illa wahum karihoona', 1, NOW(), NOW()),
(14, 55, 'فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ', 'সুতরাং তাদের ধন-সম্পদ ও সন্তান-সন্ততি যেন আপনাকে বিস্মিত না করে। আল্লাহর ইচ্ছা হল এগুলো দ্বারা দুনিয়ার জীবনে তাদের আযাবে নিপতিত রাখা এবং প্রাণবিয়োগ হওয়া কুফরী অবস্থায়।', 'Fala tuAAjibka amwaluhum wala awladuhum innama yureedu Allahu liyuAAaththibahum biha fee alhayati alddunya watazhaqa anfusuhum wahum kafiroona', 1, NOW(), NOW()),
(14, 56, 'وَيَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَٰكِنَّهُمۡ قَوۡمٞ يَفۡرَقُونَ', 'তারা আল্লাহর নামে হলফ করে বলে যে, তারা তোমাদেরই অন্তর্ভুক্ত, অথচ তারা তোমাদের অন্তর্ভূক্ত নয়, অবশ্য তারা তোমাদের ভয় করে।', 'Wayahlifoona biAllahi innahum laminkum wama hum minkum walakinnahum qawmun yafraqoona', 1, NOW(), NOW()),
(14, 57, 'لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ أَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ', 'তারা কোন আশ্রয়স্থল, কোন গুহা বা মাথা গোঁজার ঠাই পেলে সেদিকে পলায়ন করবে দ্রুতগতিতে।', 'Law yajidoona maljaan aw magharatin aw muddakhalan lawallaw ilayhi wahum yajmahoona', 1, NOW(), NOW()),
(14, 58, 'وَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ', 'তাদের মধ্যে এমন লোকও রয়েছে যারা সদকা বন্টনে আপনাকে দোষারূপ করে। এর থেকে কিছু পেলে সন্তুষ্ট হয় এবং না পেলে বিক্ষুব্ধ হয়।', 'Waminhum man yalmizuka fee alssadaqati fain oAAtoo minha radoo wain lam yuAAtaw minha itha hum yaskhatoona', 1, NOW(), NOW()),
(14, 59, 'وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'কতই না ভাল হত, যদি তারা সন্তুষ্ট হত আল্লাহ ও তার রসূলের উপর এবং বলত, আল্লাহই আমাদের জন্যে যথেষ্ট, আল্লাহ আমাদের দেবেন নিজ করুণায় এবং তাঁর রসূলও, আমরা শুধু আল্লাহকেই কামনা করি।', 'Walaw annahum radoo ma atahumu Allahu warasooluhu waqaloo hasbuna Allahu sayuteena Allahu min fadlihi warasooluhu inna ila Allahi raghiboona', 1, NOW(), NOW()),
(14, 60, '۞إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'যাকাত হল কেবল ফকির, মিসকীন, যাকাত আদায় কারী ও যাদের চিত্ত আকর্ষণ প্রয়োজন তাদে হক এবং তা দাস-মুক্তির জন্যে-ঋণ গ্রস্তদের জন্য, আল্লাহর পথে জেহাদকারীদের জন্যে এবং মুসাফিরদের জন্যে, এই হল আল্লাহর নির্ধারিত বিধান। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Innama alssadaqatu lilfuqarai waalmasakeeni waalAAamileena AAalayha waalmuallafati quloobuhum wafee alrriqabi waalgharimeena wafee sabeeli Allahi waibni alssabeeli fareedatan mina Allahi waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 61, 'وَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ ءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ', 'আর তাদের মধ্যে কেউ কেউ নবীকে ক্লেশ দেয়, এবং বলে, এ লোকটি তো কানসর্বস্ব। আপনি বলে দিন, কান হলেও তোমাদেরই মঙ্গলের জন্য, আল্লাহর উপর বিশ্বাস রাখে এবং বিশ্বাস রাখে মুসলমানদের কথার উপর। বস্তুতঃ তোমাদের মধ্যে যারা ঈমানদার তাদের জন্য তিনি রহমতবিশেষ। আর যারা আল্লাহর রসূলের প্রতি কুৎসা রটনা করে, তাদের জন্য রয়েছে বেদনাদায়ক আযাব।', 'Waminhumu allatheena yuthoona alnnabiyya wayaqooloona huwa othunun qul othunu khayrin lakum yuminu biAllahi wayuminu lilmumineena warahmatun lillatheena amanoo minkum waallatheena yuthoona rasoola Allahi lahum AAathabun aleemun', 1, NOW(), NOW()),
(14, 62, 'يَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ', 'তোমাদের সামনে আল্লাহর কসম খায় যাতে তোমাদের রাযী করতে পারে। অবশ্য তারা যদি ঈমানদার হয়ে থাকে, তবে আল্লাহকে এবং তাঁর রসূলকে রাযী করা অত্যন্ত জরুরী।', 'Yahlifoona biAllahi lakum liyurdookum waAllahu warasooluhu ahaqqu an yurdoohu in kanoo mumineena', 1, NOW(), NOW()),
(14, 63, 'أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ ذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ', 'তারা কি একথা জেনে নেয়নি যে, আল্লাহর সাথে এবং তাঁর রসূলের সাথে যে মোকাবেলা করে তার জন্যে নির্ধারিত রয়েছে দোযখ; তাতে সব সময় থাকবে। এটিই হল মহা-অপমান।', 'Alam yaAAlamoo annahu man yuhadidi Allaha warasoolahu faanna lahu nara jahannama khalidan feeha thalika alkhizyu alAAatheemu', 1, NOW(), NOW()),
(14, 64, 'يَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ', 'মুনাফেকরা এ ব্যাপারে ভয় করে যে, মুসলমানদের উপর না এমন কোন সূরা নাযিল হয়, যাতে তাদের অন্তরের গোপন বিষয় অবহিত করা হবে। সুতরাং আপনি বলে দিন, ঠাট্টা-বিদ্রপ করতে থাক; আল্লাহ তা অবশ্যই প্রকাশ করবেন যার ব্যাপারে তোমরা ভয় করছ।', 'Yahtharu almunafiqoona an tunazzala AAalayhim sooratun tunabbiohum bima fee quloobihim quli istahzioo inna Allaha mukhrijun ma tahtharoona', 1, NOW(), NOW()),
(14, 65, 'وَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ', 'আর যদি তুমি তাদের কাছে জিজ্ঞেস কর, তবে তারা বলবে, আমরা তো কথার কথা বলছিলাম এবং কৌতুক করছিলাম। আপনি বলুন, তোমরা কি আল্লাহর সাথে, তাঁর হুকুম আহকামের সাথে এবং তাঁর রসূলের সাথে ঠাট্টা করছিলে', 'Walain saaltahum layaqoolunna innama kunna nakhoodu wanalAAabu qul abiAllahi waayatihi warasoolihi kuntum tastahzioona', 1, NOW(), NOW()),
(14, 66, 'لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ إِن نَّعۡفُ عَن طَآئِفَةٖ مِّنكُمۡ نُعَذِّبۡ طَآئِفَةَۢ بِأَنَّهُمۡ كَانُواْ مُجۡرِمِينَ', 'ছলনা কর না, তোমরা যে কাফের হয়ে গেছ ঈমান প্রকাশ করার পর। তোমাদের মধ্যে কোন কোন লোককে যদি আমি ক্ষমা করে দেইও, তবে অবশ্য কিছু লোককে আযাবও দেব। কারণ, তারা ছিল গোনাহগার।', 'La taAAtathiroo qad kafartum baAAda eemanikum in naAAfu AAan taifatin minkum nuAAaththib taifatan biannahum kanoo mujrimeena', 1, NOW(), NOW()),
(14, 67, 'ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمُنكَرِ وَيَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَيَقۡبِضُونَ أَيۡدِيَهُمۡۚ نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ', 'মুনাফেক নর-নারী সবারই গতিবিধি একরকম; শিখায় মন্দ কথা, ভাল কথা থেকে বারণ করে এবং নিজ মুঠো বন্ধ রাখে। আল্লাহকে ভুলে গেছে তার, কাজেই তিনিও তাদের ভূলে গেছেন নিঃসন্দেহে মুনাফেকরাই নাফরমান।', 'Almunafiqoona waalmunafiqatu baAAduhum min baAAdin yamuroona bialmunkari wayanhawna AAani almaAAroofi wayaqbidoona aydiyahum nasoo Allaha fanasiyahum inna almunafiqeena humu alfasiqoona', 1, NOW(), NOW()),
(14, 68, 'وَعَدَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ', 'ওয়াদা করেছেন আল্লাহ, মুনাফেক পুরুষ ও মুনাফেক নারীদের এবং কাফেরদের জন্যে দোযখের আগুনের-তাতে পড়ে থাকবে সর্বদা। সেটাই তাদের জন্যে যথেষ্ট। আর আল্লাহ তাদের প্রতি অভিসম্পাত করেছেন এবং তাদের জন্যে রয়েছে স্থায়ী আযাব।', 'WaAAada Allahu almunafiqeena waalmunafiqati waalkuffara nara jahannama khalideena feeha hiya hasbuhum walaAAanahumu Allahu walahum AAathabun muqeemun', 1, NOW(), NOW()),
(14, 69, 'كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ', 'যেমন করে তোমাদের পূর্ববর্তী লোকেরা তোমাদের চেয়ে বেশী ছিল শক্তিতে এবং ধন-সম্পদের ও সন্তান-সন্ততির অধিকারীও ছিল বেশী; অতঃপর উপকৃত হয়েছে নিজেদের ভাগের দ্বারা আবার তোমরা ফায়দা উঠিয়েছ তোমাদের ভাগের দ্বারা-যেমন করে তোমাদের পূর্ববর্তীরা ফায়দা উঠিয়েছিল নিজেদের ভাগের দ্বারা। আর তোমরাও বলছ তাদেরই চলন অনুযায়ী। তারা ছিল সে লোক, যাদের আমলসমূহ নিঃশেষিত হয়ে গেছে দুনিয়া ও আখেরাতে। আর তারাই হয়েছে ক্ষতির সম্মুখীন।', 'Kaallatheena min qablikum kanoo ashadda minkum quwwatan waakthara amwalan waawladan faistamtaAAoo bikhalaqihim faistamtaAAtum bikhalaqikum kama istamtaAAa allatheena min qablikum bikhalaqihim wakhudtum kaallathee khadoo olaika habitat aAAmaluhum fee alddunya waalakhirati waolaika humu alkhasiroona', 1, NOW(), NOW()),
(14, 70, 'أَلَمۡ يَأۡتِهِمۡ نَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ إِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', 'তাদের সংবাদ কি এদের কানে এসে পৌঁছায়নি, যারা ছিল তাদের পূর্বে; নূহের আ’দের ও সামুদের সম্প্রদায় এবং ইব্রাহীমের সম্প্রদায়ের এবং মাদইয়ানবাসীদের? এবং সেসব জনপদের যেগুলোকে উল্টে দেয়া হয়েছিল? তাদের কাছে এসেছিলেন তাদের নবী পরিষ্কার নির্দেশ নিয়ে। বস্তুতঃ আল্লাহ তো এমন ছিলেন না যে, তাদের উপর জুলুম করতেন, কিন্তু তারা নিজেরাই নিজেদের উপর জুলুম করতো।', 'Alam yatihim nabao allatheena min qablihim qawmi noohin waAAadin wathamooda waqawmi ibraheema waashabi madyana waalmutafikati atathum rusuluhum bialbayyinati fama kana Allahu liyathlimahum walakin kanoo anfusahum yathlimoona', 1, NOW(), NOW()),
(14, 71, 'وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ', 'আর ঈমানদার পুরুষ ও ঈমানদার নারী একে অপরের সহায়ক। তারা ভাল কথার শিক্ষা দেয় এবং মন্দ থেকে বিরত রাখে। নামায প্রতিষ্ঠা করে, যাকাত দেয় এবং আল্লাহ ও তাঁর রসূলের নির্দেশ অনুযায়ী জীবন যাপন করে। এদেরই উপর আল্লাহ তা’আলা দয়া করবেন। নিশ্চয়ই আল্লাহ পরাক্রমশীল, সুকৌশলী।', 'Waalmuminoona waalmuminatu baAAduhum awliyao baAAdin yamuroona bialmaAAroofi wayanhawna AAani almunkari wayuqeemoona alssalata wayutoona alzzakata wayuteeAAoona Allaha warasoolahu olaika sayarhamuhumu Allahu inna Allaha AAazeezun hakeemun', 1, NOW(), NOW()),
(14, 72, 'وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'আল্লাহ ঈমানদার পুরুষ ও ঈমানদার নারীদের প্রতিশ্রুতি দিয়েছেনে কানন-কুঞ্জের, যার তলদেশে প্রবাহিত হয় প্রস্রবণ। তারা সে গুলোরই মাঝে থাকবে। আর এসব কানন-কুঞ্জে থাকবে পরিচ্ছন্ন থাকার ঘর। বস্তুতঃ এ সমুদয়ের মাঝে সবচেয়ে বড় হল আল্লাহর সন্তুষ্টি। এটিই হল মহান কৃতকার্যতা।', 'WaAAada Allahu almumineena waalmuminati jannatin tajree min tahtiha alanharu khalideena feeha wamasakina tayyibatan fee jannati AAadnin waridwanun mina Allahi akbaru thalika huwa alfawzu alAAatheemu', 1, NOW(), NOW()),
(14, 73, 'يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'হে নবী, কাফেরদের সাথে যুদ্ধ করুন এবং মুনাফেকদের সাথে তাদের সাথে কঠোরতা অবলম্বন করুন। তাদের ঠিকানা হল দোযখ এবং তাহল নিকৃষ্ট ঠিকানা।', 'Ya ayyuha alnnabiyyu jahidi alkuffara waalmunafiqeena waoghluth AAalayhim wamawahum jahannamu wabisa almaseeru', 1, NOW(), NOW()),
(14, 74, 'يَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ وَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ مِن وَلِيّٖ وَلَا نَصِيرٖ', 'তারা কসম খায় যে, আমরা বলিনি, অথচ নিঃসন্দেহে তারা বলেছে কুফরী বাক্য এবং মুসলমান হবার পর অস্বীকৃতিজ্ঞাপনকারী হয়েছে। আর তারা কামনা করেছিল এমন বস্তুর যা তারা প্রাপ্ত হয়নি। আর এসব তারই পরিণতি ছিল যে, আল্লাহ ও তাঁর রসূল তাদেরকে সম্পদশালী করে দিয়েছিলেন নিজের অনুগ্রহের মাধ্যমে। বস্তুতঃ এরা যদি তওবা করে নেয়, তবে তাদের জন্য মঙ্গল। আর যদি তা না মানে, তবে তাদের কে আযাব দেবেন আল্লাহ তা’আলা, বেদনাদায়ক আযাব দুনিয়া ও আখেরাতে। অতএব, বিশ্বচরাচরে তাদের জন্য কোন সাহায্যকারী-সমর্থক নেই।', 'Yahlifoona biAllahi ma qaloo walaqad qaloo kalimata alkufri wakafaroo baAAda islamihim wahammoo bima lam yanaloo wama naqamoo illa an aghnahumu Allahu warasooluhu min fadlihi fain yatooboo yaku khayran lahum wain yatawallaw yuAAaththibhumu Allahu AAathaban aleeman fee alddunya waalakhirati wama lahum fee alardi min waliyyin wala naseerin', 1, NOW(), NOW()),
(14, 75, '۞وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ', 'তাদের মধ্যে কেউ কেউ রয়েছে যারা আল্লাহ তা’আলার সাথে ওয়াদা করেছিল যে, তিনি যদি আমাদের প্রতি অনুগ্রহ দান করেন, তবে অবশ্যই আমরা ব্যয় করব এবং সৎকর্মীদের অন্তর্ভুক্ত হয়ে থাকব।', 'Waminhum man AAahada Allaha lain atana min fadlihi lanassaddaqanna walanakoonanna mina alssaliheena', 1, NOW(), NOW()),
(14, 76, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ', 'অতঃপর যখন তাদেরকে স্বীয় অনুগ্রহের মাধ্যমে দান করা হয়, তখন তাতে কার্পণ্য করেছে এবং কৃত ওয়াদা থেকে ফিরে গেছে তা ভেঙ্গে দিয়ে।', 'Falamma atahum min fadlihi bakhiloo bihi watawallaw wahum muAAridoona', 1, NOW(), NOW()),
(14, 77, 'فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ', 'তারপর এরই পরিণতিতে তাদের অন্তরে কপটতা স্থান করে নিয়েছে সেদিন পর্যন্ত, যেদিন তার তাঁর সাথে গিয়ে মিলবে। তা এজন্য যে, তারা আল্লাহর সাথে কৃত ওয়াদা লংঘন করেছিল এবং এজন্যে যে, তারা মিথ্যা কথা বলতো।', 'FaaAAqabahum nifaqan fee quloobihim ila yawmi yalqawnahu bima akhlafoo Allaha ma waAAadoohu wabima kanoo yakthiboona', 1, NOW(), NOW()),
(14, 78, 'أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُيُوبِ', 'তারা কি জেনে নেয়নি যে, আল্লাহ তাদের রহস্য ও শলা-পরামর্শ সম্পর্কে অবগত এবং আল্লাহ খুব ভাল করেই জানেন সমস্ত গোপন বিষয়', 'Alam yaAAlamoo anna Allaha yaAAlamu sirrahum wanajwahum waanna Allaha AAallamu alghuyoobi', 1, NOW(), NOW()),
(14, 79, 'ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ', 'সে সমস্ত লোক যারা ভৎর্সনা-বিদ্রূপ করে সেসব মুসলমানদের প্রতি যারা মন খুলে দান-খয়রাত করে এবং তাদের প্রতি যাদের কিছুই নেই শুধুমাত্র নিজের পরিশ্রমলব্দ বস্তু ছাড়া। অতঃপর তাদের প্রতি ঠাট্টা করে। আল্লাহ তাদের প্রতি ঠাট্টা করেছেন এবং তাদের জন্য রয়েছে বেদনাদায়ক আযাব।', 'Allatheena yalmizoona almuttawwiAAeena mina almumineena fee alssadaqati waallatheena la yajidoona illa juhdahum fayaskharoona minhum sakhira Allahu minhum walahum AAathabun aleemun', 1, NOW(), NOW()),
(14, 80, 'ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِينَ مَرَّةٗ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَٰلِكَ بِأَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ', 'তুমি তাদের জন্য ক্ষমা প্রার্থনা কর আর না কর। যদি তুমি তাদের জন্য সত্তর বারও ক্ষমাপ্রার্থনা কর, তথাপি কখনোই তাদেরকে আল্লাহ ক্ষমা করবেন না। তা এজন্য যে, তারা আল্লাহকে এবং তাঁর রসূলকে অস্বীকার করেছে। বস্তুতঃ আল্লাহ না-ফারমানদেরকে পথ দেখান না।', 'Istaghfir lahum aw la tastaghfir lahum in tastaghfir lahum sabAAeena marratan falan yaghfira Allahu lahum thalika biannahum kafaroo biAllahi warasoolihi waAllahu la yahdee alqawma alfasiqeena', 1, NOW(), NOW()),
(14, 81, 'فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ', 'পেছনে থেকে যাওয়া লোকেরা আল্লাহর রসূল থেকে বিচ্ছিন্ন হয়ে বসে থাকতে পেরে আনন্দ লাভ করেছে; আর জান ও মালের দ্বারা আল্লাহর রাহে জেহাদ করতে অপছন্দ করেছে এবং বলেছে, এই গরমের মধ্যে অভিযানে বের হয়ো না। বলে দাও, উত্তাপে জাহান্নামের আগুন প্রচন্ডতম। যদি তাদের বিবেচনা শক্তি থাকত।', 'Fariha almukhallafoona bimaqAAadihim khilafa rasooli Allahi wakarihoo an yujahidoo biamwalihim waanfusihim fee sabeeli Allahi waqaloo la tanfiroo fee alharri qul naru jahannama ashaddu harran law kanoo yafqahoona', 1, NOW(), NOW()),
(14, 82, 'فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ', 'অতএব, তারা সামান্য হেসে নিক এবং তারা তাদের কৃতকর্মের বদলাতে অনেক বেশী কাঁদবে।', 'Falyadhakoo qaleelan walyabkoo katheeran jazaan bima kanoo yaksiboona', 1, NOW(), NOW()),
(14, 83, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٖ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُواْ مَعِيَ أَبَدٗا وَلَن تُقَٰتِلُواْ مَعِيَ عَدُوًّاۖ إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ', 'বস্তুতঃ আল্লাহ যদি তোমাকে তাদের মধ্য থেকে কোন শ্রেণীবিশেষের দিকে ফিরিয়ে নিয়ে যান এবং অতঃপর তারা তোমার কাছে অভিযানে বেরোবার অনুমতি কামনা করে, তবে তুমি বলো যে, তোমরা কখনো আমার সাথে বেরোবে না এবং আমার পক্ষ হয়ে কোন শত্রুর সাথে যুদ্ধ করবে না, তোমরা তো প্রথমবারে বসে থাকা পছন্দ করেছ, কাজেই পেছনে পড়ে থাকা লোকদের সাথেই বসে থাক।', 'Fain rajaAAaka Allahu ila taifatin minhum faistathanooka lilkhurooji faqul lan takhrujoo maAAiya abadan walan tuqatiloo maAAiya AAaduwwan innakum radeetum bialquAAoodi awwala marratin faoqAAudoo maAAa alkhalifeena', 1, NOW(), NOW()),
(14, 84, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ', 'আর তাদের মধ্য থেকে কারো মৃত্যু হলে তার উপর কখনও নামায পড়বেন না এবং তার কবরে দাঁড়াবেন না। তারা তো আল্লাহর প্রতি অস্বীকৃতি জ্ঞাপন করেছে এবং রসূলের প্রতিও। বস্তুতঃ তারা না ফরমান অবস্থায় মৃত্যু বরণ করেছে।', 'Wala tusalli AAala ahadin minhum mata abadan wala taqum AAala qabrihi innahum kafaroo biAllahi warasoolihi wamatoo wahum fasiqoona', 1, NOW(), NOW()),
(14, 85, 'وَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ', 'আর বিস্মিত হয়ো না তাদের ধন সম্পদ ও সন্তান-সন্তুতির দরুন। আল্লাহ তো এই চান যে, এ সবের কারণে তাদেরকে আযাবের ভেতরে রাখবেন দুনিয়ায় এবং তাদের প্রাণ নির্গত হওয়া পর্যন্ত যেন তারা কাফেরই থাকে।', 'Wala tuAAjibka amwaluhum waawladuhum innama yureedu Allahu an yuAAaththibahum biha fee alddunya watazhaqa anfusuhum wahum kafiroona', 1, NOW(), NOW()),
(14, 86, 'وَإِذَآ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُواْ بِٱللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُواْ ذَرۡنَا نَكُن مَّعَ ٱلۡقَٰعِدِينَ', 'আর যখন নাযিল হয় কোন সূরা যে, তোমরা ঈমান আন আল্লাহর উপর, তাঁর রসূলের সাথে একাত্ন হয়ে; তখন বিদায় কামনা করে তাদের সামর্থ?476;ান লোকেরা এবং বলে আমাদের অব্যাহতি দিন, যাতে আমরা (নিস্ক্রিয়ভাবে) বসে থাকা লোকদের সাথে থেকে যেতে পারি।', 'Waitha onzilat sooratun an aminoo biAllahi wajahidoo maAAa rasoolihi istathanaka oloo alttawli minhum waqaloo tharna nakun maAAa alqaAAideena', 1, NOW(), NOW()),
(14, 87, 'رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ', 'তারা পেছনে পড়ে থাকা লোকদের সাথে থেকে যেতে পেরে আনন্দিত হয়েছে এবং মোহর এঁটে দেয়া হয়েছে তাদের অন্তরসমূহের উপর। বস্তুতঃ তারা বোঝে না।', 'Radoo bian yakoonoo maAAa alkhawalifi watubiAAa AAala quloobihim fahum la yafqahoona', 1, NOW(), NOW()),
(14, 88, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُوْلَـٰٓئِكَ لَهُمُ ٱلۡخَيۡرَٰتُۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'কিন্তু রসূল এবং সেসব লোক যারা ঈমান এনেছে, তাঁর সাথে তারা যুদ্ধ করেছে নিজেদের জান ও মালের দ্বারা। তাদেরই জন্য নির্ধারিত রয়েছে কল্যাণসমূহ এবং তারাই মুক্তির লক্ষ্যে উপনীত হয়েছে।', 'Lakini alrrasoolu waallatheena amanoo maAAahu jahadoo biamwalihim waanfusihim waolaika lahumu alkhayratu waolaika humu almuflihoona', 1, NOW(), NOW()),
(14, 89, 'أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'আল্লাহ তাদের জন্য তৈরী করে রেখেছেন কানন-কুঞ্জ, যার তলদেশে প্রবাহিত রয়েছে প্রস্রবণ। তারা তাতে বাস করবে অনন্তকাল। এটাই হল বিরাট কৃতকার্যতা।', 'aAAadda Allahu lahum jannatin tajree min tahtiha alanharu khalideena feeha thalika alfawzu alAAatheemu', 1, NOW(), NOW()),
(14, 90, 'وَجَآءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ ٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ', 'আর ছলনাকারী বেদুঈন লোকেরা এলো, যাতে তাদের অব্যাহতি লাভ হতে পারে এবং নিবৃত্ত থাকতে পারে তাদেরই যারা আল্লাহ ও রসূলের সাথে মিথ্যা বলে ছিল। এবার তাদের উপর শীগ্রই আসবে বেদনাদায়ক আযাব যারা কাফের।', 'Wajaa almuAAaththiroona mina alaAArabi liyuthana lahum waqaAAada allatheena kathaboo Allaha warasoolahu sayuseebu allatheena kafaroo minhum AAathabun aleemun', 1, NOW(), NOW()),
(14, 91, 'لَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ', 'দূর্বল, রুগ্ন, ব্যয়ভার বহনে অসমর্থ লোকদের জন্য কোন অপরাধ নেই, যখন তারা মনের দিক থেকে পবিত্র হবে আল্লাহ ও রসূলের সাথে। নেককারদের উপর অভিযোগের কোন পথ নেই। আর আল্লাহ হচ্ছেন ক্ষমাকারী দয়ালু।', 'Laysa AAala aldduAAafai wala AAala almarda wala AAala allatheena la yajidoona ma yunfiqoona harajun itha nasahoo lillahi warasoolihi ma AAala almuhsineena min sabeelin waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(14, 92, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ', 'আর না আছে তাদের উপর যারা এসেছে তোমার নিকট যেন তুমি তাদের বাহন দান কর এবং তুমি বলেছ, আমার কাছে এমন কোন বস্তু নেই যে, তার উপর তোমাদের সওয়ার করাব তখন তারা ফিরে গেছে অথচ তখন তাদের চোখ দিয়ে অশ্রু বইতেছিল এ দুঃখে যে, তারা এমন কোন বস্তু পাচ্ছে না যা ব্যয় করবে।', 'Wala AAala allatheena itha ma atawka litahmilahum qulta la ajidu ma ahmilukum AAalayhi tawallaw waaAAyunuhum tafeedu mina alddamAAi hazanan alla yajidoo ma yunfiqoona', 1, NOW(), NOW()),
(14, 93, '۞إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ', 'অভিযোগের পথ তো তাদের ব্যাপারে রয়েছে, যারা তোমার নিকট অব্যাহতি কামনা করে অথচ তারা সম্পদশালী। যারা পেছনে পড়ে থাকা লোকদের সাথে থাকতে পেরে আনন্দিত হয়েছে। আর আল্লাহ মোহর এঁটে দিয়েছেন তাদের অন্তরসমূহে। বস্তুতঃ তারা জানতেও পারেনি।', 'Innama alssabeelu AAala allatheena yastathinoonaka wahum aghniyao radoo bian yakoonoo maAAa alkhawalifi watabaAAa Allahu AAala quloobihim fahum la yaAAlamoona', 1, NOW(), NOW()),
(14, 94, 'يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡۚ قُل لَّا تَعۡتَذِرُواْ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', 'তুমি যখন তাদের কাছে ফিরে আসবে, তখন তারা তোমাদের নিকট ছল-ছুতা নিয়ে উপস্থিত হবে; তুমি বলো, ছল কারো না, আমি কখনো তোমাদের কথা শুনব না; আমাকে আল্লাহ তা’আলা তোমাদের অবস্থা সম্পর্কে অবহিত করে দিয়েছেন। আর এখন তোমাদের কর্ম আল্লাহই দেখবেন এবং তাঁর রসূল। তারপর তোমরা প্রত্যাবর্তিত হবে সেই গোপন ও আগোপন বিষয়ে অবগত সত্তার নিকট। তিনিই তোমাদের বাতলে দেবেন যা তোমরা করছিলে।', 'YaAAtathiroona ilaykum itha rajaAAtum ilayhim qul la taAAtathiroo lan numina lakum qad nabbaana Allahu min akhbarikum wasayara Allahu AAamalakum warasooluhu thumma turaddoona ila AAalimi alghaybi waalshshahadati fayunabbiokum bima kuntum taAAmaloona', 1, NOW(), NOW()),
(14, 95, 'سَيَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَيۡهِمۡ لِتُعۡرِضُواْ عَنۡهُمۡۖ فَأَعۡرِضُواْ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسٞۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ', 'এখন তারা তোমার সামনে আল্লাহর কসম খাবে, যখন তুমি তাদের কাছে ফিরে যাবে, যেন তুমি তাদের ক্ষমা করে দাও। সুতরাং তুমি তাদের ক্ষমা কর-নিঃসন্দেহে এরা অপবিত্র এবং তাদের কৃতকর্মের বদলা হিসাবে তাদের ঠিকানা হলো দোযখ।', 'Sayahlifoona biAllahi lakum itha inqalabtum ilayhim lituAAridoo AAanhum faaAAridoo AAanhum innahum rijsun wamawahum jahannamu jazaan bima kanoo yaksiboona', 1, NOW(), NOW()),
(14, 96, 'يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ', 'তারা তোমার সামনে কসম খাবে যাতে তুমি তাদের প্রতি রাযী হয়ে যাও। অতএব, তুমি যদি রাযী হয়ে যাও তাদের প্রতি তবু আল্লাহ তা’আলা রাযী হবেন না, এ নাফরমান লোকদের প্রতি।', 'Yahlifoona lakum litardaw AAanhum fain tardaw AAanhum fainna Allaha la yarda AAani alqawmi alfasiqeena', 1, NOW(), NOW()),
(14, 97, 'ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'বেদুইনরা কুফর ও মোনাফেকীতে অত্যন্ত কঠোর হয়ে থাকে এবং এরা সেসব নীতি-কানুন না শেখারই যোগ্য যা আল্লাহ তা’আলা তাঁর রসূলের উপর নাযিল করেছেন। বস্তুতঃ আল্লাহ সব কিছুই জানেন এবং তিনি অত্যন্ত কুশলী।', 'AlaAArabu ashaddu kufran wanifaqan waajdaru alla yaAAlamoo hudooda ma anzala Allahu AAala rasoolihi waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 98, 'وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ', 'আবার কোন কোন বেদুইন এমন ও রয়েছে যারা নিজেদের ব্যয় করাকে জরিমানা। বলে গন্য করে এবং তোমার উপর কোন দুর্দিন আসে কিনা সে অপেক্ষায় থাকে। তাদেরই উপর দুর্দিন আসুক। আর আল্লাহ হচ্ছেন শ্রবণকারী, পরিজ্ঞাত।', 'Wamina alaAArabi man yattakhithu ma yunfiqu maghraman wayatarabbasu bikumu alddawaira AAalayhim dairatu alssawi waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(14, 99, 'وَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ أَلَآ إِنَّهَا قُرۡبَةٞ لَّهُمۡۚ سَيُدۡخِلُهُمُ ٱللَّهُ فِي رَحۡمَتِهِۦٓۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'আর কোন কোন বেদুইন হল তারা, যারা ঈমান আনে আল্লাহর উপর, কেয়ামত দিনের উপর এবং নিজেদের ব্যয়কে আল্লাহর নৈকট্য এবং রসূলের দোয়া লাভের উপায় বলে গণ্য করে। জেনো! তাই হল তাদের ক্ষেত্রে নৈকট্য। আল্লাহ তাদেরকে নিজের রহমতের অন্তর্ভূক্ত করবেন। নিশ্চয়ই আল্লাহ ক্ষমাশীল, করুনাময়।', 'Wamina alaAArabi man yuminu biAllahi waalyawmi alakhiri wayattakhithu ma yunfiqu qurubatin AAinda Allahi wasalawati alrrasooli ala innaha qurbatun lahum sayudkhiluhumu Allahu fee rahmatihi inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(14, 100, 'وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'আর যারা সর্বপ্রথম হিজরতকারী ও আনছারদের মাঝে পুরাতন, এবং যারা তাদের অনুসরণ করেছে, আল্লাহ সে সমস্ত লোকদের প্রতি সন্তুষ্ট হয়েছেন এবং তারাও তাঁর প্রতি সন্তুষ্ট হয়েছে। আর তাদের জন্য প্রস্তুত রেখেছেন কানন-কুঞ্জ, যার তলদেশ দিয়ে প্রবাহিত প্রস্রবণসমূহ। সেখানে তারা থাকবে চিরকাল। এটাই হল মহান কৃতকার্যতা।', 'Waalssabiqoona alawwaloona mina almuhajireena waalansari waallatheena ittabaAAoohum biihsanin radiya Allahu AAanhum waradoo AAanhu waaAAadda lahum jannatin tajree tahtaha alanharu khalideena feeha abadan thalika alfawzu alAAatheemu', 1, NOW(), NOW()),
(14, 101, 'وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ', 'আর কিছু কিছু তোমার আশ-পাশের মুনাফেক এবং কিছু লোক মদীনাবাসী কঠোর মুনাফেকীতে অনঢ়। তুমি তাদের জান না; আমি তাদের জানি। আমি তাদেরকে আযাব দান করব দু’বার, তারপর তাদেরকে নিয়ে যাওয়া হবে মহান আযাবের দিকে।', 'Wamimman hawlakum mina alaAArabi munafiqoona wamin ahli almadeenati maradoo AAala alnnifaqi la taAAlamuhum nahnu naAAlamuhum sanuAAaththibuhum marratayni thumma yuraddoona ila AAathabin AAatheemin', 1, NOW(), NOW()),
(14, 102, 'وَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ', 'আর কোন কোন লোক রয়েছে যারা নিজেদের পাপ স্বীকার করেছে, তারা মিশ্রিত করেছে একটি নেককাজ ও অন্য একটি বদকাজ। শীঘ্রই আল্লাহ হয়ত তাদেরকে ক্ষমা করে দেবেন। নিঃঃসন্দেহে আল্লাহ ক্ষমাশীল করুণাময়।', 'Waakharoona iAAtarafoo bithunoobihim khalatoo AAamalan salihan waakhara sayyian AAasa Allahu an yatooba AAalayhim inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(14, 103, 'خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'তাদের মালামাল থেকে যাকাত গ্রহণ কর যাতে তুমি সেগুলোকে পবিত্র করতে এবং সেগুলোকে বরকতময় করতে পার এর মাধ্যমে। আর তুমি তাদের জন্য দোয়া কর, নিঃসন্দেহে তোমার দোয়া তাদের জন্য সান্ত্বনা স্বরূপ। বস্তুতঃ আল্লাহ সবকিছুই শোনেন, জানেন।', 'Khuth min amwalihim sadaqatan tutahhiruhum watuzakkeehim biha wasalli AAalayhim inna salataka sakanun lahum waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(14, 104, 'أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ هُوَ يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَأۡخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'তারা কি একথা জানতে পারেনি যে, আল্লাহ নিজেই স্বীয় বান্দাদের তওবা কবুল করেন এবং যাকাত গ্রহণ করেন? বস্তুতঃ আল্লাহই তওবা কবুলকারী, করুণাময়।', 'Alam yaAAlamoo anna Allaha huwa yaqbalu alttawbata AAan AAibadihi wayakhuthu alssadaqati waanna Allaha huwa alttawwabu alrraheemu', 1, NOW(), NOW()),
(14, 105, 'وَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', 'আর তুমি বলে দাও, তোমরা আমল করে যাও, তার পরবর্তীতে আল্লাহ দেখবেন তোমাদের কাজ এবং দেখবেন রসূল ও মুসলমানগণ। তাছাড়া তোমরা শীগ্রই প্রত্যাবর্তিত হবে তাঁর সান্নিধ্যে যিনি গোপন ও প্রকাশ্য বিষয়ে অবগত। তারপর তিনি জানিয়ে দেবেন তোমাদেরকে যা করতে।', 'Waquli iAAmaloo fasayara Allahu AAamalakum warasooluhu waalmuminoona wasaturaddoona ila AAalimi alghaybi waalshshahadati fayunabbiokum bima kuntum taAAmaloona', 1, NOW(), NOW()),
(14, 106, 'وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمۡ وَإِمَّا يَتُوبُ عَلَيۡهِمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'আবার অনেক লোক রয়েছে যাদের কাজকর্ম আল্লাহর নির্দেশের উপর স্থগিত রয়েছে; তিনি হয় তাদের আযাব দেবেন না হয় তাদের ক্ষমা করে দেবেন। বস্তুতঃ আল্লাহ সব কিছুই জ্ঞাত, বিজ্ঞতাসম্পন্ন।', 'Waakharoona murjawna liamri Allahi imma yuAAaththibuhum waimma yatoobu AAalayhim waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 107, 'وَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ', 'আর যারা নির্মাণ করেছে মসজিদ জিদের বশে এবং কুফরীর তাড়নায় মুমিনদের মধ্যে বিভেদ সৃস্টির উদ্দেশ্যে এবং ঐ লোকের জন্য ঘাটি স্বরূপ যে পূর্ব থেকে আল্লাহ ও তাঁর রসূলের সাথে যুদ্ধ করে আসছে, আর তারা অবশ্যই শপথ করবে যে, আমরা কেবল কল্যাণই চেয়েছি। পক্ষান্তরে আল্লাহ সাক্ষী যে, তারা সবাই মিথ্যুক।', 'Waallatheena ittakhathoo masjidan diraran wakufran watafreeqan bayna almumineena wairsadan liman haraba Allaha warasoolahu min qablu walayahlifunna in aradna illa alhusna waAllahu yashhadu innahum lakathiboona', 1, NOW(), NOW()),
(14, 108, 'لَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ فِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ', 'তুমি কখনো সেখানে দাড়াবে না, তবে যে মসজিদের ভিত্তি রাখা হয়েছে তাকওয়ার উপর প্রথম দিন থেকে, সেটিই তোমার দাঁড়াবার যোগ্য স্থান। সেখানে রয়েছে এমন লোক, যারা পবিত্রতাকে ভালবাসে। আর আল্লাহ পবিত্র লোকদের ভালবাসেন।', 'La taqum feehi abadan lamasjidun ossisa AAala alttaqwa min awwali yawmin ahaqqu an taqooma feehi feehi rijalun yuhibboona an yatatahharoo waAllahu yuhibbu almuttahhireena', 1, NOW(), NOW()),
(14, 109, 'أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'যে ব্যাক্তি স্বীয় গৃহের ভিত্তি রেখেছে কোন গর্তের কিনারায় যা ধ্বসে পড়ার নিকটবর্তী এবং অতঃপর তা ওকে নিয়ে দোযখের আগুনে পতিত হয়। আর আল্লাহ জালেমদের পথ দেখান না।', 'Afaman assasa bunyanahu AAala taqwa mina Allahi waridwanin khayrun am man assasa bunyanahu AAala shafa jurufin harin fainhara bihi fee nari jahannama waAllahu la yahdee alqawma alththalimeena', 1, NOW(), NOW()),
(14, 110, 'لَا يَزَالُ بُنۡيَٰنُهُمُ ٱلَّذِي بَنَوۡاْ رِيبَةٗ فِي قُلُوبِهِمۡ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'তাদের নির্মিত গৃহটি তাদের অন্তরে সদা সন্দেহের উদ্রেক করে যাবে যে পর্যন্ত না তাদের অন্তরগুলো চৌচির হয়ে যায়। আর আল্লাহ সর্বজ্ঞ প্রজ্ঞাময়।', 'La yazalu bunyanuhumu allathee banaw reebatan fee quloobihim illa an taqattaAAa quloobuhum waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(14, 111, '۞إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'আল্লাহ ক্রয় করে নিয়েছেন মুসলমানদের থেকে তাদের জান ও মাল এই মূল্যে যে, তাদের জন্য রয়েছে জান্নাত। তারা যুদ্ধ করে আল্লাহর রাহেঃ অতঃপর মারে ও মরে। তওরাত, ইঞ্জিল ও কোরআনে তিনি এ সত্য প্রতিশ্রুতিতে অবিচল। আর আল্লাহর চেয়ে প্রতিশ্রুতি রক্ষায় কে অধিক? সুতরাং তোমরা আনন্দিত হও সে লেন-দেনের উপর, যা তোমরা করছ তাঁর সাথে। আর এ হল মহান সাফল্য।', 'Inna Allaha ishtara mina almumineena anfusahum waamwalahum bianna lahumu aljannata yuqatiloona fee sabeeli Allahi fayaqtuloona wayuqtaloona waAAdan AAalayhi haqqan fee alttawrati waalinjeeli waalqurani waman awfa biAAahdihi mina Allahi faistabshiroo bibayAAikumu allathee bayaAAtum bihi wathalika huwa alfawzu alAAatheemu', 1, NOW(), NOW()),
(14, 112, 'ٱلتَّـٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّـٰٓئِحُونَ ٱلرَّـٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ', 'তারা তওবাকারী, এবাদতকারী, শোকরগোযার, (দুনিয়ার সাথে) সম্পর্কচ্ছেদকারী, রুকু ও সিজদা আদায়কারী, সৎকাজের আদেশ দানকারী ও মন্দ কাজ থেকে নিবৃতকারী এবং আল্লাহর দেওয়া সীমাসমূহের হেফাযতকারী। বস্তুতঃ সুসংবাদ দাও ঈমানদারদেরকে।', 'Alttaiboona alAAabidoona alhamidoona alssaihoona alrrakiAAoona alssajidoona alamiroona bialmaAAroofi waalnnahoona AAani almunkari waalhafithoona lihudoodi Allahi wabashshiri almumineena', 1, NOW(), NOW()),
(14, 113, 'مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ', 'নবী ও মুমিনের উচিত নয় মুশরেকদের মাগফেরাত কামনা করে, যদিও তারা আত্নীয় হোক একথা সুস্পষ্ট হওয়ার পর যে তারা দোযখী।', 'Ma kana lilnnabiyyi waallatheena amanoo an yastaghfiroo lilmushrikeena walaw kanoo olee qurba min baAAdi ma tabayyana lahum annahum ashabu aljaheemi', 1, NOW(), NOW()),
(14, 114, 'وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةٖ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوّٞ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّـٰهٌ حَلِيمٞ', 'আর ইব্রাহীম কর্তৃক স্বীয় পিতার মাগফেরাত কামনা ছিল কেবল সেই প্রতিশ্রুতির কারণে, যা তিনি তার সাথে করেছিলেন। অতঃপর যখন তাঁর কাছে একথা প্রকাশ পেল যে, সে আল্লাহর শত্রু তখন তার সাথে সম্পর্ক ছিন্ন করে নিলেন। নিঃসন্দেহে ইব্রাহীম ছিলেন বড় কোমল হৃদয়, সহনশীল।', 'Wama kana istighfaru ibraheema liabeehi illa AAan mawAAidatin waAAadaha iyyahu falamma tabayyana lahu annahu AAaduwwun lillahi tabarraa minhu inna ibraheema laawwahun haleemun', 1, NOW(), NOW()),
(14, 115, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ', 'আর আল্লাহ কোন জাতিকে হেদায়েত করার পর পথভ্রষ্ট করেন না যতক্ষণ না তাদের জন্য পরিষ্কারভাবে বলে দেন সেসব বিষয় যা থেকে তাদের বেঁচে থাকা দরকার। নিঃসন্দেহে আল্লাহ সব বিষয়ে ওয়াকেফহাল।', 'Wama kana Allahu liyudilla qawman baAAda ith hadahum hatta yubayyina lahum ma yattaqoona inna Allaha bikulli shayin AAaleemun', 1, NOW(), NOW()),
(14, 116, 'إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يُحۡيِۦ وَيُمِيتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ', 'নিশ্চয় আল্লাহরই জন্য আসমানসমূহ ও যমীনের সাম্রাজ্য। তিনিই জিন্দা করেন ও মৃত্যু ঘটান, আর আল্লাহ ব্যতীত তোমাদের জন্য কোন সহায়ও নেই, কোন সাহায্যকারীও নেই।', 'Inna Allaha lahu mulku alssamawati waalardi yuhyee wayumeetu wama lakum min dooni Allahi min waliyyin wala naseerin', 1, NOW(), NOW()),
(14, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ', 'আল্লাহ দয়াশীল নবীর প্রতি এবং মুহাজির ও আনসারদের প্রতি, যারা কঠিন মহূর্তে নবীর সঙ্গে ছিল, যখন তাদের এক দলের অন্তর ফিরে যাওয়ার উপক্রম হয়েছিল। অতঃপর তিনি দয়াপরবশ হন তাদের প্রতি। নিঃসন্দেহে তিনি তাদের প্রতি দয়াশীল ও করুনাময়।', 'Laqad taba Allahu AAala alnnabiyyi waalmuhajireena waalansari allatheena ittabaAAoohu fee saAAati alAAusrati min baAAdi ma kada yazeeghu quloobu fareeqin minhum thumma taba AAalayhim innahu bihim raoofun raheemun', 1, NOW(), NOW()),
(14, 118, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'এবং অপর তিনজনকে যাদেরকে পেছনে রাখা হয়েছিল, যখন পৃথিবী বিস্তৃত হওয়া সত্বেও তাদের জন্য সঙ্কুচিত হয়ে গেল এবং তাদের জীবন দূর্বিসহ হয়ে উঠলো; আর তারা বুঝতে পারলো যে, আল্লাহ ব্যতীত আর কোন আশ্রয়স্থল নেই-অতঃপর তিনি সদয় হলেন তাদের প্রতি যাতে তারা ফিরে আসে। নিঃসন্দেহে আল্লাহ দয়াময় করুণাশীল।', 'WaAAala alththalathati allatheena khullifoo hatta itha daqat AAalayhimu alardu bima rahubat wadaqat AAalayhim anfusuhum wathannoo an la maljaa mina Allahi illa ilayhi thumma taba AAalayhim liyatooboo inna Allaha huwa alttawwabu alrraheemu', 1, NOW(), NOW()),
(14, 119, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّـٰدِقِينَ', 'হে ঈমানদারগণ, আল্লাহকে ভয় কর এবং সত্যবাদীদের সাথে থাক।', 'Ya ayyuha allatheena amanoo ittaqoo Allaha wakoonoo maAAa alssadiqeena', 1, NOW(), NOW()),
(14, 120, 'مَا كَانَ لِأَهۡلِ ٱلۡمَدِينَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن يَتَخَلَّفُواْ عَن رَّسُولِ ٱللَّهِ وَلَا يَرۡغَبُواْ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ', 'মদীনাবাসী ও পাশ্ববর্তী পল্লীবাসীদের উচিত নয় রসূলুল্লাহর সঙ্গ ত্যাগ করে পেছনে থেকে যাওয়া এবং রসূলের প্রাণ থেকে নিজেদের প্রাণকে অধিক প্রিয় মনে করা। এটি এজন্য যে, আল্লাহর পথে যে তৃষ্ণা, ক্লান্তি ও ক্ষুধা তাদের স্পর্শ করে এবং তাদের এমন পদক্ষেপ যা কাফেরদের মনে ক্রোধের কারণ হয় আর শত্রুদের পক্ষ থেকে তারা যা কিছু প্রাপ্ত হয়-তার প্রত্যেকটির পরিবর্তে তাদের জন্য লিখিত হয়ে নেক আমল। নিঃসন্দেহে আল্লাহ সৎকর্মশীল লোকদের হক নষ্ট করেন না।', 'Ma kana liahli almadeenati waman hawlahum mina alaAArabi an yatakhallafoo AAan rasooli Allahi wala yarghaboo bianfusihim AAan nafsihi thalika biannahum la yuseebuhum thamaon wala nasabun wala makhmasatun fee sabeeli Allahi wala yataoona mawtian yagheethu alkuffara wala yanaloona min AAaduwwin naylan illa kutiba lahum bihi AAamalun salihun inna Allaha la yudeeAAu ajra almuhsineena', 1, NOW(), NOW()),
(14, 121, 'وَلَا يُنفِقُونَ نَفَقَةٗ صَغِيرَةٗ وَلَا كَبِيرَةٗ وَلَا يَقۡطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُواْ يَعۡمَلُونَ', 'আর তারা অল্প-বিস্তর যা কিছু ব্যয় করে, যত প্রান্তর তারা অতিক্রম করে, তা সবই তাদের নামে লেখা হয়, যেন আল্লাহ তাদের কৃতকর্মসমূহের উত্তম বিনিময় প্রদান করেন।', 'Wala yunfiqoona nafaqatan sagheeratan wala kabeeratan wala yaqtaAAoona wadiyan illa kutiba lahum liyajziyahumu Allahu ahsana ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(14, 122, '۞وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ', 'আর সমস্ত মুমিনের অভিযানে বের হওয়া সঙ্গত নয়। তাই তাদের প্রত্যেক দলের একটি অংশ কেন বের হলো না, যাতে দ্বীনের জ্ঞান লাভ করে এবং সংবাদ দান করে স্বজাতিকে, যখন তারা তাদের কাছে প্রত্যাবর্তন করবে, যেন তারা বাঁচতে পারে।', 'Wama kana almuminoona liyanfiroo kaffatan falawla nafara min kulli firqatin minhum taifatun liyatafaqqahoo fee alddeeni waliyunthiroo qawmahum itha rajaAAoo ilayhim laAAallahum yahtharoona', 1, NOW(), NOW()),
(14, 123, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ', 'হে ঈমানদারগণ, তোমাদের নিকটবর্তী কাফেরদের সাথে যুদ্ধ চালিয়ে যাও এবং তারা তোমাদের মধ্যে কঠোরতা অনুভব করুক আর জেনে রাখ, আল্লাহ মুত্তাকীদের সাথে রয়েছেন।', 'Ya ayyuha allatheena amanoo qatiloo allatheena yaloonakum mina alkuffari walyajidoo feekum ghilthatan waiAAlamoo anna Allaha maAAa almuttaqeena', 1, NOW(), NOW()),
(14, 124, 'وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ', 'আর যখন কোন সূরা অবতীর্ণ হয়, তখন তাদের কেউ কেউ বলে, এ সূরা তোমাদের মধ্যেকার ঈমান কতটা বৃদ্ধি করলো? অতএব যারা ঈমানদার, এ সূরা তাদের ঈমান বৃদ্ধি করেছে এবং তারা আনন্দিত হয়েছে।', 'Waitha ma onzilat sooratun faminhum man yaqoolu ayyukum zadathu hathihi eemanan faamma allatheena amanoo fazadathum eemanan wahum yastabshiroona', 1, NOW(), NOW()),
(14, 125, 'وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ', 'বস্তুতঃ যাদের অন্তরে ব্যাধি রয়েছে এটি তাদের কলুষের সাথে আরো কলুষ বৃদ্ধি করেছে এবং তারা কাফের অবস্থায়ই মৃত্যু বরণ করলো।', 'Waamma allatheena fee quloobihim maradun fazadathum rijsan ila rijsihim wamatoo wahum kafiroona', 1, NOW(), NOW()),
(14, 126, 'أَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ', 'তারা কি লক্ষ্য করে না, প্রতি বছর তারা দু’একবার বিপর্যস্ত হচ্ছে, অথচ, তারা এরপরও তওবা করে না কিংবা উপদেশ গ্রহণ করে না।', 'Awala yarawna annahum yuftanoona fee kulli AAamin marratan aw marratayni thumma la yatooboona wala hum yaththakkaroona', 1, NOW(), NOW()),
(14, 127, 'وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَىٰكُم مِّنۡ أَحَدٖ ثُمَّ ٱنصَرَفُواْۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ', 'আর যখনই কোন সূরা অবতীর্ণ হয়, তখন তারা একে অন্যের দিকে তাকায় যে, কোন মুসলমান তোমাদের দেখছে কি-না-অতঃপর সরে পড়ে। আল্লাহ ওদের অন্তরকে সত্য বিমুখ করে দিয়েছেন! নিশ্চয়ই তারা নির্বোধ সম্প্রদায়।', 'Waitha ma onzilat sooratun nathara baAAduhum ila baAAdin hal yarakum min ahadin thumma insarafoo sarafa Allahu quloobahum biannahum qawmun la yafqahoona', 1, NOW(), NOW()),
(14, 128, 'لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ', 'তোমাদের কাছে এসেছে তোমাদের মধ্য থেকেই একজন রসূল। তোমাদের দুঃখ-কষ্ট তার পক্ষে দুঃসহ। তিনি তোমাদের মঙ্গলকামী, মুমিনদের প্রতি স্নেহশীল, দয়াময়।', 'Laqad jaakum rasoolun min anfusikum AAazeezun AAalayhi ma AAanittum hareesun AAalaykum bialmumineena raoofun raheemun', 1, NOW(), NOW()),
(14, 129, 'فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ', 'এ সত্ত্বেও যদি তারা বিমুখ হয়ে থাকে, তবে বলে দাও, আল্লাহই আমার জন্য যথেষ্ট, তিনি ব্যতীত আর কারো বন্দেগী নেই। আমি তাঁরই ভরসা করি এবং তিনিই মহান আরশের অধিপতি।', 'Fain tawallaw faqul hasbiya Allahu la ilaha illa huwa AAalayhi tawakkaltu wahuwa rabbu alAAarshi alAAatheemi', 1, NOW(), NOW()),
(15, 1, 'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ', 'আলিফ-লাম-র, এগুলো হেকমতপূর্ণ কিতাবের আয়াত।', 'Aliflamra tilka ayatu alkitabi alhakeemi', 1, NOW(), NOW()),
(15, 2, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَيۡنَآ إِلَىٰ رَجُلٖ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓاْ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٞ مُّبِينٌ', 'মানুষের কাছে কি আশ্চর্য লাগছে যে, আমি ওহী পাঠিয়েছি তাদেরই মধ্য থেকে একজনের কাছে যেন তিনি মানুষকে সতর্ক করেন এবং সুসংবাদ শুনিয়ে দেন ঈমনাদারগণকে যে, তাঁদের জন্য সত্য মর্যাদা রয়েছে তাঁদের পালনকর্তার কাছে। কাফেররা বলতে লাগল, নিঃসন্দেহে এ লোক প্রকাশ্য যাদুকর।', 'Akana lilnnasi AAajaban an awhayna ila rajulin minhum an anthiri alnnasa wabashshiri allatheena amanoo anna lahum qadama sidqin AAinda rabbihim qala alkafiroona inna hatha lasahirun mubeenun', 1, NOW(), NOW()),
(15, 3, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ', 'নিশ্চয়ই তোমাদের পালনকর্তা আল্লাহ যিনি তৈরী করেছেন আসমান ও যমীনকে ছয় দিনে, অতঃপর তিনি আরশের উপর অধিষ্ঠিত হয়েছেন। তিনি কার্য পরিচালনা করেন। কেউ সুপারিশ করতে পাবে না তবে তাঁর অনুমতি ছাড়া ইনিই আল্লাহ তোমাদের পালনকর্তা। অতএব, তোমরা তাঁরই এবাদত কর। তোমরা কি কিছুই চিন্তা কর না', 'Inna rabbakumu Allahu allathee khalaqa alssamawati waalarda fee sittati ayyamin thumma istawa AAala alAAarshi yudabbiru alamra ma min shafeeAAin illa min baAAdi ithnihi thalikumu Allahu rabbukum faoAAbudoohu afala tathakkaroona', 1, NOW(), NOW()),
(15, 4, 'إِلَيۡهِ مَرۡجِعُكُمۡ جَمِيعٗاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ', 'তাঁর কাছেই ফিরে যেতে হবে তোমাদের সবাইকে, আল্লাহর ওয়াদা সত্য, তিনিই সৃষ্টি করেন প্রথমবার আবার পুনর্বার তৈরী করবেন তাদেরকে বদলা দেয়ার জন্য যারা ঈমান এনেছে এবং নেক কাজ করেছে ইনসাফের সাথে। আর যারা কাফের হয়েছে, তাদের পান করতে হবে ফুটন্ত পানি এবং ভোগ করতে হবে যন্ত্রনাদায়ক আযাব এ জন্যে যে, তারা কুফরী করছিল।', 'Ilayhi marjiAAukum jameeAAan waAAda Allahi haqqan innahu yabdao alkhalqa thumma yuAAeeduhu liyajziya allatheena amanoo waAAamiloo alssalihati bialqisti waallatheena kafaroo lahum sharabun min hameemin waAAathabun aleemun bima kanoo yakfuroona', 1, NOW(), NOW()),
(15, 5, 'هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ', 'তিনিই সে মহান সত্তা, যিনি বানিয়েছেন সুর্যকে উজ্জল আলোকময়, আর চন্দ্রকে স্নিগ্ধ আলো বিতরণকারীরূপে এবং অতঃপর নির্ধারিত করেছেন এর জন্য মনযিল সমূহ, যাতে করে তোমরা চিনতে পার বছরগুলোর সংখ্যা ও হিসাব। আল্লাহ এই সমস্ত কিছু এমনিতেই সৃষ্টি করেননি, কিন্তু যথার্থতার সাথে। তিনি প্রকাশ করেন লক্ষণসমূহ সে সমস্ত লোকের জন্য যাদের জ্ঞান আছে।', 'Huwa allathee jaAAala alshshamsa diyaan waalqamara nooran waqaddarahu manazila litaAAlamoo AAadada alssineena waalhisaba ma khalaqa Allahu thalika illa bialhaqqi yufassilu alayati liqawmin yaAAlamoona', 1, NOW(), NOW()),
(15, 6, 'إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ', 'নিশ্চয়ই রাত-দিনের পরিবর্তনের মাঝে এবং যা কিছু তিনি সৃষ্টি করেছেন আসমান ও যমীনে, সবই হল নিদর্শন সেসব লোকের জন্য যারা ভয় করে।', 'Inna fee ikhtilafi allayli waalnnahari wama khalaqa Allahu fee alssamawati waalardi laayatin liqawmin yattaqoona', 1, NOW(), NOW()),
(15, 7, 'إِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ', 'অবশ্যই যেসব লোক আমার সাক্ষাৎ লাভের আশা রাখে না এবং পার্থিব জীবন নিয়েই উৎফুল্ল রয়েছে, তাতেই প্রশান্তি অনুভব করেছে এবং যারা আমার নির্দশনসমূহ সম্পর্কে বেখবর।', 'Inna allatheena la yarjoona liqaana waradoo bialhayati alddunya waitmaannoo biha waallatheena hum AAan ayatina ghafiloona', 1, NOW(), NOW()),
(15, 8, 'أُوْلَـٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ', 'এমন লোকদের ঠিকানা হল আগুন সেসবের বদলা হিসাবে যা তারা অর্জন করছিল।', 'Olaika mawahumu alnnaru bima kanoo yaksiboona', 1, NOW(), NOW()),
(15, 9, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّـٰتِ ٱلنَّعِيمِ', 'অবশ্য যেসব লোক ঈমান এনেছে এবং সৎকাজ করেছে, তাদেরকে হেদায়েত দান করবেন তাদের পালনকর্তা, তাদের ঈমানের মাধ্যমে। এমন সুসময় কানন-কুঞ্জের প্রতি যার তলদেশে প্রবাহিত হয় প্রস্রবণসমূহ।', 'Inna allatheena amanoo waAAamiloo alssalihati yahdeehim rabbuhum bieemanihim tajree min tahtihimu alanharu fee jannati alnnaAAeemi', 1, NOW(), NOW()),
(15, 10, 'دَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ', 'সেখানে তাদের প্রার্থনা হল ‘পবিত্র তোমার সত্তা হে আল্লাহ’। আর শুভেচ্ছা হল সালাম আর তাদের প্রার্থনার সমাপ্তি হয়, ‘সমস্ত প্রশংসা বিশ্বপালক আল্লাহর জন্য’ বলে।', 'DaAAwahum feeha subhanaka allahumma watahiyyatuhum feeha salamun waakhiru daAAwahum ani alhamdu lillahi rabbi alAAalameena', 1, NOW(), NOW()),
(15, 11, '۞وَلَوۡ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَيۡرِ لَقُضِيَ إِلَيۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', 'আর যদি আল্লাহ তা’আলা মানুষকে যথাশীঘ্র অকল্যাণ পৌঁছে দেন যতশীঘ্র তার কামনা করে, তাহলে তাদের আশাই শেষ করে দিতে হত। সুতরাং যাদের মনে আমার সাক্ষাতের আশা নেই, আমি তাদেরকে তাদের দুষ্টুমিতে ব্যতিব্যস্ত ছেড়ে দিয়ে রাখি।', 'Walaw yuAAajjilu Allahu lilnnasi alshsharra istiAAjalahum bialkhayri laqudiya ilayhim ajaluhum fanatharu allatheena la yarjoona liqaana fee tughyanihim yaAAmahoona', 1, NOW(), NOW()),
(15, 12, 'وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ كَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ', 'আর যখন মানুষ কষ্টের সম্মুখীন হয়, শুয়ে বসে, দাঁড়িয়ে আমাকে ডাকতে থাকে। তারপর আমি যখন তা থেকে মুক্ত করে দেই, সে কষ্ট যখন চলে যায় তখন মনে হয় কখনো কোন কষ্টেরই সম্মুখীন হয়ে যেন আমাকে ডাকেইনি। এমনিভাবে মনঃপুত হয়েছে নির্ভয় লোকদের যা তারা করেছে।', 'Waitha massa alinsana alddurru daAAana lijanbihi aw qaAAidan aw qaiman falamma kashafna AAanhu durrahu marra kaan lam yadAAuna ila durrin massahu kathalika zuyyina lilmusrifeena ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(15, 13, 'وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُواْ وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ وَمَا كَانُواْ لِيُؤۡمِنُواْۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ', 'অবশ্য তোমাদের পূর্বে বহু দলকে ধ্বংস করে দিয়েছি, তখন তারা জালেম হয়ে গেছে। অথচ রসূল তাদের কাছেও এসব বিষয়ের প্রকৃষ্ট নির্দেশ নিয়ে এসেছিলেন। কিন্তু কিছুতেই তারা ঈমান আনল না। এমনিভাবে আমি শাস্তি দিয়ে থাকি পাপি সম্প্রদায়কে।', 'Walaqad ahlakna alquroona min qablikum lamma thalamoo wajaathum rusuluhum bialbayyinati wama kanoo liyuminoo kathalika najzee alqawma almujrimeena', 1, NOW(), NOW()),
(15, 14, 'ثُمَّ جَعَلۡنَٰكُمۡ خَلَـٰٓئِفَ فِي ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَيۡفَ تَعۡمَلُونَ', 'অতঃপর আমি তোমাদেরকে যমীনে তাদের পর প্রতিনিধি বানিয়েছি যাতে দেখতে পারি তোমরা কি কর।', 'Thumma jaAAalnakum khalaifa fee alardi min baAAdihim linanthura kayfa taAAmaloona', 1, NOW(), NOW()),
(15, 15, 'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ', 'আর যখন তাদের কাছে আমার প্রকৃষ্ট আয়াত সমূহ পাঠ করা হয়, তখন সে সমস্ত লোক বলে, যাদের আশা নেই আমার সাক্ষাতের, নিয়ে এসো কোন কোরআন এটি ছাড়া, অথবা একে পরিবর্তিত করে দাও। তাহলে বলে দাও, একে নিজের পক্ষ থেকে পরিবর্তিত করা আমার কাজ নয়। আমি সে নির্দেশেরই আনুগত্য করি, যা আমার কাছে আসে। আমি যদি স্বীয় পরওয়ারদেগারের নাফরমানী করি, তবে কঠিন দিবসের আযাবের ভয় করি।', 'Waitha tutla AAalayhim ayatuna bayyinatin qala allatheena la yarjoona liqaana iti biquranin ghayri hatha aw baddilhu qul ma yakoonu lee an obaddilahu min tilqai nafsee in attabiAAu illa ma yooha ilayya innee akhafu in AAasaytu rabbee AAathaba yawmin AAatheemin', 1, NOW(), NOW()),
(15, 16, 'قُل لَّوۡ شَآءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَيۡكُمۡ وَلَآ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ أَفَلَا تَعۡقِلُونَ', 'বলে দাও, যদি আল্লাহ চাইতেন, তবে আমি এটি তোমাদের সামনে পড়তাম না, আর নাইবা তিনি তোমাদেরেকে অবহিত করতেন এ সম্পর্কে। কারণ আমি তোমাদের মাঝে ইতিপূর্বেও একটা বয়স অতিবাহিত করেছি। তারপরেও কি তোমরা চিন্তা করবে না', 'Qul law shaa Allahu ma talawtuhu AAalaykum wala adrakum bihi faqad labithtu feekum AAumuran min qablihi afala taAAqiloona', 1, NOW(), NOW()),
(15, 17, 'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡمُجۡرِمُونَ', 'অতঃপর তার চেয়ে বড় জালেম, কে হবে, যে আল্লাহর প্রতি অপবাদ আরোপ করেছে কিংবা তাঁর আয়াতসমূহকে মিথ্যা বলে অভিহিত করছে? কস্মিনকালেও পাপীদের কোন কল্যাণ হয় না।', 'Faman athlamu mimmani iftara AAala Allahi kathiban aw kaththaba biayatihi innahu la yuflihu almujrimoona', 1, NOW(), NOW()),
(15, 18, 'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَـٰٓؤُلَآءِ شُفَعَـٰٓؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعۡلَمُ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', 'আর উপাসনা করে আল্লাহকে বাদ দিয়ে এমন বস্তুর, যা না তাদের কোন ক্ষতিসাধন করতে পারে, না লাভ এবং বলে, এরা তো আল্লাহর কাছে আমাদের সুপারিশকারী। তুমি বল, তোমরা কি আল্লাহকে এমন বিষয়ে অবহিত করছ, যে সম্পর্কে তিনি অবহিত নন আসমান ও যমীনের মাঝে ? তিনি পুতঃপবিত্র ও মহান সে সমস্ত থেকে যাকে তোমরা শরীক করছ।', 'WayaAAbudoona min dooni Allahi ma la yadurruhum wala yanfaAAuhum wayaqooloona haolai shufaAAaona AAinda Allahi qul atunabbioona Allaha bima la yaAAlamu fee alssamawati wala fee alardi subhanahu wataAAala AAamma yushrikoona', 1, NOW(), NOW()),
(15, 19, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةٗ وَٰحِدَةٗ فَٱخۡتَلَفُواْۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِفُونَ', 'আর সমস্ত মানুষ একই উম্মতভুক্ত ছিল, পরে পৃথক হয়ে গেছে। আর একটি কথা যদি তোমার পরওয়ারদেগারের পক্ষ থেকে পূর্ব নির্ধারিত না হয়ে যেত; তবে তারা যে বিষয়ে বিরোধ করছে তার মীমাংসা হয়ে যেত।', 'Wama kana alnnasu illa ommatan wahidatan faikhtalafoo walawla kalimatun sabaqat min rabbika laqudiya baynahum feema feehi yakhtalifoona', 1, NOW(), NOW()),
(15, 20, 'وَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ', 'বস্তুতঃ তারা বলে, তাঁর কাছে তাঁর পরওয়ারদেগারের পক্ষ থেকে কোন নির্দেশ এল না কেন? বলে দাও গায়েবের কথা আল্লাহই জানেন। আমি ও তোমাদের সাথে অপেক্ষায় রইলাম।', 'Wayaqooloona lawla onzila AAalayhi ayatun min rabbihi faqul innama alghaybu lillahi faintathiroo innee maAAakum mina almuntathireena', 1, NOW(), NOW()),
(15, 21, 'وَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُرُونَ', 'আর যখন আমি আস্বাদন করাই স্বীয় রহমত সে কষ্টের পর, যা তাদের ভোগ করতে হয়েছিল, তখনই তারা আমার শক্তিমত্তার মাঝে নানা রকম ছলনা তৈরী করতে আরম্ভ করবে। আপনি বলে দিন, আল্লাহ সবচেয়ে দ্রুত কলা-কৌশল তৈরী করতে পারেন। নিশ্চয়ই আমাদের ফেরেশতারা লিখে রাখে তোমাদের ছল-চাতুরী।', 'Waitha athaqna alnnasa rahmatan min baAAdi darraa massathum itha lahum makrun fee ayatina quli Allahu asraAAu makran inna rusulana yaktuboona ma tamkuroona', 1, NOW(), NOW()),
(15, 22, 'هُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ', 'তিনিই তোমাদের ভ্রমন করান স্থলে ও সাগরে। এমনকি যখন তোমরা নৌকাসমূহে আরোহণ করলে আর তা লোকজনকে অনুকূল হাওয়ায় বয়ে নিয়ে চলল এবং তাতে তারা আনন্দিত হল, নৌকাগুলোর উপর এল তীব্র বাতাস, আর সর্বদিক থেকে সেগুলোর উপর ঢেউ আসতে লাগল এবং তারা জানতে পারল যে, তারা অবরুদ্ধ হয়ে পড়েছে, তখন ডাকতে লাগল আল্লাহকে তাঁর এবাদতে নিঃস্বার্থ হয়ে যদি তুমি আমাদেরকে এ বিপদ থেকে উদ্ধার করে তোল, তাহলে নিঃসন্দেহে আমরা কৃতজ্ঞ থাকব।', 'Huwa allathee yusayyirukum fee albarri waalbahri hatta itha kuntum fee alfulki wajarayna bihim bireehin tayyibatin wafarihoo biha jaatha reehun AAasifun wajaahumu almawju min kulli makanin wathannoo annahum oheeta bihim daAAawoo Allaha mukhliseena lahu alddeena lain anjaytana min hathihi lanakoonanna mina alshshakireena', 1, NOW(), NOW()),
(15, 23, 'فَلَمَّآ أَنجَىٰهُمۡ إِذَا هُمۡ يَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۗ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغۡيُكُمۡ عَلَىٰٓ أَنفُسِكُمۖ مَّتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ', 'তারপর যখন তাদেরকে আল্লাহ বাঁচিয়ে দিলেন, তখনই তারা পৃথিবীতে অনাচার করতে লাগল অন্যায় ভাবে। হে মানুষ! শোন, তোমাদের অনাচার তোমাদেরই উপর পড়বে। পার্থিব জীবনের সুফল ভোগ করে নাও-অতঃপর আমার নিকট প্রত্যাবর্তন করতে হবে। তখন আমি বাতলে দেব, যা কিছু তোমরা করতে।', 'Falamma anjahum itha hum yabghoona fee alardi bighayri alhaqqi ya ayyuha alnnasu innama baghyukum AAala anfusikum mataAAa alhayati alddunya thumma ilayna marjiAAukum fanunabbiokum bima kuntum taAAmaloona', 1, NOW(), NOW()),
(15, 24, 'إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ', 'পার্থিব জীবনের উদাহরণ তেমনি, যেমনি আমি আসমান থেকে পানি বর্ষন করলাম, পরে তা মিলিত সংমিশ্রিত হয়ে তা থেকে যমীনের শ্যামল উদ্ভিদ বেরিয়ে এল যা মানুষ ও জীব-জন্তুরা খেয়ে থাকে। এমনকি যমীন যখন সৌন্দর্য সুষমায় ভরে উঠলো আর যমীনের অধিকর্তারা ভাবতে লাগল, এগুলো আমাদের হাতে আসবে, হঠাৎ করে তার উপর আমার নির্দেশ এল রাত্রে কিংবা দিনে, তখন সেগুলোকে কেটে স্তুপাকার করে দিল যেন কাল ও এখানে কোন আবাদ ছিল না। এমনিভাবে আমি খোলাখুলি বর্ণনা করে থাকি নিদর্শণসমূহ সে সমস্ত লোকদের জন্য যারা লক্ষ্য করে।', 'Innama mathalu alhayati alddunya kamain anzalnahu mina alssamai faikhtalata bihi nabatu alardi mimma yakulu alnnasu waalanAAamu hatta itha akhathati alardu zukhrufaha waizzayyanat wathanna ahluha annahum qadiroona AAalayha ataha amruna laylan aw naharan fajaAAalnaha haseedan kaan lam taghna bialamsi kathalika nufassilu alayati liqawmin yatafakkaroona', 1, NOW(), NOW()),
(15, 25, 'وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আর আল্লাহ শান্তি-নিরাপত্তার আলয়ের প্রতি আহবান জানান এবং যাকে ইচ্ছা সরলপথ প্রদর্শন করেন।', 'WaAllahu yadAAoo ila dari alssalami wayahdee man yashao ila siratin mustaqeemin', 1, NOW(), NOW()),
(15, 26, '۞لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'যারা সৎকর্ম করেছে তাদের জন্য রয়েছে কল্যাণ এবং তারও চেয়ে বেশী। আর তাদের মুখমন্ডলকে আবৃত করবে না মলিনতা কিংবা অপমান। তারাই হল জান্নাতবাসী, এতেই তারা বসবাস করতে থাকবে অনন্তকাল।', 'Lillatheena ahsanoo alhusna waziyadatun wala yarhaqu wujoohahum qatarun wala thillatun olaika ashabu aljannati hum feeha khalidoona', 1, NOW(), NOW()),
(15, 27, 'وَٱلَّذِينَ كَسَبُواْ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةٞۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۖ كَأَنَّمَآ أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَعٗا مِّنَ ٱلَّيۡلِ مُظۡلِمًاۚ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'আর যারা সঞ্চয় করেছে অকল্যাণ অসৎ কর্মের বদলায় সে পরিমাণ অপমান তাদের চেহারাকে আবৃত করে ফেলবে। কেউ নেই তাদেরকে বাঁচাতে পারে আল্লাহর হাত থেকে। তাদের মুখমন্ডল যেন ঢেকে দেয়া হয়েছে আধাঁর রাতের টুকরো দিয়ে। এরা হল দোযখবাসী। এরা এতেই থাকবে অনন্তকাল।', 'Waallatheena kasaboo alssayyiati jazao sayyiatin bimithliha watarhaquhum thillatun ma lahum mina Allahi min AAasimin kaannama oghshiyat wujoohuhum qitaAAan mina allayli muthliman olaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(15, 28, 'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُواْ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَآؤُكُمۡۚ فَزَيَّلۡنَا بَيۡنَهُمۡۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ', 'আর যেদিন আমি তাদের সবাইকে সমবেত করব; আর যারা শেরক করত তাদেরকে বলবঃ তোমরা এবং তোমাদের শরীকরা নিজ নিজ জায়গায় দাঁড়িয়ে যাও-অতঃপর তাদেরকে পারস্পরিক বিচ্ছিন্ন করে দেব, তখন তাদের শরীকরা বলবে, তোমরা তো আমাদের উপাসনা-বন্দেগী করনি।', 'Wayawma nahshuruhum jameeAAan thumma naqoolu lillatheena ashrakoo makanakum antum washurakaokum fazayyalna baynahum waqala shurakaohum ma kuntum iyyana taAAbudoona', 1, NOW(), NOW()),
(15, 29, 'فَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ', 'বস্তুতঃ আল্লাহ আমাদের ও তোমাদের মাঝে সাক্ষী হিসাবে যথেষ্ট। আমরা তোমাদের বন্দেগী সম্পর্কে জানতাম না।', 'Fakafa biAllahi shaheedan baynana wabaynakum in kunna AAan AAibadatikum laghafileena', 1, NOW(), NOW()),
(15, 30, 'هُنَالِكَ تَبۡلُواْ كُلُّ نَفۡسٖ مَّآ أَسۡلَفَتۡۚ وَرُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', 'সেখানে প্রত্যেকে যাচাই করে নিতে পারবে যা কিছু সে ইতিপূর্বে করেছিল এবং আল্লাহর প্রতি প্রত্যাবর্তন করবে যিনি তাদের প্রকৃত মালিক, আর তাদের কাছ থেকে দূরে যেতে থাকবে যারা মিথ্যা বলত।', 'Hunalika tabloo kullu nafsin ma aslafat waruddoo ila Allahi mawlahumu alhaqqi wadalla AAanhum ma kanoo yaftaroona', 1, NOW(), NOW()),
(15, 31, 'قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ', 'তুমি জিজ্ঞেস কর, কে রুযী দান করে তোমাদেরকে আসমান থেকে ও যমীন থেকে, কিংবা কে তোমাদের কান ও চোখের মালিক? তাছাড়া কে জীবিতকে মৃতের ভেতর থেকে বের করেন এবং কেইবা মৃতকে জীবিতের মধ্য থেকে বের করেন? কে করেন কর্ম সম্পাদনের ব্যবস্থাপনা? তখন তারা বলে উঠবে, আল্লাহ! তখন তুমি বলো তারপরেও ভয় করছ না', 'Qul man yarzuqukum mina alssamai waalardi amman yamliku alssamAAa waalabsara waman yukhriju alhayya mina almayyiti wayukhriju almayyita mina alhayyi waman yudabbiru alamra fasayaqooloona Allahu faqul afala tattaqoona', 1, NOW(), NOW()),
(15, 32, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ', 'অতএব, এ আল্লাহই তোমাদের প্রকৃত পালনকর্তা। আর সত্য প্রকাশের পরে (উদভ্রান্ত ঘুরার মাঝে) কি রয়েছে গোমরাহী ছাড়া? সুতরাং কোথায় ঘুরছ', 'Fathalikumu Allahu rabbukumu alhaqqu famatha baAAda alhaqqi illa alddalalu faanna tusrafoona', 1, NOW(), NOW()),
(15, 33, 'كَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓاْ أَنَّهُمۡ لَا يُؤۡمِنُونَ', 'এমনিভাবে সপ্রমাণিত হয়ে গেছে তোমার পরওয়ারদেগারের বাণী সেসব নাফরমানের ব্যাপারে যে, এরা ঈমান আনবে না।', 'Kathalika haqqat kalimatu rabbika AAala allatheena fasaqoo annahum la yuminoona', 1, NOW(), NOW()),
(15, 34, 'قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۚ قُلِ ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ', 'বল, আছে কি কেউ তোমাদের শরীকদের মাঝে যে সৃষ্টি কে পয়দা করতে পারে এবং আবার জীবিত করতে পারে? বল, আল্লাহই প্রথমবার সৃষ্টি করেন এবং অতঃপর তার পুনরুদ্ভব করবেন। অতএব, কোথায় ঘুরপাক খাচ্ছে', 'Qul hal min shurakaikum man yabdao alkhalqa thumma yuAAeeduhu quli Allahu yabdao alkhalqa thumma yuAAeeduhu faanna tufakoona', 1, NOW(), NOW()),
(15, 35, 'قُلۡ هَلۡ مِن شُرَكَآئِكُم مَّن يَهۡدِيٓ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ يَهۡدِي لِلۡحَقِّۗ أَفَمَن يَهۡدِيٓ إِلَى ٱلۡحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّيٓ إِلَّآ أَن يُهۡدَىٰۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ', 'জিজ্ঞেস কর, আছে কি কেউ তোমাদের শরীকদের মধ্যে যে সত্য-সঠিক পথ প্রদর্শন করবে? বল, আল্লাহই সত্য-সঠিক পথ প্রদর্শন করেন, সুতরাং এমন যে লোক সঠিক পথ দেখাবে তার কথা মান্য করা কিংবা যে লোক নিজে নিজে পথ খুঁজে পায় না, তাকে পথ দেখানো কর্তব্য। অতএব, তোমাদের কি হল, কেমন তোমাদের বিচার', 'Qul hal min shurakaikum man yahdee ila alhaqqi quli Allahu yahdee lilhaqqi afaman yahdee ila alhaqqi ahaqqu an yuttabaAAa amman la yahiddee illa an yuhda fama lakum kayfa tahkumoona', 1, NOW(), NOW()),
(15, 36, 'وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ', 'বস্তুতঃ তাদের অধিকাংশই শুধু আন্দাজ-অনুমানের উপর চলে, অথচ আন্দাজ-অনুমান সত্যের বেলায় কোন কাজেই আসে না। আল্লাহ ভাল করেই জানেন, তারা যা কিছু করে।', 'Wama yattabiAAu aktharuhum illa thannan inna alththanna la yughnee mina alhaqqi shayan inna Allaha AAaleemun bima yafAAaloona', 1, NOW(), NOW()),
(15, 37, 'وَمَا كَانَ هَٰذَا ٱلۡقُرۡءَانُ أَن يُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ', 'আর কোরআন সে জিনিস নয় যে, আল্লাহ ব্যতীত কেউ তা বানিয়ে নেবে। অবশ্য এটি পূর্ববর্তী কালামের সত্যায়ন করে এবং সে সমস্ত বিষয়ের বিশ্লেষণ দান করে যা তোমার প্রতি দেয়া হয়েছে, যাতে কোন সন্দেহ নেই-তোমার বিশ্বপালনকর্তার পক্ষ থেকে।', 'Wama kana hatha alquranu an yuftara min dooni Allahi walakin tasdeeqa allathee bayna yadayhi watafseela alkitabi la rayba feehi min rabbi alAAalameena', 1, NOW(), NOW()),
(15, 38, 'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةٖ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ', 'মানুষ কি বলে যে, এটি বানিয়ে এনেছ? বলে দাও, তোমরা নিয়ে এসো একটিই সূরা, আর ডেকে নাও, যাদেরকে নিতে সক্ষম হও আল্লাহ ব্যতীত, যদি তোমরা সত্যবাদী হয়ে থাক।', 'Am yaqooloona iftarahu qul fatoo bisooratin mithlihi waodAAoo mani istataAAtum min dooni Allahi in kuntum sadiqeena', 1, NOW(), NOW()),
(15, 39, 'بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّـٰلِمِينَ', 'কিন্তু কথা হল এই যে, তারা মিথ্যা প্রতিপন্ন করতে আরম্ভ করেছে যাকে বুঝতে, তারা অক্ষম। অথচ এখনো এর বিশ্লেষণ আসেনি। এমনিভাবে মিথ্যা প্রতিপন্ন করেছে তাদের পূর্ববর্তীরা। অতএব, লক্ষ্য করে দেখ, কেমন হয়েছে পরিণতি।', 'Bal kaththaboo bima lam yuheetoo biAAilmihi walamma yatihim taweeluhu kathalika kaththaba allatheena min qablihim faonthur kayfa kana AAaqibatu alththalimeena', 1, NOW(), NOW()),
(15, 40, 'وَمِنۡهُم مَّن يُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا يُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِينَ', 'আর তাদের মধ্যে কেউ কেউ কোরআনকে বিশ্বাস করবে এবং কেউ কেউ বিশ্বাস করবে না। বস্তুতঃ তোমার পরওয়ারদেগার যথার্থই জানেন দুরাচারদিগকে।', 'Waminhum man yuminu bihi waminhum man la yuminu bihi warabbuka aAAlamu bialmufsideena', 1, NOW(), NOW()),
(15, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّي عَمَلِي وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعۡمَلُ وَأَنَا۠ بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ', 'আর যদি তোমাকে মিথ্যা প্রতিপন্ন করে, তবে বল, আমার জন্য আমার কর্ম, আর তোমাদের জন্য তোমাদের কর্ম। তোমাদের দায়-দায়িত্ব নেই আমার কর্মের উপর এবং আমারও দায়-দায়িত্ব নেই তোমরা যা কর সেজন্য।', 'Wain kaththabooka faqul lee AAamalee walakum AAamalukum antum bareeoona mimma aAAmalu waana bareeon mimma taAAmaloona', 1, NOW(), NOW()),
(15, 42, 'وَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ', 'তাদের কেউ কেউ কান রাখে তোমাদের প্রতি; তুমি বধিরদেরকে কি শোনাবে যদি তাদের বিবেক-বুদ্ধি না থাকে', 'Waminhum man yastamiAAoona ilayka afaanta tusmiAAu alssumma walaw kanoo la yaAAqiloona', 1, NOW(), NOW()),
(15, 43, 'وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ', 'আবার তাদের মধ্যে কেউ কেউ তোমাদের প্রতি দৃষ্টিনিবদ্ধ রাখে; তুমি অন্ধদেরকে কি পথ দেখাবে যদি তারা মোটেও দেখতে না পারে।', 'Waminhum man yanthuru ilayka afaanta tahdee alAAumya walaw kanoo la yubsiroona', 1, NOW(), NOW()),
(15, 44, 'إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ', 'আল্লাহ জুলুম করেন না মানুষের উপর, বরং মানুষ নিজেই নিজের উপর জুলুম করে।', 'Inna Allaha la yathlimu alnnasa shayan walakinna alnnasa anfusahum yathlimoona', 1, NOW(), NOW()),
(15, 45, 'وَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِ وَمَا كَانُواْ مُهۡتَدِينَ', 'আর যেদিন তাদেরকে সমবেত করা হবে, যেন তারা অবস্থান করেনি, তবে দিনের একদন্ড একজন অপরজনকে চিনবে। নিঃসন্দেহে ক্ষতিগ্রস্ত হয়েছে যারা মিথ্যা প্রতিপন্ন করেছে আল্লাহর সাথে সাক্ষাতকে এবং সরলপথে আসেনি।', 'Wayawma yahshuruhum kaan lam yalbathoo illa saAAatan mina alnnahari yataAAarafoona baynahum qad khasira allatheena kaththaboo biliqai Allahi wama kanoo muhtadeena', 1, NOW(), NOW()),
(15, 46, 'وَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَلُونَ', 'আর যদি আমি দেখাই তোমাকে সে ওয়াদাসমূহের মধ্য থেকে কোন কিছু যা আমি তাদের সাথে করেছি, অথবা তোমাকে মৃত্যুদান করি, যাহোক, আমার কাছেই তাদেরকে প্রত্যাবর্তন করতে হবে। বস্তুতঃ আল্লাহ সে সমস্ত কর্মের সাক্ষী যা তারা করে।', 'Waimma nuriyannaka baAAda allathee naAAiduhum aw natawaffayannaka failayna marjiAAuhum thumma Allahu shaheedun AAala ma yafAAaloona', 1, NOW(), NOW()),
(15, 47, 'وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ', 'আর প্রত্যেক সম্প্রদায়ের একেকজন রসূল রয়েছে। যখন তাদের কাছে তাদের রসূল ন্যায়দন্ডসহ উপস্থিত হল, তখন আর তাদের উপর জুলুম হয় না।', 'Walikulli ommatin rasoolun faitha jaa rasooluhum qudiya baynahum bialqisti wahum la yuthlamoona', 1, NOW(), NOW()),
(15, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ', 'তারা আরো বলে, এ ওয়াদা কবে আসবে, যদি তোমরা সত্যবাদী হয়ে থাক', 'Wayaqooloona mata hatha alwaAAdu in kuntum sadiqeena', 1, NOW(), NOW()),
(15, 49, 'قُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَآءَ أَجَلُهُمۡ فَلَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ', 'তুমি বল, আমি আমার নিজের ক্ষতি কিংবা লাভেরও মালিক নই, কিন্তু আল্লাহ যা ইচ্ছা করেন। প্রত্যেক সম্প্রদায়ের জন্যই একেকটি ওয়াদা রয়েছে, যখন তাদের সে ওয়াদা এসে পৌঁছে যাবে, তখন না একদন্ড পেছনে সরতে পারবে, না সামনে ফসকাতে পারবে,।', 'Qul la amliku linafsee darran wala nafAAan illa ma shaa Allahu likulli ommatin ajalun itha jaa ajaluhum fala yastakhiroona saAAatan wala yastaqdimoona', 1, NOW(), NOW()),
(15, 50, 'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ', 'তুমি বল, আচ্ছা দেখ তো দেখি, যদি তোমাদের উপর তার আযাব রাতারাতি অথবা দিনের বেলায় এসে পৌঁছে যায়, তবে এর আগে পাপীরা কি করবে', 'Qul araaytum in atakum AAathabuhu bayatan aw naharan matha yastaAAjilu minhu almujrimoona', 1, NOW(), NOW()),
(15, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓۚ ءَآلۡـَٰٔنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ', 'তাহলে কি আযাব সংঘটিত হয়ে যাবার পর এর প্রতি বিশ্বাস করবে? এখন স্বীকার করলে? অথচ তোমরা এরই তাকাদা করতে', 'Athumma itha ma waqaAAa amantum bihi alana waqad kuntum bihi tastaAAjiloona', 1, NOW(), NOW()),
(15, 52, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ', 'অতঃপর বলা হবে, গোনাহগারদিগকে, ভোগ করতে থাক অনন্ত আযাব-তোমরা যা কিছু করতে তার তাই প্রতিফল।', 'Thumma qeela lillatheena thalamoo thooqoo AAathaba alkhuldi hal tujzawna illa bima kuntum taksiboona', 1, NOW(), NOW()),
(15, 53, '۞وَيَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِي وَرَبِّيٓ إِنَّهُۥ لَحَقّٞۖ وَمَآ أَنتُم بِمُعۡجِزِينَ', 'আর তোমার কাছে সংবাদ জিজ্ঞেস করে, এটা কি সত্য ? বলে দাও, অবশ্যই আমার পরওয়ারদেগারের কসম এটা সত্য। আর তোমরা পরিশ্রান্ত করে দিতে পারবে না।', 'Wayastanbioonaka ahaqqun huwa qul ee warabbee innahu lahaqqun wama antum bimuAAjizeena', 1, NOW(), NOW()),
(15, 54, 'وَلَوۡ أَنَّ لِكُلِّ نَفۡسٖ ظَلَمَتۡ مَا فِي ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّواْ ٱلنَّدَامَةَ لَمَّا رَأَوُاْ ٱلۡعَذَابَۖ وَقُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ', 'বস্তুতঃ যদি প্রত্যেক গোনাহগারের কাছে এত পরিমাণ থাকে যা আছে সমগ্র যমীনের মাঝে, আর অবশ্যই যদি সেগুলো নিজের মুক্তির বিনিময়ে দিতে চাইবে আর গোপনে গোপনে অনুতাপ করবে, যখন আযাব দেখবে। বস্তুতঃ তাদের জন্য সিদ্ধান্ত হবে ন্যায়সঙ্গত এবং তাদের উপর জুলম হবে না।', 'Walaw anna likulli nafsin thalamat ma fee alardi laiftadat bihi waasarroo alnnadamata lamma raawoo alAAathaba waqudiya baynahum bialqisti wahum la yuthlamoona', 1, NOW(), NOW()),
(15, 55, 'أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ', 'শুনে রাখ, যা কিছু রয়েছে আসমানসমূহে ও যমীনে সবই আল্লাহর। শুনে রাখ, আল্লাহর প্রতিশ্রুতি সত্য। তবে অনেকেই জানে না।', 'Ala inna lillahi ma fee alssamawati waalardi ala inna waAAda Allahi haqqun walakinna aktharahum la yaAAlamoona', 1, NOW(), NOW()),
(15, 56, 'هُوَ يُحۡيِۦ وَيُمِيتُ وَإِلَيۡهِ تُرۡجَعُونَ', 'তিনিই জীবন ও মরণ দান করেন এবং তাঁরই কাছে প্রত্যাবর্তন করতে হবে।', 'Huwa yuhyee wayumeetu wailayhi turjaAAoona', 1, NOW(), NOW()),
(15, 57, 'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ', 'হে মানবকুল, তোমাদের কাছে উপদেশবানী এসেছে তোমাদের পরওয়ারদেগারের পক্ষ থেকে এবং অন্তরের রোগের নিরাময়, হেদায়েত ও রহমত মুসলমানদের জন্য।', 'Ya ayyuha alnnasu qad jaatkum mawAAithatun min rabbikum washifaon lima fee alssudoori wahudan warahmatun lilmumineena', 1, NOW(), NOW()),
(15, 58, 'قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ هُوَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ', 'বল, আল্লাহর দয়া ও মেহেরবাণীতে। সুতরাং এরই প্রতি তাদের সন্তুষ্ট থাকা উচিৎ। এটিই উত্তম সে সমুদয় থেকে যা সঞ্চয় করছ।', 'Qul bifadli Allahi wabirahmatihi fabithalika falyafrahoo huwa khayrun mimma yajmaAAoona', 1, NOW(), NOW()),
(15, 59, 'قُلۡ أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ فَجَعَلۡتُم مِّنۡهُ حَرَامٗا وَحَلَٰلٗا قُلۡ ءَآللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ', 'বল, আচ্ছা নিজেই লক্ষ্য করে দেখ, যা কিছু আল্লাহ তোমাদের জন্য রিযিক হিসাবে অবতীর্ণ করেছেন, তোমরা সেগুলোর মধ্য থেকে কোনটাকে হারাম আর কোনটাকে হালাল সাব্যস্ত করেছ? বল, তোমাদের কি আল্লাহ নির্দেশ দিয়েছেন, নাকি আল্লাহর উপর অপবাদ আরোপ করছ', 'Qul araaytum ma anzala Allahu lakum min rizqin fajaAAaltum minhu haraman wahalalan qul allahu athina lakum am AAala Allahi taftaroona', 1, NOW(), NOW()),
(15, 60, 'وَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ', 'আর আল্লাহর প্রতি মিথ্যা অপবাদ আরোপকারীদের কি ধারণা কেয়ামত সম্পর্কে? আল্লাহ তো মানুষের প্রতি অনুগ্রহই করেন, কিন্তু অনেকেই কৃতজ্ঞতা স্বীকার করে না।', 'Wama thannu allatheena yaftaroona AAala Allahi alkathiba yawma alqiyamati inna Allaha lathoo fadlin AAala alnnasi walakinna aktharahum la yashkuroona', 1, NOW(), NOW()),
(15, 61, 'وَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ', 'বস্তুতঃ যে কোন অবস্থাতেই তুমি থাক এবং কোরআনের যে কোন অংশ থেকেই পাঠ করা কিংবা যে কোন কাজই তোমরা কর অথচ আমি তোমাদের নিকটে উপস্থিত থাকি যখন তোমরা তাতে আত্ননিয়োগ কর। আর তোমার পরওয়ারদেগার থেকে গোপন থাকে না একটি কনাও, না যমীনের এবং না আসমানের। না এর চেয়ে ক্ষুদ্র কোন কিছু আছে, না বড় যা এই প্রকৃষ্ট কিতাবে নেই।', 'Wama takoonu fee shanin wama tatloo minhu min quranin wala taAAmaloona min AAamalin illa kunna AAalaykum shuhoodan ith tufeedoona feehi wama yaAAzubu AAan rabbika min mithqali tharratin fee alardi wala fee alssamai wala asghara min thalika wala akbara illa fee kitabin mubeenun', 1, NOW(), NOW()),
(15, 62, 'أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ', 'মনে রেখো যারা আল্লাহর বন্ধু, তাদের না কোন ভয় ভীতি আছে, না তারা চিন্তান্বিত হবে।', 'Ala inna awliyaa Allahi la khawfun AAalayhim wala hum yahzanoona', 1, NOW(), NOW()),
(15, 63, 'ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ', 'যারা ঈমান এনেছে এবং ভয় করতে রয়েছে।', 'Allatheena amanoo wakanoo yattaqoona', 1, NOW(), NOW()),
(15, 64, 'لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ', 'তাদের জন্য সুসংবাদ পার্থিব জীবনে ও পরকালীন জীবনে। আল্লাহর কথার কখনো হের-ফের হয় না। এটাই হল মহা সফলতা।', 'Lahumu albushra fee alhayati alddunya wafee alakhirati la tabdeela likalimati Allahi thalika huwa alfawzu alAAatheemu', 1, NOW(), NOW()),
(15, 65, 'وَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'আর তাদের কথায় দুঃখ নিয়ো না। আসলে সমস্ত ক্ষমতা আল্লাহর। তিনিই শ্রবণকারী, সর্বজ্ঞ।', 'Wala yahzunka qawluhum inna alAAizzata lillahi jameeAAan huwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(15, 66, 'أَلَآ إِنَّ لِلَّهِ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ', 'শুনছ, আসমানসমূহে ও যমীনে যা কিছু রয়েছে সবই আল্লাহর। আর এরা যারা আল্লাহকে বাদ দিয়ে শরীকদের উপাসনার পেছনে পড়ে আছে-তা আসলে কিছুই নয়। এরা নিজেরই কল্পনার পেছনে পড়ে রয়েছে এবং এছাড়া আর কিছু নয় যে, এরা বুদ্ধি খাটাচ্ছে।', 'Ala inna lillahi man fee alssamawati waman fee alardi wama yattabiAAu allatheena yadAAoona min dooni Allahi shurakaa in yattabiAAoona illa alththanna wain hum illa yakhrusoona', 1, NOW(), NOW()),
(15, 67, 'هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ', 'তিনি তোমাদের জন্য তৈরী করেছেন রাত, যাতে করে তোমরা তাতে প্রশান্তি লাভ করতে পার, আর দিন দিয়েছেন দর্শন করার জন্য। নিঃসন্দেহে এতে নিদর্শন রয়েছে সে সব লোকের জন্য যারা শ্রবণ করে।', 'Huwa allathee jaAAala lakumu allayla litaskunoo feehi waalnnahara mubsiran inna fee thalika laayatin liqawmin yasmaAAoona', 1, NOW(), NOW()),
(15, 68, 'قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۭ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'তারা বলে, আল্লাহ পুত্র সাব্যস্ত করে নিয়েছেন-তিনি পবিত্র, তিনি অমুখাপেক্ষী। যাকিছু রয়েছে আসমান সমূহে ও যমীনে সবই তাঁর। তোমাদের কাছে তার কোন সনদ নেই। কেন তোমরা আল্লাহর প্রতি মিথ্যারোপ কর-যার কোন সনদই তোমাদের কাছে নেই', 'Qaloo ittakhatha Allahu waladan subhanahu huwa alghaniyyu lahu ma fee alssamawati wama fee alardi in AAindakum min sultanin bihatha ataqooloona AAala Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(15, 69, 'قُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ', 'বলে দাও, যারা এরূপ করে তারা অব্যাহতি পায় না।', 'Qul inna allatheena yaftaroona AAala Allahi alkathiba la yuflihoona', 1, NOW(), NOW()),
(15, 70, 'مَتَٰعٞ فِي ٱلدُّنۡيَا ثُمَّ إِلَيۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِيقُهُمُ ٱلۡعَذَابَ ٱلشَّدِيدَ بِمَا كَانُواْ يَكۡفُرُونَ', 'পার্থিবজীবনে সামান্যই লাভ, অতঃপর আমার নিকট প্রত্যাবর্তন করতে হবে। তখন আমি তাদেরকে আস্বাদন করাব কঠিন আযাব-তাদেরই কৃত কুফরীর বদলাতে।', 'MataAAun fee alddunya thumma ilayna marjiAAuhum thumma nutheequhumu alAAathaba alshshadeeda bima kanoo yakfuroona', 1, NOW(), NOW()),
(15, 71, '۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ يَٰقَوۡمِ إِن كَانَ كَبُرَ عَلَيۡكُم مَّقَامِي وَتَذۡكِيرِي بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوٓاْ أَمۡرَكُمۡ وَشُرَكَآءَكُمۡ ثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ', 'আর তাদেরকে শুনিয়ে দাও নূহের অবস্থা যখন সে স্বীয় সম্প্রদায়কে বলল, হে আমার সম্প্রদায়, যদি তোমাদের মাঝে আমার অবস্থিতি এবং আল্লাহর আয়াতসমূহের মাধ্যমে নসীহত করা ভারী বলে মনে হয়ে থাকে, তবে আমি আল্লাহর উপর ভরসা করছি। এখন তোমরা সবাই মিলে নিজেরদের কর্ম সাব্যস্ত কর এবং এতে তোমাদের শরীকদেরকে সমবেত করে নাও, যাতে তোমাদের মাঝে নিজেদের কাজের ব্যাপারে কোন সন্দেহ-সংশয় না থাকে। অতঃপর আমার সম্পর্কে যা কিছু করার করে ফেল এবং আমাকে অব্যাহতি দিও না।', 'Waotlu AAalayhim nabaa noohin ith qala liqawmihi ya qawmi in kana kabura AAalaykum maqamee watathkeeree biayati Allahi faAAala Allahi tawakkaltu faajmiAAoo amrakum washurakaakum thumma la yakun amrukum AAalaykum ghummatan thumma iqdoo ilayya wala tunthirooni', 1, NOW(), NOW()),
(15, 72, 'فَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ', 'তারপরও যদি বিমুখতা অবলম্বন কর, তবে আমি তোমাদের কাছে কোন রকম বিনিময় কামনা করি না। আমার বিনিময় হল আল্লাহর দায়িত্বে। আর আমার প্রতি নির্দেশ রয়েছে যেন আমি আনুগত্য অবলম্বন করি।', 'Fain tawallaytum fama saaltukum min ajrin in ajriya illa AAala Allahi waomirtu an akoona mina almuslimeena', 1, NOW(), NOW()),
(15, 73, 'فَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَـٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ', 'তারপরও এরা মিথ্যা প্রতিপন্ন করল। সুতরাং তাকে এবং তার সাথে নৌকায় যারা ছিল তাদের কে বাঁচিয়ে নিয়েছি এবং যথাস্থানে আবাদ করেছি। আর তাদেরকে ডুবিয়ে দিয়েছি যারা আমার কথাকে মিথ্যা প্রতিপন্ন করেছে। সুতরাং লক্ষ্য কর, কেমন পরিণতি ঘটেছে তাদের যাদেরকে ভীতি প্রদর্শন করা হয়েছিল।', 'Fakaththaboohu fanajjaynahu waman maAAahu fee alfulki wajaAAalnahum khalaifa waaghraqna allatheena kaththaboo biayatina faonthur kayfa kana AAaqibatu almunthareena', 1, NOW(), NOW()),
(15, 74, 'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ', 'অনন্তর আমি নূহের পরে বহু নবী-রসূল পাঠিয়েছি তাদের সম্প্রদায়ের প্রতি। তারপর তাদের কাছে তারা প্রকাশ্য দলীল-প্রমাণ উপস্থাপন করেছে, কিন্তু তাদের দ্বারা এমনটি হয়নি যে, ঈমান আনবে সে ব্যাপারে, যাকে তারা ইতিপূর্বে মিথ্যা প্রতিপন্ন করেছিল। এভাবেই আমি মোহর এঁটে দেই সীমালংঘনকারীদের অন্তরসমূহের উপর।', 'Thumma baAAathna min baAAdihi rusulan ila qawmihim fajaoohum bialbayyinati fama kanoo liyuminoo bima kaththaboo bihi min qablu kathalika natbaAAu AAala quloobi almuAAtadeena', 1, NOW(), NOW()),
(15, 75, 'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ', 'অতঃপর তাদের পেছনে পাঠিয়েছি আমি মূসা ও হারুনকে, ফেরাউন ও তার সর্দারের প্রতি স্বীয় নির্দেশাবলী সহকারে। অথচ তারা অহংকার করতে আরম্ভ করেছে।', 'Thumma baAAathna min baAAdihim moosa waharoona ila firAAawna wamalaihi biayatina faistakbaroo wakanoo qawman mujrimeena', 1, NOW(), NOW()),
(15, 76, 'فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوٓاْ إِنَّ هَٰذَا لَسِحۡرٞ مُّبِينٞ', 'বস্তুতঃ তারা ছিল গোনাহগার। তারপর আমার পক্ষ থেকে যখন তাদের কাছে সত্য বিষয় উপস্থিত হল, তখন বলতে লাগলো, এগুলো তো প্রকাশ্য যাদু।', 'Falamma jaahumu alhaqqu min AAindina qaloo inna hatha lasihrun mubeenun', 1, NOW(), NOW()),
(15, 77, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَآءَكُمۡۖ أَسِحۡرٌ هَٰذَا وَلَا يُفۡلِحُ ٱلسَّـٰحِرُونَ', 'মূসা বলল, সত্যের ব্যাপারে একথা বলছ, তা তোমাদের কাছে পৌঁছার পর? একি যাদু? অথচ যারা যাদুকর, তারা সফল হতে পারে না।', 'Qala moosa ataqooloona lilhaqqi lamma jaakum asihrun hatha wala yuflihu alssahiroona', 1, NOW(), NOW()),
(15, 78, 'قَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ', 'তারা বলল, তুমি কি আমাদেরকে সে পথ থেকে ফিরিয়ে দিতে এসেছ যাতে আমরা পেয়েছি আমাদের বাপ-দাদাদেরকে? আর যাতে তোমরা দুইজন এদেশের সর্দারী পেয়ে যেতে পার? আমরা তোমাদেরকে কিছুতেই মানব না।', 'Qaloo ajitana litalfitana AAamma wajadna AAalayhi abaana watakoona lakuma alkibriyao fee alardi wama nahnu lakuma bimumineena', 1, NOW(), NOW()),
(15, 79, 'وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِي بِكُلِّ سَٰحِرٍ عَلِيمٖ', 'আর ফেরাউন বলল, আমার কাছে নিয়ে এস সুদক্ষ যাদুকরদিগকে।', 'Waqala firAAawnu itoonee bikulli sahirin AAaleemin', 1, NOW(), NOW()),
(15, 80, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ', 'তারপর যখন যাদুকররা এল, মূসা তাদেরকে বলল, নিক্ষেপ কর, তোমরা যা কিছু নিক্ষেপ করে থাক।', 'Falamma jaa alssaharatu qala lahum moosa alqoo ma antum mulqoona', 1, NOW(), NOW()),
(15, 81, 'فَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ', 'অতঃপর যখন তারা নিক্ষেপ করল, মূসা বলল, যা কিছু তোমরা এনেছ তা সবই যাদু-এবার আল্লাহ এসব ভন্ডুল করে দিচ্ছেন। নিঃসন্দেহে আল্লাহ দুস্কর্মীদের কর্মকে সুষ্ঠুতা দান করেন না।', 'Falamma alqaw qala moosa ma jitum bihi alssihru inna Allaha sayubtiluhu inna Allaha la yuslihu AAamala almufsideena', 1, NOW(), NOW()),
(15, 82, 'وَيُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ', 'আল্লাহ সত্যকে সত্যে পরিণত করেন স্বীয় নির্দেশে যদিও পাপীদের তা মনঃপুত নয়।', 'Wayuhiqqu Allahu alhaqqa bikalimatihi walaw kariha almujrimoona', 1, NOW(), NOW()),
(15, 83, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفٖ مِّن فِرۡعَوۡنَ وَمَلَإِيْهِمۡ أَن يَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالٖ فِي ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِينَ', 'আর কেউ ঈমান আনল না মূসার প্রতি তাঁর কওমের কতিপয় বালক ছাড়া-ফেরাউন ও তার সর্দারদের ভয়ে যে, এরা না আবার কোন বিপদে ফেলে দেয়। ফেরাউন দেশময় কর্তꦣ2499;ত্বের শিখরে আরোহণ করেছিল। আর সে তার হাত ছেড়ে রেখেছিল।', 'Fama amana limoosa illa thurriyyatun min qawmihi AAala khawfin min firAAawna wamalaihim an yaftinahum wainna firAAawna laAAalin fee alardi wainnahu lamina almusrifeena', 1, NOW(), NOW()),
(15, 84, 'وَقَالَ مُوسَىٰ يَٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَيۡهِ تَوَكَّلُوٓاْ إِن كُنتُم مُّسۡلِمِينَ', 'আর মূসা বলল, হে আমার সম্প্রদায়, তোমরা যদি আল্লাহর উপর ঈমান এনে থাক, তবে তারই উপর ভরসা কর যদি তোমরা ফরমাবরদার হয়ে থাক।', 'Waqala moosa ya qawmi in kuntum amantum biAllahi faAAalayhi tawakkaloo in kuntum muslimeena', 1, NOW(), NOW()),
(15, 85, 'فَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'তখন তারা বলল, আমরা আল্লাহর উপর ভরসা করেছি। হে আমাদের পালনকর্তা, আমাদের উপর এ জালেম কওমের শক্তি পরীক্ষা করিও না।', 'Faqaloo AAala Allahi tawakkalna rabbana la tajAAalna fitnatan lilqawmi alththalimeena', 1, NOW(), NOW()),
(15, 86, 'وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ', 'আর আমাদেরকে অনুগ্রহ করে ছাড়িয়ে দাও এই কাফেরদের কবল থেকে।', 'Wanajjina birahmatika mina alqawmi alkafireena', 1, NOW(), NOW()),
(15, 87, 'وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُوتٗا وَٱجۡعَلُواْ بُيُوتَكُمۡ قِبۡلَةٗ وَأَقِيمُواْ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ', 'আর আমি নির্দেশ পাঠালাম মূসা এবং তার ভাইয়ের প্রতি যে, তোমরা তোমাদের জাতির জন্য মিসরের মাটিতে বাস স্থান নির্ধারণ কর। আর তোমাদের ঘরগুলো বানাবে কেবলামুখী করে এবং নামায কায়েম কর আর যারা ঈমানদার তাদেরকে সুসংবাদ দান কর।', 'Waawhayna ila moosa waakheehi an tabawwaa liqawmikuma bimisra buyootan waijAAaloo buyootakum qiblatan waaqeemoo alssalata wabashshiri almumineena', 1, NOW(), NOW()),
(15, 88, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِينَةٗ وَأَمۡوَٰلٗا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا رَبَّنَا لِيُضِلُّواْ عَن سَبِيلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰٓ أَمۡوَٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ', 'মূসা বলল, হে আমার পরওয়ারদেগার, তুমি ফেরাউনকে এবং তার সর্দারদেরকে পার্থব জীবনের আড়ম্বর দান করেছ, এবং সম্পদ দান করেছ-হে আমার পরওয়ারদেগার, এ জন্যই যে তারা তোমার পথ থেকে বিপথগামী করব! হে আমার পরওয়ারদেগার, তাদের ধন-সম্পদ ধ্বংস করে দাও এবং তাদের অন্তরগুলোকে কাঠোর করে দাও যাতে করে তারা ততক্ষণ পর্যন্ত ঈমান না আনে যতক্ষণ না বেদনাদায়ক আযাব প্রত্যক্ষ করে নেয়।', 'Waqala moosa rabbana innaka atayta firAAawna wamalaahu zeenatan waamwalan fee alhayati alddunya rabbana liyudilloo AAan sabeelika rabbana itmis AAala amwalihim waoshdud AAala quloobihim fala yuminoo hatta yarawoo alAAathaba alaleema', 1, NOW(), NOW()),
(15, 89, 'قَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ', 'বললেন, তোমাদের দোয়া মঞ্জুর হয়েছে। অতএব তোমরা দুজন অটল থাকো এবং তাদের পথে চলো না যারা অজ্ঞ।', 'Qala qad ojeebat daAAwatukuma faistaqeema wala tattabiAAanni sabeela allatheena la yaAAlamoona', 1, NOW(), NOW()),
(15, 90, '۞وَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡيٗا وَعَدۡوًاۖ حَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَـٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ', 'আর বনী-ইসরাঈলকে আমি পার করে দিয়েছি নদী। তারপর তাদের পশ্চাদ্ধাবন করেছে ফেরাউন ও তার সেনাবাহিনী, দুরাচার ও বাড়াবাড়ির উদ্দেশে। এমনকি যখন তারা ডুবতে আরম্ভ করল, তখন বলল, এবার বিশ্বাস করে নিচ্ছি যে, কোন মা’বুদ নেই তাঁকে ছাড়া যাঁর উপর ঈমান এনেছে বনী-ইসরাঈলরা। বস্তুতঃ আমিও তাঁরই অনুগতদের অন্তর্ভুক্ত।', 'Wajawazna bibanee israeela albahra faatbaAAahum firAAawnu wajunooduhu baghyan waAAadwan hatta itha adrakahu algharaqu qala amantu annahu la ilaha illa allathee amanat bihi banoo israeela waana mina almuslimeena', 1, NOW(), NOW()),
(15, 91, 'ءَآلۡـَٰٔنَ وَقَدۡ عَصَيۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِينَ', 'এখন একথা বলছ! অথচ তুমি ইতিপূর্বে না-ফরমানী করছিলে। এবং পথভ্রষ্টদেরই অন্তর্ভুক্ত ছিলে।', 'Alana waqad AAasayta qablu wakunta mina almufsideena', 1, NOW(), NOW()),
(15, 92, 'فَٱلۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَةٗۚ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ', 'অতএব আজকের দিনে বাঁচিয়ে দিচ্ছি আমি তোমার দেহকে যাতে তোমার পশ্চাদবর্তীদের জন্য নিদর্শন হতে পারে। আর নিঃসন্দেহে বহু লোক আমার মহাশক্তির প্রতি লক্ষ্য করে না।', 'Faalyawma nunajjeeka bibadanika litakoona liman khalfaka ayatan wainna katheeran mina alnnasi AAan ayatina laghafiloona', 1, NOW(), NOW()),
(15, 93, 'وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ', 'আর আমি বনী-ইসরাঈলদিগকে দান করেছি উত্তম স্থান এবং তাদেরকে আহার্য দিয়েছি পবিত্র-পরিচ্ছন্ন বস্তু-সামগ্রী। বস্তুতঃ তাদের মধ্যে মতবিরোধ হয়নি যতক্ষণ না তাদের কাছে এসে পৌছেছে সংবাদ। নিঃসন্দেহে তোমার পরওয়ারদেগার তাদের মাঝে মীমাংসা করে দেবেন কেয়ামতের দিন; যে ব্যাপারে তাদের মাঝে মতবিরোধ হয়েছিল', 'Walaqad bawwana banee israeela mubawwaa sidqin warazaqnahum mina alttayyibati fama ikhtalafoo hatta jaahumu alAAilmu inna rabbaka yaqdee baynahum yawma alqiyamati feema kanoo feehi yakhtalifoona', 1, NOW(), NOW()),
(15, 94, 'فَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَآءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ', 'সুতরাং তুমি যদি সে বস্তু সম্পর্কে কোন সন্দেহের সম্মুখীন হয়ে থাক যা তোমার প্রতি আমি নাযিল করেছি, তবে তাদেরকে জিজ্ঞেস করো যারা তোমার পূর্ব থেকে কিতাব পাঠ করছে। এতে কোন সন্দেহ নেই যে, তোমার পরওয়ারদেগারের নিকট থেকে তোমার নিকট সত্য বিষয় এসেছে। কাজেই তুমি কস্মিনকালেও সন্দেহকারী হয়ো না।', 'Fain kunta fee shakkin mimma anzalnna ilayka faisali allatheena yaqraoona alkitaba min qablika laqad jaaka alhaqqu min rabbika fala takoonanna mina almumtareena', 1, NOW(), NOW()),
(15, 95, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَٰسِرِينَ', 'এবং তাদের অন্তর্ভুক্তও হয়ো না যারা মিথ্যা প্রতিপন্ন করেছে আল্লাহর বাণীকে। তাহলে তুমিও অকল্যাণে পতিত হয়ে যাবে।', 'Wala takoonanna mina allatheena kaththaboo biayati Allahi fatakoona mina alkhasireena', 1, NOW(), NOW()),
(15, 96, 'إِنَّ ٱلَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِنُونَ', 'যাদের ব্যাপারে তোমার পরওয়ারদেগারের সিদ্ধান্ত নির্ধারিত হয়ে গেছে তারা ঈমান আনবে না।', 'Inna allatheena haqqat AAalayhim kalimatu rabbika la yuminoona', 1, NOW(), NOW()),
(15, 97, 'وَلَوۡ جَآءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ', 'যদি তাদের সামনে সমস্ত নিদর্শনাবলী এসে উপস্থিত হয় তবুও যতক্ষণ না তারা দেখতে পায় বেদনাদায়ক আযাব।', 'Walaw jaathum kullu ayatin hatta yarawoo alAAathaba alaleema', 1, NOW(), NOW()),
(15, 98, 'فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ', 'সুতরাং কোন জনপদ কেন এমন হল না যা ঈমান এনেছে অতঃপর তার সে ঈমান গ্রহণ হয়েছে কল্যাণকর? অবশ্য ইউনুসের সম্প্রদায়ের কথা আলাদা। তারা যখন ঈমান আনে তখন আমি তুলে নেই তাদের উপর থেকে অপমানজনক আযাব-পার্থিব জীবনে এবং তাদের কে কল্যাণ পৌছাই এক নিধারিত সময় পর্যন্ত।', 'Falawla kanat qaryatun amanat fanafaAAaha eemanuha illa qawma yoonusa lamma amanoo kashafna AAanhum AAathaba alkhizyi fee alhayati alddunya wamattaAAnahum ila heenin', 1, NOW(), NOW()),
(15, 99, 'وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ', 'আর তোমার পরওয়ারদেগার যদি চাইতেন, তবে পৃথিবীর বুকে যারা রয়েছে, তাদের সবাই ঈমান নিয়ে আসতে সমবেতভাবে। তুমি কি মানুষের উপর জবরদস্তী করবে ঈমান আনার জন্য', 'Walaw shaa rabbuka laamana man fee alardi kulluhum jameeAAan afaanta tukrihu alnnasa hatta yakoonoo mumineena', 1, NOW(), NOW()),
(15, 100, 'وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَيَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يَعۡقِلُونَ', 'আর কারো ঈমান আনা হতে পারে না, যতক্ষণ না আল্লাহর হুকুম হয়। পক্ষান্তরে তিনি অপবিত্রতা আরোপ করেন যারা বুদ্ধি প্রয়োগ করে না তাদের উপর।', 'Wama kana linafsin an tumina illa biithni Allahi wayajAAalu alrrijsa AAala allatheena la yaAAqiloona', 1, NOW(), NOW()),
(15, 101, 'قُلِ ٱنظُرُواْ مَاذَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِي ٱلۡأٓيَٰتُ وَٱلنُّذُرُ عَن قَوۡمٖ لَّا يُؤۡمِنُونَ', 'তাহলে আপনি বলে দিন, চেয়ে দেখ তো আসমানসমুহে ও যমীনে কি রয়েছে। আর কোন নিদর্শন এবং কোন ভীতিপ্রর্দশনই কোন কাজে আসে না সেসব লোকের জন্য যারা মান্য করে না।', 'Quli onthuroo matha fee alssamawati waalardi wama tughnee alayatu waalnnuthuru AAan qawmin la yuminoona', 1, NOW(), NOW()),
(15, 102, 'فَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ', 'সুতরাং এখন আর এমন কিছু নেই, যার অপেক্ষা করবে, কিন্তু সেসব দিনের মতই দিন, যা অতীত হয়ে গেছে এর পূর্বে। আপনি বলুন; এখন পথ দেখ; আমিও তোমাদের সাথে পথ চেয়ে রইলাম।', 'Fahal yantathiroona illa mithla ayyami allatheena khalaw min qablihim qul faintathiroo innee maAAakum mina almuntathireena', 1, NOW(), NOW()),
(15, 103, 'ثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ', 'অতঃপর আমি বাঁচিয়ে নেই নিজের রসূলগণকে এবং তাদেরকে যারা ঈমান এনেছে এমনিভাবে। ঈমানদারদের বাঁচিয়ে নেয়া আমার দায়িত্বও বটে।', 'Thumma nunajjee rusulana waallatheena amanoo kathalika haqqan AAalayna nunjee almumineena', 1, NOW(), NOW()),
(15, 104, 'قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي شَكّٖ مِّن دِينِي فَلَآ أَعۡبُدُ ٱلَّذِينَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِي يَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ', 'বলে দাও-হে মানবকুল, তোমরা যদি আমার দ্বীনের ব্যাপারে সন্দিহান হয়ে থাক, তবে (জেনো) আমি তাদের এবাদত করি না যাদের এবাদত তোমরা কর আল্লাহ ব্যতীত। কিন্তু আমি এবাদত করি আল্লাহ ত’য়ালার, যিনি তুলে নেন তোমাদেরকে। আর আমার প্রতি নির্দেশ হয়েছে যাতে আমি ঈমানদারদের অন্তর্ভুক্ত থাকি।', 'Qul ya ayyuha alnnasu in kuntum fee shakkin min deenee fala aAAbudu allatheena taAAbudoona min dooni Allahi walakin aAAbudu Allaha allathee yatawaffakum waomirtu an akoona mina almumineena', 1, NOW(), NOW()),
(15, 105, 'وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ', 'আর যেন সোজা দ্বীনের প্রতি মুখ করি সরল হয়ে এবং যেন মুশরেকদের অন্তর্ভুক্ত না হই।', 'Waan aqim wajhaka lilddeeni haneefan wala takoonanna mina almushrikeena', 1, NOW(), NOW()),
(15, 106, 'وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّـٰلِمِينَ', 'আর নির্দেশ হয়েছে আল্লাহ ব্যতীত এমন কাউকে ডাকবে না, যে তোমার ভাল করবে না মন্দও করবে না। বস্তুতঃ তুমি যদি এমন কাজ কর, তাহলে তখন তুমিও জালেমদের অন্তর্ভুক্ত হয়ে যাবে।', 'Wala tadAAu min dooni Allahi ma la yanfaAAuka wala yadurruka fain faAAalta fainnaka ithan mina alththalimeena', 1, NOW(), NOW()),
(15, 107, 'وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ', 'আর আল্লাহ যদি তোমার উপর কোন কষ্ট আরোপ করেন তাহলে কেউ নেই তা খন্ডাবার মত তাঁকে ছাড়া। পক্ষান্তরে যদি তিনি কিছু কল্যাণ দান করেন, তবে তার মেহেরবানীকে রহিত করার মতও কেউ নেই। তিনি যার প্রতি অনুগ্রহ দান করতে চান স্বীয় বান্দাদের মধ্যে তাকেই দান করেন; বস্তুত; তিনিই ক্ষমাশীল দয়ালু।', 'Wain yamsaska Allahu bidurrin fala kashifa lahu illa huwa wain yuridka bikhayrin fala radda lifadlihi yuseebu bihi man yashao min AAibadihi wahuwa alghafooru alrraheemu', 1, NOW(), NOW()),
(15, 108, 'قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنَا۠ عَلَيۡكُم بِوَكِيلٖ', 'বলে দাও, হে মানবকুল, সত্য তোমাদের কাছে পৌঁছে গেছে তোমাদের পরওয়ারদেগারের তরফ থেকে। এমন যে কেউ পথে আসে সেপথ প্রাপ্ত হয় স্বীয় মঙ্গলের জন্য। আর যে বিভ্রান্ত ঘুরতে থাকে, সে স্বীয় অমঙ্গলের জন্য বিভ্রান্ত অবস্থায় ঘুরতে থাকবে। অনন্তর আমি তোমাদের উপর অধিকারী নই।', 'Qul ya ayyuha alnnasu qad jaakumu alhaqqu min rabbikum famani ihtada fainnama yahtadee linafsihi waman dalla fainnama yadillu AAalayha wama ana AAalaykum biwakeelin', 1, NOW(), NOW()),
(15, 109, 'وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ', 'আর তুমি চল সে অনুযায়ী যেমন নির্দেশ আসে তোমার প্রতি এবং সবর কর, যতক্ষণ না ফয়সালা করেন আল্লাহ। বস্তুতঃ তিনি হচ্ছেন সর্বোত্তম ফয়সালাকারী।', 'WaittabiAA ma yooha ilayka waisbir hatta yahkuma Allahu wahuwa khayru alhakimeena', 1, NOW(), NOW()),
(16, 1, 'الٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ', 'আলিফ, লা-ম, রা; এটি এমন এক কিতাব, যার আয়াত সমূহ সুপ্রতিষ্ঠিত অতঃপর সবিস্তারে বর্ণিত এক মহাজ্ঞানী, সর্বজ্ঞ সত্তার পক্ষ হতে।', 'Aliflamra kitabun ohkimat ayatuhu thumma fussilat min ladun hakeemin khabeerin', 1, NOW(), NOW()),
(16, 2, 'أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ إِنَّنِي لَكُم مِّنۡهُ نَذِيرٞ وَبَشِيرٞ', 'যেন তোমরা আল্লাহ ব্যতীত অন্য কারো বন্দেগী না কর। নিশ্চয় আমি তোমাদের প্রতি তাঁরই পক্ষ হতে সতর্ককারী ও সুসংবাদ দাতা।', 'Alla taAAbudoo illa Allaha innanee lakum minhu natheerun wabasheerun', 1, NOW(), NOW()),
(16, 3, 'وَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ', 'আর তোমরা নিজেদের পালনকর্তা সমীপে ক্ষমা প্রার্থনা কর। অনন্তর তাঁরই প্রতি মনোনিবেশ কর। তাহলে তিনি তোমাদেরকে নির্দিষ্ট সময় পর্যন্ত উৎকৃষ্ট জীবনোপকরণ দান করবেন এবং অধিক আমলকারীকে বেশী করে দেবেন আর যদি তোমরা বিমুখ হতে থাক, তবে আমি তোমাদের উপর এক মহা দিবসের আযাবের আশঙ্কা করছি।', 'Waani istaghfiroo rabbakum thumma tooboo ilayhi yumattiAAkum mataAAan hasanan ila ajalin musamman wayuti kulla thee fadlin fadlahu wain tawallaw fainee akhafu AAalaykum AAathaba yawmin kabeerin', 1, NOW(), NOW()),
(16, 4, 'إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'আল্লাহর সান্নিধ্যেই তোমাদেরকে ফিরে যেতে হবে। আর তিনি সব কিছুর উপর ক্ষমতাবান।', 'Ila Allahi marjiAAukum wahuwa AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(16, 5, 'أَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'জেনে রাখ, নিশ্চয়ই তারা নিজেদের বক্ষদেশ ঘুরিয়ে দেয় যেন আল্লাহর নিকট হতে লুকাতে পারে। শুন, তারা তখন কাপড়ে নিজেদেরকে আচ্ছাদিত করে, তিনি তখনও জানেন যা কিছু তারা চুপিসারে বলে আর প্রকাশ্যভাবে বলে। নিশ্চয় তিনি জানেন যা কিছু অন্তর সমূহে নিহিত রয়েছে।', 'Ala innahum yathnoona sudoorahum liyastakhfoo minhu ala heena yastaghshoona thiyabahum yaAAlamu ma yusirroona wama yuAAlinoona innahu AAaleemun bithati alssudoori', 1, NOW(), NOW()),
(16, 6, '۞وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ', 'আর পৃথিবীতে কোন বিচরণশীল নেই, তবে সবার জীবিকার দায়িত্ব আল্লাহ নিয়েছেন তিনি জানেন তারা কোথায় থাকে এবং কোথায় সমাপিত হয়। সবকিছুই এক সুবিন্যস্ত কিতাবে রয়েছে।', 'Wama min dabbatin fee alardi illa AAala Allahi rizquha wayaAAlamu mustaqarraha wamustawdaAAaha kullun fee kitabin mubeenin', 1, NOW(), NOW()),
(16, 7, 'وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ', 'তিনিই আসমান ও যমীন ছয় দিনে তৈরী করেছেন, তাঁর আরশ ছিল পানির উপরে, তিনি তোমাদেরকে পরীক্ষা করতে চান যে, তোমাদের মধ্যে কে সবচেয়ে ভাল কাজ করে। আর যদি আপনি তাদেরকে বলেন যে, "নিশ্চয় তোমাদেরকে মৃত্যুর পরে জীবিত ওঠানো হবে, তখন কাফেরেরা অবশ্য বলে এটা তো স্পষ্ট যাদু', 'Wahuwa allathee khalaqa alssamawati waalarda fee sittati ayyamin wakana AAarshuhu AAala almai liyabluwakum ayyukum ahsanu AAamalan walain qulta innakum mabAAoothoona min baAAdi almawti layaqoolanna allatheena kafaroo in hatha illa sihrun mubeenun', 1, NOW(), NOW()),
(16, 8, 'وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰٓ أُمَّةٖ مَّعۡدُودَةٖ لَّيَقُولُنَّ مَا يَحۡبِسُهُۥٓۗ أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'আর যদি আমি এক নির্ধারিত মেয়াদ পর্যন্ত তাদের আযাব স্থগিত রাখি, তাহলে তারা নিশ্চয়ই বলবে কোন জিনিসে আযাব ঠেকিয়ে রাখছে? শুনে রাখ, যেদিন তাদের উপর আযাব এসে পড়বে, সেদিন কিন্তু তা ফিরে যাওয়ার নয়; তারা যে ব্যাপারে উপহাস করত তাই তাদেরকে ঘিরে ফেলবে।', 'Walain akhkharna AAanhumu alAAathaba ila ommatin maAAdoodatin layaqoolunna ma yahbisuhu ala yawma yateehim laysa masroofan AAanhum wahaqa bihim ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(16, 9, 'وَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ', 'আর অবশ্যই যদি আমি মানুষকে আমার রহমতের আস্বাদ গ্রহণ করতে দেই, অতঃপর তা তার থেকে ছিনিয়ে নেই; তাহলে সে হতাশ ও কৃতঘ্ন হয়।', 'Walain athaqna alinsana minna rahmatan thumma nazaAAnaha minhu innahu layaoosun kafoorun', 1, NOW(), NOW()),
(16, 10, 'وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ', 'আর যদি তার উপর আপতিত দুঃখ কষ্টের পরে তাকে সুখভোগ করতে দেই, তবে সে বলতে থাকে যে, আমার অমঙ্গল দূর হয়ে গেছে, আর সে আনন্দে আত্নহারা হয়, অহঙ্কারে উদ্দত হয়ে পড়ে।', 'Walain athaqnahu naAAmaa baAAda darraa massathu layaqoolanna thahaba alssayyiatu AAannee innahu lafarihun fakhoorun', 1, NOW(), NOW()),
(16, 11, 'إِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ', 'তবে যারা ধৈর্য্যধারণ করেছে এবং সৎকার্য করেছে তাদের জন্য ক্ষমা ও বিরাট প্রতিদান রয়েছে।', 'Illa allatheena sabaroo waAAamiloo alssalihati olaika lahum maghfiratun waajrun kabeerun', 1, NOW(), NOW()),
(16, 12, 'فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ إِنَّمَآ أَنتَ نَذِيرٞۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ', 'আর সম্ভবতঃ ঐসব আহকাম যা ওহীর মাধ্যমে তোমার নিকট পাঠানো হয়, তার কিছু অংশ বর্জন করবে? এবং এতে মন ছোট করে বসবে? তাদের এ কথায় যে, তাঁর উপর কোন ধন-ভান্ডার কেন অবতীর্ণ হয়নি? অথবা তাঁর সাথে কোন ফেরেশতা আসেনি কেন? তুমিতো শুধু সতর্ককারী মাত্র; আর সব কিছুরই দায়িত্বভার তো আল্লাহই নিয়েছেন।', 'FalaAAallaka tarikun baAAda ma yooha ilayka wadaiqun bihi sadruka an yaqooloo lawla onzila AAalayhi kanzun aw jaa maAAahu malakun innama anta natheerun waAllahu AAala kulli shayin wakeelun', 1, NOW(), NOW()),
(16, 13, 'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ', 'তারা কি বলে? কোরআন তুমি তৈরী করেছ? তুমি বল, তবে তোমরাও অনুরূপ দশটি সূরা তৈরী করে নিয়ে আস এবং আল্লাহ ছাড়া যাকে পার ডেকে নাও, যদি তোমাদের কথা সত্য হয়ে থাকে।', 'Am yaqooloona iftarahu qul fatoo biAAashri suwarin mithlihi muftarayatin waodAAoo mani istataAAtum min dooni Allahi in kuntum sadiqeena', 1, NOW(), NOW()),
(16, 14, 'فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ', 'অতঃপর তারা যদি তোমাদের কথা পুরণ করতে অপারগ হয়; তবে জেনে রাখ, এটি আল্লাহর এলম দ্বারা অবতীর্ণ হয়েছে; আরো একীন করে নাও যে, আল্লাহ ব্যতীত অন্য কোন মাবুদ নেই। অতএব, এখন কি তোমরা আত্নসমর্পন করবে', 'Fai llam yastajeeboo lakum faiAAlamoo annama onzila biAAilmi Allahi waan la ilaha illa huwa fahal antum muslimoona', 1, NOW(), NOW()),
(16, 15, 'مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ', 'যে ব্যক্তি পার্থিবজীবন ও তার চাকচিক্যই কামনা করে, হয় আমি তাদের দুনিয়াতেই তাদের আমলের প্রতিফল ভোগ করিয়ে দেব এবং তাতে তাদের প্রতি কিছুমাত্র কমতি করা হয় না।', 'Man kana yureedu alhayata alddunya wazeenataha nuwaffi ilayhim aAAmalahum feeha wahum feeha la yubkhasoona', 1, NOW(), NOW()),
(16, 16, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ', 'এরাই হল সেসব লোক আখেরাতে যাদের জন্য আগুন ছাড়া নেই। তারা এখানে যা কিছু করেছিল সবই বরবাদ করেছে; আর যা কিছু উপার্জন করেছিল, সবই বিনষ্ট হল।', 'Olaika allatheena laysa lahum fee alakhirati illa alnnaru wahabita ma sanaAAoo feeha wabatilun ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(16, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَـٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ وَمَن يَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِي مِرۡيَةٖ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ', 'আচ্ছা বল তো, যে ব্যক্তি তার প্রভুর সুস্পষ্ট পথে রয়েছে, আর সাথে সাথে আল্লাহর তরফ থেকে একটি সাক্ষীও বর্তমান রয়েছে এবং তার পূর্ববর্তী মূসা (আঃ) এর কিতাবও সাক্ষী যা ছিল পথনির্দেশক ও রহমত স্বরূপ, (তিনি কি অন্যান্যের সমান) অতএব তাঁরা কোরআনের প্রতি ঈমান আনেন। আর ঐসব দলগুলি যে কেউ তা অস্বীকার করে, দোযখই হবে তার ঠিকানা। অতএব, আপনি তাতে কোন সন্দেহে থাকবেন না। নিঃসন্দেহে তা আপনার পালনকর্তার পক্ষ হতে ধ্রুব সত্য; তথাপি অনেকেই তা বিশ্বাস করে না।', 'Afaman kana AAala bayyinatin min rabbihi wayatloohu shahidun minhu wamin qablihi kitabu moosa imaman warahmatan olaika yuminoona bihi waman yakfur bihi mina alahzabi faalnnaru mawAAiduhu fala taku fee miryatin minhu innahu alhaqqu min rabbika walakinna akthara alnnasi la yuminoona', 1, NOW(), NOW()),
(16, 18, 'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُوْلَـٰٓئِكَ يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَيَقُولُ ٱلۡأَشۡهَٰدُ هَـٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُواْ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ', 'আর তাদের চেয়ে বড় যালেম কে হতে পারে, যারা আল্লাহর প্রতি মিথ্যারোপ করে। এসব লোককে তাদের পালনকর্তার সাক্ষাত সম্মূখীন করা হবে আর সাক্ষিগণ বলতে থাকবে, এরাই ঐসব লোক, যারা তাদের পালনকর্তার প্রতি মিথ্যারোপ করেছিল। শুনে রাখ, যালেমদের উপর আল্লাহর অভিসম্পাত রয়েছে।', 'Waman athlamu mimmani iftara AAala Allahi kathiban olaika yuAAradoona AAala rabbihim wayaqoolu alashhadu haolai allatheena kathaboo AAala rabbihim ala laAAnatu Allahi AAala alththalimeena', 1, NOW(), NOW()),
(16, 19, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ', 'যারা আল্লাহর পথে বাধা দেয়, আর তাতে বক্রতা খুজে বেড়ায়, এরাই আখরাতকে অস্বীকার করে।', 'Allatheena yasuddoona AAan sabeeli Allahi wayabghoonaha AAiwajan wahum bialakhirati hum kafiroona', 1, NOW(), NOW()),
(16, 20, 'أُوْلَـٰٓئِكَ لَمۡ يَكُونُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَۘ يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ', 'তারা পৃথিবীতেও আল্লাহকে অপারগ করতে পারবে না এবং আল্লাহ ব্যতীত তাদের কোন সাহায্যকারীও নেই, তাদের জন্য দ্বিগুণ শাস্তি রয়েছে; তারা শুনতে পারত না এবং দেখতেও পেত না।', 'Olaika lam yakoonoo muAAjizeena fee alardi wama kana lahum min dooni Allahi min awliyaa yudaAAafu lahumu alAAathabu ma kanoo yastateeAAoona alssamAAa wama kanoo yubsiroona', 1, NOW(), NOW()),
(16, 21, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', 'এরা সে লোক, যারা নিজেরাই নিজেদেরকে ক্ষতিগ্রস্ত করেছে, আর এরা যা কিছু মিথ্যা মা’বুদ সাব্যস্ত করেছিল, তা সবই তাদের থেকে হারিয়ে গেছে।', 'Olaika allatheena khasiroo anfusahum wadalla AAanhum ma kanoo yaftaroona', 1, NOW(), NOW()),
(16, 22, 'لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ', 'আখেরাতে এরাই হবে সর্বাধিক ক্ষতিগ্রস্থ কোন সন্দেহ নেই।', 'La jarama annahum fee alakhirati humu alakhsaroona', 1, NOW(), NOW()),
(16, 23, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'নিশ্চয়ই যারা ঈমান এনেছে ও সৎকাজ করেছে এবং স্বীয় পালনকর্তার সমীপে বিনতি প্রকাশ করেছে তারাই বেহেশতবাসী, সেখানেই তারা চিরকাল থাকবে।', 'Inna allatheena amanoo waAAamiloo alsalihati waakhbatoo ila rabbihim olaika ashabu aljannati hum feeha khalidoona', 1, NOW(), NOW()),
(16, 24, '۞مَثَلُ ٱلۡفَرِيقَيۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِيرِ وَٱلسَّمِيعِۚ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ', 'উভয় পক্ষের দৃষ্টান্ত হচ্ছে যেমন অন্ধ ও বধির এবং যে দেখতে পায় ও শুনতে পায় উভয়ের অবস্থা কি এক সমান? তবুও তোমরা কি ভেবে দেখ না', 'Mathalu alfareeqayni kaalaAAma waalasammi waalbaseeri waalssameeAAi hal yastawiyani mathalan afala tathakkaroona', 1, NOW(), NOW()),
(16, 25, 'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ', 'আর অবশ্যই আমি নূহ (আঃ) কে তাঁর জাতির প্রতি প্রেরণ করেছি, (তিনি বললেন) নিশ্চয় আমি তোমাদের জন্য প্রকাশ্য সতর্ককারী।', 'Walaqad arsalna noohan ila qawmihi innee lakum natheerun mubeenun', 1, NOW(), NOW()),
(16, 26, 'أَن لَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَلِيمٖ', 'তোমরা আল্লাহ ব্যতীত কারো এবাদত করবে না। নিশ্চয় আমি তোমাদের ব্যাপারে এক যন্ত্রণাদায়ক দিনের আযাবের ভয় করছি।', 'An la taAAbudoo illa Allaha innee akhafu AAalaykum AAathaba yawmin aleemin', 1, NOW(), NOW()),
(16, 27, 'فَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ', 'তখন তাঁর কওমের কাফের প্রধানরা বলল আমরা তো আপনাকে আমাদের মত একজন মানুষ ব্যতীত আর কিছু মনে করি না; আর আমাদের মধ্যে যারা ইতর ও স্থুল-বুদ্ধিসম্পন্ন তারা ব্যতীত কাউকে তো আপনার আনুগত্য করতে দেখি না এবং আমাদের উপর আপনাদের কেন প্রাধান্য দেখি না, বরং আপনারা সবাই মিথ্যাবাদী বলে আমারা মনে করি।', 'Faqala almalao allatheena kafaroo min qawmihi ma naraka illa basharan mithlana wama naraka ittabaAAaka illa allatheena hum arathiluna badiya alrrayi wama nara lakum AAalayna min fadlin bal nathunnukum kathibeena', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(16, 28, 'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ', 'নূহ (আঃ) বললেন-হে আমার জাতি! দেখ তো আমি যদি আমার পালনকর্তার পক্ষ হতে স্পষ্ট দলীলের উপর থাক, আর তিনি যদি তাঁর পক্ষ হতে আমাকে রহমত দান করে থাকেন, তারপরেও তা তোমাদের চোখে না পড়ে, তাহলে আমি কি উহা তোমাদের উপর তোমাদের ইচ্ছার বিরুদ্ধেই চাপিয়ে দিতে পারি', 'Qala ya qawmi araaytum in kuntu AAala bayyinatin min rabbee waatanee rahmatan min AAindihi faAAummiyat AAalaykum anulzimukumooha waantum laha karihoona', 1, NOW(), NOW()),
(16, 29, 'وَيَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مَالًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ', 'আর হে আমার জাতি! আমি তো এজন্য তোমাদের কাছে কোন অর্থ চাই না; আমার পারিশ্রমিক তো আল্লাহর জিম্মায় রয়েছে। আমি কিন্তু ঈমানদারদের তাড়িয়ে দিতে পারি না। তারা অবশ্যই তাদের পালনকর্তার সাক্ষাত লাভ করবে। বরঞ্চ তোমাদেরই আমি অজ্ঞ সম্প্রদায় দেখছি।', 'Waya qawmi la asalukum AAalayhi malan in ajriya illa AAala Allahi wama ana bitaridi allatheena amanoo innahum mulaqoo rabbihim walakinnee arakum qawman tajhaloona', 1, NOW(), NOW()),
(16, 30, 'وَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ', 'আর হে আমার জাতি! আমি যদি তাদের তাড়িয়ে দেই তাহলে আমাকে আল্লাহ হতে রেহাই দেবে কে? তোমরা কি চিন্তা করে দেখ না', 'Waya qawmi man yansurunee mina Allahi in taradtuhum afala tathakkaroona', 1, NOW(), NOW()),
(16, 31, 'وَلَآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ إِنِّي مَلَكٞ وَلَآ أَقُولُ لِلَّذِينَ تَزۡدَرِيٓ أَعۡيُنُكُمۡ لَن يُؤۡتِيَهُمُ ٱللَّهُ خَيۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِيٓ أَنفُسِهِمۡ إِنِّيٓ إِذٗا لَّمِنَ ٱلظَّـٰلِمِينَ', 'আর আমি তোমাদেরকে বলি না যে, আমার কাছে আল্লাহর ভান্ডার রয়েছে এবং একথাও বলি না যে, আমি গায়বী খবরও জানি; একথাও বলি না যে, আমি একজন ফেরেশতা; আর তোমাদের দৃষ্টিতে যারা লাঞ্ছিত আল্লাহ তাদের কোন কল্যাণ দান করবেন না। তাদের মনের কথা আল্লাহ ভাল করেই জানেন। সুতরাং এমন কথা বললে আমি অন্যায় কারী হব।', 'Wala aqoolu lakum AAindee khazainu Allahi wala aAAlamu alghayba wala aqoolu innee malakun wala aqoolu lillatheena tazdaree aAAyunukum lan yutiyahumu Allahu khayran Allahu aAAlamu bima fee anfusihim innee ithan lamina alththalimeena', 1, NOW(), NOW()),
(16, 32, 'قَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'তারা বলল-হে নূহ! আমাদের সাথে আপনি তর্ক করেছেন এবং অনেক কলহ করেছেন। এখন আপনার সেই আযাব নিয়ে আসুন, যে সম্পর্কে আপনি আমাদিগকে সতর্ক করেছেন, যদি আপনি সত্যবাদী হয়ে থাকেন।', 'Qaloo ya noohu qad jadaltana faaktharta jidalana fatina bima taAAiduna in kunta mina alssadiqeena', 1, NOW(), NOW()),
(16, 33, 'قَالَ إِنَّمَا يَأۡتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعۡجِزِينَ', 'তিনি বলেন, উহা তোমাদের কাছে আল্লাহই আনবেন, যদি তিনি ইচ্ছা করেন তখন তোমরা পালিয়ে তাঁকে অপারগ করতে পারবে না।', 'Qala innama yateekum bihi Allahu in shaa wama antum bimuAAjizeena', 1, NOW(), NOW()),
(16, 34, 'وَلَا يَنفَعُكُمۡ نُصۡحِيٓ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغۡوِيَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَعُونَ', 'আর আমি তোমাদের নসীহত করতে চাইলেও তা তোমাদের জন্য ফলপ্রসূ হবে না, যদি আল্লাহ তোমাদেরকে গোমরাহ করতে চান; তিনিই তোমাদের পালনকর্তা এবং তাঁর কাছেই তোমাদের ফিরে যেতে হবে।', 'Wala yanfaAAukum nushee in aradtu an ansaha lakum in kana Allahu yureedu an yughwiyakum huwa rabbukum wailayhi turjaAAoona', 1, NOW(), NOW()),
(16, 35, 'أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَعَلَيَّ إِجۡرَامِي وَأَنَا۠ بَرِيٓءٞ مِّمَّا تُجۡرِمُونَ', 'তারা কি বলে? আপনি কোরআন রচনা করে এনেছেন? আপনি বলে দিন আমি যদি রচনা করে এনে থাকি, তবে সে অপরাধ আমার, আর তোমরা যেসব অপরাধ কর তার সাথে আমার কোন সম্পর্ক নেই।', 'Am yaqooloona iftarahu qul ini iftaraytuhu faAAalayya ijramee waana bareeon mimma tujrimoona', 1, NOW(), NOW()),
(16, 36, 'وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ', 'আর নূহ (আঃ) এর প্রতি ওহী প্রেরণ করা হলো যে, যারা ইতিমধ্যেই ঈমান এনেছে তাদের ছাড়া আপনার জাতির অন্য কেউ ঈমান আনবেনা এতএব তাদের কার্যকলাপে বিমর্ষ হবেন না।', 'Waoohiya ila noohin annahu lan yumina min qawmika illa man qad amana fala tabtais bima kanoo yafAAaloona', 1, NOW(), NOW()),
(16, 37, 'وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ', 'আর আপনি আমার সম্মুখে আমারই নির্দেশ মোতাবেক একটি নৌকা তৈরী করুন এবং পাপিষ্ঠদের ব্যাপারে আমাকে কোন কথা বলবেন না। অবশ্যই তারা ডুবে মরবে।', 'WaisnaAAi alfulka biaAAyunina wawahyina wala tukhatibnee fee allatheena thalamoo innahum mughraqoona', 1, NOW(), NOW()),
(16, 38, 'وَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ', 'তিনি নৌকা তৈরী করতে লাগলেন, আর তাঁর কওমের নেতৃস্থানীয় ব্যক্তিরা যখন পার্শ্ব দিয়ে যেত, তখন তাঁকে বিদ্রুপ করত। তিনি বললেন, তোমরা যদি আমাদের উপহাস করে থাক, তবে তোমরা যেমন উপহাস করছ আমরাও তদ্রুপ তোমাদের উপহাস করছি।', 'WayasnaAAu alfulka wakullama marra AAalayhi malaon min qawmihi sakhiroo minhu qala in taskharoo minna fainna naskharu minkum kama taskharoona', 1, NOW(), NOW()),
(16, 39, 'فَسَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ', 'অতঃপর অচিরেই জানতে পারবে-লাঞ্ছনাজনক আযাব কার উপর আসে এবং চিরস্থায়ী আযাব কার উপর অবতরণ করে।', 'Fasawfa taAAlamoona man yateehi AAathabun yukhzeehi wayahillu AAalayhi AAathabun muqeemun', 1, NOW(), NOW()),
(16, 40, 'حَتَّىٰٓ إِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ', 'অবশেষে যখন আমার হুকুম এসে পৌঁছাল এবং ভুপৃষ্ঠ উচ্ছসিত হয়ে উঠল, আমি বললামঃ সর্বপ্রকার জোড়ার দুটি করে এবং যাদের উপরে পূর্বহেߦ#2439; হুকুম হয়ে গেছে তাদের বাদি দিয়ে, আপনার পরিজনবর্গ ও সকল ঈমানদারগণকে নৌকায় তুলে নিন। বলাবাহুল্য অতি অল্পসংখ্যক লোকই তাঁর সাথে ঈমান এনেছিল।', 'Hatta itha jaa amruna wafara alttannooru qulna ihmil feeha min kullin zawjayni ithnayni waahlaka illa man sabaqa AAalayhi alqawlu waman amana wama amana maAAahu illa qaleelun', 1, NOW(), NOW()),
(16, 41, '۞وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ', 'আর তিনি বললেন, তোমরা এতে আরোহন কর। আল্লাহর নামেই এর গতি ও স্থিতি। আমার পালনকর্তা অতি ক্ষমাপরায়ন, মেহেরবান।', 'Waqala irkaboo feeha bismi Allahi majraha wamursaha inna rabbee laghafoorun raheemun', 1, NOW(), NOW()),
(16, 42, 'وَهِيَ تَجۡرِي بِهِمۡ فِي مَوۡجٖ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِي مَعۡزِلٖ يَٰبُنَيَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَٰفِرِينَ', 'আর নৌকাখানি তাদের বহন করে চলল পর্বত প্রমাণ তরঙ্গমালার মাঝে, আর নূহ (আঃ) তাঁর পুত্রকে ডাক দিলেন আর সে সরে রয়েছিল, তিনি বললেন, প্রিয় বৎস! আমাদের সাথে আরোহন কর এবং কাফেরদের সাথে থেকো না।', 'Wahiya tajree bihim fee mawjin kaaljibali wanada noohunu ibnahu wakana fee maAAzilin ya bunayya irkab maAAana wala takun maAAa alkafireena', 1, NOW(), NOW()),
(16, 43, 'قَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَيۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِينَ', 'সে বলল, আমি অচিরেই কোন পাহাড়ে আশ্রয় নেব, যা আমাকে পানি হতে রক্ষা করবে। নূহ (আঃ) বল্লেন আজকের দিনে আল্লাহর হুকুম থেকে কোন রক্ষাকারী নেই। একমাত্র তিনি যাকে দয়া করবেন। এমন সময় উভয়ের মাঝে তরঙ্গ আড়াল হয়ে দাঁড়াল, ফলে সে নিমজ্জিত হল।', 'Qala saawee ila jabalin yaAAsimunee mina almai qala la AAasima alyawma min amri Allahi illa man rahima wahala baynahuma almawju fakana mina almughraqeena', 1, NOW(), NOW()),
(16, 44, 'وَقِيلَ يَـٰٓأَرۡضُ ٱبۡلَعِي مَآءَكِ وَيَٰسَمَآءُ أَقۡلِعِي وَغِيضَ ٱلۡمَآءُ وَقُضِيَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِيِّۖ وَقِيلَ بُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'আর নির্দেশ দেয়া হল-হে পৃথিবী! তোমার পানি গিলে ফেল, আর হে আকাশ, ক্ষান্ত হও। আর পানি হ্রাস করা হল এবং কাজ শেষ হয়ে গেল, আর জুদী পর্বতে নৌকা ভিড়ল এবং ঘোষনা করা হল, দুরাত্না কাফেররা নিপাত যাক।', 'Waqeela ya ardu iblaAAee maaki waya samao aqliAAee wagheeda almao waqudiya alamru waistawat AAala aljoodiyyi waqeela buAAdan lilqawmi alththalimeena', 1, NOW(), NOW()),
(16, 45, 'وَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ', 'আর নূহ (আঃ) তাঁর পালনকর্তাকে ডেকে বললেন-হে পরওয়ারদেগার, আমার পুত্র তো আমার পরিজনদের অন্তর্ভুক্ত; আর আপনার ওয়াদাও নিঃসন্দেহে সত্য আর আপনিই সর্বাপেক্ষা বিজ্ঞ ফয়সালাকারী।', 'Wanada noohun rabbahu faqala rabbi inna ibnee min ahlee wainna waAAdaka alhaqqu waanta ahkamu alhakimeena', 1, NOW(), NOW()),
(16, 46, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ', 'আল্লাহ বলেন, হে নূহ! নিশ্চয় সে আপনার পরিবারভুক্ত নয়। নিশ্চই সে দুরাচার! সুতরাং আমার কাছে এমন দরখাস্ত করবেন না, যার খবর আপনি জানেন না। আমি আপনাকে উপপদেশ দিচ্ছি যে, আপনি অজ্ঞদের দলভুক্ত হবেন না।', 'Qala ya noohu innahu laysa min ahlika innahu AAamalun ghayru salihin fala tasalni ma laysa laka bihi AAilmun innee aAAithuka an takoona mina aljahileena', 1, NOW(), NOW()),
(16, 47, 'قَالَ رَبِّ إِنِّيٓ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞۖ وَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ', 'নূহ (আঃ) বলেন-হে আমার পালনকর্তা আমার যা জানা নেই এমন কোন দরখাস্ত করা হতে আমি আপনার কাছেই আশ্রয় প্রার্থনা করছি। আপনি যদি আমাকে ক্ষমা না করেন, দয়া না করেন, তাহলে আমি ক্ষতিগ্রস্ত হব।', 'Qala rabbi innee aAAoothu bika an asalaka ma laysa lee bihi AAilmun wailla taghfir lee watarhamnee akun mina alkhasireena', 1, NOW(), NOW()),
(16, 48, 'قِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ وَأُمَمٞ سَنُمَتِّعُهُمۡ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٞ', 'হুকুম হল-হে নূহ (আঃ)! আমার পক্ষ হতে নিরাপত্তা এবং আপনার নিজের ও সঙ্গীয় সম্প্রদায়গুলির উপর বরকত সহকারে অবতরণ করুণ। আর অন্যান্য যেসব সম্প্রদায় রয়েছে আমি তাদের কেও উপকৃত হতে দেব। অতঃপর তাদের উপর আমার দরুন আযাব আপতিত হবে।', 'Qeela ya noohu ihbit bisalamin minna wabarakatin AAalayka waAAala omamin mimman maAAaka waomamun sanumattiAAuhum thumma yamassuhum minna AAathabun aleemun', 1, NOW(), NOW()),
(16, 49, 'تِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ', 'এটি গায়বের খবর, আমি আপনার প্রতি ওহী প্রেরন করছি। ইতিপূর্বে এটা আপনার এবং আপনার জাতির জানা ছিল না। আপনি ধৈর্য্যধারণ করুন। যারা ভয় করে চলে, তাদের পরিণাম ভাল, সন্দেহ নেই।', 'Tilka min anbai alghaybi nooheeha ilayka ma kunta taAAlamuha anta wala qawmuka min qabli hatha faisbir inna alAAaqibata lilmuttaqeena', 1, NOW(), NOW()),
(16, 50, 'وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ', 'আর আদ জাতির প্রতি আমি তাদের ভাই হুদকে প্রেরণ করেছি; তিনি বলেন-হে আমার জাতি, আল্লাহর বন্দেগী কর, তিনি ভিন্ন তোমাদের কোন মাবুদ নেই, তোমরা সবাই মিথ্যা আরোপ করছ।', 'Waila AAadin akhahum hoodan qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu in antum illa muftaroona', 1, NOW(), NOW()),
(16, 51, 'يَٰقَوۡمِ لَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱلَّذِي فَطَرَنِيٓۚ أَفَلَا تَعۡقِلُونَ', 'হে আমার জাতি! আমি এজন্য তোমাদের কাছে কোন মজুরী চাই না; আমার মজুরী তাঁরই কাছে যিনি আমাকে পয়দা করেছেন; তবু তোমরা কেন বোঝ না', 'Ya qawmi la asalukum AAalayhi ajran in ajriya illa AAala allathee fataranee afala taAAqiloona', 1, NOW(), NOW()),
(16, 52, 'وَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ', 'আর হে আমার কওম! তোমাদের পালন কর্তার কাছে তোমরা ক্ষমা প্রার্থনা কর, অতঃপর তাঁরই প্রতি মনোনিবেশ কর; তিনি আসমান থেকে তোমাদের উপর বৃষ্টি ধারা প্রেরণ করবেন এবং তোমাদের শক্তির উপর শক্তি বৃদ্ধি করবেন, তোমরা কিন্তু অপরাধীদের মত বিমুখ হয়ো না।', 'Waya qawmi istaghfiroo rabbakum thumma tooboo ilayhi yursili alssamaa AAalaykum midraran wayazidkum quwwatan ila quwwatikum wala tatawallaw mujrimeena', 1, NOW(), NOW()),
(16, 53, 'قَالُواْ يَٰهُودُ مَا جِئۡتَنَا بِبَيِّنَةٖ وَمَا نَحۡنُ بِتَارِكِيٓ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِينَ', 'তারা বলল-হে হুদ, তুমি আমাদের কাছে কোন প্রমাণ নিয়ে আস নাই, আমরা তোমার কথায় আমাদের দেব-দেবীদের বর্জন করতে পারি না আর আমরা তোমার প্রতি ঈমান আনয়নকারীও নই।', 'Qaloo ya hoodu ma jitana bibayyinatin wama nahnu bitarikee alihatina AAan qawlika wama nahnu laka bimumineena', 1, NOW(), NOW()),
(16, 54, 'إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوٓءٖۗ قَالَ إِنِّيٓ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوٓاْ أَنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ', 'বরং আমরাও তো বলি যে, আমাদের কোন দেবতা তোমার উপরে শোচনীয় ভূত চাপিয়ে দিয়েছে। হুদ বললেন-আমি আল্লাহকে সাক্ষী করেছি আর তোমাও সাক্ষী থাক যে, আমার কোন সম্পর্ক নাই তাঁদের সাথে যাদের কে তোমরা শরিক করছ', 'In naqoolu illa iAAtaraka baAAdu alihatina bisooin qala innee oshhidu Allaha waishhadoo annee bareeon mimma tushrikoona', 1, NOW(), NOW()),
(16, 55, 'مِن دُونِهِۦۖ فَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ', 'তাকে ছাড়া, তোমরা সবাই মিলে আমার অনিষ্ট করার প্রয়াস চালাও, অতঃপর আমাকে কোন অবকাশ দিও না।', 'Min doonihi fakeedoonee jameeAAan thumma la tunthirooni', 1, NOW(), NOW()),
(16, 56, 'إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আমি আল্লাহর উপর নিশ্চিত ভরসা করেছি যিনি আমার এবং তোমাদের পরওয়ারদেগার। পৃথিবীর বুকে বিচরণকারী এমন কোন প্রাণী নাই যা তাঁর র্পূণ আয়ত্তাধীন নয়। আমার পালকর্তার সরল পথে সন্দেহ নেই।', 'Innee tawakkaltu AAala Allahi rabbee warabbikum ma min dabbatin illa huwa akhithun binasiyatiha inna rabbee AAala siratin mustaqeemin', 1, NOW(), NOW()),
(16, 57, 'فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ', 'তথাপি যদি তোমরা মুখ ফেরাও, তবে আমি তোমাদেরকে তা পৌছিয়েছি যা আমার কাছে তোমাদের প্রতি প্রেরিত হয়েছে; আর আমার পালনকর্তা অন্য কোন জাতিকে তোমাদের স্থলাভিষিক্ত করবেন, আর তোমরা তাঁর কিছুই বিগড়াতে পারবে না; নিশ্চয়ই আমার পরওয়ারদেগারই প্রতিটি বস্তুর হেফাজতকারী।', 'Fain tawallaw faqad ablaghtukum ma orsiltu bihi ilaykum wayastakhlifu rabbee qawman ghayrakum wala tadurroonahu shayan inna rabbee AAala kulli shayin hafeethun', 1, NOW(), NOW()),
(16, 58, 'وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ', 'আর আমার আদেশ যখন উপস্থিত হল, তখন আমি নিজ রহমতে হুদ এবং তাঁর সঙ্গী ঈমানদারগণকে পরিত্রাণ করি এবং তাদেরকে এক কঠিন শাস্তি থেকে রক্ষা করি।', 'Walamma jaa amruna najjayna hoodan waallatheena amanoo maAAahu birahmatin minna wanajjaynahum min AAathabin ghaleethin', 1, NOW(), NOW()),
(16, 59, 'وَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ', 'এ ছিল আদ জাতি, যারা তাদের পালনকর্তার আয়াতকে অমান্য করেছে, আর তদীয় রসূলগণের অবাধ্যতা করেছে এবং প্রত্যেক উদ্ধত বিরোধীদের আদেশ পালন করেছে।', 'Watilka AAadun jahadoo biayati rabbihim waAAasaw rusulahu waittabaAAoo amra kulli jabbarin AAaneedin', 1, NOW(), NOW()),
(16, 60, 'وَأُتۡبِعُواْ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ عَادٗا كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّعَادٖ قَوۡمِ هُودٖ', 'এ দুনিয়ায় তাদের পিছনে পিছনে লা’নত রয়েছে এবং কেয়ামতের দিনেও; জেনে রাখ, আদ জাতি তাদের পালনকর্তাকে অস্বীকার করেছে, হুদের জ্ঞাতি আদ জাতির প্রতি অভিসম্পাত রয়েছে জেনে রাখ।', 'WaotbiAAoo fee hathihi alddunya laAAnatan wayawma alqiyamati ala inna AAadan kafaroo rabbahum ala buAAdan liAAadin qawmi hoodin', 1, NOW(), NOW()),
(16, 61, '۞وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ', 'আর সামুদ জাতি প্রতি তাদের ভাই সালেহ কে প্রেরণ করি; তিনি বললেন, হে আমার জাতি। আল্লাহর বন্দেগী কর, তিনি ছাড়া তোমাদের কোন উপাস্য নাই। তিনিই যমীন হতে তোমাদেরকে পয়দা করেছেন, তন্মধ্যে তোমাদেরকে বসতি দান করেছেন। অতএব; তাঁর কাছে ক্ষমা প্রার্থনা কর অতঃপর তাঁরই দিকে ফিরে চল আমার পালনকর্তা নিকটেই আছেন, কবুল করে থাকেন; সন্দেহ নেই।', 'Waila thamooda akhahum salihan qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu huwa anshaakum mina alardi waistaAAmarakum feeha faistaghfiroohu thumma tooboo ilayhi inna rabbee qareebun mujeebun', 1, NOW(), NOW()),
(16, 62, 'قَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ أَتَنۡهَىٰنَآ أَن نَّعۡبُدَ مَا يَعۡبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِي شَكّٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ مُرِيبٖ', 'তারা বলল-হে সালেহ, ইতিপূর্বে তোমার কাছে আমাদের বড় আশা ছিল। আমাদের বাপ-দাদা যা পূজা করত তুমি কি আমাদেরকে তার পূজা করতে নিষেধ কর? কিন্তু যার প্রতি তুমি আমাদের আহবান জানাচ্ছ আমাদের তাতে এমন সন্দেহ রয়েছে যে, মন মোটেই সায় দিচ্ছে না।', 'Qaloo ya salihu qad kunta feena marjuwwan qabla hatha atanhana an naAAbuda ma yaAAbudu abaona wainnana lafee shakkin mimma tadAAoona ilayhi mureebun', 1, NOW(), NOW()),
(16, 63, 'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي مِنۡهُ رَحۡمَةٗ فَمَن يَنصُرُنِي مِنَ ٱللَّهِ إِنۡ عَصَيۡتُهُۥۖ فَمَا تَزِيدُونَنِي غَيۡرَ تَخۡسِيرٖ', 'সালেহ বললেন-হে আমার জাতি! তোমরা কি মনে কর, আমি যদি আমার পালনকর্তার পক্ষ হতে বুদ্ধি বিবেচনা লাভ করে থাকি আর তিনি যদি আমাকে নিজের তরফ হতে রহমত দান করে থাকেন, অতঃপর আমি যদি তাঁর অবাধ্য হই তবে তার থেকে কে আমায় রক্ষা করবে? তোমরা তো আমার ক্ষতি ছাড়া কিছুই বৃদ্ধি করতে পরবে না', 'Qala ya qawmi araaytum in kuntu AAala bayyinatin min rabbee waatanee minhu rahmatan faman yansurunee mina Allahi in AAasaytuhu fama tazeedoonanee ghayra takhseerin', 1, NOW(), NOW()),
(16, 64, 'وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ', 'আর হে আমার জাতি! আল্লাহর এ উষ্ট্রীটি তোমাদের জন্য নিদর্শন, অতএব তাকে আল্লাহর যমীনে বিচরণ করে খেতে দাও, এবং তাকে মন্দভাবে স্পর্শও করবে না। নতুবা অতি সত্বর তোমাদেরকে আযাব পাকড়াও করবে।', 'Waya qawmi hathihi naqatu Allahi lakum ayatan fatharooha takul fee ardi Allahi wala tamassooha bisooin fayakhuthakum AAathabun qareebun', 1, NOW(), NOW()),
(16, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ', 'তবু তারা উহার পা কেটে দিল। তখন সালেহ বললেন-তোমরা নিজেদের গৃহে তিনটি দিন উপভোগ করে নাও। ইহা এমন ওয়াদা যা মিথ্যা হবে না।', 'FaAAaqarooha faqala tamattaAAoo fee darikum thalathata ayyamin thalika waAAdun ghayru makthoobin', 1, NOW(), NOW()),
(16, 66, 'فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ', 'অতঃপর আমার আযাব যখন উপস্থিত হল, তখন আমি সালেহকে ও তদীয় সঙ্গী ঈমানদারগণকে নিজ রহমতে উদ্ধার করি, এবং সেদিনকার অপমান হতে রক্ষা করি। নিশ্চয় তোমার পালনকর্তা তিনি সর্বশক্তিমান পরাক্রমশালী।', 'Falamma jaa amruna najjayna salihan waallatheena amanoo maAAahu birahmatin minna wamin khizyi yawmiithin inna rabbaka huwa alqawiyyu alAAazeezu', 1, NOW(), NOW()),
(16, 67, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ', 'আর ভয়ঙ্কর গর্জন পাপিষ্ঠদের পাকড়াও করল, ফলে ভোর হতে না হতেই তারা নিজ নিজ গৃহসমূহে উপুর হয়ে পড়ে রইল।', 'Waakhatha allatheena thalamoo alssayhatu faasbahoo fee diyarihim jathimeena', 1, NOW(), NOW()),
(16, 68, 'كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدٗا لِّثَمُودَ', 'যেন তাঁরা কোনদিনই সেখানে ছিল না। জেনে রাখ, নিশ্চয় সামুদ জাতি তাদের পালনকর্তার প্রতি অস্বীকার করেছিল। আরো শুনে রাখ, সামুদ জাতির জন্য অভিশাপ রয়েছে।', 'Kaan lam yaghnaw feeha ala inna thamooda kafaroo rabbahum ala buAAdan lithamooda', 1, NOW(), NOW()),
(16, 69, 'وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ', 'আর অবশ্যই আমার প্রেরিত ফেরেশতারা ইব্রাহীমেরে কাছে সুসংবাদ নিয়ে এসেছিল তারা বলল সালাম, তিনিও বললেন-সালাম। অতঃপর অল্পক্ষণের মধ্যেই তিনি একটি ভুনা করা বাছুর নিয়ে এলেন', 'Walaqad jaat rusuluna ibraheema bialbushra qaloo salaman qala salamun fama labitha an jaa biAAijlin haneethin', 1, NOW(), NOW()),
(16, 70, 'فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ', 'কিন্তু যখন দেখলেন যে, আহার্য্যের দিকে তাদের হস্ত প্রসারিত হচ্ছে না, তখন তিনি সন্ধিগ্ধ হলেন এবং মনে মনে তাঁদের সম্পর্কে ভয় অনুভব করতে লাগলেন। তারা বলল-ভয় পাবেন না। আমরা লূতের কওমের প্রতি প্রেরিত হয়েছি।', 'Falamma raa aydiyahum la tasilu ilayhi nakirahum waawjasa minhum kheefatan qaloo la takhaf inna orsilna ila qawmi lootin', 1, NOW(), NOW()),
(16, 71, 'وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ', 'তাঁর স্ত্রীও নিকটেই দাড়িয়েছিল, সে হেসে ফেলল। অতঃপর আমি তাকে ইসহাকের জন্মের সুখবর দিলাম এবং ইসহাকের পরের ইয়াকুবেরও।', 'Waimraatuhu qaimatun fadahikat fabashsharnaha biishaqa wamin warai ishaqa yaAAqooba', 1, NOW(), NOW()),
(16, 72, 'قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ', 'সে বলল-কি দুর্ভাগ্য আমার! আমি সন্তান প্রসব করব? অথচ আমি বার্ধক্যের শেষ প্রান্তে এসে উপনীত হয়েছি আর আমার স্বামীও বৃদ্ধ, এতো ভারী আশ্চর্য কথা।', 'Qalat ya waylata aalidu waana AAajoozun wahatha baAAlee shaykhan inna hatha lashayon AAajeebun', 1, NOW(), NOW()),
(16, 73, 'قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ', 'তারা বলল-তুমি আল্লাহর হুকুম সম্পর্কে বিস্ময়বোধ করছ? হে গৃহবাসীরা, তোমাদের উপর আল্লাহর রহমত ও প্রভুত বরকত রয়েছে। নিশ্চয় আল্লাহ প্রশংসিত মহিমাময়।', 'Qaloo ataAAjabeena min amri Allahi rahmatu Allahi wabarakatuhu AAalaykum ahla albayti innahu hameedun majeedun', 1, NOW(), NOW()),
(16, 74, 'فَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ', 'অতঃপর যখন ইব্রাহীম (আঃ) এর আতঙ্ক দূর হল এবং তিনি সুসংবাদ প্রাপ্ত হলেন, তখন তিনি আমার সাথে তর্ক শুরু করলেন কওমে লূত সম্পর্কে।', 'Falamma thahaba AAan ibraheema alrrawAAu wajaathu albushra yujadiluna fee qawmi lootin', 1, NOW(), NOW()),
(16, 75, 'إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّـٰهٞ مُّنِيبٞ', 'ইব্রাহীম (আঃ) বড়ই ধৈর্য্যশীল, কোমল অন্তর, আল্লাহমুখী সন্দেহ নেই।', 'Inna ibraheema lahaleemun awwahun muneebun', 1, NOW(), NOW()),
(16, 76, 'يَـٰٓإِبۡرَٰهِيمُ أَعۡرِضۡ عَنۡ هَٰذَآۖ إِنَّهُۥ قَدۡ جَآءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡدُودٖ', 'ইব্রাহীম, এহেন ধারণা পরিহার কর; তোমার পালনকর্তার হুকুম এসে গেছে, এবং তাদের উপর সে আযাব অবশ্যই আপতিত হবে, যা কখনো প্রতিহত হবার নয়।', 'Ya ibraheemu aAArid AAan hatha innahu qad jaa amru rabbika wainnahum ateehim AAathabun ghayru mardoodin', 1, NOW(), NOW()),
(16, 77, 'وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ', 'আর যখন আমার প্রেরিত ফেরেশতাগণ লূত (আঃ) এর নিকট উপস্থিত হল। তখন তাঁদের আগমনে তিনি দুচিন্তাগ্রস্ত হলেন এবং তিনি বলতে লাগলেন, আজ অত্যন্ত কঠিন দিন।', 'Walamma jaat rusuluna lootan seea bihim wadaqa bihim tharAAan waqala hatha yawmun AAaseebun', 1, NOW(), NOW()),
(16, 78, 'وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَـٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ', 'আর তাঁর কওমের লোকেরা স্বতঃস্ফুর্তভাবে তার (গৃহ) পানে ছুটে আসতে লাগল। পূর্ব থেকেই তারা কু-কর্মে তৎপর ছিল। লূত (আঃ) বললেন-হে আমার কওম, এ আমার কন্যারা রয়েছে, এরা তোমাদের জন্য অধিক পবিত্রতমা। সুতরাং তোমরা আল্লাহকে ভয় কর এবং অতিথিদের ব্যাপারে আমাকে লজ্জিত করো না, তোমাদের মধ্যে কি কোন ভাল মানুষ নেই।', 'Wajaahu qawmuhu yuhraAAoona ilayhi wamin qablu kanoo yaAAmaloona alssayyiati qala ya qawmi haolai banatee hunna atharu lakum faittaqoo Allaha wala tukhzooni fee dayfee alaysa minkum rajulun rasheedun', 1, NOW(), NOW()),
(16, 79, 'قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ', 'তারা বলল ু তুমি তো জানই, তোমার কন্যাদের নিয়ে আমাদের কোন গরজ নেই। আর আমরা কি চাই, তাও তুমি অবশ্যই জান।', 'Qaloo laqad AAalimta ma lana fee banatika min haqqin wainnaka lataAAlamu ma nureedu', 1, NOW(), NOW()),
(16, 80, 'قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ', 'লূত (আঃ) বললেন-হায়, তোমাদের বিরুদ্ধে যদি আমার শক্তি থাকত অথবা আমি কোন সূদৃঢ় আশ্রয় গ্রহণ করতে সক্ষম হতাম।', 'Qala law anna lee bikum quwwatan aw awee ila ruknin shadeedin', 1, NOW(), NOW()),
(16, 81, 'قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ', 'মেহমান ফেরেশতাগন বলল-হে লূত (আঃ) আমরা তোমাদের পালনকর্তার পক্ষ হতে প্রেরিত ফেরেশতা। এরা কখনো তোমার দিকে পৌঁছাতে পারবে না। ব্যস তুমি কিছুটা রাত থাকতে থাকতে নিজের লোকজন নিয়ে বাইরে চলে যাও। আর তোমাদের কেউ যেন পিছনে ফিরে না তাকায়। কিন্তু তোমার স্ত্রী নিশ্চয় তার উপরও তা আপতিত হবে, যা ওদের উপর আপতিত হবে। ভোর বেলাই তাদের প্রতিশ্রুতির সময়, ভোর কি খুব নিকটে নয়', 'Qaloo ya lootu inna rusulu rabbika lan yasiloo ilayka faasri biahlika biqitAAin mina allayli wala yaltafit minkum ahadun illa imraataka innahu museebuha ma asabahum inna mawAAidahumu alssubhu alaysa alssubhu biqareebin', 1, NOW(), NOW()),
(16, 82, 'فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ', 'অবশেষে যখন আমার হুকুম এসে পৌঁছাল, তখন আমি উক্ত জনপদকে উপরকে নীচে করে দিলাম এবং তার উপর স্তরে স্তরে কাঁকর পাথর বর্ষণ করলাম।', 'Falamma jaa amruna jaAAalna AAaliyaha safilaha waamtarna AAalayha hijaratan min sijjeelin mandoodin', 1, NOW(), NOW()),
(16, 83, 'مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّـٰلِمِينَ بِبَعِيدٖ', 'যার প্রতিটি তোমার পালনকর্তার নিকট চিহ্নিত ছিল। আর সেই পাপিষ্ঠদের থেকে খুব দূরেও নয়।', 'Musawwamatan AAinda rabbika wama hiya mina alththalimeena bibaAAeedin', 1, NOW(), NOW()),
(16, 84, '۞وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ', 'আর মাদইয়ানবাসীদের প্রতি তাদের ভাই শোয়ায়েব (আঃ) কে প্রেরণ করেছি। তিনি বললেন-হে আমার কওম! আল্লাহর বন্দেগী কর, তিনি ছাড়া আমাদের কোন মাবুদ নাই। আর পরিমাপে ও ওজনে কম দিও না, আজ আমি তোমাদেরকে ভাল অবস্থায়ই দেখছি, কিন্তু আমি তোমাদের উপর এমন একদিনের আযাবের আশঙ্কা করছি যেদিনটি পরিবেষ্টনকারী।', 'Waila madyana akhahum shuAAayban qala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu wala tanqusoo almikyala waalmeezana innee arakum bikhayrin wainnee akhafu AAalaykum AAathaba yawmin muheetin', 1, NOW(), NOW()),
(16, 85, 'وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ', 'আর হে আমার জাতি, ন্যায়নিষ্ঠার সাথে ঠিকভাবে পরিমাপ কর ও ওজন দাও এবং লোকদের জিনিসপত্রে কোনরূপ ক্ষতি করো না, আর পৃথিবীতে ফাসাদ করে বেড়াবে না।', 'Waya qawmi awfoo almikyala waalmeezana bialqisti wala tabkhasoo alnnasa ashyaahum wala taAAthaw fee alardi mufsideena', 1, NOW(), NOW()),
(16, 86, 'بَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ', 'আল্লাহ প্রদত্ত উদ্ধৃত্ত তোমাদের জন্য উত্তম, যদি তোমরা ঈমানদার হও, আর আমি তো তোমাদের উপর সদা পর্যবেক্ষণকারী নই।', 'Baqiyyatu Allahi khayrun lakum in kuntum mumineena wama ana AAalaykum bihafeethin', 1, NOW(), NOW()),
(16, 87, 'قَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَـٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ', 'তারা বলল-হে শোয়ায়েব (আঃ) আপনার নামায কি আপনাকে ইহাই শিক্ষা দেয় যে, আমরা ঐসব উপাস্যদেরকে পরিত্যাগ করব আমাদের বাপ-দাদারা যাদের উপাসনা করত? অথবা আমাদের ধন-সম্পদে ইচ্ছামত যা কিছু করে থাকি, তা ছেড়ে দেব? আপনি তো একজন খাস মহৎ ব্যক্তি ও সৎপথের পথিক।', 'Qaloo ya shuAAaybu asalatuka tamuruka an natruka ma yaAAbudu abaona aw an nafAAala fee amwalina ma nashao innaka laanta alhaleemu alrrasheedu', 1, NOW(), NOW()),
(16, 88, 'قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ', 'শোয়ায়েব (আঃ) বললেন-হে দেশবাসী, তোমরা কি মনে কর! আমি যদি আমার পরওয়ারদেগারের পক্ষ হতে সুস্পষ্ট দলীলের উপর কায়েম থাকি আর তিনি যদি নিজের তরফ হতে আমাকে উত্তম রিযিক দান করে থাকেন, (তবে কি আমি তাঁর হুকুম অমান্য করতে পারি?) আর আমি চাই না যে তোমাদেরকে যা ছাড়াতে চাই পরে নিজেই সে কাজে লিপ্ত হব, আমি তো যথাসাধ্য শোধরাতে চাই। আল্লাহর মদদ দ্বারাই কিন্তু কাজ হয়ে থাকে, আমি তাঁর উপরই নির্ভর করি এবং তাঁরই প্রতি ফিরে যাই।', 'Qala ya qawmi araaytum in kuntu AAala bayyinatin min rabbee warazaqanee minhu rizqan hasanan wama oreedu an okhalifakum ila ma anhakum AAanhu in oreedu illa alislaha ma istataAAtu wama tawfeeqee illa biAllahi AAalayhi tawakkaltu wailayhi oneebu', 1, NOW(), NOW()),
(16, 89, 'وَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ وَمَا قَوۡمُ لُوطٖ مِّنكُم بِبَعِيدٖ', 'আর হে আমার জাতি! আমার সাথে জিদ করে তোমরা নূহ বা হুদ অথবা সালেহ (আঃ) এর কওমের মত নিজেদের উপর আযাব ডেকে আনবে না। আর লূতের জাতি তো তোমাদের থেকে খুব দূরে নয়।', 'Waya qawmi la yajrimannakum shiqaqee an yuseebakum mithlu ma asaba qawma noohin aw qawma hoodin aw qawma salihin wama qawmu lootin minkum bibaAAeedin', 1, NOW(), NOW()),
(16, 90, 'وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ', 'আর তোমাদের পালনকর্তার কাছে মার্জনা চাও এবং তাঁরই পানে ফিরে এসো নিশ্চয়ই আমার পরওয়ারদেগার খুবই মেহেরবান অতিস্নেহময়।', 'Waistaghfiroo rabbakum thumma tooboo ilayhi inna rabbee raheemun wadoodun', 1, NOW(), NOW()),
(16, 91, 'قَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ', 'তারা বলল-হে শোয়ায়েব (আঃ) আপনি যা বলেছেন তার অনেক কথাই আমরা বুঝি নাই, আমারা তো আপনাকে আমাদের মধ্যে দূর্বল ব্যক্তি রূপে মনে করি। আপনার ভাই বন্ধুরা না থাকলে আমরা আপনাকে প্রস্তরাঘাতে হত্যা করতাম। আমাদের দৃষ্টিতে আপনি কোন মর্যাদাবান ব্যক্তি নন।', 'Qaloo ya shuAAaybu ma nafqahu katheeran mimma taqoolu wainna lanaraka feena daAAeefan walawla rahtuka larajamnaka wama anta AAalayna biAAazeezin', 1, NOW(), NOW()),
(16, 92, 'قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ إِنَّ رَبِّي بِمَا تَعۡمَلُونَ مُحِيطٞ', 'শোয়ায়েব (আঃ) বলেন-হে আমার জাতি, আমার ভাই বন্ধুরা কি তোমাদের কাছে আল্লাহর চেয়ে প্রভাবশালী? আর তোমরা তাকে বিস্মৃত হয়ে পেছনে ফেলে রেখেছ, নিশ্চয় তোমাদের কার্যকলাপ আমার পালনকর্তার আয়ত্তে রয়েছে।', 'Qala ya qawmi arahtee aAAazzu AAalaykum mina Allahi waittakhathtumoohu waraakum thihriyyan inna rabbee bima taAAmaloona muheetun', 1, NOW(), NOW()),
(16, 93, 'وَيَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ سَوۡفَ تَعۡلَمُونَ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَمَنۡ هُوَ كَٰذِبٞۖ وَٱرۡتَقِبُوٓاْ إِنِّي مَعَكُمۡ رَقِيبٞ', 'আর হে আমার জাতি, তোমরা নিজ স্থানে কাজ করে যাও, আমিও কাজ করছি, অচিরেই জানতে পারবে কার উপর অপমানকর আযাব আসে আর কে মিথ্যাবাদী? আর তোমরাও অপেক্ষায় থাক, আমিও তোমাদের সাথে অপেক্ষায় রইলাম।', 'Waya qawmi iAAmaloo AAala makanatikum innee AAamilun sawfa taAAlamoona man yateehi AAathabun yukhzeehi waman huwa kathibun wairtaqiboo inne maAAakum raqeebun', 1, NOW(), NOW()),
(16, 94, 'وَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ', 'আর আমার হুকুম যখন এল, আমি শোয়ায়েব (আঃ) ও তাঁর সঙ্গী ঈমানদারগণকে নিজ রহমতে রক্ষা করি আর পাপিষ্ঠদের উপর বিকট গর্জন পতিত হলো। ফলে ভোর না হতেই তারা নিজেদের ঘরে উপুড় হয়ে পড়ে রইল।', 'Walamma jaa amruna najjayna shuAAayban waallatheena amanoo maAAahu birahmatin minna waakhathati allatheena thalamoo alssayhatu faasbahoo fee diyarihim jathimeena', 1, NOW(), NOW()),
(16, 95, 'كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَآۗ أَلَا بُعۡدٗا لِّمَدۡيَنَ كَمَا بَعِدَتۡ ثَمُودُ', 'যেন তারা সেখানে কখনো বসবাসই করে নাই। জেনে রাখ, সামুদের প্রতি অভিসম্পাতের মত মাদইয়ানবাসীর উপরেও অভিসম্পাত।', 'Kaan lam yaghnaw feeha ala buAAdan limadyana kama baAAidat thamoodu', 1, NOW(), NOW()),
(16, 96, 'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ', 'আর আমি মূসা (আঃ) কে প্রেরণ করি আমার নিদর্শনাদি ও সুস্পষ্ট সনদসহ', 'Walaqad arsalna moosa biayatina wasultanin mubeenin', 1, NOW(), NOW()),
(16, 97, 'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱتَّبَعُوٓاْ أَمۡرَ فِرۡعَوۡنَۖ وَمَآ أَمۡرُ فِرۡعَوۡنَ بِرَشِيدٖ', 'ফেরাউন ও তার পারিষদবর্গের কাছে, তবুও তারা ফেরাউনের হুকুমে চলতে থাকে, অথচ ফেরাউনের কোন কথা ন্যায় সঙ্গত ছিল না।', 'Ila firAAawna wamalaihi faittabaAAoo amra firAAawna wama amru firAAawna birasheedin', 1, NOW(), NOW()),
(16, 98, 'يَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ', 'কেয়ামতের দিন সে তার জাতির লোকদের আগে আগে থাকবে এবং তাদেরকে জাহান্নামের আগুনে পৌঁছে দিবে। আর সেটা অতীব নিকৃষ্ট স্থান, সেখানে তারা পৌঁছেছে।।', 'Yaqdumu qawmahu yawma alqiyamati faawradahumu alnnara wabisa alwirdu almawroodu', 1, NOW(), NOW()),
(16, 99, 'وَأُتۡبِعُواْ فِي هَٰذِهِۦ لَعۡنَةٗ وَيَوۡمَ ٱلۡقِيَٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ', 'আর এ জগতেও তাদের পেছনে লানত রয়েছে এবং কিয়ামতের দিনেও; অত্যন্ত জঘন্য প্রতিফল, যা তারা পেয়েছে।', 'WaotbiAAoo fee hathihi laAAnatan wayawma alqiyamati bisa alrrifdu almarfoodu', 1, NOW(), NOW()),
(16, 100, 'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَيۡكَۖ مِنۡهَا قَآئِمٞ وَحَصِيدٞ', 'এ হচ্ছে কয়েকটি জনপদের সামান্য ইতিবৃত্ত, যা আমি আপনাকে শোনাচ্ছি। তন্মধ্যে কোন কোনটি এখনও বর্তমান আছে আর কোন কোনটির শিকড় কেটে দেয়া হয়েছে।', 'Thalika min anbai alqura naqussuhu AAalayka minha qaimun wahaseedun', 1, NOW(), NOW()),
(16, 101, 'وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ فَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡبِيبٖ', 'আমি কিন্তু তাদের প্রতি জুলুম করি নাই বরং তারা নিজেরাই নিজের উপর অবিচার করেছে। ফলে আল্লাহকে বাদ দিয়ে তারা যেসব মাবুদকে ডাকতো আপনার পালনকর্তার হুকুম যখন এসে পড়ল, তখন কেউ কোন কাজে আসল না। তারা শুধু বিপর্যয়ই বৃদ্ধি করল।', 'Wama thalamnahum walakin thalamoo anfusahum fama aghnat AAanhum alihatuhumu allatee yadAAoona min dooni Allahi min shayin lamma jaa amru rabbika wama zadoohum ghayra tatbeebin', 1, NOW(), NOW()),
(16, 102, 'وَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ', 'আর তোমার পরওয়ারদেগার যখন কোন পাপপূর্ণ জনপদকে ধরেন, তখন এমনিভাবেই ধরে থাকেন। নিশ্চয় তাঁর পাকড়াও খুবই মারাত্নক, বড়ই কঠোর।', 'Wakathalika akhthu rabbika itha akhatha alqura wahiya thalimatun inna akhthahu aleemun shadeedun', 1, NOW(), NOW()),
(16, 103, 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّمَنۡ خَافَ عَذَابَ ٱلۡأٓخِرَةِۚ ذَٰلِكَ يَوۡمٞ مَّجۡمُوعٞ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوۡمٞ مَّشۡهُودٞ', 'নিশ্চয় ইহার মধ্যে নিদর্শন রয়েছে এমন প্রতিটি মানুষের জন্য যে আখেরাতের আযাবকে ভয় করে। উহা এমন একদিন, যে দিন সব মানুষেই সমবেত হবে, সেদিনটি যে হাযিরের দিন।', 'Inna fee thalika laayatan liman khafa AAathaba alakhirati thalika yawmun majmooAAun lahu alnnasu wathalika yawmun mashhoodun', 1, NOW(), NOW()),
(16, 104, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٖ مَّعۡدُودٖ', 'আর আমি যে উহা বিলম্বিত করি, তা শুধু একটি ওয়াদার কারণে যা নির্ধারিত রয়েছে।', 'Wama nuakhkhiruhu illa liajalin maAAdoodin', 1, NOW(), NOW()),
(16, 105, 'يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِيّٞ وَسَعِيدٞ', 'যেদিন তা আসবে সেদিন আল্লাহর অনুমতি ছাড়া কেউ কোন কথা বলতে পারে না। অতঃপর কিছু লোক হবে হতভাগ্য আর কিছু লোক সৌভাগ্যবান।', 'Yawma yati la takallamu nafsun illa biithnihi faminhum shaqiyyun wasaAAeedin', 1, NOW(), NOW()),
(16, 106, 'فَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ', 'অতএব যারা হতভাগ্য তারা দোযখে যাবে, সেখানে তারা আর্তনাদ ও চিৎকার করতে থাকবে।', 'Faamma allatheena shaqoo fafee alnnari lahum feeha zafeerun washaheequn', 1, NOW(), NOW()),
(16, 107, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالٞ لِّمَا يُرِيدُ', 'তারা সেখানে চিরকাল থাকবে, যতদিন আসমান ও যমীন বর্তমান থাকবে। তবে তোমার প্রতিপালক অন্য কিছু ইচ্ছা করলে ভিন্ন কথা। নিশ্চয় তোমার পরওয়ারদেগার যা ইচ্ছা করতে পারেন।', 'Khalideena feeha ma damati alssamawatu waalardu illa ma shaa rabbuka inna rabbaka faAAAAalun lima yureedu', 1, NOW(), NOW()),
(16, 108, '۞وَأَمَّا ٱلَّذِينَ سُعِدُواْ فَفِي ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَآءَ رَبُّكَۖ عَطَآءً غَيۡرَ مَجۡذُوذٖ', 'আর যারা সৌভাগ্যবান তারা বেহেশতের মাঝে, সেখানেই চিরদিন থাকবে, যতদিন আসমান ও যমীন বর্তমান থাকবে। তবে তোমার প্রভু অন্য কিছু ইচ্ছা করলে ভিন্ন কথা। এ দানের ধারাবাহিকতা কখনো ছিন্ন হওয়ার নয়।', 'Waamma allatheena suAAidoo fafee aljannati khalideena feeha ma damati alssamawatu waalardu illa ma shaa rabbuka AAataan ghayra majthoothin', 1, NOW(), NOW()),
(16, 109, 'فَلَا تَكُ فِي مِرۡيَةٖ مِّمَّا يَعۡبُدُ هَـٰٓؤُلَآءِۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَابَآؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَنقُوصٖ', 'অতএব, তারা যেসবের উপাসনা করে তুমি সে ব্যাপারে কোনরূপ ধোঁকায় পড়বে না। তাদের পূর্ববর্তী বাপ-দাদারা যেমন পূজা উপাসনা করত, এরাও তেমন করছে। আর নিশ্চয় আমি তাদেরকে আযাবের ভাগ কিছু মাত্রও কম না করেই পুরোপুরি দান করবো।', 'Fala taku fee miryatin mimma yaAAbudu haolai ma yaAAbudoona illa kama yaAAbudu abaohum min qablu wainna lamuwaffoohum naseebahum ghayra manqoosin', 1, NOW(), NOW()),
(16, 110, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ', 'আর আমি মূসা (আঃ)-কে অবশ্যই কিতাব দিয়েছিলাম অতঃপর তাতে বিরোধ সৃষ্টি হল; বলাবাহুল্য তোমার পালনকর্তার পক্ষ হতে, একটি কথা যদি আগেই বলা না হত, তাহলে তাদের মধ্যে চুড়ান্ত ফয়সালা হয়ে যেত তারা এ ব্যাপারে এমনই সন্দেহ প্রবণ যে, কিছুতেই নিশ্চিত হতে পারছে না।', 'Walaqad atayna moosa alkitaba faikhtulifa feehi walawla kalimatun sabaqat min rabbika laqudiya baynahum wainnahum lafee shakkin minhu mureebun', 1, NOW(), NOW()),
(16, 111, 'وَإِنَّ كُلّٗا لَّمَّا لَيُوَفِّيَنَّهُمۡ رَبُّكَ أَعۡمَٰلَهُمۡۚ إِنَّهُۥ بِمَا يَعۡمَلُونَ خَبِيرٞ', 'আর যত লোকই হোক না কেন, যখন সময় হবে, তোমার প্রভু তাদের সকলেরই আমলের প্রতিদান পুরোপুরি দান করবেন। নিশ্চয় তিনি তাদের যাবতীয় কার্যকলাপের খবর রাখেন।', 'Wainna kullan lamma layuwaffiyannahum rabbuka aAAmalahum innahu bima yaAAmaloona khabeerun', 1, NOW(), NOW()),
(16, 112, 'فَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡاْۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٞ', 'অতএব, তুমি এবং তোমার সাথে যারা তওবা করেছে সবাই সোজা পথে চলে যাও-যেমন তোমায় হুকুম দেয়া হয়েছে এবং সীমা লঙ্ঘন করবে না, তোমরা যা কিছু করছ, নিশ্চয় তিনি তার প্রতি দৃষ্টি রাখেন।', 'Faistaqim kama omirta waman taba maAAaka wala tatghaw innahu bima taAAmaloona baseerun', 1, NOW(), NOW()),
(16, 113, 'وَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ', 'আর পাপিষ্ঠদের প্রতি ঝুঁকবে না। নতুবা তোমাদেরকেও আগুনে ধরবে। আর আল্লাহ ব্যতীত তোমাদের কোন বন্ধু নাই। অতএব কোথাও সাহায্য পাবে না।', 'Wala tarkanoo ila allatheena thalamoo fatamassakumu alnnaru wama lakum min dooni Allahi min awliyaa thumma la tunsaroona', 1, NOW(), NOW()),
(16, 114, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّـٰكِرِينَ', 'আর দিনের দুই প্রান্তেই নামায ঠিক রাখবে, এবং রাতের প্রান্তভাগে পূর্ণ কাজ অবশ্যই পাপ দূর করে দেয়, যারা স্মরণ রাখে তাদের জন্য এটি এক মহা স্মারক।', 'Waaqimi alssalata tarafayi alnnahari wazulafan mina allayli inna alhasanati yuthhibna alssayyiati thalika thikra lilththakireena', 1, NOW(), NOW()),
(16, 115, 'وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ', 'আর ধৈর্য্যধারণ কর, নিশ্চয়ই আল্লাহ পূণ্যবানদের প্রতিদান বিনষ্ট করেন না।', 'Waisbir fainna Allaha la yudeeAAu ajra almuhsineena', 1, NOW(), NOW()),
(16, 116, 'فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ', 'কাজেই, তোমাদের পূর্ববতী জাতি গুলির মধ্যে এমন সৎকর্মশীল কেন রইল না, যারা পৃথিবীতে বিপর্যয় সৃষ্টি করতে বাধা দিত; তবে মুষ্টিমেয় লোক ছিল যাদেরকে আমি তাদের মধ্য হতে রক্ষা করেছি। আর পাপিষ্ঠরা তো ভোগ বিলাসে মত্ত ছিল যার সামগ্রী তাদেরকে যথেষ্ট দেয়া হয়েছিল। আসলে তারা ছিল মহা অপরাধী।', 'Falawla kana mina alqurooni min qablikum oloo baqiyyatin yanhawna AAani alfasadi fee alardi illa qaleelan mimman anjayna minhum waittabaAAa allatheena thalamoo ma otrifoo feehi wakanoo mujrimeena', 1, NOW(), NOW()),
(16, 117, 'وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا مُصۡلِحُونَ', 'আর তোমার পালনকর্তা এমন নন যে, জনবসতিগুলোকে অন্যায়ভাবে ধ্বংস করে দেবেন, সেখানকার লোকেরা সৎকর্মশীল হওয়া সত্ত্বেও।', 'Wama kana rabbuka liyuhlika alqura bithulmin waahluha muslihoona', 1, NOW(), NOW()),
(16, 118, 'وَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ', 'আর তোমার পালনকর্তা যদি ইচ্ছা করতেন, তবে অবশ্যই সব মানুষকে একই জাতিসত্তায় পরিনত করতে পারতেন আর তারা বিভিন্ন ভাগে বিভক্ত হতো না।', 'Walaw shaa rabbuka lajaAAala alnnasa ommatan wahidatan wala yazaloona mukhtalifeena', 1, NOW(), NOW()),
(16, 119, 'إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ', 'তোমার পালনকর্তা যাদের উপর রহমত করেছেন, তারা ব্যতীত সবাই চিরদিন মতভেদ করতেই থাকবে এবং এজন্যই তাদেরকে সৃষ্টি করেছেন। আর তোমার আল্লাহর কথাই পূর্ণ হল যে, অবশ্যই আমি জাহান্নামকে জ্বিন ও মানুষ দ্বারা একযোগে ভর্তি করব।', 'Illa man rahima rabbuka walithalika khalaqahum watammat kalimatu rabbika laamlaanna jahannama mina aljinnati waalnnasi ajmaAAeena', 1, NOW(), NOW()),
(16, 120, 'وَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَآءَكَ فِي هَٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةٞ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ', 'আর আমি রসূলগণের সব বৃত্তান্তই তোমাকে বলছি, যদ্দ্বারা তোমার অন্তরকে মজবুত করছি। আর এভাবে তোমার নিকট মহাসত্য এবং ঈমানদারদের জন্য নসীহত ও স্বরণীয় বিষয়বস্তু এসেছে।', 'Wakullan naqussu AAalayka min anbai alrrusuli ma nuthabbitu bihi fuadaka wajaaka fee hathihi alhaqqu wamawAAithatun wathikra lilmumineena', 1, NOW(), NOW()),
(16, 121, 'وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَٰمِلُونَ', 'আর যারা ঈমান আনে না, তাদেরকে বলে দাও যে, তোমরা নিজ নিজ অবস্থায় কাজ করে যাও আমরাও কাজ করে যাই।', 'Waqul lillatheena la yuminoona iAAmaloo AAala makanatikum inna AAamiloona', 1, NOW(), NOW()),
(16, 122, 'وَٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ', 'এবং তোমরাও অপেক্ষা করে থাক, আমরাও অপেক্ষায় রইলাম।', 'Waintathiroo inna muntathiroona', 1, NOW(), NOW()),
(16, 123, 'وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ', 'আর আল্লাহর কাছেই আছে আসমান ও যমীনের গোপন তথ্য; আর সকল কাজের প্রত্যাবর্তন তাঁরই দিকে; অতএব, তাঁরই বন্দেগী কর এবং তাঁর উপর ভরসা রাখ, আর তোমাদের কার্যকলাপ সম্বন্ধে তোমার পালনকর্তা কিন্তু বে-খবর নন।', 'Walillahi ghaybu alssamawati waalardi wailayhi yurjaAAu alamru kulluhu faoAAbudhu watawakkal AAalayhi wama rabbuka bighafilin AAamma taAAmaloona', 1, NOW(), NOW()),
(17, 1, 'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ', 'আলিফ-লা-ম-রা; এগুলো সুস্পষ্ট গ্রন্থের আয়াত।', 'Aliflamra tilka ayatu alkitabi almubeenu', 1, NOW(), NOW()),
(17, 2, 'إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ', 'আমি একে আরবী ভাষায় কোরআন রূপে অবতীর্ণ করেছি, যাতে তোমরা বুঝতে পার।', 'Inna anzalnahu quranan AAarabiyyan laAAallakum taAAqiloona', 1, NOW(), NOW()),
(17, 3, 'نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَآ أَوۡحَيۡنَآ إِلَيۡكَ هَٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَٰفِلِينَ', 'আমি তোমার নিকট উত্তম কাহিনী বর্ণনা করেছি, যেমতে আমি এ কোরআন তোমার নিকট অবতীর্ণ করেছি। তুমি এর আগে অবশ্যই এ ব্যাপারে অনবহিতদের অন্তর্ভূক্ত ছিলে।', 'Nahnu naqussu AAalayka ahsana alqasasi bima awhayna ilayka hatha alqurana wain kunta min qablihi lamina alghafileena', 1, NOW(), NOW()),
(17, 4, 'إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَـٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ', 'যখন ইউসুফ পিতাকে বললঃ পিতা, আমি স্বপ্নে দেখেছি এগারটি নক্ষত্রকে। সুর্যকে এবং চন্দ্রকে। আমি তাদেরকে আমার উদ্দেশে সেজদা করতে দেখেছি।', 'Ith qala yoosufu liabeehi ya abati innee raaytu ahada AAashara kawkaban waalshshamsa waalqamara raaytuhum lee sajideena', 1, NOW(), NOW()),
(17, 5, 'قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ', 'তিনি বললেনঃ বৎস, তোমার ভাইদের সামনে এ স্বপ্ন বর্ণনা করো না। তাহলে তারা তোমার বিরুদ্ধে চক্রান্ত করবে। নিশ্চয় শয়তান মানুষের প্রকাশ্য।', 'Qala ya bunayya la taqsus ruyaka AAala ikhwatika fayakeedoo laka kaydan inna alshshaytana lilinsani AAaduwwun mubeenun', 1, NOW(), NOW()),
(17, 6, 'وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ', 'এমনিভাবে তোমার পালনকর্তা তোমাকে মনোনীত করবেন এবং তোমাকে বাণীসমূহের নিগুঢ় তত্ত্ব শিক্ষা দেবেন এবং পূর্ণ করবেন স্বীয় অনুগ্রহ তোমার প্রতি ও ইয়াকুব পরিবার-পরিজনের প্রতি; যেমন ইতিপূর্বে তোমার পিতৃপুরুষ ইব্রাহীম ও ইসহাকের প্রতি পূর্ণ করেছেন। নিশ্চয় তোমার পালনকর্তা অত্যন্ত জ্ঞানী, প্রজ্ঞাময়।', 'Wakathalika yajtabeeka rabbuka wayuAAallimuka min taweeli alahadeethi wayutimmu niAAmatahu AAalayka waAAala ali yaAAqooba kama atammaha AAala abawayka min qablu ibraheema waishaqa inna rabbaka AAaleemun hakeemun', 1, NOW(), NOW()),
(17, 7, '۞لَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ', 'অবশ্য ইউসুফ ও তাঁর ভাইদের কাহিনীতে জিজ্ঞাসুদের জন্যে নিদর্শনাবলী রয়েছে।', 'Laqad kana fee yoosufa waikhwatihi ayatun lilssaileena', 1, NOW(), NOW()),
(17, 8, 'إِذۡ قَالُواْ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِي ضَلَٰلٖ مُّبِينٍ', 'যখন তারা বললঃ অবশ্যই ইউসুফ ও তাঁর ভাই আমাদের পিতার কাছে আমাদের চাইতে অধিক প্রিয় অথচ আমরা একটা সংহত শক্তি বিশেষ। নিশ্চয় আমাদের পিতা স্পষ্ট ভ্রান্তিতে রয়েছেন।', 'Ith qaloo layoosufu waakhoohu ahabbu ila abeena minna wanahnu AAusbatun inna abana lafee dalalin mubeenin', 1, NOW(), NOW()),
(17, 9, 'ٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ', 'হত্যা কর ইউসুফকে কিংবা ফেলে আস তাকে অন্য কোন স্থানে। এতে শুধু তোমাদের প্রতিই তোমাদের পিতার মনোযোগ নিবিষ্ট হবে এবং এরপর তোমরা যোগ্য বিবেচিত হয়ে থাকবে।', 'Oqtuloo yoosufa awi itrahoohu ardan yakhlu lakum wajhu abeekum watakoonoo min baAAdihi qawman saliheena', 1, NOW(), NOW()),
(17, 10, 'قَالَ قَآئِلٞ مِّنۡهُمۡ لَا تَقۡتُلُواْ يُوسُفَ وَأَلۡقُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّ يَلۡتَقِطۡهُ بَعۡضُ ٱلسَّيَّارَةِ إِن كُنتُمۡ فَٰعِلِينَ', 'তাদের মধ্য থেকে একজন বলল, তোমরা ইউসুফ কে হত্যা করো না, বরং ফেলে দাও তাকে অন্ধকূপে যাতে কোন পথিক তাকে উঠিয়ে নিয়ে যায়, যদি তোমাদের কিছু করতেই হয়।', 'Qala qailun minhum la taqtuloo yoosufa waalqoohu fee ghayabati aljubbi yaltaqithu baAAdu alssayyarati in kuntum faAAileena', 1, NOW(), NOW()),
(17, 11, 'قَالُواْ يَـٰٓأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', 'তারা বললঃ পিতাঃ ব্যাপার কি, আপনি ইউসুফের ব্যাপারে আমাদেরকে বিশ্বাস করেন না ? আমরা তো তার হিতাকাংখী।', 'Qaloo ya abana ma laka la tamanna AAala yoosufa wainna lahu lanasihoona', 1, NOW(), NOW()),
(17, 12, 'أَرۡسِلۡهُ مَعَنَا غَدٗا يَرۡتَعۡ وَيَلۡعَبۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'আগামীকাল তাকে আমাদের সাথে প্রেরণ করুন-তৃপ্তিসহ খাবে এবং খেলাধুলা করবে এবং আমরা অবশ্যই তার রক্ষণাবেক্ষন করব।', 'Arsilhu maAAana ghadan yartaAA wayalAAab wainna lahu lahafithoona', 1, NOW(), NOW()),
(17, 13, 'قَالَ إِنِّي لَيَحۡزُنُنِيٓ أَن تَذۡهَبُواْ بِهِۦ وَأَخَافُ أَن يَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَٰفِلُونَ', 'তিনি বললেনঃ আমার দুশ্চিন্তা হয় যে, তোমরা তাকে নিয়ে যাবে এবং আমি আশঙ্কা করি যে, ব্যাঘ্র তাঁকে খেয়ে ফেলবে এবং তোমরা তার দিক থেকে গাফেল থাকবে।', 'Qala innee layahzununee an thathhaboo bihi waakhafu an yakulahu alththibu waantum AAanhu ghafiloona', 1, NOW(), NOW()),
(17, 14, 'قَالُواْ لَئِنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّآ إِذٗا لَّخَٰسِرُونَ', 'তারা বললঃ আমরা একটি ভারী দল থাকা সত্ত্বেও যদি ব্যাঘ্র তাকে খেয়ে ফেলে, তবে আমরা সবই হারালাম।', 'Qaloo lain akalahu alththibu wanahnu AAusbatun inna ithan lakhasiroona', 1, NOW(), NOW()),
(17, 15, 'فَلَمَّا ذَهَبُواْ بِهِۦ وَأَجۡمَعُوٓاْ أَن يَجۡعَلُوهُ فِي غَيَٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَيۡنَآ إِلَيۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَٰذَا وَهُمۡ لَا يَشۡعُرُونَ', 'অতঃপর তারা যখন তাকে নিয়ে চলল এবং অন্ধকূপে নিক্ষেপ করতে একমত হল এবং আমি তাকে ইঙ্গিত করলাম যে, তুমি তাদেরকে তাদের এ কাজের কথা বলবে এমতাবস্থায় যে, তারা তোমাকে চিনবে না।', 'Falamma thahaboo bihi waajmaAAoo an yajAAaloohu fee ghayabati aljubbi waawhayna ilayhi latunabiannahum biamrihim hatha wahum la yashAAuroona', 1, NOW(), NOW()),
(17, 16, 'وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ', 'তারা রাতের বেলায় কাঁদতে কাঁদতে পিতার কাছে এল।', 'Wajaoo abahum AAishaan yabkoona', 1, NOW(), NOW()),
(17, 17, 'قَالُواْ يَـٰٓأَبَانَآ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَآ أَنتَ بِمُؤۡمِنٖ لَّنَا وَلَوۡ كُنَّا صَٰدِقِينَ', 'তারা বললঃ পিতাঃ আমরা দৌড় প্রতিযোগিতা করতে গিয়েছিলাম এবং ইউসুফকে আসবাব-পত্রের কাছে রেখে গিয়েছিলাম। অতঃপর তাকে বাঘে খেয়ে ফেলেছে। আপনি তো আমাদেরকে বিশ্বাস করবেন না, যদিও আমরা সত্যবাদী।', 'Qaloo ya abana inna thahabna nastabiqu watarakna yoosufa AAinda mataAAina faakalahu alththibu wama anta bimuminin lana walaw kunna sadiqeena', 1, NOW(), NOW()),
(17, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'এবং তারা তার জামায় কৃত্রিম রক্ত লাগিয়ে আনল। বললেনঃ এটা কখনই নয়; বরং তোমাদের মন তোমাদেরকে একটা কথা সাজিয়ে দিয়েছে। সুতরাং এখন ছবর করাই শ্রেয়। তোমরা যা বর্ণনা করছ, সে বিষয়ে একমাত্র আল্লাহই আমার সাহায্য স্থল।', 'Wajaoo AAala qameesihi bidamin kathibin qala bal sawwalat lakum anfusukum amran fasabrun jameelun waAllahu almustaAAanu AAala ma tasifoona', 1, NOW(), NOW()),
(17, 19, 'وَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ', 'এবং একটি কাফেলা এল। অতঃপর তাদের পানি সংগ্রাহককে প্রেরণ করল। সে বালতি ফেলল। বললঃ কি আনন্দের কথা। এ তো একটি কিশোর তারা তাকে পন্যদ্রব্য গণ্য করে গোপন করে ফেলল। আল্লাহ খুব জানেন যা কিছু তারা করেছিল।', 'Wajaat sayyaratun faarsaloo waridahum faadla dalwahu qala ya bushra hatha ghulamun waasarroohu bidaAAatan waAllahu AAaleemun bima yaAAmaloona', 1, NOW(), NOW()),
(17, 20, 'وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّـٰهِدِينَ', 'ওরা তাকে কম মূল্যে বিক্রি করে দিল গনাগুণতি কয়েক দেরহাম এবং তাঁর ব্যাপারে নিরাসক্ত ছিল।', 'Washarawhu bithamanin bakhsin darahima maAAdoodatin wakanoo feehi mina alzzahideena', 1, NOW(), NOW()),
(17, 21, 'وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ', 'মিসরে যে ব্যক্তি তাকে ক্রয় করল, সে তার স্ত্রীকে বললঃ একে সম্মানে রাখ। সম্ভবতঃ সে আমাদের কাছে আসবে অথবা আমরা তাকে পুত্ররূপে গ্রহণ করে নেব। এমনিভাবে আমি ইউসুফকে এদেশে প্রতিষ্ঠিত করলাম এবং এ জন্যে যে তাকে বাক্যাদির পূর্ণ মর্ম অনুধাবনের পদ্ধতি বিষয়ে শিক্ষা দেই। আল্লাহ নিজ কাজে প্রবল থাকেন, কিন্তু অধিকাংশ লোক তা জানে না।', 'Waqala allathee ishtarahu min misra liimraatihi akrimee mathwahu AAasa an yanfaAAana aw nattakhithahu waladan wakathalika makkanna liyoosufa fee alardi walinuAAallimahu min taweeli alahadeethi waAllahu ghalibun AAala amrihi walakinna akthara alnnasi la yaAAlamoona', 1, NOW(), NOW()),
(17, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ', 'যখন সে পূর্ণ যৌবনে পৌছে গেল, তখন তাকে প্রজ্ঞা ও ব্যুৎপত্তি দান করলাম। এমননিভাবে আমি সৎকর্মপরায়ণদেরকে প্রতিদান দেই।', 'Walamma balagha ashuddahu ataynahu hukman waAAilman wakathalika najzee almuhsineena', 1, NOW(), NOW()),
(17, 23, 'وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّـٰلِمُونَ', 'আর সে যে মহিলার ঘরে ছিল, ঐ মহিলা তাকে ফুসলাতে লাগল এবং দরজাসমূহ বন্ধ করে দিল। সে মহিলা বললঃ শুন! তোমাকে বলছি, এদিকে আস, সে বললঃ আল্লাহ রক্ষা করুন; তোমার স্বামী আমার মালিক। তিনি আমাকে সযত্নে থাকতে দিয়েছেন। নিশ্চয় সীমা লংঘনকারীগণ সফল হয় না।', 'Warawadathu allatee huwa fee baytiha AAan nafsihi waghallaqati alabwaba waqalat hayta laka qala maAAatha Allahi innahu rabbee ahsana mathwaya innahu la yuflihu alththalimoona', 1, NOW(), NOW()),
(17, 24, 'وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ', 'নিশ্চয় মহিলা তার বিষয়ে চিন্তা করেছিল এবং সেও মহিলার বিষয়ে চিন্তা করত। যদি না সে স্বীয় পালনকর্তার মহিমা অবলোকন করত। এমনিবাবে হয়েছে, যাতে আমি তার কাছ থেকে মন্দ বিষয় ও নিলজ্জ বিষয় সরিয়ে দেই। নিশ্চয় সে আমার মনোনীত বান্দাদের একজন।', 'Walaqad hammat bihi wahamma biha lawla an raa burhana rabbihi kathalika linasrifa AAanhu alssooa waalfahshaa innahu min AAibadina almukhlaseena', 1, NOW(), NOW()),
(17, 25, 'وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ', 'তারা উভয়ে ছুটে দরজার দিকে গেল এবং মহিলা ইউসুফের জামা পিছন দিক থেকে ছিঁড়ে ফেলল। উভয়ে মহিলার স্বামীকে দরজার কাছে পেল। মহিলা বললঃ যে ব্যক্তি তোমার পরিজনের সাথে কুকর্মের ইচ্ছা করে, তাকে কারাগারে পাঠানো অথবা অন্য কোন যন্ত্রণাদায়ক শাস্তি দেয়া ছাড়া তার আর কি শাস্তি হতে পারে', 'Waistabaqa albaba waqaddat qameesahu min duburin waalfaya sayyidaha lada albabi qalat ma jazao man arada biahlika sooan illa an yusjana aw AAathabun aleemun', 1, NOW(), NOW()),
(17, 26, 'قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ', 'ইউসুফ (আঃ) বললেন, সেই আমাকে আত্মসংবরণ না করতে ফুসলিয়েছে। মহিলার পরিবারে জনৈক সাক্ষী দিল যে, যদি তার জামা সামনের দিক থেকে ছিন্ন থাকে, তবে মহিলা সত্যবাদিনী এবং সে মিথ্যাবাদি।', 'Qala hiya rawadatnee AAan nafsee washahida shahidun min ahliha in kana qameesuhu qudda min qubulin fasadaqat wahuwa mina alkathibeena', 1, NOW(), NOW()),
(17, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّـٰدِقِينَ', 'এবং যদি তার জামা পেছনের দিক থেকে ছিন্ন থাকে, তবে মহিলা মিথ্যাবাদিনী এবং সে সত্যবাদী।', 'Wain kana qameesuhu qudda min duburin fakathabat wahuwa mina alssadiqeena', 1, NOW(), NOW()),
(17, 28, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ', 'অতঃপর গৃহস্বামী যখন দেখল যে, তার জামা পেছন দিক থেকে ছিন্ন, তখন সে বলল, নিশ্চয় এটা তোমাদের ছলনা। নিঃসন্দেহে তোমাদের ছলনা খুবই মারাত্নক।', 'Falamma raa qameesahu qudda min duburin qala innahu min kaydikunna inna kaydakunna AAatheemun', 1, NOW(), NOW()),
(17, 29, 'يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ', 'ইউসুফ এ প্রসঙগ ছাড়! আর হে নারী, এ পাপের জন্য ক্ষমা প্রার্থনা কর নিঃসন্দেহে তুমি-ই পাপাচারিনী।', 'Yoosufu aAArid AAan hatha waistaghfiree lithanbiki innaki kunti mina alkhatieena', 1, NOW(), NOW()),
(17, 30, '۞وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ', 'নগরে মহিলারা বলাবলি করতে লাগল যে, আযীযের স্ত্রী স্বীয় গোলামকে কুমতলব চরিতার্থ করার জন্য ফুসলায়। সে তার প্রেমে উম্মত্ত হয়ে গেছে। আমরা তো তাকে প্রকাশ্য ভ্রান্তিতে দেখতে পাচ্ছি।', 'Waqala niswatun fee almadeenati imraatu alAAazeezi turawidu fataha AAan nafsihi qad shaghafaha hubban inna lanaraha fee dalalin mubeenin', 1, NOW(), NOW()),
(17, 31, 'فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ', 'যখন সে তাদের চক্রান্ত শুনল, তখন তাদেরকে ডেকে পাঠাল এবং তাদের জন্যে একটি ভোজ সভার আয়োজন করল। সে তাদের প্রত্যেককে একটি ছুরি দিয়ে বললঃ ইউসুফ এদের সামনে চলে এস। যখন তারা তাকে দেখল, হতভম্ব হয়ে গেল এবং আপন হাত কেটে ফেলল। তারা বললঃ কখনই নয় এ ব্যক্তি মানব নয়। এ তো কোন মহান ফেরেশতা।', 'Falamma samiAAat bimakrihinna arsalat ilayhinna waaAAtadat lahunna muttakaan waatat kulla wahidatin minhunna sikkeenan waqalati okhruj AAalayhinna falamma raaynahu akbarnahu waqattaAAna aydiyahunna waqulna hasha lillahi ma hatha basharan in hatha illa malakun kareemun', 1, NOW(), NOW()),
(17, 32, 'قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّـٰغِرِينَ', 'মহিলা বললঃ এ ঐ ব্যক্তি, যার জন্যে তোমরা আমাকে ভৎর্সনা করছিলে। আমি ওরই মন জয় করতে চেয়েছিলাম। কিন্তু সে নিজেকে নিবৃত্ত রেখেছে। আর আমি যা আদেশ দেই, সে যদি তা না করে, তবে অবশ্যই সে কারাগারে প্রেরিত হবে এবং লাঞ্চিত হবে।', 'Qalat fathalikunna allathee lumtunnanee feehi walaqad rawadtuhu AAan nafsihi faistAAsama walain lam yafAAal ma amuruhu layusjananna walayakoonan mina alssaghireena', 1, NOW(), NOW()),
(17, 33, 'قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ', 'ইউসুফ বললঃ হে পালনকর্তা তারা আমাকে যে কাজের দিকে আহবান করে, তার চাইতে আমি কারাগারই পছন্দ করি। যদি আপনি তাদের চক্রান্ত আমার উপর থেকে প্রতিহত না করেন, তবে আমি তাদের প্রতি আকৃষ্ট হয়ে পড়ব এবং অজ্ঞদের অন্তর্ভূক্ত হয়ে যাব।', 'Qala rabbi alssijnu ahabbu ilayya mimma yadAAoonanee ilayhi wailla tasrif AAannee kaydahunna asbu ilayhinna waakun mina aljahileena', 1, NOW(), NOW()),
(17, 34, 'فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'অতঃপর তার পালনকর্তা তার দোয়া কবুল করে নিলেন। অতঃপর তাদের চক্রান্ত প্রতিহত করলেন। নিশ্চয় তিনি সর্বশ্রোতা ও সর্বজ্ঞ।', 'Faistajaba lahu rabbuhu fasarafa AAanhu kaydahunna innahu huwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(17, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ', 'অতঃপর এসব নিদর্শন দেখার পর তারা তাকে কিছুদিন কারাগারে রাখা সমীচীন মনে করল।', 'Thumma bada lahum min baAAdi ma raawoo alayati layasjununnahu hatta heenin', 1, NOW(), NOW()),
(17, 36, 'وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَيَانِۖ قَالَ أَحَدُهُمَآ إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ وَقَالَ ٱلۡأٓخَرُ إِنِّيٓ أَرَىٰنِيٓ أَحۡمِلُ فَوۡقَ رَأۡسِي خُبۡزٗا تَأۡكُلُ ٱلطَّيۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِيلِهِۦٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ', 'তাঁর সাথে কারাগারে দুজন যুবক প্রবেশ করল। তাদের একজন বললঃ আমি স্বপ্নে দেখলাম যে, আমি মদ নিঙড়াচ্ছি। অপরজন বললঃ আমি দেখলাম যে, নিজ মাথায় রুটি বহন করছি। তা থেকে পাখী ঠুকরিয়ে খাচ্ছে। আমাদের কে এর ব্যাখ্যা বলুন। আমরা আপনাকে সৎকর্মশীল দেখতে পাচ্ছি।', 'Wadakhala maAAahu alssijna fatayani qala ahaduhuma innee aranee aAAsiru khamran waqala alakharu innee aranee ahmilu fawqa rasee khubzan takulu alttayru minhu nabbina bitaweelihi inna naraka mina almuhsineena', 1, NOW(), NOW()),
(17, 37, 'قَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ', 'তিনি বললেনঃ তোমাদেরকে প্রত্যহ যে খাদ্য দেয়া হয়, তা তোমাদের কাছে আসার আগেই আমি তার ব্যাখ্যা বলে দেব। এ জ্ঞান আমার পালনকর্তা আমাকে শিক্ষা দিয়েছেন। আমি ঐসব লোকের ধর্ম পরিত্যাগ করেছি যারা আল্লাহর প্রতি বিশ্বাস স্থাপন করে না এবং পরকালে অবিশ্বাসী।', 'Qala la yateekuma taAAamun turzaqanihi illa nabbatukuma bitaweelihi qabla an yatiyakuma thalikuma mimma AAallamanee rabbee innee taraktu millata qawmin la yuminoona biAllahi wahum bialakhirati hum kafiroona', 1, NOW(), NOW()),
(17, 38, 'وَٱتَّبَعۡتُ مِلَّةَ ءَابَآءِيٓ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَۚ مَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ', 'আমি আপন পিতৃপুরুষ ইব্রাহীম, ইসহাক ও ইয়াকুবের ধর্ম অনুসরণ করছি। আমাদের জন্য শোভা পায় না যে, কোন বস্তুকে আল্লাহর অংশীদার করি। এটা আমাদের প্রতি এবং অন্য সব লোকের প্রতি আল্লাহর অনুগ্রহ। কিন্ত অধিকাংশ লোক অনুগ্রহ স্বীকার করে না।', 'WaittabaAAtu millata abaee ibraheema waishaqa wayaAAqooba ma kana lana an nushrika biAllahi min shayin thalika min fadli Allahi AAalayna waAAala alnnasi walakinna akthara alnnasi la yashkuroona', 1, NOW(), NOW()),
(17, 39, 'يَٰصَٰحِبَيِ ٱلسِّجۡنِ ءَأَرۡبَابٞ مُّتَفَرِّقُونَ خَيۡرٌ أَمِ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ', 'হে কারাগারের সঙ্গীরা! পৃথক পৃথক অনেক উপাস্য ভাল, না পরাক্রমশালী এক আল্লাহ', 'Ya sahibayi alssijni aarbabun mutafarriqoona khayrun ami Allahu alwahidu alqahharu', 1, NOW(), NOW()),
(17, 40, 'مَا تَعۡبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسۡمَآءٗ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ', 'তোমরা আল্লাহকে ছেড়ে নিছক কতগুলো নামের এবাদত কর, সেগুলো তোমরা এবং তোমাদের বাপ-দাদারা সাব্যস্ত করে নিয়েছে। আল্লাহ এদের কোন প্রমাণ অবতীর্ণ করেননি। আল্লাহ ছাড়া কারও বিধান দেবার ক্ষমতা নেই। তিনি আদেশ দিয়েছেন যে, তিনি ব্যতীত অন্য কারও এবাদত করো না। এটাই সরল পথ। কিন্তু অধিকাংশ লোক তা জানে না।', 'Ma taAAbudoona min doonihi illa asmaan sammaytumooha antum waabaokum ma anzala Allahu biha min sultanin ini alhukmu illa lillahi amara alla taAAbudoo illa iyyahu thalika alddeenu alqayyimu walakinna akthara alnnasi la yaAAlamoona', 1, NOW(), NOW()),
(17, 41, 'يَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ وَأَمَّا ٱلۡأٓخَرُ فَيُصۡلَبُ فَتَأۡكُلُ ٱلطَّيۡرُ مِن رَّأۡسِهِۦۚ قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ', 'হে কারাগারের সঙ্গীরা! তোমাদের একজন আপন প্রভুকে মদ্যপান করাবে এবং দ্বিতীয়জন, তাকে শুলে চড়ানো হবে। অতঃপর তার মস্তক থেকে পাখী আহার করবে। তোমরা যে, বিষয়ে জানার আগ্রহী তার সিদ্ধান্ত হয়ে গেছে।', 'Ya sahibayi alssijni amma ahadukuma fayasqee rabbahu khamran waamma alakharu fayuslabu fatakulu alttayru min rasihi qudiya alamru allathee feehi tastaftiyani', 1, NOW(), NOW()),
(17, 42, 'وَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ', 'যে ব্যক্তি সম্পর্কে ধারণা ছিল যে, সে মুক্তি পাবে, তাকে ইউসুফ বলে দিলঃ আপন প্রভুর কাছে আমার আলোচনা করবে। অতঃপর শয়তান তাকে প্রভুর কাছে আলোচনার কথা ভুলিয়ে দিল। ফলে তাঁকে কয়েক বছর কারাগারে থাকতে হল।', 'Waqala lillathee thanna annahu najin minhuma othkurnee AAinda rabbika faansahu alshshaytanu thikra rabbihi falabitha fee alssijni bidAAa sineena', 1, NOW(), NOW()),
(17, 43, 'وَقَالَ ٱلۡمَلِكُ إِنِّيٓ أَرَىٰ سَبۡعَ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعَ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖۖ يَـٰٓأَيُّهَا ٱلۡمَلَأُ أَفۡتُونِي فِي رُءۡيَٰيَ إِن كُنتُمۡ لِلرُّءۡيَا تَعۡبُرُونَ', 'বাদশাহ বললঃ আমি স্বপ্নে দেখলাম, সাতটি মোটাতাজা গাভী-এদেরকে সাতটি শীর্ণ গাভী খেয়ে যাচ্ছে এবং সাতটি সবুজ শীষ ও অন্যগুলো শুষ্ক। হে পরিষদবর্গ! তোমরা আমাকে আমার স্বপ্নের ব্যাখ্যা বল, যদি তোমরা স্বপ্নের ব্যাখ্যায় পারদর্শী হয়ে থাক।', 'Waqala almaliku innee ara sabAAa baqaratin simanin yakuluhunna sabAAun AAijafun wasabAAa sunbulatin khudrin waokhara yabisatin ya ayyuha almalao aftoonee fee ruyaya in kuntum lilrruya taAAburoona', 1, NOW(), NOW()),
(17, 44, 'قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمٖۖ وَمَا نَحۡنُ بِتَأۡوِيلِ ٱلۡأَحۡلَٰمِ بِعَٰلِمِينَ', 'তারা বললঃ এটা কল্পনাপ্রসূত স্বপ্ন। এরূপ স্বপ্নের ব্যাখ্যা আমাদের জানা নেই।', 'Qaloo adghathu ahlamin wama nahnu bitaweeli alahlami biAAalimeena', 1, NOW(), NOW()),
(17, 45, 'وَقَالَ ٱلَّذِي نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ', 'দু’জন কারারুদ্ধের মধ্য থেকে যে ব্যক্তি মুক্তি পেয়েছিল এবং দীর্ঘকাল পর স্মরণ হলে, সে বলল, আমি তোমাদেরকে এর ব্যাখ্যা বলছি। তোমরা আমাকে প্রেরণ কর।', 'Waqala allathee naja minhuma waiddakara baAAda ommatin ana onabbiokum bitaweelihi faarsilooni', 1, NOW(), NOW()),
(17, 46, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ وَسَبۡعِ سُنۢبُلَٰتٍ خُضۡرٖ وَأُخَرَ يَابِسَٰتٖ لَّعَلِّيٓ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ يَعۡلَمُونَ', 'সে তথায় পৌঁছে বললঃ হে ইউসুফ! হে সত্যবাদী! সাতটি মোটাতাজা গাভী-তাদেরকে খাচ্ছে সাতটি শীর্ণ গাভী এবং সাতটি সবুজ শীর্ষ ও অন্যগুলো শুষ্ক; আপনি আমাদেরকে এ স্বপ্ন সম্পর্কে পথনির্দেশ প্রদান করুনঃ যাতে আমি তাদের কাছে ফিরে গিয়ে তাদের অবগত করাতে পারি।', 'Yoosufu ayyuha alssiddeequ aftina fee sabAAi baqaratin simanin yakuluhunna sabAAun AAijafun wasabAAi sunbulatin khudrin waokhara yabisatin laAAallee arjiAAu ila alnnasi laAAallahum yaAAlamoona', 1, NOW(), NOW()),
(17, 47, 'قَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ', 'বললঃ তোমরা সাত বছর উত্তম রূপে চাষাবাদ করবে। অতঃপর যা কাটবে, তার মধ্যে যে সামান্য পরিমাণ তোমরা খাবে তা ছাড়া অবশিষ্ট শস্য শীষ সমেত রেখে দেবে।', 'Qala tazraAAoona sabAAa sineena daaban fama hasadtum fatharoohu fee sunbulihi illa qaleelan mimma takuloona', 1, NOW(), NOW()),
(17, 48, 'ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ', 'এবং এরপরে আসবে দূর্ভিক্ষের সাত বছর; তোমরা এ দিনের জন্যে যা রেখেছিলে, তা খেয়ে যাবে, কিন্তু অল্প পরিমাণ ব্যতীত, যা তোমরা তুলে রাখবে।', 'Thumma yatee min baAAdi thalika sabAAun shidadun yakulna ma qaddamtum lahunna illa qaleelan mimma tuhsinoona', 1, NOW(), NOW()),
(17, 49, 'ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ عَامٞ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعۡصِرُونَ', 'এর পরেই আসবে একবছর-এতে মানুষের উপর বৃষ্টি বর্ষিত হবে এবং এতে তারা রস নিঙড়াবে।', 'Thumma yatee min baAAdi thalika AAamun feehi yughathu alnnasu wafeehi yaAAsiroona', 1, NOW(), NOW()),
(17, 50, 'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّـٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ', 'বাদশাহ বললঃ ফিরে যাও তোমাদের প্রভুর কাছে এবং জিজ্ঞেস কর তাকে ঐ মহিলার স্বরূপ কি, যারা স্বীয় হস্ত কর্তন করেছিল! আমার পালনকর্তা তো তাদের ছলনা সবই জানেন।', 'Waqala almaliku itoonee bihi falamma jaahu alrrasoolu qala irjiAA ila rabbika faisalhu ma balu alnniswati allatee qattaAAna aydiyahunna inna rabbee bikaydihinna AAaleemun', 1, NOW(), NOW()),
(17, 51, 'قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ', 'বাদশাহ মহিলাদেরকে বললেনঃ তোমাদের হাল-হাকিকত কি, যখন তোমরা ইউসুফকে আত্মসংবরণ থেকে ফুসলিয়েছিলে? তারা বললঃ আল্লাহ মহান, আমরা তার সম্পর্কে মন্দ কিছু জানি না। আযীয-পত্মি বললঃ এখন সত্য কথা প্রকাশ হয়ে গেছে। আমিই তাকে আত্মসংবরণ থেকে ফুসলিয়েছিলাম এবং সে সত্যবাদী।', 'Qala ma khatbukunna ith rawadtunna yoosufa AAan nafsihi qulna hasha lillahi ma AAalimna AAalayhi min sooin qalati imraatu alAAazeezi alana hashasa alhaqqu ana rawadtuhu AAan nafsihi wainnahu lamina alssadiqeena', 1, NOW(), NOW()),
(17, 52, 'ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ', 'ইউসুফ বললেনঃ এটা এজন্য, যাতে আযীয জেনে নেয় যে, আমি গোপনে তার সাথে বিশ্বাসঘাতকতা করিনি। আরও এই যে, আল্লাহ বিশ্বাসঘাতকদের প্রতারণাকে এগুতে দেন না।', 'Thalika liyaAAlama annee lam akhunhu bialghaybi waanna Allaha la yahdee kayda alkhaineena', 1, NOW(), NOW()),
(17, 53, '۞وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ', 'আমি নিজেকে নির্দোষ বলি না। নিশ্চয় মানুষের মন মন্দ কর্মপ্রবণ কিন্তু সে নয়-আমার পালনকর্তা যার প্রতি অনুগ্রহ করেন। নিশ্চয় আমার পালনকর্তা ক্ষমাশীল, দয়ালু।', 'Wama obarrio nafsee inna alnnafsa laammaratun bialssooi illa ma rahima rabbee inna rabbee ghafoorun raheemun', 1, NOW(), NOW()),
(17, 54, 'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ', 'বাদশাহ বললঃ তাকে আমার কাছে নিয়ে এসো। আমি তাকে নিজের বিশ্বস্ত সহচর করে রাখব। অতঃপর যখন তার সাথে মতবিনিময় করল, তখন বললঃ নিশ্চয়ই আপনি আমার কাছে আজ থেকে বিশ্বস্ত হিসাবে মর্যাদার স্থান লাভ করেছেন।', 'Waqala almaliku itoonee bihi astakhlishu linafsee falamma kallamahu qala innaka alyawma ladayna makeenun ameenun', 1, NOW(), NOW()),
(17, 55, 'قَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ', 'ইউসুফ বললঃ আমাকে দেশের ধন-ভান্ডারে নিযুক্ত করুন। আমি বিশ্বস্ত রক্ষক ও অধিক জ্ঞানবান।', 'Qala ijAAalnee AAala khazaini alardi innee hafeethun AAaleemun', 1, NOW(), NOW()),
(17, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ', 'এমনিভাবে আমি ইউসুফকে সে দেশের বুকে প্রতিষ্ঠা দান করেছি। সে তথায় যেখানে ইচ্ছা স্থান করে নিতে পারত। আমি স্বীয় রহমত যাকে ইচ্ছা পৌছে দেই এবং আমি পূণ্যবানদের প্রতিদান বিনষ্ট করি না।', 'Wakathalika makanna liyoosufa fee alardi yatabawwao minha haythu yashao nuseebu birahmatina man nashao wala nudeeAAu ajra almuhsineena', 1, NOW(), NOW()),
(17, 57, 'وَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ', 'এবং ঐ লোকদের জন্য পরকালে প্রতিদান উত্তম যারা ঈমান এনেছে ও সতর্কতা অবলম্বন করে।', 'Walaajru alakhirati khayrun lillatheena amanoo wakanoo yattaqoona', 1, NOW(), NOW()),
(17, 58, 'وَجَآءَ إِخۡوَةُ يُوسُفَ فَدَخَلُواْ عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ', 'ইউসুফের ভ্রাতারা আগমন করল, অতঃপর তার কাছে উপস্থিত হল। সে তাদেরকে চিনল এবং তারা তাকে চিনল না।', 'Wajaa ikhwatu yoosufa fadakhaloo AAalayhi faAAarafahum wahum lahu munkiroona', 1, NOW(), NOW()),
(17, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِي بِأَخٖ لَّكُم مِّنۡ أَبِيكُمۡۚ أَلَا تَرَوۡنَ أَنِّيٓ أُوفِي ٱلۡكَيۡلَ وَأَنَا۠ خَيۡرُ ٱلۡمُنزِلِينَ', 'এবং সে যখন তাদেরকে তাদের রসদ প্রস্তুত করে দিল, তখন সে বললঃ তোমাদের বৈমাত্রেয় ভাইকে আমার কাছে নিয়ে এসো। তোমরা কি দেখ না যে, আমি পুরা মাপ দেই এবং মেহমানদেরকে উত্তম সমাদার করি', 'Walamma jahhazahum bijahazihim qala itoonee biakhin lakum min abeekum ala tarawna annee oofee alkayla waana khayru almunzileena', 1, NOW(), NOW()),
(17, 60, 'فَإِن لَّمۡ تَأۡتُونِي بِهِۦ فَلَا كَيۡلَ لَكُمۡ عِندِي وَلَا تَقۡرَبُونِ', 'অতঃপর যদি তাকে আমার কাছে না আন, তবে আমার কাছে তোমাদের কোন বরাদ্ধ নেই এবং তোমরা আমার কাছে আসতে পারবে না।', 'Fain lam tatoonee bihi fala kayla lakum AAindee wala taqrabooni', 1, NOW(), NOW()),
(17, 61, 'قَالُواْ سَنُرَٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', 'তারা বললঃ আমরা তার সম্পর্কে তার পিতাকে সম্মত করার চেষ্টা করব এবং আমাদেরকে একাজ করতেই হবে।', 'Qaloo sanurawidu AAanhu abahu wainna lafaAAiloona', 1, NOW(), NOW()),
(17, 62, 'وَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ', 'এবং সে ভৃত্যদেরকে বললঃ তাদের পণ্যমূল্য তাদের রসদ-পত্রের মধ্যে রেখে দাও-সম্ভবতঃ তারা গৃহে পৌঁছে তা বুঝতে পারবে, সম্ভবতঃ তারা পুনর্বার আসবে।', 'Waqala lifityanihi ijAAaloo bidaAAatahum fee rihalihim laAAallahum yaAArifoonaha itha inqalaboo ila ahlihim laAAallahum yarjiAAoona', 1, NOW(), NOW()),
(17, 63, 'فَلَمَّا رَجَعُوٓاْ إِلَىٰٓ أَبِيهِمۡ قَالُواْ يَـٰٓأَبَانَا مُنِعَ مِنَّا ٱلۡكَيۡلُ فَأَرۡسِلۡ مَعَنَآ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'তারা যখন তাদের পিতার কাছে ফিরে এল তখন বললঃ হে আমাদের পিতা, আমাদের জন্যে খাদ্য শস্যের বরাদ্দ নিষিদ্ধ করা হয়েছে। অতএব আপনি আমাদের ভাইকে আমাদের সাথে প্রেরণ করুন; যাতে আমরা খাদ্য শস্যের বরাদ্দ আনতে পারি এবং আমরা অবশ্যই তার পুরোপুরি হেফাযত করব।', 'Falamma rajaAAoo ila abeehim qaloo ya abana muniAAa minna alkaylu faarsil maAAana akhana naktal wainna lahu lahafithoona', 1, NOW(), NOW()),
(17, 64, 'قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ', 'বললেন, আমি তার সম্পর্কে তোমাদেরকে কি সেরূপ বিশ্বাস করব, যেমন ইতিপূর্বে তার ভাই সম্পর্কে বিশ্বাস করেছিলাম? অতএব আল্লাহ উত্তম হেফাযতকারী এবং তিনিই সর্বাধিক দয়ালু।', 'Qala hal amanukum AAalayhi illa kama amintukum AAala akheehi min qablu faAllahu khayrun hafithan wahuwa arhamu alrrahimeena', 1, NOW(), NOW()),
(17, 65, 'وَلَمَّا فَتَحُواْ مَتَٰعَهُمۡ وَجَدُواْ بِضَٰعَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡۖ قَالُواْ يَـٰٓأَبَانَا مَا نَبۡغِيۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتۡ إِلَيۡنَاۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِيرٖۖ ذَٰلِكَ كَيۡلٞ يَسِيرٞ', 'এবং যখন তারা আসবাবপত্র খুলল, তখন দেখতে পেল যে, তাদেরকে তাদের পন্যমুল্য ফেরত দেয়া হয়েছে। তারা বললঃ হে আমাদের পিতা, আমরা আর কি চাইতে পারি। এই আমাদের প্রদত্ত পন্যমূল্য, আমাদেরকে ফেরত দেয়া হয়েছে। এখন আমরা আবার আমাদের পরিবারবর্গের জন্যে রসদ আনব এবং আমাদের ভাইয়ের দেখাশোনা করব এবং এক এক উটের বরাদ্দ খাদ্যশস্য আমরা অতিরিক্ত আনব। ঐ বরাদ্দ সহজ।', 'Walamma fatahoo mataAAahum wajadoo bidaAAatahum ruddat ilayhim qaloo ya abana ma nabghee hathihi bidaAAatuna ruddat ilayna wanameeru ahlana wanahfathu akhana wanazdadu kayla baAAeerin thalika kaylun yaseerun', 1, NOW(), NOW()),
(17, 66, 'قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقٗا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِي بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمۡۖ فَلَمَّآ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ', 'বললেন, তাকে ততক্ষণ তোমাদের সাথে পাঠাব না, যতক্ষণ তোমরা আমাকে আল্লাহর নামে অঙ্গীকার না দাও যে, তাকে অবশ্যই আমার কাছে পৌঁছে দেবে; কিন্তু যদি তোমরা সবাই একান্তই অসহায় না হয়ে যাও। অতঃপর যখন সবাই তাঁকে অঙ্গীকার দিল, তখন তিনি বললেনঃ আমাদের মধ্যে যা কথাবার্তা হলো সে ব্যাপারে আল্লাহই মধ্যস্থ রইলেন।', 'Qala lan orsilahu maAAakum hatta tutooni mawthiqan mina Allahi latatunnanee bihi illa an yuhata bikum falamma atawhu mawthiqahum qala Allahu AAala ma naqoolu wakeelun', 1, NOW(), NOW()),
(17, 67, 'وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ', 'ইয়াকুব বললেনঃ হে আমার বৎসগণ! সবাই একই প্রবেশদ্বার দিয়ে যেয়ো না, বরং পৃথক পৃথক দরজা দিয়ে প্রবেশ করো। আল্লাহর কোন বিধান থেকে আমি তোমাদেরকে রক্ষা করতে পারি না। নির্দেশ আল্লাহরই চলে। তাঁরই উপর আমি ভরসা করি এবং তাঁরই উপর ভরসা করা উচিত ভরসাকারীদের।', 'Waqala ya baniyya la tadkhuloo min babin wahidin waodkhuloo min abwabin mutafarriqatin wama oghnee AAankum mina Allahi min shayin ini alhukmu illa lillahi AAalayhi tawakkaltu waAAalayhi falyatawakkali almutawakkiloona', 1, NOW(), NOW()),
(17, 68, 'وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ', 'তারা যখন পিতার কথামত প্রবেশ করল, তখন আল্লাহর বিধানের বিরুদ্ধে তা তাদের বাঁচাতে পারল না। কিন্তু ইয়াকুবের সিদ্ধান্তে তাঁর মনের একটি বাসনা ছিল, যা তিনি পূর্ণ করেছেন। এবং তিনি তো আমার শেখানো বিষয় অবগত ছিলেন। কিন্তু অনেক মানুষ অবগত নয়।', 'Walamma dakhaloo min haythu amarahum aboohum ma kana yughnee AAanhum mina Allahi min shayin illa hajatan fee nafsi yaAAqooba qadaha wainnahu lathoo AAilmin lima AAallamnahu walakinna akthara alnnasi la yaAAlamoona', 1, NOW(), NOW()),
(17, 69, 'وَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَخَاهُۖ قَالَ إِنِّيٓ أَنَا۠ أَخُوكَ فَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَعۡمَلُونَ', 'যখন তারা ইউসুফের কাছে উপস্থিত হল, তখন সে আপন ভ্রাতাকে নিজের কাছে রাখল। বললঃ নিশ্চই আমি তোমার সহোদর। অতএব তাদের কৃতকর্মের জন্যে দুঃখ করো না।', 'Walamma dakhaloo AAala yoosufa awa ilayhi akhahu qala innee ana akhooka fala tabtais bima kanoo yaAAmaloona', 1, NOW(), NOW()),
(17, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ', 'অতঃপর যখন ইউসুফ তাদের রসদপত্র প্রস্তুত করে দিল, তখন পানপাত্র আপন ভাইয়ের রসদের মধ্যে রেখে দিল। অতঃপর একজন ঘোষক ডেকে বললঃ হে কাফেলার লোকজন, তোমরা অবশ্যই চোর।', 'Falamma jahhazahum bijahazihim jaAAala alssiqayata fee rahli akheehi thumma aththana muaththinun ayyatuha alAAeeru innakum lasariqoona', 1, NOW(), NOW()),
(17, 71, 'قَالُواْ وَأَقۡبَلُواْ عَلَيۡهِم مَّاذَا تَفۡقِدُونَ', 'তারা ওদের দিকে মুখ করে বললঃ তোমাদের কি হারিয়েছে', 'Qaloo waaqbaloo AAalayhim matha tafqidoona', 1, NOW(), NOW()),
(17, 72, 'قَالُواْ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمۡلُ بَعِيرٖ وَأَنَا۠ بِهِۦ زَعِيمٞ', 'তারা বললঃ আমরা বাদশাহর পানপাত্র হারিয়েছি এবং যে কেউ এটা এনে দেবে সে এক উটের বোঝা পরিমাণ মাল পাবে এবং আমি এর যামিন।', 'Qaloo nafqidu suwaAAa almaliki waliman jaa bihi himlu baAAeerin waana bihi zaAAeemun', 1, NOW(), NOW()),
(17, 73, 'قَالُواْ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِي ٱلۡأَرۡضِ وَمَا كُنَّا سَٰرِقِينَ', 'তারা বললঃ আল্লাহর কসম, তোমরা তো জান, আমরা অনর্থ ঘটাতে এদেশে আসিনি এবং আমরা কখনও চোর ছিলাম না।', 'Qaloo taAllahi laqad AAalimtum ma jina linufsida fee alardi wama kunna sariqeena', 1, NOW(), NOW()),
(17, 74, 'قَالُواْ فَمَا جَزَـٰٓؤُهُۥٓ إِن كُنتُمۡ كَٰذِبِينَ', 'তারা বললঃ যদি তোমরা মিথ্যাবাদী হও, তবে যে, চুরি করেছে তার কি শাস্তি', 'Qaloo fama jazaohu in kuntum kathibeena', 1, NOW(), NOW()),
(17, 75, 'قَالُواْ جَزَـٰٓؤُهُۥ مَن وُجِدَ فِي رَحۡلِهِۦ فَهُوَ جَزَـٰٓؤُهُۥۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ', 'তারা বললঃ এর শাস্তি এই যে, যার রসদপত্র থেকে তা পাওয়া যাবে, এর প্রতিদানে সে দাসত্বে যাবে। আমরা যালেমদেরকে এভাবেই শাস্তি দেই।', 'Qaloo jazaohu man wujida fee rahlihi fahuwa jazaohu kathalika najzee alththalimeena', 1, NOW(), NOW()),
(17, 76, 'فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَبۡلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَآءِ أَخِيهِۚ كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ', 'অতঃপর ইউসুফ আপন ভাইদের থলের পূর্বে তাদের থলে তল্লাশী শুরু করলেন। অবশেষে সেই পাত্র আপন ভাইয়ের থলের মধ্য থেকে বের করলেন। এমনিভাবে আমি ইউসুফকে কৌশল শিক্ষা দিয়েছিলাম। সে বাদশাহর আইনে আপন ভাইকে কখনও দাসত্বে দিতে পারত না, কিু栦#2438;ল্লাহ যদি ইচ্ছা করেন। আমি যাকে ইচ্ছা, মর্যাদায় উন্নীত করি এবং প্রত্যেক জ্ঞানীর উপরে আছে অধিকতর এক জ্ঞানীজন।', 'Fabadaa biawAAiyatihim qabla wiAAai akheehi thumma istakhrajaha min wiAAai akheehi kathalika kidna liyoosufa ma kana liyakhutha akhahu fee deeni almaliki illa an yashaa Allahu narfaAAu darajatin man nashao wafawqa kulli thee AAilmin AAaleemun', 1, NOW(), NOW()),
(17, 77, '۞قَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ', 'তারা বলতে লাগলঃ যদি সে চুরি করে থাকে, তবে তার এক ভাইও ইতিপূর্বে চুরি করেছিল। তখন ইউসুফ প্রকৃত ব্যাপার নিজের মনে রাখলেন এবং তাদেরকে জানালেন না। মনে মনে বললেনঃ তোমরা লোক হিসাবে নিতান্ত মন্দ এবং আল্লাহ খুব জ্ঞাত রয়েছেন, যা তোমরা বর্ণনা করছ', 'Qaloo in yasriq faqad saraqa akhun lahu min qablu faasarraha yoosufu fee nafsihi walam yubdiha lahum qala antum sharrun makanan waAllahu aAAlamu bima tasifoona', 1, NOW(), NOW()),
(17, 78, 'قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا فَخُذۡ أَحَدَنَا مَكَانَهُۥٓۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ', 'তারা বলতে লাগলঃ হে আযীয, তার পিতা আছেন, যিনি খুবই বৃদ্ধ বয়স্ক। সুতরাং আপনি আমাদের একজনকে তার বদলে রেখে দিন। আমরা আপনাকে অনুগ্রহশীল ব্যক্তিদের একজন দেখতে পাচ্ছি।', 'Qaloo ya ayyuha alAAazeezu inna lahu aban shaykhan kabeeran fakhuth ahadana makanahu inna naraka mina almuhsineena', 1, NOW(), NOW()),
(17, 79, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذٗا لَّظَٰلِمُونَ', 'তিনি বললেনঃ যার কাছে আমরা আমাদের মাল পেয়েছি, তাকে ছাড়া আর কাউকে গ্রেফতার করা থেকে আল্লাহ আমাদের রক্ষা করুন। তা হলে তো আমরা নিশ্চিতই অন্যায়কারী হয়ে যাব।', 'Qala maAAatha Allahi an nakhutha illa man wajadna mataAAana AAindahu inna ithan lathalimoona', 1, NOW(), NOW()),
(17, 80, 'فَلَمَّا ٱسۡتَيۡـَٔسُواْ مِنۡهُ خَلَصُواْ نَجِيّٗاۖ قَالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَمُوٓاْ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَيۡكُم مَّوۡثِقٗا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِي يُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ يَأۡذَنَ لِيٓ أَبِيٓ أَوۡ يَحۡكُمَ ٱللَّهُ لِيۖ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ', 'অতঃপর যখন তারা তাঁর কাছ থেকে নিরাশ হয়ে গেল, তখন পরামর্শের জন্যে এখানে বসল। তাদের জ্যেষ্ঠ ভাই বললঃ তোমরা কি জান না যে, পিতা তোমাদের কাছ থেকে আল্লাহর নামে অঙ্গীকার নিয়েছেন এবং পূর্বে ইউসুফের ব্যাপারেও তোমরা অন্যায় করেছো? অতএব আমি তো কিছুতেই এদেশ ত্যাগ করব না, যে পর্যন্ত না পিতা আমাকে আদেশ দেন অথবা আল্লাহ আমার পক্ষে কোন ব্যবস্থা করে দেন। তিনিই সর্বোত্তম ব্যবস্থাপক।', 'Falamma istayasoo minhu khalasoo najiyyan qala kabeeruhum alam taAAlamoo anna abakum qad akhatha AAalaykum mawthiqan mina Allahi wamin qablu ma farrattum fee yoosufa falan abraha alarda hatta yathana lee abee aw yahkuma Allahu lee wahuwa khayru alhakimeena', 1, NOW(), NOW()),
(17, 81, 'ٱرۡجِعُوٓاْ إِلَىٰٓ أَبِيكُمۡ فَقُولُواْ يَـٰٓأَبَانَآ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ', 'তোমরা তোমাদের পিতার কাছে ফিরে যাও এবং বলঃ পিতা আপনার ছেলে চুরি করেছে। আমরা তাই বলে দিলাম, যা আমাদের জানা ছিল এবং অদৃশ্য বিষয়ের প্রতি আমাদের লক্ষ্য ছিল না।', 'IrjiAAoo ila abeekum faqooloo ya abana inna ibnaka saraqa wama shahidna illa bima AAalimna wama kunna lilghaybi hafitheena', 1, NOW(), NOW()),
(17, 82, 'وَسۡـَٔلِ ٱلۡقَرۡيَةَ ٱلَّتِي كُنَّا فِيهَا وَٱلۡعِيرَ ٱلَّتِيٓ أَقۡبَلۡنَا فِيهَاۖ وَإِنَّا لَصَٰدِقُونَ', 'জিজ্ঞেস করুন ঐ জনপদের লোকদেরকে যেখানে আমরা ছিলাম এবং ঐ কাফেলাকে, যাদের সাথে আমরা এসেছি। নিশ্চিতই আমরা সত্য বলছি।', 'Waisali alqaryata allatee kunna feeha waalAAeera allatee aqbalna feeha wainna lasadiqoona', 1, NOW(), NOW()),
(17, 83, 'قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', 'তিনি বললেনঃ কিছুই না, তোমরা মনগড়া একটি কথা নিয়েই এসেছ। এখন ধৈর্য্যধারণই উত্তম। সম্ভবতঃ আল্লাহ তাদের সবাইকে একসঙ্গে আমার কাছে নিয়ে আসবেন তিনি সুবিজ্ঞ, প্রজ্ঞাময়।', 'Qala bal sawwalat lakum anfusukum amran fasabrun jameelun AAasa Allahu an yatiyanee bihim jameeAAan innahu huwa alAAaleemu alhakeemu', 1, NOW(), NOW()),
(17, 84, 'وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَـٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ', 'এবং তাদের দিক থেকে তিনি মুখ ফিরিয়ে নিলেন এবং বললেনঃ হায় আফসোস ইউসুফের জন্যে। এবং দুঃখে তাঁর চক্ষুদ্বয় সাদা হয়ে গেল। এবং অসহনীয় মনস্তাপে তিনি ছিলেন ক্লিষ্ট।', 'Watawalla AAanhum waqala ya asafa AAala yoosufa waibyaddat AAaynahu mina alhuzni fahuwa katheemun', 1, NOW(), NOW()),
(17, 85, 'قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ', 'তারা বলতে লাগলঃ আল্লাহর কসম আপনি তো ইউসুফের স্মরণ থেকে নিবৃত হবেন না, যে পর্যন্ত মরণপন্ন না হয়ে যান কিংবা মৃতবরণ না করেন', 'Qaloo taAllahi taftao tathkuru yoosufa hatta takoona haradan aw takoona mina alhalikeena', 1, NOW(), NOW()),
(17, 86, 'قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'তিনি বললেনঃ আমি তো আমার দুঃখ ও অস্থিরতা আল্লাহর সমীপেই নিবেদন করছি এবং আল্লাহর পক্ষ থেকে আমি যা জানি, তা তোমরা জান না।', 'Qala innama ashkoo baththee wahuznee ila Allahi waaAAlamu mina Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(17, 87, 'يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ', 'বৎসগণ! যাও, ইউসুফ ও তার ভাইকে তালাশ কর এবং আল্লাহর রহমত থেকে নিরাশ হয়ো না। নিশ্চয় আল্লাহর রহমত থেকে কাফের সম্প্রদায়, ব্যতীত অন্য কেউ নিরাশ হয় না।', 'Ya baniyya ithhaboo fatahassasoo min yoosufa waakheehi wala tayasoo min rawhi Allahi innahu la yayasu min rawhi Allahi illa alqawmu alkafiroona', 1, NOW(), NOW()),
(17, 88, 'فَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَـٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ', 'অতঃপর যখন তারা ইউসুফের কাছে পৌঁছল তখন বললঃ হে আযীয, আমরা ও আমাদের পরিবারবর্গ কষ্টের সম্মুখীন হয়ে পড়েছি এবং আমরা অপর্যাপ্ত পুঁজি নিয়ে এসেছি। অতএব আপনি আমাদের পুরোপুরি বরাদ্দ দিন এবং আমাদের কে দান করুন। আল্লাহ দাতাদেরকে প্রতিদান দিয়ে থাকেন।', 'Falamma dakhaloo AAalayhi qaloo ya ayyuha alAAazeezu massana waahlana alddurru wajina bibidaAAatin muzjatin faawfi lana alkayla watasaddaq AAalayna inna Allaha yajzee almutasaddiqeena', 1, NOW(), NOW()),
(17, 89, 'قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ', 'ইউসুফ বললেনঃ তোমাদের জানা আছে কি, যা তোমরা ইউসুফ ও তার ভাইয়ের সাথে করেছ, যখন তোমরা অপরিণামদর্শী ছিলে', 'Qala hal AAalimtum ma faAAaltum biyoosufa waakheehi ith antum jahiloona', 1, NOW(), NOW()),
(17, 90, 'قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ', 'তারা বলল, তবে কি তুমিই ইউসুফ! বললেনঃ আমিই ইউসুফ এবং এ হল আমার সহোদর ভাই। আল্লাহ আমাদের প্রতি অনুগ্রহ করেছেন। নিশ্চয় যে তাকওয়া অবলম্বন করে এবং সবর করে, আল্লাহ এহেন সৎকর্মশীলদের প্রতিদান বিনষ্ট করেন না।', 'Qaloo ainnaka laanta yoosufa qala ana yoosufu wahatha akhee qad manna Allahu AAalayna innahu man yattaqi wayasbir fainna Allaha la yudeeAAu ajra almuhsineena', 1, NOW(), NOW()),
(17, 91, 'قَالُواْ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَيۡنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'তারা বললঃ আল্লাহর কসম, আমাদের চাইতে আল্লাহ তোমাকে পছন্দ করেছেন এবং আমরা অবশ্যই অপরাধী ছিলাম।', 'Qaloo taAllahi laqad atharaka Allahu AAalayna wain kunna lakhatieena', 1, NOW(), NOW()),
(17, 92, 'قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّـٰحِمِينَ', 'বললেন, আজ তোমাদের বিরুদ্ধে কোন অভিযোগ নেই। আল্লাহ তোমাদের কে ক্ষমা করুন। তিনি সব মেহেরবানদের চাইতে অধিক মেহেরবান।', 'Qala la tathreeba AAalaykumu alyawma yaghfiru Allahu lakum wahuwa arhamu alrrahimeena', 1, NOW(), NOW()),
(17, 93, 'ٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا وَأۡتُونِي بِأَهۡلِكُمۡ أَجۡمَعِينَ', 'তোমরা আমার এ জামাটি নিয়ে যাও। এটি আমার পিতার মুখমন্ডলের উপর রেখে দিও, এতে তাঁর দৃষ্টি শক্তি ফিরে আসবে। আর তোমাদের পরিবারবর্গের সবাইকে আমার কাছে নিয়ে এস।', 'Ithhaboo biqameesee hatha faalqoohu AAala wajhi abee yati baseeran watoonee biahlikum ajmaAAeena', 1, NOW(), NOW()),
(17, 94, 'وَلَمَّا فَصَلَتِ ٱلۡعِيرُ قَالَ أَبُوهُمۡ إِنِّي لَأَجِدُ رِيحَ يُوسُفَۖ لَوۡلَآ أَن تُفَنِّدُونِ', 'যখন কাফেলা রওয়ানা হল, তখন তাদের পিতা বললেনঃ যদি তোমরা আমাকে অপ্রকৃতিস্থ না বল, তবে বলিঃ আমি নিশ্চিতরূপেই ইউসুফের গন্ধ পাচ্ছি।', 'Walamma fasalati alAAeeru qala aboohum innee laajidu reeha yoosufa lawla an tufannidooni', 1, NOW(), NOW()),
(17, 95, 'قَالُواْ تَٱللَّهِ إِنَّكَ لَفِي ضَلَٰلِكَ ٱلۡقَدِيمِ', 'লোকেরা বললঃ আল্লাহর কসম, আপনি তো সেই পুরানো ভ্রান্তিতেই পড়ে আছেন।', 'Qaloo taAllahi innaka lafee dalalika alqadeemi', 1, NOW(), NOW()),
(17, 96, 'فَلَمَّآ أَن جَآءَ ٱلۡبَشِيرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِيرٗاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ', 'অতঃপর যখন সুসংবাদদাতা পৌঁছল, সে জামাটি তাঁর মুখে রাখল। অমনি তিনি দৃষ্টি শক্তি ফিরে পেলেন। বললেনঃ আমি কি তোমাদেরকে বলিনি যে, আমি আল্লাহর পক্ষ থেকে যা জানি তোমরা তা জান না', 'Falamma an jaa albasheeru alqahu AAala wajhihi fairtadda baseeran qala alam aqul lakum innee aAAlamu mina Allahi ma la taAAlamoona', 1, NOW(), NOW()),
(17, 97, 'قَالُواْ يَـٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', 'তারা বললঃ পিতা আমাদের অপরাধ ক্ষমা করান। নিশ্চয় আমরা অপরাধী ছিলাম।', 'Qaloo ya abana istaghfir lana thunoobana inna kunna khatieena', 1, NOW(), NOW()),
(17, 98, 'قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ', 'বললেন, সত্বরই আমি পালনকর্তার কাছে তোমাদের জন্য ক্ষমা চাইব। নিশ্চয় তিনি ক্ষমাশীল, দয়ালূ।', 'Qala sawfa astaghfiru lakum rabbee innahu huwa alghafooru alrraheemu', 1, NOW(), NOW()),
(17, 99, 'فَلَمَّا دَخَلُواْ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيۡهِ أَبَوَيۡهِ وَقَالَ ٱدۡخُلُواْ مِصۡرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', 'অতঃপর যখন তারা ইউসুফের কাছে পৌঁছল, তখন ইউসুফ পিতা-মাতাকে নিজের কাছে জায়গা দিলেন এবং বললেনঃ আল্লাহ চাহেন তো শান্তি চিত্তে মিসরে প্রবেশ করুন।', 'Falamma dakhaloo AAala yoosufa awa ilayhi abawayhi waqala odkhuloo misra in shaa Allahu amineena', 1, NOW(), NOW()),
(17, 100, 'وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَـٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', 'এবং তিনি পিতা-মাতাকে সিংহাসনের উপর বসালেন এবং তারা সবাই তাঁর সামনে সেজদাবনত হল। তিনি বললেনঃ পিতা এ হচ্ছে আমার ইতিপূর্বেকার স্বপ্নের বর্ণনা আমার পালনকর্তা একে সত্যে পরিণত করেছেন এবং তিনি আমার প্রতি অনুগ্রহ করেছেন। আমাকে জেল থেকে বের করেছেন এবং আপনাদেরকে গ্রাম থেকে নিয়ে এসেছেন, শয়তান আমার ও আমার ভাইদের মধ্যে কলহ সৃষ্টি করে দেয়ার পর। আমার পালনকর্তা যা চান, কৌশলে সম্পন্ন করেন। নিশ্চয় তিনি বিজ্ঞ, প্রজ্ঞাময়।', 'WarafaAAa abawayhi AAala alAAarshi wakharroo lahu sujjadan waqala ya abati hatha taweelu ruyaya min qablu qad jaAAalaha rabbee haqqan waqad ahsana bee ith akhrajanee mina alssijni wajaa bikum mina albadwi min baAAdi an nazagha alshshaytanu baynee wabayna ikhwatee inna rabbee lateefun lima yashao innahu huwa alAAaleemu alhakeemu', 1, NOW(), NOW()),
(17, 101, '۞رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ', 'হে পালনকর্তা আপনি আমাকে রাষ্ট্রক্ষমতাও দান করেছেন এবং আমাকে বিভিন্ন তাৎপর্য সহ ব্যাখ্যা করার বিদ্যা শিখিয়ে দিয়েছেন। হে নভোমন্ডল ও ভূ-মন্ডলের স্রষ্টা, আপনিই আমার কার্যনির্বাহী ইহকাল ও পরকালে। আমাকে ইসলামের উপর মৃত্যুদান করুন এবং আমাকে স্বজনদের সাথে মিলিত করুন।', 'Rabbi qad ataytanee mina almulki waAAallamtanee min taweeli alahadeethi fatira alssamawati waalardi anta waliyyee fee alddunya waalakhirati tawaffanee musliman waalhiqnee bialssaliheena', 1, NOW(), NOW()),
(17, 102, 'ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۖ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ أَجۡمَعُوٓاْ أَمۡرَهُمۡ وَهُمۡ يَمۡكُرُونَ', 'এগুলো অদৃশ্যের খবর, আমি আপনার কাছে প্রেরণ করি। আপনি তাদের কাছে ছিলেন না, যখন তারা স্বীয় কাজ সাব্যস্ত করছিল এবং চক্রান্ত করছিল।', 'Thalika min anbai alghaybi nooheehi ilayka wama kunta ladayhim ith ajmaAAoo amrahum wahum yamkuroona', 1, NOW(), NOW()),
(17, 103, 'وَمَآ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِينَ', 'আপনি যতই চান, অধিকাংশ লোক বিশ্বাসকারী নয়।', 'Wama aktharu alnnasi walaw harasta bimumineena', 1, NOW(), NOW()),
(17, 104, 'وَمَا تَسۡـَٔلُهُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ', 'আপনি এর জন্যে তাদের কাছে কোন বিনিময় চান না। এটা তো সারা বিশ্বের জন্যে উপদেশ বৈ নয়।', 'Wama tasaluhum AAalayhi min ajrin in huwa illa thikrun lilAAalameena', 1, NOW(), NOW()),
(17, 105, 'وَكَأَيِّن مِّنۡ ءَايَةٖ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ', 'অনেক নিদর্শন রয়েছে নভোমন্ডলে ও ভু-মন্ডলে যেগুলোর উপর দিয়ে তারা পথ অতিক্রম করে এবং তারা এসবের দিকে মনোনিবেশ করে না।', 'Wakaayyin min ayatin fee alssamawati waalardi yamurroona AAalayha wahum AAanha muAAridoona', 1, NOW(), NOW()),
(17, 106, 'وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ', 'অনেক মানুষ আল্লাহর প্রতি বিশ্বাস স্থাপন করে, কিন্তু সাথে সাথে শিরকও করে।', 'Wama yuminu aktharuhum biAllahi illa wahum mushrikoona', 1, NOW(), NOW()),
(17, 107, 'أَفَأَمِنُوٓاْ أَن تَأۡتِيَهُمۡ غَٰشِيَةٞ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ', 'তারা কি নির্ভীক হয়ে গেছে এ বিষয়ে যে, আল্লাহর আযাবের কোন বিপদ তাদেরকে আবৃত করে ফেলবে অথবা তাদের কাছে হঠাৎ কেয়ামত এসে যাবে, অথচ তারা টেরও পাবে না', 'Afaaminoo an tatiyahum ghashiyatun min AAathabi Allahi aw tatiyahumu alssaAAatu baghtatan wahum la yashAAuroona', 1, NOW(), NOW()),
(17, 108, 'قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ', 'বলে দিনঃ এই আমার পথ। আমি আল্লাহর দিকে বুঝে সুঝে দাওয়াত দেই আমি এবং আমার অনুসারীরা। আল্লাহ পবিত্র। আমি অংশীবাদীদের অন্তর্ভুক্ত নই।', 'Qul hathihi sabeelee adAAoo ila Allahi AAala baseeratin ana wamani ittabaAAanee wasubhana Allahi wama ana mina almushrikeena', 1, NOW(), NOW()),
(17, 109, 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰٓۗ أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ٱتَّقَوۡاْۚ أَفَلَا تَعۡقِلُونَ', 'আপনার পূর্বে আমি যতজনকে রসূল করে পাঠিয়েছি, তারা সবাই পুরুষই ছিল জনপদবাসীদের মধ্য থেকে। আমি তাঁদের কাছে ওহী প্রেরণ করতাম। তারা কি দেশ-বিদেশ ভ্রমণ করে না, যাতে দেখে নিত কিরূপ পরিণতি হয়েছে তাদের যারা পূর্বে ছিল ? সংযমকারীদের জন্যে পরকালের আবাসই উত্তম। তারা কি এখনও বোঝে না', 'Wama arsalna min qablika illa rijalan noohee ilayhim min ahli alqura afalam yaseeroo fee alardi fayanthuroo kayfa kana AAaqibatu allatheena min qablihim waladaru alakhirati khayrun lillatheena ittaqaw afala taAAqiloona', 1, NOW(), NOW()),
(17, 110, 'حَتَّىٰٓ إِذَا ٱسۡتَيۡـَٔسَ ٱلرُّسُلُ وَظَنُّوٓاْ أَنَّهُمۡ قَدۡ كُذِبُواْ جَآءَهُمۡ نَصۡرُنَا فَنُجِّيَ مَن نَّشَآءُۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ', 'এমনকি যখন পয়গম্বরগণ নৈরাশ্যে পতিত হয়ে যেতেন, এমনকি এরূপ ধারণা করতে শুরু করতেন যে, তাদের অনুমান বুঝি মিথ্যায় পরিণত হওয়ার উপক্রম হয়েছিল, তখন তাদের কাছে আমার সাহায্য পৌছে। অতঃপর আমি যাদের চেয়েছি তারা উদ্ধার পেয়েছে। আমার শাস্তি অপরাধী সম্প্রদায় থেকে প্রতিহত হয় না।', 'Hatta itha istayasa alrrusulu wathannoo annahum qad kuthiboo jaahum nasruna fanujjiya man nashao wala yuraddu basuna AAani alqawmi almujrimeena', 1, NOW(), NOW()),
(17, 111, 'لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ', 'তাদের কাহিনীতে বুদ্ধিমানদের জন্য রয়েছে প্রচুর শিক্ষণীয় বিষয়, এটা কোন মনগড়া কথা নয়, কিন্তু যারা বিশ্বাস স্থাপন করে তাদের জন্যে পূর্বেকার কালামের সমর্থন এবং প্রত্যেক বস্তুর বিবরণ রহমত ও হেদায়েত।', 'Laqad kana fee qasasihim AAibratun liolee alalbabi ma kana hadeethan yuftara walakin tasdeeqa allathee bayna yadayhi watafseela kulli shayin wahudan warahmatan liqawmin yuminoona', 1, NOW(), NOW()),
(18, 1, 'الٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ', 'আলিফ-লাম-মীম-রা; এগুলো কিতাবের আয়াত। যা কিছু আপনার পালনকর্তার পক্ষ থেকে অবতীর্ণ হয়েছে, তা সত্য। কিন্তু অধিকাংশ মানুষ এতে বিশ্বাস করে না।', 'Aliflammeemra tilka ayatu alkitabi waallathee onzila ilayka min rabbika alhaqqu walakinna akthara alnnasi la yuminoona', 1, NOW(), NOW()),
(18, 2, 'ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ', 'আল্লাহ, যিনি উর্ধ্বদেশে স্থাপন করেছেন আকাশমন্ডলীকে স্তম্ভ ব্যতীত। তোমরা সেগুলো দেখ। অতঃপর তিনি আরশের উপর অধিষ্ঠিত হয়েছেন। এবং সূর্য ও চন্দ্রকে কর্মে নিয়োজিত করেছেন। প্রত্যেকে নির্দিষ্ট সময় মোতাবেক আবর্তন করে। তিনি সকল বিষয় পরিচালনা করেন, নিদর্শনসমূহ প্রকাশ করেন, যাতে তোমরা স্বীয় পালনকর্তার সাথে সাক্ষাত সম্বন্ধে নিশ্চিত বিশ্বাসী হও।', 'Allahu allathee rafaAAa alssamawati bighayri AAamadin tarawnaha thumma istawa AAala alAAarshi wasakhkhara alshshamsa waalqamara kullun yajree liajalin musamman yudabbiru alamra yufassilu alayati laAAallakum biliqai rabbikum tooqinoona', 1, NOW(), NOW()),
(18, 3, 'وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ', 'তিনিই ভুমন্ডলকে বিস্তৃত করেছেন এবং তাতে পাহাড় পর্বত ও নদ-নদী স্থাপন করেছেন এবং প্রত্যেক ফলের মধ্যে দু’দু প্রকার সৃষ্টি করে রেখেছেন। তিনি দিনকে রাত্রি দ্বারা আবৃত করেন। এতে তাদের জন্যে নিদর্শণ রয়েছে, যারা চিন্তা করে।', 'Wahuwa allathee madda alarda wajaAAala feeha rawasiya waanharan wamin kulli alththamarati jaAAala feeha zawjayni ithnayni yughshee allayla alnnahara inna fee thalika laayatin liqawmin yatafakkaroona', 1, NOW(), NOW()),
(18, 4, 'وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّـٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ', 'এবং যমিনে বিভিন্ন শস্য ক্ষেত্র রয়েছে-একটি অপরটির সাথে সংলগ্ন এবং আঙ্গুরের বাগান আছে আর শস্য ও খজ্জꦣ2497;র রয়েছে-একটির মূল অপরটির সাথে মিলিত এবং কতক মিলিত নয়। এগুলো কে একই পানি দ্বারা সেচ করা হয়। আর আমি স্বাদে একটিকে অপরটির চাইতে উৎকৃষ্টতর করে দেই। এগুলোর মধ্যে নিদর্শণ রয়েছে তাদের জন্য যারা চিন্তা ভাবনা করে।', 'Wafee alardi qitaAAun mutajawiratun wajannatun min aAAnabin wazarAAun wanakheelun sinwanun waghayru sinwanin yusqa bimain wahidin wanufaddilu baAAdaha AAala baAAdin fee alokuli inna fee thalika laayatin liqawmin yaAAqiloona', 1, NOW(), NOW()),
(18, 5, '۞وَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ جَدِيدٍۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَـٰٓئِكَ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَاقِهِمۡۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ', 'যদি আপনি বিস্ময়ের বিষয় চান, তবে তাদের একথা বিস্ময়কর যে, আমরা যখন মাটি হয়ে যাব, তখনও কি নতুন ভাবে সৃজিত হব? এরাই স্বীয় পালনকর্তার সত্তায় অবিশ্বাসী হয়ে গেছে, এদের গর্দানেই লৌহ-শৃংখল পড়বে এবং এরাই দোযখী এরা তাতে চিরকাল থাকবে।', 'Wain taAAjab faAAajabun qawluhum aitha kunna turaban ainna lafee khalqin jadeedin olaika allatheena kafaroo birabbihim waolaika alaghlalu fee aAAnaqihim waolaika ashabu alnnari hum feeha khalidoona', 1, NOW(), NOW()),
(18, 6, 'وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ', 'এরা আপনার কাছে মঙ্গলের পরিবর্তে দ্রুত অমঙ্গল কামনা করে। তাদের পূর্বে অনুরূপ অনেক শাস্তিপ্রাপ্ত জনগোষ্ঠী অতিক্রান্ত হয়েছে। আপনার পালনকর্তা মানুষকে তাদের অন্যায় সত্বেও ক্ষমা করেন এবং আপনার পালনকর্তা কঠিন শাস্তিদাতা ও বটে।', 'WayastaAAjiloonaka bialssayyiati qabla alhasanati waqad khalat min qablihimu almathulatu wainna rabbaka lathoo maghfiratin lilnnasi AAala thulmihim wainna rabbaka lashadeedu alAAiqabi', 1, NOW(), NOW()),
(18, 7, 'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرٞۖ وَلِكُلِّ قَوۡمٍ هَادٍ', 'কাফেররা বলেঃ তাঁর প্রতি তাঁর পালনকর্তার পক্ষ থেকে কোন নিদর্শন অবতীর্ণ হল না কেন? আপনার কাজ তো ভয় প্রদর্শন করাই এবং প্রত্যেক সম্প্রদায়ের জন্যে পথপ্রদর্শক হয়েছে।', 'Wayaqoolu allatheena kafaroo lawla onzila AAalayhi ayatun min rabbihi innama anta munthirun walikulli qawmin hadin', 1, NOW(), NOW()),
(18, 8, 'ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَيۡءٍ عِندَهُۥ بِمِقۡدَارٍ', 'আল্লাহ জানেন প্রত্যেক নারী যা গর্ভধারণ করে এবং গর্ভাশয়ে যা সঙ্কুচিত ও বর্ধিত হয়। এবং তাঁর কাছে প্রত্যেক বস্তুরই একটা পরিমাণ রয়েছে।', 'Allahu yaAAlamu ma tahmilu kullu ontha wama tagheedu alarhamu wama tazdadu wakullu shayin AAindahu bimiqdarin', 1, NOW(), NOW()),
(18, 9, 'عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ', 'তিনি সকল গোপন ও প্রকাশ্য বিষয় অবগত, মহোত্তম, সর্বোচ্চ মর্যাদাবান।', 'AAalimu alghaybi waalshshahadati alkabeeru almutaAAali', 1, NOW(), NOW()),
(18, 10, 'سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ بِٱلنَّهَارِ', 'তোমাদের মধ্যে কেউ গোপনে কথা বলুক বা তা সশব্দে প্রকাশ করুক, রাতের অন্ধকারে সে আত্নগোপন করুক বা প্রকাশ্য দিবালোকে বিচরণ করুক, সবাই তাঁর নিকট সমান।', 'Sawaon minkum man asarra alqawla waman jahara bihi waman huwa mustakhfin biallayli wasaribun bialnnahari', 1, NOW(), NOW()),
(18, 11, 'لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'তাঁর পক্ষ থেকে অনুসরণকারী রয়েছে তাদের অগ্রে এবং পশ্চাতে, আল্লাহর নির্দেশে তারা ওদের হেফাযত করে। আল্লাহ কোন জাতির অবস্থা পরিবর্তন করেন না, যে পর্যন্ত না তারা তাদের নিজেদের অবস্থা পরিবর্তন করে। আল্লাহ যখন কোন জাতির উপর বিপদ চান, তখন তা রদ হওয়ার নয় এবং তিনি ব্যতীত তাদের কোন সাহায্যকারী নেই।', 'Lahu muAAaqqibatun min bayni yadayhi wamin khalfihi yahfathoonahu min amri Allahi inna Allaha la yughayyiru ma biqawmin hatta yughayyiroo ma bianfusihim waitha arada Allahu biqawmin sooan fala maradda lahu wama lahum min doonihi min walin', 1, NOW(), NOW()),
(18, 12, 'هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', 'তিনিই তোমাদেরকে বিদ্যুৎ দেখান ভয়ের জন্যে এবং আশার জন্যে এবং উক্ষিত করেন ঘন মেঘমালা।', 'Huwa allathee yureekumu albarqa khawfan watamaAAan wayunshio alssahaba alththiqala', 1, NOW(), NOW()),
(18, 13, 'وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَـٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ', 'তাঁর প্রশংসা পাঠ করে বজ্র এবং সব ফেরেশতা, সভয়ে। তিনি বজ্রপাত করেন, অতঃপর যাকে ইচছা, তাকে তা দ্বারা আঘাত করেন; তথাপি তারা আল্লাহ সম্পর্কে বিতন্ডা করে, অথচ তিনি মহাশক্তিশালী।', 'Wayusabbihu alrraAAdu bihamdihi waalmalaikatu min kheefatihi wayursilu alssawaAAiqa fayuseebu biha man yashao wahum yujadiloona fee Allahi wahuwa shadeedu almihali', 1, NOW(), NOW()),
(18, 14, 'لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ', 'সত্যের আহবান একমাত্র তাঁরই এবং তাকে ছাড়া যাদেরকে ডাকে, তারা তাদের কোন কাজে আসে না; ওদের দৃষ্টান্ত সেরূপ, যেমন কেউ দু’ হাত পানির দিকে প্রসারিত করে যাতে পানি তার মুখে পৌঁছে যায়। অথচ পানি কোন সময় পৌঁছাবে না। কাফেরদের যত আহবান তার সবই পথভ্রষ্টতা।', 'Lahu daAAwatu alhaqqi waallatheena yadAAoona min doonihi la yastajeeboona lahum bishayin illa kabasiti kaffayhi ila almai liyablugha fahu wama huwa bibalighihi wama duAAao alkafireena illa fee dalalin', 1, NOW(), NOW()),
(18, 15, 'وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩', 'আল্লাহকে সেজদা করে যা কিছু নভোমন্ডলে ও ভূমন্ডলে আছে ইচ্ছায় অথবা অনিচ্ছায় এবং তাদের প্রতিচ্ছায়াও সকাল-সন্ধ্যায়।', 'Walillahi yasjudu man fee alssamawati waalardi tawAAan wakarhan wathilaluhum bialghuduwwi waalasali', 1, NOW(), NOW()),
(18, 16, 'قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّـٰرُ', 'জিজ্ঞেস করুন নভোমন্ডল ও ভুমন্ডলের পালনকর্তা কে? বলে দিনঃ আল্লাহ! বলুনঃ তবে কি তোমরা আল্লাহ ব্যতীত এমন অভিভাবক স্থির করেছ, যারা নিজেদের ভাল-মন্দের ও মালিক নয়? বলুনঃ অন্ধ চক্ষুষ্মান কি সমান হয়? অথবা কোথাও কি অন্ধকার ও আলো সমান হয়। তবে কি তারা আল্লাহর জন্য এমন অংশীদার স্থির করেছে যে, তারা কিছু সৃষ্টি করেছে, যেমন সৃষ্টি করেছেন আল্লাহ? অতঃপর তাদের সৃষ্টি এরূপ বিভ্রান্তি ঘটিয়েছে? বলুনঃ আল্লাহই প্রত্যেক বস্তুর স্রষ্টা এবং তিনি একক, পরাক্রমশালী।', 'Qul man rabbu alssamawati waalardi quli Allahu qul afaittakhathtum min doonihi awliyaa la yamlikoona lianfusihim nafAAan wala darran qul hal yastawee alaAAma waalbaseeru am hal tastawee alththulumatu waalnnooru am jaAAaloo lillahi shurakaa khalaqoo kakhalqihi fatashabaha alkhalqu AAalayhim quli Allahu khaliqu kulli shayin wahuwa alwahidu alqahharu', 1, NOW(), NOW()),
(18, 17, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ', 'তিনি আকাশ থেকে পানি বর্ষণ করেন। অতঃপর স্রোতধারা প্রবাহিত হতে থাকে নিজ নিজ পরিমাণ অনুযায়ী। অতঃপর স্রোতধারা স্ফীত ফেনারাশি উপরে নিয়ে আসে। এবং অলঙ্কার অথবা তৈজসপত্রের জন্যে যে বস্তুকে আগুনে উত্তপ্ত করে, তাতেও তেমনি ফেনারাশি থাকে। এমনি ভাবে আল্লাহ সত্য ও অসত্যের দৃষ্টান্ত প্রদান করেন। অতএব, ফেনা তো শুকিয়ে খতম হয়ে যায় এবং যা মানুষের উপকারে আসে, তা জমিতে অবশিষ্ট থাকে। আল্লাহ এমনিভাবে দৃষ্টান্তসমূহ বর্ণনা করেন।', 'Anzala mina alssamai maan fasalat awdiyatun biqadariha faihtamala alssaylu zabadan rabiyan wamimma yooqidoona AAalayhi fee alnnari ibtighaa hilyatin aw mataAAin zabadun mithluhu kathalika yadribu Allahu alhaqqa waalbatila faamma alzzabadu fayathhabu jufaan waamma ma yanfaAAu alnnasa fayamkuthu fee alardi kathalika yadribu Allahu alamthala', 1, NOW(), NOW()),
(18, 18, 'لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ أُوْلَـٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ', 'যারা পালনকর্তার আদেশ পালন করে, তাদের জন্য উত্তম প্রতিদান রয়েছে এবং যারা আদেশ পালন করে না, যদি তাদের কাছে জগতের সবকিছু থাকে এবং তার সাথে তার সমপরিমাণ আরও থাকে, তবে সবই নিজেদের মুক্তিপণ স্বরূপ দিয়ে দেবে। তাদের জন্যে রয়েছে কঠোর হিসাব। তাদের আবাস হবে জাহান্নাম। সেটা কতইনা নিকৃষ্ট অবস্থান।', 'Lillatheena istajaboo lirabbihimu alhusna waallatheena lam yastajeeboo lahu law anna lahum ma fee alardi jameeAAan wamithlahu maAAahu laiftadaw bihi olaika lahum sooo alhisabi wamawahum jahannamu wabisa almihadu', 1, NOW(), NOW()),
(18, 19, '۞أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ', 'যে ব্যক্তি জানে যে, যা কিছু পালনকর্তার পক্ষ থেকে আপনার প্রতি অবর্তীর্ণ হয়েছে তা সত্য সে কি ঐ ব্যক্তির সমান, যে অন্ধ? তারাই বোঝে, যারা বোধশক্তি সম্পন্ন।', 'Afaman yaAAlamu annama onzila ilayka min rabbika alhaqqu kaman huwa aAAma innama yatathakkaru oloo alalbabi', 1, NOW(), NOW()),
(18, 20, 'ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ', 'এরা এমন লোক, যারা আল্লাহর প্রতিশ্রুতি পূর্ণ করে এবং অঙ্গীকার ভঙ্গ করে না।', 'Allatheena yoofoona biAAahdi Allahi wala yanqudoona almeethaqa', 1, NOW(), NOW()),
(18, 21, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ', 'এবং যারা বজায় রাখে ঐ সম্পর্ক, যা বজায় রাখতে আল্লাহ আদেশ দিয়েছেন এবং স্বীয় পালনকর্তাকে ভয় করে এবং কঠোর হিসাবের আশঙ্কা রাখে।', 'Waallatheena yasiloona ma amara Allahu bihi an yoosala wayakhshawna rabbahum wayakhafoona sooa alhisabi', 1, NOW(), NOW()),
(18, 22, 'وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَـٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ', 'এবং যারা স্বীয় পালনকর্তার সন্তুষ্টির জন্যে সবর করে, নামায প্রতিষ্টা করে আর আমি তাদেরকে যা দিয়েছি, তা থেকে গোপনে ও প্রকাশ্য ব্যয় করে এবং যারা মন্দের বিপরীতে ভাল করে, তাদের জন্যে রয়েছে পরকালের গৃহ।', 'Waallatheena sabaroo ibtighaa wajhi rabbihim waaqamoo alssalata waanfaqoo mimma razaqnahum sirran waAAalaniyatan wayadraoona bialhasanati alssayyiata olaika lahum AAuqba alddari', 1, NOW(), NOW()),
(18, 23, 'جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۖ وَٱلۡمَلَـٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ', 'তা হচ্ছে বসবাসের বাগান। তাতে তারা প্রবেশ করবে এবং তাদের সৎকর্মশীল বাপ-দাদা, স্বামী-স্ত্রী ও সন্তানেরা। ফেরেশতারা তাদের কাছে আসবে প্রত্যেক দরজা দিয়ে।', 'Jannatu AAadnin yadkhuloonaha waman salaha min abaihim waazwajihim wathurriyyatihim waalmalaikatu yadkhuloona AAalayhim min kulli babin', 1, NOW(), NOW()),
(18, 24, 'سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ', 'বলবেঃ তোমাদের সবরের কারণে তোমাদের উপর শান্তি বর্ষিত হোক। আর তোমাদের এ পরিণাম-গৃহ কতই না চমৎকার।', 'Salamun AAalaykum bima sabartum faniAAma AAuqba alddari', 1, NOW(), NOW()),
(18, 25, 'وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَـٰٓئِكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ', 'এবং যারা আল্লাহর অঙ্গীকারকে দৃঢ় ও পাকা-পোক্ত করার পর তা ভঙ্গ করে, আল্লাহ যে, সম্পর্ক বজায় রাখতে আদেশ করেছেন, তা ছিন্ন করে এবং পৃথিবীতে অশান্তি সৃষ্টি করে, ওরা ঐ সমস্ত লোক যাদের জন্যে রয়েছে অভিসম্পাত এবং ওদের জন্যে রয়েছে কঠিন আযাব।', 'Waallatheena yanqudoona AAahda Allahi min baAAdi meethaqihi wayaqtaAAoona ma amara Allahu bihi an yoosala wayufsidoona fee alardi olaika lahumu allaAAnatu walahum sooo alddari', 1, NOW(), NOW()),
(18, 26, 'ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ', 'আল্লাহ যার জন্যে ইচ্ছা রুযী প্রশস্ত করেন এবং সংকুচিত করেন। তারা পার্থিব জীবনের প্রতি মুগ্ধ। পার্থিবজীবন পরকালের সামনে অতি সামান্য সম্পদ বৈ নয়।', 'Allahu yabsutu alrrizqa liman yashao wayaqdiru wafarihoo bialhayati alddunya wama alhayatu alddunya fee alakhirati illa mataAAun', 1, NOW(), NOW()),
(18, 27, 'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ', 'কাফেররা বলেঃ তাঁর প্রতি তাঁর পালনকর্তার পক্ষ থেকে কোন নিদর্শন কেন অবতীর্ণ হলো না? বলে দিন, আল্লাহ যাকে ইচ্ছা পথভ্রষ্ট করেন এবং যে, মনোনিবেশ করে, তাকে নিজের দিকে পথপ্রদর্শন করেন।', 'Wayaqoolu allatheena kafaroo lawla onzila AAalayhi ayatun min rabbihi qul inna Allaha yudillu man yashao wayahdee ilayhi man anaba', 1, NOW(), NOW()),
(18, 28, 'ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ', 'যারা বিশ্বাস স্থাপন করে এবং তাদের অন্তর আল্লাহর যিকির দ্বারা শান্তি লাভ করে; জেনে রাখ, আল্লাহর যিকির দ্বারাই অন্তর সমূহ শান্তি পায়।', 'Allatheena amanoo watatmainnu quloobuhum bithikri Allahi ala bithikri Allahi tatmainnu alquloobu', 1, NOW(), NOW()),
(18, 29, 'ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابٖ', 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে, তাদের জন্যে রয়েছে সুসংবাদ এবং মনোরম প্রত্যাবর্তণস্থল।', 'Allatheena amanoo waAAamiloo alssalihati tooba lahum wahusnu maabin', 1, NOW(), NOW()),
(18, 30, 'كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةٖ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمٞ لِّتَتۡلُوَاْ عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ قُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ', 'এমনিভাবে আমি আপনাকে একটি উম্মতের মধ্যে প্রেরণ করেছি। তাদের পূর্বে অনেক উম্মত অতিক্রান্ত হয়েছে। যাতে আপনি তাদেরকে ঐ নির্দেশ শুনিয়ে দেন, যা আমি আপনার কাছে প্রেরণ করেছি। তথাপি তারা দয়াময়কে অস্বীকার করে। বলুনঃ তিনিই আমার পালনকর্তা। তিনি ব্যতীত কারও উপাসনা নাই। আমি তাঁর উপরই ভরসা করেছি এবং তাঁর দিকেই আমার প্রত্যাবর্তণ।', 'Kathalika arsalnaka fee ommatin qad khalat min qabliha omamun litatluwa AAalayhimu allathee awhayna ilayka wahum yakfuroona bialrrahmani qul huwa rabbee la ilaha illa huwa AAalayhi tawakkaltu wailayhi matabi', 1, NOW(), NOW()),
(18, 31, 'وَلَوۡ أَنَّ قُرۡءَانٗا سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبٗا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ', 'যদি কোন কোরআন এমন হত, যার সাহায্যে পাহাড় চলমান হয় অথবা যমীন খন্ডিত হয় অথবা মৃতরা কথা বলে, তবে কি হত? বরং সব কাজ তো আল্লাহর হাতে। ঈমানদাররা কি এ ব্যাপারে নিশ্চিত নয় যে, যদি আল্লাহ চাইতেন, তবে সব মানুষকে সৎপথে পরিচালিত করতেন? কাফেররা তাদের কৃতকর্মের কারণে সব সময় আঘাত পেতে থাকবে অথবা তাদের গৃহের নিকটবর্তী স্থানে আঘাত নেমে আসবে, যে, পর্যন্ত আল্লাহর ওয়াদা না আসে। নিশ্চয় আল্লাহ ওয়াদার খেলাফ করেন না।', 'Walaw anna quranan suyyirat bihi aljibalu aw quttiAAat bihi alardu aw kullima bihi almawta bal lillahi alamru jameeAAan afalam yayasi allatheena amanoo an law yashao Allahu lahada alnnasa jameeAAan wala yazalu allatheena kafaroo tuseebuhum bima sanaAAoo qariAAatun aw tahullu qareeban min darihim hatta yatiya waAAdu Allahi inna Allaha la yukhlifu almeeAAada', 1, NOW(), NOW()),
(18, 32, 'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ', 'আপনার পূর্বে কত রাসূলের সাথে ঠাট্টা করা হয়েছে। অতঃপর আমি কাফেরদেরকে কিছু অবকাশ দিয়েছি। , এর পর তাদেরকে পাকড়াও করেছি। অতএব কেমন ছিল আমার শাস্তি।', 'Walaqadi istuhzia birusulin min qablika faamlaytu lillatheena kafaroo thumma akhathtuhum fakayfa kana AAiqabi', 1, NOW(), NOW()),
(18, 33, 'أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُواْ لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعۡلَمُ فِي ٱلۡأَرۡضِ أَم بِظَٰهِرٖ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُواْ مَكۡرُهُمۡ وَصُدُّواْ عَنِ ٱلسَّبِيلِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ', 'ওরা প্রত্যেকেই কি মাথার উপর স্ব স্ব কৃতকর্ম নিয়ে দন্ডায়মান নয়? এবং তারা আল্লাহর জন্য অংশীদার সাব্যস্ত করে। বলুন; নাম বল অথবা খবর দাও পৃথিবীর এমন কিছু জিনিস সম্পর্কে যা তিনি জানেন না? অথবা অসার কথাবার্তা বলছ? বরং সুশোভিত করা হয়েছে কাফেরদের জন্যে তাদের প্রতারণাকে এবং তাদেরকে সৎপথ থেকে বাধা দান করা হয়েছে। আল্লাহ যাকে পথভ্রষ্ট করেন, তার কোন পথ প্রদর্শক নেই।', 'Afaman huwa qaimun AAala kulli nafsin bima kasabat wajaAAaloo lillahi shurakaa qul sammoohum am tunabbioonahu bima la yaAAlamu fee alardi am bithahirin mina alqawli bal zuyyina lillatheena kafaroo makruhum wasuddoo AAani alssabeeli waman yudlili Allahu fama lahu min hadin', 1, NOW(), NOW()),
(18, 34, 'لَّهُمۡ عَذَابٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ', 'দুনিয়ার জীবনেই এদের জন্য রয়েছে আযাব এবং অতি অবশ্য আখেরাতের জীবন কঠোরতম। আল্লাহর কবল থেকে তাদের কোন রক্ষাকারী নেই।', 'Lahum AAathabun fee alhayati alddunya walaAAathabu alakhirati ashaqqu wama lahum mina Allahi min waqin', 1, NOW(), NOW()),
(18, 35, '۞مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ أُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى ٱلۡكَٰفِرِينَ ٱلنَّارُ', 'পরহেযগারদের জন্যে প্রতিশ্রুত জান্নাতের অবস্থা এই যে, তার নিম্নে নির্ঝরিণীসমূহ প্রবাহিত হয়। তার ফলসমূহ চিরস্থায়ী এবং ছায়াও। এটা তাদের প্রতিদান, যারা সাবধান হয়েছে এবং কাফেরদের প্রতিফল অগ্নি।', 'Mathalu aljannati allatee wuAAida almuttaqoona tajree min tahtiha alanharu okuluha daimun wathilluha tilka AAuqba allatheena ittaqaw waAAuqba alkafireena alnnaru', 1, NOW(), NOW()),
(18, 36, 'وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ', 'এবং যাদেরকে আমি গ্রন্থ দিয়েছি, তারা আপনার প্রতি যা অবতীর্ণ হয়েছে, তজ্জন্যে আনন্দিত হয় এবং কোন কোন দল এর কোন কোন বিষয় অস্বীকার করে। বলুন, আমাকে এরূপ আদেশই দেয়া হয়েছে যে, আমি আল্লাহর এবাদত করি। এবং তাঁর সাথে অংশীদার না করি। আমি তাঁর দিকেই দাওয়াত দেই এবং তাঁর কাছেই আমার প্রত্যাবর্তন।', 'Waallatheena ataynahumu alkitaba yafrahoona bima onzila ilayka wamina alahzabi man yunkiru baAAdahu qul innama omirtu an aAAbuda Allaha wala oshrika bihi ilayhi adAAoo wailayhi maabi', 1, NOW(), NOW()),
(18, 37, 'وَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيّٗاۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا وَاقٖ', 'এমনিভাবেই আমি এ কোরআনকে আরবী ভাষায় নির্দেশরূপে অবতীর্ণ করেছি। যদি আপনি তাদের প্রবৃত্তির অনুসরণ করেন আপনার কাছে জ্ঞান পৌঁছার পর, তবে আল্লাহর কবল থেকে আপনার না কোন সাহায্যকারী আছে এবং না কোন রক্ষাকারী।', 'Wakathalika anzalnahu hukman AAarabiyyan walaini ittabaAAta ahwaahum baAAda ma jaaka mina alAAilmi ma laka mina Allahi min waliyyin wala waqin', 1, NOW(), NOW()),
(18, 38, 'وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَٰجٗا وَذُرِّيَّةٗۚ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلٖ كِتَابٞ', 'আপনার পূর্বে আমি অনেক রসূল প্রেরণ করেছি এবং তাঁদেরকে পত্নী ও সন্তান-সন্ততি দিয়েছি। কোন রসূলের এমন সাধ্য ছিল না যে আল্লাহর নির্দেশ ছাড়া কোন নিদর্শন উপস্থিত করে। প্রত্যেকটি ওয়াদা লিখিত আছে।', 'Walaqad arsalna rusulan min qablika wajaAAalna lahum azwajan wathurriyyatan wama kana lirasoolin an yatiya biayatin illa biithni Allahi likulli ajalin kitabun', 1, NOW(), NOW()),
(18, 39, 'يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ', 'আল্লাহ যা ইচ্ছা মিটিয়ে দেন এবং বহাল রাখেন এবং মূলগ্রন্থ তাঁর কাছেই রয়েছে।', 'Yamhoo Allahu ma yashao wayuthbitu waAAindahu ommu alkitabi', 1, NOW(), NOW()),
(18, 40, 'وَإِن مَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ', 'আমি তাদের সাথে যে ওয়াদা করেছি, তার কোন একটি যদি আপনাকে দেখিয়ে দেই কিংবা আপনাকে উঠিয়ে নেই, তাতে কি আপনার দায়িত্ব তো পৌছে দেয়া এবং আমার দায়িত্ব হিসাব নেয়া।', 'Wain ma nuriyannaka baAAda allathee naAAiduhum aw natawaffayannaka fainnama AAalayka albalaghu waAAalayna alhisabu', 1, NOW(), NOW()),
(18, 41, 'أَوَلَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِيعُ ٱلۡحِسَابِ', 'তারা কি দেখে না যে, আমি তাদের দেশকে চতুর্দিক থেকে সমানে সঙ্কুচিত করে আসছি? আল্লাহ নির্দেশ দেন। তাঁর নির্দেশকে পশ্চাতে নিক্ষেপকারী কেউ নেই। তিনি দ্রুত হিসাব গ্রহণ করেন।', 'Awalam yaraw anna natee alarda nanqusuha min atrafiha waAllahu yahkumu la muAAaqqiba lihukmihi wahuwa sareeAAu alhisabi', 1, NOW(), NOW()),
(18, 42, 'وَقَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعٗاۖ يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسٖۗ وَسَيَعۡلَمُ ٱلۡكُفَّـٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ', 'তাদের পূর্বে যারা ছিল, তারা চক্রান্ত করেছে। আর সকল চক্রান্ত তো আল্লাহর হাতেই আছে। তিনি জানেন প্রত্যেক ব্যক্তি যা কিছু করে। কাফেররা জেনে নেবে যে, পর জীবনের আবাসস্থল কাদের জন্য রয়েছে।', 'Waqad makara allatheena min qablihim falillahi almakru jameeAAan yaAAlamu ma taksibu kullu nafsin wasayaAAlamu alkuffaru liman AAuqba alddari', 1, NOW(), NOW()),
(18, 43, 'وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلٗاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ', 'কাফেররা বলেঃ আপনি প্রেরিত ব্যক্তি নন। বলে দিন, আমার ও তোমাদের মধ্যে প্রকৃষ্ট সাক্ষী হচ্ছেন আল্লাহ এবং ঐ ব্যক্তি, যার কাছে গ্রন্থের জ্ঞান আছে।', 'Wayaqoolu allatheena kafaroo lasta mursalan qul kafa biAllahi shaheedan baynee wabaynakum waman AAindahu AAilmu alkitabi', 1, NOW(), NOW()),
(19, 1, 'الٓرۚ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ', 'আলিফ-লাম-রা; এটি একটি গ্রন্থ, যা আমি আপনার প্রতি নাযিল করেছি-যাতে আপনি মানুষকে অন্ধকার থেকে আলোর দিকে বের করে আনেন-পরাক্রান্ত, প্রশংসার যোগ্য পালনকর্তার নির্দেশে তাঁরই পথের দিকে।', 'Aliflamra kitabun anzalnahu ilayka litukhrija alnnasa mina alththulumati ila alnnoori biithni rabbihim ila sirati alAAazeezi alhameedi', 1, NOW(), NOW()),
(19, 2, 'ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَوَيۡلٞ لِّلۡكَٰفِرِينَ مِنۡ عَذَابٖ شَدِيدٍ', 'তিনি আল্লাহ; যিনি নভোমন্ডল ও ভূ-মন্ডলের সবকিছুর মালিক। কাফেরদের জন্যে বিপদ রয়েছে, কঠোর আযাব', 'Allahi allathee lahu ma fee alssamawati wama fee alardi wawaylun lilkafireena min AAathabin shadeedin', 1, NOW(), NOW()),
(19, 3, 'ٱلَّذِينَ يَسۡتَحِبُّونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدٖ', 'যারা পরকালের চাইতে পার্থিব জীবনকে পছন্দ করে; আল্লাহর পথে বাধা দান করে এবং তাতে বক্রতা অন্বেষণ করে, তারা পথ ভুলে দূরে পড়ে আছে।', 'Allatheena yastahibboona alhayata alddunya AAala alakhirati wayasuddoona AAan sabeeli Allahi wayabghoonaha AAiwajan olaika fee dalalin baAAeedin', 1, NOW(), NOW()),
(19, 4, 'وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'আমি সব পয়গম্বরকেই তাদের স্বজাতির ভাষাভাষী করেই প্রেরণ করেছি, যাতে তাদেরকে পরিষ্কার বোঝাতে পারে। অতঃপর আল্লাহ যাকে ইচ্ছা, পথঃভ্রষ্ট করেন এবং যাকে ইচ্ছা সৎপথ প্রদর্শন করেন। তিনি পরাক্রান্ত, প্রজ্ঞাময়।', 'Wama arsalna min rasoolin illa bilisani qawmihi liyubayyina lahum fayudillu Allahu man yashao wayahdee man yashao wahuwa alAAazeezu alhakeemu', 1, NOW(), NOW()),
(19, 5, 'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ', 'আমি মূসাকে নিদর্শনাবলী সহ প্রেরণ করেছিলাম যে, স্বজাতিকে অন্ধকার থেকে আলোর দিকে আনয়ন এবং তাদেরকে আল্লাহর দিনসমূহ স্মরণ করান। নিশ্চয় এতে প্রত্যেক ধৈর্যশীল কৃতজ্ঞের জন্যে নিদর্শনাবলী রয়েছে।', 'Walaqad arsalna moosa biayatina an akhrij qawmaka mina alththulumati ila alnnoori wathakkirhum biayyami Allahi inna fee thalika laayatin likulli sabbarin shakoorin', 1, NOW(), NOW()),
(19, 6, 'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ', 'যখন মূসা স্বজাতিকে বললেনঃ তোমাদের প্রতি আল্লাহর অনুগ্রহ স্মরণ কর যখন তিনি তোমাদেরকে ফেরাউনের সম্প্রদায়ের কবল থেকে মুক্তি দেন। তারা তোমাদেরকে অত্যন্ত নিকৃষ্ট ধরনের শাস্তি দিত, তোমাদের ছেলেদেরকে হত্যা করত এবং তোমাদের মেয়েদেরকে জীবিত রাখত। এবং এতে তোমাদের পালনকর্তার পক্ষ থেকে বিরাট পরীক্ষা হয়েছিল।', 'Waith qala moosa liqawmihi othkuroo niAAmata Allahi AAalaykum ith anjakum min ali firAAawna yasoomoonakum sooa alAAathabi wayuthabbihoona abnaakum wayastahyoona nisaakum wafee thalikum balaon min rabbikum AAatheemun', 1, NOW(), NOW()),
(19, 7, 'وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ', 'যখন তোমাদের পালনকর্তা ঘোষণা করলেন যে, যদি কৃতজ্ঞতা স্বীকার কর, তবে তোমাদেরকে আরও দেব এবং যদি অকৃতজ্ঞ হও তবে নিশ্চয়ই আমার শাস্তি হবে কঠোর।', 'Waith taaththana rabbukum lain shakartum laazeedannakum walain kafartum inna AAathabee lashadeedun', 1, NOW(), NOW()),
(19, 8, 'وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ', 'এবং মূসা বললেনঃ তোমরা এবং পৃথিবীর সবাই যদি কুফরী কর, তথাপি আল্লাহ অমুখাপেক্ষী, যাবতীয় গুনের আধার।', 'Waqala moosa in takfuroo antum waman fee alardi jameeAAan fainna Allaha laghaniyyun hameedun', 1, NOW(), NOW()),
(19, 9, 'أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ', 'তোমাদের কাছে কি তোমাদের পূর্ববর্তী কওমে নূহ, আদ ও সামুদের এবং তাদের পরবর্তীদের খবর পৌছেনি? তাদের বিষয়ে আল্লাহ ছাড়া আর কেউ জানে না। তাদের কাছে তাদের পয়গম্বর প্রমানাদি নিয়ে আগমন করেন। অতঃপর তারা নিজেদের হাত নিজেদের মুখে রেখে দিয়েছে এবং বলেছে, যা কিছু সহ তোমাদেরকে প্রেরণ করা হয়েছে, আমরা তা মানি না এবং যে পথের দিকে তোমরা আমাদেরকে দাওয়াত দাও, সে সম্পর্কে আমাদের মনে সন্দেহ আছে, যা আমাদেরকে উৎকন্ঠায় ফেলে রেখেছে।', 'Alam yatikum nabao allatheena min qablikum qawmi noohin waAAadin wathamooda waallatheena min baAAdihim la yaAAlamuhum illa Allahu jaathum rusuluhum bialbayyinati faraddoo aydiyahum fee afwahihim waqaloo inna kafarna bima orsiltum bihi wainna lafee shakkin mimma tadAAoonana ilayhi mureebun', 1, NOW(), NOW()),
(19, 10, '۞قَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَدۡعُوكُمۡ لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنٖ مُّبِينٖ', 'তাদের পয়গম্বরগণ বলেছিলেনঃ আল্লাহ সম্পর্কে কি সন্দেহ আছে, যিনি নভোমন্ডল ও ভুমন্ডলের স্রষ্টা? তিনি তোমাদেরকে আহবান করেন যাতে তোমাদের কিছু গুনাহ ক্ষমা করেন এবং নির্দিষ্ট মেয়াদ পর্যন্ত তোমাদের সময় দেন। তারা বলতঃ তোমরা তো আমাদের মতই মানুষ! তোমরা আমাদেরকে ঐ উপাস্য থেকে বিরত রাখতে চাও, যার এবাদত আমাদের পিতৃপুরুষগণ করত। অতএব তোমরা কোন সুস্পষ্ট প্রমাণ আনয়ন কর।', 'Qalat rusuluhum afee Allahi shakkun fatiri alssamawati waalardi yadAAookum liyaghfira lakum min thunoobikum wayuakhkhirakum ila ajalin musamman qaloo in antum illa basharun mithluna tureedoona an tasuddoona AAamma kana yaAAbudu abaona fatoona bisultanin mubeenin', 1, NOW(), NOW()),
(19, 11, 'قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرٞ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَآ أَن نَّأۡتِيَكُم بِسُلۡطَٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ', 'তাদের পয়গম্বর তাদেরকে বলেনঃ আমারাও তোমাদের মত মানুষ, কিন্তু আল্লাহ বান্দাদের মধ্য থেকে যার উপরে ইচ্ছা, অনুগ্রহ করেন। আল্লাহর নির্দেশ ব্যতীত তোমাদের কাছে প্রমাণ নিয়ে আসা আমাদের কাজ নয়; ঈমানদারদের আল্লাহর উপর ভরসা করা চাই।', 'Qalat lahum rusuluhum in nahnu illa basharun mithlukum walakinna Allaha yamunnu AAala man yashao min AAibadihi wama kana lana an natiyakum bisultanin illa biithni Allahi waAAala Allahi falyatawakkali almuminoona', 1, NOW(), NOW()),
(19, 12, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ', 'আমাদের আল্লাহর উপর ভরসা না করার কি কারণ থাকতে পারে, অথচ তিনি আমাদেরকে আমাদের পথ বলে দিয়েছেন। তোমরা আমাদেরকে যে পীড়ন করেছ, তজ্জন্যে আমরা সবর করব। ভরসাকারিগণের আল্লাহর উপরই ভরসা করা উচিত।', 'Wama lana alla natawakkala AAala Allahi waqad hadana subulana walanasbiranna AAala ma athaytumoona waAAala Allahi falyatawakkali almutawakkiloona', 1, NOW(), NOW()),
(19, 13, 'وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّـٰلِمِينَ', 'কাফেররা পয়গম্বরগণকে বলেছিলঃ আমরা তোমাদেরকে দেশ থেকে বের করে দেব অথবা তোমরা আমাদের ধর্মে ফিরে আসবে। তখন তাদের কাছে তাদের পালনকর্তা ওহী প্রেরণ করলেন যে, আমি জালিমদেরকে অবশ্যই ধ্বংস করে দেব।', 'Waqala allatheena kafaroo lirusulihim lanukhrijannakum min ardina aw lataAAoodunna fee millatina faawha ilayhim rabbuhum lanuhlikanna alththalimeena', 1, NOW(), NOW()),
(19, 14, 'وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ', 'তাদের পর তোমাদেরকে দেশে আবাদ করব। এটা ঐ ব্যক্তি পায়, যে আমার সামনে দন্ডায়মান হওয়াকে এবং আমার আযাবের ওয়াদাকে ভয় করে।', 'Walanuskinannakumu alarda min baAAdihim thalika liman khafa maqamee wakhafa waAAeedi', 1, NOW(), NOW()),
(19, 15, 'وَٱسۡتَفۡتَحُواْ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٖ', 'পয়গম্বরগণ ফয়সালা চাইতে লাগলেন এবং প্রত্যেক অবাধ্য, হঠকারী ব্যর্থ কাম হল।', 'Waistaftahoo wakhaba kullu jabbarin AAaneedin', 1, NOW(), NOW()),
(19, 16, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسۡقَىٰ مِن مَّآءٖ صَدِيدٖ', 'তার পেছনে দোযখ রয়েছে। তাতে পূঁজ মিশানো পানি পান করানো হবে।', 'Min waraihi jahannamu wayusqa min main sadeedin', 1, NOW(), NOW()),
(19, 17, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ وَمَا هُوَ بِمَيِّتٖۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٞ', 'ঢোক গিলে তা পান করবে। এবং গলার ভিতরে প্রবেশ করতে পারবে না। প্রতি দিক থেকে তার কাছে মৃত্যু আগমন করবে এবং সে মরবে না। তার পশ্চাতেও রয়েছে কঠোর আযাব।', 'YatajarraAAuhu wala yakadu yuseeghuhu wayateehi almawtu min kulli makanin wama huwa bimayyitin wamin waraihi AAathabun ghaleethun', 1, NOW(), NOW()),
(19, 18, 'مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ', 'যারা স্বীয় পালনকর্তার সত্তার অবিশ্বাসী তাদের অবস্থা এই যে, তাদের কর্মসমূহ ছাইভস্মের মত যার উপর দিয়ে প্রবল বাতাস বয়ে যায় ধূলিঝড়ের দিন। তাদের উপার্জনের কোন অংশই তাদের করতলগত হবে না। এটাই দুরবর্তী পথভ্রষ্টতা।', 'Mathalu allatheena kafaroo birabbihim aAAmaluhum karamadin ishtaddat bihi alrreehu fee yawmin AAasifin la yaqdiroona mimma kasaboo AAala shayin thalika huwa alddalalu albaAAeedu', 1, NOW(), NOW()),
(19, 19, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ', 'তুমি কি দেখনি যে, আল্লাহ নভোমন্ডল ও ভুমন্ডল যথাবিধি সৃষ্টি করেছেন? যদি তিনি ইচ্ছা করেন, তবে তোমাদেরকে বিলুপ্তিতে নিয়ে যাবেন এবং নতুন সৃষ্টি আনয়ন করবেন।', 'Alam tara anna Allaha khalaqa alssamawati waalarda bialhaqqi in yasha yuthhibkum wayati bikhalqin jadeedin', 1, NOW(), NOW()),
(19, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ', 'এটা আল্লাহর পক্ষে মোটেই কঠিন নয়।', 'Wama thalika AAala Allahi biAAazeezin', 1, NOW(), NOW()),
(19, 21, 'وَبَرَزُواْ لِلَّهِ جَمِيعٗا فَقَالَ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَيۡءٖۚ قَالُواْ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَيۡنَٰكُمۡۖ سَوَآءٌ عَلَيۡنَآ أَجَزِعۡنَآ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِيصٖ', 'সবাই আল্লাহর সামনে দন্ডায়মান হবে এবং দুর্বলেরা বড়দেরকে বলবেঃ আমরা তো তোমাদের অনুসারী ছিলাম-অতএব, তোমরা আল্লাহর আযাব থেকে আমাদেরকে কিছুমাত্র রক্ষা করবে কি? তারা বলবেঃ যদি আল্লাহ আমাদেরকে সৎপথ দেখাতেন, তবে আমরা অবশ্যই তোমাদের কে সৎপথ দেখাতাম। এখন তো আমাদের ধৈর্য্যচ্যুত হই কিংবা সবর করি-সবই আমাদের জন্যে সমান আমাদের রেহাই নেই।', 'Wabarazoo lillahi jameeAAan faqala aldduAAafao lillatheena istakbaroo inna kunna lakum tabaAAan fahal antum mughnoona AAanna min AAathabi Allahi min shayin qaloo law hadana Allahu lahadaynakum sawaon AAalayna ajaziAAna am sabarna ma lana min maheesin', 1, NOW(), NOW()),
(19, 22, 'وَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ بِمَآ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ', 'যখন সব কাজের ফায়সলা হয়ে যাবে, তখন শয়তান বলবেঃ নিশ্চয় আল্লাহ তোমাদেরকে সত্য ওয়াদা দিয়েছিলেন এবং আমি তোমাদের সাথে ওয়াদা করেছি, অতঃপর তা ভঙ্গ করেছি। তোমাদের উপর তো আমার কোন ক্ষমতা ছিল না, কিন্তু এতটুকু যে, আমি তোমাদেরকে ডেকেছি, অতঃপর তোমরা আমার কথা মেনে নিয়েছ। অতএব তোমরা আমাকে ভৎর্সনা করো না এবং নিজেদেরকেই ভৎর্সনা কর। আমি তোমাদের উদ্ধারে সাহায্যকারী নই। এবং তোমরাও আমার উদ্ধারে সাহায্যকারী নও। ইতোপূর্বে তোমরা আমাকে যে আল্লাহর শরীক করেছিলে, আমি তা অস্বীকার করি। নিশ্চয় যারা জালেম তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।', 'Waqala alshshaytanu lamma qudiya alamru inna Allaha waAAadakum waAAda alhaqqi wawaAAadtukum faakhlaftukum wama kana liya AAalaykum min sultanin illa an daAAawtukum faistajabtum lee fala taloomoonee waloomoo anfusakum ma ana bimusrikhikum wama antum bimusrikhiyya innee kafartu bima ashraktumooni min qablu inna alththalimeena lahum AAathabun aleemun', 1, NOW(), NOW()),
(19, 23, 'وَأُدۡخِلَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِيَّتُهُمۡ فِيهَا سَلَٰمٌ', 'এবং যারা বিশ্বাস স্থাপণ করে এবং সৎকর্ম সম্পাদন করে তাদেরকে এমন উদ্যানে প্রবেশ করানো হবে, যার পাদদেশ দিয়ে নির্ঝরিনী সমূহ প্রবাহিত হবে তারা তাতে পালনকর্তার নির্দেশে অনন্তকাল থাকবে। যেখানে তাদের সম্ভাষণ হবে সালাম।', 'Waodkhila allatheena amanoo waAAamiloo alssalihati jannatin tajree min tahtiha alanharu khalideena feeha biithni rabbihim tahiyyatuhum feeha salamun', 1, NOW(), NOW()),
(19, 24, 'أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ', 'তুমি কি লক্ষ্য কর না, আল্লাহ তা’আলা কেমন উপমা বর্ণনা করেছেনঃ পবিত্র বাক্য হলো পবিত্র বৃক্ষের মত। তার শিকড় মজবুত এবং শাখা আকাশে উত্থিত।', 'Alam tara kayfa daraba Allahu mathalan kalimatan tayyibatan kashajaratin tayyibatin asluha thabitun wafarAAuha fee alssamai', 1, NOW(), NOW()),
(19, 25, 'تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ', 'সে পালনকর্তার নির্দেশে অহরহ ফল দান করে। আল্লাহ মানুষের জন্যে দৃষ্টান্ত বর্ণণা করেন-যাতে তারা চিন্তা-ভাবনা করে।', 'Tutee okulaha kulla heenin biithni rabbiha wayadribu Allahu alamthala lilnnasi laAAallahum yatathakkaroona', 1, NOW(), NOW()),
(19, 26, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ', 'এবং নোংরা বাক্যের উদাহরণ হলো নোংরা বৃক্ষ। একে মাটির উপর থেকে উপড়ে নেয়া হয়েছে। এর কোন স্থিতি নেই।', 'Wamathalu kalimatin khabeethatin kashajaratin khabeethatin ijtuththat min fawqi alardi ma laha min qararin', 1, NOW(), NOW()),
(19, 27, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ', 'আল্লাহ তা’আলা মুমিনদেরকে মজবুত বাক্য দ্বারা মজবুত করেন। পার্থিবজীবনে এবং পরকালে। এবং আল্লাহ জালেমদেরকে পথভ্রষ্ট করেন। আল্লাহ যা ইচ্ছা, তা করেন।', 'Yuthabbitu Allahu allatheena amanoo bialqawli alththabiti fee alhayati alddunya wafee alakhirati wayudillu Allahu alththalimeena wayafAAalu Allahu ma yashao', 1, NOW(), NOW()),
(19, 28, '۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ', 'তুমি কি তাদের কে দেখনি, যারা আল্লাহর নেয়ামতকে কুফরে পরিণত করেছে এবং স্ব-জাতিকে সম্মুখীন করেছে ধ্বংসের আলয়ে।', 'Alam tara ila allatheena baddaloo niAAmata Allahi kufran waahalloo qawmahum dara albawari', 1, NOW(), NOW()),
(19, 29, 'جَهَنَّمَ يَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ', 'দোযখের? তারা তাতে প্রবেশ করবে সেটা কতই না মন্দ আবাস।', 'Jahannama yaslawnaha wabisa alqararu', 1, NOW(), NOW()),
(19, 30, 'وَجَعَلُواْ لِلَّهِ أَندَادٗا لِّيُضِلُّواْ عَن سَبِيلِهِۦۗ قُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ', 'এবং তারা আল্লাহর জন্যে সমকক্ষ স্থির করেছে, যাতে তারা তার পথ থেকে বিচ্যুত করে দেয়। বলুনঃ মজা উপভোগ করে নাও। অতঃপর তোমাদেরকে অগ্নির দিকেই ফিরে যেতে হবে।', 'WajaAAaloo lillahi andadan liyudilloo AAan sabeelihi qul tamattaAAoo fainna maseerakum ila alnnari', 1, NOW(), NOW()),
(19, 31, 'قُل لِّعِبَادِيَ ٱلَّذِينَ ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خِلَٰلٌ', 'আমার বান্দাদেরকে বলে দিন যারা বিশ্বাস স্থাপন করেছে, তারা নামায কায়েম রাখুক এবং আমার দেয়া রিযিক থেকে গোপনে ও প্রকাশ্যে ব্যয় করুক ঐদিন আসার আগে, যেদিন কোন বেচা কেনা নেই এবং বন্ধুত্বও নেই।', 'Qul liAAibadiya allatheena amanoo yuqeemoo alssalata wayunfiqoo mimma razaqnahum sirran waAAalaniyatan min qabli an yatiya yawmun la bayAAun feehi wala khilalun', 1, NOW(), NOW()),
(19, 32, 'ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ', 'তিনিই আল্লাহ, যিনি নভোমন্ডল ও ভুমন্ডল সৃজন করেছেন এবং আকাশ থেকে পানি বর্ষণ করে অতঃপর তা দ্বারা তোমাদের জন্যে ফলের রিযিক উৎপন্ন করেছেন এবং নৌকাকে তোমাদের আজ্ঞাবহ করেছেন, যাতে তাঁর আদেশে সমুদ্রে চলা ফেরা করে এবং নদ-নদীকে তোমাদের সেবায় নিয়োজিত করেছেন।', 'Allahu allathee khalaqa alssamawati waalarda waanzala mina alssamai maan faakhraja bihi mina alththamarati rizqan lakum wasakhkhara lakumu alfulka litajriya fee albahri biamrihi wasakhkhara lakumu alanhara', 1, NOW(), NOW()),
(19, 33, 'وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ', 'এবং তোমাদের সেবায় নিয়োজিত করেছেন সূর্যকে এবং চন্দ্রকে সর্বদা এক নিয়মে এবং রাত্রি ও দিবাকে তোমাদের কাজে লাগিয়েছেন।', 'Wasakhkhara lakumu alshshamsa waalqamara daibayni wasakhkhara lakumu allayla waalnnahara', 1, NOW(), NOW()),
(19, 34, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومٞ كَفَّارٞ', 'যে সকল বস্তু তোমরা চেয়েছ, তার প্রত্যেকটি থেকেই তিনি তোমাদেরকে দিয়েছেন। যদি আল্লাহর নেয়ামত গণনা কর, তবে গুণে শেষ করতে পারবে না। নিশ্চয় মানুষ অত্যন্ত অন্যায়কারী, অকৃতজ্ঞ।', 'Waatakum min kulli ma saaltumoohu wain taAAuddoo niAAmata Allahi la tuhsooha inna alinsana lathaloomun kaffarun', 1, NOW(), NOW()),
(19, 35, 'وَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ', 'যখন ইব্রাহীম বললেনঃ হে পালনকর্তা, এ শহরকে শান্তিময় করে দিন এবং আমাকে ও আমার সন্তান সন্ততিকে মূর্তি পূজা থেকে দূরে রাখুন।', 'Waith qala ibraheemu rabbi ijAAal hatha albalada aminan waojnubnee wabaniyya an naAAbuda alasnama', 1, NOW(), NOW()),
(19, 36, 'رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ', 'হে পালনকর্তা, এরা অনেক মানুষকে বিপথগামী করেছে। অতএব যে আমার অনুসরণ করে, সে আমার এবং কেউ আমার অবাধ্যতা করলে নিশ্চয় আপনি ক্ষমাশীল, পরম দয়ালু।', 'Rabbi innahunna adlalna katheeran mina alnnasi faman tabiAAanee fainnahu minnee waman AAasanee fainnaka ghafoorun raheemun', 1, NOW(), NOW()),
(19, 37, 'رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ', 'হে আমাদের পালনকর্তা, আমি নিজের এক সন্তানকে তোমার পবিত্র গৃহের সন্নিকটে চাষাবাদহীন উপত্যকায় আবাদ করেছি; হে আমাদের পালনকর্তা, যাতে তারা নামায কায়েম রাখে। অতঃপর আপনি কিছু লোকের অন্তরকে তাদের প্রতি আকৃষ্ট করুন এবং তাদেরকে ফলাদি দ্বারা রুযী দান করুন, সম্ভবতঃ তারা কৃতজ্ঞতা প্রকাশ করবে', 'Rabbana innee askantu min thurriyyatee biwadin ghayri thee zarAAin AAinda baytika almuharrami rabbana liyuqeemoo alssalata faijAAal afidatan mina alnnasi tahwee ilayhim waorzuqhum mina alththamarati laAAallahum yashkuroona', 1, NOW(), NOW()),
(19, 38, 'رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَيۡءٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ', 'হে আমাদের পালনকর্তা, আপনি তো জানেন আমরা যা কিছু গোপনে করি এবং যা কিছু প্রকাশ্য করি। আল্লাহর কাছে পৃথিবীতে ও আকাশে কোন কিছুই গোপন নয়।', 'Rabbana innaka taAAlamu ma nukhfee wama nuAAlinu wama yakhfa AAala Allahi min shayin fee alardi wala fee alssamai', 1, NOW(), NOW()),
(19, 39, 'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ', 'সমস্ত প্রশংসা আল্লাহরই, যিনি আমাকে এই বার্ধক্যে ইসমাঈল ও ইসহাক দান করেছেন নিশ্চয় আমার পালনকর্তা দোয়া শ্রবণ করেন।', 'Alhamdu lillahi allathee wahaba lee AAala alkibari ismaAAeela waishaqa inna rabbee lasameeAAu aldduAAai', 1, NOW(), NOW()),
(19, 40, 'رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ', 'হে আমার পালনকর্তা, আমাকে নামায কায়েমকারী করুন এবং আমার সন্তানদের মধ্যে থেকেও। হে আমাদের পালনকর্তা, এবং কবুল করুন আমাদের দোয়া।', 'Rabbi ijAAalnee muqeema alssalati wamin thurriyyatee rabbana wtaqabbal duAAai', 1, NOW(), NOW()),
(19, 41, 'رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ', 'হে আমাদের পালনকর্তা, আমাকে, আমার পিতা-মাতাকে এবং সব মুমিনকে ক্ষমা করুন, যেদিন হিসাব কায়েম হবে।', 'Rabbana ighfir lee waliwalidayya walilmumineena yawma yaqoomu alhisabu', 1, NOW(), NOW()),
(19, 42, 'وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّـٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ', 'জালেমরা যা করে, সে সম্পর্কে আল্লাহকে কখনও বেখবর মনে করো না তাদেরকে তো ঐ দিন পর্যন্ত অবকাশ দিয়ে রেখেছেন, যেদিন চক্ষুসমূহ বিস্ফোরিত হবে।', 'Wala tahsabanna Allaha ghafilan AAamma yaAAmalu alththalimoona innama yuakhkhiruhum liyawmin tashkhasu feehi alabsaru', 1, NOW(), NOW()),
(19, 43, 'مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ', 'তারা মস্তক উপরে তুলে ভীত-বিহবল চিত্তে দৌড়াতে থাকবে। তাদের দিকে তাদের দৃষ্টি ফিরে আসবে না এবং তাদের অন্তর উড়ে যাবে।', 'MuhtiAAeena muqniAAee ruoosihim la yartaddu ilayhim tarfuhum waafidatuhum hawaon', 1, NOW(), NOW()),
(19, 44, 'وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالٖ', 'মানুষকে ঐ দিনের ভয় প্রদর্শন করুন, যেদিন তাদের কাছে আযাব আসবে। তখন জালেমরা বলবেঃ হে আমাদের পালনকর্তা, আমাদেরকে সামান্য মেয়াদ পর্যন্ত সময় দিন, যাতে আমরা আপনার আহবানে সাড়া দিতে এবং পয়গম্বরগণের অনুসরণ করতে পারি। তোমরা কি ইতোপূর্বে কসম খেতে না যে, তোমাদেরকে দুনিয়া থেকে যেতে হবে না', 'Waanthiri alnnasa yawma yateehimu alAAathabu fayaqoolu allatheena thalamoo rabbana akhkhirna ila ajalin qareebin nujib daAAwataka wanattabiAAi alrrusula awalam takoonoo aqsamtum min qablu ma lakum min zawalin', 1, NOW(), NOW()),
(19, 45, 'وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ أَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ', 'তোমরা তাদের বাসভূমিতেই বসবাস করতে, যারা নিজেদের উপর জুলুম করেছে এবং তোমাদের জানা হয়ে গিয়েছিল যে, আমি তাদের সাথে কিরূপ ব্যবহার করেছি এবং আমি তোমাদেরকে ওদের সব কাহিনীই বর্ণনা করেছি।', 'Wasakantum fee masakini allatheena thalamoo anfusahum watabayyana lakum kayfa faAAalna bihim wadarabna lakumu alamthala', 1, NOW(), NOW()),
(19, 46, 'وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ', 'তারা নিজেদের মধ্যে ভীষণ চক্রান্ত করে নিয়েছে এবং আল্লাহর সামনে রক্ষিত আছে তাদের কু-চক্রান্ত। তাদের কুটকৌশল পাহাড় টলিয়ে দেয়ার মত হবে না।', 'Waqad makaroo makrahum waAAinda Allahi makruhum wain kana makruhum litazoola minhu aljibalu', 1, NOW(), NOW()),
(19, 47, 'فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ ذُو ٱنتِقَامٖ', 'অতএব আল্লাহর প্রতি ধারণা করো না যে, তিনি রসূলগণের সাথে কৃত ওয়াদা ভঙ্গ করবেন নিশ্চয় আল্লাহ পরাক্রমশালী, প্রতিশোধ গ্রহণকারী।', 'Fala tahsabanna Allaha mukhlifa waAAdihi rusulahu inna Allaha AAazeezun thoo intiqamin', 1, NOW(), NOW()),
(19, 48, 'يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ', 'যেদিন পরিবর্তিত করা হবে এ পৃথিবীকে অন্য পৃথিবীতে এবং পরিবর্তিত করা হবে আকাশ সমূহকে এবং লোকেরা পরাক্রমশালী এবং আল্লাহর সামনে পেশ হবে।', 'Yawma tubaddalu alardu ghayra alardi waalssamawatu wabarazoo lillahi alwahidi alqahhari', 1, NOW(), NOW()),
(19, 49, 'وَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ', 'তুমি ঐদিন পাপীদেরকে পরস্পরে শৃংখলা বদ্ধ দেখবে।', 'Watara almujrimeena yawmaithin muqarraneena fee alasfadi', 1, NOW(), NOW()),
(19, 50, 'سَرَابِيلُهُم مِّن قَطِرَانٖ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ', 'তাদের জামা হবে দাহ্য আলকাতরার এবং তাদের মুখমন্ডলকে আগুন আচ্ছন্ন করে ফেলবে।', 'Sarabeeluhum min qatranin wataghsha wujoohahumu alnnaru', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(19, 51, 'لِيَجۡزِيَ ٱللَّهُ كُلَّ نَفۡسٖ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ', 'যাতে আল্লাহ প্রত্যেককে তার কৃতকর্মের প্রতিদান দেন। নিশ্চয় আল্লাহ দ্রুত হিসাব গ্রহণকারী।', 'Liyajziya Allahu kulla nafsin ma kasabat inna Allaha sareeAAu alhisabi', 1, NOW(), NOW()),
(19, 52, 'هَٰذَا بَلَٰغٞ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ', 'এটা মানুষের একটি সংবাদনামা এবং যাতে এতদ্বারা ভীত হয় এবং যাতে জেনে নেয় যে, উপাস্য তিনিই-একক; এবং যাতে বুদ্ধিমানরা চিন্তা-ভাবনা করে।', 'Hatha balaghun lilnnasi waliyuntharoo bihi waliyaAAlamoo annama huwa ilahun wahidun waliyaththakkara oloo alalbabi', 1, NOW(), NOW()),
(20, 1, 'الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانٖ مُّبِينٖ', 'আলিফ-লা-ম-রা; এগুলো পরিপূর্ণ গ্রন্থ ও সুস্পষ্ট কোরআনের আয়াত।', 'Aliflamra tilka ayatu alkitabi waquranin mubeenin', 1, NOW(), NOW()),
(20, 2, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ', 'কোন সময় কাফেররা আকাঙ্ক্ষা করবে যে, কি চমৎকার হত, যদি তারা মুসলমান হত।', 'Rubama yawaddu allatheena kafaroo law kanoo muslimeena', 1, NOW(), NOW()),
(20, 3, 'ذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ', 'আপনি ছেড়ে দিন তাদেরকে, খেয়ে নিক এবং ভোগ করে নিক এবং আশায় ব্যাপৃত থাকুক। অতি সত্বর তারা জেনে নেবে।', 'Tharhum yakuloo wayatamattaAAoo wayulhihimu alamalu fasawfa yaAAlamoona', 1, NOW(), NOW()),
(20, 4, 'وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ', 'আমি কোন জনপদ ধবংস করিনি; কিন্ত তার নির্দিষ্ট সময় লিখিত ছিল।', 'Wama ahlakna min qaryatin illa walaha kitabun maAAloomun', 1, NOW(), NOW()),
(20, 5, 'مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ', 'কোন সম্প্রদায় তার নির্দিষ্ট সময়ের অগ্রে যায় না এবং পশ্চাতে থাকে না।', 'Ma tasbiqu min ommatin ajalaha wama yastakhiroona', 1, NOW(), NOW()),
(20, 6, 'وَقَالُواْ يَـٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونٞ', 'তারা বললঃ হে ঐ ব্যক্তি, যার প্রতি কোরআন নাযিল হয়েছে, আপনি তো একজন উম্মাদ।', 'Waqaloo ya ayyuha allathee nuzzila AAalayhi alththikru innaka lamajnoonun', 1, NOW(), NOW()),
(20, 7, 'لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'যদি আপনি সত্যবাদী হন, তবে আমাদের কাছে ফেরেশতাদেরকে আনেন না কেন', 'Law ma tateena bialmalaikati in kunta mina alssadiqeena', 1, NOW(), NOW()),
(20, 8, 'مَا نُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ', 'আমি ফেরেশতাদেরকে একমাত্র ফায়সালার জন্যেই নাযিল করি। তখন তাদেরকে অবকাশ দেয়া হবে না।', 'Ma nunazzilu almalaikata illa bialhaqqi wama kanoo ithan munthareena', 1, NOW(), NOW()),
(20, 9, 'إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'আমি স্বয়ং এ উপদেশ গ্রন্থ অবতারণ করেছি এবং আমি নিজেই এর সংরক্ষক।', 'Inna nahnu nazzalna alththikra wainna lahu lahafithoona', 1, NOW(), NOW()),
(20, 10, 'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ', 'আমি আপনার পূর্বে পূর্ববর্তী সম্প্রদায়ের মধ্যে রসূল প্রেরণ করেছি।', 'Walaqad arsalna min qablika fee shiyaAAi alawwaleena', 1, NOW(), NOW()),
(20, 11, 'وَمَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'ওদের কাছে এমন কোন রসূল আসেননি, যাদের সাথে ওরা ঠাট্টাবিদ্রূপ করতে থাকেনি।', 'Wama yateehim min rasoolin illa kanoo bihi yastahzioona', 1, NOW(), NOW()),
(20, 12, 'كَذَٰلِكَ نَسۡلُكُهُۥ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ', 'এমনিভাবে আমি এ ধরনের আচরণ পাপীদের অন্তরে বদ্ধমূল করে দেই।', 'Kathalika naslukuhu fee quloobi almujrimeena', 1, NOW(), NOW()),
(20, 13, 'لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ', 'ওরা এর প্রতি বিশ্বাস করবে না। পূর্ববর্তীদের এমন রীতি চলে আসছে।', 'La yuminoona bihi waqad khalat sunnatu alawwaleena', 1, NOW(), NOW()),
(20, 14, 'وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابٗا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ', 'যদি আমি ওদের সামনে আকাশের কোন দরজাও খুলে দেই আর তাতে ওরা দিনভর আরোহণ ও করতে থাকে।', 'Walaw fatahna AAalayhim baban mina alssamai fathalloo feehi yaAArujoona', 1, NOW(), NOW()),
(20, 15, 'لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمٞ مَّسۡحُورُونَ', 'তবুও ওরা একথাই বলবে যে, আমাদের দৃষ্টির বিভ্রাট ঘটানো হয়েছে না বরং আমরা যাদুগ্রস্ত হয়ে পড়েছি।', 'Laqaloo innama sukkirat absaruna bal nahnu qawmun mashooroona', 1, NOW(), NOW()),
(20, 16, 'وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ', 'নিশ্চয় আমি আকাশে রাশিচক্র সৃষ্টি করেছি এবং তাকে দর্শকদের জন্যে সুশোভিত করে দিয়েছি।', 'Walaqad jaAAalna fee alssamai buroojan wazayyannaha lilnnathireena', 1, NOW(), NOW()),
(20, 17, 'وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنٖ رَّجِيمٍ', 'আমি আকাশকে প্রত্যেক বিতাড়িত শয়তান থেকে নিরাপদ করে দিয়েছি।', 'Wahafithnaha min kulli shaytanin rajeemin', 1, NOW(), NOW()),
(20, 18, 'إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابٞ مُّبِينٞ', 'কিন্তু যে চুরি করে শুনে পালায়, তার পশ্চাদ্ধাবন করে উজ্জ্বল উল্কাপিন্ড।', 'Illa mani istaraqa alssamAAa faatbaAAahu shihabun mubeenun', 1, NOW(), NOW()),
(20, 19, 'وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ', 'আমি ভু-পৃষ্ঠকে বিস্তৃত করেছি এবং তার উপর পর্বতমালা স্থাপন করেছি এবং তাতে প্রত্যেক বস্তু সুপরিমিতভাবে উৎপন্ন করেছি।', 'Waalarda madadnaha waalqayna feeha rawasiya waanbatna feeha min kulli shayin mawzoonin', 1, NOW(), NOW()),
(20, 20, 'وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ', 'আমি তোমাদের জন্যে তাতে জীবিকার উপকরন সৃষ্টি করছি এবং তাদের জন্যেও যাদের অন্নদাতা তোমরা নও।', 'WajaAAalna lakum feeha maAAayisha waman lastum lahu biraziqeena', 1, NOW(), NOW()),
(20, 21, 'وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ', 'আমার কাছে প্রত্যেক বস্তুর ভান্ডার রয়েছে। আমি নির্দিষ্ট পরিমানেই তা অবতরণ করি।', 'Wain min shayin illa AAindana khazainuhu wama nunazziluhu illa biqadarin maAAloomin', 1, NOW(), NOW()),
(20, 22, 'وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ', 'আমি বৃষ্টিগর্ভ বায়ু পরিচালনা করি অতঃপর আকাশ থেকে পানি বর্ষণ করি, এরপর তোমাদেরকে তা পান করাই। বস্তুতঃ তোমাদের কাছে এর ভান্ডার নেই।', 'Waarsalna alrriyaha lawaqiha faanzalna mina alssamai maan faasqaynakumoohu wama antum lahu bikhazineena', 1, NOW(), NOW()),
(20, 23, 'وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ', 'আমিই জীবনদান করি, মৃত্যুদান করি এবং আমিই চুড়ান্ত মালিকানার অধিকারী।', 'Wainna lanahnu nuhyee wanumeetu wanahnu alwarithoona', 1, NOW(), NOW()),
(20, 24, 'وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ', 'আমি জেনে রেখেছি তোমাদের অগ্রগামীদেরকে এবং আমি জেনে রেখেছি পশ্চাদগামীদেরকে।', 'Walaqad AAalimna almustaqdimeena minkum walaqad AAalimna almustakhireena', 1, NOW(), NOW()),
(20, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ', 'আপনার পালনকর্তাই তাদেরকে একত্রিত করে আনবেন। নিশ্চয় তিনি প্রজ্ঞাবান, জ্ঞানময়।', 'Wainna rabbaka huwa yahshuruhum innahu hakeemun AAaleemun', 1, NOW(), NOW()),
(20, 26, 'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', 'আমি মানবকে পচা কর্দম থেকে তৈরী বিশুস্ক ঠনঠনে মাটি দ্বারা সৃষ্টি করেছি।', 'Walaqad khalaqna alinsana min salsalin min hamain masnoonin', 1, NOW(), NOW()),
(20, 27, 'وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ', 'এবং জিনকে এর আগে লু এর আগুনের দ্বারা সৃজিত করেছি।', 'Waaljanna khalaqnahu min qablu min nari alssamoomi', 1, NOW(), NOW()),
(20, 28, 'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', 'আর আপনার পালনকর্তা যখন ফেরেশতাদেরকে বললেনঃ আমি পচা কর্দম থেকে তৈরী বিশুষ্ক ঠনঠনে মাটি দ্বারা সৃষ্ট একটি মানব জাতির পত্তন করব।', 'Waith qala rabbuka lilmalaikati innee khaliqun basharan min salsalin min hamain masnoonin', 1, NOW(), NOW()),
(20, 29, 'فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ', 'অতঃপর যখন তাকে ঠিকঠাক করে নেব এবং তাতে আমার রূহ থেকে ফঁুক দেব, তখন তোমরা তার সামনে সেজদায় পড়ে যেয়ো।', 'Faitha sawwaytuhu wanafakhtu feehi min roohee faqaAAoo lahu sajideena', 1, NOW(), NOW()),
(20, 30, 'فَسَجَدَ ٱلۡمَلَـٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ', 'তখন ফেরেশতারা সবাই মিলে সেজদা করল।', 'Fasajada almalaikatu kulluhum ajmaAAoona', 1, NOW(), NOW()),
(20, 31, 'إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّـٰجِدِينَ', 'কিন্তু ইবলীস-সে সেজদাকারীদের অন্তর্ভূক্ত হতে স্বীকৃত হল না।', 'Illa ibleesa aba an yakoona maAAa alssajideena', 1, NOW(), NOW()),
(20, 32, 'قَالَ يَـٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِينَ', 'আল্লাহ বললেনঃ হে ইবলিস, তোমার কি হলো যে তুমি সেজদাকারীদের অন্তর্ভূক্ত হতে স্বীকৃত হলে না', 'Qala ya ibleesu ma laka alla takoona maAAa alssajideena', 1, NOW(), NOW()),
(20, 33, 'قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ', 'বললঃ আমি এমন নই যে, একজন মানবকে সেজদা করব, যাকে আপনি পচা কর্দম থেকে তৈরী ঠনঠনে বিশুষ্ক মাটি দ্বারা সৃষ্টি করেছেন।', 'Qala lam akun liasjuda libasharin khalaqtahu min salsalin min hamain masnoonin', 1, NOW(), NOW()),
(20, 34, 'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ', 'আল্লাহ বললেনঃ তবে তুমি এখান থেকে বের হয়ে যাও। তুমি বিতাড়িত।', 'Qala faokhruj minha fainnaka rajeemun', 1, NOW(), NOW()),
(20, 35, 'وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ', 'এবং তোমার প্রতি ন্যায় বিচারের দিন পর্যন্ত অভিসম্পাত।', 'Wainna AAalayka allaAAnata ila yawmi alddeeni', 1, NOW(), NOW()),
(20, 36, 'قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ', 'সে বললঃ হে আমার পালনকর্তা, আপনি আমাকে পুনরুত্থান দিবস পর্যন্ত অবকাশ দিন।', 'Qala rabbi faanthirnee ila yawmi yubAAathoona', 1, NOW(), NOW()),
(20, 37, 'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ', 'আল্লাহ বললেনঃ তোমাকে অবকাশ দেয়া হল।', 'Qala fainnaka mina almunthareena', 1, NOW(), NOW()),
(20, 38, 'إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ', 'সেই অবধারিত সময় উপস্থিত হওয়ার দিন পর্যন্ত।', 'Ila yawmi alwaqti almaAAloomi', 1, NOW(), NOW()),
(20, 39, 'قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ', 'সে বললঃ হে আমার পলনকর্তা, আপনি যেমন আমাকে পথ ভ্রষ্ট করেছেন, আমিও তাদের সবাইকে পৃথিবীতে নানা সৌন্দর্যে আকৃষ্ট করব এবং তাদের সবাইকে পথ ভ্রষ্ঠ করে দেব।', 'Qala rabbi bima aghwaytanee laozayyinanna lahum fee alardi walaoghwiyannahum ajmaAAeena', 1, NOW(), NOW()),
(20, 40, 'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ', 'আপনার মনোনীত বান্দাদের ব্যতীত।', 'Illa AAibadaka minhumu almukhlaseena', 1, NOW(), NOW()),
(20, 41, 'قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ', 'আল্লাহ বললেনঃ এটা আমা পর্যন্ত সোজা পথ।', 'Qala hatha siratun AAalayya mustaqeemun', 1, NOW(), NOW()),
(20, 42, 'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ', 'যারা আমার বান্দা, তাদের উপর তোমার কোন ক্ষমতা নেই; কিন্তু পথভ্রান্তদের মধ্য থেকে যারা তোমার পথে চলে।', 'Inna AAibadee laysa laka AAalayhim sultanun illa mani ittabaAAaka mina alghaweena', 1, NOW(), NOW()),
(20, 43, 'وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ', 'তাদের সবার নির্ধারিত স্থান হচ্ছে জাহান্নাম।', 'Wainna jahannama lamawAAiduhum ajmaAAeena', 1, NOW(), NOW()),
(20, 44, 'لَهَا سَبۡعَةُ أَبۡوَٰبٖ لِّكُلِّ بَابٖ مِّنۡهُمۡ جُزۡءٞ مَّقۡسُومٌ', 'এর সাতটি দরজা আছে। প্রত্যেক দরজার জন্যে এক একটি পৃথক দল আছে।', 'Laha sabAAatu abwabin likulli babin minhum juzon maqsoomun', 1, NOW(), NOW()),
(20, 45, 'إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ', 'নিশ্চয় খোদাভীরুরা বাগান ও নির্ঝরিনীসহূহে থাকবে।', 'Inna almuttaqeena fee jannatin waAAuyoonin', 1, NOW(), NOW()),
(20, 46, 'ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'বলা হবেঃ এগুলোতে নিরাপত্তা ও শান্তি সহকরে প্রবেশ কর।', 'Odkhulooha bisalamin amineena', 1, NOW(), NOW()),
(20, 47, 'وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ', 'তাদের অন্তরে যে ক্রোধ ছিল, আমি তা দূর করে দেব। তারা ভাই ভাইয়ের মত সামনা-সামনি আসনে বসবে।', 'WanazaAAna ma fee sudoorihim min ghillin ikhwanan AAala sururin mutaqabileena', 1, NOW(), NOW()),
(20, 48, 'لَا يَمَسُّهُمۡ فِيهَا نَصَبٞ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ', 'সেখানে তাদের মোটেই কষ্ট হবে না এবং তারা সেখান থেকে বহিস্কৃত হবে না।', 'La yamassuhum feeha nasabun wama hum minha bimukhrajeena', 1, NOW(), NOW()),
(20, 49, '۞نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ', 'আপনি আমার বান্দাদেরকে জানিয়ে দিন যে, আমি অত্যন্ত ক্ষমাশীল দয়ালু।', 'Nabbi AAibadee annee ana alghafooru alrraheemu', 1, NOW(), NOW()),
(20, 50, 'وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ', 'এবং ইহাও যে, আমার শাস্তিই যন্ত্রনাদায়ক শাস্তি।', 'Wa anna AAathabee huwa alAAathabu alaleemu', 1, NOW(), NOW()),
(20, 51, 'وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ', 'আপনি তাদেরকে ইব্রাহীমের মেহমানদের অবস্থা শুনিয়ে দিন।', 'Wanabbihum AAan dayfi ibraheema', 1, NOW(), NOW()),
(20, 52, 'إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ', 'যখন তারা তাঁর গৃহে আগমন করল এবং বললঃ সালাম। তিনি বললেনঃ আমরা তোমাদের ব্যাপারে ভীত।', 'Ith dakhaloo AAalayhi faqaloo salaman qala inna minkum wajiloona', 1, NOW(), NOW()),
(20, 53, 'قَالُواْ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٖ', 'তারা বললঃ ভয় করবেন না। আমরা আপনাকে একজন জ্ঞানবান ছেলে-সন্তানের সুসংবাদ দিচ্ছি।', 'Qaloo la tawjal inna nubashshiruka bighulamin AAaleemin', 1, NOW(), NOW()),
(20, 54, 'قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ', 'তিনি বললেনঃ তোমরা কি আমাকে এমতাবস্থায় সুসংবাদ দিচ্ছ, যখন আমি বার্ধক্যে পৌছে গেছি', 'Qala abashshartumoonee AAala an massaniya alkibaru fabima tubashshirooni', 1, NOW(), NOW()),
(20, 55, 'قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ', 'তারা বললঃ আমরা আপনাকে সত্য সু-সংবাদ দিচ্ছি! অতএব আপনি নিরাশ হবেন না।', 'Qaloo bashsharnaka bialhaqqi fala takun mina alqaniteena', 1, NOW(), NOW()),
(20, 56, 'قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', 'তিনি বললেনঃ পালনকর্তার রহমত থেকে পথভ্রষ্টরা ছাড়া কে নিরাশ হয়', 'Qala waman yaqnatu min rahmati rabbihi illa alddalloona', 1, NOW(), NOW()),
(20, 57, 'قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ', 'তিনি বললেনঃ অতঃপর তোমাদের প্রধান উদ্দেশ্য কি হে আল্লাহর প্রেরিতগণ', 'Qala fama khatbukum ayyuha almursaloona', 1, NOW(), NOW()),
(20, 58, 'قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ', 'তারা বললঃ আমরা একটি অপরাধী সম্প্রদায়ের প্রতি প্রেরিত হয়েছি।', 'Qaloo inna orsilna ila qawmin mujrimeena', 1, NOW(), NOW()),
(20, 59, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ', 'কিন্তু লূতের পরিবার-পরিজন। আমরা অবশ্যই তাদের সবাইকে বাঁচিয়ে নেব।', 'Illa ala lootin inna lamunajjoohum ajmaAAeena', 1, NOW(), NOW()),
(20, 60, 'إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ', 'তবে তার স্ত্রী। আমরা স্থির করেছি যে, সে থেকে যাওয়াদের দলভূক্ত হবে।', 'Illa imraatahu qaddarna innaha lamina alghabireena', 1, NOW(), NOW()),
(20, 61, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ', 'অতঃপর যখন প্রেরিতরা লূতের গৃহে পৌছল।', 'Falamma jaa ala lootin almursaloona', 1, NOW(), NOW()),
(20, 62, 'قَالَ إِنَّكُمۡ قَوۡمٞ مُّنكَرُونَ', 'তিনি বললেনঃ তোমরা তো অপরিচিত লোক।', 'Qala innakum qawmun munkaroona', 1, NOW(), NOW()),
(20, 63, 'قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ يَمۡتَرُونَ', 'তারা বললঃ না বরং আমরা আপনার কাছে ঐ বস্তু নিয়ে এসেছি, যে সম্পর্কে তারা বিবাদ করত।', 'Qaloo bal jinaka bima kanoo feehi yamtaroona', 1, NOW(), NOW()),
(20, 64, 'وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ', 'এবং আমরা আপনার কাছে সত্য বিষয় নিয়ে এসেছি এবং আমরা সত্যবাদী।', 'Waataynaka bialhaqqi wainna lasadiqoona', 1, NOW(), NOW()),
(20, 65, 'فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ', 'অতএব আপনি শেষরাত্রে পরিবারের সকলকে নিয়ে চলে যান এবং আপনি তাদের পশ্চাদনুসরণ করবেন না এবং আপনাদের মধ্যে কেউ যেন পিছন ফিরে না দেখে। আপনারা যেখানে আদেশ প্রাপ্ত হচ্ছেন সেখানে যান।', 'Faasri biahlika biqitAAin mina allayli waittabiAA adbarahum wala yaltafit minkum ahadun waimdoo haythu tumaroona', 1, NOW(), NOW()),
(20, 66, 'وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَـٰٓؤُلَآءِ مَقۡطُوعٞ مُّصۡبِحِينَ', 'আমি লূতকে এ বিষয় পরিজ্ঞাত করে দেই যে, সকাল হলেই তাদেরকে সমুলে বিনাশ করে দেয়া হবে।', 'Waqadayna ilayhi thalika alamra anna dabira haolai maqtooAAun musbiheena', 1, NOW(), NOW()),
(20, 67, 'وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ', 'শহরবাসীরা আনন্দ-উল্লাস করতে করতে পৌছল।', 'Wajaa ahlu almadeenati yastabshiroona', 1, NOW(), NOW()),
(20, 68, 'قَالَ إِنَّ هَـٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ', 'লূত বললেনঃ তারা আমার মেহমান। অতএব আমাকে লাঞ্ছিত করো না।', 'Qala inna haolai dayfee fala tafdahooni', 1, NOW(), NOW()),
(20, 69, 'وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ', 'তোমরা আল্লাহকে ভয় কর এবং আমার ইযযত নষ্ট করো না।', 'Waittaqoo Allaha wala tukhzooni', 1, NOW(), NOW()),
(20, 70, 'قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ', 'তার বললঃ আমরা কি আপনাকে জগৎদ্বাসীর সমর্থন করতে নিষেধ করিনি।', 'Qaloo awalam nanhaka AAani alAAalameena', 1, NOW(), NOW()),
(20, 71, 'قَالَ هَـٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ', 'তিনি বললেনঃ যদি তোমরা একান্ত কিছু করতেই চাও, তবে আমার কন্যারা উপস্থিত আছে।', 'Qala haolai banatee in kuntum faAAileena', 1, NOW(), NOW()),
(20, 72, 'لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ يَعۡمَهُونَ', 'আপনার প্রাণের কসম, তারা আপন নেশায় প্রমত্ত ছিল।', 'LaAAamruka innahum lafee sakratihim yaAAmahoona', 1, NOW(), NOW()),
(20, 73, 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ', 'অতঃপর সুর্যোদয়ের সময় তাদেরকে প্রচন্ড একটি শব্দ এসে পাকড়াও করল।', 'Faakhathathumu alssayhatu mushriqeena', 1, NOW(), NOW()),
(20, 74, 'فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ', 'অতঃপর আমি জনপদটিকে উল্টে দিলাম এবং তাদের উপর কঙ্করের প্রস্থর বর্ষণ করলাম।', 'FajaAAalna AAaliyaha safilaha waamtarna AAalayhim hijaratan min sijjeelin', 1, NOW(), NOW()),
(20, 75, 'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ', 'নিশ্চয় এতে চিন্তাশীলদের জন্যে নিদর্শনাবলী রয়েছে।', 'Inna fee thalika laayatin lilmutawassimeena', 1, NOW(), NOW()),
(20, 76, 'وَإِنَّهَا لَبِسَبِيلٖ مُّقِيمٍ', 'জনপদটি সোজা পথে অবস্থিত রয়েছে।', 'Wainnaha labisabeelin muqeemin', 1, NOW(), NOW()),
(20, 77, 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ', 'নিশ্চয় এতে ঈমানদারদের জন্যে নিদর্শণ আছে।', 'Inna fee thalika laayatan lilmumineena', 1, NOW(), NOW()),
(20, 78, 'وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ', 'নিশ্চয় গহীন বনের অধিবাসীরা পাপী ছিল।', 'Wain kana ashabu alaykati lathalimeena', 1, NOW(), NOW()),
(20, 79, 'فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ', 'অতঃপর আমি তাদের কাছ থেকে প্রতিশোধ নিয়েছি। উভয় বস্তি প্রকাশ্য রাস্তার উপর অবস্থিত।', 'Faintaqamna minhum wainnahuma labiimamin mubeenin', 1, NOW(), NOW()),
(20, 80, 'وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ', 'নিশ্চয় হিজরের বাসিন্দারা পয়গম্বরগণের প্রতি মিথ্যারোপ করেছে।', 'Walaqad kaththaba ashabu alhijri almursaleena', 1, NOW(), NOW()),
(20, 81, 'وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ', 'আমি তাদেরকে নিজের নিদর্শনাবলী দিয়েছি। অতঃপর তারা এগুলো থেকে মুখ ফিরিয়ে নেয়।', 'Waataynahum ayatina fakanoo AAanha muAArideena', 1, NOW(), NOW()),
(20, 82, 'وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ', 'তারা পাহাড়ে নিশ্চিন্তে ঘর খোদাই করত।', 'Wakanoo yanhitoona mina aljibali buyootan amineena', 1, NOW(), NOW()),
(20, 83, 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ', 'অতঃপর এক প্রত্যুষে তাদের উপর একটা শব্দ এসে আঘাত করল।', 'Faakhathathumu alssayhatu musbiheena', 1, NOW(), NOW()),
(20, 84, 'فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ', 'তখন কোন উপকারে আসল না যা তারা উপার্জন করেছিল।', 'Fama aghna AAanhum ma kanoo yaksiboona', 1, NOW(), NOW()),
(20, 85, 'وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ', 'আমি নভোমন্ডল, ভুমন্ডল এবং এতদুভয়ের মধ্যবর্তী যা আছে তা তাৎপর্যহীন সৃষ্টি করিনি। কেয়ামত অবশ্যই আসবে। অতএব পরম ঔদাসীন্যের সাথে ওদের ক্রিয়াকর্ম উপক্ষো করুন।', 'Wama khalaqna alssamawati waalarda wama baynahuma illa bialhaqqi wainna alssaAAata laatiyatun faisfahi alssafha aljameela', 1, NOW(), NOW()),
(20, 86, 'إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِيمُ', 'নিশ্চয় আপনার পালনকর্তাই স্রষ্টা, সর্বজ্ঞ।', 'Inna rabbaka huwa alkhallaqu alAAaleemu', 1, NOW(), NOW()),
(20, 87, 'وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ', 'আমি আপনাকে সাতটি বার বার পঠিতব্য আয়াত এবং মহান কোরআন দিয়েছি।', 'Walaqad ataynaka sabAAan mina almathanee waalqurana alAAatheema', 1, NOW(), NOW()),
(20, 88, 'لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ', 'আপনি চক্ষু তুলে ঐ বস্তুর প্রতি দেখবেন না, যা আমি তাদের মধ্যে কয়েক প্রকার লোককে ভোগ করার জন্যে দিয়েছি, তাদের জন্যে চিন্তিত হবেন না আর ঈমানদারদের জন্যে স্বীয় বাহু নত করুন।', 'La tamuddanna AAaynayka ila ma mattaAAna bihi azwajan minhum wala tahzan AAalayhim waikhfid janahaka lilmumineena', 1, NOW(), NOW()),
(20, 89, 'وَقُلۡ إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ', 'আর বলুনঃ আমি প্রকাশ্য ভয় প্রদর্শক।', 'Waqul innee ana alnnatheeru almubeenu', 1, NOW(), NOW()),
(20, 90, 'كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ', 'যেমন আমি নাযিল করেছি যারা বিভিন্ন মতে বিভক্ত তাদের উপর।', 'Kama anzalna AAala almuqtasimeena', 1, NOW(), NOW()),
(20, 91, 'ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ', 'যারা কোরআনকে খন্ড খন্ড করেছে।', 'Allatheena jaAAaloo alqurana AAideena', 1, NOW(), NOW()),
(20, 92, 'فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ', 'অতএব আপনার পালনকর্তার কসম, আমি অবশ্যই ওদের সবাইকে জিজ্ঞাসাবাদ করব।', 'Fawarabbika lanasalannahum ajmaAAeena', 1, NOW(), NOW()),
(20, 93, 'عَمَّا كَانُواْ يَعۡمَلُونَ', 'ওদের কাজকর্ম সম্পর্কে।', 'AAamma kanoo yaAAmaloona', 1, NOW(), NOW()),
(20, 94, 'فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ', 'অতএব আপনি প্রকাশ্যে শুনিয়ে দিন যা আপনাকে আদেশ করা হয় এবং মুশরিকদের পরওয়া করবেন না।', 'FaisdaAA bima tumaru waaAArid AAani almushrikeena', 1, NOW(), NOW()),
(20, 95, 'إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ', 'বিদ্রুপকারীদের জন্যে আমি আপনার পক্ষ থেকে যথেষ্ট।', 'Inna kafaynaka almustahzieena', 1, NOW(), NOW()),
(20, 96, 'ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ', 'যারা আল্লাহর সাথে অন্য উপাস্য সাব্যস্ত করে। অতএব অতিসত্তর তারা জেনে নেবে।', 'Allatheena yajAAaloona maAAa Allahi ilahan akhara fasawfa yaAAlamoona', 1, NOW(), NOW()),
(20, 97, 'وَلَقَدۡ نَعۡلَمُ أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ', 'আমি জানি যে আপনি তাদের কথাবর্তায় হতোদ্যম হয়ে পড়েন।', 'Walaqad naAAlamu annaka yadeequ sadruka bima yaqooloona', 1, NOW(), NOW()),
(20, 98, 'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِينَ', 'অতএব আপনি পালনকর্তার সৌন্দর্য স্মরণ করুন এবং সেজদাকারীদের অন্তর্ভূক্ত হয়ে যান।', 'Fasabbih bihamdi rabbika wakun mina alssajideena', 1, NOW(), NOW()),
(20, 99, 'وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ', 'এবং পালনকর্তার এবাদত করুন, যে পর্যন্ত আপনার কাছে নিশ্চিত কথা না আসে।', 'WaoAAbud rabbaka hatta yatiyaka alyaqeenu', 1, NOW(), NOW()),
(21, 1, 'أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', 'আল্লাহর নির্দেশ এসে গেছে। অতএব এর জন্যে তাড়াহুড়া করো না। ওরা যেসব শরীক সাব্যস্ত করছে সেসব থেকে তিনি পবিত্র ও বহু উর্ধ্বে।', 'Ata amru Allahi fala tastaAAjiloohu subhanahu wataAAala AAamma yushrikoona', 1, NOW(), NOW()),
(21, 2, 'يُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', 'তিনি স্বীয় নির্দেশে বান্দাদের মধ্যে যার কাছে ইচ্ছা, নির্দেশসহ ফেরেশতাদেরকে এই মর্মে নাযিল করেন যে, হুশিয়ার করে দাও, আমি ছাড়া কোন উপাস্য নেই। অতএব আমাকে ভয় কর।', 'Yunazzilu almalaikata bialrroohi min amrihi AAala man yashao min AAibadihi an anthiroo annahu la ilaha illa ana faittaqooni', 1, NOW(), NOW()),
(21, 3, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', 'যিনি যথাবিধি আকাশরাজি ও ভূ-মন্ডল সৃষ্টি করেছেন। তারা যাকে শরীক করে তিনি তার বহু উর্ধ্বে।', 'Khalaqa alssamawati waalarda bialhaqqi taAAala AAamma yushrikoona', 1, NOW(), NOW()),
(21, 4, 'خَلَقَ ٱلۡإِنسَٰنَ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ', 'তিনি মানবকে এক ফোটা বীর্য থেকে সৃষ্টি করেছেন। এতদসত্বেও সে প্রকাশ্য বিতন্ডাকারী হয়ে গেছে।', 'Khalaqa alinsana min nutfatin faitha huwa khaseemun mubeenun', 1, NOW(), NOW()),
(21, 5, 'وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ', 'চতুষ্পদ জন্তুকে তিনি সৃষ্টি করেছেন। এতে তোমাদের জন্যে শীত বস্ত্রের উপকরণ আছে। আর অনেক উপকার হয়েছে এবং কিছু সংখ্যককে তোমরা আহার্যে?2474;রিণত করে থাক।', 'WaalanAAama khalaqaha lakum feeha difon wamanafiAAu waminha takuloona', 1, NOW(), NOW()),
(21, 6, 'وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ', 'এদের দ্বারা তোমাদের সম্মান হয়, যখন বিকালে চারণভূমি থেকে নিয়ে আস এবং সকালে চারণ ভূমিতে নিয়ে যাও।', 'Walakum feeha jamalun heena tureehoona waheena tasrahoona', 1, NOW(), NOW()),
(21, 7, 'وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ', 'এরা তোমাদের বোঝা এমন শহর পর্যন্ত বহন করে নিয়ে যায়, যেখানে তোমরা প্রাণান্তকর পরিশ্রۦ#2478; ব্যতীত পৌছাতে পারতে না। নিশ্চয় তোমাদের প্রভু অত্যন্ত দয়াদ্র, পরম দয়ালু।', 'Watahmilu athqalakum ila baladin lam takoonoo baligheehi illa bishiqqi alanfusi inna rabbakum laraoofun raheemun', 1, NOW(), NOW()),
(21, 8, 'وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ', 'তোমাদের আরোহণের জন্যে এবং শোভার জন্যে তিনি ঘোড়া, খচ্চর ও গাধা সৃষ্টি করেছেন। আর তিনি এমন জিনিস সৃষ্টি করেন যা তোমরা জান না।', 'Waalkhayla waalbighala waalhameera litarkabooha wazeenatan wayakhluqu ma la taAAlamoona', 1, NOW(), NOW()),
(21, 9, 'وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ', 'সরল পথ আল্লাহ পর্যন্ত পৌছে এবং পথগুলোর মধ্যে কিছু বক্র পথও রয়েছে। তিনি ইচ্ছা করলে তোমাদের সবাইকে সৎপথে পরিচালিত করতে পারতেন।', 'WaAAala Allahi qasdu alssabeeli waminha jairun walaw shaa lahadakum ajmaAAeena', 1, NOW(), NOW()),
(21, 10, 'هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ شَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ', 'তিনি তোমাদের জন্যে আকাশ থেকে পানি বর্ষণ করেছেন। এই পানি থেকে তোমরা পান কর এবং এ থেকেই উদ্ভিদ উৎপন্ন হয়, যাতে তোমরা পশুচারণ কর।', 'Huwa allathee anzala mina alssamai maan lakum minhu sharabun waminhu shajarun feehi tuseemoona', 1, NOW(), NOW()),
(21, 11, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ', 'এ পানি দ্বারা তোমাদের জন্যে উৎপাদন করেন ফসল, যয়তুন, খেজুর, আঙ্গুর ও সর্বপ্রকার ফল। নিশ্চয় এতে চিন্তাশীলদের জন্যে নিদর্শন রয়েছে।', 'Yunbitu lakum bihi alzzarAAa waalzzaytoona waalnnakheela waalaAAnaba wamin kulli alththamarati inna fee thalika laayatan liqawmin yatafakkaroona', 1, NOW(), NOW()),
(21, 12, 'وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ', 'তিনিই তোমাদের কাজে নিয়োজিত করেছেন রাত্রি, দিন, সূর্য এবং চন্দ্রকে। তারকাসমূহ তাঁরই বিধানের কর্মে নিয়োজিত রয়েছে। নিশ্চয়ই এতে বোধশক্তিসম্পন্নদের জন্যে নিদর্শনাবলী রয়েছে।', 'Wasakhkhara lakumu allayla waalnnahara waalshshamsa waalqamara waalnnujoomu musakhkharatun biamrihi inna fee thalika laayatin liqawmin yaAAqiloona', 1, NOW(), NOW()),
(21, 13, 'وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ', 'তোমাদের জন্যে পৃথিবীতে যেসব রং-বেরঙের বস্তু ছড়িয়ে দিয়েছেন, সেগুলোতে নিদর্শন রয়েছে তাদের জন্যে যারা চিন্তা-ভাবনা করে।', 'Wama tharaa lakum fee alardi mukhtalifan alwanuhu inna fee thalika laayatan liqawmin yaththakkaroona', 1, NOW(), NOW()),
(21, 14, 'وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ', 'তিনিই কাজে লাগিয়ে দিয়েছেন সমুদ্রকে, যাতে তা থেকে তোমরা তাজা মাংস খেতে পার এবং তা থেকে বের করতে পার পরিধেয় অলঙ্কার। তুমি তাতে জলযান সমূহকে পানি চিরে চলতে দেখবে এবং যাতে তোমরা আল্লাহর কৃপা অন্বেষণ কর এবং যাতে তার অনুগ্রহ স্বীকার কর।', 'Wahuwa allathee sakhkhara albahra litakuloo minhu lahman tariyyan watastakhrijoo minhu hilyatan talbasoonaha watara alfulka mawakhira feehi walitabtaghoo min fadlihi walaAAallakum tashkuroona', 1, NOW(), NOW()),
(21, 15, 'وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرٗا وَسُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ', 'এবং তিনি পৃথিবীর উপর বোঝা রেখেছেন যে, কখনো যেন তা তোমাদেরকে নিয়ে হেলে-দুলে না পড়ে এবং নদী ও পথ তৈরী করেছেন, যাতে তোমরা পথ প্রদর্শিত হও।', 'Waalqa fee alardi rawasiya an tameeda bikum waanharan wasubulan laAAallakum tahtadoona', 1, NOW(), NOW()),
(21, 16, 'وَعَلَٰمَٰتٖۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ', 'এবং তিনি পথ নির্ণয়ক বহু চিহ্ন সৃষ্টি করেছেন, এবং তারকা দ্বারা ও মানুষ পথের নির্দেশ পায়।', 'WaAAalamatin wabialnnajmi hum yahtadoona', 1, NOW(), NOW()),
(21, 17, 'أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ', 'যিনি সৃষ্টি করে, তিনি কি সে লোকের সমতুল্য যে সৃষ্টি করতে পারে না? তোমরা কি চিন্তা করবে না', 'Afaman yakhluqu kaman la yakhluqu afala tathakkaroona', 1, NOW(), NOW()),
(21, 18, 'وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ', 'যদি আল্লাহর নেয়ামত গণনা কর, শেষ করতে পারবে না। নিশ্চয় আল্লাহ ক্ষমাশীল, দয়ালু।', 'Wain taAAuddoo niAAmata Allahi la tuhsooha inna Allaha laghafoorun raheemun', 1, NOW(), NOW()),
(21, 19, 'وَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ', 'আল্লাহ জানেন যা তোমরা গোপন কর এবং যা তোমরা প্রকাশ কর।', 'WaAllahu yaAAlamu ma tusirroona wama tuAAlinoona', 1, NOW(), NOW()),
(21, 20, 'وَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ', 'এবং যারা আল্লাহকে ছেড়ে অন্যদের ডাকে, ওরা তো কোন বস্তুই সৃষ্টি করে না; বরং ওরা নিজেরাই সৃজিত।', 'Waallatheena yadAAoona min dooni Allahi la yakhluqoona shayan wahum yukhlaqoona', 1, NOW(), NOW()),
(21, 21, 'أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ', 'তারা মৃত-প্রাণহীন এবং কবে পুনরুত্থিত হবে, জানে না।', 'Amwatun ghayru ahyain wama yashAAuroona ayyana yubAAathoona', 1, NOW(), NOW()),
(21, 22, 'إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ', 'আমাদের ইলাহ একক ইলাহ। অনন্তর যারা পরজীবনে বিশ্বাস করে না, তাদের অন্তর সত্যবিমুখ এবং তারা অহংকার প্রদর্শন করেছে।', 'Ilahukum ilahun wahidun faallatheena la yuminoona bialakhirati quloobuhum munkiratun wahum mustakbiroona', 1, NOW(), NOW()),
(21, 23, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ', 'নিঃসন্দেহে আল্লাহ তাদের গোপন ও প্রকাশ্য যাবতীয় বিষয়ে অবগত। নিশ্চিতই তিনি অহংকারীদের পছন্দ করেন না।', 'La jarama anna Allaha yaAAlamu ma yusirroona wama yuAAlinoona innahu la yuhibbu almustakbireena', 1, NOW(), NOW()),
(21, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', 'যখন তাদেরকে বলা হয়ঃ তোমাদের পালনকর্তা কি নাযিল করেছেন? তারা বলেঃ পূর্ববর্তীদের কিসসা-কাহিনী।', 'Waitha qeela lahum matha anzala rabbukum qaloo asateeru alawwaleena', 1, NOW(), NOW()),
(21, 25, 'لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ', 'ফলে কেয়ামতের দিন ওরা পূর্ণমাত্রায় বহন করবে ওদের পাপভার এবং পাপভার তাদেরও যাদেরকে তারা তাদের অজ্ঞতাহেতু বিপথগামী করে শুনে নাও, খুবই নিকৃষ্ট বোঝা যা তারা বহন করে।', 'Liyahmiloo awzarahum kamilatan yawma alqiyamati wamin awzari allatheena yudilloonahum bighayri AAilmin ala saa ma yaziroona', 1, NOW(), NOW()),
(21, 26, 'قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ', 'নিশ্চয় চক্রান্ত করেছে তাদের পূর্ববর্তীরা, অতঃপর আল্লাহ তাদের চক্রান্তের ইমারতের ভিত্তিমূলে আঘাত করেছিলেন। এরপর উপর থেকে তাদের মাথায় ছাদ ধ্বসে পড়ে গেছে এবং তাদের উপর আযাব এসেছে যেখান থেকে তাদের ধারণা ছিল না।', 'Qad makara allatheena min qablihim faata Allahu bunyanahum mina alqawaAAidi fakharra AAalayhimu alssaqfu min fawqihim waatahumu alAAathabu min haythu la yashAAuroona', 1, NOW(), NOW()),
(21, 27, 'ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تُشَـٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ', 'অতঃপর কেয়ামতের দিন তিনি তাদেরকে লাঞ্ছিত করবেন এবং বলবেনঃ আমার অংশীদাররা কোথায়, যাদের ব্যাপারে তোমরা খুব হঠকারিতা করতে ? যারা জ্ঞানপ্রাপ্ত হয়েছিল তারা বলবেঃ নিশ্চয়ই আজকের দিনে লাঞ্ছনা ও দুর্গতি কাফেরদের জন্যে', 'Thumma yawma alqiyamati yukhzeehim wayaqoolu ayna shurakaiya allatheena kuntum tushaqqoona feehim qala allatheena ootoo alAAilma inna alkhizya alyawma waalssooa AAala alkafireena', 1, NOW(), NOW()),
(21, 28, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ', 'ফেরেশতারা তাদের জান এমতাঅবস্থায় কবজ করে যে, তারা নিজেদের উপর যুলুম করেছে। তখন তারা অনুগত্য প্রকাশ করবে যে, আমরা তো কোন মন্দ কাজ করতাম না। হঁ্যা নিশ্চয় আল্লাহ সববিষয় অবগত আছেন, যা তোমরা করতে।', 'Allatheena tatawaffahumu almalaikatu thalimee anfusihim faalqawoo alssalama ma kunna naAAmalu min sooin bala inna Allaha AAaleemun bima kuntum taAAmaloona', 1, NOW(), NOW()),
(21, 29, 'فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ', 'অতএব, জাহান্নামের দরজসমূহে প্রবেশ কর, এতেই অনন্তকাল বাস কর। আর অহংকারীদের আবাসস্থল কতই নিকৃষ্ট।', 'Faodkhuloo abwaba jahannama khalideena feeha falabisa mathwa almutakabbireena', 1, NOW(), NOW()),
(21, 30, '۞وَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ', 'পরহেযগারদেরকে বলা হয়ঃ তোমাদের পালনকর্তা কি নাযিল করেছেন? তারা বলেঃ মহাকল্যাণ। যারা এ জগতে সৎকাজ করে, তাদের জন্যে কল্যাণ রয়েছে এবং পরকালের গৃহ আরও উত্তম। পরহেযগারদের গৃহ কি চমৎকার', 'Waqeela lillatheena ittaqaw matha anzala rabbukum qaloo khayran lillatheena ahsanoo fee hathihi alddunya hasanatun waladaru alakhirati khayrun walaniAAma daru almuttaqeena', 1, NOW(), NOW()),
(21, 31, 'جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ', 'সর্বদা বসবাসের উদ্যান, তারা যাতে প্রবেশ করবে। এর পাদদেশে দিয়ে স্রোতস্বিনী প্রবাহিত হয় তাদের জন্যে তাতে তা-ই রয়েছে, যা তারা চায় এমনিভাবে প্রতিদান দেবেন আল্লাহর পরহেযগারদেরকে', 'Jannatu AAadnin yadkhuloonaha tajree min tahtiha alanharu lahum feeha ma yashaoona kathalika yajzee Allahu almuttaqeena', 1, NOW(), NOW()),
(21, 32, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ', 'ফেরেশতা যাদের জান কবজ করেন তাদের পবিত্র থাকা অবস্থায়। ফেরেশতারা বলেঃ তোমাদের প্রতি শাস্তি বর্ষিত হোক। তোমরা যা করতে, তার প্রতিদানে জান্নাতে প্রবেশ কর।', 'Allatheena tatawaffahumu almalaikatu tayyibeena yaqooloona salamun AAalaykumu odkhuloo aljannata bima kuntum taAAmaloona', 1, NOW(), NOW()),
(21, 33, 'هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', 'কাফেররা কি এখন অপেক্ষা করছে যে, তাদের কাছে ফেরেশতারা আসবে কিংবা আপনার পালনকর্তার নির্দেশ পৌছবে? তাদের পূর্ববর্তীরা এমনই করেছিল। আল্লাহ তাদের প্রতি অবিচার করেননি; কিন্তু তারা স্বয়ং নিজেদের প্রতি জুলুম করেছিল।', 'Hal yanthuroona illa an tatiyahumu almalaikatu aw yatiya amru rabbika kathalika faAAala allatheena min qablihim wama thalamahumu Allahu walakin kanoo anfusahum yathlimoona', 1, NOW(), NOW()),
(21, 34, 'فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'সুতরাং তাদের মন্দ কাজের শাস্তি তাদেরই মাথায় আপতিত হয়েছে এবং তারা যে ঠাট্টা বিদ্রুপ করত, তাই উল্টে তাদের উপর পড়েছে।', 'Faasabahum sayyiatu ma AAamiloo wahaqa bihim ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(21, 35, 'وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٖ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءٖۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ', 'মুশরিকরা বললঃ যদি আল্লাহ চাইতেন, তবে আমরা তাঁকে ছাড়া কারও এবাদত করতাম না এবং আমাদের পিতৃপুরুষেরাও করত না এবং তাঁর নির্দেশ ছাড়া কোন বস্তুই আমরা হারাম করতাম না। তাদের পূর্ববর্তীরা এমনই করেছে। রাসূলের দায়িত্ব তো শুধুমাত্র সুস্পষ্ট বাণী পৌছিয়ে দেয়া।', 'Waqala allatheena ashrakoo law shaa Allahu ma AAabadna min doonihi min shayin nahnu wala abaona wala harramna min doonihi min shayin kathalika faAAala allatheena min qablihim fahal AAala alrrusuli illa albalaghu almubeenu', 1, NOW(), NOW()),
(21, 36, 'وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّـٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ', 'আমি প্রত্যেক উম্মতের মধ্যেই রাসূল প্রেরণ করেছি এই মর্মে যে, তোমরা আল্লাহর এবাদত কর এবং তাগুত থেকে নিরাপদ থাক। অতঃপর তাদের মধ্যে কিছু সংখ্যককে আল্লাহ হেদায়েত করেছেন এবং কিছু সংখ্যকের জন্যে বিপথগামিতা অবধারিত হয়ে গেল। সুতরাং তোমরা পৃথিবীতে ভ্রমণ কর এবং দেখ মিথ্যারোপকারীদের কিরূপ পরিণতি হয়েছে।', 'Walaqad baAAathna fee kulli ommatin rasoolan ani oAAbudoo Allaha waijtaniboo alttaghoota faminhum man hada Allahu waminhum man haqqat AAalayhi alddalalatu faseeroo fee alardi faonthuroo kayfa kana AAaqibatu almukaththibeena', 1, NOW(), NOW()),
(21, 37, 'إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ', 'আপনি তাদেরকে সুপথে আনতে আগ্রহী হলেও আল্লাহ যাকে বিপথগামী করেন তিনি তাকে পথ দেখান না এবং তাদের কোন সাহায্যকারী ও নেই।', 'In tahris AAala hudahum fainna Allaha la yahdee man yudillu wama lahum min nasireena', 1, NOW(), NOW()),
(21, 38, 'وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ', 'তারা আল্লাহর নামে কঠোর শপথ করে যে, যার মৃত্যু হয় আল্লাহ তাকে পুনরুজ্জীবিত করবেন না। অবশ্যই এর পাকাপোক্ত ওয়াদা হয়ে গেছে। কিন্তু, অধিকাংশ লোক জানে না।', 'Waaqsamoo biAllahi jahda aymanihim la yabAAathu Allahu man yamootu bala waAAdan AAalayhi haqqan walakinna akthara alnnasi la yaAAlamoona', 1, NOW(), NOW()),
(21, 39, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ', 'তিনি পুনরুজ্জীবিত করবেনই, যাতে যে বিষয়ে তাদের মধ্যে মতানৈক্য ছিল তা প্রকাশ করা যায় এবং যাতে কাফেরেরা জেনে নেয় যে, তারা মিথ্যাবাদী ছিল।', 'Liyubayyina lahumu allathee yakhtalifoona feehi waliyaAAlama allatheena kafaroo annahum kanoo kathibeena', 1, NOW(), NOW()),
(21, 40, 'إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', 'আমি যখন কোন কিছু করার ইচ্ছা করি; তখন তাকে কেবল এতটুকুই বলি যে, হয়ে যাও,। সুতরাং তা হয়ে যায়।', 'Innama qawluna lishayin itha aradnahu an naqoola lahu kun fayakoonu', 1, NOW(), NOW()),
(21, 41, 'وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ', 'যারা নির্যাতিত হওয়ার পর আল্লাহর জন্যে গৃহত্যাগ করেছে, আমি অবশ্যই তাদেরকে দুনিয়াতে উত্তম আবাস দেব এবং পরকালের পুরস্কার তো সর্বাধিক; হায়! যদি তারা জানত।', 'Waallatheena hajaroo fee Allahi min baAAdi ma thulimoo lanubawwiannahum fee alddunya hasanatan walaajru alakhirati akbaru law kanoo yaAAlamoona', 1, NOW(), NOW()),
(21, 42, 'ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ', 'যারা দৃঢ়পদ রয়েছে এবং তাদের পালনকর্তার উপর ভরসা করেছে।', 'Allatheena sabaroo waAAala rabbihim yatawakkaloona', 1, NOW(), NOW()),
(21, 43, 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ', 'আপনার পূর্বেও আমি প্রত্যাদেশসহ মানবকেই তাদের প্রতি প্রেরণ করেছিলাম অতএব জ্ঞানীদেরকে জিজ্ঞেস কর, যদি তোমাদের জানা না থাকে', 'Wama arsalna min qablika illa rijalan noohee ilayhim faisaloo ahla alththikri in kuntum la taAAlamoona', 1, NOW(), NOW()),
(21, 44, 'بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ', 'প্রেরণ করেছিলাম তাদেরকে নিꦣ2503;দশাবলী ও অবতীর্ণ গ্রন্থসহ এবং আপনার কাছে আমি স্মরণিকা অবতীর্ণ করেছি, যাতে আপনি লোকদের সামনে ঐসব বিষয় বিবৃত করেন, যে গুলো তোদের প্রতি নাযিল করা হয়েছে, যাতে তারা চিন্তা-ভাবনা করে।', 'Bialbayyinati waalzzuburi waanzalna ilayka alththikra litubayyina lilnnasi ma nuzzila ilayhim walaAAallahum yatafakkaroona', 1, NOW(), NOW()),
(21, 45, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ', 'যারা কুচক্র করে, তারা কি এ বিষয়ে ভয় করে না যে, আল্লাহ তাদেরকে ভূগর্ভে বিলীন করে দিবেন কিংবা তাদের কাছে এমন জায়গা থেকে আযাব আসবে যা তাদের ধারণাতীত।', 'Afaamina allatheena makaroo alssayyiati an yakhsifa Allahu bihimu alarda aw yatiyahumu alAAathabu min haythu la yashAAuroona', 1, NOW(), NOW()),
(21, 46, 'أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ', 'কিংবা চলাফেরার মধ্যেই তাদেরকে পাকড়াও করবে, তারা তো তা ব্যর্থ করতে পারবে না।', 'Aw yakhuthahum fee taqallubihim fama hum bimuAAjizeena', 1, NOW(), NOW()),
(21, 47, 'أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ', 'কিংবা ভীতি প্রদর্শনের পর তাদেরকে পাকড়াও করবেন? তোমাদের পালনকর্তা তো অত্যন্ত নম্র, দয়ালু।', 'Aw yakhuthahum AAala takhawwufin fainna rabbakum laraoofun raheemun', 1, NOW(), NOW()),
(21, 48, 'أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدٗا لِّلَّهِ وَهُمۡ دَٰخِرُونَ', 'তারা কি আল্লাহর সৃজিত বস্তু দেখে না, যার ছায়া আল্লাহর প্রতি বিনীতভাবে সেজদাবনত থেকে ডান ও বাম দিকে ঝুঁকে পড়ে।', 'Awa lam yaraw ila ma khalaqa Allahu min shayin yatafayyao thilaluhu AAani alyameeni waalshshamaili sujjadan lillahi wahum dakhiroona', 1, NOW(), NOW()),
(21, 49, 'وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةٖ وَٱلۡمَلَـٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ', 'আল্লাহকে সেজদা করে যা কিছু নভোমন্ডলে আছে এবং যা কিছু ভুমন্ডলে আছে এবং ফেরেশতাগণ; তারা অহংকার করে না।', 'Walillahi yasjudu ma fee alssamawati wama fee alardi min dabbatin waalmalaikatu wahum la yastakbiroona', 1, NOW(), NOW()),
(21, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩', 'তারা তাদের উপর পরাক্রমশালী তাদের পালনকর্তাকে ভয় করে এবং তারা যা আদেশ পায়, তা করে', 'Yakhafoona rabbahum min fawqihim wayafAAaloona ma yumaroona', 1, NOW(), NOW()),
(21, 51, '۞وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّـٰيَ فَٱرۡهَبُونِ', 'আল্লাহ বললেনঃ তোমরা দুই উপাস্য গ্রহণ করো না উপাস্য তো মাত্র একজনই। অতএব আমাকেই ভয় কর।', 'Waqala Allahu la tattakhithoo ilahayni ithnayni innama huwa ilahun wahidun faiyyaya fairhabooni', 1, NOW(), NOW()),
(21, 52, 'وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ', 'যা কিছু নভোমন্ডল ও ভুমন্ডলে আছে তা তাঁরই এবাদত করা শাশ্বত কর্তব্য। তোমরা কি আল্লাহ ব্যতীত কাউকে ভয় করবে', 'Walahu ma fee alssamawati waalardi walahu alddeenu wasiban afaghayra Allahi tattaqoona', 1, NOW(), NOW()),
(21, 53, 'وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ', 'তোমাদের কাছে যে সমস্ত নেয়ামত আছে, তা আল্লাহরই পক্ষ থেকে। অতঃপর তোমরা যখন দুঃখে-কষ্টে পতিত হও তখন তাঁরই নিকট কান্নাকাটি কর।', 'Wama bikum min niAAmatin famina Allahi thumma itha massakumu alddurru failayhi tajaroona', 1, NOW(), NOW()),
(21, 54, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ', 'এরপর যখন আল্লাহ তোমাদের কষ্ট দুরীভূত করে দেন, তখনই তোমাদের একদল স্বীয় পালনকর্তার সাথে অংশীদার সাব্যস্ত করতে থাকে।', 'Thumma itha kashafa alddurra AAankum itha fareequn minkum birabbihim yushrikoona', 1, NOW(), NOW()),
(21, 55, 'لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ', 'যাতে ঐ নেয়ামত অস্বীকার করে, যা আমি তাদেরকে দিয়েছি। অতএব মজা ভোগ করে নাও-সত্বরই তোমরা জানতে পারবে।', 'Liyakfuroo bima ataynahum fatamattaAAoo fasawfa taAAlamoona', 1, NOW(), NOW()),
(21, 56, 'وَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ', 'তারা আমার দেয়া জীবনোপকরণ থেকে তাদের জন্যে একটি অংশ নির্ধারিত করে, যাদের কোন খবরই তারা রাখে না। আল্লাহর কসম, তোমরা যে অপবাদ আরোপ করছ, সে সম্পর্কে অবশ্যই জিজ্ঞাসিত হবে।', 'WayajAAaloona lima la yaAAlamoona naseeban mimma razaqnahum taAllahi latusalunna AAamma kuntum taftaroona', 1, NOW(), NOW()),
(21, 57, 'وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ', 'তারা আল্লাহর জন্যে কন্যা সন্তান নির্ধারণ করে-তিনি পবিত্র মহিমান্বিত এবং নিজেদের জন্যে ওরা তাই স্থির করে যা ওরা চায়।', 'WayajAAaloona lillahi albanati subhanahu walahum ma yashtahoona', 1, NOW(), NOW()),
(21, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ', 'যখন তাদের কাউকে কন্যা সন্তানের সুসংবাদ দেয়া হয়, তখন তারা মুখ কাল হয়ে যায় এবং অসহ্য মনস্তাপে ক্লিষ্ট হতে থাকে।', 'Waitha bushshira ahaduhum bialontha thalla wajhuhu muswaddan wahuwa katheemun', 1, NOW(), NOW()),
(21, 59, 'يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ', 'তাকে শোনানো সুসংবাদের দুঃখে সে লোকদের কাছ থেকে মুখ লুকিয়ে থাকে। সে ভাবে, অপমান সহ্য করে তাকে থাকতে দেবে, না তাকে মাটির নীচে পুতে ফেলবে। শুনে রাখ, তাদের ফয়সালা খুবই নিকৃষ্ট।', 'Yatawara mina alqawmi min sooi ma bushshira bihi ayumsikuhu AAala hoonin am yadussuhu fee altturabi ala saa ma yahkumoona', 1, NOW(), NOW()),
(21, 60, 'لِلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'যারা পরকাল বিশ্বাস করে না, তাদের উদাহরণ নিকৃষ্ট এবং আল্লাহর উদাহরণই মহান, তিনি পরাক্রমশালী, প্রজ্ঞাময়।', 'Lillatheena la yuminoona bialakhirati mathalu alssawi walillahi almathalu alaAAla wahuwa alAAazeezu alhakeemu', 1, NOW(), NOW()),
(21, 61, 'وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ', 'যদি আল্লাহ লোকদেরকে তাদের অন্যায় কাজের কারণে পাকড়াও করতেন, তবে ভুপৃষ্ঠে চলমান কোন কিছুকেই ছাড়তেন না। কিন্তু তিনি প্রতিশ্রুতি সময় পর্যন্ত তাদেরকে অবকাশ দেন। অতঃপর নির্ধারিত সময়ে যখন তাদের মৃত্যু এসে যাবে, তখন এক মুহুর্তও বিলম্বিত কিংবা তরাম্বিত করতে পারবে না।', 'Walaw yuakhithu Allahu alnnasa bithulmihim ma taraka AAalayha min dabbatin walakin yuakhkhiruhum ila ajalin musamman faitha jaa ajaluhum la yastakhiroona saAAatan wala yastaqdimoona', 1, NOW(), NOW()),
(21, 62, 'وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ', 'যা নিজেদের মন চায় না তারই তারা আল্লাহর জন্যে সাব্যস্ত করে এবং তাদের জিহবা মিথ্যা বর্ণনা করে যে, তাদের জন্যে রয়েছে কল্যাণ। স্বতঃসিদ্ধ কথা যে, তাদের জন্যে রয়েছে আগুন এবং তাদেরকেই সর্বাগ্রে নিক্ষেপ করা হবে।', 'WayajAAaloona lillahi ma yakrahoona watasifu alsinatuhumu alkathiba anna lahumu alhusna la jarama anna lahumu alnnara waannahum mufratoona', 1, NOW(), NOW()),
(21, 63, 'تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'আল্লাহর কসম, আমি আপনার পূর্বে বিভিন্ন সম্প্রদায়ে রাসূল প্রেরণ করেছি, অতঃপর শয়তান তাদেরকে কর্ম সমূহ শোভনীয় করে দেখিয়েছে। আজ সেই তাদের অভিভাবক এবং তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।', 'TaAllahi laqad arsalna ila omamin min qablika fazayyana lahumu alshshaytanu aAAmalahum fahuwa waliyyuhumu alyawma walahum AAathabun aleemun', 1, NOW(), NOW()),
(21, 64, 'وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ', 'আমি আপনার প্রতি এ জন্যেই গ্রন্থ নাযিল করেছি, যাতে আপনি সরল পথ প্রদর্শনের জন্যে তাদের কে পরিষ্কার বর্ণনা করে দেন, যে বিষয়ে তারা মতবিরোধ করছে এবং ঈমানদারকে ক্ষমা করার জন্যে।', 'Wama anzalna AAalayka alkitaba illa litubayyina lahumu allathee ikhtalafoo feehi wahudan warahmatan liqawmin yuminoona', 1, NOW(), NOW()),
(21, 65, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ', 'আল্লাহ আকাশ থেকে পানি বর্ষণ করেছেন, তদ্বারা যমীনকে তার মৃত্যুর পর পুনর্জীবিত করেছেন। নিশ্চয় এতে তাদের জন্যে নিদর্শন রয়েছে, যারা শ্রবণ করে।', 'WaAllahu anzala mina alssamai maan faahya bihi alarda baAAda mawtiha inna fee thalika laayatan liqawmin yasmaAAoona', 1, NOW(), NOW()),
(21, 66, 'وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّـٰرِبِينَ', 'তোমাদের জন্যে চতুস্পদ জন্তুদের মধ্যে চিন্তা করার অবকাশ রয়েছে। আমি তোমাদেরকে পান করাই তাদের উদরস্থিত বস্তুসমুহের মধ্যে থেকে গোবর ও রক্ত নিঃসৃত দুগ্ধ যা পানকারীদের জন্যে উপাদেয়।', 'Wainna lakum fee alanAAami laAAibratan nusqeekum mimma fee butoonihi min bayni farthin wadamin labanan khalisan saighan lilshsharibeena', 1, NOW(), NOW()),
(21, 67, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ', 'এবং খেজুর বৃক্ষ ও আঙ্গুর ফল থেকে তোমরা মধ্য ও উত্তম খাদ্য তৈরী করে থাক, এতে অবশ্যই বোধশক্তি সম্পন্ন সম্প্রদায়ের জন্যে নিদর্শন রয়েছে।', 'Wamin thamarati alnnakheeli waalaAAnabi tattakhithoona minhu sakaran warizqan hasanan inna fee thalika laayatan liqawmin yaAAqiloona', 1, NOW(), NOW()),
(21, 68, 'وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ', 'আপনার পালনকর্তা মধু মক্ষিকাকে আদেশ দিলেনঃ পর্বতগাহ্রে, বৃক্ষ এবং উঁচু চালে গৃহ তৈরী কর', 'Waawha rabbuka ila alnnahli ani ittakhithee mina aljibali buyootan wamina alshshajari wamimma yaAArishoona', 1, NOW(), NOW()),
(21, 69, 'ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ', 'এরপর সর্বপ্রকার ফল থেকে ভক্ষণ কর এবং আপন পালনকর্তার উম্মুক্ত পথ সমূহে চলমান হও। তার পেট থেকে বিভিন্ন রঙে পানীয় নির্গত হয়। তাতে মানুষের জন্যে রয়েছে রোগের প্রতিকার। নিশ্চয় এতে চিন্তাশীল সম্প্রদায়ের জন্যে নিদর্শন রয়েছে।', 'Thumma kulee min kulli alththamarati faoslukee subula rabbiki thululan yakhruju min butooniha sharabun mukhtalifun alwanuhu feehi shifaon lilnnasi inna fee thalika laayatan liqawmin yatafakkaroona', 1, NOW(), NOW()),
(21, 70, 'وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ', 'আল্লাহ তোমাদেরকে সৃষ্টি করেছেন এরপর তোমাদের মৃত্যুদান করেন। তোমাদের মধ্যে কেউ কেউ পৌছে যায় জরাগ্রস্ত অকর্মন্য বয়সে, ফলে যা কিছু তারা জানত সে সম্পর্কে তারা সজ্ঞান থাকবে না। নিশ্চয় আল্লাহ সু-বিজ্ঞ সর্বশক্তিমান।', 'WaAllahu khalaqakum thumma yatawaffakum waminkum man yuraddu ila arthali alAAumuri likay la yaAAlama baAAda AAilmin shayan inna Allaha AAaleemun qadeerun', 1, NOW(), NOW()),
(21, 71, 'وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ', 'আল্লাহ তা’আলা জীবনোপকরণে তোমাদের একজনকে অন্যজনের চাইতে শ্রেষ্টত্ব দিয়েছেন। অতএব যাদেরকে শ্রেষ্ঠত্ব দেয়া হয়েছে, তারা তাদের অধীনস্থ দাস-দাসীদেরকে স্বীয় জীবিকা থেকে এমন কিছু দেয় না, যাতে তারা এ বিষয়ে তাদের সমান হয়ে যাবে। তবে কি তারা আল্লাহর নেয়ামত অস্বীকার করে।', 'WaAllahu faddala baAAdakum AAala baAAdin fee alrrizqi fama allatheena fuddiloo biraddee rizqihim AAala ma malakat aymanuhum fahum feehi sawaon afabiniAAmati Allahi yajhadoona', 1, NOW(), NOW()),
(21, 72, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ', 'আল্লাহ তোমাদের জন্যে তোমাদেরই শ্রেণী থেকে জোড়া পয়দা করেছেন এবং তোমাদের যুগল থেকে তোমাদেরকে পুত্র ও পৌত্রাদি দিয়েছেন এবং তোমাদেরকে উত্তম জীবনোপকরণ দান করেছেন। অতএব তারা কি মিথ্যা বিষয়ে বিশ্বাস স্থাপন করে এবং আল্লাহর অনুগ্রহ অস্বীকার করে', 'WaAllahu jaAAala lakum min anfusikum azwajan wajaAAala lakum min azwajikum baneena wahafadatan warazaqakum mina alttayyibati afabialbatili yuminoona wabiniAAmati Allahi hum yakfuroona', 1, NOW(), NOW()),
(21, 73, 'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقٗا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـٔٗا وَلَا يَسۡتَطِيعُونَ', 'তারা আল্লাহ ব্যতীত এমন বস্তুর ইবাদত করে, যে তাদের জন্যে ভুমন্ডল ও নভোমন্ডল থেকে সামান্য রুযী দেওয়ার ও অধিকার রাখে না এবং মুক্তি ও রাখে না।', 'WayaAAbudoona min dooni Allahi ma la yamliku lahum rizqan mina alssamawati waalardi shayan wala yastateeAAoona', 1, NOW(), NOW()),
(21, 74, 'فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', 'অতএব, আল্লাহর কোন সদৃশ সাব্যস্ত করো না, নিশ্চয় আল্লাহ জানেন এবং তোমরা জান না।', 'Fala tadriboo lillahi alamthala inna Allaha yaAAlamu waantum la taAAlamoona', 1, NOW(), NOW()),
(21, 75, '۞ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ', 'আল্লাহ একটি দৃষ্টান্ত বর্ণনা করেছেন, অপরের মালিকানাধীন গোলামের যে, কোন কিছুর উপর শক্তি রাখে না এবং এমন একজন যাকে আমি নিজের পক্ষ থেকে চমৎকার রুযী দিয়েছি। অতএব, সে তা থেকে ব্যয় করে গোপনে ও প্রকাশ্যে উভয়ে কি সমান হয়? সব প্রশংসা আল্লাহর, কিন্তু অনেক মানুষ জানে না।', 'Daraba Allahu mathalan AAabdan mamlookan la yaqdiru AAala shayin waman razaqnahu minna rizqan hasanan fahuwa yunfiqu minhu sirran wajahran hal yastawoona alhamdu lillahi bal aktharuhum la yaAAlamoona', 1, NOW(), NOW()),
(21, 76, 'وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আল্লাহ আরেকটি দৃষ্টান্ত বর্ণনা করেছেন, দু’ব্যক্তির, একজন বোবা কোন কাজ করতে পারে না। সে মালিকের উপর বোঝা। যেদিকে তাকে পাঠায়, কোন সঠিক কাজ করে আসে না। সে কি সমান হবে ঐ ব্যক্তির, যে ন্যায় বিচারের আদেশ করে এবং সরল পথে কায়েম রয়েছে।', 'Wadaraba Allahu mathalan rajulayni ahaduhuma abkamu la yaqdiru AAala shayin wahuwa kallun AAala mawlahu aynama yuwajjihhu la yati bikhayrin hal yastawee huwa waman yamuru bialAAadli wahuwa AAala siratin mustaqeemin', 1, NOW(), NOW()),
(21, 77, 'وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'নভোমন্ডল ও ভূমন্ডলের গোপন রহস্য আল্লাহর কাছেই রয়েছে। কিয়ামতের ব্যাপারটি তো এমন, যেমন চোখের পলক অথবা তার চাইতেও নিকটবর্তী। নিশ্চয় আল্লাহ সব কিছুর উপর শক্তিমান।', 'Walillahi ghaybu alssamawati waalardi wama amru alssaAAati illa kalamhi albasari aw huwa aqrabu inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(21, 78, 'وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ', 'আল্লাহ তোমাদেরকে তোমাদের মায়ের গর্ভ থেকে বের করেছেন। তোমরা কিছুই জানতে না। তিনি তোমাদেরকে কর্ণ, চক্ষু ও অন্তর দিয়েছেন, যাতে তোমরা অনুগ্রহ স্বীকার কর।', 'WaAllahu akhrajakum min butooni ommahatikum la taAAlamoona shayan wajaAAala lakumu alssamAAa waalabsara waalafidata laAAallakum tashkuroona', 1, NOW(), NOW()),
(21, 79, 'أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ', 'তারা কি উড়ন্ত পাখীকে দেখে না? এগুলো আকাশের অন্তরীক্ষে আজ্ঞাধীন রয়েছে। আল্লাহ ছাড়া কেউ এগুলোকে আগলে রাখে না। নিশ্চয় এতে বিশ্বাসীদের জন্যে নিদর্শনবলী রয়েছে।', 'Alam yaraw ila alttayri musakhkharatin fee jawwi alssamai ma yumsikuhunna illa Allahu inna fee thalika laayatin liqawmin yuminoona', 1, NOW(), NOW()),
(21, 80, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ', 'আল্লাহ করে দিয়েছেন তোমাদের গৃহকে অবস্থানের জায়গা এবং চতুস্পদ জন্তুর চামড়া দ্বারা করেছেন তোমার জন্যে তাঁবুর ব্যবস্থা। তোমরা এগুলোকে সফরকালে ও অবস্থান কালে পাও। ভেড়ার পশম, উটের বাবরি চুল ও ছাগলের লোম দ্বারা কত আসবাবপত্র ও ব্যবহারের সামগ্রী তৈরী করেছেন এক নির্দিষ্ট সময় পর্যন্ত।', 'WaAllahu jaAAala lakum min buyootikum sakanan wajaAAala lakum min juloodi alanAAami buyootan tastakhiffoonaha yawma thaAAnikum wayawma iqamatikum wamin aswafiha waawbariha waashAAariha athathan wamataAAan ila heenin', 1, NOW(), NOW()),
(21, 81, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ', 'আল্লাহ তোমাদের জন্যে সৃজিত বস্তু দ্বারা ছায়া করে দিয়েছেন এবং পাহাড় সমূহে তোমাদের জন্যে আত্ন গোপনের জায়গা করেছেন এবং তোমাদের জন্যে পোশাক তৈরী করে দিয়েছেন, যা তোমাদেরকে গ্রীষ্ম এবং বিপদের সময় রক্ষা করে। এমনিভাবে তিনি তোমাদের প্রতি স্বীয় অনুগ্রহের পূর্ণতা দান করেন, যাতে তোমরা আত্নসমর্পণ কর।', 'WaAllahu jaAAala lakum mimma khalaqa thilalan wajaAAala lakum mina aljibali aknanan wajaAAala lakum sarabeela taqeekumu alharra wasarabeela taqeekum basakum kathalika yutimmu niAAmatahu AAalaykum laAAallakum tuslimoona', 1, NOW(), NOW()),
(21, 82, 'فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ', 'অতঃপর যদি তারা পৃষ্ঠ প্রদর্শন করে, তবে আপনার কাজ হল সুস্পষ্ট ভাবে পৌছে দেয়া মাত্র।', 'Fain tawallaw fainnama AAalayka albalaghu almubeenu', 1, NOW(), NOW()),
(21, 83, 'يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ', 'তারা আল্লাহর অনুগ্রহ চিনে, এরপর অস্বীকার করে এবং তাদের অধিকাংশই অকৃতজ্ঞ।', 'YaAArifoona niAAmata Allahi thumma yunkiroonaha waaktharuhumu alkafiroona', 1, NOW(), NOW()),
(21, 84, 'وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةٖ شَهِيدٗا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ', 'যেদিন আমি প্রত্যেক উম্মত থেকে একজন বর্ণনাকারী দাঁড় করাব, তখন কাফেরদেরকে অনুমতি দেয়া হবে না এবং তাদের তওবা ও গ্রহণ করা হবে না।', 'Wayawma nabAAathu min kulli ommatin shaheedan thumma la yuthanu lillatheena kafaroo wala hum yustaAAtaboona', 1, NOW(), NOW()),
(21, 85, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ', 'যখন জালেমরা আযাব প্রত্যক্ষ করবে, তখন তাদের থেকে তা লঘু করা হবে না এবং তাদেরকে কোন অবকাশ দেয়া হবে না।', 'Waitha raa allatheena thalamoo alAAathaba fala yukhaffafu AAanhum wala hum yuntharoona', 1, NOW(), NOW()),
(21, 86, 'وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَـٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ', 'মুশরিকরা যখন ঐ সব বস্তুকে দেখবে, যেসবকে তারা আল্লাহর সাথে শরীক সাব্যস্ত করেছিল, তখন বলবেঃ হে আমাদের পালনকর্তা এরাই তারা যারা আমাদের শেরেকীর উপাদান, তোমাকে ছেড়ে আমরা যাদেরকে ডাকতাম। তখন ওরা তাদেরকে বলবেঃ তোমরা মিথ্যাবাদী।', 'Waitha raa allatheena ashrakoo shurakaahum qaloo rabbana haolai shurakaona allatheena kunna nadAAoo min doonika faalqaw ilayhimu alqawla innakum lakathiboona', 1, NOW(), NOW()),
(21, 87, 'وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ', 'সেদিন তারা আল্লাহর সামনে আত্নসমর্পন করবে এবং তারা যে মিথ্যা অপবাদ দিত তা বিস্মৃত হবে।', 'Waalqaw ila Allahi yawmaithin alssalama wadalla AAanhum ma kanoo yaftaroona', 1, NOW(), NOW()),
(21, 88, 'ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ', 'যারা কাফের হয়েছে এবং আল্লাহর পথে বাধা সৃষ্টি করেছে, আমি তাদেরকে আযাবের পর আযাব বাড়িয়ে দেব। কারণ, তারা অশান্তি সৃষ্টি করত।', 'Allatheena kafaroo wasaddoo AAan sabeeli Allahi zidnahum AAathaban fawqa alAAathabi bima kanoo yufsidoona', 1, NOW(), NOW()),
(21, 89, 'وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ', 'সেদিন প্রত্যেক উম্মতের মধ্যে আমি একজন বর্ণনাকারী দাঁড় করাব তাদের বিপক্ষে তাদের মধ্য থেকেই এবং তাদের বিষয়ে আপনাকে সাক্ষী স্বরূপ উপস্থাপন করব। আমি আপনার প্রতি গ্রন্থ নাযিল করেছি যেটি এমন যে তা প্রত্যেক বস্তুর সুস্পষ্ট বর্ণনা, হেদায়েত, রহমত এবং মুসলমানদের জন্যে সুসংবাদ।', 'Wayawma nabAAathu fee kulli ommatin shaheedan AAalayhim min anfusihim wajina bika shaheedan AAala haolai wanazzalna AAalayka alkitaba tibyanan likulli shayin wahudan warahmatan wabushra lilmuslimeena', 1, NOW(), NOW()),
(21, 90, '۞إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ', 'আল্লাহ ন্যায়পরায়ণতা, সদাচরণ এবং আত্নীয়-স্বজনকে দান করার আদেশ দেন এবং তিনি অশ্লীলতা, অসঙ্গত কাজ এবং অবাধ্যতা করতে বারণ করেন। তিনি তোমাদের উপদেশ দেন যাতে তোমরা স্মরণ রাখ।', 'Inna Allaha yamuru bialAAadli waalihsani waeetai thee alqurba wayanha AAani alfahshai waalmunkari waalbaghyi yaAAithukum laAAallakum tathakkaroona', 1, NOW(), NOW()),
(21, 91, 'وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ', 'আল্লাহর নামে অঙ্গীকার করার পর সে অঙ্গীকার পূর্ণ কর এবং পাকাপাকি কসম করার পর তা ভঙ্গ করো না, অথচ তোমরা আল্লাহকে জামিন করেছ। তোমরা যা কর আল্লাহ তা জানেন।', 'Waawfoo biAAahdi Allahi itha AAahadtum wala tanqudoo alaymana baAAda tawkeediha waqad jaAAaltumu Allaha AAalaykum kafeelan inna Allaha yaAAlamu ma tafAAaloona', 1, NOW(), NOW()),
(21, 92, 'وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', 'তোমরা ঐ মহিলার মত হয়ো না, যে পরিশ্রমের পর কাটা সূতা টুকরো টুকরো করে ছিড়ে ফেলে, তোমরা নিজেদের কসমসমূহকে পারস্পরিক প্রবঞ্চনার বাহানা রূপে গ্রহণ কর এজন্যে যে, অন্য দল অপেক্ষা এক দল অধিক ক্ষমতাবান হয়ে যায়। এতদ্বারা তো আল্লাহ শুধু তোমাদের পরীক্ষা করেন। আল্লাহ অবশ্যই কিয়ামতের দিন প্রকাশ করে দেবেন, যে বিষয়ে তোমরা কলহ করতে।', 'Wala takoonoo kaallatee naqadat ghazlaha min baAAdi quwwatin ankathan tattakhithoona aymanakum dakhalan baynakum an takoona ommatun hiya arba min ommatin innama yablookumu Allahu bihi walayubayyinanna lakum yawma alqiyamati ma kuntum feehi takhtalifoona', 1, NOW(), NOW()),
(21, 93, 'وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ', 'আল্লাহ ইচ্ছা করলে তোমাদের সবাইকে এক জাতি করে দিতে পারতেন, কিন্তু তিনি যাকে ইচ্ছা বিপথগামী করেন এবং যাকে ইচ্ছা পথ প্রদর্শন করেন। তোমরা যা কর সে বিষয়ে অবশ্যই জিজ্ঞাসিত হবে।', 'Walaw shaa Allahu lajaAAalakum ommatan wahidatan walakin yudillu man yashao wayahdee man yashao walatusalunna AAamma kuntum taAAmaloona', 1, NOW(), NOW()),
(21, 94, 'وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ', 'তোমরা স্বীয় কসমসমূহকে পারস্পরিক কলহ দ্বন্দ্বের বাহানা করো না। তা হলে দৃঢ়ভাবে প্রতিষ্ঠিত হওয়ার পর পা ফসকে যাবে এবং তোমরা শাস্তির স্বাদ আস্বাদন করবে এ কারণে যে, তোমরা আমার পথে বাধা দান করেছ এবং তোমাদের কঠোর শাস্তি হবে।', 'Wala tattakhithoo aymanakum dakhalan baynakum fatazilla qadamun baAAda thubootiha watathooqoo alssooa bima sadadtum AAan sabeeli Allahi walakum AAathabun AAatheemun', 1, NOW(), NOW()),
(21, 95, 'وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ', 'তোমরা আল্লাহর অঙ্গীকারের বিনিময়ে সামান্য মূল্য গ্রহণ করো না। নিশ্চয় আল্লাহর কাছে যা আছে, তা উত্তম তোমাদের জন্যে, যদি তোমরা জ্ঞানী হও।', 'Wala tashtaroo biAAahdi Allahi thamanan qaleelan innama AAinda Allahi huwa khayrun lakum in kuntum taAAlamoona', 1, NOW(), NOW()),
(21, 96, 'مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ', 'তোমাদের কাছে যা আছে নিঃশেষ হয়ে যাবে এবং আল্লাহর কাছে যা আছে, কখনও তা শেষ হবে না। যারা সবর করে, আমি তাদেরকে প্রাপ্য প্রতিদান দেব তাদের উত্তম কর্মের প্রতিদান স্বরূপ যা তারা করত।', 'Ma AAindakum yanfadu wama AAinda Allahi baqin walanajziyanna allatheena sabaroo ajrahum biahsani ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(21, 97, 'مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ', 'যে সৎকর্ম সম্পাদন করে এবং সে ঈমাণদার, পুরুষ হোক কিংবা নারী আমি তাকে পবিত্র জীবন দান করব এবং প্রতিদানে তাদেরকে তাদের উত্তম কাজের কারণে প্রাপ্য পুরষ্কার দেব যা তারা করত।', 'Man AAamila salihan min thakarin aw ontha wahuwa muminun falanuhyiyannahu hayatan tayyibatan walanajziyannahum ajrahum biahsani ma kanoo yaAAmaloona', 1, NOW(), NOW()),
(21, 98, 'فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ', 'অতএব, যখন আপনি কোরআন পাঠ করেন তখন বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় গ্রহণ করুন।', 'Faitha qarata alqurana faistaAAith biAllahi mina alshshaytani alrrajeemi', 1, NOW(), NOW()),
(21, 99, 'إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ', 'তার আধিপত্য চলে না তাদের উপর যারা বিশ্বাস স্থাপন করে এবং আপন পালন কর্তার উপর ভরসা রাখে।', 'Innahu laysa lahu sultanun AAala allatheena amanoo waAAala rabbihim yatawakkaloona', 1, NOW(), NOW()),
(21, 100, 'إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ', 'তার আধিপত্য তো তাদের উপরই চলে, যারা তাকে বন্ধু মনে করে এবং যারা তাকে অংশীদার মানে।', 'Innama sultanuhu AAala allatheena yatawallawnahu waallatheena hum bihi mushrikoona', 1, NOW(), NOW()),
(21, 101, 'وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ', 'এবং যখন আমি এক আয়াতের স্থলে অন্য আয়াত উপস্থিত করি এবং আল্লাহ যা অবতীর্ণ করেন তিনিই সে সম্পর্কে ভাল জানেন; তখন তারা বলেঃ আপনি তো মনগড়া উক্তি করেন; বরং তাদের অধিকাংশ লোকই জানে না।', 'Waitha baddalna ayatan makana ayatin waAllahu aAAlamu bima yunazzilu qaloo innama anta muftarin bal aktharuhum la yaAAlamoona', 1, NOW(), NOW()),
(21, 102, 'قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ', 'বলুন, একে পবিত্র ফেরেশতা পালনকর্তার পক্ষ থেকে নিশ্চিত সত্যসহ নাযিল করেছেন, যাতে মুমিনদেরকে প্রতিষ্ঠিত করেন এবং এটা মুসলমানদের জন্যে পথ নির্দেশ ও সু-সংবাদ স্বরূপ।', 'Qul nazzalahu roohu alqudusi min rabbika bialhaqqi liyuthabbita allatheena amanoo wahudan wabushra lilmuslimeena', 1, NOW(), NOW()),
(21, 103, 'وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ', 'আমি তো ভালভাবেই জানি যে, তারা বলেঃ তাকে জনৈক ব্যক্তি শিক্ষা দেয়। যার দিকে তারা ইঙ্গিত করে, তার ভাষা তো আরবী নয় এবং এ কোরআন পরিষ্কার আরবী ভাষায়।', 'Walaqad naAAlamu annahum yaqooloona innama yuAAallimuhu basharun lisanu allathee yulhidoona ilayhi aAAjamiyyun wahatha lisanun AAarabiyyun mubeenun', 1, NOW(), NOW()),
(21, 104, 'إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ', 'যারা আল্লাহর কথায় বিশ্বাস করে না, তাদেরকে আল্লাহ পথ প্রদর্শন করেন না এবং তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।', 'Inna allatheena la yuminoona biayati Allahi la yahdeehimu Allahu walahum AAathabun aleemun', 1, NOW(), NOW()),
(21, 105, 'إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ', 'মিথ্যা কেবল তারা রচনা করে, যারা আল্লাহর নিদর্শনে বিশ্বাস করে না এবং তারাই মিথ্যাবাদী।', 'Innama yaftaree alkathiba allatheena la yuminoona biayati Allahi waolaika humu alkathiboona', 1, NOW(), NOW()),
(21, 106, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ', 'যার উপর জবরদস্তি করা হয় এবং তার অন্তর বিশ্বাসে অটল থাকে সে ব্যতীত যে কেউ বিশ্বাসী হওয়ার পর আল্লাহতে অবিশ্বাসী হয় এবং কুফরীর জন্য মন উম্মুক্ত করে দেয় তাদের উপর আপতিত হবে আল্লাহর গযব এবং তাদের জন্যে রয়েছে শাস্তি।', 'Man kafara biAllahi min baAAdi eemanihi illa man okriha waqalbuhu mutmainnun bialeemani walakin man sharaha bialkufri sadran faAAalayhim ghadabun mina Allahi walahum AAathabun AAatheemun', 1, NOW(), NOW()),
(21, 107, 'ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ', 'এটা এ জন্যে যে, তারা পার্থিব জীবনকে পরকালের চাইতে প্রিয় মনে করেছে এবং আল্লাহ অবিশ্বাসীদেরকে পথ প্রদর্শন করেন না।', 'Thalika biannahumu istahabboo alhayata alddunya AAala alakhirati waanna Allaha la yahdee alqawma alkafireena', 1, NOW(), NOW()),
(21, 108, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ', 'এরাই তারা, আল্লাহ তা’য়ালা এদেরই অন্তর, কর্ণ ও চক্ষুর উপর মোহর মেরে দিয়েছেন এবং এরাই কান্ড জ্ঞানহীন।', 'Olaika allatheena tabaAAa Allahu AAala quloobihim wasamAAihim waabsarihim waolaika humu alghafiloona', 1, NOW(), NOW()),
(21, 109, 'لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ', 'বলাবাহুল্য পরকালে এরাই ক্ষতি গ্রস্ত হবে।', 'La jarama annahum fee alakhirati humu alkhasiroona', 1, NOW(), NOW()),
(21, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ', 'যারা দুঃখ-কষ্ট ভোগের পর দেশত্যাগী হয়েছে অতঃপর জেহাদ করেছে, নিশ্চয় আপনার পালনকর্তা এসব বিষয়ের পরে অবশ্যই ক্ষমাশীল, পরম দয়ালু।', 'Thumma inna rabbaka lillatheena hajaroo min baAAdi ma futinoo thumma jahadoo wasabaroo inna rabbaka min baAAdiha laghafoorun raheemun', 1, NOW(), NOW()),
(21, 111, '۞يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ', 'যেদিন প্রত্যেক ব্যক্তি আত্ন-সমর্থনে সওয়াল জওয়াব করতে করতে আসবে এবং প্রত্যেক ব্যক্তি তাদের কৃতকর্মের পূর্ণ ফল পাবে এবং তাদের উপর জুলুম করা হবে না।', 'Yawma tatee kullu nafsin tujadilu AAan nafsiha watuwaffa kullu nafsin ma AAamilat wahum la yuthlamoona', 1, NOW(), NOW()),
(21, 112, 'وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ', 'আল্লাহ দৃষ্টান্ত বর্ণনা করেছেন একটি জনপদের, যা ছিল নিরাপদ ও নিশ্চিন্ত, তথায় প্রত্যেক জায়গা থেকে আসত প্রচুর জীবনোপকরণ। অতঃপর তারা আল্লাহর নেয়ামতের প্রতি অকৃতজ্ঞতা প্রকাশ করল। তখন আল্লাহ তাদেরকে তাদের কৃতকর্মের কারণে স্বাদ আস্বাদন করালেন, ক্ষুধা ও ভীতির।', 'Wadaraba Allahu mathalan qaryatan kanat aminatan mutmainnatan yateeha rizquha raghadan min kulli makanin fakafarat bianAAumi Allahi faathaqaha Allahu libasa aljooAAi waalkhawfi bima kanoo yasnaAAoona', 1, NOW(), NOW()),
(21, 113, 'وَلَقَدۡ جَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ', 'তাদের কাছে তাদের মধ্য থেকেই একজন রাসূল আগমন করেছিলেন। অনন্তর ওরা তাঁর প্রতি মিথ্যারোপ করল। তখন আযাব এসে তাদরকে পাকড়াও করল এবং নিশ্চিতই ওরা ছিল পাপাচারী।', 'Walaqad jaahum rasoolun minhum fakaththaboohu faakhathahumu alAAathabu wahum thalimoona', 1, NOW(), NOW()),
(21, 114, 'فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ', 'অতএব, আল্লাহ তোমাদেরকে যেসব হালাল ও পবিত্র বস্তু দিয়েছেন, তা তোমরা আহার কর এবং আল্লাহর অনুগ্রহের জন্যে কৃতজ্ঞতা প্রকাশ কর যদি তোমরা তাঁরই এবাদতকারী হয়ে থাক।', 'Fakuloo mimma razaqakumu Allahu halalan tayyiban waoshkuroo niAAmata Allahi in kuntum iyyahu taAAbudoona', 1, NOW(), NOW()),
(21, 115, 'إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'অবশ্যই আল্লাহ তোমাদের জন্যে হারাম করেছেন রক্ত, শুকরের মাংস এবং যা জবাই কালে আল্লাহ ছাড়া অন্যের নাম উচ্চারণ করা হয়েছে। অতঃপর কেউ সীমালঙ্ঘন কারী না হয়ে নিরুপায় হয়ে পড়লে তবে, আল্লাহ ক্ষমাশীল, পরম দয়ালু।', 'Innama harrama AAalaykumu almaytata waalddama walahma alkhinzeeri wama ohilla lighayri Allahi bihi famani idturra ghayra baghin wala AAadin fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(21, 116, 'وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ', 'তোমাদের মুখ থেকে সাধারনতঃ যেসব মিথ্যা বের হয়ে আসে তেমনি করে তোমরা আল্লাহর বিরুদ্ধে মিথ্যা অপবাদ আরোপ করে বল না যে, এটা হালাল এবং ওটা হারাম। নিশ্চয় যারা আল্লাহর বিরুদ্ধে মিথ্যা আরোপ করে, তাদের মঙ্গল হবে না।', 'Wala taqooloo lima tasifu alsinatukumu alkathiba hatha halalun wahatha haramun litaftaroo AAala Allahi alkathiba inna allatheena yaftaroona AAala Allahi alkathiba la yuflihoona', 1, NOW(), NOW()),
(21, 117, 'مَتَٰعٞ قَلِيلٞ وَلَهُمۡ عَذَابٌ أَلِيمٞ', 'যৎসামান্য সুখ-সম্ভোগ ভোগ করে নিক। তাদের জন্যে যন্ত্রনাদায়ক শাস্তি রয়েছে।', 'MataAAun qaleelun walahum AAathabun aleemun', 1, NOW(), NOW()),
(21, 118, 'وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ', 'ইহুদীদের জন্যে আমি তো কেবল তাই হারাম করেছিলাম যা ইতিপূর্বে আপনার নিকট উল্লেখ করেছি। আমি তাদের প্রতি কোন জুলুম করিনি, কিন্তু তারাই নিজেদের উপর জুলুম করত।', 'WaAAala allatheena hadoo harramna ma qasasna AAalayka min qablu wama thalamnahum walakin kanoo anfusahum yathlimoona', 1, NOW(), NOW()),
(21, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ', 'অনন্তর যারা অজ্ঞতাবশতঃ মন্দ কাজ করে, অতঃপর তওবা করে এবং নিজেকে সংশোধন করে নেয়, আপনার পালনকর্তা এসবের পরে তাদের জন্যে অবশ্যই ক্ষমাশীল, দয়ালু।', 'Thumma inna rabbaka lillatheena AAamiloo alssooa bijahalatin thumma taboo min baAAdi thalika waaslahoo inna rabbaka min baAAdiha laghafoorun raheemun', 1, NOW(), NOW()),
(21, 120, 'إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ', 'নিশ্চয় ইব্রাহীম ছিলেন এক সম্প্রদায়ের প্রতীক, সবকিছু থেকে মুখ ফিরিয়ে এক আল্লাহরই অনুগত এবং তিনি শেরককারীদের অন্তর্ভুক্ত ছিলেন না।', 'Inna ibraheema kana ommatan qanitan lillahi haneefan walam yaku mina almushrikeena', 1, NOW(), NOW()),
(21, 121, 'شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'তিনি তাঁর অনুগ্রহের প্রতি কৃতজ্ঞতা প্রকাশকারী ছিলেন। আল্লাহ তাঁকে মনোনীত করেছিলেন এবং সরল পথে পরিচালিত করেছিলেন।', 'Shakiran lianAAumihi ijtabahu wahadahu ila siratin mustaqeemin', 1, NOW(), NOW()),
(21, 122, 'وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ', 'আমি তাঁকে দুনিয়াতে দান করেছি কল্যাণ এবং তিনি পরকালেও সৎকর্মশীলদের অন্তর্ভূক্ত।', 'Waataynahu fee alddunya hasanatan wainnahu fee alakhirati lamina alssaliheena', 1, NOW(), NOW()),
(21, 123, 'ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ', 'অতঃপর আপনার প্রতি প্রত্যাদেশ প্রেরণ করেছি যে, ইব্রাহীমের দ্বীন অনুসরণ করুন, যিনি একনিষ্ঠ ছিলেন এবং শিরককারীদের অন্তর্ভূক্ত ছিলেন না।', 'Thumma awhayna ilayka ani ittabiAA millata ibraheema haneefan wama kana mina almushrikeena', 1, NOW(), NOW()),
(21, 124, 'إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ', 'শনিবার দিন পালন যে, নির্ধারণ করা হয়েছিল, তা তাদের জন্যেই যারা এতে মতবিরোধ করেছিল। আপনার পালনকর্তা কিয়ামতের দিন তাদের মধ্যে ফয়সালা করবেন যে বিষয়ে তারা মতবিরোধ করত।', 'Innama juAAila alssabtu AAala allatheena ikhtalafoo feehi wainna rabbaka layahkumu baynahum yawma alqiyamati feema kanoo feehi yakhtalifoona', 1, NOW(), NOW()),
(21, 125, 'ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ', 'আপন পালনকর্তার পথের প্রতি আহবান করুন জ্ঞানের কথা বুঝিয়ে ও উপদেশ শুনিয়ে উত্তমরূপে এবং তাদের সাথে বিতর্ক করুন পছন্দ যুক্ত পন্থায়। নিশ্চয় আপনার পালনকর্তাই ঐ ব্যক্তি সম্পর্কে বিশেষ ভাবে জ্ঞাত রয়েছেন, যে তাঁর পথ থেকে বিচ্যুত হয়ে পড়েছে এবং তিনিই ভাল জানেন তাদেরকে, যারা সঠিক পথে আছে।', 'OdAAu ila sabeeli rabbika bialhikmati waalmawAAithati alhasanati wajadilhum biallatee hiya ahsanu inna rabbaka huwa aAAlamu biman dalla AAan sabeelihi wahuwa aAAlamu bialmuhtadeena', 1, NOW(), NOW()),
(21, 126, 'وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّـٰبِرِينَ', 'আর যদি তোমরা প্রতিশোধ গ্রহণ কর, তবে ঐ পরিমাণ প্রতিশোধ গ্রহণ করবে, যে পরিমাণ তোমাদেরকে কষ্ট দেয়া হয়। যদি সবর কর, তবে তা সবরকারীদের জন্যে উত্তম।', 'Wain AAaqabtum faAAaqiboo bimithli ma AAooqibtum bihi walain sabartum lahuwa khayrun lilssabireena', 1, NOW(), NOW()),
(21, 127, 'وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ', 'আপনি সবর করবেন। আপনার সবর আল্লাহর জন্য ব্যতীত নয়, তাদের জন্যে দুঃখ করবেন না এবং তাদের চক্রান্তের কারণে মন ছোট করবেন না।', 'Waisbir wama sabruka illa biAllahi wala tahzan AAalayhim wala taku fee dayqin mimma yamkuroona', 1, NOW(), NOW()),
(21, 128, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ', 'নিশ্চয় আল্লাহ তাদের সঙ্গে আছেন, যারা পরহেযগার এবং যারা সৎকর্ম করে।', 'Inna Allaha maAAa allatheena ittaqaw waallatheena hum muhsinoona', 1, NOW(), NOW()),
(22, 1, 'سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ', 'পরম পবিত্র ও মহিমাময় সত্তা তিনি, যিনি স্বীয় বান্দাকে রাত্রি বেলায় ভ্রমণ করিয়েছিলেন মসজিদে হারাম থেকে মসজিদে আকসা পর্যান্ত-যার চার দিকে আমি পর্যাপ্ত বরকত দান করেছি যাতে আমি তাঁকে কুদরতের কিছু নিদর্শন দেখিয়ে দেই। নিশ্চয়ই তিনি পরম শ্রবণকারী ও দর্শনশীল।', 'Subhana allathee asra biAAabdihi laylan mina almasjidi alharami ila almasjidi alaqsa allathee barakna hawlahu linuriyahu min ayatina innahu huwa alssameeAAu albaseeru', 1, NOW(), NOW()),
(22, 2, 'وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا', 'আমি মূসাকে কিতাব দিয়েছি এবং সেটিকে বনী-ইসরাঈলের জন্যে হেদায়েতে পরিণত করেছি যে, তোমরা আমাকে ছাড়া কাউকে কার্যনিবাহী স্থির করো না।', 'Waatayna moosa alkitaba wajaAAalnahu hudan libanee israeela alla tattakhithoo min doonee wakeelan', 1, NOW(), NOW()),
(22, 3, 'ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا', 'তোমরা তাদের সন্তান, যাদেরকে আমি নূহের সাথে সওয়ার করিয়েছিলাম। নিশ্চয় সে ছিল কৃতজ্ঞ বান্দা।', 'Thurriyyata man hamalna maAAa noohin innahu kana AAabdan shakooran', 1, NOW(), NOW()),
(22, 4, 'وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا', 'আমি বনী ইসরাঈলকে কিতাবে পরিষ্কার বলে দিয়েছি যে, তোমরা পৃথিবীর বুকে দুবার অনর্থ সৃষ্টি করবে এবং অত্যন্ত বড় ধরনের অবাধ্যতায় লিপ্ত হবে।', 'Waqadayna ila banee israeela fee alkitabi latufsidunna fee alardi marratayni walataAAlunna AAuluwwan kabeeran', 1, NOW(), NOW()),
(22, 5, 'فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا', 'অতঃপর যখন প্রতিশ্রুতি সেই প্রথম সময়টি এল, তখন আমি তোমাদের বিরুদ্ধে প্রেরণ করলাম আমার কঠোর যোদ্ধা বান্দাদেরকে। অতঃপর তারা প্রতিটি জনপদের আনাচে-কানাচে পর্যন্ত ছড়িয়ে পড়ল। এ ওয়াদা পূর্ণ হওয়ারই ছিল।', 'Faitha jaa waAAdu oolahuma baAAathna AAalaykum AAibadan lana olee basin shadeedin fajasoo khilala alddiyari wakana waAAdan mafAAoolan', 1, NOW(), NOW()),
(22, 6, 'ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا', 'অতঃপর আমি তোমাদের জন্যে তাদের বিরুদ্ধে পালা ঘুয়িয়ে দিলাম, তোমাদেরকে ধন-সম্পদ ও পুত্রসন্তান দ্বারা সাহায্য করলাম এবং তোমাদেরকে জনসংখ্যার দিক দিয়ে একটা বিরাট বাহিনীতে পরিণত করলাম।', 'Thumma radadna lakumu alkarrata AAalayhim waamdadnakum biamwalin wabaneena wajaAAalnakum akthara nafeeran', 1, NOW(), NOW()),
(22, 7, 'إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا', 'তোমরা যদি ভাল কর, তবে নিজেদেরই ভাল করবে এবং যদি মন্দ কর তবে তাও নিজেদের জন্যেই। এরপর যখন দ্বিতীয় সে সময়টি এল, তখন অন্য বান্দাদেরকে প্রেরণ করলাম, যাতে তোমাদের মুখমন্ডল বিকৃত করে দেয়, আর মসজিদে ঢুকে পড়ে যেমন প্রথমবার ঢুকেছিল এবং যেখানেই জয়ী হয়, সেখানেই পুরোপুরি ধ্বংসযজ্ঞ চালায়।', 'In ahsantum ahsantum lianfusikum wain asatum falaha faitha jaa waAAdu alakhirati liyasoooo wujoohakum waliyadkhuloo almasjida kama dakhaloohu awwala marratin waliyutabbiroo ma AAalaw tatbeeran', 1, NOW(), NOW()),
(22, 8, 'عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا', 'হয়ত তোমাদের পালনকর্তা তোমাদের প্রতি অনুগ্রহ করবেন। কিন্তু যদি পুনরায় তদ্রূপ কর, আমিও পুনরায় তাই করব। আমি জাহান্নামকে কাফেরদের জন্যে কয়েদখানা করেছি।', 'AAasa rabbukum an yarhamakum wain AAudtum AAudna wajaAAalna jahannama lilkafireena haseeran', 1, NOW(), NOW()),
(22, 9, 'إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا', 'এই কোরআন এমন পথ প্রদর্শন করে, যা সর্বাধিক সরল এবং সৎকর্ম পরায়ণ মুমিনদেরকে সুসংবাদ দেয় যে, তাদের জন্যে মহা পুরস্কার রয়েছে।', 'Inna hatha alqurana yahdee lillatee hiya aqwamu wayubashshiru almumineena allatheena yaAAmaloona alssalihati anna lahum ajran kabeeran', 1, NOW(), NOW()),
(22, 10, 'وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا', 'এবং যারা পরকালে বিশ্বাস করে না, আমি তাদের জন্যে যন্ত্রণাদায়ক শাস্তি প্রস্তুত করেছি।', 'Waanna allatheena la yuminoona bialakhirati aAAtadna lahum AAathaban aleeman', 1, NOW(), NOW()),
(22, 11, 'وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا', 'মানুষ যেভাবে কল্যাণ কামনা করে, সেভাবেই অকল্যাণ কামনা করে। মানুষ তো খুবই দ্রুততা প্রিয়।', 'WayadAAu alinsanu bialshsharri duAAaahu bialkhayri wakana alinsanu AAajoolan', 1, NOW(), NOW()),
(22, 12, 'وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا', 'আমি রাত্রি ও দিনকে দুটি নিদর্শন করেছি। অতঃপর নিস্প্রভ করে দিয়েছি রাতের নিদর্শন এবং দিনের নিদর্শনকে দেখার উপযোগী করেছি, যাতে তোমরা তোমাদের পালনকর্তার অনুগ্রহ অন্বেষণ কর এবং যাতে তোমরা স্থির করতে পার বছরসমূহের গণনা ও হিসাব এবং আমি সব বিষয়কে বিস্তারিত ভাবে বর্ণনা করেছি।', 'WajaAAalna allayla waalnnahara ayatayni famahawna ayata allayli wajaAAalna ayata alnnahari mubsiratan litabtaghoo fadlan min rabbikum walitaAAlamoo AAadada alssineena waalhisaba wakulla shayin fassalnahu tafseelan', 1, NOW(), NOW()),
(22, 13, 'وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَـٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا', 'আমি প্রত্যেক মানুষের কর্মকে তার গ্রীবলগ্ন করে রেখেছি। কেয়ামতের দিন বের করে দেখাব তাকে একটি কিতাব, যা সে খোলা অবস্থায় পাবে।', 'Wakulla insanin alzamnahu tairahu fee AAunuqihi wanukhriju lahu yawma alqiyamati kitaban yalqahu manshooran', 1, NOW(), NOW()),
(22, 14, 'ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا', 'পাঠ কর তুমি তোমার কিতাব। আজ তোমার হিসাব গ্রহণের জন্যে তুমিই যথেষ্ট।', 'Iqra kitabaka kafa binafsika alyawma AAalayka haseeban', 1, NOW(), NOW()),
(22, 15, 'مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا', 'যে কেউ সৎপথে চলে, তারা নিজের মঙ্গলের জন্যেই সৎ পথে চলে। আর যে পথভ্রষ্ট হয়, তারা নিজের অমঙ্গলের জন্যেই পথ ভ্রষ্ট হয়। কেউ অপরের বোঝা বহন করবে না। কোন রাসূল না পাঠানো পর্যন্ত আমি কাউকেই শাস্তি দান করি না।', 'Mani ihtada fainnama yahtadee linafsihi waman dalla fainnama yadillu AAalayha wala taziru waziratun wizra okhra wama kunna muAAaththibeena hatta nabAAatha rasoolan', 1, NOW(), NOW()),
(22, 16, 'وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا', 'যখন আমি কোন জনপদকে ধ্বংস করার ইচ্ছা করি তখন তার অবস্থাপন্ন লোকদেরকে উদ্ধুদ্ধ করি অতঃপর তারা পাপাচারে মেতে উঠে। তখন সে জনগোষ্টীর উপর আদেশ অবধারিত হয়ে যায়। অতঃপর আমি তাকে উঠিয়ে আছাড় দেই।', 'Waitha aradna an nuhlika qaryatan amarna mutrafeeha fafasaqoo feeha fahaqqa AAalayha alqawlu fadammarnaha tadmeeran', 1, NOW(), NOW()),
(22, 17, 'وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', 'নূহের পর আমি অনেক উম্মতকে ধ্বংস করেছি। আপনার পালনকর্তাই বান্দাদের পাপাচারের সংবাদ জানা ও দেখার জন্যে যথেষ্ট।', 'Wakam ahlakna mina alqurooni min baAAdi noohin wakafa birabbika bithunoobi AAibadihi khabeeran baseeran', 1, NOW(), NOW()),
(22, 18, 'مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا', 'যে কেউ ইহকাল কামনা করে, আমি সেসব লোককে যা ইচ্ছা সত্ত্বর দিয়ে দেই। অতঃপর তাদের জন্যে জাহান্নাম নির্ধারণ করি। ওরা তাতে নিন্দিত-বিতাড়িত অবস্থায় প্রবেশ করবে।', 'Man kana yureedu alAAajilata AAajjalna lahu feeha ma nashao liman nureedu thumma jaAAalna lahu jahannama yaslaha mathmooman madhooran', 1, NOW(), NOW()),
(22, 19, 'وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا', 'আর যারা পরকাল কামনা করে এবং মুমিন অবস্থায় তার জন্য যথাযথ চেষ্টা-সাধনা করে, এমন লোকদের চেষ্টা স্বীকৃত হয়ে থাকে।', 'Waman arada alakhirata wasaAAa laha saAAyaha wahuwa muminun faolaika kana saAAyuhum mashkooran', 1, NOW(), NOW()),
(22, 20, 'كُلّٗا نُّمِدُّ هَـٰٓؤُلَآءِ وَهَـٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا', 'এদেরকে এবং ওদেরকে প্রত্যেককে আমি আপনার পালনকর্তার দান পৌছে দেই এবং আপনার পালকর্তার দান অবধারিত।', 'Kullan numiddu haolai wahaolai min AAatai rabbika wama kana AAatao rabbika mahthooran', 1, NOW(), NOW()),
(22, 21, 'ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا', 'দেখুন, আমি তাদের একদলকে অপরের উপর কিভাবে শ্রেষ্ঠত্ব দান করলাম। পরকাল তো নিশ্চয়ই মর্তবায় শ্রেষ্ঠ এবং ফযীলতে শ্রেষ্ঠতম।', 'Onthur kayfa faddalna baAAdahum AAala baAAdin walalakhiratu akbaru darajatin waakbaru tafdeelan', 1, NOW(), NOW()),
(22, 22, 'لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا', 'স্থির করো না আল্লাহর সাথে অন্য কোন উপাস্য। তাহলে তুমি নিন্দিত ও অসহায় হয়ে পড়বে।', 'La tajAAal maAAa Allahi ilahan akhara fataqAAuda mathmooman makhthoolan', 1, NOW(), NOW()),
(22, 23, '۞وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا', 'তোমার পালনকর্তা আদেশ করেছেন যে, তাঁকে ছাড়া অন্য কারও এবাদত করো না এবং পিতা-মাতার সাথে সদ্ব-ব্যবহার কর। তাদের মধ্যে কেউ অথবা উভয়েই যদি তোমার জীবদ্দশায় বার্ধক্যে উপনীত হয়; তবে তাদেরকে ‘উহ’ শব্দটিও বলো না এবং তাদেরকে ধমক দিও না এবং বল তাদেরকে শিষ্ঠাচারপূর্ণ কথা।', 'Waqada rabbuka alla taAAbudoo illa iyyahu wabialwalidayni ihsanan imma yablughanna AAindaka alkibara ahaduhuma aw kilahuma fala taqul lahuma offin wala tanharhuma waqul lahuma qawlan kareeman', 1, NOW(), NOW()),
(22, 24, 'وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا', 'তাদের সামনে ভালবাসার সাথে, নম্রভাবে মাথা নত করে দাও এবং বলঃ হে পালনকর্তা, তাদের উভয়ের প্রতি রহম কর, যেমন তারা আমাকে শৈশবকালে লালন-পালন করেছেন।', 'Waikhfid lahuma janaha alththulli mina alrrahmati waqul rabbi irhamhuma kama rabbayanee sagheeran', 1, NOW(), NOW()),
(22, 25, 'رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّـٰبِينَ غَفُورٗا', 'তোমাদের পালনকর্তা তোমাদের মনে যা আছে তা ভালই জানেন। যদি তোমরা সৎ হও, তবে তিনি তওবাকারীদের জন্যে ক্ষমাশীল।', 'Rabbukum aAAlamu bima fee nufoosikum in takoonoo saliheena fainnahu kana lilawwabeena ghafooran', 1, NOW(), NOW()),
(22, 26, 'وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا', 'আত্নীয়-স্বজনকে তার হক দান কর এবং অভাবগ্রস্ত ও মুসাফিরকেও। এবং কিছুতেই অপব্যয় করো না।', 'Waati tha alqurba haqqahu waalmiskeena waibna alssabeeli wala tubaththir tabtheeran', 1, NOW(), NOW()),
(22, 27, 'إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا', 'নিশ্চয় অপব্যয়কারীরা শয়তানের ভাই। শয়তান স্বীয় পালনকর্তার প্রতি অতিশয় অকৃতজ্ঞ।', 'Inna almubaththireena kanoo ikhwana alshshayateeni wakana alshshaytanu lirabbihi kafooran', 1, NOW(), NOW()),
(22, 28, 'وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا', 'এবং তোমার পালনকর্তার করুণার প্রত্যাশায় অপেক্ষামান থাকাকালে যদি কোন সময় তাদেরকে বিমুখ করতে হয়, তখন তাদের সাথে নম্রভাবে কথা বল।', 'Waimma tuAAridanna AAanhumu ibtighaa rahmatin min rabbika tarjooha faqul lahum qawlan maysooran', 1, NOW(), NOW()),
(22, 29, 'وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا', 'তুমি একেবারে ব্যয়-কুষ্ঠ হয়োনা এবং একেবারে মুক্ত হস্তও হয়ো না। তাহলে তুমি তিরস্কৃতি, নিঃস্ব হয়ে বসে থাকবে।', 'Wala tajAAal yadaka maghloolatan ila AAunuqika wala tabsutha kulla albasti fataqAAuda malooman mahsooran', 1, NOW(), NOW()),
(22, 30, 'إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', 'নিশ্চয় তোমার পালকর্তা যাকে ইচ্ছা অধিক জীবনোপকরণ দান করেন এবং তিনিই তা সংকুচিতও করে দেন। তিনিই তাঁর বান্দাদের সম্পর্কে ভালোভাবে অবহিত,-সব কিছু দেখছেন।', 'Inna rabbaka yabsutu alrrizqa liman yashao wayaqdiru innahu kana biAAibadihi khabeeran baseeran', 1, NOW(), NOW()),
(22, 31, 'وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا', 'দারিদ্রের ভয়ে তোমাদের সন্তানদেরকে হত্যা করো না। তাদেরকে এবং তোমাদেরকে আমিই জীবনোপকরণ দিয়ে থাকি। নিশ্চয় তাদেরকে হত্যা করা মারাত্নক অপরাধ।', 'Wala taqtuloo awladakum khashyata imlaqin nahnu narzuquhum waiyyakum inna qatlahum kana khitan kabeeran', 1, NOW(), NOW()),
(22, 32, 'وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا', 'আর ব্যভিচারের কাছেও যেয়ো না। নিশ্চয় এটা অশ্লীল কাজ এবং মন্দ পথ।', 'Wala taqraboo alzzina innahu kana fahishatan wasaa sabeelan', 1, NOW(), NOW()),
(22, 33, 'وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا', 'সে প্রাণকে হত্যা করো না, যাকে আল্লাহ হারাম করেছেন; কিন্তু ন্যায়ভাবে। যে ব্যক্তি অন্যায়ভাবে নিহত হয়, আমি তার উত্তরাধিকারীকে ক্ষমতা দান করি। অতএব, সে যেন হত্যার ব্যাপারে সীমা লঙ্ঘন না করে। নিশ্চয় সে সাহায্যপ্রাপ্ত।', 'Wala taqtuloo alnnafsa allatee harrama Allahu illa bialhaqqi waman qutila mathlooman faqad jaAAalna liwaliyyihi sultanan fala yusrif fee alqatli innahu kana mansooran', 1, NOW(), NOW()),
(22, 34, 'وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا', 'আর, এতিমের মালের কাছেও যেয়ো না, একমাত্র তার কল্যাণ আকাংখা ছাড়া; সংশ্লিষ্ট ব্যক্তির যৌবনে পদার্পন করা পর্যন্ত এবং অঙ্গীকার পূর্ন কর। নিশ্চয় অঙ্গীকার সম্পর্কে জিজ্ঞাসাবাদ করা হবে।', 'Wala taqraboo mala alyateemi illa biallatee hiya ahsanu hatta yablugha ashuddahu waawfoo bialAAahdi inna alAAahda kana masoolan', 1, NOW(), NOW()),
(22, 35, 'وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا', 'মেপে দেয়ার সময় পূর্ণ মাপে দেবে এবং সঠিক দাঁড়িপালায় ওজন করবে। এটা উত্তম; এর পরিণাম শুভ।', 'Waawfoo alkayla itha kiltum wazinoo bialqistasi almustaqeemi thalika khayrun waahsanu taweelan', 1, NOW(), NOW()),
(22, 36, 'وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَـٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا', 'যে বিষয়ে তোমার কোন জ্ঞান নেই, তার পিছনে পড়ো না। নিশ্চয় কান, চক্ষু ও অন্তঃকরণ এদের প্রত্যেকটিই জিজ্ঞাসিত হবে।', 'Wala taqfu ma laysa laka bihi AAilmun inna alssamAAa waalbasara waalfuada kullu olaika kana AAanhu masoolan', 1, NOW(), NOW()),
(22, 37, 'وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا', 'পৃথিবীতে দম্ভভরে পদচারণা করো না। নিশ্চয় তুমি তো ভূ পৃষ্ঠকে কখনই বিদীর্ণ করতে পারবে না এবং উচ্চতায় তুমি কখনই পর্বত প্রমাণ হতে পারবে না।', 'Wala tamshi fee alardi marahan innaka lan takhriqa alarda walan tablugha aljibala toolan', 1, NOW(), NOW()),
(22, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا', 'এ সবের মধ্যে যেগুলো মন্দকাজ, সেগুলো তোমার পালনকর্তার কাছে অপছন্দনীয়।', 'Kullu thalika kana sayyiohu AAinda rabbika makroohan', 1, NOW(), NOW()),
(22, 39, 'ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا', 'এটা ঐ হিকমতের অন্তর্ভূক্ত, যা আপনার পালনকর্তা আপনাকে ওহী মারফত দান করেছেন। আল্লাহর সাথে অন্য কোন উপাস্য স্থির করবেন না। তাহলে অভিযুক্ত ও আল্লাহর অনুগ্রহ থেকে বিতাড়িত অবস্থায় জাহান্নামে নিক্ষিপ্ত হবেন।', 'Thalika mimma awha ilayka rabbuka mina alhikmati wala tajAAal maAAa Allahi ilahan akhara fatulqa fee jahannama malooman madhooran', 1, NOW(), NOW()),
(22, 40, 'أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَـٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا', 'তোমাদের পালনকর্তা কি তোমাদের জন্যে পুত্র সন্তান নির্ধারিত করেছেন এবং নিজের জন্যে ফেরেশতাদেরকে কন্যারূপে গ্রহণ করেছেন? নিশ্চয় তোমরা গুরুতর গর্হিত কথাবার্তা বলছ।', 'Afaasfakum rabbukum bialbaneena waittakhatha mina almalaikati inathan innakum lataqooloona qawlan AAatheeman', 1, NOW(), NOW()),
(22, 41, 'وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا', 'আমি এই কোরআনে নানাভাবে বুঝিয়েছি, যাতে তারা চিন্তা করে। অথচ এতে তাদের কেবল বিমুখতাই বৃদ্ধি পায়।', 'Walaqad sarrafna fee hatha alqurani liyaththakkaroo wama yazeeduhum illa nufooran', 1, NOW(), NOW()),
(22, 42, 'قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا', 'বলুনঃ তাদের কথামত যদি তাঁর সাথে অন্যান্য উপাস্য থাকত; তবে তারা আরশের মালিক পর্যন্ত পৌছার পথ অন্বেষন করত।', 'Qul law kana maAAahu alihatun kama yaqooloona ithan laibtaghaw ila thee alAAarshi sabeelan', 1, NOW(), NOW()),
(22, 43, 'سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا', 'তিনি নেহায়েত পবিত্র ও মহিমান্বিত এবং তারা যা বলে থাকে তা থেকে বহু উর্ধ্বে।', 'Subhanahu wataAAala AAamma yaqooloona AAuluwwan kabeeran', 1, NOW(), NOW()),
(22, 44, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا', 'সপ্ত আকাশ ও পৃথিবী এবং এগুলোর মধ্যে যাকিছু আছে সমস্ত কিছু তাঁরই পবিত্রতা ও মহিমা ঘোষণা করে। এবং এমন কিছু নেই যা তার সপ্রশংস পবিত্রতা ও মহিমা ঘোষনা করে না। কিন্তু তাদের পবিত্রতা, মহিমা ঘোষণা তোমরা অনুধাবন করতে পার না। নিশ্চয় তিনি অতি সহনশীল, ক্ষমাপরায়ণ।', 'Tusabbihu lahu alssamawatu alssabAAu waalardu waman feehinna wain min shayin illa yusabbihu bihamdihi walakin la tafqahoona tasbeehahum innahu kana haleeman ghafooran', 1, NOW(), NOW()),
(22, 45, 'وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا', 'যখন আপনি কোরআন পাঠ করেন, তখন আমি আপনার মধ্যে ও পরকালে অবিশ্বাসীদের মধ্যে প্রচ্ছন্ন পর্দা ফেলে দেই।', 'Waitha qarata alqurana jaAAalna baynaka wabayna allatheena la yuminoona bialakhirati hijaban mastooran', 1, NOW(), NOW()),
(22, 46, 'وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا', 'আমি তাদের অন্তরের উপর আবরণ রেখে দেই, যাতে তারা একে উপলব্ধি করতে না পারে এবং তাদের কর্ণকুহরে বোঝা চাপিয়ে দেই। যখন আপনি কোরআনে পালনকর্তার একত্ব আবৃত্তি করেন, তখন ও অনীহাবশতঃ ওরা পৃষ্ট প্রদর্শন করে চলে যায়।', 'WajaAAalna AAala quloobihim akinnatan an yafqahoohu wafee athanihim waqran waitha thakarta rabbaka fee alqurani wahdahu wallaw AAala adbarihim nufooran', 1, NOW(), NOW()),
(22, 47, 'نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا', 'যখন তারা কান পেতে আপনার কথা শোনে, তখন তারা কেন কান পেতে তা শোনে, তা আমি ভাল জানি এবং এও জানি গোপনে আলোচনাকালে যখন জালেমরা বলে, তোমরা তো এক যাদুগ্রস্থ ব্যক্তির অনুসরণ করছ।', 'Nahnu aAAlamu bima yastamiAAoona bihi ith yastamiAAoona ilayka waith hum najwa ith yaqoolu alththalimoona in tattabiAAoona illa rajulan mashooran', 1, NOW(), NOW()),
(22, 48, 'ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا', 'দেখুন, ওরা আপনার জন্যে কেমন উপমা দেয়। ওরা পথভ্রষ্ট হয়েছে। অতএব, ওরা পথ পেতে পারে না।', 'Onthur kayfa daraboo laka alamthala fadalloo fala yastateeAAoona sabeelan', 1, NOW(), NOW()),
(22, 49, 'وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا', 'তারা বলেঃ যখন আমরা অস্থিতে পরিণত ও চূর্ণ বিচূর্ণ হয়ে যাব, তখনও কি নতুন করে সৃজিত হয়ে উত্থিত হব', 'Waqaloo aitha kunna AAithaman warufatan ainna lamabAAoothoona khalqan jadeedan', 1, NOW(), NOW()),
(22, 50, '۞قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا', 'বলুনঃ তোমরা পাথর হয়ে যাও কিংবা লোহা।', 'Qul koonoo hijaratan aw hadeedan', 1, NOW(), NOW()),
(22, 51, 'أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا', 'অথবা এমন কোন বস্তু, যা তোমাদের ধারণায় খুবই কঠিন; তথাপি তারা বলবেঃ আমাদের কে পুর্নবার কে সৃষ্টি করবে। বলুনঃ যিনি তোমাদেরকে প্রথমবার সৃজন করেছেন। অতঃপর তারা আপনার সামনে মাথা নাড়বে এবং বলবেঃ এটা কবে হবে? বলুনঃ হবে, সম্ভবতঃ শ্রীঘ্রই।', 'Aw khalqan mimma yakburu fee sudoorikum fasayaqooloona man yuAAeeduna quli allathee fatarakum awwala marratin fasayunghidoona ilayka ruoosahum wayaqooloona mata huwa qul AAasa an yakoona qareeban', 1, NOW(), NOW()),
(22, 52, 'يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا', 'যেদিন তিনি তোমাদেরকে আহবান করবেন, অতঃপর তোমরা তাঁর প্রশংসা করতে করতে চলে আসবে। এবং তোমরা অনুমান করবে যে, সামান্য সময়ই অবস্থান করেছিলে।', 'Yawma yadAAookum fatastajeeboona bihamdihi watathunnoona in labithtum illa qaleelan', 1, NOW(), NOW()),
(22, 53, 'وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا', 'আমার বান্দাদেরকে বলে দিন, তারা যেন যা উত্তম এমন কথাই বলে। শয়তান তাদের মধ্যে সংঘর্ষ বাধায়। নিশ্চয় শয়তান মানুষের প্রকাশ্য শত্রু।', 'Waqul liAAibadee yaqooloo allatee hiya ahsanu inna alshshaytana yanzaghu baynahum inna alshshaytana kana lilinsani AAaduwwan mubeenan', 1, NOW(), NOW()),
(22, 54, 'رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا', 'তোমাদের পালনকর্তা তোমাদের সম্পর্কে ভালভাবে জ্ঞাত আছেন। তিনি যদি চান, তোমাদের প্রতি রহমত করবেন কিংবা যদি চান, তোমাদের আযাব দিবেন। আমি আপনাকে ওদের সবার তত্ত্বাবধায়ক রূপে প্রেরণ করিনি।', 'Rabbukum aAAlamu bikum in yasha yarhamkum aw in yasha yuAAaththibkum wama arsalnaka AAalayhim wakeelan', 1, NOW(), NOW()),
(22, 55, 'وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا', 'আপনার পালনকর্তা তাদের সম্পর্কে ভালভাবে জ্ঞাত আছেন, যারা আকাশসমূহে ও ভুপৃষ্ঠে রয়েছে। আমি তো কতক পয়গম্বরকে কতক পয়গম্বরের উপর শ্রেষ্ঠত্ব দান করেছি এবং দাউদকে যবুর দান করেছি।', 'Warabbuka aAAlamu biman fee alssamawati waalardi walaqad faddalna baAAda alnnabiyyeena AAala baAAdin waatayna dawooda zabooran', 1, NOW(), NOW()),
(22, 56, 'قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا', 'বলুনঃ আল্লাহ ব্যতীত যাদেরকে তোমরা উপাস্য মনে কর, তাদেরকে আহবান কর। অথচ ওরা তো তোমাদের কষ্ট দুর করার ক্ষমতা রাখে না এবং তা পরিবর্তনও করতে পারে না।', 'Quli odAAu allatheena zaAAamtum min doonihi fala yamlikoona kashfa alddurri AAankum wala tahweelan', 1, NOW(), NOW()),
(22, 57, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا', 'যাদেরকে তারা আহবান করে, তারা নিজেরাই তো তাদের পালনকর্তার নৈকট্য লাভের জন্য মধ্যস্থ তালাশ করে যে, তাদের মধ্যে কে নৈকট্যশীল। তারা তাঁর রহমতের আশা করে এবং তাঁর শাস্তিকে ভয় করে। নিশ্চয় আপনার পালনকর্তার শাস্তি ভয়াবহ।', 'Olaika allatheena yadAAoona yabtaghoona ila rabbihimu alwaseelata ayyuhum aqrabu wayarjoona rahmatahu wayakhafoona AAathabahu inna AAathaba rabbika kana mahthooran', 1, NOW(), NOW()),
(22, 58, 'وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا', 'এমন কোন জনপদ নেই, যাকে আমি কেয়ামত দিবসের পূর্বে ধ্বংস করব না অথবা যাকে কঠোর শাস্তি দেব না। এটা তো গ্রন্থে লিপিবদ্ধ হয়ে গেছে।', 'Wain min qaryatin illa nahnu muhlikooha qabla yawmi alqiyamati aw muAAaththibooha AAathaban shadeedan kana thalika fee alkitabi mastooran', 1, NOW(), NOW()),
(22, 59, 'وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا', 'পূর্ববর্তীগণ কতৃꦣ2453; নিদর্শন অস্বীকার করার ফলেই আমাকে নিদর্শনাবলী প্রেরণ থেকে বিরত থাকতে হয়েছে। আমি তাদেরকে বোঝাবার জন্যে সামুদকে উষ্ট্রী দিয়েছিলাম। অতঃপর তারা তার প্রতি জুলুম করেছিল। আমি ভীতি প্রদর্শনের উদ্দেশেই নিদর্শন প্রেরণ করি।', 'Wama manaAAana an nursila bialayati illa an kaththaba biha alawwaloona waatayna thamooda alnnaqata mubsiratan fathalamoo biha wama nursilu bialayati illa takhweefan', 1, NOW(), NOW()),
(22, 60, 'وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا', 'এবং স্মরণ করুন, আমি আপনাকে বলে দিয়েছিলাম যে, আপনার পালনকর্তা মানুষকে পরিবেষ্টন করে রেখেছেন এবং যে দৃশ্য আমি আপনাকে দেখিয়েছি তাও কোরআনে উল্লেখিত অভিশপ্ত বৃক্ষ কেবল মানুষের পরীক্ষার জন্যে। আমি তাদেরকে ভয় প্রদর্শন করি। কিন্তু এতে তাদের অবাধ্যতাই আরও বৃদ্ধি পায়।', 'Waith qulna laka inna rabbaka ahata bialnnasi wama jaAAalna alrruya allatee araynaka illa fitnatan lilnnasi waalshshajarata almalAAoonata fee alqurani wanukhawwifuhum fama yazeeduhum illa tughyanan kabeeran', 1, NOW(), NOW()),
(22, 61, 'وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا', 'স্মরণ কর, যখন আমি ফেরেশতাদেরকে বললামঃ আদমকে সেজদা কর, তখন ইবলীস ব্যতীত সবাই সেজদায় পড়ে গেল। কিন্তু সে বললঃ আমি কি এমন ব্যক্তিকে সেজদা করব, যাকে আপনি মাটির দ্বারা সৃষ্টি করেছেন', 'Waith qulna lilmalaikati osjudoo liadama fasajadoo illa ibleesa qala aasjudu liman khalaqta teenan', 1, NOW(), NOW()),
(22, 62, 'قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا', 'সে বললঃ দেখুন তো, এনা সে ব্যক্তি, যাকে আপনি আমার চাইতেও উচ্চ মার্যাদা দিয়ে দিয়েছেন। যদি আপনি আমাকে কেয়ামত দিবস পর্যন্ত সময় দেন, তবে আমি সামান্য সংখ্যক ছাড়া তার বংশধরদেরকে সমূলে নষ্ট করে দেব।', 'Qala araaytaka hatha allathee karramta AAalayya lain akhkhartani ila yawmi alqiyamati laahtanikanna thurriyyatahu illa qaleelan', 1, NOW(), NOW()),
(22, 63, 'قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا', 'আল্লাহ বলেনঃ চলে যা, অতঃপর তাদের মধ্য থেকে যে তোর অনুগামী হবে, জাহান্নামই হবে তাদের সবার শাস্তি-ভরপুর শাস্তি।', 'Qala ithhab faman tabiAAaka minhum fainna jahannama jazaokum jazaan mawfooran', 1, NOW(), NOW()),
(22, 64, 'وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا', 'তুই সত্যচ্যুত করে তাদের মধ্য থেকে যাকে পারিস স্বীয় আওয়ায দ্বারা, স্বীয় অশ্বারোহী ও পদাতিক বাহিনী নিয়ে তাদেরকে আক্রমণ কর, তাদের অর্থ-সম্পদ ও সন্তান-সন্ততিতে শরীক হয়ে যা এবং তাদেরকে প্রতিশ্রুতি দে। ছলনা ছাড়া শয়তান তাদেরকে কোন প্রতিশ্রুতি দেয় না।', 'Waistafziz mani istataAAta minhum bisawtika waajlib AAalayhim bikhaylika warajlika washarikhum fee alamwali waalawladi waAAidhum wama yaAAiduhumu alshshaytanu illa ghurooran', 1, NOW(), NOW()),
(22, 65, 'إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا', 'আমার বান্দাদের উপর তোর কোন ক্ষমতা নেই আপনার পালনকর্তা যথেষ্ট কার্যনির্বাহী।', 'Inna AAibadee laysa laka AAalayhim sultanun wakafa birabbika wakeelan', 1, NOW(), NOW()),
(22, 66, 'رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا', 'তোমাদের পালনকর্তা তিনিই, যিনি তোমাদের জন্যে সমুদ্রে জলযান চালনা করেন, যাতে তোমরা তার অনুগ্রহ অন্বেষন করতে পারো। নিঃ সন্দেহে তিনি তোমাদের প্রতি পরম দয়ালূ।', 'Rabbukumu allathee yuzjee lakumu alfulka fee albahri litabtaghoo min fadlihi innahu kana bikum raheeman', 1, NOW(), NOW()),
(22, 67, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا', 'যখন সমুদ্রে তোমাদের উপর বিপদ আসে, তখন শুধু আল্লাহ ব্যতীত যাদেরকে তোমরা আহবান করে থাক তাদেরকে তোমরা বিস্মৃত হয়ে যাও। অতঃপর তিনি যখন তোমাদেরকে স্থলে ভিড়িয়ে উদ্ধার করে নেন, তখন তোমরা মুখ ফিরিয়ে নাও। মানুষ বড়ই অকৃতজ্ঞ।', 'Waitha massakumu alddurru fee albahri dalla man tadAAoona illa iyyahu falamma najjakum ila albarri aAAradtum wakana alinsanu kafooran', 1, NOW(), NOW()),
(22, 68, 'أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا', 'তোমরা কি এ বিষয়ে নিশ্চিন্ত রয়েছ যে, তিনি তোমাদেরকে স্থলভাগে কোথাও ভূগর্ভস্থ করবেন না। অথবা তোমাদের উপর প্রস্তর বর্ষণকারী ঘুর্ণিঝড় প্রেরণ করবেন না, তখন তোমরা নিজেদের জন্যে কোন কর্মবিধায়ক পাবে না।', 'Afaamintum an yakhsifa bikum janiba albarri aw yursila AAalaykum hasiban thumma la tajidoo lakum wakeelan', 1, NOW(), NOW()),
(22, 69, 'أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا', 'অথবা তোমরা কি এ বিষয়ে নিশ্চিন্ত যে, তিনি তোমাদেরকে আরেকবার সমুদ্রে নিয়ে যাবেন না, অতঃপর তোমাদের জন্যে মহা ঝটিকা প্রেরণ করবেন না, অতঃপর অকৃতজ্ঞতার শাস্তিস্বরূপ তোমাদেরকে নিমজ্জত করবেন না, তখন তোমরা আমার বিরুদ্ধে এ বিষয়ে সাহায্যকারী কাউকে পাবে না।', 'Am amintum an yuAAeedakum feehi taratan okhra fayursila AAalaykum qasifan mina alrreehi fayughriqakum bima kafartum thumma la tajidoo lakum AAalayna bihi tabeeAAan', 1, NOW(), NOW()),
(22, 70, '۞وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا', 'নিশ্চয় আমি আদম সন্তানকে মর্যাদা দান করেছি, আমি তাদেরকে স্থলে ও জলে চলাচলের বাহন দান করেছি; তাদেরকে উত্তম জীবনোপকরণ প্রদান করেছি এবং তাদেরকে অনেক সৃষ্ট বস্তুর উপর শ্রেষ্ঠত্ব দান করেছি।', 'Walaqad karramna banee adama wahamalnahum fee albarri waalbahri warazaqnahum mina alttayyibati wafaddalnahum AAala katheerin mimman khalaqna tafdeelan', 1, NOW(), NOW()),
(22, 71, 'يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَـٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا', 'স্মরণ কর, যেদিন আমি প্রত্যেক দলকে তাদের নেতাসহ আহবান করব, অতঃপর যাদেরকে তাদের ডান হাতে আমলনামা দেয়া হবে, তারা নিজেদের আমলনামা পাঠ করবে এবং তাদের প্রতি সামান্য পরিমাণও জুলুম হবে না।', 'Yawma nadAAoo kulla onasin biimamihim faman ootiya kitabahu biyameenihi faolaika yaqraoona kitabahum wala yuthlamoona fateelan', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(22, 72, 'وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا', 'যে ব্যক্তি ইহকালে অন্ধ ছিল সে পরকালেও অন্ধ এবং অধিকতর পথভ্রান্ত।', 'Waman kana fee hathihi aAAma fahuwa fee alakhirati aAAma waadallu sabeelan', 1, NOW(), NOW()),
(22, 73, 'وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا', 'তারা তো আপনাকে হটিয়ে দিতে চাচ্ছিল যে বিষয় আমি আপনার প্রতি ওহীর মাধ্যমে যা প্রেরণ করেছি তা থেকে আপনার পদঙ্খলন ঘটানোর জন্যে তারা চুড়ান্ত চেষ্টা করেছে, যাতে আপনি আমার প্রতি কিছু মিথ্যা সম্বন্ধযুক্ত করেন। এতে সফল হলে তারা আপনাকে বন্ধুরূপে গ্রহণ করে নিত।', 'Wain kadoo layaftinoonaka AAani allathee awhayna ilayka litaftariya AAalayna ghayrahu waithan laittakhathooka khaleelan', 1, NOW(), NOW()),
(22, 74, 'وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا', 'আমি আপনাকে দৃঢ়পদ না রাখলে আপনি তাদের প্রতি কিছুটা ঝুঁকেই পড়তেন।', 'Walawla an thabbatnaka laqad kidta tarkanu ilayhim shayan qaleelan', 1, NOW(), NOW()),
(22, 75, 'إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا', 'তখন আমি অবশ্যই আপনাকে ইহজীবনে ও পরজীবনে দ্বিগুণ শাস্তির আস্বাদন করাতাম। এ সময় আপনি আমার মোকাবিলায় কোন সাহায্যকারী পেতেন না।', 'Ithan laathaqnaka diAAfa alhayati wadiAAfa almamati thumma la tajidu laka AAalayna naseeran', 1, NOW(), NOW()),
(22, 76, 'وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا', 'তারা তো আপনাকে এ ভুখন্ড থেকে উৎখাত করে দিতে চুড়ান্ত চেষ্টা করেছিল যাতে আপনাকে এখান থেকে বহিস্কার করে দেয়া যায়। তখন তারাও আপনার পর সেখানে অল্প কালই মাত্র টিকে থাকত।', 'Wain kadoo layastafizzoonaka mina alardi liyukhrijooka minha waithan la yalbathoona khilafaka illa qaleelan', 1, NOW(), NOW()),
(22, 77, 'سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا', 'আপনার পূর্বে আমি যত রসূল প্রেরণ করেছি, তাদের ক্ষেত্রেও এরূপ নিয়ম ছিল। আপনি আমার নিয়মের কোন ব্যতিক্রম পাবেন না।', 'Sunnata man qad arsalna qablaka min rusulina wala tajidu lisunnatina tahweelan', 1, NOW(), NOW()),
(22, 78, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا', 'সূর্য ঢলে পড়ার সময় থেকে রাত্রির অন্ধকার পর্যন্ত নামায কায়েম করুন এবং ফজরের কোরআন পাঠও। নিশ্চয় ফজরের কোরআন পাঠ মুখোমুখি হয়।', 'Aqimi alssalata lidulooki alshshamsi ila ghasaqi allayli waqurana alfajri inna qurana alfajri kana mashhoodan', 1, NOW(), NOW()),
(22, 79, 'وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا', 'রাত্রির কিছু অংশ কোরআন পাঠ সহ জাগ্রত থাকুন। এটা আপনার জন্যে অতিরিক্ত। হয়ত বা আপনার পালনকর্তা আপনাকে মোকামে মাহমুদে পৌঁছাবেন।', 'Wamina allayli fatahajjad bihi nafilatan laka AAasa an yabAAathaka rabbuka maqaman mahmoodan', 1, NOW(), NOW()),
(22, 80, 'وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا', 'বলুনঃ হে পালনকর্তা! আমাকে দাখিল করুন সত্যরূপে এবং আমাকে বের করুন সত্যরূপে এবং দান করুন আমাকে নিজের কাছ থেকে রাষ্ট্রীয় সাহায্য।', 'Waqul rabbi adkhilnee mudkhala sidqin waakhrijnee mukhraja sidqin waijAAal lee min ladunka sultanan naseeran', 1, NOW(), NOW()),
(22, 81, 'وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا', 'বলুনঃ সত্য এসেছে এবং মিথ্যা বিলুপ্ত হয়েছে। নিশ্চয় মিথ্যা বিলুপ্ত হওয়ারই ছিল।', 'Waqul jaa alhaqqu wazahaqa albatilu inna albatila kana zahooqan', 1, NOW(), NOW()),
(22, 82, 'وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّـٰلِمِينَ إِلَّا خَسَارٗا', 'আমি কোরআনে এমন বিষয় নাযিল করি যা রোগের সুচিকিৎসা এবং মুমিনের জন্য রহমত। গোনাহগারদের তো এতে শুধু ক্ষতিই বৃদ্ধি পায়।', 'Wanunazzilu mina alqurani ma huwa shifaon warahmatun lilmumineena wala yazeedu alththalimeena illa khasaran', 1, NOW(), NOW()),
(22, 83, 'وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا', 'আমি মানুষকে নেয়ামত দান করলে সে মুখ ফিরিয়ে নেয় এবং অহংকারে দুরে সরে যায়; যখন তাকে কোন অনিষ্ট স্পর্শ করে, তখন সে একেবারে হতাশ হয়ে পড়ে।', 'Waitha anAAamna AAala alinsani aAArada wanaa bijanibihi waitha massahu alshsharru kana yaoosan', 1, NOW(), NOW()),
(22, 84, 'قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا', 'বলুনঃ প্রত্যেকেই নিজ রীতি অনুযায়ী কাজ করে। অতঃপর আপনার পালনকর্তা বিশেষ রূপে জানেন, কে সর্বাপেক্ষা নির্ভূল পথে আছে।', 'Qul kullun yaAAmalu AAala shakilatihi farabbukum aAAlamu biman huwa ahda sabeelan', 1, NOW(), NOW()),
(22, 85, 'وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا', 'তারা আপনাকে রূহ সম্পর্কে জিজ্ঞেস করে। বলে দিনঃ রূহ আমার পালনকর্তার আদেশ ঘটিত। এ বিষয়ে তোমাদেরকে সামান্য জ্ঞানই দান করা হয়েছে।', 'Wayasaloonaka AAani alrroohi quli alrroohu min amri rabbee wama ooteetum mina alAAilmi illa qaleelan', 1, NOW(), NOW()),
(22, 86, 'وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا', 'আমি ইচ্ছা করলে আপনার কাছে ওহীর মাধমে যা প্রেরণ করেছি তা অবশ্যই প্রত্যাহার করতে পারতাম। অতঃপর আপনি নিজের জন্যে তা আনয়নের ব্যাপারে আমার মোকাবিলায় কোন দায়িত্ব বহনকারী পাবেন না।', 'Walain shina lanathhabanna biallathee awhayna ilayka thumma la tajidu laka bihi AAalayna wakeelan', 1, NOW(), NOW()),
(22, 87, 'إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا', 'এ প্রত্যাহার না করা আপনার পালনকর্তার মেহেরবানী। নিশ্চয় আপনার প্রতি তাঁর করুণা বিরাট।', 'Illa rahmatan min rabbika inna fadlahu kana AAalayka kabeeran', 1, NOW(), NOW()),
(22, 88, 'قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا', 'বলুনঃ যদি মানব ও জ্বিন এই কোরআনের অনুরূপ রচনা করে আনয়নের জন্যে জড়ো হয়, এবং তারা পরস্পরের সাহায্যকারী হয়; তবুও তারা কখনও এর অনুরূপ রচনা করে আনতে পারবে না।', 'Qul laini ijtamaAAati alinsu waaljinnu AAala an yatoo bimithli hatha alqurani la yatoona bimithlihi walaw kana baAAduhum libaAAdin thaheeran', 1, NOW(), NOW()),
(22, 89, 'وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا', 'আমি এই কোরআনে মানুষকে বিভিন্ন উপকার দ্বারা সব রকম বিষয়বস্তু বুঝিয়েছি। কিন্তু অধিকাংশ লোক অস্বীকার না করে থাকেনি।', 'Walaqad sarrafna lilnnasi fee hatha alqurani min kulli mathalin faaba aktharu alnnasi illa kufooran', 1, NOW(), NOW()),
(22, 90, 'وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا', 'এবং তারা বলেঃ আমরা কখনও আপনাকে বিশ্বাস করব না, যে পর্যন্ত না আপনি ভূপৃষ্ঠ থেকে আমাদের জন্যে একটি ঝরণা প্রবাহিত করে দিন।', 'Waqaloo lan numina laka hatta tafjura lana mina alardi yanbooAAan', 1, NOW(), NOW()),
(22, 91, 'أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا', 'অথবা আপনার জন্যে খেজুরের ও আঙ্গুরের একটি বাগান হবে, অতঃপর আপনি তার মধ্যে নির্ঝরিনীসমূহ প্রবাহিত করে দেবেন।', 'Aw takoona laka jannatun min nakheelin waAAinabin fatufajjira alanhara khilalaha tafjeeran', 1, NOW(), NOW()),
(22, 92, 'أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ قَبِيلًا', 'অথবা আপনি যেমন বলে থাকেন, তেমনিভাবে আমাদের উপর আসমানকে খন্ড-বিখন্ড করে ফেলে দেবেন অথবা আল্লাহ ও ফেরেশতাদেরকে আমাদের সামনে নিয়ে আসবেন।', 'Aw tusqita alssamaa kama zaAAamta AAalayna kisafan aw tatiya biAllahi waalmalaikati qabeelan', 1, NOW(), NOW()),
(22, 93, 'أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا', 'অথবা আপনার কোন সোনার তৈরী গৃহ হবে অথবা আপনি আকাশে আরোহণ করবেন এবং আমরা আপনার আকাশে আরোহণকে কখনও বিশ্বাস করবনা, যে পর্যন্ত না আপনি অবতীর্ণ করেন আমাদের প্রতি এক গ্রন্থ, যা আমরা পাঠ করব। বলুনঃ পবিত্র মহান আমার পালনকর্তা, একজন মানব, একজন রসূল বৈ আমি কে', 'Aw yakoona laka baytun min zukhrufin aw tarqa fee alssamai walan numina liruqiyyika hatta tunazzila AAalayna kitaban naqraohu qul subhana rabbee hal kuntu illa basharan rasoolan', 1, NOW(), NOW()),
(22, 94, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا', 'আল্লাহ কি মানুষকে পয়গম্বর করে পাঠিয়েছেন? তাদের এই উক্তিই মানুষকে ঈমান আনয়ন থেকে বিরত রাখে, যখন তাদের নিকট আসে হেদায়েত।', 'Wama manaAAa alnnasa an yuminoo ith jaahumu alhuda illa an qaloo abaAAatha Allahu basharan rasoolan', 1, NOW(), NOW()),
(22, 95, 'قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَـٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا', 'বলুনঃ যদি পৃথিবীতে ফেরেশতারা স্বচ্ছন্দে বিচরণ করত, তবে আমি আকাশ থেকে কোন ফেরেশতাকেই তাদের নিকট পয়গাম্বর করে প্রেরণ করতাম।', 'Qul law kana fee alardi malaikatun yamshoona mutmainneena lanazzalna AAalayhim mina alssamai malakan rasoolan', 1, NOW(), NOW()),
(22, 96, 'قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا', 'বলুনঃ আমার ও তোমাদের মধ্যে সত্য প্রতিষ্ঠাকারী হিসেবে আল্লাহই যথেষ্ট। তিনি তো স্বীয় বান্দাদের বিষয়ে খবর রাখেন ও দেখেন।', 'Qul kafa biAllahi shaheedan baynee wabaynakum innahu kana biAAibadihi khabeeran baseeran', 1, NOW(), NOW()),
(22, 97, 'وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا', 'আল্লাহ যাকে পথ প্রদর্শন করেন, সেই তো সঠিক পথ প্রাপ্ত এবং যাকে পথ ভ্রষ্ট করেন, তাদের জন্যে আপনি আল্লাহ ছাড়া কোন সাহায্যকারী পাবেন না। আমি কেয়ামতের দিন তাদের সমবেত করব তাদের মুখে ভর দিয়ে চলা অবস্থায়, অন্ধ অবস্থায়, মুক অবস্থায় এবং বধির অবস্থায়। তাদের আবাসস্থল জাহান্নাম। যখনই নির্বাপিত হওয়ার উপক্রম হবে আমি তখন তাদের জন্যে অগ্নি আরও বৃদ্ধি করে দিব।', 'Waman yahdi Allahu fahuwa almuhtadi waman yudlil falan tajida lahum awliyaa min doonihi wanahshuruhum yawma alqiyamati AAala wujoohihim AAumyan wabukman wasumman mawahum jahannamu kullama khabat zidnahum saAAeeran', 1, NOW(), NOW()),
(22, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا', 'এটাই তাদের শাস্তি। কারণ, তারা আমার নিদর্শনসমূহ অস্বীকার করেছে এবং বলেছেঃ আমরা যখন অস্থিতে পরিণত ও চুর্ণ-বিচুর্ণ হয়ে যাব, তখনও কি আমরা নতুনভাবে সৃজিত হয়ে উত্থিত হব', 'Thalika jazaohum biannahum kafaroo biayatina waqaloo aitha kunna AAithaman warufatan ainna lamabAAoothoona khalqan jadeedan', 1, NOW(), NOW()),
(22, 99, '۞أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورٗا', 'তারা কি দেখেনি যে, যে আল্লাহ আসমান ও যমিন সৃজিত করেছেন, তিনি তাদের মত মানুষও পুনরায় সৃষ্টি করতে সক্ষম? তিনি তাদের জন্যে স্থির করেছেন একটি নির্দিষ্ট কাল, এতে কোন সন্দেহ নেই; অতঃপর জালেমরা অস্বীকার ছাড়া কিছু করেনি।', 'Awalam yaraw anna Allaha allathee khalaqa alssamawati waalarda qadirun AAala an yakhluqa mithlahum wajaAAala lahum ajalan la rayba feehi faaba alththalimoona illa kufooran', 1, NOW(), NOW()),
(22, 100, 'قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا', 'বলুনঃ যদি আমার পালনকর্তার রহমতের ভান্ডার তোমাদের হাতে থাকত, তবে ব্যয়িত হয়ে যাওয়ার আশঙ্কায় অবশ্যই তা ধরে রাখতে। মানুষ তো অতিশয় কৃপণ।', 'Qul law antum tamlikoona khazaina rahmati rabbee ithan laamsaktum khashyata alinfaqi wakana alinsanu qatooran', 1, NOW(), NOW()),
(22, 101, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا', 'আপনি বণী-ইসরাঈলকে জিজ্ঞেস করুন, আমি মূসাকে নয়টি প্রকাশ্য নিদর্শন দান করেছি। যখন তিনি তাদের কাছে আগমন করেন, ফেরাউন তাকে বললঃ হে মূসা, আমার ধারনায় তুমি তো জাদুগ্রস্থ।', 'Walaqad atayna moosa tisAAa ayatin bayyinatin faisal banee israeela ith jaahum faqala lahu firAAawnu innee laathunnuka ya moosa mashooran', 1, NOW(), NOW()),
(22, 102, 'قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَـٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا', 'তিনি বললেনঃ তুমি জান যে, আসমান ও যমীনের পালনকর্তাই এসব নিদর্শনাবলী প্রত্যক্ষ প্রমাণস্বরূপ নাযিল করেছেন। হে ফেরাউন, আমার ধারণায় তুমি ধ্বংস হতে চলেছো।', 'Qala laqad AAalimta ma anzala haolai illa rabbu alssamawati waalardi basaira wainnee laathunnuka ya firAAawnu mathbooran', 1, NOW(), NOW()),
(22, 103, 'فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا', 'অতঃপর সে বনী ইসরাঈলকে দেশ থেকে উৎখাত করতে চাইল, তখন আমি তাকে ও তার সঙ্গীদের সবাইকে নিমজ্জত করে দিলাম।', 'Faarada an yastafizzahum mina alardi faaghraqnahu waman maAAahu jameeAAan', 1, NOW(), NOW()),
(22, 104, 'وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا', 'তারপর আমি বনী ইসলাঈলকে বললামঃ এ দেশে তোমরা বসবাস কর। অতঃপর যখন পরকালের ওয়াদা বাস্তবায়িত হবে, তখন তোমাদের কে জড়ো করে নিয়ে উপস্থিত হব।', 'Waqulna min baAAdihi libanee israeela oskunoo alarda faitha jaa waAAdu alakhirati jina bikum lafeefan', 1, NOW(), NOW()),
(22, 105, 'وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا', 'আমি সত্যসহ এ কোরআন নাযিল করেছি এবং সত্য সহ এটা নাযিল হয়েছে। আমি তো আপনাকে শুধু সুসংবাদাতা ও ভয়প্রদর্শক করেই প্রেরণ করেছি।', 'Wabialhaqqi anzalnahu wabialhaqqi nazala wama arsalnaka illa mubashshiran wanatheeran', 1, NOW(), NOW()),
(22, 106, 'وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا', 'আমি কোরআনকে যতিচিহ্ন সহ পৃথক পৃথকভাবে পাঠের উপযোগী করেছি, যাতে আপনি একে লোকদের কাছে ধীরে ধীরে পাঠ করেন এবং আমি একে যথাযথ ভাবে অবতীর্ণ করেছি।', 'Waquranan faraqnahu litaqraahu AAala alnnasi AAala mukthin wanazzalnahu tanzeelan', 1, NOW(), NOW()),
(22, 107, 'قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ', 'বলুনঃ তোমরা কোরআনকে মান্য কর অথবা অমান্য কর; যারা এর পূর্ব থেকে এলেম প্রাপ্ত হয়েছে, যখন তাদের কাছে এর তেলাওয়াত করা হয়, তখন তারা নতমস্তকে সেজদায় লুটিয়ে পড়ে।', 'Qul aminoo bihi aw la tuminoo inna allatheena ootoo alAAilma min qablihi itha yutla AAalayhim yakhirroona lilathqani sujjadan', 1, NOW(), NOW()),
(22, 108, 'وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا', 'এবং বলেঃ আমাদের পালনকর্তা পবিত্র, মহান। নিঃসন্দেহে আমাদের পালকর্তার ওয়াদা অবশ্যই পূর্ণ হবে।', 'Wayaqooloona subhana rabbina in kana waAAdu rabbina lamafAAoolan', 1, NOW(), NOW()),
(22, 109, 'وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩', 'তারা ক্রন্দন করতে করতে নতমস্তকে ভুমিতে লুটিয়ে পড়ে এবং তাদের বিনয়ভাব আরো বৃদ্ধি পায়।', 'Wayakhirroona lilathqani yabkoona wayazeeduhum khushooAAan', 1, NOW(), NOW()),
(22, 110, 'قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا', 'বলুনঃ আল্লাহ বলে আহবান কর কিংবা রহমান বলে, যে নামেই আহবান কর না কেন, সব সুন্দর নাম তাঁরই। আপনি নিজের নামায আদায়কালে স্বর উচ্চগ্রাসে নিয়ে গিয়ে পড়বেন না এবং নিঃশব্দেও পড়বেন না। এতদুভয়ের মধ্যমপন্থা অবলম্বন করুন।', 'Quli odAAoo Allaha awi odAAoo alrrahmana ayyan ma tadAAoo falahu alasmao alhusna wala tajhar bisalatika wala tukhafit biha waibtaghi bayna thalika sabeelan', 1, NOW(), NOW()),
(22, 111, 'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا', 'বলুনঃ সমস্ত প্রশংসা আল্লাহর যিনি না কোন সন্তান রাখেন, না তাঁর সার্বভৌমত্বে কোন শরীক আছে এবং যিনি দুর্দশাগ্রস্ত হন না, যে কারণে তাঁর কোন সাহয্যকারীর প্রয়োজন হতে পারে। সুতরাং আপনি স-সম্ভ্রমে তাঁর মাহাত্ন?2476;র্ণনা করতে থাকুন।', 'Waquli alhamdu lillahi allathee lam yattakhith waladan walam yakun lahu shareekun fee almulki walam yakun lahu waliyyun mina alththulli wakabbirhu takbeeran', 1, NOW(), NOW()),
(23, 1, 'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ', 'সব প্রশংসা আল্লাহর যিনি নিজের বান্দার প্রতি এ গ্রন্থ নাযিল করেছেন এবং তাতে কোন বক্রতা রাখেননি।', 'Alhamdu lillahi allathee anzala AAala AAabdihi alkitaba walam yajAAal lahu AAiwajan', 1, NOW(), NOW()),
(23, 2, 'قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا', 'একে সুপ্রতিষ্ঠিত করেছেন যা আল্লাহর পক্ষ থেকে একটি ভীষণ বিপদের ভয় প্রদর্শন করে এবং মুমিনদেরকে যারা সৎকর্ম সম্পাদন করে-তাদেরকে সুসংবাদ দান করে যে, তাদের জন্যে উত্তম প্রতিদান রয়েছে।', 'Qayyiman liyunthira basan shadeedan min ladunhu wayubashshira almumineena allatheena yaAAmaloona alssalihati anna lahum ajran hasanan', 1, NOW(), NOW()),
(23, 3, 'مَّـٰكِثِينَ فِيهِ أَبَدٗا', 'তারা তাতে চিরকাল অবস্থান করবে।', 'Makitheena feehi abadan', 1, NOW(), NOW()),
(23, 4, 'وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗا', 'এবং তাদেরকে ভয় প্রদর্শন করার জন্যে যারা বলে যে, আল্লাহর সন্তান রয়েছে।', 'Wayunthira allatheena qaloo ittakhatha Allahu waladan', 1, NOW(), NOW()),
(23, 5, 'مَّا لَهُم بِهِۦ مِنۡ عِلۡمٖ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبٗا', 'এ সম্পর্কে তাদের কোন জ্ঞান নেই এবং তাদের পিতৃপুরুষদেরও নেই। কত কঠিন তাদের মুখের কথা। তারা যা বলে তা তো সবই মিথ্যা।', 'Ma lahum bihi min AAilmin wala liabaihim kaburat kalimatan takhruju min afwahihim in yaqooloona illa kathiban', 1, NOW(), NOW()),
(23, 6, 'فَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا', 'যদি তারা এই বিষয়বস্তুর প্রতি বিশ্বাস স্থাপন না করে, তবে তাদের পশ্চাতে সম্ভবতঃ আপনি পরিতাপ করতে করতে নিজের প্রাণ নিপাত করবেন।', 'FalaAAallaka bakhiAAun nafsaka AAala atharihim in lam yuminoo bihatha alhadeethi asafan', 1, NOW(), NOW()),
(23, 7, 'إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا', 'আমি পৃথিবীস্থ সব কিছুকে পৃথিবীর জন্যে শোভা করেছি, যাতে লোকদের পরীক্ষা করি যে, তাদের মধ্যে কে ভাল কাজ করে।', 'Inna jaAAalna ma AAala alardi zeenatan laha linabluwahum ayyuhum ahsanu AAamalan', 1, NOW(), NOW()),
(23, 8, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيۡهَا صَعِيدٗا جُرُزًا', 'এবং তার উপর যাকিছু রয়েছে, অবশ্যই তা আমি উদ্ভিদশূন্য মাটিতে পরিণত করে দেব।', 'Wainna lajaAAiloona ma AAalayha saAAeedan juruzan', 1, NOW(), NOW()),
(23, 9, 'أَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا', 'আপনি কি ধারণা করেন যে, গুহা ও গর্তের অধিবাসীরা আমার নিদর্শনাবলীর মধ্যে বিস্ময়কর ছিল', 'Am hasibta anna ashaba alkahfi waalrraqeemi kanoo min ayatina AAajaban', 1, NOW(), NOW()),
(23, 10, 'إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا', 'যখন যুবকরা পাহাড়ের গুহায় আশ্রয়গ্রহণ করে তখন দোআ করেঃ হে আমাদের পালনকর্তা, আমাদেরকে নিজের কাছ থেকে রহমত দান করুন এবং আমাদের জন্যে আমাদের কাজ সঠিকভাবে পূর্ণ করুন।', 'Ith awa alfityatu ila alkahfi faqaloo rabbana atina min ladunka rahmatan wahayyi lana min amrina rashadan', 1, NOW(), NOW()),
(23, 11, 'فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي ٱلۡكَهۡفِ سِنِينَ عَدَدٗا', 'তখন আমি কয়েক বছরের জন্যে গুহায় তাদের কানের উপর নিদ্রার পর্দা ফেলে দেই।', 'Fadarabna AAala athanihim fee alkahfi sineena AAadadan', 1, NOW(), NOW()),
(23, 12, 'ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا', 'অতঃপর আমি তাদেরকে পুনরত্থিত করি, একথা জানার জন্যে যে, দুই দলের মধ্যে কোন দল তাদের অবস্থানকাল সম্পর্কে অধিক নির্ণয় করতে পারে।', 'Thumma baAAathnahum linaAAlama ayyu alhizbayni ahsa lima labithoo amadan', 1, NOW(), NOW()),
(23, 13, 'نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى', 'আপনার কাছে তাদের ইতিবৃত্তান্ত সঠিকভাবে বর্ণনা করছি। তারা ছিল কয়েকজন যুবক। তারা তাদের পালনকর্তার প্রতি বিশ্বাস স্থাপন করেছিল এবং আমি তাদের সৎপথে চলার শক্তি বাড়িয়ে দিয়েছিলাম।', 'Nahnu naqussu AAalayka nabaahum bialhaqqi innahum fityatun amanoo birabbihim wazidnahum hudan', 1, NOW(), NOW()),
(23, 14, 'وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ لَّقَدۡ قُلۡنَآ إِذٗا شَطَطًا', 'আমি তাদের মন দৃঢ় করেছিলাম, যখন তারা উঠে দাঁড়িয়েছিল। অতঃপর তারা বললঃ আমাদের পালনকর্তা আসমান ও যমীনের পালনকর্তা আমরা কখনও তার পরিবর্তে অন্য কোন উপাস্যকে আহবান করব না। যদি করি, তবে তা অত্যন্ত গর্হিত কাজ হবে।', 'Warabatna AAala quloobihim ith qamoo faqaloo rabbuna rabbu alssamawati waalardi lan nadAAuwa min doonihi ilahan laqad qulna ithan shatatan', 1, NOW(), NOW()),
(23, 15, 'هَـٰٓؤُلَآءِ قَوۡمُنَا ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ لَّوۡلَا يَأۡتُونَ عَلَيۡهِم بِسُلۡطَٰنِۭ بَيِّنٖۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا', 'এরা আমাদেরই স্ব-জাতি, এরা তাঁর পরিবর্তে অনেক উপাস্য গ্রহণ করেছে। তারা এদের সম্পর্কে প্রকাশ্য প্রমাণ উপস্থিত করে না কেন? যে আল্লাহ সম্পর্কে মিথ্যা উদ্ভাবন করে, তার চাইতে অধিক গোনাহগার আর কে', 'Haolai qawmuna ittakhathoo min doonihi alihatan lawla yatoona AAalayhim bisultanin bayyinin faman athlamu mimmani iftara AAala Allahi kathiban', 1, NOW(), NOW()),
(23, 16, 'وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقٗا', 'তোমরা যখন তাদের থেকে পৃথক হলে এবং তারা আল্লাহর পরিবর্তে যাদের এবাদত করে তাদের থেকে, তখন তোমরা গুহায় আশ্রয়গ্রহণ কর। তোমাদের পালনকর্তা তোমাদের জন্যে দয়া বিস্তার করবেন এবং তিনি তোমাদের জন্য তোমাদের কাজ কর্মকে ফলপ্রসু করার ব্যবস্থা করবেন।', 'Waithi iAAtazaltumoohum wama yaAAbudoona illa Allaha fawoo ila alkahfi yanshur lakum rabbukum min rahmatihi wayuhayyi lakum min amrikum mirfaqan', 1, NOW(), NOW()),
(23, 17, '۞وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيّٗا مُّرۡشِدٗا', 'তুমি সূর্যকে দেখবে, যখন উদিত হয়, তাদের গুহা থেকে পাশ কেটে ডান দিকে চলে যায় এবং যখন অস্ত যায়, তাদের থেকে পাশ কেটে বামদিকে চলে যায়, অথচ তারা গুহার প্রশস্ত চত্বরে অবস্থিত। এটা আল্লাহর নিদর্শনাবলীর অন্যতম। আল্লাহ যাকে সৎপথে চালান, সেই সৎপথ প্রাপ্ত এবং তিনি যাকে পথভ্রষ্ট করেন, আপনি কখনও তার জন্যে পথপ্রদর্শনকারী ও সাহায্যকারী পাবেন না।', 'Watara alshshamsa itha talaAAat tazawaru AAan kahfihim thata alyameeni waitha gharabat taqriduhum thata alshshimali wahum fee fajwatin minhu thalika min ayati Allahi man yahdi Allahu fahuwa almuhtadi waman yudlil falan tajida lahu waliyyan murshidan', 1, NOW(), NOW()),
(23, 18, 'وَتَحۡسَبُهُمۡ أَيۡقَاظٗا وَهُمۡ رُقُودٞۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَارٗا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبٗا', 'তুমি মনে করবে তারা জাগ্রত, অথচ তারা নিদ্রিত। আমি তাদেরকে পার্শ্ব পরিবর্তন করাই ডান দিকে ও বাম দিকে। তাদের কুকুর ছিল সামনের পা দুটি গুহাদ্বারে প্রসারিত করে। যদি তুমি উঁকি দিয়ে তাদেরকে দেখতে, তবে পেছন ফিরে পলায়ন করতে এবং তাদের ভয়ে আতংক গ্রস্ত হয়ে পড়তে।', 'Watahsabuhum ayqathan wahum ruqoodun wanuqallibuhum thata alyameeni wathata alshshimali wakalbuhum basitun thiraAAayhi bialwaseedi lawi ittalaAAta AAalayhim lawallayta minhum firaran walamulita minhum ruAAban', 1, NOW(), NOW()),
(23, 19, 'وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا', 'আমি এমনি ভাবে তাদেরকে জাগ্রত করলাম, যাতে তারা পরস্পর জিজ্ঞাসাবাদ করে। তাদের একজন বললঃ তোমরা কতকাল অবস্থান করেছ? তাদের কেউ বললঃ একদিন অথবা একদিনের কিছু অংশ অবস্থান করছি। কেউ কেউ বললঃ তোমাদের পালনকর্তাই ভাল জানেন তোমরা কতকাল অবস্থান করেছ। এখন তোমাদের একজনকে তোমাদের এই মুদ্রাসহ শহরে প্রেরণ কর; সে যেন দেখে কোন খাদ্য পবিত্র। অতঃপর তা থেকে যেন কিছু খাদ্য নিয়ে আসে তোমাদের জন্য; সে যেন নম্রতা সহকারে যায় ও কিছুতেই যেন তোমাদের খবর কাউকে না জানায়।', 'Wakathalika baAAathnahum liyatasaaloo baynahum qala qailun minhum kam labithtum qaloo labithna yawman aw baAAda yawmin qaloo rabbukum aAAlamu bima labithtum faibAAathoo ahadakum biwariqikum hathihi ila almadeenati falyanthur ayyuha azka taAAaman falyatikum birizqin minhu walyatalattaf wala yushAAiranna bikum ahadan', 1, NOW(), NOW()),
(23, 20, 'إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا', 'তারা যদি তোমাদের খবর জানতে পারে, তবে পাথর মেরে তোমাদেরকে হত্যা করবে, অথবা তোমাদেরকে তাদের ধর্মে ফিরিয়ে নেবে। তাহলে তোমরা কখনই সাফল্য লাভ করবে না।', 'Innahum in yathharoo AAalaykum yarjumookum aw yuAAeedookum fee millatihim walan tuflihoo ithan abadan', 1, NOW(), NOW()),
(23, 21, 'وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا', 'এমনিভাবে আমি তাদের খবর প্রকাশ করে দিলাম, যাতে তারা জ্ঞাত হয় যে, আল্লাহর ওয়াদা সত্য এবং কেয়ামতে কোন সন্দেহ নেই। যখন তারা নিজেদের কর্তব্য বিষয়ে পরস্পর বিতর্ক করছিল, তখন তারা বললঃ তাদের উপর সৌধ নির্মাণ কর। তাদের পালনকর্তা তাদের বিষয়ে ভাল জানেন। তাদের কর্তব্য বিষয়ে যাদের মত প্রবল হল, তারা বললঃ আমরা অবশ্যই তাদের স্থানে মসজিদ নির্মান করব।', 'Wakathalika aAAtharna AAalayhim liyaAAlamoo anna waAAda Allahi haqqun waanna alsaAAata la rayba feeha ith yatanazaAAoona baynahum amrahum faqaloo ibnoo AAalayhim bunyanan rabbuhum aAAlamu bihim qala allatheena ghalaboo AAala amrihim lanattakhithanna AAalayhim masjidan', 1, NOW(), NOW()),
(23, 22, 'سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا', 'অজ্ঞাত বিষয়ে অনুমানের উপর ভিত্তি করে এখন তারা বলবেঃ তারা ছিল তিন জন; তাদের চতুর্থটি তাদের কুকুর। একথাও বলবে; তারা পাঁচ জন। তাদের ছষ্ঠটি ছিল তাদের কুকুর। আরও বলবেঃ তারা ছিল সাত জন। তাদের অষ্টমটি ছিল তাদের কুকুর। বলুনঃ আমার পালনকর্তা তাদের সংখ্যা ভাল জানেন। তাদের খবর অল্প লোকই জানে। সাধারণ আলোচনা ছাড়া আপনি তাদের সম্পর্কে বিতর্ক করবেন না এবং তাদের অবস্থা সম্পর্কে তাদের কাউকে জিজ্ঞাসাবাদ ও করবেন না।', 'Sayaqooloona thalathatun rabiAAuhum kalbuhum wayaqooloona khamsatun sadisuhum kalbuhum rajman bialghaybi wayaqooloona sabAAatun wathaminuhum kalbuhum qul rabbee aAAlamu biAAiddatihim ma yaAAlamuhum illa qaleelun fala tumari feehim illa miraan thahiran wala tastafti feehim minhum ahadan', 1, NOW(), NOW()),
(23, 23, 'وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا', 'আপনি কোন কাজের বিষয়ে বলবেন না যে, সেটি আমি আগামী কাল করব।', 'Wala taqoolanna lishayin innee faAAilun thalika ghadan', 1, NOW(), NOW()),
(23, 24, 'إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا', '‘আল্লাহ ইচ্ছা করলে’ বলা ব্যতিরেকে। যখন ভুলে যান, তখন আপনার পালনকর্তাকে স্মরণ করুন এবং বলুনঃ আশা করি আমার পালনকর্তা আমাকে এর চাইতেও নিকটতম সত্যের পথ নির্দেশ করবেন।', 'Illa an yashaa Allahu waothkur rabbaka itha naseeta waqul AAasa an yahdiyani rabbee liaqraba min hatha rashadan', 1, NOW(), NOW()),
(23, 25, 'وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةٖ سِنِينَ وَٱزۡدَادُواْ تِسۡعٗا', 'তাদের উপর তাদের গুহায় তিনশ বছর, অতিরিক্ত আরও নয় বছর অতিবাহিত হয়েছে।', 'Walabithoo fee kahfihim thalatha miatin sineena waizdadoo tisAAan', 1, NOW(), NOW()),
(23, 26, 'قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا', 'বলুনঃ তারা কতকাল অবস্থান করেছে, তা আল্লাহই ভাল জানেন। নভোমন্ডল ও ভুমন্ডলের অদৃশ্য বিষয়ের জ্ঞান তাঁরই কাছে রয়েছে। তিনি কত চমৎকার দেখেন ও শোনেন। তিনি ব্যতীত তাদের জন্য কোন সাহায্যকারী নেই। তিনি কাউকে নিজ কর্তৃত্বে শরীক করেন না।', 'Quli Allahu aAAlamu bima labithoo lahu ghaybu alssamawati waalardi absir bihi waasmiAA ma lahum min doonihi min waliyyin wala yushriku fee hukmihi ahadan', 1, NOW(), NOW()),
(23, 27, 'وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدٗا', 'আপনার প্রতি আপনার পালনকর্তার যে, কিতাব প্রত্যাদিষ্ট করা হয়েছে, তা পাঠ করুন। তাঁর বাক্য পরিবর্তন করার কেউ নাই। তাঁকে ব্যতীত আপনি কখনই কোন আশ্রয় স্থল পাবেন না।', 'Waotlu ma oohiya ilayka min kitabi rabbika la mubaddila likalimatihi walan tajida min doonihi multahadan', 1, NOW(), NOW()),
(23, 28, 'وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا', 'আপনি নিজেকে তাদের সংসর্গে আবদ্ধ রাখুন যারা সকাল ও সন্ধ্যায় তাদের পালনকর্তাকে তাঁর সন্তুষ্টি অর্জনের উদ্দেশ্যে আহবান করে এবং আপনি পার্থিব জীবনের সৌন্দর্য কামনা করে তাদের থেকে নিজের দৃষ্টি ফিরিয়ে নেবেন না। যার মনকে আমার স্মরণ থেকে গাফেল করে দিয়েছি, যে, নিজের প্রবৃত্তির অনুসরণ করে এবং যার কার্য কলাপ হচ্ছে সীমা অতিক্রম করা, আপনি তার অনুগত্য করবেন না।', 'Waisbir nafsaka maAAa allatheena yadAAoona rabbahum bialghadati waalAAashiyyi yureedoona wajhahu wala taAAdu AAaynaka AAanhum tureedu zeenata alhayati alddunya wala tutiAA man aghfalna qalbahu AAan thikrina waittabaAAa hawahu wakana amruhu furutan', 1, NOW(), NOW()),
(23, 29, 'وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّـٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا', 'বলুনঃ সত্য তোমাদের পালনকর্তার পক্ষ থেকে আগত। অতএব, যার ইচ্ছা, বিশ্বাস স্থাপন করুক এবং যার ইচ্ছা অমান্য করুক। আমি জালেমদের জন্যে অগ্নি প্রস্তুত করে রেখেছি, যার বেষ্টনী তাদের কে পরিবেষ্টন করে থাকবে। যদি তারা পানীয় প্রার্থনা করে, তবে পুঁজের ন্যায় পানীয় দেয়া হবে যা তাদের মুখমন্ডল দগ্ধ করবে। কত নিকৃষ্ট পানীয় এবং খুবই মন্দ আশ্রয়।', 'Waquli alhaqqu min rabbikum faman shaa falyumin waman shaa falyakfur inna aAAtadna lilththalimeena naran ahata bihim suradiquha wain yastagheethoo yughathoo bimain kaalmuhli yashwee alwujooha bisa alshsharabu wasaat murtafaqan', 1, NOW(), NOW()),
(23, 30, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا', 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে আমি সৎকর্মশীলদের পুরস্কার নষ্ট করি না।', 'Inna allatheena amanoo waAAamiloo alssalihati inna la nudeeAAu ajra man ahsana AAamalan', 1, NOW(), NOW()),
(23, 31, 'أُوْلَـٰٓئِكَ لَهُمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَيَلۡبَسُونَ ثِيَابًا خُضۡرٗا مِّن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقٗا', 'তাদেরই জন্যে আছে বসবাসের জান্নাত। তাদের পাদদেশে প্রবাহিত হয় নহরসমূহ। তাদের তথায় স্বর্ণ-কংকনে অলংকৃত করা হবে এবং তারা পাতলা ও মোটা রেশমের সবুজ কাপর পরিধান করবে এমতাবস্থায় যে, তারা সিংহাসনে সমাসীন হবে। চমৎকার প্রতিদান এবং কত উত্তম আশ্রয়।', 'Olaika lahum jannatu AAadnin tajree min tahtihimu alanharu yuhallawna feeha min asawira min thahabin wayalbasoona thiyaban khudran min sundusin waistabraqin muttakieena feeha AAala alaraiki niAAma alththawabu wahasunat murtafaqan', 1, NOW(), NOW()),
(23, 32, '۞وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا', 'আপনি তাদের কাছে দু ব্যক্তির উদাহরণ বর্ণনা করুন। আমি তাদের একজনকে দুটি আঙ্গুরের বাগান দিয়েছি এবং এ দু’টিকে খর্জুর বৃক্ষ দ্বারা পরিবেষ্টিত করেছি এবং দু এর মাঝখানে করেছি শস্যক্ষেত্র।', 'Waidrib lahum mathalan rajulayni jaAAalna liahadihima jannatayni min aAAnabin wahafafnahuma binakhlin wajaAAalna baynahuma zarAAan', 1, NOW(), NOW()),
(23, 33, 'كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا', 'উভয় বাগানই ফলদান করে এবং তা থেকে কিছুই হ্রাস করত না এবং উভয়ের ফাঁকে ফাঁকে আমি নহর প্রবাহিত করেছি।', 'Kilta aljannatayni atat okulaha walam tathlim minhu shayan wafajjarna khilalahuma naharan', 1, NOW(), NOW()),
(23, 34, 'وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا', 'সে ফল পেল। অতঃপর কথা প্রসঙ্গে সঙ্গীকে বললঃ আমার ধন-সম্পদ তোমার চাইতে বেশী এবং জনবলে আমি অধিক শক্তিশালী।', 'Wakana lahu thamarun faqala lisahibihi wahuwa yuhawiruhu ana aktharu minka malan waaAAazzu nafaran', 1, NOW(), NOW()),
(23, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا', 'নিজের প্রতি জুলুম করে সে তার বাগানে প্রবেশ করল। সে বললঃ আমার মনে হয় না যে, এ বাগান কখনও ধ্বংস হয়ে যাবে।', 'Wadakhala jannatahu wahuwa thalimun linafsihi qala ma athunnu an tabeeda hathihi abadan', 1, NOW(), NOW()),
(23, 36, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا', 'এবং আমি মনে করি না যে, কেয়ামত অনুষ্ঠিত হবে। যদি কখনও আমার পালনকর্তার কাছে আমাকে পৌঁছে দেয়া হয়, তবে সেখানে এর চাইতে উৎকৃষ্ট পাব।', 'Wama athunnu alssaAAata qaimatan walain rudidtu ila rabbee laajidanna khayran minha munqalaban', 1, NOW(), NOW()),
(23, 37, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرۡتَ بِٱلَّذِي خَلَقَكَ مِن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ سَوَّىٰكَ رَجُلٗا', 'তার সঙ্গী তাকে কথা প্রসঙ্গে বললঃ তুমি তাঁকে অস্বীকার করছ, যিনি তোমাকে সৃষ্টি করেছেন মাটি থেকে, অতঃপর বীর্য থেকে, অতঃপর র্পূনাঙ্গ করেছেন তোমাকে মানবাকৃতিতে', 'Qala lahu sahibuhu wahuwa yuhawiruhu akafarta biallathee khalaqaka min turabin thumma min nutfatin thumma sawwaka rajulan', 1, NOW(), NOW()),
(23, 38, 'لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّي وَلَآ أُشۡرِكُ بِرَبِّيٓ أَحَدٗا', 'কিন্তু আমি তো একথাই বলি, আল্লাহই আমার পালনকর্তা এবং আমি কাউকে আমার পালনকর্তার শরীক মানি না।', 'Lakinna huwa Allahu rabbee wala oshriku birabbee ahadan', 1, NOW(), NOW()),
(23, 39, 'وَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا', 'যদি তুমি আমাকে ধনে ও সন্তানে তোমার চাইতে কম দেখ, তবে যখন তুমি তোমার বাগানে প্রবেশ করলে, তখন একথা কেন বললে না; আল্লাহ যা চান, তাই হয়। আল্লাহর দেয়া ব্যতীত কোন শক্তি নেই।', 'Walawla ith dakhalta jannataka qulta ma shaa Allahu la quwwata illa biAllahi in tarani ana aqalla minka malan wawaladan', 1, NOW(), NOW()),
(23, 40, 'فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَانٗا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدٗا زَلَقًا', 'আশাকরি আমার পালকর্তা আমাকে তোমার বাগান অপেক্ষা উৎকৃষ্টতর কিছু দেবেন এবং তার (তোমার বাগানের) উপর আসমান থেকে আগুন প্রেরণ করবেন। অতঃপর সকাল বেলায় তা পরিষ্কার ময়দান হয়ে যাবে।', 'FaAAasa rabbee an yutiyani khayran min jannatika wayursila AAalayha husbanan mina alssamai fatusbiha saAAeedan zalaqan', 1, NOW(), NOW()),
(23, 41, 'أَوۡ يُصۡبِحَ مَآؤُهَا غَوۡرٗا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبٗا', 'অথবা সকালে তার পানি শুকিয়ে যাবে। অতঃপর তুমি তা তালাশ করে আনতে পারবে না।', 'Aw yusbiha maoha ghawran falan tastateeAAa lahu talaban', 1, NOW(), NOW()),
(23, 42, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا', 'অতঃপর তার সব ফল ধ্বংস হয়ে গেল এবং সে তাতে যা ব্যয় করেছিল, তার জন্য সকালে হাত কচলিয়ে আক্ষেপ করতে লাগল। বাগনটি কাঠসহ পুড়ে গিয়েছিল। সে বলতে লাগলঃ হায়, আমি যদি কাউকে আমার পালনকর্তার সাথে শরীক না করতাম।', 'Waoheeta bithamarihi faasbaha yuqallibu kaffayhi AAala ma anfaqa feeha wahiya khawiyatun AAala AAurooshiha wayaqoolu ya laytanee lam oshrik birabbee ahadan', 1, NOW(), NOW()),
(23, 43, 'وَلَمۡ تَكُن لَّهُۥ فِئَةٞ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', 'আল্লাহ ব্যতীত তাকে সাহায্য করার কোন লোক হল না এবং সে নিজেও প্রতিকার করতে পারল না।', 'Walam takun lahu fiatun yansuroonahu min dooni Allahi wama kana muntasiran', 1, NOW(), NOW()),
(23, 44, 'هُنَالِكَ ٱلۡوَلَٰيَةُ لِلَّهِ ٱلۡحَقِّۚ هُوَ خَيۡرٞ ثَوَابٗا وَخَيۡرٌ عُقۡبٗا', 'এরূপ ক্ষেত্রে সব অধিকার সত্য আল্লাহর। তারই পুরস্কার উত্তম এবং তারই প্রদত্ত প্রতিদান শ্রেষ্ঠ।', 'Hunalika alwalayatu lillahi alhaqqi huwa khayrun thawaban wakhayrun AAuqban', 1, NOW(), NOW()),
(23, 45, 'وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقۡتَدِرًا', 'তাদের কাছে পার্থিব জীবনের উপমা বর্ণনা করুন। তা পানির ন্যায়, যা আমি আকাশ থেকে নাযিল করি। অতঃপর এর সংমিশ্রণে শ্যামল সবুজ ভূমিজ লতা-পাতা নির্গত হয়; অতঃপর তা এমন শুস্ক চুর্ণ-বিচুর্ণ হয় যে, বাতাসে উড়ে যায়। আল্লাহ এ সবকিছুর উপর শক্তিমান।', 'Waidrib lahum mathala alhayati alddunya kamain anzalnahu mina alssamai faikhtalata bihi nabatu alardi faasbaha hasheeman tathroohu alrriyahu wakana Allahu AAala kulli shayin muqtadiran', 1, NOW(), NOW()),
(23, 46, 'ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا', 'ধনৈশ্বর্য ও সন্তান-সন্ততি পার্থিব জীবনের সৌন্দর্য এবং স্থায়ী সৎকর্মসমূহ আপনার পালনকর্তার কাছে প্রতিদান প্রাপ্তি ও আশা লাভের জন্যে উত্তম।', 'Almalu waalbanoona zeenatu alhayati alddunya waalbaqiyatu alssalihatu khayrun AAinda rabbika thawaban wakhayrun amalan', 1, NOW(), NOW()),
(23, 47, 'وَيَوۡمَ نُسَيِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ وَحَشَرۡنَٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدٗا', 'যেদিন আমি পর্বতসমূহকে পরিচালনা করব এবং আপনি পৃথিবীকে দেখবেন একটি উম্মুক্ত প্রান্তর এবং আমি মানুষকে একত্রিত করব অতঃপর তাদের কাউকে ছাড়ব না।', 'Wayawma nusayyiru aljibala watara alarda barizatan wahasharnahum falam nughadir minhum ahadan', 1, NOW(), NOW()),
(23, 48, 'وَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّٗا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدٗا', 'তারা আপনার পালনকর্তার সামনে পেশ হবে সারিবদ্ধ ভাবে এবং বলা হবেঃ তোমরা আমার কাছে এসে গেছ; যেমন তোমাদেরকে প্রথম বার সৃষ্টি করেছিলাম। না, তোমরা তো বলতে যে, আমি তোমাদের জন্যে কোন প্রতিশ্রুত সময় নির্দিষ্ট করব না।', 'WaAAuridoo AAala rabbika saffan laqad jitumoona kama khalaqnakum awwala marratin bal zaAAamtum allan najAAala lakum mawAAidan', 1, NOW(), NOW()),
(23, 49, 'وَوُضِعَ ٱلۡكِتَٰبُ فَتَرَى ٱلۡمُجۡرِمِينَ مُشۡفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا', 'আর আমলনামা সামনে রাখা হবে। তাতে যা আছে; তার কারণে আপনি অপরাধীদেরকে ভীত-সন্ত্রস্ত দেখবেন। তারা বলবেঃ হায় আফসোস, এ কেমন আমলনামা। এ যে ছোট বড় কোন কিছুই বাদ দেয়নি-সবই এতে রয়েছে। তারা তাদের কৃতকর্মকে সামনে উপস্থিত পাবে। আপনার পালনকর্তা কারও প্রতি জুলুম করবেন না।', 'WawudiAAa alkitabu fatara almujrimeena mushfiqeena mimma feehi wayaqooloona ya waylatana ma lihatha alkitabi la yughadiru sagheeratan wala kabeeratan illa ahsaha wawajadoo ma AAamiloo hadiran wala yathlimu rabbuka ahadan', 1, NOW(), NOW()),
(23, 50, 'وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّـٰلِمِينَ بَدَلٗا', 'যখন আমি ফেরেশতাদেরকে বললামঃ আদমকে সেজদা কর, তখন সবাই সেজদা করল ইবলীস ব্যতীত। সে ছিল জিনদের একজন। সে তার পালনকর্তার আদেশ অমান্য করল। অতএব তোমরা কি আমার পরিবর্তে তাকে এবং তার বংশধরকে বন্ধুরূপে গ্রহণ করছ? অথচ তারা তোমাদের শত্রু। এটা জালেমদের জন্যে খুবই নিকৃষ্ট বদল।', 'Waith qulna lilmalaikati osjudoo liadama fasajadoo illa ibleesa kana mina aljinni fafasaqa AAan amri rabbihi afatattakhithoonahu wathurriyyatahu awliyaa min doonee wahum lakum AAaduwwun bisa lilththalimeena badalan', 1, NOW(), NOW()),
(23, 51, '۞مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدٗا', 'নভোমন্ডল ও ভুমন্ডলের সৃজনকালে আমি তাদেরকে সাক্ষ্য রাখিনি এবং তাদের নিজেদের সৃজনকালেও না। এবং আমি এমনও নই যে, বিভ্রান্ত কারীদেরকে সাহায্যকারীরূপে গ্রহণ করবো।', 'Ma ashhadtuhum khalqa alssamawati waalardi wala khalqa anfusihim wama kuntu muttakhitha almudilleena AAadudan', 1, NOW(), NOW()),
(23, 52, 'وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ٱلَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَجَعَلۡنَا بَيۡنَهُم مَّوۡبِقٗا', 'যেদিন তিনি বলবেনঃ তোমরা যাদেরকে আমার শরীক মনে করতে তাদেরকে ডাক। তারা তখন তাদেরকে ডাকবে, কিন্তু তারা এ আহবানে সাড়া দেবে না। আমি তাদের মধ্যস্থলে রেখে দেব একটি মৃত্যু গহবর।', 'Wayawma yaqoolu nadoo shurakaiya allatheena zaAAamtum fadaAAawhum falam yastajeeboo lahum wajaAAalna baynahum mawbiqan', 1, NOW(), NOW()),
(23, 53, 'وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ يَجِدُواْ عَنۡهَا مَصۡرِفٗا', 'অপরাধীরা আগুন দেখে বোঝে নেবে যে, তাদেরকে তাতে পতিত হতে হবে এবং তারা তা থেকে রাস্তা পরিবর্তন করতে পারবে না।', 'Waraa almujrimoona alnnara fathannoo annahum muwaqiAAooha walam yajidoo AAanha masrifan', 1, NOW(), NOW()),
(23, 54, 'وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا', 'নিশ্চয় আমি এ কোরআনে মানুষকে নানাভাবে বিভিন্ন উপমার দ্বারা আমার বাণী বুঝিয়েছি। মানুষ সব বস্তু থেকে অধিক তর্কপ্রিয়।', 'Walaqad sarrafna fee hatha alqurani lilnnasi min kulli mathalin wakana alinsanu akthara shayin jadalan', 1, NOW(), NOW()),
(23, 55, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰ وَيَسۡتَغۡفِرُواْ رَبَّهُمۡ إِلَّآ أَن تَأۡتِيَهُمۡ سُنَّةُ ٱلۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ قُبُلٗا', 'হেদায়েত আসার পর এ প্রতীক্ষাই শুধু মানুষকে বিশ্বাস স্থাপন করতে এবং তাদের পালনকর্তার কাছে ক্ষমা প্রার্থনা করতে বিরত রাখে যে, কখন আসবে তাদের কাছে পূর্ববর্তীদের রীতিনীতি অথবা কখন আসবে তাদের কাছেআযাব সামনাসামনি।', 'Wama manaAAa alnnasa an yuminoo ith jaahumu alhuda wayastaghfiroo rabbahum illa an tatiyahum sunnatu alawwaleena aw yatiyahumu alAAathabu qubulan', 1, NOW(), NOW()),
(23, 56, 'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا', 'আমি রাসূলগনকে সুসংবাদ দাতা ও ভয় প্রদর্শন কারীরূপেই প্রেরণ করি এবং কাফেররাই মিথ্যা অবলম্বনে বিতর্ক করে, তা দ্বারা সত্যকে ব্যর্থ করে দেয়ার উদ্দেশে এবং তারা আমার নিদর্শনাবলীও যদ্বারা তাদেরকে ভয় প্রদর্শন করা হয়, সেগুলোকে ঠাট্টারূপে গ্রহণ করেছে।', 'Wama nursilu almursaleena illa mubashshireena wamunthireena wayujadilu allatheena kafaroo bialbatili liyudhidoo bihi alhaqqa waittakhathoo ayatee wama onthiroo huzuwan', 1, NOW(), NOW()),
(23, 57, 'وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا', 'তার চাইতে অধিক জালেম কে, যাকে তার পালনকর্তার কালাম দ্বারা বোঝানো হয়, অতঃপর সে তা থেকে মুখ ফিরিয়ে নেয় এবং তার পূর্ববর্তী কৃতকর্মসমূহ ভুলে যায়? আমি তাদের অন্তরের উপর পর্দা রেখে দিয়েছি, যেন তা না বোঝে এবং তাদের কানে রয়েছে বধিরতার বোঝা। যদি আপনি তাদেরকে সৎপথের প্রতি দাওয়াত দেন, তবে কখনই তারা সৎপথে আসবে না।', 'Waman athlamu mimman thukkira biayati rabbihi faaAArada AAanha wanasiya ma qaddamat yadahu inna jaAAalna AAala quloobihim akinnatan an yafqahoohu wafee athanihim waqran wain tadAAuhum ila alhuda falan yahtadoo ithan abadan', 1, NOW(), NOW()),
(23, 58, 'وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدٞ لَّن يَجِدُواْ مِن دُونِهِۦ مَوۡئِلٗا', 'আপনার পালনকর্তা ক্ষমাশীল, দয়ালু, যদি তিনি তাদেরকে তাদের কৃতকর্মের জন্যে পাকড়াও করেন তবে তাদের শাস্তি ত্বরাম্বিত করতেন, কিন্তু তাদের জন্য রয়েছে একটি প্রতিশ্রুত সময়, যা থেকে তারা সরে যাওয়ার জায়গা পাবে না।', 'Warabbuka alghafooru thoo alrrahmati law yuakhithuhum bima kasaboo laAAajjala lahumu alAAathaba bal lahum mawAAidun lan yajidoo min doonihi mawilan', 1, NOW(), NOW()),
(23, 59, 'وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدٗا', 'এসব জনপদও তাদেরকে আমি ধংস করে দিয়েছি, যখন তারা জালেম হয়ে গিয়েছিল এবং আমি তাদের ধ্বংসের জন্যে একটি প্রতিশ্রুত সময় নির্দিষ্ট করেছিলাম।', 'Watilka alqura ahlaknahum lamma thalamoo wajaAAalna limahlikihim mawAAidan', 1, NOW(), NOW()),
(23, 60, 'وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا', 'যখন মূসা তাঁর যুবক (সঙ্গী) কে বললেনঃ দুই সমুদ্রের সঙ্গমস্থলে না পৌছা পর্যন্ত আমি আসব না অথবা আমি যুগ যুগ ধরে চলতে থাকব।', 'Waith qala moosa lifatahu la abrahu hatta ablugha majmaAAa albahrayni aw amdiya huquban', 1, NOW(), NOW()),
(23, 61, 'فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا', 'অতঃপর যখন তাঁরা দুই সুমুদ্রের সঙ্গমস্থলে পৌছালেন, তখন তাঁরা নিজেদের মাছের কথা ভুলে গেলেন। অতঃপর মাছটি সমুদ্রে সুড়ঙ্গ পথ সৃষ্টি করে নেমে গেল।', 'Falamma balagha majmaAAa baynihima nasiya hootahuma faittakhatha sabeelahu fee albahri saraban', 1, NOW(), NOW()),
(23, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا', 'যখন তাঁরা সে স্থানটি অতিক্রম করে গেলেন, মূসা সঙ্গী কে বললেনঃ আমাদের নাশতা আন। আমরা এই সফরে পরিশ্রান্ত হয়ে পড়েছি।', 'Falamma jawaza qala lifatahu atina ghadaana laqad laqeena min safarina hatha nasaban', 1, NOW(), NOW()),
(23, 63, 'قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا', 'সে বললঃ আপনি কি লক্ষ্য করেছেন, আমরা যখন প্রস্তর খন্ডে আশ্রয় নিয়েছিলাম, তখন আমি মাছের কথা ভুলে গিয়েছিলাম। শয়তানই আমাকে একথা স্মরণ রাখতে ভুলিয়ে দিয়েছিল। মাছটি আশ্চর্য জনক ভাবে সমুদ্রে নিজের পথ করে নিয়েছে।', 'Qala araayta ith awayna ila alssakhrati fainnee naseetu alhoota wama ansaneehu illa alshshaytanu an athkurahu waittakhatha sabeelahu fee albahri AAajaban', 1, NOW(), NOW()),
(23, 64, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا', 'মূসা বললেনঃ আমরা তো এ স্থানটিই খুঁজছিলাম। অতঃপর তাঁরা নিজেদের চিহ্ন ধরে ফিরে চললেন।', 'Qala thalika ma kunna nabghi fairtadda AAala atharihima qasasan', 1, NOW(), NOW()),
(23, 65, 'فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا', 'অতঃপর তাঁরা আমার বান্দাদের মধ্যে এমন একজনের সাক্ষাত পেলেন, যাকে আমি আমার পক্ষ থেকে রহমত দান করেছিলাম ও আমার পক্ষ থেকে দিয়েছিলাম এক বিশেষ জ্ঞান।', 'Fawajada AAabdan min AAibadina ataynahu rahmatan min AAindina waAAallamnahu min ladunna AAilman', 1, NOW(), NOW()),
(23, 66, 'قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا', 'মূসা তাঁকে বললেনঃ আমি কি এ শর্তে আপনার অনুসরণ করতে পারি যে, সত্যপথের যে জ্ঞান আপনাকে শেখানো হয়েছে, তা থেকে আমাকে কিছু শিক্ষা দেবেন', 'Qala lahu moosa hal attabiAAuka AAala an tuAAallimani mimma AAullimta rushdan', 1, NOW(), NOW()),
(23, 67, 'قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا', 'তিনি বললেনঃ আপনি আমার সাথে কিছুতেই ধৈর্য্যধারণ করে থাকতে পারবেন না।', 'Qala innaka lan tastateeAAa maAAiya sabran', 1, NOW(), NOW()),
(23, 68, 'وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا', 'যে বিষয় বোঝা আপনার আয়ত্তাধীন নয়, তা দেখে আপনি ধৈর্য্যধারণ করবেন কেমন করে', 'Wakayfa tasbiru AAala ma lam tuhit bihi khubran', 1, NOW(), NOW()),
(23, 69, 'قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا', 'মূসা বললেনঃ আল্লাহ চাহেন তো আপনি আমাকে ধৈর্য্যশীল পাবেন এবং আমি আপনার কোন আদেশ অমান্য করব না।', 'Qala satajidunee in shaa Allahu sabiran wala aAAsee laka amran', 1, NOW(), NOW()),
(23, 70, 'قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا', 'তিনি বললেনঃ যদি আপনি আমার অনুসরণ করেনই তবে কোন বিষয়ে আমাকে প্রশ্ন করবেন না, যে পর্যন্ত না আমি নিজেই সে সম্পর্কে আপনাকে কিছু বলি।', 'Qala faini ittabaAAtanee fala tasalnee AAan shayin hatta ohditha laka minhu thikran', 1, NOW(), NOW()),
(23, 71, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرٗا', 'অতঃপর তারা চলতে লাগলঃ অবশেষে যখন তারা নৌকায় আরোহণ করল, তখন তিনি তাতে ছিদ্র করে দিলেন। মূসা বললেনঃ আপনি কি এর আরোহীদেরকে ডুবিয়ে দেয়ার জন্যে এতে ছিদ্র করে দিলেন? নিশ্চয়ই আপনি একটি গুরুতর মন্দ কাজ করলেন।', 'Faintalaqa hatta itha rakiba fee alssafeenati kharaqaha qala akharaqtaha litughriqa ahlaha laqad jita shayan imran', 1, NOW(), NOW()),
(23, 72, 'قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا', 'তিনি বললেনঃ আমি কি বলিনি যে, আপনি আমার সাথে কিছুতেই ধৈর্য্য ধরতে পারবেন না', 'Qala alam aqul innaka lan tastateeAAa maAAiya sabran', 1, NOW(), NOW()),
(23, 73, 'قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرٗا', 'মূসা বললেনঃ আমাকে আমার ভুলের জন্যে অপরাধী করবেন না এবং আমার কাজে আমার উপর কঠোরতা আরোপ করবেন না।', 'Qala la tuakhithnee bima naseetu wala turhiqnee min amree AAusran', 1, NOW(), NOW()),
(23, 74, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمٗا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسٗا زَكِيَّةَۢ بِغَيۡرِ نَفۡسٖ لَّقَدۡ جِئۡتَ شَيۡـٔٗا نُّكۡرٗا', 'অতঃপর তারা চলতে লাগল। অবশেষে যখন একটি বালকের সাক্ষাত পেলেন, তখন তিনি তাকে হত্যা করলেন। মূসা বললেন? আপনি কি একটি নিস্পাপ জীবন শেষ করে দিলেন প্রাণের বিনিময় ছাড়াই? নিশ্চয়ই আপনি তো এক গুরুতর অন্যায় কাজ করলেন।', 'Faintalaqa hatta itha laqiya ghulaman faqatalahu qala aqatalta nafsan zakiyyatan bighayri nafsin laqad jita shayan nukran', 1, NOW(), NOW()),
(23, 75, '۞قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا', 'তিনি বললেনঃ আমি কি বলিনি যে, আপনি আমার সাথে ধৈর্য্য ধরে থাকতে পারবেন না।', 'Qala alam aqul laka innaka lan tastateeAAa maAAiya sabran', 1, NOW(), NOW()),
(23, 76, 'قَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۭ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا', 'মূসা বললেনঃ এরপর যদি আমি আপনাকে কোন বিষয়ে প্রশ্ন করি, তবে আপনি আমাকে সাথে রাখবেন না। আপনি আমার পক্ষ থেকে অভিযোগ মুক্ত হয়ে গেছেন।', 'Qala in saaltuka AAan shayin baAAdaha fala tusahibnee qad balaghta min ladunnee AAuthran', 1, NOW(), NOW()),
(23, 77, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهۡلَ قَرۡيَةٍ ٱسۡتَطۡعَمَآ أَهۡلَهَا فَأَبَوۡاْ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارٗا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَجۡرٗا', 'অতঃপর তারা চলতে লাগল, অবশেষে যখন একটি জনপদের অধিবাসীদের কাছে পৌছে তাদের কাছে খাবার চাইল, তখন তারা তাদের অতিথেয়তা করতে অস্বীকার করল। অতঃপর তারা সেখানে একটি পতনোম্মুখ প্রাচীর দেখতে পেলেন, সেটি তিনি সোজা করে দাঁড় করিয়ে দিলেন। মূসা বললেনঃ আপনি ইচ্ছা করলে তাদের কাছ থেকে এর পারিশ্রমিক আদায় করতে পারতেন।', 'Faintalaqa hatta itha ataya ahla qaryatin istatAAama ahlaha faabaw an yudayyifoohuma fawajada feeha jidaran yureedu an yanqadda faaqamahu qala law shita laittakhathta AAalayhi ajran', 1, NOW(), NOW()),
(23, 78, 'قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا', 'তিনি বললেনঃ এখানেই আমার ও আপনার মধ্যে সম্পর্কচ্ছেদ হল। এখন যে বিষয়ে আপনি ধৈর্য্য ধরতে পারেননি, আমি তার তাৎপর্য বলে দিচ্ছি।', 'Qala hatha firaqu baynee wabaynika saonabbioka bitaweeli ma lam tastatiAA AAalayhi sabran', 1, NOW(), NOW()),
(23, 79, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا', 'নৌকাটির ব্যাপারে-সেটি ছিল কয়েকজন দরিদ্র ব্যক্তির। তারা সমুদ্রে জীবিকা অন্বেষন করত। আমি ইচ্ছা করলাম যে, সেটিকে ক্রটিযুক্ত করে দেই। তাদের অপরদিকে ছিল এক বাদশাহ। সে বলপ্রয়োগে প্রত্যেকটি নৌকা ছিনিয়ে নিত।', 'Amma alssafeenatu fakanat limasakeena yaAAmaloona fee albahri faaradtu an aAAeebaha wakana waraahum malikun yakhuthu kulla safeenatin ghasban', 1, NOW(), NOW()),
(23, 80, 'وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا', 'বালকটির ব্যাপার তার পিতা-মাতা ছিল ঈমানদার। আমি আশঙ্কা করলাম যে, সে অবাধ্যতা ও কুফর দ্বারা তাদেরকে প্রভাবিত করবে।', 'Waamma alghulamu fakana abawahu muminayni fakhasheena an yurhiqahuma tughyanan wakufran', 1, NOW(), NOW()),
(23, 81, 'فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا', 'অতঃপর আমি ইচ্ছা করলাম যে, তাদের পালনকর্তা তাদেরকে মহত্তর, তার চাইতে পবিত্রতায় ও ভালবাসায় ঘনিষ্ঠতর একটি শ্রেষ্ঠ সন্তান দান করুক।', 'Faaradna an yubdilahuma rabbuhuma khayran minhu zakatan waaqraba ruhman', 1, NOW(), NOW()),
(23, 82, 'وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا', 'প্রাচীরের ব্যাপার-সেটি ছিল নগরের দুজন পিতৃহীন বালকের। এর নীচে ছিল তাদের গুপ্তধন এবং তাদের পিতা ছিল সৎকর্ম পরায়ন। সুতরাং আপনার পালনকর্তা দায়বশতঃ ইচ্ছা করলেন যে, তারা যৌবনে পদার্পন করুক এবং নিজেদের গুপ্তধন উদ্ধার করুক। আমি নিজ মতে এটা করিনি। আপনি যে বিষয়ে ধৈর্য্যধারণ করতে অক্ষম হয়েছিলেন, এই হল তার ব্যাখ্যা।', 'Waamma aljidaru fakana lighulamayni yateemayni fee almadeenati wakana tahtahu kanzun lahuma wakana aboohuma salihan faarada rabbuka an yablugha ashuddahuma wayastakhrija kanzahuma rahmatan min rabbika wama faAAaltuhu AAan amree thalika taweelu ma lam tastiAA AAalayhi sabran', 1, NOW(), NOW()),
(23, 83, 'وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا', 'তারা আপনাকে যুলকারনাইন সম্পর্কে জিজ্ঞাসা করে। বলুনঃ আমি তোমাদের কাছে তাঁর কিছু অবস্থা বর্ণনা করব।', 'Wayasaloonaka AAan thee alqarnayni qul saatloo AAalaykum minhu thikran', 1, NOW(), NOW()),
(23, 84, 'إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا', 'আমি তাকে পৃথিবীতে প্রতিষ্ঠিত করেছিলাম এবং প্রত্যেক বিষয়ের কার্যোপকরণ দান করেছিলাম।', 'Inna makkanna lahu fee alardi waataynahu min kulli shayin sababan', 1, NOW(), NOW()),
(23, 85, 'فَأَتۡبَعَ سَبَبًا', 'অতঃপর তিনি এক কার্যোপকরণ অবলম্বন করলেন।', 'FaatbaAAa sababan', 1, NOW(), NOW()),
(23, 86, 'حَتَّىٰٓ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِي عَيۡنٍ حَمِئَةٖ وَوَجَدَ عِندَهَا قَوۡمٗاۖ قُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا', 'অবশেষে তিনি যখন সুর্যের অস্তাচলে পৌছলেন; তখন তিনি সুর্যকে এক পঙ্কিল জলাশয়ে অস্ত যেতে দেখলেন এবং তিনি সেখানে এক সম্প্রদায়কে দেখতে পেলেন। আমি বললাম, হে যুলকারনাইন! আপনি তাদেরকে শাস্তি দিতে পারেন অথবা তাদেরকে সদয়ভাবে গ্রহণ করতে পারেন।', 'Hatta itha balagha maghriba alshshamsi wajadaha taghrubu fee AAaynin hamiatin wawajada AAindaha qawman qulna ya tha alqarnayni imma an tuAAaththiba waimma an tattakhitha feehim husnan', 1, NOW(), NOW()),
(23, 87, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابٗا نُّكۡرٗا', 'তিনি বললেনঃ যে কেউ সীমালঙ্ঘনকারী হবে আমি তাকে শাস্তি দেব। অতঃপর তিনি তাঁর পালনকর্তার কাছে ফিরে যাবেন। তিনি তাকে কঠোর শাস্তি দেবেন।', 'Qala amma man thalama fasawfa nuAAaththibuhu thumma yuraddu ila rabbihi fayuAAaththibuhu AAathaban nukran', 1, NOW(), NOW()),
(23, 88, 'وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا', 'এবং যে বিশ্বাস স্থাপন করে ও সৎকর্ম করে তার জন্য প্রতিদান রয়েছে কল্যাণ এবং আমার কাজে তাকে সহজ নির্দেশ দেব।', 'Waamma man amana waAAamila salihan falahu jazaan alhusna wasanaqoolu lahu min amrina yusran', 1, NOW(), NOW()),
(23, 89, 'ثُمَّ أَتۡبَعَ سَبَبًا', 'অতঃপর তিনি এক উপায় অবলম্বন করলেন।', 'Thumma atbaAAa sababan', 1, NOW(), NOW()),
(23, 90, 'حَتَّىٰٓ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمٖ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرٗا', 'অবশেষে তিনি যখন সূর্যের উদয়াচলে পৌছলেন, তখন তিনি তাকে এমন এক সম্প্রদায়ের উপর উদয় হতে দেখলেন, যাদের জন্যে সূর্যতাপ থেকে আত্নরক্ষার কোন আড়াল আমি সৃষ্টি করিনি।', 'Hatta itha balagha matliAAa alshshamsi wajadaha tatluAAu AAala qawmin lam najAAal lahum min dooniha sitran', 1, NOW(), NOW()),
(23, 91, 'كَذَٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَيۡهِ خُبۡرٗا', 'প্রকৃত ঘটনা এমনিই। তার বৃত্তান্ত আমি সম্যক অবগত আছি।', 'Kathalika waqad ahatna bima ladayhi khubran', 1, NOW(), NOW()),
(23, 92, 'ثُمَّ أَتۡبَعَ سَبَبًا', 'আবার তিনি এক পথ ধরলেন।', 'Thumma atbaAAa sababan', 1, NOW(), NOW()),
(23, 93, 'حَتَّىٰٓ إِذَا بَلَغَ بَيۡنَ ٱلسَّدَّيۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمٗا لَّا يَكَادُونَ يَفۡقَهُونَ قَوۡلٗا', 'অবশেষে যখন তিনি দুই পর্বত প্রচীরের মধ্যস্থলে পৌছলেন, তখন তিনি সেখানে এক জাতিকে পেলেন, যারা তাঁর কথা একেবারেই বুঝতে পারছিল না।', 'Hatta itha balagha bayna alssaddayni wajada min doonihima qawman la yakadoona yafqahoona qawlan', 1, NOW(), NOW()),
(23, 94, 'قَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا', 'তারা বললঃ হে যুলকারনাইন, ইয়াজুজ ও মাজুজ দেশে অশান্তি সৃষ্টি করেছে। আপনি বললে আমরা আপনার জন্যে কিছু কর ধার্য করব এই শর্তে যে, আপনি আমাদের ও তাদের মধ্যে একটি প্রাচীর নির্মাণ করে দেবেন।', 'Qaloo ya tha alqarnayni inna yajooja wamajooja mufsidoona fee alardi fahal najAAalu laka kharjan AAala an tajAAala baynana wabaynahum saddan', 1, NOW(), NOW()),
(23, 95, 'قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا', 'তিনি বললেনঃ আমার পালনকর্তা আমাকে যে সামর্থ?2470;িয়েছেন, তাই যথেষ্ট। অতএব, তোমরা আমাকে শ্রম দিয়ে সাহায্য কর। আমি তোমাদের ও তাদের মধ্যে একটি সুদৃঢ় প্রাচীর নির্মাণ করে দেব।', 'Qala ma makkannee feehi rabbee khayrun faaAAeenoonee biquwwatin ajAAal baynakum wabaynahum radman', 1, NOW(), NOW()),
(23, 96, 'ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا', 'তোমরা আমাকে লোহার পাত এনে দাও। অবশেষে যখন পাহাড়ের মধ্যবর্তী ফাঁকা স্থান পূর্ণ হয়ে গেল, তখন তিনি বললেনঃ তোমরা হাঁপরে দম দিতে থাক। অবশেষে যখন তা আগুনে পরিণত হল, তখন তিনি বললেনঃ তোমরা গলিত তামা নিয়ে এস, আমি তা এর উপরে ঢেলে দেই।', 'Atoonee zubara alhadeedi hatta itha sawa bayna alsadafayni qala onfukhoo hatta itha jaAAalahu naran qala atoonee ofrigh AAalayhi qitran', 1, NOW(), NOW()),
(23, 97, 'فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا', 'অতঃপর ইয়াজুজ ও মাজুজ তার উপরে আরোহণ করতে পারল না এবং তা ভেদ করতে ও সক্ষম হল না।', 'Fama istaAAoo an yathharoohu wama istataAAoo lahu naqban', 1, NOW(), NOW()),
(23, 98, 'قَالَ هَٰذَا رَحۡمَةٞ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي حَقّٗا', 'যুলকারনাইন বললেনঃ এটা আমার পালনকর্তার অনুগ্রহ। যখন আমার পালনকর্তার প্রতিশ্রুত সময় আসবে, তখন তিনি একে চূর্ণ-বিচূর্ণ করে দেবেন এবং আমার পালনকর্তার প্রতিশ্রুতি সত্য।', 'Qala hatha rahmatun min rabbee faitha jaa waAAdu rabbee jaAAalahu dakkaa wakana waAAdu rabbee haqqan', 1, NOW(), NOW()),
(23, 99, '۞وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذٖ يَمُوجُ فِي بَعۡضٖۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعٗا', 'আমি সেদিন তাদেরকে দলে দলে তরঙ্গের আকারে ছেড়ে দেব এবং শিঙ্গায় ফুঁৎকার দেয়া হবে। অতঃপর আমি তাদের সবাইকে একত্রিত করে আনব।', 'Watarakna baAAdahum yawmaithin yamooju fee baAAdin wanufikha fee alssoori fajamaAAnahum jamAAan', 1, NOW(), NOW()),
(23, 100, 'وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا', 'সেদিন আমি কাফেরদের কাছে জাহান্নামকে প্রত্যক্ষ ভাবে উপস্থিত করব।', 'WaAAaradna jahannama yawmaithin lilkafireena AAardan', 1, NOW(), NOW()),
(23, 101, 'ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا', 'যাদের চক্ষুসমূহের উপর পর্দা ছিল আমার স্মরণ থেকে এবং যারা শুনতেও সক্ষম ছিল না।', 'Allatheena kanat aAAyunuhum fee ghitain AAan thikree wakanoo la yastateeAAoona samAAan', 1, NOW(), NOW()),
(23, 102, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا', 'কাফেররা কি মনে করে যে, তারা আমার পরিবর্তে আমার বান্দাদেরকে অভিভাবক রূপে গ্রহণ করবে? আমি কাফেরদের অভ্যর্থনার জন্যে জাহান্নামকে প্রস্তুত করে রেখেছি।', 'Afahasiba allatheena kafaroo an yattakhithoo AAibadee min doonee awliyaa inna aAAtadna jahannama lilkafireena nuzulan', 1, NOW(), NOW()),
(23, 103, 'قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا', 'বলুনঃ আমি কি তোমাদেরকে সেসব লোকের সংবাদ দেব, যারা কর্মের দিক দিয়ে খুবই ক্ষতিগ্রস্ত।', 'Qul hal nunabbiokum bialakhsareena aAAmalan', 1, NOW(), NOW()),
(23, 104, 'ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا', 'তারাই সে লোক, যাদের প্রচেষ্টা পার্থিবজীবনে বিভ্রান্ত হয়, অথচ তারা মনে করে যে, তারা সৎকর্ম করেছে।', 'Allatheena dalla saAAyuhum fee alhayati alddunya wahum yahsaboona annahum yuhsinoona sunAAan', 1, NOW(), NOW()),
(23, 105, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا', 'তারাই সে লোক, যারা তাদের পালনকর্তার নিদর্শনাবলী এবং তাঁর সাথে সাক্ষাতের বিষয় অস্বীকার করে। ফলে তাদের কর্ম নিষ্ফল হয়ে যায়। সুতরাং কেয়ামতের দিন তাদের জন্য আমি কোন গুরুত্ব স্থির করব না।', 'Olaika allatheena kafaroo biayati rabbihim waliqaihi fahabitat aAAmaluhum fala nuqeemu lahum yawma alqiyamati waznan', 1, NOW(), NOW()),
(23, 106, 'ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا', 'জাহান্নাম-এটাই তাদের প্রতিফল; কারণ, তারা কাফের হয়েছে এবং আমার নিদর্শনাবলী ও রসূলগণকে বিদ্রূপের বিষয় রূপে গ্রহণ করেছে।', 'Thalika jazaohum jahannamu bima kafaroo waittakhathoo ayatee warusulee huzuwan', 1, NOW(), NOW()),
(23, 107, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا', 'যারা বিশ্বাস স্থাপন করে ও সৎকর্ম সম্পাদন করে, তাদের অভ্যর্থনার জন্যে আছে জান্নাতুল ফেরদাউস।', 'Inna allatheena amanoo waAAamiloo alssalihati kanat lahum jannatu alfirdawsi nuzulan', 1, NOW(), NOW()),
(23, 108, 'خَٰلِدِينَ فِيهَا لَا يَبۡغُونَ عَنۡهَا حِوَلٗا', 'সেখানে তারা চিরকাল থাকবে, সেখান থেকে স্থান পরিবর্তন করতে চাইবে না।', 'Khalideena feeha la yabghoona AAanha hiwalan', 1, NOW(), NOW()),
(23, 109, 'قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدٗا', 'বলুনঃ আমার পালনকর্তার কথা, লেখার জন্যে যদি সমুদ্রের পানি কালি হয়, তবে আমার পালনকর্তার কথা, শেষ হওয়ার আগেই সে সমুদ্র নিঃশেষিত হয়ে যাবে। সাহায্যার্থে অনুরূপ আরেকটি সমুদ্র এনে দিলেও।', 'Qul law kana albahru midadan likalimati rabbee lanafida albahru qabla an tanfada kalimatu rabbee walaw jina bimithlihi madadan', 1, NOW(), NOW()),
(23, 110, 'قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلٗا صَٰلِحٗا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا', 'বলুনঃ আমি ও তোমাদের মতই একজন মানুষ, আমার প্রতি প্রত্যাদেশ হয় যে, তোমাদের ইলাহই একমাত্র ইলাহ। অতএব, যে ব্যক্তি তার পালনকর্তার সাক্ষাত কামনা করে, সে যেন, সৎকর্ম সম্পাদন করে এবং তার পালনকর্তার এবাদতে কাউকে শরীক না করে।', 'Qul innama ana basharun mithlukum yooha ilayya annama ilahukum ilahun wahidun faman kana yarjoo liqaa rabbihi falyaAAmal AAamalan salihan wala yushrik biAAibadati rabbihi ahadan', 1, NOW(), NOW()),
(24, 1, 'كٓهيعٓصٓ', 'কাফ-হা-ইয়া-আইন-সাদ', 'KafhayaAAaynsad', 1, NOW(), NOW()),
(24, 2, 'ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ', 'এটা আপনার পালনকর্তার অনুগ্রহের বিবরণ তাঁর বান্দা যাকারিয়ার প্রতি।', 'Thikru rahmati rabbika AAabdahu zakariyya', 1, NOW(), NOW()),
(24, 3, 'إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا', 'যখন সে তাঁর পালনকর্তাকে আহবান করেছিল নিভৃতে।', 'Ith nada rabbahu nidaan khafiyyan', 1, NOW(), NOW()),
(24, 4, 'قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا', 'সে বললঃ হে আমার পালনকর্তা আমার অস্থি বয়স-ভারাবনত হয়েছে; বার্ধক্যে মস্তক সুশুভ্র হয়েছে; হে আমার পালনকর্তা! আপনাকে ডেকে আমি কখনও বিফলমনোরথ হইনি।', 'Qala rabbi innee wahana alAAathmu minnee waishtaAAala alrrasu shayban walam akun biduAAaika rabbi shaqiyyan', 1, NOW(), NOW()),
(24, 5, 'وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا', 'আমি ভয় করি আমার পর আমার স্বগোত্রকে এবং আমার স্ত্রী বন্ধ্যা; কাজেই আপনি নিজের পক্ষ থেকে আমাকে এক জন কর্তব্য পালনকারী দান করুন।', 'Wainnee khiftu almawaliya min waraee wakanati imraatee AAaqiran fahab lee min ladunka waliyyan', 1, NOW(), NOW()),
(24, 6, 'يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا', 'সে আমার স্থলাভিষিক্ত হবে ইয়াকুব বংশের এবং হে আমার পালনকর্তা, তাকে করুন সন্তোষজনক।', 'Yarithunee wayarithu min ali yaAAqooba waijAAalhu rabbi radiyyan', 1, NOW(), NOW()),
(24, 7, 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا', 'হে যাকারিয়া, আমি তোমাকে এক পুত্রের সুসংবাদ দিচ্ছি, তার নাম হবে ইয়াহইয়া। ইতিপূর্বে এই নামে আমি কারও নাম করণ করিনি।', 'Ya zakariyya inna nubashshiruka bighulamin ismuhu yahya lam najAAal lahu min qablu samiyyan', 1, NOW(), NOW()),
(24, 8, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا', 'সে বললঃ হে আমার পালনকর্তা কেমন করে আমার পুত্র হবে অথচ আমার স্ত্রী যে বন্ধ্যা, আর আমিও যে বার্ধক্যের শেষ প্রান্তে উপনীত।', 'Qala rabbi anna yakoonu lee ghulamun wakanati imraatee AAaqiran waqad balaghtu mina alkibari AAitiyyan', 1, NOW(), NOW()),
(24, 9, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَيَّ هَيِّنٞ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَيۡـٔٗا', 'তিনি বললেনঃ এমনিতেই হবে। তোমার পালনকর্তা বলে দিয়েছেনঃ এটা আমার পক্ষে সহজ। আমি তো পুর্বে তোমাকে সৃষ্টি করেছি এবং তুমি কিছুই ছিলে না।', 'Qala kathalika qala rabbuka huwa AAalayya hayyinun waqad khalaqtuka min qablu walam taku shayan', 1, NOW(), NOW()),
(24, 10, 'قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٖ سَوِيّٗا', 'সে বললঃ হে আমার পালনকর্তা, আমাকে একটি নির্দশন দিন। তিনি বললেন তোমার নিদর্শন এই যে, তুমি সুস্থ অবস্থায় তিন দিন মানুষের সাথে কথাবার্তা বলবে না।', 'Qala rabbi ijAAal lee ayatan qala ayatuka alla tukallima alnnasa thalatha layalin sawiyyan', 1, NOW(), NOW()),
(24, 11, 'فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةٗ وَعَشِيّٗا', 'অতঃপর সে কক্ষ থেকে বের হয়ে তার সম্প্রদায়ের কাছে এল এবং ইঙ্গিতে তাদেরকে সকাল সন্ধ্যায় আল্লাহকে স্মরণ করতে বললঃ', 'Fakharaja AAala qawmihi mina almihrabi faawha ilayhim an sabbihoo bukratan waAAashiyyan', 1, NOW(), NOW()),
(24, 12, 'يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا', 'হে ইয়াহইয়া দৃঢ়তার সাথে এই গ্রন্থ ধারণ কর। আমি তাকে শৈশবেই বিচারবুদ্ধি দান করেছিলাম।', 'Ya yahya khuthi alkitaba biquwwatin waataynahu alhukma sabiyyan', 1, NOW(), NOW()),
(24, 13, 'وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا', 'এবং নিজের পক্ষ থেকে আগ্রহ ও পবিত্রতা দিয়েছি। সে ছিল পরহেযগার।', 'Wahananan min ladunna wazakatan wakana taqiyyan', 1, NOW(), NOW()),
(24, 14, 'وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا', 'পিতা-মাতার অনুগত এবং সে উদ্ধত, নাফরমান ছিল না।', 'Wabarran biwalidayhi walam yakun jabbaran AAasiyyan', 1, NOW(), NOW()),
(24, 15, 'وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا', 'তার প্রতি শান্তি-যেদিন সে জন্মগ্রহণ করে এবং যেদিন মৃত্যুবরণ করবে এবং যেদিন জীবিতাবস্থায় পুনরুত্থিত হবে।', 'Wasalamun AAalayhi yawma wulida wayawma yamootu wayawma yubAAathu hayyan', 1, NOW(), NOW()),
(24, 16, 'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا', 'এই কিতাবে মারইয়ামের কথা বর্ণনা করুন, যখন সে তার পরিবারের লোকজন থেকে পৃথক হয়ে পূর্বদিকে এক স্থানে আশ্রয় নিল।', 'Waothkur fee alkitabi maryama ithi intabathat min ahliha makanan sharqiyyan', 1, NOW(), NOW()),
(24, 17, 'فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا', 'অতঃপর তাদের থেকে নিজেকে আড়াল করার জন্যে সে পর্দা করলো। অতঃপর আমি তার কাছে আমার রূহ প্রেরণ করলাম, সে তার নিকট পুর্ণ মানবাকৃতিতে আত্নপ্রকাশ করল।', 'Faittakhathat min doonihim hijaban faarsalna ilayha roohana fatamaththala laha basharan sawiyyan', 1, NOW(), NOW()),
(24, 18, 'قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا', 'মারইয়াম বললঃ আমি তোমা থেকে দয়াময়ের আশ্রয় প্রার্থনা করি যদি তুমি আল্লাহভীরু হও।', 'Qalat innee aAAoothu bialrrahmani minka in kunta taqiyyan', 1, NOW(), NOW()),
(24, 19, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا', 'সে বললঃ আমি তো শুধু তোমার পালনকর্তা প্রেরিত, যাতে তোমাকে এক পবিত্র পুত্র দান করে যাব।', 'Qala innama ana rasoolu rabbiki liahaba laki ghulaman zakiyyan', 1, NOW(), NOW()),
(24, 20, 'قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا', 'মরিইয়াম বললঃ কিরূপে আমার পুত্র হবে, যখন কোন মানব আমাকে স্পর্শ করেনি এবং আমি ব্যভিচারিণীও কখনও ছিলাম না', 'Qalat anna yakoonu lee ghulamun walam yamsasnee basharun walam aku baghiyyan', 1, NOW(), NOW()),
(24, 21, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنٞۖ وَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ وَرَحۡمَةٗ مِّنَّاۚ وَكَانَ أَمۡرٗا مَّقۡضِيّٗا', 'সে বললঃ এমনিতেই হবে। তোমার পালনকর্তা বলেছেন, এটা আমার জন্যে সহজ সাধ্য এবং আমি তাকে মানুষের জন্যে একটি নিদর্শন ও আমার পক্ষ থেকে অনুগ্রহ স্বরূপ করতে চাই। এটা তো এক স্থিরীকৃত ব্যাপার।', 'Qala kathaliki qala rabbuki huwa AAalayya hayyinun walinajAAalahu ayatan lilnnasi warahmatan minna wakana amran maqdiyyan', 1, NOW(), NOW()),
(24, 22, '۞فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانٗا قَصِيّٗا', 'অতঃপর তিনি গর্ভে সন্তান ধারণ করলেন এবং তৎসহ এক দূরবর্তী স্থানে চলে গেলেন।', 'Fahamalathu faintabathat bihi makanan qasiyyan', 1, NOW(), NOW()),
(24, 23, 'فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا', 'প্রসব বেদনা তাঁকে এক খেজুর বৃক্ষ-মূলে আশ্রয় নিতে বাধ্য করল। তিনি বললেনঃ হায়, আমি যদি কোনরূপে এর পূর্বে মরে যেতাম এবং মানুষের স্মৃতি থেকে বিলুপ্ত হয়ে, যেতাম', 'Faajaaha almakhadu ila jithAAi alnnakhlati qalat ya laytanee mittu qabla hatha wakuntu nasyan mansiyyan', 1, NOW(), NOW()),
(24, 24, 'فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا', 'অতঃপর ফেরেশতা তাকে নিম্নদিক থেকে আওয়ায দিলেন যে, তুমি দুঃখ করো না। তোমার পালনকর্তা তোমার পায়ের তলায় একটি নহর জারি করেছেন।', 'Fanadaha min tahtiha alla tahzanee qad jaAAala rabbuki tahtaki sariyyan', 1, NOW(), NOW()),
(24, 25, 'وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا', 'আর তুমি নিজের দিকে খেজুর গাছের কান্ডে নাড়া দাও, তা থেকে তোমার উপর সুপক্ক খেজুর পতিত হবে।', 'Wahuzzee ilayki bijithAAi alnnakhlati tusaqit AAalayki rutaban janiyyan', 1, NOW(), NOW()),
(24, 26, 'فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا', 'যখন আহার কর, পান কর এবং চক্ষু শীতল কর। যদি মানুষের মধ্যে কাউকে তুমি দেখ, তবে বলে দিওঃ আমি আল্লাহর উদ্দেশে রোযা মানত করছি। সুতরাং আজ আমি কিছুতেই কোন মানুষের সাথে কথা বলব না।', 'Fakulee waishrabee waqarree AAaynan faimma tarayinna mina albashari ahadan faqoolee innee nathartu lilrrahmani sawman falan okallima alyawma insiyyan', 1, NOW(), NOW()),
(24, 27, 'فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا', 'অতঃপর তিনি সন্তানকে নিয়ে তার সম্প্রদায়ের কাছে উপস্থিত হলেন। তারা বললঃ হে মারইয়াম, তুমি একটি অঘটন ঘটিয়ে বসেছ।', 'Faatat bihi qawmaha tahmiluhu qaloo ya maryamu laqad jiti shayan fariyyan', 1, NOW(), NOW()),
(24, 28, 'يَـٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا', 'হে হারূণ-ভাগিনী, তোমার পিতা অসৎ ব্যক্তি ছিলেন না এবং তোমার মাতাও ছিল না ব্যভিচারিনী।', 'Ya okhta haroona ma kana abooki imraa sawin wama kanat ommuki baghiyyan', 1, NOW(), NOW()),
(24, 29, 'فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا', 'অতঃপর তিনি হাতে সন্তানের দিকে ইঙ্গিত করলেন। তারা বললঃ যে কোলের শিশু তার সাথে আমরা কেমন করে কথা বলব', 'Faasharat ilayhi qaloo kayfa nukallimu man kana fee almahdi sabiyyan', 1, NOW(), NOW()),
(24, 30, 'قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا', 'সন্তান বললঃ আমি তো আল্লাহর দাস। তিনি আমাকে কিতাব দিয়েছেন এবং আমাকে নবী করেছেন।', 'Qala innee AAabdu Allahi ataniya alkitaba wajaAAalanee nabiyyan', 1, NOW(), NOW()),
(24, 31, 'وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا', 'আমি যেখানেই থাকি, তিনি আমাকে বরকতময় করেছেন। তিনি আমাকে নির্দেশ দিয়েছেন, যতদিন জীবিত থাকি, ততদিন নামায ও যাকাত আদায় করতে।', 'WajaAAalanee mubarakan ayna ma kuntu waawsanee bialssalati waalzzakati ma dumtu hayyan', 1, NOW(), NOW()),
(24, 32, 'وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا', 'এবং জননীর অনুগত থাকতে এবং আমাকে তিনি উদ্ধত ও হতভাগ্য করেননি।', 'Wabarran biwalidatee walam yajAAalnee jabbaran shaqiyyan', 1, NOW(), NOW()),
(24, 33, 'وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا', 'আমার প্রতি সালাম যেদিন আমি জন্মগ্রহণ করেছি, যেদিন মৃত্যুবরণ করব এবং যেদিন পুনরুজ্জীবিত হয়ে উত্থিত হব।', 'Waalssalamu AAalayya yawma wulidtu wayawma amootu wayawma obAAathu hayyan', 1, NOW(), NOW()),
(24, 34, 'ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِي فِيهِ يَمۡتَرُونَ', 'এই মারইয়ামের পুত্র ঈসা। সত্যকথা, যে সম্পর্কে লোকেরা বিতর্ক করে।', 'Thalika AAeesa ibnu maryama qawla alhaqqi allathee feehi yamtaroona', 1, NOW(), NOW()),
(24, 35, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'আল্লাহ এমন নন যে, সন্তান গ্রহণ করবেন, তিনি পবিত্র ও মহিমাময় সত্তা, তিনি যখন কোন কাজ করা সিদ্ধান্ত করেন, তখন একথাই বলেনঃ হও এবং তা হয়ে যায়।', 'Ma kana lillahi an yattakhitha min waladin subhanahu itha qada amran fainnama yaqoolu lahu kun fayakoonu', 1, NOW(), NOW()),
(24, 36, 'وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ', 'তিনি আরও বললেনঃ নিশ্চয় আল্লাহ আমার পালনকর্তা ও তোমাদের পালনকর্তা। অতএব, তোমরা তার এবাদত কর। এটা সরল পথ।', 'Wainna Allaha rabbee warabbukum faoAAbudoohu hatha siratun mustaqeemun', 1, NOW(), NOW()),
(24, 37, 'فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ', 'অতঃপর তাদের মধ্যে দলগুলো পৃথক পৃথক পথ অবলম্বন করল। সুতরাং মহাদিবস আগমনকালে কাফেরদের জন্যে ধবংস।', 'Faikhtalafa alahzabu min baynihim fawaylun lillatheena kafaroo min mashhadi yawmin AAatheemin', 1, NOW(), NOW()),
(24, 38, 'أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلٖ مُّبِينٖ', 'সেদিন তারা কি চমৎকার শুনবে এবং দেখবে, যেদিন তারা আমার কাছে আগমন করবে। কিন্তু আজ জালেমরা প্রকাশ্য বিভ্রান্তিতে রয়েছে।', 'AsmiAA bihim waabsir yawma yatoonana lakini alththalimoona alyawma fee dalalin mubeenin', 1, NOW(), NOW()),
(24, 39, 'وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ', 'আপনি তাদেরকে পরিতাপের দিবস সম্পর্কে হুশিয়ার করে দিন যখন সব ব্যাপারের মীমাংসা হয়ে যাবে। এখন তারা অনবধানতায় আছে এবং তারা বিশ্বাস স্থাপন করছে না।', 'Waanthirhum yawma alhasrati ith qudiya alamru wahum fee ghaflatin wahum la yuminoona', 1, NOW(), NOW()),
(24, 40, 'إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ', 'আমিই চুড়ান্ত মালিকানার অধিকারী হব পৃথিবীর এবং তার উপর যারা আছে তাদের এবং আমারই কাছে তারা প্রত্যাবর্তিত হবে।', 'Inna nahnu narithu alarda waman AAalayha wailayna yurjaAAoona', 1, NOW(), NOW()),
(24, 41, 'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا', 'আপনি এই কিতাবে ইব্রাহীমের কথা বর্ণনা করুন। নিশ্চয় তিনি ছিলেন সত্যবাদী, নবী।', 'Waothkur fee alkitabi ibraheema innahu kana siddeeqan nabiyyan', 1, NOW(), NOW()),
(24, 42, 'إِذۡ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا', 'যখন তিনি তার পিতাকে বললেনঃ হে আমার পিতা, যে শোনে না, দেখে না এবং তোমার কোন উপকারে আসে না, তার এবাদত কেন কর', 'Ith qala liabeehi ya abati lima taAAbudu ma la yasmaAAu wala yubsiru wala yughnee AAanka shayan', 1, NOW(), NOW()),
(24, 43, 'يَـٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا', 'হে আমার পিতা, আমার কাছে এমন জ্ঞান এসেছে; যা তোমার কাছে আসেনি, সুতরাং আমার অনুসরণ কর, আমি তোমাকে সরল পথ দেখাব।', 'Ya abati innee qad jaanee mina alAAilmi ma lam yatika faittabiAAnee ahdika siratan sawiyyan', 1, NOW(), NOW()),
(24, 44, 'يَـٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا', 'হে আমার পিতা, শয়তানের এবাদত করো না। নিশ্চয় শয়তান দয়াময়ের অবাধ্য।', 'Ya abati la taAAbudi alshshaytana inna alshshaytana kana lilrrahmani AAasiyyan', 1, NOW(), NOW()),
(24, 45, 'يَـٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا', 'হে আমার পিতা, আমি আশঙ্কা করি, দয়াময়ের একটি আযাব তোমাকে স্পর্শ করবে, অতঃপর তুমি শয়তানের সঙ্গী হয়ে যাবে।', 'Ya abati innee akhafu an yamassaka AAathabun mina alrrahmani fatakoona lilshshyatani waliyyan', 1, NOW(), NOW()),
(24, 46, 'قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَـٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيّٗا', 'পিতা বললঃ যে ইব্রাহীম, তুমি কি আমার উপাস্যদের থেকে মুখ ফিরিয়ে নিচ্ছ? যদি তুমি বিরত না হও, আমি অবশ্যই প্রস্তরাঘাতে তোমার প্রাণনাশ করব। তুমি চিরতরে আমার কাছ থেকে দূর হয়ে যাও।', 'Qala araghibun anta AAan alihatee ya ibraheemu lain lam tantahi laarjumannaka waohjurnee maliyyan', 1, NOW(), NOW()),
(24, 47, 'قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيّٗا', 'ইব্রাহীম বললেনঃ তোমার উপর শান্তি হোক, আমি আমার পালনকর্তার কাছে তোমার জন্যে ক্ষমা প্রার্থনা করব। নিশ্চয় তিনি আমার প্রতি মেহেরবান।', 'Qala salamun AAalayka saastaghfiru laka rabbee innahu kana bee hafiyyan', 1, NOW(), NOW()),
(24, 48, 'وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا', 'আমি পরিত্যাগ করছি তোমাদেরকে এবং তোমরা আল্লাহ ব্যতীত যাদের এবাদত কর তাদেরকে; আমি আমার পালনকর্তার এবাদত করব। আশা করি, আমার পালনকর্তার এবাদত করে আমি বঞ্চিত হব না।', 'WaaAAtazilukum wama tadAAoona min dooni Allahi waadAAoo rabbee AAasa alla akoona biduAAai rabbee shaqiyyan', 1, NOW(), NOW()),
(24, 49, 'فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا', 'অতঃপর তিনি যখন তাদেরকে এবং তার আল্লাহ ব্যতীত যাদের এবাদত করত, তাদের সবাইকে পরিত্যাগ করলেন, তখন আমি তাকে দান করলাম ইসহাক ও ইয়াকুব এবং প্রত্যেককে নবী করলাম।', 'Falamma iAAtazalahum wama yaAAbudoona min dooni Allahi wahabna lahu ishaqa wayaAAqooba wakullan jaAAalna nabiyyan', 1, NOW(), NOW()),
(24, 50, 'وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيّٗا', 'আমি তাদেরকে দান করলাম আমার অনুগ্রহ এবং তাদেরকে দিলাম সমুচ্চ সুখ্যাতি।', 'Wawahabna lahum min rahmatina wajaAAalna lahum lisana sidqin AAaliyyan', 1, NOW(), NOW()),
(24, 51, 'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا', 'এই কিতাবে মূসার কথা বর্ণনা করুন, তিনি ছিলেন মনোনীত এবং তিনি ছিলেন রাসূল, নবী।', 'Waothkur fee alkitabi moosa innahu kana mukhlasan wakana rasoolan nabiyyan', 1, NOW(), NOW()),
(24, 52, 'وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيّٗا', 'আমি তাকে আহবান করলাম তূর পাহাড়ের ডান দিক থেকে এবং গুঢ়তত্ত্ব আলোচনার উদ্দেশে তাকে নিকটবর্তী করলাম।', 'Wanadaynahu min janibi alttoori alaymani waqarrabnahu najiyyan', 1, NOW(), NOW()),
(24, 53, 'وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا', 'আমি নিজ অনুগ্রহে তাঁকে দান করলাম তাঁর ভাই হারুনকে নবীরূপে।', 'Wawahabna lahu min rahmatina akhahu haroona nabiyyan', 1, NOW(), NOW()),
(24, 54, 'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا', 'এই কিতাবে ইসমাঈলের কথা বর্ণনা করুন, তিনি প্রতিশ্রুতি পালনে সত্যাশ্রয়ী এবং তিনি ছিলেন রসূল, নবী।', 'Waothkur fee alkitabi ismaAAeela innahu kana sadiqa alwaAAdi wakana rasoolan nabiyyan', 1, NOW(), NOW()),
(24, 55, 'وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا', 'তিনি তাঁর পরিবারবর্গকে নামায ও যাকাত আদায়ের নির্দেশ দিতেন এবং তিনি তাঁর পালনকর্তার কাছে পছন্দনীয় ছিলেন।', 'Wakana yamuru ahlahu bialssalati waalzzakati wakana AAinda rabbihi mardiyyan', 1, NOW(), NOW()),
(24, 56, 'وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا', 'এই কিতাবে ইদ্রীসের কথা আলোচনা করুন, তিনি ছিলেন সত্যবাদী নবী।', 'Waothkur fee alkitabi idreesa innahu kana siddeeqan nabiyyan', 1, NOW(), NOW()),
(24, 57, 'وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا', 'আমি তাকে উচ্চে উন্নীত করেছিলাম।', 'WarafaAAnahu makanan AAaliyyan', 1, NOW(), NOW()),
(24, 58, 'أُوْلَـٰٓئِكَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحٖ وَمِن ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَـٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا۩', 'এরাই তারা-নবীগণের মধ্য থেকে যাদেরকে আল্লাহ তা’আলা নেয়ামত দান করেছেন। এরা আদমের বংশধর এবং যাদেরকে আমি নূহের সাথে নৌকায় আরোহন করিয়েছিলাম, তাদের বংশধর, এবং ইব্রাহীম ও ইসরাঈলের বংশধর এবং যাদেরকে আমি পথ প্রদর্শন করেছি ও মনোনীত করেছি, তাদের বংশোদ্ভূত। তাদের কাছে যখন দয়াময় আল্লাহর আয়াতসমূহ পাঠ করা হত, তখন তারা সেজদায় লুটিয়ে পড়ত এবং ক্রন্দন করত।', 'Olaika allatheena anAAama Allahu AAalayhim mina alnnabiyyeena min thurriyyati adama wamimman hamalna maAAa noohin wamin thurriyyati ibraheema waisraeela wamimman hadayna waijtabayna itha tutla AAalayhim ayatu alrrahmani kharroo sujjadan wabukiyyan', 1, NOW(), NOW()),
(24, 59, '۞فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا', 'অতঃপর তাদের পরে এল অপদার্থ পরবর্তীরা। তারা নামায নষ্ট করল এবং কুপ্রবৃত্তির অনুবর্তী হল। সুতরাং তারা অচিরেই পথভ্রষ্টতা প্রত্যক্ষ করবে।', 'Fakhalafa min baAAdihim khalfun adaAAoo alssalata waittabaAAoo alshshahawati fasawfa yalqawna ghayyan', 1, NOW(), NOW()),
(24, 60, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ شَيۡـٔٗا', 'কিন্তু তারা ব্যতীত, যারা তওবা করেছে, বিশ্বাস স্থাপন করেছে। সুতরাং তারা জান্নাতে প্রবেশ করবে এবং তাদের উপর কোন জুলুম করা হবে না।', 'Illa man taba waamana waAAamila salihan faolaika yadkhuloona aljannata wala yuthlamoona shayan', 1, NOW(), NOW()),
(24, 61, 'جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ بِٱلۡغَيۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِيّٗا', 'তাদের স্থায়ী বসবাস হবে যার ওয়াদা দয়াময় আল্লাহ তাঁর বান্দাদেরকে অদৃশ্যভাবে দিয়েছেন। অবশ্যই তাঁর ওয়াদার তারা পৌঁছাবে।', 'Jannati AAadnin allatee waAAada alrrahmanu AAibadahu bialghaybi innahu kana waAAduhu matiyyan', 1, NOW(), NOW()),
(24, 62, 'لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَٰمٗاۖ وَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا', 'তারা সেখানে সালাম ব্যতীত কোন অসার কথাবার্তা শুনবে না এবং সেখানে সকাল-সন্ধ্যা তাদের জন্যে রুযী থাকবে।', 'La yasmaAAoona feeha laghwan illa salaman walahum rizquhum feeha bukratan waAAashiyyan', 1, NOW(), NOW()),
(24, 63, 'تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِيّٗا', 'এটা ঐ জান্নাত যার অধিকারী করব আমার বান্দাদের মধ্যে পরহেযগারদেরকে।', 'Tilka aljannatu allatee noorithu min AAibadina man kana taqiyyan', 1, NOW(), NOW()),
(24, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيّٗا', '(জিব্রাইল বললঃ) আমি আপনার পালনকর্তার আদেশ ব্যতীত অবতরণ করি না, যা আমাদের সামনে আছে, যা আমাদের পশ্চাতে আছে এবং যা এ দুই-এর মধ্যস্থলে আছে, সবই তাঁর এবং আপনার পালনকর্তা বিস্মৃত হওয়ার নন।', 'Wama natanazzalu illa biamri rabbika lahu ma bayna aydeena wama khalfana wama bayna thalika wama kana rabbuka nasiyyan', 1, NOW(), NOW()),
(24, 65, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا', 'তিনি নভোমন্ডল, ভূমন্ডলে এতদুভয়ের মধ্যবর্তী সবার পালনকর্তা। সুতরাং তাঁরই বন্দেগী করুন এবং তাতে দৃঢ় থাকুন আপনি কি তাঁর সমনাম কাউকে জানেন', 'Rabbu alssamawati waalardi wama baynahuma faoAAbudhu waistabir liAAibadatihi hal taAAlamu lahu samiyyan', 1, NOW(), NOW()),
(24, 66, 'وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا', 'মানুষ বলেঃ আমার মৃত্যু হলে পর আমি কি জীবিত অবস্থায় পুনরুত্থিত হব', 'Wayaqoolu alinsanu aitha ma mittu lasawfa okhraju hayyan', 1, NOW(), NOW()),
(24, 67, 'أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ وَلَمۡ يَكُ شَيۡـٔٗا', 'মানুষ কি স্মরণ করে না যে, আমি তাকে ইতি পূর্বে সৃষ্টি করেছি এবং সে তখন কিছুই ছিল না।', 'Awala yathkuru alinsanu anna khalaqnahu min qablu walam yaku shayan', 1, NOW(), NOW()),
(24, 68, 'فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا', 'সুতরাং আপনার পালনকর্তার কসম, আমি অবশ্যই তাদেরকে এবং শয়তানদেরকে একত্রে সমবেত করব, অতঃপর অবশ্যই তাদেরকে নতজানু অবস্থায় জাহান্নামের চারপাশে উপস্থিত করব।', 'Fawarabbika lanahshurannahum waalshshayateena thumma lanuhdirannahum hawla jahannama jithiyyan', 1, NOW(), NOW()),
(24, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا', 'অতঃপর প্রত্যেক সম্প্রদায়ের মধ্যে যে দয়াময় আল্লাহর সর্বাধিক অবাধ্য আমি অবশ্যই তাকে পৃথক করে নেব।', 'Thumma lananziAAanna min kulli sheeAAatin ayyuhum ashaddu AAala alrrahmani AAitiyyan', 1, NOW(), NOW()),
(24, 70, 'ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيّٗا', 'অতঃপর তাদের মধ্যে যারা জাহান্নামে প্রবেশের অধিক যোগ্য, আমি তাদের বিষয়ে ভালোভাবে জ্ঞাত আছি।', 'Thumma lanahnu aAAlamu biallatheena hum awla biha siliyyan', 1, NOW(), NOW()),
(24, 71, 'وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا', 'তোমাদের মধ্যে এমন কেউ নেই যে তথায় পৌছবে না। এটা আপনার পালনকর্তার অনিবার্য ফায়সালা।', 'Wain minkum illa wariduha kana AAala rabbika hatman maqdiyyan', 1, NOW(), NOW()),
(24, 72, 'ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّـٰلِمِينَ فِيهَا جِثِيّٗا', 'অতঃপর আমি পরহেযগারদেরকে উদ্ধার করব এবং জালেমদেরকে সেখানে নতজানু অবস্থায় ছেড়ে দেব।', 'Thumma nunajjee allatheena ittaqaw wanatharu alththalimeena feeha jithiyyan', 1, NOW(), NOW()),
(24, 73, 'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا', 'যখন তাদের কাছে আমার সুস্পষ্ট আয়াতসমূহ তেলাওয়াত করা হয়, তখন কাফেররা মুমিনদেরকে বলেঃ দুই দলের মধ্যে কোনটি মর্তবায় শ্রেষ্ঠ এবং কার মজলিস উত্তম', 'Waitha tutla AAalayhim ayatuna bayyinatin qala allatheena kafaroo lillatheena amanoo ayyu alfareeqayni khayrun maqaman waahsanu nadiyyan', 1, NOW(), NOW()),
(24, 74, 'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا', 'তাদের পূর্বে কত মানব গোষ্ঠীকে আমি বিনাশ করেছি, তারা তাদের চাইতে সম্পদে ও জাঁক-জমকে শ্রেষ্ঠ ছিল।', 'Wakam ahlakna qablahum min qarnin hum ahsanu athathan wariyan', 1, NOW(), NOW()),
(24, 75, 'قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا', 'বলুন, যারা পথভ্রষ্টতায় আছে, দয়াময় আল্লাহ তাদেরকে যথেষ্ট অবকাশ দেবেন; এমনকি অবশেষে তারা প্রত্যক্ষ করবে যে বিষয়ে তাদেরকে ওয়াদা দেয়া হচ্ছে, তা আযাব হোক অথবা কেয়ামতই হোক। সুতরাং তখন তারা জানতে পারবে কে মর্তবায় নিকৃষ্ট ও দলবলে দূর্বল।', 'Qul man kana fee alddalalati falyamdud lahu alrrahmanu maddan hatta itha raaw ma yooAAadoona imma alAAathaba waimma alssaAAata fasayaAAlamoona man huwa sharrun makanan waadAAafu jundan', 1, NOW(), NOW()),
(24, 76, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدٗىۗ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا', 'যারা সৎপথে চলে আল্লাহ তাদের পথপ্রাপ্তি বৃদ্ধি করেন এবং স্থায়ী সৎকর্মসমূহ তোমার পালনকর্তার কাছে সওয়াবের দিক দিয়ে শ্রেষ্ঠ এবং প্রতিদান হিসেবেও শ্রেষ্ট।', 'Wayazeedu Allahu allatheena ihtadaw hudan waalbaqiyatu alssalihatu khayrun AAinda rabbika thawaban wakhayrun maraddan', 1, NOW(), NOW()),
(24, 77, 'أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالٗا وَوَلَدًا', 'আপনি কি তাকে লক্ষ্য করেছেন যে, আমার নিদর্শনাবলীতে বিশ্বাস করে না এবং বলেঃ আমাকে অর্থ-সম্পদ ও সন্তান-সন্ততি অবশ্যই দেয়া হবে।', 'Afaraayta allathee kafara biayatina waqala laootayanna malan wawaladan', 1, NOW(), NOW()),
(24, 78, 'أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا', 'সে কি অদৃশ্য বিষয় জেনে ফেলেছে, অথবা দয়াময় আল্লাহর নিকট থেকে কোন প্রতিশ্রুতি প্রাপ্ত হয়েছে', 'AttalaAAa alghayba ami ittakhatha AAinda alrrahmani AAahdan', 1, NOW(), NOW()),
(24, 79, 'كَلَّاۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا', 'না, এটা ঠিক নয়। সে যা বলে আমি তা লিখে রাখব এবং তার শাস্তি দীর্ঘায়িত করতে থাকব।', 'Kalla sanaktubu ma yaqoolu wanamuddu lahu mina alAAathabi maddan', 1, NOW(), NOW()),
(24, 80, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا', 'সে যা বলে, মৃত্যুর পর আমি তা নিয়ে নেব এবং সে আমার কাছে আসবে একাকী।', 'Wanarithuhu ma yaqoolu wayateena fardan', 1, NOW(), NOW()),
(24, 81, 'وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا', 'তারা আল্লাহ ব্যতীত অন্যান্য ইলাহ গ্রহণ করেছে, যাতে তারা তাদের জন্যে সাহায্যকারী হয়।', 'Waittakhathoo min dooni Allahi alihatan liyakoonoo lahum AAizzan', 1, NOW(), NOW()),
(24, 82, 'كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا', 'কখনই নয়, তারা তাদের এবাদত অস্বীকার করবে এবং তাদের বিপক্ষে চলে যাবে।', 'Kalla sayakfuroona biAAibadatihim wayakoonoona AAalayhim diddan', 1, NOW(), NOW()),
(24, 83, 'أَلَمۡ تَرَ أَنَّآ أَرۡسَلۡنَا ٱلشَّيَٰطِينَ عَلَى ٱلۡكَٰفِرِينَ تَؤُزُّهُمۡ أَزّٗا', 'আপনি কি লক্ষ্য করেননি যে, আমি কাফেরদের উপর শয়তানদেরকে ছেড়ে দিয়েছি। তারা তাদেরকে বিশেষভাবে (মন্দকর্মে) উৎসাহিত করে।', 'Alam tara anna arsalna alshshayateena AAala alkafireena taozzuhum azzan', 1, NOW(), NOW()),
(24, 84, 'فَلَا تَعۡجَلۡ عَلَيۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدّٗا', 'সুতরাং তাদের ব্যাপারে আপনি তাড়াহুড়া করবেন না। আমি তো তাদের গণনা পূর্ণ করছি মাত্র।', 'Fala taAAjal AAalayhim innama naAAuddu lahum AAaddan', 1, NOW(), NOW()),
(24, 85, 'يَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدٗا', 'সেদিন দয়াময়ের কাছে পরহেযগারদেরকে অতিথিরূপে সমবেত করব', 'Yawma nahshuru almuttaqeena ila alrrahmani wafdan', 1, NOW(), NOW()),
(24, 86, 'وَنَسُوقُ ٱلۡمُجۡرِمِينَ إِلَىٰ جَهَنَّمَ وِرۡدٗا', 'এবং অপরাধীদেরকে পিপাসার্ত অবস্থায় জাহান্নামের দিকে হাঁকিয়ে নিয়ে যাব।', 'Wanasooqu almujrimeena ila jahannama wirdan', 1, NOW(), NOW()),
(24, 87, 'لَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا', 'যে দয়াময় আল্লাহর কাছ থেকে প্রতিশ্রুতি গ্রহণ করেছে, সে ব্যতীত আর কেউ সুপারিশ করার অধিকারী হবে না।', 'La yamlikoona alshshafaAAata illa mani ittakhatha AAinda alrrahmani AAahdan', 1, NOW(), NOW()),
(24, 88, 'وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗا', 'তারা বলেঃ দয়াময় আল্লাহ সন্তান গ্রহণ করেছেন।', 'Waqaloo ittakhatha alrrahmanu waladan', 1, NOW(), NOW()),
(24, 89, 'لَّقَدۡ جِئۡتُمۡ شَيۡـًٔا إِدّٗا', 'নিশ্চয় তোমরা তো এক অদ্ভুত কান্ড করেছ।', 'Laqad jitum shayan iddan', 1, NOW(), NOW()),
(24, 90, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا', 'হয় তো এর কারণেই এখনই নভোমন্ডল ফেটে পড়বে, পৃথিবী খন্ড-বিখন্ড হবে এবং পর্বতমালা চূর্ণ-বিচুর্ণ হবে।', 'Takadu alssamawatu yatafattarna minhu watanshaqqu alardu watakhirru aljibalu haddan', 1, NOW(), NOW()),
(24, 91, 'أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا', 'এ কারণে যে, তারা দয়াময় আল্লাহর জন্যে সন্তান আহবান করে।', 'An daAAaw lilrrahmani waladan', 1, NOW(), NOW()),
(24, 92, 'وَمَا يَنۢبَغِي لِلرَّحۡمَٰنِ أَن يَتَّخِذَ وَلَدًا', 'অথচ সন্তান গ্রহণ করা দয়াময়ের জন্য শোভনীয় নয়।', 'Wama yanbaghee lilrrahmani an yattakhitha waladan', 1, NOW(), NOW()),
(24, 93, 'إِن كُلُّ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدٗا', 'নভোমন্ডল ও ভূ-মন্ডলে কেউ নেই যে, দয়াময় আল্লাহর কাছে দাস হয়ে উপস্থিত হবে না।', 'In kullu man fee alssamawati waalardi illa atee alrrahmani AAabdan', 1, NOW(), NOW()),
(24, 94, 'لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدّٗا', 'তাঁর কাছে তাদের পরিসংখ্যান রয়েছে এবং তিনি তাদেরকে গণনা করে রেখেছেন।', 'Laqad ahsahum waAAaddahum AAaddan', 1, NOW(), NOW()),
(24, 95, 'وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ ٱلۡقِيَٰمَةِ فَرۡدًا', 'কেয়ামতের দিন তাদের সবাই তাঁর কাছে একাকী অবস্থায় আসবে।', 'Wakulluhum ateehi yawma alqiyamati fardan', 1, NOW(), NOW()),
(24, 96, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا', 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে, তাদেরকে দয়াময় আল্লাহ ভালবাসা দেবেন।', 'Inna allatheena amanoo waAAamiloo alssalihati sayajAAalu lahumu alrrahmanu wuddan', 1, NOW(), NOW()),
(24, 97, 'فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمٗا لُّدّٗا', 'আমি কোরআনকে আপনার ভাষায় সহজ করে দিয়েছি, যাতে আপনি এর দ্বারা পরহেযগারদেরকে সুসংবাদ দেন এবং কলহকারী সম্প্রদায়কে সতর্ক করেন।', 'Fainnama yassarnahu bilisanika litubashshira bihi almuttaqeena watunthira bihi qawman luddan', 1, NOW(), NOW()),
(24, 98, 'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا', 'তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করেছি। আপনি কি তাদের কাহারও সাড়া পান, অথবা তাদের ক্ষীনতম আওয়ায ও শুনতে পান', 'Wakam ahlakna qablahum min qarnin hal tuhissu minhum min ahadin aw tasmaAAu lahum rikzan', 1, NOW(), NOW()),
(25, 1, 'طه', 'তোয়া-হা', 'Taha', 1, NOW(), NOW()),
(25, 2, 'مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ', 'আপনাকে ক্লেশ দেবার জন্য আমি আপনার প্রতি কোরআন অবতীর্ণ করিনি।', 'Ma anzalna AAalayka alqurana litashqa', 1, NOW(), NOW()),
(25, 3, 'إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ', 'কিন্তু তাদেরই উপদেশের জন্য যারা ভয় করে।', 'Illa tathkiratan liman yakhsha', 1, NOW(), NOW()),
(25, 4, 'تَنزِيلٗا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى', 'এটা তাঁর কাছ থেকে অবতীর্ণ, যিনি ভূমন্ডল ও সমুচ্চ নভোমন্ডল সৃষ্টি করেছেন।', 'Tanzeelan mimman khalaqa alarda waalssamawati alAAula', 1, NOW(), NOW()),
(25, 5, 'ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ', 'তিনি পরম দয়াময়, আরশে সমাসীন হয়েছেন।', 'Alrrahmanu AAala alAAarshi istawa', 1, NOW(), NOW()),
(25, 6, 'لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ', 'নভোমন্ডলে, ভুমন্ডলে, এতদুভয়ের মধ্যবর্তী স্থানে এবং সিক্ত ভূগর্ভে যা আছে, তা তাঁরই।', 'Lahu ma fee alssamawati wama fee alardi wama baynahuma wama tahta alththara', 1, NOW(), NOW()),
(25, 7, 'وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى', 'যদি তুমি উচ্চকন্ঠেও কথা বল, তিনি তো গুপ্ত ও তদপেক্ষাও গুপ্ত বিষয়বস্তু জানেন।', 'Wain tajhar bialqawli fainnahu yaAAlamu alssirra waakhfa', 1, NOW(), NOW()),
(25, 8, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ', 'আল্লাহ তিনি ব্যতীত কোন উপাস্য ইলাহ নেই। সব সৌন্দর্যমন্ডিত নাম তাঁরই।', 'Allahu la ilaha illa huwa lahu alasmao alhusna', 1, NOW(), NOW()),
(25, 9, 'وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 'আপনার কাছে মূসার বৃত্তান্ত পৌঁছেছে কি।', 'Wahal ataka hadeethu moosa', 1, NOW(), NOW()),
(25, 10, 'إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى', 'তিনি যখন আগুন দেখলেন, তখন পরিবারবর্গকে বললেনঃ তোমরা এখানে অবস্থান কর আমি আগুন দেখেছি। সম্ভবতঃ আমি তা থেকে তোমাদের কাছে কিছু আগুন জালিয়ে আনতে পারব অথবা আগুনে পৌছে পথের সন্ধান পাব।', 'Ith raa naran faqala liahlihi omkuthoo innee anastu naran laAAallee ateekum minha biqabasin aw ajidu AAala alnnari hudan', 1, NOW(), NOW()),
(25, 11, 'فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ', 'অতঃপর যখন তিনি আগুনের কাছে পৌছলেন, তখন আওয়াজ আসল হে মূসা', 'Falamma ataha noodiya ya moosa', 1, NOW(), NOW()),
(25, 12, 'إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى', 'আমিই তোমার পালনকর্তা, অতএব তুমি জুতা খুলে ফেল, তুমি পবিত্র উপত্যকা তুয়ায় রয়েছ।', 'Innee ana rabbuka faikhlaAA naAAlayka innaka bialwadi almuqaddasi tuwan', 1, NOW(), NOW()),
(25, 13, 'وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ', 'এবং আমি তোমাকে মনোনীত করেছি, অতএব যা প্রত্যাদেশ করা হচ্ছে, তা শুনতে থাক।', 'Waana ikhtartuka faistamiAA lima yooha', 1, NOW(), NOW()),
(25, 14, 'إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ', 'আমিই আল্লাহ আমি ব্যতীত কোন ইলাহ নেই। অতএব আমার এবাদত কর এবং আমার স্মরণার্থে নামায কায়েম কর।', 'Innanee ana Allahu la ilaha illa ana faoAAbudnee waaqimi alssalata lithikree', 1, NOW(), NOW()),
(25, 15, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ', 'কেয়ামত অবশ্যই আসবে, আমি তা গোপন রাখতে চাই; যাতে প্রত্যেকেই তার কর্মানুযায়ী ফল লাভ করে।', 'Inna alssaAAata atiyatun akadu okhfeeha litujza kullu nafsin bima tasAAa', 1, NOW(), NOW()),
(25, 16, 'فَلَا يَصُدَّنَّكَ عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ', 'সুতরাং যে ব্যক্তি কেয়ামতে বিশ্বাস রাখে না এবং নিজ খাহেশের অনুসরণ করে, সে যেন তোমাকে তা থেকে নিবৃত্ত না করে। নিবৃত্ত হলে তুমি ধবংস হয়ে যাবে।', 'Fala yasuddannaka AAanha man la yuminu biha waittabaAAa hawahu fatarda', 1, NOW(), NOW()),
(25, 17, 'وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ', 'হে মূসা, তোমার ডানহাতে ওটা কি', 'Wama tilka biyameenika ya moosa', 1, NOW(), NOW()),
(25, 18, 'قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ', 'তিনি বললেনঃ এটা আমার লাঠি, আমি এর উপর ভর দেই এবং এর দ্বারা আমার ছাগপালের জন্যে বৃক্ষপত্র ঝেড়ে ফেলি এবং এতে আমার অন্যান্য কাজ ও চলে।', 'Qala hiya AAasaya atawakkao AAalayha waahushshu biha AAala ghanamee waliya feeha maaribu okhra', 1, NOW(), NOW()),
(25, 19, 'قَالَ أَلۡقِهَا يَٰمُوسَىٰ', 'আল্লাহ বললেনঃ হে মূসা, তুমি ওটা নিক্ষেপ কর।', 'Qala alqiha ya moosa', 1, NOW(), NOW()),
(25, 20, 'فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ', 'অতঃপর তিনি তা নিক্ষেপ করলেন, অমনি তা সাপ হয়ে ছুটাছুটি করতে লাগল।', 'Faalqaha faitha hiya hayyatun tasAAa', 1, NOW(), NOW()),
(25, 21, 'قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ', 'আল্লাহ বললেনঃ তুমি তাকে ধর এবং ভয় করো না, আমি এখনি একে পূর্বাবস্থায় ফিরিয়ে দেব।', 'Qala khuthha wala takhaf sanuAAeeduha seerataha aloola', 1, NOW(), NOW()),
(25, 22, 'وَٱضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ', 'তোমার হাত বগলে রাখ, তা বের হয়ে আসবে নির্মল উজ্জ্বল হয়ে অন্য এক নিদর্শন রূপে; কোন দোষ ছাড়াই।', 'Waodmum yadaka ila janahika takhruj baydaa min ghayri sooin ayatan okhra', 1, NOW(), NOW()),
(25, 23, 'لِنُرِيَكَ مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى', 'এটা এজন্যে যে, আমি আমার বিরাট নিদর্শনাবলীর কিছু তোমাকে দেখাই।', 'Linuriyaka min ayatina alkubra', 1, NOW(), NOW()),
(25, 24, 'ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ', 'ফেরাউনের নিকট যাও, সে দারুণ উদ্ধত হয়ে গেছে।', 'Ithhab ila firAAawna innahu tagha', 1, NOW(), NOW()),
(25, 25, 'قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي', 'মূসা বললেনঃ হে আমার পালনকর্তা আমার বক্ষ প্রশস্ত করে দিন।', 'Qala rabbi ishrah lee sadree', 1, NOW(), NOW()),
(25, 26, 'وَيَسِّرۡ لِيٓ أَمۡرِي', 'এবং আমার কাজ সহজ করে দিন।', 'Wayassir lee amree', 1, NOW(), NOW()),
(25, 27, 'وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي', 'এবং আমার জিহবা থেকে জড়তা দূর করে দিন।', 'Waohlul AAuqdatan min lisanee', 1, NOW(), NOW()),
(25, 28, 'يَفۡقَهُواْ قَوۡلِي', 'যাতে তারা আমার কথা বুঝতে পারে।', 'Yafqahoo qawlee', 1, NOW(), NOW()),
(25, 29, 'وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي', 'এবং আমার পরিবারবর্গের মধ্য থেকে আমার একজন সাহায্যকারী করে দিন।', 'WaijAAal lee wazeeran min ahlee', 1, NOW(), NOW()),
(25, 30, 'هَٰرُونَ أَخِي', 'আমার ভাই হারুনকে।', 'Haroona akhee', 1, NOW(), NOW()),
(25, 31, 'ٱشۡدُدۡ بِهِۦٓ أَزۡرِي', 'তার মাধ্যমে আমার কোমর মজবুত করুন।', 'Oshdud bihi azree', 1, NOW(), NOW()),
(25, 32, 'وَأَشۡرِكۡهُ فِيٓ أَمۡرِي', 'এবং তাকে আমার কাজে অংশীদার করুন।', 'Waashrikhu fee amree', 1, NOW(), NOW()),
(25, 33, 'كَيۡ نُسَبِّحَكَ كَثِيرٗا', 'যাতে আমরা বেশী করে আপনার পবিত্রতা ও মহিমা ঘোষনা করতে পারি।', 'Kay nusabbihaka katheeran', 1, NOW(), NOW()),
(25, 34, 'وَنَذۡكُرَكَ كَثِيرًا', 'এবং বেশী পরিমাণে আপনাকে স্মরণ করতে পারি।', 'Wanathkuraka katheeran', 1, NOW(), NOW()),
(25, 35, 'إِنَّكَ كُنتَ بِنَا بَصِيرٗا', 'আপনি তো আমাদের অবস্থা সবই দেখছেন।', 'Innaka kunta bina baseeran', 1, NOW(), NOW()),
(25, 36, 'قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ', 'আল্লাহ বললেনঃ হে মূসা, তুমি যা চেয়েছ তা তোমাকে দেয়া হল।', 'Qala qad ooteeta sulaka ya moosa', 1, NOW(), NOW()),
(25, 37, 'وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ', 'আমি তোমার প্রতি আরও একবার অনুগ্রহ করেছিলাম।', 'Walaqad mananna AAalayka marratan okhra', 1, NOW(), NOW()),
(25, 38, 'إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'যখন আমি তোমার মাতাকে নির্দেশ দিয়েছিলাম যা অতঃপর বর্ণিত হচ্ছে।', 'Ith awhayna ila ommika ma yooha', 1, NOW(), NOW()),
(25, 39, 'أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ', 'যে, তুমি (মূসাকে) সিন্দুকে রাখ, অতঃপর তা দরিয়ায় ভাসিয়ে দাও, অতঃপর দরিয়া তাকে তীরে ঠেলে দেবে। তাকে আমার শক্র ও তার শক্র উঠিয়ে নেবে। আমি তোমার প্রতি মহব্বত সঞ্চারিত করেছিলাম আমার নিজের পক্ষ থেকে, যাতে তুমি আমার দৃষ্টির সামনে প্রতি পালিত হও।', 'Ani iqthifeehi fee alttabooti faiqthifeehi fee alyammi falyulqihi alyammu bialssahili yakhuthhu AAaduwwun lee waAAaduwwun lahu waalqaytu AAalayka mahabbatan minnee walitusnaAAa AAala AAaynee', 1, NOW(), NOW()),
(25, 40, 'إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ', 'যখন তোমার ভগিনী এসে বললঃ আমি কি তোমাদেরকে বলে দেব কে তাকে লালন পালন করবে। অতঃপর আমি তোমাকে তোমার মাতার কাছে ফিরিয়ে দিলাম, যাতে তার চক্ষু শীতল হয় এবং দুঃখ না পায়। তুমি এক ব্যক্তিকে হত্যা করেছিলে, অতঃপর আমি তোমাকে এই দুশ্চিন্তা থেকে মুক্তি দেই; আমি তোমাকে অনেক পরীক্ষা করেছি। অতঃপর তুমি কয়েক বছর মাদইয়ান বাসীদের মধ্যে অবস্থান করেছিলে; হে মূসা, অতঃপর তুমি নির্ধারিত সময়ে এসেছ।', 'Ith tamshee okhtuka fataqoolu hal adullukum AAala man yakfuluhu farajaAAnaka ila ommika kay taqarra AAaynuha wala tahzana waqatalta nafsan fanajjaynaka mina alghammi wafatannaka futoonan falabithta sineena fee ahli madyana thumma jita AAala qadarin ya moosa', 1, NOW(), NOW()),
(25, 41, 'وَٱصۡطَنَعۡتُكَ لِنَفۡسِي', 'এবং আমি তোমাকে আমার নিজের জন্য তৈরী করে নিয়েছি।', 'WaistanaAAtuka linafsee', 1, NOW(), NOW()),
(25, 42, 'ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي', 'তুমি ও তোমার ভাই আমার নিদর্শনাবলীসহ যাও এবং আমার স্মরণে শৈথিল্য করো না।', 'Ithhab anta waakhooka biayatee wala taniya fee thikree', 1, NOW(), NOW()),
(25, 43, 'ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ', 'তোমরা উভয়ে ফেরআউনের কাছে যাও সে খুব উদ্ধত হয়ে গেছে।', 'Ithhaba ila firAAawna innahu tagha', 1, NOW(), NOW()),
(25, 44, 'فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ', 'অতঃপর তোমরা তাকে নম্র কথা বল, হয়তো সে চিন্তা-ভাবনা করবে অথবা ভীত হবে।', 'Faqoola lahu qawlan layyinan laAAallahu yatathakkaru aw yakhsha', 1, NOW(), NOW()),
(25, 45, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ', 'তারা বললঃ হে আমাদের পালনকর্তা, আমরা আশঙ্কা করি যে, সে আমাদের প্রতি জুলুম করবে কিংবা উত্তেজিত হয়ে উঠবে।', 'Qala rabbana innana nakhafu an yafruta AAalayna aw an yatgha', 1, NOW(), NOW()),
(25, 46, 'قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ', 'আল্লাহ বললেনঃ তোমরা ভয় করো না, আমি তোমাদের সাথে আছি, আমি শুনি ও দেখি।', 'Qala la takhafa innanee maAAakuma asmaAAu waara', 1, NOW(), NOW()),
(25, 47, 'فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةٖ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ', 'অতএব তোমরা তার কাছে যাও এবং বলঃ আমরা উভয়েই তোমার পালনকর্তার প্রেরিত রসূল, অতএব আমাদের সাথে বনী ইসরাঈলকে যেতে দাও এবং তাদেরকে নিপীড়ন করো না। আমরা তোমার পালনকর্তার কাছ থেকে নিদর্শন নিয়ে তোমার কাছে আগমন করেছি। এবং যে সৎপথ অনুসরণ করে, তার প্রতি শান্তি।', 'Fatiyahu faqoola inna rasoola rabbika faarsil maAAana banee israeela wala tuAAaththibhum qad jinaka biayatin min rabbika waalssalamu AAala mani ittabaAAa alhuda', 1, NOW(), NOW()),
(25, 48, 'إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', 'আমরা ওহী লাভ করেছি যে, যে ব্যক্তি মিথ্যারোপ করে এবং মুখ ফিরিয়ে নেয়, তার উপর আযাব পড়বে।', 'Inna qad oohiya ilayna anna alAAathaba AAala man kaththaba watawalla', 1, NOW(), NOW()),
(25, 49, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', 'সে বললঃ তবে হে মূসা, তোমাদের পালনকর্তা কে', 'Qala faman rabbukuma ya moosa', 1, NOW(), NOW()),
(25, 50, 'قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ', 'মূসা বললেনঃ আমাদের পালনকর্তা তিনি, যিনি প্রত্যেক বস্তুকে তার যোগ্য আকৃতি দান করেছেন, অতঃপর পথপ্রদর্শন করেছেন।', 'Qala rabbuna allathee aAAta kulla shayin khalqahu thumma hada', 1, NOW(), NOW()),
(25, 51, 'قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ', 'ফেরাউন বললঃ তাহলে অতীত যুগের লোকদের অবস্থা কি', 'Qala fama balu alqurooni aloola', 1, NOW(), NOW()),
(25, 52, 'قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبٖۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى', 'মূসা বললেনঃ তাদের খবর আমার পালনকর্তার কাছে লিখিত আছে। আমার পালনকর্তা ভ্রান্ত হন না এং বিস্মৃতও হন না।', 'Qala AAilmuha AAinda rabbee fee kitabin la yadillu rabbee wala yansa', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(25, 53, 'ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدٗا وَسَلَكَ لَكُمۡ فِيهَا سُبُلٗا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّن نَّبَاتٖ شَتَّىٰ', 'তিনি তোমাদের জন্যে পৃথিবীকে শয্যা করেছেন এবং তাতে চলার পথ করেছেন, আকাশ থেকে বৃষ্টি বর্ষণ করেছেন এবং তা দ্বারা আমি বিভিন্ন প্রকার উদ্ভিদ উৎপন্ন করেছি।', 'Allathee jaAAala lakumu alarda mahdan wasalaka lakum feeha subulan waanzala mina alssamai maan faakhrajna bihi azwajan min nabatin shatta', 1, NOW(), NOW()),
(25, 54, 'كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ', 'তোমরা আহার কর এবং তোমাদের চতুস্পদ জন্তু চরাও। নিশ্চয় এতে বিবেক বানদের জন্যে নিদর্শন রয়েছে।', 'Kuloo wairAAaw anAAamakum inna fee thalika laayatin liolee alnnuha', 1, NOW(), NOW()),
(25, 55, '۞مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ', 'এ মাটি থেকেই আমি তোমাদেরকে সৃজন করেছি, এতেই তোমাদেরকে ফিরিয়ে দিব এবং পুনরায় এ থেকেই আমি তোমাদেরকে উত্থিত করব।', 'Minha khalaqnakum wafeeha nuAAeedukum waminha nukhrijukum taratan okhra', 1, NOW(), NOW()),
(25, 56, 'وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', 'আমি ফেরাউনকে আমার সব নিদর্শন দেখিয়ে দিয়েছি, অতঃপর সে মিথ্যা আরোপ করেছে এবং অমান্য করেছে।', 'Walaqad araynahu ayatina kullaha fakaththaba waaba', 1, NOW(), NOW()),
(25, 57, 'قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ', 'সে বললঃ হে মূসা, তুমি কি যাদুর জোরে আমাদেরকে দেশ থেকে বহিষ্কার করার জন্যে আগমন করেছ', 'Qala ajitana litukhrijana min ardina bisihrika ya moosa', 1, NOW(), NOW()),
(25, 58, 'فَلَنَأۡتِيَنَّكَ بِسِحۡرٖ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدٗا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانٗا سُوٗى', 'অতএব, আমরাও তোমার মোকাবেলায় তোমার নিকট অনুরূপ যাদু উপস্থিত করব। সুতরাং আমাদের ও তোমার মধ্যে একটি ওয়াদার দিন ঠিক কর, যার খেলাফ আমরাও করব না এবং তুমিও করবে না একটি পরিষ্কার প্রান্তরে।', 'Falanatiyannaka bisihrin mithlihi faijAAal baynana wabaynaka mawAAidan la nukhlifuhu nahnu wala anta makanan suwan', 1, NOW(), NOW()),
(25, 59, 'قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحٗى', 'মূসা বললঃ তোমাদের ওয়াদার দিন উৎসবের দিন এবং পূর্বাহেߠলোকজন সমবেত হবে।', 'Qala mawAAidukum yawmu alzzeenati waan yuhshara alnnasu duhan', 1, NOW(), NOW()),
(25, 60, 'فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ', 'অতঃপর ফেরাউন প্রস্থান করল এবং তার সব কলাকৌশল জমা করল অতঃপর উপস্থিত হল।', 'Fatawalla firAAawnu fajamaAAa kaydahu thumma ata', 1, NOW(), NOW()),
(25, 61, 'قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبٗا فَيُسۡحِتَكُم بِعَذَابٖۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ', 'মূসা (আঃ) তাদেরকে বললেনঃ দুর্ভাগ্য তোমাদের; তোমরা আল্লাহর প্রতি মিথ্যা আরোপ করো না। তাহলে তিনি তোমাদেরকে আযাব দ্বারা ধবংস করে দেবেন। যে মিথ্যা উদভাবন করে, সেই বিফল মনোরথ হয়েছে।', 'Qala lahum moosa waylakum la taftaroo AAala Allahi kathiban fayushitakum biAAathabin waqad khaba mani iftara', 1, NOW(), NOW()),
(25, 62, 'فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ', 'অতঃপর তারা তাদের কাজে নিজেদের মধ্যে বিতর্ক করল এবং গোপনে পরামর্শ করল।', 'FatanazaAAoo amrahum baynahum waasarroo alnnajwa', 1, NOW(), NOW()),
(25, 63, 'قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ', 'তারা বললঃ এই দুইজন নিশ্চিতই যাদুকর, তারা তাদের যাদু দ্বারা তোমাদেরকে তোমাদের দেশ থেকে বহিস্কার করতে চায় এবং তোমাদের উৎকৃষ্ট জীবন ব্যবস্থা রহিত করতে চায়।', 'Qaloo in hathani lasahirani yureedani an yukhrijakum min ardikum bisihrihima wayathhaba bitareeqatikumu almuthla', 1, NOW(), NOW()),
(25, 64, 'فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفّٗاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ', 'অতএব, তোমরা তোমাদের কলাকৌশল সুসংহত কর, অতঃপর সারিবদ্ধ হয়ে আস। আজ যে জয়ী হবে, সেই সফলকাম হবে।', 'FaajmiAAoo kaydakum thumma itoo saffan waqad aflaha alyawma mani istaAAla', 1, NOW(), NOW()),
(25, 65, 'قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ', 'তারা বললঃ হে মূসা, হয় তুমি নিক্ষেপ কর, না হয় আমরা প্রথমে নিক্ষেপ করি।', 'Qaloo ya moosa imma an tulqiya waimma an nakoona awwala man alqa', 1, NOW(), NOW()),
(25, 66, 'قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ', 'মূসা বললেনঃ বরং তোমরাই নিক্ষেপ কর। তাদের যাদুর প্রভাবে হঠাৎ তাঁর মনে হল, যেন তাদের রশিগুলো ও লাঠিগুলো চুটাছুটি করছে।', 'Qala bal alqoo faitha hibaluhum waAAisiyyuhum yukhayyalu ilayhi min sihrihim annaha tasAAa', 1, NOW(), NOW()),
(25, 67, 'فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةٗ مُّوسَىٰ', 'অতঃপর মূসা মনে মনে কিছুটা ভীতি অনুভব করলেন।', 'Faawjasa fee nafsihi kheefatan moosa', 1, NOW(), NOW()),
(25, 68, 'قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ', 'আমি বললামঃ ভয় করো না, তুমি বিজয়ী হবে।', 'Qulna la takhaf innaka anta alaAAla', 1, NOW(), NOW()),
(25, 69, 'وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرٖۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ', 'তোমার ডান হাতে যা আছে তুমি তা নিক্ষেপ কর। এটা যা কিছু তারা করেছে তা গ্রাস করে ফেলবে। তারা যা করেছে তা তো কেবল যাদুকরের কলাকৌশল। যাদুকর যেখানেই থাকুক, সফল হবে না।', 'Waalqi ma fee yameenika talqaf ma sanaAAoo innama sanaAAoo kaydu sahirin wala yuflihu alssahiru haythu ata', 1, NOW(), NOW()),
(25, 70, 'فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدٗا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', 'অতঃপর যাদুকররা সেজদায় পড়ে গেল। তারা বললঃ আমরা হারুন ও মূসার পালনকর্তার প্রতি বিশ্বাস স্থাপন করলাম।', 'Faolqiya alssaharatu sujjadan qaloo amanna birabbi haroona wamoosa', 1, NOW(), NOW()),
(25, 71, 'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابٗا وَأَبۡقَىٰ', 'ফেরাউন বললঃ আমার অনুমতি দানের পূর্বেই? তোমরা কি তার প্রতি বিশ্বাস স্থাপন করলে; দেখছি সেই তোমাদের প্রধান, সে তোমাদেরকে যাদু শিক্ষা দিয়েছে। অতএব আমি অবশ্যই তোমাদের হস্তপদ বিপরীত দিক থেকে কর্তন করব এবং আমি তোমাদেরকে খর্জুর বৃক্ষের কান্ডে শূলে চড়াব এবং তোমরা নিশ্চিত রূপেই জানতে পারবে আমাদের মধ্যে কার আযাব কঠোরতর এবং অধিক্ষণ স্থায়ী।', 'Qala amantum lahu qabla an athana lakum innahu lakabeerukumu allathee AAallamakumu alssihra falaoqattiAAanna aydiyakum waarjulakum min khilafin walaosallibannakum fee juthooAAi alnnakhli walataAAlamunna ayyuna ashaddu AAathaban waabqa', 1, NOW(), NOW()),
(25, 72, 'قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ', 'যাদুকররা বললঃ আমাদের কাছে যে, সুস্পষ্ট প্রমাণ এসেছে তার উপর এবং যিনি আমাদের কে সৃষ্টি করেছেন, তাঁর উপর আমরা কিছুতেই তোমাকে প্রাধান্য দেব না। অতএব, তুমি যা ইচ্ছা করতে পার। তুমি তো শুধু এই পার্থিব জীবনেই যা করার করবে।', 'Qaloo lan nuthiraka AAala ma jaana mina albayyinati waallathee fatarana faiqdi ma anta qadin innama taqdee hathihi alhayata alddunya', 1, NOW(), NOW()),
(25, 73, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرٞ وَأَبۡقَىٰٓ', 'আমরা আমাদের পালনকর্তার প্রতি বিশ্বাস স্থাপন করেছি যাতে তিনি আমাদের পাপ এবং তুমি আমাদেরকে যে যাদু করতে বাধ্য করেছ, তা মার্জনা করেন। আল্লাহ শ্রেষ্ঠ ও চিরস্থায়ী।', 'Inna amanna birabbina liyaghfira lana khatayana wama akrahtana AAalayhi mina alssihri waAllahu khayrun waabqa', 1, NOW(), NOW()),
(25, 74, 'إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمٗا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ', 'নিশ্চয়ই যে তার পালনকর্তার কাছে অপরাধী হয়ে আসে, তার জন্য রয়েছে জাহান্নাম। সেখানে সে মরবে না এবং বাঁচবেও না।', 'Innahu man yati rabbahu mujriman fainna lahu jahannama la yamootu feeha wala yahya', 1, NOW(), NOW()),
(25, 75, 'وَمَن يَأۡتِهِۦ مُؤۡمِنٗا قَدۡ عَمِلَ ٱلصَّـٰلِحَٰتِ فَأُوْلَـٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ', 'আর যারা তাঁর কাছে আসে এমন ঈমানদার হয়ে যায় সৎকর্ম সম্পাদন করেছে, তাদের জন্যে রয়েছে সুউচ্চ মর্তবা।', 'Waman yatihi muminan qad AAamila alssalihati faolaika lahumu alddarajatu alAAula', 1, NOW(), NOW()),
(25, 76, 'جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', 'বসবাসের এমন পুষ্পোদ্যান রয়েছে যার তলদেশে দিয়ে নির্ঝরিণীসমূহ প্রবাহিত হয়। সেখানে তারা চিরকাল থাকবে এটা তাদেরই পুরস্কার, যারা পবিত্র হয়।', 'Jannatu AAadnin tajree min tahtiha alanharu khalideena feeha wathalika jazao man tazakka', 1, NOW(), NOW()),
(25, 77, 'وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقٗا فِي ٱلۡبَحۡرِ يَبَسٗا لَّا تَخَٰفُ دَرَكٗا وَلَا تَخۡشَىٰ', 'আমি মূসা প্রতি এই মর্মে ওহী করলাম যে, আমার বান্দাদেরকে নিয়ে রাত্রিযোগে বের হয়ে যাও এবং তাদের জন্যে সমুদ্রে শুষ্কপথ নির্মাণ কর। পেছন থেকে এসে তোমাদের ধরে ফেলার আশঙ্কা করো না এবং পানিতে ডুবে যাওয়ার ভয় করো না।', 'Walaqad awhayna ila moosa an asri biAAibadee faidrib lahum tareeqan fee albahri yabasan la takhafu darakan wala takhsha', 1, NOW(), NOW()),
(25, 78, 'فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ', 'অতঃপর ফেরাউন তার সৈন্যবাহিনী নিয়ে তাদের পশ্চাদ্ধাবন করল এবং সমুদ্র তাদেরকে সম্পূর্ণরূপে নিমজ্জত করল।', 'FaatbaAAahum firAAawnu bijunoodihi faghashiyahum mina alyammi ma ghashiyahum', 1, NOW(), NOW()),
(25, 79, 'وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ', 'ফেরআউন তার সম্প্রদায়কে বিভ্রান্ত করেছিল এবং সৎপথ দেখায়নি।', 'Waadalla firAAawnu qawmahu wama hada', 1, NOW(), NOW()),
(25, 80, 'يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ', 'হে বনী-ইসরাঈল! আমি তোমাদেরকে তোমাদের শক্রুর কবল থেকে উদ্ধার করেছি, তুর পাহাড়ের দক্ষিণ পার্শ্বে তোমাদেরকে প্রতিশ্রুতি দান করেছি এবং তোমাদের কাছে ‘মান্না’ ও ‘সালওয়া’ নাযিল করেছি।', 'Ya banee israeela qad anjaynakum min AAaduwwikum wawaAAadnakum janiba alttoori alaymana wanazzalna AAalaykumu almanna waalssalwa', 1, NOW(), NOW()),
(25, 81, 'كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ', 'বলেছিঃ আমার দেয়া পবিত্র বস্তুসমূহ খাও এবং এতে সীমালংঘন করো না, তা হলে তোমাদের উপর আমার ক্রোধ নেমে আসবে এবং যার উপর আমার ক্রোধ নেমে আসে সে ধবংস হয়ে যায়।', 'Kuloo min tayyibati ma razaqnakum wala tatghaw feehi fayahilla AAalaykum ghadabee waman yahlil AAalayhi ghadabee faqad hawa', 1, NOW(), NOW()),
(25, 82, 'وَإِنِّي لَغَفَّارٞ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا ثُمَّ ٱهۡتَدَىٰ', 'আর যে তওবা করে, ঈমান আনে এবং সৎকর্ম করে অতঃপর সৎপথে অটল থাকে, আমি তার প্রতি অবশ্যই ক্ষমাশীল।', 'Wainnee laghaffarun liman taba waamana waAAamila salihan thumma ihtada', 1, NOW(), NOW()),
(25, 83, '۞وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ', 'হে মূসা, তোমার সম্প্রদায়কে পেছনে ফেলে তুমি ত্বরা করলে কেন', 'Wama aAAjalaka AAan qawmika ya moosa', 1, NOW(), NOW()),
(25, 84, 'قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ', 'তিনি বললেনঃ এই তো তারা আমার পেছনে আসছে এবং হে আমার পালনকর্তা, আমি তাড়াতাড়ি তোমার কাছে এলাম, যাতে তুমি সন্তুষ্ট হও।', 'Qala hum olai AAala atharee waAAajiltu ilayka rabbi litarda', 1, NOW(), NOW()),
(25, 85, 'قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ', 'বললেনঃ আমি তোমার সম্প্রদায়কে পরীক্ষা করেছি তোমার পর এবং সামেরী তাদেরকে পথভ্রষ্ট করেছে।', 'Qala fainna qad fatanna qawmaka min baAAdika waadallahumu alssamiriyyu', 1, NOW(), NOW()),
(25, 86, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗاۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبٞ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي', 'অতঃপর মূসা তাঁর সম্প্রদায়ের কাছে ফিরে গেলেন ক্রদ্ধ ও অনুতপ্ত অবস্থায়। তিনি বললেনঃ হে আমার সম্প্রদায়, তোমাদের পালনকর্তা কি তোমাদেরকে একটি উত্তম প্রতিশ্রুতি দেননি? তবে কি প্রতিশ্রুতির সময়কাল তোমাদের কাছে দীর্ঘ হয়েছে, না তোমরা চেয়েছ যে, তোমাদের উপর তোমাদের পালনকর্তার ক্রোধ নেমে আসুক, যে কারণে তোমরা আমার সাথে কৃত ওয়াদা ভঙ্গ করলে', 'FarajaAAa moosa ila qawmihi ghadbana asifan qala ya qawmi alam yaAAidkum rabbukum waAAdan hasanan afatala AAalaykumu alAAahdu am aradtum an yahilla AAalaykum ghadabun min rabbikum faakhlaftum mawAAidee', 1, NOW(), NOW()),
(25, 87, 'قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارٗا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ', 'তারা বললঃ আমরা তোমার সাথে কৃত ওয়াদা স্বেচ্ছায় ভঙ্গ করিনি; কিন্তু আমাদের উপর ফেরউনীদের অলংকারের বোঝা চাপিয়ে দেয়া হয়েছিল। অতঃপর আমরা তা নিক্ষেপ করে দিয়েছি। এমনি ভাবে সামেরীও নিক্ষেপ করেছে।', 'Qaloo ma akhlafna mawAAidaka bimalkina walakinna hummilna awzaran min zeenati alqawmi faqathafnaha fakathalika alqa alssamiriyyu', 1, NOW(), NOW()),
(25, 88, 'فَأَخۡرَجَ لَهُمۡ عِجۡلٗا جَسَدٗا لَّهُۥ خُوَارٞ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ', 'অতঃপর সে তাদের জন্য তৈরী করে বের করল একটি গো-বৎস, একটা দেহ, যার মধ্যে গরুর শব্দ ছিল। তারা বললঃ এটা তোমাদের উপাস্য এবং মূসার ও উপাস্য, অতঃপর মূসা ভুলে গেছে।', 'Faakhraja lahum AAijlan jasadan lahu khuwarun faqaloo hatha ilahukum wailahu moosa fanasiya', 1, NOW(), NOW()),
(25, 89, 'أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلٗا وَلَا يَمۡلِكُ لَهُمۡ ضَرّٗا وَلَا نَفۡعٗا', 'তারা কি দেখে না যে, এটা তাদের কোন কথার উত্তর দেয় না এবং তারে কোন ক্ষতি ও উপকার করার ক্ষমতাও রাখে না', 'Afala yarawna alla yarjiAAu ilayhim qawlan wala yamliku lahum darran wala nafAAan', 1, NOW(), NOW()),
(25, 90, 'وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي', 'হারুন তাদেরকে পুর্বেই বলেছিলেনঃ হে আমার কওম, তোমরা তো এই গো-বৎস দ্বারা পরীক্ষায় নিপতিত হয়েছ এবং তোমাদের পালনকর্তা দয়াময়। অতএব, তোমরা আমার অনুসরণ কর এবং আমার আদেশ মেনে চল।', 'Walaqad qala lahum haroonu min qablu ya qawmi innama futintum bihi wainna rabbakumu alrrahmanu faittabiAAoonee waateeAAoo amree', 1, NOW(), NOW()),
(25, 91, 'قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ', 'তারা বললঃ মূসা আমাদের কাছে ফিরে আসা পর্যন্ত আমরা সদাসর্বদা এর সাথেই সংযুক্ত হয়ে বসে থাকব।', 'Qaloo lan nabraha AAalayhi AAakifeena hatta yarjiAAa ilayna moosa', 1, NOW(), NOW()),
(25, 92, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ', 'মূসা বললেনঃ হে হারুন, তুমি যখন তাদেরকে পথ ভ্রষ্ট হতে দেখলে, তখন তোমাকে কিসে নিবৃত্ত করল', 'Qala ya haroonu ma manaAAaka ith raaytahum dalloo', 1, NOW(), NOW()),
(25, 93, 'أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي', 'আমার পদাঙ্ক অনুসরণ করা থেকে? তবে তুমি কি আমার আদেশ অমান্য করেছ', 'Alla tattabiAAani afaAAasayta amree', 1, NOW(), NOW()),
(25, 94, 'قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي', 'তিনি বললেনঃ হে আমার জননী-তনয়, আমার শ্মশ্রু ও মাথার চুল ধরে আকর্ষণ করো না; আমি আশঙ্কা করলাম যে, তুমি বলবেঃ তুমি বনী-ইসরাঈলের মধ্যে বিভেদ সৃষ্টি করেছ এবং আমার কথা স্মরণে রাখনি।', 'Qala ya bna omma la takhuth bilihyatee wala birasee innee khasheetu an taqoola farraqta bayna banee israeela walam tarqub qawlee', 1, NOW(), NOW()),
(25, 95, 'قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ', 'মূসা বললেন হে সামেরী, এখন তোমার ব্যাপার কি', 'Qala fama khatbuka ya samiriyyu', 1, NOW(), NOW()),
(25, 96, 'قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةٗ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي', 'সে বললঃ আমি দেখলাম যা অন্যেরা দেখেনি। অতঃপর আমি সেই প্রেরিত ব্যক্তির পদচিহেߦ#2480; নীচ থেকে এক মুঠি মাটি নিয়ে নিলাম। অতঃপর আমি তা নিক্ষেপ করলাম। আমাকে আমার মন এই মন্ত্রণাই দিল।', 'Qala basurtu bima lam yabsuroo bihi faqabadtu qabdatan min athari alrrasooli fanabathtuha wakathalika sawwalat lee nafsee', 1, NOW(), NOW()),
(25, 97, 'قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدٗا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا', 'মূসা বললেনঃ দূর হ, তোর জন্য সারা জীবন এ শাস্তিই রইল যে, তুই বলবি; আমাকে স্পর্শ করো না, এবং তোর জন্য একটি নির্দিষ্ট ওয়াদা আছে, যার ব্যতিক্রম হবে না। তুই তোর সেই ইলাহের প্রতি লক্ষ্য কর, যাকে তুই ঘিরে থাকতি। আমরা সেটি জালিয়ে দেবই। অতঃপর একে বিক্ষিপ্ত করে সাগরে ছড়িয়ে দেবই।', 'Qala faithhab fainna laka fee alhayati an taqoola la misasa wainna laka mawAAidan lan tukhlafahu waonthur ila ilahika allathee thalta AAalayhi AAakifan lanuharriqannahu thumma lanansifannahu fee alyammi nasfan', 1, NOW(), NOW()),
(25, 98, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمٗا', 'তোমাদের ইলাহ তো কেবল আল্লাহই, যিনি ব্যতীত অন্য কোন ইলাহ নেই। সব বিষয় তাঁর জ্ঞানের পরিধিভুক্ত।', 'Innama ilahukumu Allahu allathee la ilaha illa huwa wasiAAa kulla shayin AAilman', 1, NOW(), NOW()),
(25, 99, 'كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرٗا', 'এমনিভাবে আমি পূর্বে যা ঘটেছে, তার সংবাদ আপনার কাছে বর্ণনা করি। আমি আমার কাছ থেকে আপনাকে দান করেছি পড়ার গ্রন্থ।', 'Kathalika naqussu AAalayka min anbai ma qad sabaqa waqad ataynaka min ladunna thikran', 1, NOW(), NOW()),
(25, 100, 'مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا', 'যে এ থেকে মুখ ফিরিয়ে নেবে, সে কেয়ামতের দিন বোঝা বহন করবে।', 'Man aAArada AAanhu fainnahu yahmilu yawma alqiyamati wizran', 1, NOW(), NOW()),
(25, 101, 'خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلٗا', 'তারা তাতে চিরকাল থাকবে এবং কেয়ামতের দিন এই বোঝা তাদের জন্যে মন্দ হবে।', 'Khalideena feehi wasaa lahum yawma alqiyamati himlan', 1, NOW(), NOW()),
(25, 102, 'يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ زُرۡقٗا', 'যেদিন সিঙ্গায় ফূৎকার দেয়া হবে, সেদিন আমি অপরাধীদেরকে সমবেত করব নীল চক্ষু অবস্থায়।', 'Yawma yunfakhu fee alssoori wanahshuru almujrimeena yawmaithin zurqan', 1, NOW(), NOW()),
(25, 103, 'يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرٗا', 'তারা চুপিসারে পরস্পরে বলাবলি করবেঃ তোমরা মাত্র দশ দিন অবস্থান করেছিলে।', 'Yatakhafatoona baynahum in labithtum illa AAashran', 1, NOW(), NOW()),
(25, 104, 'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمٗا', 'তারা কি বলে তা আমি ভালোভাবে জানি। তাদের মধ্যে যে, অপেক্ষাকৃত উত্তম পথের অনুসারী সে বলবেঃ তোমরা মাত্র একদিন অবস্থান করেছিলে।', 'Nahnu aAAlamu bima yaqooloona ith yaqoolu amthaluhum tareeqatan in labithtum illa yawman', 1, NOW(), NOW()),
(25, 105, 'وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفٗا', 'তারা আপনাকে পাহাড় সম্পর্কে প্রশ্ন করা। অতএব, আপনি বলুনঃ আমার পালনকর্তা পহাড়সমূহকে সমূলে উৎপাটন করে বিক্ষিপ্ত করে দিবেন।', 'Wayasaloonaka AAani aljibali faqul yansifuha rabbee nasfan', 1, NOW(), NOW()),
(25, 106, 'فَيَذَرُهَا قَاعٗا صَفۡصَفٗا', 'অতঃপর পৃথিবীকে মসৃণ সমতলভূমি করে ছাড়বেন।', 'Fayatharuha qaAAan safsafan', 1, NOW(), NOW()),
(25, 107, 'لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا', 'তুমি তাতে মোড় ও টিলা দেখবে না।', 'La tara feeha AAiwajan wala amtan', 1, NOW(), NOW()),
(25, 108, 'يَوۡمَئِذٖ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسٗا', 'সেই দিন তারা আহবানকারীর অনুসরণ করবে, যার কথা এদিক-সেদিক হবে না এবং দয়াময় আল্লাহর ভয়ে সব শব্দ ক্ষীণ হয়ে যাবে। সুতরাং মৃদু গুঞ্জন ব্যতীত তুমি কিছুই শুনবে না।', 'Yawmaithin yattabiAAoona alddaAAiya la AAiwaja lahu wakhashaAAati alaswatu lilrrahmani fala tasmaAAu illa hamsan', 1, NOW(), NOW()),
(25, 109, 'يَوۡمَئِذٖ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلٗا', 'দয়াময় আল্লাহ যাকে অনুমতি দেবেন এবং যার কথায় সন্তুষ্ট হবেন সে ছাড়া কারও সুপারিশ সেদিন কোন উপকারে আসবে না।', 'Yawmaithin la tanfaAAu alshshafaAAatu illa man athina lahu alrrahmanu waradiya lahu qawlan', 1, NOW(), NOW()),
(25, 110, 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمٗا', 'তিনি জানেন যা কিছু তাদের সামনে ও পশ্চাতে আছে এবং তারা তাকে জ্ঞান দ্বারা আয়ত্ত করতে পারে না।', 'YaAAlamu ma bayna aydeehim wama khalfahum wala yuheetoona bihi AAilman', 1, NOW(), NOW()),
(25, 111, '۞وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمٗا', 'সেই চিরঞ্জীব চিরস্থায়ীর সামনে সব মুখমন্ডল অবনমিত হবে এবং সে ব্যর্থ হবে যে জুলুমের বোঝা বহন করবে।', 'WaAAanati alwujoohu lilhayyi alqayyoomi waqad khaba man hamala thulman', 1, NOW(), NOW()),
(25, 112, 'وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا يَخَافُ ظُلۡمٗا وَلَا هَضۡمٗا', 'যে ঈমানদার অবস্থায় সৎকর্ম সম্পাদন করে, সে জুলুম ও ক্ষতির আশঙ্কা করবে না।', 'Waman yaAAmal mina alssalihati wahuwa muminun fala yakhafu thulman wala hadman', 1, NOW(), NOW()),
(25, 113, 'وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيّٗا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرٗا', 'এমনিভাবে আমি আরবী ভাষায় কোরআন নাযিল করেছি এবং এতে নানাভাবে সতর্কবাণী ব্যক্ত করেছি, যাতে তারা আল্লাহভীরু হয় অথবা তাদের অন্তরে চিন্তার খোরাক যোগায়।', 'Wakathalika anzalnahu quranan AAarabiyyan wasarrafna feehi mina alwaAAeedi laAAallahum yattaqoona aw yuhdithu lahum thikran', 1, NOW(), NOW()),
(25, 114, 'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا', 'সত্যিকার অধীশ্বর আল্লাহ মহান। আপনার প্রতি আল্লাহর ওহী সম্পুর্ণ হওয়ার পূর্বে আপনি কোরআন গ্রহণের ব্যপারে তাড়াহুড়া করবেন না এবং বলুনঃ হে আমার পালনকর্তা, আমার জ্ঞান বৃদ্ধি করুন।', 'FataAAala Allahu almaliku alhaqqu wala taAAjal bialqurani min qabli an yuqda ilayka wahyuhu waqul rabbi zidnee AAilman', 1, NOW(), NOW()),
(25, 115, 'وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمٗا', 'আমি ইতিপূর্বে আদমকে নির্দেশ দিয়েছিলাম। অতঃপর সে ভুলে গিয়েছিল এবং আমি তার মধ্যে দৃঢ়তা পাইনি।', 'Walaqad AAahidna ila adama min qablu fanasiya walam najid lahu AAazman', 1, NOW(), NOW()),
(25, 116, 'وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ', 'যখন আমি ফেরেশতাদেরকে বললামঃ তোমরা আদমকে সেজদা কর, তখন ইবলীস ব্যতীত সবাই সেজদা করল। সে অমান্য করল।', 'Waith qulna lilmalaikati osjudoo liadama fasajadoo illa ibleesa aba', 1, NOW(), NOW()),
(25, 117, 'فَقُلۡنَا يَـٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوّٞ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ', 'অতঃপর আমি বললামঃ হে আদম, এ তোমার ও তোমার স্ত্রীর শত্রু, সুতরাং সে যেন বের করে না দেয় তোমাদের জান্নাত থেকে। তাহলে তোমরা কষ্টে পতিত হবে।', 'Faqulna ya adamu inna hatha AAaduwwun laka walizawjika fala yukhrijannakuma mina aljannati fatashqa', 1, NOW(), NOW()),
(25, 118, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ', 'তোমাকে এই দেয়া হল যে, তুমি এতে ক্ষুধার্ত হবে না এবং বস্ত্রহীণ হবে না।', 'Inna laka alla tajooAAa feeha wala taAAra', 1, NOW(), NOW()),
(25, 119, 'وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ', 'এবং তোমার পিপাসাও হবে না এবং রৌদ্রেও কষ্ট পাবে না।', 'Waannaka la tathmao feeha wala tadha', 1, NOW(), NOW()),
(25, 120, 'فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَـٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ', 'অতঃপর শয়তান তাকে কুমন্ত্রনা দিল, বললঃ হে আদম, আমি কি তোমাকে বলে দিব অনন্তকাল জীবিত থাকার বৃক্ষের কথা এবং অবিনশ্বর রাজত্বের কথা', 'Fawaswasa ilayhi alshshaytanu qala ya adamu hal adulluka AAala shajarati alkhuldi wamulkin la yabla', 1, NOW(), NOW()),
(25, 121, 'فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', 'অতঃপর তারা উভয়েই এর ফল ভক্ষণ করল, তখন তাদের সামনে তাদের লজ্জাস্থান খুলে গেল এবং তারা জান্নাতের বৃক্ষ-পত্র দ্বারা নিজেদেরকে আবৃত করতে শুরু করল। আদম তার পালনকর্তার অবাধ্যতা করল, ফলে সে পথ ভ্রষ্ঠ হয়ে গেল।', 'Faakala minha fabadat lahuma sawatuhuma watafiqa yakhsifani AAalayhima min waraqi aljannati waAAasa adamu rabbahu faghawa', 1, NOW(), NOW()),
(25, 122, 'ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ', 'এরপর তার পালনকর্তা তাকে মনোনীত করলেন, তার প্রতি মনোযোগী হলেন এবং তাকে সুপথে আনয়ন করলেন।', 'Thumma ijtabahu rabbuhu fataba AAalayhi wahada', 1, NOW(), NOW()),
(25, 123, 'قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدٗى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ', 'তিনি বললেনঃ তোমরা উভয়েই এখান থেকে এক সঙ্গে নেমে যাও। তোমরা একে অপরের শত্রু। এরপর যদি আমার পক্ষ থেকে তোমাদের কাছে হেদায়েত আসে, তখন যে আমার বর্ণিত পথ অনুসরণ করবে, সে পথভ্রষ্ঠ হবে না এবং কষ্টে পতিত হবে না।', 'Qala ihbita minha jameeAAan baAAdukum libaAAdin AAaduwwun faimma yatiyannakum minnee hudan famani ittabaAAa hudaya fala yadillu wala yashqa', 1, NOW(), NOW()),
(25, 124, 'وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةٗ ضَنكٗا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ', 'এবং যে আমার স্মরণ থেকে মুখ ফিরিয়ে নেবে, তার জীবিকা সংকীর্ণ হবে এবং আমি তাকে কেয়ামতের দিন অন্ধ অবস্থায় উত্থিত করব।', 'Waman aAArada AAan thikree fainna lahu maAAeeshatan dankan wanahshuruhu yawma alqiyamati aAAman', 1, NOW(), NOW()),
(25, 125, 'قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرٗا', 'সে বলবেঃ হে আমার পালনকর্তা আমাকে কেন অন্ধ অবস্থায় উত্থিত করলেন? আমি তো চক্ষুমান ছিলাম।', 'Qala rabbi lima hashartanee aAAma waqad kuntu baseeran', 1, NOW(), NOW()),
(25, 126, 'قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ', 'আল্লাহ বলবেনঃ এমনিভাবে তোমার কাছে আমার আয়াতসমূহ এসেছিল, অতঃপর তুমি সেগুলো ভুলে গিয়েছিলে। তেমনিভাবে আজ তোমাকে ভুলে যাব।', 'Qala kathalika atatka ayatuna fanaseetaha wakathalika alyawma tunsa', 1, NOW(), NOW()),
(25, 127, 'وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ', 'এমনিভাবে আমি তাকে প্রতিফল দেব, যে সীমালঙ্ঘন করে এবং পালনকর্তার কথায় বিশ্বাস স্থাপন না করে। তার পরকালের শাস্তি কঠোরতর এবং অনেক স্থায়ী।', 'Wakathalika najzee man asrafa walam yumin biayati rabbihi walaAAathabu alakhirati ashaddu waabqa', 1, NOW(), NOW()),
(25, 128, 'أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّأُوْلِي ٱلنُّهَىٰ', 'আমি এদের পূর্বে অনেক সম্প্রদায়কে ধবংস করেছি। যাদের বাসভুমিতে এরা বিচরণ করে, এটা কি এদেরকে সৎপথ প্রদর্শন করল না? নিশ্চয় এতে বুদ্ধিমানদের জন্যে নিদর্শনাবলী রয়েছে।', 'Afalam yahdi lahum kam ahlakna qablahum mina alqurooni yamshoona fee masakinihim inna fee thalika laayatin liolee alnnuha', 1, NOW(), NOW()),
(25, 129, 'وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامٗا وَأَجَلٞ مُّسَمّٗى', 'আপনার পালনকর্তার পক্ষ থেকে পূর্ব সিদ্ধান্ত এবং একটি কাল নির্দিষ্ট না থাকলে শাস্তি অবশ্যম্ভাবী হয়ে যেত।', 'Walawla kalimatun sabaqat min rabbika lakana lizaman waajalun musamman', 1, NOW(), NOW()),
(25, 130, 'فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ', 'সুতরাং এরা যা বলে সে বিষয়ে ধৈর্য্য ধারণ করুন এবং আপনার পালনকর্তার প্রশংসা পবিত্রতা ও মহিমা ঘোষনা করুন সূর্যোদয়ের পূর্বে, সূর্যাস্তের পূর্বে এবং পবিত্রতা ও মহিমা ঘোষনা করুন রাত্রির কিছু অংশ ও দিবাভাগে, সম্ভবতঃ তাতে আপনি সন্তুষ্ট হবেন।', 'Faisbir AAala ma yaqooloona wasabbih bihamdi rabbika qabla tulooAAi alshshamsi waqabla ghuroobiha wamin anai allayli fasabbih waatrafa alnnahari laAAallaka tarda', 1, NOW(), NOW()),
(25, 131, 'وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرٞ وَأَبۡقَىٰ', 'আমি এদের বিভিন্ন প্রকার লোককে পরীক্ষা করার জন্যে পার্থিবজীবনের সৌন্দর্য স্বরূপ ভোগ-বিলাসের যে উপকরণ দিয়েছি, আপনি সেই সব বস্তুর প্রতি দৃষ্টি নিক্ষেপ করবেন না। আপনার পালনকর্তার দেয়া রিযিক উৎকৃষ্ট ও অধিক স্থায়ী।', 'Wala tamuddanna AAaynayka ila ma mattaAAna bihi azwajan minhum zahrata alhayati alddunya linaftinahum feehi warizqu rabbika khayrun waabqa', 1, NOW(), NOW()),
(25, 132, 'وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ', 'আপনি আপনার পরিবারের লোকদেরকে নামাযের আদেশ দিন এবং নিজেও এর ওপর অবিচল থাকুন। আমি আপনার কাছে কোন রিযিক চাই না। আমি আপনাকে রিযিক দেই এবং আল্লাহ ভীরুতার পরিণাম শুভ।', 'Wamur ahlaka bialssalati waistabir AAalayha la nasaluka rizqan nahnu narzuquka waalAAaqibatu lilttaqwa', 1, NOW(), NOW()),
(25, 133, 'وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةٖ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ', 'এরা বলেঃ সে আমাদের কাছে তার পালনকর্তার কাছ থেকে কোন নিদর্শন আনয়ন করে না কেন? তাদের কাছে কি প্রমাণ আসেনি, যা পূর্ববর্তী গ্রন্থসমূহে আছে', 'Waqaloo lawla yateena biayatin min rabbihi awalam tatihim bayyinatu ma fee alssuhufi aloola', 1, NOW(), NOW()),
(25, 134, 'وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابٖ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولٗا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ', 'যদি আমি এদেরকে ইতিপূর্বে কোন শাস্তি দ্বারা ধ্বংস করতাম, তবে এরা বলতঃ হে আমাদের পালনকর্তা, আপনি আমাদের কাছে একজন রসূল প্রেরণ করলেন না কেন? তাহলে তো আমরা অপমানিত ও হেয় হওয়ার পূর্বেই আপনার নিদর্শন সমূহ মেনে চলতাম।', 'Walaw anna ahlaknahum biAAathabin min qablihi laqaloo rabbana lawla arsalta ilayna rasoolan fanattabiAAa ayatika min qabli an nathilla wanakhza', 1, NOW(), NOW()),
(25, 135, 'قُلۡ كُلّٞ مُّتَرَبِّصٞ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ', 'বলুন, প্রত্যেকেই পথপানে চেয়ে আছে, সুতরাং তোমরাও পথপানে চেয়ে থাক। অদূর ভবিষ্যতে তোমরা জানতে পারবে কে সরল পথের পথিক এবং কে সৎপথ প্রাপ্ত হয়েছে।', 'Qul kullun mutarabbisun fatarabbasoo fasataAAlamoona man ashabu alssirati alssawiyyi wamani ihtada', 1, NOW(), NOW()),
(26, 1, 'ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةٖ مُّعۡرِضُونَ', 'মানুষের হিসাব-কিতাবের সময় নিকটবর্তী; অথচ তারা বেখবর হয়ে মুখ ফিরিয়ে নিচ্ছে।', 'Iqtaraba lilnnasi hisabuhum wahum fee ghaflatin muAAridoona', 1, NOW(), NOW()),
(26, 2, 'مَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ', 'তাদের কাছে তাদের পালনকর্তার পক্ষ থেকে যখনই কোন নতুন উপদেশ আসে, তারা তা খেলার ছলে শ্রবণ করে।', 'Ma yateehim min thikrin min rabbihim muhdathin illa istamaAAoohu wahum yalAAaboona', 1, NOW(), NOW()),
(26, 3, 'لَاهِيَةٗ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ', 'তাদের অন্তর থাকে খেলায় মত্ত। জালেমরা গোপনে পরামর্শ করে, সে তো তোমাদেরই মত একজন মানুষ; এমতাবস্থায় দেখে শুনে তোমরা তার যাদুর কবলে কেন পড়', 'Lahiyatan quloobuhum waasarroo alnnajwa allatheena thalamoo hal hatha illa basharun mithlukum afatatoona alssihra waantum tubsiroona', 1, NOW(), NOW()),
(26, 4, 'قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ', 'পয়গম্বর বললেনঃ নভোমন্ডল ও ভুমন্ডলের কথাই আমার পালনকর্তা জানেন। তিনি সবকিছু শোনেন, সবকিছু জানেন।', 'Qala rabbee yaAAlamu alqawla fee alssamai waalardi wahuwa alssameeAAu alAAaleemu', 1, NOW(), NOW()),
(26, 5, 'بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرٞ فَلۡيَأۡتِنَا بِـَٔايَةٖ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ', 'এছাড়া তারা আরও বলেঃ অলীক স্বপ্ন; না সে মিথ্যা উদ্ভাবন করেছে, না সে একজন কবি। অতএব সে আমাদের কাছে কোন নিদর্শন আনয়ন করুক, যেমন নিদর্শন সহ আগমন করেছিলেন পূর্ববর্তীগন।', 'Bal qaloo adghathu ahlamin bali iftarahu bal huwa shaAAirun falyatina biayatin kama orsila alawwaloona', 1, NOW(), NOW()),
(26, 6, 'مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ', 'তাদের পূর্বে যেসব জনপদ আমি ধবংস করে দিয়েছি, তারা বিশ্বাস স্থাপন করেনি; এখন এরা কি বিশ্বাস স্থাপন করবে', 'Ma amanat qablahum min qaryatin ahlaknaha afahum yuminoona', 1, NOW(), NOW()),
(26, 7, 'وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ', 'আপনার পূর্বে আমি মানুষই প্রেরণ করেছি, যাদের কাছে আমি ওহী পাঠাতাম। অতএব তোমরা যদি না জান তবে যারা স্মরণ রাখে তাদেরকে জিজ্ঞেস কর।', 'Wama arsalna qablaka illa rijalan noohee ilayhim faisaloo ahla alththikri in kuntum la taAAlamoona', 1, NOW(), NOW()),
(26, 8, 'وَمَا جَعَلۡنَٰهُمۡ جَسَدٗا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ', 'আমি তাদেরকে এমন দেহ বিশিষ্ট করিনি যে, তারা খাদ্য ভক্ষণ করত না এবং তারা চিরস্থায়ীও ছিল না।', 'Wama jaAAalnahum jasadan la yakuloona alttaAAama wama kanoo khalideena', 1, NOW(), NOW()),
(26, 9, 'ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ', 'অতঃপর আমি তাদেরকে দেয়া আমার প্রতিশ্রুতি পূর্ণ করলাম সুতরাং তাদেরকে এবং যাদেরকে ইচ্ছা বাঁচিয়ে দিলাম এবং ধবংস করে ছিলাম সীমালঙ্ঘনকারীদেরকে।', 'Thumma sadaqnahumu alwaAAda faanjaynahum waman nashao waahlakna almusrifeena', 1, NOW(), NOW()),
(26, 10, 'لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبٗا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ', 'আমি তোমাদের প্রতি একটি কিতাব অবর্তীর্ণ করেছি; এতে তোমাদের জন্যে উপদেশ রয়েছে। তোমরা কি বোঝ না', 'Laqad anzalna ilaykum kitaban feehi thikrukum afala taAAqiloona', 1, NOW(), NOW()),
(26, 11, 'وَكَمۡ قَصَمۡنَا مِن قَرۡيَةٖ كَانَتۡ ظَالِمَةٗ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ', 'আমি কত জনপদের ধ্বংস সাধন করেছি যার অধিবাসীরা ছিল পাপী এবং তাদের পর সৃষ্টি করেছি অন্য জাতি।', 'Wakam qasamna min qaryatin kanat thalimatan waanshana baAAdaha qawman akhareena', 1, NOW(), NOW()),
(26, 12, 'فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ', 'অতঃপর যখন তারা আমার আযাবের কথা টের পেল, তখনই তারা সেখান থেকে পলায়ন করতে লাগল।', 'Falamma ahassoo basana itha hum minha yarkudoona', 1, NOW(), NOW()),
(26, 13, 'لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ', 'পলায়ন করো না এবং ফিরে এস, যেখানে তোমরা বিলাসিতায় মত্ত ছিলে ও তোমাদের আবাসগৃহে; সম্ভবত; কেউ তোমাদের জিজ্ঞেস করবে।', 'La tarkudoo wairjiAAoo ila ma otriftum feehi wamasakinikum laAAallakum tusaloona', 1, NOW(), NOW()),
(26, 14, 'قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'তারা বললঃ হায়, দুর্ভোগ আমাদের, আমরা অবশ্যই পাপী ছিলাম।', 'Qaloo ya waylana inna kunna thalimeena', 1, NOW(), NOW()),
(26, 15, 'فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ', 'তাদের এই আর্তনাদ সব সময় ছিল, শেষ পর্যন্ত আমি তাদেরকে করে দিলাম যেন কর্তিত শস্য ও নির্বাপিত অগ্নি।', 'Fama zalat tilka daAAwahum hatta jaAAalnahum haseedan khamideena', 1, NOW(), NOW()),
(26, 16, 'وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ', 'আকাশ পৃথিবী এতদুভয়ের মধ্যে যা আছে, তা আমি ক্রীড়াচ্ছলে সৃষ্টি করিনি।', 'Wama khalaqna alssamaa waalarda wama baynahuma laAAibeena', 1, NOW(), NOW()),
(26, 17, 'لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوٗا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', 'আমি যদি ক্রীড়া উপকরণ সৃষ্টি করতে চাইতাম, তবে আমি আমার কাছে যা আছে তা দ্বারাই তা করতাম, যদি আমাকে করতে হত।', 'Law aradna an nattakhitha lahwan laittakhathnahu min ladunna in kunna faAAileena', 1, NOW(), NOW()),
(26, 18, 'بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقٞۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ', 'বরং আমি সত্যকে মিথ্যার উপর নিক্ষেপ করি, অতঃপর সত্য মিথ্যার মস্তক চুর্ণ-বিচূর্ণ করে দেয়, অতঃপর মিথ্যা তৎক্ষণাৎ নিশ্চিহ্ন হয়ে যায়। তোমরা যা বলছ, তার জন্যে তোমাদের দুর্ভোগ।', 'Bal naqthifu bialhaqqi AAala albatili fayadmaghuhu faitha huwa zahiqun walakumu alwaylu mimma tasifoona', 1, NOW(), NOW()),
(26, 19, 'وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ', 'নভোমন্ডল ও ভুমন্ডলে যারা আছে, তারা তাঁরই। আর যারা তাঁর সান্নিধ্যে আছে তারা তাঁর ইবাদতে অহংকার করে না এবং অলসতাও করে না।', 'Walahu man fee alssamawati waalardi waman AAindahu la yastakbiroona AAan AAibadatihi wala yastahsiroona', 1, NOW(), NOW()),
(26, 20, 'يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ', 'তারা রাত্রিদিন তাঁর পবিত্রতা ও মহিমা বর্ণনা করে এবং ক্লান্ত হয় না।', 'Yusabbihoona allayla waalnnahara la yafturoona', 1, NOW(), NOW()),
(26, 21, 'أَمِ ٱتَّخَذُوٓاْ ءَالِهَةٗ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ', 'তারা কি মৃত্তিকা দ্বারা তৈরী উপাস্য গ্রহণ করেছে, যে তারা তাদেরকে জীবিত করবে', 'Ami ittakhathoo alihatan mina alardi hum yunshiroona', 1, NOW(), NOW()),
(26, 22, 'لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ', 'যদি নভোমন্ডল ও ভুমন্ডলে আল্লাহ ব্যতীত অন্যান্য উপাস্য থাকত, তবে উভয়ের ধ্বংস হয়ে যেত। অতএব তারা যা বলে, তা থেকে আরশের অধিপতি আল্লাহ পবিত্র।', 'Law kana feehima alihatun illa Allahu lafasadata fasubhana Allahi rabbi alAAarshi AAamma yasifoona', 1, NOW(), NOW()),
(26, 23, 'لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ', 'তিনি যা করেন, তৎসম্পর্কে তিনি জিজ্ঞাসিত হবেন না এবং তাদেরকে জিজ্ঞেস করা হবে।', 'La yusalu AAamma yafAAalu wahum yusaloona', 1, NOW(), NOW()),
(26, 24, 'أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ', 'তারা কি আল্লাহ ব্যতীত অন্যান্য উপাস্য গ্রহণ করেছে? বলুন, তোমরা তোমাদের প্রমাণ আন। এটাই আমার সঙ্গীদের কথা এবং এটাই আমার পুর্ববর্তীদের কথা। বরং তাদের অধিকাংশই সত্য জানে না; অতএব তারা টালবাহানা করে।', 'Ami ittakhathoo min doonihi alihatan qul hatoo burhanakum hatha thikru man maAAiya wathikru man qablee bal aktharuhum la yaAAlamoona alhaqqa fahum muAAridoona', 1, NOW(), NOW()),
(26, 25, 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ', 'আপনার পূর্বে আমি যে রাসূলই প্রেরণ করেছি, তাকে এ আদেশই প্রেরণ করেছি যে, আমি ব্যতীত অন্য কোন উপাস্য নেই। সুতরাং আমারই এবাদত কর।', 'Wama arsalna min qablika min rasoolin illa noohee ilayhi annahu la ilaha illa ana faoAAbudooni', 1, NOW(), NOW()),
(26, 26, 'وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدٗاۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادٞ مُّكۡرَمُونَ', 'তারা বললঃ দয়াময় আল্লাহ সন্তান গ্রহণ করেছে। তাঁর জন্য কখনও ইহা যোগ্য নয়; বরং তারা তো তাঁর সম্মানিত বান্দা।', 'Waqaloo ittakhatha alrrahmanu waladan subhanahu bal AAibadun mukramoona', 1, NOW(), NOW()),
(26, 27, 'لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ', 'তারা আগে বেড়ে কথা বলতে পারে না এবং তারা তাঁর আদেশেই কাজ করে।', 'La yasbiqoonahu bialqawli wahum biamrihi yaAAmaloona', 1, NOW(), NOW()),
(26, 28, 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ', 'তাদের সম্মুখে ও পশ্চাতে যা আছে, তা তিনি জানেন। তারা শুধু তাদের জন্যে সুপারিশ করে, যাদের প্রতি আল্লাহ সন্তুষ্ট এবং তারা তাঁর ভয়ে ভীত।', 'YaAAlamu ma bayna aydeehim wama khalfahum wala yashfaAAoona illa limani irtada wahum min khashyatihi mushfiqoona', 1, NOW(), NOW()),
(26, 29, '۞وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهٞ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ', 'তাদের মধ্যে যে বলে যে, তিনি ব্যতীত আমিই উপাস্য, তাকে আমি জাহান্নামের শাস্তি দেব। আমি জালেমদেরকে এভাবেই প্রতিফল দিয়ে থাকি।', 'Waman yaqul minhum innee ilahun min doonihi fathalika najzeehi jahannama kathalika najzee alththalimeena', 1, NOW(), NOW()),
(26, 30, 'أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقٗا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ', 'কাফেররা কি ভেবে দেখে না যে, আকাশমন্ডলী ও পৃথিবীর মুখ বন্ধ ছিল, অতঃপর আমি উভয়কে খুলে দিলাম এবং প্রাণবন্ত সবকিছু আমি পানি থেকে সৃষ্টি করলাম। এরপরও কি তারা বিশ্বাস স্থাপন করবে না', 'Awalam yara allatheena kafaroo anna alssamawati waalarda kanata ratqan fafataqnahuma wajaAAalna mina almai kulla shayin hayyin afala yuminoona', 1, NOW(), NOW()),
(26, 31, 'وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجٗا سُبُلٗا لَّعَلَّهُمۡ يَهۡتَدُونَ', 'আমি পৃথিবীতে ভারী বোঝা রেখে দিয়েছি যাতে তাদেরকে নিয়ে পৃথিবী ঝুঁকে না পড়ে এবং তাতে প্রশস্ত পথ রেখেছি, যাতে তারা পথ প্রাপ্ত হয়।', 'WajaAAalna fee alardi rawasiya an tameeda bihim wajaAAalna feeha fijajan subulan laAAallahum yahtadoona', 1, NOW(), NOW()),
(26, 32, 'وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفٗا مَّحۡفُوظٗاۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ', 'আমি আকাশকে সুরক্ষিত ছাদ করেছি; অথচ তারা আমার আকাশস্থ নিদর্শনাবলী থেকে মুখ ফিরিয়ে রাখে।', 'WajaAAalna alssamaa saqfan mahfoothan wahum AAan ayatiha muAAridoona', 1, NOW(), NOW()),
(26, 33, 'وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ فِي فَلَكٖ يَسۡبَحُونَ', 'তিনিই সৃষ্টি করেছেন রাত্রি ও দিন এবং সূর্য ও চন্দ্র। সবাই আপন আপন কক্ষপথে বিচরণ করে।', 'Wahuwa allathee khalaqa allayla waalnnahara waalshshamsa waalqamara kullun fee falakin yasbahoona', 1, NOW(), NOW()),
(26, 34, 'وَمَا جَعَلۡنَا لِبَشَرٖ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ', 'আপনার পূর্বেও কোন মানুষকে আমি অনন্ত জীবন দান করিনি। সুতরাং আপনার মৃত্যু হলে তারা কি চিরঞ্জীব হবে', 'Wama jaAAalna libasharin min qablika alkhulda afain mitta fahumu alkhalidoona', 1, NOW(), NOW()),
(26, 35, 'كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ', 'প্রত্যেককে মৃত্যুর স্বাদ আস্বাদন করতে হবে। আমি তোমাদেরকে মন্দ ও ভাল দ্বারা পরীক্ষা করে থাকি এবং আমারই কাছে তোমরা প্রত্যাবর্তিত হবে।', 'Kullu nafsin thaiqatu almawti wanablookum bialshsharri waalkhayri fitnatan wailayna turjaAAoona', 1, NOW(), NOW()),
(26, 36, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ', 'কাফেররা যখন আপনাকে দেখে তখন আপনার সাথে ঠাট্টা করা ছাড়া তাদের আর কোন কাজ থাকে না, একি সেই ব্যক্তি, যে তোমাদের দেব-দেবীদের সমালোচনা করে? এবং তারাই তো রহমান’ এর আলোচনায় অস্বীকার করে।', 'Waitha raaka allatheena kafaroo in yattakhithoonaka illa huzuwan ahatha allathee yathkuru alihatakum wahum bithikri alrrahmani hum kafiroona', 1, NOW(), NOW()),
(26, 37, 'خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلٖۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ', 'সৃষ্টিগত ভাবে মানুষ ত্বরাপ্রবণ, আমি সত্তরই তোমাদেরকে আমার নিদর্শনাবলী দেখাব। অতএব আমাকে শীঘ্র করতে বলো না।', 'Khuliqa alinsanu min AAajalin saoreekum ayatee fala tastaAAjiloona', 1, NOW(), NOW()),
(26, 38, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ', 'এবং তারা বলেঃ যদি তোমরা সত্যবাদী হও তবে এই ওয়াদা কবে পুর্ণ হবে', 'Wayaqooloona mata hatha alwaAAdu in kuntum sadiqeena', 1, NOW(), NOW()),
(26, 39, 'لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ', 'যদি কাফেররা ঐ সময়টি জানত, যখন তারা তাদের সম্মুখ ও পৃষ্ঠদেশ থেকে অগ্নি প্রতিরোধ করতে পারবে না এবং তারা সাহায্য প্রাপ্ত হবে না।', 'Law yaAAlamu allatheena kafaroo heena la yakuffoona AAan wujoohihimu alnnara wala AAan thuhoorihim wala hum yunsaroona', 1, NOW(), NOW()),
(26, 40, 'بَلۡ تَأۡتِيهِم بَغۡتَةٗ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ', 'বরং তা আসবে তাদের উপর অতর্কিত ভাবে, অতঃপর তাদেরকে তা হতবুদ্ধি করে দেবে, তখন তারা তা রোধ করতেও পারবে না এবং তাদেরকে অবকাশও দেয়া হবে না।', 'Bal tateehim baghtatan fatabhatuhum fala yastateeAAoona raddaha wala hum yuntharoona', 1, NOW(), NOW()),
(26, 41, 'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'আপনার পূর্বেও অনেক রাসূলের সাথে ঠাট্টা-বিদ্রূপ করা হয়েছে। অতঃপর যে বিষয়ে তারা ঠাট্টা করত তা উল্টো ঠাট্টাকারীদের উপরই আপতিত হয়েছে।', 'Walaqadi istuhzia birusulin min qablika fahaqa biallatheena sakhiroo minhum ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(26, 42, 'قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ', 'বলুনঃ ‘রহমান’ থেকে কে তোমাদেরকে হেফাযত করবে রাত্রে ও দিনে। বরং তারা তাদের পালনকর্তার স্মরণ থেকে মুখ ফিরিয়ে রাখে।', 'Qul man yaklaokum biallayli waalnnahari mina alrrahmani bal hum AAan thikri rabbihim muAAridoona', 1, NOW(), NOW()),
(26, 43, 'أَمۡ لَهُمۡ ءَالِهَةٞ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ', 'তবে কি আমি ব্যতীত তাদের এমন দেব-দেবী আছে যারা তাদেরকে রক্ষা করবে? তারা তো নিজেদেরই সাহায্য করতে সক্ষম নয় এবং তারা আমার মোকাবেলায় সাহায্যকারীও পাবে না।', 'Am lahum alihatun tamnaAAuhum min doonina la yastateeAAoona nasra anfusihim wala hum minna yushaboona', 1, NOW(), NOW()),
(26, 44, 'بَلۡ مَتَّعۡنَا هَـٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ', 'বরং আমি তাদেরকে এবং তাদের বাপ-দাদাকে ভোগসম্বার দিয়েছিলাম, এমনকি তাদের আয়ুস্কালও দীর্ঘ হয়েছিল। তারা কি দেখে না যে, আমি তাদের দেশকে চতুর্দিক থেকে হ্রাস করে আনছি। এরপরও কি তারা বিজয়ী হবে', 'Bal mattaAAna haolai waabaahum hatta tala AAalayhimu alAAumuru afala yarawna anna natee alarda nanqusuha min atrafiha afahumu alghaliboona', 1, NOW(), NOW()),
(26, 45, 'قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'বলুনঃ আমি তো কেবল ওহীর মাধ্যমেই তোমাদেরকে সতর্ক করি, কিন্তু বধিরদেরকে যখন সতর্ক করা হয়, তখন তারা সে সতর্কবাণী শোনে না।', 'Qul innama onthirukum bialwahyi wala yasmaAAu alssummu aldduAAaa itha ma yuntharoona', 1, NOW(), NOW()),
(26, 46, 'وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةٞ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'আপনার পালনকর্তার আযাবের কিছুমাত্রও তাদেরকে স্পর্শ করলে তারা বলতে থাকবে, হায় আমাদের দুর্ভাগ্য, আমরা অবশ্যই পাপী ছিলাম।', 'Walain massathum nafhatun min AAathabi rabbika layaqoolunna ya waylana inna kunna thalimeena', 1, NOW(), NOW()),
(26, 47, 'وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسٞ شَيۡـٔٗاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةٖ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ', 'আমি কেয়ামতের দিন ন্যায়বিচারের মানদন্ড স্থাপন করব। সুতরাং কারও প্রতি জুলুম হবে না। যদি কোন আমল সরিষার দানা পরিমাণও হয়, আমি তা উপস্থিত করব এবং হিসাব গ্রহণের জন্যে আমিই যথেষ্ট।', 'WanadaAAu almawazeena alqista liyawmi alqiyamati fala tuthlamu nafsun shayan wain kana mithqala habbatin min khardalin atayna biha wakafa bina hasibeena', 1, NOW(), NOW()),
(26, 48, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءٗ وَذِكۡرٗا لِّلۡمُتَّقِينَ', 'আমি মূসা ও হারুণকে দান করেছিলাম মীমাংসাকারী গ্রন্থ, আলো ও উপদেশ, আল্লাহ ভীরুদের জন্যে', 'Walaqad atayna moosa waharoona alfurqana wadiyaan wathikran lilmuttaqeena', 1, NOW(), NOW()),
(26, 49, 'ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ', 'যারা না দেখেই তাদের পালনকর্তাকে ভয় করে এবং কেয়ামতের ভয়ে শঙ্কিত।', 'Allatheena yakhshawna rabbahum bialghaybi wahum mina alssaAAati mushfiqoona', 1, NOW(), NOW()),
(26, 50, 'وَهَٰذَا ذِكۡرٞ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ', 'এবং এটা একটা বরকতময় উপদেশ, যা আমি নাযিল করেছি। অতএব তোমরা কি একে অস্বীকার কর', 'Wahatha thikrun mubarakun anzalnahu afaantum lahu munkiroona', 1, NOW(), NOW()),
(26, 51, '۞وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', 'আর, আমি ইতিপূর্বে ইব্রাহীমকে তার সৎপন্থা দান করেছিলাম এবং আমি তার সম্পর্কে সম্যক পরিজ্ঞাত ও ছিলাম।', 'Walaqad atayna ibraheema rushdahu min qablu wakunna bihi AAalimeena', 1, NOW(), NOW()),
(26, 52, 'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ', 'যখন তিনি তাঁর পিতা ও তাঁর সম্প্রদায়কে বললেনঃ এই মূর্তিগুলো কী, যাদের তোমরা পূজারী হয়ে বসে আছ।', 'Ith qala liabeehi waqawmihi ma hathihi alttamatheelu allatee antum laha AAakifoona', 1, NOW(), NOW()),
(26, 53, 'قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', 'তারা বললঃ আমরা আমাদের বাপ-দাদাকে এদের পুজা করতে দেখেছি।', 'Qaloo wajadna abaana laha AAabideena', 1, NOW(), NOW()),
(26, 54, 'قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلٖ مُّبِينٖ', 'তিনি বললেনঃ তোমরা প্রকাশ্য গোমরাহীতে আছ এবং তোমাদের বাপ-দাদারাও।', 'Qala laqad kuntum antum waabaokum fee dalalin mubeenin', 1, NOW(), NOW()),
(26, 55, 'قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّـٰعِبِينَ', 'তারা বললঃ তুমি কি আমাদের কাছে সত্যসহ আগমন করেছ, না তুমি কৌতুক করছ', 'Qaloo ajitana bialhaqqi am anta mina allaAAibeena', 1, NOW(), NOW()),
(26, 56, 'قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّـٰهِدِينَ', 'তিনি বললেনঃ না, তিনিই তোমাদের পালনকর্তা যিনি নভোমন্ডল ও ভুমন্ডলের পালনকর্তা, যিনি এগুলো সৃষ্টি করেছেন; এবং আমি এই বিষয়েরই সাক্ষ্যদাতা।', 'Qala bal rabbukum rabbu alssamawati waalardi allathee fatarahunna waana AAala thalikum mina alshshahideena', 1, NOW(), NOW()),
(26, 57, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ', 'আল্লাহর কসম, যখন তোমরা পৃষ্ঠ প্রদর্শন করে চলে যাবে, তখন আমি তোমাদের মূর্তিগুলোর ব্যাপারে একটা ব্যবস্থা অবলম্বন করব।', 'WataAllahi laakeedanna asnamakum baAAda an tuwalloo mudbireena', 1, NOW(), NOW()),
(26, 58, 'فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرٗا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ', 'অতঃপর তিনি সেগুলোকে চূর্ণ-বিচুর্ণ করে দিলেন ওদের প্রধানটি ব্যতীতঃ যাতে তারা তাঁর কাছে প্রত্যাবর্তন করে।', 'FajaAAalahum juthathan illa kabeeran lahum laAAallahum ilayhi yarjiAAoona', 1, NOW(), NOW()),
(26, 59, 'قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِينَ', 'তারা বললঃ আমাদের উপাস্যদের সাথে এরূপ ব্যবহার কে করল? সে তো নিশ্চয়ই কোন জালিম।', 'Qaloo man faAAala hatha bialihatina innahu lamina alththalimeena', 1, NOW(), NOW()),
(26, 60, 'قَالُواْ سَمِعۡنَا فَتٗى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ', 'কতক লোকে বললঃ আমরা এক যুবককে তাদের সম্পর্কে বিরূপ আলোচনা করতে শুনেছি; তাকে ইব্রাহীম বলা হয়।', 'Qaloo samiAAna fatan yathkuruhum yuqalu lahu ibraheemu', 1, NOW(), NOW()),
(26, 61, 'قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ', 'তারা বললঃ তাকে জনসমক্ষে উপস্থিত কর, যাতে তারা দেখে।', 'Qaloo fatoo bihi AAala aAAyuni alnnasi laAAallahum yashhadoona', 1, NOW(), NOW()),
(26, 62, 'قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَـٰٓإِبۡرَٰهِيمُ', 'তারা বললঃ হে ইব্রাহীম তুমিই কি আমাদের উপাস্যদের সাথে এরূপ ব্যবহার করেছ', 'Qaloo aanta faAAalta hatha bialihatina ya ibraheemu', 1, NOW(), NOW()),
(26, 63, 'قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ', 'তিনি বললেনঃ না এদের এই প্রধানই তো একাজ করেছে। অতএব তাদেরকে জিজ্ঞেস কর, যদি তারা কথা বলতে পারে।', 'Qala bal faAAalahu kabeeruhum hatha faisaloohum in kanoo yantiqoona', 1, NOW(), NOW()),
(26, 64, 'فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّـٰلِمُونَ', 'অতঃপর মনে মনে চিন্তা করল এবং বললঃ লোক সকল; তোমরাই বে ইনসাফ।', 'FarajaAAoo ila anfusihim faqaloo innakum antumu alththalimoona', 1, NOW(), NOW()),
(26, 65, 'ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَـٰٓؤُلَآءِ يَنطِقُونَ', 'অতঃপর তারা ঝুঁকে গেল মস্তক নত করে, তুমি তো জান যে, এরা কথা বলে না', 'Thumma nukisoo AAala ruoosihim laqad AAalimta ma haolai yantiqoona', 1, NOW(), NOW()),
(26, 66, 'قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـٔٗا وَلَا يَضُرُّكُمۡ', 'তিনি বললেনঃ তোমরা কি আল্লাহর পরিবর্তে এমন কিছুর এবাদত কর, যা তোমাদের কোন উপকার ও করতে পারে না এবং ক্ষতিও করতে পারে না', 'Qala afataAAbudoona min dooni Allahi ma la yanfaAAukum shayan wala yadurrukum', 1, NOW(), NOW()),
(26, 67, 'أُفّٖ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ', 'ধিক তোমাদের জন্যে এবং তোমরা আল্লাহ ব্যতীত যাদেরই এবাদত কর, ওদের জন্যে। তোমরা কি বোঝ না', 'Offin lakum walima taAAbudoona min dooni Allahi afala taAAqiloona', 1, NOW(), NOW()),
(26, 68, 'قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ', 'তারা বললঃ একে পুড়িয়ে দাও এবং তোমাদের উপাস্যদের সাহায্য কর, যদি তোমরা কিছু করতে চাও।', 'Qaloo harriqoohu waonsuroo alihatakum in kuntum faAAileena', 1, NOW(), NOW()),
(26, 69, 'قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ', 'আমি বললামঃ হে অগ্নি, তুমি ইব্রাহীমের উপর শীতল ও নিরাপদ হয়ে যাও।', 'Qulna ya naru koonee bardan wasalaman AAala ibraheema', 1, NOW(), NOW()),
(26, 70, 'وَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ', 'তারা ইব্রাহীমের বিরুদ্ধে ফন্দি আঁটতে চাইল, অতঃপর আমি তাদেরকেই সর্বাধিক ক্ষতিগ্রস্থ করে দিলাম।', 'Waaradoo bihi kaydan fajaAAalnahumu alakhsareena', 1, NOW(), NOW()),
(26, 71, 'وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ', 'আমি তাঁকে ও লূতকে উদ্ধার করে সেই দেশে পৌঁছিয়ে দিলাম, যেখানে আমি বিশ্বের জন্যে কল্যাণ রেখেছি।', 'Wanajjaynahu walootan ila alardi allatee barakna feeha lilAAalameena', 1, NOW(), NOW()),
(26, 72, 'وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةٗۖ وَكُلّٗا جَعَلۡنَا صَٰلِحِينَ', 'আমি তাকে দান করলাম ইসহাক ও পুরস্কার স্বরূপ দিলাম ইয়াকুব এবং প্রত্যেককেই সৎকর্ম পরায়ণ করলাম।', 'Wawahabna lahu ishaqa wayaAAqooba nafilatan wakullan jaAAalna saliheena', 1, NOW(), NOW()),
(26, 73, 'وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ', 'আমি তাঁদেরকে নেতা করলাম। তাঁরা আমার নির্দেশ অনুসারে পথ প্রদর্শন করতেন। আমি তাঁদের প্রতি ওহী নাযিল করলাম সৎকর্ম করার, নামায কায়েম করার এবং যাকাত দান করার। তাঁরা আমার এবাদতে ব্যাপৃত ছিল।', 'WajaAAalnahum aimmatan yahdoona biamrina waawhayna ilayhim fiAAla alkhayrati waiqama alssalati waeetaa alzzakati wakanoo lana AAabideena', 1, NOW(), NOW()),
(26, 74, 'وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَـٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَٰسِقِينَ', 'এবং আমি লূতকে দিয়েছিলাম প্রজ্ঞা ও জ্ঞান এবং তাঁকে ঐ জনপদ থেকে উদ্ধার করেছিলাম, যারা নোংরা কাজে লিপ্ত ছিল। তারা মন্দ ও নাফরমান সম্প্রদায় ছিল।', 'Walootan ataynahu hukman waAAilman wanajjaynahu mina alqaryati allatee kanat taAAmalu alkhabaitha innahum kanoo qawma sawin fasiqeena', 1, NOW(), NOW()),
(26, 75, 'وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِينَ', 'আমি তাকে আমার অনুগ্রহের অন্তর্ভুক্ত করেছিলাম। সে ছিল সৎকর্মশীলদের একজন।', 'Waadkhalnahu fee rahmatina innahu mina alssaliheena', 1, NOW(), NOW()),
(26, 76, 'وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ', 'এবং স্মরণ করুন নূহকে; যখন তিনি এর পূর্বে আহবান করেছিলেন। তখন আমি তাঁর দোয়া কবুল করেছিলাম, অতঃপর তাঁকে ও তাঁর পরিবারবর্গকে মহা সংকট থেকে উদ্ধার করেছিলাম।', 'Wanoohan ith nada min qablu faistajabna lahu fanajjaynahu waahlahu mina alkarbi alAAatheemi', 1, NOW(), NOW()),
(26, 77, 'وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءٖ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ', 'এবং আমি তাঁকে ঐ সম্প্রদায়ের বিপক্ষে সাহায্য করেছিলাম, যারা আমার নিদর্শনাবলীকে অস্বীকার করেছিল। নিশ্চয়, তারা ছিল এক মন্দ সম্প্রদায়। অতঃপর আমি তাদের সবাইকে নিমজ্জত করেছিলাম।', 'Wanasarnahu mina alqawmi allatheena kaththaboo biayatina innahum kanoo qawma sawin faaghraqnahum ajmaAAeena', 1, NOW(), NOW()),
(26, 78, 'وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ', 'এবং স্মরণ করুন দাউদ ও সুলায়মানকে, যখন তাঁরা শস্যক্ষেত্র সম্পর্কে বিচার করেছিলেন। তাতে রাত্রিকালে কিছু লোকের মেষ ঢুকে পড়েছিল। তাদের বিচার আমার সম্মুখে ছিল।', 'Wadawooda wasulaymana ith yahkumani fee alharthi ith nafashat feehi ghanamu alqawmi wakunna lihukmihim shahideena', 1, NOW(), NOW()),
(26, 79, 'فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمٗا وَعِلۡمٗاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ', 'অতঃপর আমি সুলায়মানকে সে ফায়সালা বুঝিয়ে দিয়েছিলাম এবং আমি উভয়কে প্রজ্ঞা ও জ্ঞান দিয়েছিলাম। আমি পর্বত ও পক্ষীসমূহকে দাউদের অনুগত করে দিয়েছিলাম; তারা আমার পবিত্রতা ও মহিমা ঘোষণা করত। এই সমস্ত আমিই করেছিলাম।', 'Fafahhamnaha sulaymana wakullan atayna hukman waAAilman wasakhkharna maAAa dawooda aljibala yusabbihna waalttayra wakunna faAAileena', 1, NOW(), NOW()),
(26, 80, 'وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ', 'আমি তাঁকে তোমাদের জন্যে বর্ম নির্মান শিক্ষা দিয়েছিলাম, যাতে তা যুদ্ধে তোমাদেরকে রক্ষা করে। অতএব তোমরা কি কৃতজ্ঞ হবে', 'WaAAallamnahu sanAAata laboosin lakum lituhsinakum min basikum fahal antum shakiroona', 1, NOW(), NOW()),
(26, 81, 'وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةٗ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ', 'এবং সুলায়মানের অধীন করে দিয়েছিলাম প্রবল বায়ুকে; তা তাঁর আদেশে প্রবাহিত হত ঐ দেশের দিকে, যেখানে আমি কল্যাণ দান করেছি। আমি সব বিষয়েই সম্যক অবগত রয়েছি।', 'Walisulaymana alrreeha AAasifatan tajree biamrihi ila alardi allatee barakna feeha wakunna bikulli shayin AAalimeena', 1, NOW(), NOW()),
(26, 82, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلٗا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ', 'এবং অধীন করেছি শয়তানদের কতককে, যারা তার জন্যে ডুবুরীর কাজ করত এবং এ ছাড়া অন্য আরও অনেক কাজ করত। আমি তাদেরকে নিয়ন্ত্রন করে রাখতাম।', 'Wamina alshshayateeni man yaghoosoona lahu wayaAAmaloona AAamalan doona thalika wakunna lahum hafitheena', 1, NOW(), NOW()),
(26, 83, '۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ', 'এবং স্মরণ করুন আইয়্যুবের কথা, যখন তিনি তাঁর পালনকর্তাকে আহবান করে বলেছিলেনঃ আমি দুঃখকষ্টে পতিত হয়েছি এবং আপনি দয়াবানদের চাইতেও সর্বশ্রেষ্ট দয়াবান।', 'Waayyooba ith nada rabbahu annee massaniya alddurru waanta arhamu alrrahimeena', 1, NOW(), NOW()),
(26, 84, 'فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ', 'অতঃপর আমি তাঁর আহবানে সাড়া দিলাম এবং তাঁর দুঃখকষ্ট দূর করে দিলাম এবং তাঁর পরিবরাবর্গ ফিরিয়ে দিলাম, আর তাদের সাথে তাদের সমপরিমাণ আরও দিলাম আমার পক্ষ থেকে কৃপাবশতঃ আর এটা এবাদত কারীদের জন্যে উপদেশ স্বরূপ।', 'Faistajabna lahu fakashafna ma bihi min durrin waataynahu ahlahu wamithlahum maAAahum rahmatan min AAindina wathikra lilAAabideena', 1, NOW(), NOW()),
(26, 85, 'وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّـٰبِرِينَ', 'এবং ইসমাঈল, ই’দ্রীস ও যুলকিফলের কথা স্মরণ করুন, তাঁরা প্রত্যেকেই ছিলেন সবরকারী।', 'WaismaAAeela waidreesa watha alkifli kullun mina alssabireena', 1, NOW(), NOW()),
(26, 86, 'وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِينَ', 'আমি তাঁদেরকে আমার রহমাতপ্রাপ্তদের অন্তর্ভূক্ত করেছিলাম। তাঁরা ছিলেন সৎকর্মপরায়ণ।', 'Waadkhalnahum fee rahmatina innahum mina alssaliheena', 1, NOW(), NOW()),
(26, 87, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ', 'এবং মাছওয়ালার কথা স্মরণ করুন তিনি ক্রুদ্ধ হয়ে চলে গিয়েছিলেন, অতঃপর মনে করেছিলেন যে, আমি তাঁকে ধৃত করতে পারব না। অতঃপর তিনি অন্ধকারের মধ্যে আহবান করলেনঃ তুমি ব্যতীত কোন উপাস্য নেই; তুমি নির্দোষ আমি গুনাহগার।', 'Watha alnnooni ith thahaba mughadiban fathanna an lan naqdira AAalayhi fanada fee alththulumati an la ilaha illa anta subhanaka innee kuntu mina alththalimeena', 1, NOW(), NOW()),
(26, 88, 'فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ', 'অতঃপর আমি তাঁর আহবানে সাড়া দিলাম এবং তাঁকে দুশ্চিন্তা থেকে মুক্তি দিলাম। আমি এমনি ভাবে বিশ্ববাসীদেরকে মুক্তি দিয়ে থাকি।', 'Faistajabna lahu wanajjaynahu mina alghammi wakathalika nunjee almumineena', 1, NOW(), NOW()),
(26, 89, 'وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدٗا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ', 'এবং যাকারিয়ার কথা স্মরণ করুন, যখন সে তার পালনকর্তাকে আহবান করেছিল; হে আমার পালনকর্তা আমাকে একা রেখো না। তুমি তো উত্তম ওয়ারিস।', 'Wazakariyya ith nada rabbahu rabbi la tatharnee fardan waanta khayru alwaritheena', 1, NOW(), NOW()),
(26, 90, 'فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ', 'অতঃপর আমি তার দোয়া কবুল করেছিলাম, তাকে দান করেছিলাম ইয়াহইয়া এবং তার জন্যে তার স্ত্রীকে প্রসব যোগ্য করেছিলাম। তারা সৎকর্মে ঝাঁপিয়ে পড়ত, তারা আশা ও ভীতি সহকারে আমাকে ডাকত এবং তারা ছিল আমার কাছে বিনীত।', 'Faistajabna lahu wawahabna lahu yahya waaslahna lahu zawjahu innahum kanoo yusariAAoona fee alkhayrati wayadAAoonana raghaban warahaban wakanoo lana khashiAAeena', 1, NOW(), NOW()),
(26, 91, 'وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ', 'এবং সেই নারীর কথা আলোচনা করুন, যে তার কামপ্রবৃত্তিকে বশে রেখেছিল, অতঃপর আমি তার মধ্যে আমার রূহ ফুঁকে দিয়েছিলাম এবং তাকে তার পুত্রকে বিশ্ববাসীর জন্য নিদর্শন করেছিলাম।', 'Waallatee ahsanat farjaha fanafakhna feeha min roohina wajaAAalnaha waibnaha ayatan lilAAalameena', 1, NOW(), NOW()),
(26, 92, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ', 'তারা সকলেই তোমাদের ধর্মের; একই ধর্মে তো বিশ্বাসী সবাই এবং আমিই তোমাদের পালনকর্তা, অতএব আমার বন্দেগী কর।', 'Inna hathihi ommatukum ommatan wahidatan waana rabbukum faoAAbudooni', 1, NOW(), NOW()),
(26, 93, 'وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ', 'এবং মানুষ তাদের কার্যকলাপ দ্বারা পারস্পরিক বিষয়ে ভেদ সৃষ্টি করেছে। প্রত্যেকেই আমার কাছে প্রত্যাবর্তিত হবে।', 'WataqattaAAoo amrahum baynahum kullun ilayna rajiAAoona', 1, NOW(), NOW()),
(26, 94, 'فَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ وَهُوَ مُؤۡمِنٞ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', 'অতঃপর যে বিশ্বাসী অবস্থায় সৎকর্ম সম্পাদন করে, তার প্রচেষ্টা অস্বীকৃত হবে না এবং আমি তা লিপিবদ্ধ করে রাখি।', 'Faman yaAAmal mina alssalihati wahuwa muminun fala kufrana lisaAAyihi wainna lahu katiboona', 1, NOW(), NOW()),
(26, 95, 'وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ', 'যেসব জনপদকে আমি ধ্বংস করে দিয়েছি, তার অধিবাসীদের ফিরে না আসা অবধারিত।', 'Waharamun AAala qaryatin ahlaknaha annahum la yarjiAAoona', 1, NOW(), NOW()),
(26, 96, 'حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبٖ يَنسِلُونَ', 'যে পর্যন্ত না ইয়াজুজ ও মাজুজকে বন্ধন মুক্ত করে দেয়া হবে এবং তারা প্রত্যেক উচ্চভুমি থেকে দ্রুত ছুটে আসবে।', 'Hatta itha futihat yajooju wamajooju wahum min kulli hadabin yansiloona', 1, NOW(), NOW()),
(26, 97, 'وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةٖ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ', 'আমোঘ প্রতিশ্রুত সময় নিকটবর্তী হলে কাফেরদের চক্ষু উচ্চে স্থির হয়ে যাবে; হায় আমাদের দূর্ভাগ্য, আমরা এ বিষয়ে বেখবর ছিলাম; বরং আমরা গোনাহগরই ছিলাম।', 'Waiqtaraba alwaAAdu alhaqqu faitha hiya shakhisatun absaru allatheena kafaroo ya waylana qad kunna fee ghaflatin min hatha bal kunna thalimeena', 1, NOW(), NOW()),
(26, 98, 'إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ', 'তোমরা এবং আল্লাহর পরিবর্তে তোমরা যাদের পুজা কর, সেগুলো দোযখের ইন্ধন। তোমরাই তাতে প্রবেশ করবে।', 'Innakum wama taAAbudoona min dooni Allahi hasabu jahannama antum laha waridoona', 1, NOW(), NOW()),
(26, 99, 'لَوۡ كَانَ هَـٰٓؤُلَآءِ ءَالِهَةٗ مَّا وَرَدُوهَاۖ وَكُلّٞ فِيهَا خَٰلِدُونَ', 'এই মূর্তিরা যদি উপাস্য হত, তবে জাহান্নামে প্রবেশ করত না। প্রত্যেকেই তাতে চিরস্থায়ী হয়ে পড়ে থাকবে।', 'Law kana haolai alihatan ma waradooha wakullun feeha khalidoona', 1, NOW(), NOW()),
(26, 100, 'لَهُمۡ فِيهَا زَفِيرٞ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ', 'তারা সেখানে চীৎকার করবে এবং সেখানে তারা কিছুই শুনতে পাবে না।', 'Lahum feeha zafeerun wahum feeha la yasmaAAoona', 1, NOW(), NOW()),
(26, 101, 'إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَـٰٓئِكَ عَنۡهَا مُبۡعَدُونَ', 'যাদের জন্য প্রথম থেকেই আমার পক্ষ থেকে কল্যাণ নির্ধারিত হয়েছে তারা দোযখ থেকে দূরে থাকবে।', 'Inna allatheena sabaqat lahum minna alhusna olaika AAanha mubAAadoona', 1, NOW(), NOW()),
(26, 102, 'لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ', 'তারা তার ক্ষীণতম শব্দও শুনবে না এবং তারা তাদের মনের বাসনা অনুযায়ী চিরকাল বসবাস করবে।', 'La yasmaAAoona haseesaha wahum fee ma ishtahat anfusuhum khalidoona', 1, NOW(), NOW()),
(26, 103, 'لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ', 'মহা ত্রাস তাদেরকে চিন্তান্বিত করবে না এবং ফেরেশতারা তাদেরকে অভ্যর্থনা করবেঃ আজ তোমাদের দিন, যে দিনের ওয়াদা তোমাদেরকে দেয়া হয়েছিল।', 'La yahzunuhumu alfazaAAu alakbaru watatalaqqahumu almalaikatu hatha yawmukumu allathee kuntum tooAAadoona', 1, NOW(), NOW()),
(26, 104, 'يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقٖ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ', 'সেদিন আমি আকাশকে গুটিয়ে নেব, যেমন গুটানো হয় লিখিত কাগজপত্র। যেভাবে আমি প্রথমবার সৃষ্টি করেছিলাম, সেভাবে পুনরায় সৃষ্টি করব। আমার ওয়াদা নিশ্চিত, আমাকে তা পূর্ণ করতেই হবে।', 'Yawma natwee alssamaa katayyi alssijlli lilkutubi kama badana awwala khalqin nuAAeeduhu waAAdan AAalayna inna kunna faAAileena', 1, NOW(), NOW()),
(26, 105, 'وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّـٰلِحُونَ', 'আমি উপদেশের পর যবুরে লিখে দিয়েছি যে, আমার সৎকর্মপরায়ণ বান্দাগণ অবশেষে পৃথিবীর অধিকারী হবে।', 'Walaqad katabna fee alzzaboori min baAAdi alththikri anna alarda yarithuha AAibadiya alssalihoona', 1, NOW(), NOW()),
(26, 106, 'إِنَّ فِي هَٰذَا لَبَلَٰغٗا لِّقَوۡمٍ عَٰبِدِينَ', 'এতে এবাদতকারী সম্প্রদায়ের জন্যে পর্যাপ্ত বিষয়বস্তু আছে।', 'Inna fee hatha labalaghan liqawmin AAabideena', 1, NOW(), NOW()),
(26, 107, 'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةٗ لِّلۡعَٰلَمِينَ', 'আমি আপনাকে বিশ্ববাসীর জন্যে রহমত স্বরূপই প্রেরণ করেছি।', 'Wama arsalnaka illa rahmatan lilAAalameena', 1, NOW(), NOW()),
(26, 108, 'قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ', 'বলুনঃ আমাকে তো এ আদেশই দেয়া হয়েছে যে, তোমাদের উপাস্য একমাত্র উপাস্য। সুতরাংতোমরা কি আজ্ঞাবহ হবে', 'Qul innama yooha ilayya annama ilahukum ilahun wahidun fahal antum muslimoona', 1, NOW(), NOW()),
(26, 109, 'فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءٖۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدٞ مَّا تُوعَدُونَ', 'অতঃপর যদি তারা মুখ ফিরিয়ে নেয়, তবে বলে দিনঃ আমি তোমাদেরকে পরিস্কার ভাবে সতর্ক করেছি এবং আমি জানি না, তোমাদেরকে যে ওয়াদা দেয়া হয়েছে, তা নিকটবর্তী না দূরবর্তী।', 'Fain tawallaw faqul athantukum AAala sawain wain adree aqareebun am baAAeedun ma tooAAadoona', 1, NOW(), NOW()),
(26, 110, 'إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ', 'তিনি জানেন, যে কথা সশব্দে বল এবং যে কথা তোমরা গোপন কর।', 'Innahu yaAAlamu aljahra mina alqawli wayaAAlamu ma taktumoona', 1, NOW(), NOW()),
(26, 111, 'وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةٞ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينٖ', 'আমি জানি না সম্ভবতঃ বিলম্বের মধ্যে তোমাদের জন্যে একটি পরীক্ষা এবং এক সময় পর্যন্ত ভোগ করার সুযোগ।', 'Wain adree laAAallahu fitnatun lakum wamataAAun ila heenin', 1, NOW(), NOW()),
(26, 112, 'قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ', 'পয়গাম্বর বললেনঃ হে আমার পালনকর্তা, আপনি ন্যায়ানুগ ফয়সালা করে দিন। আমাদের পালনকর্তা তো দয়াময়, তোমরা যা বলছ, সে বিষয়ে আমরা তাঁর কাছেই সাহায্য প্রার্থনা করি।', 'Qala rabbi ohkum bialhaqqi warabbuna alrrahmanu almustaAAanu AAala ma tasifoona', 1, NOW(), NOW()),
(27, 1, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمٞ', 'হে লোক সকল! তোমাদের পালনকর্তাকে ভয় কর। নিশ্চয় কেয়ামতের প্রকম্পন একটি ভয়ংকর ব্যাপার।', 'Ya ayyuha alnnasu ittaqoo rabbakum inna zalzalata alssaAAati shayon AAatheemun', 1, NOW(), NOW()),
(27, 2, 'يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٞ', 'যেদিন তোমরা তা প্রত্যক্ষ করবে, সেদিন প্রত্যেক স্তন্যধাত্রী তার দুধের শিশুকে বিস্মৃত হবে এবং প্রত্যেক গর্ভবতী তার গর্ভপাত করবে এবং মানুষকে তুমি দেখবে মাতাল; অথচ তারা মাতাল নয় বস্তুতঃ আল্লাহর আযাব সুকঠিন।', 'Yawma tarawnaha tathhalu kullu murdiAAatin AAamma ardaAAat watadaAAu kullu thati hamlin hamlaha watara alnnasa sukara wama hum bisukara walakinna AAathaba Allahi shadeedun', 1, NOW(), NOW()),
(27, 3, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَيَتَّبِعُ كُلَّ شَيۡطَٰنٖ مَّرِيدٖ', 'কতক মানুষ অজ্ঞানতাবশতঃ আল্লাহ সম্পꦣ2503;ক বিতর্ক করে এবং প্রত্যেক অবাধ্য শয়তানের অনুসরণ করে।', 'Wamina alnnasi man yujadilu fee Allahi bighayri AAilmin wayattabiAAu kulla shaytanin mareedin', 1, NOW(), NOW()),
(27, 4, 'كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'শয়তান সম্পর্কে লিখে দেয়া হয়েছে যে, যে কেউ তার সাথী হবে, সে তাকে বিভ্রান্ত করবে এবং দোযখের আযাবের দিকে পরিচালিত করবে।', 'Kutiba AAalayhi annahu man tawallahu faannahu yudilluhu wayahdeehi ila AAathabi alssaAAeeri', 1, NOW(), NOW()),
(27, 5, 'يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ', 'হে লোকসকল! যদি তোমরা পুনরুত্থানের ব্যাপারে সন্দিগ্ধ হও, তবে (ভেবে দেখ-) আমি তোমাদেরকে মৃত্তিকা থেকে সৃষ্টি করেছি। এরপর বীর্য থেকে, এরপর জমাট রক্ত থেকে, এরপর পূর্ণাকৃতিবিশিষ্ট ও অপূর্ণাকৃতিবিশিষ্ট মাংসপিন্ড থেকে, তোমাদের কাছে ব্যক্ত করার জন্যে। আর আমি এক নির্দিষ্ট কালের জন্যে মাতৃগর্ভে যা ইচ্ছা রেখে দেই, এরপর আমি তোমাদেরকে শিশু অবস্থায় বের করি; তারপর যাতে তোমরা যৌবনে পদার্পণ কর। তোমাদের মধ্যে কেউ কেউ মৃত্যুমুখে পতিত হয় এবং তোমাদের মধ্যে কাউকে নিষ্কর্মা বয়স পর্যন্ত পৌছানো হয়, যাতে সে জানার পর জ্ঞাত বিষয় সম্পর্কে সজ্ঞান থাকে না। তুমি ভূমিকে পতিত দেখতে পাও, অতঃপর আমি যখন তাতে বৃষ্টি বর্ষণ করি, তখন তা সতেজ ও স্ফীত হয়ে যায় এবং সর্বপ্রকার সুদৃশ্য উদ্ভিদ উৎপন্ন করে।', 'Ya ayyuha alnnasu in kuntum fee raybin mina albaAAthi fainna khalaqnakum min turabin thumma min nutfatin thumma min AAalaqatin thumma min mudghatin mukhallaqatin waghayri mukhallaqatin linubayyina lakum wanuqirru fee alarhami ma nashao ila ajalin musamman thumma nukhrijukum tiflan thumma litablughoo ashuddakum waminkum man yutawaffa waminkum man yuraddu ila arthali alAAumuri likayla yaAAlama min baAAdi AAilmin shayan watara alarda hamidatan faitha anzalna AAalayha almaa ihtazzat warabat waanbatat min kulli zawjin baheejin', 1, NOW(), NOW()),
(27, 6, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'এগুলো এ কারণে যে, আল্লাহ সত্য এবং তিনি মৃতকে জীবিত করেন এবং তিনি সবকিছুর উপর ক্ষমতাবান।', 'Thalika bianna Allaha huwa alhaqqu waannahu yuhyee almawta waannahu AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(27, 7, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٞ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ', 'এবং এ কারণে যে, কেয়ামত অবশ্যম্ভাবী, এতে সন্দেহ নেই এবং এ কারণে যে, কবরে যারা আছে, আল্লাহ তাদেরকে পুনরুত্থিত করবেন।', 'Waanna alssaAAata atiyatun la rayba feeha waanna Allaha yabAAathu man fee alquboori', 1, NOW(), NOW()),
(27, 8, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمٖ وَلَا هُدٗى وَلَا كِتَٰبٖ مُّنِيرٖ', 'কতক মানুষ জ্ঞান; প্রমাণ ও উজ্জ্বল কিতাব ছাড়াই আল্লাহ সম্পর্কে বিতর্ক করে।', 'Wamina alnnasi man yujadilu fee Allahi bighayri AAilmin wala hudan wala kitabin muneerin', 1, NOW(), NOW()),
(27, 9, 'ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ', 'সে পার্শ্ব পরিবর্তন করে বিতর্ক করে, যাতে আল্লাহর পথ থেকে বিভ্রান্ত করে দেয়। তার জন্যে দুনিয়াতে লাঞ্ছনা আছে এবং কেয়ামতের দিন আমি তাকে দহন-যন্ত্রণা আস্বাদন করাব।', 'Thaniya AAitfihi liyudilla AAan sabeeli Allahi lahu fee alddunya khizyun wanutheequhu yawma alqiyamati AAathaba alhareeqi', 1, NOW(), NOW()),
(27, 10, 'ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ', 'এটা তোমার দুই হাতের কর্মের কারণে, আল্লাহ বান্দাদের প্রতি জুলুম করেন না।', 'Thalika bima qaddamat yadaka waanna Allaha laysa bithallamin lilAAabeedi', 1, NOW(), NOW()),
(27, 11, 'وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ', 'মানুষের মধ্যে কেউ কেউ দ্বিধা-দ্বন্দ্বে জড়িত হয়ে আল্লাহর এবাদত করে। যদি সে কল্যাণ প্রাপ্ত হয়, তবে এবাদতের উপর কায়েম থাকে এবং যদি কোন পরীক্ষায় পড়ে, তবে পূর্বাবস্থায় ফিরে যায়। সে ইহকালে ও পরকালে ক্ষতিগ্রস্ত। এটাই প্রকাশ্য ক্ষতি', 'Wamina alnnasi man yaAAbudu Allaha AAala harfin fain asabahu khayrun itmaanna bihi wain asabathu fitnatun inqalaba AAala wajhihi khasira alddunya waalakhirata thalika huwa alkhusranu almubeenu', 1, NOW(), NOW()),
(27, 12, 'يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ', 'সে আল্লাহর পরিবর্তে এমন কিছুকে ডাকে, যে তার অপকার করতে পারে না এবং উপকারও করতে পারে না। এটাই চরম পথভ্রষ্টতা।', 'YadAAoo min dooni Allahi ma la yadurruhu wama la yanfaAAuhu thalika huwa alddalalu albaAAeedu', 1, NOW(), NOW()),
(27, 13, 'يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ', 'সে এমন কিছুকে ডাকে, যার অপকার উপকারের আগে পৌছে। কত মন্দ এই বন্ধু এবং কত মন্দ এই সঙ্গী।', 'YadAAoo laman darruhu aqrabu min nafAAihi labisa almawla walabisa alAAasheeru', 1, NOW(), NOW()),
(27, 14, 'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ', 'যারা বিশ্বাস স্থাপন করে ও সৎকর্ম সম্পাদন করে, আল্লাহ তাদেরকে জান্নাতে দাখিল করবেন, যার তলদেশ দিয়ে নির্ঝরণীসমূহ প্রবাহিত হয়। আল্লাহ যা ইচ্ছা তাই করেন।', 'Inna Allaha yudkhilu allatheena amanoo waAAamiloo alssalihati jannatin tajree min tahtiha alanharu inna Allaha yafAAalu ma yureedu', 1, NOW(), NOW()),
(27, 15, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ', 'সে ধারণা করে যে, আল্লাহ কখনই ইহকালে ও পরকালে রাসূলকে সাহায্য করবেন না, সে একটি রশি আকাশ পর্যন্ত ঝুলিয়ে নিক; এরপর কেটে দিক; অতঃপর দেখুক তার এই কৌশল তার আক্রোশ দূর করে কিনা।', 'Man kana yathunnu an lan yansurahu Allahu fee alddunya waalakhirati falyamdud bisababin ila alssamai thumma liyaqtaAA falyanthur hal yuthhibanna kayduhu ma yagheethu', 1, NOW(), NOW()),
(27, 16, 'وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتٖ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ', 'এমনিভাবে আমি সুস্পষ্ট আয়াত রূপে কোরআন নাযিল করেছি এবং আল্লাহ-ই যাকে ইচ্ছা হেদায়েত করেন।', 'Wakathalika anzalnahu ayatin bayyinatin waanna Allaha yahdee man yureedu', 1, NOW(), NOW()),
(27, 17, 'إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ', 'যারা মুসলমান, যারা ইহুদী, সাবেয়ী, খ্রীষ্টান, অগ্নিপুজক এবং যারা মুশরেক, কেয়ামতের দিন আল্লাহ অবশ্যই তাদের মধ্যে ফায়সালা করে দেবেন। সবকিছুই আল্লাহর দৃষ্টির সামনে।', 'Inna allatheena amanoo waallatheena hadoo waalssabieena waalnnasara waalmajoosa waallatheena ashrakoo inna Allaha yafsilu baynahum yawma alqiyamati inna Allaha AAala kulli shayin shaheedun', 1, NOW(), NOW()),
(27, 18, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٞ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩', 'তুমি কি দেখনি যে, আল্লাহকে সেজদা করে যা কিছু আছে নভোমন্ডলে, যা কিছু আছে ভুমন্ডলে, সূর্য, চন্দ্র, তারকারাজি পর্বতরাজি বৃক্ষলতা, জীবজন্তু এবং অনেক মানুষ। আবার অনেকের উপর অবধারিত হয়েছে শাস্তি। আল্লাহ যাকে ইচ্ছা লাঞ্ছিত করেন, তাকে কেউ সম্মান দিতে পারে না। আল্লাহ যা ইচ্ছা তাই করেন', 'Alam tara anna Allaha yasjudu lahu man fee alssamawati waman fee alardi waalshshamsu waalqamaru waalnnujoomu waaljibalu waalshshajaru waalddawabbu wakatheerun mina alnnasi wakatheerun haqqa AAalayhi alAAathabu waman yuhini Allahu fama lahu min mukrimin inna Allaha yafAAalu ma yashao', 1, NOW(), NOW()),
(27, 19, '۞هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابٞ مِّن نَّارٖ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ', 'এই দুই বাদী বিবাদী, তারা তাদের পালনকর্তা সম্পর্কে বিতর্ক করে। অতএব যারা কাফের, তাদের জন্যে আগুনের পোশাক তৈরী করা হয়েছে। তাদের মাথার উপর ফুটন্ত পানি ঢেলে দেয়া হবে।', 'Hathani khasmani ikhtasamoo fee rabbihim faallatheena kafaroo quttiAAat lahum thiyabun min narin yusabbu min fawqi ruoosihimu alhameemu', 1, NOW(), NOW()),
(27, 20, 'يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ', 'ফলে তাদের পেটে যা আছে, তা এবং চর্ম গলে বের হয়ে যাবে।', 'Yusharu bihi ma fee butoonihim waaljuloodu', 1, NOW(), NOW()),
(27, 21, 'وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ', 'তাদের জন্যে আছে লোহার হাতুড়ি।', 'Walahum maqamiAAu min hadeedin', 1, NOW(), NOW()),
(27, 22, 'كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ', 'তারা যখনই যন্ত্রনায় অতিষ্ঠ হয়ে জাহান্নাম থেকে বের হতে চাইবে, তখনই তাদেরকে তাতে ফিরিয়ে দেয়া হবে। বলা হবেঃ দহন শাস্তি আস্বাদন কর।', 'Kullama aradoo an yakhrujoo minha min ghammin oAAeedoo feeha wathooqoo AAathaba alhareeqi', 1, NOW(), NOW()),
(27, 23, 'إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ', 'নিশ্চয় যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম করে, আল্লাহ তাদেরকে দাখিল করবেন উদ্যান সমূহে, যার তলদেশ দিয়ে নির্ঝরিণীসমূহ প্রবাহিত হবে। তাদেরকে তথায় স্বর্ণ-কংকন ও মুক্তা দ্বারা অলংকৃত করা হবে এবং তথায় তাদের পোশাক হবে রেশমী।', 'Inna Allaha yudkhilu allatheena amanoo waAAamiloo alssalihati jannatin tajree min tahtiha alanharu yuhallawna feeha min asawira min thahabin waluluan walibasuhum feeha hareerun', 1, NOW(), NOW()),
(27, 24, 'وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ', 'তারা পথপ্রদর্শিত হয়েছিল সৎবাক্যের দিকে এবং পরিচালিত হয়েছিল প্রশংসিত আল্লাহর পথপানে।', 'Wahudoo ila alttayyibi mina alqawli wahudoo ila sirati alhameedi', 1, NOW(), NOW()),
(27, 25, 'إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمٖ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمٖ', 'যারা কুফর করে ও আল্লাহর পথে বাধা সৃষ্টি করে এবং সেই মসজিদে হারাম থেকে বাধা দেয়, যাকে আমি প্রস্তুত করেছি স্থানীয় ও বহিরাগত সকল মানুষের জন্যে সমভাবে এবং যে মসজিদে হারামে অন্যায়ভাবে কোন ধর্মদ্রোহী কাজ করার ইচছা করে, আমি তাদেরকে যন্ত্রানাদায়ক শাস্তি আস্বাদন করাব।', 'Inna allatheena kafaroo wayasuddoona AAan sabeeli Allahi waalmasjidi alharami allathee jaAAalnahu lilnnasi sawaan alAAakifu feehi waalbadi waman yurid feehi biilhadin bithulmin nuthiqhu min AAathabin aleemin', 1, NOW(), NOW()),
(27, 26, 'وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـٔٗا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'যখন আমি ইব্রাহীমকে বায়তুল্লাহর স্থান ঠিক করে দিয়েছিলাম যে, আমার সাথে কাউকে শরীক করো না এবং আমার গৃহকে পবিত্র রাখ তাওয়াফকারীদের জন্যে, নামাযে দন্ডায়মানদের জন্যে এবং রকু সেজদাকারীদের জন্যে।', 'Waith bawwana liibraheema makana albayti an la tushrik bee shayan watahhir baytiya lilttaifeena waalqaimeena waalrrukkaAAi alssujoodi', 1, NOW(), NOW()),
(27, 27, 'وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالٗا وَعَلَىٰ كُلِّ ضَامِرٖ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقٖ', 'এবং মানুষের মধ্যে হজ্বের জন্যে ঘোষণা প্রচার কর। তারা তোমার কাছে আসবে পায়ে হেঁটে এবং সর্বপ্রকার কৃশকায় উটের পিঠে সওয়ার হয়ে দূর-দূরান্ত থেকে।', 'Waaththin fee alnnasi bialhajji yatooka rijalan waAAala kulli damirin yateena min kulli fajjin AAameeqin', 1, NOW(), NOW()),
(27, 28, 'لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامٖ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ', 'যাতে তারা তাদের কল্যাণের স্থান পর্যন্ত পৌছে এবং নির্দিষ্ট দিনগুলোতে আল্লাহর নাম স্মরণ করে তাঁর দেয়া চতুস্পদ জন্তু যবেহ করার সময়। অতঃপর তোমরা তা থেকে আহার কর এবং দুঃস্থ-অভাবগ্রস্থকে আহার করাও।', 'Liyashhadoo manafiAAa lahum wayathkuroo isma Allahi fee ayyamin maAAloomatin AAala ma razaqahum min baheemati alanAAami fakuloo minha waatAAimoo albaisa alfaqeera', 1, NOW(), NOW()),
(27, 29, 'ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ', 'এরপর তারা যেন দৈহিক ময়লা দূর করে দেয়, তাদের মানত পূর্ণ করে এবং এই সুসংরক্ষিত গৃহের তাওয়াফ করে।', 'Thumma lyaqdoo tafathahum walyoofoo nuthoorahum walyattawwafoo bialbayti alAAateeqi', 1, NOW(), NOW()),
(27, 30, 'ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ', 'এটা শ্রবণযোগ্য। আর কেউ আল্লাহর সম্মানযোগ্য বিধানাবলীর প্রতি সম্মান প্রদর্শন করলে পালনকর্তার নিকট তা তার জন্যে উত্তম। উল্লেখিত ব্যতিক্রমগুলো ছাড়া তোমাদের জন্যে চতুস্পদ জন্তু হালাল করা হয়েছে। সুতরাং তোমরা মূর্তিদের অপবিত্রতা থেকে বেঁচে থাক এবং মিথ্যা কথন থেকে দূরে সরে থাক', 'Thalika waman yuAAaththim hurumati Allahi fahuwa khayrun lahu AAinda rabbihi waohillat lakumu alanAAamu illa ma yutla AAalaykum faijtaniboo alrrijsa mina alawthani waijtaniboo qawla alzzoori', 1, NOW(), NOW()),
(27, 31, 'حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ', 'আল্লাহর দিকে একনিষ্ট হয়ে, তাঁর সাথে শরীক না করে; এবং যে কেউ আল্লাহর সাথে শরীক করল; সে যেন আকাশ থেকে ছিটকে পড়ল, অতঃপর মৃতভোজী পাখী তাকে ছোঁ মেরে নিয়ে গেল অথবা বাতাস তাকে উড়িয়ে নিয়ে কোন দূরবর্তী স্থানে নিক্ষেপ করল।', 'Hunafaa lillahi ghayra mushrikeena bihi waman yushrik biAllahi fakaannama kharra mina alssamai fatakhtafuhu alttayru aw tahwee bihi alrreehu fee makanin saheeqin', 1, NOW(), NOW()),
(27, 32, 'ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَـٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ', 'এটা শ্রবণযোগ্য কেউ আল্লাহর নামযুক্ত বস্তুসমুহের প্রতি সম্মান প্রদর্শন করলে তা তো তার হৃদয়ের আল্লাহভীতি প্রসূত।', 'Thalika waman yuAAaththim shaAAaira Allahi fainnaha min taqwa alquloobi', 1, NOW(), NOW()),
(27, 33, 'لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ', 'চতুস্পদ জন্তুসমূহের মধ্যে তোমাদের জন্যে নির্দিষ্টকাল পর্যন্ত উপকার রয়েছে। অতঃপর এগুলোকে পৌছাতে হবে মুক্ত গৃহ পর্যন্ত।', 'Lakum feeha manafiAAu ila ajalin musamman thumma mahilluha ila albayti alAAateeqi', 1, NOW(), NOW()),
(27, 34, 'وَلِكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكٗا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ', 'আমি প্রত্যেক উম্মতের জন্যে কোরবানী নির্ধারণ করেছি, যাতে তারা আল্লাহর দেয়া চতুস্পদ জন্তু যবেহ কারার সময় আল্লাহর নাম উচ্চারণ করে। অতএব তোমাদের আল্লাহ তো একমাত্র আল্লাহ সুতরাং তাঁরই আজ্ঞাধীন থাক এবং বিনয়ীগণকে সুসংবাদ দাও', 'Walikulli ommatin jaAAalna mansakan liyathkuroo isma Allahi AAala ma razaqahum min baheemati alanAAami failahukum ilahun wahidun falahu aslimoo wabashshiri almukhbiteena', 1, NOW(), NOW()),
(27, 35, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ', 'যাদের অন্তর আল্লাহর নাম স্মরণ করা হলে ভীত হয় এবং যারা তাদের বিপদাপদে ধৈর্য্যধারণ করে এবং যারা নামায কায়েম করে ও আমি যা দিয়েছি, তা থেকে ব্যয় করে।', 'Allatheena itha thukira Allahu wajilat quloobuhum waalssabireena AAala ma asabahum waalmuqeemee alssalati wamimma razaqnahum yunfiqoona', 1, NOW(), NOW()),
(27, 36, 'وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَـٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرٞۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ', 'এবং কা’বার জন্যে উৎসর্গীকৃত উটকে আমি তোমাদের জন্যে আল্লাহর অন্যতম নিদর্শন করেছি। এতে তোমাদের জন্যে মঙ্গল রয়েছে। সুতরাং সারিবদ্ধভাবে বাঁধা অবস্থায় তাদের যবেহ করার সময় তোমরা আল্লাহর নাম উচ্চারণ কর। অতঃপর যখন তারা কাত হয়ে পড়ে যায় তখন তা থেকে তোমরা আহার কর এবং আহার করাও যে কিছু যাচ্ঞা করে না তাকে এবং যে যাচ্ঞা করে তাকে। এমনিভাবে আমি এগুলোকে তোমাদের বশীভূত করে দিয়েছি, যাতে তোমরা কৃতজ্ঞতা প্রকাশ কর।', 'Waalbudna jaAAalnaha lakum min shaAAairi Allahi lakum feeha khayrun faothkuroo isma Allahi AAalayha sawaffa faitha wajabat junoobuha fakuloo minha waatAAimoo alqaniAAa waalmuAAtarra kathalika sakhkharnaha lakum laAAallakum tashkuroona', 1, NOW(), NOW()),
(27, 37, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ', 'এগুলোর গোশত ও রক্ত আল্লাহর কাছে পৌঁছে না, কিন্তু পৌঁছে তাঁর কাছে তোমাদের মনের তাকওয়া। এমনিভাবে তিনি এগুলোকে তোমাদের বশ করে দিয়েছেন, যাতে তোমরা আল্লাহর মহত্ত্ব ঘোষণা কর এ কারণে যে, তিনি তোমাদের পথ প্রদর্শন করেছেন। সুতরাং সৎকর্মশীলদের সুসংবাদ শুনিয়ে দিন।', 'Lan yanala Allaha luhoomuha wala dimaoha walakin yanaluhu alttaqwa minkum kathalika sakhkharaha lakum litukabbiroo Allaha AAala ma hadakum wabashshiri almuhsineena', 1, NOW(), NOW()),
(27, 38, '۞إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٖ كَفُورٍ', 'আল্লাহ মুমিনদের থেকে শত্রুদেরকে হটিয়ে দেবেন। আল্লাহ কোন বিশ্বাসঘাতক অকৃতজ্ঞকে পছন্দ করেন না।', 'Inna Allaha yudafiAAu AAani allatheena amanoo inna Allaha la yuhibbu kulla khawwanin kafoorin', 1, NOW(), NOW()),
(27, 39, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ', 'যুদ্ধে অনুমতি দেয়া হল তাদেরকে যাদের সাথে কাফেররা যুদ্ধ করে; কারণ তাদের প্রতি অত্যাচার করা হয়েছে। আল্লাহ তাদেরকে সাহায্য করতে অবশ্যই সক্ষম।', 'Othina lillatheena yuqataloona biannahum thulimoo wainna Allaha AAala nasrihim laqadeerun', 1, NOW(), NOW()),
(27, 40, 'ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ', 'যাদেরকে তাদের ঘর-বাড়ী থেকে অন্যায়ভাবে বহিস্কার করা হয়েছে শুধু এই অপরাধে যে, তারা বলে আমাদের পালনকর্তা আল্লাহ। আল্লাহ যদি মানবজাতির একদলকে অপর দল দ্বারা প্রতিহত না করতেন, তবে (খ্রীষ্টানদের) নির্ঝন গির্জা, এবাদত খানা, (ইহুদীদের) উপাসনালয় এবং মসজিদসমূহ বিধ্বস্ত হয়ে যেত, যেগুলাতে আল্লাহর নাম অধিক স্মরণ করা হয়। আল্লাহ নিশ্চয়ই তাদেরকে সাহায্য করবেন, যারা আল্লাহর সাহায্য করে। নিশ্চয়ই আল্লাহ পরাক্রমশালী শক্তিধর।', 'Allatheena okhrijoo min diyarihim bighayri haqqin illa an yaqooloo rabbuna Allahu walawla dafAAu Allahi alnnasa baAAdahum bibaAAdin lahuddimat sawamiAAu wabiyaAAun wasalawatun wamasajidu yuthkaru feeha ismu Allahi katheeran walayansuranna Allahu man yansuruhu inna Allaha laqawiyyun AAazeezun', 1, NOW(), NOW()),
(27, 41, 'ٱلَّذِينَ إِن مَّكَّنَّـٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ', 'তারা এমন লোক যাদেরকে আমি পৃথিবীতে শক্তি-সামর্থ?2470;ান করলে তারা নামায কায়েম করবে, যাকাত দেবে এবং সৎকাজে আদেশ ও অসৎকাজে নিষেধ করবে। প্রত্যেক কর্মের পরিণাম আল্লাহর এখতিয়ারভূক্ত।', 'Allatheena in makkannahum fee alardi aqamoo alssalata waatawoo alzzakata waamaroo bialmaAAroofi wanahaw AAani almunkari walillahi AAaqibatu alomoori', 1, NOW(), NOW()),
(27, 42, 'وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَعَادٞ وَثَمُودُ', 'তারা যদি আপনাকে মিথ্যাবাদী বলে, তবে তাদের পূর্বে মিথ্যাবাদী বলেছে কওমে নূহ, আদ, সামুদ', 'Wain yukaththibooka faqad kaththabat qablahum qawmu noohin waAAadun wathamoodu', 1, NOW(), NOW()),
(27, 43, 'وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطٖ', 'ইব্রাহীম ও লূতের সম্প্রদায়ও।', 'Waqawmu ibraheema waqawmu lootin', 1, NOW(), NOW()),
(27, 44, 'وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ', 'এবং মাদইয়ানের অধিবাসীরা এবং মিথ্যাবাদী বলা হয়েছিল মূসাকেও। অতঃপর আমি কাফেরদেরকে সুযোগ দিয়েছিলাম এরপর তাদেরকে পাকড়াও করেছিলাম অতএব কি ভীষণ ছিল আমাকে অস্বীকৃতির পরিণাম।', 'Waashabu madyana wakuththiba moosa faamlaytu lilkafireena thumma akhathtuhum fakayfa kana nakeeri', 1, NOW(), NOW()),
(27, 45, 'فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةٞ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرٖ مُّعَطَّلَةٖ وَقَصۡرٖ مَّشِيدٍ', 'আমি কত জনপদ ধ্বংস করেছি এমতাবস্থায় যে, তারা ছিল গোনাহগার। এই সব জনপদ এখন ধ্বংসস্তুপে পরিণত হয়েছে এবং কত কূপ পরিত্যক্ত হয়েছে ও কত সুদৃঢ় প্রাসাদ ধ্বংস হয়েছে।', 'Fakaayyin min qaryatin ahlaknaha wahiya thalimatun fahiya khawiyatun AAala AAurooshiha wabirin muAAattalatin waqasrin masheedin', 1, NOW(), NOW()),
(27, 46, 'أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانٞ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ', 'তারা কি এই উদ্দেশ্যে দেশ ভ্রমণ করেনি, যাতে তারা সমঝদার হৃদয় ও শ্রবণ শক্তি সম্পন্ন কর্ণের অধিকারী হতে পারে? বস্তুতঃ চক্ষু তো অন্ধ হয় না, কিন্তু বক্ষ স্থিত অন্তরই অন্ধ হয়।', 'Afalam yaseeroo fee alardi fatakoona lahum quloobun yaAAqiloona biha aw athanun yasmaAAoona biha fainnaha la taAAma alabsaru walakin taAAma alquloobu allatee fee alssudoori', 1, NOW(), NOW()),
(27, 47, 'وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةٖ مِّمَّا تَعُدُّونَ', 'তারা আপনাকে আযাব ত্বরান্বিত করতে বলে। অথচ আল্লাহ কখনও তাঁর ওয়াদা ভঙ্গ করেন না। আপনার পালনকর্তার কাছে একদিন তোমাদের গণনার এক হাজার বছরের সমান।', 'WayastaAAjiloonaka bialAAathabi walan yukhlifa Allahu waAAdahu wainna yawman AAinda rabbika kaalfi sanatin mimma taAAuddoona', 1, NOW(), NOW()),
(27, 48, 'وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةٞ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ', 'এবং আমি কত জনপদকে অবকাশ দিয়েছি এমতাবস্থায় যে, তারা গোনাহগার ছিল। এরপর তাদেরকে পাকড়াও করেছি এবং আমার কাছেই প্রত্যাবর্তন করতে হবে।', 'Wakaayyin min qaryatin amlaytu laha wahiya thalimatun thumma akhathtuha wailayya almaseeru', 1, NOW(), NOW()),
(27, 49, 'قُلۡ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرٞ مُّبِينٞ', 'বলুনঃ হে লোক সকল! আমি তো তোমাদের জন্যে স্পষ্ট ভাষায় সতর্ককারী।', 'Qul ya ayyuha alnnasu innama ana lakum natheerun mubeenun', 1, NOW(), NOW()),
(27, 50, 'فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ', 'সুতরাং যারা বিশ্বাস স্থাপন করেছে এবং সৎকর্ম করেছে, তাদের জন্যে আছে পাপ মার্জনা এবং সম্মানজনক রুযী।', 'Faallatheena amanoo waAAamiloo alssalihati lahum maghfiratun warizqun kareemun', 1, NOW(), NOW()),
(27, 51, 'وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ', 'এবং যারা আমার আয়াতসমূহকে ব্যর্থ করার জন্যে চেষ্টা করে, তারাই দোযখের অধিবাসী।', 'Waallatheena saAAaw fee ayatina muAAajizeena olaika ashabu aljaheemi', 1, NOW(), NOW()),
(27, 52, 'وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'আমি আপনার পূর্বে যে সমস্ত রাসূল ও নবী প্রেরণ করেছি, তারা যখনই কিছু কল্পনা করেছে, তখনই শয়তান তাদের কল্পনায় কিছু মিশ্রণ করে দিয়েছে। অতঃপর আল্লাহ দূর করে দেন শয়তান যা মিশ্রণ করে। এরপর আল্লাহ তাঁর আয়াতসমূহকে সু-প্রতিষ্ঠিত করেন এবং আল্লাহ জ্ঞানময়, প্রজ্ঞাময়।', 'Wama arsalna min qablika min rasoolin wala nabiyyin illa itha tamanna alqa alshshaytanu fee omniyyatihi fayansakhu Allahu ma yulqee alshshaytanu thumma yuhkimu Allahu ayatihi waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(27, 53, 'لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةٗ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدٖ', 'এ কারণে যে, শয়তান যা মিশ্রণ করে, তিনি তা পরীক্ষাস্বরূপ করে দেন, তাদের জন্যে, যাদের অন্তরে রোগ আছে এবং যারা পাষাণহৃদয়। গোনাহগাররা দূরবর্তী বিরোধিতায় লিপ্ত আছে।', 'LiyajAAala ma yulqee alshshaytanu fitnatan lillatheena fee quloobihim maradun waalqasiyati quloobuhum wainna alththalimeena lafee shiqaqin baAAeedin', 1, NOW(), NOW()),
(27, 54, 'وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'এবং এ কারণেও যে, যাদেরকে জ্ঞানদান করা হয়েছে; তারা যেন জানে যে এটা আপনার পালনকর্তার পক্ষ থেকে সত্য; অতঃপর তারা যেন এতে বিশ্বাস স্তাপন করে এবং তাদের অন্তর যেন এর প্রতি বিজয়ী হয়। আল্লাহই বিশ্বাস স্থাপনকারীকে সরল পথ প্রদর্শন করেন।', 'WaliyaAAlama allatheena ootoo alAAilma annahu alhaqqu min rabbika fayuminoo bihi fatukhbita lahu quloobuhum wainna Allaha lahadi allatheena amanoo ila siratin mustaqeemin', 1, NOW(), NOW()),
(27, 55, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةٖ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ', 'কাফেররা সর্বদাই সন্দেহ পোষন করবে যে পর্যন্ত না তাদের কাছে আকস্মিকভাবে কেয়ামত এসে পড়ে অথবা এসে পড়ে তাদের কাছে এমন দিবসের শাস্তি যা থেকে রক্ষার উপায় নেই।', 'Wala yazalu allatheena kafaroo fee miryatin minhu hatta tatiyahumu alssaAAatu baghtatan aw yatiyahum AAathabu yawmin AAaqeemin', 1, NOW(), NOW()),
(27, 56, 'ٱلۡمُلۡكُ يَوۡمَئِذٖ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فِي جَنَّـٰتِ ٱلنَّعِيمِ', 'রাজত্ব সেদিন আল্লাহরই; তিনিই তাদের বিচার করবেন। অতএব যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে তারা নেয়ামত পূর্ণ কাননে থাকবে।', 'Almulku yawmaithin lillahi yahkumu baynahum faallatheena amanoo waAAamiloo alssalihati fee jannati alnnaAAeemi', 1, NOW(), NOW()),
(27, 57, 'وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ', 'এবং যারা কুফরি করে এবং আমার আয়াত সমূহকে মিথ্যা বলে তাদের জন্যে লাঞ্ছনাকর শাস্তি রয়েছে।', 'Waallatheena kafaroo wakaththaboo biayatina faolaika lahum AAathabun muheenun', 1, NOW(), NOW()),
(27, 58, 'وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ', 'যারা আল্লাহর পথে গৃহ ত্যাগ করেছে, এরপর নিহত হয়েছে অথবা মরে গেছে; আল্লাহ তাদেরকে অবশ্যই উৎকৃষ্ট জীবিকা দান করবেন এবং আল্লাহ সর্বোৎকৃষ্ট রিযিক দাতা।', 'Waallatheena hajaroo fee sabeeli Allahi thumma qutiloo aw matoo layarzuqannahumu Allahu rizqan hasanan wainna Allaha lahuwa khayru alrraziqeena', 1, NOW(), NOW()),
(27, 59, 'لَيُدۡخِلَنَّهُم مُّدۡخَلٗا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٞ', 'তাদেরকে অবশ্যই এমন এক স্থানে পৌছাবেন, যাকে তারা পছন্দ করবে এবং আল্লাহ জ্ঞানময়, সহনশীল।', 'Layudkhilannahum mudkhalan yardawnahu wainna Allaha laAAaleemun haleemun', 1, NOW(), NOW()),
(27, 60, '۞ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ', 'এ তো শুনলে, যে ব্যক্তি নিপীড়িত হয়ে নিপীড়ন পরিমাণে প্রতিশোধ গ্রহণ করে এবং পুনরায় সে নিপীড়িত হয়, আল্লাহ অবশ্যই তাকে সাহায্য করবেন। নিশ্চয় আল্লাহ মার্জনাকারী ক্ষমাশীল।', 'Thalika waman AAaqaba bimithli ma AAooqiba bihi thumma bughiya AAalayhi layansurannahu Allahu inna Allaha laAAafuwwun ghafoorun', 1, NOW(), NOW()),
(27, 61, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ', 'এটা এ জন্যে যে, আল্লাহ রাত্রিকে দিনের মধ্যে এবং দিনকে রাত্রির মধ্য দাখিল করে দেন এবং আল্লাহ সবকিছু শোনেন, দেখেন।', 'Thalika bianna Allaha yooliju allayla fee alnnahari wayooliju alnnahara fee allayli waanna Allaha sameeAAun baseerun', 1, NOW(), NOW()),
(27, 62, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ', 'এটা এ কারণেও যে, আল্লাহই সত্য; আর তাঁর পরিবর্তে তারা যাকে ডাকে, তা অসত্য এবং আল্লাহই সবার উচ্চে, মহান।', 'Thalika bianna Allaha huwa alhaqqu waanna ma yadAAoona min doonihi huwa albatilu waanna Allaha huwa alAAaliyyu alkabeeru', 1, NOW(), NOW()),
(27, 63, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٞ', 'তুমি কি দেখ না যে, আল্লাহ আকাশ থেকে পানি বর্ষণ করেন, অতঃপর ভূপৃষ্ট সবুজ-শ্যামল হয়ে উঠে। নিশ্চয় আল্লাহ সুক্ষদর্শী, সর্ববিষয়ে খবরদার।', 'Alam tara anna Allaha anzala mina alssamai maan fatusbihu alardu mukhdarratan inna Allaha lateefun khabeerun', 1, NOW(), NOW()),
(27, 64, 'لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ', 'নভোমন্ডল ও ভুপৃষ্ঠে যা কিছু আছে, সব তাঁরই এবং আল্লাহই অভাবমুক্ত প্রশংসার অধিকারী।', 'Lahu ma fee alssamawati wama fee alardi wainna Allaha lahuwa alghaniyyu alhameedu', 1, NOW(), NOW()),
(27, 65, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ', 'তুমি কি দেখ না যে, ভূপৃষ্টে যা আছে এবং সমুদ্রে চলমান নৌকা তৎসমুদয়কে আল্লাহ নিজ আদেশে তোমাদের অধীন করে দিয়েছেন এবং তিনি আকাশ স্থির রাখেন, যাতে তাঁর আদেশ ব্যতীত ভূপৃষ্টে পতিত না হয়। নিশ্চয় আল্লাহ মানুষের প্রতি করুণাশীল, দয়াবান।', 'Alam tara anna Allaha sakhkhara lakum ma fee alardi waalfulka tajree fee albahri biamrihi wayumsiku alssamaa an taqaAAa AAala alardi illa biithnihi inna Allaha bialnnasi laraoofun raheemun', 1, NOW(), NOW()),
(27, 66, 'وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورٞ', 'তিনিই তোমাদেরকে জীবিত করেছেন, অতঃপর তিনিই তোমাদেরকে মৃত্যুদান করবেন ও পুনরায় জীবিত করবেন। নিশ্চয় মানুষ বড় অকৃতজ্ঞ।', 'Wahuwa allathee ahyakum thumma yumeetukum thumma yuhyeekum inna alinsana lakafoorun', 1, NOW(), NOW()),
(27, 67, 'لِّكُلِّ أُمَّةٖ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدٗى مُّسۡتَقِيمٖ', 'আমি প্রত্যেক উম্মতের জন্যে এবাদতের একটি নিয়ম-কানুন নির্ধারণ করে দিয়েছি, যা তারা পালন করে। অতএব তারা যেন এ ব্যাপারে আপনার সাথে বিতর্ক না করে। আপনি তাদেরকে পালনকর্তার দিকে আহবান করুন। নিশ্চয় আপনি সরল পথেই আছেন।', 'Likulli ommatin jaAAalna mansakan hum nasikoohu fala yunaziAAunnaka fee alamri waodAAu ila rabbika innaka laAAala hudan mustaqeemin', 1, NOW(), NOW()),
(27, 68, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ', 'তারা যদি আপনার সাথে বিতর্ক করে, তবে বলে দিন, তোমরা যা কর, সে সর্ম্পকে আল্লাহ অধিক জ্ঞাত।', 'Wain jadalooka faquli Allahu aAAlamu bima taAAmaloona', 1, NOW(), NOW()),
(27, 69, 'ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ', 'তোমরা যে বিষয়ে মতবিরোধ করছ, আল্লাহ কিয়ামতের দিন সেই বিষয়ে তোমাদের মধ্যে ফায়সালা করবেন।', 'Allahu yahkumu baynakum yawma alqiyamati feema kuntum feehi takhtalifoona', 1, NOW(), NOW()),
(27, 70, 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ', 'তুমি কি জান না যে, আল্লাহ জানেন যা কিছু আকাশে ও ভুমন্ডলে আছে এসব কিতাবে লিখিত আছে। এটা আল্লাহর কাছে সহজ।', 'Alam taAAlam anna Allaha yaAAlamu ma fee alssamai waalardi inna thalika fee kitabin inna thalika AAala Allahi yaseerun', 1, NOW(), NOW()),
(27, 71, 'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمٞۗ وَمَا لِلظَّـٰلِمِينَ مِن نَّصِيرٖ', 'তারা আল্লাহর পরিবর্তে এমন কিছুর পূজা করে, যার কোন সনদ নাযিল করা হয়নি এবং সে সম্পর্কে তাদের কোন জ্ঞান নেই। বস্তুতঃ জালেমদের কোন সাহায্যকারী নেই।', 'WayaAAbudoona min dooni Allahi ma lam yunazzil bihi sultanan wama laysa lahum bihi AAilmun wama lilththalimeena min naseerin', 1, NOW(), NOW()),
(27, 72, 'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ', 'যখন তাদের কাছে আমার সুস্পষ্ট আয়াতসমূহ আবৃত্তি করা হয়, তখন তুমি কাফেরদের চোখে মুখে অসন্তোষের লক্ষণ প্রত্যক্ষ করতে পারবে। যারা তাদের কাছে আমার আয়াত সমূহ পাঠ করে, তারা তাদের প্রতি মার মুখো হয়ে উঠে। বলুন, আমি কি তোমাদেরকে তদপেক্ষা মন্দ কিছুর সংবাদ দেব? তা আগুন; আল্লাহ কাফেরদেরকে এর ওয়াদা দিয়েছেন। এটা কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল।', 'Waitha tutla AAalayhim ayatuna bayyinatin taAArifu fee wujoohi allatheena kafaroo almunkara yakadoona yastoona biallatheena yatloona AAalayhim ayatina qul afaonabbiokum bisharrin min thalikum alnnaru waAAadaha Allahu allatheena kafaroo wabisa almaseeru', 1, NOW(), NOW()),
(27, 73, 'يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٞ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابٗا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ', 'হে লোক সকল! একটি উপমা বর্ণনা করা হলো, অতএব তোমরা তা মনোযোগ দিয়ে শোন; তোমরা আল্লাহর পরিবর্তে যাদের পূজা কর, তারা কখনও একটি মাছি সৃষ্টি করতে পারবে না, যদিও তারা সকলে একত্রিত হয়। আর মাছি যদি তাদের কাছ থেকে কোন কিছু ছিনিয়ে নেয়, তবে তারা তার কাছ থেকে তা উদ্ধার করতে পারবে না, প্রার্থনাকারী ও যার কাছে প্রার্থনা করা হয়, উভয়েই শক্তিহীন।', 'Ya ayyuha alnnasu duriba mathalun faistamiAAoo lahu inna allatheena tadAAoona min dooni Allahi lan yakhluqoo thubaban walawi ijtamaAAoo lahu wain yaslubuhumu alththubabu shayan la yastanqithoohu minhu daAAufa alttalibu waalmatloobu', 1, NOW(), NOW()),
(27, 74, 'مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ', 'তারা আল্লাহর যথাযোগ্য মর্যাদা বোঝেনি। নিশ্চয় আল্লাহ শক্তিধর, মহাপরাক্রমশীল।', 'Ma qadaroo Allaha haqqa qadrihi inna Allaha laqawiyyun AAazeezun', 1, NOW(), NOW()),
(27, 75, 'ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَـٰٓئِكَةِ رُسُلٗا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٞ', 'আল্লাহ ফেরেশতা ও মানুষের মধ্য থেকে রাসূল মনোনীত করেন। আল্লাহ সর্বশ্রোতা, সর্ব দ্রষ্টা', 'Allahu yastafee mina almalaikati rusulan wamina alnnasi inna Allaha sameeAAun baseerun', 1, NOW(), NOW()),
(27, 76, 'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ', 'তিনি জানেন যা তাদের সামনে আছে এবং যা পশ্চাতে আছে এবং সবকিছু আল্লাহর দিকে প্রত্যাবর্তিত হবে।', 'YaAAlamu ma bayna aydeehim wama khalfahum waila Allahi turjaAAu alomooru', 1, NOW(), NOW()),
(27, 77, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩', 'হে মুমিনগণ! তোমরা রুকু কর, সেজদা কর, তোমাদের পালনকর্তার এবাদত কর এবং সৎকাজ সম্পাদন কর, যাতে তোমরা সফলকাম হতে পার।', 'Ya ayyuha allatheena amanoo irkaAAoo waosjudoo waoAAbudoo rabbakum waifAAaloo alkhayra laAAallakum tuflihoona', 1, NOW(), NOW()),
(27, 78, 'وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ', 'তোমরা আল্লাহর জন্যে শ্রম স্বীকার কর যেভাবে শ্রম স্বীকার করা উচিত। তিনি তোমাদেরকে পছন্দ করেছেন এবং ধর্মের ব্যাপারে তোমাদের উপর কোন সংকীর্ণতা রাখেননি। তোমরা তোমাদের পিতা ইব্রাহীমের ধর্মে কায়েম থাক। তিনিই তোমাদের নাম মুসলমান রেখেছেন পূর্বেও এবং এই কোরআনেও, যাতে রসূল তোমাদের জন্যে সাক্ষ্যদাতা এবং তোমরা সাক্ষ্যদাতা হও মানবমন্ডলির জন্যে। সুতরাং তোমরা নামায কায়েম কর, যাকাত দাও এবং আল্লাহকে শক্তভাবে ধারণ কর। তিনিই তোমাদের মালিক। অতএব তিনি কত উত্তম মালিক এবং কত উত্তম সাহায্যকারী।', 'Wajahidoo fee Allahi haqqa jihadihi huwa ijtabakum wama jaAAala AAalaykum fee alddeeni min harajin millata abeekum ibraheema huwa sammakumu almuslimeena min qablu wafee hatha liyakoona alrrasoolu shaheedan AAalaykum watakoonoo shuhadaa AAala alnnasi faaqeemoo alssalata waatoo alzzakata waiAAtasimoo biAllahi huwa mawlakum faniAAma almawla waniAAma alnnaseeru', 1, NOW(), NOW()),
(28, 1, 'قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ', 'মুমিনগণ সফলকাম হয়ে গেছে', 'Qad aflaha almuminoona', 1, NOW(), NOW()),
(28, 2, 'ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ', 'যারা নিজেদের নামাযে বিনয়-নম্র', 'Allatheena hum fee salatihim khashiAAoona', 1, NOW(), NOW()),
(28, 3, 'وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ', 'যারা অনর্থক কথা-বার্তায় নির্লিপ্ত', 'Waallatheena hum AAani allaghwi muAAridoona', 1, NOW(), NOW()),
(28, 4, 'وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ', 'যারা যাকাত দান করে থাকে', 'Waallatheena hum lilzzakati faAAiloona', 1, NOW(), NOW()),
(28, 5, 'وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ', 'এবং যারা নিজেদের যৌনাঙ্গকে সংযত রাখে।', 'Waallatheena hum lifuroojihim hafithoona', 1, NOW(), NOW()),
(28, 6, 'إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ', 'তবে তাদের স্ত্রী ও মালিকানাভুক্ত দাসীদের ক্ষেত্রে সংযত না রাখলে তারা তিরস্কৃত হবে না।', 'Illa AAala azwajihim aw ma malakat aymanuhum fainnahum ghayru maloomeena', 1, NOW(), NOW()),
(28, 7, 'فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ', 'অতঃপর কেউ এদেরকে ছাড়া অন্যকে কামনা করলে তারা সীমালংঘনকারী হবে।', 'Famani ibtagha waraa thalika faolaika humu alAAadoona', 1, NOW(), NOW()),
(28, 8, 'وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ', 'এবং যারা আমানত ও অঙ্গীকার সম্পর্কে হুশিয়ার থাকে।', 'Waallatheena hum liamanatihim waAAahdihim raAAoona', 1, NOW(), NOW()),
(28, 9, 'وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ', 'এবং যারা তাদের নামাযসমূহের খবর রাখে।', 'Waallatheena hum AAala salawatihim yuhafithoona', 1, NOW(), NOW()),
(28, 10, 'أُوْلَـٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ', 'তারাই উত্তরাধিকার লাভ করবে।', 'Olaika humu alwarithoona', 1, NOW(), NOW()),
(28, 11, 'ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ', 'তারা শীতল ছায়াময় উদ্যানের উত্তরাধিকার লাভ করবে। তারা তাতে চিরকাল থাকবে।', 'Allatheena yarithoona alfirdawsa hum feeha khalidoona', 1, NOW(), NOW()),
(28, 12, 'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ', 'আমি মানুষকে মাটির সারাংশ থেকে সৃষ্টি করেছি।', 'Walaqad khalaqna alinsana min sulalatin min teenin', 1, NOW(), NOW()),
(28, 13, 'ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ', 'অতঃপর আমি তাকে শুক্রবিন্দু রূপে এক সংরক্ষিত আধারে স্থাপন করেছি।', 'Thumma jaAAalnahu nutfatan fee qararin makeenin', 1, NOW(), NOW()),
(28, 14, 'ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ', 'এরপর আমি শুক্রবিন্দুকে জমাট রক্তরূপে সৃষ্টি করেছি, অতঃপর জমাট রক্তকে মাংসপিন্ডে পরিণত করেছি, এরপর সেই মাংসপিন্ড থেকে অস্থি সৃষ্টি করেছি, অতঃপর অস্থিকে মাংস দ্বারা আবৃত করেছি, অবশেষে তাকে নতুন রূপে দাঁড় করিয়েছি। নিপুণতম সৃষ্টিকর্তা আল্লাহ কত কল্যাণময়।', 'Thumma khalaqna alnnutfata AAalaqatan fakhalaqna alAAalaqata mudghatan fakhalaqna almudghata AAithaman fakasawna alAAithama lahman thumma anshanahu khalqan akhara fatabaraka Allahu ahsanu alkhaliqeena', 1, NOW(), NOW()),
(28, 15, 'ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ', 'এরপর তোমরা মৃত্যুবরণ করবে', 'Thumma innakum baAAda thalika lamayyitoona', 1, NOW(), NOW()),
(28, 16, 'ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ', 'অতঃপর কেয়ামতের দিন তোমরা পুনরুত্থিত হবে।', 'Thumma innakum yawma alqiyamati tubAAathoona', 1, NOW(), NOW()),
(28, 17, 'وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ', 'আমি তোমাদের উপর সুপ্তপথ সৃষ্টি করেছি এবং আমি সৃষ্টি সম্বন্ধে অনবধান নই।', 'Walaqad khalaqna fawqakum sabAAa taraiqa wama kunna AAani alkhalqi ghafileena', 1, NOW(), NOW()),
(28, 18, 'وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّـٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ', 'আমি আকাশ থেকে পানি বর্ষণ করে থাকি পরিমাণ মত অতঃপর আমি জমিনে সংরক্ষণ করি এবং আমি তা অপসারণও করতে সক্ষম।', 'Waanzalna mina alssamai maan biqadarin faaskannahu fee alardi wainna AAala thahabin bihi laqadiroona', 1, NOW(), NOW()),
(28, 19, 'فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّـٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ', 'অতঃপর আমি তা দ্বারা তোমাদের জন্যে খেজুর ও আঙ্গুরের বাগান সৃষ্টি করেছি। তোমাদের জন্যে এতে প্রচুর ফল আছে এবং তোমরা তা থেকে আহার করে থাক।', 'Faanshana lakum bihi jannatin min nakheelin waaAAnabin lakum feeha fawakihu katheeratun waminha takuloona', 1, NOW(), NOW()),
(28, 20, 'وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ', 'এবং ঐ বৃক্ষ সৃষ্টি করেছি, যা সিনাই পর্বতে জন্মায় এবং আহারকারীদের জন্যে তৈল ও ব্যঞ্জন উৎপন্ন করে।', 'Washajaratan takhruju min toori saynaa tanbutu bialdduhni wasibghin lilakileena', 1, NOW(), NOW()),
(28, 21, 'وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ', 'এবং তোমাদের জন্যে চতুস্পদ জন্তু সমূহের মধ্যে চিন্তা করার বিষয় রয়েছে। আমি তোমাদেরকে তাদের উদরস্থিত বস্তু থেকে পান করাই এবং তোমাদের জন্যে তাদের মধ্যে প্রচুর উপকারিতা আছে। তোমরা তাদের কতককে ভক্ষণ কর।', 'Wainna lakum fee alanAAami laAAibratan nusqeekum mimma fee butooniha walakum feeha manafiAAu katheeratun waminha takuloona', 1, NOW(), NOW()),
(28, 22, 'وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ', 'তাদের পিঠে ও জলযানে তোমরা আরোহণ করে চলাফেরা করে থাক।', 'WaAAalayha waAAala alfulki tuhmaloona', 1, NOW(), NOW()),
(28, 23, 'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ', 'আমি নূহকে তার সম্প্রদায়ের কাছে প্রেরণ করেছিলাম। সে বলেছিলঃ হে আমার সম্প্রদায়, তোমরা আল্লাহর বন্দেগী কর। তিনি ব্যতীত তোমাদের কোন মাবুদ নেই। তোমরা কি ভয় কর না।', 'Walaqad arsalna noohan ila qawmihi faqala ya qawmi oAAbudoo Allaha ma lakum min ilahin ghayruhu afala tattaqoona', 1, NOW(), NOW()),
(28, 24, 'فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَـٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ', 'তখন তার সম্প্রদায়ের কাফের-প্রধানরা বলেছিলঃ এ তো তোমাদের মতই একজন মানুষ বৈ নয়। সে তোমাদের উপর নেতৃত্ব করতে চায়। আল্লাহ ইচ্ছা করলে ফেরেশতাই নাযিল করতেন। আমরা আমাদের পূর্বপুরুষদের মধ্যে এরূপ কথা শুনিনি।', 'Faqala almalao allatheena kafaroo min qawmihi ma hatha illa basharun mithlukum yureedu an yatafaddala AAalaykum walaw shaa Allahu laanzala malaikatan ma samiAAna bihatha fee abaina alawwaleena', 1, NOW(), NOW()),
(28, 25, 'إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ', 'সে তো এক উম্মাদ ব্যক্তি বৈ নয়। সুতরাং কিছুকাল তার ব্যাপারে অপেক্ষা কর।', 'In huwa illa rajulun bihi jinnatun fatarabbasoo bihi hatta heenin', 1, NOW(), NOW()),
(28, 26, 'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ', 'নূহ বলেছিলঃ হে আমার পালনকর্তা, আমাকে সাহায্য কর; কেননা, তারা আমাকে মিথ্যাবাদী বলছে।', 'Qala rabbi onsurnee bima kaththabooni', 1, NOW(), NOW()),
(28, 27, 'فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ', 'অতঃপর আমি তার কাছে আদেশ প্রেরণ করলাম যে, তুমি আমার দৃষ্টির সামনে এবং আমার নির্দেশে নৌকা তৈরী কর। এরপর যখন আমার আদেশ আসে এবং চুল্লী প্লাবিত হয়, তখন নৌকায় তুলে নাও, প্রত্যেক জীবের এক এক জোড়া এবং তোমার পরিবারবর্গকে, তাদের মধ্যে যাদের বিপক্ষে পূর্বে সিদ্ধান্ত নেয়া হয়েছে তাদের ছাড়া। এবং তুমি জালেমদের সম্পর্কে আমাকে কিছু বলো না। নিশ্চয় তারা নিমজ্জত হবে।', 'Faawhayna ilayhi ani isnaAAi alfulka biaAAyunina wawahyina faitha jaa amruna wafara alttannooru faosluk feeha min kullin zawjayni ithnayni waahlaka illa man sabaqa AAalayhi alqawlu minhum wala tukhatibnee fee allatheena thalamoo innahum mughraqoona', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(28, 28, 'فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'যখন তুমি ও তোমার সঙ্গীরা নৌকায় আরোহণ করবে, তখন বলঃ আল্লাহর শোকর, যিনি আমাদেরকে জালেম সম্প্রদায়ের কবল থেকে উদ্ধার করেছেন।', 'Faitha istawayta anta waman maAAaka AAala alfulki faquli alhamdu lillahi allathee najjana mina alqawmi alththalimeena', 1, NOW(), NOW()),
(28, 29, 'وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ', 'আরও বলঃ পালনকর্তা, আমাকে কল্যাণকর ভাবে নামিয়ে দাও, তুমি শ্রেষ্ঠ অবতারণকারী।', 'Waqul rabbi anzilnee munzalan mubarakan waanta khayru almunzileena', 1, NOW(), NOW()),
(28, 30, 'إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ', 'এতে নিদর্শনাবলী রয়েছে এবং আমি পরীক্ষাকারী।', 'Inna fee thalika laayatin wain kunna lamubtaleena', 1, NOW(), NOW()),
(28, 31, 'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ', 'অতঃপর অন্য এক সম্প্রদায় আমি তার স্থলাভিষিক্ত করেছিলাম।', 'Thumma anshana min baAAdihim qarnan akhareena', 1, NOW(), NOW()),
(28, 32, 'فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ', 'এবং তাদেরই একজনকে তাদের মধ্যে রসূলরূপে প্রেরণ করেছিলাম এই বলে যে, তোমরা আল্লাহর বন্দেগী কর। তিনি ব্যতীত তোমাদের অন্য কোন মাবুদ নেই। তবুও কি তোমরা ভয় করবে না', 'Faarsalna feehim rasoolan minhum ani oAAbudoo Allaha ma lakum min ilahin ghayruhu afala tattaqoona', 1, NOW(), NOW()),
(28, 33, 'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ', 'তাঁর সম্প্রদায়ের প্রধানরা যারা কাফের ছিল, পরকালের সাক্ষাতকে মিথ্যা বলত এবং যাদেরকে আমি পার্থিব জীবনে সুখ-স্বাচ্ছন্দ্য দিয়েছিলাম, তারা বললঃ এতো আমাদের মতই একজন মানুষ বৈ নয়। তোমরা যা খাও, সেও তাই খায় এবং তোমরা যা পান কর, সেও তাই পান করে।', 'Waqala almalao min qawmihi allatheena kafaroo wakaththaboo biliqai alakhirati waatrafnahum fee alhayati alddunya ma hatha illa basharun mithlukum yakulu mimma takuloona minhu wayashrabu mimma tashraboona', 1, NOW(), NOW()),
(28, 34, 'وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ', 'যদি তোমরা তোমাদের মতই একজন মানুষের আনুগত্য কর, তবে তোমরা নিশ্চিতরূপেই ক্ষতিগ্রস্ত হবে।', 'Walain ataAAtum basharan mithlakum innakum ithan lakhasiroona', 1, NOW(), NOW()),
(28, 35, 'أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ', 'সে কি তোমাদেরকে এই ওয়াদা দেয় যে, তোমরা মারা গেলে এবং মৃত্তিকা ও অস্থিতে পরিণত হলে তোমাদেরকে পুনরুজ্জীবিত করা হবে', 'AyaAAidukum annakum itha mittum wakuntum turaban waAAithaman annakum mukhrajoona', 1, NOW(), NOW()),
(28, 36, '۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ', 'তোমাদেরকে যে ওয়াদা দেয়া হচ্ছে, তা কোথায় হতে পারে', 'Hayhata hayhata lima tooAAadoona', 1, NOW(), NOW()),
(28, 37, 'إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ', 'আমাদের পার্থিবজীবনই একমাত্র জীবন। আমরা মরি ও বাঁচি এখানেই এবং আমারা পুনরুত্থিত হবো না।', 'In hiya illa hayatuna alddunya namootu wanahya wama nahnu bimabAAootheena', 1, NOW(), NOW()),
(28, 38, 'إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ', 'সে তো এমন ব্যক্তি বৈ নয়, যে আল্লাহ সম্বন্ধে মিথ্যা উদ্ভাবন করেছে এবং আমরা তাকে বিশ্বাস করি না।', 'In huwa illa rajulun iftara AAala Allahi kathiban wama nahnu lahu bimumineena', 1, NOW(), NOW()),
(28, 39, 'قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ', 'তিনি বললেনঃ হে আমার পালনকর্তা, আমাকে সাহায্য কর, কারণ তারা আমাকে মিথ্যাবাদী বলছে।', 'Qala rabbi onsurnee bima kaththabooni', 1, NOW(), NOW()),
(28, 40, 'قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ', 'আল্লাহ বললেনঃ কিছু দিনের মধ্যে তারা সকাল বেলা অনুতপ্ত হবে।', 'Qala AAamma qaleelin layusbihunna nadimeena', 1, NOW(), NOW()),
(28, 41, 'فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'অতঃপর সত্য সত্যই এক ভয়ংকর শব্দ তাদেরকে হতচকিত করল এবং আমি তাদেরকে বাত্যা-তাড়িত আবর্জনা সদৃশ করে দিলাম। অতঃপর ধ্বংস হোক পাপী সম্প্রদায়।', 'Faakhathathumu alssayhatu bialhaqqi fajaAAalnahum ghuthaan fabuAAdan lilqawmi alththalimeena', 1, NOW(), NOW()),
(28, 42, 'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ', 'এরপর তাদের পরে আমি বহু সম্প্রদায় সৃষ্টি করেছি।', 'Thumma anshana min baAAdihim quroonan akhareena', 1, NOW(), NOW()),
(28, 43, 'مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ', 'কোন সম্প্রদায় তার নির্দিষ্ট কালের অগ্রে যেতে পারে না। এবং পশ্চাতেও থকাতে পারে না।', 'Ma tasbiqu min ommatin ajalaha wama yastakhiroona', 1, NOW(), NOW()),
(28, 44, 'ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ', 'এরপর আমি একাদিক্রমে আমার রসূল প্রেরণ করেছি। যখনই কোন উম্মতের কাছে তাঁর রসূল আগমন করেছেন, তখনই তারা তাঁকে মিথ্যাবাদী বলেছে। অতঃপর আমি তাদের একের পর এক ধ্বংস করেছি এবং তাদেরকে কাহিনীর বিষয়ে পরিণত করেছি। সুতরাং ধ্বংস হোক অবিশ্বাসীরা।', 'Thumma arsalna rusulana tatra kulla ma jaa ommatan rasooluha kaththaboohu faatbaAAna baAAdahum baAAdan wajaAAalnahum ahadeetha fabuAAdan liqawmin la yuminoona', 1, NOW(), NOW()),
(28, 45, 'ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ', 'অতঃপর আমি মূসা ও হারুণকে প্রেরণ করেছিলাম আমার নিদর্শনাবলী ও সুস্পষ্ট সনদসহ', 'Thumma arsalna moosa waakhahu haroona biayatina wasultanin mubeenin', 1, NOW(), NOW()),
(28, 46, 'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ', 'ফেরআউন ও তার অমাত্যদের কাছে। অতঃপর তারা অহংকার করল এবং তারা উদ্ধত সম্প্রদায় ছিল।', 'Ila firAAawna wamalaihi faistakbaroo wakanoo qawman AAaleena', 1, NOW(), NOW()),
(28, 47, 'فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ', 'তারা বললঃ আমরা কি আমাদের মতই এ দুই ব্যক্তিতে বিশ্বাস স্থাপন করব; অথচ তাদের সম্প্রদায় আমাদের দাস', 'Faqaloo anuminu libasharayni mithlina waqawmuhuma lana AAabidoona', 1, NOW(), NOW()),
(28, 48, 'فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ', 'অতঃপর তারা উভয়কে মিথ্যাবাদী বলল। ফলে তারা ধ্বংস প্রাপ্ত হল।', 'Fakaththaboohuma fakanoo mina almuhlakeena', 1, NOW(), NOW()),
(28, 49, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ', 'আমি মূসাকে কিতাব দিয়েছিলাম যাতে তারা সৎপথ পায়।', 'Walaqad atayna moosa alkitaba laAAallahum yahtadoona', 1, NOW(), NOW()),
(28, 50, 'وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ', 'এবং আমি মরিয়ম তনয় ও তাঁর মাতাকে এক নিদর্শন দান করেছিলাম। এবং তাদেরকে এক অবস্থানযোগ্য স্বচ্ছ পানি বিশিষ্ট টিলায় আশ্রয় দিয়েছিলাম।', 'WajaAAalna ibna maryama waommahu ayatan waawaynahuma ila rabwatin thati qararin wamaAAeenin', 1, NOW(), NOW()),
(28, 51, 'يَـٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ', 'হে রসূলগণ, পবিত্র বস্তু আহার করুন এবং সৎকাজ করুন। আপনারা যা করেন সে বিষয়ে আমি পরিজ্ঞাত।', 'Ya ayyuha alrrusulu kuloo mina alttayyibati waiAAmaloo salihan innee bima taAAmaloona AAaleemun', 1, NOW(), NOW()),
(28, 52, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ', 'আপনাদের এই উম্মত সব তো একই ধর্মের অনুসারী এবং আমি আপনাদের পালনকর্তা; অতএব আমাকে ভয় করুন।', 'Wainna hathihi ommatukum ommatan wahidatan waana rabbukum faittaqooni', 1, NOW(), NOW()),
(28, 53, 'فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ', 'অতঃপর মানুষ তাদের বিষয়কে বহুধা বিভক্ত করে দিয়েছে। প্রত্যেক সম্প্রদায় নিজ নিজ মতবাদ নিয়ে আনন্দিত হচ্ছে।', 'FataqattaAAoo amrahum baynahum zuburan kullu hizbin bima ladayhim farihoona', 1, NOW(), NOW()),
(28, 54, 'فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ', 'অতএব তাদের কিছু কালের জন্যে তাদের অজ্ঞানতায় নিমজ্জত থাকতে দিন।', 'Fatharhum fee ghamratihim hatta heenin', 1, NOW(), NOW()),
(28, 55, 'أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ', 'তারা কি মনে করে যে, আমি তাদেরকে ধন-সম্পদ ও সন্তান-সন্ততি দিয়ে যাচ্ছি।', 'Ayahsaboona annama numidduhum bihi min malin wabaneena', 1, NOW(), NOW()),
(28, 56, 'نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ', 'তাতে করে তাদেরকে দ্রুত মঙ্গলের দিকে নিয়ে যাচ্ছি? বরং তারা বোঝে না।', 'NusariAAu lahum fee alkhayrati bal la yashAAuroona', 1, NOW(), NOW()),
(28, 57, 'إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ', 'নিশ্চয় যারা তাদের পালনকর্তার ভয়ে সন্ত্রস্ত', 'Inna allatheena hum min khashyati rabbihim mushfiqoona', 1, NOW(), NOW()),
(28, 58, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ', 'যারা তাদের পালনকর্তার কথায় বিশ্বাস স্থাপন করে', 'Waallatheena hum biayati rabbihim yuminoona', 1, NOW(), NOW()),
(28, 59, 'وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ', 'যারা তাদের পালনকর্তার সাথে কাউকে শরীক করে না', 'Waallatheena hum birabbihim la yushrikoona', 1, NOW(), NOW()),
(28, 60, 'وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ', 'এবং যারা যা দান করবার, তা ভীত, কম্পিত হৃদয়ে এ কারণে দান করে যে, তারা তাদের পালনকর্তার কাছে প্রত্যাবর্তন করবে', 'Waallatheena yutoona ma ataw waquloobuhum wajilatun annahum ila rabbihim rajiAAoona', 1, NOW(), NOW()),
(28, 61, 'أُوْلَـٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ', 'তারাই কল্যাণ দ্রুত অর্জন করে এবং তারা তাতে অগ্রগামী।', 'Olaika yusariAAoona fee alkhayrati wahum laha sabiqoona', 1, NOW(), NOW()),
(28, 62, 'وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ', 'আমি কাউকে তার সাধ্যাতীত দায়িত্ব অর্পন করি না। আমার এক কিতাব আছে, যা সত্য ব্যক্ত করে এবং তাদের প্রতি জুলুম করা হবে না।', 'Wala nukallifu nafsan illa wusAAaha waladayna kitabun yantiqu bialhaqqi wahum la yuthlamoona', 1, NOW(), NOW()),
(28, 63, 'بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ', 'না, তাদের অন্তর এ বিষয়ে অজ্ঞানতায় আচ্ছন্ন, এ ছাড়া তাদের আরও কাজ রয়েছে, যা তারা করছে।', 'Bal quloobuhum fee ghamratin min hatha walahum aAAmalun min dooni thalika hum laha AAamiloona', 1, NOW(), NOW()),
(28, 64, 'حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ', 'এমনকি, যখন আমি তাদের ঐশ্বর্যশালী লোকদেরকে শাস্তি দ্বারা পাকড়াও করব, তখনই তারা চীৎকার জুড়ে দেবে।', 'Hatta itha akhathna mutrafeehim bialAAathabi itha hum yajaroona', 1, NOW(), NOW()),
(28, 65, 'لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'অদ্য চীৎকার করো না। তোমরা আমার কাছ থেকে নিস্কৃতি পাবে না।', 'La tajaroo alyawma innakum minna la tunsaroona', 1, NOW(), NOW()),
(28, 66, 'قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ', 'তোমাদেরকে আমার আয়াতসমূহ শোনানো হত, তখন তোমরা উল্টো পায়ে সরে পড়তে।', 'Qad kanat ayatee tutla AAalaykum fakuntum AAala aAAqabikum tankisoona', 1, NOW(), NOW()),
(28, 67, 'مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ', 'অহংকার করে এ বিষয়ে অর্থহীন গল্প-গুজব করে যেতে।', 'Mustakbireena bihi samiran tahjuroona', 1, NOW(), NOW()),
(28, 68, 'أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ', 'অতএব তারা কি এই কালাম সম্পꦣ2503;ক চিন্তা-ভাবনা করে না? না তাদের কাছে এমন কিছু এসেছে, যা তাদের পিতৃপুরুষদের কাছে আসেনি', 'Afalam yaddabbaroo alqawla am jaahum ma lam yati abaahumu alawwaleena', 1, NOW(), NOW()),
(28, 69, 'أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ', 'না তারা তাদের রসূলকে চেনে না, ফলে তারা তাঁকে অস্বীকার করে', 'Am lam yaAArifoo rasoolahum fahum lahu munkiroona', 1, NOW(), NOW()),
(28, 70, 'أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ', 'না তারা বলে যে, তিনি পাগল ? বরং তিনি তাদের কাছে সত্য নিয়ে আগমন করেছেন এবং তাদের অধিকাংশ সত্যকে অপছন্দ করে।', 'Am yaqooloona bihi jinnatun bal jaahum bialhaqqi waaktharuhum lilhaqqi karihoona', 1, NOW(), NOW()),
(28, 71, 'وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ', 'সত্য যদি তাদের কাছে কামনা-বাসনার অনুসারী হত, তবে নভোমন্ডল ও ভূমন্ডল এবং এগুলোর মধ্যবর্তꦣ2496; সবকিছুই বিশৃঙ্খল হয়ে পড়ত। বরং আমি তাদেরকে দান করেছি উপদেশ, কিন্তু তারা তাদের উপদেশ অনুধাবন করে না।', 'Walawi ittabaAAa alhaqqu ahwaahum lafasadati alssamawatu waalardu waman feehinna bal ataynahum bithikrihim fahum AAan thikrihim muAAridoona', 1, NOW(), NOW()),
(28, 72, 'أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّـٰزِقِينَ', 'না আপনি তাদের কাছে কোন প্রতিদান চান? আপনার পালনকর্তার প্রতিদান উত্তম এবং তিনিই রিযিকদাতা।', 'Am tasaluhum kharjan fakharaju rabbika khayrun wahuwa khayru alrraziqeena', 1, NOW(), NOW()),
(28, 73, 'وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আপনি তো তাদেরকে সোজা পথে দাওয়াত দিচ্ছেন', 'Wainnaka latadAAoohum ila siratin mustaqeemin', 1, NOW(), NOW()),
(28, 74, 'وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', 'আর যারা পরকালে বিশ্বাস করে না, তারা সোজা পথ থেকে বিচ্যুত হয়ে গেছে।', 'Wainna allatheena la yuminoona bialakhirati AAani alssirati lanakiboona', 1, NOW(), NOW()),
(28, 75, '۞وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ', 'যদি আমি তাদের প্রতি দয়া করি এবং তাদের কষ্ট দূর করে দেই, তবুও তারা তাদের অবাধ্যতায় দিশেহারা হয়ে লেগে থাকবে।', 'Walaw rahimnahum wakashafna ma bihim min durrin lalajjoo fee tughyanihim yaAAmahoona', 1, NOW(), NOW()),
(28, 76, 'وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ', 'আমি তাদেরকে শাস্তি দ্বারা পাকড়াও করেছিলাম, কিন্তু তারা তাদের পালনকর্তার সামনে নত হল না এবং কাকুতি-মিনুতিও করল না।', 'Walaqad akhathnahum bialAAathabi fama istakanoo lirabbihim wama yatadarraAAoona', 1, NOW(), NOW()),
(28, 77, 'حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ', 'অবশেষে যখন আমি তাদের জন্য কঠিন শাস্তির দ্বার খুলে দেব, তখন তাতে তাদের আশা ভঙ্গ হবে।', 'Hatta itha fatahna AAalayhim baban tha AAathabin shadeedin itha hum feehi mublisoona', 1, NOW(), NOW()),
(28, 78, 'وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ', 'তিনি তোমাদের কান, চোখ ও অন্তঃকরণ সৃষ্টি করেছেন; তোমরা খুবই অল্প কৃতজ্ঞতা স্বীকার করে থাক।', 'Wahuwa allathee anshaa lakumu alssamAAa waalabsara waalafidata qaleelan ma tashkuroona', 1, NOW(), NOW()),
(28, 79, 'وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ', 'তিনিই তোমাদেরকে পৃথিবীতে ছড়িয়ে রেখেছেন এবং তারই দিকে তোমাদেরকে সমবেত করা হবে।', 'Wahuwa allathee tharaakum fee alardi wailayhi tuhsharoona', 1, NOW(), NOW()),
(28, 80, 'وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ', 'তিনিই প্রাণ দান করেন এবং মৃত্যু ঘটান এবং দিবা-রাত্রির বিবর্তন তাঁরই কাজ, তবু ও কি তোমরা বুঝবে না', 'Wahuwa allathee yuhyee wayumeetu walahu ikhtilafu allayli waalnnahari afala taAAqiloona', 1, NOW(), NOW()),
(28, 81, 'بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ', 'বরং তারা বলে যেমন তাদের পূর্ববর্তীরা বলত।', 'Bal qaloo mithla ma qala alawwaloona', 1, NOW(), NOW()),
(28, 82, 'قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ', 'তারা বলেঃ যখন আমরা মরে যাব এবং মৃত্তিকা ও অস্থিতে পরিণত হব, তখনও কি আমরা পুনরুত্থিত হব', 'Qaloo aitha mitna wakunna turaban waAAithaman ainna lamabAAoothoona', 1, NOW(), NOW()),
(28, 83, 'لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ', 'অতীতে আমাদেরকে এবং আমাদের পিতৃপুরুষদেরকে এই ওয়াদাই দেয়া হয়েছে। এটা তো পূর্ববতীদের কল্প-কথা বৈ কিছুই নয়।', 'Laqad wuAAidna nahnu waabaona hatha min qablu in hatha illa asateeru alawwaleena', 1, NOW(), NOW()),
(28, 84, 'قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ', 'বলুন পৃথিবী এবং পৃথিবীতে যারা আছে, তারা কার? যদি তোমরা জান, তবে বল।', 'Qul limani alardu waman feeha in kuntum taAAlamoona', 1, NOW(), NOW()),
(28, 85, 'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ', 'এখন তারা বলবেঃ সবই আল্লাহর। বলুন, তবুও কি তোমরা চিন্তা কর না', 'Sayaqooloona lillahi qul afala tathakkaroona', 1, NOW(), NOW()),
(28, 86, 'قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ', 'বলুনঃ সপ্তাকাশ ও মহা-আরশের মালিক কে', 'Qul man rabbu alssamawati alssabAAi warabbu alAAarshi alAAatheemi', 1, NOW(), NOW()),
(28, 87, 'سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ', 'এখন তারা বলবেঃ আল্লাহ। বলুন, তবুও কি তোমরা ভয় করবে না', 'Sayaqooloona lillahi qul afala tattaqoona', 1, NOW(), NOW()),
(28, 88, 'قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ', 'বলুনঃ তোমাদের জানা থাকলে বল, কার হাতে সব বস্তুর কতৃর্ꦣ2468;্ব, যিনি রক্ষা করেন এবং যার কবল থেকে কেউ রক্ষা করতে পারে না', 'Qul man biyadihi malakootu kulli shayin wahuwa yujeeru wala yujaru AAalayhi in kuntum taAAlamoona', 1, NOW(), NOW()),
(28, 89, 'سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ', 'এখন তারা বলবেঃ আল্লাহর। বলুনঃ তাহলে কোথা থেকে তোমাদেরকে জাদু করা হচ্ছে', 'Sayaqooloona lillahi qul faanna tusharoona', 1, NOW(), NOW()),
(28, 90, 'بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ', 'কিছুই নয়, আমি তাদের কাছে সত্য পৌঁছিয়েছি, আর তারা তো মিথ্যাবাদী।', 'Bal ataynahum bialhaqqi wainnahum lakathiboona', 1, NOW(), NOW()),
(28, 91, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 'আল্লাহ কোন সন্তান গ্রহণ করেননি এবং তাঁর সাথে কোন মাবুদ নেই। থাকলে প্রত্যেক মাবুদ নিজ নিজ সৃষ্টি নিয়ে চলে যেত এবং একজন অন্যজনের উপর প্রবল হয়ে যেত। তারা যা বলে, তা থেকে আল্লাহ পবিত্র।', 'Ma ittakhatha Allahu min waladin wama kana maAAahu min ilahin ithan lathahaba kullu ilahin bima khalaqa walaAAala baAAduhum AAala baAAdin subhana Allahi AAamma yasifoona', 1, NOW(), NOW()),
(28, 92, 'عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ', 'তিনি দৃশ্য ও অদৃশ্যের জ্ঞানী। তারা শরীক করে, তিনি তা থেকে উর্ধ্বে।', 'AAalimi alghaybi waalshshahadati fataAAala AAamma yushrikoona', 1, NOW(), NOW()),
(28, 93, 'قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ', 'বলুনঃ হে আমার পালনকর্তা! যে বিষয়ে তাদেরকে ওয়াদা দেয়া হয়েছে তা যদি আমাকে দেখান', 'Qul rabbi imma turiyannee ma yooAAadoona', 1, NOW(), NOW()),
(28, 94, 'رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ', 'হে আমার পালনকর্তা! তবে আপনি আমাকে গোনাহগার সম্প্রদায়ের অন্তর্ভূক্ত করবেন না।', 'Rabbi fala tajAAalnee fee alqawmi alththalimeena', 1, NOW(), NOW()),
(28, 95, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ', 'আমি তাদেরকে যে বিষয়ের ওয়াদা দিয়েছি, তা আপনাকে দেখাতে অবশ্যই সক্ষম।', 'Wainna AAala an nuriyaka ma naAAiduhum laqadiroona', 1, NOW(), NOW()),
(28, 96, 'ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ', 'মন্দের জওয়াবে তাই বলুন, যা উত্তম। তারা যা বলে, আমি সে বিষয়ে সবিশেষ অবগত।', 'IdfaAA biallatee hiya ahsanu alssayyiata nahnu aAAlamu bima yasifoona', 1, NOW(), NOW()),
(28, 97, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'বলুনঃ হে আমার পালনকর্তা! আমি শয়তানের প্ররোচনা থেকে আপনার আশ্রয় প্রার্থনা করি', 'Waqul rabbi aAAoothu bika min hamazati alshshayateeni', 1, NOW(), NOW()),
(28, 98, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ', 'এবং হে আমার পালনকর্তা! আমার নিকট তাদের উপস্থিতি থেকে আপনার আশ্রয় প্রার্থনা করি।', 'WaaAAoothu bika rabbi an yahdurooni', 1, NOW(), NOW()),
(28, 99, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ', 'যখন তাদের কারও কাছে মৃত্যু আসে, তখন সে বলেঃ হে আমার পালণকর্তা! আমাকে পুনরায় (দুনিয়াতে ) প্রেরণ করুন।', 'Hatta itha jaa ahadahumu almawtu qala rabbi irjiAAooni', 1, NOW(), NOW()),
(28, 100, 'لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ', 'যাতে আমি সৎকর্ম করতে পারি, যা আমি করিনি। কখনই নয়, এ তো তার একটি কথার কথা মাত্র। তাদের সামনে পর্দা আছে পুনরুত্থান দিবস পর্যন্ত।', 'LaAAallee aAAmalu salihan feema taraktu kalla innaha kalimatun huwa qailuha wamin waraihim barzakhun ila yawmi yubAAathoona', 1, NOW(), NOW()),
(28, 101, 'فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ', 'অতঃপর যখন শিংগায় ফুৎকার দেয়া হবে, সেদিন তাদের পারস্পরিক আত্নীয়তার বন্ধন থাকবে না এবং একে অপরকে জিজ্ঞাসাবাদ করবে না।', 'Faitha nufikha fee alssoori fala ansaba baynahum yawmaithin wala yatasaaloona', 1, NOW(), NOW()),
(28, 102, 'فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'যাদের পাল্লা ভারী হবে, তারাই হবে সফলকাম', 'Faman thaqulat mawazeenuhu faolaika humu almuflihoona', 1, NOW(), NOW()),
(28, 103, 'وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ', 'এবং যাদের পাল্লা হাল্কা হবে তারাই নিজেদের ক্ষতিসাধন করেছে, তারা দোযখেই চিরকাল বসবাস করবে।', 'Waman khaffat mawazeenuhu faolaika allatheena khasiroo anfusahum fee jahannama khalidoona', 1, NOW(), NOW()),
(28, 104, 'تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ', 'আগুন তাদের মুখমন্ডল দগ্ধ করবে এবং তারা তাতে বীভৎস আকার ধারন করবে।', 'Talfahu wujoohahumu alnnaru wahum feeha kalihoona', 1, NOW(), NOW()),
(28, 105, 'أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ', 'তোমাদের সামনে কি আমার আয়াত সমূহ পঠিত হত না? তোমরা তো সেগুলোকে মিথ্যা বলতে।', 'Alam takun ayatee tutla AAalaykum fakuntum biha tukaththiboona', 1, NOW(), NOW()),
(28, 106, 'قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ', 'তারা বলবেঃ হে আমাদের পালনকর্তা, আমরা দূর্ভাগ্যের হাতে পরাভূত ছিলাম এবং আমরা ছিলাম বিভ্রান্ত জাতি।', 'Qaloo rabbana ghalabat AAalayna shiqwatuna wakunna qawman dalleena', 1, NOW(), NOW()),
(28, 107, 'رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ', 'হে আমাদের পালনকর্তা! এ থেকে আমাদেরকে উদ্ধার কর; আমরা যদি পুনরায় তা করি, তবে আমরা গোনাহগার হব।', 'Rabbana akhrijna minha fain AAudna fainna thalimoona', 1, NOW(), NOW()),
(28, 108, 'قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ', 'আল্লাহ বলবেনঃ তোমরা ধিকৃত অবস্থায় এখানেই পড়ে থাক এবং আমার সাথে কোন কথা বলো না।', 'Qala ikhsaoo feeha wala tukallimooni', 1, NOW(), NOW()),
(28, 109, 'إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ', 'আমার বান্দাদের একদলে বলতঃ হে আমাদের পালনকর্তা! আমরা বিশ্বাস স্থাপন করেছি। অতএব তুমি আমাদেরকে ক্ষমা কর ও আমাদের প্রতি রহম কর। তুমি তো দয়ালুদের মধ্যে শ্রেষ্ঠ দয়ালু।', 'Innahu kana fareequn min AAibadee yaqooloona rabbana amanna faighfir lana wairhamna waanta khayru alrrahimeena', 1, NOW(), NOW()),
(28, 110, 'فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ', 'অতঃপর তোমরা তাদেরকে ঠাট্টার পাত্ররূপে গ্রহণ করতে। এমনকি, তা তোমাদেরকে আমার স্মরণ ভুলিয়ে দিয়েছিল এবং তোমরা তাদেরকে দেখে পরিহাস করতে।', 'Faittakhathtumoohum sikhriyyan hatta ansawkum thikree wakuntum minhum tadhakoona', 1, NOW(), NOW()),
(28, 111, 'إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ', 'আজ আমি তাদেরকে তাদের সবরের কারণে এমন প্রতিদান দিয়েছি যে, তারাই সফলকাম।', 'Innee jazaytuhumu alyawma bima sabaroo annahum humu alfaizoona', 1, NOW(), NOW()),
(28, 112, 'قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ', 'আল্লাহ বলবেনঃ তোমরা পৃথিবীতে কতদিন অবস্থান করলে বছরের গণনায়', 'Qala kam labithtum fee alardi AAadada sineena', 1, NOW(), NOW()),
(28, 113, 'قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ', 'তারা বলবে, আমরা একদিন অথবা দিনের কিছু অংশ অবস্থান করেছি। অতএব আপনি গণনাকারীদেরকে জিজ্ঞেস করুন।', 'Qaloo labithna yawman aw baAAda yawmin faisali alAAaddeena', 1, NOW(), NOW()),
(28, 114, 'قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ', 'আল্লাহ বলবেনঃ তোমরা তাতে অল্পদিনই অবস্থান করেছ, যদি তোমরা জানতে', 'Qala in labithtum illa qaleelan law annakum kuntum taAAlamoona', 1, NOW(), NOW()),
(28, 115, 'أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ', 'তোমরা কি ধারণা কর যে, আমি তোমাদেরকে অনর্থক সৃষ্টি করেছি এবং তোমরা আমার কাছে ফিরে আসবে না', 'Afahasibtum annama khalaqnakum AAabathan waannakum ilayna la turjaAAoona', 1, NOW(), NOW()),
(28, 116, 'فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ', 'অতএব শীর্ষ মহিমায় আল্লাহ, তিনি সত্যিকার মালিক, তিনি ব্যতীত কোন মাবুদ নেই। তিনি সম্মানিত আরশের মালিক।', 'FataAAala Allahu almaliku alhaqqu la ilaha illa huwa rabbu alAAarshi alkareemi', 1, NOW(), NOW()),
(28, 117, 'وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ', 'যে কেউ আল্লাহর সাথে অন্য উপাস্যকে ডাকে, তার কাছে যার সনদ নেই, তার হিসাব তার পালণকর্তার কাছে আছে। নিশ্চয় কাফেররা সফলকাম হবে না।', 'Waman yadAAu maAAa Allahi ilahan akhara la burhana lahu bihi fainnama hisabuhu AAinda rabbihi innahu la yuflihu alkafiroona', 1, NOW(), NOW()),
(28, 118, 'وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّـٰحِمِينَ', 'বলূনঃ হে আমার পালনকর্তা, ক্ষমা করুন ও রহম করুন। রহমকারীদের মধ্যে আপনি শ্রেষ্ট রহমকারী।', 'Waqul rabbi ighfir wairham waanta khayru alrrahimeena', 1, NOW(), NOW()),
(29, 1, 'سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتٖ لَّعَلَّكُمۡ تَذَكَّرُونَ', 'এটা একটা সূরা যা আমি নাযিল করেছি, এবং দায়িত্বে অপরিহার্য করেছি। এতে আমি সুস্পষ্ট আয়াতসমূহ অবতীর্ণ করেছি, যাতে তোমরা স্মরণ রাখ।', 'Sooratun anzalnaha wafaradnaha waanzalna feeha ayatin bayyinatin laAAallakum tathakkaroona', 1, NOW(), NOW()),
(29, 2, 'ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ', 'ব্যভিচারিণী নারী ব্যভিচারী পুরুষ; তাদের প্রত্যেককে একশ’ করে বেত্রাঘাত কর। আল্লাহর বিধান কার্যকর কারণে তাদের প্রতি যেন তোমাদের মনে দয়ার উদ্রেক না হয়, যদি তোমরা আল্লাহর প্রতি ও পরকালের প্রতি বিশ্বাসী হয়ে থাক। মুসলমানদের একটি দল যেন তাদের শাস্তি প্রত্যক্ষ করে।', 'Alzzaniyatu waalzzanee faijlidoo kulla wahidin minhuma miata jaldatin wala takhuthkum bihima rafatun fee deeni Allahi in kuntum tuminoona biAllahi waalyawmi alakhiri walyashhad AAathabahuma taifatun mina almumineena', 1, NOW(), NOW()),
(29, 3, 'ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ', 'ব্যভিচারী পুরুষ কেবল ব্যভিচারিণী নারী অথবা মুশরিকা নারীকেই বিয়ে করে এবং ব্যভিচারিণীকে কেবল ব্যভিচারী অথবা মুশরিক পুরুষই বিয়ে করে এবং এদেরকে মুমিনদের জন্যে হারাম করা হয়েছে।', 'Alzzanee la yankihu illa zaniyatan aw mushrikatan waalzzaniyatu la yankihuha illa zanin aw mushrikun wahurrima thalika AAala almumineena', 1, NOW(), NOW()),
(29, 4, 'وَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', 'যারা সতী-সাধ্বী নারীর প্রতি অপবাদ আরোপ করে অতঃপর স্বপক্ষে চার জন পুরুষ সাক্ষী উপস্থিত করে না, তাদেরকে আশিটি বেত্রাঘাত করবে এবং কখনও তাদের সাক্ষ্য কবুল করবে না। এরাই না’ফারমান।', 'Waallatheena yarmoona almuhsanati thumma lam yatoo biarbaAAati shuhadaa faijlidoohum thamaneena jaldatan wala taqbaloo lahum shahadatan abadan waolaika humu alfasiqoona', 1, NOW(), NOW()),
(29, 5, 'إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'কিন্তু যারা এরপর তওবা করে এবং সংশোধিত হয়, আল্লাহ ক্ষমাশীল, পরম মেহেরবান।', 'Illa allatheena taboo min baAAdi thalika waaslahoo fainna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(29, 6, 'وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِينَ', 'এবং যারা তাদের স্ত্রীদের প্রতি অপবাদ আরোপ করে এবং তারা নিজেরা ছাড়া তাদের কোন সাক্ষী নেই, এরূপ ব্যক্তির সাক্ষ্য এভাবে হবে যে, সে আল্লাহর কসম খেয়ে চারবার সাক্ষ্য দেবে যে, সে অবশ্যই সত্যবাদী।', 'Waallatheena yarmoona azwajahum walam yakun lahum shuhadao illa anfusuhum fashahadatu ahadihim arbaAAu shahadatin biAllahi innahu lamina alssadiqeena', 1, NOW(), NOW()),
(29, 7, 'وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ', 'এবং পঞ্চমবার বলবে যে, যদি সে মিথ্যাবাদী হয় তবে তার উপর আল্লাহর লানত।', 'Waalkhamisatu anna laAAnata Allahi AAalayhi in kana mina alkathibeena', 1, NOW(), NOW()),
(29, 8, 'وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ', 'এবং স্ত্রীর শাস্তি রহিত হয়ে যাবে যদি সে আল্লাহর কসম খেয়ে চার বার সাক্ষ্য দেয় যে, তার স্বামী অবশ্যই মিথ্যাবাদী', 'Wayadrao AAanha alAAathaba an tashhada arbaAAa shahadatin biAllahi innahu lamina alkathibeena', 1, NOW(), NOW()),
(29, 9, 'وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّـٰدِقِينَ', 'এবং পঞ্চমবার বলে যে, যদি তার স্বামী সত্যবাদী হয় তবে তার ওপর আল্লাহর গযব নেমে আসবে।', 'Waalkhamisata anna ghadaba Allahi AAalayha in kana mina alssadiqeena', 1, NOW(), NOW()),
(29, 10, 'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', 'তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকলে এবং আল্লাহ তওবা কবুল কারী, প্রজ্ঞাময় না হলে কত কিছুই যে হয়ে যেত।', 'Walawla fadlu Allahi AAalaykum warahmatuhu waanna Allaha tawwabun hakeemun', 1, NOW(), NOW()),
(29, 11, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ', 'যারা মিথ্যা অপবাদ রটনা করেছে, তারা তোমাদেরই একটি দল। তোমরা একে নিজেদের জন্যে খারাপ মনে করো না; বরং এটা তোমাদের জন্যে মঙ্গলজনক। তাদের প্রত্যেকের জন্যে ততটুকু আছে যতটুকু সে গোনাহ করেছে এবং তাদের মধ্যে যে এ ব্যাপারে অগ্রণী ভূমিকা নিয়েছে, তার জন্যে রয়েছে বিরাট শাস্তি।', 'Inna allatheena jaoo bialifki AAusbatun minkum la tahsaboohu sharran lakum bal huwa khayrun lakum likulli imriin minhum ma iktasaba mina alithmi waallathee tawalla kibrahu minhum lahu AAathabun AAatheemun', 1, NOW(), NOW()),
(29, 12, 'لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ', 'তোমরা যখন একথা শুনলে, তখন ঈমানদার পুরুষ ও নারীগণ কেন নিজেদের লোক সম্পর্কে উত্তম ধারণা করনি এবং বলনি যে, এটা তো নির্জলা অপবাদ', 'Lawla ith samiAAtumoohu thanna almuminoona waalmuminatu bianfusihim khayran waqaloo hatha ifkun mubeenun', 1, NOW(), NOW()),
(29, 13, 'لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَـٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ', 'তারা কেন এ ব্যাপারে চার জন সাক্ষী উপস্থিত করেনি; অতঃপর যখন তারা সাক্ষী উপস্থিত করেনি, তখন তারাই আল্লাহর কাছে মিথ্যাবাদী।', 'Lawla jaoo AAalayhi biarbaAAati shuhadaa faith lam yatoo bialshshuhadai faolaika AAinda Allahi humu alkathiboona', 1, NOW(), NOW()),
(29, 14, 'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ', 'যদি ইহকালে ও পরকালে তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকত, তবে তোমরা যা চর্চা করছিলে, তজ্জন্যে তোমাদেরকে গুরুতর আযাব স্পর্শ করত।', 'Walawla fadlu Allahi AAalaykum warahmatuhu fee alddunya waalakhirati lamassakum fee ma afadtum feehi AAathabun AAatheemun', 1, NOW(), NOW()),
(29, 15, 'إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ', 'যখন তোমরা একে মুখে মুখে ছড়াচ্ছিলে এবং মুখে এমন বিষয় উচ্চারণ করছিলে, যার কোন জ্ঞান তোমাদের ছিল না। তোমরা একে তুচ্ছ মনে করছিলে, অথচ এটা আল্লাহর কাছে গুরুতর ব্যাপার ছিল।', 'Ith talaqqawnahu bialsinatikum wataqooloona biafwahikum ma laysa lakum bihi AAilmun watahsaboonahu hayyinan wahuwa AAinda Allahi AAatheemun', 1, NOW(), NOW()),
(29, 16, 'وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ', 'তোমরা যখন এ কথা শুনলে তখন কেন বললে না যে, এ বিষয়ে কথা বলা আমাদের উচিত নয়। আল্লাহ তো পবিত্র, মহান। এটা তো এক গুরুতর অপবাদ।', 'Walawla ith samiAAtumoohu qultum ma yakoonu lana an natakallama bihatha subhanaka hatha buhtanun AAatheemun', 1, NOW(), NOW()),
(29, 17, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ', 'আল্লাহ তোমাদেরকে উপদেশ দিচ্ছেন, তোমরা যদি ঈমানদার হও, তবে তখনও পুনরায় এ ধরণের আচরণের পুনরাবৃত্তি করো না।', 'YaAAithukumu Allahu an taAAoodoo limithlihi abadan in kuntum mumineena', 1, NOW(), NOW()),
(29, 18, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'আল্লাহ তোমাদের জন্যে কাজের কথা স্পষ্ট করে বর্ণনা করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Wayubayyinu Allahu lakumu alayati waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(29, 19, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ', 'যারা পছন্দ করে যে, ঈমানদারদের মধ্যে ব্যভিচার প্রসার লাভ করুক, তাদের জন্যে ইহাকাল ও পরকালে যন্ত্রণাদায়ক শাস্তি রয়েছে। আল্লাহ জানেন, তোমরা জান না।', 'Inna allatheena yuhibboona an tasheeAAa alfahishatu fee allatheena amanoo lahum AAathabun aleemun fee alddunya waalakhirati waAllahu yaAAlamu waantum la taAAlamoona', 1, NOW(), NOW()),
(29, 20, 'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٞ رَّحِيمٞ', 'যদি তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকত এবং আল্লাহ দয়ালু, মেহেরবান না হতেন, তবে কত কিছুই হয়ে যেত।', 'Walawla fadlu Allahi AAalaykum warahmatuhu waanna Allaha raoofun raheemun', 1, NOW(), NOW()),
(29, 21, '۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ', 'হে ঈমানদারগণ, তোমরা শয়তানের পদাঙ্ক অনুসরণ করো না। যে কেউ শয়তানের পদাঙ্ক অনুসরণ করবে, তখন তো শয়তান নির্লজ্জতা ও মন্দ কাজেরই আদেশ করবে। যদি আল্লাহর অনুগ্রহ ও দয়া তোমাদের প্রতি না থাকত, তবে তোমাদের কেউ কখনও পবিত্র হতে পারতে না। কিন্তু আল্লাহ যাকে ইচ্ছা পবিত্র করেন। আল্লাহ সবকিছু শোনেন, জানেন।', 'Ya ayyuha allatheena amanoo la tattabiAAoo khutuwati alshshaytani waman yattabiAA khutuwati alshshaytani fainnahu yamuru bialfahshai waalmunkari walawla fadlu Allahi AAalaykum warahmatuhu ma zaka minkum min ahadin abadan walakinna Allaha yuzakkee man yashao waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(29, 22, 'وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ', 'তোমাদের মধ্যে যারা উচ্চমর্যাদা ও আর্থিক প্রাচুর্যের অধিকারী, তারা যেন কসম না খায় যে, তারা আত্নীয়-স্বজনকে, অভাবগ্রস্তকে এবং আল্লাহর পথে হিজরতকারীদেরকে কিছুই দেবে না। তাদের ক্ষমা করা উচিত এবং দোষক্রটি উপেক্ষা করা উচিত। তোমরা কি কামনা কর না যে, আল্লাহ তোমাদেরকে ক্ষমা করেন? আল্লাহ ক্ষমাশীল, পরম করুণাময়।', 'Wala yatali oloo alfadli minkum waalssaAAati an yutoo olee alqurba waalmasakeena waalmuhajireena fee sabeeli Allahi walyaAAfoo walyasfahoo ala tuhibboona an yaghfira Allahu lakum waAllahu ghafoorun raheemun', 1, NOW(), NOW()),
(29, 23, 'إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ', 'যারা সতী-সাধ্বী, নিরীহ ঈমানদার নারীদের প্রতি অপবাদ আরোপ করে, তারা ইহকালে ও পরকালে ধিকৃত এবং তাদের জন্যে রয়েছে গুরুতর শাস্তি।', 'Inna allatheena yarmoona almuhsanati alghafilati almuminati luAAinoo fee alddunya waalakhirati walahum AAathabun AAatheemun', 1, NOW(), NOW()),
(29, 24, 'يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ', 'যেদিন প্রকাশ করে দেবে তাদের জিহবা, তাদের হাত ও তাদের পা, যা কিছু তারা করত', 'Yawma tashhadu AAalayhim alsinatuhum waaydeehim waarjuluhum bima kanoo yaAAmaloona', 1, NOW(), NOW()),
(29, 25, 'يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ', 'সেদিন আল্লাহ তাদের সমুচিত শাস্তি পুরোপুরি দেবেন এবং তারা জানতে পারবে যে, অল্লাহই সত্য, স্পষ্ট ব্যক্তকারী।', 'Yawmaithin yuwaffeehimu Allahu deenahumu alhaqqa wayaAAlamoona anna Allaha huwa alhaqqu almubeenu', 1, NOW(), NOW()),
(29, 26, 'ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَـٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ', 'দুশ্চরিত্রা নারীকূল দুশ্চরিত্র পুরুষকুলের জন্যে এবং দুশ্চরিত্র পুরুষকুল দুশ্চরিত্রা নারীকুলের জন্যে। সচ্চরিত্রা নারীকুল সচ্চরিত্র পুরুষকুলের জন্যে এবং সচ্চরিত্র পুরুষকুল সচ্চরিত্রা নারীকুলের জন্যে। তাদের সম্পর্কে লোকে যা বলে, তার সাথে তারা সম্পর্কহীন। তাদের জন্যে আছে ক্ষমা ও সম্মানজনক জীবিকা।', 'Alkhabeethatu lilkhabeetheena waalkhabeethoona lilkhabeethati waalttayyibatu lilttayyibeena waalttayyiboona lilttayyibati olaika mubarraoona mimma yaqooloona lahum maghfiratun warizqun kareemun', 1, NOW(), NOW()),
(29, 27, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ', 'হে মুমিনগণ, তোমরা নিজেদের গৃহ ব্যতীত অন্য গৃহে প্রবেশ করো না, যে পর্যন্ত আলাপ-পরিচয় না কর এবং গৃহবাসীদেরকে সালাম না কর। এটাই তোমাদের জন্যে উত্তম, যাতে তোমরা স্মরণ রাখ।', 'Ya ayyuha allatheena amanoo la tadkhuloo buyootan ghayra buyootikum hatta tastanisoo watusallimoo AAala ahliha thalikum khayrun lakum laAAallakum tathakkaroona', 1, NOW(), NOW()),
(29, 28, 'فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ', 'যদি তোমরা গৃহে কাউকে না পাও, তবে অনুমতি গ্রহণ না করা পর্যন্ত সেখানে প্রবেশ করো না। যদি তোমাদেরকে বলা হয় ফিরে যাও, তবে ফিরে যাবে। এতে তোমাদের জন্যে অনেক পবিত্রতা আছে এবং তোমরা যা কর, আল্লাহ তা ভালোভাবে জানেন।', 'Fain lam tajidoo feeha ahadan fala tadkhulooha hatta yuthana lakum wain qeela lakumu irjiAAoo fairjiAAoo huwa azka lakum waAllahu bima taAAmaloona AAaleemun', 1, NOW(), NOW()),
(29, 29, 'لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ فِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ', 'যে গৃহে কেউ বাস করে না, যাতে তোমাদের সামগ্রী আছে এমন গৃহে প্রবেশ করাতে তোমাদের কোন পাপ নেই এবং আল্লাহ জানেন তোমরা যা প্রকাশ কর এবং যা গোপন কর।', 'Laysa AAalaykum junahun an tadkhuloo buyootan ghayra maskoonatin feeha mataAAun lakum waAllahu yaAAlamu ma tubdoona wama taktumoona', 1, NOW(), NOW()),
(29, 30, 'قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ', 'মুমিনদেরকে বলুন, তারা যেন তাদের দৃষ্টি নত রাখে এবং তাদের যৌনাঙ্গর হেফাযত করে। এতে তাদের জন্য খুব পবিত্রতা আছে। নিশ্চয় তারা যা করে আল্লাহ তা অবহিত আছেন।', 'Qul lilmumineena yaghuddoo min absarihum wayahfathoo furoojahum thalika azka lahum inna Allaha khabeerun bima yasnaAAoona', 1, NOW(), NOW()),
(29, 31, 'وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّـٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ', 'ঈমানদার নারীদেরকে বলুন, তারা যেন তাদের দৃষ্টিকে নত রাখে এবং তাদের যৌন অঙ্গের হেফাযত করে। তারা যেন যা সাধারণতঃ প্রকাশমান, তা ছাড়া তাদের সৌন্দর্য প্রদর্শন না করে এবং তারা যেন তাদের মাথার ওড়না বক্ষ দেশে ফেলে রাখে এবং তারা যেন তাদের স্বামী, পিতা, শ্বশুর, পুত্র, স্বামীর পুত্র, ভ্রাতা, ভ্রাতুস্পুত্র, ভগ্নিপুত্র, স্ত্রীলোক অধিকারভুক্ত বাঁদী, যৌনকামনামুক্ত পুরুষ, ও বালক, যারা নারীদের গোপন অঙ্গ সম্পর্কে অজ্ঞ, তাদের ব্যতীত কারো আছে তাদের সৌন্দর্য প্রকাশ না করে, তারা যেন তাদের গোপন সাজ-সজ্জা প্রকাশ করার জন্য জোরে পদচারণা না করে। মুমিনগণ, তোমরা সবাই আল্লাহর সামনে তওবা কর, যাতে তোমরা সফলকাম হও।', 'Waqul lilmuminati yaghdudna min absarihinna wayahfathna furoojahunna wala yubdeena zeenatahunna illa ma thahara minha walyadribna bikhumurihinna AAala juyoobihinna wala yubdeena zeenatahunna illa libuAAoolatihinna aw abaihinna aw abai buAAoolatihinna aw abnaihinna aw abnai buAAoolatihinna aw ikhwanihinna aw banee ikhwanihinna aw banee akhawatihinna aw nisaihinna aw ma malakat aymanuhunna awi alttabiAAeena ghayri olee alirbati mina alrrijali awi alttifli allatheena lam yathharoo AAala AAawrati alnnisai wala yadribna biarjulihinna liyuAAlama ma yukhfeena min zeenatihinna watooboo ila Allahi jameeAAan ayyuha almuminoona laAAallakum tuflihoona', 1, NOW(), NOW()),
(29, 32, 'وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّـٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ', 'তোমাদের মধ্যে যারা বিবাহহীন, তাদের বিবাহ সম্পাদন করে দাও এবং তোমাদের দাস ও দাসীদের মধ্যে যারা সৎকর্মপরায়ন, তাদেরও। তারা যদি নিঃস্ব হয়, তবে আল্লাহ নিজ অনুগ্রহে তাদেরকে সচ্ছল করে দেবেন। আল্লাহ প্রাচুর্যময়, সর্বজ্ঞ।', 'Waankihoo alayama minkum waalssaliheena min AAibadikum waimaikum in yakoonoo fuqaraa yughnihimu Allahu min fadlihi waAllahu wasiAAun AAaleemun', 1, NOW(), NOW()),
(29, 33, 'وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ', 'যারা বিবাহে সামর্থ নয়, তারা যেন সংযম অবলম্বন করে যে পর্যন্ত না আল্লাহ নিজ অনুগ্রহে তাদেরকে অভাবমুক্ত করে দেন। তোমাদের অধিকারভুক্তদের মধ্যে যারা মুক্তির জন্য লিখিত চুক্তি করতে চায়, তাদের সাথে তোমরা লিখিত চুক্তি কর যদি জান যে, তাদের মধ্যে কল্যাণ আছে। আল্লাহ তোমাদেরকে যে, অর্থ-কড়ি দিয়েছেন, তা থেকে তাদেরকে দান কর। তোমাদের দাসীরা নিজেদের পবিত্রতা রক্ষা করতে চাইলে তোমরা পার্থিব জীবনের সম্পদের লালসায় তাদেরকে ব্যভিচারে বাধ্য কারো না। যদি কেহ তাদের উপর জোর-জবরদস্তি করে, তবে তাদের উপর জোর-জবরদস্তির পর আল্লাহ তাদের প্রতি ক্ষমাশীল, পরম দয়ালু।', 'WalyastaAAfifi allatheena la yajidoona nikahan hatta yughniyahumu Allahu min fadlihi waallatheena yabtaghoona alkitaba mimma malakat aymanukum fakatiboohum in AAalimtum feehim khayran waatoohum min mali Allahi allathee atakum wala tukrihoo fatayatikum AAala albighai in aradna tahassunan litabtaghoo AAarada alhayati alddunya waman yukrihhunna fainna Allaha min baAAdi ikrahihinna ghafoorun raheemun', 1, NOW(), NOW()),
(29, 34, 'وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتٖ مُّبَيِّنَٰتٖ وَمَثَلٗا مِّنَ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۡ وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ', 'আমি তোমাদের প্রতি অবতীর্ণ করেছি সুস্পষ্ট আয়াতসমূহ, তোমাদের পূর্ববর্তীদের কিছু দৃষ্টান্ত এবং আল্লাহ ভীরুদের জন্যে দিয়েছি উপদেশ।', 'Walaqad anzalna ilaykum ayatin mubayyinatin wamathalan mina allatheena khalaw min qablikum wamawAAithatan lilmuttaqeena', 1, NOW(), NOW()),
(29, 35, '۞ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'আল্লাহ নভোমন্ডল ও ভূমন্ডলের জ্যোতি, তাঁর জ্যোতির উদাহরণ যেন একটি কুলঙ্গি, যাতে আছে একটি প্রদীপ, প্রদীপটি একটি কাঁচপাত্রে স্থাপিত, কাঁচপাত্রটি উজ্জ্বল নক্ষত্র সদৃশ্য। তাতে পুতঃপবিত্র যয়তুন বৃক্ষের তৈল প্রজ্বলিত হয়, যা পূর্বমুখী নয় এবং পশ্চিমমুখীও নয়। অগ্নি স্পর্শ না করলেও তার তৈল যেন আলোকিত হওয়ার নিকটবর্তী। জ্যোতির উপর জ্যোতি। আল্লাহ যাকে ইচ্ছা পথ দেখান তাঁর জ্যোতির দিকে। আল্লাহ মানুষের জন্যে দৃষ্টান্তসমূহ বর্ণনা করেন এবং আল্লাহ সব বিষয়ে জ্ঞাত।', 'Allahu nooru alssamawati waalardi mathalu noorihi kamishkatin feeha misbahun almisbahu fee zujajatin alzzujajatu kaannaha kawkabun durriyyun yooqadu min shajaratin mubarakatin zaytoonatin la sharqiyyatin wala gharbiyyatin yakadu zaytuha yudeeo walaw lam tamsashu narun noorun AAala noorin yahdee Allahu linoorihi man yashao wayadribu Allahu alamthala lilnnasi waAllahu bikulli shayin AAaleemun', 1, NOW(), NOW()),
(29, 36, 'فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ', 'আল্লাহ যেসব গৃহকে মর্যাদায় উন্নীত করার এবং সেগুলোতে তাঁর নাম উচ্চারণ করার আদেশ দিয়েছেন, সেখানে সকাল ও সন্ধ্যায় তাঁর পবিত্রতা ও মহিমা ঘোষণা করে', 'Fee buyootin athina Allahu an turfaAAa wayuthkara feeha ismuhu yusabbihu lahu feeha bialghuduwwi waalasali', 1, NOW(), NOW()),
(29, 37, 'رِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ', 'এমন লোকেরা, যাদেরকে ব্যবসা-বাণিজ্য ও ক্রয়-বিক্রয় আল্লাহর স্মরণ থেকে, নামায কায়েম করা থেকে এবং যাকাত প্রদান করা থেকে বিরত রাখে না। তারা ভয় করে সেই দিনকে, যেদিন অন্তর ও দৃষ্টিসমূহ উল্টে যাবে।', 'Rijalun la tulheehim tijaratun wala bayAAun AAan thikri Allahi waiqami alssalati waeetai alzzakati yakhafoona yawman tataqallabu feehi alquloobu waalabsaru', 1, NOW(), NOW()),
(29, 38, 'لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ', '(তারা আল্লাহর পবিত্রতা ঘোষণা করে) যাতে আল্লাহ তাদের উৎকৃষ্টতর কাজের প্রতিদান দেন এবং নিজ অনুগ্রহে আরও অধিক দেন। আল্লাহ যাকে ইচ্ছা অপরিমিত রুযী দান করেন।', 'Liyajziyahumu Allahu ahsana ma AAamiloo wayazeedahum min fadlihi waAllahu yarzuqu man yashao bighayri hisabin', 1, NOW(), NOW()),
(29, 39, 'وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ', 'যারা কাফের, তাদের কর্ম মরুভুমির মরীচিকা সদৃশ, যাকে পিপাসার্ত ব্যক্তি পানি মনে করে। এমনকি, সে যখন তার কাছে যায়, তখন কিছুই পায় না এবং পায় সেখানে আল্লাহকে, অতঃপর আল্লাহ তার হিসাব চুকিয়ে দেন। আল্লাহ দ্রুত হিসাব গ্রহণকারী।', 'Waallatheena kafaroo aAAmaluhum kasarabin biqeeAAatin yahsabuhu alththamanu maan hatta itha jaahu lam yajidhu shayan wawajada Allaha AAindahu fawaffahu hisabahu waAllahu sareeAAu alhisabi', 1, NOW(), NOW()),
(29, 40, 'أَوۡ كَظُلُمَٰتٖ فِي بَحۡرٖ لُّجِّيّٖ يَغۡشَىٰهُ مَوۡجٞ مِّن فَوۡقِهِۦ مَوۡجٞ مِّن فَوۡقِهِۦ سَحَابٞۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورٗا فَمَا لَهُۥ مِن نُّورٍ', 'অথবা (তাদের কর্ম) প্রমত্ত সমুদ্রের বুকে গভীর অন্ধকারের ন্যায়, যাকে উদ্বেলিত করে তরঙ্গের উপর তরঙ্গ, যার উপরে ঘন কালো মেঘ আছে। একের উপর এক অন্ধকার। যখন সে তার হাত বের করে, তখন তাকে একেবারেই দেখতে পায় না। আল্লাহ যাকে জ্যোতি দেন না, তার কোন জ্যোতিই নেই।', 'Aw kathulumatin fee bahrin lujjiyyin yaghshahu mawjun min fawqihi mawjun min fawqihi sahabun thulumatun baAAduha fawqa baAAdin itha akhraja yadahu lam yakad yaraha waman lam yajAAali Allahu lahu nooran fama lahu min noorin', 1, NOW(), NOW()),
(29, 41, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَـٰٓفَّـٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ', 'তুমি কি দেখ না যে, নভোমন্ডল ও ভূমন্ডলে যারা আছে, তারা এবং উড়ন্ত পক্ষীকুল তাদের পাখা বিস্তার করতঃ আল্লাহর পবিত্রতা ও মহিমা ঘোষণা করে? প্রত্যেকেই তার যোগ্য এবাদত এবং পবিত্রতা ও মহিমা ঘোষণার পদ্ধতি জানে। তারা যা করে, আল্লাহ সে বিষয়ে সম্যক জ্ঞাত।', 'Alam tara anna Allaha yusabbihu lahu man fee alssamawati waalardi waalttayru saffatin kullun qad AAalima salatahu watasbeehahu waAllahu AAaleemun bima yafAAaloona', 1, NOW(), NOW()),
(29, 42, 'وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ', 'নভোমন্ডল ও ভূমন্ডলের সার্বভৌমত্ব আল্লাহরই এবং তাঁরই দিকে প্রত্যাবর্তন করতে হবে।', 'Walillahi mulku alssamawati waalardi waila Allahi almaseeru', 1, NOW(), NOW()),
(29, 43, 'أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي سَحَابٗا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامٗا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٖ فِيهَا مِنۢ بَرَدٖ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ', 'তুমি কি দেখ না যে, আল্লাহ মেঘমালাকে সঞ্চালিত করেন, অতঃপর তাকে পুঞ্জীভূত করেন, অতঃপর তাকে স্তরে স্তরে রাখেন; অতঃপর তুমি দেখ যে, তার মধ্য থেকে বারিধারা নির্গত হয়। তিনি আকাশস্থিত শিলাস্তুপ থেকে শিলাবর্ষণ করেন এবং তা দ্বারা যাকে ইচ্ছা আঘাত করেন এবং যার কাছ থেকে ইচ্ছা, তা অন্যদিকে ফিরিয়ে দেন। তার বিদ্যুৎঝলক দৃষ্টিশক্তি যেন বিলীন করে দিতে চায়।', 'Alam tara anna Allaha yuzjee sahaban thumma yuallifu baynahu thumma yajAAaluhu rukaman fatara alwadqa yakhruju min khilalihi wayunazzilu mina alssamai min jibalin feeha min baradin fayuseebu bihi man yashao wayasrifuhu AAan man yashao yakadu sana barqihi yathhabu bialabsari', 1, NOW(), NOW()),
(29, 44, 'يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ', 'আল্লাহ দিন ও রাত্রির পরিবর্তন ঘটান। এতে অর্ন্তদৃষ্টি-সম্পন্নগণের জন্যে চিন্তার উপকরণ রয়েছে।', 'Yuqallibu Allahu allayla waalnnahara inna fee thalika laAAibratan liolee alabsari', 1, NOW(), NOW()),
(29, 45, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٖ مِّن مَّآءٖۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعٖۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ', 'আল্লাহ প্রত্যেক চলন্ত জীবকে পানি দ্বারা সৃষ্টি করেছেন। তাদের কতক বুকে ভয় দিয়ে চলে, কতক দুই পায়ে ভর দিয়ে চলে এবং কতক চার পায়ে ভর দিয়ে চলে; আল্লাহ যা ইচ্ছা সৃষ্টি করেন। নিশ্চয়ই আল্লাহ সবকিছু করতে সক্ষম।', 'WaAllahu khalaqa kulla dabbatin min main faminhum man yamshee AAala batnihi waminhum man yamshee AAala rijlayni waminhum man yamshee AAala arbaAAin yakhluqu Allahu ma yashao inna Allaha AAala kulli shayin qadeerun', 1, NOW(), NOW()),
(29, 46, 'لَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ', 'আমি তো সুস্পষ্ট আয়াত সমূহ অবর্তীর্ণ করেছি। আল্লাহ যাকে ইচ্ছা সরল পথে পরিচালনা করেন।', 'Laqad anzalna ayatin mubayyinatin waAllahu yahdee man yashao ila siratin mustaqeemin', 1, NOW(), NOW()),
(29, 47, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ', 'তারা বলেঃ আমরা আল্লাহ ও রসূলের প্রতি বিশ্বাস স্থাপন করেছি এবং আনুগত্য করি; কিন্তু অতঃপর তাদের একদল মুখ ফিরিয়ে নেয় এবং তারা বিশ্বাসী নয়।', 'Wayaqooloona amanna biAllahi wabialrrasooli waataAAna thumma yatawalla fareequn minhum min baAAdi thalika wama olaika bialmumineena', 1, NOW(), NOW()),
(29, 48, 'وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ', 'তাদের মধ্যে ফয়সালা করার জন্য যখন তাদেরকে আল্লাহ ও রসূলের দিকে আহবান করা হয তখন তাদের একদল মুখ ফিরিয়ে নেয়।', 'Waitha duAAoo ila Allahi warasoolihi liyahkuma baynahum itha fareequn minhum muAAridoona', 1, NOW(), NOW()),
(29, 49, 'وَإِن يَكُن لَّهُمُ ٱلۡحَقُّ يَأۡتُوٓاْ إِلَيۡهِ مُذۡعِنِينَ', 'সত্য তাদের স্বপক্ষে হলে তারা বিনীতভাবে রসূলের কাছে ছুটে আসে।', 'Wain yakun lahumu alhaqqu yatoo ilayhi muthAAineena', 1, NOW(), NOW()),
(29, 50, 'أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 'তাদের অন্তরে কি রোগ আছে, না তারা ধোঁকায় পড়ে আছে; না তারা ভয় করে যে, আল্লাহ ও তাঁর রাসূল তাদের প্রতি অবিচার করবেন? বরং তারাই তো অবিচারকারী', 'Afee quloobihim maradun ami irtaboo am yakhafoona an yaheefa Allahu AAalayhim warasooluhu bal olaika humu alththalimoona', 1, NOW(), NOW()),
(29, 51, 'إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ', 'মুমিনদের বক্তব্য কেবল এ কথাই যখন তাদের মধ্যে ফয়সালা করার জন্যে আল্লাহ ও তাঁর রসূলের দিকে তাদেরকে আহবান করা হয়, তখন তারা বলেঃ আমরা শুনলাম ও আদেশ মান্য করলাম। তারাই সফলকাম।', 'Innama kana qawla almumineena itha duAAoo ila Allahi warasoolihi liyahkuma baynahum an yaqooloo samiAAna waataAAna waolaika humu almuflihoona', 1, NOW(), NOW()),
(29, 52, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ', 'যারা আল্লাহ ও তাঁর রসূলের আনুগত্য করে আল্লাহকে ভয় করে ও তাঁর শাস্তি থেকে বেঁচে থাকে তারাই কৃতকার্য।', 'Waman yutiAAi Allaha warasoolahu wayakhsha Allaha wayattaqhi faolaika humu alfaizoona', 1, NOW(), NOW()),
(29, 53, '۞وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ', 'তারা দৃঢ়ভাবে আল্লাহর কসম খেয়ে বলে যে, আপনি তাদেরকে আদেশ করলে তারা সবকিছু ছেড়ে বের হবেই। বলুনঃ তোমরা কসম খেয়ো না। নিয়মানুযায়ী তোমাদের আনুগত্য, তোমরা যা কিছু কর নিশ্চয় আল্লাহ সে বিষয়ে জ্ঞাত।', 'Waaqsamoo biAllahi jahda aymanihim lain amartahum layakhrujunna qul la tuqsimoo taAAatun maAAroofatun inna Allaha khabeerun bima taAAmaloona', 1, NOW(), NOW()),
(29, 54, 'قُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ', 'বলুনঃ আল্লাহর আনুগত্য কর এবং রসূলের আনুগত্য কর। অতঃপর যদি তোমরা মুখ ফিরিয়ে নাও, তবে তার উপর ন্যস্ত দায়িত্বের জন্যে সে দায়ী এবং তোমাদের উপর ন্যস্ত দায়িত্বের জন্যে তোমরা দায়ী। তোমরা যদি তাঁর আনুগত্য কর, তবে সৎ পথ পাবে। রসূলের দায়িত্ব তো কেবল সুস্পষ্টরূপে পৌছে দেয়া।', 'Qul ateeAAoo Allaha waateeAAoo alrrasoola fain tawallaw fainnama AAalayhi ma hummila waAAalaykum ma hummiltum wain tuteeAAoohu tahtadoo wama AAala alrrasooli illa albalaghu almubeena', 1, NOW(), NOW()),
(29, 55, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي شَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ', 'তোমাদের মধ্যে যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে, আল্লাহ তাদেরকে ওয়াদা দিয়েছেন যে, তাদেরকে অবশ্যই পৃথিবীতে শাসনকর্তৃত্ব দান করবেন। যেমন তিনি শাসনকতৃꦣ2468;্ব দান করেছেন তাদের পূর্ববতীদেরকে এবং তিনি অবশ্যই সুদৃঢ় করবেন তাদের ধর্মকে, যা তিনি তাদের জন্যে পছন্দ করেছেন এবং তাদের ভয়-ভীতির পরিবর্তে অবশ্যই তাদেরকে শান্তি দান করবেন। তারা আমার এবাদত করবে এবং আমার সাথে কাউকে শরীক করবে না। এরপর যারা অকৃতজ্ঞ হবে, তারাই অবাধ্য।', 'WaAAada Allahu allatheena amanoo minkum waAAamiloo alssalihati layastakhlifannahum fee alardi kama istakhlafa allatheena min qablihim walayumakkinanna lahum deenahumu allathee irtada lahum walayubaddilannahum min baAAdi khawfihim amnan yaAAbudoonanee la yushrikoona bee shayan waman kafara baAAda thalika faolaika humu alfasiqoona', 1, NOW(), NOW()),
(29, 56, 'وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ', 'নামায কায়েম কর, যাকাত প্রদান কর এবং রসূলের আনুগত্য কর যাতে তোমরা অনুগ্রহ প্রাপ্ত হও।', 'Waaqeemoo alssalata waatoo alzzakata waateeAAoo alrrasoola laAAallakum turhamoona', 1, NOW(), NOW()),
(29, 57, 'لَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ', 'তোমরা কাফেরদেরকে পৃথিবীতে পরাক্রমশালী মনে করো না। তাদের ঠিকানা অগ্নি। কতই না নিকৃষ্ট এই প্রত্যাবর্তনস্থল।', 'La tahsabanna allatheena kafaroo muAAjizeena fee alardi wamawahumu alnnaru walabisa almaseeru', 1, NOW(), NOW()),
(29, 58, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّـٰتٖۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتٖ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّـٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضٖۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'হে মুমিনগণ! তোমাদের দাসদাসীরা এবং তোমাদের মধ্যে যারা প্রাপ্ত বয়স্ক হয়নি তারা যেন তিন সময়ে তোমাদের কাছে অনুমতি গ্রহণ করে, ফজরের নামাযের পূর্বে, দুপুরে যখন তোমরা বস্ত্র খুলে রাখ এবং এশার নামাযের পর। এই তিন সময় তোমাদের দেহ খোলার সময়। এ সময়ের পর তোমাদের ও তাদের জন্যে কোন দোষ নেই। তোমাদের একে অপরের কাছে তো যাতায়াত করতেই হয়, এমনি ভাবে আল্লাহ তোমাদের কাছে সুস্পষ্ট আয়াতসমূহ বিবৃত করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Ya ayyuha allatheena amanoo liyastathinkumu allatheena malakat aymanukum waallatheena lam yablughoo alhuluma minkum thalatha marratin min qabli salati alfajri waheena tadaAAoona thiyabakum mina alththaheerati wamin baAAdi salati alAAishai thalathu AAawratin lakum laysa AAalaykum wala AAalayhim junahun baAAdahunna tawwafoona AAalaykum baAAdukum AAala baAAdin kathalika yubayyinu Allahu lakumu alayati waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(29, 59, 'وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ', 'তোমাদের সন্তান-সন্ততিরা যখন বায়োপ্রাপ্ত হয়, তারাও যেন তাদের পূর্ববর্তীদের ন্যায় অনুমতি চায়। এমনিভাবে আল্লাহ তাঁর আয়াতসমূহ তোমাদের কাছে বর্ণনা করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।', 'Waitha balagha alatfalu minkumu alhuluma falyastathinoo kama istathana allatheena min qablihim kathalika yubayyinu Allahu lakum ayatihi waAllahu AAaleemun hakeemun', 1, NOW(), NOW()),
(29, 60, 'وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّـٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ', 'বৃদ্ধা নারী, যারা বিবাহের আশা রাখে না, যদি তারা তাদের সৌন্দর্য?2474;্রকাশ না করে তাদের বস্ত্র খুলে রাখে। তাদের জন্যে দোষ নেই, তবে এ থেকে বিরত থাকাই তাদের জন্যে উত্তম। আল্লাহ সর্বশ্রোতা, সর্বজ্ঞ।', 'WaalqawaAAidu mina alnnisai allatee la yarjoona nikahan falaysa AAalayhinna junahun an yadaAAna thiyabahunna ghayra mutabarrijatin bizeenatin waan yastaAAfifna khayrun lahunna waAllahu sameeAAun AAaleemun', 1, NOW(), NOW()),
(29, 61, 'لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞ وَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّـٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ فَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ', 'অন্ধের জন্যে দোষ নেই, খঞ্জের জন্যে দোষ নেই, রোগীর জন্যে দোষ নেই, এবং তোমাদের নিজেদের জন্যেও দোষ নেই যে, তোমরা আহার করবে তোমাদের গৃহে অথবা তোমাদের পিতাদের গৃহে অথবা তোমাদের মাতাদের গৃহে অথবা তোমাদের ভ্রাতাদের গৃহে অথবা তোমাদের ভগিণীদের গৃহে অথবা তোমাদের পিতৃব্যদের গৃহে অথবা তোমাদের ফুফুদের গৃহে অথবা তোমাদের মামাদের গৃহে অথবা তোমাদের খালাদের গৃহে অথবা সেই গৃহে, যার চাবি আছে তোমাদের হাতে অথবা তোমাদের বন্ধুদের গৃহে। তোমরা একত্রে আহার কর অথবা পৃথকভবে আহার কর, তাতে তোমাদের কোন দোষ নেই। অতঃপর যখন তোমরা গৃহে প্রবেশ কর, তখন তোমাদের স্বজনদের প্রতি সালাম বলবে। এটা আল্লাহর কাছ থেকে কল্যাণময় ও পবিত্র দোয়া। এমনিভাবে আল্লাহ তোমাদের জন্যে আয়াতসমূহ বিশদভাবে বর্ননা করেন, যাতে তোমরা বুঝে নাও।', 'Laysa AAala alaAAma harajun wala AAala alaAAraji harajun wala AAala almareedi harajun wala AAala anfusikum an takuloo min buyootikum aw buyooti abaikum aw buyooti ommahatikum aw buyooti ikhwanikum aw buyooti akhawatikum aw buyooti aAAmamikum aw buyooti AAammatikum aw buyooti akhwalikum aw buyooti khalatikum aw ma malaktum mafatihahu aw sadeeqikum laysa AAalaykum junahun an takuloo jameeAAan aw ashtatan faitha dakhaltum buyootan fasallimoo AAala anfusikum tahiyyatan min AAindi Allahi mubarakatan tayyibatan kathalika yubayyinu Allahu lakumu alayati laAAallakum taAAqiloona', 1, NOW(), NOW()),
(29, 62, 'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَـٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ', 'মুমিন তো তারাই; যারা আল্লাহর ও রসূলের প্রতি বিশ্বাস স্থাপন করে এবং রসূলের সাথে কোন সমষ্টিগত কাজে শরীক হলে তাঁর কাছ থেকে অনুমতি গ্রহণ ব্যতীত চলে যায় না। যারা আপনার কাছে অনুমতি প্রার্থনা করে, তারাই আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করে। অতএব তারা আপনার কাছে তাদের কোন কাজের জন্যে অনুমতি চাইলে আপনি তাদের মধ্যে যাকে ইচ্ছা অনুমতি দিন এবং তাদের জন্যে আল্লাহর কাছে ক্ষমা প্রার্থনা করুন। আল্লাহ ক্ষমাশীল, মেহেরবান।', 'Innama almuminoona allatheena amanoo biAllahi warasoolihi waitha kanoo maAAahu AAala amrin jamiAAin lam yathhaboo hatta yastathinoohu inna allatheena yastathinoonaka olaika allatheena yuminoona biAllahi warasoolihi faitha istathanooka libaAAdi shanihim fathan liman shita minhum waistaghfir lahumu Allaha inna Allaha ghafoorun raheemun', 1, NOW(), NOW()),
(29, 63, 'لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمۡ لِوَاذٗاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ', 'রসূলের আহবানকে তোমরা তোমাদের একে অপরকে আহ্বানের মত গণ্য করো না। আল্লাহ তাদেরকে জানেন, যারা তোমাদের মধ্যে চুপিসারে সরে পড়ে। অতএব যারা তাঁর আদেশের বিরুদ্ধাচরণ করে, তারা এ বিষয়ে সতর্ক হোক যে, বিপর্যয় তাদেরকে স্পর্শ করবে অথবা যন্ত্রণাদায়ক শাস্তি তাদেরকে গ্রাস করবে।', 'La tajAAaloo duAAaa alrrasooli baynakum kaduAAai baAAdikum baAAdan qad yaAAlamu Allahu allatheena yatasallaloona minkum liwathan falyahthari allatheena yukhalifoona AAan amrihi an tuseebahum fitnatun aw yuseebahum AAathabun aleemun', 1, NOW(), NOW()),
(29, 64, 'أَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ', 'মনে রেখো নভোমন্ডল ও ভূমন্ডলে যা আছে, তা আল্লাহরই। তোমরা যে অবস্থায় আছ তা তিনি জানেন। যেদিন তারা তাঁর কাছে প্রত্যাবর্তিত হবে, সেদিন তিনি বলে দেবেন তারা যা করেছে। আল্লাহ প্রত্যেক বিষয়ই জানেন।', 'Ala inna lillahi ma fee alssamawati waalardi qad yaAAlamu ma antum AAalayhi wayawma yurjaAAoona ilayhi fayunabbiohum bima AAamiloo waAllahu bikulli shayin AAaleemun', 1, NOW(), NOW()),
(30, 1, 'تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا', 'পরম কল্যাণময় তিনি যিনি তাঁর বান্দার প্রতি ফয়সালার গ্রন্থ অবর্তীণ করেছেন, যাতে সে বিশ্বজগতের জন্যে সতর্ককারী হয়,।', 'Tabaraka allathee nazzala alfurqana AAala AAabdihi liyakoona lilAAalameena natheeran', 1, NOW(), NOW()),
(30, 2, 'ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا', 'তিনি হলেন যাঁর রয়েছে নভোমন্ডল ও ভূমন্ডলের রাজত্ব। তিনি কোন সন্তান গ্রহণ করেননি। রাজত্বে তাঁর কোন অংশীদার নেই। তিনি প্রত্যেক বস্তু সৃষ্টি করেছেন, অতঃপর তাকে শোধিত করেছেন পরিমিতভাবে।', 'Allathee lahu mulku alssamawati waalardi walam yattakhith waladan walam yakun lahu shareekun fee almulki wakhalaqa kulla shayin faqaddarahu taqdeeran', 1, NOW(), NOW()),
(30, 3, 'وَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا', 'তারা তাঁর পরিবর্তে কত উপাস্য গ্রহণ করেছে, যারা কিছুই সৃষ্টি করে না এবং তারা নিজেরাই সৃষ্ট এবং নিজেদের ভালও করতে পারে না, মন্দও করতে পারে না এবং জীবন, মরণ ও পুনরুজ্জীবনের ও তারা মালিক নয়।', 'Waittakhathoo min doonihi alihatan la yakhluqoona shayan wahum yukhlaqoona wala yamlikoona lianfusihim darran wala nafAAan wala yamlikoona mawtan wala hayatan wala nushooran', 1, NOW(), NOW()),
(30, 4, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمٗا وَزُورٗا', 'কাফেররা বলে, এটা মিথ্যা বৈ নয়, যা তিনি উদ্ভাবন করেছেন এবং অন্য লোকেরা তাঁকে সাহায্য করেছে। অবশ্যই তারা অবিচার ও মিথ্যার আশ্রয় নিয়েছে।', 'Waqala allatheena kafaroo in hatha illa ifkun iftarahu waaAAanahu AAalayhi qawmun akharoona faqad jaoo thulman wazooran', 1, NOW(), NOW()),
(30, 5, 'وَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا', 'তারা বলে, এগুলো তো পুরাকালের রূপকথা, যা তিনি লিখে রেখেছেন। এগুলো সকাল-সন্ধ্যায় তাঁর কাছে শেখানো হয়।', 'Waqaloo asateeru alawwaleena iktatabaha fahiya tumla AAalayhi bukratan waaseelan', 1, NOW(), NOW()),
(30, 6, 'قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا', 'বলুন, একে তিনিই অবতীর্ণ করেছেন, যিনি নভোমন্ডল ও ভূমন্ডলের গোপন রহস্য অবগত আছেন। তিনি ক্ষমাশীল, মেহেরবান।', 'Qul anzalahu allathee yaAAlamu alssirra fee alssamawati waalardi innahu kana ghafooran raheeman', 1, NOW(), NOW()),
(30, 7, 'وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ لَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكٞ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'তারা বলে, এ কেমন রসূল যে, খাদ্য আহার করে এবং হাটে-বাজারে চলাফেরা করে? তাঁর কাছে কেন কোন ফেরেশতা নাযিল করা হল না যে, তাঁর সাথে সতর্ককারী হয়ে থাকত', 'Waqaloo mali hatha alrrasooli yakulu alttaAAama wayamshee fee alaswaqi lawla onzila ilayhi malakun fayakoona maAAahu natheeran', 1, NOW(), NOW()),
(30, 8, 'أَوۡ يُلۡقَىٰٓ إِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةٞ يَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا', 'অথবা তিনি ধন-ভান্ডার প্রাপ্ত হলেন না কেন, অথবা তাঁর একটি বাগান হল না কেন, যা থেকে তিনি আহার করতেন? জালেমরা বলে, তোমরা তো একজন জাদুগ্রস্ত ব্যক্তিরই অনুসরণ করছ।', 'Aw yulqa ilayhi kanzun aw takoonu lahu jannatun yakulu minha waqala alththalimoona in tattabiAAoona illa rajulan mashooran', 1, NOW(), NOW()),
(30, 9, 'ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَٰلَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا', 'দেখুন, তারা আপনার কেমন দৃষ্টান্ত বর্ণনা করে! অতএব তারা পথভ্রষ্ট হয়েছে, এখন তারা পথ পেতে পারে না।', 'Onthur kayfa daraboo laka alamthala fadalloo fala yastateeAAoona sabeelan', 1, NOW(), NOW()),
(30, 10, 'تَبَارَكَ ٱلَّذِيٓ إِن شَآءَ جَعَلَ لَكَ خَيۡرٗا مِّن ذَٰلِكَ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَيَجۡعَل لَّكَ قُصُورَۢا', 'কল্যানময় তিনি, যিনি ইচ্ছা করলে আপনাকে তদপেক্ষা উত্তম বস্তু দিতে পারেন-বাগ-বাগিচা, যার তলদেশে নহর প্রবাহিত হয় এবং দিতে পারেন আপনাকে প্রাসাদসমূহ।', 'Tabaraka allathee in shaa jaAAala laka khayran min thalika jannatin tajree min tahtiha alanharu wayajAAal laka qusooran', 1, NOW(), NOW()),
(30, 11, 'بَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', 'বরং তারা কেয়ামতকে অস্বীকার করে এবং যে কেয়ামতকে অস্বীকার করে, আমি তার জন্যে অগ্নি প্রস্তুত করেছি।', 'Bal kaththaboo bialssaAAati waaAAtadna liman kaththaba bialssaAAati saAAeeran', 1, NOW(), NOW()),
(30, 12, 'إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا', 'অগ্নি যখন দূর থেকে তাদেরকে দেখবে, তখন তারা শুনতে পাবে তার গর্জন ও হুঙ্কার।', 'Itha raathum min makanin baAAeedin samiAAoo laha taghayyuthan wazafeeran', 1, NOW(), NOW()),
(30, 13, 'وَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورٗا', 'যখন এক শিকলে কয়েকজন বাঁধা অবস্থায় জাহান্নামের কোন সংকীর্ণ স্থানে নিক্ষেপ করা হবে, তখন সেখানে তারা মৃত্যুকে ডাকবে।', 'Waitha olqoo minha makanan dayyiqan muqarraneena daAAaw hunalika thubooran', 1, NOW(), NOW()),
(30, 14, 'لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورٗا وَٰحِدٗا وَٱدۡعُواْ ثُبُورٗا كَثِيرٗا', 'বলা হবে, আজ তোমরা এক মৃত্যুকে ডেকো না অনেক মৃত্যুকে ডাক।', 'La tadAAoo alyawma thubooran wahidan waodAAoo thubooran katheeran', 1, NOW(), NOW()),
(30, 15, 'قُلۡ أَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَآءٗ وَمَصِيرٗا', 'বলুন এটা উত্তম, না চিরকাল বসবাসের জান্নাত, যার সুসংবাদ দেয়া হয়েছে মুত্তাকীদেরকে? সেটা হবে তাদের প্রতিদান ও প্রত্যাবর্তন স্থান।', 'Qul athalika khayrun am jannatu alkhuldi allatee wuAAida almuttaqoona kanat lahum jazaan wamaseeran', 1, NOW(), NOW()),
(30, 16, 'لَّهُمۡ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدٗا مَّسۡـُٔولٗا', 'তারা চিরকাল বসবাসরত অবস্থায় সেখানে যা চাইবে, তাই পাবে। এই প্রার্থিত ওয়াদা পূরণ আপনার পালনকর্তার দায়িত্ব।', 'Lahum feeha ma yashaoona khalideena kana AAala rabbika waAAdan masoolan', 1, NOW(), NOW()),
(30, 17, 'وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَـٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ', 'সেদিন আল্লাহ একত্রিত করবেন তাদেরকে এবং তারা আল্লাহর পরিবর্তে যাদের এবাদত করত তাদেরকে, সেদিন তিনি উপাস্যদেরকে বলবেন, তোমরাই কি আমার এই বান্দাদেরকে পথভ্রান্ত করেছিলে, না তারা নিজেরাই পথভ্রান্ত হয়েছিল', 'Wayawma yahshuruhum wama yaAAbudoona min dooni Allahi fayaqoolu aantum adlaltum AAibadee haolai am hum dalloo alssabeela', 1, NOW(), NOW()),
(30, 18, 'قَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا', 'তারা বলবে-আপনি পবিত্র, আমরা আপনার পরিবর্তে অন্যকে মুরুব্বীরূপে গ্রহণ করতে পারতাম না; কিন্তু আপনিই তো তাদেরকে এবং তাদের পিতৃপুরুষদেরকে ভোগসম্ভার দিয়েছিলেন, ফলে তারা আপনার স্মৃতি বিস্মৃত হয়েছিল এবং তারা ছিল ধ্বংসপ্রাপ্ত জাতি।', 'Qaloo subhanaka ma kana yanbaghee lana an nattakhitha min doonika min awliyaa walakin mattaAAtahum waabaahum hatta nasoo alththikra wakanoo qawman booran', 1, NOW(), NOW()),
(30, 19, 'فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفٗا وَلَا نَصۡرٗاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابٗا كَبِيرٗا', 'আল্লাহ মুশরিকদেরকে বলবেন, তোমাদের কথা তো তারা মিথ্যা সাব্যস্ত করল, এখন তোমরা শাস্তি প্রতিরোধ করতে পারবে না এবং সাহায্যও করতে পারবে না। তোমাদের মধ্যে যে গোনাহগার আমি তাকে গুরুতর শাস্তি আস্বাদন করাব।', 'Faqad kaththabookum bima taqooloona fama tastateeAAoona sarfan wala nasran waman yathlim minkum nuthiqhu AAathaban kabeeran', 1, NOW(), NOW()),
(30, 20, 'وَمَآ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِينَ إِلَّآ إِنَّهُمۡ لَيَأۡكُلُونَ ٱلطَّعَامَ وَيَمۡشُونَ فِي ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا', 'আপনার পূর্বে যত রসূল প্রেরণ করেছি, তারা সবাই খাদ্য গ্রহণ করত এবং হাটে-বাজারে চলাফেরা করত। আমি তোমাদের এককে অপরের জন্যে পরীক্ষাস্বরূপ করেছি। দেখি, তোমরা সবর কর কিনা। আপনার পালনকর্তা সব কিছু দেখেন।', 'Wama arsalna qablaka mina almursaleena illa innahum layakuloona alttaAAama wayamshoona fee alaswaqi wajaAAalna baAAdakum libaAAdin fitnatan atasbiroona wakana rabbuka baseeran', 1, NOW(), NOW()),
(30, 21, '۞وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَـٰٓئِكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوّٗا كَبِيرٗا', 'যারা আমার সাক্ষাৎ আশা করে না, তারা বলে, আমাদের কাছে ফেরেশতা অবতীর্ণ করা হল না কেন? অথবা আমরা আমাদের পালনকর্তাকে দেখি না কেন? তারা নিজেদের অন্তরে অহংকার পোষণ করে এবং গুরুতর অবাধ্যতায় মেতে উঠেছে।', 'Waqala allatheena la yarjoona liqaana lawla onzila AAalayna almalaikatu aw nara rabbana laqadi istakbaroo fee anfusihim waAAataw AAutuwwan kabeeran', 1, NOW(), NOW()),
(30, 22, 'يَوۡمَ يَرَوۡنَ ٱلۡمَلَـٰٓئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِذٖ لِّلۡمُجۡرِمِينَ وَيَقُولُونَ حِجۡرٗا مَّحۡجُورٗا', 'যেদিন তারা ফেরেশতাদেরকে দেখবে, সেদিন অপরাধীদের জন্যে কোন সুসংবাদ থাকবে না এবং তারা বলবে, কোন বাধা যদি তা আটকে রাখত।', 'Yawma yarawna almalaikata la bushra yawmaithin lilmujrimeena wayaqooloona hijran mahjooran', 1, NOW(), NOW()),
(30, 23, 'وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا', 'আমি তাদের কৃতকর্মের প্রতি মনোনিবেশ করব, অতঃপর সেগুলোকে বিক্ষিপ্ত ধুলিকণারূপে করে দেব।', 'Waqadimna ila ma AAamiloo min AAamalin fajaAAalnahu habaan manthooran', 1, NOW(), NOW()),
(30, 24, 'أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرٞ مُّسۡتَقَرّٗا وَأَحۡسَنُ مَقِيلٗا', 'সেদিন জান্নাতীদের বাসস্থান হবে উত্তম এবং বিশ্রামস্থল হবে মনোরম।', 'Ashabu aljannati yawmaithin khayrun mustaqarran waahsanu maqeelan', 1, NOW(), NOW()),
(30, 25, 'وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَٰمِ وَنُزِّلَ ٱلۡمَلَـٰٓئِكَةُ تَنزِيلًا', 'সেদিন আকাশ মেঘমালাসহ বিদীর্ণ হবে এবং সেদিন ফেরেশতাদের নামিয়ে দেয়া হবে', 'Wayawma tashaqqaqu alssamao bialghamami wanuzzila almalaikatu tanzeelan', 1, NOW(), NOW()),
(30, 26, 'ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ وَكَانَ يَوۡمًا عَلَى ٱلۡكَٰفِرِينَ عَسِيرٗا', 'সেদিন সত্যিকার রাজত্ব হবে দয়াময় আল্লাহর এবং কাফেরদের পক্ষে দিনটি হবে কঠিন।', 'Almulku yawmaithin alhaqqu lilrrahmani wakana yawman AAala alkafireena AAaseeran', 1, NOW(), NOW()),
(30, 27, 'وَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا', 'জালেম সেদিন আপন হস্তদ্বয় দংশন করতে করতে বলবে, হায় আফসোস! আমি যদি রসূলের সাথে পথ অবলম্বন করতাম।', 'Wayawma yaAAaddu alththalimu AAala yadayhi yaqoolu ya laytanee ittakhathtu maAAa alrrasooli sabeelan', 1, NOW(), NOW()),
(30, 28, 'يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا', 'হায় আমার দূর্ভাগ্য, আমি যদি অমুককে বন্ধুরূপে গ্রহণ না করতাম।', 'Ya waylata laytanee lam attakhith fulanan khaleelan', 1, NOW(), NOW()),
(30, 29, 'لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا', 'আমার কাছে উপদেশ আসার পর সে আমাকে তা থেকে বিভ্রান্ত করেছিল। শয়তান মানুষকে বিপদকালে ধোঁকা দেয়।', 'Laqad adallanee AAani alththikri baAAda ith jaanee wakana alshshaytanu lilinsani khathoolan', 1, NOW(), NOW()),
(30, 30, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورٗا', 'রসূল বললেনঃ হে আমার পালনকর্তা, আমার সম্প্রদায় এই কোরআনকে প্রলাপ সাব্যস্ত করেছে।', 'Waqala alrrasoolu ya rabbi inna qawmee ittakhathoo hatha alqurana mahjooran', 1, NOW(), NOW()),
(30, 31, 'وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا', 'এমনিভাবে প্রত্যেক নবীর জন্যে আমি অপরাধীদের মধ্য থেকে শত্রু করেছি। আপনার জন্যে আপনার পালনকর্তা পথপ্রদর্শক ও সাহায্যকারীরূপে যথেষ্ট।', 'Wakathalika jaAAalna likulli nabiyyin AAaduwwan mina almujrimeena wakafa birabbika hadiyan wanaseeran', 1, NOW(), NOW()),
(30, 32, 'وَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا', 'সত্য প্রত্যাখানকারীরা বলে, তাঁর প্রতি সমগ্র কোরআন একদফায় অবতীর্ণ হল না কেন? আমি এমনিভাবে অবতীর্ণ করেছি এবং ক্রমে ক্রমে আবৃত্তি করেছি আপনার অন্তকরণকে মজবুত করার জন্যে।', 'Waqala allatheena kafaroo lawla nuzzila AAalayhi alquranu jumlatan wahidatan kathalika linuthabbita bihi fuadaka warattalnahu tarteelan', 1, NOW(), NOW()),
(30, 33, 'وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا', 'তারা আপনার কাছে কোন সমস্যা উপস্থাপিত করলেই আমি আপনাকে তার সঠিক জওয়াব ও সুন্দর ব্যাখ্যা দান করি।', 'Wala yatoonaka bimathalin illa jinaka bialhaqqi waahsana tafseeran', 1, NOW(), NOW()),
(30, 34, 'ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا', 'যাদেরকে মুখ থুবড়ে পড়ে থাকা অবস্থায় জাহান্নামের দিকে একত্রিত করা হবে, তাদেরই স্থান হবে নিকৃষ্ট এবং তারাই পথভ্রষ্ট।', 'Allatheena yuhsharoona AAala wujoohihim ila jahannama olaika sharrun makanan waadallu sabeelan', 1, NOW(), NOW()),
(30, 35, 'وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرٗا', 'আমি তো মূসাকে কিতাব দিয়েছি এবং তাঁর সাথে তাঁর ভ্রাতা হারুনকে সাহায্যকারী করেছি।', 'Walaqad atayna moosa alkitaba wajaAAalna maAAahu akhahu haroona wazeeran', 1, NOW(), NOW()),
(30, 36, 'فَقُلۡنَا ٱذۡهَبَآ إِلَى ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا فَدَمَّرۡنَٰهُمۡ تَدۡمِيرٗا', 'অতঃপর আমি বলেছি, তোমরা সেই সম্প্রদায়ের কাছে যাও, যারা আমার আয়াতসমূহকে মিথ্যা অভিহিত করেছে। অতঃপর আমি তাদেরকে সমূলে ধ্বংস করে দিয়েছি।', 'Faqulna ithhaba ila alqawmi allatheena kaththaboo biayatina fadammarnahum tadmeeran', 1, NOW(), NOW()),
(30, 37, 'وَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّـٰلِمِينَ عَذَابًا أَلِيمٗا', 'নূহের সম্প্রদায় যখন রসূলগণের প্রতি মিথ্যারোপ করল, তখন আমি তাদেরকে নিমজ্জত করলাম এবং তাদেরকে মানবমন্ডলীর জন্যে নিদর্শন করে দিলাম। জালেমদের জন্যে আমি যন্ত্রণাদায়ক শাস্তি প্রস্তুত করে রেখেছি।', 'Waqawma noohin lamma kaththaboo alrrusula aghraqnahum wajaAAalnahum lilnnasi ayatan waaAAtadna lilththalimeena AAathaban aleeman', 1, NOW(), NOW()),
(30, 38, 'وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا', 'আমি ধ্বংস করেছি আদ, সামুদ, কপবাসী এবং তাদের মধ্যবর্তী অনেক সম্প্রদায়কে।', 'WaAAadan wathamooda waashaba alrrassi waquroonan bayna thalika katheeran', 1, NOW(), NOW()),
(30, 39, 'وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا', 'আমি প্রত্যেকের জন্যেই দৃষ্টান্ত বর্ণনা করেছি এবং প্রত্যেককেই সম্পুর্ণরূপে ধ্বংস করেছি।', 'Wakullan darabna lahu alamthala wakullan tabbarna tatbeeran', 1, NOW(), NOW()),
(30, 40, 'وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا', 'তারা তো সেই জনপদের উপর দিয়েই যাতায়াত করে, যার ওপর বর্ষিত হয়েছে মন্দ বৃষ্টি। তবে কি তারা তা প্রত্যক্ষ করে না? বরং তারা পুনরুজ্জীবনের আশঙ্কা করে না।', 'Walaqad ataw AAala alqaryati allatee omtirat matara alssawi afalam yakoonoo yarawnaha bal kanoo la yarjoona nushooran', 1, NOW(), NOW()),
(30, 41, 'وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا', 'তারা যখন আপনাকে দেখে, তখন আপনাকে কেবল বিদ্রুপের পাত্ররূপে গ্রহণ করে, বলে, এ-ই কি সে যাকে আল্লাহ ‘রসূল’ করে প্রেরণ করেছেন', 'Waitha raawka in yattakhithoonaka illa huzuwan ahatha allathee baAAatha Allahu rasoolan', 1, NOW(), NOW()),
(30, 42, 'إِن كَادَ لَيُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَآ أَن صَبَرۡنَا عَلَيۡهَاۚ وَسَوۡفَ يَعۡلَمُونَ حِينَ يَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِيلًا', 'সে তো আমাদেরকে আমাদের উপাস্যগণের কাছ থেকে সরিয়েই দিত, যদি আমরা তাদেরকে আঁকড়ে ধরে না থাকতাম। তারা যখন শাস্তি প্রত্যক্ষ করবে, তখন জানতে পারবে কে অধিক পথভ্রষ্ট।', 'In kada layudilluna AAan alihatina lawla an sabarna AAalayha wasawfa yaAAlamoona heena yarawna alAAathaba man adallu sabeelan', 1, NOW(), NOW()),
(30, 43, 'أَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا', 'আপনি কি তাকে দেখেন না, যে তারা প্রবৃত্তিকে উপাস্যরূপে গ্রহণ করে? তবুও কি আপনি তার যিম্মাদার হবেন', 'Araayta mani ittakhatha ilahahu hawahu afaanta takoonu AAalayhi wakeelan', 1, NOW(), NOW()),
(30, 44, 'أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا', 'আপনি কি মনে করেন যে, তাদের অধিকাংশ শোনে অথবা বোঝে ? তারা তো চতুস্পদ জন্তুর মত; বরং আরও পথভ্রান্ত', 'Am tahsabu anna aktharahum yasmaAAoona aw yaAAqiloona in hum illa kaalanAAami bal hum adallu sabeelan', 1, NOW(), NOW()),
(30, 45, 'أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا', 'তুমি কি তোমার পালনকর্তাকে দেখ না, তিনি কিভাবে ছায়াকে বিলম্বিত করেন? তিনি ইচ্ছা করলে একে স্থির রাখতে পারতেন। এরপর আমি সূর্যকে করেছি এর নির্দেশক।', 'Alam tara ila rabbika kayfa madda alththilla walaw shaa lajaAAalahu sakinan thumma jaAAalna alshshamsa AAalayhi daleelan', 1, NOW(), NOW()),
(30, 46, 'ثُمَّ قَبَضۡنَٰهُ إِلَيۡنَا قَبۡضٗا يَسِيرٗا', 'অতঃপর আমি একে নিজের দিকে ধীরে ধীরে গুটিয়ে আনি।', 'Thumma qabadnahu ilayna qabdan yaseeran', 1, NOW(), NOW()),
(30, 47, 'وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِبَاسٗا وَٱلنَّوۡمَ سُبَاتٗا وَجَعَلَ ٱلنَّهَارَ نُشُورٗا', 'তিনিই তো তোমাদের জন্যে রাত্রিকে করেছেন আবরণ, নিদ্রাকে বিশ্রাম এবং দিনকে করেছেন বাইরে গমনের জন্যে।', 'Wahuwa allathee jaAAala lakumu allayla libasan waalnnawma subatan wajaAAala alnnahara nushooran', 1, NOW(), NOW()),
(30, 48, 'وَهُوَ ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ طَهُورٗا', 'তিনিই স্বীয় রহমতের প্রাক্কালে বাতাসকে সুসংবাদবাহীরূপে প্রেরণ করেন। এবং আমি আকাশ থেকে পবিত্রতা অর্জনের জন্যে পানি বর্ষণ করি।', 'Wahuwa allathee arsala alrriyaha bushran bayna yaday rahmatihi waanzalna mina alssamai maan tahooran', 1, NOW(), NOW()),
(30, 49, 'لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةٗ مَّيۡتٗا وَنُسۡقِيَهُۥ مِمَّا خَلَقۡنَآ أَنۡعَٰمٗا وَأَنَاسِيَّ كَثِيرٗا', 'তদ্দ্বারা মৃত ভূভাগকে সঞ্জীবিত করার জন্যে এবং আমার সৃষ্ট জীবজন্তু ও অনেক মানুষের তৃষ্ণা নিবারণের জন্যে।', 'Linuhyiya bihi baldatan maytan wanusqiyahu mimma khalaqna anAAaman waanasiyya katheeran', 1, NOW(), NOW()),
(30, 50, 'وَلَقَدۡ صَرَّفۡنَٰهُ بَيۡنَهُمۡ لِيَذَّكَّرُواْ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا', 'এবং আমি তা তাদের মধ্যে বিভিন্নভাবে বিতরণ করি, যাতে তারা স্মরণ করে। কিন্তু অধিকাংশ লোক অকৃতজ্ঞতা ছাড়া কিছুই করে না।', 'Walaqad sarrafnahu baynahum liyaththakkaroo faaba aktharu alnnasi illa kufooran', 1, NOW(), NOW()),
(30, 51, 'وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا', 'আমি ইচ্ছা করলে প্রত্যেক জনপদে একজন ভয় প্রদর্শনকারী প্রেরণ করতে পারতাম।', 'Walaw shina labaAAathna fee kulli qaryatin natheeran', 1, NOW(), NOW()),
(30, 52, 'فَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا', 'অতএব আপনি কাফেরদের আনুগত্য করবেন না এবং তাদের সাথে এর সাহায্যে কঠোর সংগ্রাম করুন।', 'Fala tutiAAi alkafireena wajahidhum bihi jihadan kabeeran', 1, NOW(), NOW()),
(30, 53, '۞وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا عَذۡبٞ فُرَاتٞ وَهَٰذَا مِلۡحٌ أُجَاجٞ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخٗا وَحِجۡرٗا مَّحۡجُورٗا', 'তিনিই সমান্তরালে দুই সমুদ্র প্রবাহিত করেছেন, এটি মিষ্ট, তৃষ্ণা নিবারক ও এটি লোনা, বিস্বাদ; উভয়ের মাঝখানে রেখেছেন একটি অন্তরায়, একটি দুর্ভেদ্য আড়াল।', 'Wahuwa allathee maraja albahrayni hatha AAathbun furatun wahatha milhun ojajun wajaAAala baynahuma barzakhan wahijran mahjooran', 1, NOW(), NOW()),
(30, 54, 'وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرٗا فَجَعَلَهُۥ نَسَبٗا وَصِهۡرٗاۗ وَكَانَ رَبُّكَ قَدِيرٗا', 'তিনিই পানি থেকে সৃষ্টি করেছেন মানবকে, অতঃপর তাকে রক্তগত, বংশ ও বৈবাহিক সম্পর্কশীল করেছেন। তোমার পালনকর্তা সবকিছু করতে সক্ষম।', 'Wahuwa allathee khalaqa mina almai basharan fajaAAalahu nasaban wasihran wakana rabbuka qadeeran', 1, NOW(), NOW()),
(30, 55, 'وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا', 'তারা এবাদত করে আল্লাহর পরিবর্তে এমন কিছুর, যা তাদের উপকার করতে পারে না এবং ক্ষতিও করতে পারে না। কাফের তো তার পালনকর্তার প্রতি পৃষ্ঠপ্রদর্শনকারী।', 'WayaAAbudoona min dooni Allahi ma la yanfaAAuhum wala yadurruhum wakana alkafiru AAala rabbihi thaheeran', 1, NOW(), NOW()),
(30, 56, 'وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا', 'আমি আপনাকে সুসংবাদ ও সতর্ককারীরূপেই প্রেরণ করেছি।', 'Wama arsalnaka illa mubashshiran wanatheeran', 1, NOW(), NOW()),
(30, 57, 'قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا', 'বলুন, আমি তোমাদের কাছে এর কোন বিনিময় চাই না, কিন্তু যে ইচ্ছা করে, সে তার পালনকর্তার পথ অবলম্বন করুক।', 'Qul ma asalukum AAalayhi min ajrin illa man shaa an yattakhitha ila rabbihi sabeelan', 1, NOW(), NOW()),
(30, 58, 'وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'আপনি সেই চিরঞ্জীবের উপর ভরসা করুন, যার মৃত্যু নেই এবং তাঁর প্রশংসাসহ পবিত্রতা ঘোষণা করুন। তিনি বান্দার গোনাহ সম্পর্কে যথেষ্ট খবরদার।', 'Watawakkal AAala alhayyi allathee la yamootu wasabbih bihamdihi wakafa bihi bithunoobi AAibadihi khabeeran', 1, NOW(), NOW()),
(30, 59, 'ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ فَسۡـَٔلۡ بِهِۦ خَبِيرٗا', 'তিনি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের অন্তর্বর্তী সবকিছু ছয়দিনে সৃস্টি করেছেন, অতঃপর আরশে সমাসীন হয়েছেন। তিনি পরম দয়াময়। তাঁর সম্পর্কে যিনি অবগত, তাকে জিজ্ঞেস কর।', 'Allathee khalaqa alssamawati waalarda wama baynahuma fee sittati ayyamin thumma istawa AAala alAAarshi alrrahmanu faisal bihi khabeeran', 1, NOW(), NOW()),
(30, 60, 'وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩', 'তাদেরকে যখন বলা হয়, দয়াময়কে সেজদা কর, তখন তারা বলে, দয়াময় আবার কে? তুমি কাউকে সেজদা করার আদেশ করলেই কি আমরা সেজদা করব? এতে তাদের পলায়নপরতাই বৃদ্ধি পায়।', 'Waitha qeela lahumu osjudoo lilrrahmani qaloo wama alrrahmanu anasjudu lima tamuruna wazadahum nufooran', 1, NOW(), NOW()),
(30, 61, 'تَبَارَكَ ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجٗا وَجَعَلَ فِيهَا سِرَٰجٗا وَقَمَرٗا مُّنِيرٗا', 'কল্যাণময় তিনি, যিনি নভোমন্ডলে রাশিচক্র সৃষ্টি করেছেন এবং তাতে রেখেছেন সূর্য ও দীপ্তিময় চন্দ্র।', 'Tabaraka allathee jaAAala fee alssamai buroojan wajaAAala feeha sirajan waqamaran muneeran', 1, NOW(), NOW()),
(30, 62, 'وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا', 'যারা অনুসন্ধানপ্রিয় অথবা যারা কৃতজ্ঞতাপ্রিয় তাদের জন্যে তিনি রাত্রি ও দিবস সৃষ্টি করেছেন পরিবর্তনশীলরূপে।', 'Wahuwa allathee jaAAala allayla waalnnahara khilfatan liman arada an yaththakkara aw arada shukooran', 1, NOW(), NOW()),
(30, 63, 'وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا', 'রহমান-এর বান্দা তারাই, যারা পৃথিবীতে নম্রভাবে চলাফেরা করে এবং তাদের সাথে যখন মুর্খরা কথা বলতে থাকে, তখন তারা বলে, সালাম।', 'WaAAibadu alrrahmani allatheena yamshoona AAala alardi hawnan waitha khatabahumu aljahiloona qaloo salaman', 1, NOW(), NOW()),
(30, 64, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا', 'এবং যারা রাত্রি যাপন করে পালনকর্তার উদ্দেশ্যে সেজদাবনত হয়ে ও দন্ডায়মান হয়ে', 'Waallatheena yabeetoona lirabbihim sujjadan waqiyaman', 1, NOW(), NOW()),
(30, 65, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'এবং যারা বলে, হে আমার পালনকর্তা, আমাদের কাছথেকে জাহান্নামের শাস্তি হটিয়ে দাও। নিশ্চয় এর শাস্তি নিশ্চিত বিনাশ', 'Waallatheena yaqooloona rabbana isrif AAanna AAathaba jahannama inna AAathabaha kana gharaman', 1, NOW(), NOW()),
(30, 66, 'إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا', 'বসবাস ও অবস্থানস্থল হিসেবে তা কত নিকৃষ্ট জায়গা।', 'Innaha saat mustaqarran wamuqaman', 1, NOW(), NOW()),
(30, 67, 'وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا', 'এবং তারা যখন ব্যয় করে, তখন অযথা ব্যয় করে না কৃপণতাও করে না এবং তাদের পন্থা হয় এতদুভয়ের মধ্যবর্তী।', 'Waallatheena itha anfaqoo lam yusrifoo walam yaqturoo wakana bayna thalika qawaman', 1, NOW(), NOW()),
(30, 68, 'وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا', 'এবং যারা আল্লাহর সাথে অন্য উপাস্যের এবাদত করে না, আল্লাহ যার হত্যা অবৈধ করেছেন, সঙ্গত কারণ ব্যতীত তাকে হত্যা করে না এবং ব্যভিচার করে না। যারা একাজ করে, তারা শাস্তির সম্মুখীন হবে।', 'Waallatheena la yadAAoona maAAa Allahi ilahan akhara wala yaqtuloona alnnafsa allatee harrama Allahu illa bialhaqqi wala yaznoona waman yafAAal thalika yalqa athaman', 1, NOW(), NOW()),
(30, 69, 'يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا', 'কেয়ামতের দিন তাদের শাস্তি দ্বিগুন হবে এবং তথায় লাঞ্ছিত অবস্থায় চিরকাল বসবাস করবে।', 'YudaAAaf lahu alAAathabu yawma alqiyamati wayakhlud feehi muhanan', 1, NOW(), NOW()),
(30, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا', 'কিন্তু যারা তওবা করে বিশ্বাস স্থাপন করে এবং সৎকর্ম করে, আল্লাহ তাদের গোনাহকে পুন্য দ্বারা পরিবর্তত করে এবং দেবেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।', 'Illa man taba waamana waAAamila AAamalan salihan faolaika yubaddilu Allahu sayyiatihim hasanatin wakana Allahu ghafooran raheeman', 1, NOW(), NOW()),
(30, 71, 'وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا', 'যে তওবা করে ও সৎকর্ম করে, সে ফিরে আসার স্থান আল্লাহর দিকে ফিরে আসে।', 'Waman taba waAAamila salihan fainnahu yatoobu ila Allahi mataban', 1, NOW(), NOW()),
(30, 72, 'وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا', 'এবং যারা মিথ্যা কাজে যোগদান করে না এবং যখন অসার ক্রিয়াকর্মের সম্মুখীন হয়, তখন মান রক্ষার্থে ভদ্রভাবে চলে যায়।', 'Waallatheena la yashhadoona alzzoora waitha marroo biallaghwi marroo kiraman', 1, NOW(), NOW()),
(30, 73, 'وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا', 'এবং যাদেরকে তাদের পালনকর্তার আয়াতসমূহ বোঝানো হলে তাতে অন্ধ ও বধির সদৃশ আচরণ করে না।', 'Waallatheena itha thukkiroo biayati rabbihim lam yakhirroo AAalayha summan waAAumyanan', 1, NOW(), NOW()),
(30, 74, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا', 'এবং যারা বলে, হে আমাদের পালনকর্তা, আমাদের স্ত্রীদের পক্ষ থেকে এবং আমাদের সন্তানের পক্ষ থেকে আমাদের জন্যে চোখের শীতলতা দান কর এবং আমাদেরকে মুত্তাকীদের জন্যে আদর্শস্বরূপ কর।', 'Waallatheena yaqooloona rabbana hab lana min azwajina wathurriyyatina qurrata aAAyunin waijAAalna lilmuttaqeena imaman', 1, NOW(), NOW()),
(30, 75, 'أُوْلَـٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا', 'তাদেরকে তাদের সবরের প্রতিদানে জান্নাতে কক্ষ দেয়া হবে এবং তাদেরকে তথায় দোয়া ও সালাম সহকারে অভ্যর্থনা করা হবে।', 'Olaika yujzawna alghurfata bima sabaroo wayulaqqawna feeha tahiyyatan wasalaman', 1, NOW(), NOW()),
(30, 76, 'خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا', 'তথায় তারা চিরকাল বসবাস করবে। অবস্থানস্থল ও বাসস্থান হিসেবে তা কত উত্তম।', 'Khalideena feeha hasunat mustaqarran wamuqaman', 1, NOW(), NOW()),
(30, 77, 'قُلۡ مَا يَعۡبَؤُاْ بِكُمۡ رَبِّي لَوۡلَا دُعَآؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا', 'বলুন, আমার পালনকর্তা পরওয়া করেন না যদি তোমরা তাঁকে না ডাক। তোমরা মিথ্যা বলেছ। অতএব সত্বর নেমে আসবে অনিবার্য শাস্তি।', 'Qul ma yaAAbao bikum rabbee lawla duAAaokum faqad kaththabtum fasawfa yakoonu lizaman', 1, NOW(), NOW()),
(31, 1, 'طسٓمٓ', 'ত্বা, সীন, মীম।', 'Taseenmeem', 1, NOW(), NOW()),
(31, 2, 'تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ', 'এগুলো সুস্পষ্ট কিতাবের আয়াত।', 'Tilka ayatu alkitabi almubeeni', 1, NOW(), NOW()),
(31, 3, 'لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ', 'তারা বিশ্বাস করে না বলে আপনি হয়তো মর্মব্যথায় আত্নঘাতী হবেন।', 'LaAAallaka bakhiAAun nafsaka alla yakoonoo mumineena', 1, NOW(), NOW()),
(31, 4, 'إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ', 'আমি যদি ইচ্ছা করি, তবে আকাশ থেকে তাদের কাছে কোন নিদর্শন নাযিল করতে পারি। অতঃপর তারা এর সামনে নত হয়ে যাবে।', 'In nasha nunazzil AAalayhim mina alssamai ayatan fathallat aAAnaquhum laha khadiAAeena', 1, NOW(), NOW()),
(31, 5, 'وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ', 'যখনই তাদের কাছে রহমান এর কোন নতুন উপদেশ আসে, তখনই তারা তা থেকে মুখ ফিরিয়ে নেয়।', 'Wama yateehim min thikrin mina alrrahmani muhdathin illa kanoo AAanhu muAArideena', 1, NOW(), NOW()),
(31, 6, 'فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَـٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ', 'অতএব তারা তো মিথ্যারোপ করেছেই; সুতরাং যে বিষয় নিয়ে তারা ঠাট্টা-বিদ্রুপ করত, তার যথার্থ স্বরূপ শীঘ্রই তাদের কাছে পৌছবে।', 'Faqad kaththaboo fasayateehim anbao ma kanoo bihi yastahzioona', 1, NOW(), NOW()),
(31, 7, 'أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ', 'তারা কি ভুপৃষ্ঠের প্রতি দৃষ্টিপাত করে না? আমি তাতে সর্বপ্রকার বিশেষ-বস্তু কত উদগত করেছি।', 'Awalam yaraw ila alardi kam anbatna feeha min kulli zawjin kareemin', 1, NOW(), NOW()),
(31, 8, 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', 'নিশ্চয় এতে নিদর্শন আছে, কিন্তু তাদের অধিকাংশই বিশ্বাসী নয়।', 'Inna fee thalika laayatan wama kana aktharuhum mumineena', 1, NOW(), NOW()),
(31, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', 'আপনার পালনকর্তা তো পরাক্রমশালী পরম দয়ালু।', 'Wainna rabbaka lahuwa alAAazeezu alrraheemu', 1, NOW(), NOW()),
(31, 10, 'وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ', 'যখন আপনার পালনকর্তা মূসাকে ডেকে বললেনঃ তুমি পাপিষ্ঠ সম্প্রদায়ের নিকট যাও', 'Waith nada rabbuka moosa ani iti alqawma alththalimeena', 1, NOW(), NOW()),
(31, 11, 'قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ', 'ফেরাউনের সম্প্রদায়ের নিকট; তারা কি ভয় করে না', 'Qawma firAAawna ala yattaqoona', 1, NOW(), NOW()),
(31, 12, 'قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ', 'সে বলল, হে আমার পালনকর্তা, আমার আশংকা হচ্ছে যে, তারা আমাকে মিথ্যাবাদী বলে দেবে।', 'Qala rabbi innee akhafu an yukaththibooni', 1, NOW(), NOW()),
(31, 13, 'وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ', 'এবং আমার মন হতবল হয়ে পড়ে এবং আমার জিহবা অচল হয়ে যায়। সুতরাং হারুনের কাছে বার্তা প্রেরণ করুন।', 'Wayadeequ sadree wala yantaliqu lisanee faarsil ila haroona', 1, NOW(), NOW()),
(31, 14, 'وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ', 'আমার বিরুদ্ধে তাদের অভিযোগ আছে। অতএব আমি আশংকা করি যে, তারা আমাকে হত্যা করবে।', 'Walahum AAalayya thanbun faakhafu an yaqtulooni', 1, NOW(), NOW()),
(31, 15, 'قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ', 'আল্লাহ বলেন, কখনই নয় তোমরা উভয়ে যাও আমার নিদর্শনাবলী নিয়ে। আমি তোমাদের সাথে থেকে শোনব।', 'Qala kalla faithhaba biayatina inna maAAakum mustamiAAoona', 1, NOW(), NOW()),
(31, 16, 'فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ', 'অতএব তোমরা ফেরআউনের কাছে যাও এবং বল, আমরা বিশ্বজগতের পালনকর্তার রসূল।', 'Fatiya firAAawna faqoola inna rasoolu rabbi alAAalameena', 1, NOW(), NOW()),
(31, 17, 'أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَـٰٓءِيلَ', 'যাতে তুমি বনী-ইসরাঈলকে আমাদের সাথে যেতে দাও।', 'An arsil maAAana banee israeela', 1, NOW(), NOW()),
(31, 18, 'قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ', 'ফেরাউন বলল, আমরা কি তোমাকে শিশু অবস্থায় আমাদের মধ্যে লালন-পালন করিনি? এবং তুমি আমাদের মধ্যে জীবনের বহু বছর কাটিয়েছ।', 'Qala alam nurabbika feena waleedan walabithta feena min AAumurika sineena', 1, NOW(), NOW()),
(31, 19, 'وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ', 'তুমি সেই-তোমরা অপরাধ যা করবার করেছ। তুমি হলে কৃতঘ্ন।', 'WafaAAalta faAAlataka allatee faAAalta waanta mina alkafireena', 1, NOW(), NOW()),
(31, 20, 'قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'মূসা বলল, আমি সে অপরাধ তখন করেছি, যখন আমি ভ্রান্ত ছিলাম।', 'Qala faAAaltuha ithan waana mina alddalleena', 1, NOW(), NOW()),
(31, 21, 'فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ', 'অতঃপর আমি ভীত হয়ে তোমাদের কাছ থেকে পলায়ন করলাম। এরপর আমার পালনকর্তা আমাকে প্রজ্ঞা দান করেছেন এবং আমাকে পয়গম্বর করেছেন।', 'Fafarartu minkum lamma khiftukum fawahaba lee rabbee hukman wajaAAalanee mina almursaleena', 1, NOW(), NOW()),
(31, 22, 'وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَـٰٓءِيلَ', 'আমার প্রতি তোমার যে অনুগ্রহের কথা বলছ, তা এই যে, তুমি বনী-ইসলাঈলকে গোলাম বানিয়ে রেখেছ।', 'Watilka niAAmatun tamunnuha AAalayya an AAabbadta banee israeela', 1, NOW(), NOW()),
(31, 23, 'قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ', 'ফেরাউন বলল, বিশ্বজগতের পালনকর্তা আবার কি', 'Qala firAAawnu wama rabbu alAAalameena', 1, NOW(), NOW()),
(31, 24, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ', 'মূসা বলল, তিনি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছুর পালনকর্তা যদি তোমরা বিশ্বাসী হও।', 'Qala rabbu alssamawati waalardi wama baynahuma in kuntum mooqineena', 1, NOW(), NOW()),
(31, 25, 'قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ', 'ফেরাউন তার পরিষদবর্গকে বলল, তোমরা কি শুনছ না', 'Qala liman hawlahu ala tastamiAAoona', 1, NOW(), NOW()),
(31, 26, 'قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ', 'মূসা বলল, তিনি তোমাদের পালনকর্তা এবং তোমাদের পূর্ববর্তীদেরও পালনকর্তা।', 'Qala rabbukum warabbu abaikumu alawwaleena', 1, NOW(), NOW()),
(31, 27, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ', 'ফেরাউন বলল, তোমাদের প্রতি প্রেরিত তোমাদের রসূলটি নিশ্চয়ই বদ্ধ পাগল।', 'Qala inna rasoolakumu allathee orsila ilaykum lamajnoonun', 1, NOW(), NOW()),
(31, 28, 'قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ', 'মূসা বলল, তিনি পূর্ব, পশ্চিম ও এতদুভয়ের মধ্যবর্তী সব কিছুর পালনকর্তা, যদি তোমরা বোঝ।', 'Qala rabbu almashriqi waalmaghribi wama baynahuma in kuntum taAAqiloona', 1, NOW(), NOW()),
(31, 29, 'قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ', 'ফেরাউন বলল, তুমি যদি আমার পরিবর্তে অন্যকে উপাস্যরূপে গ্রহণ কর তবে আমি অবশ্যই তোমাকে কারাগারে নিক্ষেপ করব।', 'Qala laini ittakhathta ilahan ghayree laajAAalannaka mina almasjooneena', 1, NOW(), NOW()),
(31, 30, 'قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ', 'মূসা বলল, আমি তোমার কাছে কোন স্পষ্ট বিষয় নিয়ে আগমন করলেও কি', 'Qala awalaw jituka bishayin mubeenin', 1, NOW(), NOW()),
(31, 31, 'قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ', 'ফেরাউন বলল, তুমি সত্যবাদী হলে তা উপস্থিত কর।', 'Qala fati bihi in kunta mina alssadiqeena', 1, NOW(), NOW()),
(31, 32, 'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ', 'অতঃপর তিনি লাঠি নিক্ষেপ করলে মুহূর্তের মধ্যে তা সুস্পষ্ট অজগর হয়ে গেল।', 'Faalqa AAasahu faitha hiya thuAAbanun mubeenun', 1, NOW(), NOW()),
(31, 33, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّـٰظِرِينَ', 'আর তিনি তার হাত বের করলেন, তৎক্ষণাৎ তা দর্শকদের কাছে সুশুভ্র প্রতিভাত হলো।', 'WanazaAAa yadahu faitha hiya baydao lilnnathireena', 1, NOW(), NOW()),
(31, 34, 'قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ', 'ফেরাউন তার পরিষদবর্গকে বলল, নিশ্চয় এ একজন সুদক্ষ জাদুকর।', 'Qala lilmalai hawlahu inna hatha lasahirun AAaleemun', 1, NOW(), NOW()),
(31, 35, 'يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ', 'সে তার জাদু বলে তোমাদেরকে তোমাদের দেশ থেকে বহিস্কার করতে চায়। অতএব তোমাদের মত কি', 'Yureedu an yukhrijakum min ardikum bisihrihi famatha tamuroona', 1, NOW(), NOW()),
(31, 36, 'قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ', 'তারা বলল, তাকে ও তার ভাইকে কিছু অবকাশ দিন এবং শহরে শহরে ঘোষক প্রেরণ করুন।', 'Qaloo arjih waakhahu waibAAath fee almadaini hashireena', 1, NOW(), NOW()),
(31, 37, 'يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ', 'তারা যেন আপনার কাছে প্রত্যেকটি দক্ষ জাদুকর কে উপস্থিত করে।', 'Yatooka bikulli sahharin AAaleemin', 1, NOW(), NOW()),
(31, 38, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ', 'অতঃপর এক নির্দিষ্ট দিনে জাদুকরদেরকে একত্রিত করা হল।', 'FajumiAAa alssaharatu limeeqati yawmin maAAloomin', 1, NOW(), NOW()),
(31, 39, 'وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ', 'এবং জনগণের মধ্যে ঘোষণা করা হল, তোমরাও সমবেত হও।', 'Waqeela lilnnasi hal antum mujtamiAAoona', 1, NOW(), NOW()),
(31, 40, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ', 'যাতে আমরা জাদুকরদের অনুসরণ করতে পারি-যদি তারাই বিজয়ী হয়।', 'LaAAallana nattabiAAu alssaharata in kanoo humu alghalibeena', 1, NOW(), NOW()),
(31, 41, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ', 'যখন যাদুকররা আগমণ করল, তখন ফেরআউনকে বলল, যদি আমরা বিজয়ী হই, তবে আমরা পুরস্কার পাব তো', 'Falamma jaa alssaharatu qaloo lifirAAawna ainna lana laajran in kunna nahnu alghalibeena', 1, NOW(), NOW()),
(31, 42, 'قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ', 'ফেরাউন বলল, হঁ্যা এবং তখন তোমরা আমার নৈকট্যশীলদের অন্তর্ভুক্ত হবে।', 'Qala naAAam wainnakum ithan lamina almuqarrabeena', 1, NOW(), NOW()),
(31, 43, 'قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ', 'মূসা (আঃ) তাদেরকে বললেন, নিক্ষেপ কর তোমরা যা নিক্ষেপ করবে।', 'Qala lahum moosa alqoo ma antum mulqoona', 1, NOW(), NOW()),
(31, 44, 'فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ', 'অতঃপর তারা তাদের রশি ও লাঠি নিক্ষেপ করল এবং বলল, ফেরাউনের ইযযতের কসম, আমরাই বিজয়ী হব।', 'Faalqaw hibalahum waAAisiyyahum waqaloo biAAizzati firAAawna inna lanahnu alghaliboona', 1, NOW(), NOW()),
(31, 45, 'فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ', 'অতঃপর মূসা তাঁর লাঠি নিক্ষেপ করল, হঠাৎ তা তাদের অলীক কীর্তিগুলোকে গ্রাস করতে লাগল।', 'Faalqa moosa AAasahu faitha hiya talqafu ma yafikoona', 1, NOW(), NOW()),
(31, 46, 'فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'তখন জাদুকররা সেজদায় নত হয়ে গেল।', 'Faolqiya alssaharatu sajideena', 1, NOW(), NOW()),
(31, 47, 'قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ', 'তারা বলল, আমরা রাব্বুল আলামীনের প্রতি বিশ্বাস স্থাপন করলাম।', 'Qaloo amanna birabbi alAAalameena', 1, NOW(), NOW()),
(31, 48, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'যিনি মূসা ও হারুনের রব।', 'Rabbi moosa waharoona', 1, NOW(), NOW()),
(31, 49, 'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ', 'ফেরাউন বলল, আমার অনুমতি দানের পূর্বেই তোমরা কি তাকে মেনে নিলে? নিশ্চয় সে তোমাদের প্রধান, যে তোমাদেরকে জাদু শিক্ষা দিয়েছে। শীঘ্রই তোমরা পরিণাম জানতে পারবে। আমি অবশ্যই তোমাদের হাত ও পা বিপরীত দিক থেকে কর্তন করব। এবং তোমাদের সবাইকে শূলে চড়াব।', 'Qala amantum lahu qabla an athana lakum innahu lakabeerukumu allathee AAallamakumu alssihra falasawfa taAAlamoona laoqattiAAanna aydiyakum waarjulakum min khilafin walaosallibannakum ajmaAAeena', 1, NOW(), NOW()),
(31, 50, 'قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'তারা বলল, কোন ক্ষতি নেই। আমরা আমাদের পালনকর্তার কাছে প্রত্যাবর্তন করব।', 'Qaloo la dayra inna ila rabbina munqaliboona', 1, NOW(), NOW()),
(31, 51, 'إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ', 'আমরা আশা করি, আমাদের পালনকর্তা আমাদের ক্রটি-বিচ্যুতি মার্জনা করবেন। কারণ, আমরা বিশ্বাস স্থাপনকারীদের মধ্যে অগ্রণী।', 'Inna natmaAAu an yaghfira lana rabbuna khatayana an kunna awwala almumineena', 1, NOW(), NOW()),
(31, 52, '۞وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ', 'আমি মূসাকে আদেশ করলাম যে, আমার বান্দাদেরকে নিয়ে রাত্রিযোগে বের হয়ে যাও, নিশ্চয় তোমাদের পশ্চাদ্ধাবন করা হবে।', 'Waawhayna ila moosa an asri biAAibadee innakum muttabaAAoona', 1, NOW(), NOW()),
(31, 53, 'فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ', 'অতঃপর ফেরাউন শহরে শহরে সংগ্রাহকদেরকে প্রেরণ করল', 'Faarsala firAAawnu fee almadaini hashireena', 1, NOW(), NOW()),
(31, 54, 'إِنَّ هَـٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ', 'নিশ্চয় এরা (বনী-ইসরাঈলরা) ক্ষুদ্র একটি দল।', 'Inna haolai lashirthimatun qaleeloona', 1, NOW(), NOW()),
(31, 55, 'وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ', 'এবং তারা আমাদের ক্রোধের উদ্রেক করেছে।', 'Wainnahum lana laghaithoona', 1, NOW(), NOW()),
(31, 56, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', 'এবং আমরা সবাই সদা শংকিত।', 'Wainna lajameeAAun hathiroona', 1, NOW(), NOW()),
(31, 57, 'فَأَخۡرَجۡنَٰهُم مِّن جَنَّـٰتٖ وَعُيُونٖ', 'অতঃপর আমি ফেরআউনের দলকে তাদের বাগ-বাগিচা ও ঝর্ণাসমূহ থেকে বহিষ্কার করলাম।', 'Faakhrajnahum min jannatin waAAuyoonin', 1, NOW(), NOW()),
(31, 58, 'وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ', 'এবং ধন-ভান্ডার ও মনোরম স্থানসমূহ থেকে।', 'Wakunoozin wamaqamin kareemin', 1, NOW(), NOW()),
(31, 59, 'كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَـٰٓءِيلَ', 'এরূপই হয়েছিল এবং বনী-ইসলাঈলকে করে দিলাম এসবের মালিক।', 'Kathalika waawrathnaha banee israeela', 1, NOW(), NOW()),
(31, 60, 'فَأَتۡبَعُوهُم مُّشۡرِقِينَ', 'অতঃপর সুর্যোদয়ের সময় তারা তাদের পশ্চাদ্ধাবন করল।', 'FaatbaAAoohum mushriqeena', 1, NOW(), NOW()),
(31, 61, 'فَلَمَّا تَرَـٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ', 'যখন উভয় দল পরস্পরকে দেখল, তখন মূসার সঙ্গীরা বলল, আমরা যে ধরা পড়ে গেলাম।', 'Falamma taraa aljamAAani qala ashabu moosa inna lamudrakoona', 1, NOW(), NOW()),
(31, 62, 'قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ', 'মূসা বলল, কখনই নয়, আমার সাথে আছেন আমার পালনকর্তা। তিনি আমাকে পথ বলে দেবেন।', 'Qala kalla inna maAAiya rabbee sayahdeeni', 1, NOW(), NOW()),
(31, 63, 'فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ', 'অতঃপর আমি মূসাকে আদেশ করলাম, তোমার লাঠি দ্বারা সমূদ্রকে আঘাত কর। ফলে, তা বিদীর্ণ হয়ে গেল এবং প্রত্যেক ভাগ বিশাল পর্বতসদৃশ হয়ে গেল।', 'Faawhayna ila moosa ani idrib biAAasaka albahra fainfalaqa fakana kullu firqin kaalttawdi alAAatheemi', 1, NOW(), NOW()),
(31, 64, 'وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ', 'আমি সেথায় অপর দলকে পৌঁছিয়ে দিলাম।', 'Waazlafna thamma alakhareena', 1, NOW(), NOW()),
(31, 65, 'وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ', 'এবং মূসা ও তাঁর সংগীদের সবাইকে বাঁচিয়ে দিলাম।', 'Waanjayna moosa waman maAAahu ajmaAAeena', 1, NOW(), NOW()),
(31, 66, 'ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ', 'অতঃপর অপর দলটিকে নিমজ্জত কললাম।', 'Thumma aghraqna alakhareena', 1, NOW(), NOW()),
(31, 67, 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', 'নিশ্চয় এতে একটি নিদর্শন আছে এবং তাদের অধিকাংশই বিশ্বাসী ছিল না।', 'Inna fee thalika laayatan wama kana aktharuhum mumineena', 1, NOW(), NOW()),
(31, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', 'আপনার পালনকর্তা অবশ্যই পরাক্রমশালী, পরম দয়ালু।', 'Wainna rabbaka lahuwa alAAazeezu alrraheemu', 1, NOW(), NOW());
INSERT INTO ayahs (`surah_id`, `number`, `text_ar`, `text_bn`, `transliteration`, `is_active`, `created_at`, `updated_at`) VALUES 
(31, 69, 'وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ', 'আর তাদেরকে ইব্রাহীমের বৃত্তান্ত শুনিয়ে দিন।', 'Waotlu AAalayhim nabaa ibraheema', 1, NOW(), NOW()),
(31, 70, 'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ', 'যখন তাঁর পিতাকে এবং তাঁর সম্প্রদায়কে বললেন, তোমরা কিসের এবাদত কর', 'Ith qala liabeehi waqawmihi ma taAAbudoona', 1, NOW(), NOW()),
(31, 71, 'قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ', 'তারা বলল, আমরা প্রতিমার পূজা করি এবং সারাদিন এদেরকেই নিষ্ঠার সাথে আঁকড়ে থাকি।', 'Qaloo naAAbudu asnaman fanathallu laha AAakifeena', 1, NOW(), NOW()),
(31, 72, 'قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ', 'ইব্রাহীম (আঃ) বললেন, তোমরা যখন আহবান কর, তখন তারা শোনে কি', 'Qala hal yasmaAAoonakum ith tadAAoona', 1, NOW(), NOW()),
(31, 73, 'أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ', 'অথবা তারা কি তোমাদের উপকার কিংবা ক্ষতি করতে পারে', 'Aw yanfaAAoonakum aw yadurroona', 1, NOW(), NOW()),
(31, 74, 'قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ', 'তারা বললঃ না, তবে আমরা আমাদের পিতৃপুরুষদেরকে পেয়েছি, তারা এরূপই করত।', 'Qaloo bal wajadna abaana kathalika yafAAaloona', 1, NOW(), NOW()),
(31, 75, 'قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ', 'ইব্রাহীম বললেন, তোমরা কি তাদের সম্পর্কে ভেবে দেখেছ, যাদের পূজা করে আসছ।', 'Qala afaraaytum ma kuntum taAAbudoona', 1, NOW(), NOW()),
(31, 76, 'أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ', 'তোমরা এবং তোমাদের পূর্ববর্তী পিতৃপুরুষেরা', 'Antum waabaokumu alaqdamoona', 1, NOW(), NOW()),
(31, 77, 'فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ', 'বিশ্বপালনকর্তা ব্যতীত তারা সবাই আমার শত্রু।', 'Fainnahum AAaduwwun lee illa rabba alAAalameena', 1, NOW(), NOW()),
(31, 78, 'ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ', 'যিনি আমাকে সৃষ্টি করেছেন, অতঃপর তিনিই আমাকে পথপ্রদর্শন করেন', 'Allathee khalaqanee fahuwa yahdeeni', 1, NOW(), NOW()),
(31, 79, 'وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ', 'যিনি আমাকে আহার এবং পানীয় দান করেন', 'Waallathee huwa yutAAimunee wayasqeeni', 1, NOW(), NOW()),
(31, 80, 'وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ', 'যখন আমি রোগাক্রান্ত হই, তখন তিনিই আরোগ্য দান করেন।', 'Waitha maridtu fahuwa yashfeeni', 1, NOW(), NOW()),
(31, 81, 'وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ', 'যিনি আমার মৃত্যু ঘটাবেন, অতঃপর পুনর্জীবন দান করবেন।', 'Waallathee yumeetunee thumma yuhyeeni', 1, NOW(), NOW()),
(31, 82, 'وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ', 'আমি আশা করি তিনিই বিচারের দিনে আমার ক্রটি-বিচ্যুতি মাফ করবেন।', 'Waallathee atmaAAu an yaghfira lee khateeatee yawma alddeeni', 1, NOW(), NOW()),
(31, 83, 'رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّـٰلِحِينَ', 'হে আমার পালনকর্তা, আমাকে প্রজ্ঞা দান কর এবং আমাকে সৎকর্মশীলদের অন্তর্ভুক্ত কর', 'Rabbi hab lee hukman waalhiqnee bialssaliheena', 1, NOW(), NOW()),
(31, 84, 'وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ', 'এবং আমাকে পরবর্তীদের মধ্যে সত্যভাষী কর।', 'WaijAAal lee lisana sidqin fee alakhireena', 1, NOW(), NOW()),
(31, 85, 'وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ', 'এবং আমাকে নেয়ামত উদ্যানের অধিকারীদের অন্তর্ভূক্ত কর।', 'WaijAAalnee min warathati jannati alnnaAAeemi', 1, NOW(), NOW()),
(31, 86, 'وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ', 'এবং আমার পিতাকে ক্ষমা কর। সে তো পথভ্রষ্টদের অন্যতম।', 'Waighfir liabee innahu kana mina alddalleena', 1, NOW(), NOW()),
(31, 87, 'وَلَا تُخۡزِنِي يَوۡمَ يُبۡعَثُونَ', 'এবং পূনরুত্থান দিবসে আমাকে লাঞ্ছিত করো না', 'Wala tukhzinee yawma yubAAathoona', 1, NOW(), NOW()),
(31, 88, 'يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ', 'যে দিবসে ধন-সম্পদ ও সন্তান সন্ততি কোন উপকারে আসবে না', 'Yawma la yanfaAAu malun wala banoona', 1, NOW(), NOW()),
(31, 89, 'إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ', 'কিন্তু যে সুস্থ অন্তর নিয়ে আল্লাহর কাছে আসবে।', 'Illa man ata Allaha biqalbin saleemin', 1, NOW(), NOW()),
(31, 90, 'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ', 'জান্নাত আল্লাহভীরুদের নিকটবর্তী করা হবে।', 'Waozlifati aljannatu lilmuttaqeena', 1, NOW(), NOW()),
(31, 91, 'وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ', 'এবং বিপথগামীদের সামনে উম্মোচিত করা হবে জাহান্নাম।', 'Waburrizati aljaheemu lilghaweena', 1, NOW(), NOW()),
(31, 92, 'وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ', 'তাদেরকে বলা হবেঃ তারা কোথায়, তোমরা যাদের পূজা করতে।', 'Waqeela lahum ayna ma kuntum taAAbudoona', 1, NOW(), NOW()),
(31, 93, 'مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ', 'আল্লাহর পরিবর্তে? তারা কি তোমাদের সাহায্য করতে পারে, অথবা তারা প্রতিশোধ নিতে পারে', 'Min dooni Allahi hal yansuroonakum aw yantasiroona', 1, NOW(), NOW()),
(31, 94, 'فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ', 'অতঃপর তাদেরকে এবং পথভ্রষ্টদেরকে আধোমুখি করে নিক্ষেপ করা হবে জাহান্নামে।', 'Fakubkiboo feeha hum waalghawoona', 1, NOW(), NOW()),
(31, 95, 'وَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ', 'এবং ইবলীস বাহিনীর সকলকে।', 'Wajunoodu ibleesa ajmaAAoona', 1, NOW(), NOW()),
(31, 96, 'قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ', 'তারা তথায় কথা কাটাকাটিতে লিপ্ত হয়ে বলবেঃ', 'Qaloo wahum feeha yakhtasimoona', 1, NOW(), NOW()),
(31, 97, 'تَٱللَّهِ إِن كُنَّا لَفِي ضَلَٰلٖ مُّبِينٍ', 'আল্লাহর কসম, আমরা প্রকাশ্য বিভ্রান্তিতে লিপ্ত ছিলাম।', 'TaAllahi in kunna lafee dalalin mubeenin', 1, NOW(), NOW()),
(31, 98, 'إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ', 'যখন আমরা তোমাদেরকে বিশ্ব-পালনকর্তার সমতুল্য গন্য করতাম।', 'Ith nusawweekum birabbi alAAalameena', 1, NOW(), NOW()),
(31, 99, 'وَمَآ أَضَلَّنَآ إِلَّا ٱلۡمُجۡرِمُونَ', 'আমাদেরকে দুষ্টকর্মীরাই গোমরাহ করেছিল।', 'Wama adallana illa almujrimoona', 1, NOW(), NOW()),
(31, 100, 'فَمَا لَنَا مِن شَٰفِعِينَ', 'অতএব আমাদের কোন সুপারিশকারী নেই।', 'Fama lana min shafiAAeena', 1, NOW(), NOW()),
(31, 101, 'وَلَا صَدِيقٍ حَمِيمٖ', 'এবং কোন সহৃদয় বন্ধু ও নেই।', 'Wala sadeeqin hameemin', 1, NOW(), NOW()),
(31, 102, 'فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ', 'হায়, যদি কোনরুপে আমরা পৃথিবীতে প্রত্যাবর্তনের সুযোগ পেতাম, তবে আমরা বিশ্বাস স্থাপনকারী হয়ে যেতাম।', 'Falaw anna lana karratan fanakoona mina almumineena', 1, NOW(), NOW()),
(31, 103, 'إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ', 'নিশ্চয়, এতে নিদর্শন আছে এবং তাদের অধিকাংশই বিশ্বাসী নয়।', 'Inna fee thalika laayatan wama kana aktharuhum mumineena', 1, NOW(), NOW()),
(31, 104, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', 'আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।', 'Wainna rabbaka lahuwa alAAazeezu alrraheemu', 1, NOW(), NOW()),
(31, 105, 'كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِينَ', 'নূহের সম্প্রদায় পয়গম্বরগণকে মিথ্যারোপ করেছে।', 'Kaththabat qawmu noohin almursaleena', 1, NOW(), NOW()),
(31, 106, 'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ', 'যখন তাদের ভ্রাতা নূহ তাদেরকে বললেন, তোমাদের কি ভয় নেই', 'Ith qala lahum akhoohum noohun ala tattaqoona', 1, NOW(), NOW()),
(31, 107, 'إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ', 'আমি তোমাদের জন্য বিশ্বস্ত বার্তাবাহক।', 'Innee lakum rasoolun ameenun', 1, NOW(), NOW()),
(31, 108, 'فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।', 'Faittaqoo Allaha waateeAAooni', 1, NOW(), NOW()),
(31, 109, 'وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ', 'আমি তোমাদের কাছে এর জন্য কোন প্রতিদান চাই না, আমার প্রতিদান তো বিশ্ব-পালনকর্তাই দেবেন।', 'Wama asalukum AAalayhi min ajrin in ajriya illa AAala rabbi alAAalameena', 1, NOW(), NOW()),
(31, 110, 'فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ', 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।', 'Faittaqoo Allaha waateeAAooni', 1, NOW(), NOW()),
(31, 111, '۞قَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ', 'তারা বলল, আমরা কি তোমাকে মেনে নেব যখন তোমার অনুসরণ করছে ইতরজনেরা', 'Qaloo anuminu laka waittabaAAaka alarthaloona', 1, NOW(), NOW()),
(31, 112, 'قَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ', 'নূহ বললেন, তারা কি কাজ করছে, তা জানা আমার কি দরকার', 'Qala wama AAilmee bima kanoo yaAAmaloona', 1, NOW(), NOW()),
(31, 113, 'إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّيۖ لَوۡ تَشۡعُرُونَ', 'তাদের হিসাব নেয়া আমার পালনকর্তারই কাজ; যদি তোমরা বুঝতে', 'In hisabuhum illa AAala rabbee law tashAAuroona', 1, NOW(), NOW()),
