(86, 13, 'وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ', 'যখন জান্নাতকে (মানুষের) কাছে নিয়ে আসা হবে,', 'Waitha aljannatu ozlifat', 1, NOW(), NOW()),
(86, 14, 'عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ', '(তখন) প্রত্যেক ব্যক্তিই জানতে পারবে সে কী জিনিস (আল্লাহ তায়ালার কাছে) হাজির করেছে;', 'AAalimat nafsun ma ahdarat', 1, NOW(), NOW()),
(86, 15, 'فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ', 'আমি শপথ করছি সেসব তারকাপুঞ্জের যা (চলতে চলতে ) গা ঢাকা দেয়,', 'Fala oqsimu bialkhunnasi', 1, NOW(), NOW()),
(86, 16, 'ٱلۡجَوَارِ ٱلۡكُنَّسِ', '(আবার মাঝে মাঝে) যা অদৃশ্য হয়ে যায়,', 'Aljawari alkunnasi', 1, NOW(), NOW()),
(86, 17, 'وَٱلَّيۡلِ إِذَا عَسۡعَسَ', '(শপথ) রাতের যখন তা নিঃশেষ হয়ে যায়,', 'Waallayli itha AAasAAasa', 1, NOW(), NOW()),
(86, 18, 'وَٱلصُّبۡحِ إِذَا تَنَفَّسَ', '(শপথ) সকাল বেলার যখন তা (দিনের আলোয়) নিশ্বাস নেয়,', 'Waalssubhi itha tanaffasa', 1, NOW(), NOW()),
